import type { BankQuestion } from "@/lib/bank";

/** Child Development and Pedagogy (Child Development and Pedagogy): 2000 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"cdp-child-development-1","question":"The RTE Act, 2009 provides free and compulsory education for children aged:","options":["3–14 years","6–14 years","6–18 years","5–15 years"],"answer":1,"explanation":"Article 21A, made operational by the RTE Act 2009, guarantees free and compulsory education to every child aged 6 to 14 (Classes 1–8). 3–6 is the pre-school (ECCE) band, and extending the right to age 18 is only a proposal, not the law.","difficulty":"easy","questionHi":"शिक्षा का अधिकार (RTE) अधिनियम, 2009 किस आयु वर्ग के बच्चों के लिए निःशुल्क एवं अनिवार्य शिक्षा का प्रावधान करता है?","optionsHi":["3–14 वर्ष","6–14 वर्ष","6–18 वर्ष","5–15 वर्ष"],"explanationHi":"अनुच्छेद 21A, जिसे RTE अधिनियम 2009 द्वारा लागू किया गया, 6 से 14 वर्ष (कक्षा 1–8) के प्रत्येक बच्चे को निःशुल्क एवं अनिवार्य शिक्षा की गारंटी देता है। 3–6 वर्ष प्री-स्कूल (ECCE) का आयु वर्ग है, और अधिकार को 18 वर्ष तक बढ़ाना केवल एक प्रस्ताव है, कानून नहीं।"},
  {"id":"cdp-child-development-2","question":"RTE stands for:","options":["Right to Education","Rules of Teaching Excellence","Right to Employment","Reading, Teaching and Evaluation"],"answer":0,"explanation":"The Right of Children to Free and Compulsory Education Act, 2009.","difficulty":"easy","questionHi":"RTE का पूर्ण रूप क्या है?","optionsHi":["शिक्षा का अधिकार (Right to Education)","शिक्षण उत्कृष्टता के नियम (Rules of Teaching Excellence)","रोजगार का अधिकार (Right to Employment)","पठन, शिक्षण और मूल्यांकन (Reading, Teaching and Evaluation)"],"explanationHi":"बच्चों का निःशुल्क और अनिवार्य शिक्षा का अधिकार अधिनियम, 2009।"},
  {"id":"cdp-child-development-3","question":"Which thinker is associated with the stages of cognitive development?","options":["Jean Piaget","B. F. Skinner","Ivan Pavlov","Sigmund Freud"],"answer":0,"explanation":"Piaget described four stages of cognitive development: sensorimotor, preoperational, concrete operational and formal operational. Skinner and Pavlov are behaviourists, and Freud's stages are psychosexual, not cognitive.","difficulty":"easy","questionHi":"संज्ञानात्मक विकास की अवस्थाओं से कौन-सा विचारक संबंधित है?","optionsHi":["जीन पियाजे","बी. एफ. स्किनर","इवान पावलोव","सिगमंड फ्रायड"],"explanationHi":"पियाजे ने संज्ञानात्मक विकास की चार अवस्थाएँ बताईं: संवेदी-गामक, पूर्व-संक्रियात्मक, मूर्त संक्रियात्मक और औपचारिक संक्रियात्मक। स्किनर और पावलोव व्यवहारवादी हैं, तथा फ्रायड की अवस्थाएँ मनोलैंगिक हैं, संज्ञानात्मक नहीं।"},
  {"id":"cdp-child-development-4","question":"The concept of the Zone of Proximal Development was given by:","options":["Piaget","Vygotsky","Kohlberg","Skinner"],"answer":1,"explanation":"Lev Vygotsky introduced the ZPD: what a learner can do with help but not yet alone.","difficulty":"moderate","questionHi":"निकटस्थ विकास का क्षेत्र (ZPD) की अवधारणा किसने दी?","optionsHi":["पियाजे","वाइगोत्स्की","कोहलबर्ग","स्किनर"],"explanationHi":"लेव वाइगोत्स्की ने ZPD की अवधारणा दी: वह जो अधिगमकर्ता सहायता से कर सकता है, पर अभी अकेले नहीं कर सकता।"},
  {"id":"cdp-child-development-5","question":"The theory of multiple intelligences was proposed by:","options":["Howard Gardner","Jean Piaget","Lawrence Kohlberg","B. F. Skinner"],"answer":0,"explanation":"Howard Gardner proposed multiple intelligences in Frames of Mind (1983), listing linguistic, logical-mathematical, spatial and other separate intelligences. Kohlberg's stages describe moral reasoning, not kinds of intelligence.","difficulty":"moderate","questionHi":"बहुबुद्धि सिद्धांत किसने प्रस्तावित किया?","optionsHi":["हॉवर्ड गार्डनर","जीन पियाजे","लॉरेंस कोहलबर्ग","बी. एफ. स्किनर"],"explanationHi":"हॉवर्ड गार्डनर ने अपनी पुस्तक ‘फ्रेम्स ऑफ माइंड’ (1983) में बहुबुद्धि सिद्धांत प्रस्तावित किया, जिसमें भाषायी, तार्किक-गणितीय, स्थानिक आदि अलग-अलग बुद्धियाँ बताई गई हैं। कोहलबर्ग की अवस्थाएँ नैतिक चिंतन को बताती हैं, बुद्धि के प्रकारों को नहीं।"},
  {"id":"cdp-child-development-6","question":"The term “scaffolding” in learning is associated with:","options":["Piaget","Vygotsky","Kohlberg","Erikson"],"answer":1,"explanation":"Scaffolding, temporary support from a more capable person, comes from Vygotsky’s sociocultural theory.","difficulty":"moderate","questionHi":"अधिगम में “पाड़ (scaffolding)” पद किससे संबंधित है?","optionsHi":["पियाजे","वाइगोत्स्की","कोहलबर्ग","एरिक्सन"],"explanationHi":"पाड़ (scaffolding), यानी किसी अधिक सक्षम व्यक्ति द्वारा दिया गया अस्थायी सहारा, वाइगोत्स्की के सामाजिक-सांस्कृतिक सिद्धांत से आया है।"},
  {"id":"cdp-child-development-7","question":"Object permanence develops during which of Piaget’s stages?","options":["Sensorimotor","Pre-operational","Concrete operational","Formal operational"],"answer":0,"explanation":"Object permanence develops in the sensorimotor stage (0–2 years).","difficulty":"hard","questionHi":"वस्तु स्थायित्व पियाजे की किस अवस्था में विकसित होता है?","optionsHi":["संवेदी-गामक","पूर्व-संक्रियात्मक","मूर्त संक्रियात्मक","औपचारिक संक्रियात्मक"],"explanationHi":"वस्तु स्थायित्व संवेदी-गामक अवस्था (0–2 वर्ष) में विकसित होता है।"},
  {"id":"cdp-child-development-8","question":"According to Piaget, abstract and hypothetical thinking develops in the:","options":["Sensorimotor stage","Pre-operational stage","Concrete operational stage","Formal operational stage"],"answer":3,"explanation":"The formal operational stage (11+ years) brings abstract and hypothetical reasoning.","difficulty":"hard","questionHi":"पियाजे के अनुसार अमूर्त और परिकल्पनात्मक चिंतन किस अवस्था में विकसित होता है?","optionsHi":["संवेदी-गामक अवस्था","पूर्व-संक्रियात्मक अवस्था","मूर्त संक्रियात्मक अवस्था","औपचारिक संक्रियात्मक अवस्था"],"explanationHi":"औपचारिक संक्रियात्मक अवस्था (11+ वर्ष) में अमूर्त और परिकल्पनात्मक तर्क का विकास होता है।"},
  {"id":"cdp-child-development-9","question":"Kohlberg’s theory deals with:","options":["Cognitive development","Moral development","Psychosocial development","Language development"],"answer":1,"explanation":"Kohlberg proposed three levels and six stages of moral development.","difficulty":"hard","questionHi":"कोहलबर्ग का सिद्धांत किससे संबंधित है?","optionsHi":["संज्ञानात्मक विकास","नैतिक विकास","मनोसामाजिक विकास","भाषा विकास"],"explanationHi":"कोहलबर्ग ने नैतिक विकास के तीन स्तर और छह चरण प्रस्तावित किए।"},
  {"id":"cdp-child-development-10","question":"Operant conditioning was proposed by:","options":["Ivan Pavlov","B. F. Skinner","Edward Thorndike","Albert Bandura"],"answer":1,"explanation":"Skinner showed that behaviour is shaped by reinforcement and punishment; Pavlov’s is classical conditioning.","difficulty":"very-hard","questionHi":"क्रियाप्रसूत अनुबंधन (operant conditioning) किसने प्रस्तावित किया?","optionsHi":["इवान पावलोव","बी. एफ. स्किनर","एडवर्ड थॉर्नडाइक","अल्बर्ट बंडूरा"],"explanationHi":"स्किनर ने दिखाया कि व्यवहार पुनर्बलन और दंड से आकार लेता है; पावलोव का सिद्धांत शास्त्रीय अनुबंधन है।"},
  {"id":"cdp-child-development-11","question":"“Egocentrism” is a characteristic of which Piagetian stage?","options":["Sensorimotor","Pre-operational","Concrete operational","Formal operational"],"answer":1,"explanation":"Pre-operational children (2–7) find it hard to see things from another person’s point of view.","difficulty":"very-hard","questionHi":"“अहंकेंद्रिता” पियाजे की किस अवस्था की विशेषता है?","optionsHi":["संवेदी-गामक","पूर्व-संक्रियात्मक","मूर्त संक्रियात्मक","औपचारिक संक्रियात्मक"],"explanationHi":"पूर्व-संक्रियात्मक अवस्था (2–7 वर्ष) के बच्चों को दूसरे व्यक्ति के दृष्टिकोण से चीजों को देखना कठिन लगता है।"},
  {"id":"cdp-child-development-12","question":"Erik Erikson’s stage of “Industry vs Inferiority” corresponds to the age group:","options":["0–1 years","3–6 years","6–12 years","12–18 years"],"answer":2,"explanation":"Industry vs Inferiority covers the school years, about 6 to 12.","difficulty":"very-hard","questionHi":"एरिक एरिक्सन की “उद्यमिता बनाम हीनता” अवस्था किस आयु वर्ग से संबंधित है?","optionsHi":["0–1 वर्ष","3–6 वर्ष","6–12 वर्ष","12–18 वर्ष"],"explanationHi":"उद्यमिता बनाम हीनता की अवस्था विद्यालय के वर्षों, लगभग 6 से 12 वर्ष, को समेटती है।"},
  {"id":"cdp-child-development-13","question":"According to Piaget, the stage of development from birth to about 2 years is the:","options":["Pre-operational stage","Sensorimotor stage","Concrete operational stage","Formal operational stage"],"answer":1,"explanation":"Infants learn through senses and movement in the sensorimotor stage.","difficulty":"easy","source":"CTET · UPTET","questionHi":"पियाजे के अनुसार जन्म से लगभग 2 वर्ष तक की विकास अवस्था कौन-सी है?","optionsHi":["पूर्व-संक्रियात्मक अवस्था","संवेदी-गामक अवस्था","मूर्त संक्रियात्मक अवस्था","औपचारिक संक्रियात्मक अवस्था"],"explanationHi":"संवेदी-गामक अवस्था में शिशु इंद्रियों और गति के माध्यम से सीखते हैं।"},
  {"id":"cdp-child-development-14","question":"The Right to Education Act, 2009 makes education free and compulsory for children aged:","options":["3–6 years","6–14 years","5–15 years","6–18 years"],"answer":1,"explanation":"The RTE Act 2009 (under Article 21A) makes education free and compulsory for children aged 6 to 14, i.e. Classes 1 to 8. The 3–6 band is early childhood care and education, and 6–18 is not covered by the Act.","difficulty":"easy","source":"CTET · SUPER TET","questionHi":"शिक्षा का अधिकार अधिनियम, 2009 किस आयु के बच्चों के लिए शिक्षा को निःशुल्क एवं अनिवार्य बनाता है?","optionsHi":["3–6 वर्ष","6–14 वर्ष","5–15 वर्ष","6–18 वर्ष"],"explanationHi":"RTE अधिनियम 2009 (अनुच्छेद 21A के अंतर्गत) 6 से 14 वर्ष, यानी कक्षा 1 से 8 तक के बच्चों के लिए शिक्षा को निःशुल्क एवं अनिवार्य बनाता है। 3–6 वर्ष का वर्ग प्रारंभिक बाल्यावस्था देखभाल एवं शिक्षा का है, और 6–18 वर्ष इस अधिनियम के दायरे में नहीं आता।"},
  {"id":"cdp-child-development-15","question":"Vygotsky’s “Zone of Proximal Development” refers to the gap between what a child can do:","options":["Alone and with a more capable person’s help","In the home language and in the school language","When rewarded and when no reward is offered","In familiar and in unfamiliar settings"],"answer":0,"explanation":"ZPD is the range of tasks a learner can do with guidance but not yet alone.","difficulty":"moderate","source":"CTET · UPTET","questionHi":"वाइगोत्स्की का “निकटस्थ विकास का क्षेत्र” बच्चे के किन दो कार्यों के बीच का अंतर है?","optionsHi":["अकेले और किसी अधिक सक्षम व्यक्ति की सहायता से","घर की भाषा और विद्यालय की भाषा में","पुरस्कार मिलने पर और पुरस्कार न मिलने पर","परिचित और अपरिचित परिवेश में"],"explanationHi":"ZPD उन कार्यों का दायरा है जिन्हें अधिगमकर्ता मार्गदर्शन से कर सकता है, पर अभी अकेले नहीं कर सकता।"},
  {"id":"cdp-child-development-16","question":"Howard Gardner is known for the theory of:","options":["Moral development","Multiple intelligences","Classical conditioning","Psychosocial development"],"answer":1,"explanation":"Gardner proposed several independent intelligences: linguistic, logical, spatial, musical and more.","difficulty":"moderate","source":"CTET · KVS","questionHi":"हॉवर्ड गार्डनर किस सिद्धांत के लिए जाने जाते हैं?","optionsHi":["नैतिक विकास","बहुबुद्धि","शास्त्रीय अनुबंधन","मनोसामाजिक विकास"],"explanationHi":"गार्डनर ने कई स्वतंत्र बुद्धियाँ प्रस्तावित कीं: भाषायी, तार्किक, स्थानिक, संगीतात्मक आदि।"},
  {"id":"cdp-child-development-17","question":"Classical conditioning was demonstrated by Pavlov using:","options":["Rats in a box","Dogs and a bell","Pigeons","Children and a doll"],"answer":1,"explanation":"Pavlov paired a bell with food until the bell alone made dogs salivate.","difficulty":"hard","source":"CTET · UPTET","questionHi":"पावलोव ने शास्त्रीय अनुबंधन का प्रदर्शन किसके द्वारा किया?","optionsHi":["बक्से में चूहे","कुत्ते और घंटी","कबूतर","बच्चे और गुड़िया"],"explanationHi":"पावलोव ने घंटी को भोजन के साथ तब तक जोड़ा जब तक केवल घंटी बजने से ही कुत्तों के मुँह में लार आने लगी।"},
  {"id":"cdp-child-development-18","question":"A child who learns to read a word and then reads it again correctly a week later is showing which process of memory?","options":["Encoding","Storage","Retrieval","Forgetting"],"answer":2,"explanation":"Encoding and storage happened when the word was first learnt; reading it correctly a week later means pulling it back out of long-term memory, which is retrieval. Forgetting would be the failure of that retrieval.","difficulty":"very-hard","source":"CTET · DSSSB","questionHi":"एक बच्चा कोई शब्द पढ़ना सीखता है और एक सप्ताह बाद उसे फिर सही पढ़ लेता है। यह स्मृति की किस प्रक्रिया को दर्शाता है?","optionsHi":["कूटसंकेतन (एन्कोडिंग)","संचयन","पुनःप्राप्ति","विस्मरण"],"explanationHi":"कूटसंकेतन और संचयन तब हुए जब शब्द पहली बार सीखा गया; एक सप्ताह बाद उसे सही पढ़ने का अर्थ है उसे दीर्घकालिक स्मृति से वापस निकालना, यानी पुनःप्राप्ति। विस्मरण इसी पुनःप्राप्ति की विफलता होगा।"},
  {"id":"cdp-child-development-19","question":"At Kohlberg’s pre-conventional level, a child judges right and wrong mainly by:","options":["Social approval","Punishment and reward","Universal ethical principles","Law and order"],"answer":1,"explanation":"Pre-conventional morality is about avoiding punishment and getting rewards.","difficulty":"hard","questionHi":"कोहलबर्ग के पूर्व-परंपरागत स्तर पर बच्चा सही और गलत का निर्णय मुख्यतः किसके आधार पर करता है?","optionsHi":["सामाजिक स्वीकृति","दंड और पुरस्कार","सार्वभौमिक नैतिक सिद्धांत","कानून और व्यवस्था"],"explanationHi":"पूर्व-परंपरागत नैतिकता दंड से बचने और पुरस्कार पाने पर केंद्रित होती है।"},
  {"id":"cdp-child-development-20","question":"Which of these is an example of formative assessment?","options":["The board exam at the end of the year","Class quizzes with feedback during a unit","An entrance test used to select students","The final term exam that decides promotion"],"answer":1,"explanation":"Formative assessment happens during learning and is used to improve it.","difficulty":"hard","questionHi":"इनमें से कौन-सा रचनात्मक आकलन का उदाहरण है?","optionsHi":["वर्ष के अंत की बोर्ड परीक्षा","इकाई के दौरान प्रतिपुष्टि सहित कक्षा की क्विज़","विद्यार्थियों के चयन के लिए प्रयुक्त प्रवेश परीक्षा","पदोन्नति तय करने वाली अंतिम सत्र परीक्षा"],"explanationHi":"रचनात्मक आकलन सीखने के दौरान होता है और सीखने को बेहतर बनाने के लिए प्रयोग किया जाता है।"},
  {"id":"cdp-child-development-21","question":"Bruner’s three modes of representation are:","options":["Enactive, iconic, symbolic","Sensory, motor, verbal","Concrete, abstract, formal","Visual, auditory, kinaesthetic"],"answer":0,"explanation":"Bruner said knowledge is represented through action (enactive), images (iconic) and language or symbols (symbolic), and good teaching moves through all three. Visual-auditory-kinaesthetic is the VAK learning-styles model, not Bruner's.","difficulty":"very-hard","questionHi":"ब्रूनर के निरूपण के तीन प्रकार कौन-से हैं?","optionsHi":["क्रियात्मक, प्रतिबिंबात्मक, सांकेतिक (Enactive, iconic, symbolic)","संवेदी, गामक, शाब्दिक","मूर्त, अमूर्त, औपचारिक","दृश्य, श्रव्य, गतिबोधी"],"explanationHi":"ब्रूनर के अनुसार ज्ञान का निरूपण क्रिया (क्रियात्मक), प्रतिबिंबों (प्रतिबिंबात्मक) और भाषा या प्रतीकों (सांकेतिक) के माध्यम से होता है, और अच्छा शिक्षण तीनों से होकर गुजरता है। दृश्य-श्रव्य-गतिबोधी VAK अधिगम शैली मॉडल है, ब्रूनर का नहीं।"},
  {"id":"cdp-child-development-22","question":"Wolfgang Köhler demonstrated “learning by insight” in experiments with:","options":["Cats","Dogs","Chimpanzees","Laboratory rats"],"answer":2,"explanation":"His chimpanzee Sultan joined sticks to reach a banana, showing sudden insight.","difficulty":"very-hard","questionHi":"वोल्फगैंग कोहलर ने “अंतर्दृष्टि द्वारा अधिगम” का प्रदर्शन किन पर प्रयोगों में किया?","optionsHi":["बिल्लियाँ","कुत्ते","चिंपैंजी","प्रयोगशाला के चूहे"],"explanationHi":"उनके चिंपैंजी सुल्तान ने केले तक पहुँचने के लिए डंडों को जोड़ लिया, जिससे अचानक अंतर्दृष्टि का पता चलता है।"},
  {"id":"cdp-child-development-23","question":"How many of these statements are correct? I. Piaget’s concrete operational stage covers roughly 2 to 7 years. II. Conservation develops in the concrete operational stage. III. Object permanence develops in the sensorimotor stage. IV. Abstract reasoning begins in the pre-operational stage.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and III are correct. I is wrong: 2 to 7 years is the pre-operational stage; the concrete operational stage is about 7 to 11. IV is wrong: abstract reasoning belongs to the formal operational stage.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. पियाजे की मूर्त संक्रियात्मक अवस्था लगभग 2 से 7 वर्ष तक होती है। II. संरक्षण मूर्त संक्रियात्मक अवस्था में विकसित होता है। III. वस्तु स्थायित्व संवेदी-गामक अवस्था में विकसित होता है। IV. अमूर्त तर्क पूर्व-संक्रियात्मक अवस्था में शुरू होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"II और III सही हैं। I गलत है: 2 से 7 वर्ष पूर्व-संक्रियात्मक अवस्था है; मूर्त संक्रियात्मक अवस्था लगभग 7 से 11 वर्ष की होती है। IV गलत है: अमूर्त तर्क औपचारिक संक्रियात्मक अवस्था का है।"},
  {"id":"cdp-child-development-24","question":"How many of these statements are correct? I. The RTE Act, 2009 came into force on 1 April 2010. II. It reserves 25% of entry-level seats in private unaided schools for disadvantaged children. III. It lets schools hold screening tests for admission.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. The Act bans screening procedures and capitation fees.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. RTE अधिनियम, 2009 1 अप्रैल 2010 को लागू हुआ। II. यह निजी गैर-सहायता प्राप्त विद्यालयों में प्रारंभिक कक्षा की 25% सीटें वंचित वर्ग के बच्चों के लिए आरक्षित करता है। III. यह विद्यालयों को प्रवेश के लिए स्क्रीनिंग परीक्षा लेने की अनुमति देता है।","optionsHi":["केवल एक","केवल दो","तीनों","कोई नहीं"],"explanationHi":"केवल I और II सही हैं। अधिनियम स्क्रीनिंग प्रक्रियाओं और कैपिटेशन शुल्क पर रोक लगाता है।"},
  {"id":"cdp-child-development-25","question":"A child knows that a ball of clay rolled into a sausage still has the same amount of clay. According to Piaget, the child has acquired:","options":["Conservation","Object permanence","Egocentrism","Animism"],"answer":0,"explanation":"Conservation develops in the concrete operational stage (about 7 to 11 years).","difficulty":"very-hard","questionHi":"एक बच्चा जानता है कि मिट्टी की गेंद को लंबे रोल जैसा बना देने पर भी मिट्टी की मात्रा उतनी ही रहती है। पियाजे के अनुसार बच्चे ने क्या अर्जित कर लिया है?","optionsHi":["संरक्षण","वस्तु स्थायित्व","अहंकेंद्रिता","सजीववाद"],"explanationHi":"संरक्षण मूर्त संक्रियात्मक अवस्था (लगभग 7 से 11 वर्ष) में विकसित होता है।"},
  {"id":"cdp-child-development-26","question":"Vygotsky’s Zone of Proximal Development is the gap between:","options":["What a child can do alone and with guidance","A child’s mental age and chronological age","What a child knows and what the curriculum expects","A child’s performance at home and at school"],"answer":0,"explanation":"The ZPD is what a learner can do with help from a more knowledgeable other but not yet alone; scaffolding works inside it.","difficulty":"very-hard","questionHi":"वाइगोत्स्की का निकटस्थ विकास का क्षेत्र किन दोनों के बीच का अंतर है?","optionsHi":["बच्चा अकेले क्या कर सकता है और मार्गदर्शन से क्या कर सकता है","बच्चे की मानसिक आयु और कालानुक्रमिक आयु","बच्चा क्या जानता है और पाठ्यक्रम उससे क्या अपेक्षा करता है","घर और विद्यालय में बच्चे का प्रदर्शन"],"explanationHi":"ZPD वह है जो अधिगमकर्ता किसी अधिक जानकार व्यक्ति की सहायता से कर सकता है पर अभी अकेले नहीं; पाड़ (scaffolding) इसी के भीतर काम करता है।"},
  {"id":"cdp-child-development-27","question":"How many of these statements are correct? I. Kohlberg’s theory deals with moral development. II. Erikson proposed eight psychosocial stages. III. Piaget proposed five stages of cognitive development.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. Piaget proposed four stages: sensorimotor, pre-operational, concrete operational and formal operational.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. कोहलबर्ग का सिद्धांत नैतिक विकास से संबंधित है। II. एरिक्सन ने आठ मनोसामाजिक अवस्थाएँ प्रस्तावित कीं। III. पियाजे ने संज्ञानात्मक विकास की पाँच अवस्थाएँ प्रस्तावित कीं।","optionsHi":["केवल एक","केवल दो","तीनों","कोई नहीं"],"explanationHi":"केवल I और II सही हैं। पियाजे ने चार अवस्थाएँ प्रस्तावित कीं: संवेदी-गामक, पूर्व-संक्रियात्मक, मूर्त संक्रियात्मक और औपचारिक संक्रियात्मक।"},
  {"id":"cdp-child-development-28","question":"Which pair of theory and psychologist is NOT correctly matched?","options":["Classical conditioning – Ivan Pavlov","Social learning theory – Bandura","Multiple intelligences – Gardner","Trial-and-error learning – Skinner"],"answer":3,"explanation":"Trial-and-error learning, with the laws of effect, exercise and readiness, is Thorndike’s. Skinner gave operant conditioning.","difficulty":"very-hard","source":"CTET · KVS","questionHi":"सिद्धांत और मनोवैज्ञानिक की कौन-सी जोड़ी सही सुमेलित नहीं है?","optionsHi":["शास्त्रीय अनुबंधन – इवान पावलोव","सामाजिक अधिगम सिद्धांत – बंडूरा","बहुबुद्धि – गार्डनर","प्रयास और त्रुटि अधिगम – स्किनर"],"explanationHi":"प्रयास और त्रुटि अधिगम, जिसमें प्रभाव, अभ्यास और तत्परता के नियम हैं, थॉर्नडाइक का है। स्किनर ने क्रियाप्रसूत अनुबंधन दिया।"},
  {"id":"cdp-child-development-29","question":"How many of these statements about Erikson’s theory are correct? I. Autonomy vs shame and doubt is the first stage. II. Identity vs role confusion belongs to early adulthood. III. The stages end with adolescence. IV. Initiative vs guilt covers roughly 3 to 6 years.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only IV is correct. The first stage is trust vs mistrust, identity vs role confusion is the adolescent stage (early adulthood is intimacy vs isolation), and the stages run to old age, ending with integrity vs despair.","difficulty":"very-hard","source":"CTET · DSSSB","questionHi":"एरिक्सन के सिद्धांत के बारे में इनमें से कितने कथन सही हैं? I. स्वायत्तता बनाम शर्म और संदेह पहली अवस्था है। II. पहचान बनाम भूमिका भ्रांति प्रारंभिक वयस्कता की अवस्था है। III. अवस्थाएँ किशोरावस्था पर समाप्त हो जाती हैं। IV. पहल बनाम अपराधबोध लगभग 3 से 6 वर्ष को समेटता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल IV सही है। पहली अवस्था विश्वास बनाम अविश्वास है, पहचान बनाम भूमिका भ्रांति किशोरावस्था की अवस्था है (प्रारंभिक वयस्कता घनिष्ठता बनाम अलगाव है), और अवस्थाएँ वृद्धावस्था तक चलती हैं, जो अखंडता बनाम निराशा पर समाप्त होती हैं।"},
  {"id":"cdp-child-development-30","question":"The Right of Children to Free and Compulsory Education Act, 2009 gives effect to which Article of the Constitution?","options":["Article 14","Article 21A","Article 45","Article 51A"],"answer":1,"explanation":"Article 21A, inserted by the 86th Amendment (2002), makes elementary education a fundamental right; Article 45 now deals with early childhood care below six years.","difficulty":"easy","source":"CTET · UPTET · State TETs","questionHi":"बच्चों का निःशुल्क और अनिवार्य शिक्षा का अधिकार अधिनियम, 2009 संविधान के किस अनुच्छेद को प्रभावी बनाता है?","optionsHi":["अनुच्छेद 14","अनुच्छेद 21A","अनुच्छेद 45","अनुच्छेद 51A"],"explanationHi":"86वें संशोधन (2002) द्वारा जोड़ा गया अनुच्छेद 21A प्रारंभिक शिक्षा को मौलिक अधिकार बनाता है; अनुच्छेद 45 अब छह वर्ष से कम आयु की प्रारंभिक बाल्यावस्था देखभाल से संबंधित है।"},
  {"id":"cdp-child-development-31","question":"According to Piaget, the stage of cognitive development from about 2 to 7 years is the:","options":["Sensorimotor stage","Pre-operational stage","Concrete operational stage","Formal operational stage"],"answer":1,"explanation":"The pre-operational stage (2–7 years) is marked by symbolic play, egocentrism and lack of conservation.","difficulty":"easy","source":"CTET · UPTET · State TETs","questionHi":"पियाजे के अनुसार लगभग 2 से 7 वर्ष की संज्ञानात्मक विकास अवस्था कौन-सी है?","optionsHi":["संवेदी-गामक अवस्था","पूर्व-संक्रियात्मक अवस्था","मूर्त संक्रियात्मक अवस्था","औपचारिक संक्रियात्मक अवस्था"],"explanationHi":"पूर्व-संक्रियात्मक अवस्था (2–7 वर्ष) की पहचान प्रतीकात्मक खेल, अहंकेंद्रिता और संरक्षण के अभाव से होती है।"},
  {"id":"cdp-child-development-32","question":"The “law of effect” in learning was proposed by:","options":["Ivan Pavlov","B. F. Skinner","Thorndike","Albert Bandura"],"answer":2,"explanation":"Thorndike’s law of effect states that responses followed by satisfying consequences are strengthened; Skinner later built operant conditioning on this idea.","difficulty":"easy","source":"CTET · UPTET · State TETs","questionHi":"अधिगम में “प्रभाव का नियम” किसने प्रस्तावित किया?","optionsHi":["इवान पावलोव","बी. एफ. स्किनर","थॉर्नडाइक","अल्बर्ट बंडूरा"],"explanationHi":"थॉर्नडाइक का प्रभाव का नियम कहता है कि संतोषजनक परिणाम वाली प्रतिक्रियाएँ सुदृढ़ होती हैं; स्किनर ने बाद में इसी विचार पर क्रियाप्रसूत अनुबंधन खड़ा किया।"},
  {"id":"cdp-child-development-33","question":"The 5+3+3+4 curricular structure for school education was recommended by:","options":["National Policy on Education, 1986","Right to Education Act, 2009","National Education Policy, 2020","Kothari Commission, 1966"],"answer":2,"explanation":"NEP 2020 replaces the 10+2 pattern with foundational (5 years), preparatory (3), middle (3) and secondary (4) stages covering ages 3 to 18.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"विद्यालयी शिक्षा के लिए 5+3+3+4 पाठ्यचर्या संरचना की अनुशंसा किसने की?","optionsHi":["राष्ट्रीय शिक्षा नीति, 1986","शिक्षा का अधिकार अधिनियम, 2009","राष्ट्रीय शिक्षा नीति, 2020","कोठारी आयोग, 1966"],"explanationHi":"NEP 2020 10+2 पद्धति की जगह आधारभूत (5 वर्ष), प्रारंभिक (3), मध्य (3) और माध्यमिक (4) चरण लाती है, जो 3 से 18 वर्ष की आयु को समेटते हैं।"},
  {"id":"cdp-child-development-34","question":"The formula IQ = (Mental age ÷ Chronological age) × 100 was given by:","options":["Alfred Binet","William Stern","Lewis Terman","Charles Spearman"],"answer":1,"explanation":"William Stern proposed the intelligence quotient in 1912; Binet devised the mental-age scale and Terman popularised the IQ in the Stanford–Binet test.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"सूत्र IQ = (मानसिक आयु ÷ कालानुक्रमिक आयु) × 100 किसने दिया?","optionsHi":["अल्फ्रेड बिने","विलियम स्टर्न","लुईस टरमन","चार्ल्स स्पीयरमैन"],"explanationHi":"विलियम स्टर्न ने 1912 में बुद्धि लब्धि प्रस्तावित की; बिने ने मानसिक आयु का पैमाना बनाया और टरमन ने स्टैनफोर्ड–बिने परीक्षण में IQ को लोकप्रिय बनाया।"},
  {"id":"cdp-child-development-35","question":"According to Vygotsky, the most important tool for cognitive development is:","options":["Maturation","Language","Reinforcement","Physical play"],"answer":1,"explanation":"For Vygotsky, language and social interaction mediate thinking; private speech becomes inner speech that guides problem solving.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"वाइगोत्स्की के अनुसार संज्ञानात्मक विकास का सबसे महत्वपूर्ण उपकरण क्या है?","optionsHi":["परिपक्वता","भाषा","पुनर्बलन","शारीरिक खेल"],"explanationHi":"वाइगोत्स्की के लिए भाषा और सामाजिक अंतःक्रिया चिंतन का माध्यम हैं; निजी वाक् आंतरिक वाक् बन जाती है, जो समस्या समाधान का मार्गदर्शन करती है।"},
  {"id":"cdp-child-development-36","question":"A child is generally regarded as “gifted” if the IQ is above:","options":["90","110","130","150"],"answer":2,"explanation":"An IQ of about 130 or more (two standard deviations above the mean of 100) is the usual threshold for giftedness.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"किसी बच्चे को सामान्यतः “प्रतिभाशाली” तब माना जाता है जब उसका IQ इससे अधिक हो:","optionsHi":["90","110","130","150"],"explanationHi":"लगभग 130 या अधिक IQ (औसत 100 से दो मानक विचलन ऊपर) प्रतिभाशालिता की सामान्य सीमा है।"},
  {"id":"cdp-child-development-37","question":"An examination held at the end of a term to judge how much students have learnt is an example of:","options":["Formative assessment","Diagnostic assessment","Summative assessment","Placement assessment"],"answer":2,"explanation":"Summative assessment measures learning at the end of a unit or course; formative assessment happens during teaching to improve it.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"सत्र के अंत में यह जाँचने के लिए ली गई परीक्षा कि विद्यार्थियों ने कितना सीखा, किसका उदाहरण है?","optionsHi":["रचनात्मक आकलन","निदानात्मक आकलन","योगात्मक आकलन","स्थान-निर्धारण आकलन"],"explanationHi":"योगात्मक आकलन किसी इकाई या पाठ्यक्रम के अंत में अधिगम को मापता है; रचनात्मक आकलन शिक्षण के दौरान उसे बेहतर बनाने के लिए होता है।"},
  {"id":"cdp-child-development-38","question":"Dyslexia is a learning disability that mainly affects:","options":["Reading","Arithmetic","Handwriting","Motor coordination"],"answer":0,"explanation":"Dyslexia affects reading and spelling; dyscalculia affects arithmetic, dysgraphia writing and dyspraxia motor coordination.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"डिस्लेक्सिया एक अधिगम अक्षमता है जो मुख्यतः किसे प्रभावित करती है?","optionsHi":["पढ़ना","अंकगणित","लिखावट","गामक समन्वय"],"explanationHi":"डिस्लेक्सिया पढ़ने और वर्तनी को प्रभावित करता है; डिस्कैल्कुलिया अंकगणित को, डिसग्राफिया लेखन को और डिस्प्रैक्सिया गामक समन्वय को प्रभावित करता है।"},
  {"id":"cdp-child-development-39","question":"Under NEP 2020, the foundational stage covers children aged:","options":["3 to 6 years","3 to 8 years","6 to 10 years","5 to 8 years"],"answer":1,"explanation":"The foundational stage spans three years of pre-school (ages 3–6) plus classes 1 and 2 (ages 6–8).","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"NEP 2020 के अंतर्गत आधारभूत चरण किस आयु के बच्चों को समेटता है?","optionsHi":["3 से 6 वर्ष","3 से 8 वर्ष","6 से 10 वर्ष","5 से 8 वर्ष"],"explanationHi":"आधारभूत चरण में तीन वर्ष का प्री-स्कूल (आयु 3–6) तथा कक्षा 1 और 2 (आयु 6–8) शामिल हैं।"},
  {"id":"cdp-child-development-40","question":"Kohlberg’s “good boy–good girl” orientation, where a child seeks approval of others, belongs to the:","options":["Pre-conventional level","Conventional level","Post-conventional level","Autonomous level"],"answer":1,"explanation":"Stage 3 (interpersonal conformity) is the first stage of the conventional level; stage 4 is law-and-order orientation.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"कोहलबर्ग का “अच्छा लड़का–अच्छी लड़की” अभिविन्यास, जहाँ बच्चा दूसरों की स्वीकृति चाहता है, किस स्तर का है?","optionsHi":["पूर्व-परंपरागत स्तर","परंपरागत स्तर","उत्तर-परंपरागत स्तर","स्वायत्त स्तर"],"explanationHi":"चरण 3 (पारस्परिक अनुरूपता) परंपरागत स्तर का पहला चरण है; चरण 4 कानून-और-व्यवस्था अभिविन्यास है।"},
  {"id":"cdp-child-development-41","question":"A toddler who has learnt the word “dog” sees a cow for the first time and calls it “dog”. In Piaget’s terms this is an example of:","options":["Accommodation","Assimilation","Equilibration","Conservation"],"answer":1,"explanation":"The child fits new experience into an existing schema (assimilation); creating a new schema for “cow” would be accommodation.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"एक छोटा बच्चा “कुत्ता” शब्द सीख चुका है। वह पहली बार गाय को देखता है और उसे “कुत्ता” कहता है। पियाजे की शब्दावली में यह किसका उदाहरण है?","optionsHi":["समायोजन","आत्मसात्करण","साम्यधारण","संरक्षण"],"explanationHi":"बच्चा नए अनुभव को अपनी मौजूदा स्कीमा में बैठा लेता है (आत्मसात्करण); “गाय” के लिए नई स्कीमा बनाना समायोजन होता।"},
  {"id":"cdp-child-development-42","question":"Erikson’s stage of “autonomy vs shame and doubt” corresponds to the age range:","options":["Birth to 1 year","1 to 3 years","3 to 6 years","6 to 12 years"],"answer":1,"explanation":"Toddlers (1–3 years) learn self-control and independence; success gives autonomy, over-restriction gives shame and doubt.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"एरिक्सन की “स्वायत्तता बनाम शर्म और संदेह” अवस्था किस आयु वर्ग से संबंधित है?","optionsHi":["जन्म से 1 वर्ष","1 से 3 वर्ष","3 से 6 वर्ष","6 से 12 वर्ष"],"explanationHi":"छोटे बच्चे (1–3 वर्ष) आत्म-नियंत्रण और स्वतंत्रता सीखते हैं; सफलता से स्वायत्तता मिलती है, अत्यधिक रोक-टोक से शर्म और संदेह।"},
  {"id":"cdp-child-development-43","question":"The pupil–teacher ratio prescribed by the RTE Act for classes I to V is:","options":["25:1","30:1","35:1","40:1"],"answer":1,"explanation":"The Schedule to the RTE Act requires 30:1 for classes I–V (two teachers for up to 60 children) and 35:1 for classes VI–VIII.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"RTE अधिनियम द्वारा कक्षा I से V के लिए निर्धारित विद्यार्थी–शिक्षक अनुपात कितना है?","optionsHi":["25:1","30:1","35:1","40:1"],"explanationHi":"RTE अधिनियम की अनुसूची कक्षा I–V के लिए 30:1 (60 बच्चों तक दो शिक्षक) और कक्षा VI–VIII के लिए 35:1 अनिवार्य करती है।"},
  {"id":"cdp-child-development-44","question":"Dyscalculia refers to a specific learning difficulty in:","options":["Reading fluency","Spelling and writing","Mathematics","Speech articulation"],"answer":2,"explanation":"Dyscalculia affects number sense and arithmetic; such children struggle with counting, place value and simple calculations.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"डिस्कैल्कुलिया किस क्षेत्र में विशिष्ट अधिगम कठिनाई को कहते हैं?","optionsHi":["पठन प्रवाह","वर्तनी और लेखन","गणित","वाणी उच्चारण"],"explanationHi":"डिस्कैल्कुलिया संख्या-बोध और अंकगणित को प्रभावित करता है; ऐसे बच्चों को गिनती, स्थानीय मान और सरल गणनाओं में कठिनाई होती है।"},
  {"id":"cdp-child-development-45","question":"A student who easily understands the moods and feelings of classmates shows, in Gardner’s theory, a high level of:","options":["Intrapersonal intelligence","Interpersonal intelligence","Naturalistic intelligence","Linguistic intelligence"],"answer":1,"explanation":"Interpersonal intelligence is sensitivity to others’ feelings and motives; intrapersonal intelligence is understanding one’s own emotions.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"जो विद्यार्थी अपने सहपाठियों के मनोभावों और भावनाओं को आसानी से समझ लेता है, वह गार्डनर के सिद्धांत में किस बुद्धि के उच्च स्तर को दर्शाता है?","optionsHi":["अंतःव्यक्तिक बुद्धि","अंतर्वैयक्तिक (पारस्परिक) बुद्धि","प्रकृतिवादी बुद्धि","भाषायी बुद्धि"],"explanationHi":"पारस्परिक बुद्धि दूसरों की भावनाओं और मंशाओं के प्रति संवेदनशीलता है; अंतःव्यक्तिक बुद्धि अपनी भावनाओं को समझना है।"},
  {"id":"cdp-child-development-46","question":"Bandura’s Bobo doll experiment demonstrated:","options":["Classical conditioning","Insight learning","Observational learning","Trial-and-error learning"],"answer":2,"explanation":"Children who watched an adult hit the doll imitated the aggression, showing that behaviour is learnt by observing models (social learning theory).","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"बंडूरा के बोबो डॉल प्रयोग ने क्या प्रदर्शित किया?","optionsHi":["शास्त्रीय अनुबंधन","अंतर्दृष्टि अधिगम","अवलोकनात्मक अधिगम","प्रयास और त्रुटि अधिगम"],"explanationHi":"जिन बच्चों ने किसी वयस्क को गुड़िया को मारते देखा, उन्होंने उस आक्रामकता की नकल की, जो दिखाता है कि व्यवहार आदर्शों (मॉडल) को देखकर सीखा जाता है (सामाजिक अधिगम सिद्धांत)।"},
  {"id":"cdp-child-development-47","question":"Under the RTE Act, a child above six years who has never been admitted to a school shall be admitted to:","options":["Class I, regardless of the child’s actual age","A class appropriate to his or her age","A bridge course for one year first","A pre-primary class to build school readiness"],"answer":1,"explanation":"Section 4 provides age-appropriate admission with special training to help the child catch up with peers.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"RTE अधिनियम के अंतर्गत, छह वर्ष से अधिक आयु के जिस बच्चे का कभी किसी विद्यालय में प्रवेश नहीं हुआ, उसे किसमें प्रवेश दिया जाएगा?","optionsHi":["कक्षा I में, बच्चे की वास्तविक आयु चाहे जो हो","उसकी आयु के अनुरूप कक्षा में","पहले एक वर्ष के सेतु पाठ्यक्रम में","विद्यालय-तत्परता बनाने के लिए प्री-प्राइमरी कक्षा में"],"explanationHi":"धारा 4 आयु के अनुरूप प्रवेश का प्रावधान करती है, साथ ही विशेष प्रशिक्षण देती है ताकि बच्चा अपने साथियों के बराबर आ सके।"},
  {"id":"cdp-child-development-48","question":"How many of these statements about Piaget’s theory are correct? I. The formal operational stage begins at about 11 years. II. Reversibility of thought is achieved in the concrete operational stage. III. Animism is a feature of the pre-operational stage. IV. Piaget held that learning precedes development.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: Piaget held that development precedes and limits learning; it is Vygotsky who argued that learning can lead development.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"पियाजे के सिद्धांत के बारे में इनमें से कितने कथन सही हैं? I. औपचारिक संक्रियात्मक अवस्था लगभग 11 वर्ष की आयु से शुरू होती है। II. चिंतन की उत्क्रमणीयता मूर्त संक्रियात्मक अवस्था में प्राप्त होती है। III. सजीववाद पूर्व-संक्रियात्मक अवस्था की विशेषता है। IV. पियाजे का मत था कि अधिगम विकास से पहले आता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: पियाजे का मत था कि विकास अधिगम से पहले आता है और उसे सीमित करता है; यह वाइगोत्स्की हैं जिन्होंने तर्क दिया कि अधिगम विकास को आगे ले जा सकता है।"},
  {"id":"cdp-child-development-49","question":"Assertion (A): Vygotsky stressed scaffolding by a more knowledgeable other. Reason (R): For Vygotsky, cognitive development is a socially mediated process.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because higher mental functions develop through interaction with capable others, support within the zone of proximal development (scaffolding) is central; R is the reason for A.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"अभिकथन (A): वाइगोत्स्की ने किसी अधिक जानकार व्यक्ति द्वारा पाड़ (scaffolding) देने पर बल दिया। कारण (R): वाइगोत्स्की के लिए संज्ञानात्मक विकास एक सामाजिक रूप से मध्यस्थित प्रक्रिया है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"चूँकि उच्च मानसिक प्रक्रियाएँ सक्षम व्यक्तियों के साथ अंतःक्रिया से विकसित होती हैं, इसलिए निकटस्थ विकास के क्षेत्र में दिया गया सहारा (पाड़) केंद्रीय है; R ही A का कारण है।"},
  {"id":"cdp-child-development-50","question":"Match Kohlberg’s stages with their orientations: 1. Stage 1 2. Stage 2 3. Stage 4 4. Stage 6; a. Universal ethical principles b. Law and order c. Punishment and obedience d. Instrumental exchange (“what’s in it for me”)","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-a, 4-b"],"answer":0,"explanation":"Stage 1 punishment–obedience, stage 2 instrumental exchange, stage 3 good boy–good girl, stage 4 law and order, stage 5 social contract, stage 6 universal ethical principles.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"कोहलबर्ग के चरणों का उनके अभिविन्यासों से मिलान कीजिए: 1. चरण 1 2. चरण 2 3. चरण 4 4. चरण 6; a. सार्वभौमिक नैतिक सिद्धांत b. कानून और व्यवस्था c. दंड और आज्ञापालन d. साधनात्मक विनिमय (“इसमें मेरा क्या फायदा”)","optionsHi":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-a, 4-b"],"explanationHi":"चरण 1 दंड–आज्ञापालन, चरण 2 साधनात्मक विनिमय, चरण 3 अच्छा लड़का–अच्छी लड़की, चरण 4 कानून और व्यवस्था, चरण 5 सामाजिक अनुबंध, चरण 6 सार्वभौमिक नैतिक सिद्धांत।"},
  {"id":"cdp-child-development-51","question":"Which of the following is NOT a principle of development?","options":["Development proceeds from head to toe (cephalocaudal)","Development proceeds from the centre of the body outward (proximodistal)","Development proceeds from specific to general","Development is a continuous process"],"answer":2,"explanation":"Development moves from general to specific: a baby waves its whole arm before it can grasp with its fingers.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"निम्नलिखित में से कौन-सा विकास का सिद्धांत नहीं है?","optionsHi":["विकास सिर से पैर की ओर होता है (शीर्षगामी)","विकास शरीर के केंद्र से बाहर की ओर होता है (निकट-दूर)","विकास विशिष्ट से सामान्य की ओर होता है","विकास एक सतत प्रक्रिया है"],"explanationHi":"विकास सामान्य से विशिष्ट की ओर होता है: शिशु उँगलियों से पकड़ना सीखने से पहले पूरी बाँह हिलाता है।"},
  {"id":"cdp-child-development-52","question":"How many of these statements about the RTE Act, 2009 are correct? I. It covers children aged 6 to 14 years. II. Section 12(1)(c) requires private unaided schools to admit at least 25% children from weaker sections in the entry class. III. No board examination may be held until the completion of elementary education. IV. Mild physical punishment is permitted as a last resort.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct (Section 30 bars board exams). IV is wrong: Section 17 prohibits all physical punishment and mental harassment.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"RTE अधिनियम, 2009 के बारे में इनमें से कितने कथन सही हैं? I. यह 6 से 14 वर्ष के बच्चों को समेटता है। II. धारा 12(1)(c) के अनुसार निजी गैर-सहायता प्राप्त विद्यालयों को प्रारंभिक कक्षा में कमजोर वर्गों के कम से कम 25% बच्चों को प्रवेश देना होगा। III. प्रारंभिक शिक्षा पूरी होने तक कोई बोर्ड परीक्षा नहीं ली जा सकती। IV. अंतिम उपाय के रूप में हल्का शारीरिक दंड स्वीकृत है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं (धारा 30 बोर्ड परीक्षाओं पर रोक लगाती है)। IV गलत है: धारा 17 सभी प्रकार के शारीरिक दंड और मानसिक उत्पीड़न को प्रतिबंधित करती है।"},
  {"id":"cdp-child-development-53","question":"How many of these statements about NEP 2020 are correct? I. It replaces the 10+2 structure with 5+3+3+4. II. It aims at a 100% Gross Enrolment Ratio in school education by 2030. III. It makes the mother tongue compulsory as the medium of instruction up to class 8. IV. It was approved by the Union Cabinet on 29 July 2020.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. III is wrong: NEP 2020 says the home language or mother tongue should be the medium “wherever possible” at least till class 5, preferably till class 8; it is a recommendation, not a compulsion.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"NEP 2020 के बारे में इनमें से कितने कथन सही हैं? I. यह 10+2 संरचना की जगह 5+3+3+4 लाती है। II. इसका लक्ष्य 2030 तक विद्यालयी शिक्षा में 100% सकल नामांकन अनुपात है। III. यह कक्षा 8 तक शिक्षा के माध्यम के रूप में मातृभाषा को अनिवार्य बनाती है। IV. इसे 29 जुलाई 2020 को केंद्रीय मंत्रिमंडल ने मंजूरी दी।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। III गलत है: NEP 2020 कहती है कि “जहाँ तक संभव हो” कम से कम कक्षा 5 तक, और अधिमानतः कक्षा 8 तक, घर की भाषा या मातृभाषा शिक्षा का माध्यम हो; यह अनुशंसा है, बाध्यता नहीं।"},
  {"id":"cdp-child-development-54","question":"In Maslow’s hierarchy, which need comes immediately above safety needs?","options":["Esteem and recognition needs","Self-actualisation needs","Belongingness and love needs","Physiological (survival) needs"],"answer":2,"explanation":"The order from the base is physiological → safety → belongingness and love → esteem → self-actualisation.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"मैस्लो के पदानुक्रम में सुरक्षा आवश्यकताओं के ठीक ऊपर कौन-सी आवश्यकता आती है?","optionsHi":["सम्मान और मान्यता की आवश्यकताएँ","आत्म-सिद्धि की आवश्यकताएँ","अपनत्व और प्रेम की आवश्यकताएँ","शारीरिक (जीवन-रक्षा) आवश्यकताएँ"],"explanationHi":"आधार से क्रम यह है: शारीरिक → सुरक्षा → अपनत्व और प्रेम → सम्मान → आत्म-सिद्धि।"},
  {"id":"cdp-child-development-55","question":"Assertion (A): A teacher should use formative assessment regularly during a unit. Reason (R): Formative assessment gives feedback that lets the teacher modify teaching while learning is still in progress.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Formative assessment is “assessment for learning”; its purpose is timely feedback, which is exactly why it should be continuous.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"अभिकथन (A): शिक्षक को इकाई के दौरान नियमित रूप से रचनात्मक आकलन करना चाहिए। कारण (R): रचनात्मक आकलन ऐसी प्रतिपुष्टि देता है जिससे अधिगम चलते रहने के दौरान ही शिक्षक अपना शिक्षण बदल सकता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"रचनात्मक आकलन “अधिगम के लिए आकलन” है; इसका उद्देश्य समय पर प्रतिपुष्टि देना है, और इसी कारण यह सतत होना चाहिए।"},
  {"id":"cdp-child-development-56","question":"Match the psychologist with the concept: 1. Pavlov 2. Chomsky 3. Binet 4. Spearman; a. g-factor of intelligence b. Language acquisition device c. First intelligence test d. Classical conditioning","options":["1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a","1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-a, 4-c"],"answer":0,"explanation":"Pavlov → classical conditioning, Chomsky → innate language acquisition device, Binet → first practical intelligence test (1905), Spearman → two-factor (g and s) theory.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"मनोवैज्ञानिक का अवधारणा से मिलान कीजिए: 1. पावलोव 2. चॉम्स्की 3. बिने 4. स्पीयरमैन; a. बुद्धि का g-कारक b. भाषा अर्जन युक्ति c. पहला बुद्धि परीक्षण d. शास्त्रीय अनुबंधन","optionsHi":["1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a","1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-a, 4-c"],"explanationHi":"पावलोव → शास्त्रीय अनुबंधन, चॉम्स्की → जन्मजात भाषा अर्जन युक्ति, बिने → पहला व्यावहारिक बुद्धि परीक्षण (1905), स्पीयरमैन → द्विकारक (g और s) सिद्धांत।"},
  {"id":"cdp-child-development-57","question":"How many of these statements about theories of intelligence are correct? I. Spearman proposed the two-factor theory. II. Thurstone proposed seven primary mental abilities. III. The Binet–Simon scale was first published in 1905. IV. Sternberg’s triarchic theory includes analytical, creative and practical intelligence.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct; the common confusion is attributing multiple intelligences (Gardner) to Thurstone or the g-factor to Binet.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"बुद्धि के सिद्धांतों के बारे में इनमें से कितने कथन सही हैं? I. स्पीयरमैन ने द्विकारक सिद्धांत प्रस्तावित किया। II. थर्स्टन ने सात प्राथमिक मानसिक योग्यताएँ प्रस्तावित कीं। III. बिने–साइमन पैमाना पहली बार 1905 में प्रकाशित हुआ। IV. स्टर्नबर्ग के त्रितंत्र सिद्धांत में विश्लेषणात्मक, सृजनात्मक और व्यावहारिक बुद्धि शामिल हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं; आम भ्रम बहुबुद्धि (गार्डनर) को थर्स्टन से या g-कारक को बिने से जोड़ देने का है।"},
  {"id":"cdp-child-development-58","question":"A four-year-old says her doll is “sad” because it fell down. According to Piaget, this illustrates:","options":["Conservation","Animism","Reversibility","Decentration"],"answer":1,"explanation":"Animism, attributing life and feelings to inanimate objects, is typical of the pre-operational stage; conservation and reversibility come later.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"एक चार वर्ष की बच्ची कहती है कि उसकी गुड़िया “उदास” है क्योंकि वह गिर गई। पियाजे के अनुसार यह क्या दर्शाता है?","optionsHi":["संरक्षण","सजीववाद","उत्क्रमणीयता","विकेंद्रण"],"explanationHi":"निर्जीव वस्तुओं में जीवन और भावनाएँ मानना सजीववाद है, जो पूर्व-संक्रियात्मक अवस्था की विशेषता है; संरक्षण और उत्क्रमणीयता बाद में आते हैं।"},
  {"id":"cdp-child-development-59","question":"A student refuses to copy in an examination, saying “rules must be obeyed, otherwise there will be chaos in school”. In Kohlberg’s scheme the student is at:","options":["Stage 1, punishment and obedience","Stage 3, interpersonal conformity","Stage 4, law and order","Stage 5, social contract"],"answer":2,"explanation":"Reasoning that rules must be upheld to maintain social order is the law-and-order orientation (stage 4, conventional level); stage 1 would cite fear of punishment.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"एक विद्यार्थी परीक्षा में नकल करने से इनकार करता है और कहता है, “नियमों का पालन होना चाहिए, वरना विद्यालय में अव्यवस्था फैल जाएगी।” कोहलबर्ग की योजना में वह किस चरण पर है?","optionsHi":["चरण 1, दंड और आज्ञापालन","चरण 3, पारस्परिक अनुरूपता","चरण 4, कानून और व्यवस्था","चरण 5, सामाजिक अनुबंध"],"explanationHi":"सामाजिक व्यवस्था बनाए रखने के लिए नियमों का पालन आवश्यक मानना कानून-और-व्यवस्था अभिविन्यास (चरण 4, परंपरागत स्तर) है; चरण 1 में दंड के भय का हवाला दिया जाता।"},
  {"id":"cdp-child-development-60","question":"Inclusive education means:","options":["Separate special schools for children with disabilities","All children learning together in regular classrooms","Admitting only students who pass an entrance test","Teaching every subject only through the mother tongue"],"answer":1,"explanation":"Inclusive education places every child, whatever their ability, background or disability, in the same classroom and adapts teaching to meet their needs.","difficulty":"easy","source":"CTET · State TETs","questionHi":"समावेशी शिक्षा का अर्थ है:","optionsHi":["दिव्यांग बच्चों के लिए अलग विशेष विद्यालय","सभी बच्चों का नियमित कक्षाओं में एक साथ सीखना","केवल प्रवेश परीक्षा उत्तीर्ण करने वाले विद्यार्थियों को प्रवेश देना","प्रत्येक विषय को केवल मातृभाषा में पढ़ाना"],"explanationHi":"समावेशी शिक्षा हर बच्चे को, चाहे उसकी योग्यता, पृष्ठभूमि या दिव्यांगता कुछ भी हो, एक ही कक्षा में रखती है और उनकी आवश्यकताओं के अनुसार शिक्षण को ढालती है।"},
  {"id":"cdp-child-development-61","question":"The idea of “learning by doing” is most closely associated with:","options":["B. F. Skinner","Ivan Pavlov","John Dewey","Sigmund Freud"],"answer":2,"explanation":"John Dewey, the pragmatist philosopher, held that children learn best through activity and real experience rather than passive listening.","difficulty":"easy","source":"CTET · State TETs","questionHi":"“करके सीखना” का विचार सबसे अधिक किससे जुड़ा है?","optionsHi":["बी. एफ. स्किनर","इवान पावलोव","जॉन डेवी","सिगमंड फ्रायड"],"explanationHi":"जॉन डेवी, जो एक प्रयोजनवादी दार्शनिक थे, का मत था कि बच्चे निष्क्रिय होकर सुनने की बजाय गतिविधि और वास्तविक अनुभव से सबसे अच्छा सीखते हैं।"},
  {"id":"cdp-child-development-62","question":"Kohlberg’s theory of moral development has:","options":["Three stages with no separate levels","Six stages grouped into three levels","Eight stages that span the whole lifespan","Four stages that match Piaget’s stages"],"answer":1,"explanation":"Kohlberg described pre-conventional, conventional and post-conventional levels, each with two stages, making six stages in all.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कोहलबर्ग के नैतिक विकास के सिद्धांत में क्या है?","optionsHi":["तीन चरण, अलग से कोई स्तर नहीं","तीन स्तरों में बँटे छह चरण","पूरे जीवनकाल में फैले आठ चरण","पियाजे की अवस्थाओं से मेल खाते चार चरण"],"explanationHi":"कोहलबर्ग ने पूर्व-परंपरागत, परंपरागत और उत्तर-परंपरागत स्तर बताए, जिनमें से प्रत्येक में दो चरण हैं, यानी कुल छह चरण।"},
  {"id":"cdp-child-development-63","question":"Which of these is an example of intrinsic motivation?","options":["A student studies hard to win the class prize","A student reads storybooks because she enjoys it","A student works hard so as to avoid punishment","A student studies to please her parents and teachers"],"answer":1,"explanation":"Intrinsic motivation comes from interest and enjoyment of the activity itself. Prizes, punishment and approval of others are external (extrinsic) motivators.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"इनमें से कौन-सा आंतरिक अभिप्रेरणा का उदाहरण है?","optionsHi":["एक विद्यार्थी कक्षा का पुरस्कार जीतने के लिए कठिन पढ़ाई करता है","एक विद्यार्थी कहानी की किताबें इसलिए पढ़ती है क्योंकि उसे अच्छा लगता है","एक विद्यार्थी दंड से बचने के लिए कड़ी मेहनत करता है","एक विद्यार्थी अपने माता-पिता और शिक्षकों को खुश करने के लिए पढ़ती है"],"explanationHi":"आंतरिक अभिप्रेरणा गतिविधि में ही रुचि और आनंद से आती है। पुरस्कार, दंड और दूसरों की स्वीकृति बाह्य अभिप्रेरक हैं।"},
  {"id":"cdp-child-development-64","question":"ADHD, a condition that affects a child’s attention and self-control in class, stands for:","options":["Attention Deficit Hyperactivity Disorder","Auditory Development Hearing Disorder","Acquired Developmental Handicap Disorder","Attention Delay and Hearing Difficulty"],"answer":0,"explanation":"Children with Attention Deficit Hyperactivity Disorder find it hard to sustain attention and may be impulsive or overactive; short tasks and structured routines help them.","difficulty":"moderate","source":"CTET · KVS · State TETs","questionHi":"ADHD, एक ऐसी स्थिति जो कक्षा में बच्चे के ध्यान और आत्म-नियंत्रण को प्रभावित करती है, का पूर्ण रूप है:","optionsHi":["ध्यान अभाव सक्रियता विकार (Attention Deficit Hyperactivity Disorder)","श्रवण विकास श्रवण विकार (Auditory Development Hearing Disorder)","अर्जित विकासात्मक विकलांगता विकार (Acquired Developmental Handicap Disorder)","ध्यान विलंब और श्रवण कठिनाई (Attention Delay and Hearing Difficulty)"],"explanationHi":"ध्यान अभाव सक्रियता विकार वाले बच्चों को ध्यान टिकाए रखना कठिन लगता है और वे आवेगी या अति-सक्रिय हो सकते हैं; छोटे कार्य और संरचित दिनचर्या उनकी मदद करते हैं।"},
  {"id":"cdp-child-development-65","question":"Continuous and comprehensive evaluation (CCE) of a child’s understanding is provided for in which law?","options":["The Right to Education Act, 2009","The Rights of Persons with Disabilities Act, 2016","The Juvenile Justice Act, 2015","The National Commission for Protection of Child Rights Act, 2005"],"answer":0,"explanation":"Section 29(2) of the RTE Act requires the curriculum and evaluation procedure to include comprehensive and continuous evaluation of the child’s understanding and ability to apply knowledge.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"बच्चे की समझ के सतत और व्यापक मूल्यांकन (CCE) का प्रावधान किस कानून में है?","optionsHi":["शिक्षा का अधिकार अधिनियम, 2009","दिव्यांगजन अधिकार अधिनियम, 2016","किशोर न्याय अधिनियम, 2015","राष्ट्रीय बाल अधिकार संरक्षण आयोग अधिनियम, 2005"],"explanationHi":"RTE अधिनियम की धारा 29(2) के अनुसार पाठ्यचर्या और मूल्यांकन प्रक्रिया में बच्चे की समझ और ज्ञान को प्रयोग में लाने की क्षमता का व्यापक एवं सतत मूल्यांकन शामिल होना चाहिए।"},
  {"id":"cdp-child-development-66","question":"According to Freud, the “id” operates on the:","options":["Reality principle","Morality principle","Pleasure principle","Social principle"],"answer":2,"explanation":"The id seeks immediate gratification (pleasure principle), the ego follows the reality principle, and the superego represents moral standards.","difficulty":"moderate","source":"CTET · KVS · State TETs","questionHi":"फ्रायड के अनुसार “इड” किस सिद्धांत पर कार्य करता है?","optionsHi":["वास्तविकता सिद्धांत","नैतिकता सिद्धांत","सुख सिद्धांत","सामाजिक सिद्धांत"],"explanationHi":"इड तत्काल संतुष्टि चाहता है (सुख सिद्धांत), ईगो वास्तविकता सिद्धांत का पालन करता है, और सुपरईगो नैतिक मानकों का प्रतिनिधित्व करता है।"},
  {"id":"cdp-child-development-67","question":"In Piaget’s theory, a “schema” is:","options":["A reward-and-punishment plan for shaping behaviour","An organised mental pattern for understanding the world","A standardised test that measures a child’s mental age","The gap between what a child can do alone and with help"],"answer":1,"explanation":"Schemas are mental frameworks that are built and changed through assimilation and accommodation. The gap described in the last option is Vygotsky’s ZPD.","difficulty":"hard","source":"CTET · State TETs","questionHi":"पियाजे के सिद्धांत में “स्कीमा” क्या है?","optionsHi":["व्यवहार को आकार देने की पुरस्कार-और-दंड योजना","संसार को समझने का एक संगठित मानसिक प्रतिरूप","बच्चे की मानसिक आयु मापने वाला मानकीकृत परीक्षण","बच्चा अकेले क्या कर सकता है और सहायता से क्या कर सकता है, इसके बीच का अंतर"],"explanationHi":"स्कीमाएँ मानसिक ढाँचे हैं जो आत्मसात्करण और समायोजन द्वारा बनते और बदलते हैं। अंतिम विकल्प में वर्णित अंतर वाइगोत्स्की का ZPD है।"},
  {"id":"cdp-child-development-68","question":"Which intelligence did Howard Gardner add in 1995 as the eighth in his theory of multiple intelligences?","options":["Existential","Naturalistic","Emotional","Interpersonal"],"answer":1,"explanation":"Gardner added naturalistic intelligence (recognising and classifying plants, animals and nature) in 1995. Existential intelligence has only been suggested as a possible ninth.","difficulty":"hard","source":"CTET · State TETs","questionHi":"हॉवर्ड गार्डनर ने 1995 में अपने बहुबुद्धि सिद्धांत में आठवीं बुद्धि के रूप में कौन-सी बुद्धि जोड़ी?","optionsHi":["अस्तित्वपरक","प्रकृतिवादी","भावनात्मक","अंतर्वैयक्तिक"],"explanationHi":"गार्डनर ने 1995 में प्रकृतिवादी बुद्धि (पौधों, जानवरों और प्रकृति को पहचानना और वर्गीकृत करना) जोड़ी। अस्तित्वपरक बुद्धि को केवल संभावित नौवीं के रूप में सुझाया गया है।"},
  {"id":"cdp-child-development-69","question":"Which of these is NOT one of Thorndike’s primary laws of learning?","options":["Law of readiness","Law of exercise","Law of effect","Law of insight"],"answer":3,"explanation":"Thorndike’s three primary laws are readiness, exercise and effect. Insight learning comes from Köhler and the Gestalt school.","difficulty":"hard","source":"CTET · State TETs","questionHi":"इनमें से कौन-सा थॉर्नडाइक का अधिगम का प्राथमिक नियम नहीं है?","optionsHi":["तत्परता का नियम","अभ्यास का नियम","प्रभाव का नियम","अंतर्दृष्टि का नियम"],"explanationHi":"थॉर्नडाइक के तीन प्राथमिक नियम तत्परता, अभ्यास और प्रभाव हैं। अंतर्दृष्टि अधिगम कोहलर और गेस्टाल्ट संप्रदाय से आता है।"},
  {"id":"cdp-child-development-70","question":"A teacher asks, “In how many ways can we use a brick?” This question mainly encourages:","options":["Convergent thinking","Divergent thinking","Rote memory","Concrete operational thinking"],"answer":1,"explanation":"Open-ended questions with many possible answers promote divergent (creative) thinking. Convergent thinking aims at one correct answer.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"एक शिक्षक पूछता है, “हम ईंट का कितने तरीकों से उपयोग कर सकते हैं?” यह प्रश्न मुख्यतः किसे प्रोत्साहित करता है?","optionsHi":["अभिसारी चिंतन","अपसारी चिंतन","रटने की स्मृति","मूर्त संक्रियात्मक चिंतन"],"explanationHi":"कई संभावित उत्तरों वाले खुले प्रश्न अपसारी (सृजनात्मक) चिंतन को बढ़ावा देते हैं। अभिसारी चिंतन का लक्ष्य एक ही सही उत्तर होता है।"},
  {"id":"cdp-child-development-71","question":"According to Vygotsky, a child talking aloud to herself while solving a puzzle (private speech):","options":["Shows that she is egocentric and immature","Helps her guide and regulate her own thinking","Is an early sign of a speech or language disorder","Should be stopped at once, as it disturbs others"],"answer":1,"explanation":"Vygotsky saw private speech as a tool of self-regulation that later becomes inner speech. Piaget, by contrast, called it egocentric speech.","difficulty":"hard","source":"CTET · State TETs","questionHi":"वाइगोत्स्की के अनुसार, पहेली हल करते समय किसी बच्ची का स्वयं से ज़ोर-ज़ोर से बोलना (निजी वाक्):","optionsHi":["यह दर्शाता है कि वह अहंकेंद्रित और अपरिपक्व है","उसे अपने चिंतन को निर्देशित और नियंत्रित करने में मदद करता है","वाणी या भाषा विकार का प्रारंभिक संकेत है","तुरंत रोक देना चाहिए, क्योंकि इससे दूसरों को बाधा होती है"],"explanationHi":"वाइगोत्स्की निजी वाक् को आत्म-नियमन का उपकरण मानते थे जो आगे चलकर आंतरिक वाक् बन जाता है। इसके विपरीत, पियाजे ने इसे अहंकेंद्रित वाक् कहा।"},
  {"id":"cdp-child-development-72","question":"Which of the following is a projective test of personality?","options":["16PF questionnaire","Rorschach inkblot test","Stanford–Binet test","Raven’s Progressive Matrices"],"answer":1,"explanation":"In the Rorschach test the subject interprets ambiguous inkblots, projecting inner feelings. 16PF is a self-report inventory, while Stanford–Binet and Raven’s are intelligence tests.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"निम्नलिखित में से कौन-सा व्यक्तित्व का प्रक्षेपी परीक्षण है?","optionsHi":["16PF प्रश्नावली","रोर्शा स्याही-धब्बा परीक्षण","स्टैनफोर्ड–बिने परीक्षण","रेवेन की प्रोग्रेसिव मैट्रिसेस"],"explanationHi":"रोर्शा परीक्षण में व्यक्ति अस्पष्ट स्याही-धब्बों की व्याख्या करता है और अपनी आंतरिक भावनाओं का प्रक्षेपण करता है। 16PF एक स्व-प्रतिवेदन सूची है, जबकि स्टैनफोर्ड–बिने और रेवेन के परीक्षण बुद्धि परीक्षण हैं।"},
  {"id":"cdp-child-development-73","question":"A test given to find the specific areas in which a student has learning difficulties is a:","options":["Diagnostic test","Achievement test","Aptitude test","Placement test"],"answer":0,"explanation":"A diagnostic test pinpoints the exact weaknesses so that remedial teaching can follow. An achievement test measures how much has been learnt.","difficulty":"hard","source":"CTET · State TETs","questionHi":"यह पता लगाने के लिए दिया गया परीक्षण कि विद्यार्थी को किन विशिष्ट क्षेत्रों में अधिगम कठिनाई है, कहलाता है:","optionsHi":["निदानात्मक परीक्षण","उपलब्धि परीक्षण","अभिक्षमता परीक्षण","स्थान-निर्धारण परीक्षण"],"explanationHi":"निदानात्मक परीक्षण सटीक कमजोरियों की पहचान करता है ताकि उसके बाद उपचारात्मक शिक्षण दिया जा सके। उपलब्धि परीक्षण यह मापता है कि कितना सीखा गया है।"},
  {"id":"cdp-child-development-74","question":"Arrange these levels of Bloom’s revised taxonomy from the lowest to the highest: 1. Applying 2. Remembering 3. Creating 4. Analysing","options":["2, 1, 4, 3","2, 4, 1, 3","1, 2, 4, 3","2, 1, 3, 4"],"answer":0,"explanation":"The revised taxonomy (Anderson and Krathwohl, 2001) runs Remembering → Understanding → Applying → Analysing → Evaluating → Creating, with Creating at the top.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"ब्लूम के संशोधित वर्गीकरण के इन स्तरों को निम्नतम से उच्चतम क्रम में व्यवस्थित कीजिए: 1. अनुप्रयोग (Applying) 2. स्मरण (Remembering) 3. सृजन (Creating) 4. विश्लेषण (Analysing)","optionsHi":["2, 1, 4, 3","2, 4, 1, 3","1, 2, 4, 3","2, 1, 3, 4"],"explanationHi":"संशोधित वर्गीकरण (एंडरसन और क्रैथवोल, 2001) का क्रम है: स्मरण → बोध → अनुप्रयोग → विश्लेषण → मूल्यांकन → सृजन, जिसमें सृजन सबसे ऊपर है।"},
  {"id":"cdp-child-development-75","question":"Assertion (A): Constructivist teaching discourages rote memorisation of facts. Reason (R): Constructivism holds that learners actively build knowledge by linking new experiences to what they already know.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because knowledge is constructed, not received, constructivists prefer activities, discussion and exploration over memorising. R explains A.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): रचनावादी शिक्षण तथ्यों को रटने को हतोत्साहित करता है। कारण (R): रचनावाद मानता है कि अधिगमकर्ता नए अनुभवों को अपने पूर्व ज्ञान से जोड़कर सक्रिय रूप से ज्ञान का निर्माण करते हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"चूँकि ज्ञान ग्रहण नहीं किया जाता बल्कि निर्मित किया जाता है, रचनावादी रटने की बजाय गतिविधियों, चर्चा और अन्वेषण को पसंद करते हैं। R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-76","question":"Assertion (A): Boys and girls should be given different curricula because gender decides intellectual ability. Reason (R): Gender roles are largely shaped by society through socialisation.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"A is false: intellectual ability does not depend on gender, and separate curricula reinforce stereotypes. R is true: gender is a social construct learnt through family, school and media.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): लड़कों और लड़कियों को अलग-अलग पाठ्यचर्या दी जानी चाहिए क्योंकि लिंग बौद्धिक योग्यता तय करता है। कारण (R): लिंग भूमिकाएँ काफी हद तक समाज द्वारा समाजीकरण के माध्यम से गढ़ी जाती हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"A असत्य है: बौद्धिक योग्यता लिंग पर निर्भर नहीं करती, और अलग पाठ्यचर्या रूढ़ियों को बढ़ावा देती है। R सत्य है: लिंग एक सामाजिक निर्मिति है जो परिवार, विद्यालय और मीडिया से सीखी जाती है।"},
  {"id":"cdp-child-development-77","question":"Match the psychologist with the idea: 1. Albert Bandura 2. Jerome Bruner 3. David Ausubel 4. Wolfgang Köhler; a. Insight learning b. Meaningful verbal learning and advance organisers c. Discovery learning d. Social (observational) learning","options":["1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a"],"answer":3,"explanation":"Bandura proposed social learning, Bruner discovery learning, Ausubel meaningful reception learning with advance organisers, and Köhler insight learning.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"मनोवैज्ञानिक का विचार से मिलान कीजिए: 1. अल्बर्ट बंडूरा 2. जेरोम ब्रूनर 3. डेविड ऑसुबेल 4. वोल्फगैंग कोहलर; a. अंतर्दृष्टि अधिगम b. सार्थक शाब्दिक अधिगम और अग्रिम संगठक c. अन्वेषण अधिगम d. सामाजिक (अवलोकनात्मक) अधिगम","optionsHi":["1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a"],"explanationHi":"बंडूरा ने सामाजिक अधिगम, ब्रूनर ने अन्वेषण अधिगम, ऑसुबेल ने अग्रिम संगठकों सहित सार्थक ग्रहणशील अधिगम, और कोहलर ने अंतर्दृष्टि अधिगम प्रस्तावित किया।"},
  {"id":"cdp-child-development-78","question":"Child A is 8 years old with a mental age of 10 years; child B is 10 years old with a mental age of 8 years. What is the difference between their IQs?","options":["20","45","25","2"],"answer":1,"explanation":"IQ = (MA ÷ CA) × 100. A: 10/8 × 100 = 125. B: 8/10 × 100 = 80. Difference = 125 − 80 = 45.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"बच्चा A 8 वर्ष का है और उसकी मानसिक आयु 10 वर्ष है; बच्चा B 10 वर्ष का है और उसकी मानसिक आयु 8 वर्ष है। उनके IQ का अंतर कितना है?","optionsHi":["20","45","25","2"],"explanationHi":"IQ = (मानसिक आयु ÷ कालानुक्रमिक आयु) × 100। A: 10/8 × 100 = 125। B: 8/10 × 100 = 80। अंतर = 125 − 80 = 45।"},
  {"id":"cdp-child-development-79","question":"Which of the following is NOT a feature of a child-centred classroom?","options":["Children learn through activities, play and group discussion","The teacher acts as a facilitator rather than a lecturer","The textbook and teacher are the sole sources of knowledge","Children’s own experiences are linked to what is taught"],"answer":2,"explanation":"Child-centred pedagogy uses many sources of learning and treats the teacher as a facilitator; treating the textbook and teacher as the sole sources of knowledge is the traditional, teacher-centred approach.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"निम्नलिखित में से कौन-सी बाल-केंद्रित कक्षा की विशेषता नहीं है?","optionsHi":["बच्चे गतिविधियों, खेल और समूह चर्चा से सीखते हैं","शिक्षक व्याख्यानदाता की बजाय सुगमकर्ता की भूमिका निभाता है","पाठ्यपुस्तक और शिक्षक ही ज्ञान के एकमात्र स्रोत हैं","बच्चों के अपने अनुभवों को जो पढ़ाया जाता है उससे जोड़ा जाता है"],"explanationHi":"बाल-केंद्रित शिक्षाशास्त्र अधिगम के अनेक स्रोतों का उपयोग करता है और शिक्षक को सुगमकर्ता मानता है; पाठ्यपुस्तक और शिक्षक को ज्ञान का एकमात्र स्रोत मानना पारंपरिक, शिक्षक-केंद्रित दृष्टिकोण है।"},
  {"id":"cdp-child-development-80","question":"How many of these statements about the Rights of Persons with Disabilities Act, 2016 are correct? I. It recognises 14 types of disabilities. II. It replaced the Persons with Disabilities Act, 1995. III. It gives every child with benchmark disability aged 6 to 18 years the right to free education. IV. Specific learning disabilities are not included among the specified disabilities.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and III are correct. I is wrong: the Act recognises 21 types of disabilities, up from seven in the 1995 Act. IV is wrong: specific learning disabilities such as dyslexia are among those 21.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"दिव्यांगजन अधिकार अधिनियम, 2016 के बारे में इनमें से कितने कथन सही हैं? I. यह 14 प्रकार की दिव्यांगताओं को मान्यता देता है। II. इसने दिव्यांगजन अधिनियम, 1995 का स्थान लिया। III. यह 6 से 18 वर्ष की आयु के प्रत्येक बेंचमार्क दिव्यांगता वाले बच्चे को निःशुल्क शिक्षा का अधिकार देता है। IV. विनिर्दिष्ट दिव्यांगताओं में विशिष्ट अधिगम अक्षमताएँ शामिल नहीं हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"II और III सही हैं। I गलत है: अधिनियम 21 प्रकार की दिव्यांगताओं को मान्यता देता है, जो 1995 के अधिनियम के सात प्रकारों से अधिक हैं। IV गलत है: डिस्लेक्सिया जैसी विशिष्ट अधिगम अक्षमताएँ इन 21 में शामिल हैं।"},
  {"id":"cdp-child-development-81","question":"How many of these statements are correct? I. Piaget saw the child as a “little scientist” who constructs knowledge. II. Vygotsky argued that learning leads development. III. Piaget held that language drives thought. IV. Vygotsky proposed four universal, fixed stages of cognitive development.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I and II are correct. Piaget held that thought comes before language, and the four universal stages are Piaget’s idea; Vygotsky stressed culture and social interaction instead of fixed stages.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"इनमें से कितने कथन सही हैं? I. पियाजे बच्चे को “नन्हा वैज्ञानिक” मानते थे जो ज्ञान का निर्माण करता है। II. वाइगोत्स्की का तर्क था कि अधिगम विकास को आगे ले जाता है। III. पियाजे का मत था कि भाषा चिंतन को संचालित करती है। IV. वाइगोत्स्की ने संज्ञानात्मक विकास की चार सार्वभौमिक, निश्चित अवस्थाएँ प्रस्तावित कीं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I और II सही हैं। पियाजे का मत था कि चिंतन भाषा से पहले आता है, और चार सार्वभौमिक अवस्थाएँ पियाजे का विचार हैं; वाइगोत्स्की ने निश्चित अवस्थाओं की बजाय संस्कृति और सामाजिक अंतःक्रिया पर बल दिया।"},
  {"id":"cdp-child-development-82","question":"A teacher excuses students from an extra written task whenever they listen attentively in class, and attentive listening increases. This is an example of:","options":["Positive reinforcement","Negative reinforcement","Punishment","Extinction"],"answer":1,"explanation":"Removing something unpleasant (the extra task) to strengthen a behaviour is negative reinforcement. Punishment weakens behaviour, so it is the common wrong answer.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"एक शिक्षक जब भी विद्यार्थी कक्षा में ध्यान से सुनते हैं, उन्हें अतिरिक्त लिखित कार्य से छूट दे देते हैं, और ध्यान से सुनना बढ़ जाता है। यह किसका उदाहरण है?","optionsHi":["धनात्मक पुनर्बलन","ऋणात्मक पुनर्बलन","दंड","विलोपन"],"explanationHi":"किसी व्यवहार को सुदृढ़ करने के लिए अप्रिय चीज़ (अतिरिक्त कार्य) हटाना ऋणात्मक पुनर्बलन है। दंड व्यवहार को कमजोर करता है, इसलिए वह आम गलत उत्तर है।"},
  {"id":"cdp-child-development-83","question":"How many of these are examples of assessment for learning? I. Oral questions during a lesson followed by feedback II. Peer assessment of first drafts III. A year-end board examination IV. A portfolio reviewed with feedback during the term","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV give feedback while learning is going on, so they are assessment for learning (formative). A year-end board exam is assessment of learning (summative).","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"इनमें से कितने अधिगम के लिए आकलन के उदाहरण हैं? I. पाठ के दौरान मौखिक प्रश्न और उसके बाद प्रतिपुष्टि II. प्रथम प्रारूपों का सहपाठी आकलन III. वर्ष के अंत की बोर्ड परीक्षा IV. सत्र के दौरान प्रतिपुष्टि सहित समीक्षा किया गया पोर्टफोलियो","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV अधिगम चलते रहने के दौरान प्रतिपुष्टि देते हैं, इसलिए वे अधिगम के लिए आकलन (रचनात्मक) हैं। वर्ष के अंत की बोर्ड परीक्षा अधिगम का आकलन (योगात्मक) है।"},
  {"id":"cdp-child-development-84","question":"Arrange in chronological order: 1. National Curriculum Framework 2005 2. Right to Education Act 3. Kothari Commission report 4. National Education Policy 2020","options":["3, 2, 1, 4","1, 3, 2, 4","3, 1, 2, 4","3, 1, 4, 2"],"answer":2,"explanation":"Kothari Commission report 1966 → NCF 2005 → RTE Act 2009 → NEP 2020.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. राष्ट्रीय पाठ्यचर्या की रूपरेखा 2005 2. शिक्षा का अधिकार अधिनियम 3. कोठारी आयोग की रिपोर्ट 4. राष्ट्रीय शिक्षा नीति 2020","optionsHi":["3, 2, 1, 4","1, 3, 2, 4","3, 1, 2, 4","3, 1, 4, 2"],"explanationHi":"कोठारी आयोग की रिपोर्ट 1966 → NCF 2005 → RTE अधिनियम 2009 → NEP 2020।"},
  {"id":"cdp-child-development-85","question":"Who described adolescence as a period of ‘storm and stress’?","options":["G. Stanley Hall","Erik H. Erikson","Sigmund Freud","Lawrence Kohlberg"],"answer":0,"explanation":"G. Stanley Hall, in his 1904 work on adolescence, called it a time of ‘storm and stress’ marked by emotional ups and downs. Erikson described adolescence as identity vs role confusion, and later researchers found that not every adolescent goes through such turmoil.","difficulty":"easy","source":"CTET · UPTET · State TETs","questionHi":"किशोरावस्था को ‘तूफान और तनाव’ का काल किसने कहा?","optionsHi":["जी. स्टैनली हॉल","एरिक एच. एरिक्सन","सिगमंड फ्रायड","लॉरेंस कोहलबर्ग"],"explanationHi":"जी. स्टैनली हॉल ने किशोरावस्था पर अपनी 1904 की कृति में इसे भावनात्मक उतार-चढ़ाव से भरा ‘तूफान और तनाव’ का समय कहा। एरिक्सन ने किशोरावस्था को पहचान बनाम भूमिका भ्रांति बताया, और बाद के शोधकर्ताओं ने पाया कि हर किशोर ऐसी उथल-पुथल से नहीं गुजरता।"},
  {"id":"cdp-child-development-86","question":"The ‘kindergarten’ (children’s garden) system of early education was started by:","options":["John Locke","Rabindranath Tagore","Friedrich Froebel","Maria Montessori"],"answer":2,"explanation":"Friedrich Froebel opened the first kindergarten in Germany in 1837, stressing play, songs and ‘gifts’ (educational toys). Montessori developed her own method later, around 1907.","difficulty":"easy","source":"CTET · UPTET · State TETs","questionHi":"प्रारंभिक शिक्षा की ‘किंडरगार्टन’ (बच्चों का बगीचा) प्रणाली किसने शुरू की?","optionsHi":["जॉन लॉक","रवींद्रनाथ टैगोर","फ्रेडरिक फ्रोबेल","मारिया मॉन्टेसरी"],"explanationHi":"फ्रेडरिक फ्रोबेल ने 1837 में जर्मनी में पहला किंडरगार्टन खोला, जिसमें खेल, गीतों और ‘उपहारों’ (शैक्षिक खिलौनों) पर बल दिया गया। मॉन्टेसरी ने अपनी पद्धति बाद में, लगभग 1907 में, विकसित की।"},
  {"id":"cdp-child-development-87","question":"‘Emile’, the book that urged education according to the child’s nature, was written by:","options":["Jean-Jacques Rousseau","John Dewey","Johann Heinrich Pestalozzi","Friedrich Froebel"],"answer":0,"explanation":"Rousseau’s ‘Emile’ (1762) argued that children should learn through nature and experience at their own pace, an early root of child-centred education.","difficulty":"easy","source":"CTET · UPTET · State TETs","questionHi":"‘एमील’ पुस्तक, जिसने बच्चे की प्रकृति के अनुसार शिक्षा देने का आग्रह किया, किसने लिखी?","optionsHi":["जीन-जैक्स रूसो","जॉन डेवी","जोहान हाइनरिक पेस्टालॉजी","फ्रेडरिक फ्रोबेल"],"explanationHi":"रूसो की ‘एमील’ (1762) ने तर्क दिया कि बच्चों को प्रकृति और अनुभव से अपनी गति से सीखना चाहिए; यह बाल-केंद्रित शिक्षा की एक प्रारंभिक जड़ है।"},
  {"id":"cdp-child-development-88","question":"Development of control proceeding from the head towards the feet, so that a baby controls its head before its legs, is called the:","options":["Cephalocaudal principle","Principle of individual differences","Principle of integration","Proximodistal principle"],"answer":0,"explanation":"Cephalocaudal means ‘head to tail’. The proximodistal principle describes development from the centre of the body outward, for example arm control before finger control.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"नियंत्रण का विकास सिर से पैरों की ओर होना, जिससे शिशु अपने पैरों से पहले सिर पर नियंत्रण करता है, कहलाता है:","optionsHi":["शीर्षगामी सिद्धांत","वैयक्तिक भिन्नता का सिद्धांत","एकीकरण का सिद्धांत","निकट-दूर सिद्धांत"],"explanationHi":"शीर्षगामी का अर्थ है ‘सिर से पूँछ की ओर’। निकट-दूर सिद्धांत शरीर के केंद्र से बाहर की ओर विकास को बताता है, जैसे उँगलियों से पहले बाँह पर नियंत्रण।"},
  {"id":"cdp-child-development-89","question":"The Montessori method of education places the greatest emphasis on:","options":["Self-directed learning with sensory materials","Rote learning under strict teacher control","Competitive examinations from an early age","Learning only through stories told by the teacher"],"answer":0,"explanation":"Montessori classrooms give children self-correcting materials that train the senses, so they learn by themselves (auto-education) while the teacher observes and guides.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"मॉन्टेसरी शिक्षा पद्धति किस पर सबसे अधिक बल देती है?","optionsHi":["संवेदी सामग्री के साथ स्व-निर्देशित अधिगम","शिक्षक के कड़े नियंत्रण में रटकर सीखना","छोटी उम्र से प्रतियोगी परीक्षाएँ","केवल शिक्षक द्वारा सुनाई गई कहानियों से सीखना"],"explanationHi":"मॉन्टेसरी कक्षाओं में बच्चों को स्व-सुधारक सामग्री दी जाती है जो इंद्रियों को प्रशिक्षित करती है, जिससे वे स्वयं सीखते हैं (स्वयं-शिक्षा) जबकि शिक्षक अवलोकन और मार्गदर्शन करता है।"},
  {"id":"cdp-child-development-90","question":"The theory that an infant’s early emotional bond with a caregiver shapes later relationships is the attachment theory of:","options":["John Bowlby","Lawrence Kohlberg","Edward Thorndike","B. F. Skinner"],"answer":0,"explanation":"John Bowlby argued that a secure attachment to a responsive caregiver gives the child a safe base from which to explore. Mary Ainsworth later studied attachment types with the ‘strange situation’ test.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"शिशु का देखभालकर्ता के साथ प्रारंभिक भावनात्मक बंधन बाद के संबंधों को आकार देता है, यह किसका लगाव सिद्धांत है?","optionsHi":["जॉन बाउल्बी","लॉरेंस कोहलबर्ग","एडवर्ड थॉर्नडाइक","बी. एफ. स्किनर"],"explanationHi":"जॉन बाउल्बी ने तर्क दिया कि संवेदनशील देखभालकर्ता से सुरक्षित लगाव बच्चे को अन्वेषण के लिए एक सुरक्षित आधार देता है। मैरी एन्सवर्थ ने बाद में ‘स्ट्रेंज सिचुएशन’ परीक्षण से लगाव के प्रकारों का अध्ययन किया।"},
  {"id":"cdp-child-development-91","question":"Parents who are warm and responsive but also set clear rules and explain them follow which parenting style, according to Diana Baumrind?","options":["Authoritative","Authoritarian","Permissive","Neglectful"],"answer":0,"explanation":"Authoritative parenting combines high warmth with high control and is linked with confident, self-reliant children. Authoritarian parents are strict but cold, and permissive parents are warm but set few limits.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"जो माता-पिता स्नेहपूर्ण और संवेदनशील होते हैं, पर साथ ही स्पष्ट नियम बनाते हैं और उन्हें समझाते हैं, डायना बॉमरिंड के अनुसार वे किस पालन-पोषण शैली का अनुसरण करते हैं?","optionsHi":["प्राधिकारिक (authoritative)","सत्तावादी (authoritarian)","उदार (permissive)","उपेक्षापूर्ण"],"explanationHi":"प्राधिकारिक पालन-पोषण उच्च स्नेह को उच्च नियंत्रण के साथ जोड़ता है और आत्मविश्वासी, आत्मनिर्भर बच्चों से जुड़ा है। सत्तावादी माता-पिता सख्त पर रूखे होते हैं, और उदार माता-पिता स्नेही पर कम सीमाएँ तय करने वाले होते हैं।"},
  {"id":"cdp-child-development-92","question":"A ‘spiral curriculum’, in which topics are revisited at increasing levels of depth, was proposed by:","options":["Jean Piaget","Jerome Bruner","Abraham Maslow","Ivan Pavlov"],"answer":1,"explanation":"Bruner held that any subject can be taught in some honest form to any child, and then revisited in more complex forms as the child grows.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"‘सर्पिल पाठ्यचर्या’, जिसमें विषयों को बढ़ती गहराई के स्तरों पर दोहराया जाता है, किसने प्रस्तावित की?","optionsHi":["जीन पियाजे","जेरोम ब्रूनर","अब्राहम मैस्लो","इवान पावलोव"],"explanationHi":"ब्रूनर का मत था कि किसी भी विषय को किसी सही रूप में किसी भी बच्चे को पढ़ाया जा सकता है, और फिर बच्चे के बड़े होने पर उसे अधिक जटिल रूपों में दोहराया जा सकता है।"},
  {"id":"cdp-child-development-93","question":"The ‘forgetting curve’, showing that most forgetting happens soon after learning, was given by:","options":["Wolfgang Köhler","Hermann Ebbinghaus","Edward L. Thorndike","Frederic Bartlett"],"answer":1,"explanation":"Ebbinghaus tested his own memory of nonsense syllables and found a steep early drop in retention that later levels off. This is why regular revision soon after learning helps.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"‘विस्मरण वक्र’, जो दर्शाता है कि अधिकांश विस्मरण सीखने के तुरंत बाद होता है, किसने दिया?","optionsHi":["वोल्फगैंग कोहलर","हरमन एबिंगहॉस","एडवर्ड एल. थॉर्नडाइक","फ्रेडरिक बार्टलेट"],"explanationHi":"एबिंगहॉस ने निरर्थक शब्दांशों की अपनी ही स्मृति का परीक्षण किया और पाया कि धारण में शुरुआत में तेज गिरावट होती है जो बाद में स्थिर हो जाती है। इसीलिए सीखने के तुरंत बाद नियमित पुनरावृत्ति सहायक होती है।"},
  {"id":"cdp-child-development-94","question":"A child who calls every four-legged animal ‘dog’ learns that cows are different and forms a new category for them. In Piaget’s terms, the child has shown:","options":["Conservation","Object permanence","Assimilation","Accommodation"],"answer":3,"explanation":"Accommodation is changing an existing schema or making a new one when new experience does not fit. Calling the cow ‘dog’ in the first place would have been assimilation.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"जो बच्चा हर चार पैर वाले जानवर को ‘कुत्ता’ कहता है, वह सीखता है कि गाय अलग होती हैं और उनके लिए एक नई श्रेणी बनाता है। पियाजे की शब्दावली में बच्चे ने क्या दर्शाया?","optionsHi":["संरक्षण","वस्तु स्थायित्व","आत्मसात्करण","समायोजन"],"explanationHi":"समायोजन का अर्थ है जब नया अनुभव मौजूदा ढाँचे में न बैठे तो किसी मौजूदा स्कीमा को बदलना या नई स्कीमा बनाना। शुरुआत में गाय को ‘कुत्ता’ कहना आत्मसात्करण था।"},
  {"id":"cdp-child-development-95","question":"Carol Gilligan criticised Kohlberg’s theory of moral development mainly because she felt it:","options":["Had too few stages to capture adult moral growth","Drew on male subjects and ignored an ethic of care","Ignored the role of rewards and punishment in morality","Was meant only for adults, not for children"],"answer":1,"explanation":"Gilligan argued that Kohlberg’s justice-based stages, drawn mostly from boys, undervalued moral reasoning based on care and relationships, which she found more often in women.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कैरोल गिलिगन ने कोहलबर्ग के नैतिक विकास के सिद्धांत की आलोचना मुख्यतः इसलिए की क्योंकि उनके अनुसार वह:","optionsHi":["वयस्कों की नैतिक वृद्धि को समेटने के लिए उसमें बहुत कम चरण थे","पुरुष प्रतिभागियों पर आधारित था और देखभाल की नैतिकता की उपेक्षा करता था","नैतिकता में पुरस्कार और दंड की भूमिका की उपेक्षा करता था","केवल वयस्कों के लिए था, बच्चों के लिए नहीं"],"explanationHi":"गिलिगन ने तर्क दिया कि कोहलबर्ग के न्याय-आधारित चरण, जो अधिकतर लड़कों से लिए गए थे, देखभाल और संबंधों पर आधारित नैतिक चिंतन को कम आँकते थे, जो उन्होंने महिलाओं में अधिक पाया।"},
  {"id":"cdp-child-development-96","question":"J. P. Guilford’s ‘Structure of Intellect’ model classifies intellectual abilities along which three dimensions?","options":["Operations, contents and products","Fluid, crystallised and general","Analytical, creative and practical","Verbal, numerical and spatial"],"answer":0,"explanation":"Guilford crossed operations (such as cognition and divergent production), contents and products to produce many distinct abilities. Analytical, creative and practical belong to Sternberg, and fluid–crystallised to Cattell.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"जे. पी. गिलफोर्ड का ‘बुद्धि की संरचना’ मॉडल बौद्धिक योग्यताओं को किन तीन आयामों में वर्गीकृत करता है?","optionsHi":["संक्रियाएँ, विषयवस्तु और उत्पाद","तरल, मूर्त और सामान्य","विश्लेषणात्मक, सृजनात्मक और व्यावहारिक","शाब्दिक, संख्यात्मक और स्थानिक"],"explanationHi":"गिलफोर्ड ने संक्रियाओं (जैसे संज्ञान और अपसारी उत्पादन), विषयवस्तु और उत्पादों को मिलाकर अनेक भिन्न योग्यताएँ बनाईं। विश्लेषणात्मक, सृजनात्मक और व्यावहारिक स्टर्नबर्ग के हैं, और तरल–मूर्त कैटल के।"},
  {"id":"cdp-child-development-97","question":"The idea of ‘emotional intelligence’ was popularised by whose 1995 book?","options":["Alfred Binet","Robert Sternberg","Howard Gardner","Daniel Goleman"],"answer":3,"explanation":"Daniel Goleman’s ‘Emotional Intelligence’ (1995) spread the concept, first proposed by Salovey and Mayer, of recognising and managing one’s own and others’ emotions.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"‘भावनात्मक बुद्धि’ का विचार किसकी 1995 की पुस्तक से लोकप्रिय हुआ?","optionsHi":["अल्फ्रेड बिने","रॉबर्ट स्टर्नबर्ग","हॉवर्ड गार्डनर","डैनियल गोलमैन"],"explanationHi":"डैनियल गोलमैन की ‘इमोशनल इंटेलिजेंस’ (1995) ने अपनी और दूसरों की भावनाओं को पहचानने और प्रबंधित करने की उस अवधारणा को फैलाया, जिसे पहले सेलोवे और मेयर ने प्रस्तावित किया था।"},
  {"id":"cdp-child-development-98","question":"A child who has learnt to ride a bicycle finds it easier to learn to ride a scooter. This is an example of:","options":["Retroactive inhibition","Zero transfer","Negative transfer","Positive transfer"],"answer":3,"explanation":"Positive transfer occurs when earlier learning helps new learning because the skills share elements such as balance. Negative transfer is when earlier learning gets in the way.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"जिस बच्चे ने साइकिल चलाना सीख लिया है, उसे स्कूटर चलाना सीखना आसान लगता है। यह किसका उदाहरण है?","optionsHi":["पश्चोन्मुख अवरोध","शून्य अंतरण","ऋणात्मक अंतरण","धनात्मक अंतरण"],"explanationHi":"धनात्मक अंतरण तब होता है जब पूर्व अधिगम नए अधिगम में सहायक होता है क्योंकि कौशलों में संतुलन जैसे तत्व समान होते हैं। ऋणात्मक अंतरण तब है जब पूर्व अधिगम बाधा बनता है।"},
  {"id":"cdp-child-development-99","question":"The NIPUN Bharat Mission, launched in July 2021, aims to ensure that every child achieves:","options":["Proficiency in spoken English by the end of Class 5","Basic digital and coding literacy by Class 8","Job-ready vocational skills by Class 10","Foundational literacy and numeracy by Class 3"],"answer":3,"explanation":"NIPUN Bharat (National Initiative for Proficiency in Reading with Understanding and Numeracy) targets foundational literacy and numeracy by the end of Grade 3, with 2026–27 as the target year.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"जुलाई 2021 में शुरू किए गए निपुण भारत मिशन का लक्ष्य यह सुनिश्चित करना है कि हर बच्चा प्राप्त करे:","optionsHi":["कक्षा 5 के अंत तक बोली जाने वाली अंग्रेजी में दक्षता","कक्षा 8 तक बुनियादी डिजिटल और कोडिंग साक्षरता","कक्षा 10 तक रोजगारोन्मुख व्यावसायिक कौशल","कक्षा 3 तक आधारभूत साक्षरता और संख्या-ज्ञान"],"explanationHi":"निपुण भारत (समझ के साथ पढ़ने और संख्या-ज्ञान में दक्षता के लिए राष्ट्रीय पहल) का लक्ष्य कक्षा 3 के अंत तक आधारभूत साक्षरता और संख्या-ज्ञान है, जिसका लक्ष्य वर्ष 2026–27 है।"},
  {"id":"cdp-child-development-100","question":"‘Action research’ was introduced into education to help teachers solve their own classroom problems by:","options":["B. F. Skinner and Sidney Pressey","Jean Piaget and Bärbel Inhelder","Kurt Lewin and Stephen M. Corey","Lev Vygotsky and Alexander Luria"],"answer":2,"explanation":"Kurt Lewin coined the term, and Stephen M. Corey popularised action research in education in the 1950s as a way for teachers to study and improve their own practice.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"शिक्षकों को अपनी कक्षा की समस्याएँ स्वयं हल करने में मदद के लिए शिक्षा में ‘क्रियात्मक अनुसंधान’ किसने प्रारंभ किया?","optionsHi":["बी. एफ. स्किनर और सिडनी प्रेसी","जीन पियाजे और बार्बेल इनहेल्डर","कर्ट लेविन और स्टीफन एम. कोरी","लेव वाइगोत्स्की और अलेक्जेंडर लूरिया"],"explanationHi":"कर्ट लेविन ने यह शब्द गढ़ा, और स्टीफन एम. कोरी ने 1950 के दशक में शिक्षा में क्रियात्मक अनुसंधान को शिक्षकों द्वारा अपने अभ्यास का अध्ययन और सुधार करने के तरीके के रूप में लोकप्रिय बनाया।"},
  {"id":"cdp-child-development-101","question":"Paulo Freire criticised the ‘banking concept’ of education, in which:","options":["The teacher deposits facts into passive students","Students save up marks to use in final examinations","Students are taught how to save and manage money","Schools are run like banks, chiefly to make a profit"],"answer":0,"explanation":"In ‘Pedagogy of the Oppressed’ Freire argued against treating learners as empty accounts to be filled, and called for dialogue and critical thinking instead.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"पाउलो फ्रेरे ने शिक्षा की ‘बैंकिंग अवधारणा’ की आलोचना की, जिसमें:","optionsHi":["शिक्षक निष्क्रिय विद्यार्थियों में तथ्य जमा करता है","विद्यार्थी अंतिम परीक्षाओं में उपयोग के लिए अंक बचाकर रखते हैं","विद्यार्थियों को पैसे बचाना और प्रबंधित करना सिखाया जाता है","विद्यालय बैंकों की तरह चलाए जाते हैं, मुख्यतः लाभ कमाने के लिए"],"explanationHi":"‘पेडागॉजी ऑफ द ऑप्रेस्ड’ में फ्रेरे ने अधिगमकर्ताओं को भरे जाने वाले खाली खातों की तरह मानने का विरोध किया और उसके स्थान पर संवाद और आलोचनात्मक चिंतन का आह्वान किया।"},
  {"id":"cdp-child-development-102","question":"A student who learnt French last year keeps mixing up French words while learning Spanish this year. This is an example of:","options":["Positive transfer","Proactive interference","Decay","Retroactive interference"],"answer":1,"explanation":"In proactive interference old learning disrupts the recall of new learning. If the new Spanish words made the student forget French, that would be retroactive interference.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"जिस विद्यार्थी ने पिछले वर्ष फ्रेंच सीखी थी, वह इस वर्ष स्पैनिश सीखते समय फ्रेंच शब्दों को मिलाता रहता है। यह किसका उदाहरण है?","optionsHi":["धनात्मक अंतरण","अग्रोन्मुख व्यतिकरण","क्षय","पश्चोन्मुख व्यतिकरण"],"explanationHi":"अग्रोन्मुख व्यतिकरण में पुराना अधिगम नए अधिगम के पुनःस्मरण में बाधा डालता है। यदि नए स्पैनिश शब्दों के कारण विद्यार्थी फ्रेंच भूल जाता, तो वह पश्चोन्मुख व्यतिकरण होता।"},
  {"id":"cdp-child-development-103","question":"How many of these statements about the principles of development are correct? I. Development is a continuous process. II. Development proceeds from the centre of the body outward. III. All children develop at the same rate. IV. Development results from the interaction of heredity and environment.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct; II is the proximodistal principle. III is wrong: development follows a similar sequence in all children, but its rate differs from child to child.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"विकास के सिद्धांतों के बारे में इनमें से कितने कथन सही हैं? I. विकास एक सतत प्रक्रिया है। II. विकास शरीर के केंद्र से बाहर की ओर होता है। III. सभी बच्चे एक ही दर से विकसित होते हैं। IV. विकास आनुवंशिकता और पर्यावरण की अंतःक्रिया का परिणाम है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं; II निकट-दूर सिद्धांत है। III गलत है: विकास सभी बच्चों में एक समान क्रम का अनुसरण करता है, पर उसकी दर हर बच्चे में अलग-अलग होती है।"},
  {"id":"cdp-child-development-104","question":"Match the learning difficulty with the area it mainly affects: 1. Dyslexia 2. Dysgraphia 3. Dyspraxia 4. Dysphasia; a. Language and speech b. Motor coordination c. Writing d. Reading","options":["1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b"],"answer":2,"explanation":"Dyslexia affects reading, dysgraphia writing, dyspraxia the planning and coordination of movement, and dysphasia the use and understanding of spoken language.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"अधिगम कठिनाई का मिलान उस क्षेत्र से कीजिए जिसे वह मुख्यतः प्रभावित करती है: 1. डिस्लेक्सिया 2. डिसग्राफिया 3. डिस्प्रैक्सिया 4. डिस्फेसिया; a. भाषा और वाणी b. गामक समन्वय c. लेखन d. पठन","optionsHi":["1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b"],"explanationHi":"डिस्लेक्सिया पठन को, डिसग्राफिया लेखन को, डिस्प्रैक्सिया गति की योजना और समन्वय को, और डिस्फेसिया बोली गई भाषा के उपयोग और समझ को प्रभावित करता है।"},
  {"id":"cdp-child-development-105","question":"Assertion (A): Teachers should avoid labelling children as ‘slow learners’ or ‘failures’. Reason (R): Labels can lower a child’s self-concept and teachers’ expectations, which can then become a self-fulfilling prophecy.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Studies of the Pygmalion effect show that children tend to perform as teachers expect, so a negative label can push achievement down. That is why R explains A.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"अभिकथन (A): शिक्षकों को बच्चों को ‘मंद अधिगमकर्ता’ या ‘असफल’ जैसे लेबल देने से बचना चाहिए। कारण (R): लेबल बच्चे की आत्म-अवधारणा और शिक्षकों की अपेक्षाओं को कम कर सकते हैं, जो फिर स्वयं-पूर्ति भविष्यवाणी बन सकती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"पिग्मैलियन प्रभाव के अध्ययन दिखाते हैं कि बच्चे प्रायः वैसा ही प्रदर्शन करते हैं जैसी शिक्षक अपेक्षा करते हैं, इसलिए नकारात्मक लेबल उपलब्धि को नीचे ला सकता है। इसीलिए R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-106","question":"A student argues: ‘Laws are agreements made by people for the common good; if a law violates basic rights, it should be changed through democratic means.’ In Kohlberg’s scheme this reasoning belongs to:","options":["Stage 5, social contract orientation","Stage 2, instrumental exchange","Stage 3, good boy–good girl orientation","Stage 4, law and order orientation"],"answer":0,"explanation":"Seeing laws as changeable social contracts that should protect rights is Stage 5 (post-conventional). Stage 4 treats laws as fixed rules to be obeyed to keep order.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"एक विद्यार्थी तर्क देता है: ‘कानून लोगों द्वारा सामान्य हित के लिए किए गए समझौते हैं; यदि कोई कानून मूल अधिकारों का उल्लंघन करता है, तो उसे लोकतांत्रिक तरीकों से बदला जाना चाहिए।’ कोहलबर्ग की योजना में यह तर्क किसका है?","optionsHi":["चरण 5, सामाजिक अनुबंध अभिविन्यास","चरण 2, साधनात्मक विनिमय","चरण 3, अच्छा लड़का–अच्छी लड़की अभिविन्यास","चरण 4, कानून और व्यवस्था अभिविन्यास"],"explanationHi":"कानूनों को बदले जा सकने वाले सामाजिक अनुबंध के रूप में देखना, जिन्हें अधिकारों की रक्षा करनी चाहिए, चरण 5 (उत्तर-परंपरागत) है। चरण 4 कानूनों को व्यवस्था बनाए रखने के लिए पालन किए जाने वाले निश्चित नियम मानता है।"},
  {"id":"cdp-child-development-107","question":"How many of these statements are correct? I. PARAKH was set up as a national assessment centre under the CBSE. II. The National Curriculum Framework for the Foundational Stage (2022) covers children aged 6 to 14. III. Vidya Pravesh is a three-month play-based school-preparation module for children entering Grade 6. IV. The National Curriculum Framework for School Education (2023) was drafted by a committee headed by Dr K. Kasturirangan.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only IV is correct. PARAKH was set up under the NCERT, the foundational stage covers ages 3 to 8, and Vidya Pravesh is the three-month play-based module for children entering Grade 1.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"इनमें से कितने कथन सही हैं? I. PARAKH की स्थापना CBSE के अंतर्गत राष्ट्रीय आकलन केंद्र के रूप में की गई थी। II. आधारभूत चरण के लिए राष्ट्रीय पाठ्यचर्या की रूपरेखा (2022) 6 से 14 वर्ष के बच्चों को समेटती है। III. विद्या प्रवेश कक्षा 6 में प्रवेश करने वाले बच्चों के लिए तीन माह का खेल-आधारित विद्यालय-तैयारी मॉड्यूल है। IV. विद्यालयी शिक्षा के लिए राष्ट्रीय पाठ्यचर्या की रूपरेखा (2023) का मसौदा डॉ. के. कस्तूरीरंगन की अध्यक्षता वाली समिति ने तैयार किया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल IV सही है। PARAKH की स्थापना NCERT के अंतर्गत हुई थी, आधारभूत चरण 3 से 8 वर्ष की आयु को समेटता है, और विद्या प्रवेश कक्षा 1 में प्रवेश करने वाले बच्चों के लिए तीन माह का खेल-आधारित मॉड्यूल है।"},
  {"id":"cdp-child-development-108","question":"Arrange in chronological order: 1. Bandura’s Bobo doll experiments 2. Gardner proposes multiple intelligences 3. Binet–Simon intelligence scale 4. Skinner publishes ‘The Behavior of Organisms’","options":["3, 4, 1, 2","3, 4, 2, 1","3, 1, 4, 2","4, 3, 1, 2"],"answer":0,"explanation":"The Binet–Simon scale came in 1905, Skinner’s book on operant conditioning in 1938, the Bobo doll studies in 1961 and Gardner’s ‘Frames of Mind’ in 1983.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. बंडूरा के बोबो डॉल प्रयोग 2. गार्डनर द्वारा बहुबुद्धि का प्रस्ताव 3. बिने–साइमन बुद्धि पैमाना 4. स्किनर द्वारा ‘द बिहेवियर ऑफ ऑर्गेनिज़्म्स’ का प्रकाशन","optionsHi":["3, 4, 1, 2","3, 4, 2, 1","3, 1, 4, 2","4, 3, 1, 2"],"explanationHi":"बिने–साइमन पैमाना 1905 में आया, क्रियाप्रसूत अनुबंधन पर स्किनर की पुस्तक 1938 में, बोबो डॉल अध्ययन 1961 में और गार्डनर की ‘फ्रेम्स ऑफ माइंड’ 1983 में।"},
  {"id":"cdp-child-development-109","question":"A student who fails a test says, ‘I was just unlucky today.’ According to Weiner’s attribution theory, the student has attributed the failure to a cause that is:","options":["External, stable and controllable","External, unstable and uncontrollable","Internal, stable and uncontrollable","Internal, unstable and controllable"],"answer":1,"explanation":"Luck lies outside the person, changes from day to day and cannot be controlled. Lack of effort would be internal, unstable and controllable, and low ability internal, stable and uncontrollable.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"परीक्षा में असफल होने पर एक विद्यार्थी कहता है, ‘आज मैं बस बदकिस्मत था।’ वाइनर के आरोपण सिद्धांत के अनुसार विद्यार्थी ने असफलता का कारण किस प्रकार के कारक को माना है?","optionsHi":["बाह्य, स्थिर और नियंत्रणीय","बाह्य, अस्थिर और अनियंत्रणीय","आंतरिक, स्थिर और अनियंत्रणीय","आंतरिक, अस्थिर और नियंत्रणीय"],"explanationHi":"भाग्य व्यक्ति के बाहर होता है, दिन-प्रतिदिन बदलता है और नियंत्रित नहीं किया जा सकता। प्रयास की कमी आंतरिक, अस्थिर और नियंत्रणीय होती, और कम योग्यता आंतरिक, स्थिर और अनियंत्रणीय।"},
  {"id":"cdp-child-development-110","question":"Match the defence mechanism with its example: 1. Rationalisation 2. Projection 3. Displacement 4. Regression; a. An older child starts sucking his thumb after a sibling is born b. A child scolded by the teacher kicks his little brother at home c. A dishonest pupil accuses classmates of cheating d. A boy who is not chosen for the team says he never wanted to play anyway","options":["1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a"],"answer":3,"explanation":"Rationalisation gives a convenient excuse (sour grapes), projection puts one’s own faults on others, displacement vents feelings on a safer target, and regression is a return to earlier, childish behaviour.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"रक्षा-युक्ति का मिलान उसके उदाहरण से कीजिए: 1. युक्तियुक्तकरण 2. प्रक्षेपण 3. विस्थापन 4. प्रत्यावर्तन; a. भाई-बहन के जन्म के बाद एक बड़ा बच्चा अँगूठा चूसने लगता है b. शिक्षक से डाँट खाया बच्चा घर पर अपने छोटे भाई को लात मारता है c. एक बेईमान विद्यार्थी सहपाठियों पर नकल का आरोप लगाता है d. टीम में न चुना गया लड़का कहता है कि वह तो खेलना ही नहीं चाहता था","optionsHi":["1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a"],"explanationHi":"युक्तियुक्तकरण एक सुविधाजनक बहाना देता है (खट्टे अंगूर), प्रक्षेपण अपनी कमियाँ दूसरों पर डालता है, विस्थापन भावनाओं को किसी सुरक्षित लक्ष्य पर निकालता है, और प्रत्यावर्तन पहले के, बचकाने व्यवहार की ओर लौटना है।"},
  {"id":"cdp-child-development-111","question":"Which of the following is NOT usually a characteristic of a creative child?","options":["Preference for a single, fixed correct answer","Curiosity and a habit of asking unusual questions","Tolerance for ambiguity and open-ended tasks","Divergent thinking with many original ideas"],"answer":0,"explanation":"Creative children produce many original ideas and are comfortable with open-ended problems. Looking for one fixed answer is convergent thinking, which tests of creativity do not reward.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"निम्नलिखित में से कौन-सी सृजनशील बच्चे की सामान्यतः विशेषता नहीं है?","optionsHi":["एकमात्र, निश्चित सही उत्तर को प्राथमिकता","जिज्ञासा और असामान्य प्रश्न पूछने की आदत","अस्पष्टता और खुले कार्यों के प्रति सहनशीलता","अनेक मौलिक विचारों के साथ अपसारी चिंतन"],"explanationHi":"सृजनशील बच्चे अनेक मौलिक विचार देते हैं और खुली समस्याओं में सहज रहते हैं। एक निश्चित उत्तर खोजना अभिसारी चिंतन है, जिसे सृजनशीलता के परीक्षण महत्व नहीं देते।"},
  {"id":"cdp-child-development-112","question":"Assertion (A): Gifted children do not need any special educational provision because they can learn on their own. Reason (R): Gifted children have exceptional abilities that need enrichment or acceleration to develop fully.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"A is false and R is true. Without challenge, gifted children may become bored, underachieve or develop behaviour problems, so they need enrichment, acceleration or ability-appropriate tasks.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"अभिकथन (A): प्रतिभाशाली बच्चों को किसी विशेष शैक्षिक प्रावधान की आवश्यकता नहीं होती क्योंकि वे स्वयं सीख सकते हैं। कारण (R): प्रतिभाशाली बच्चों में असाधारण योग्यताएँ होती हैं जिन्हें पूर्ण विकास के लिए संवर्धन या त्वरण की आवश्यकता होती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"A असत्य है और R सत्य है। चुनौती के बिना प्रतिभाशाली बच्चे ऊब सकते हैं, अपेक्षा से कम उपलब्धि कर सकते हैं या व्यवहार संबंधी समस्याएँ विकसित कर सकते हैं, इसलिए उन्हें संवर्धन, त्वरण या योग्यता के अनुरूप कार्यों की आवश्यकता होती है।"},
  {"id":"cdp-child-development-113","question":"How many of these statements about intelligence tests are correct? I. The Stanford–Binet test is an individual test. II. The WISC was developed by David Wechsler. III. Raven’s Progressive Matrices is a verbal test. IV. Bhatia’s Battery is a verbal test of intelligence.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I and II are correct. Raven’s Progressive Matrices is a non-verbal, culture-reducing test of abstract reasoning, and C. M. Bhatia’s Battery is a set of performance tests designed for Indian children.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"बुद्धि परीक्षणों के बारे में इनमें से कितने कथन सही हैं? I. स्टैनफोर्ड–बिने परीक्षण एक वैयक्तिक परीक्षण है। II. WISC को डेविड वेक्स्लर ने विकसित किया। III. रेवेन की प्रोग्रेसिव मैट्रिसेस एक शाब्दिक परीक्षण है। IV. भाटिया बैटरी बुद्धि का एक शाब्दिक परीक्षण है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I और II सही हैं। रेवेन की प्रोग्रेसिव मैट्रिसेस अमूर्त तर्क का अशाब्दिक, संस्कृति-निरपेक्षता की ओर उन्मुख परीक्षण है, और सी. एम. भाटिया की बैटरी भारतीय बच्चों के लिए बनाए गए निष्पादन परीक्षणों का समूह है।"},
  {"id":"cdp-child-development-114","question":"Arrange Bronfenbrenner’s environmental systems from the innermost to the outermost around the child: 1. Exosystem 2. Microsystem 3. Macrosystem 4. Mesosystem","options":["2, 1, 4, 3","2, 4, 3, 1","2, 4, 1, 3","4, 2, 1, 3"],"answer":2,"explanation":"The microsystem (family, school) is closest; the mesosystem links microsystems (home–school); the exosystem affects the child indirectly (a parent’s workplace); the macrosystem is the wider culture. The chronosystem adds change over time.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"ब्रोनफेनब्रेनर की पर्यावरणीय प्रणालियों को बच्चे के सबसे भीतरी से सबसे बाहरी क्रम में व्यवस्थित कीजिए: 1. बाह्यतंत्र (Exosystem) 2. सूक्ष्मतंत्र (Microsystem) 3. वृहत्तंत्र (Macrosystem) 4. मध्यतंत्र (Mesosystem)","optionsHi":["2, 1, 4, 3","2, 4, 3, 1","2, 4, 1, 3","4, 2, 1, 3"],"explanationHi":"सूक्ष्मतंत्र (परिवार, विद्यालय) सबसे निकट है; मध्यतंत्र सूक्ष्मतंत्रों को जोड़ता है (घर–विद्यालय); बाह्यतंत्र बच्चे को परोक्ष रूप से प्रभावित करता है (माता-पिता का कार्यस्थल); वृहत्तंत्र व्यापक संस्कृति है। कालतंत्र समय के साथ परिवर्तन जोड़ता है।"},
  {"id":"cdp-child-development-115","question":"Which of the following is NOT usually counted as a domain of child development?","options":["Physical","Cognitive","Socio-emotional","Financial"],"answer":3,"explanation":"Child development is usually studied in physical, cognitive (including language) and socio-emotional domains, which interact with one another.","difficulty":"easy","source":"CTET · State TETs","questionHi":"निम्नलिखित में से किसे सामान्यतः बाल विकास का एक क्षेत्र नहीं गिना जाता?","optionsHi":["शारीरिक","संज्ञानात्मक","सामाजिक-संवेगात्मक","वित्तीय"],"explanationHi":"बाल विकास का अध्ययन सामान्यतः शारीरिक, संज्ञानात्मक (भाषा सहित) और सामाजिक-संवेगात्मक क्षेत्रों में किया जाता है, जो एक-दूसरे के साथ अंतःक्रिया करते हैं।"},
  {"id":"cdp-child-development-116","question":"The “Heinz dilemma”, about a man who steals a drug to save his dying wife, was used to study moral reasoning by:","options":["Jean Piaget","Lawrence Kohlberg","Erik H. Erikson","Abraham H. Maslow"],"answer":1,"explanation":"Kohlberg classified children's reasons for their answers, not the answers themselves, into six stages of moral reasoning.","difficulty":"easy","source":"CTET · State TETs","questionHi":"“हाइंज की दुविधा”, जो एक व्यक्ति के अपनी मरणासन्न पत्नी को बचाने के लिए दवा चुराने के बारे में है, का उपयोग नैतिक चिंतन के अध्ययन के लिए किसने किया?","optionsHi":["जीन पियाजे","लॉरेंस कोहलबर्ग","एरिक एच. एरिक्सन","अब्राहम एच. मैस्लो"],"explanationHi":"कोहलबर्ग ने बच्चों के उत्तरों को नहीं, बल्कि उन उत्तरों के पीछे के कारणों को नैतिक चिंतन के छह चरणों में वर्गीकृत किया।"},
  {"id":"cdp-child-development-117","question":"A baby first controls the movements of the shoulders and arms, and only later the fingers. This illustrates the:","options":["Cephalocaudal principle","Principle of individual differences","Proximodistal principle","Principle of interaction"],"answer":2,"explanation":"Proximodistal development proceeds from the centre of the body outwards. Cephalocaudal development proceeds from head to foot.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"शिशु पहले कंधों और बाँहों की गतियों पर नियंत्रण करता है, और उँगलियों पर बाद में। यह किसका उदाहरण है?","optionsHi":["शीर्षगामी सिद्धांत","वैयक्तिक भिन्नता का सिद्धांत","निकट-दूर सिद्धांत","अंतःक्रिया का सिद्धांत"],"explanationHi":"निकट-दूर विकास शरीर के केंद्र से बाहर की ओर होता है। शीर्षगामी विकास सिर से पैर की ओर होता है।"},
  {"id":"cdp-child-development-118","question":"In Erikson's theory, the stage of “initiative vs guilt” corresponds roughly to the age of:","options":["Birth to 1 year","3 to 6 years","6 to 12 years","12 to 18 years"],"answer":1,"explanation":"Pre-school children who are encouraged to plan and try things develop initiative; harsh criticism breeds guilt. Industry vs inferiority follows in the school years.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"एरिक्सन के सिद्धांत में “पहल बनाम अपराधबोध” अवस्था लगभग किस आयु की है?","optionsHi":["जन्म से 1 वर्ष","3 से 6 वर्ष","6 से 12 वर्ष","12 से 18 वर्ष"],"explanationHi":"जिन प्री-स्कूल बच्चों को योजना बनाने और चीजें आज़माने के लिए प्रोत्साहित किया जाता है, उनमें पहल विकसित होती है; कठोर आलोचना से अपराधबोध पनपता है। उद्यमिता बनाम हीनता विद्यालयी वर्षों में आती है।"},
  {"id":"cdp-child-development-119","question":"A collection of a child's work gathered over a term to show progress and reflection is called a:","options":["Portfolio","Rubric","Anecdotal record","Achievement test"],"answer":0,"explanation":"A portfolio shows growth over time and often includes the child's own reflections. A rubric is a scoring guide; an anecdotal record notes a single observed incident.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"प्रगति और चिंतन दिखाने के लिए एक सत्र के दौरान इकट्ठा किया गया बच्चे के कार्य का संग्रह कहलाता है:","optionsHi":["पोर्टफोलियो","रूब्रिक","आख्यानात्मक अभिलेख","उपलब्धि परीक्षण"],"explanationHi":"पोर्टफोलियो समय के साथ वृद्धि दिखाता है और प्रायः उसमें बच्चे का अपना चिंतन शामिल होता है। रूब्रिक अंकन का मार्गदर्शक है; आख्यानात्मक अभिलेख किसी एक देखी गई घटना को दर्ज करता है।"},
  {"id":"cdp-child-development-120","question":"A five-year-old says a tall, thin glass holds more juice than a short, wide one with the same amount, looking only at the height. According to Piaget, this shows:","options":["Animism","Centration","Object permanence","Hypothetical reasoning"],"answer":1,"explanation":"Centration is focusing on one striking feature and ignoring others, typical of the pre-operational stage; it is why such children fail conservation tasks.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"एक पाँच वर्ष का बच्चा कहता है कि समान मात्रा के रस के लिए लंबा, पतला गिलास छोटे, चौड़े गिलास से अधिक रस रखता है, क्योंकि वह केवल ऊँचाई देखता है। पियाजे के अनुसार यह दर्शाता है:","optionsHi":["सजीववाद","केंद्रीकरण","वस्तु स्थायित्व","परिकल्पनात्मक तर्क"],"explanationHi":"केंद्रीकरण का अर्थ है एक आकर्षक विशेषता पर ध्यान देना और अन्य की उपेक्षा करना, जो पूर्व-संक्रियात्मक अवस्था की विशेषता है; इसी कारण ऐसे बच्चे संरक्षण के कार्यों में विफल होते हैं।"},
  {"id":"cdp-child-development-121","question":"The ability to arrange sticks in order of length (seriation) generally develops in which Piagetian stage?","options":["Sensorimotor","Pre-operational","Formal operational","Concrete operational"],"answer":3,"explanation":"Seriation, along with conservation, reversibility and class inclusion, is mastered in the concrete operational stage (about 7 to 11 years).","difficulty":"hard","source":"CTET · State TETs","questionHi":"डंडों को लंबाई के क्रम में सजाने की क्षमता (क्रमबद्धता) सामान्यतः पियाजे की किस अवस्था में विकसित होती है?","optionsHi":["संवेदी-गामक","पूर्व-संक्रियात्मक","औपचारिक संक्रियात्मक","मूर्त संक्रियात्मक"],"explanationHi":"क्रमबद्धता, संरक्षण, उत्क्रमणीयता और वर्ग-समावेशन के साथ, मूर्त संक्रियात्मक अवस्था (लगभग 7 से 11 वर्ष) में महारत में आती है।"},
  {"id":"cdp-child-development-122","question":"Raymond Cattell divided general intelligence into:","options":["Fluid and crystallised intelligence","Verbal and performance intelligence","Analytical, creative and practical intelligence","Primary mental abilities"],"answer":0,"explanation":"Fluid intelligence is the ability to reason with new problems; crystallised intelligence is accumulated knowledge. Sternberg proposed the triarchic model and Thurstone the primary mental abilities.","difficulty":"hard","source":"CTET · State TETs","questionHi":"रेमंड कैटल ने सामान्य बुद्धि को किसमें विभाजित किया?","optionsHi":["तरल और मूर्त बुद्धि","शाब्दिक और निष्पादन बुद्धि","विश्लेषणात्मक, सृजनात्मक और व्यावहारिक बुद्धि","प्राथमिक मानसिक योग्यताएँ"],"explanationHi":"तरल बुद्धि नई समस्याओं के साथ तर्क करने की क्षमता है; मूर्त बुद्धि संचित ज्ञान है। स्टर्नबर्ग ने त्रितंत्र मॉडल और थर्स्टन ने प्राथमिक मानसिक योग्यताएँ प्रस्तावित कीं।"},
  {"id":"cdp-child-development-123","question":"Robert Sternberg's triarchic theory describes intelligence as having which three aspects?","options":["Verbal, numerical and spatial reasoning","Fluid, crystallised and emotional","Analytical, creative and practical","Linguistic, logical and musical"],"answer":2,"explanation":"Sternberg's theory includes componential (analytical), experiential (creative) and contextual (practical) intelligence.","difficulty":"hard","source":"CTET · State TETs","questionHi":"रॉबर्ट स्टर्नबर्ग का त्रितंत्र सिद्धांत बुद्धि के किन तीन पहलुओं का वर्णन करता है?","optionsHi":["शाब्दिक, संख्यात्मक और स्थानिक तर्क","तरल, मूर्त और भावनात्मक","विश्लेषणात्मक, सृजनात्मक और व्यावहारिक","भाषायी, तार्किक और संगीतात्मक"],"explanationHi":"स्टर्नबर्ग के सिद्धांत में घटकीय (विश्लेषणात्मक), अनुभवात्मक (सृजनात्मक) और संदर्भगत (व्यावहारिक) बुद्धि शामिल हैं।"},
  {"id":"cdp-child-development-124","question":"Rats that explored a maze without reward and then quickly found the food once it was introduced showed that they had learnt the layout. Who described this “latent learning”?","options":["Edward Tolman","Ivan Pavlov","B. F. Skinner","Edward Thorndike"],"answer":0,"explanation":"Tolman argued the rats had formed a “cognitive map” that was not shown until there was a reason to use it, challenging strict behaviourism.","difficulty":"hard","source":"CTET · State TETs","questionHi":"जिन चूहों ने बिना पुरस्कार के भूलभुलैया का अन्वेषण किया और भोजन रखे जाने पर उसे जल्दी खोज लिया, उन्होंने दिखाया कि उन्होंने उसकी बनावट सीख ली थी। इस “अव्यक्त अधिगम” का वर्णन किसने किया?","optionsHi":["एडवर्ड टॉलमैन","इवान पावलोव","बी. एफ. स्किनर","एडवर्ड थॉर्नडाइक"],"explanationHi":"टॉलमैन ने तर्क दिया कि चूहों ने एक “संज्ञानात्मक मानचित्र” बना लिया था जो तब तक प्रकट नहीं हुआ जब तक उसके उपयोग का कारण नहीं मिला, जिसने कठोर व्यवहारवाद को चुनौती दी।"},
  {"id":"cdp-child-development-125","question":"George Miller's classic finding about short-term memory is that it can hold about:","options":["Two or three items","Seven, plus or minus two, items","Twenty items","An unlimited number of items for a few seconds"],"answer":1,"explanation":"Miller (1956) put the span at about 7 ± 2 chunks; grouping information into chunks helps learners hold more.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अल्पकालिक स्मृति के बारे में जॉर्ज मिलर की क्लासिक खोज यह है कि वह लगभग कितनी मदें रख सकती है?","optionsHi":["दो या तीन मदें","सात, धन-ऋण दो, मदें","बीस मदें","कुछ सेकंड के लिए असीमित मदें"],"explanationHi":"मिलर (1956) ने इसकी सीमा लगभग 7 ± 2 खंड (chunk) बताई; सूचना को खंडों में समूहित करने से अधिगमकर्ता अधिक याद रख पाते हैं।"},
  {"id":"cdp-child-development-126","question":"To build a “growth mindset” as described by Carol Dweck, a teacher should mainly praise children for:","options":["Being naturally clever and gifted","Getting answers right on the first try","Effort, strategies and persistence","Finishing work before everyone else"],"answer":2,"explanation":"Praising effort and strategy teaches that ability can grow; praising only “cleverness” can make children avoid challenges for fear of failing.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कैरोल ड्वेक द्वारा वर्णित “विकासशील मानसिकता” बनाने के लिए शिक्षक को मुख्यतः बच्चों की किस बात की प्रशंसा करनी चाहिए?","optionsHi":["स्वाभाविक रूप से होशियार और प्रतिभाशाली होने की","पहली बार में उत्तर सही करने की","प्रयास, युक्तियों और दृढ़ता की","सबसे पहले काम पूरा करने की"],"explanationHi":"प्रयास और युक्ति की प्रशंसा यह सिखाती है कि योग्यता बढ़ सकती है; केवल “होशियारी” की प्रशंसा बच्चों को असफलता के डर से चुनौतियों से बचने वाला बना सकती है।"},
  {"id":"cdp-child-development-127","question":"After the RTE (Amendment) Act, 2019, which is true of examinations in Classes 5 and 8?","options":["Detention is completely prohibited in every class until elementary education ends","Board examinations become compulsory for every student at the end of Class 5","Failing students get a re-exam in two months; States may then allow detention","Only private unaided schools may hold back students who fail these exams"],"answer":2,"explanation":"The amendment to Section 16 lets the appropriate government hold regular exams in Classes 5 and 8, with a re-exam within two months, before a child can be held back.","difficulty":"hard","source":"CTET · State TETs","questionHi":"RTE (संशोधन) अधिनियम, 2019 के बाद, कक्षा 5 और 8 की परीक्षाओं के बारे में क्या सत्य है?","optionsHi":["प्रारंभिक शिक्षा समाप्त होने तक हर कक्षा में रोके रखना पूरी तरह प्रतिबंधित है","कक्षा 5 के अंत में हर विद्यार्थी के लिए बोर्ड परीक्षाएँ अनिवार्य हो जाती हैं","असफल विद्यार्थियों को दो माह में पुनः परीक्षा मिलती है; राज्य तब रोके रखने की अनुमति दे सकते हैं","केवल निजी गैर-सहायता प्राप्त विद्यालय ही इन परीक्षाओं में असफल विद्यार्थियों को रोक सकते हैं"],"explanationHi":"धारा 16 में संशोधन उपयुक्त सरकार को कक्षा 5 और 8 में नियमित परीक्षाएँ लेने की अनुमति देता है, जिसमें दो माह के भीतर पुनः परीक्षा होती है, उसके बाद ही बच्चे को रोका जा सकता है।"},
  {"id":"cdp-child-development-128","question":"Consider the following statements about Bloom's revised taxonomy (2001): 1. It names the levels with verbs, such as remembering and understanding, instead of nouns. 2. It places creating above evaluating at the top. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. Anderson and Krathwohl's revision renamed the levels and replaced “synthesis” with “creating” as the highest level.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"ब्लूम के संशोधित वर्गीकरण (2001) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह स्तरों को संज्ञाओं की जगह क्रियाओं से नाम देता है, जैसे स्मरण और बोध। 2. यह सृजन को मूल्यांकन के ऊपर शीर्ष पर रखता है। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। एंडरसन और क्रैथवोल के संशोधन ने स्तरों के नाम बदले और “संश्लेषण” की जगह “सृजन” को सर्वोच्च स्तर बनाया।"},
  {"id":"cdp-child-development-129","question":"Arrange the levels of the affective domain (Krathwohl) from the lowest to the highest: 1. Valuing 2. Receiving 3. Characterisation 4. Responding 5. Organisation","options":["2, 4, 1, 3, 5","2, 1, 4, 5, 3","4, 2, 1, 5, 3","2, 4, 1, 5, 3"],"answer":3,"explanation":"The order is receiving, responding, valuing, organisation and characterisation by a value, as values become part of the learner's character.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"भावात्मक क्षेत्र (क्रैथवोल) के स्तरों को निम्नतम से उच्चतम क्रम में व्यवस्थित कीजिए: 1. मूल्य-स्वीकरण (Valuing) 2. ग्रहण करना (Receiving) 3. चरित्रीकरण (Characterisation) 4. अनुक्रिया (Responding) 5. संगठन (Organisation)","optionsHi":["2, 4, 1, 3, 5","2, 1, 4, 5, 3","4, 2, 1, 5, 3","2, 4, 1, 5, 3"],"explanationHi":"क्रम है: ग्रहण करना, अनुक्रिया, मूल्य-स्वीकरण, संगठन और मूल्य द्वारा चरित्रीकरण, क्योंकि मूल्य अधिगमकर्ता के चरित्र का हिस्सा बन जाते हैं।"},
  {"id":"cdp-child-development-130","question":"Match the section of the RTE Act, 2009 with its subject: A. Section 13 B. Section 17 C. Section 21 D. Section 29 — 1. School Management Committee 2. Ban on capitation fee and screening for admission 3. Curriculum and evaluation procedure 4. Ban on physical punishment and mental harassment","options":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3"],"answer":0,"explanation":"Section 13 bars capitation fees and screening, 17 bans corporal punishment, 21 requires School Management Committees, and 29 lays down curriculum principles, including continuous and comprehensive evaluation.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"RTE अधिनियम, 2009 की धारा का उसके विषय से मिलान कीजिए: A. धारा 13 B. धारा 17 C. धारा 21 D. धारा 29 — 1. विद्यालय प्रबंधन समिति 2. प्रवेश के लिए कैपिटेशन शुल्क और स्क्रीनिंग पर रोक 3. पाठ्यचर्या और मूल्यांकन प्रक्रिया 4. शारीरिक दंड और मानसिक उत्पीड़न पर रोक","optionsHi":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3"],"explanationHi":"धारा 13 कैपिटेशन शुल्क और स्क्रीनिंग पर रोक लगाती है, 17 शारीरिक दंड पर प्रतिबंध लगाती है, 21 विद्यालय प्रबंधन समितियों को अनिवार्य करती है, और 29 पाठ्यचर्या के सिद्धांत निर्धारित करती है, जिनमें सतत एवं व्यापक मूल्यांकन शामिल है।"},
  {"id":"cdp-child-development-131","question":"Assertion (A): Samagra Shiksha treats school education as a continuum from pre-school to Class XII. Reason (R): Launched in 2018, it subsumed the Sarva Shiksha Abhiyan, the Rashtriya Madhyamik Shiksha Abhiyan and the Teacher Education scheme.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: merging the elementary, secondary and teacher-education schemes created one integrated programme for all stages of school.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): समग्र शिक्षा विद्यालयी शिक्षा को प्री-स्कूल से कक्षा XII तक एक सतत शृंखला के रूप में देखती है। कारण (R): 2018 में शुरू की गई इस योजना ने सर्व शिक्षा अभियान, राष्ट्रीय माध्यमिक शिक्षा अभियान और शिक्षक शिक्षा योजना को अपने में समाहित कर लिया।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है: प्रारंभिक, माध्यमिक और शिक्षक शिक्षा की योजनाओं के विलय से विद्यालय के सभी चरणों के लिए एक एकीकृत कार्यक्रम बना।"},
  {"id":"cdp-child-development-132","question":"How many of these abilities are typically achieved in Piaget's concrete operational stage? I. Reversibility II. Conservation III. Seriation IV. Class inclusion","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four belong to the concrete operational stage: reversibility, conservation, seriation (ordering by size) and class inclusion all appear at about 7 to 11 years.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"पियाजे की मूर्त संक्रियात्मक अवस्था में सामान्यतः इनमें से कितनी क्षमताएँ प्राप्त होती हैं? I. उत्क्रमणीयता II. संरक्षण III. क्रमबद्धता IV. वर्ग-समावेशन","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों मूर्त संक्रियात्मक अवस्था की हैं: उत्क्रमणीयता, संरक्षण, क्रमबद्धता (आकार के अनुसार क्रम में रखना) और वर्ग-समावेशन, ये सब लगभग 7 से 11 वर्ष की आयु में प्रकट होते हैं।"},
  {"id":"cdp-child-development-133","question":"Consider the following statements about Vygotsky's ideas: 1. The “more knowledgeable other” can be a peer, not only an adult. 2. Scaffolding should be gradually withdrawn as the child becomes competent. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. This is why peer tutoring and group work are useful, and why support is faded so the learner can work independently.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"वाइगोत्स्की के विचारों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. “अधिक जानकार अन्य” केवल वयस्क नहीं, कोई सहपाठी भी हो सकता है। 2. जैसे-जैसे बच्चा सक्षम होता जाता है, पाड़ (scaffolding) को धीरे-धीरे हटाया जाना चाहिए। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। इसीलिए सहपाठी शिक्षण और समूह कार्य उपयोगी हैं, और इसीलिए सहायता धीरे-धीरे कम की जाती है ताकि अधिगमकर्ता स्वतंत्र रूप से कार्य कर सके।"},
  {"id":"cdp-child-development-134","question":"Assertion (A): Shown seven roses and three lilies and asked, “Are there more roses or more flowers?”, a pre-operational child often says “more roses”. Reason (R): Pre-operational children have not yet mastered class inclusion.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: the child compares the two sub-classes instead of the sub-class with the whole class, an ability that comes in the concrete operational stage.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): सात गुलाब और तीन कुमुदिनी दिखाकर पूछा जाए, “गुलाब अधिक हैं या फूल अधिक हैं?”, तो पूर्व-संक्रियात्मक बच्चा प्रायः कहता है “गुलाब अधिक”। कारण (R): पूर्व-संक्रियात्मक बच्चों ने अभी वर्ग-समावेशन में महारत हासिल नहीं की होती।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है: बच्चा उप-वर्ग की तुलना पूरे वर्ग से करने की बजाय दो उप-वर्गों की आपस में तुलना करता है; यह क्षमता मूर्त संक्रियात्मक अवस्था में आती है।"},
  {"id":"cdp-child-development-135","question":"A six-year-old agrees that two rows of seven coins are equal when they are lined up. When one row is spread out, she says it has more. When the teacher pushes it back, she says they are equal again, but on spreading it once more she repeats her claim. Which feature of pre-operational thought most directly stops her from mentally ‘undoing’ the change?","options":["Animism","Irreversibility","Lack of object permanence","Transductive reasoning"],"answer":1,"explanation":"She cannot run the transformation backwards in her head, so each new layout is judged afresh; this is irreversibility. Centration on length adds to the error, but the inability to undo the change is the core limitation asked about.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक छह वर्ष की बच्ची मानती है कि सात-सात सिक्कों की दो पंक्तियाँ तब बराबर हैं जब वे एक सीध में रखी हों। जब एक पंक्ति को फैला दिया जाता है, तो वह कहती है कि उसमें अधिक सिक्के हैं। जब शिक्षक उसे वापस समेट देता है, तो वह फिर कहती है कि वे बराबर हैं, पर उसे दोबारा फैलाने पर वह अपना दावा दोहराती है। पूर्व-संक्रियात्मक चिंतन की कौन-सी विशेषता उसे परिवर्तन को मन में ‘पलटने’ से सबसे सीधे रोकती है?","optionsHi":["सजीववाद","अनुत्क्रमणीयता","वस्तु स्थायित्व का अभाव","अनुप्रेरक (ट्रांसडक्टिव) तर्क"],"explanationHi":"वह परिवर्तन को मन में उलटे क्रम में नहीं चला पाती, इसलिए हर नए विन्यास का निर्णय नए सिरे से करती है; यही अनुत्क्रमणीयता है। लंबाई पर केंद्रीकरण त्रुटि को बढ़ाता है, पर परिवर्तन को पलट न पाना ही यहाँ पूछी गई मूल सीमा है।"},
  {"id":"cdp-child-development-136","question":"A teacher helps a Class 2 child assemble a 30-piece jigsaw. Which of her actions goes AGAINST the principle of scaffolding?","options":["Showing how to start with the edge pieces and then letting the child continue","Asking, ‘Which pieces have a straight side?’ to focus the child’s attention","Keeping up full hints for every piece after she starts fitting them alone","Grouping the pieces by colour so that the task is broken into smaller parts"],"answer":2,"explanation":"Scaffolding is temporary and contingent: support should fade as competence grows. Continuing full hints after the child shows independence removes the challenge that drives development.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षिका कक्षा 2 के एक बच्चे को 30 टुकड़ों की जिगसॉ पहेली जोड़ने में मदद करती है। उसका कौन-सा कार्य पाड़ (scaffolding) के सिद्धांत के विरुद्ध है?","optionsHi":["किनारे के टुकड़ों से शुरू करना दिखाना और फिर बच्चे को आगे जारी रखने देना","बच्चे का ध्यान केंद्रित करने के लिए पूछना, ‘किन टुकड़ों की एक किनारी सीधी है?’","जब बच्चा अकेले टुकड़े जोड़ने लगे, तब भी हर टुकड़े के लिए पूरे संकेत देते रहना","पहेली के टुकड़ों को रंग के अनुसार समूहित करना ताकि कार्य छोटे भागों में बँट जाए"],"explanationHi":"पाड़ अस्थायी और परिस्थिति-आधारित होता है: योग्यता बढ़ने पर सहायता घटनी चाहिए। बच्चे के स्वतंत्र होने के बाद भी पूरे संकेत देते रहना उस चुनौती को हटा देता है जो विकास को आगे बढ़ाती है।"},
  {"id":"cdp-child-development-137","question":"Two eight-year-olds both solve tasks up to an eight-year level on their own. With hints and leading questions, Arjun solves tasks up to a twelve-year level, while Bunty reaches only a nine-year level. From Vygotsky’s viewpoint, the most valid conclusion is:","options":["Their independent level is equal, but Arjun has a wider zone of proximal development","Both children are at the same level of development, so they should be taught in exactly the same way","Arjun is more intelligent, because his independent score is higher than Bunty’s","Bunty has reached the upper limit of his development and cannot learn further"],"answer":0,"explanation":"Vygotsky argued that what a child can do with help reveals maturing functions; equal independent scores can hide very different ZPDs, which matter for instruction. Their independent scores are equal, so the third option is factually wrong.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"दो आठ वर्ष के बच्चे दोनों अकेले आठ वर्ष के स्तर तक के कार्य हल कर लेते हैं। संकेतों और मार्गदर्शक प्रश्नों की मदद से अर्जुन बारह वर्ष के स्तर तक के कार्य हल कर लेता है, जबकि बंटी केवल नौ वर्ष के स्तर तक पहुँचता है। वाइगोत्स्की के दृष्टिकोण से सबसे उचित निष्कर्ष क्या है?","optionsHi":["उनका स्वतंत्र स्तर समान है, पर अर्जुन का निकटस्थ विकास का क्षेत्र अधिक व्यापक है","दोनों बच्चे विकास के समान स्तर पर हैं, इसलिए उन्हें बिल्कुल एक ही तरीके से पढ़ाया जाना चाहिए","अर्जुन अधिक बुद्धिमान है, क्योंकि उसका स्वतंत्र प्राप्तांक बंटी से अधिक है","बंटी अपने विकास की ऊपरी सीमा तक पहुँच चुका है और आगे नहीं सीख सकता"],"explanationHi":"वाइगोत्स्की का तर्क था कि बच्चा सहायता से जो कर सकता है वह परिपक्व हो रहे प्रकार्यों को दर्शाता है; समान स्वतंत्र प्राप्तांक बहुत भिन्न ZPD को छिपा सकते हैं, जो शिक्षण के लिए महत्वपूर्ण हैं। उनके स्वतंत्र प्राप्तांक समान हैं, इसलिए तीसरा विकल्प तथ्यात्मक रूप से गलत है।"},
  {"id":"cdp-child-development-138","question":"Asked why he shares his tiffin with Kabir, a nine-year-old says, ‘Kabir gave me half his sandwich yesterday, and if I share today he’ll share tomorrow too.’ This reasoning best fits Kohlberg’s:","options":["Stage 3: good boy–good girl orientation","Stage 1: punishment and obedience orientation","Stage 4: law and order orientation","Stage 2: instrumental exchange orientation"],"answer":3,"explanation":"The act is justified by a fair deal that serves his own interest, the hallmark of Stage 2. Stage 3 would appeal to being seen as a good, caring friend.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"यह पूछने पर कि वह अपना टिफिन कबीर के साथ क्यों बाँटता है, नौ वर्ष का एक बच्चा कहता है, ‘कबीर ने कल मुझे अपना आधा सैंडविच दिया था, और अगर आज मैं बाँटूँगा तो वह कल भी बाँटेगा।’ यह तर्क कोहलबर्ग के किससे सबसे अच्छी तरह मेल खाता है?","optionsHi":["चरण 3: अच्छा लड़का–अच्छी लड़की अभिविन्यास","चरण 1: दंड और आज्ञापालन अभिविन्यास","चरण 4: कानून और व्यवस्था अभिविन्यास","चरण 2: साधनात्मक विनिमय अभिविन्यास"],"explanationHi":"कार्य को एक उचित सौदे से उचित ठहराया गया है जो उसके अपने हित की पूर्ति करता है, जो चरण 2 की पहचान है। चरण 3 में एक अच्छे, परवाह करने वाले मित्र के रूप में देखे जाने की बात होती।"},
  {"id":"cdp-child-development-139","question":"Two students both say Heinz should NOT steal the drug. Student P says, ‘He would be caught and put in jail.’ Student Q says, ‘If everyone broke the law whenever they felt justified, society would collapse.’ In Kohlberg’s scheme:","options":["Both are at the same stage because they reach the same decision","P is at Stage 1 and Q is at Stage 4","P is at Stage 2 and Q is at Stage 3","P is at Stage 4 and Q is at Stage 5"],"answer":1,"explanation":"Kohlberg classified the reasoning, not the decision. Fear of punishment marks Stage 1; maintaining social order through law marks Stage 4.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"दो विद्यार्थी दोनों कहते हैं कि हाइंज को दवा नहीं चुरानी चाहिए। विद्यार्थी P कहता है, ‘वह पकड़ा जाएगा और जेल में डाला जाएगा।’ विद्यार्थी Q कहता है, ‘अगर हर कोई जब भी उचित समझे कानून तोड़े, तो समाज बिखर जाएगा।’ कोहलबर्ग की योजना में:","optionsHi":["दोनों एक ही चरण पर हैं क्योंकि वे एक ही निर्णय पर पहुँचते हैं","P चरण 1 पर है और Q चरण 4 पर","P चरण 2 पर है और Q चरण 3 पर","P चरण 4 पर है और Q चरण 5 पर"],"explanationHi":"कोहलबर्ग ने निर्णय को नहीं, तर्क को वर्गीकृत किया। दंड का भय चरण 1 की पहचान है; कानून के माध्यम से सामाजिक व्यवस्था बनाए रखना चरण 4 की पहचान है।"},
  {"id":"cdp-child-development-140","question":"A Class 9 student keeps changing friend groups, hobbies and career plans, and often asks, ‘Who am I really?’ Her parents fear something is wrong. According to Erik Erikson, the teacher should explain that:","options":["Her exploration is normal in the identity vs role confusion stage and helps form identity","She has regressed to the industry vs inferiority stage and needs remedial teaching","She is facing the intimacy vs isolation crisis, which normally belongs to adolescence","Her autonomy was not developed in early childhood, so the problem cannot now be corrected"],"answer":0,"explanation":"Trying out roles is the normal work of Erikson’s adolescent stage. Intimacy vs isolation belongs to young adulthood, and Erikson did not see earlier stages as permanently fixing later outcomes.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 9 की एक विद्यार्थी लगातार मित्र-समूह, शौक और करियर की योजनाएँ बदलती रहती है और अक्सर पूछती है, ‘मैं वास्तव में कौन हूँ?’ उसके माता-पिता को डर है कि कुछ गड़बड़ है। एरिक एरिक्सन के अनुसार शिक्षक को यह समझाना चाहिए कि:","optionsHi":["उसका यह अन्वेषण पहचान बनाम भूमिका भ्रांति की अवस्था में सामान्य है और पहचान बनाने में सहायक है","वह उद्यमिता बनाम हीनता की अवस्था में लौट गई है और उसे उपचारात्मक शिक्षण की आवश्यकता है","वह घनिष्ठता बनाम अलगाव के संकट का सामना कर रही है, जो सामान्यतः किशोरावस्था का होता है","प्रारंभिक बाल्यावस्था में उसकी स्वायत्तता विकसित नहीं हुई थी, इसलिए समस्या अब ठीक नहीं की जा सकती"],"explanationHi":"भूमिकाएँ आज़माना एरिक्सन की किशोरावस्था की अवस्था का सामान्य कार्य है। घनिष्ठता बनाम अलगाव युवा वयस्कता की अवस्था है, और एरिक्सन पहले की अवस्थाओं को बाद के परिणामों को स्थायी रूप से तय करने वाला नहीं मानते थे।"},
  {"id":"cdp-child-development-141","question":"A Class 3 child is constantly compared with a ‘topper’ sibling and given tasks far beyond his ability, at which he keeps failing. Erikson’s theory warns that he is at risk of developing:","options":["Mistrust, from the trust vs mistrust stage","Guilt, from the initiative vs guilt stage","Inferiority, from the industry vs inferiority stage","Role confusion, from the identity vs role confusion stage"],"answer":2,"explanation":"From about 6 to 12 years children judge themselves by their competence at tasks valued by school and peers; repeated failure and comparison breed inferiority. Achievable tasks and recognition of effort build industry.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 3 के एक बच्चे की तुलना लगातार ‘टॉपर’ भाई/बहन से की जाती है और उसे उसकी क्षमता से कहीं कठिन कार्य दिए जाते हैं, जिनमें वह बार-बार असफल होता है। एरिक्सन का सिद्धांत चेतावनी देता है कि उसमें किसके विकसित होने का जोखिम है?","optionsHi":["विश्वास बनाम अविश्वास की अवस्था से उपजा अविश्वास","पहल बनाम अपराधबोध की अवस्था से उपजा अपराधबोध","उद्यमिता बनाम हीनता की अवस्था से उपजी हीनता","पहचान बनाम भूमिका भ्रांति की अवस्था से उपजी भूमिका भ्रांति"],"explanationHi":"लगभग 6 से 12 वर्ष की आयु में बच्चे स्वयं को विद्यालय और साथियों द्वारा मूल्यवान माने जाने वाले कार्यों में अपनी दक्षता से आँकते हैं; बार-बार की असफलता और तुलना हीनता को जन्म देती है। प्राप्य कार्य और प्रयास की सराहना उद्यमिता का निर्माण करती है।"},
  {"id":"cdp-child-development-142","question":"Jerome Bruner claimed that any subject can be taught effectively in some intellectually honest form to any child at any stage of development. Which classroom implication follows from this claim?","options":["Complex ideas should be postponed until the child has reached the formal operational stage","Abstract symbols should be introduced as early as possible to speed up development","Each topic should be taught only once, in full depth, so that it need not be repeated","Big ideas can be taught early in enactive or iconic form and revisited in a spiral"],"answer":3,"explanation":"Bruner’s claim underlies the spiral curriculum: big ideas are introduced early in a form suited to the child and revisited with greater abstraction. Waiting for readiness is the position he was challenging.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"जेरोम ब्रूनर ने दावा किया कि किसी भी विषय को विकास के किसी भी चरण पर किसी भी बच्चे को किसी बौद्धिक रूप से ईमानदार रूप में प्रभावी ढंग से पढ़ाया जा सकता है। इस दावे से कक्षा के लिए कौन-सा निहितार्थ निकलता है?","optionsHi":["जटिल विचारों को तब तक टाल देना चाहिए जब तक बच्चा औपचारिक संक्रियात्मक अवस्था में न पहुँच जाए","विकास को तेज़ करने के लिए अमूर्त प्रतीकों को यथाशीघ्र आरंभ कर देना चाहिए","प्रत्येक विषय को केवल एक बार, पूरी गहराई में पढ़ाना चाहिए ताकि उसे दोहराना न पड़े","बड़े विचारों को क्रियात्मक या प्रतिबिंबात्मक रूप में जल्दी पढ़ाया जा सकता है और सर्पिल रूप में दोहराया जा सकता है"],"explanationHi":"ब्रूनर का दावा सर्पिल पाठ्यचर्या का आधार है: बड़े विचार बच्चे के अनुकूल रूप में जल्दी प्रस्तुत किए जाते हैं और अधिक अमूर्तता के साथ दोहराए जाते हैं। तत्परता की प्रतीक्षा करना वही मत है जिसे उन्होंने चुनौती दी थी।"},
  {"id":"cdp-child-development-143","question":"To teach the water cycle, a teacher uses a song, a role-play of water drops, a labelled diagram and a group discussion on local rainfall. Which statement best reflects Howard Gardner’s theory in this case?","options":["The lesson offers several entry points, so children with different strengths can engage","The teacher should first find each child’s single learning style and teach that child only through it","Intelligence is one general ability, so the variety of activities only adds interest","Each child’s intelligences are fixed at birth, so the activities cannot develop them"],"answer":0,"explanation":"Gardner recommends teaching important ideas in several ways. He explicitly rejected equating multiple intelligences with ‘learning styles’ that restrict a child to one channel, and he saw intelligences as open to development.","difficulty":"hard","source":"CTET · State TETs","questionHi":"जलचक्र पढ़ाने के लिए एक शिक्षिका गीत, पानी की बूँदों का भूमिका-अभिनय, नामांकित चित्र और स्थानीय वर्षा पर समूह चर्चा का उपयोग करती है। इस स्थिति में हॉवर्ड गार्डनर के सिद्धांत को कौन-सा कथन सबसे अच्छी तरह दर्शाता है?","optionsHi":["पाठ में कई प्रवेश-बिंदु हैं, इसलिए भिन्न-भिन्न क्षमताओं वाले बच्चे जुड़ सकते हैं","शिक्षक को पहले हर बच्चे की एकमात्र अधिगम शैली खोजनी चाहिए और उस बच्चे को केवल उसी के माध्यम से पढ़ाना चाहिए","बुद्धि एक सामान्य योग्यता है, इसलिए गतिविधियों की विविधता केवल रुचि बढ़ाती है","हर बच्चे की बुद्धियाँ जन्म से निश्चित होती हैं, इसलिए गतिविधियाँ उन्हें विकसित नहीं कर सकतीं"],"explanationHi":"गार्डनर महत्वपूर्ण विचारों को कई तरीकों से पढ़ाने की अनुशंसा करते हैं। उन्होंने बहुबुद्धि को ‘अधिगम शैलियों’ के बराबर मानने को, जो बच्चे को एक ही माध्यम तक सीमित करती हैं, स्पष्ट रूप से अस्वीकार किया, और वे बुद्धियों को विकास के लिए खुला मानते थे।"},
  {"id":"cdp-child-development-144","question":"Which of the following was NOT one of Howard Gardner’s criteria for accepting an ability as a separate intelligence?","options":["It can be isolated by brain damage, sparing other abilities","It has a distinct developmental history and an expert ‘end-state’ performance","It has an identifiable core operation or set of operations","It correlates highly with scores on standard IQ tests"],"answer":3,"explanation":"Gardner’s criteria include potential isolation by brain damage, a developmental history, core operations, existence of savants and prodigies, and encoding in a symbol system. A high correlation with IQ would argue against it being a separate intelligence.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"निम्नलिखित में से कौन-सा किसी योग्यता को अलग बुद्धि के रूप में स्वीकार करने के लिए हॉवर्ड गार्डनर के मानदंडों में से एक नहीं था?","optionsHi":["मस्तिष्क क्षति द्वारा इसे अलग किया जा सकता है, जबकि अन्य योग्यताएँ बची रहती हैं","इसका एक विशिष्ट विकासात्मक इतिहास और विशेषज्ञ ‘अंतिम-अवस्था’ निष्पादन है","इसका एक पहचानने योग्य मूल संक्रिया या संक्रियाओं का समूह है","मानक IQ परीक्षणों के अंकों के साथ इसका उच्च सहसंबंध है"],"explanationHi":"गार्डनर के मानदंडों में मस्तिष्क क्षति द्वारा संभावित पृथक्करण, विकासात्मक इतिहास, मूल संक्रियाएँ, सैवेंट और प्रतिभाशाली बालकों का अस्तित्व, और प्रतीक-प्रणाली में कूटबद्धता शामिल हैं। IQ के साथ उच्च सहसंबंध इसके अलग बुद्धि होने के विरुद्ध तर्क देगा।"},
  {"id":"cdp-child-development-145","question":"A child believes that heavy things always sink. On a field trip she sees a large log floating, becomes puzzled, and after discussion begins to think that whether something floats depends on more than its weight. In Piaget’s terms, her puzzlement and her revised idea are respectively:","options":["Assimilation and equilibrium","Disequilibrium and accommodation","Accommodation and disequilibrium","Conservation and seriation"],"answer":1,"explanation":"The conflict between her schema and what she saw creates disequilibrium; changing the schema to fit the new experience is accommodation, which restores equilibrium.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक बच्ची मानती है कि भारी चीजें हमेशा डूबती हैं। क्षेत्र-भ्रमण में वह एक बड़े लट्ठे को तैरते देखती है, उलझन में पड़ जाती है, और चर्चा के बाद सोचने लगती है कि कोई चीज़ तैरेगी या नहीं, यह केवल उसके वज़न पर नहीं बल्कि और बातों पर भी निर्भर करता है। पियाजे की शब्दावली में उसकी उलझन और उसका संशोधित विचार क्रमशः क्या हैं?","optionsHi":["आत्मसात्करण और साम्य","असाम्य और समायोजन","समायोजन और असाम्य","संरक्षण और क्रमबद्धता"],"explanationHi":"उसकी स्कीमा और उसने जो देखा, उनके बीच का टकराव असाम्य पैदा करता है; नए अनुभव के अनुरूप स्कीमा को बदलना समायोजन है, जो साम्य को पुनः स्थापित करता है।"},
  {"id":"cdp-child-development-146","question":"Asked to find out what decides how fast a pendulum swings, a 14-year-old changes only the length while keeping the weight and the push the same, then tests each factor in turn. A 9-year-old changes the length and the weight together. The older child is showing:","options":["Seriation, the ordering skill that the younger child has not yet acquired","Class inclusion, the part–whole logic typical of the concrete operational stage","Hypothetico-deductive reasoning, isolating one variable at a time","Object permanence, which lets the older child keep the pendulum in mind"],"answer":2,"explanation":"Testing one variable at a time to check hypotheses is the hallmark of formal operational thought (Inhelder and Piaget’s pendulum task). Concrete operational children tend to vary several factors at once.","difficulty":"hard","source":"CTET · State TETs","questionHi":"यह पता लगाने को कहा जाने पर कि पेंडुलम कितनी तेज़ झूलेगा यह किससे तय होता है, एक 14 वर्ष का किशोर वज़न और धक्का समान रखते हुए केवल लंबाई बदलता है, फिर हर कारक को बारी-बारी से परखता है। एक 9 वर्ष का बच्चा लंबाई और वज़न दोनों एक साथ बदलता है। बड़ा बच्चा क्या दर्शा रहा है?","optionsHi":["क्रमबद्धता, वह क्रमण-कौशल जो छोटे बच्चे ने अभी अर्जित नहीं किया है","वर्ग-समावेशन, मूर्त संक्रियात्मक अवस्था की विशिष्ट अंश–पूर्ण तर्क-शक्ति","परिकल्पनात्मक-निगमनात्मक तर्क, एक समय में एक चर को अलग करना","वस्तु स्थायित्व, जो बड़े बच्चे को पेंडुलम को मन में रखने देता है"],"explanationHi":"परिकल्पनाओं की जाँच के लिए एक समय में एक चर परखना औपचारिक संक्रियात्मक चिंतन की पहचान है (इनहेल्डर और पियाजे का पेंडुलम कार्य)। मूर्त संक्रियात्मक बच्चे प्रायः कई कारकों को एक साथ बदलते हैं।"},
  {"id":"cdp-child-development-147","question":"A Class 5 child easily solves ‘Ravi is taller than Mohan and Mohan is taller than Sohan; who is the tallest?’ But told ‘Suppose all elephants were purple; Moti is an elephant, so what colour is Moti?’, he replies, ‘Elephants are grey, not purple.’ This best shows that:","options":["He is concrete operational: he reasons about real facts, not contrary-to-fact premises","He is still pre-operational, since he cannot yet use transitive reasoning about heights","He has reached formal operations but is careless with imaginary premises","He lacks conservation, which is a prerequisite for all logical reasoning"],"answer":0,"explanation":"He handles transitivity (concrete operations) but cannot accept a hypothetical premise and reason from it, which needs formal operational thought.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 5 का एक बच्चा ‘रवि मोहन से लंबा है और मोहन सोहन से लंबा है; सबसे लंबा कौन है?’ आसानी से हल कर लेता है। परंतु जब उससे कहा जाता है, ‘मान लो सभी हाथी बैंगनी होते; मोती एक हाथी है, तो मोती का रंग क्या है?’ तो वह उत्तर देता है, ‘हाथी तो स्लेटी होते हैं, बैंगनी नहीं।’ यह सबसे अच्छी तरह क्या दर्शाता है?","optionsHi":["वह मूर्त संक्रियात्मक है: वह वास्तविक तथ्यों के बारे में तर्क करता है, तथ्य-विरुद्ध आधार-वाक्यों के बारे में नहीं","वह अभी पूर्व-संक्रियात्मक है, क्योंकि वह अभी ऊँचाई के बारे में संक्रामक तर्क का उपयोग नहीं कर सकता","वह औपचारिक संक्रियाओं तक पहुँच गया है, पर काल्पनिक आधार-वाक्यों के प्रति लापरवाह है","उसमें संरक्षण का अभाव है, जो सभी तार्किक चिंतन की पूर्वापेक्षा है"],"explanationHi":"वह संक्रामकता (मूर्त संक्रियाएँ) संभाल लेता है, पर किसी काल्पनिक आधार-वाक्य को स्वीकार कर उससे तर्क नहीं कर पाता, जिसके लिए औपचारिक संक्रियात्मक चिंतन चाहिए।"},
  {"id":"cdp-child-development-148","question":"Students forget new science terms within days when they just repeat them aloud, but remember them for weeks when they link each term to familiar examples and use it to explain events around them. According to the levels-of-processing view of Craik and Lockhart, this is because:","options":["Repeating aloud moves information straight into long-term memory storage","Short-term memory has unlimited capacity whenever the information is meaningful","Forgetting is caused only by the passage of time, not by how one studies","Meaningful, elaborative processing leaves deeper, longer-lasting memory traces"],"answer":3,"explanation":"Craik and Lockhart argued that retention depends on depth of processing; semantic elaboration produces stronger traces than maintenance rehearsal.","difficulty":"hard","source":"CTET · State TETs","questionHi":"जब विद्यार्थी नए विज्ञान शब्दों को केवल ज़ोर से दोहराते हैं तो कुछ ही दिनों में भूल जाते हैं, पर जब हर शब्द को परिचित उदाहरणों से जोड़ते हैं और उसका उपयोग अपने आसपास की घटनाओं को समझाने में करते हैं तो हफ्तों तक याद रखते हैं। क्रेक और लॉकहार्ट के प्रक्रमण-स्तर दृष्टिकोण के अनुसार इसका कारण यह है कि:","optionsHi":["ज़ोर से दोहराने से जानकारी सीधे दीर्घकालिक स्मृति संचय में चली जाती है","जब भी जानकारी सार्थक हो, अल्पकालिक स्मृति की क्षमता असीमित हो जाती है","विस्मरण केवल समय बीतने से होता है, इससे नहीं कि कोई कैसे पढ़ता है","सार्थक, विस्तारणात्मक प्रक्रमण अधिक गहरे, अधिक टिकाऊ स्मृति-चिह्न छोड़ता है"],"explanationHi":"क्रेक और लॉकहार्ट ने तर्क दिया कि धारण प्रक्रमण की गहराई पर निर्भर करता है; अर्थगत विस्तारण रखरखाव पुनरावृत्ति की तुलना में अधिक सशक्त चिह्न बनाता है।"},
  {"id":"cdp-child-development-149","question":"A child was repeatedly humiliated in front of the class during maths periods. Now she feels anxious as soon as she sees her maths textbook, even at home. In terms of classical conditioning:","options":["The textbook is the unconditioned stimulus and anxiety the unconditioned response","The humiliation is the conditioned stimulus and the textbook the unconditioned stimulus","The textbook is now a conditioned stimulus, and the anxiety a conditioned response","The anxiety is an operant behaviour that is being negatively reinforced"],"answer":2,"explanation":"Humiliation (UCS) naturally caused fear (UCR). Paired with it, the once-neutral textbook became a CS that alone now produces anxiety, a CR. Such conditioned anxiety is why classroom climate matters.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक बच्ची को गणित के पीरियड में कक्षा के सामने बार-बार अपमानित किया गया। अब गणित की पाठ्यपुस्तक देखते ही वह घबरा जाती है, घर पर भी। शास्त्रीय अनुबंधन के संदर्भ में:","optionsHi":["पाठ्यपुस्तक अनानुबंधित उद्दीपक है और घबराहट अनानुबंधित अनुक्रिया","अपमान अनुबंधित उद्दीपक है और पाठ्यपुस्तक अनानुबंधित उद्दीपक","पाठ्यपुस्तक अब अनुबंधित उद्दीपक है, और घबराहट अनुबंधित अनुक्रिया","घबराहट एक क्रियाप्रसूत व्यवहार है जिसे ऋणात्मक पुनर्बलन मिल रहा है"],"explanationHi":"अपमान (UCS) ने स्वाभाविक रूप से भय (UCR) उत्पन्न किया। उसके साथ जुड़कर, पहले तटस्थ रही पाठ्यपुस्तक एक CS बन गई जो अब अकेले घबराहट, यानी CR, पैदा करती है। ऐसी अनुबंधित घबराहट ही कारण है कि कक्षा का वातावरण मायने रखता है।"},
  {"id":"cdp-child-development-150","question":"Whenever Manav disrupts the class, the teacher takes away ten minutes of his break time, and his disruptions decrease. In operant terms this is:","options":["Negative reinforcement","Negative punishment","Positive punishment","Extinction"],"answer":1,"explanation":"Removing something pleasant to reduce a behaviour is negative punishment. Negative reinforcement removes something unpleasant and increases a behaviour, a common mix-up.","difficulty":"hard","source":"CTET · State TETs","questionHi":"जब भी मानव कक्षा में बाधा डालता है, शिक्षक उसके अवकाश का दस मिनट छीन लेते हैं, और उसकी बाधाएँ घट जाती हैं। क्रियाप्रसूत शब्दावली में यह है:","optionsHi":["ऋणात्मक पुनर्बलन","ऋणात्मक दंड","धनात्मक दंड","विलोपन"],"explanationHi":"किसी व्यवहार को घटाने के लिए कोई सुखद चीज़ हटाना ऋणात्मक दंड है। ऋणात्मक पुनर्बलन कोई अप्रिय चीज़ हटाता है और व्यवहार को बढ़ाता है, जो एक आम भ्रम है।"},
  {"id":"cdp-child-development-151","question":"A teacher decides to stop responding to a child who calls out answers without raising her hand. For the first few days the calling out becomes louder and more frequent. The teacher should understand that:","options":["This is an extinction burst; if she stays consistent the behaviour should decline","Ignoring has failed, so she should go back to responding to the child","The child is being negatively reinforced by being ignored","This shows spontaneous recovery, which means the behaviour has been permanently learnt"],"answer":0,"explanation":"When a reinforcer is withdrawn, behaviour often intensifies briefly (an extinction burst). Giving in at this point reinforces the louder behaviour on an intermittent schedule and makes it harder to remove.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक शिक्षिका उस बच्ची को प्रतिक्रिया देना बंद करने का निर्णय लेती है जो हाथ उठाए बिना उत्तर बोल देती है। पहले कुछ दिनों तक बीच में बोलना और ज़ोर से तथा अधिक बार होने लगता है। शिक्षिका को यह समझना चाहिए कि:","optionsHi":["यह विलोपन विस्फोट है; यदि वह निरंतरता बनाए रखे तो व्यवहार घटना चाहिए","अनदेखी करना विफल हो गया है, इसलिए उसे बच्ची को प्रतिक्रिया देना फिर शुरू कर देना चाहिए","अनदेखी किए जाने से बच्ची को ऋणात्मक पुनर्बलन मिल रहा है","यह स्वतः पुनर्प्राप्ति दर्शाता है, जिसका अर्थ है कि व्यवहार स्थायी रूप से सीख लिया गया है"],"explanationHi":"जब कोई पुनर्बलक हटाया जाता है, तो व्यवहार प्रायः थोड़े समय के लिए तेज़ हो जाता है (विलोपन विस्फोट)। इस मोड़ पर हार मान लेना रुक-रुक कर चलने वाली अनुसूची पर तेज़ व्यवहार को पुनर्बलित करता है और उसे हटाना कठिन बना देता है।"},
  {"id":"cdp-child-development-152","question":"A teacher wants students to keep reading at home even after the class reward chart is withdrawn. Which pattern of rewards, while the chart is in use, is most likely to produce reading that resists extinction?","options":["A sticker for every single book, so that no reading goes unrewarded","A sticker exactly after every fifth book, so pupils know what to expect","A sticker on the last day of every month, whatever was read","A sticker after an unpredictable number of books, about one in four"],"answer":3,"explanation":"A variable-ratio schedule produces high, steady responding that is most resistant to extinction, because the learner cannot tell when the reward has stopped. Continuous reinforcement extinguishes fastest.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षिका चाहती है कि कक्षा का पुरस्कार चार्ट हटा लिए जाने के बाद भी विद्यार्थी घर पर पढ़ते रहें। चार्ट के उपयोग के दौरान पुरस्कारों का कौन-सा पैटर्न ऐसी पढ़ाई पैदा करने की सबसे अधिक संभावना रखता है जो विलोपन का प्रतिरोध करे?","optionsHi":["हर एक किताब पर एक स्टिकर, ताकि कोई पढ़ाई बिना पुरस्कार के न रहे","ठीक हर पाँचवीं किताब के बाद एक स्टिकर, ताकि विद्यार्थी जानें कि क्या अपेक्षा करनी है","हर महीने के अंतिम दिन एक स्टिकर, चाहे कुछ भी पढ़ा गया हो","अप्रत्याशित संख्या में किताबों के बाद एक स्टिकर, लगभग हर चार में एक"],"explanationHi":"परिवर्ती-अनुपात अनुसूची उच्च, स्थिर अनुक्रिया उत्पन्न करती है जो विलोपन का सबसे अधिक प्रतिरोध करती है, क्योंकि अधिगमकर्ता यह नहीं बता सकता कि पुरस्कार कब बंद हो गया। सतत पुनर्बलन सबसे जल्दी विलुप्त होता है।"},
  {"id":"cdp-child-development-153","question":"Simran is convinced she ‘can never do maths’. According to Bandura, which step would most strongly raise her self-efficacy in maths?","options":["Telling her again and again, ‘You are a bright girl, you can surely do it’","Letting her watch the class topper solve difficult problems with ease","Giving her graded tasks she can really succeed at, then harder ones","Excusing her from maths tests until she feels more confident in herself"],"answer":2,"explanation":"Mastery experiences are the strongest source of self-efficacy. Verbal persuasion is weaker, and a model seen as very unlike oneself (the topper) has less effect than a similar model.","difficulty":"hard","source":"CTET · State TETs","questionHi":"सिमरन को पूरा यकीन है कि वह ‘गणित कभी नहीं कर सकती’। बंडूरा के अनुसार कौन-सा कदम गणित में उसकी आत्म-प्रभावकारिता को सबसे अधिक बढ़ाएगा?","optionsHi":["उससे बार-बार कहना, ‘तुम होशियार लड़की हो, तुम ज़रूर कर सकती हो’","उसे कक्षा के टॉपर को कठिन सवाल आसानी से हल करते देखने देना","उसे क्रमिक कार्य देना जिनमें वह वास्तव में सफल हो सके, फिर कठिन कार्य","जब तक उसमें अपने प्रति अधिक आत्मविश्वास न आ जाए, उसे गणित के परीक्षणों से छूट देना"],"explanationHi":"निपुणता के अनुभव आत्म-प्रभावकारिता का सबसे सशक्त स्रोत हैं। शाब्दिक प्रोत्साहन कमज़ोर है, और अपने से बहुत भिन्न माना जाने वाला आदर्श (टॉपर) समान आदर्श की तुलना में कम प्रभाव डालता है।"},
  {"id":"cdp-child-development-154","question":"A child watches a folk dance closely and can describe every step accurately afterwards, wanting badly to perform it, but cannot yet coordinate her movements to do so. In Bandura’s model of observational learning, the breakdown is at the stage of:","options":["Attention to the model","Motor reproduction","Retention in memory","Motivation to perform"],"answer":1,"explanation":"She attended and retained the steps, and she is motivated; what is missing is the physical ability to reproduce them. Practice with feedback is needed.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक बच्ची लोक नृत्य को ध्यान से देखती है और बाद में हर कदम को सही-सही बता सकती है, उसे प्रस्तुत करने की बहुत इच्छा है, पर वह अभी इसके लिए अपनी गतियों का समन्वय नहीं कर पाती। बंडूरा के अवलोकनात्मक अधिगम मॉडल में बाधा किस चरण पर है?","optionsHi":["आदर्श पर ध्यान","गामक पुनरुत्पादन","स्मृति में धारण","प्रदर्शन की अभिप्रेरणा"],"explanationHi":"उसने ध्यान दिया और कदमों को याद रखा, और वह अभिप्रेरित भी है; जो अनुपस्थित है वह उन्हें दोहराने की शारीरिक क्षमता है। प्रतिपुष्टि सहित अभ्यास की आवश्यकता है।"},
  {"id":"cdp-child-development-155","question":"After seeing the teacher praise Rekha for her neat notebook in front of the class, several other children begin to keep their notebooks neat, though none of them has been praised yet. This is best explained by:","options":["Vicarious reinforcement","Classical conditioning","Trial-and-error learning","Negative reinforcement"],"answer":0,"explanation":"Seeing a model rewarded raises the observers’ expectation of reward, which Bandura called vicarious reinforcement.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"शिक्षक को रेखा की साफ-सुथरी कॉपी की कक्षा के सामने प्रशंसा करते देख, कई अन्य बच्चे अपनी कॉपियाँ साफ रखने लगते हैं, जबकि उनमें से किसी की अभी प्रशंसा नहीं हुई है। इसे सबसे अच्छी तरह कौन-सा कारक समझाता है?","optionsHi":["प्रतिनिधिक पुनर्बलन","शास्त्रीय अनुबंधन","प्रयास और त्रुटि अधिगम","ऋणात्मक पुनर्बलन"],"explanationHi":"किसी आदर्श को पुरस्कृत होते देखना प्रेक्षकों की पुरस्कार की अपेक्षा बढ़ाता है, जिसे बंडूरा ने प्रतिनिधिक पुनर्बलन कहा।"},
  {"id":"cdp-child-development-156","question":"A Class 4 student with low vision has joined a regular school. Which plan best reflects inclusive education under the RPwD Act, 2016?","options":["Recommend a special school, since the pace of a regular class may slow her down","Exempt her from all written assessments so that she is never under pressure","Ask her to sit at the back so that she does not feel singled out by classmates","Seat her near the board, give large-print or audio material and read aloud the board work"],"answer":3,"explanation":"Inclusion means adapting seating, materials and teaching so that the child learns in the regular class with reasonable accommodation, not segregating or exempting her.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 4 की कम दृष्टि वाली एक विद्यार्थी ने एक सामान्य विद्यालय में प्रवेश लिया है। RPwD अधिनियम, 2016 के अंतर्गत समावेशी शिक्षा को कौन-सी योजना सबसे अच्छी तरह दर्शाती है?","optionsHi":["विशेष विद्यालय की अनुशंसा करना, क्योंकि सामान्य कक्षा की गति उसे धीमा कर सकती है","उसे सभी लिखित आकलनों से छूट देना ताकि उस पर कभी दबाव न पड़े","उसे पीछे बैठने को कहना ताकि सहपाठियों के बीच वह अलग न दिखे","उसे बोर्ड के पास बैठाना, बड़े अक्षरों वाली या श्रव्य सामग्री देना और बोर्ड का कार्य पढ़कर सुनाना"],"explanationHi":"समावेशन का अर्थ है बैठने की व्यवस्था, सामग्री और शिक्षण को ढालना ताकि बच्चा उचित समायोजन के साथ सामान्य कक्षा में सीखे, न कि उसे अलग करना या छूट देना।"},
  {"id":"cdp-child-development-157","question":"In a lesson on plants, a teacher presents the content as a picture chart, a real potted plant to touch, an oral explanation and a short text with key words highlighted. Under Universal Design for Learning, she is mainly applying the principle of:","options":["Multiple means of engagement","Multiple means of action and expression","Multiple means of representation","Individualised remedial teaching"],"answer":2,"explanation":"Offering the same content in several forms (visual, tactile, auditory, text) is multiple means of representation. Letting children show learning in different ways would be action and expression.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"पौधों पर एक पाठ में शिक्षिका सामग्री को चित्र चार्ट, छूने के लिए एक असली गमले का पौधा, मौखिक व्याख्या और प्रमुख शब्द रेखांकित किए गए एक छोटे पाठ के रूप में प्रस्तुत करती है। अधिगम के सार्वभौमिक डिज़ाइन (UDL) के अंतर्गत वह मुख्यतः किस सिद्धांत को लागू कर रही है?","optionsHi":["जुड़ाव के अनेक साधन","क्रिया और अभिव्यक्ति के अनेक साधन","निरूपण के अनेक साधन","वैयक्तिकृत उपचारात्मक शिक्षण"],"explanationHi":"एक ही सामग्री को कई रूपों (दृश्य, स्पर्शीय, श्रव्य, पाठ) में प्रस्तुत करना निरूपण के अनेक साधन हैं। बच्चों को सीखे हुए को अलग-अलग तरीकों से दिखाने देना क्रिया और अभिव्यक्ति होती।"},
  {"id":"cdp-child-development-158","question":"A school admits children with disabilities into its regular classes but makes no change in teaching, materials, building or assessment; the children are expected to ‘cope like everyone else’. This situation is best described as:","options":["Inclusion, because the children study in the same classroom as others","Integration: placed in the mainstream but expected to fit an unchanged system","Segregation, because the children are kept in a separate special unit","Mainstreaming with full reasonable accommodation, as the RPwD Act requires"],"answer":1,"explanation":"Inclusion changes the system to fit every child; mere physical placement without accommodation is integration. The RPwD Act 2016 requires reasonable accommodation.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक विद्यालय दिव्यांग बच्चों को अपनी सामान्य कक्षाओं में प्रवेश देता है पर शिक्षण, सामग्री, भवन या आकलन में कोई बदलाव नहीं करता; बच्चों से अपेक्षा की जाती है कि वे ‘बाकी सबकी तरह निभा लें’। इस स्थिति का सबसे उपयुक्त वर्णन है:","optionsHi":["समावेशन, क्योंकि बच्चे दूसरों के साथ एक ही कक्षा में पढ़ते हैं","एकीकरण: मुख्यधारा में रखा गया पर एक अपरिवर्तित व्यवस्था में ढलने की अपेक्षा","पृथक्करण, क्योंकि बच्चों को अलग विशेष इकाई में रखा गया है","पूर्ण उचित समायोजन के साथ मुख्यधारा में लाना, जैसा RPwD अधिनियम की अपेक्षा है"],"explanationHi":"समावेशन व्यवस्था को हर बच्चे के अनुकूल बदलता है; समायोजन के बिना केवल शारीरिक रूप से रखना एकीकरण है। RPwD अधिनियम 2016 उचित समायोजन की अपेक्षा करता है।"},
  {"id":"cdp-child-development-159","question":"A school claims to follow continuous and comprehensive evaluation because it now holds a written unit test every week in every subject. The strongest criticism of this claim is that:","options":["It equates continuous with frequent testing and ignores co-scholastic areas","Weekly tests are too few; CCE requires a written test every single day","CCE forbids all written tests, so the school is actually breaking the rules","CCE is meant only for co-scholastic areas, so subject tests are irrelevant"],"answer":0,"explanation":"‘Continuous’ refers to ongoing assessment during learning (observation, projects, discussion, portfolios), and ‘comprehensive’ to scholastic and co-scholastic growth. More tests only add testing pressure.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक विद्यालय दावा करता है कि वह सतत और व्यापक मूल्यांकन का पालन करता है क्योंकि अब वह हर विषय में हर सप्ताह एक लिखित इकाई परीक्षा लेता है। इस दावे की सबसे सशक्त आलोचना यह है कि:","optionsHi":["यह ‘सतत’ को बार-बार परीक्षा लेने के बराबर मानता है और सह-शैक्षिक क्षेत्रों की उपेक्षा करता है","साप्ताहिक परीक्षाएँ बहुत कम हैं; CCE में हर एक दिन लिखित परीक्षा आवश्यक है","CCE सभी लिखित परीक्षाओं को निषिद्ध करता है, इसलिए विद्यालय वास्तव में नियम तोड़ रहा है","CCE केवल सह-शैक्षिक क्षेत्रों के लिए है, इसलिए विषय परीक्षाएँ अप्रासंगिक हैं"],"explanationHi":"‘सतत’ सीखने के दौरान चलने वाले आकलन (अवलोकन, परियोजनाएँ, चर्चा, पोर्टफोलियो) को दर्शाता है, और ‘व्यापक’ शैक्षिक तथा सह-शैक्षिक विकास को। अधिक परीक्षाएँ केवल परीक्षण का दबाव बढ़ाती हैं।"},
  {"id":"cdp-child-development-160","question":"After a writing task, students use a rubric to judge their own drafts, note what they need to improve, and set a target for the next draft. This is best described as:","options":["Assessment of learning","Summative assessment","Norm-referenced assessment","Assessment as learning"],"answer":3,"explanation":"When learners themselves monitor and regulate their learning through self-assessment, assessment becomes part of learning (assessment as learning), developing metacognition.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक लेखन कार्य के बाद विद्यार्थी रूब्रिक की मदद से अपने प्रारूपों का स्वयं मूल्यांकन करते हैं, यह नोट करते हैं कि उन्हें क्या सुधारना है, और अगले प्रारूप के लिए लक्ष्य तय करते हैं। इसका सबसे अच्छा वर्णन है:","optionsHi":["अधिगम का आकलन","योगात्मक आकलन","मानक-संदर्भित आकलन","अधिगम के रूप में आकलन"],"explanationHi":"जब अधिगमकर्ता स्वयं आत्म-आकलन द्वारा अपने सीखने की निगरानी और नियमन करते हैं, तो आकलन अधिगम का हिस्सा बन जाता है (अधिगम के रूप में आकलन), जो अधिसंज्ञान विकसित करता है।"},
  {"id":"cdp-child-development-161","question":"Which report on a Class 2 reading test is criterion-referenced?","options":["Riya scored higher than 80% of the Class 2 children in her whole district","Riya reads 40 words a minute with 95% accuracy, meeting the set Grade 2 standard","Riya ranked 3rd out of 42 children in her section on this test","Riya’s score lies one standard deviation above the mean of her class"],"answer":1,"explanation":"A criterion-referenced report compares performance with a fixed standard of what the child can do. Percentiles, ranks and standard scores compare her with other children (norm-referenced).","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 2 के पठन परीक्षण की कौन-सी रिपोर्ट कसौटी-संदर्भित है?","optionsHi":["रिया ने अपने पूरे जिले के 80% बच्चों (कक्षा 2) से अधिक अंक पाए","रिया प्रति मिनट 40 शब्द 95% शुद्धता के साथ पढ़ती है, जो निर्धारित कक्षा 2 का मानक पूरा करता है","इस परीक्षण में रिया अपने अनुभाग में तीसरे स्थान पर रही (कुल 42 बच्चों में)","रिया का अंक उसकी कक्षा के माध्य से एक मानक विचलन ऊपर है"],"explanationHi":"कसौटी-संदर्भित रिपोर्ट प्रदर्शन की तुलना इस बात के निश्चित मानक से करती है कि बच्चा क्या कर सकता है। शतमक, रैंक और मानक प्राप्तांक उसकी तुलना अन्य बच्चों से करते हैं (मानक-संदर्भित)।"},
  {"id":"cdp-child-development-162","question":"A Class 4 maths test on multiplication uses long word problems written in difficult English. Many children who multiply well in class score poorly. The main problem with the test is its:","options":["Reliability, because the scores would change if the test were repeated","Objectivity, because different teachers would mark it differently","Validity, as it partly measures English reading, not multiplication","Practicability, because it takes too long to administer"],"answer":2,"explanation":"A test is valid if it measures what it intends to. Here reading ability contaminates the score, so it is not a valid test of multiplication, even if it gives consistent results.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 4 का गुणा पर एक गणित परीक्षण कठिन अंग्रेजी में लिखे लंबे शब्द-प्रश्नों का उपयोग करता है। कई बच्चे जो कक्षा में अच्छा गुणा करते हैं, कम अंक पाते हैं। परीक्षण की मुख्य समस्या उसकी कौन-सी है?","optionsHi":["विश्वसनीयता, क्योंकि परीक्षण दोहराने पर अंक बदल जाएँगे","वस्तुनिष्ठता, क्योंकि अलग-अलग शिक्षक उसे अलग तरह से अंक देंगे","वैधता, क्योंकि वह आंशिक रूप से गुणा नहीं बल्कि अंग्रेजी पठन को मापता है","व्यावहारिकता, क्योंकि उसे प्रशासित करने में बहुत समय लगता है"],"explanationHi":"कोई परीक्षण तब वैध होता है जब वह वही मापे जो मापना चाहता है। यहाँ पठन-योग्यता अंक को दूषित करती है, इसलिए यह गुणा का वैध परीक्षण नहीं है, भले ही वह सुसंगत परिणाम दे।"},
  {"id":"cdp-child-development-163","question":"Studies show that identical twins reared apart have more similar intelligence test scores than unrelated children reared together, yet adopted children from deprived homes gain considerably when raised in enriched homes. The most defensible conclusion is:","options":["Heredity sets a range; environment decides where within it a child develops","Intelligence is fixed entirely by heredity, so enrichment cannot really raise it","Intelligence is decided entirely by environment, as adoption studies prove","Heredity and environment act separately, so their effects can simply be added"],"answer":0,"explanation":"Both findings together point to interaction: genes contribute substantially, but environment shapes how that potential is realised. Neither extreme position fits both findings.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अध्ययन बताते हैं कि अलग-अलग पाले गए समान जुड़वाँ बच्चों के बुद्धि परीक्षण अंक साथ पाले गए असंबंधित बच्चों से अधिक समान होते हैं, फिर भी वंचित घरों से गोद लिए गए बच्चे समृद्ध घरों में पाले जाने पर काफी लाभ पाते हैं। सबसे उचित निष्कर्ष क्या है?","optionsHi":["आनुवंशिकता एक सीमा तय करती है; पर्यावरण तय करता है कि बच्चा उसके भीतर कहाँ तक विकसित होता है","बुद्धि पूरी तरह आनुवंशिकता से निश्चित होती है, इसलिए संवर्धन उसे वास्तव में नहीं बढ़ा सकता","बुद्धि पूरी तरह पर्यावरण से तय होती है, जैसा कि गोद लेने के अध्ययन सिद्ध करते हैं","आनुवंशिकता और पर्यावरण अलग-अलग कार्य करते हैं, इसलिए उनके प्रभाव सीधे जोड़े जा सकते हैं"],"explanationHi":"दोनों निष्कर्ष मिलकर अंतःक्रिया की ओर संकेत करते हैं: जीन का योगदान पर्याप्त है, पर पर्यावरण तय करता है कि उस क्षमता को कितना साकार किया जाए। कोई भी चरम मत दोनों निष्कर्षों में फिट नहीं बैठता।"},
  {"id":"cdp-child-development-164","question":"A four-year-old, while playing with a friend, explains how to play a board game: ‘You put this here, then that goes there,’ pointing at pieces the friend cannot see from across the room. According to Piaget, this speech shows:","options":["Animism, treating the game pieces as if they were alive","Centration, focusing on a single dimension of the game","A lack of object permanence for pieces out of sight","Egocentrism: difficulty taking another’s point of view"],"answer":3,"explanation":"The child assumes the listener sees what she sees, so ‘this’ and ‘there’ seem clear to her. Piaget called this egocentric thought and speech.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"एक चार वर्ष की बच्ची, मित्र के साथ खेलते हुए, बोर्ड गेम खेलना समझाती है: ‘इसे यहाँ रखो, फिर वो वहाँ जाता है,’ उन मोहरों की ओर इशारा करते हुए जिन्हें कमरे के दूसरी ओर से मित्र नहीं देख सकता। पियाजे के अनुसार यह वाक् क्या दर्शाता है?","optionsHi":["सजीववाद, खेल के मोहरों को ऐसे मानना मानो वे जीवित हों","केंद्रीकरण, खेल के किसी एक आयाम पर ध्यान केंद्रित करना","नज़र से ओझल मोहरों के लिए वस्तु स्थायित्व का अभाव","अहंकेंद्रिता: दूसरे के दृष्टिकोण को समझने में कठिनाई"],"explanationHi":"बच्ची मान लेती है कि श्रोता वही देखता है जो वह देखती है, इसलिए उसे ‘इसे’ और ‘वहाँ’ स्पष्ट लगते हैं। पियाजे ने इसे अहंकेंद्रित चिंतन और वाक् कहा।"},
  {"id":"cdp-child-development-165","question":"A Class 3 textbook picture shows only mothers cooking and only fathers going to an office. The most appropriate response of a gender-sensitive teacher is to:","options":["Skip the picture so that the issue of gender does not come up at all","Explain that this is how families naturally divide work between men and women","Ask who does which work at home and discuss whether any work belongs to one gender","Tell the girls in the class that they will not have to cook when they grow up"],"answer":2,"explanation":"Drawing on children’s own experiences and discussing stereotypes helps them question fixed gender roles, as NCF 2005 urges. Ignoring or endorsing the picture leaves the stereotype unexamined.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 3 की पाठ्यपुस्तक के एक चित्र में केवल माताएँ खाना पकाती और केवल पिता दफ़्तर जाते दिखाए गए हैं। लिंग-संवेदनशील शिक्षक की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["चित्र को छोड़ देना ताकि लिंग का मुद्दा उठे ही नहीं","समझाना कि परिवार स्वाभाविक रूप से पुरुषों और महिलाओं में काम ऐसे ही बाँटते हैं","पूछना कि घर पर कौन-सा काम कौन करता है और चर्चा करना कि क्या कोई काम किसी एक लिंग का होता है","कक्षा की लड़कियों से कहना कि बड़े होने पर उन्हें खाना नहीं पकाना पड़ेगा"],"explanationHi":"बच्चों के अपने अनुभवों के आधार पर चर्चा करना और रूढ़ियों पर बात करना उन्हें निश्चित लिंग-भूमिकाओं पर प्रश्न करने में मदद करता है, जैसा NCF 2005 आग्रह करता है। चित्र की अनदेखी या समर्थन रूढ़ि को बिना जाँचे छोड़ देता है।"},
  {"id":"cdp-child-development-166","question":"At the start of the year a teacher is told (wrongly) that five randomly chosen children are ‘late bloomers’ about to make big gains. She gives them more attention, wait-time and encouragement, and by the year’s end they have indeed improved more than others. This illustrates:","options":["The halo effect","The Pygmalion effect","Regression towards the mean","The Hawthorne effect"],"answer":1,"explanation":"Rosenthal and Jacobson showed that teachers’ expectations can change how they treat pupils and so shape achievement. This is why labelling children is harmful.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"वर्ष की शुरुआत में एक शिक्षिका को (गलत तरीके से) बताया जाता है कि यादृच्छिक रूप से चुने गए पाँच बच्चे ‘देर से खिलने वाले’ हैं जो बड़ी प्रगति करने वाले हैं। वह उन्हें अधिक ध्यान, प्रतीक्षा-समय और प्रोत्साहन देती है, और वर्ष के अंत तक वे वास्तव में दूसरों से अधिक सुधर जाते हैं। यह क्या दर्शाता है?","optionsHi":["प्रभामंडल प्रभाव","पिग्मैलियन प्रभाव","माध्य की ओर प्रतिगमन","हॉथॉर्न प्रभाव"],"explanationHi":"रोज़ेंथल और जैकबसन ने दिखाया कि शिक्षकों की अपेक्षाएँ उनके विद्यार्थियों के साथ व्यवहार को बदल सकती हैं और इस प्रकार उपलब्धि को आकार दे सकती हैं। इसीलिए बच्चों पर लेबल लगाना हानिकारक है।"},
  {"id":"cdp-child-development-167","question":"Children in a class love drawing in their free time. The school begins to give a prize for every drawing. Some weeks later the prizes are stopped, and the children now draw much less than they did before prizes began. The best explanation is that:","options":["The prizes undermined their intrinsic interest, so drawing began to feel like work","The prizes were too small to make a lasting difference to their habits","The children have become better at drawing and no longer need practice","Drawing has been extinguished, since it was never reinforced before the prizes"],"answer":0,"explanation":"Expected tangible rewards for an already enjoyable activity can reduce intrinsic motivation (the overjustification effect). Drawing was intrinsically motivated before the prizes, so the last option is wrong.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा के बच्चों को खाली समय में चित्र बनाना पसंद है। विद्यालय हर चित्र पर पुरस्कार देना शुरू करता है। कुछ सप्ताह बाद पुरस्कार बंद कर दिए जाते हैं, और बच्चे अब पुरस्कार शुरू होने से पहले की तुलना में बहुत कम चित्र बनाते हैं। सबसे अच्छा स्पष्टीकरण क्या है?","optionsHi":["पुरस्कारों ने उनकी आंतरिक रुचि को कमज़ोर कर दिया, इसलिए चित्र बनाना काम जैसा लगने लगा","पुरस्कार इतने छोटे थे कि उनकी आदतों में स्थायी अंतर नहीं ला सके","बच्चे चित्र बनाने में बेहतर हो गए हैं और उन्हें अब अभ्यास की आवश्यकता नहीं है","चित्र बनाना विलुप्त हो गया है, क्योंकि पुरस्कारों से पहले उसे कभी पुनर्बलित नहीं किया गया था"],"explanationHi":"पहले से आनंददायक गतिविधि के लिए अपेक्षित ठोस पुरस्कार आंतरिक अभिप्रेरणा को घटा सकते हैं (अतिऔचित्य प्रभाव)। पुरस्कारों से पहले चित्र बनाना आंतरिक रूप से अभिप्रेरित था, इसलिए अंतिम विकल्प गलत है।"},
  {"id":"cdp-child-development-168","question":"Before a difficult problem-solving test, a teacher tells the class that this test will ‘decide your whole future’. Students who were confident in practice now make careless errors on the hardest questions. According to the Yerkes–Dodson principle:","options":["Higher anxiety always improves performance, so the errors must be due to lack of preparation","Performance does not depend on the level of arousal or anxiety at all","Arousal improves performance on complex tasks but harms performance on simple ones","Performance peaks at moderate arousal, and the peak is lower for complex tasks"],"answer":3,"explanation":"Performance rises with arousal up to an optimum and then falls; for difficult tasks the optimum is lower. The third option reverses the actual relationship.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक कठिन समस्या-समाधान परीक्षण से पहले एक शिक्षिका कक्षा से कहती है कि यह परीक्षा ‘तुम्हारा पूरा भविष्य तय करेगी’। जो विद्यार्थी अभ्यास में आत्मविश्वासी थे, वे अब सबसे कठिन प्रश्नों पर लापरवाही भरी गलतियाँ करते हैं। यर्क्स–डॉडसन सिद्धांत के अनुसार:","optionsHi":["अधिक चिंता हमेशा प्रदर्शन सुधारती है, इसलिए गलतियाँ तैयारी की कमी के कारण होंगी","प्रदर्शन उत्तेजन या चिंता के स्तर पर बिल्कुल निर्भर नहीं करता","उत्तेजन जटिल कार्यों पर प्रदर्शन सुधारता है पर सरल कार्यों पर बिगाड़ता है","प्रदर्शन मध्यम उत्तेजन पर चरम पर होता है, और जटिल कार्यों के लिए वह चरम निम्न होता है"],"explanationHi":"प्रदर्शन उत्तेजन के साथ एक अनुकूलतम बिंदु तक बढ़ता है और फिर गिरता है; कठिन कार्यों के लिए अनुकूलतम बिंदु नीचा होता है। तीसरा विकल्प वास्तविक संबंध को उलट देता है।"},
  {"id":"cdp-child-development-169","question":"Several children in a rural school come to school without breakfast and cannot concentrate in the first periods. In terms of Maslow’s hierarchy, the most logical first step is to:","options":["Meet their physiological needs first, for example through a morning snack","Offer prizes and praise to build up their self-esteem in class","Give them more interesting lessons so that they want to learn for its own sake","Hold parent meetings on the importance of regular study and education"],"answer":0,"explanation":"Maslow held that lower (deficiency) needs such as hunger must be met before higher needs such as esteem and self-actualisation can guide behaviour.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"ग्रामीण विद्यालय के कई बच्चे बिना नाश्ते के स्कूल आते हैं और पहले पीरियड में ध्यान केंद्रित नहीं कर पाते। मैस्लो के पदानुक्रम के संदर्भ में सबसे तर्कसंगत पहला कदम क्या है?","optionsHi":["पहले उनकी शारीरिक आवश्यकताएँ पूरी करना, जैसे सुबह का नाश्ता देकर","कक्षा में उनका आत्म-सम्मान बढ़ाने के लिए पुरस्कार और प्रशंसा देना","उन्हें अधिक रोचक पाठ देना ताकि वे सीखने के लिए स्वयं सीखना चाहें","नियमित अध्ययन और शिक्षा के महत्व पर अभिभावक बैठकें करना"],"explanationHi":"मैस्लो का मत था कि भूख जैसी निम्न (अभाव) आवश्यकताएँ पूरी होनी चाहिए, तभी सम्मान और आत्म-सिद्धि जैसी उच्च आवश्यकताएँ व्यवहार का मार्गदर्शन कर सकती हैं।"},
  {"id":"cdp-child-development-170","question":"Aman, aged 9, gives thoughtful oral answers in science discussions and does well in mental maths, but reads very slowly, guesses words from the first letter, and spells ‘was’ as ‘saw’ and ‘said’ as ‘sed’. The most likely explanation is:","options":["Intellectual disability, because his reading is far below the level for his age","Dyslexia: his difficulty is limited to decoding and spelling, not reasoning","Laziness, since he clearly answers well in class whenever he wants to","ADHD, since his reading errors show careless attention to the text"],"answer":1,"explanation":"Average or better reasoning with a specific, unexpected difficulty in decoding and spelling fits dyslexia; intellectual disability would affect reasoning broadly. Labelling him lazy is a damaging misconception.","difficulty":"hard","source":"CTET · State TETs","questionHi":"9 वर्ष का अमन विज्ञान चर्चाओं में विचारपूर्ण मौखिक उत्तर देता है और मानसिक गणित में अच्छा है, पर बहुत धीमा पढ़ता है, पहले अक्षर से शब्द का अनुमान लगाता है, और ‘was’ को ‘saw’ तथा ‘said’ को ‘sed’ लिखता है। सबसे संभावित स्पष्टीकरण क्या है?","optionsHi":["बौद्धिक अक्षमता, क्योंकि उसका पठन उसकी आयु के स्तर से बहुत नीचे है","डिस्लेक्सिया: उसकी कठिनाई केवल अक्षर-पहचान (डिकोडिंग) और वर्तनी तक सीमित है, तर्क तक नहीं","आलस्य, क्योंकि वह स्पष्ट रूप से कक्षा में जब चाहे अच्छा उत्तर देता है","ADHD, क्योंकि उसकी पठन त्रुटियाँ पाठ पर लापरवाह ध्यान दर्शाती हैं"],"explanationHi":"औसत या बेहतर तर्क के साथ डिकोडिंग और वर्तनी में विशिष्ट, अप्रत्याशित कठिनाई डिस्लेक्सिया से मेल खाती है; बौद्धिक अक्षमता तर्क को व्यापक रूप से प्रभावित करती। उसे आलसी कहना एक हानिकारक भ्रांति है।"},
  {"id":"cdp-child-development-171","question":"Which classroom strategy is most suitable for a child with ADHD?","options":["Giving long worksheets so that he slowly learns to sit still for longer periods","Seating him near the window so that he can relax and calm himself down","Short tasks with clear steps, brief movement breaks and a seat near the teacher","Ignoring all his work until he finishes a whole task without any help"],"answer":2,"explanation":"Children with ADHD benefit from structure, short tasks, frequent feedback and chances to move. A seat by the window adds distraction, and long tasks set them up to fail.","difficulty":"hard","source":"CTET · State TETs","questionHi":"ADHD वाले बच्चे के लिए कक्षा की कौन-सी रणनीति सबसे उपयुक्त है?","optionsHi":["लंबी कार्यपत्रिकाएँ देना ताकि वह धीरे-धीरे अधिक देर तक बैठना सीख जाए","उसे खिड़की के पास बैठाना ताकि वह आराम करे और स्वयं को शांत कर सके","स्पष्ट चरणों वाले छोटे कार्य, संक्षिप्त गति-विराम और शिक्षक के पास की सीट","जब तक वह पूरा कार्य बिना किसी मदद के पूरा न कर ले, उसके सारे काम की अनदेखी करना"],"explanationHi":"ADHD वाले बच्चों को संरचना, छोटे कार्य, बार-बार प्रतिपुष्टि और चलने-फिरने के अवसरों से लाभ होता है। खिड़की के पास की सीट ध्यान भटकाती है, और लंबे कार्य उन्हें विफल होने के लिए तैयार करते हैं।"},
  {"id":"cdp-child-development-172","question":"A Class 2 child becomes very upset when the timetable changes without notice, rarely makes eye contact, and talks at length only about trains. Which support is most appropriate in an inclusive class?","options":["Insisting that she make eye contact while talking, so that she learns social skills","Changing her seat often so that she gets used to change and becomes flexible","Avoiding her interest in trains, as it distracts her and the class from the lesson","Using a visual daily schedule, warning her of changes and using her interest in trains"],"answer":3,"explanation":"These traits suggest autism spectrum disorder. Predictable routines, visual supports and building on special interests reduce anxiety and aid learning; forced eye contact and sudden change raise distress.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 2 की एक बच्ची समय-सारणी बिना सूचना बदले जाने पर बहुत परेशान हो जाती है, शायद ही कभी नज़रें मिलाती है, और केवल रेलगाड़ियों के बारे में लंबी बातें करती है। समावेशी कक्षा में कौन-सा सहयोग सबसे उपयुक्त है?","optionsHi":["बात करते समय नज़रें मिलाने पर ज़ोर देना, ताकि वह सामाजिक कौशल सीखे","उसकी सीट बार-बार बदलना ताकि वह परिवर्तन की आदी होकर लचीली बने","रेलगाड़ियों में उसकी रुचि से बचना, क्योंकि यह उसे और कक्षा को पाठ से भटकाती है","दृश्य दैनिक कार्यक्रम का उपयोग करना, परिवर्तनों की पूर्व चेतावनी देना और रेलगाड़ियों में उसकी रुचि का उपयोग करना"],"explanationHi":"ये लक्षण ऑटिज़्म स्पेक्ट्रम विकार का संकेत देते हैं। पूर्वानुमेय दिनचर्या, दृश्य सहायता और विशेष रुचियों पर निर्माण चिंता घटाते हैं और सीखने में सहायता करते हैं; ज़बरदस्ती नज़रें मिलवाना और अचानक परिवर्तन परेशानी बढ़ाते हैं।"},
  {"id":"cdp-child-development-173","question":"Priya, a gifted Class 4 student, finishes class work early and is bored. Which of the following is an example of ENRICHMENT rather than acceleration?","options":["Promoting her straight to Class 5 so that she studies at a higher level","Giving her another worksheet of similar sums each time she finishes early","Asking her to explore an open-ended question on the topic in depth and present it","Letting her spend the extra time helping the teacher check other children’s notebooks"],"answer":2,"explanation":"Enrichment broadens and deepens learning at the same grade level through challenging, higher-order tasks. Grade skipping is acceleration, and more of the same is just busy work.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 4 की प्रतिभाशाली विद्यार्थी प्रिया कक्षा-कार्य जल्दी पूरा कर लेती है और ऊब जाती है। निम्नलिखित में से कौन-सा त्वरण के बजाय संवर्धन का उदाहरण है?","optionsHi":["उसे सीधे कक्षा 5 में पदोन्नत कर देना ताकि वह उच्च स्तर पर पढ़े","जब भी वह जल्दी पूरा कर ले, उसे उसी तरह के सवालों की एक और कार्यपत्रिका देना","उसे विषय पर किसी खुले प्रश्न को गहराई से खोजने और प्रस्तुत करने को कहना","उसे अतिरिक्त समय शिक्षक को अन्य बच्चों की कॉपियाँ जाँचने में मदद करने में बिताने देना"],"explanationHi":"संवर्धन चुनौतीपूर्ण, उच्च-स्तरीय कार्यों के माध्यम से उसी कक्षा-स्तर पर अधिगम को व्यापक और गहरा बनाता है। कक्षा छोड़ना त्वरण है, और उसी तरह का और काम केवल व्यस्त रखने वाला कार्य है।"},
  {"id":"cdp-child-development-174","question":"Children from a tribal community in a Class 1 classroom speak a language different from the school language and remain silent in class. Consistent with NEP 2020 and NCF 2005, the teacher should:","options":["Use their home language in class as a bridge while building the school language","Insist on the school language only, so that they pick it up faster by immersion","Seat them separately until they have learnt enough of the school language","Tell parents to speak only the school language at home from now on"],"answer":0,"explanation":"Both documents treat the home language as a resource; learning through it builds confidence and concepts, and supports the move to other languages. Banning it silences children.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 1 की कक्षा में एक जनजातीय समुदाय के बच्चे विद्यालय की भाषा से भिन्न भाषा बोलते हैं और कक्षा में चुप रहते हैं। NEP 2020 और NCF 2005 के अनुरूप शिक्षक को क्या करना चाहिए?","optionsHi":["विद्यालय की भाषा सिखाते हुए उनकी घर की भाषा को पुल के रूप में कक्षा में प्रयोग करना","केवल विद्यालय की भाषा पर ज़ोर देना, ताकि वे निमज्जन (immersion) से उसे जल्दी सीख लें","जब तक वे विद्यालय की भाषा पर्याप्त न सीख लें, उन्हें अलग बैठाना","अभिभावकों से कहना कि अब से घर पर केवल विद्यालय की भाषा बोलें"],"explanationHi":"दोनों दस्तावेज़ घर की भाषा को एक संसाधन मानते हैं; उसके माध्यम से सीखना आत्मविश्वास और अवधारणाएँ बनाता है, और अन्य भाषाओं की ओर बढ़ने में सहायक होता है। उसे प्रतिबंधित करना बच्चों को चुप करा देता है।"},
  {"id":"cdp-child-development-175","question":"Assertion (A): Piaget held that a child’s language reflects the concepts the child has already formed. Reason (R): For Piaget, cognitive development comes first and language develops on its basis.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Piaget saw language as dependent on thought: children use words for the concepts their cognitive structures allow. Vygotsky, by contrast, gave language a formative role in thought.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अभिकथन (A): पियाजे का मत था कि बच्चे की भाषा उन अवधारणाओं को प्रतिबिंबित करती है जो बच्चा पहले ही बना चुका है। कारण (R): पियाजे के लिए संज्ञानात्मक विकास पहले आता है और भाषा उसके आधार पर विकसित होती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"पियाजे भाषा को चिंतन पर निर्भर मानते थे: बच्चे उन अवधारणाओं के लिए शब्द प्रयोग करते हैं जिनकी अनुमति उनकी संज्ञानात्मक संरचनाएँ देती हैं। इसके विपरीत, वाइगोत्स्की ने भाषा को चिंतन में रचनात्मक भूमिका दी।"},
  {"id":"cdp-child-development-176","question":"In a science activity, students must hang a lamp using a ruler, string and tape. Most of them say there is ‘nothing to use as a support’, because they see the ruler only as something for measuring. Their difficulty is called:","options":["Insight","Transfer of learning","Functional fixedness","Proactive interference"],"answer":2,"explanation":"Functional fixedness (Duncker) is the tendency to see an object only in its usual function, which blocks creative problem solving.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक विज्ञान गतिविधि में विद्यार्थियों को एक फुटे (रूलर), डोरी और टेप की मदद से एक लैंप लटकाना है। उनमें से अधिकांश कहते हैं कि ‘सहारे के लिए कुछ भी उपयोग करने को नहीं है’, क्योंकि वे फुटे को केवल मापने की चीज़ के रूप में देखते हैं। उनकी इस कठिनाई को कहते हैं:","optionsHi":["अंतर्दृष्टि","अधिगम का अंतरण","प्रकार्यात्मक स्थिरता","अग्रोन्मुख व्यतिकरण"],"explanationHi":"प्रकार्यात्मक स्थिरता (डंकर) किसी वस्तु को केवल उसके सामान्य प्रकार्य में देखने की प्रवृत्ति है, जो सृजनात्मक समस्या समाधान को अवरुद्ध करती है।"},
  {"id":"cdp-child-development-177","question":"Before her exam, Neha lists the topics she does not yet understand, decides which to revise first, and after each session tests herself to see whether her plan is working. Neha is mainly using:","options":["Rote memorisation","Metacognition","Convergent thinking","Overlearning"],"answer":1,"explanation":"Planning, monitoring and evaluating one’s own learning is metacognition, a key aim of learner-centred teaching.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"परीक्षा से पहले नेहा उन विषयों की सूची बनाती है जो उसे अभी समझ नहीं आए, तय करती है कि पहले किन्हें दोहराना है, और हर सत्र के बाद स्वयं को परखती है कि उसकी योजना काम कर रही है या नहीं। नेहा मुख्यतः किसका उपयोग कर रही है?","optionsHi":["रटकर याद करना","अधिसंज्ञान (मेटाकॉग्निशन)","अभिसारी चिंतन","अतिअधिगम"],"explanationHi":"अपने सीखने की योजना बनाना, निगरानी करना और मूल्यांकन करना अधिसंज्ञान है, जो अधिगमकर्ता-केंद्रित शिक्षण का एक प्रमुख लक्ष्य है।"},
  {"id":"cdp-child-development-178","question":"A Class 6 child says, ‘Plants get their food from the soil, that is why we put manure.’ A teacher following constructivist principles would most likely:","options":["Mark the answer wrong and dictate the correct definition of photosynthesis","Ignore the answer because the child will learn the correct idea in higher classes","Tell the class that the child is wrong and ask another child for the right answer","Ask her to explain her reasoning, then let her test it by growing plants in light and dark"],"answer":3,"explanation":"Constructivism treats a misconception as the child’s present idea; it should be surfaced and challenged through experience so that the child reconstructs it, not merely overwritten by a definition.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 6 की एक बच्ची कहती है, ‘पौधों को अपना भोजन मिट्टी से मिलता है, इसीलिए हम खाद डालते हैं।’ रचनावादी सिद्धांतों का पालन करने वाला शिक्षक सबसे अधिक संभावना से क्या करेगा?","optionsHi":["उत्तर को गलत चिह्नित करेगा और प्रकाश-संश्लेषण की सही परिभाषा लिखवाएगा","उत्तर की अनदेखी करेगा क्योंकि बच्ची ऊँची कक्षाओं में सही विचार सीख लेगी","कक्षा को बताएगा कि बच्ची गलत है और सही उत्तर के लिए किसी दूसरे बच्चे से पूछेगा","उससे अपना तर्क समझाने को कहेगा, फिर उसे प्रकाश और अँधेरे में पौधे उगाकर उसे परखने देगा"],"explanationHi":"रचनावाद किसी भ्रांत धारणा को बच्चे का वर्तमान विचार मानता है; उसे सामने लाकर अनुभव के माध्यम से चुनौती दी जानी चाहिए ताकि बच्चा उसका पुनर्निर्माण करे, न कि केवल किसी परिभाषा से उसे मिटा दिया जाए।"},
  {"id":"cdp-child-development-179","question":"A teacher divides a lesson on the Indian monsoon into four parts. Each member of a home group studies one part with members of other groups who have the same part, then returns to teach it to the home group. Each student is tested on all four parts. This technique is:","options":["The jigsaw technique","Peer tutoring by an abler student","Programmed instruction","Brainstorming"],"answer":0,"explanation":"In Aronson’s jigsaw method each learner becomes an ‘expert’ on one piece, creating positive interdependence, since the group needs everyone’s part.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"एक शिक्षिका भारतीय मानसून के पाठ को चार भागों में बाँटती है। एक गृह-समूह का प्रत्येक सदस्य अन्य समूहों के उन सदस्यों के साथ एक भाग का अध्ययन करता है जिनके पास वही भाग है, फिर उसे गृह-समूह को पढ़ाने लौटता है। प्रत्येक विद्यार्थी का चारों भागों पर परीक्षण होता है। यह तकनीक है:","optionsHi":["जिगसॉ तकनीक","अधिक सक्षम विद्यार्थी द्वारा सहपाठी शिक्षण","अभिक्रमित अनुदेशन","मंथन (ब्रेनस्टॉर्मिंग)"],"explanationHi":"एरोनसन की जिगसॉ विधि में प्रत्येक अधिगमकर्ता एक टुकड़े का ‘विशेषज्ञ’ बन जाता है, जिससे सकारात्मक अन्योन्याश्रितता बनती है, क्योंकि समूह को सबके भाग की आवश्यकता होती है।"},
  {"id":"cdp-child-development-180","question":"How many of the following statements about Kohlberg’s theory are correct? I. The stages follow an invariant sequence, so a stage cannot be skipped. II. Every adult eventually reaches Stage 6. III. Advanced moral reasoning requires a matching level of cognitive development, though cognitive development alone does not ensure it. IV. A person’s stage is decided by the action chosen in a dilemma.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. Few people reach the post-conventional stages, and the stage is judged from the reasoning behind a choice, not the choice itself.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कोहलबर्ग के सिद्धांत के बारे में निम्नलिखित में से कितने कथन सही हैं? I. चरण एक अपरिवर्तनीय क्रम का अनुसरण करते हैं, इसलिए कोई चरण छोड़ा नहीं जा सकता। II. हर वयस्क अंततः चरण 6 तक पहुँचता है। III. उन्नत नैतिक चिंतन के लिए संज्ञानात्मक विकास का मेल खाता स्तर आवश्यक है, यद्यपि अकेला संज्ञानात्मक विकास उसे सुनिश्चित नहीं करता। IV. किसी व्यक्ति का चरण दुविधा में चुनी गई क्रिया से तय होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। कम लोग ही उत्तर-परंपरागत चरणों तक पहुँचते हैं, और चरण का निर्णय किसी चुनाव के पीछे के तर्क से होता है, स्वयं चुनाव से नहीं।"},
  {"id":"cdp-child-development-181","question":"To help Class 1 children understand that the amount of water does not change when it is poured into a differently shaped glass, which approach would Piaget most strongly favour?","options":["Telling them the rule clearly and asking them to memorise it for the test","Showing a chart that explains conservation with labelled pictures","Letting them pour water between different containers, predict, check and discuss","Rewarding children who give the correct answer until all of them say it"],"answer":2,"explanation":"Piaget saw children as active constructors of knowledge through action on materials; teaching a verbal rule or rewarding the answer gives a parroted response without the underlying operation.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 1 के बच्चों को यह समझाने के लिए कि पानी को अलग आकार के गिलास में डालने पर उसकी मात्रा नहीं बदलती, पियाजे किस उपागम का सबसे अधिक समर्थन करते?","optionsHi":["उन्हें नियम स्पष्ट बताना और परीक्षा के लिए उसे याद करने को कहना","लेबल लगे चित्रों के साथ संरक्षण समझाने वाला चार्ट दिखाना","उन्हें अलग-अलग बर्तनों के बीच पानी उँडेलने, अनुमान लगाने, जाँचने और चर्चा करने देना","जब तक सभी बच्चे सही उत्तर न बोलने लगें, तब तक सही उत्तर देने वाले बच्चों को पुरस्कृत करना"],"explanationHi":"पियाजे बच्चों को सामग्री पर क्रिया द्वारा ज्ञान का सक्रिय निर्माता मानते थे; शाब्दिक नियम सिखाना या उत्तर पर पुरस्कार देना अंतर्निहित संक्रिया के बिना रटा हुआ उत्तर देता है।"},
  {"id":"cdp-child-development-182","question":"Tanu began walking at 10 months and her cousin at 15 months; both are healthy and now walk equally well. Both crawled before they walked. Which principle of development do these facts illustrate together?","options":["Development is unpredictable in both its sequence and its rate","Development proceeds from specific responses to general ones","Later development depends entirely on early development","The sequence of development is similar for all, but the rate varies"],"answer":3,"explanation":"Both crawled before walking (same sequence) but at different ages (different rate), the principle of individual differences within a common pattern.","difficulty":"hard","source":"CTET · State TETs","questionHi":"तनु ने 10 माह में चलना शुरू किया और उसके चचेरे भाई ने 15 माह में; दोनों स्वस्थ हैं और अब समान रूप से अच्छा चलते हैं। दोनों चलने से पहले रेंगे थे। ये तथ्य मिलकर विकास के किस सिद्धांत को दर्शाते हैं?","optionsHi":["विकास अपने क्रम और दर, दोनों में अप्रत्याशित होता है","विकास विशिष्ट अनुक्रियाओं से सामान्य अनुक्रियाओं की ओर होता है","बाद का विकास पूरी तरह प्रारंभिक विकास पर निर्भर करता है","विकास का क्रम सबके लिए समान होता है, पर दर भिन्न होती है"],"explanationHi":"दोनों चलने से पहले रेंगे (समान क्रम) पर अलग-अलग आयु में (भिन्न दर), यानी साझा प्रतिरूप के भीतर वैयक्तिक भिन्नता का सिद्धांत।"},
  {"id":"cdp-child-development-183","question":"NEP 2020 gives high priority to Early Childhood Care and Education. Its stated reason is that:","options":["Children must learn to read and write fluently before the age of three","Over 85% of cumulative brain development occurs before age six","Formal written examinations should begin at the pre-school stage","Children below six cannot learn through play and need formal lessons"],"answer":1,"explanation":"NEP 2020 notes that over 85% of cumulative brain development happens before age 6, so play-based, activity-based early learning is critical. It does not call for early formal reading or exams.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"NEP 2020 प्रारंभिक बाल्यावस्था देखभाल एवं शिक्षा (ECCE) को उच्च प्राथमिकता देती है। इसका बताया गया कारण यह है कि:","optionsHi":["बच्चों को तीन वर्ष की आयु से पहले धाराप्रवाह पढ़ना-लिखना सीख लेना चाहिए","संचयी मस्तिष्क विकास का 85% से अधिक छह वर्ष की आयु से पहले होता है","औपचारिक लिखित परीक्षाएँ प्री-स्कूल चरण में शुरू होनी चाहिए","छह वर्ष से कम उम्र के बच्चे खेल से नहीं सीख सकते और उन्हें औपचारिक पाठ चाहिए"],"explanationHi":"NEP 2020 नोट करती है कि संचयी मस्तिष्क विकास का 85% से अधिक 6 वर्ष की आयु से पहले होता है, इसलिए खेल-आधारित, गतिविधि-आधारित प्रारंभिक अधिगम महत्वपूर्ण है। वह प्रारंभिक औपचारिक पठन या परीक्षाओं की माँग नहीं करती।"},
  {"id":"cdp-child-development-184","question":"A teacher asks children to find out how much water their family uses in a day and to suggest ways of saving it, then uses their data in class. Which NCF 2005 guiding principle does this best reflect?","options":["Making examinations more flexible and integrated with classroom life","Enriching the curriculum so that it goes beyond textbooks","Connecting knowledge to life outside the school","Nurturing an overriding identity informed by caring concerns within the democratic polity"],"answer":2,"explanation":"Using children’s home experience as the basis of learning connects school knowledge with life outside school, the first of NCF 2005’s guiding principles.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षिका बच्चों से यह पता लगाने को कहती है कि उनका परिवार दिन में कितना पानी उपयोग करता है और उसे बचाने के तरीके सुझाने को कहती है, फिर कक्षा में उनके आँकड़ों का उपयोग करती है। यह NCF 2005 के किस मार्गदर्शक सिद्धांत को सबसे अच्छी तरह दर्शाता है?","optionsHi":["परीक्षाओं को अधिक लचीला और कक्षा-जीवन से एकीकृत बनाना","पाठ्यचर्या को समृद्ध बनाना ताकि वह पाठ्यपुस्तकों से आगे जाए","ज्ञान को विद्यालय के बाहर के जीवन से जोड़ना","लोकतांत्रिक राजव्यवस्था के भीतर परवाह भरी चिंताओं से प्रेरित एक सर्वोपरि पहचान का पोषण करना"],"explanationHi":"बच्चों के घर के अनुभव को अधिगम का आधार बनाना विद्यालयी ज्ञान को विद्यालय के बाहर के जीवन से जोड़ता है, जो NCF 2005 के मार्गदर्शक सिद्धांतों में पहला है।"},
  {"id":"cdp-child-development-185","question":"Which piece of written feedback on a student’s essay is most effective for formative purposes?","options":["‘7/10. A good effort overall, though some parts need more work.’","‘Excellent work! Keep it up and you will surely get full marks.’","‘Your work is better than most of the class, so you should feel very proud.’","‘In paragraph 3, give an example to support your claim about pollution.’"],"answer":3,"explanation":"Effective formative feedback is specific, focuses on the task, and tells the learner how to close the gap. Marks, vague praise and comparisons with others give no direction for improvement.","difficulty":"hard","source":"CTET · State TETs","questionHi":"किसी विद्यार्थी के निबंध पर लिखित प्रतिपुष्टि का कौन-सा रूप रचनात्मक उद्देश्य के लिए सबसे प्रभावी है?","optionsHi":["‘7/10. कुल मिलाकर अच्छा प्रयास, हालाँकि कुछ भागों पर और काम चाहिए।’","‘उत्कृष्ट कार्य! ऐसे ही करते रहो और तुम्हें निश्चित रूप से पूरे अंक मिलेंगे।’","‘तुम्हारा काम कक्षा के अधिकांश बच्चों से बेहतर है, इसलिए तुम्हें बहुत गर्व होना चाहिए।’","‘अनुच्छेद 3 में, प्रदूषण के बारे में अपने दावे के समर्थन में एक उदाहरण दो।’"],"explanationHi":"प्रभावी रचनात्मक प्रतिपुष्टि विशिष्ट होती है, कार्य पर केंद्रित होती है, और अधिगमकर्ता को बताती है कि अंतर को कैसे पाटे। अंक, अस्पष्ट प्रशंसा और दूसरों से तुलना सुधार की कोई दिशा नहीं देते।"},
  {"id":"cdp-child-development-186","question":"The holistic progress card proposed in NEP 2020 is best described as:","options":["A report card showing only the marks scored in the board-subject tests each term","A 360-degree report with self, peer and teacher assessment across all domains","A record of the child’s progress kept only by the parents at home","A rank list comparing every child’s marks with the class average"],"answer":1,"explanation":"NEP 2020 proposes a 360-degree progress card covering all domains, with inputs from the child, peers and teacher, to show each learner’s progress and uniqueness.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"NEP 2020 में प्रस्तावित समग्र प्रगति पत्र का सबसे अच्छा वर्णन है:","optionsHi":["एक रिपोर्ट कार्ड जो प्रत्येक सत्र में बोर्ड-विषयों के परीक्षणों में केवल प्राप्त अंक दिखाता है","स्व-, सहपाठी और शिक्षक आकलन सहित सभी क्षेत्रों में 360-डिग्री रिपोर्ट","बच्चे की प्रगति का ऐसा अभिलेख जो केवल माता-पिता घर पर रखते हैं","हर बच्चे के अंकों की कक्षा के औसत से तुलना करने वाली रैंक सूची"],"explanationHi":"NEP 2020 सभी क्षेत्रों को समेटने वाले 360-डिग्री प्रगति पत्र का प्रस्ताव करती है, जिसमें बच्चे, सहपाठियों और शिक्षक के इनपुट हों, ताकि हर अधिगमकर्ता की प्रगति और विशिष्टता दिखे।"},
  {"id":"cdp-child-development-187","question":"In a subtraction test, 14 of 35 students write 82 − 46 = 44, and make similar errors in other sums that need regrouping. What should the teacher do first?","options":["Reteach the whole chapter to the entire class from the very beginning","Give these students more subtraction worksheets of the same type for practice","Treat the result as a careless mistake and move on to the next chapter","Analyse the shared error to diagnose the misconception, then plan remedial teaching"],"answer":3,"explanation":"A shared error pattern points to a shared misconception (here, subtracting the smaller digit from the larger in each column); diagnosis comes before remediation. 82 − 46 = 36, but taking 6 − 2 = 4 in the ones column and 8 − 4 = 4 in the tens gives 44.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"एक घटाव परीक्षण में 14 विद्यार्थी (कुल 35 में से) 82 − 46 = 44 लिखते हैं, और हासिल (regrouping) वाले अन्य सवालों में भी इसी तरह की गलतियाँ करते हैं। शिक्षक को सबसे पहले क्या करना चाहिए?","optionsHi":["पूरी कक्षा को पूरा अध्याय बिल्कुल शुरू से दोबारा पढ़ाना","इन विद्यार्थियों को अभ्यास के लिए उसी प्रकार की और घटाव कार्यपत्रिकाएँ देना","परिणाम को लापरवाही की गलती मानकर अगले अध्याय पर बढ़ जाना","साझा त्रुटि का विश्लेषण कर भ्रांत धारणा का निदान करना, फिर उपचारात्मक शिक्षण की योजना बनाना"],"explanationHi":"साझा त्रुटि का पैटर्न साझा भ्रांत धारणा की ओर संकेत करता है (यहाँ, हर स्तंभ में छोटे अंक को बड़े अंक से घटाना); उपचार से पहले निदान आता है। 82 − 46 = 36, पर इकाई स्तंभ में 6 − 2 = 4 और दहाई में 8 − 4 = 4 लेने से 44 आता है।"},
  {"id":"cdp-child-development-188","question":"Insulted by a classmate, Kavya notices her anger rising, takes a few deep breaths, and replies calmly. In Daniel Goleman’s model of emotional intelligence, she is mainly showing:","options":["Empathy","Social skills","Self-regulation","Self-motivation"],"answer":2,"explanation":"Recognising an emotion is self-awareness; controlling how one acts on it is self-regulation. Empathy concerns others’ feelings.","difficulty":"hard","source":"CTET · State TETs","questionHi":"किसी सहपाठी द्वारा अपमानित किए जाने पर काव्या अपने भीतर गुस्सा बढ़ता महसूस करती है, कुछ गहरी साँसें लेती है, और शांति से उत्तर देती है। डैनियल गोलमैन के भावनात्मक बुद्धि मॉडल में वह मुख्यतः क्या दर्शा रही है?","optionsHi":["समानुभूति","सामाजिक कौशल","आत्म-नियमन","आत्म-अभिप्रेरणा"],"explanationHi":"किसी भावना को पहचानना आत्म-जागरूकता है; उस पर कैसे कार्य करना है इसे नियंत्रित करना आत्म-नियमन है। समानुभूति दूसरों की भावनाओं से संबंधित है।"},
  {"id":"cdp-child-development-189","question":"In Mary Ainsworth’s ‘strange situation’, a toddler shows little distress when the mother leaves and, when she returns, looks away and does not seek contact. This pattern is classified as:","options":["Insecure-avoidant attachment","Secure attachment","Insecure-resistant (ambivalent) attachment","Stranger anxiety, a normal sign of secure attachment"],"answer":0,"explanation":"A securely attached child is upset at separation and is comforted on reunion; ignoring or avoiding the mother on return marks the avoidant pattern.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"मैरी एन्सवर्थ की ‘स्ट्रेंज सिचुएशन’ में एक छोटा बच्चा माँ के जाने पर बहुत कम परेशानी दिखाता है और, जब वह लौटती है, तो दूसरी ओर देखता है तथा संपर्क नहीं चाहता। इस प्रतिरूप को वर्गीकृत किया जाता है:","optionsHi":["असुरक्षित-परिहारी लगाव","सुरक्षित लगाव","असुरक्षित-प्रतिरोधी (द्विपक्षी) लगाव","अजनबी-चिंता, जो सुरक्षित लगाव का एक सामान्य संकेत है"],"explanationHi":"सुरक्षित रूप से जुड़ा बच्चा बिछड़ने पर परेशान होता है और मिलने पर शांत हो जाता है; लौटने पर माँ की उपेक्षा करना या उससे बचना परिहारी प्रतिरूप की पहचान है।"},
  {"id":"cdp-child-development-190","question":"Parents give their child whatever he asks for, rarely set rules or limits, and are very warm and affectionate. In Baumrind’s classification this is the:","options":["Authoritarian style","Authoritative style","Permissive (indulgent) style","Uninvolved (neglectful) style"],"answer":2,"explanation":"High warmth with low demands and control is permissive. Authoritative parents are warm but also set and explain limits; neglectful parents are low on both.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"माता-पिता अपने बच्चे को वह सब देते हैं जो वह माँगता है, शायद ही कभी नियम या सीमाएँ तय करते हैं, और बहुत स्नेहशील हैं। बॉमरिंड के वर्गीकरण में यह है:","optionsHi":["सत्तावादी शैली","प्राधिकारिक शैली","उदार (लाड़-प्यार वाली) शैली","अनासक्त (उपेक्षापूर्ण) शैली"],"explanationHi":"उच्च स्नेह के साथ कम अपेक्षाएँ और नियंत्रण उदार शैली है। प्राधिकारिक माता-पिता स्नेही होते हैं पर सीमाएँ भी तय करते और समझाते हैं; उपेक्षापूर्ण माता-पिता दोनों में कम होते हैं।"},
  {"id":"cdp-child-development-191","question":"A three-year-old who has not had her afternoon nap insists, ‘It isn’t afternoon, because I haven’t had my nap.’ According to Piaget, this is an example of:","options":["Deductive reasoning","Inductive reasoning","Hypothetico-deductive reasoning","Transductive reasoning"],"answer":3,"explanation":"Transductive reasoning links one particular to another as if one caused the other (nap → afternoon), instead of reasoning from general to particular or particular to general.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"तीन वर्ष की एक बच्ची, जिसने अपनी दोपहर की झपकी नहीं ली है, अड़कर कहती है, ‘अभी दोपहर नहीं हुई, क्योंकि मैंने झपकी नहीं ली।’ पियाजे के अनुसार यह किसका उदाहरण है?","optionsHi":["निगमनात्मक तर्क","आगमनात्मक तर्क","परिकल्पनात्मक-निगमनात्मक तर्क","अनुप्रेरक (ट्रांसडक्टिव) तर्क"],"explanationHi":"अनुप्रेरक तर्क एक विशिष्ट बात को दूसरी विशिष्ट बात से ऐसे जोड़ता है मानो एक दूसरे का कारण हो (झपकी → दोपहर), बजाय सामान्य से विशिष्ट या विशिष्ट से सामान्य की ओर तर्क करने के।"},
  {"id":"cdp-child-development-192","question":"Which statement correctly contrasts Piaget and Vygotsky on the relation between learning and development?","options":["Piaget held that learning leads development; Vygotsky held that development must come first","Piaget: development sets limits for learning; Vygotsky: instruction runs ahead and leads it","Both held that development is entirely due to biological maturation, not learning","Both held that social interaction plays no real part in children’s cognitive growth"],"answer":1,"explanation":"For Piaget, what a child can learn depends on stage; for Vygotsky, instruction within the ZPD awakens functions that are maturing, so learning drives development.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अधिगम और विकास के संबंध पर पियाजे और वाइगोत्स्की की तुलना करने वाला कौन-सा कथन सही है?","optionsHi":["पियाजे का मत था कि अधिगम विकास को आगे ले जाता है; वाइगोत्स्की का मत था कि विकास पहले आना चाहिए","पियाजे: विकास अधिगम की सीमाएँ तय करता है; वाइगोत्स्की: शिक्षण आगे चलता है और उसे नेतृत्व देता है","दोनों का मत था कि विकास पूरी तरह जैविक परिपक्वता के कारण होता है, अधिगम के कारण नहीं","दोनों का मत था कि बच्चों की संज्ञानात्मक वृद्धि में सामाजिक अंतःक्रिया की कोई वास्तविक भूमिका नहीं है"],"explanationHi":"पियाजे के लिए बच्चा क्या सीख सकता है यह अवस्था पर निर्भर करता है; वाइगोत्स्की के लिए ZPD के भीतर शिक्षण उन प्रकार्यों को जगाता है जो परिपक्व हो रहे हैं, इसलिए अधिगम विकास को आगे बढ़ाता है।"},
  {"id":"cdp-child-development-193","question":"A teacher keeps a running record of how each child participates in group work, notes the strategies children use, and adjusts the next day’s lesson accordingly. Which statement about this practice is correct?","options":["It is formative assessment, because it is used to adapt ongoing teaching","It is summative assessment, because it records children’s performance","It is not assessment at all, because no marks or grades are given","It is norm-referenced assessment, because children are being compared"],"answer":0,"explanation":"Assessment is formative when its evidence is used to shape ongoing teaching and learning; marks are not needed, and the purpose, not the format, decides the type.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षिका समूह कार्य में हर बच्चे की भागीदारी का सतत अभिलेख रखती है, बच्चों द्वारा प्रयुक्त युक्तियाँ नोट करती है, और उसी के अनुसार अगले दिन के पाठ को समायोजित करती है। इस अभ्यास के बारे में कौन-सा कथन सही है?","optionsHi":["यह रचनात्मक आकलन है, क्योंकि इसका उपयोग चल रहे शिक्षण को अनुकूलित करने में होता है","यह योगात्मक आकलन है, क्योंकि यह बच्चों के प्रदर्शन को दर्ज करता है","यह आकलन है ही नहीं, क्योंकि कोई अंक या ग्रेड नहीं दिया जा रहा","यह मानक-संदर्भित आकलन है, क्योंकि बच्चों की तुलना की जा रही है"],"explanationHi":"आकलन तब रचनात्मक होता है जब उसके साक्ष्य का उपयोग चल रहे शिक्षण और अधिगम को आकार देने में होता है; अंकों की आवश्यकता नहीं है, और प्रकार का निर्णय रूप से नहीं, उद्देश्य से होता है।"},
  {"id":"cdp-child-development-194","question":"A teacher makes a restless Class 1 child copy the same row of letters again and again just before lunch, although the child’s hand is tired and he is not interested. The child becomes irritated and starts scribbling. Which of Thorndike’s laws best explains his reaction?","options":["Law of exercise","Law of effect","Law of readiness","Law of belongingness"],"answer":2,"explanation":"By the law of readiness, being forced to act when not ready is annoying. More drill (exercise) without readiness produces frustration, not learning.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षक कक्षा 1 के एक बेचैन बच्चे से लंच से ठीक पहले अक्षरों की एक ही पंक्ति बार-बार लिखवाता है, जबकि बच्चे का हाथ थक चुका है और उसकी रुचि नहीं है। बच्चा चिढ़ जाता है और आड़ी-तिरछी लकीरें खींचने लगता है। थॉर्नडाइक का कौन-सा नियम उसकी प्रतिक्रिया को सबसे अच्छी तरह समझाता है?","optionsHi":["अभ्यास का नियम","प्रभाव का नियम","तत्परता का नियम","संबद्धता का नियम"],"explanationHi":"तत्परता के नियम के अनुसार, तैयार न होने पर कार्य करने के लिए बाध्य किया जाना खीझ पैदा करता है। तत्परता के बिना और अभ्यास (पुनरावृत्ति) निराशा पैदा करता है, अधिगम नहीं।"},
  {"id":"cdp-child-development-195","question":"Before a unit on the solar system, a teacher begins with a short overview: ‘Just as children in a ring game move around the person in the centre, planets move around the sun, each on its own path.’ According to David Ausubel, this introduction serves as:","options":["An advance organiser linking new material to what learners know","A discovery task in which learners find the principle on their own","Negative reinforcement for attentive behaviour","A summative check of prior knowledge"],"answer":0,"explanation":"Ausubel’s advance organiser is a broad, introductory frame that anchors new information to existing cognitive structure, making it meaningful rather than rote.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"सौरमंडल की इकाई से पहले एक शिक्षिका एक संक्षिप्त अवलोकन से शुरुआत करती है: ‘जैसे घेरे वाले खेल में बच्चे बीच वाले व्यक्ति के चारों ओर घूमते हैं, वैसे ही ग्रह सूर्य के चारों ओर घूमते हैं, प्रत्येक अपने पथ पर।’ डेविड ऑसुबेल के अनुसार यह परिचय किस रूप में कार्य करता है?","optionsHi":["अग्रिम संगठक जो नई सामग्री को अधिगमकर्ताओं के ज्ञान से जोड़ता है","अन्वेषण कार्य जिसमें अधिगमकर्ता स्वयं सिद्धांत खोजते हैं","ध्यानपूर्ण व्यवहार के लिए ऋणात्मक पुनर्बलन","पूर्व ज्ञान की योगात्मक जाँच"],"explanationHi":"ऑसुबेल का अग्रिम संगठक एक व्यापक, परिचयात्मक ढाँचा है जो नई सूचना को मौजूदा संज्ञानात्मक संरचना से जोड़ता है, जिससे वह रटी हुई नहीं बल्कि सार्थक बनती है।"},
  {"id":"cdp-child-development-196","question":"To teach the concept ‘mammal’, a teacher includes a bat and a whale among her examples, and a penguin and a crocodile as non-examples. The main reason for choosing these is to:","options":["Make the lesson longer and more interesting with some unusual animals","Test whether children have memorised the names of many different animals","Avoid any discussion of the common animals that children already know","Make the defining features clear, so children neither over- nor undergeneralise"],"answer":3,"explanation":"Unusual examples and close non-examples force attention to the defining features (e.g. hair, feeding young on milk) rather than surface features such as habitat or flight, so children neither overgeneralise (‘all flying things are birds’) nor undergeneralise (‘animals in water cannot be mammals’).","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"‘स्तनधारी’ की अवधारणा सिखाने के लिए एक शिक्षिका अपने उदाहरणों में चमगादड़ और व्हेल तथा गैर-उदाहरणों में पेंगुइन और मगरमच्छ को शामिल करती है। इन्हें चुनने का मुख्य कारण है:","optionsHi":["कुछ असामान्य जानवरों के साथ पाठ को लंबा और अधिक रोचक बनाना","यह परखना कि बच्चों ने अनेक भिन्न जानवरों के नाम रट लिए हैं या नहीं","उन सामान्य जानवरों की चर्चा से बचना जिन्हें बच्चे पहले से जानते हैं","परिभाषित करने वाली विशेषताओं को स्पष्ट करना, ताकि बच्चे न अतिसामान्यीकरण करें न अल्पसामान्यीकरण"],"explanationHi":"असामान्य उदाहरण और निकट के गैर-उदाहरण ध्यान को परिभाषित करने वाली विशेषताओं (जैसे बाल, बच्चों को दूध पिलाना) की ओर खींचते हैं, न कि आवास या उड़ने जैसी सतही विशेषताओं की ओर, ताकि बच्चे न अतिसामान्यीकरण करें (‘उड़ने वाली सब चीजें पक्षी हैं’) न अल्पसामान्यीकरण (‘पानी में रहने वाले जानवर स्तनधारी नहीं हो सकते’)।"},
  {"id":"cdp-child-development-197","question":"A teacher reads out a list of 15 new words once. When children are asked to recall them, most remember the first few and the last few, but forget those in the middle. This is the:","options":["Zeigarnik effect","Serial position effect","Law of exercise","Distributed practice effect"],"answer":1,"explanation":"Recall is better for early items (primacy, more rehearsal) and late items (recency, still in short-term memory) than for middle items.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षिका 15 नए शब्दों की सूची एक बार पढ़कर सुनाती है। जब बच्चों से उन्हें याद करने को कहा जाता है, तो अधिकांश को शुरुआत के कुछ और अंत के कुछ शब्द याद रहते हैं, पर बीच वाले भूल जाते हैं। यह है:","optionsHi":["ज़ाइगार्निक प्रभाव","क्रमिक स्थिति प्रभाव","अभ्यास का नियम","वितरित अभ्यास प्रभाव"],"explanationHi":"प्रारंभिक मदों (प्राथमिकता, अधिक पुनरावृत्ति) और अंतिम मदों (नवीनता, अब भी अल्पकालिक स्मृति में) का पुनःस्मरण बीच की मदों से बेहतर होता है।"},
  {"id":"cdp-child-development-198","question":"Two groups spend three hours in total revising the same chapter. Group A revises for three hours on the night before the test; Group B revises for 30 minutes on each of six days. A week after the test, Group B remembers much more. This supports the principle that:","options":["Massed practice is better for long-term retention than spaced practice","Total study time alone decides how much is remembered, not its spacing","Spaced practice gives better long-term retention than massed practice","Forgetting does not happen if the material studied is meaningful"],"answer":2,"explanation":"Spacing the same amount of practice over time strengthens retention, the spacing effect first shown by Ebbinghaus. Cramming may help briefly but is forgotten faster.","difficulty":"hard","source":"CTET · State TETs","questionHi":"दो समूह एक ही अध्याय को दोहराने में कुल तीन घंटे लगाते हैं। समूह A परीक्षा से पहले की रात तीन घंटे दोहराता है; समूह B छह दिनों में प्रत्येक दिन 30 मिनट दोहराता है। परीक्षा के एक सप्ताह बाद समूह B को बहुत अधिक याद रहता है। यह किस सिद्धांत का समर्थन करता है?","optionsHi":["दीर्घकालिक धारण के लिए संहत अभ्यास वितरित अभ्यास से बेहतर है","केवल कुल अध्ययन समय ही तय करता है कि कितना याद रहेगा, उसका अंतराल नहीं","वितरित अभ्यास संहत अभ्यास की तुलना में बेहतर दीर्घकालिक धारण देता है","यदि पढ़ी गई सामग्री सार्थक हो तो विस्मरण होता ही नहीं"],"explanationHi":"उतने ही अभ्यास को समय में फैलाने से धारण मजबूत होता है, यह अंतराल प्रभाव एबिंगहॉस ने पहली बार दिखाया था। रटाई थोड़े समय के लिए मदद कर सकती है पर जल्दी भुला दी जाती है।"},
  {"id":"cdp-child-development-199","question":"After learning a new set of spellings in English this week, Meena finds she can no longer recall some spellings she learnt last month. This is an example of:","options":["Proactive interference","Positive transfer","Repression (motivated forgetting)","Retroactive interference"],"answer":3,"explanation":"Retroactive interference is when new learning disrupts the recall of older learning. Proactive interference works the other way, with old learning disrupting new.","difficulty":"hard","source":"CTET · State TETs","questionHi":"इस सप्ताह अंग्रेजी की वर्तनियों का एक नया समूह सीखने के बाद मीना पाती है कि पिछले महीने सीखी कुछ वर्तनियाँ अब उसे याद नहीं आतीं। यह किसका उदाहरण है?","optionsHi":["अग्रोन्मुख व्यतिकरण","धनात्मक अंतरण","दमन (अभिप्रेरित विस्मरण)","पश्चोन्मुख व्यतिकरण"],"explanationHi":"पश्चोन्मुख व्यतिकरण तब होता है जब नया अधिगम पुराने अधिगम के पुनःस्मरण में बाधा डालता है। अग्रोन्मुख व्यतिकरण इसके उलट काम करता है, जिसमें पुराना अधिगम नए में बाधा डालता है।"},
  {"id":"cdp-child-development-200","question":"Asked why he did not copy in the test, a Class 6 student says, ‘My teacher trusts me, and she would be so disappointed; I want her to think I am a good student.’ This reasoning belongs to Kohlberg’s:","options":["Pre-conventional level, Stage 2","Conventional level, Stage 3","Conventional level, Stage 4","Post-conventional level, Stage 5"],"answer":1,"explanation":"Seeking approval and wanting to be seen as ‘good’ by significant others marks Stage 3. Stage 4 would appeal to rules and order, Stage 2 to personal gain.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"यह पूछे जाने पर कि उसने परीक्षा में नकल क्यों नहीं की, कक्षा 6 का एक विद्यार्थी कहता है, ‘मेरी शिक्षिका मुझ पर भरोसा करती हैं, और उन्हें बहुत निराशा होगी; मैं चाहता हूँ कि वे मुझे अच्छा विद्यार्थी समझें।’ यह तर्क कोहलबर्ग के किस स्तर का है?","optionsHi":["पूर्व-परंपरागत स्तर, चरण 2","परंपरागत स्तर, चरण 3","परंपरागत स्तर, चरण 4","उत्तर-परंपरागत स्तर, चरण 5"],"explanationHi":"स्वीकृति चाहना और महत्वपूर्ण लोगों की नज़र में ‘अच्छा’ दिखना चाहना चरण 3 की पहचान है। चरण 4 नियमों और व्यवस्था की बात करता, चरण 2 व्यक्तिगत लाभ की।"},
  {"id":"cdp-child-development-201","question":"Piaget told children two stories: John accidentally broke 15 cups while opening a door; Henry broke one cup while trying to steal jam. A six-year-old says John is naughtier. This shows:","options":["Heteronomous morality: judging by damage rather than intention","Autonomous morality, in which the child carefully weighs intentions","Kohlberg’s Stage 4 reasoning about upholding law and order","Post-conventional reasoning based on universal ethical principles"],"answer":0,"explanation":"Young children in Piaget’s heteronomous stage (moral realism) judge by visible consequences; older children in the autonomous stage judge by intention and would call Henry naughtier.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"पियाजे ने बच्चों को दो कहानियाँ सुनाईं: जॉन ने दरवाज़ा खोलते समय अनजाने में 15 कप तोड़ दिए; हेनरी ने जैम चुराने की कोशिश में एक कप तोड़ा। छह वर्ष का एक बच्चा कहता है कि जॉन अधिक शरारती है। यह दर्शाता है:","optionsHi":["परतंत्र नैतिकता: मंशा की बजाय नुकसान से निर्णय करना","स्वायत्त नैतिकता, जिसमें बच्चा मंशाओं को ध्यान से तौलता है","कोहलबर्ग का चरण 4 तर्क, कानून और व्यवस्था बनाए रखने के बारे में","सार्वभौमिक नैतिक सिद्धांतों पर आधारित उत्तर-परंपरागत तर्क"],"explanationHi":"पियाजे की परतंत्र अवस्था (नैतिक यथार्थवाद) में छोटे बच्चे दृश्य परिणामों से निर्णय करते हैं; स्वायत्त अवस्था के बड़े बच्चे मंशा से निर्णय करते हैं और हेनरी को अधिक शरारती कहेंगे।"},
  {"id":"cdp-child-development-202","question":"A five-year-old keeps planning ‘shop’ and ‘doctor’ games and organising other children, but the teacher repeatedly calls her bossy and stops her games. According to Erikson, the child is at risk of developing a sense of:","options":["Shame and doubt","Inferiority","Guilt","Mistrust"],"answer":2,"explanation":"In the preschool years (initiative vs guilt) children take initiative in planning and leading play; repeated criticism of such initiative can produce guilt. Inferiority belongs to the school-age stage.","difficulty":"hard","source":"CTET · State TETs","questionHi":"पाँच वर्ष की एक बच्ची लगातार ‘दुकान’ और ‘डॉक्टर’ के खेलों की योजना बनाती है और अन्य बच्चों को संगठित करती है, पर शिक्षिका बार-बार उसे रोबीली कहकर उसके खेल रोक देती हैं। एरिक्सन के अनुसार बच्ची में किस भावना के विकसित होने का जोखिम है?","optionsHi":["शर्म और संदेह","हीनता","अपराधबोध","अविश्वास"],"explanationHi":"प्री-स्कूल वर्षों (पहल बनाम अपराधबोध) में बच्चे खेल की योजना बनाने और उसका नेतृत्व करने में पहल करते हैं; ऐसी पहल की बार-बार आलोचना अपराधबोध पैदा कर सकती है। हीनता विद्यालय-आयु की अवस्था की है।"},
  {"id":"cdp-child-development-203","question":"A student keeps a reflective diary, knows her own strengths and weaknesses well, and sets realistic personal goals. In Gardner’s theory she shows high:","options":["Interpersonal intelligence","Existential intelligence","Linguistic intelligence","Intrapersonal intelligence"],"answer":3,"explanation":"Intrapersonal intelligence is understanding oneself, one’s feelings and motives. Interpersonal intelligence concerns understanding other people.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"एक विद्यार्थी चिंतनशील डायरी रखती है, अपनी शक्तियों और कमज़ोरियों को अच्छी तरह जानती है, और यथार्थवादी व्यक्तिगत लक्ष्य तय करती है। गार्डनर के सिद्धांत में वह किसके उच्च स्तर को दर्शाती है?","optionsHi":["अंतर्वैयक्तिक बुद्धि","अस्तित्वपरक बुद्धि","भाषायी बुद्धि","अंतःव्यक्तिक बुद्धि"],"explanationHi":"अंतःव्यक्तिक बुद्धि स्वयं को, अपनी भावनाओं और मंशाओं को समझना है। अंतर्वैयक्तिक बुद्धि दूसरे लोगों को समझने से संबंधित है।"},
  {"id":"cdp-child-development-204","question":"Asked for unusual uses of a brick, Rahul lists 20 uses, but every one is a kind of building or support (wall, step, doorstop, pillar…). Sana lists 8 uses that include a paperweight, a weapon, a weight for exercise and crushed red powder for colour. Which statement is correct?","options":["Rahul is higher in both fluency and flexibility","Sana is higher in fluency; Rahul is higher in originality","Rahul is higher in fluency, while Sana is higher in flexibility","Both are equal in creativity, because creativity is measured only by the total number of ideas"],"answer":2,"explanation":"Fluency is the number of ideas; flexibility is the number of different categories. Rahul’s many ideas fall in one category, while Sana’s fewer ideas cover several categories.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"ईंट के असामान्य उपयोग पूछे जाने पर राहुल 20 उपयोग गिनाता है, पर हर एक किसी न किसी निर्माण या सहारे का रूप है (दीवार, सीढ़ी, दरवाज़े का रोक, खंभा…)। सना 8 उपयोग गिनाती है जिनमें कागज़ का भार, हथियार, कसरत का वज़न और रंग के लिए पिसा हुआ लाल चूर्ण शामिल हैं। कौन-सा कथन सही है?","optionsHi":["राहुल प्रवाह और लचीलापन दोनों में अधिक है","सना प्रवाह में अधिक है; राहुल मौलिकता में अधिक है","राहुल प्रवाह में अधिक है, जबकि सना लचीलेपन में अधिक है","दोनों सृजनशीलता में बराबर हैं, क्योंकि सृजनशीलता केवल विचारों की कुल संख्या से मापी जाती है"],"explanationHi":"प्रवाह विचारों की संख्या है; लचीलापन अलग-अलग श्रेणियों की संख्या है। राहुल के अनेक विचार एक ही श्रेणी में आते हैं, जबकि सना के कम विचार कई श्रेणियों को समेटते हैं।"},
  {"id":"cdp-child-development-205","question":"An intelligence test standardised on urban children asks, ‘What do you do when an escalator stops?’ Rural children who have never seen an escalator score lower on it. The main problem is that the test:","options":["Is culturally biased: it measures exposure, not ability","Is too reliable, giving rural children the same score every time","Measures emotional intelligence instead of general intelligence","Correctly shows that rural children have lower general intelligence"],"answer":0,"explanation":"Items that depend on specific cultural experience disadvantage children who lack it; the score reflects exposure, not intelligence. Culture-fair tests try to reduce this.","difficulty":"hard","source":"CTET · State TETs","questionHi":"शहरी बच्चों पर मानकीकृत एक बुद्धि परीक्षण पूछता है, ‘जब एस्केलेटर रुक जाए तो आप क्या करते हैं?’ जिन ग्रामीण बच्चों ने कभी एस्केलेटर नहीं देखा, वे इस पर कम अंक पाते हैं। मुख्य समस्या यह है कि परीक्षण:","optionsHi":["सांस्कृतिक रूप से पक्षपाती है: वह योग्यता नहीं, अनुभव के संपर्क को मापता है","बहुत अधिक विश्वसनीय है, जो ग्रामीण बच्चों को हर बार वही अंक देता है","सामान्य बुद्धि की बजाय भावनात्मक बुद्धि को मापता है","सही ढंग से दिखाता है कि ग्रामीण बच्चों की सामान्य बुद्धि कम है"],"explanationHi":"जो पद विशिष्ट सांस्कृतिक अनुभव पर निर्भर करते हैं, वे उन बच्चों को हानि पहुँचाते हैं जिनके पास वह अनुभव नहीं है; अंक बुद्धि नहीं, संपर्क को दर्शाता है। संस्कृति-निरपेक्ष परीक्षण इसे घटाने का प्रयास करते हैं।"},
  {"id":"cdp-child-development-206","question":"On a modern deviation-IQ test with a mean of 100 and a standard deviation of 15, a child scores 130. Assuming a normal distribution, which statement is correct?","options":["The child’s mental age is 30% higher than her chronological age","The child scored 30% more marks than an average child of the same age","The child is in the ‘very superior’ range only if her chronological age is above 10","The child is two standard deviations above the mean, above about 97–98% of peers"],"answer":3,"explanation":"130 = 100 + 2 × 15. About 2.3% of a normal distribution lies above +2 SD. A deviation IQ compares a child with same-age peers; it is not a mental-age ratio or a percentage of marks.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"माध्य 100 और मानक विचलन 15 वाले आधुनिक विचलन-IQ परीक्षण पर एक बच्ची 130 अंक पाती है। सामान्य बंटन मानते हुए कौन-सा कथन सही है?","optionsHi":["बच्ची की मानसिक आयु उसकी कालानुक्रमिक आयु से 30% अधिक है","बच्ची ने समान आयु के औसत बच्चे से 30% अधिक अंक पाए","बच्ची ‘अति उत्कृष्ट’ श्रेणी में तभी है जब उसकी कालानुक्रमिक आयु 10 से अधिक हो","बच्ची माध्य से दो मानक विचलन ऊपर है, लगभग 97–98% साथियों से ऊपर"],"explanationHi":"130 = 100 + 2 × 15। सामान्य बंटन का लगभग 2.3% +2 SD से ऊपर होता है। विचलन IQ बच्चे की तुलना समान आयु के साथियों से करता है; यह मानसिक-आयु अनुपात या अंकों का प्रतिशत नहीं है।"},
  {"id":"cdp-child-development-207","question":"Under the Rights of Persons with Disabilities Act, 2016, ‘reasonable accommodation’ means:","options":["Admitting a child with a disability only if she can follow the regular class without help","Appropriate adjustments, without undue burden, so she can exercise rights equally","Providing a separate special school close to the child’s home, with transport","Reducing the syllabus for all children in a class that has a child with a disability"],"answer":1,"explanation":"The Act defines reasonable accommodation as appropriate modifications and adjustments, without undue burden, to ensure equal enjoyment of rights; examples are ramps, scribes, extra time and accessible materials.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"दिव्यांगजन अधिकार अधिनियम, 2016 के अंतर्गत ‘उचित समायोजन’ का अर्थ है:","optionsHi":["दिव्यांग बच्चे को तभी प्रवेश देना जब वह बिना मदद के सामान्य कक्षा के साथ चल सके","अनुचित बोझ के बिना उपयुक्त समायोजन, ताकि वह अधिकारों का समान रूप से उपयोग कर सके","बच्चे के घर के पास परिवहन सहित एक अलग विशेष विद्यालय उपलब्ध कराना","जिस कक्षा में दिव्यांग बच्चा हो, उसमें सभी बच्चों के लिए पाठ्यक्रम घटाना"],"explanationHi":"अधिनियम उचित समायोजन को अधिकारों का समान उपभोग सुनिश्चित करने के लिए, अनुचित बोझ के बिना, उपयुक्त संशोधन और समायोजन के रूप में परिभाषित करता है; उदाहरण हैं रैंप, लेखक (स्क्राइब), अतिरिक्त समय और सुगम्य सामग्री।"},
  {"id":"cdp-child-development-208","question":"A mother’s employer suddenly changes her working hours to a late shift, so she can no longer help her son with homework, and his work suffers. In Bronfenbrenner’s ecological model, the mother’s workplace is part of the child’s:","options":["Microsystem","Mesosystem","Exosystem","Macrosystem"],"answer":2,"explanation":"The exosystem includes settings the child does not take part in directly but that affect him, such as a parent’s workplace. The mesosystem links two of the child’s own settings, such as home and school.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक माँ का नियोक्ता अचानक उसके कार्य के घंटे देर की पाली में बदल देता है, जिससे वह अब अपने बेटे की गृहकार्य में मदद नहीं कर पाती, और उसका काम बिगड़ने लगता है। ब्रोनफेनब्रेनर के पारिस्थितिकी मॉडल में माँ का कार्यस्थल बच्चे के किस तंत्र का हिस्सा है?","optionsHi":["सूक्ष्मतंत्र","मध्यतंत्र","बाह्यतंत्र","वृहत्तंत्र"],"explanationHi":"बाह्यतंत्र में वे परिवेश शामिल हैं जिनमें बच्चा सीधे भाग नहीं लेता पर जो उसे प्रभावित करते हैं, जैसे माता-पिता का कार्यस्थल। मध्यतंत्र बच्चे के अपने दो परिवेशों को जोड़ता है, जैसे घर और विद्यालय।"},
  {"id":"cdp-child-development-209","question":"A 14-year-old refuses to go to school because of a small pimple, convinced that ‘everyone will be staring at me all day’. David Elkind called this form of adolescent egocentrism the:","options":["Imaginary audience","Personal fable","Identity foreclosure","Psychosocial moratorium"],"answer":0,"explanation":"The imaginary audience is the belief that one is the focus of everyone’s attention. The personal fable is the belief that one’s experiences are unique and that one is invulnerable.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"14 वर्ष का एक किशोर एक छोटे-से मुँहासे के कारण स्कूल जाने से मना कर देता है, इस विश्वास के साथ कि ‘सब लोग दिन भर मुझे घूरते रहेंगे’। डेविड एल्किंड ने किशोर अहंकेंद्रिता के इस रूप को क्या कहा?","optionsHi":["काल्पनिक श्रोता","व्यक्तिगत गाथा","पहचान अवरोधन","मनोसामाजिक स्थगन"],"explanationHi":"काल्पनिक श्रोता यह विश्वास है कि हर किसी का ध्यान स्वयं पर केंद्रित है। व्यक्तिगत गाथा यह विश्वास है कि किसी के अनुभव अद्वितीय हैं और वह अजेय है।"},
  {"id":"cdp-child-development-210","question":"A student learning to type improves steadily for three weeks, then shows no improvement for ten days in spite of practice, and later starts improving again. The flat period is best described as:","options":["Extinction of the learned skill","Forgetting due to disuse","Negative transfer of training","A plateau in the learning curve"],"answer":3,"explanation":"A plateau is a temporary flat stretch in a learning curve, often caused by fatigue, loss of motivation, or the need to reorganise a skill at a higher level; it does not mean learning has stopped for good.","difficulty":"hard","source":"CTET · State TETs","questionHi":"टाइप करना सीख रहा एक विद्यार्थी तीन सप्ताह तक लगातार सुधार करता है, फिर अभ्यास के बावजूद दस दिन तक कोई सुधार नहीं दिखाता, और बाद में फिर सुधरने लगता है। इस सपाट अवधि का सबसे अच्छा वर्णन है:","optionsHi":["सीखे हुए कौशल का विलोपन","अनुपयोग के कारण विस्मरण","प्रशिक्षण का ऋणात्मक अंतरण","अधिगम वक्र में पठार (प्लैटो)"],"explanationHi":"पठार अधिगम वक्र में एक अस्थायी सपाट खंड है, जो प्रायः थकान, अभिप्रेरणा की कमी या कौशल को उच्च स्तर पर पुनर्गठित करने की आवश्यकता के कारण होता है; इसका अर्थ यह नहीं कि सीखना सदा के लिए रुक गया है।"},
  {"id":"cdp-child-development-211","question":"A teacher assesses a science project with a tool that lists criteria (planning, data, explanation, presentation) and, for each criterion, describes what ‘beginning’, ‘developing’ and ‘proficient’ work looks like. This tool is a:","options":["Checklist","Rubric","Anecdotal record","Cumulative record"],"answer":1,"explanation":"A rubric pairs criteria with descriptions of performance at each level. A checklist records only whether a feature is present or absent.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षक एक विज्ञान परियोजना का आकलन ऐसे उपकरण से करता है जिसमें कसौटियाँ (योजना, आँकड़े, व्याख्या, प्रस्तुति) सूचीबद्ध हैं और प्रत्येक कसौटी के लिए वर्णन है कि ‘आरंभिक’, ‘विकासशील’ और ‘दक्ष’ कार्य कैसा दिखता है। यह उपकरण है:","optionsHi":["जाँच-सूची (चेकलिस्ट)","रूब्रिक","आख्यानात्मक अभिलेख","संचयी अभिलेख"],"explanationHi":"रूब्रिक कसौटियों को प्रत्येक स्तर के प्रदर्शन के वर्णन के साथ जोड़ता है। जाँच-सूची केवल यह दर्ज करती है कि कोई विशेषता उपस्थित है या अनुपस्थित।"},
  {"id":"cdp-child-development-212","question":"During recess a teacher notices a usually shy child comforting a younger child who has fallen, and later writes a brief, factual note of what happened, with the date. This record is called:","options":["A rating scale","A cumulative record","An anecdotal record","A sociogram"],"answer":2,"explanation":"An anecdotal record is a short, objective description of a significant incident in a child’s behaviour, useful for assessing personal and social qualities.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अवकाश के दौरान एक शिक्षिका देखती है कि एक सामान्यतः शर्मीला बच्चा गिर पड़े छोटे बच्चे को सांत्वना दे रहा है, और बाद में तारीख के साथ घटना का एक संक्षिप्त, तथ्यात्मक नोट लिखती है। इस अभिलेख को कहते हैं:","optionsHi":["निर्धारण मापनी (रेटिंग स्केल)","संचयी अभिलेख","आख्यानात्मक अभिलेख","समाजमिति (सोशियोग्राम)"],"explanationHi":"आख्यानात्मक अभिलेख बच्चे के व्यवहार की किसी महत्वपूर्ण घटना का संक्षिप्त, वस्तुनिष्ठ वर्णन है, जो व्यक्तिगत और सामाजिक गुणों के आकलन में उपयोगी है।"},
  {"id":"cdp-child-development-213","question":"Which question targets the ‘evaluating’ level of Bloom’s revised taxonomy?","options":["Name two methods of purifying water that are used in Indian homes.","Explain in your own words why boiling makes water safe to drink.","Use a filter to clean a sample of muddy water from the school pond.","Boiling or filtering: which would you recommend for your village, and why?"],"answer":3,"explanation":"Evaluating means making and justifying a judgement against criteria. Naming is remembering, explaining is understanding, and using a filter is applying.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कौन-सा प्रश्न ब्लूम के संशोधित वर्गीकरण के ‘मूल्यांकन’ स्तर को लक्षित करता है?","optionsHi":["भारतीय घरों में प्रयुक्त पानी शुद्ध करने की दो विधियों के नाम बताइए।","अपने शब्दों में समझाइए कि उबालने से पानी पीने के लिए सुरक्षित क्यों हो जाता है।","स्कूल के तालाब के गंदे पानी के नमूने को साफ करने के लिए छन्ने का उपयोग कीजिए।","उबालना या छानना: आप अपने गाँव के लिए किसकी अनुशंसा करेंगे, और क्यों?"],"explanationHi":"मूल्यांकन का अर्थ है कसौटियों के आधार पर निर्णय लेना और उसे उचित ठहराना। नाम बताना स्मरण है, समझाना बोध है, और छन्ने का उपयोग करना अनुप्रयोग है।"},
  {"id":"cdp-child-development-214","question":"A teacher who knows that a student comes from a well-off family and has neat handwriting gives his essay higher marks than another essay of equal quality. This is an example of:","options":["The halo effect","The central tendency error","The recency effect","Criterion-referenced marking"],"answer":0,"explanation":"The halo effect is when one favourable impression (neatness, background) colours the judgement of unrelated qualities. Clear rubrics and anonymous marking reduce it.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"एक शिक्षक, जो जानता है कि एक विद्यार्थी संपन्न परिवार से है और उसकी लिखावट साफ है, उसके निबंध को समान गुणवत्ता वाले दूसरे निबंध से अधिक अंक देता है। यह किसका उदाहरण है?","optionsHi":["प्रभामंडल प्रभाव","केंद्रीय प्रवृत्ति त्रुटि","नवीनता प्रभाव","कसौटी-संदर्भित अंकन"],"explanationHi":"प्रभामंडल प्रभाव तब होता है जब एक अनुकूल धारणा (सफाई, पृष्ठभूमि) असंबंधित गुणों के आकलन को रंग देती है। स्पष्ट रूब्रिक और गुमनाम अंकन इसे घटाते हैं।"},
  {"id":"cdp-child-development-215","question":"A 22-month-old says ‘Daddy go car’ and ‘more juice’. This stage of language development is called:","options":["Babbling","Holophrastic speech","Telegraphic speech","Cooing"],"answer":2,"explanation":"Two- or three-word utterances keeping the key content words and dropping function words are telegraphic speech. Holophrastic speech uses single words for whole ideas.","difficulty":"hard","source":"CTET · State TETs","questionHi":"22 माह का एक बच्चा कहता है ‘पापा जाओ गाड़ी’ और ‘और जूस’। भाषा विकास की इस अवस्था को क्या कहते हैं?","optionsHi":["बलबलाना (बैबलिंग)","एकशब्दीय वाक् (होलोफ्रेस्टिक)","तारवत (टेलीग्राफिक) वाक्","कूजन (कूइंग)"],"explanationHi":"दो या तीन शब्दों के कथन जो मुख्य सार्थक शब्द रखते हैं और प्रकार्य शब्द छोड़ देते हैं, तारवत वाक् हैं। एकशब्दीय वाक् में पूरे विचार के लिए एक ही शब्द प्रयोग होता है।"},
  {"id":"cdp-child-development-216","question":"According to Vygotsky, the order in which speech develops in relation to thought is:","options":["Inner speech → private speech → social speech","Private speech → social speech → inner speech","Social speech → inner speech → private speech","Social speech → private speech → inner speech"],"answer":3,"explanation":"Speech first serves to communicate with others, is then turned on oneself aloud as private speech to guide action, and finally goes ‘underground’ as silent inner speech, a tool of thought.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"वाइगोत्स्की के अनुसार चिंतन के संबंध में वाक् के विकास का क्रम क्या है?","optionsHi":["आंतरिक वाक् → निजी वाक् → सामाजिक वाक्","निजी वाक् → सामाजिक वाक् → आंतरिक वाक्","सामाजिक वाक् → आंतरिक वाक् → निजी वाक्","सामाजिक वाक् → निजी वाक् → आंतरिक वाक्"],"explanationHi":"वाक् पहले दूसरों से संवाद के काम आती है, फिर क्रिया को निर्देशित करने के लिए ज़ोर से स्वयं की ओर मुड़ती है (निजी वाक्), और अंत में मौन आंतरिक वाक् के रूप में ‘भीतर’ चली जाती है, जो चिंतन का उपकरण है।"},
  {"id":"cdp-child-development-217","question":"In a science lesson the teacher gives students magnets and various objects, asks, ‘What kinds of things does a magnet attract?’, and lets them test, record and find the pattern themselves, stepping in with questions only when needed. This approach is most closely linked with:","options":["Bruner’s discovery learning","Skinner’s programmed learning","Pavlov’s classical conditioning","Thorndike’s trial-and-error learning by drill"],"answer":0,"explanation":"Bruner advocated discovery learning, in which learners find principles through active exploration with guidance; it builds understanding and transfer.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"एक विज्ञान पाठ में शिक्षक विद्यार्थियों को चुंबक और अनेक वस्तुएँ देता है, पूछता है, ‘चुंबक किस प्रकार की चीज़ों को आकर्षित करता है?’, और उन्हें स्वयं परखने, दर्ज करने और प्रतिरूप खोजने देता है, केवल आवश्यकता होने पर प्रश्नों के साथ हस्तक्षेप करता है। यह उपागम सबसे अधिक किससे जुड़ा है?","optionsHi":["ब्रूनर का अन्वेषण अधिगम","स्किनर का अभिक्रमित अधिगम","पावलोव का शास्त्रीय अनुबंधन","थॉर्नडाइक का अभ्यास द्वारा प्रयास और त्रुटि अधिगम"],"explanationHi":"ब्रूनर ने अन्वेषण अधिगम की वकालत की, जिसमें अधिगमकर्ता मार्गदर्शन के साथ सक्रिय खोज द्वारा सिद्धांत खोजते हैं; यह समझ और अंतरण का निर्माण करता है।"},
  {"id":"cdp-child-development-218","question":"Which of the following statements about adolescent peer groups is most accurate for a teacher planning classroom activities?","options":["Peers have no influence once children reach adolescence, because family influence dominates","Peer influence is always negative and should be kept out of the classroom entirely","Peer acceptance matters greatly to adolescents, so structured group work can use it well","Adolescents learn best working alone, because they are naturally egocentric"],"answer":2,"explanation":"Need for belonging and peer approval rises in adolescence; it can lead to conformity, but well-planned cooperative tasks channel it towards learning and social skills.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा की गतिविधियों की योजना बना रहे शिक्षक के लिए किशोरों के सहपाठी समूहों के बारे में निम्नलिखित में से कौन-सा कथन सबसे सटीक है?","optionsHi":["किशोरावस्था में पहुँचने के बाद साथियों का कोई प्रभाव नहीं रहता, क्योंकि परिवार का प्रभाव हावी रहता है","साथियों का प्रभाव हमेशा नकारात्मक होता है और उसे कक्षा से पूरी तरह दूर रखना चाहिए","किशोरों के लिए साथियों की स्वीकृति बहुत मायने रखती है, इसलिए संरचित समूह कार्य उसका अच्छा उपयोग कर सकता है","किशोर अकेले काम करके सबसे अच्छा सीखते हैं, क्योंकि वे स्वभाव से अहंकेंद्रित होते हैं"],"explanationHi":"अपनत्व और साथियों की स्वीकृति की आवश्यकता किशोरावस्था में बढ़ती है; यह अनुरूपता की ओर ले जा सकती है, पर भलीभाँति योजनाबद्ध सहयोगी कार्य उसे अधिगम और सामाजिक कौशलों की ओर मोड़ते हैं।"},
  {"id":"cdp-child-development-219","question":"A Class 2 teacher notices that a child who learnt to count objects by tens in maths now groups items in tens on her own while sorting seeds in EVS. The teacher is seeing:","options":["Negative transfer","Positive transfer","Retroactive interference","Spontaneous recovery"],"answer":1,"explanation":"Learning in one setting that helps performance in another is positive transfer. Teaching for understanding and showing links across subjects promotes it.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 2 की एक शिक्षिका देखती है कि जिस बच्ची ने गणित में वस्तुओं को दहाइयों में गिनना सीखा था, वह अब EVS में बीज छाँटते समय स्वयं ही वस्तुओं को दहाइयों में समूहित कर रही है। शिक्षिका क्या देख रही है?","optionsHi":["ऋणात्मक अंतरण","धनात्मक अंतरण","पश्चोन्मुख व्यतिकरण","स्वतः पुनर्प्राप्ति"],"explanationHi":"एक परिवेश में सीखा हुआ जब दूसरे में प्रदर्शन में सहायक हो, तो वह धनात्मक अंतरण है। समझ के लिए शिक्षण और विषयों के बीच संबंध दिखाना इसे बढ़ावा देता है।"},
  {"id":"cdp-child-development-220","question":"Assertion (A): According to Vygotsky, cultural tools such as language, number systems and writing shape the way children think. Reason (R): Vygotsky held that higher mental functions first appear between people and are then internalised by the individual.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Vygotsky’s ‘general genetic law’ says every function appears twice, first socially and then individually; because cultural tools are used socially before being internalised, they come to shape thought.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अभिकथन (A): वाइगोत्स्की के अनुसार भाषा, संख्या-प्रणाली और लेखन जैसे सांस्कृतिक उपकरण बच्चों के सोचने के ढंग को आकार देते हैं। कारण (R): वाइगोत्स्की का मत था कि उच्च मानसिक प्रकार्य पहले लोगों के बीच प्रकट होते हैं और फिर व्यक्ति द्वारा आत्मसात किए जाते हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"वाइगोत्स्की का ‘सामान्य आनुवंशिक नियम’ कहता है कि हर प्रकार्य दो बार प्रकट होता है, पहले सामाजिक रूप से और फिर वैयक्तिक रूप से; चूँकि सांस्कृतिक उपकरण आत्मसात होने से पहले सामाजिक रूप से उपयोग किए जाते हैं, वे चिंतन को आकार देने लगते हैं।"},
  {"id":"cdp-child-development-221","question":"How many of these statements about formative and summative assessment are correct? I. The same test can be formative or summative depending on how its results are used. II. Summative assessment usually comes at the end of a unit or term. III. Formative assessment can use observation, quizzes and drafts during instruction. IV. Formative assessment is mainly for improving learning, while summative is mainly for certifying it.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The purpose decides whether a test is formative or summative; summative comes at the end of a unit or term; formative uses many tools such as observation, quizzes and drafts; and it mainly aims to improve learning.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"रचनात्मक और योगात्मक आकलन के बारे में इनमें से कितने कथन सही हैं? I. एक ही परीक्षण रचनात्मक या योगात्मक हो सकता है, यह इस पर निर्भर करता है कि उसके परिणामों का उपयोग कैसे होता है। II. योगात्मक आकलन सामान्यतः इकाई या सत्र के अंत में होता है। III. रचनात्मक आकलन शिक्षण के दौरान अवलोकन, क्विज़ और प्रारूपों का उपयोग कर सकता है। IV. रचनात्मक आकलन मुख्यतः अधिगम को बेहतर बनाने के लिए होता है, जबकि योगात्मक मुख्यतः उसे प्रमाणित करने के लिए।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। उद्देश्य तय करता है कि परीक्षण रचनात्मक है या योगात्मक; योगात्मक इकाई या सत्र के अंत में आता है; रचनात्मक अवलोकन, क्विज़ और प्रारूप जैसे अनेक उपकरण प्रयोग करता है; और इसका मुख्य लक्ष्य अधिगम को बेहतर बनाना है।"},
  {"id":"cdp-child-development-222","question":"A Class 5 child often hits other children. When the teacher shouts at him and gives a slap in anger, the hitting does not stop and he begins hitting younger children more often. Social learning theory best explains this because:","options":["Punishment of any kind always increases the behaviour it follows","The child is being negatively reinforced by the teacher’s shouting","The child’s hitting is due to heredity and so cannot be changed","The teacher is modelling aggression, which the child imitates"],"answer":3,"explanation":"Bandura showed that children imitate aggressive models, especially powerful adults. Corporal punishment is also banned under Section 17 of the RTE Act.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 5 का एक बच्चा अक्सर दूसरे बच्चों को मारता है। जब शिक्षक उस पर चिल्लाते हैं और गुस्से में एक थप्पड़ मारते हैं, तो मारना बंद नहीं होता और वह छोटे बच्चों को और अधिक बार मारने लगता है। सामाजिक अधिगम सिद्धांत इसे सबसे अच्छी तरह इसलिए समझाता है क्योंकि:","optionsHi":["किसी भी प्रकार का दंड जिस व्यवहार के बाद आता है, उसे हमेशा बढ़ाता है","शिक्षक के चिल्लाने से बच्चे को ऋणात्मक पुनर्बलन मिल रहा है","बच्चे का मारना आनुवंशिकता के कारण है और इसलिए बदला नहीं जा सकता","शिक्षक आक्रामकता का आदर्श (मॉडल) प्रस्तुत कर रहे हैं, जिसकी बच्चा नकल करता है"],"explanationHi":"बंडूरा ने दिखाया कि बच्चे आक्रामक आदर्शों, विशेषकर शक्तिशाली वयस्कों, की नकल करते हैं। RTE अधिनियम की धारा 17 के अंतर्गत शारीरिक दंड प्रतिबंधित भी है।"},
  {"id":"cdp-child-development-223","question":"An 18-month-old who saw a cousin throw a tantrum yesterday stamps her feet and screams in exactly the same way today, with the cousin nowhere around. For Piaget, this deferred imitation is important because it shows:","options":["That the child is still at the stage of simple reflex actions","The start of mental representation, as the sensorimotor stage ends","That the child has already acquired conservation of quantity","That the behaviour was learnt through classical conditioning"],"answer":1,"explanation":"Imitating a model who is no longer present requires a stored mental image; Piaget took this as evidence of emerging symbolic thought at the end of the sensorimotor period.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"18 माह की एक बच्ची, जिसने कल अपने चचेरे भाई को नखरे करते देखा था, आज उसी तरह पैर पटकती और चीखती है, जबकि चचेरा भाई कहीं मौजूद नहीं है। पियाजे के लिए यह विलंबित अनुकरण महत्वपूर्ण है क्योंकि यह दर्शाता है:","optionsHi":["कि बच्चा अभी सरल प्रतिवर्ती क्रियाओं की अवस्था में है","संवेदी-गामक अवस्था के समाप्त होने के साथ मानसिक निरूपण की शुरुआत","कि बच्चे ने मात्रा का संरक्षण पहले ही अर्जित कर लिया है","कि यह व्यवहार शास्त्रीय अनुबंधन से सीखा गया था"],"explanationHi":"किसी ऐसे आदर्श का अनुकरण करने के लिए, जो अब उपस्थित नहीं है, संचित मानसिक प्रतिमा चाहिए; पियाजे ने इसे संवेदी-गामक काल के अंत में उभरते प्रतीकात्मक चिंतन का प्रमाण माना।"},
  {"id":"cdp-child-development-224","question":"A four-year-old rides a stick as a ‘horse’ and, while playing ‘school’, sits still far longer than she does in real class. From Vygotsky’s viewpoint, the main developmental value of such pretend play is that it:","options":["Lets the child escape from all rules and adult demands for a while","Is only a way of releasing the child’s surplus physical energy","Separates meaning from objects and makes her follow the rules of a role","Shows that the child is still egocentric and should be moved on to formal tasks"],"answer":2,"explanation":"Vygotsky saw make-believe play as a leading activity that creates a zone of proximal development: substituting objects frees thought from things, and keeping to role rules builds self-regulation beyond the child’s everyday level, so she behaves ‘a head taller’ than herself.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"चार वर्ष की एक बच्ची डंडे को ‘घोड़ा’ बनाकर उस पर सवार होती है और ‘स्कूल’ खेलते समय असली कक्षा की तुलना में कहीं अधिक देर तक शांत बैठती है। वाइगोत्स्की के दृष्टिकोण से ऐसे कल्पनाशील खेल का मुख्य विकासात्मक मूल्य यह है कि वह:","optionsHi":["बच्चे को कुछ समय के लिए सभी नियमों और वयस्कों की माँगों से बचने देता है","केवल बच्चे की अतिरिक्त शारीरिक ऊर्जा निकालने का एक तरीका है","अर्थ को वस्तुओं से अलग करता है और उसे किसी भूमिका के नियमों का पालन कराता है","दर्शाता है कि बच्चा अभी अहंकेंद्रित है और उसे औपचारिक कार्यों की ओर बढ़ाना चाहिए"],"explanationHi":"वाइगोत्स्की कल्पनाशील खेल को एक अग्रणी गतिविधि मानते थे जो निकटस्थ विकास का क्षेत्र बनाती है: वस्तुओं का प्रतिस्थापन चिंतन को वस्तुओं से मुक्त करता है, और भूमिका के नियमों का पालन बच्चे के रोज़मर्रा के स्तर से परे आत्म-नियमन बनाता है, जिससे वह स्वयं से ‘एक सिर ऊँचा’ व्यवहार करती है।"},
  {"id":"cdp-child-development-225","question":"To teach a child with a mild intellectual disability to wash his hands properly, the teacher breaks the skill into small steps (wet hands, apply soap, rub palms, rub backs, rinse, dry), teaches each step with demonstration and praise, and links them together. This approach is called:","options":["Task analysis","Brainstorming","Discovery learning","Programmed failure"],"answer":0,"explanation":"Task analysis breaks a complex skill into small, sequenced steps that are taught and reinforced one by one, a key strategy for learners with intellectual disabilities.","difficulty":"hard","source":"CTET · State TETs","questionHi":"हल्की बौद्धिक अक्षमता वाले बच्चे को ठीक से हाथ धोना सिखाने के लिए शिक्षक कौशल को छोटे चरणों में बाँटता है (हाथ गीले करना, साबुन लगाना, हथेलियाँ रगड़ना, पीठ रगड़ना, धोना, सुखाना), प्रत्येक चरण को प्रदर्शन और प्रशंसा के साथ सिखाता है, और उन्हें जोड़ देता है। इस उपागम को कहते हैं:","optionsHi":["कार्य विश्लेषण","मंथन","अन्वेषण अधिगम","नियोजित विफलता"],"explanationHi":"कार्य विश्लेषण किसी जटिल कौशल को छोटे, क्रमबद्ध चरणों में बाँटता है जिन्हें एक-एक करके सिखाया और पुनर्बलित किया जाता है; यह बौद्धिक अक्षमता वाले अधिगमकर्ताओं के लिए एक प्रमुख रणनीति है।"},
  {"id":"cdp-child-development-226","question":"Varun asks unusually deep questions in class discussions and solves puzzles quickly, but rarely finishes written work, scores poorly and often disturbs others. A thoughtful teacher should first consider that he may be:","options":["A slow learner who needs simpler tasks and more drill","A child with an intellectual disability needing special help","A child who is simply indisciplined and needs stricter punishment","A gifted underachiever who is bored by unchallenging work"],"answer":3,"explanation":"High reasoning ability with poor performance and disruptive boredom is a classic profile of gifted underachievement; challenge and engagement, not simplification or punishment, address it.","difficulty":"hard","source":"CTET · State TETs","questionHi":"वरुण कक्षा चर्चाओं में असामान्य रूप से गहरे प्रश्न पूछता है और पहेलियाँ जल्दी हल करता है, पर लिखित कार्य शायद ही पूरा करता है, कम अंक पाता है और अक्सर दूसरों को बाधित करता है। एक विचारशील शिक्षक को सबसे पहले यह विचार करना चाहिए कि वह संभवतः है:","optionsHi":["मंद अधिगमकर्ता जिसे सरल कार्य और अधिक अभ्यास चाहिए","बौद्धिक अक्षमता वाला बच्चा जिसे विशेष सहायता चाहिए","केवल अनुशासनहीन बच्चा जिसे कड़ा दंड चाहिए","प्रतिभाशाली पर कम उपलब्धि वाला बच्चा, जो चुनौतीहीन कार्य से ऊब गया है"],"explanationHi":"उच्च तर्क-क्षमता के साथ कमज़ोर प्रदर्शन और बाधा डालने वाली ऊब प्रतिभाशाली कम-उपलब्धि का एक क्लासिक प्रोफ़ाइल है; इसका समाधान चुनौती और जुड़ाव है, सरलीकरण या दंड नहीं।"},
  {"id":"cdp-child-development-227","question":"A teacher always asks boys to move benches and girls to decorate the notice board and serve water to guests. She never states any view on gender. Through these routine practices, children are learning gender roles via the:","options":["Formal curriculum","Hidden curriculum","Spiral curriculum","Co-scholastic curriculum"],"answer":1,"explanation":"The hidden curriculum is the unstated lessons conveyed by routines, expectations and practices; here it quietly teaches stereotyped gender roles.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षिका हमेशा लड़कों से बेंच हटवाने और लड़कियों से सूचना-पट्ट सजाने तथा मेहमानों को पानी देने को कहती है। वह लिंग पर कभी कोई राय नहीं बताती। इन नियमित व्यवहारों के माध्यम से बच्चे लिंग-भूमिकाएँ किसके द्वारा सीख रहे हैं?","optionsHi":["औपचारिक पाठ्यचर्या","छिपी हुई पाठ्यचर्या","सर्पिल पाठ्यचर्या","सह-शैक्षिक पाठ्यचर्या"],"explanationHi":"छिपी हुई पाठ्यचर्या वे अनकहे पाठ हैं जो दिनचर्याओं, अपेक्षाओं और व्यवहारों के माध्यम से मिलते हैं; यहाँ वह चुपचाप रूढ़िबद्ध लिंग-भूमिकाएँ सिखा रही है।"},
  {"id":"cdp-child-development-228","question":"Which remark from a student best shows a mastery (learning) goal orientation rather than a performance goal orientation?","options":["‘I chose the easy questions so that I would not look stupid in front of the class.’","‘I picked the hard problem to really understand fractions, even if I get it wrong.’","‘I want to score more marks than Rohit in this test, at any cost.’","‘I only study the topics that are likely to come in the exam.’"],"answer":1,"explanation":"Mastery goals focus on understanding and improving; performance goals focus on looking competent or beating others, and often lead learners to avoid challenge.","difficulty":"hard","source":"CTET · State TETs","questionHi":"विद्यार्थी की कौन-सी टिप्पणी निष्पादन लक्ष्य अभिविन्यास की बजाय निपुणता (अधिगम) लक्ष्य अभिविन्यास को सबसे अच्छी तरह दर्शाती है?","optionsHi":["‘मैंने आसान प्रश्न चुने ताकि कक्षा के सामने मूर्ख न दिखूँ।’","‘मैंने भिन्न को सचमुच समझने के लिए कठिन सवाल चुना, भले ही मैं गलत हो जाऊँ।’","‘मुझे इस परीक्षा में रोहित से अधिक अंक लाने हैं, चाहे कुछ भी हो।’","‘मैं केवल वही विषय पढ़ता हूँ जिनके परीक्षा में आने की संभावना है।’"],"explanationHi":"निपुणता लक्ष्य समझने और सुधारने पर केंद्रित होते हैं; निष्पादन लक्ष्य सक्षम दिखने या दूसरों को हराने पर केंद्रित होते हैं, और प्रायः अधिगमकर्ताओं को चुनौती से बचने की ओर ले जाते हैं।"},
  {"id":"cdp-child-development-229","question":"After failing a test, a student says, ‘I am just not a maths person.’ Using Weiner’s attribution theory, the teacher would most help her by encouraging her to attribute the failure to:","options":["Bad luck, which is external and beyond anyone’s control","The difficulty of the test, which is external and stable over time","Low ability, which is internal and stable, so she should accept it","Insufficient effort or a poor strategy, which she can change and control"],"answer":3,"explanation":"Attributing failure to stable, uncontrollable causes such as ability lowers persistence; attributing it to effort or strategy, which the student can change, keeps motivation alive.","difficulty":"hard","source":"CTET · State TETs","questionHi":"परीक्षा में असफल होने के बाद एक विद्यार्थी कहती है, ‘मैं बस गणित वाली इंसान नहीं हूँ।’ वाइनर के आरोपण सिद्धांत का उपयोग करते हुए, शिक्षक उसकी सबसे अधिक मदद तब करेगा जब उसे असफलता का कारण किसे मानने के लिए प्रोत्साहित करे?","optionsHi":["बुरी किस्मत, जो बाह्य है और किसी के नियंत्रण से परे है","परीक्षा की कठिनाई, जो बाह्य है और समय के साथ स्थिर है","कम योग्यता, जो आंतरिक और स्थिर है, इसलिए उसे स्वीकार कर लेना चाहिए","अपर्याप्त प्रयास या कमज़ोर युक्ति, जिसे वह बदल और नियंत्रित कर सकती है"],"explanationHi":"असफलता का कारण योग्यता जैसे स्थिर, अनियंत्रणीय कारकों को मानने से दृढ़ता घटती है; उसे प्रयास या युक्ति, जिसे विद्यार्थी बदल सकता है, से जोड़ने पर अभिप्रेरणा जीवित रहती है।"},
  {"id":"cdp-child-development-230","question":"After failing repeatedly in maths and being scolded each time, a Class 5 child now does not even try the easy sums and says, ‘What’s the use? I’ll get it wrong anyway.’ This condition is best described as:","options":["Learned helplessness","Intrinsic motivation","Functional fixedness","Self-actualisation"],"answer":0,"explanation":"Seligman described learned helplessness: after repeated experiences of uncontrollable failure a person stops trying even when success is possible. Small, assured successes help to break it.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"गणित में बार-बार असफल होने और हर बार डाँट खाने के बाद कक्षा 5 का एक बच्चा अब आसान सवाल भी हल करने की कोशिश नहीं करता और कहता है, ‘क्या फायदा? मैं वैसे भी गलत कर दूँगा।’ इस स्थिति का सबसे अच्छा वर्णन है:","optionsHi":["सीखी हुई असहायता","आंतरिक अभिप्रेरणा","प्रकार्यात्मक स्थिरता","आत्म-सिद्धि"],"explanationHi":"सेलिगमैन ने सीखी हुई असहायता का वर्णन किया: अनियंत्रणीय असफलता के बार-बार अनुभवों के बाद व्यक्ति सफलता संभव होने पर भी प्रयास करना छोड़ देता है। छोटी, सुनिश्चित सफलताएँ इसे तोड़ने में मदद करती हैं।"},
  {"id":"cdp-child-development-231","question":"A teacher who used to call on a student within a second of asking a question begins waiting three to five seconds before taking an answer. According to research on wait time, the most likely effect is:","options":["Students lose interest and the class becomes noisy and restless","More students answer, and answers become longer and more thoughtful","Only the fastest students answer, just as they did before","Students answer less, because the silence makes them anxious"],"answer":1,"explanation":"Mary Budd Rowe found that a longer wait time leads to more students responding, longer and better-reasoned answers, and more questions from students.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"एक शिक्षक, जो प्रश्न पूछने के एक सेकंड के भीतर किसी विद्यार्थी को बुला लेता था, उत्तर लेने से पहले तीन से पाँच सेकंड प्रतीक्षा करने लगता है। प्रतीक्षा-समय पर शोध के अनुसार सबसे संभावित प्रभाव क्या है?","optionsHi":["विद्यार्थियों की रुचि घट जाती है और कक्षा शोरगुल वाली और बेचैन हो जाती है","अधिक विद्यार्थी उत्तर देते हैं, और उत्तर लंबे तथा अधिक विचारपूर्ण हो जाते हैं","केवल सबसे तेज़ विद्यार्थी उत्तर देते हैं, जैसा वे पहले भी करते थे","विद्यार्थी कम उत्तर देते हैं, क्योंकि चुप्पी उन्हें चिंतित करती है"],"explanationHi":"मैरी बड रोवे ने पाया कि लंबा प्रतीक्षा-समय अधिक विद्यार्थियों के उत्तर देने, लंबे और बेहतर तर्क वाले उत्तरों, और विद्यार्थियों द्वारा अधिक प्रश्न पूछे जाने की ओर ले जाता है।"},
  {"id":"cdp-child-development-232","question":"How many of these statements about growth and development are correct? I. Growth refers mainly to quantitative changes such as height and weight. II. Development includes qualitative changes in functioning. III. Growth in height continues throughout life. IV. Development can continue even after physical growth stops.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. Growth in height stops after adolescence, but development (in thinking, skills and personality) continues throughout life.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"वृद्धि और विकास के बारे में इनमें से कितने कथन सही हैं? I. वृद्धि मुख्यतः ऊँचाई और वज़न जैसे मात्रात्मक परिवर्तनों को कहते हैं। II. विकास में कार्यप्रणाली के गुणात्मक परिवर्तन शामिल हैं। III. ऊँचाई में वृद्धि जीवन भर जारी रहती है। IV. शारीरिक वृद्धि रुकने के बाद भी विकास जारी रह सकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। ऊँचाई में वृद्धि किशोरावस्था के बाद रुक जाती है, पर विकास (चिंतन, कौशल और व्यक्तित्व में) जीवन भर जारी रहता है।"},
  {"id":"cdp-child-development-233","question":"According to Freud, the period from about six years to puberty, when children’s energy is directed mainly towards school learning, skills and same-sex friendships, is the:","options":["Phallic stage","Anal stage","Genital stage","Latency stage"],"answer":3,"explanation":"Freud’s latency stage covers the primary school years, when sexual impulses are relatively dormant and energy goes into learning and friendships. It roughly matches Erikson’s industry vs inferiority stage.","difficulty":"hard","source":"CTET · State TETs","questionHi":"फ्रायड के अनुसार लगभग छह वर्ष से यौवनारंभ तक की अवधि, जब बच्चों की ऊर्जा मुख्यतः विद्यालयी अधिगम, कौशलों और समलैंगिक मित्रताओं की ओर निर्देशित होती है, कौन-सी अवस्था है?","optionsHi":["लिंगप्रधान (फैलिक) अवस्था","गुदीय अवस्था","जननांगीय अवस्था","सुषुप्ति (लेटेंसी) अवस्था"],"explanationHi":"फ्रायड की सुषुप्ति अवस्था प्राथमिक विद्यालय के वर्षों को समेटती है, जब यौन आवेग अपेक्षाकृत सुषुप्त रहते हैं और ऊर्जा अधिगम और मित्रताओं में लगती है। यह मोटे तौर पर एरिक्सन की उद्यमिता बनाम हीनता अवस्था से मेल खाती है।"},
  {"id":"cdp-child-development-234","question":"In a crèche, one caregiver responds promptly and warmly to an infant’s cries, while in another, infants are fed and changed at irregular times and their crying is often ignored. According to Erikson, infants in the second crèche are more likely to develop:","options":["A basic mistrust of the world","A sense of guilt about their own actions","A sense of inferiority","Role confusion"],"answer":0,"explanation":"Erikson’s first stage (trust vs mistrust) depends on consistent, responsive care; unpredictable or neglectful care breeds mistrust.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिशु-गृह (क्रेच) में एक देखभालकर्ता शिशु के रोने पर तुरंत और स्नेह से प्रतिक्रिया देती है, जबकि दूसरे में शिशुओं को अनियमित समय पर खिलाया और बदला जाता है और उनके रोने को अक्सर अनदेखा किया जाता है। एरिक्सन के अनुसार दूसरे क्रेच के शिशुओं में किसके विकसित होने की संभावना अधिक है?","optionsHi":["संसार के प्रति बुनियादी अविश्वास","अपने कार्यों के प्रति अपराधबोध की भावना","हीनता की भावना","भूमिका भ्रांति"],"explanationHi":"एरिक्सन की पहली अवस्था (विश्वास बनाम अविश्वास) सुसंगत, संवेदनशील देखभाल पर निर्भर करती है; अनिश्चित या उपेक्षापूर्ण देखभाल अविश्वास को जन्म देती है।"},
  {"id":"cdp-child-development-235","question":"Under NEP 2020’s 5+3+3+4 structure, a 12-year-old in Grade 7 is in which stage, and what is the recommended emphasis?","options":["Preparatory stage; play- and discovery-based learning with light textbooks","Middle stage; experiential learning across subjects, with subject teachers","Secondary stage; multidisciplinary study with choice of subjects and greater critical thinking","Foundational stage; flexible, multilevel, activity-based learning"],"answer":1,"explanation":"The Middle stage covers Grades 6–8 (ages about 11–14) and introduces subject teachers and more abstract concepts through experiential learning. Grades 3–5 form the Preparatory stage and 9–12 the Secondary stage.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"NEP 2020 की 5+3+3+4 संरचना के अंतर्गत, कक्षा 7 में पढ़ने वाला 12 वर्ष का बच्चा किस चरण में है, और अनुशंसित बल किस पर है?","optionsHi":["प्रारंभिक चरण; खेल- और अन्वेषण-आधारित अधिगम, हल्की पाठ्यपुस्तकों के साथ","मध्य चरण; विषय शिक्षकों के साथ सभी विषयों में अनुभवात्मक अधिगम","माध्यमिक चरण; विषयों के चयन और अधिक आलोचनात्मक चिंतन के साथ बहु-विषयक अध्ययन","आधारभूत चरण; लचीला, बहुस्तरीय, गतिविधि-आधारित अधिगम"],"explanationHi":"मध्य चरण कक्षा 6–8 (आयु लगभग 11–14) को समेटता है और अनुभवात्मक अधिगम के माध्यम से विषय शिक्षक और अधिक अमूर्त अवधारणाएँ लाता है। कक्षा 3–5 प्रारंभिक चरण और 9–12 माध्यमिक चरण बनाती हैं।"},
  {"id":"cdp-child-development-236","question":"NCF 2005’s concern about heavy school bags, rote learning and exam stress drew on which earlier report?","options":["The Kothari Commission report, 1966","The Mudaliar Commission report, 1953","The Yash Pal Committee report, 1993","The Radhakrishnan Commission report, 1949"],"answer":2,"explanation":"The Yash Pal Committee’s ‘Learning Without Burden’ (1993) identified the burden of non-comprehension as a key problem, and NCF 2005 built on it.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"भारी स्कूल बैग, रटने की प्रवृत्ति और परीक्षा के तनाव के बारे में NCF 2005 की चिंता किस पूर्ववर्ती रिपोर्ट पर आधारित थी?","optionsHi":["कोठारी आयोग की रिपोर्ट, 1966","मुदालियर आयोग की रिपोर्ट, 1953","यशपाल समिति की रिपोर्ट, 1993","राधाकृष्णन आयोग की रिपोर्ट, 1949"],"explanationHi":"यशपाल समिति की ‘बोझ के बिना शिक्षा’ (1993) ने न समझने के बोझ को एक प्रमुख समस्या के रूप में पहचाना, और NCF 2005 ने उसी पर निर्माण किया।"},
  {"id":"cdp-child-development-237","question":"Studies in several collectivist societies found that adults who reasoned mainly in terms of duties to family and community were often scored at Kohlberg’s Stage 3 or 4, rarely higher. This finding is mainly used to argue that Kohlberg’s scheme:","options":["Proves that people in those societies are morally less developed than Westerners","Shows that moral reasoning does not really develop with age at all","Is a theory of moral emotions rather than of moral reasoning","May be culturally biased towards Western ideas of individual rights and justice"],"answer":3,"explanation":"Critics argue that the highest stages reflect an individualistic, justice-based ideal; community-oriented moral reasoning may be mature in its own terms but is underscored.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कई सामूहिकतावादी समाजों में हुए अध्ययनों में पाया गया कि जो वयस्क मुख्यतः परिवार और समुदाय के प्रति कर्तव्यों के संदर्भ में तर्क करते थे, उन्हें प्रायः कोहलबर्ग के चरण 3 या 4 पर आँका गया, शायद ही कभी उससे ऊपर। इस निष्कर्ष का उपयोग मुख्यतः यह तर्क देने के लिए किया जाता है कि कोहलबर्ग की योजना:","optionsHi":["सिद्ध करती है कि उन समाजों के लोग पश्चिमी लोगों की तुलना में नैतिक रूप से कम विकसित हैं","दर्शाती है कि नैतिक चिंतन आयु के साथ वास्तव में विकसित ही नहीं होता","नैतिक चिंतन का नहीं, बल्कि नैतिक भावनाओं का सिद्धांत है","व्यक्तिगत अधिकारों और न्याय के पश्चिमी विचारों के प्रति सांस्कृतिक रूप से पक्षपाती हो सकती है"],"explanationHi":"आलोचकों का तर्क है कि सर्वोच्च चरण एक व्यक्तिवादी, न्याय-आधारित आदर्श को दर्शाते हैं; समुदाय-उन्मुख नैतिक चिंतन अपने ढंग से परिपक्व हो सकता है पर उसे कम आँका जाता है।"},
  {"id":"cdp-child-development-238","question":"In Martin Hughes’s ‘policeman doll’ task, many children aged about 3½ to 5 could hide a doll where two ‘policemen’ could not see it, though most failed Piaget’s three-mountains task. The finding is used to argue that:","options":["Piaget overestimated the perspective-taking abilities of young children","Young children can take another’s view when a task makes human sense to them","Egocentrism in fact lasts until the formal operational stage","Perspective taking depends only on a child’s language ability"],"answer":1,"explanation":"Hughes showed that in a meaningful, familiar context young children can decentre; the abstract mountains task masked their competence, a common critique of Piaget.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"मार्टिन ह्यूज़ के ‘पुलिसवाला गुड़िया’ कार्य में लगभग 3½ से 5 वर्ष के कई बच्चे गुड़िया को ऐसी जगह छिपा सके जहाँ दो ‘पुलिसवाले’ उसे नहीं देख सकते थे, जबकि अधिकांश पियाजे के तीन-पर्वत कार्य में विफल रहे। इस निष्कर्ष का उपयोग यह तर्क देने के लिए किया जाता है कि:","optionsHi":["पियाजे ने छोटे बच्चों की दृष्टिकोण-ग्रहण क्षमताओं को अधिक आँका","छोटे बच्चे दूसरे का दृष्टिकोण ले सकते हैं जब कार्य उन्हें मानवीय रूप से सार्थक लगे","अहंकेंद्रिता वास्तव में औपचारिक संक्रियात्मक अवस्था तक बनी रहती है","दृष्टिकोण-ग्रहण केवल बच्चे की भाषा-योग्यता पर निर्भर करता है"],"explanationHi":"ह्यूज़ ने दिखाया कि सार्थक, परिचित संदर्भ में छोटे बच्चे विकेंद्रण कर सकते हैं; अमूर्त पर्वत कार्य ने उनकी क्षमता को छिपा दिया, जो पियाजे की एक आम आलोचना है।"},
  {"id":"cdp-child-development-239","question":"NEP 2020 calls for board examinations to be reformed mainly so that they:","options":["Test core competencies rather than coaching and memorisation","Are held every month instead of once at the end of the year","Are made harder so that fewer students pass and standards rise","Test only objective, factual recall that is easy to mark"],"answer":0,"explanation":"NEP 2020 wants board exams to be ‘easier’ in the sense of testing core concepts and competencies, reducing the need for coaching and rote learning.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"NEP 2020 बोर्ड परीक्षाओं में सुधार की माँग मुख्यतः इसलिए करती है ताकि वे:","optionsHi":["कोचिंग और रटंत की बजाय मूल दक्षताओं का परीक्षण करें","वर्ष के अंत में एक बार की बजाय हर माह ली जाएँ","कठिन बनाई जाएँ ताकि कम विद्यार्थी उत्तीर्ण हों और स्तर ऊँचा हो","केवल वस्तुनिष्ठ, तथ्यात्मक स्मरण का परीक्षण करें जिसे जाँचना आसान हो"],"explanationHi":"NEP 2020 चाहती है कि बोर्ड परीक्षाएँ इस अर्थ में ‘आसान’ हों कि वे मूल अवधारणाओं और दक्षताओं का परीक्षण करें, जिससे कोचिंग और रटंत शिक्षा की आवश्यकता घटे।"},
  {"id":"cdp-child-development-240","question":"The same essay is given 8/20 by one examiner and 16/20 by another. The main weakness this reveals is in the test’s:","options":["Content validity","Predictive validity","Scoring reliability","Norm-referencing"],"answer":2,"explanation":"When different scorers give very different marks to the same answer, the scoring is unreliable. Rubrics and moderation improve inter-rater reliability; validity concerns whether the right thing is measured.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक ही निबंध को एक परीक्षक 8/20 और दूसरा 16/20 अंक देता है। यह परीक्षण की किस कमजोरी को उजागर करता है?","optionsHi":["विषयवस्तु वैधता","भविष्यसूचक वैधता","अंकन विश्वसनीयता","मानक-संदर्भन"],"explanationHi":"जब अलग-अलग अंककर्ता एक ही उत्तर को बहुत भिन्न अंक देते हैं, तो अंकन अविश्वसनीय होता है। रूब्रिक और मॉडरेशन अंतर-मूल्यांकनकर्ता विश्वसनीयता सुधारते हैं; वैधता इससे संबंधित है कि क्या सही चीज़ मापी जा रही है।"},
  {"id":"cdp-child-development-241","question":"A music school gives applicants a test to predict how well they would do if trained, though most have never studied music. This is:","options":["An achievement test","A diagnostic test","An attitude scale","An aptitude test"],"answer":3,"explanation":"An aptitude test predicts potential to learn a skill with training. An achievement test measures what has already been learnt, and a diagnostic test finds specific difficulties.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक संगीत विद्यालय आवेदकों को यह अनुमान लगाने के लिए एक परीक्षण देता है कि प्रशिक्षण मिलने पर वे कितना अच्छा करेंगे, जबकि अधिकांश ने कभी संगीत नहीं सीखा है। यह है:","optionsHi":["उपलब्धि परीक्षण","निदानात्मक परीक्षण","अभिवृत्ति मापनी","अभिक्षमता परीक्षण"],"explanationHi":"अभिक्षमता परीक्षण प्रशिक्षण के साथ किसी कौशल को सीखने की संभावित क्षमता का अनुमान लगाता है। उपलब्धि परीक्षण वह मापता है जो पहले ही सीखा जा चुका है, और निदानात्मक परीक्षण विशिष्ट कठिनाइयाँ खोजता है।"},
  {"id":"cdp-child-development-242","question":"Each child in a class names two classmates they would most like to work with. The teacher draws the choices as arrows. One child receives no arrows from anyone. The tool and the child’s position are respectively:","options":["A sociogram; an isolate","A rating scale; a star","A cumulative record; a leader","A projective test; a rejectee"],"answer":0,"explanation":"Sociometry (Moreno) uses peer choices drawn as a sociogram; a child chosen by none is an isolate, while one chosen by many is a star.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा का प्रत्येक बच्चा दो सहपाठियों के नाम बताता है जिनके साथ वह सबसे अधिक काम करना चाहेगा। शिक्षक इन चुनावों को तीरों के रूप में बनाता है। एक बच्चे को किसी से कोई तीर नहीं मिलता। उपकरण और बच्चे की स्थिति क्रमशः क्या हैं?","optionsHi":["समाजमिति आरेख (सोशियोग्राम); एकाकी (आइसोलेट)","निर्धारण मापनी; सितारा (स्टार)","संचयी अभिलेख; नेता","प्रक्षेपी परीक्षण; अस्वीकृत"],"explanationHi":"समाजमिति (मोरेनो) साथियों के चुनावों का उपयोग करती है जिन्हें समाजमिति आरेख के रूप में बनाया जाता है; जिसे कोई नहीं चुनता वह एकाकी है, जबकि जिसे बहुत से लोग चुनते हैं वह सितारा है।"},
  {"id":"cdp-child-development-243","question":"In a Montessori class, a child tries to fit wooden cylinders into holes of matching sizes. If one goes into the wrong hole, the last cylinder will not fit, so the child sees the mistake without being told. This feature reflects Montessori’s principle of:","options":["Reinforcement by the teacher’s praise","Auto-education via control of error","Learning by rote repetition of tasks","Group competition among the children"],"answer":1,"explanation":"Montessori’s materials have a built-in ‘control of error’, letting the child discover and correct mistakes independently, the idea of auto-education.","difficulty":"hard","source":"CTET · State TETs","questionHi":"मॉन्टेसरी कक्षा में एक बच्चा लकड़ी के बेलनों को मेल खाते आकार के छेदों में बिठाने का प्रयास करता है। यदि कोई गलत छेद में चला जाए, तो आखिरी बेलन नहीं बैठेगा, इसलिए बच्चा बिना बताए अपनी गलती देख लेता है। यह विशेषता मॉन्टेसरी के किस सिद्धांत को दर्शाती है?","optionsHi":["शिक्षक की प्रशंसा द्वारा पुनर्बलन","त्रुटि-नियंत्रण द्वारा स्वयं-शिक्षा","कार्यों की रटंत पुनरावृत्ति से अधिगम","बच्चों के बीच समूह प्रतिस्पर्धा"],"explanationHi":"मॉन्टेसरी की सामग्री में अंतर्निहित ‘त्रुटि-नियंत्रण’ होता है, जिससे बच्चा स्वतंत्र रूप से गलतियाँ खोजकर सुधार लेता है; यही स्वयं-शिक्षा का विचार है।"},
  {"id":"cdp-child-development-244","question":"Class 6 students run a small school stationery shop, keeping accounts, ordering stock and dividing duties, and learn maths and social skills through it. This reflects John Dewey’s view that:","options":["Learning should happen mainly through lectures and textbooks","Children should be kept away from real-life responsibilities","The school should be a miniature society built on purposeful activity","Discipline is best taught through a system of rewards and punishments"],"answer":2,"explanation":"Dewey saw the school as an embryonic community in which children learn by doing purposeful, social activities connected to life.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 6 के विद्यार्थी एक छोटी स्कूल स्टेशनरी दुकान चलाते हैं, हिसाब रखते हैं, माल मँगवाते हैं और कर्तव्य बाँटते हैं, और उसके माध्यम से गणित और सामाजिक कौशल सीखते हैं। यह जॉन डेवी के किस विचार को दर्शाता है?","optionsHi":["अधिगम मुख्यतः व्याख्यानों और पाठ्यपुस्तकों से होना चाहिए","बच्चों को वास्तविक जीवन की जिम्मेदारियों से दूर रखना चाहिए","विद्यालय उद्देश्यपूर्ण गतिविधि पर आधारित एक लघु समाज होना चाहिए","अनुशासन सबसे अच्छा पुरस्कार और दंड की प्रणाली से सिखाया जाता है"],"explanationHi":"डेवी विद्यालय को एक भ्रूणीय समुदाय मानते थे जिसमें बच्चे जीवन से जुड़ी उद्देश्यपूर्ण, सामाजिक गतिविधियों को करके सीखते हैं।"},
  {"id":"cdp-child-development-245","question":"Which classroom practice is most distinctively social constructivist (Vygotskian) rather than individual cognitive constructivist (Piagetian)?","options":["A child working alone with materials to discover a rule for herself","The teacher giving a lecture followed by individual practice at desks","A child being rewarded with a star for each correct answer","Small groups debating explanations and building on one another’s ideas"],"answer":3,"explanation":"Both see learners as active, but social constructivism places the source of understanding in dialogue and joint activity with others. Lone discovery fits Piaget; rewards fit behaviourism.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कौन-सी कक्षा-पद्धति वैयक्तिक संज्ञानात्मक रचनावाद (पियाजे) की बजाय सामाजिक रचनावाद (वाइगोत्स्की) की सबसे विशिष्ट है?","optionsHi":["बच्ची का सामग्री के साथ अकेले काम करके स्वयं कोई नियम खोजना","शिक्षक का व्याख्यान देना और उसके बाद डेस्क पर वैयक्तिक अभ्यास","हर सही उत्तर पर बच्चे को सितारा देकर पुरस्कृत करना","छोटे समूहों का स्पष्टीकरणों पर बहस करना और एक-दूसरे के विचारों पर निर्माण करना"],"explanationHi":"दोनों अधिगमकर्ताओं को सक्रिय मानते हैं, पर सामाजिक रचनावाद समझ का स्रोत दूसरों के साथ संवाद और संयुक्त गतिविधि में रखता है। अकेली खोज पियाजे से मेल खाती है; पुरस्कार व्यवहारवाद से।"},
  {"id":"cdp-child-development-246","question":"How many of these ideas are consistent with behaviourism? I. Learning is a change in observable behaviour. II. Punishment strengthens the behaviour it follows. III. Learners actively construct meaning from experience. IV. Complex behaviour can be built by reinforcing successive approximations.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and IV are behaviourist. II is wrong: it is reinforcement that strengthens a behaviour, while punishment weakens it. III is a constructivist idea that behaviourism leaves out.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"इनमें से कितने विचार व्यवहारवाद के अनुरूप हैं? I. अधिगम देखे जा सकने वाले व्यवहार में परिवर्तन है। II. दंड जिस व्यवहार के बाद आता है उसे सुदृढ़ करता है। III. अधिगमकर्ता अनुभव से सक्रिय रूप से अर्थ का निर्माण करते हैं। IV. क्रमिक सन्निकटनों को पुनर्बलित करके जटिल व्यवहार बनाया जा सकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और IV व्यवहारवादी हैं। II गलत है: व्यवहार को पुनर्बलन सुदृढ़ करता है, जबकि दंड उसे कमज़ोर करता है। III एक रचनावादी विचार है जिसे व्यवहारवाद छोड़ देता है।"},
  {"id":"cdp-child-development-247","question":"A very withdrawn child never speaks in class. The teacher first praises her for looking at the speaker, then only when she raises her hand, then only when she says a word, and finally only when she gives a full answer. This technique is called:","options":["Shaping","Chaining of reflexes","Extinction","Modelling"],"answer":0,"explanation":"Shaping reinforces successive approximations of the target behaviour, raising the requirement step by step (Skinner).","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक बहुत संकोची बच्ची कक्षा में कभी नहीं बोलती। शिक्षिका पहले उसकी वक्ता की ओर देखने पर प्रशंसा करती है, फिर केवल तब जब वह हाथ उठाती है, फिर केवल तब जब वह एक शब्द बोलती है, और अंत में केवल तब जब वह पूरा उत्तर देती है। इस तकनीक को कहते हैं:","optionsHi":["आकारण (शेपिंग)","प्रतिवर्तों की शृंखलाबद्धता","विलोपन","आदर्श-प्रस्तुति (मॉडलिंग)"],"explanationHi":"आकारण लक्ष्य व्यवहार के क्रमिक सन्निकटनों को पुनर्बलित करता है और आवश्यकता को चरण-दर-चरण बढ़ाता है (स्किनर)।"},
  {"id":"cdp-child-development-248","question":"A child in Class 3 stammers when answering. What should the teacher do?","options":["Complete the words for him so that he and the class save time","Tell him to speak faster and more confidently, without stopping","Listen patiently, without finishing his sentences or allowing mockery","Exempt him from all oral activities to spare him embarrassment"],"answer":2,"explanation":"Patience and an accepting class reduce the anxiety that worsens stammering; finishing words, hurrying him or excluding him from speaking all lower confidence.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 3 का एक बच्चा उत्तर देते समय हकलाता है। शिक्षक को क्या करना चाहिए?","optionsHi":["उसके लिए शब्द पूरे कर देना ताकि उसका और कक्षा का समय बचे","उससे कहना कि रुके बिना और अधिक तेज़ तथा आत्मविश्वास से बोले","धैर्य से सुनना, उसके वाक्य पूरे किए बिना और मज़ाक उड़ाए जाने की अनुमति दिए बिना","उसे शर्मिंदगी से बचाने के लिए सभी मौखिक गतिविधियों से छूट देना"],"explanationHi":"धैर्य और स्वीकार करने वाली कक्षा उस चिंता को घटाती है जो हकलाहट को बढ़ाती है; शब्द पूरे करना, उसे जल्दी करवाना या उसे बोलने से बाहर रखना, ये सब आत्मविश्वास घटाते हैं।"},
  {"id":"cdp-child-development-249","question":"A teacher tells a student caught bullying, ‘I don’t accept what you did, and there will be consequences, but I still value you and believe you can do better.’ This reflects Carl Rogers’s idea of:","options":["Conditional positive regard","Negative reinforcement","Authoritarian classroom control","Unconditional positive regard"],"answer":3,"explanation":"Rogers held that accepting the person while disapproving of a behaviour supports a healthy self-concept and growth; regard tied to good behaviour is conditional.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"धमकाने (बुलिंग) में पकड़े गए एक विद्यार्थी से शिक्षक कहती है, ‘तुमने जो किया मैं उसे स्वीकार नहीं करती, और परिणाम होंगे, पर मैं फिर भी तुम्हारी कद्र करती हूँ और मानती हूँ कि तुम बेहतर कर सकते हो।’ यह कार्ल रोजर्स के किस विचार को दर्शाता है?","optionsHi":["सशर्त सकारात्मक सम्मान","ऋणात्मक पुनर्बलन","सत्तावादी कक्षा नियंत्रण","बिना शर्त सकारात्मक सम्मान"],"explanationHi":"रोजर्स का मत था कि किसी व्यवहार को अस्वीकार करते हुए व्यक्ति को स्वीकार करना स्वस्थ आत्म-अवधारणा और विकास का समर्थन करता है; अच्छे व्यवहार से बँधा सम्मान सशर्त होता है।"},
  {"id":"cdp-child-development-250","question":"Which statement about emotion and learning is best supported by research and by NCF 2005?","options":["A safe, supportive climate aids attention and memory; chronic fear impairs them","Emotions are irrelevant to learning, which is a purely cognitive process","Fear of punishment is the most effective way to keep children attentive","Emotions matter only in co-scholastic activities such as sports and music"],"answer":0,"explanation":"Emotion and cognition are intertwined: anxiety narrows attention and hampers working memory, while a secure classroom encourages questioning and exploration.","difficulty":"hard","source":"CTET · State TETs","questionHi":"संवेग और अधिगम के बारे में कौन-सा कथन शोध और NCF 2005 द्वारा सबसे अच्छी तरह समर्थित है?","optionsHi":["सुरक्षित, सहयोगी वातावरण ध्यान और स्मृति में सहायक होता है; दीर्घकालिक भय उन्हें बाधित करता है","संवेग अधिगम के लिए अप्रासंगिक हैं, जो एक विशुद्ध संज्ञानात्मक प्रक्रिया है","दंड का भय बच्चों को ध्यानमग्न रखने का सबसे प्रभावी तरीका है","संवेग केवल खेल और संगीत जैसी सह-शैक्षिक गतिविधियों में मायने रखते हैं"],"explanationHi":"संवेग और संज्ञान आपस में गुँथे हैं: चिंता ध्यान को संकुचित करती है और कार्यकारी स्मृति में बाधा डालती है, जबकि सुरक्षित कक्षा प्रश्न पूछने और अन्वेषण को प्रोत्साहित करती है।"},
  {"id":"cdp-child-development-251","question":"In a Class 3 room in Jaipur, the teacher always rang a brass hand-bell just before scolding the class loudly. Weeks later the children fall silent and tense up at the bell even on days she is calm and does not scold. In this situation the bell is functioning as the:","options":["Conditioned stimulus","Unconditioned stimulus","Conditioned response","Neutral stimulus that is not yet conditioned"],"answer":0,"explanation":"The bell was originally neutral; after repeated pairing with scolding (the unconditioned stimulus) it alone now triggers tension, so it has become a conditioned stimulus. The tension it evokes is the conditioned response.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"जयपुर में कक्षा 3 के एक कमरे में शिक्षिका हमेशा कक्षा को ज़ोर से डाँटने से ठीक पहले पीतल की एक हाथ की घंटी बजाती थी। हफ्तों बाद बच्चे घंटी बजने पर चुप और तनावग्रस्त हो जाते हैं, उन दिनों में भी जब वह शांत होती है और डाँटती नहीं। इस स्थिति में घंटी किस रूप में कार्य कर रही है?","optionsHi":["अनुबंधित उद्दीपक","अनानुबंधित उद्दीपक","अनुबंधित अनुक्रिया","तटस्थ उद्दीपक जो अभी अनुबंधित नहीं हुआ है"],"explanationHi":"घंटी मूलतः तटस्थ थी; डाँट (अनानुबंधित उद्दीपक) के साथ बार-बार जुड़ने के बाद अब अकेली घंटी तनाव उत्पन्न करती है, इसलिए वह अनुबंधित उद्दीपक बन गई है। उससे उत्पन्न तनाव अनुबंधित अनुक्रिया है।"},
  {"id":"cdp-child-development-252","question":"Meenu was humiliated at the blackboard during a maths period in Class 4. Now her heart races not only when she sees her maths notebook but also when she merely sees a geometry box or a page of number puzzles. The spread of her anxiety to these related objects illustrates:","options":["Stimulus discrimination","Stimulus generalisation","Spontaneous recovery","Extinction"],"answer":1,"explanation":"When a conditioned response is evoked by stimuli similar to the original conditioned stimulus, it is stimulus generalisation. Discrimination would be the opposite: responding only to the original stimulus.","difficulty":"moderate","source":"CTET · UPTET","questionHi":"कक्षा 4 में गणित के पीरियड में मीनू को ब्लैकबोर्ड पर अपमानित किया गया। अब उसका दिल न केवल गणित की कॉपी देखने पर तेज़ धड़कता है, बल्कि ज्यामिति बॉक्स या संख्या-पहेलियों का पन्ना देखने पर भी। इन संबंधित वस्तुओं तक उसकी घबराहट का फैलना किसे दर्शाता है?","optionsHi":["उद्दीपक विभेदन","उद्दीपक सामान्यीकरण","स्वतः पुनर्प्राप्ति","विलोपन"],"explanationHi":"जब अनुबंधित अनुक्रिया मूल अनुबंधित उद्दीपक से मिलते-जुलते उद्दीपकों द्वारा उत्पन्न होती है, तो वह उद्दीपक सामान्यीकरण है। विभेदन इसका उलटा होता: केवल मूल उद्दीपक पर अनुक्रिया करना।"},
  {"id":"cdp-child-development-253","question":"A Class 2 child's fear of the school's guard dog was gradually removed after many friendly, harmless encounters. After the two-month summer break, on the first day back, he briefly shows fear again on seeing the dog, though less strongly than before. This reappearance is best explained as:","options":["Stimulus generalisation","Higher-order conditioning","Spontaneous recovery","Negative reinforcement"],"answer":2,"explanation":"A conditioned response that was extinguished can reappear, usually weaker, after a rest interval: Pavlov called this spontaneous recovery. It shows extinction suppresses a response rather than erasing the learning.","difficulty":"hard","source":"CTET Paper 1 · REET","questionHi":"कक्षा 2 के एक बच्चे का विद्यालय के पहरेदार कुत्ते का डर कई मैत्रीपूर्ण, हानिरहित मुलाकातों के बाद धीरे-धीरे दूर हो गया था। दो माह की गर्मी की छुट्टियों के बाद, वापसी के पहले दिन, कुत्ते को देखकर वह थोड़ी देर के लिए फिर डर दिखाता है, हालाँकि पहले से कम तीव्रता से। इस पुनः प्रकट होने का सबसे अच्छा स्पष्टीकरण है:","optionsHi":["उद्दीपक सामान्यीकरण","उच्च-क्रम अनुबंधन","स्वतः पुनर्प्राप्ति","ऋणात्मक पुनर्बलन"],"explanationHi":"जो अनुबंधित अनुक्रिया विलुप्त हो चुकी थी, वह विश्राम अवधि के बाद, प्रायः कमज़ोर रूप में, फिर प्रकट हो सकती है: पावलोव ने इसे स्वतः पुनर्प्राप्ति कहा। यह दिखाता है कि विलोपन अनुक्रिया को दबाता है, अधिगम को मिटाता नहीं।"},
  {"id":"cdp-child-development-254","question":"Using Pavlov's principles, which procedure would extinguish a Class 1 child's conditioned fear of the school's loud assembly siren?","options":["Pair the siren with an even stronger frightening event so the child habituates","Present the frightening event alone many times without the siren","Punish the child each time he shows fear of the siren","Sound the siren repeatedly while nothing frightening follows it"],"answer":3,"explanation":"Classical extinction occurs when the conditioned stimulus is repeatedly presented without the unconditioned stimulus. Punishing fear or adding stronger aversive events would only strengthen or add anxiety.","difficulty":"hard","source":"KVS PRT · DSSSB PRT","questionHi":"पावलोव के सिद्धांतों के अनुसार, विद्यालय के तेज़ सभा-सायरन से कक्षा 1 के एक बच्चे में बने अनुबंधित भय को कौन-सी प्रक्रिया विलुप्त करेगी?","optionsHi":["सायरन को और भी भयावह घटना के साथ जोड़ना ताकि बच्चा अभ्यस्त हो जाए","भयावह घटना को सायरन के बिना अकेले कई बार प्रस्तुत करना","जब भी बच्चा सायरन से डर दिखाए, उसे दंडित करना","सायरन को बार-बार बजाना जबकि उसके बाद कुछ भी भयावह न हो"],"explanationHi":"शास्त्रीय विलोपन तब होता है जब अनुबंधित उद्दीपक को अनानुबंधित उद्दीपक के बिना बार-बार प्रस्तुत किया जाता है। डर के लिए दंड देना या और अधिक प्रतिकूल घटनाएँ जोड़ना केवल चिंता को बढ़ाएगा या जोड़ेगा।"},
  {"id":"cdp-child-development-255","question":"Ms Kaur's frown always came just before she gave detention, so the class learned to fall silent at her frown. Later, she started tapping the duster on the desk just before frowning. Now the duster tap alone silences the class, though it was never directly followed by detention. This is an example of:","options":["Higher-order conditioning","Stimulus generalisation from the frown","Shaping by successive steps","Insight into the teacher's signals"],"answer":0,"explanation":"A new neutral stimulus (duster tap) paired with an already conditioned stimulus (frown) itself becomes conditioned: second-order or higher-order conditioning. Generalisation would need the tap to resemble the frown.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"सुश्री कौर की भौंहें चढ़ना हमेशा उनके डिटेंशन देने से ठीक पहले होता था, इसलिए कक्षा उनकी भौंहें चढ़ने पर चुप होना सीख गई। बाद में उन्होंने भौंहें चढ़ाने से ठीक पहले डस्टर को मेज़ पर थपथपाना शुरू किया। अब केवल डस्टर की थपथप ही कक्षा को चुप करा देती है, जबकि उसके बाद सीधे डिटेंशन कभी नहीं हुआ। यह किसका उदाहरण है?","optionsHi":["उच्च-क्रम अनुबंधन","भौंहें चढ़ने से उद्दीपक सामान्यीकरण","क्रमिक चरणों द्वारा आकारण","शिक्षिका के संकेतों के प्रति अंतर्दृष्टि"],"explanationHi":"एक नया तटस्थ उद्दीपक (डस्टर की थपथप), जो पहले से अनुबंधित उद्दीपक (भौंहें) के साथ जुड़ता है, स्वयं अनुबंधित हो जाता है: द्वितीय-क्रम या उच्च-क्रम अनुबंधन। सामान्यीकरण के लिए थपथप का भौंहों जैसा होना आवश्यक होता।"},
  {"id":"cdp-child-development-256","question":"Consider these statements on classical conditioning. I. The conditioned response is usually similar to, but weaker than, the unconditioned response. II. Conditioning is generally strongest when the conditioned stimulus comes slightly before the unconditioned stimulus. III. Backward pairing, with the unconditioned stimulus first, is usually the most effective arrangement. IV. It mainly explains involuntary, reflex-like responses such as fear or salivation. Which are correct?","options":["I and III only","I, II and IV only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"Forward (delay) pairing, where the CS slightly precedes the UCS, works best; backward pairing produces weak or no conditioning, so III is false. The other three are standard findings.","difficulty":"very-hard","source":"CTET Paper 1 · Super TET","questionHi":"शास्त्रीय अनुबंधन पर इन कथनों पर विचार कीजिए। I. अनुबंधित अनुक्रिया सामान्यतः अनानुबंधित अनुक्रिया के समान पर उससे कमज़ोर होती है। II. अनुबंधन सामान्यतः तब सबसे सशक्त होता है जब अनुबंधित उद्दीपक अनानुबंधित उद्दीपक से थोड़ा पहले आता है। III. पश्च युग्मन, जिसमें अनानुबंधित उद्दीपक पहले आता है, सामान्यतः सबसे प्रभावी व्यवस्था है। IV. यह मुख्यतः भय या लार टपकने जैसी अनैच्छिक, प्रतिवर्त-सदृश अनुक्रियाओं को समझाता है। कौन-से सही हैं?","optionsHi":["केवल I और III","केवल I, II और IV","केवल II, III और IV","I, II, III और IV"],"explanationHi":"अग्र (विलंब) युग्मन, जिसमें CS, UCS से थोड़ा पहले आता है, सबसे अच्छा काम करता है; पश्च युग्मन कमज़ोर या कोई अनुबंधन नहीं देता, इसलिए III गलत है। अन्य तीन मानक निष्कर्ष हैं।"},
  {"id":"cdp-child-development-257","question":"Arjun, in Class 1, is terrified of the school swimming pool. His teacher first lets him sit near the pool eating his favourite snack with his best friend, then dip his feet while chatting, and only weeks later stand in the shallow end. Which principle is the teacher applying?","options":["Negative reinforcement, removing his fear each time he moves closer to the pool","Vicarious punishment of fear by watching a calm friend in the water","Counter-conditioning, pairing the pool with pleasure in graded steps","Insight learning through a sudden restructuring of the whole situation"],"answer":2,"explanation":"Pairing a feared stimulus, in small graded steps, with a response incompatible with fear (relaxation, pleasure) is counter-conditioning or systematic desensitisation, which grows out of classical conditioning.","difficulty":"hard","source":"CTET · HTET","questionHi":"कक्षा 1 का अर्जुन विद्यालय के तरण-ताल से बहुत डरता है। उसके शिक्षक पहले उसे अपने सबसे अच्छे मित्र के साथ अपना पसंदीदा नाश्ता खाते हुए ताल के पास बैठने देते हैं, फिर बातें करते हुए पैर डुबोने देते हैं, और हफ्तों बाद ही उथले सिरे पर खड़े होने देते हैं। शिक्षक कौन-सा सिद्धांत लागू कर रहे हैं?","optionsHi":["ऋणात्मक पुनर्बलन, जो ताल के निकट जाने पर हर बार उसका डर हटाता है","शांत मित्र को पानी में देखकर डर का प्रतिनिधिक दंड","प्रति-अनुबंधन, ताल को क्रमिक चरणों में सुख के साथ जोड़ना","पूरी स्थिति के अचानक पुनर्गठन द्वारा अंतर्दृष्टि अधिगम"],"explanationHi":"किसी भयावह उद्दीपक को छोटे, क्रमिक चरणों में डर के असंगत अनुक्रिया (विश्राम, सुख) से जोड़ना प्रति-अनुबंधन या क्रमिक असंवेदीकरण है, जो शास्त्रीय अनुबंधन से निकला है।"},
  {"id":"cdp-child-development-258","question":"A Class 5 teacher announces a visit to the science lab. The children line up eagerly with notebooks, but at the door she cancels the visit and the children become irritable and restless. Thorndike would explain their annoyance mainly through the:","options":["Law of effect","Law of exercise","Law of multiple response","Law of readiness"],"answer":3,"explanation":"By the law of readiness, when a person is prepared to act, being prevented from acting is annoying. The children were set for the activity and blocking it frustrated them.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 5 की एक शिक्षिका विज्ञान प्रयोगशाला के भ्रमण की घोषणा करती है। बच्चे उत्साह से कॉपियाँ लेकर पंक्ति में खड़े हो जाते हैं, पर दरवाज़े पर वह भ्रमण रद्द कर देती है और बच्चे चिड़चिड़े और बेचैन हो जाते हैं। थॉर्नडाइक उनकी खीझ को मुख्यतः किस नियम से समझाते?","optionsHi":["प्रभाव का नियम","अभ्यास का नियम","बहु-अनुक्रिया का नियम","तत्परता का नियम"],"explanationHi":"तत्परता के नियम के अनुसार, जब व्यक्ति कार्य करने को तैयार हो, तो उसे कार्य करने से रोका जाना खीझ पैदा करता है। बच्चे गतिविधि के लिए तैयार थे और उसे रोकना उन्हें निराश कर गया।"},
  {"id":"cdp-child-development-259","question":"In his later work (1930s), Thorndike revised his own laws of learning. Which revision did he actually make?","options":["He gave repetition less weight and found punishment weakens bonds far less than reward strengthens them","He dropped the law of effect entirely and kept only the law of exercise, since practice alone builds bonds","He made the law of readiness the master law, replacing the law of effect as the basis of all learning","He concluded that repetition without any feedback is the strongest single factor in fixing a response"],"answer":0,"explanation":"Thorndike found that repetition alone does little without satisfying consequences, and that the 'annoyer' half of the law of effect is weak: reward strengthens connections far more than punishment weakens them.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"अपने बाद के कार्य (1930 के दशक) में थॉर्नडाइक ने अपने ही अधिगम के नियमों में संशोधन किया। उन्होंने वास्तव में कौन-सा संशोधन किया?","optionsHi":["उन्होंने पुनरावृत्ति को कम महत्व दिया और पाया कि दंड संबंधों को उतना कमज़ोर नहीं करता जितना पुरस्कार उन्हें सुदृढ़ करता है","उन्होंने प्रभाव का नियम पूरी तरह छोड़ दिया और केवल अभ्यास का नियम रखा, क्योंकि केवल अभ्यास ही संबंध बनाता है","उन्होंने तत्परता के नियम को प्रमुख नियम बना दिया, जो सभी अधिगम के आधार के रूप में प्रभाव के नियम की जगह लेता है","उन्होंने निष्कर्ष निकाला कि किसी भी प्रतिपुष्टि के बिना पुनरावृत्ति किसी अनुक्रिया को स्थिर करने का सबसे प्रबल एकल कारक है"],"explanationHi":"थॉर्नडाइक ने पाया कि संतोषजनक परिणामों के बिना केवल पुनरावृत्ति से बहुत कम होता है, और प्रभाव के नियम का ‘खिझाने वाला’ भाग कमज़ोर है: पुरस्कार संबंधों को दंड के कमज़ोर करने से कहीं अधिक सुदृढ़ करता है।"},
  {"id":"cdp-child-development-260","question":"Riya mastered her multiplication tables in Class 3 but did not use them at all during a long illness. When she returned months later she had forgotten many of them. Which of Thorndike's laws best accounts for this?","options":["Law of readiness, since illness left her unprepared","Law of exercise, through its law of disuse","Law of effect, through the annoyance of illness","Law of associative shifting to new contexts"],"answer":1,"explanation":"The law of exercise has two parts, use and disuse: connections that are not practised weaken over time. Riya's loss came from disuse, not from an annoying consequence.","difficulty":"moderate","source":"CTET · REET","questionHi":"रिया ने कक्षा 3 में गुणा की पहाड़े याद कर लिए थे, पर लंबी बीमारी के दौरान उनका बिल्कुल उपयोग नहीं किया। महीनों बाद लौटने पर वह उनमें से कई भूल चुकी थी। थॉर्नडाइक का कौन-सा नियम इसे सबसे अच्छी तरह समझाता है?","optionsHi":["तत्परता का नियम, क्योंकि बीमारी ने उसे तैयार नहीं छोड़ा","अभ्यास का नियम, अपने अनुपयोग के नियम के माध्यम से","प्रभाव का नियम, बीमारी की खीझ के माध्यम से","नए संदर्भों में सहचारी स्थानांतरण का नियम"],"explanationHi":"अभ्यास के नियम के दो भाग हैं, उपयोग और अनुपयोग: जिन संबंधों का अभ्यास नहीं होता वे समय के साथ कमज़ोर पड़ जाते हैं। रिया की हानि अनुपयोग से हुई, किसी खिझाने वाले परिणाम से नहीं।"},
  {"id":"cdp-child-development-261","question":"Which observation most clearly separates Thorndike's puzzle-box learning in cats from Köhler's insight learning in chimpanzees?","options":["Thorndike's cats were rewarded with food on escaping, while Köhler's apes received no reward","Köhler's apes needed many more trials than Thorndike's cats before reaching a solution","In Thorndike's work escape time fell gradually and irregularly, with no sudden solution","Thorndike's cats solved the box only after watching other cats escape from it first"],"answer":2,"explanation":"Trial-and-error learning shows a gradual, irregular learning curve; insight shows a sudden drop once the relationships are grasped. Köhler's apes also received food (bananas), and Thorndike's cats did not learn by observation.","difficulty":"hard","source":"CTET Paper 2 · UPTET","questionHi":"कौन-सा अवलोकन बिल्लियों में थॉर्नडाइक के पहेली-पिंजरे अधिगम को चिंपैंजियों में कोहलर के अंतर्दृष्टि अधिगम से सबसे स्पष्ट रूप से अलग करता है?","optionsHi":["थॉर्नडाइक की बिल्लियों को बचकर निकलने पर भोजन से पुरस्कृत किया गया, जबकि कोहलर के वानरों को कोई पुरस्कार नहीं मिला","कोहलर के वानरों को समाधान तक पहुँचने से पहले थॉर्नडाइक की बिल्लियों से कहीं अधिक प्रयास करने पड़े","थॉर्नडाइक के कार्य में बचकर निकलने का समय धीरे-धीरे और अनियमित रूप से घटा, बिना किसी अचानक समाधान के","थॉर्नडाइक की बिल्लियाँ पिंजरा तभी हल कर सकीं जब उन्होंने पहले अन्य बिल्लियों को उससे निकलते देखा"],"explanationHi":"प्रयास और त्रुटि अधिगम एक क्रमिक, अनियमित अधिगम वक्र दिखाता है; अंतर्दृष्टि संबंधों को समझ लेने पर अचानक गिरावट दिखाती है। कोहलर के वानरों को भी भोजन (केले) मिला, और थॉर्नडाइक की बिल्लियाँ अवलोकन से नहीं सीखीं।"},
  {"id":"cdp-child-development-262","question":"A Class 2 child who has learnt to knock and say ‘May I come in?’ at the classroom door does the same, unprompted, on reaching the principal's office for the first time. Among Thorndike's subsidiary laws, this response to a new situation in the way one responded to a similar familiar one is the law of:","options":["Set or attitude","Partial activity or prepotency","Multiple response","Assimilation or analogy"],"answer":3,"explanation":"Thorndike's law of assimilation (analogy) says a learner responds to a new situation as he did to a similar one already learnt. Multiple response refers to trying varied responses until one succeeds.","difficulty":"hard","source":"DSSSB PRT · KVS PRT","questionHi":"कक्षा 2 का एक बच्चा, जिसने कक्षा के दरवाज़े पर खटखटाना और ‘क्या मैं अंदर आ सकता हूँ?’ कहना सीखा है, प्रधानाचार्य के कार्यालय पर पहली बार पहुँचने पर बिना कहे वही करता है। थॉर्नडाइक के सहायक नियमों में, किसी नई स्थिति में उसी तरह प्रतिक्रिया करना जैसे किसी समान परिचित स्थिति में की थी, किस नियम का उदाहरण है?","optionsHi":["मनोवृत्ति या अभिवृत्ति","आंशिक क्रिया या प्रभुत्व","बहु-अनुक्रिया","आत्मसात्करण या सादृश्य"],"explanationHi":"थॉर्नडाइक का आत्मसात्करण (सादृश्य) का नियम कहता है कि अधिगमकर्ता किसी नई स्थिति में वैसे ही अनुक्रिया करता है जैसे किसी समान, पहले सीखी स्थिति में की थी। बहु-अनुक्रिया का अर्थ है विभिन्न अनुक्रियाएँ तब तक आज़माना जब तक एक सफल न हो।"},
  {"id":"cdp-child-development-263","question":"Which classroom practice is the most direct application of Thorndike's law of effect?","options":["Making sure a beginner's correct attempt is promptly followed by success or approval","Asking children to copy each new word twenty times so the bond is fixed by practice","Starting a lesson only when children seem physically and mentally ready to write","Teaching each topic in small separate parts before showing children the whole"],"answer":0,"explanation":"The law of effect says responses followed by satisfying consequences are strengthened. Repeated copying reflects the law of exercise and starting when ready reflects the law of readiness.","difficulty":"moderate","source":"CTET Paper 1 · Super TET","questionHi":"कौन-सी कक्षा-पद्धति थॉर्नडाइक के प्रभाव के नियम का सबसे सीधा अनुप्रयोग है?","optionsHi":["यह सुनिश्चित करना कि नौसिखिए के सही प्रयास के तुरंत बाद सफलता या स्वीकृति मिले","बच्चों से हर नया शब्द बीस बार लिखवाना ताकि संबंध अभ्यास से स्थिर हो जाए","पाठ तभी शुरू करना जब बच्चे शारीरिक और मानसिक रूप से लिखने को तैयार दिखें","बच्चों को पूरा दिखाने से पहले हर विषय को छोटे अलग-अलग भागों में पढ़ाना"],"explanationHi":"प्रभाव का नियम कहता है कि संतोषजनक परिणामों वाली अनुक्रियाएँ सुदृढ़ होती हैं। बार-बार नकल करना अभ्यास के नियम को दर्शाता है और तैयार होने पर शुरू करना तत्परता के नियम को।"},
  {"id":"cdp-child-development-264","question":"A Class 7 teacher announces that anyone who submits every homework this week will be excused from the Saturday extra worksheet. Homework submission rises sharply. The teacher has used:","options":["Positive punishment","Negative reinforcement","Negative punishment","Positive reinforcement"],"answer":1,"explanation":"Removing something unpleasant (the extra worksheet) to increase a behaviour is negative reinforcement. Any reinforcement, positive or negative, increases behaviour; punishment decreases it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक शिक्षिका घोषणा करती है कि जो भी इस सप्ताह हर गृहकार्य जमा करेगा, उसे शनिवार की अतिरिक्त कार्यपत्रिका से छूट मिलेगी। गृहकार्य जमा करना तेज़ी से बढ़ता है। शिक्षिका ने क्या प्रयोग किया है?","optionsHi":["धनात्मक दंड","ऋणात्मक पुनर्बलन","ऋणात्मक दंड","धनात्मक पुनर्बलन"],"explanationHi":"किसी व्यवहार को बढ़ाने के लिए कोई अप्रिय चीज़ (अतिरिक्त कार्यपत्रिका) हटाना ऋणात्मक पुनर्बलन है। कोई भी पुनर्बलन, धनात्मक या ऋणात्मक, व्यवहार को बढ़ाता है; दंड उसे घटाता है।"},
  {"id":"cdp-child-development-265","question":"Whenever Kabir throws chalk in class he loses ten minutes of his games period, and soon he stops throwing chalk. In operant terms the teacher has used:","options":["Negative reinforcement","Positive punishment","Negative punishment","Extinction"],"answer":2,"explanation":"Taking away something pleasant (games time) to reduce a behaviour is negative punishment (response cost). Negative reinforcement would increase a behaviour by removing something unpleasant.","difficulty":"hard","source":"CTET · HTET","questionHi":"जब भी कबीर कक्षा में चॉक फेंकता है, उसके खेल के पीरियड के दस मिनट कट जाते हैं, और जल्द ही वह चॉक फेंकना बंद कर देता है। क्रियाप्रसूत शब्दावली में शिक्षक ने क्या प्रयोग किया है?","optionsHi":["ऋणात्मक पुनर्बलन","धनात्मक दंड","ऋणात्मक दंड","विलोपन"],"explanationHi":"किसी व्यवहार को घटाने के लिए कोई सुखद चीज़ (खेल का समय) छीनना ऋणात्मक दंड (प्रतिक्रिया-मूल्य) है। ऋणात्मक पुनर्बलन किसी अप्रिय चीज़ को हटाकर व्यवहार को बढ़ाता।"},
  {"id":"cdp-child-development-266","question":"A Class 8 science teacher gives short surprise quizzes at unpredictable times, sometimes twice a week and sometimes once in ten days. Students now revise steadily every day. Reinforcement for revising is being delivered on which schedule?","options":["Continuous reinforcement","Fixed interval","Variable ratio","Variable interval"],"answer":3,"explanation":"Reinforcement becomes available after unpredictable lengths of time, which is a variable-interval schedule; it produces steady, moderate responding without the end-of-period cramming of fixed intervals.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 8 का एक विज्ञान शिक्षक अप्रत्याशित समय पर छोटी औचक क्विज़ लेता है, कभी सप्ताह में दो बार और कभी दस दिन में एक बार। विद्यार्थी अब हर दिन नियमित रूप से दोहराते हैं। दोहराने के लिए पुनर्बलन किस अनुसूची पर दिया जा रहा है?","optionsHi":["सतत पुनर्बलन","स्थिर अंतराल","परिवर्ती अनुपात","परिवर्ती अंतराल"],"explanationHi":"पुनर्बलन अप्रत्याशित अवधियों के बाद उपलब्ध होता है, जो परिवर्ती-अंतराल अनुसूची है; यह स्थिर अंतरालों की अवधि-अंत की रटाई के बिना स्थिर, मध्यम अनुक्रिया पैदा करती है।"},
  {"id":"cdp-child-development-267","question":"A school holds its monthly unit test on the last Friday of every month. Teachers notice students barely study in the first three weeks and cram heavily in the final week, then slack again after the test. This pattern is typical of a:","options":["Fixed-interval schedule","Variable-interval schedule","Fixed-ratio schedule","Continuous reinforcement schedule"],"answer":0,"explanation":"Predictable time-based reinforcement produces the fixed-interval 'scallop': low responding just after reinforcement, rising sharply as the known time approaches.","difficulty":"hard","source":"KVS TGT · NVS TGT","questionHi":"एक विद्यालय अपनी मासिक इकाई परीक्षा हर महीने के अंतिम शुक्रवार को लेता है। शिक्षक देखते हैं कि विद्यार्थी पहले तीन सप्ताह मुश्किल से पढ़ते हैं और अंतिम सप्ताह में जमकर रटते हैं, फिर परीक्षा के बाद फिर ढीले पड़ जाते हैं। यह प्रतिरूप किस अनुसूची की विशिष्टता है?","optionsHi":["स्थिर-अंतराल अनुसूची","परिवर्ती-अंतराल अनुसूची","स्थिर-अनुपात अनुसूची","सतत पुनर्बलन अनुसूची"],"explanationHi":"पूर्वानुमेय समय-आधारित पुनर्बलन स्थिर-अंतराल का ‘स्कैलप’ उत्पन्न करता है: पुनर्बलन के तुरंत बाद कम अनुक्रिया, जो ज्ञात समय निकट आने पर तेज़ी से बढ़ती है।"},
  {"id":"cdp-child-development-268","question":"Assertion (A): A child's habit of whining for sweets, rewarded by a parent only occasionally and unpredictably, is very hard to extinguish. Reason (R): Under a variable-ratio schedule the learner has often gone unrewarded before, so a run of unrewarded responses does not signal that reward has stopped.","options":["A is true but R is false","Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":1,"explanation":"Behaviour on a variable-ratio schedule is the most resistant to extinction precisely because non-reward is normal under it, so the learner cannot easily detect that reinforcement has ended.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): मिठाई के लिए बच्चे की ज़िद करने की आदत, जिसे माता-पिता कभी-कभार और अप्रत्याशित रूप से पुरस्कृत करते हैं, को विलुप्त करना बहुत कठिन होता है। कारण (R): परिवर्ती-अनुपात अनुसूची में अधिगमकर्ता प्रायः बिना पुरस्कार के रहा होता है, इसलिए बिना पुरस्कार की अनुक्रियाओं की शृंखला यह संकेत नहीं देती कि पुरस्कार बंद हो गया है।","optionsHi":["A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A असत्य है परंतु R सत्य है"],"explanationHi":"परिवर्ती-अनुपात अनुसूची पर व्यवहार विलोपन का सबसे अधिक प्रतिरोध करता है, ठीक इसलिए कि उसमें पुरस्कार न मिलना सामान्य है, इसलिए अधिगमकर्ता आसानी से पता नहीं लगा पाता कि पुनर्बलन समाप्त हो गया है।"},
  {"id":"cdp-child-development-269","question":"Tanvi, a Class 1 child, does not speak at all in school. Her teacher first praises her for nodding, then for whispering to a friend, then for whispering to the teacher, and finally for saying a word aloud in a small group. The teacher is using:","options":["Forward chaining of already learnt steps","Extinction of silence","Shaping by successive approximations","Vicarious reinforcement"],"answer":2,"explanation":"Reinforcing closer and closer approximations of a target behaviour that the child cannot yet produce is shaping. Chaining links already learnt steps into a sequence.","difficulty":"moderate","source":"CTET · REET","questionHi":"कक्षा 1 की तन्वी विद्यालय में बिल्कुल नहीं बोलती। उसकी शिक्षिका पहले उसके सिर हिलाने की, फिर मित्र से फुसफुसाने की, फिर शिक्षिका से फुसफुसाने की, और अंत में छोटे समूह में एक शब्द ज़ोर से बोलने की प्रशंसा करती है। शिक्षिका क्या प्रयोग कर रही है?","optionsHi":["पहले से सीखे चरणों की अग्र शृंखलाबद्धता","चुप्पी का विलोपन","क्रमिक सन्निकटनों द्वारा आकारण","प्रतिनिधिक पुनर्बलन"],"explanationHi":"किसी लक्ष्य व्यवहार के, जिसे बच्चा अभी उत्पन्न नहीं कर सकता, अधिकाधिक निकट सन्निकटनों को पुनर्बलित करना आकारण है। शृंखलाबद्धता पहले से सीखे चरणों को एक क्रम में जोड़ती है।"},
  {"id":"cdp-child-development-270","question":"A teacher wants Class 3 children to quickly learn the habit of writing the date on every page and then keep doing it for the rest of the year. Which reinforcement plan best fits operant research?","options":["Reinforce only now and then from the very first day, so the habit never depends on reward","Reinforce every instance throughout the whole year, so the habit never weakens","Reinforce every instance at first and then stop all reinforcement at once","Reinforce every instance at first, then gradually shift to intermittent reinforcement"],"answer":3,"explanation":"Continuous reinforcement gives the fastest acquisition, while intermittent reinforcement gives the greatest persistence; thinning from one to the other gives both. Stopping abruptly invites extinction.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक शिक्षिका चाहती है कि कक्षा 3 के बच्चे हर पन्ने पर तारीख लिखने की आदत जल्दी सीखें और फिर पूरे वर्ष उसे करते रहें। क्रियाप्रसूत शोध के अनुसार कौन-सी पुनर्बलन योजना सबसे उपयुक्त है?","optionsHi":["पहले ही दिन से केवल कभी-कभार पुनर्बलित करना, ताकि आदत कभी पुरस्कार पर निर्भर न हो","पूरे वर्ष हर बार पुनर्बलित करना, ताकि आदत कभी कमज़ोर न हो","शुरू में हर बार पुनर्बलित करना और फिर सारा पुनर्बलन एकदम बंद कर देना","शुरू में हर बार पुनर्बलित करना, फिर धीरे-धीरे आंतरायिक पुनर्बलन की ओर बढ़ना"],"explanationHi":"सतत पुनर्बलन सबसे तेज़ अर्जन देता है, जबकि आंतरायिक पुनर्बलन सबसे अधिक टिकाऊपन देता है; एक से दूसरे की ओर धीरे-धीरे बढ़ना दोनों देता है। अचानक रोक देना विलोपन को निमंत्रण देता है।"},
  {"id":"cdp-child-development-271","question":"Rohan used to call out answers and the teacher always responded to him. She now decides to ignore every call-out and attend only when he raises his hand. In the first few days his calling out becomes louder and more frequent. What should she do?","options":["Treat it as an expected extinction burst; stay consistent and reinforce hand-raising","Conclude that ignoring has failed and switch to scolding him firmly in front of the class","Respond to him occasionally so that he calms down and the burst passes sooner","Move him to the back of the room so his calling out disturbs fewer children"],"answer":0,"explanation":"A temporary surge when reinforcement is withdrawn is an extinction burst. Giving in occasionally would place calling out on an intermittent schedule and make it even harder to extinguish.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"रोहन बीच में उत्तर बोल देता था और शिक्षिका हमेशा उसे प्रतिक्रिया देती थीं। अब वे हर बीच में बोलने की अनदेखी करने और केवल तभी ध्यान देने का निर्णय लेती हैं जब वह हाथ उठाए। पहले कुछ दिनों में उसका बीच में बोलना ज़ोर से और अधिक बार होने लगता है। उन्हें क्या करना चाहिए?","optionsHi":["इसे अपेक्षित विलोपन विस्फोट मानना; निरंतरता बनाए रखना और हाथ उठाने को पुनर्बलित करना","निष्कर्ष निकालना कि अनदेखी विफल हो गई और कक्षा के सामने उसे कड़ाई से डाँटना","कभी-कभी उसे प्रतिक्रिया देना ताकि वह शांत हो जाए और विस्फोट जल्दी गुज़र जाए","उसे कमरे में पीछे बैठा देना ताकि उसका बीच में बोलना कम बच्चों को बाधित करे"],"explanationHi":"पुनर्बलन हटाने पर व्यवहार में अस्थायी उछाल विलोपन विस्फोट है। कभी-कभी हार मान लेना बीच में बोलने को आंतरायिक अनुसूची पर रख देगा और उसे विलुप्त करना और कठिन बना देगा।"},
  {"id":"cdp-child-development-272","question":"A Class 4 teacher tells a child who dislikes arithmetic but loves drawing: ‘Finish these five sums and then you may paint for the rest of the period.’ The arithmetic work increases. Which principle is being used?","options":["Law of readiness","Premack principle","Negative reinforcement","Vicarious reinforcement"],"answer":1,"explanation":"Using a preferred, high-frequency activity (painting) as the reinforcer for a less preferred one (sums) is the Premack principle, sometimes called 'Grandma's rule'.","difficulty":"hard","source":"KVS PRT · Super TET","questionHi":"कक्षा 4 की एक शिक्षिका अंकगणित को नापसंद करने पर भी चित्रकारी को पसंद करने वाले बच्चे से कहती है: ‘ये पाँच सवाल पूरे करो और फिर बाकी पीरियड चित्र बना सकते हो।’ अंकगणित का कार्य बढ़ जाता है। कौन-सा सिद्धांत प्रयोग हो रहा है?","optionsHi":["तत्परता का नियम","प्रेमैक सिद्धांत","ऋणात्मक पुनर्बलन","प्रतिनिधिक पुनर्बलन"],"explanationHi":"कम पसंदीदा गतिविधि (सवाल) के लिए पुनर्बलक के रूप में किसी पसंदीदा, उच्च-आवृत्ति गतिविधि (चित्रकारी) का उपयोग प्रेमैक सिद्धांत है, जिसे कभी-कभी ‘दादी माँ का नियम’ कहा जाता है।"},
  {"id":"cdp-child-development-273","question":"Which of the following is NOT a feature of Skinner's programmed instruction?","options":["Material broken into small, logically ordered steps called frames","The learner makes an active, written response in every single frame","The learner moves on only after the teacher grades the whole unit","Each learner works through the programme at his or her own pace"],"answer":2,"explanation":"Programmed instruction relies on immediate feedback after each frame; delaying feedback until the end of a unit violates the principle of immediate reinforcement.","difficulty":"moderate","source":"CTET · DSSSB PRT","questionHi":"निम्नलिखित में से कौन-सा स्किनर के अभिक्रमित अनुदेशन की विशेषता नहीं है?","optionsHi":["सामग्री छोटे, तार्किक रूप से क्रमबद्ध चरणों में विभाजित, जिन्हें फ्रेम कहते हैं","अधिगमकर्ता हर एक फ्रेम में सक्रिय, लिखित अनुक्रिया करता है","अधिगमकर्ता तभी आगे बढ़ता है जब शिक्षक पूरी इकाई को अंक दे दे","प्रत्येक अधिगमकर्ता कार्यक्रम को अपनी गति से पूरा करता है"],"explanationHi":"अभिक्रमित अनुदेशन प्रत्येक फ्रेम के बाद तत्काल प्रतिपुष्टि पर निर्भर करता है; इकाई के अंत तक प्रतिपुष्टि में देरी करना तत्काल पुनर्बलन के सिद्धांत का उल्लंघन है।"},
  {"id":"cdp-child-development-274","question":"Which of these statements about punishment in school are supported by behavioural research and Indian law? I. Punishment tends to suppress a behaviour without teaching what to do instead. II. Repeated punishment can make the teacher herself a conditioned stimulus for fear. III. Mild physical punishment is permitted under the RTE Act if parents consent. IV. If any punishment is used, it is more effective when immediate and consistent.","options":["I and II only","II and III only","I, III and IV only","I, II and IV only"],"answer":3,"explanation":"Section 17 of the RTE Act, 2009 prohibits physical punishment and mental harassment, so III is false. The other statements reflect well-known behavioural findings about punishment.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"विद्यालय में दंड के बारे में इनमें से कौन-से कथन व्यवहारात्मक शोध और भारतीय कानून से समर्थित हैं? I. दंड किसी व्यवहार को दबाता है, यह सिखाए बिना कि उसकी जगह क्या करना है। II. बार-बार का दंड शिक्षक को ही भय का अनुबंधित उद्दीपक बना सकता है। III. यदि माता-पिता सहमत हों तो RTE अधिनियम के अंतर्गत हल्का शारीरिक दंड स्वीकृत है। IV. यदि कोई दंड प्रयोग किया जाए, तो वह तत्काल और सुसंगत होने पर अधिक प्रभावी होता है।","optionsHi":["केवल I और II","केवल II और III","केवल I, III और IV","केवल I, II और IV"],"explanationHi":"RTE अधिनियम, 2009 की धारा 17 शारीरिक दंड और मानसिक उत्पीड़न को प्रतिबंधित करती है, इसलिए III गलत है। अन्य कथन दंड के बारे में प्रसिद्ध व्यवहारात्मक निष्कर्षों को दर्शाते हैं।"},
  {"id":"cdp-child-development-275","question":"A Class 2 teacher runs a token system: children earn stars for finishing work, and ten stars can be exchanged for extra library time. In behavioural terms, the stars are:","options":["Primary reinforcers, valued for their own sake","Unconditioned stimuli for working","Secondary (conditioned) reinforcers","Negative reinforcers that remove boredom"],"answer":2,"explanation":"Stars have no value in themselves; they become reinforcing through their link with something valued, which makes them secondary or conditioned reinforcers. Primary reinforcers satisfy biological needs.","difficulty":"moderate","source":"CTET Paper 1 · REET","questionHi":"कक्षा 2 की एक शिक्षिका टोकन प्रणाली चलाती है: बच्चे कार्य पूरा करने पर सितारे कमाते हैं, और दस सितारे अतिरिक्त पुस्तकालय समय से बदले जा सकते हैं। व्यवहारात्मक दृष्टि से सितारे हैं:","optionsHi":["प्राथमिक पुनर्बलक, जिनका अपने आप में मूल्य है","कार्य करने के लिए अनानुबंधित उद्दीपक","द्वितीयक (अनुबंधित) पुनर्बलक","ऋणात्मक पुनर्बलक जो ऊब हटाते हैं"],"explanationHi":"सितारों का अपने आप में कोई मूल्य नहीं है; वे किसी मूल्यवान वस्तु से जुड़ने के कारण पुनर्बलक बनते हैं, जो उन्हें द्वितीयक या अनुबंधित पुनर्बलक बनाता है। प्राथमिक पुनर्बलक जैविक आवश्यकताओं को पूरा करते हैं।"},
  {"id":"cdp-child-development-276","question":"In a Class 6 classroom in Jaipur, Ravi solves every arithmetic puzzle in the textbook quickly, but when friends must share a limited budget for a cricket kit fairly among players with different needs, he cannot find a workable plan. Salma, an average scorer in written tests, quickly proposes an arrangement everyone accepts. In Sternberg’s triarchic theory, Salma’s strength lies mainly in:","options":["Componential (analytical) intelligence","Contextual (practical) intelligence","Experiential (creative) intelligence","Interpersonal intelligence"],"answer":1,"explanation":"Solving real-life problems in one’s everyday setting is Sternberg’s contextual or practical intelligence; ‘interpersonal intelligence’ belongs to Gardner’s theory, not Sternberg’s, and Ravi’s puzzle skill is the analytical (componential) part.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"जयपुर की कक्षा 6 में रवि पाठ्यपुस्तक की हर अंकगणितीय पहेली जल्दी हल कर लेता है, पर जब मित्रों को अलग-अलग ज़रूरतों वाले खिलाड़ियों के बीच क्रिकेट किट के लिए सीमित बजट निष्पक्ष रूप से बाँटना होता है, तो वह कोई कारगर योजना नहीं खोज पाता। सलमा, जो लिखित परीक्षाओं में औसत अंक लाती है, जल्दी ही ऐसी व्यवस्था प्रस्तावित करती है जो सबको मान्य होती है। स्टर्नबर्ग के त्रितंत्र सिद्धांत में सलमा की शक्ति मुख्यतः किसमें है?","optionsHi":["घटकीय (विश्लेषणात्मक) बुद्धि","संदर्भगत (व्यावहारिक) बुद्धि","अनुभवात्मक (सृजनात्मक) बुद्धि","अंतर्वैयक्तिक बुद्धि"],"explanationHi":"अपने रोज़मर्रा के परिवेश में वास्तविक जीवन की समस्याएँ हल करना स्टर्नबर्ग की संदर्भगत या व्यावहारिक बुद्धि है; ‘अंतर्वैयक्तिक बुद्धि’ गार्डनर के सिद्धांत की है, स्टर्नबर्ग के नहीं, और रवि का पहेली कौशल विश्लेषणात्मक (घटकीय) भाग है।"},
  {"id":"cdp-child-development-277","question":"Which of the following statements about Howard Gardner’s theory are correct? I. Frames of Mind (1983) originally proposed seven intelligences. II. Naturalist intelligence was added to the list later. III. Gardner treats each intelligence as the same thing as a learning style. IV. Gardner argued that each intelligence can be measured adequately by a short paper-and-pencil test.","options":["I, II and III only","II and IV only","I and II only","I, III and IV only"],"answer":2,"explanation":"Gardner began with seven intelligences and added the naturalist one in the 1990s. He has explicitly rejected equating intelligences with learning styles and criticised reliance on short written tests, so III and IV are false.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"हॉवर्ड गार्डनर के सिद्धांत के बारे में निम्नलिखित में से कौन-से कथन सही हैं? I. ‘फ्रेम्स ऑफ माइंड’ (1983) ने मूलतः सात बुद्धियाँ प्रस्तावित कीं। II. प्रकृतिवादी बुद्धि को सूची में बाद में जोड़ा गया। III. गार्डनर प्रत्येक बुद्धि को अधिगम शैली के समान मानते हैं। IV. गार्डनर ने तर्क दिया कि प्रत्येक बुद्धि को छोटे कागज़-पेंसिल परीक्षण से पर्याप्त रूप से मापा जा सकता है।","optionsHi":["केवल I, II और III","केवल II और IV","केवल I और II","केवल I, III और IV"],"explanationHi":"गार्डनर ने सात बुद्धियों से शुरुआत की और 1990 के दशक में प्रकृतिवादी बुद्धि जोड़ी। उन्होंने बुद्धियों को अधिगम शैलियों के बराबर मानने को स्पष्ट रूप से अस्वीकार किया और छोटे लिखित परीक्षणों पर निर्भरता की आलोचना की, इसलिए III और IV गलत हैं।"},
  {"id":"cdp-child-development-278","question":"Assertion (A): A student who scores well above average in mathematics is, on the whole, also likely to score somewhat above average in language tests. Reason (R): Spearman held that a general factor, ‘g’, enters into performance on all intellectual tasks, along with specific factors for each task.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Scores on different mental tests correlate positively (the ‘positive manifold’); Spearman explained this by a common g factor, with s factors accounting for the differences between tasks.","difficulty":"hard","source":"CTET · State TET","questionHi":"अभिकथन (A): जो विद्यार्थी गणित में औसत से बहुत ऊपर अंक लाता है, उसके भाषा परीक्षणों में भी कुल मिलाकर औसत से कुछ ऊपर अंक लाने की संभावना होती है। कारण (R): स्पीयरमैन का मत था कि एक सामान्य कारक ‘g’ सभी बौद्धिक कार्यों के निष्पादन में प्रवेश करता है, साथ ही प्रत्येक कार्य के लिए विशिष्ट कारक भी।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"विभिन्न मानसिक परीक्षणों के अंक धनात्मक रूप से सहसंबद्ध होते हैं (‘धनात्मक अनेकता’); स्पीयरमैन ने इसे एक साझा g कारक से समझाया, जिसमें s कारक कार्यों के बीच के अंतर को बताते हैं।"},
  {"id":"cdp-child-development-279","question":"Which of the following tasks is the clearest example of what J. P. Guilford called ‘convergent production’?","options":["Suggesting as many titles as possible for a story read in class","Writing three different endings for a folk tale the class has just heard","Completing the analogy ‘Hand : Glove :: Foot : ?’ with one word","Listing as many unusual uses as possible for an old bicycle tyre"],"answer":2,"explanation":"Convergent production narrows to a single correct answer, as in an analogy with one right completion; the other three tasks ask for many varied responses, which is divergent production.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"निम्नलिखित में से कौन-सा कार्य जे. पी. गिलफोर्ड द्वारा कहे गए ‘अभिसारी उत्पादन’ का सबसे स्पष्ट उदाहरण है?","optionsHi":["कक्षा में पढ़ी गई कहानी के लिए यथासंभव अधिक शीर्षक सुझाना","कक्षा द्वारा अभी सुनी गई लोककथा के तीन अलग-अलग अंत लिखना","सादृश्य ‘Hand : Glove :: Foot : ?’ को एक शब्द से पूरा करना","पुराने साइकिल टायर के यथासंभव अधिक असामान्य उपयोगों की सूची बनाना"],"explanationHi":"अभिसारी उत्पादन एक ही सही उत्तर तक सीमित होता है, जैसे उस सादृश्य में जिसका एक सही समापन है; अन्य तीन कार्य अनेक विविध अनुक्रियाएँ माँगते हैं, जो अपसारी उत्पादन है।"},
  {"id":"cdp-child-development-280","question":"A test battery used in a Bhopal school reports separate scores for verbal comprehension, word fluency, number, space, associative memory, perceptual speed and reasoning, and deliberately gives no single overall score. The test designer’s view of intelligence is closest to that of:","options":["Spearman’s two-factor theory","Cattell’s fluid and crystallised intelligence","Jensen’s Level I and Level II abilities","Thurstone’s primary mental abilities"],"answer":3,"explanation":"Thurstone identified seven primary mental abilities (exactly the seven listed) and initially rejected a single dominant g, so a profile without one overall score reflects his view.","difficulty":"hard","source":"KVS PGT · DSSSB TGT","questionHi":"भोपाल के एक विद्यालय में प्रयुक्त एक परीक्षण बैटरी शाब्दिक बोध, शब्द प्रवाह, संख्या, स्थान, साहचर्य स्मृति, प्रत्यक्षण गति और तर्क के अलग-अलग अंक बताती है, और जानबूझकर कोई एक समग्र अंक नहीं देती। परीक्षण-निर्माता की बुद्धि संबंधी दृष्टि सबसे अधिक किसके निकट है?","optionsHi":["स्पीयरमैन का द्विकारक सिद्धांत","कैटल की तरल और मूर्त बुद्धि","जेन्सन की स्तर I और स्तर II योग्यताएँ","थर्स्टन की प्राथमिक मानसिक योग्यताएँ"],"explanationHi":"थर्स्टन ने सात प्राथमिक मानसिक योग्यताएँ पहचानीं (ठीक वही सात जो सूचीबद्ध हैं) और शुरू में किसी एक प्रबल g को अस्वीकार किया, इसलिए एक समग्र अंक के बिना प्रोफ़ाइल उनके दृष्टिकोण को दर्शाती है।"},
  {"id":"cdp-child-development-281","question":"A 68-year-old retired Hindi teacher in Varanasi has a richer vocabulary and general knowledge than ever, but she now solves unfamiliar timed pattern puzzles more slowly than she did at 25. This pattern is best explained by the view that:","options":["Crystallised ability is kept or grows with age while fluid ability tends to decline","Fluid intelligence keeps growing with age while crystallised intelligence steadily declines","General intelligence (g) declines equally across all abilities after middle age","Her linguistic intelligence has gradually replaced her logical-mathematical intelligence"],"answer":0,"explanation":"In Cattell’s model, crystallised intelligence (accumulated knowledge, vocabulary) holds up or rises with age, while fluid intelligence (solving novel problems quickly) peaks early and declines; option B reverses the two.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"वाराणसी की 68 वर्ष की एक सेवानिवृत्त हिंदी शिक्षिका का शब्दकोश और सामान्य ज्ञान पहले से कहीं समृद्ध है, पर अब वह अपरिचित समयबद्ध प्रतिरूप-पहेलियाँ 25 वर्ष की आयु की तुलना में धीमे हल करती है। इस प्रतिरूप को सबसे अच्छी तरह कौन-सा मत समझाता है?","optionsHi":["मूर्त योग्यता आयु के साथ बनी रहती या बढ़ती है जबकि तरल योग्यता घटने लगती है","तरल बुद्धि आयु के साथ बढ़ती रहती है जबकि मूर्त बुद्धि लगातार घटती है","सामान्य बुद्धि (g) मध्य आयु के बाद सभी योग्यताओं में समान रूप से घटती है","उसकी भाषायी बुद्धि ने धीरे-धीरे उसकी तार्किक-गणितीय बुद्धि की जगह ले ली है"],"explanationHi":"कैटल के मॉडल में मूर्त बुद्धि (संचित ज्ञान, शब्दकोश) आयु के साथ बनी रहती या बढ़ती है, जबकि तरल बुद्धि (नई समस्याओं को जल्दी हल करना) जल्दी चरम पर पहुँचकर घटती है; विकल्प B दोनों को उलट देता है।"},
  {"id":"cdp-child-development-282","question":"An 8-year-old has a mental age of 10. At 12 years, the same child has a mental age of 14, so she is still exactly two years ahead. Using the classic ratio IQ (MA ÷ CA × 100), which conclusion is correct?","options":["The ratio IQ stays at 125 because her two-year lead over her age is unchanged","The ratio IQ rises to about 140 because her mental age has increased by four years","The ratio IQ falls to 100 because both of her ages increased by the same four years","The ratio IQ falls from 125 to about 117 though she is still two years ahead"],"answer":3,"explanation":"10/8 × 100 = 125 but 14/12 × 100 ≈ 116.7. The same absolute lead gives a smaller ratio as age rises, one reason ratio IQ was replaced by the deviation IQ.","difficulty":"very-hard","source":"CTET Paper 2 · KVS PGT","questionHi":"एक 8 वर्ष के बच्चे की मानसिक आयु 10 है। 12 वर्ष की आयु में उसी बच्चे की मानसिक आयु 14 है, इसलिए वह अब भी ठीक दो वर्ष आगे है। क्लासिक अनुपात IQ (MA ÷ CA × 100) का उपयोग करते हुए कौन-सा निष्कर्ष सही है?","optionsHi":["अनुपात IQ 125 ही रहता है क्योंकि उसकी आयु से दो वर्ष की बढ़त अपरिवर्तित है","अनुपात IQ लगभग 140 हो जाता है क्योंकि उसकी मानसिक आयु चार वर्ष बढ़ी है","अनुपात IQ घटकर 100 हो जाता है क्योंकि उसकी दोनों आयु समान चार वर्ष बढ़ीं","अनुपात IQ 125 से घटकर लगभग 117 हो जाता है, यद्यपि वह अब भी दो वर्ष आगे है"],"explanationHi":"10/8 × 100 = 125 पर 14/12 × 100 ≈ 116.7। उतनी ही निरपेक्ष बढ़त आयु बढ़ने पर छोटा अनुपात देती है, जो अनुपात IQ की जगह विचलन IQ आने का एक कारण था।"},
  {"id":"cdp-child-development-283","question":"On a deviation-IQ test with a mean of 100 and a standard deviation of 15, Pooja scores 85. Assuming scores are normally distributed, about what proportion of children of her age score BELOW her?","options":["About 16%","About 15%","About 34%","About 50%"],"answer":0,"explanation":"85 is one standard deviation below the mean; about 34% of scores lie between −1 SD and the mean, so about 50 − 34 = 16% fall below. ‘15%’ confuses the SD value with a percentage.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"माध्य 100 और मानक विचलन 15 वाले विचलन-IQ परीक्षण पर पूजा 85 अंक पाती है। अंकों का सामान्य बंटन मानते हुए, उसकी आयु के लगभग कितने अनुपात बच्चे उससे नीचे अंक पाते हैं?","optionsHi":["लगभग 16%","लगभग 15%","लगभग 34%","लगभग 50%"],"explanationHi":"85 माध्य से एक मानक विचलन नीचे है; लगभग 34% अंक −1 SD और माध्य के बीच होते हैं, इसलिए लगभग 50 − 34 = 16% नीचे होते हैं। ‘15%’ SD के मान को प्रतिशत समझ लेने की भूल है।"},
  {"id":"cdp-child-development-284","question":"A school psychologist in Chennai still uses an intelligence test whose norms were set about 25 years ago. Given the Flynn effect, today’s children tested against these old norms will most likely:","options":["Score lower than their true standing, because tests become harder over time","Score higher than on freshly normed tests, overestimating their standing","Score the same, because well-made IQ norms stay valid and never need revision","Score randomly, because the Flynn effect makes the old test unreliable"],"answer":1,"explanation":"Average raw performance on IQ tests rose over the 20th century (the Flynn effect), so old norms are too easy a yardstick and inflate today’s IQ scores, which is why tests are periodically re-normed.","difficulty":"very-hard","source":"KVS PGT · State TET","questionHi":"चेन्नई का एक विद्यालय मनोवैज्ञानिक अब भी एक बुद्धि परीक्षण का उपयोग करता है जिसके मानक लगभग 25 वर्ष पहले बनाए गए थे। फ्लिन प्रभाव को देखते हुए, इन पुराने मानकों से परखे जाने पर आज के बच्चे सबसे अधिक संभावना से:","optionsHi":["अपनी वास्तविक स्थिति से कम अंक पाएँगे, क्योंकि परीक्षण समय के साथ कठिन होते जाते हैं","नए मानकीकृत परीक्षणों की तुलना में अधिक अंक पाएँगे, जिससे उनकी स्थिति अधिक आँकी जाएगी","समान अंक पाएँगे, क्योंकि भली-भाँति बनाए गए IQ मानक वैध रहते हैं और उन्हें कभी संशोधन की आवश्यकता नहीं होती","यादृच्छिक अंक पाएँगे, क्योंकि फ्लिन प्रभाव पुराने परीक्षण को अविश्वसनीय बना देता है"],"explanationHi":"20वीं सदी में IQ परीक्षणों पर औसत कच्चा प्रदर्शन बढ़ा (फ्लिन प्रभाव), इसलिए पुराने मानक एक बहुत आसान मापदंड हैं और आज के IQ अंकों को फुला देते हैं, इसीलिए परीक्षणों को समय-समय पर पुनः मानकीकृत किया जाता है।"},
  {"id":"cdp-child-development-285","question":"Match the thinkers with their contribution: 1. Salovey and Mayer 2. Daniel Goleman 3. Robert Sternberg 4. J. P. Guilford; a. Introduced the term ‘emotional intelligence’ in a 1990 research paper b. Popularised emotional intelligence through a 1995 best-selling book c. Triarchic theory of intelligence d. Structure-of-intellect model","options":["1-b, 2-a, 3-c, 4-d","1-a, 2-b, 3-d, 4-c","1-a, 2-b, 3-c, 4-d","1-b, 2-a, 3-d, 4-c"],"answer":2,"explanation":"Peter Salovey and John Mayer coined and defined emotional intelligence in 1990; Goleman’s 1995 book made it popular. Sternberg gave the triarchic theory and Guilford the structure of intellect.","difficulty":"hard","source":"CTET · DSSSB PRT","questionHi":"विचारकों का उनके योगदान से मिलान कीजिए: 1. सैलोवे और मेयर 2. डैनियल गोलमैन 3. रॉबर्ट स्टर्नबर्ग 4. जे. पी. गिलफोर्ड; a. 1990 के एक शोधपत्र में ‘भावनात्मक बुद्धि’ पद प्रस्तुत किया b. 1995 की बेस्टसेलर पुस्तक द्वारा भावनात्मक बुद्धि को लोकप्रिय बनाया c. बुद्धि का त्रितंत्र सिद्धांत d. बुद्धि की संरचना मॉडल","optionsHi":["1-b, 2-a, 3-c, 4-d","1-a, 2-b, 3-d, 4-c","1-a, 2-b, 3-c, 4-d","1-b, 2-a, 3-d, 4-c"],"explanationHi":"पीटर सैलोवे और जॉन मेयर ने 1990 में भावनात्मक बुद्धि का पद गढ़ा और परिभाषित किया; गोलमैन की 1995 की पुस्तक ने उसे लोकप्रिय बनाया। स्टर्नबर्ग ने त्रितंत्र सिद्धांत और गिलफोर्ड ने बुद्धि की संरचना दी।"},
  {"id":"cdp-child-development-286","question":"Ankit fails to get selected for the district football team. Instead of blaming the selectors, he draws up a practice plan, keeps working at it with optimism, and tries again next season. In Daniel Goleman’s model of emotional intelligence, this mainly reflects:","options":["Empathy","Social skills with teammates","Self-awareness of feelings","Self-motivation"],"answer":3,"explanation":"Goleman’s ‘motivation’ domain covers persisting towards goals with optimism despite setbacks. Empathy and social skills concern others’ feelings and relationships, and self-awareness is only recognising one’s own emotions.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"अंकित जिला फुटबॉल टीम के लिए चयनित नहीं होता। चयनकर्ताओं को दोष देने की बजाय वह अभ्यास योजना बनाता है, आशावाद के साथ उस पर काम करता रहता है, और अगले सत्र में फिर प्रयास करता है। डैनियल गोलमैन के भावनात्मक बुद्धि मॉडल में यह मुख्यतः क्या दर्शाता है?","optionsHi":["समानुभूति","साथियों के साथ सामाजिक कौशल","भावनाओं की आत्म-जागरूकता","आत्म-अभिप्रेरणा"],"explanationHi":"गोलमैन का ‘अभिप्रेरणा’ क्षेत्र असफलताओं के बावजूद आशावाद के साथ लक्ष्यों की ओर डटे रहने को समेटता है। समानुभूति और सामाजिक कौशल दूसरों की भावनाओं और संबंधों से जुड़े हैं, और आत्म-जागरूकता केवल अपनी भावनाओं को पहचानना है।"},
  {"id":"cdp-child-development-287","question":"A child with autism who has very limited speech can draw a detailed, accurate sketch of a temple after seeing it once. Howard Gardner cites cases like this (savants and selective brain damage) mainly as evidence that:","options":["Different intelligences are relatively independent of one another","Intelligence is fixed entirely by heredity and cannot be changed","A single general intelligence underlies all of a person's abilities","Standard IQ tests measure spatial ability adequately on their own"],"answer":0,"explanation":"Savants and patients who lose one ability while keeping others show that abilities can be isolated, one of Gardner’s criteria for counting a capacity as a separate intelligence; this argues against one all-purpose g.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"सीमित वाणी वाला ऑटिज़्म से ग्रस्त एक बच्चा किसी मंदिर को एक बार देखकर उसका विस्तृत, सटीक रेखाचित्र बना सकता है। हॉवर्ड गार्डनर ऐसे मामलों (सैवेंट और चयनात्मक मस्तिष्क क्षति) को मुख्यतः किसके प्रमाण के रूप में उद्धृत करते हैं?","optionsHi":["विभिन्न बुद्धियाँ एक-दूसरे से अपेक्षाकृत स्वतंत्र होती हैं","बुद्धि पूरी तरह आनुवंशिकता से निश्चित होती है और बदली नहीं जा सकती","एक सामान्य बुद्धि व्यक्ति की सभी योग्यताओं का आधार है","मानक IQ परीक्षण अकेले स्थानिक योग्यता को पर्याप्त रूप से मापते हैं"],"explanationHi":"सैवेंट और वे रोगी जो एक योग्यता खो देते हैं पर अन्य बनाए रखते हैं, यह दिखाते हैं कि योग्यताओं को अलग किया जा सकता है, जो किसी क्षमता को अलग बुद्धि गिनने के गार्डनर के मानदंडों में से एक है; यह एक सर्व-उद्देशीय g के विरुद्ध तर्क देता है।"},
  {"id":"cdp-child-development-288","question":"Which of the following classroom practices MISAPPLIES Howard Gardner’s theory of multiple intelligences?","options":["Offering several entry points to a topic, such as a story, a diagram and a hands-on activity","Letting students show their understanding of a chapter through a poem, a model or a presentation","Labelling a child ‘bodily-kinaesthetic’ and teaching her every subject only through movement","Using a child’s strength in music to build her confidence before a hard grammar unit begins"],"answer":2,"explanation":"Gardner himself warns against labelling children by one intelligence or treating intelligences as fixed learning styles; the theory calls for varied approaches for all children, not confining a child to one channel.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"निम्नलिखित में से कौन-सी कक्षा-पद्धति हॉवर्ड गार्डनर के बहुबुद्धि सिद्धांत का गलत अनुप्रयोग करती है?","optionsHi":["किसी विषय के कई प्रवेश-बिंदु देना, जैसे कहानी, आरेख और व्यावहारिक गतिविधि","विद्यार्थियों को अध्याय की अपनी समझ कविता, मॉडल या प्रस्तुति के माध्यम से दिखाने देना","किसी बच्ची को ‘शारीरिक-गतिबोधी’ का लेबल देना और उसे हर विषय केवल गति के माध्यम से पढ़ाना","कठिन व्याकरण इकाई शुरू होने से पहले बच्ची का आत्मविश्वास बढ़ाने के लिए संगीत में उसकी शक्ति का उपयोग करना"],"explanationHi":"गार्डनर स्वयं बच्चों को किसी एक बुद्धि के आधार पर लेबल देने या बुद्धियों को निश्चित अधिगम शैलियाँ मानने के विरुद्ध चेतावनी देते हैं; सिद्धांत सभी बच्चों के लिए विविध उपागमों की माँग करता है, किसी बच्चे को एक माध्यम तक सीमित करने की नहीं।"},
  {"id":"cdp-child-development-289","question":"Before attempting a word problem, Meena decides which strategy to use, keeps checking whether it is working, and switches to drawing a diagram when she gets stuck. In Sternberg’s componential subtheory, these executive processes are called:","options":["Metacomponents","Knowledge-acquisition components","Performance components","Automatisation"],"answer":0,"explanation":"Metacomponents plan, monitor and evaluate problem-solving. Performance components actually carry out the steps, and knowledge-acquisition components learn new information.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"शब्द-समस्या का प्रयास करने से पहले मीना तय करती है कि कौन-सी युक्ति प्रयोग करनी है, बार-बार जाँचती है कि वह काम कर रही है या नहीं, और अटकने पर आरेख बनाने की ओर मुड़ जाती है। स्टर्नबर्ग के घटकीय उप-सिद्धांत में इन कार्यकारी प्रक्रियाओं को क्या कहते हैं?","optionsHi":["अधिघटक (मेटाकॉम्पोनेंट)","ज्ञान-अर्जन घटक","निष्पादन घटक","स्वचालन"],"explanationHi":"अधिघटक समस्या-समाधान की योजना बनाते, निगरानी करते और मूल्यांकन करते हैं। निष्पादन घटक वास्तव में चरणों को पूरा करते हैं, और ज्ञान-अर्जन घटक नई सूचना सीखते हैं।"},
  {"id":"cdp-child-development-290","question":"Sunita, a girl from a tribal village in Bastar, finds that her hostel’s rigid meal timings clash with the early bus she must take to reach a science coaching class. Rather than skipping meals or leaving the hostel, she persuades the warden to keep a packed breakfast for students who leave early. In Sternberg’s contextual subtheory, this is an example of:","options":["Adaptation to the environment","Selection of a new environment","Automatisation of a routine","Shaping of the environment"],"answer":3,"explanation":"Sternberg’s practical intelligence works through adapting to, shaping or selecting environments. Sunita changes the environment to suit her needs, which is shaping; adapting would mean changing herself, and selection would mean moving to another hostel.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"बस्तर के एक जनजातीय गाँव की लड़की सुनीता पाती है कि उसके छात्रावास के कठोर भोजन-समय उस सुबह की बस से टकराते हैं जो उसे विज्ञान की कोचिंग कक्षा तक पहुँचने के लिए पकड़नी होती है। भोजन छोड़ने या छात्रावास छोड़ने की बजाय, वह वार्डन को मनाती है कि जल्दी जाने वाले विद्यार्थियों के लिए बँधा हुआ नाश्ता रखा जाए। स्टर्नबर्ग के संदर्भगत उप-सिद्धांत में यह किसका उदाहरण है?","optionsHi":["परिवेश के प्रति अनुकूलन","नए परिवेश का चयन","किसी दिनचर्या का स्वचालन","परिवेश को आकार देना"],"explanationHi":"स्टर्नबर्ग की व्यावहारिक बुद्धि परिवेशों के प्रति अनुकूलन, उन्हें आकार देने या उनका चयन करने के माध्यम से काम करती है। सुनीता परिवेश को अपनी ज़रूरतों के अनुसार बदलती है, जो आकार देना है; अनुकूलन का अर्थ स्वयं को बदलना होता, और चयन का अर्थ किसी दूसरे छात्रावास में जाना।"},
  {"id":"cdp-child-development-291","question":"Asked to list uses of a brick, Rahul gives twelve answers: wall, house, hut, well, cowshed, temple, school, boundary, steps, toilet, oven and tank. On the usual divergent-thinking scoring (as in Torrance’s tests), his response is:","options":["High in flexibility but low in fluency","High in fluency but low in flexibility","High in originality and elaboration","Low in fluency and low in flexibility"],"answer":1,"explanation":"Fluency counts the number of ideas (twelve is many), while flexibility counts the number of different categories; all his ideas fall in one category, ‘building something’, so flexibility is low.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"ईंट के उपयोग गिनाने को कहे जाने पर राहुल बारह उत्तर देता है: दीवार, घर, झोपड़ी, कुआँ, गोशाला, मंदिर, स्कूल, सीमा, सीढ़ियाँ, शौचालय, तंदूर और टंकी। अपसारी-चिंतन के सामान्य अंकन (जैसे टॉरेंस के परीक्षणों में) पर उसकी अनुक्रिया है:","optionsHi":["लचीलेपन में उच्च पर प्रवाह में निम्न","प्रवाह में उच्च पर लचीलेपन में निम्न","मौलिकता और विस्तारण में उच्च","प्रवाह में निम्न और लचीलेपन में निम्न"],"explanationHi":"प्रवाह विचारों की संख्या गिनता है (बारह बहुत हैं), जबकि लचीलापन अलग-अलग श्रेणियों की संख्या गिनता है; उसके सभी विचार एक ही श्रेणी, ‘कुछ बनाना’, में आते हैं, इसलिए लचीलापन कम है।"},
  {"id":"cdp-child-development-292","question":"Gauri struggles for an hour with a geometry construction, gives up and goes to play kabaddi, and the next morning the method suddenly strikes her while brushing her teeth; she then checks it carefully. In Graham Wallas’s model of creative thinking, the time when she had stopped working on the problem consciously is the stage of:","options":["Preparation","Illumination","Verification","Incubation"],"answer":3,"explanation":"Wallas’s stages are preparation (working on it), incubation (setting it aside while ideas form unconsciously), illumination (the sudden insight) and verification (checking it). The break corresponds to incubation.","difficulty":"moderate","source":"CTET · DSSSB PRT","questionHi":"गौरी एक घंटे तक ज्यामिति की रचना से जूझती है, हार मानकर कबड्डी खेलने चली जाती है, और अगली सुबह दाँत साफ करते समय अचानक उसे तरीका सूझ जाता है; फिर वह उसे ध्यान से जाँचती है। ग्राहम वैलेस के सृजनात्मक चिंतन के मॉडल में, जब उसने समस्या पर सचेत रूप से काम करना बंद कर दिया था, वह समय किस चरण का है?","optionsHi":["तैयारी","प्रबोधन (इल्यूमिनेशन)","सत्यापन","उद्भवन (इन्क्यूबेशन)"],"explanationHi":"वैलेस के चरण हैं तैयारी (उस पर काम करना), उद्भवन (उसे अलग रखना जबकि विचार अचेतन रूप से बनते हैं), प्रबोधन (अचानक अंतर्दृष्टि) और सत्यापन (उसकी जाँच)। विराम उद्भवन के अनुरूप है।"},
  {"id":"cdp-child-development-293","question":"A principal proposes that the school’s creativity club admit only students with an IQ above 140, ‘because only very intelligent children can be truly creative’. Which response is best supported by research on intelligence and creativity?","options":["Agree, since creativity rises steadily with IQ at every level of ability","Agree, since creativity and intelligence are really one and the same ability","Disagree, since creativity is purely inherited and cannot be developed","Disagree, since above a moderate IQ, IQ predicts creativity only weakly"],"answer":3,"explanation":"The threshold hypothesis holds that some reasonable level of intelligence (often put near IQ 120) helps creativity, but above it IQ and creativity are only weakly related; creativity can also be nurtured, so a high IQ cut-off is not justified.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"एक प्रधानाचार्य प्रस्ताव रखते हैं कि विद्यालय की सृजनात्मकता क्लब में केवल 140 से ऊपर IQ वाले विद्यार्थियों को प्रवेश दिया जाए, ‘क्योंकि केवल बहुत बुद्धिमान बच्चे ही वास्तव में सृजनशील हो सकते हैं।’ बुद्धि और सृजनशीलता पर शोध द्वारा कौन-सी प्रतिक्रिया सबसे अच्छी तरह समर्थित है?","optionsHi":["सहमत होना, क्योंकि सृजनशीलता योग्यता के हर स्तर पर IQ के साथ लगातार बढ़ती है","सहमत होना, क्योंकि सृजनशीलता और बुद्धि वास्तव में एक ही योग्यता हैं","असहमत होना, क्योंकि सृजनशीलता पूर्णतः आनुवंशिक है और विकसित नहीं की जा सकती","असहमत होना, क्योंकि मध्यम IQ से ऊपर, IQ सृजनशीलता का केवल कमज़ोर पूर्वानुमान देता है"],"explanationHi":"देहली परिकल्पना कहती है कि बुद्धि का कोई उचित स्तर (प्रायः IQ 120 के निकट माना जाता है) सृजनशीलता में सहायक होता है, पर उससे ऊपर IQ और सृजनशीलता का संबंध केवल कमज़ोर होता है; सृजनशीलता का पोषण भी किया जा सकता है, इसलिए ऊँची IQ सीमा उचित नहीं है।"},
  {"id":"cdp-child-development-294","question":"Which teacher practice is most likely to SUPPRESS divergent thinking in a Class 5 classroom?","options":["Asking ‘In how many ways could we measure the length of this room?’ before teaching units","Awarding marks only when an answer matches the guidebook's model answer word for word","Accepting unusual answers and asking the child to explain the reasoning behind them","Giving children time to think before calling for answers to an open question"],"answer":1,"explanation":"Rewarding only the one ‘approved’ wording teaches children to converge on expected answers and avoid risk; the other practices invite many ideas and value original reasoning.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"कक्षा 5 में कौन-सी शिक्षक-पद्धति अपसारी चिंतन को दबाने की सबसे अधिक संभावना रखती है?","optionsHi":["इकाइयाँ पढ़ाने से पहले पूछना ‘हम इस कमरे की लंबाई कितने तरीकों से माप सकते हैं?’","अंक केवल तभी देना जब उत्तर मार्गदर्शिका के आदर्श उत्तर से शब्दशः मेल खाए","असामान्य उत्तरों को स्वीकार करना और बच्चे से उनके पीछे का तर्क समझाने को कहना","खुले प्रश्न पर उत्तर माँगने से पहले बच्चों को सोचने का समय देना"],"explanationHi":"केवल एक ‘स्वीकृत’ शब्दावली को पुरस्कृत करना बच्चों को अपेक्षित उत्तरों पर अभिसरित होना और जोखिम से बचना सिखाता है; अन्य पद्धतियाँ अनेक विचारों को आमंत्रित करती हैं और मौलिक तर्क को महत्व देती हैं।"},
  {"id":"cdp-child-development-295","question":"A city school selects children for its gifted programme solely on an IQ score above 130. A critic using Joseph Renzulli’s three-ring conception of giftedness would say the selection ignores:","options":["Creativity and task commitment","Emotional intelligence and parental income","Chronological age and mental age","Fluid and crystallised intelligence"],"answer":0,"explanation":"Renzulli sees gifted behaviour as the overlap of above-average ability, creativity and task commitment; an IQ cut-off captures only the first ring.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक शहरी विद्यालय अपने प्रतिभाशाली कार्यक्रम के लिए बच्चों का चयन केवल 130 से ऊपर के IQ अंक पर करता है। जोसेफ रेंज़ुली की प्रतिभाशालिता की त्रि-वलय अवधारणा का उपयोग करने वाला आलोचक कहेगा कि चयन किसकी उपेक्षा करता है?","optionsHi":["सृजनशीलता और कार्य-प्रतिबद्धता","भावनात्मक बुद्धि और माता-पिता की आय","कालानुक्रमिक आयु और मानसिक आयु","तरल और मूर्त बुद्धि"],"explanationHi":"रेंज़ुली प्रतिभाशाली व्यवहार को औसत से ऊपर योग्यता, सृजनशीलता और कार्य-प्रतिबद्धता के अतिव्यापन के रूप में देखते हैं; IQ की सीमा केवल पहले वलय को पकड़ती है।"},
  {"id":"cdp-child-development-296","question":"Imran, a Class 5 student in Pune, has dyslexia and writes slowly with many spelling errors, but his oral explanations of how pulleys and gears work are far beyond his age. The most appropriate response is to:","options":["Treat him as an underachiever who is simply not trying hard enough at his writing","Place him only in remedial reading classes until his reading reaches grade level","Recognise him as twice-exceptional: enrich his strength and support his reading","Withhold enrichment activities until his written work matches his oral ability"],"answer":2,"explanation":"A child can be gifted and have a learning disability at once (twice-exceptional); focusing only on the deficit wastes the talent and harms motivation, so both needs must be met together.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"पुणे में कक्षा 5 का विद्यार्थी इमरान डिस्लेक्सिया से ग्रस्त है और धीरे लिखता है तथा वर्तनी की कई गलतियाँ करता है, पर घिरनी और गियर कैसे काम करते हैं, इसकी उसकी मौखिक व्याख्याएँ उसकी आयु से कहीं आगे हैं। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["उसे कम उपलब्धि वाला मानना जो अपने लेखन पर पर्याप्त मेहनत नहीं कर रहा","जब तक उसका पठन कक्षा-स्तर तक न पहुँच जाए, उसे केवल उपचारात्मक पठन कक्षाओं में रखना","उसे द्वि-असाधारण (ट्वाइस-एक्सेप्शनल) के रूप में पहचानना: उसकी शक्ति को समृद्ध करना और उसके पठन में सहायता देना","जब तक उसका लिखित कार्य उसकी मौखिक योग्यता के बराबर न हो जाए, संवर्धन गतिविधियाँ रोककर रखना"],"explanationHi":"एक बच्चा एक साथ प्रतिभाशाली और अधिगम अक्षमता वाला हो सकता है (द्वि-असाधारण); केवल कमी पर ध्यान देना प्रतिभा को व्यर्थ करता है और अभिप्रेरणा को हानि पहुँचाता है, इसलिए दोनों आवश्यकताओं को एक साथ पूरा करना चाहिए।"},
  {"id":"cdp-child-development-297","question":"A three-year-old in a Bengaluru preschool says ‘I goed to the park’ and ‘I saw two mouses’, forms she has never heard from adults. Such errors are most damaging to which view?","options":["Chomsky’s view that children have an innate capacity to discover the grammatical rules of language","Skinner’s view that language is learned by imitating and being reinforced for adult speech","Vygotsky’s view that speech is first social and only later turns inward as thought","The view that children actively construct language rules from the speech they hear"],"answer":1,"explanation":"Over-regularisation shows that the child is applying a rule (add ‘-ed’, add ‘-s’) to new cases, not copying heard forms; this supports rule-based, nativist or constructivist accounts and challenges pure imitation and reinforcement.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"बेंगलुरु के प्री-स्कूल में तीन वर्ष की एक बच्ची कहती है ‘I goed to the park’ और ‘I saw two mouses’, ऐसे रूप जो उसने वयस्कों से कभी नहीं सुने। ऐसी त्रुटियाँ किस मत के लिए सबसे अधिक हानिकारक हैं?","optionsHi":["चॉम्स्की का मत कि बच्चों में भाषा के व्याकरणिक नियम खोजने की जन्मजात क्षमता होती है","स्किनर का मत कि भाषा वयस्कों की वाणी की नकल करने और उसके लिए पुनर्बलन पाने से सीखी जाती है","वाइगोत्स्की का मत कि वाक् पहले सामाजिक होती है और केवल बाद में भीतर मुड़कर चिंतन बन जाती है","यह मत कि बच्चे जो भाषण सुनते हैं उससे भाषा के नियम सक्रिय रूप से निर्मित करते हैं"],"explanationHi":"अति-नियमितीकरण दिखाता है कि बच्चा नए मामलों में एक नियम (‘-ed’ जोड़ो, ‘-s’ जोड़ो) लगा रहा है, सुने हुए रूपों की नकल नहीं कर रहा; यह नियम-आधारित, जन्मजातवादी या रचनावादी विवरणों का समर्थन करता है और शुद्ध अनुकरण और पुनर्बलन को चुनौती देता है।"},
  {"id":"cdp-child-development-298","question":"A five-year-old in Lucknow talks aloud to herself while building a block tower (‘No, the big one goes at the bottom…’), and talks even more when the tower falls. Which pairing of interpretations is correct?","options":["Piaget: speech that guides her action and later turns into inner speech; Vygotsky: egocentric speech of immature thought","Piaget and Vygotsky: both see it as a sign of language delay needing speech therapy","Piaget: egocentric speech showing she cannot yet take others’ views; Vygotsky: private speech regulating her actions","Piaget and Vygotsky: both see it as useless speech that should be discouraged"],"answer":2,"explanation":"Piaget saw such talk as egocentric speech that fades as thinking matures; Vygotsky saw it as private speech, a tool of self-regulation that increases with task difficulty and later goes underground as inner speech.","difficulty":"very-hard","source":"CTET Paper 2 · KVS PGT","questionHi":"लखनऊ की पाँच वर्ष की एक बच्ची ब्लॉकों की मीनार बनाते समय ज़ोर-ज़ोर से स्वयं से बात करती है (‘नहीं, बड़ा वाला नीचे जाएगा…’), और मीनार गिरने पर और अधिक बोलती है। व्याख्याओं की कौन-सी जोड़ी सही है?","optionsHi":["पियाजे: वाक् जो उसकी क्रिया का मार्गदर्शन करती है और बाद में आंतरिक वाक् बन जाती है; वाइगोत्स्की: अपरिपक्व चिंतन की अहंकेंद्रित वाक्","पियाजे और वाइगोत्स्की: दोनों इसे भाषा-विलंब का संकेत मानते हैं जिसे वाक्-चिकित्सा चाहिए","पियाजे: अहंकेंद्रित वाक् जो दर्शाती है कि वह अभी दूसरों के दृष्टिकोण नहीं ले सकती; वाइगोत्स्की: निजी वाक् जो उसकी क्रियाओं का नियमन करती है","पियाजे और वाइगोत्स्की: दोनों इसे व्यर्थ वाक् मानते हैं जिसे हतोत्साहित किया जाना चाहिए"],"explanationHi":"पियाजे ऐसी बातचीत को अहंकेंद्रित वाक् मानते थे जो चिंतन के परिपक्व होने पर घटती है; वाइगोत्स्की इसे निजी वाक् मानते थे, आत्म-नियमन का एक उपकरण जो कार्य की कठिनाई के साथ बढ़ता है और बाद में आंतरिक वाक् के रूप में ‘भीतर’ चला जाता है।"},
  {"id":"cdp-child-development-299","question":"Which statement best reflects the present status of the Sapir–Whorf hypothesis among psychologists?","options":["The weak version, that language can influence some perception and memory, has support; the strong version is largely rejected","Both versions have been completely disproved, so language has no effect at all on thought or memory","The strong version, that language completely determines what people can think, is now widely accepted","Only the strong version has experimental support, because people cannot perceive colours for which they have no name at all"],"answer":0,"explanation":"Research (for example on colour terms and spatial words) shows language can shape some habits of thought (linguistic relativity), but people can perceive and think about things they have no word for, so strict linguistic determinism is rejected.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"मनोवैज्ञानिकों के बीच सैपिर–व्हॉर्फ परिकल्पना की वर्तमान स्थिति को कौन-सा कथन सबसे अच्छी तरह दर्शाता है?","optionsHi":["दुर्बल संस्करण, कि भाषा कुछ प्रत्यक्षण और स्मृति को प्रभावित कर सकती है, को समर्थन है; प्रबल संस्करण को काफी हद तक अस्वीकार कर दिया गया है","दोनों संस्करण पूरी तरह खंडित हो चुके हैं, इसलिए भाषा का चिंतन या स्मृति पर कोई प्रभाव नहीं पड़ता","प्रबल संस्करण, कि भाषा पूरी तरह तय करती है कि लोग क्या सोच सकते हैं, अब व्यापक रूप से स्वीकृत है","केवल प्रबल संस्करण को प्रयोगात्मक समर्थन है, क्योंकि लोग उन रंगों को बिल्कुल नहीं देख सकते जिनका कोई नाम न हो"],"explanationHi":"शोध (उदाहरणतः रंग-शब्दों और स्थानिक शब्दों पर) दिखाता है कि भाषा चिंतन की कुछ आदतों को आकार दे सकती है (भाषायी सापेक्षता), पर लोग उन चीज़ों को देख और सोच सकते हैं जिनके लिए उनके पास शब्द नहीं हैं, इसलिए कठोर भाषायी नियतिवाद अस्वीकृत है।"},
  {"id":"cdp-child-development-300","question":"Assertion (A): In a Class 8 physics quiz in a Haryana school, girls scored lower than boys, which proves that girls have less natural aptitude for physics. Reason (R): Gender roles and expectations are learned through socialisation in the family, the school and the media.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"One quiz result cannot prove an innate difference; such gaps are better explained by expectations, encouragement and opportunities. R correctly states that gender roles are socially learned.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"अभिकथन (A): हरियाणा के एक विद्यालय में कक्षा 8 की भौतिकी क्विज़ में लड़कियों ने लड़कों से कम अंक पाए, जो सिद्ध करता है कि लड़कियों में भौतिकी के लिए स्वाभाविक अभिक्षमता कम है। कारण (R): लिंग भूमिकाएँ और अपेक्षाएँ परिवार, विद्यालय और मीडिया में समाजीकरण के माध्यम से सीखी जाती हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"एक क्विज़ का परिणाम किसी जन्मजात अंतर को सिद्ध नहीं कर सकता; ऐसे अंतरों को अपेक्षाएँ, प्रोत्साहन और अवसर बेहतर समझाते हैं। R सही कहता है कि लिंग भूमिकाएँ सामाजिक रूप से सीखी जाती हैं।"},
  {"id":"cdp-child-development-301","question":"A three-month-old in an anganwadi holds her head steady but cannot yet sit, and she swipes at a rattle with her whole arm long before she can pick up a bead with her fingers. Which pair of principles, in that order, explains the two observations?","options":["Cephalocaudal; proximodistal","Proximodistal; cephalocaudal","Continuity; individual differences","Cephalocaudal; specific to general"],"answer":0,"explanation":"Head control before sitting is head-to-tail (cephalocaudal); whole-arm swipes before finger grasp is centre-to-periphery (proximodistal). Option B swaps the two, the commonest mix-up.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"एक आँगनवाड़ी में तीन माह की एक बच्ची अपना सिर स्थिर रखती है पर अभी बैठ नहीं सकती, और वह उँगलियों से मनका उठा पाने से बहुत पहले पूरी बाँह से झुनझुने पर हाथ मारती है। सिद्धांतों की कौन-सी जोड़ी, उसी क्रम में, इन दोनों अवलोकनों को समझाती है?","optionsHi":["शीर्षगामी; निकट-दूर","निकट-दूर; शीर्षगामी","निरंतरता; वैयक्तिक भिन्नता","शीर्षगामी; विशिष्ट से सामान्य"],"explanationHi":"बैठने से पहले सिर पर नियंत्रण सिर-से-पूँछ की ओर (शीर्षगामी) है; उँगली से पकड़ने से पहले पूरी बाँह से हाथ मारना केंद्र-से-परिधि की ओर (निकट-दूर) है। विकल्प B दोनों को बदल देता है, जो सबसे आम भ्रम है।"},
  {"id":"cdp-child-development-302","question":"Riya walked at 10 months and Arjun at 15 months; both are healthy and in Class 1 now run and jump equally well. Which inference is most consistent with the principles of development?","options":["Arjun’s development is delayed and he needs remedial motor training now","The sequence of motor milestones is shared by children, but the rate varies","Both the rate and the sequence vary so much that developmental norms are useless","Early walking signals higher intelligence, so Riya will do better in academics"],"answer":1,"explanation":"Children pass through the same broad sequence (sit, stand, walk) at different rates; a five-month spread in walking is normal variation, not delay.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"रिया 10 माह में चली और अर्जुन 15 माह में; दोनों स्वस्थ हैं और अब कक्षा 1 में समान रूप से अच्छा दौड़ते-कूदते हैं। विकास के सिद्धांतों के साथ कौन-सा निष्कर्ष सबसे अधिक संगत है?","optionsHi":["अर्जुन का विकास विलंबित है और उसे अब उपचारात्मक गामक प्रशिक्षण चाहिए","गामक उपलब्धियों का क्रम बच्चों में साझा होता है, पर दर भिन्न होती है","दर और क्रम दोनों इतने भिन्न होते हैं कि विकासात्मक मानक बेकार हैं","जल्दी चलना उच्च बुद्धि का संकेत है, इसलिए रिया शैक्षिक रूप से बेहतर करेगी"],"explanationHi":"बच्चे एक ही व्यापक क्रम (बैठना, खड़ा होना, चलना) से अलग-अलग दरों पर गुज़रते हैं; चलने में पाँच माह का अंतर सामान्य विविधता है, विलंब नहीं।"},
  {"id":"cdp-child-development-303","question":"‘Development is continuous, but its rate is not uniform.’ Which observation best illustrates this statement?","options":["Height increases by exactly the same amount every year from birth to eighteen","All children speak their first word at exactly twelve months, without exception","A toddler’s vocabulary grows slowly at first and then spurts in the second year","Once a skill is mastered, development in that particular area stops for good"],"answer":2,"explanation":"Development never halts but moves in spurts and plateaus; the vocabulary spurt shows continuity with an uneven rate. Uniform yearly growth (A) contradicts the statement.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"‘विकास सतत है, पर उसकी दर एकसमान नहीं है।’ कौन-सा अवलोकन इस कथन को सबसे अच्छी तरह दर्शाता है?","optionsHi":["जन्म से अठारह वर्ष तक हर वर्ष ऊँचाई ठीक समान मात्रा में बढ़ती है","सभी बच्चे बिना किसी अपवाद के ठीक बारह माह पर अपना पहला शब्द बोलते हैं","एक छोटे बच्चे का शब्दकोश शुरू में धीरे बढ़ता है और फिर दूसरे वर्ष में तेज़ी से उछलता है","एक बार कोई कौशल सीख लेने पर उस विशेष क्षेत्र में विकास सदा के लिए रुक जाता है"],"explanationHi":"विकास कभी रुकता नहीं पर उछालों और पठारों में चलता है; शब्दकोश का उछाल असमान दर के साथ निरंतरता दिखाता है। एकसमान वार्षिक वृद्धि (A) कथन का खंडन करती है।"},
  {"id":"cdp-child-development-304","question":"Assertion (A): A Class 2 teacher should not expect every child in her class to be ready to read fluently at the same time. Reason (R): Development follows a predictable sequence.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both statements are true, but A follows from individual differences in the RATE of development, not from the common sequence; a predictable sequence alone would not explain different readiness times.","difficulty":"very-hard","source":"CTET Paper 1 · State TET","questionHi":"अभिकथन (A): कक्षा 2 की शिक्षिका को अपनी कक्षा के हर बच्चे से एक ही समय पर धाराप्रवाह पढ़ने के लिए तैयार होने की अपेक्षा नहीं करनी चाहिए। कारण (R): विकास एक पूर्वानुमेय क्रम का अनुसरण करता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों कथन सत्य हैं, पर A विकास की दर में वैयक्तिक भिन्नताओं से निकलता है, साझा क्रम से नहीं; केवल पूर्वानुमेय क्रम तत्परता के भिन्न समयों को नहीं समझाता।"},
  {"id":"cdp-child-development-305","question":"In Gesell’s co-twin study, one twin was trained in stair-climbing for weeks from an early age; the other was trained only briefly, weeks later, and quickly caught up. What does the result mainly support?","options":["Intensive early training can make any skill appear at any age the trainer chooses","Maturation sets readiness, so practice before readiness gives little lasting gain","Motor skills depend on environment and practice alone, not on biological maturation","Identical twins always develop at different rates, whatever training they receive"],"answer":1,"explanation":"The late-trained twin matched the early-trained one with far less practice, showing that maturation (readiness) limits what early training can achieve.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"गेसेल के सह-जुड़वाँ अध्ययन में एक जुड़वाँ को कम उम्र से कई सप्ताह तक सीढ़ी चढ़ने का प्रशिक्षण दिया गया; दूसरे को सप्ताहों बाद केवल थोड़े समय के लिए प्रशिक्षण मिला, और उसने जल्दी ही बराबरी कर ली। परिणाम मुख्यतः किसका समर्थन करता है?","optionsHi":["गहन प्रारंभिक प्रशिक्षण किसी भी कौशल को प्रशिक्षक की चुनी किसी भी आयु में प्रकट करा सकता है","परिपक्वता तत्परता तय करती है, इसलिए तत्परता से पहले का अभ्यास बहुत कम स्थायी लाभ देता है","गामक कौशल केवल पर्यावरण और अभ्यास पर निर्भर करते हैं, जैविक परिपक्वता पर नहीं","समान जुड़वाँ हमेशा अलग-अलग दरों पर विकसित होते हैं, चाहे उन्हें कोई भी प्रशिक्षण मिले"],"explanationHi":"देर से प्रशिक्षित जुड़वाँ ने बहुत कम अभ्यास से जल्दी प्रशिक्षित जुड़वाँ की बराबरी कर ली, जो दर्शाता है कि परिपक्वता (तत्परता) सीमित करती है कि प्रारंभिक प्रशिक्षण क्या हासिल कर सकता है।"},
  {"id":"cdp-child-development-306","question":"A Class 7 girl with a strong musical bent keeps asking to join the school band, spends free periods in the music room and seeks out older students who play, which sharpens her talent further. Which kind of heredity–environment link does this illustrate?","options":["Passive gene–environment correlation via her home","Evocative gene–environment correlation from teachers","Active gene–environment correlation (niche-picking)","Canalisation of an inborn musical talent"],"answer":2,"explanation":"When a child herself seeks out settings that suit her inherited tendencies, it is active correlation or niche-picking, which grows stronger with age. Evocative would mean others reacting to her, not her choosing.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक संगीत-प्रवृत्ति वाली लड़की विद्यालय के बैंड में शामिल होने की बार-बार माँग करती है, खाली पीरियड संगीत कक्ष में बिताती है और वाद्य बजाने वाले बड़े विद्यार्थियों को ढूँढ़ती है, जिससे उसकी प्रतिभा और निखरती है। यह वंशागति–पर्यावरण संबंध के किस प्रकार को दर्शाता है?","optionsHi":["उसके घर के माध्यम से निष्क्रिय जीन–पर्यावरण सहसंबंध","शिक्षकों से उद्दीपित (इवोकेटिव) जीन–पर्यावरण सहसंबंध","सक्रिय जीन–पर्यावरण सहसंबंध (निशे-पिकिंग)","जन्मजात संगीत प्रतिभा का नलिकाकरण (कैनलाइज़ेशन)"],"explanationHi":"जब बच्ची स्वयं उन परिवेशों को खोजती है जो उसकी वंशानुगत प्रवृत्तियों के अनुकूल हैं, तो यह सक्रिय सहसंबंध या निशे-पिकिंग है, जो आयु के साथ प्रबल होता जाता है। उद्दीपित का अर्थ होता दूसरों का उस पर प्रतिक्रिया करना, उसका स्वयं चुनना नहीं।"},
  {"id":"cdp-child-development-307","question":"A cheerful infant who smiles and babbles a lot draws more talk and play from adults around her, and this extra interaction further boosts her social skills. This is best described as:","options":["Active gene–environment correlation (niche-picking)","Passive gene–environment correlation","Canalisation","Evocative gene–environment correlation"],"answer":3,"explanation":"The child’s inherited temperament evokes particular responses from others, which then shape her development: evocative (reactive) correlation. Active would require her to choose environments, which infants cannot yet do.","difficulty":"very-hard","source":"CTET Paper 1 · State TET","questionHi":"एक प्रसन्न शिशु जो खूब मुस्कुराती और बलबलाती है, अपने आसपास के वयस्कों से अधिक बातचीत और खेल पाती है, और यह अतिरिक्त अंतःक्रिया उसके सामाजिक कौशल को और बढ़ाती है। इसका सबसे अच्छा वर्णन है:","optionsHi":["सक्रिय जीन–पर्यावरण सहसंबंध (निशे-पिकिंग)","निष्क्रिय जीन–पर्यावरण सहसंबंध","नलिकाकरण (कैनलाइज़ेशन)","उद्दीपित (इवोकेटिव) जीन–पर्यावरण सहसंबंध"],"explanationHi":"बच्ची की वंशानुगत प्रकृति दूसरों से विशेष प्रतिक्रियाएँ उद्दीपित करती है, जो फिर उसके विकास को आकार देती हैं: उद्दीपित (प्रतिक्रियात्मक) सहसंबंध। सक्रिय के लिए उसे परिवेश चुनने होते, जो शिशु अभी नहीं कर सकते।"},
  {"id":"cdp-child-development-308","question":"Both parents of a child are keen readers who fill the home with books and talk; the child inherits some of their verbal aptitude and also grows up surrounded by print. Which concept describes this?","options":["Passive gene–environment correlation","Evocative gene–environment correlation","Active gene–environment correlation","Reaction range"],"answer":0,"explanation":"Parents provide both the genes and an environment matching them, without any choice by the child: passive correlation, strongest in early childhood.","difficulty":"very-hard","source":"KVS PRT · DSSSB","questionHi":"एक बच्चे के दोनों माता-पिता शौकीन पाठक हैं जो घर को किताबों और बातचीत से भर देते हैं; बच्चा उनकी कुछ शाब्दिक अभिक्षमता वंशानुगत पाता है और साथ ही मुद्रित सामग्री से घिरा पलता है। कौन-सी अवधारणा इसका वर्णन करती है?","optionsHi":["निष्क्रिय जीन–पर्यावरण सहसंबंध","उद्दीपित (इवोकेटिव) जीन–पर्यावरण सहसंबंध","सक्रिय जीन–पर्यावरण सहसंबंध","प्रतिक्रिया-सीमा"],"explanationHi":"माता-पिता जीन और उनसे मेल खाता परिवेश दोनों देते हैं, बच्चे के किसी चुनाव के बिना: निष्क्रिय सहसंबंध, जो प्रारंभिक बाल्यावस्था में सबसे प्रबल होता है।"},
  {"id":"cdp-child-development-309","question":"When a two-month-old is upset she cries, kicks and waves her arms with her whole body; by age four she may simply frown or say she is angry. Which principle of development does this mainly illustrate?","options":["Proximodistal direction, from the trunk out to the limbs","Cephalocaudal direction, from head to toe","Development proceeds from general to specific responses","Development is spiral rather than linear"],"answer":2,"explanation":"Diffuse whole-body reactions give way to specific, differentiated responses: the general-to-specific principle. Proximodistal is about motor control spreading from trunk to fingers, not about emotional expression.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"जब दो माह की बच्ची परेशान होती है तो वह पूरे शरीर से रोती, लात मारती और बाँहें हिलाती है; चार वर्ष की आयु तक वह बस त्योरी चढ़ा सकती है या कह सकती है कि वह गुस्से में है। यह मुख्यतः विकास के किस सिद्धांत को दर्शाता है?","optionsHi":["निकट-दूर दिशा, धड़ से अंगों की ओर","शीर्षगामी दिशा, सिर से पैर की ओर","विकास सामान्य से विशिष्ट अनुक्रियाओं की ओर बढ़ता है","विकास रैखिक नहीं बल्कि सर्पिल होता है"],"explanationHi":"विसरित पूरे-शरीर की प्रतिक्रियाएँ विशिष्ट, विभेदित अनुक्रियाओं को स्थान देती हैं: सामान्य-से-विशिष्ट सिद्धांत। निकट-दूर गामक नियंत्रण के धड़ से उँगलियों तक फैलने के बारे में है, भावनात्मक अभिव्यक्ति के बारे में नहीं।"},
  {"id":"cdp-child-development-310","question":"A Class 1 child with an untreated hearing loss shows delayed speech, avoids playing with classmates and is falling behind in reading. Which principle of development explains why one problem has spread to so many areas?","options":["Development proceeds cephalocaudally, so problems spread from the head downwards","Development is decided solely by heredity, so all of her delays share one cause","Development in each domain runs independently, so these are three separate problems","Development in different domains is interrelated, so one difficulty affects others"],"answer":3,"explanation":"Physical, language, social and cognitive development are interlinked; hearing loss hampers speech, which in turn affects peer interaction and literacy.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"अनुपचारित श्रवण-हानि वाला कक्षा 1 का एक बच्चा विलंबित वाणी दिखाता है, सहपाठियों के साथ खेलने से बचता है और पठन में पिछड़ रहा है। विकास का कौन-सा सिद्धांत समझाता है कि एक समस्या इतने क्षेत्रों में क्यों फैल गई?","optionsHi":["विकास शीर्षगामी रूप से होता है, इसलिए समस्याएँ सिर से नीचे की ओर फैलती हैं","विकास केवल आनुवंशिकता से तय होता है, इसलिए उसके सभी विलंबों का एक ही कारण है","प्रत्येक क्षेत्र में विकास स्वतंत्र रूप से चलता है, इसलिए ये तीन अलग-अलग समस्याएँ हैं","विभिन्न क्षेत्रों में विकास परस्पर संबद्ध होता है, इसलिए एक कठिनाई दूसरों को प्रभावित करती है"],"explanationHi":"शारीरिक, भाषा, सामाजिक और संज्ञानात्मक विकास आपस में जुड़े हैं; श्रवण-हानि वाणी में बाधा डालती है, जो आगे साथियों से अंतःक्रिया और साक्षरता को प्रभावित करती है।"},
  {"id":"cdp-child-development-311","question":"Children who start learning a second language in early childhood usually acquire a native-like accent, whereas those who start as adults rarely do, though adults still learn grammar and vocabulary well. Which idea best explains this?","options":["There are sensitive periods when some kinds of learning come most readily","Development stops completely after puberty, so adults cannot change","Language ability is entirely inherited and is fixed at birth for every person","Adults cannot learn any new language once their first language is set"],"answer":0,"explanation":"A sensitive period is a window of heightened readiness, not an absolute cut-off; adults can still learn a language, just with more difficulty in pronunciation, so B and D overstate it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"जो बच्चे प्रारंभिक बाल्यावस्था में दूसरी भाषा सीखना शुरू करते हैं, वे सामान्यतः मातृभाषा जैसा उच्चारण अर्जित कर लेते हैं, जबकि वयस्कता में शुरू करने वाले शायद ही कर पाते हैं, यद्यपि वयस्क व्याकरण और शब्दावली अच्छी तरह सीख लेते हैं। कौन-सा विचार इसे सबसे अच्छी तरह समझाता है?","optionsHi":["संवेदनशील अवधियाँ होती हैं जब कुछ प्रकार का अधिगम सबसे सहजता से होता है","यौवनारंभ के बाद विकास पूरी तरह रुक जाता है, इसलिए वयस्क बदल नहीं सकते","भाषा-क्षमता पूरी तरह वंशानुगत होती है और हर व्यक्ति के लिए जन्म से निश्चित होती है","पहली भाषा तय हो जाने के बाद वयस्क कोई नई भाषा नहीं सीख सकते"],"explanationHi":"संवेदनशील अवधि बढ़ी हुई तत्परता की एक खिड़की है, पूर्ण सीमा नहीं; वयस्क अब भी भाषा सीख सकते हैं, बस उच्चारण में अधिक कठिनाई के साथ, इसलिए B और D अतिशयोक्ति करते हैं।"},
  {"id":"cdp-child-development-312","question":"Which of these statements are correct? I. The sequence of development is largely similar across children. II. The rate of development is the same for all children of an age. III. Development results from interaction between heredity and environment. IV. Growth and development mean the same thing.","options":["I and III only","I, II and III only","II and IV only","I, III and IV only"],"answer":0,"explanation":"Sequence is common and heredity–environment interact (I, III). The rate differs between children (II false) and growth is quantitative while development is broader, including qualitative change (IV false).","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"इनमें से कौन-से कथन सही हैं? I. विकास का क्रम बच्चों में काफी हद तक समान होता है। II. विकास की दर एक आयु के सभी बच्चों के लिए समान होती है। III. विकास आनुवंशिकता और पर्यावरण की अंतःक्रिया से होता है। IV. वृद्धि और विकास का एक ही अर्थ है।","optionsHi":["केवल I और III","केवल I, II और III","केवल II और IV","केवल I, III और IV"],"explanationHi":"क्रम साझा होता है और आनुवंशिकता–पर्यावरण अंतःक्रिया करते हैं (I, III)। दर बच्चों में अलग-अलग होती है (II गलत) और वृद्धि मात्रात्मक है जबकि विकास व्यापक है, जिसमें गुणात्मक परिवर्तन भी शामिल है (IV गलत)।"},
  {"id":"cdp-child-development-313","question":"An LKG teacher has children make big arm movements tracing shapes in sand and on the board, then crayon work on large sheets, and only later pencil work in four-line notebooks. Which principle is she following?","options":["Cephalocaudal","Proximodistal","Individual differences","Development is reversible"],"answer":1,"explanation":"Control spreads from the shoulder and arm (near the body’s centre) to the wrist and fingers, so large movements precede fine pencil grip: proximodistal.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक LKG शिक्षिका बच्चों से रेत में और बोर्ड पर आकृतियाँ बनाने में बाँह की बड़ी गतियाँ करवाती है, फिर बड़े चार्ट पर क्रेयॉन का कार्य, और उसके बाद ही चार-रेखा वाली कॉपियों में पेंसिल का कार्य। वह किस सिद्धांत का पालन कर रही है?","optionsHi":["शीर्षगामी","निकट-दूर","वैयक्तिक भिन्नता","विकास उत्क्रमणीय है"],"explanationHi":"नियंत्रण कंधे और बाँह (शरीर के केंद्र के निकट) से कलाई और उँगलियों की ओर फैलता है, इसलिए बड़ी गतियाँ बारीक पेंसिल पकड़ से पहले आती हैं: निकट-दूर।"},
  {"id":"cdp-child-development-314","question":"Two boys inherit a similar potential for height, but one suffers chronic malnutrition and ends up much shorter. Which statement best captures the heredity–environment relationship here?","options":["Heredity fixes the exact height a child will reach, whatever he eats or does","Environment alone decides height, so the boys’ shared heredity is irrelevant here","Heredity sets a range, and environment largely decides where within it a child ends up","A height lost through malnutrition will be inherited by the shorter boy’s children"],"answer":2,"explanation":"Heredity sets limits (a reaction range); nutrition and care determine how much of that potential is realised. D is the Lamarckian misconception that acquired traits are inherited.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"दो लड़कों को ऊँचाई की समान संभाव्यता वंशानुगत मिली है, पर एक को दीर्घकालिक कुपोषण होता है और वह काफी छोटा रह जाता है। कौन-सा कथन यहाँ आनुवंशिकता–पर्यावरण संबंध को सबसे अच्छी तरह दर्शाता है?","optionsHi":["आनुवंशिकता बच्चे की पहुँचने वाली ठीक ऊँचाई तय करती है, चाहे वह कुछ भी खाए या करे","अकेला पर्यावरण ऊँचाई तय करता है, इसलिए यहाँ लड़कों की साझा आनुवंशिकता अप्रासंगिक है","आनुवंशिकता एक सीमा तय करती है, और पर्यावरण काफी हद तक तय करता है कि बच्चा उसके भीतर कहाँ पहुँचता है","कुपोषण से घटी ऊँचाई छोटे लड़के के बच्चों को वंशानुगत मिलेगी"],"explanationHi":"आनुवंशिकता सीमाएँ तय करती है (प्रतिक्रिया-सीमा); पोषण और देखभाल तय करते हैं कि उस क्षमता का कितना साकार होता है। D लैमार्कवादी भ्रांति है कि अर्जित लक्षण वंशानुगत होते हैं।"},
  {"id":"cdp-child-development-315","question":"Many Class 6 students in a Kendriya Vidyalaya are weak in fractions. Which step best reflects the principle that development and learning are continuous and cumulative?","options":["Start the Class 6 syllabus as written, since earlier learning does not matter","Find out what students already know about parts and wholes and build on it","Conclude that the weak students lack the inherited ability for mathematics","Wait, because maturation alone will remove the gap as they grow older"],"answer":1,"explanation":"Because each new stage builds on earlier ones, gaps must be identified and bridged from where children are. C wrongly blames heredity; D wrongly leaves learning to maturation.","difficulty":"moderate","source":"KVS TGT · NVS","questionHi":"केंद्रीय विद्यालय में कक्षा 6 के कई विद्यार्थी भिन्नों में कमज़ोर हैं। विकास और अधिगम के सतत और संचयी होने के सिद्धांत को कौन-सा कदम सबसे अच्छी तरह दर्शाता है?","optionsHi":["कक्षा 6 का पाठ्यक्रम जैसा लिखा है वैसा शुरू करना, क्योंकि पहले का अधिगम मायने नहीं रखता","पता लगाना कि विद्यार्थी भाग और पूर्ण के बारे में पहले से क्या जानते हैं और उस पर निर्माण करना","निष्कर्ष निकालना कि कमज़ोर विद्यार्थियों में गणित की वंशानुगत योग्यता नहीं है","प्रतीक्षा करना, क्योंकि बड़े होने के साथ परिपक्वता अकेले ही अंतर मिटा देगी"],"explanationHi":"चूँकि प्रत्येक नई अवस्था पहले की अवस्थाओं पर बनती है, इसलिए अंतरों को पहचानकर वहीं से पाटना चाहिए जहाँ बच्चे हैं। C गलत ढंग से आनुवंशिकता को दोष देता है; D गलत ढंग से अधिगम को परिपक्वता पर छोड़ देता है।"},
  {"id":"cdp-child-development-316","question":"A teacher declares, ‘Give me any child and I can make him a doctor or a thief; it depends only on how I train him.’ Which is the soundest criticism of this view?","options":["It overstates the role of heredity, which training can easily overcome","It ignores the limits set by heredity and maturation, and individual differences","It is fully correct, since learning is all that matters in development","It ignores the role of reinforcement and punishment in shaping learning"],"answer":1,"explanation":"This echoes Watson’s extreme environmentalism; it ignores the contribution of heredity, maturation and individual differences. A gets the direction backwards, and D misses that reinforcement IS the training it relies on.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक शिक्षक घोषणा करता है, ‘मुझे कोई भी बच्चा दे दो और मैं उसे डॉक्टर या चोर बना सकता हूँ; यह केवल इस पर निर्भर करता है कि मैं उसे कैसे प्रशिक्षित करता हूँ।’ इस मत की सबसे सुदृढ़ आलोचना कौन-सी है?","optionsHi":["यह आनुवंशिकता की भूमिका को बढ़ा-चढ़ाकर बताता है, जिसे प्रशिक्षण आसानी से पार कर सकता है","यह आनुवंशिकता और परिपक्वता द्वारा तय सीमाओं और वैयक्तिक भिन्नताओं की उपेक्षा करता है","यह पूर्णतः सही है, क्योंकि विकास में केवल अधिगम मायने रखता है","यह अधिगम को आकार देने में पुनर्बलन और दंड की भूमिका की उपेक्षा करता है"],"explanationHi":"यह वॉटसन के चरम पर्यावरणवाद की प्रतिध्वनि है; यह आनुवंशिकता, परिपक्वता और वैयक्तिक भिन्नताओं के योगदान की उपेक्षा करता है। A दिशा उलटा लेता है, और D यह चूक जाता है कि पुनर्बलन ही वह प्रशिक्षण है जिस पर वह निर्भर है।"},
  {"id":"cdp-child-development-317","question":"In adoption studies, children’s IQ scores tend to correlate more with their biological parents’ scores than with their adoptive parents’, yet children adopted into enriched homes often score higher on average than expected. What is the best conclusion?","options":["Only heredity matters, because the correlations follow the biological parents, not the adoptive ones","Only environment matters, because the average scores of adopted children rose","Heredity relates to individual differences; a better environment can raise the average level","Neither heredity nor environment affects intelligence, as the two results conflict"],"answer":2,"explanation":"Correlation reflects rank-order similarity (largely linked to heredity), whereas the mean level can shift with environment; both findings together show interaction, not one factor alone.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"गोद लेने के अध्ययनों में, बच्चों के IQ अंक उनके दत्तक माता-पिता के अंकों की तुलना में जैविक माता-पिता के अंकों से अधिक सहसंबद्ध होते हैं, फिर भी समृद्ध घरों में गोद लिए गए बच्चे प्रायः अपेक्षा से औसतन अधिक अंक पाते हैं। सबसे अच्छा निष्कर्ष क्या है?","optionsHi":["केवल आनुवंशिकता मायने रखती है, क्योंकि सहसंबंध जैविक माता-पिता का अनुसरण करते हैं, दत्तक का नहीं","केवल पर्यावरण मायने रखता है, क्योंकि गोद लिए गए बच्चों के औसत अंक बढ़े","आनुवंशिकता वैयक्तिक भिन्नताओं से संबंधित है; बेहतर पर्यावरण औसत स्तर को बढ़ा सकता है","न आनुवंशिकता न पर्यावरण बुद्धि को प्रभावित करता है, क्योंकि दोनों परिणाम परस्पर विरोधी हैं"],"explanationHi":"सहसंबंध क्रम-स्थिति की समानता को दर्शाता है (काफी हद तक आनुवंशिकता से जुड़ा), जबकि माध्य स्तर पर्यावरण से बदल सकता है; दोनों निष्कर्ष मिलकर अंतःक्रिया दिखाते हैं, किसी एक कारक को नहीं।"},
  {"id":"cdp-child-development-318","question":"Which of the following does NOT illustrate the cephalocaudal principle?","options":["An infant controls eye and neck movements before controlling the trunk","At birth the head is proportionally the largest part of the body","A baby controls arm movements before finger movements","A baby sits before she stands"],"answer":2,"explanation":"Arm before fingers is centre-to-periphery, i.e. proximodistal. The other three show the head-to-tail order of cephalocaudal development.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"निम्नलिखित में से कौन-सा शीर्षगामी सिद्धांत का उदाहरण नहीं है?","optionsHi":["शिशु धड़ पर नियंत्रण से पहले आँखों और गर्दन की गतियों पर नियंत्रण करता है","जन्म के समय सिर शरीर का अनुपातिक रूप से सबसे बड़ा भाग होता है","शिशु उँगलियों की गतियों से पहले बाँह की गतियों पर नियंत्रण करता है","शिशु खड़ा होने से पहले बैठता है"],"explanationHi":"उँगलियों से पहले बाँह केंद्र-से-परिधि है, यानी निकट-दूर। अन्य तीन शीर्षगामी विकास के सिर-से-पूँछ के क्रम को दर्शाते हैं।"},
  {"id":"cdp-child-development-319","question":"Infants can distinguish speech sounds from many languages, but by around their first birthday they become expert in the sounds of their mother tongue and lose some ability to tell apart sounds their language does not use. Which view of development does this support?","options":["Development is a one-way process of gains only","Development is fixed entirely by heredity","Development proceeds from head to toe","Development involves both gains and losses"],"answer":3,"explanation":"Specialising in the home language (a gain) comes with reduced sensitivity to foreign contrasts (a loss): development is multidirectional, not only accumulation.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"शिशु कई भाषाओं की वाक्-ध्वनियों में भेद कर सकते हैं, पर अपने पहले जन्मदिन के आसपास तक वे अपनी मातृभाषा की ध्वनियों में निपुण हो जाते हैं और उन ध्वनियों में भेद करने की कुछ क्षमता खो देते हैं जिन्हें उनकी भाषा प्रयोग नहीं करती। यह विकास के किस दृष्टिकोण का समर्थन करता है?","optionsHi":["विकास केवल लाभों की एकदिशीय प्रक्रिया है","विकास पूरी तरह आनुवंशिकता से निश्चित होता है","विकास सिर से पैर की ओर होता है","विकास में लाभ और हानि दोनों शामिल हैं"],"explanationHi":"घर की भाषा में विशेषज्ञता (एक लाभ) के साथ विदेशी विरोधाभासों के प्रति घटी संवेदनशीलता (एक हानि) आती है: विकास बहुदिशात्मक है, केवल संचय नहीं।"},
  {"id":"cdp-child-development-320","question":"Assertion (A): Early childhood experiences have a strong influence on later development. Reason (R): Development is cumulative, with later abilities built on earlier ones.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because each stage builds on what came before, early experiences lay the base for later development; R directly explains A.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"अभिकथन (A): प्रारंभिक बाल्यावस्था के अनुभवों का बाद के विकास पर सशक्त प्रभाव पड़ता है। कारण (R): विकास संचयी है, जिसमें बाद की योग्यताएँ पहले की योग्यताओं पर बनती हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"चूँकि प्रत्येक अवस्था उससे पहले आई अवस्था पर बनती है, प्रारंभिक अनुभव बाद के विकास की नींव रखते हैं; R सीधे A की व्याख्या करता है।"},
  {"id":"cdp-child-development-321","question":"Phenylketonuria (PKU) is a genetic disorder that, untreated, causes intellectual disability; a special diet started in infancy largely prevents this. What does PKU best demonstrate?","options":["Genetic traits can never be modified by the environment a child grows up in","Intelligence is determined by environment alone, here by the child's diet","Diet changes a child’s genes so the disorder is no longer inherited","The effect of a genetic condition can depend on environmental conditions"],"answer":3,"explanation":"The gene is unchanged, but the environment (diet) changes its outcome: heredity and environment interact, and ‘genetic’ does not mean ‘unchangeable’.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"फेनिलकीटोन्यूरिया (PKU) एक आनुवंशिक विकार है जो अनुपचारित रहने पर बौद्धिक अक्षमता पैदा करता है; शैशवावस्था में शुरू किया गया विशेष आहार इसे काफी हद तक रोकता है। PKU सबसे अच्छी तरह क्या प्रदर्शित करता है?","optionsHi":["आनुवंशिक लक्षण बच्चे के पलने के पर्यावरण से कभी बदले नहीं जा सकते","बुद्धि केवल पर्यावरण से निर्धारित होती है, यहाँ बच्चे के आहार से","आहार बच्चे के जीन बदल देता है, इसलिए विकार अब वंशानुगत नहीं रहता","किसी आनुवंशिक स्थिति का प्रभाव पर्यावरणीय परिस्थितियों पर निर्भर कर सकता है"],"explanationHi":"जीन अपरिवर्तित रहता है, पर पर्यावरण (आहार) उसका परिणाम बदल देता है: आनुवंशिकता और पर्यावरण अंतःक्रिया करते हैं, और ‘आनुवंशिक’ का अर्थ ‘अपरिवर्तनीय’ नहीं है।"},
  {"id":"cdp-child-development-322","question":"What is the most appropriate way for a primary teacher to use developmental norms such as ‘most children can hop on one foot by age four’?","options":["Label any child who is even a month behind the norm as abnormal and refer him at once","Ignore norms completely, since every child is unique and cannot be compared with others","Promote to the next class only those children who meet every single norm on time","Use norms as broad guides to flag children for closer observation, allowing for variation"],"answer":3,"explanation":"Norms are averages around which normal variation is wide; they flag children for observation, not for labelling or detention. Option D balances predictability of sequence with individual differences in rate.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"‘अधिकांश बच्चे चार वर्ष की आयु तक एक पैर पर कूद सकते हैं’ जैसे विकासात्मक मानकों का उपयोग करने का प्राथमिक शिक्षक के लिए सबसे उपयुक्त तरीका क्या है?","optionsHi":["मानक से एक माह भी पीछे रहने वाले किसी भी बच्चे को असामान्य कहना और तुरंत संदर्भित करना","मानकों को पूरी तरह अनदेखा करना, क्योंकि हर बच्चा अद्वितीय है और उसकी दूसरों से तुलना नहीं हो सकती","अगली कक्षा में केवल उन्हीं बच्चों को पदोन्नत करना जो हर एक मानक को समय पर पूरा करें","मानकों को व्यापक मार्गदर्शक के रूप में उपयोग करना जो बच्चों को निकट अवलोकन के लिए चिह्नित करें, विविधता का ध्यान रखते हुए"],"explanationHi":"मानक औसत हैं जिनके आसपास सामान्य विविधता व्यापक होती है; वे बच्चों को अवलोकन के लिए चिह्नित करते हैं, लेबल लगाने या रोकने के लिए नहीं। विकल्प D क्रम की पूर्वानुमेयता को दर की वैयक्तिक भिन्नताओं के साथ संतुलित करता है।"},
  {"id":"cdp-child-development-323","question":"An eight-year-old not only knows more words than a four-year-old but also sorts objects into categories like ‘fruits’ and ‘vehicles’, whereas the younger child groups them by colour. The second change is best described as:","options":["Quantitative change, i.e. growth in size","Maturation without any learning","Cephalocaudal change","Qualitative change in development"],"answer":3,"explanation":"Knowing more words is a quantitative increase; a new way of organising knowledge (taxonomic rather than perceptual) is a qualitative change, which is what distinguishes development from mere growth.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"एक आठ वर्ष का बच्चा न केवल चार वर्ष के बच्चे से अधिक शब्द जानता है, बल्कि वस्तुओं को ‘फल’ और ‘वाहन’ जैसी श्रेणियों में छाँटता भी है, जबकि छोटा बच्चा उन्हें रंग के आधार पर समूहित करता है। दूसरे परिवर्तन का सबसे अच्छा वर्णन है:","optionsHi":["मात्रात्मक परिवर्तन, यानी आकार में वृद्धि","बिना किसी अधिगम के परिपक्वता","शीर्षगामी परिवर्तन","विकास में गुणात्मक परिवर्तन"],"explanationHi":"अधिक शब्द जानना मात्रात्मक वृद्धि है; ज्ञान को संगठित करने का नया तरीका (प्रत्यक्षण-आधारित नहीं, वर्गिकी-आधारित) गुणात्मक परिवर्तन है, जो विकास को मात्र वृद्धि से अलग करता है।"},
  {"id":"cdp-child-development-324","question":"Which classroom situation best reflects the principle that development is a product of heredity and environment working together rather than of either alone?","options":["A teacher assumes a child of illiterate parents can never learn to read well, whatever the teaching","A child with an aptitude for drawing improves greatly once given materials, time and guidance","A teacher believes rigorous daily drill can turn every child in the class into a top athlete","A child’s height is attributed solely to the diet provided at home"],"answer":1,"explanation":"Aptitude (heredity) flowers only with opportunity and guidance (environment). A wrongly treats heredity as destiny, C overstates environment, D ignores genetic potential.","difficulty":"moderate","source":"KVS PRT · NVS","questionHi":"कौन-सी कक्षा-स्थिति इस सिद्धांत को सबसे अच्छी तरह दर्शाती है कि विकास आनुवंशिकता और पर्यावरण के साथ मिलकर काम करने का उत्पाद है, न कि किसी एक का?","optionsHi":["शिक्षक मानता है कि निरक्षर माता-पिता का बच्चा शिक्षण चाहे जैसा हो, कभी अच्छा पढ़ना नहीं सीख सकता","चित्रकारी की अभिक्षमता वाला बच्चा सामग्री, समय और मार्गदर्शन मिलने पर बहुत सुधर जाता है","शिक्षक मानता है कि कड़ा दैनिक अभ्यास कक्षा के हर बच्चे को शीर्ष एथलीट बना सकता है","बच्चे की ऊँचाई का श्रेय केवल घर पर मिलने वाले आहार को दिया जाता है"],"explanationHi":"अभिक्षमता (आनुवंशिकता) केवल अवसर और मार्गदर्शन (पर्यावरण) से खिलती है। A गलत ढंग से आनुवंशिकता को नियति मानता है, C पर्यावरण को बढ़ा-चढ़ाकर बताता है, D आनुवंशिक क्षमता की उपेक्षा करता है।"},
  {"id":"cdp-child-development-325","question":"How many of these statements about growth and development are correct? I. Development continues through life, while physical growth largely stops at maturity. II. Development can be both progressive and regressive, as in old age. III. Development is predictable in direction. IV. All aspects of development proceed at the same rate in a child.","options":["One","Two","Three","Four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: different domains develop at different rates, e.g. the brain grows fastest early, reproductive organs at puberty.","difficulty":"very-hard","source":"CTET Paper 2 · State TET","questionHi":"वृद्धि और विकास के बारे में इनमें से कितने कथन सही हैं? I. विकास जीवन भर चलता है, जबकि शारीरिक वृद्धि प्रायः परिपक्वता पर रुक जाती है। II. विकास प्रगतिशील और प्रतिगामी दोनों हो सकता है, जैसे वृद्धावस्था में। III. विकास दिशा में पूर्वानुमेय है। IV. बच्चे में विकास के सभी पहलू एक ही दर से आगे बढ़ते हैं।","optionsHi":["एक","दो","तीन","चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: विभिन्न क्षेत्र अलग-अलग दरों पर विकसित होते हैं, जैसे मस्तिष्क शुरू में सबसे तेज़ बढ़ता है, प्रजनन अंग यौवनारंभ पर।"},
  {"id":"cdp-child-development-326","question":"Ritika, a Class 3 student in a Jaipur school, has a moderate hearing loss and uses hearing aids. Which teacher practice will help her most during whole-class explanation?","options":["Speaking much louder than usual and exaggerating lip movements so that she can catch every single word","Seating her at the back so that she is not singled out, and giving her a copy of the notes later","Facing the class at a natural pace, seating her near the front with a view of faces, and adding written key words","Excusing her from oral discussions and giving her written work instead, since listening is tiring for her"],"answer":2,"explanation":"Speech-reading needs a clear view of a natural, unexaggerated face, and visual back-up fills the gaps; shouting distorts sound through hearing aids and exaggerated lips mislead, while exclusion from discussion defeats inclusion.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"जयपुर के एक विद्यालय में कक्षा 3 की रितिका को मध्यम श्रवण-हानि है और वह श्रवण-यंत्र का उपयोग करती है। पूरी कक्षा को समझाने के दौरान शिक्षक का कौन-सा व्यवहार उसकी सबसे अधिक मदद करेगा?","optionsHi":["सामान्य से बहुत ज़ोर से बोलना और होंठों की गतियों को बढ़ा-चढ़ाकर दिखाना ताकि वह हर शब्द पकड़ सके","उसे पीछे बैठाना ताकि वह अलग न दिखे, और बाद में उसे नोट्स की प्रति देना","स्वाभाविक गति से कक्षा की ओर मुख करके बोलना, उसे चेहरे दिखने वाली जगह पर आगे बैठाना, और लिखित मुख्य शब्द जोड़ना","उसे मौखिक चर्चाओं से छूट देना और उसकी जगह लिखित कार्य देना, क्योंकि उसके लिए सुनना थकाने वाला है"],"explanationHi":"वाक्-पठन के लिए स्वाभाविक, अतिरंजित न किए गए चेहरे का स्पष्ट दृश्य चाहिए, और दृश्य सहायता कमियों को भरती है; चिल्लाना श्रवण-यंत्रों के माध्यम से ध्वनि को विकृत करता है और बढ़ा-चढ़ाकर बने होंठ भ्रमित करते हैं, जबकि चर्चा से बाहर रखना समावेशन को विफल करता है।"},
  {"id":"cdp-child-development-327","question":"Assertion (A): In an inclusive class, a child with a disability must be assessed on exactly the same task, in the same mode and time, as everyone else, otherwise the assessment is unfair. Reason (R): Equity in education means giving every child identical treatment.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","Both A and R are false"],"answer":3,"explanation":"Equity means giving each child what she needs to reach the same goal (e.g. extra time, a scribe, Braille), which is equality of opportunity, not identical treatment; so both A and R are false.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): समावेशी कक्षा में दिव्यांग बच्चे का आकलन ठीक उसी कार्य पर, उसी माध्यम और समय में होना चाहिए जैसा सबका, अन्यथा आकलन अनुचित है। कारण (R): शिक्षा में समता का अर्थ है हर बच्चे के साथ समान व्यवहार करना।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A और R दोनों असत्य हैं"],"explanationHi":"समता का अर्थ है हर बच्चे को वह देना जिसकी उसे समान लक्ष्य तक पहुँचने के लिए आवश्यकता है (जैसे अतिरिक्त समय, लेखक, ब्रेल), जो अवसर की समानता है, समान व्यवहार नहीं; इसलिए A और R दोनों असत्य हैं।"},
  {"id":"cdp-child-development-328","question":"Match the arrangement with its description. 1. Segregation 2. Integration 3. Inclusion 4. Exclusion; a. The child is denied access to any form of schooling b. Children with disabilities are taught in separate special schools c. The child is placed in a regular class but must adapt to an unchanged system d. The regular school changes its curriculum, teaching and environment so that all children learn together","options":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-d, 4-a","1-b, 2-d, 3-c, 4-a","1-a, 2-c, 3-d, 4-b"],"answer":1,"explanation":"Segregation separates, integration places the child in the mainstream but expects her to fit in, and inclusion changes the system to fit every child; exclusion keeps her out altogether.","difficulty":"moderate","source":"CTET · KVS · DSSSB","questionHi":"व्यवस्था का मिलान उसके वर्णन से कीजिए। 1. पृथक्करण 2. एकीकरण 3. समावेशन 4. बहिष्करण; a. बच्चे को किसी भी प्रकार की स्कूली शिक्षा तक पहुँच से वंचित किया जाता है b. दिव्यांग बच्चों को अलग विशेष विद्यालयों में पढ़ाया जाता है c. बच्चे को सामान्य कक्षा में रखा जाता है पर उसे एक अपरिवर्तित प्रणाली के अनुरूप ढलना पड़ता है d. सामान्य विद्यालय अपनी पाठ्यचर्या, शिक्षण और परिवेश बदलता है ताकि सभी बच्चे साथ सीखें","optionsHi":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-d, 4-a","1-b, 2-d, 3-c, 4-a","1-a, 2-c, 3-d, 4-b"],"explanationHi":"पृथक्करण अलग करता है, एकीकरण बच्चे को मुख्यधारा में रखता है पर उससे ढलने की अपेक्षा करता है, और समावेशन हर बच्चे के अनुकूल प्रणाली बदलता है; बहिष्करण उसे पूरी तरह बाहर रखता है।"},
  {"id":"cdp-child-development-329","question":"Fatima, in Class 4 at a Lucknow school, reads fluently and writes well-organised stories. Yet she still counts on her fingers to decide whether 7 or 4 is larger, cannot estimate whether 48 + 39 is nearer 90 or 50, and keeps mixing up the steps of subtraction. Her difficulty most likely points to:","options":["Dyslexia","Dyscalculia","Dysgraphia","Mild intellectual disability"],"answer":1,"explanation":"A specific, unexpected weakness in number sense, magnitude comparison and arithmetic procedures, with strong reading and writing, fits dyscalculia; intellectual disability would show a general delay across areas.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"लखनऊ के एक विद्यालय में कक्षा 4 की फातिमा धाराप्रवाह पढ़ती है और सुव्यवस्थित कहानियाँ लिखती है। फिर भी वह यह तय करने के लिए उँगलियों पर गिनती है कि 7 या 4 बड़ा है, अनुमान नहीं लगा पाती कि 48 + 39 की संख्या 90 के निकट है या 50 के, और घटाव के चरण गड़बड़ करती रहती है। उसकी कठिनाई सबसे संभावित रूप से किस ओर इशारा करती है?","optionsHi":["डिस्लेक्सिया","डिस्कैल्कुलिया","डिसग्राफिया","हल्की बौद्धिक अक्षमता"],"explanationHi":"मज़बूत पठन और लेखन के साथ संख्या-बोध, परिमाण-तुलना और अंकगणितीय प्रक्रियाओं में विशिष्ट, अप्रत्याशित कमज़ोरी डिस्कैल्कुलिया से मेल खाती है; बौद्धिक अक्षमता सभी क्षेत्रों में सामान्य विलंब दिखाती।"},
  {"id":"cdp-child-development-330","question":"Kabir, in Class 5, gives rich oral answers and reads well, plays cricket and ties his shoelaces easily, but his written work has uneven letter sizes, poor spacing and mixed capitals, and he tires quickly while writing. Which step best supports him without lowering the learning goal?","options":["Letting him show knowledge orally or by typing in tests, with short, targeted handwriting support","Giving him extra copywriting pages as homework every day until his handwriting finally improves","Deducting marks for neatness so that he learns to take more care over his written work","Exempting him from all written subjects so that he is not stressed by writing at all"],"answer":0,"explanation":"His difficulty is specific to the act of writing (dysgraphia), so an alternative mode of expression keeps the content goal intact while the skill is supported separately; extra copying and penalties only punish the disability.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 5 का कबीर समृद्ध मौखिक उत्तर देता है और अच्छा पढ़ता है, क्रिकेट खेलता है और जूतों के फीते आसानी से बाँधता है, पर उसके लिखित कार्य में अक्षरों के आकार असमान, दूरी खराब और बड़े अक्षर मिले-जुले होते हैं, और लिखते समय वह जल्दी थक जाता है। अधिगम-लक्ष्य को घटाए बिना कौन-सा कदम उसकी सबसे अच्छी सहायता करता है?","optionsHi":["उसे परीक्षणों में मौखिक रूप से या टाइप करके ज्ञान दिखाने देना, साथ में छोटी, लक्षित लिखावट सहायता","जब तक उसकी लिखावट सुधर न जाए, रोज़ गृहकार्य में अतिरिक्त नकल-लेखन पृष्ठ देना","साफ़-सफ़ाई के लिए अंक काटना ताकि वह अपने लिखित कार्य पर अधिक ध्यान देना सीखे","उसे सभी लिखित विषयों से छूट देना ताकि वह लिखने से तनावग्रस्त न हो"],"explanationHi":"उसकी कठिनाई लिखने की क्रिया तक विशिष्ट है (डिसग्राफिया), इसलिए अभिव्यक्ति का वैकल्पिक माध्यम विषयवस्तु के लक्ष्य को अक्षुण्ण रखता है जबकि कौशल को अलग से सहारा दिया जाता है; अतिरिक्त नकल और अंक काटना केवल अक्षमता को दंडित करते हैं।"},
  {"id":"cdp-child-development-331","question":"Which of these statements about ADHD are correct? I. The signs must be seen in more than one setting, such as both home and school, not in one class only. II. It is mainly caused by poor parenting and eating too much sugar. III. Children with the mainly inattentive type are often quiet daydreamers who go unnoticed. IV. ADHD is named as one of the 21 specified disabilities in the RPwD Act, 2016.","options":["I, II and III only","III and IV only","I and III only","I, III and IV only"],"answer":2,"explanation":"ADHD shows across settings and the inattentive type is easily missed; the parenting-and-sugar idea is a myth, and the RPwD Act's list includes specific learning disabilities and autism but not ADHD as a separate category.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"ADHD के बारे में इनमें से कौन-से कथन सही हैं? I. लक्षण एक से अधिक परिवेशों में दिखने चाहिए, जैसे घर और विद्यालय दोनों में, केवल एक कक्षा में नहीं। II. यह मुख्यतः खराब परवरिश और बहुत अधिक चीनी खाने से होता है। III. मुख्यतः असावधान प्रकार वाले बच्चे प्रायः शांत दिवास्वप्न देखने वाले होते हैं जिन पर ध्यान नहीं जाता। IV. RPwD अधिनियम, 2016 में ADHD को 21 विनिर्दिष्ट दिव्यांगताओं में से एक के रूप में नामित किया गया है।","optionsHi":["केवल I, II और III","केवल III और IV","केवल I और III","केवल I, III और IV"],"explanationHi":"ADHD कई परिवेशों में दिखता है और असावधान प्रकार आसानी से छूट जाता है; परवरिश-और-चीनी का विचार एक मिथक है, और RPwD अधिनियम की सूची में विशिष्ट अधिगम अक्षमताएँ और ऑटिज़्म शामिल हैं पर ADHD अलग श्रेणी के रूप में नहीं।"},
  {"id":"cdp-child-development-332","question":"Meera, a Class 2 child on the autism spectrum, covers her ears and becomes very distressed every day during morning assembly, when loudspeakers are used. What is the most appropriate response?","options":["Insisting that she stays in the middle of the assembly every day so that she gets used to the noise","Recording each outburst as indiscipline and informing the parents so they can correct her at home","Advising the parents to keep her at home until she outgrows the problem, to avoid upsetting her","Planning a sensory adjustment, such as ear defenders or a quieter spot, with a visual schedule"],"answer":3,"explanation":"Sensory over-sensitivity is common in autism and is real distress, not defiance; reasonable adjustments and predictability let her take part, whereas forced exposure, punishment or exclusion all fail her.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 2 की मीरा, जो ऑटिज़्म स्पेक्ट्रम पर है, हर दिन सुबह की सभा के दौरान, जब लाउडस्पीकर का उपयोग होता है, कानों को ढक लेती है और बहुत परेशान हो जाती है। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["हर दिन उसे सभा के बीच में रहने पर ज़ोर देना ताकि वह शोर की आदी हो जाए","हर आक्रोश को अनुशासनहीनता के रूप में दर्ज करना और माता-पिता को सूचित करना ताकि वे घर पर उसे सुधारें","माता-पिता को सलाह देना कि जब तक वह समस्या से उबर न जाए, उसे घर पर रखें ताकि वह परेशान न हो","दृश्य समय-सारिणी के साथ संवेदी समायोजन की योजना बनाना, जैसे कान ढकने वाले उपकरण (ईयर डिफेंडर) या कोई शांत स्थान"],"explanationHi":"संवेदी अति-संवेदनशीलता ऑटिज़्म में आम है और वास्तविक कष्ट है, अवज्ञा नहीं; उचित समायोजन और पूर्वानुमेयता उसे भाग लेने देते हैं, जबकि ज़बरदस्ती संपर्क, दंड या बहिष्करण सब उसे विफल करते हैं।"},
  {"id":"cdp-child-development-333","question":"A teacher tells her Class 4 students, ‘Come on, pull up your socks for the exam!’ Arjun, who is on the autism spectrum, bends down and pulls up his socks. Which interpretation and response are most appropriate?","options":["He is mocking the teacher, so he should be warned in front of the class to stop such behaviour","He has taken the words literally, so instructions should be literal and idioms taught explicitly","He has a hearing problem and should be referred for an audiometry test before the exam","He is not paying attention and should be moved to the front bench where she can watch him"],"answer":1,"explanation":"Many autistic children take language literally and miss implied meanings; the teacher should say exactly what she means and teach figurative expressions directly, not treat it as defiance.","difficulty":"moderate","source":"CTET · KVS · DSSSB","questionHi":"एक शिक्षिका अपने कक्षा 4 के विद्यार्थियों से कहती है, ‘चलो, परीक्षा के लिए अपने मोज़े ऊपर खींचो!’ (पूरी तैयारी करो)। अर्जुन, जो ऑटिज़्म स्पेक्ट्रम पर है, झुककर अपने मोज़े ऊपर खींच लेता है। कौन-सी व्याख्या और प्रतिक्रिया सबसे उपयुक्त है?","optionsHi":["वह शिक्षिका का मज़ाक उड़ा रहा है, इसलिए कक्षा के सामने उसे ऐसे व्यवहार को रोकने की चेतावनी देनी चाहिए","उसने शब्दों को अक्षरशः लिया है, इसलिए निर्देश शाब्दिक होने चाहिए और मुहावरे स्पष्ट रूप से सिखाए जाने चाहिए","उसे श्रवण समस्या है और परीक्षा से पहले ऑडियोमेट्री जाँच के लिए संदर्भित किया जाना चाहिए","वह ध्यान नहीं दे रहा है और उसे आगे की बेंच पर बैठाया जाना चाहिए जहाँ शिक्षिका उस पर नज़र रख सके"],"explanationHi":"कई ऑटिस्टिक बच्चे भाषा को शाब्दिक रूप से लेते हैं और निहित अर्थ चूक जाते हैं; शिक्षिका को ठीक वही कहना चाहिए जो वह कहना चाहती है और आलंकारिक अभिव्यक्तियाँ सीधे सिखानी चाहिए, इसे अवज्ञा नहीं मानना चाहिए।"},
  {"id":"cdp-child-development-334","question":"Sana, who is totally blind, studies in Class 6 of a government school in Bhopal. The class is starting a unit on triangles and angles. What is the most appropriate plan?","options":["Exempting her from geometry, since it is a visual topic, and giving her extra arithmetic practice instead","Asking a classmate to draw all her figures and write her answers for her, so she keeps pace with the class","Explaining every figure orally in detail, since she can follow spoken descriptions without needing to touch anything","Using raised-line diagrams and cut-outs she can handle, describing the board aloud, and a Taylor frame for sums"],"answer":3,"explanation":"Blind learners build spatial concepts through touch combined with description; tactile materials and adapted tools give her access to the same content, while exemption or dependence on peers denies it.","difficulty":"hard","source":"CTET · State TETs","questionHi":"भोपाल के एक सरकारी विद्यालय की कक्षा 6 में पढ़ने वाली सना पूर्णतः दृष्टिहीन है। कक्षा त्रिभुज और कोण की एक इकाई शुरू कर रही है। सबसे उपयुक्त योजना क्या है?","optionsHi":["उसे ज्यामिति से छूट देना, क्योंकि यह एक दृश्य विषय है, और उसकी जगह अतिरिक्त अंकगणित अभ्यास देना","किसी सहपाठी से उसकी सारी आकृतियाँ बनवाना और उसके उत्तर लिखवाना, ताकि वह कक्षा के साथ चल सके","हर आकृति को विस्तार से मौखिक रूप से समझाना, क्योंकि वह बिना किसी चीज़ को छुए बोले गए वर्णनों को समझ सकती है","उभरी रेखाओं वाले आरेख और काटे हुए आकार जिन्हें वह छू सके, बोर्ड का कार्य ज़ोर से बताना, और सवालों के लिए टेलर फ्रेम का उपयोग"],"explanationHi":"दृष्टिहीन अधिगमकर्ता स्पर्श को वर्णन के साथ जोड़कर स्थानिक अवधारणाएँ बनाते हैं; स्पर्शीय सामग्री और अनुकूलित उपकरण उसे वही विषयवस्तु तक पहुँच देते हैं, जबकि छूट या साथियों पर निर्भरता उसे वंचित करती है।"},
  {"id":"cdp-child-development-335","question":"Parents of Ishaan, a Class 3 child with low vision, ask the teacher not to let him read print because using his weak eyes will ‘use up’ his remaining sight. What is the most appropriate response?","options":["Agree and start teaching him only through Braille and listening, so that his remaining sight is saved","Agree, but let him read print for only a few minutes a day, resting his eyes in between sessions","Explain that using residual vision does not harm it, and support print with large type, magnifiers and good contrast","Explain that low vision usually improves with age, so he can start reading print later when his eyes are stronger"],"answer":2,"explanation":"Using remaining vision does not wear it out; children with low vision are taught to use it efficiently with optical aids and adapted print, with Braille chosen on the basis of functional assessment, not fear.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 3 के कम दृष्टि वाले बच्चे इशान के माता-पिता शिक्षक से कहते हैं कि उसे छपी सामग्री न पढ़ने दें, क्योंकि कमज़ोर आँखों का उपयोग उसकी बची हुई दृष्टि को ‘खत्म’ कर देगा। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["सहमत होना और उसे केवल ब्रेल और सुनने से पढ़ाना शुरू करना, ताकि उसकी बची दृष्टि बचाई जा सके","सहमत होना, पर उसे दिन में केवल कुछ मिनट छपी सामग्री पढ़ने देना, सत्रों के बीच आँखों को आराम देते हुए","समझाना कि अवशिष्ट दृष्टि का उपयोग उसे नुकसान नहीं पहुँचाता, और छपी सामग्री को बड़े अक्षरों, आवर्धकों और अच्छे विपर्यास के साथ सहारा देना","समझाना कि कम दृष्टि प्रायः आयु के साथ सुधरती है, इसलिए वह बाद में छपी सामग्री पढ़ना शुरू कर सकता है जब उसकी आँखें मज़बूत हों"],"explanationHi":"बची हुई दृष्टि का उपयोग उसे घिसाता नहीं; कम दृष्टि वाले बच्चों को प्रकाशीय सहायकों और अनुकूलित छपाई के साथ उसे कुशलता से प्रयोग करना सिखाया जाता है, और ब्रेल का चयन प्रकार्यात्मक आकलन के आधार पर होता है, भय के आधार पर नहीं।"},
  {"id":"cdp-child-development-336","question":"For teaching a Class 3 child with mild intellectual disability, which of the following practices is the LEAST appropriate?","options":["Teaching a general rule in abstract form first and expecting him to apply it on his own","Breaking a skill into small steps and teaching each with demonstration and practice","Using concrete objects and real-life contexts such as shopping with coins at a class shop","Giving frequent, immediate feedback and repeating practice in varied situations"],"answer":0,"explanation":"Children with intellectual disability find abstraction and spontaneous transfer especially difficult, so concepts should start concrete, be broken into steps and be practised across settings; abstract-first teaching is the mismatch.","difficulty":"hard","source":"CTET · State TETs","questionHi":"हल्की बौद्धिक अक्षमता वाले कक्षा 3 के बच्चे को पढ़ाने के लिए निम्नलिखित में से कौन-सी पद्धति सबसे कम उपयुक्त है?","optionsHi":["पहले सामान्य नियम को अमूर्त रूप में पढ़ाना और उससे अपेक्षा करना कि वह उसे स्वयं लागू करे","किसी कौशल को छोटे चरणों में बाँटना और प्रत्येक को प्रदर्शन और अभ्यास के साथ पढ़ाना","मूर्त वस्तुओं और वास्तविक जीवन के संदर्भों का उपयोग करना, जैसे कक्षा की दुकान में सिक्कों से खरीदारी","बार-बार, तत्काल प्रतिपुष्टि देना और विभिन्न स्थितियों में अभ्यास दोहराना"],"explanationHi":"बौद्धिक अक्षमता वाले बच्चों को अमूर्तन और स्वतःस्फूर्त अंतरण विशेष रूप से कठिन लगता है, इसलिए अवधारणाएँ मूर्त से शुरू हों, चरणों में बँटी हों और विभिन्न परिवेशों में अभ्यास की जाएँ; अमूर्त-पहले शिक्षण बेमेल है।"},
  {"id":"cdp-child-development-337","question":"A school selects children for its ‘gifted’ programme only by their scores on a timed IQ test. Which view of giftedness most directly challenges this practice?","options":["Spearman’s idea of a general factor ‘g’ that underlies performance on all mental tasks","Renzulli’s view that giftedness is ability interacting with creativity and task commitment","Binet’s concept of mental age, measured through tasks graded by difficulty for each age","Terman’s long-term study, which identified gifted children by their high IQ scores alone"],"answer":1,"explanation":"Renzulli argued that ability alone is not giftedness; creativity and task commitment must interact with it, so a single IQ cut-off misses many gifted learners. The other three views support or rely on IQ measurement.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"एक विद्यालय अपने ‘प्रतिभाशाली’ कार्यक्रम के लिए बच्चों का चयन केवल समयबद्ध IQ परीक्षण में उनके अंकों से करता है। प्रतिभाशालिता का कौन-सा दृष्टिकोण इस प्रथा को सबसे सीधे चुनौती देता है?","optionsHi":["स्पीयरमैन का सामान्य कारक ‘g’ का विचार, जो सभी मानसिक कार्यों के निष्पादन का आधार है","रेंज़ुली का मत कि प्रतिभाशालिता योग्यता की सृजनशीलता और कार्य-प्रतिबद्धता के साथ अंतःक्रिया है","बिने की मानसिक आयु की अवधारणा, जिसे प्रत्येक आयु के लिए कठिनाई के अनुसार श्रेणीबद्ध कार्यों से मापा जाता है","टरमन का दीर्घकालिक अध्ययन, जिसने प्रतिभाशाली बच्चों को केवल उनके उच्च IQ अंकों से पहचाना"],"explanationHi":"रेंज़ुली ने तर्क दिया कि अकेली योग्यता प्रतिभाशालिता नहीं है; सृजनशीलता और कार्य-प्रतिबद्धता को उससे अंतःक्रिया करनी चाहिए, इसलिए एक ही IQ सीमा कई प्रतिभाशाली अधिगमकर्ताओं को चूक जाती है। अन्य तीन दृष्टिकोण IQ मापन का समर्थन करते हैं या उस पर निर्भर हैं।"},
  {"id":"cdp-child-development-338","question":"After a unit on the water cycle, a Class 5 teacher lets each child show what they have learnt through a labelled poster, a short skit, a written paragraph or a working model. Which principle of Universal Design for Learning is she applying most directly?","options":["Multiple means of representation of content","Multiple means of engagement and interest","Multiple means of action and expression","Differentiation by content"],"answer":2,"explanation":"Offering several ways for learners to demonstrate understanding is ‘action and expression’ (the ‘how’ of learning); representation concerns how content is presented, and engagement concerns interest and motivation.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"जलचक्र की एक इकाई के बाद कक्षा 5 की एक शिक्षिका हर बच्चे को नामांकित पोस्टर, छोटी नाटिका, लिखित अनुच्छेद या कार्यशील मॉडल के माध्यम से दिखाने देती है कि उसने क्या सीखा। वह अधिगम के सार्वभौमिक डिज़ाइन के किस सिद्धांत को सबसे सीधे लागू कर रही है?","optionsHi":["विषयवस्तु के निरूपण के अनेक साधन","जुड़ाव और रुचि के अनेक साधन","क्रिया और अभिव्यक्ति के अनेक साधन","विषयवस्तु द्वारा विभेदन"],"explanationHi":"अधिगमकर्ताओं को समझ दिखाने के कई तरीके देना ‘क्रिया और अभिव्यक्ति’ (अधिगम का ‘कैसे’) है; निरूपण इससे संबंधित है कि विषयवस्तु कैसे प्रस्तुत की जाती है, और जुड़ाव रुचि और अभिप्रेरणा से।"},
  {"id":"cdp-child-development-339","question":"Assertion (A): Universal Design for Learning builds flexible options into a lesson from the planning stage, instead of adding special modifications after some children fail. Reason (R): Universal Design for Learning is meant only for children with certified disabilities.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"UDL designs for learner variability from the start, which benefits every learner (like a ramp that also helps people with prams), so it is not limited to children with disabilities.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): अधिगम का सार्वभौमिक डिज़ाइन पाठ की योजना के चरण से ही लचीले विकल्प बनाता है, कुछ बच्चों के असफल होने के बाद विशेष संशोधन जोड़ने के बजाय। कारण (R): अधिगम का सार्वभौमिक डिज़ाइन केवल प्रमाणित दिव्यांगता वाले बच्चों के लिए है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"UDL शुरू से ही अधिगमकर्ता की विविधता के लिए डिज़ाइन करता है, जिससे हर अधिगमकर्ता को लाभ होता है (उस रैंप की तरह जो बच्चागाड़ी वालों की भी मदद करता है), इसलिए यह दिव्यांग बच्चों तक सीमित नहीं है।"},
  {"id":"cdp-child-development-340","question":"Before teaching fractions, a Class 4 teacher gives a short pre-test. Based on it, one group folds paper strips, a second uses fraction cards on a number line, and a third solves word problems, all working towards the same learning goal. She is differentiating:","options":["Content, according to students’ interests","Product, according to students’ learning profiles","Process, according to students’ readiness","The learning environment, according to students’ interests"],"answer":2,"explanation":"Different activities towards the same goal is differentiation of process, and grouping on pre-test results is differentiation by readiness; the product (what they finally show) and content (the goal) stay the same.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"भिन्न पढ़ाने से पहले कक्षा 4 की एक शिक्षिका एक छोटा पूर्व-परीक्षण देती है। उसके आधार पर एक समूह कागज़ की पट्टियाँ मोड़ता है, दूसरा संख्या रेखा पर भिन्न-कार्ड का उपयोग करता है, और तीसरा शब्द-प्रश्न हल करता है, सभी एक ही अधिगम-लक्ष्य की ओर कार्य करते हैं। वह किसका विभेदन कर रही है?","optionsHi":["विषयवस्तु, विद्यार्थियों की रुचियों के अनुसार","उत्पाद, विद्यार्थियों के अधिगम प्रोफ़ाइल के अनुसार","प्रक्रिया, विद्यार्थियों की तत्परता के अनुसार","अधिगम परिवेश, विद्यार्थियों की रुचियों के अनुसार"],"explanationHi":"एक ही लक्ष्य की ओर भिन्न गतिविधियाँ प्रक्रिया का विभेदन हैं, और पूर्व-परीक्षण के परिणामों पर समूह बनाना तत्परता के अनुसार विभेदन है; उत्पाद (अंततः वे क्या दिखाते हैं) और विषयवस्तु (लक्ष्य) वही रहते हैं।"},
  {"id":"cdp-child-development-341","question":"A teacher who claims to practise differentiated instruction divides her class in April into fixed ‘slow’, ‘average’ and ‘bright’ groups that stay the same for the whole year. What is the main problem with this?","options":["Differentiation requires that all children always do exactly the same task at the same pace","Fixed groups are the correct method; the only issue is that the names should be kept secret","Grouping of any kind is against inclusive education and should be avoided in every class","Fixed ability groups become tracking; differentiation needs flexible groups that change"],"answer":3,"explanation":"Differentiation relies on flexible grouping that shifts by task and by fresh evidence; fixed groups label children and can create a self-fulfilling prophecy, while grouping itself is not the problem.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षिका जो विभेदित अनुदेशन का अभ्यास करने का दावा करती है, अप्रैल में अपनी कक्षा को निश्चित ‘मंद’, ‘औसत’ और ‘तेज़’ समूहों में बाँट देती है जो पूरे वर्ष वैसे ही रहते हैं। इसमें मुख्य समस्या क्या है?","optionsHi":["विभेदन के लिए आवश्यक है कि सभी बच्चे हमेशा एक ही गति से बिल्कुल एक ही कार्य करें","निश्चित समूह सही पद्धति हैं; एकमात्र समस्या यह है कि नाम गुप्त रखे जाने चाहिए","किसी भी प्रकार का समूहीकरण समावेशी शिक्षा के विरुद्ध है और हर कक्षा में टाला जाना चाहिए","निश्चित योग्यता समूह ट्रैकिंग बन जाते हैं; विभेदन के लिए लचीले समूह चाहिए जो बदलते रहें"],"explanationHi":"विभेदन लचीले समूहीकरण पर निर्भर करता है जो कार्य और नए साक्ष्य के अनुसार बदलता है; निश्चित समूह बच्चों पर लेबल लगाते हैं और स्वयं-पूर्ति भविष्यवाणी बना सकते हैं, जबकि समूहीकरण स्वयं समस्या नहीं है।"},
  {"id":"cdp-child-development-342","question":"A recognised school refuses to build a ramp or make any adjustment for a Class 2 child with a certified locomotor disability of 30%, arguing that the RPwD Act, 2016 applies only to ‘benchmark disabilities’ of 40% or more. Which statement is correct?","options":["The school is right, because the Act gives no educational rights to children below the 40% benchmark","The school is wrong: the 40% benchmark only unlocks extra benefits; reasonable accommodation is owed to all","The school is right, but only if it is a private unaided school that receives no government aid","The school is wrong, because every disability is treated as a benchmark disability once it is certified"],"answer":1,"explanation":"A benchmark disability (not less than 40% of a specified disability) unlocks certain extra benefits, but the Act's provisions on inclusive education and reasonable accommodation are framed for children with disabilities as a whole.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक मान्यता प्राप्त विद्यालय 30% के प्रमाणित गतिशीलता-दिव्यांगता वाले कक्षा 2 के बच्चे के लिए रैंप बनाने या कोई समायोजन करने से इनकार करता है, यह तर्क देते हुए कि RPwD अधिनियम, 2016 केवल 40% या अधिक की ‘बेंचमार्क दिव्यांगताओं’ पर लागू होता है। कौन-सा कथन सही है?","optionsHi":["विद्यालय सही है, क्योंकि अधिनियम 40% बेंचमार्क से नीचे के बच्चों को कोई शैक्षिक अधिकार नहीं देता","विद्यालय गलत है: 40% बेंचमार्क केवल अतिरिक्त लाभ खोलता है; उचित समायोजन सभी का देय है","विद्यालय सही है, परंतु केवल तब जब वह निजी गैर-सहायता प्राप्त विद्यालय हो जिसे कोई सरकारी सहायता नहीं मिलती","विद्यालय गलत है, क्योंकि प्रमाणित होते ही हर दिव्यांगता को बेंचमार्क दिव्यांगता माना जाता है"],"explanationHi":"बेंचमार्क दिव्यांगता (किसी विनिर्दिष्ट दिव्यांगता का 40% से कम नहीं) कुछ अतिरिक्त लाभ खोलती है, पर समावेशी शिक्षा और उचित समायोजन से संबंधित अधिनियम के प्रावधान समग्र रूप से दिव्यांग बच्चों के लिए बनाए गए हैं।"},
  {"id":"cdp-child-development-343","question":"Consider: I. Under the RTE Act, 2009, the right to free and compulsory education covers ages 6 to 14. II. Under the RPwD Act, 2016, every child with a benchmark disability has the right to free education from 6 to 18 years. III. The RPwD Act defines inclusive education as a system in which students with and without disability learn together and teaching is suitably adapted. Which are correct?","options":["I and II only","I and III only","II and III only","I, II and III"],"answer":3,"explanation":"All three are correct: RTE covers 6–14, the RPwD Act extends free education to 18 for children with benchmark disabilities, and it defines inclusive education as learning together with adapted teaching.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"विचार कीजिए: I. RTE अधिनियम, 2009 के अंतर्गत, निःशुल्क और अनिवार्य शिक्षा का अधिकार 6 से 14 वर्ष की आयु को समेटता है। II. RPwD अधिनियम, 2016 के अंतर्गत, बेंचमार्क दिव्यांगता वाले प्रत्येक बच्चे को 6 से 18 वर्ष तक निःशुल्क शिक्षा का अधिकार है। III. RPwD अधिनियम समावेशी शिक्षा को ऐसी प्रणाली के रूप में परिभाषित करता है जिसमें दिव्यांग और गैर-दिव्यांग विद्यार्थी साथ सीखते हैं और शिक्षण को उपयुक्त रूप से अनुकूलित किया जाता है। कौन-से सही हैं?","optionsHi":["केवल I और II","केवल I और III","केवल II और III","I, II और III"],"explanationHi":"तीनों सही हैं: RTE 6–14 को समेटता है, RPwD अधिनियम बेंचमार्क दिव्यांगता वाले बच्चों के लिए निःशुल्क शिक्षा को 18 तक बढ़ाता है, और वह समावेशी शिक्षा को अनुकूलित शिक्षण के साथ साथ-साथ सीखने के रूप में परिभाषित करता है।"},
  {"id":"cdp-child-development-344","question":"A private unaided school in Delhi admits children under the RTE quota for disadvantaged and weaker sections, but seats them in a separate section in the afternoon with a different uniform. How should this be judged?","options":["It is discriminatory segregation; these children should learn in the same classes with no visible marker","It is acceptable because the children may feel more comfortable with peers from similar backgrounds","It is acceptable if the parents sign their written consent to the separate arrangement","It is necessary so that the school can track the children for its fee reimbursement claims"],"answer":0,"explanation":"The 25% provision exists so that children from different backgrounds learn together; separate sections or uniforms mark and segregate them, which is discrimination, not inclusion.","difficulty":"hard","source":"CTET · State TETs","questionHi":"दिल्ली का एक निजी गैर-सहायता प्राप्त विद्यालय RTE कोटे के अंतर्गत वंचित और कमज़ोर वर्गों के बच्चों को प्रवेश देता है, पर उन्हें दोपहर में अलग अनुभाग में, अलग वर्दी के साथ बैठाता है। इसका आकलन कैसे किया जाना चाहिए?","optionsHi":["यह भेदभावपूर्ण पृथक्करण है; इन बच्चों को बिना किसी दृश्य चिह्न के उन्हीं कक्षाओं में सीखना चाहिए","यह स्वीकार्य है क्योंकि बच्चे समान पृष्ठभूमि के साथियों के साथ अधिक सहज महसूस कर सकते हैं","यह स्वीकार्य है यदि माता-पिता अलग व्यवस्था के लिए लिखित सहमति पर हस्ताक्षर करें","यह आवश्यक है ताकि विद्यालय अपने शुल्क प्रतिपूर्ति दावों के लिए बच्चों को ट्रैक कर सके"],"explanationHi":"25% का प्रावधान इसलिए है कि विभिन्न पृष्ठभूमियों के बच्चे साथ सीखें; अलग अनुभाग या वर्दी उन्हें चिह्नित और पृथक करते हैं, जो भेदभाव है, समावेशन नहीं।"},
  {"id":"cdp-child-development-345","question":"Several children in a Class 2 class in rural Bihar are first-generation learners whose parents cannot read. Their homework is often incomplete. What is the most appropriate step for the teacher?","options":["Send notes asking the parents to arrange private tuition so the homework gets completed regularly","Design homework children can do alone or with family through talk and activity, and support them in school","Lower her expectations of these children, since they lack a literate home environment to help","Make them stand at the back until their homework becomes regular, so that the habit is built early"],"answer":1,"explanation":"First-generation learners lack academic help at home, not ability; homework that does not depend on literate parents and support in school address the real gap, while lowered expectations and punishment widen it.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"ग्रामीण बिहार की कक्षा 2 के कई बच्चे प्रथम-पीढ़ी के अधिगमकर्ता हैं जिनके माता-पिता पढ़ नहीं सकते। उनका गृहकार्य प्रायः अधूरा रहता है। शिक्षक के लिए सबसे उपयुक्त कदम क्या है?","optionsHi":["माता-पिता को नोट भेजना कि वे निजी ट्यूशन की व्यवस्था करें ताकि गृहकार्य नियमित रूप से पूरा हो","ऐसा गृहकार्य बनाना जो बच्चे अकेले या परिवार के साथ बातचीत और गतिविधि से कर सकें, और विद्यालय में उनकी सहायता करना","इन बच्चों से अपेक्षाएँ घटा देना, क्योंकि उनके पास मदद करने के लिए साक्षर घरेलू वातावरण नहीं है","जब तक उनका गृहकार्य नियमित न हो जाए, उन्हें पीछे खड़ा रखना, ताकि आदत जल्दी बने"],"explanationHi":"प्रथम-पीढ़ी के अधिगमकर्ताओं के पास घर पर शैक्षिक सहायता का अभाव होता है, योग्यता का नहीं; साक्षर माता-पिता पर निर्भर न रहने वाला गृहकार्य और विद्यालय में सहायता वास्तविक अंतर को संबोधित करते हैं, जबकि घटी अपेक्षाएँ और दंड उसे बढ़ाते हैं।"},
  {"id":"cdp-child-development-346","question":"In a Class 1 classroom in a Jharkhand village, most children speak Santhali or Mundari at home, while the textbook is in Hindi. Which approach is most appropriate?","options":["Forbidding home languages in class so that the children pick up Hindi faster through immersion","Translating every sentence of the textbook word for word into the home language throughout the year","Referring these children for speech-and-language assessment because they are slow in Hindi","Using the children’s home languages as a resource and building a bridge from them to Hindi"],"answer":3,"explanation":"Children learn a new language best when their first language is respected and used as a foundation; banning it is subtractive and damages confidence, and second-language learning is not a disorder.","difficulty":"hard","source":"CTET · State TETs","questionHi":"झारखंड के एक गाँव की कक्षा 1 में अधिकांश बच्चे घर पर संथाली या मुंडारी बोलते हैं, जबकि पाठ्यपुस्तक हिंदी में है। कौन-सा उपागम सबसे उपयुक्त है?","optionsHi":["कक्षा में घर की भाषाओं को प्रतिबंधित करना ताकि बच्चे निमज्जन से हिंदी जल्दी सीख लें","पूरे वर्ष पाठ्यपुस्तक के हर वाक्य का घर की भाषा में शब्दशः अनुवाद करना","इन बच्चों को वाक्-भाषा आकलन के लिए संदर्भित करना क्योंकि वे हिंदी में धीमे हैं","बच्चों की घर की भाषाओं को संसाधन के रूप में उपयोग करना और उनसे हिंदी तक पुल बनाना"],"explanationHi":"बच्चे नई भाषा तब सबसे अच्छा सीखते हैं जब उनकी पहली भाषा का सम्मान हो और उसे आधार बनाया जाए; उसे प्रतिबंधित करना घटाने वाला है और आत्मविश्वास को हानि पहुँचाता है, और दूसरी भाषा सीखना कोई विकार नहीं है।"},
  {"id":"cdp-child-development-347","question":"A Class 6 teacher regularly asks the girls to decorate the classroom and serve water at events, and the boys to shift benches and manage the sound system. What is the main concern here?","options":["It wastes teaching time that should be spent on completing the syllabus for the term","It reinforces gender stereotypes through the hidden curriculum; tasks should be rotated","It is fine because it matches what boys and girls are naturally good at doing","It is fine as long as the textbook content itself is fully gender-neutral"],"answer":1,"explanation":"Routine task allocation teaches children what is ‘proper’ for each gender even if no one says it aloud; rotating tasks challenges the stereotype, and gender-neutral textbooks cannot undo what classroom practice teaches.","difficulty":"moderate","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 6 की एक शिक्षिका नियमित रूप से लड़कियों से कक्षा सजाने और कार्यक्रमों में पानी पिलाने को कहती है, और लड़कों से बेंच खिसकाने और साउंड सिस्टम सँभालने को। यहाँ मुख्य चिंता क्या है?","optionsHi":["यह शिक्षण का वह समय बर्बाद करता है जो सत्र का पाठ्यक्रम पूरा करने में लगना चाहिए","यह छिपी हुई पाठ्यचर्या के माध्यम से लिंग रूढ़ियों को पुष्ट करता है; कार्यों की अदला-बदली होनी चाहिए","यह ठीक है क्योंकि यह उससे मेल खाता है जिसमें लड़के और लड़कियाँ स्वाभाविक रूप से अच्छे होते हैं","यह तब तक ठीक है जब तक पाठ्यपुस्तक की सामग्री स्वयं पूरी तरह लिंग-तटस्थ है"],"explanationHi":"नियमित कार्य-आवंटन बच्चों को सिखाता है कि प्रत्येक लिंग के लिए क्या ‘उचित’ है, भले ही कोई ज़ोर से न कहे; कार्यों की अदला-बदली रूढ़ि को चुनौती देती है, और लिंग-तटस्थ पाठ्यपुस्तकें उसे नहीं मिटा सकतीं जो कक्षा का आचरण सिखाता है।"},
  {"id":"cdp-child-development-348","question":"On learning that Pinki’s parents are migrant construction workers, her teacher quietly assumes she will not do well. Over the term she gives Pinki less time to answer, fewer challenging questions and less praise, and Pinki’s performance actually falls. This best illustrates:","options":["Stereotype threat experienced by Pinki","The halo effect of her family's background on grading","A self-fulfilling prophecy (Pygmalion effect)","Learned helplessness after repeated failure"],"answer":2,"explanation":"The teacher's low expectation changed her own behaviour, which in turn lowered the child's performance, which is the self-fulfilling prophecy; stereotype threat is the student's own anxiety about confirming a stereotype at the moment of performance.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"यह जानने पर कि पिंकी के माता-पिता प्रवासी निर्माण मज़दूर हैं, उसकी शिक्षिका चुपचाप मान लेती है कि वह अच्छा नहीं करेगी। सत्र के दौरान वह पिंकी को उत्तर देने के लिए कम समय, कम चुनौतीपूर्ण प्रश्न और कम प्रशंसा देती है, और पिंकी का प्रदर्शन वास्तव में गिर जाता है। यह सबसे अच्छी तरह क्या दर्शाता है?","optionsHi":["पिंकी द्वारा अनुभव की गई रूढ़ि-खतरा (स्टीरियोटाइप थ्रेट)","अंकन पर उसके परिवार की पृष्ठभूमि का प्रभामंडल प्रभाव","स्वयं-पूर्ति भविष्यवाणी (पिग्मैलियन प्रभाव)","बार-बार की असफलता के बाद सीखी हुई असहायता"],"explanationHi":"शिक्षिका की निम्न अपेक्षा ने उसके अपने व्यवहार को बदला, जिसने बदले में बच्ची का प्रदर्शन घटाया, यही स्वयं-पूर्ति भविष्यवाणी है; रूढ़ि-खतरा प्रदर्शन के क्षण में किसी रूढ़ि की पुष्टि होने की विद्यार्थी की अपनी चिंता है।"},
  {"id":"cdp-child-development-349","question":"Just before a maths test, a teacher jokes, ‘Let’s see if the girls can manage this one.’ Several girls who usually do well in maths score noticeably lower that day. Which concept best explains this drop?","options":["Stereotype threat","The Pygmalion effect","The Hawthorne effect","The halo effect"],"answer":0,"explanation":"Reminding a group of a negative stereotype just before a task creates anxiety about confirming it, which lowers performance on the spot; the Pygmalion effect works through a teacher's treatment of a child over time.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"गणित परीक्षण से ठीक पहले एक शिक्षक मज़ाक करता है, ‘देखते हैं कि लड़कियाँ इसे सँभाल पाती हैं या नहीं।’ गणित में सामान्यतः अच्छा करने वाली कई लड़कियाँ उस दिन उल्लेखनीय रूप से कम अंक पाती हैं। कौन-सी अवधारणा इस गिरावट को सबसे अच्छी तरह समझाती है?","optionsHi":["रूढ़ि-खतरा (स्टीरियोटाइप थ्रेट)","पिग्मैलियन प्रभाव","हॉथॉर्न प्रभाव","प्रभामंडल प्रभाव"],"explanationHi":"किसी कार्य से ठीक पहले किसी समूह को नकारात्मक रूढ़ि की याद दिलाना उसकी पुष्टि होने की चिंता पैदा करता है, जो तत्काल प्रदर्शन घटाती है; पिग्मैलियन प्रभाव समय के साथ शिक्षक के बच्चे के प्रति व्यवहार के माध्यम से काम करता है।"},
  {"id":"cdp-child-development-350","question":"Which of these statements about teaching children with hearing impairment are correct? I. Delayed vocabulary in such a child is often a result of reduced access to language, not of low intelligence. II. Lip-reading alone gives full access to speech, because every speech sound can be seen on the lips. III. The teacher should stand so that light falls on her face, not with a window behind her.","options":["I only","I and II only","II and III only","I and III only"],"answer":3,"explanation":"Many sounds look alike or are invisible on the lips (p/b/m, k/g), so lip-reading alone is incomplete; a well-lit face aids speech-reading, and language delay reflects reduced access, not low intelligence.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"श्रवण-बाधित बच्चों को पढ़ाने के बारे में इनमें से कौन-से कथन सही हैं? I. ऐसे बच्चे में विलंबित शब्दावली प्रायः भाषा तक कम पहुँच का परिणाम है, कम बुद्धि का नहीं। II. केवल होंठ-पठन वाक् तक पूर्ण पहुँच देता है, क्योंकि हर वाक्-ध्वनि होंठों पर देखी जा सकती है। III. शिक्षक को इस प्रकार खड़ा होना चाहिए कि रोशनी उसके चेहरे पर पड़े, पीछे खिड़की न हो।","optionsHi":["केवल I","केवल I और II","केवल II और III","केवल I और III"],"explanationHi":"कई ध्वनियाँ होंठों पर एक जैसी दिखती हैं या अदृश्य होती हैं (p/b/m, k/g), इसलिए केवल होंठ-पठन अधूरा है; अच्छी तरह रोशन चेहरा वाक्-पठन में सहायक है, और भाषा-विलंब कम पहुँच दर्शाता है, कम बुद्धि नहीं।"},
  {"id":"cdp-child-development-351","question":"Ten-month-old Tara has twice found a rattle hidden under a red cloth. Now, while she watches, her mother hides it under a blue cloth placed beside the red one. Tara lifts the red cloth again. According to Piaget, this behaviour shows that:","options":["Her object permanence is still incomplete; she links the toy to the action and place where she found it before","She has entered the tertiary circular reaction substage and is deliberately varying her actions to test outcomes","She has full object permanence but is egocentric, assuming the toy is where she wants it to be","She is showing a primary circular reaction, repeating an action centred on her own body"],"answer":0,"explanation":"This is the classic A-not-B error of sensorimotor substage 4: the infant searches for hidden objects but ties them to past successful actions. Only around substage 5 does she follow visible displacements correctly.","difficulty":"hard","source":"CTET · State TETs","questionHi":"दस माह की तारा को एक झुनझुना दो बार लाल कपड़े के नीचे छिपा हुआ मिल चुका है। अब, जब वह देख रही है, उसकी माँ उसे लाल कपड़े के बगल में रखे नीले कपड़े के नीचे छिपाती है। तारा फिर लाल कपड़ा उठाती है। पियाजे के अनुसार यह व्यवहार दर्शाता है कि:","optionsHi":["उसका वस्तु स्थायित्व अभी अधूरा है; वह खिलौने को उस क्रिया और स्थान से जोड़ती है जहाँ वह उसे पहले मिला था","वह तृतीयक वृत्तीय प्रतिक्रिया की उप-अवस्था में प्रवेश कर चुकी है और परिणामों को परखने के लिए जानबूझकर अपनी क्रियाएँ बदल रही है","उसमें पूर्ण वस्तु स्थायित्व है पर वह अहंकेंद्रित है, यह मानती है कि खिलौना वहीं है जहाँ वह चाहती है","वह प्राथमिक वृत्तीय प्रतिक्रिया दिखा रही है, जो उसके अपने शरीर पर केंद्रित क्रिया को दोहराना है"],"explanationHi":"यह संवेदी-गामक उप-अवस्था 4 की क्लासिक A-not-B त्रुटि है: शिशु छिपी वस्तुओं को खोजता है पर उन्हें पिछली सफल क्रियाओं से जोड़ता है। उप-अवस्था 5 के आसपास ही वह दिखाई देने वाले विस्थापनों का सही अनुसरण करती है।"},
  {"id":"cdp-child-development-352","question":"A six-month-old in a crèche in Pune accidentally kicks and sees the hanging toy above her cot jingle. She then kicks again and again, smiling each time the toy moves. Piaget would place this behaviour in the substage of:","options":["Primary circular reactions","Secondary circular reactions","Tertiary circular reactions","Coordination of secondary schemes"],"answer":1,"explanation":"Secondary circular reactions (about 4 to 8 months) are repeated actions that produce an interesting effect in the external world. Primary reactions centre on the infant’s own body; tertiary reactions involve deliberately varying the action.","difficulty":"hard","source":"CTET · State TETs","questionHi":"पुणे के एक शिशु-गृह में छह माह की एक बच्ची संयोग से लात मारती है और अपने पालने के ऊपर लटके खिलौने को खनकते देखती है। फिर वह बार-बार लात मारती है, हर बार खिलौने के हिलने पर मुस्कुराती है। पियाजे इस व्यवहार को किस उप-अवस्था में रखते?","optionsHi":["प्राथमिक वृत्तीय प्रतिक्रियाएँ","द्वितीयक वृत्तीय प्रतिक्रियाएँ","तृतीयक वृत्तीय प्रतिक्रियाएँ","द्वितीयक स्कीमाओं का समन्वय"],"explanationHi":"द्वितीयक वृत्तीय प्रतिक्रियाएँ (लगभग 4 से 8 माह) वे दोहराई गई क्रियाएँ हैं जो बाहरी संसार में कोई रोचक प्रभाव उत्पन्न करती हैं। प्राथमिक प्रतिक्रियाएँ शिशु के अपने शरीर पर केंद्रित होती हैं; तृतीयक प्रतिक्रियाओं में क्रिया को जानबूझकर बदला जाता है।"},
  {"id":"cdp-child-development-353","question":"A 15-month-old drops a spoon from his high chair, then throws it, then drops it from higher, then rolls it off the edge, watching closely each time to see where it lands. Piaget would describe this as:","options":["A secondary circular reaction, since the same interesting result is reproduced","Deferred imitation of an action he saw an adult perform earlier","A tertiary circular reaction, varying actions to discover new results","Symbolic play using the spoon to stand for something else"],"answer":2,"explanation":"In tertiary circular reactions (about 12 to 18 months) the toddler experiments like a ‘little scientist’, deliberately varying actions to see what happens. A secondary reaction repeats the same action for the same effect.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"15 माह का एक बच्चा अपनी ऊँची कुर्सी से चम्मच गिराता है, फिर उसे फेंकता है, फिर और ऊँचाई से गिराता है, फिर किनारे से लुढ़काता है, हर बार ध्यान से देखता हुआ कि वह कहाँ गिरता है। पियाजे इसका वर्णन कैसे करते?","optionsHi":["द्वितीयक वृत्तीय प्रतिक्रिया, क्योंकि वही रोचक परिणाम दोहराया जाता है","किसी वयस्क को पहले करते देखी गई क्रिया का विलंबित अनुकरण","तृतीयक वृत्तीय प्रतिक्रिया, नए परिणाम खोजने के लिए क्रियाओं को बदलना","प्रतीकात्मक खेल, जिसमें चम्मच किसी और चीज़ का प्रतिनिधित्व करता है"],"explanationHi":"तृतीयक वृत्तीय प्रतिक्रियाओं (लगभग 12 से 18 माह) में बच्चा ‘नन्हे वैज्ञानिक’ की तरह प्रयोग करता है, यह देखने के लिए जानबूझकर क्रियाओं को बदलता है कि क्या होता है। द्वितीयक प्रतिक्रिया उसी प्रभाव के लिए वही क्रिया दोहराती है।"},
  {"id":"cdp-child-development-354","question":"Asked how the hills near her village came to be, a five-year-old in Uttarakhand replies, ‘Big people made them by piling up lots and lots of stones.’ Which feature of pre-operational thought does this reply show?","options":["Animism","Centration","Transductive reasoning","Artificialism"],"answer":3,"explanation":"Artificialism is the belief that natural things were made by people or human-like agents. Animism, by contrast, would attribute life or feelings to the hills themselves.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"यह पूछे जाने पर कि उसके गाँव के पास की पहाड़ियाँ कैसे बनीं, उत्तराखंड की पाँच वर्ष की एक बच्ची उत्तर देती है, ‘बड़े लोगों ने ढेर सारे पत्थर जमाकर उन्हें बनाया।’ यह उत्तर पूर्व-संक्रियात्मक चिंतन की कौन-सी विशेषता दर्शाता है?","optionsHi":["सजीववाद","केंद्रीकरण","अनुप्रेरक (ट्रांसडक्टिव) तर्क","कृत्रिमवाद"],"explanationHi":"कृत्रिमवाद यह विश्वास है कि प्राकृतिक चीज़ें लोगों या मानव-सदृश कर्ताओं द्वारा बनाई गईं। इसके विपरीत, सजीववाद स्वयं पहाड़ियों में जीवन या भावनाएँ मानता।"},
  {"id":"cdp-child-development-355","question":"A Class 1 child is shown seven marigolds and three roses and agrees that all of them are flowers. Asked, ‘Are there more marigolds or more flowers?’, she says, ‘More marigolds.’ The best Piagetian explanation is that she:","options":["Cannot yet keep the whole class and a sub-class in mind at the same time","Has not learnt the words ‘marigold’ and ‘flower’, so the error is purely linguistic","Lacks object permanence for the roses, which are fewer","Is showing animism by treating the marigolds as more alive"],"answer":0,"explanation":"Failure of class inclusion comes from centration on the larger sub-class: once she thinks of the marigolds, she loses sight of the whole set. The child already knows the words, so the error is about logic, not vocabulary.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 1 की एक बच्ची को सात गेंदे के फूल और तीन गुलाब दिखाए जाते हैं और वह मानती है कि वे सब फूल हैं। पूछे जाने पर, ‘गेंदे अधिक हैं या फूल अधिक हैं?’, वह कहती है, ‘गेंदे अधिक।’ सबसे अच्छी पियाजे-आधारित व्याख्या यह है कि वह:","optionsHi":["अभी पूरे वर्ग और उप-वर्ग को एक साथ मन में नहीं रख सकती","‘गेंदा’ और ‘फूल’ शब्द नहीं सीख पाई है, इसलिए त्रुटि विशुद्ध भाषायी है","गुलाबों के लिए, जो कम हैं, वस्तु स्थायित्व का अभाव रखती है","गेंदों को अधिक जीवित मानकर सजीववाद दिखा रही है"],"explanationHi":"वर्ग-समावेशन की विफलता बड़े उप-वर्ग पर केंद्रीकरण से आती है: जैसे ही वह गेंदों के बारे में सोचती है, पूरे समुच्चय को नज़रअंदाज़ कर देती है। बच्ची शब्द पहले से जानती है, इसलिए त्रुटि तर्क की है, शब्दावली की नहीं।"},
  {"id":"cdp-child-development-356","question":"Three Class 2 children explain why the water poured into a taller, narrower glass is still the same amount. Match each reason with Piaget’s term. P. ‘You didn’t add any or take any away.’ Q. ‘It is taller, but it is also thinner.’ R. ‘Pour it back and it will look just like before.’ 1. Compensation (reciprocity) 2. Identity 3. Inversion (negation)","options":["P-1, Q-2, R-3","P-2, Q-3, R-1","P-2, Q-1, R-3","P-3, Q-1, R-2"],"answer":2,"explanation":"Nothing added or removed is the identity argument; height offset by width is compensation; undoing the action to return to the start is inversion. All three show the reversible thinking of concrete operations.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"कक्षा 2 के तीन बच्चे समझाते हैं कि लंबे, संकरे गिलास में उँडेला गया पानी अब भी उतना ही है। प्रत्येक कारण का मिलान पियाजे के पद से कीजिए। P. ‘तुमने न कुछ जोड़ा, न कुछ निकाला।’ Q. ‘यह लंबा है, पर साथ ही पतला भी है।’ R. ‘इसे वापस उँडेलो तो यह पहले जैसा ही दिखेगा।’ 1. क्षतिपूर्ति (पारस्परिकता) 2. तादात्म्य 3. प्रतिलोमन (निषेध)","optionsHi":["P-1, Q-2, R-3","P-2, Q-3, R-1","P-2, Q-1, R-3","P-3, Q-1, R-2"],"explanationHi":"कुछ जोड़ा या निकाला न जाना तादात्म्य का तर्क है; ऊँचाई की भरपाई चौड़ाई से होना क्षतिपूर्ति है; क्रिया को पलटकर शुरुआती स्थिति में लौटना प्रतिलोमन है। तीनों मूर्त संक्रियाओं की उत्क्रमणीय चिंतन-क्षमता को दर्शाते हैं।"},
  {"id":"cdp-child-development-357","question":"Rohit, aged 8, is sure that a clay ball flattened into a roti still has the same amount of clay, but insists that the roti now weighs less. Piaget’s term for such unevenness in the use of the same mental operation across different tasks is:","options":["Vertical décalage","Horizontal décalage","Centration","Transductive reasoning"],"answer":1,"explanation":"Horizontal décalage is the uneven appearance of one operation, such as conservation, across different contents within the same stage. Vertical décalage refers to the same content being mastered again at a higher stage.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"8 वर्ष का रोहित निश्चित है कि रोटी की तरह चपटी की गई मिट्टी की गेंद में अब भी उतनी ही मिट्टी है, पर ज़ोर देकर कहता है कि रोटी का वज़न अब कम है। विभिन्न कार्यों में एक ही मानसिक संक्रिया के उपयोग की ऐसी असमानता के लिए पियाजे का पद क्या है?","optionsHi":["ऊर्ध्वाधर विचलन (वर्टिकल डेकैलेज)","क्षैतिज विचलन (हॉरिजॉन्टल डेकैलेज)","केंद्रीकरण","अनुप्रेरक (ट्रांसडक्टिव) तर्क"],"explanationHi":"क्षैतिज विचलन एक ही अवस्था के भीतर विभिन्न विषयवस्तुओं में संरक्षण जैसी किसी एक संक्रिया का असमान रूप से प्रकट होना है। ऊर्ध्वाधर विचलन का अर्थ है उसी विषयवस्तु में उच्चतर अवस्था में दोबारा निपुणता प्राप्त करना।"},
  {"id":"cdp-child-development-358","question":"According to Piaget, the different types of conservation are usually mastered in which order?","options":["Number → substance (mass) → weight → volume","Substance (mass) → number → volume → weight","Number → weight → substance (mass) → volume","Volume → weight → substance (mass) → number"],"answer":0,"explanation":"Conservation of number appears around 6 to 7 years, substance around 7 to 8, weight around 9 to 10, and volume only around 11 to 12. This staggered order is itself an example of horizontal décalage.","difficulty":"hard","source":"CTET · State TETs","questionHi":"पियाजे के अनुसार संरक्षण के विभिन्न प्रकारों में सामान्यतः किस क्रम से निपुणता आती है?","optionsHi":["संख्या → पदार्थ (द्रव्यमान) → भार → आयतन","पदार्थ (द्रव्यमान) → संख्या → आयतन → भार","संख्या → भार → पदार्थ (द्रव्यमान) → आयतन","आयतन → भार → पदार्थ (द्रव्यमान) → संख्या"],"explanationHi":"संख्या का संरक्षण लगभग 6 से 7 वर्ष में आता है, पदार्थ का लगभग 7 से 8, भार का लगभग 9 से 10, और आयतन का केवल लगभग 11 से 12 वर्ष में। यह चरणबद्ध क्रम स्वयं क्षैतिज विचलन का उदाहरण है।"},
  {"id":"cdp-child-development-359","question":"Given four bottles of colourless liquid and a dropper bottle that turns certain mixtures yellow, a 15-year-old first writes down every possible combination and then tests them one by one. A 9-year-old mixes them at random and stops as soon as yellow appears. The older student is showing:","options":["Seriation, the ordering skill typical of concrete operations","Tertiary circular reactions carried into adolescence","Conservation of quantity across the four liquids","Combinatorial reasoning of the formal operational stage"],"answer":3,"explanation":"Planning all possible combinations in advance is the combinatorial, hypothetico-deductive reasoning of formal operations. The younger child’s unplanned trial and error is typical of concrete operational thinking.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"रंगहीन द्रव की चार बोतलें और एक ड्रॉपर बोतल दी गई है, जो कुछ मिश्रणों को पीला कर देती है। 15 वर्ष का एक किशोर पहले हर संभव संयोजन लिखता है और फिर उन्हें एक-एक करके परखता है। 9 वर्ष का एक बच्चा उन्हें यादृच्छिक रूप से मिलाता है और पीला दिखते ही रुक जाता है। बड़ा विद्यार्थी क्या दर्शा रहा है?","optionsHi":["क्रमबद्धता, मूर्त संक्रियाओं का विशिष्ट क्रमण-कौशल","किशोरावस्था तक पहुँची तृतीयक वृत्तीय प्रतिक्रियाएँ","चारों द्रवों में मात्रा का संरक्षण","औपचारिक संक्रियात्मक अवस्था का संयोजनात्मक तर्क"],"explanationHi":"सभी संभव संयोजनों की पहले से योजना बनाना औपचारिक संक्रियाओं का संयोजनात्मक, परिकल्पनात्मक-निगमनात्मक तर्क है। छोटे बच्चे का अयोजित प्रयास और त्रुटि मूर्त संक्रियात्मक चिंतन की विशेषता है।"},
  {"id":"cdp-child-development-360","question":"Which sequence best describes how Piaget’s equilibration works when a child meets a fact that clashes with her current idea?","options":["Accommodation → disequilibrium → assimilation → equilibrium","Equilibrium → disequilibrium → accommodation → a new, more stable equilibrium","Disequilibrium → equilibrium → accommodation → assimilation","Equilibrium → assimilation → disequilibrium → the old equilibrium restored unchanged"],"answer":1,"explanation":"A conflicting experience upsets the existing balance; the child restores it by changing her schemas (accommodation), reaching a higher-level equilibrium. Development is a move to a better balance, not a return to the old one.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"जब बच्ची ऐसे तथ्य से मिलती है जो उसके वर्तमान विचार से टकराता है, तब पियाजे की साम्यधारण प्रक्रिया का सबसे अच्छा वर्णन कौन-सा क्रम करता है?","optionsHi":["समायोजन → असाम्य → आत्मसात्करण → साम्य","साम्य → असाम्य → समायोजन → एक नया, अधिक स्थिर साम्य","असाम्य → साम्य → समायोजन → आत्मसात्करण","साम्य → आत्मसात्करण → असाम्य → पुराना साम्य बिना बदले पुनः स्थापित"],"explanationHi":"कोई विरोधी अनुभव मौजूदा संतुलन को बिगाड़ता है; बच्ची अपनी स्कीमाओं को बदलकर (समायोजन) उसे पुनः स्थापित करती है, और उच्चतर स्तर का साम्य प्राप्त करती है। विकास बेहतर संतुलन की ओर बढ़ना है, पुराने में लौटना नहीं।"},
  {"id":"cdp-child-development-361","question":"Consider these statements about the factors Piaget saw behind cognitive development. 1. Social transmission, such as being told something, helps only if the child has schemas able to assimilate it. 2. Maturation alone is enough for conservation to appear, whatever the child’s experiences. 3. Equilibration is the self-regulating process that coordinates maturation, experience and social transmission. Which is/are correct?","options":["1 and 3 only","2 and 3 only","1 only","1, 2 and 3"],"answer":0,"explanation":"Piaget held that no single factor is sufficient; maturation sets possibilities but needs experience, and telling helps only when the child can assimilate it. Equilibration integrates the other factors, so statement 2 is wrong.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"पियाजे द्वारा संज्ञानात्मक विकास के पीछे माने गए कारकों के बारे में इन कथनों पर विचार कीजिए। 1. सामाजिक संचरण, जैसे किसी चीज़ का बताया जाना, तभी मदद करता है जब बच्चे के पास उसे आत्मसात् कर सकने वाली स्कीमाएँ हों। 2. संरक्षण के प्रकट होने के लिए अकेली परिपक्वता पर्याप्त है, बच्चे के अनुभव चाहे जो हों। 3. साम्यधारण वह स्व-नियामक प्रक्रिया है जो परिपक्वता, अनुभव और सामाजिक संचरण का समन्वय करती है। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 3","केवल 2 और 3","केवल 1","1, 2 और 3"],"explanationHi":"पियाजे का मत था कि कोई एक कारक पर्याप्त नहीं है; परिपक्वता संभावनाएँ तय करती है पर उसे अनुभव चाहिए, और बताना तभी मदद करता है जब बच्चा उसे आत्मसात् कर सके। साम्यधारण अन्य कारकों को एकीकृत करता है, इसलिए कथन 2 गलत है।"},
  {"id":"cdp-child-development-362","question":"In the conservation-of-number task, a Class 1 child says the spread-out row of counters has ‘more’ than the bunched row. Which response from the teacher is most in keeping with Piaget’s ideas?","options":["Tell her the correct answer firmly and have her repeat it until she remembers","Praise her every time she says ‘same’, so that the correct reply is reinforced","Ask her how she knows, and let her count and rearrange both rows to test her own idea","Drop the topic until she turns seven, since stages cannot be influenced by experience"],"answer":2,"explanation":"Piaget valued the child’s own activity and the conflict between prediction and result. Drilling or rewarding the answer (behaviourist) gives no understanding, and Piaget never said experience is irrelevant, only that it must match the child’s level.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"संख्या-संरक्षण कार्य में कक्षा 1 की एक बच्ची कहती है कि फैलाई गई गोटियों की पंक्ति में सटी हुई पंक्ति से ‘अधिक’ हैं। पियाजे के विचारों के अनुरूप शिक्षक की कौन-सी प्रतिक्रिया सबसे उपयुक्त है?","optionsHi":["उसे सही उत्तर दृढ़ता से बताना और याद होने तक दोहराने को कहना","हर बार जब वह ‘बराबर’ कहे उसकी प्रशंसा करना, ताकि सही उत्तर पुनर्बलित हो","उससे पूछना कि उसे कैसे पता, और उसे दोनों पंक्तियों को गिनने और पुनर्व्यवस्थित करने देना ताकि वह अपने विचार को स्वयं परखे","सात वर्ष की आयु होने तक विषय छोड़ देना, क्योंकि अवस्थाओं को अनुभव से प्रभावित नहीं किया जा सकता"],"explanationHi":"पियाजे बच्चे की अपनी गतिविधि और पूर्वानुमान तथा परिणाम के बीच के टकराव को महत्व देते थे। रटवाना या उत्तर को पुरस्कृत करना (व्यवहारवादी) समझ नहीं देता, और पियाजे ने कभी नहीं कहा कि अनुभव अप्रासंगिक है, केवल यह कि वह बच्चे के स्तर से मेल खाना चाहिए।"},
  {"id":"cdp-child-development-363","question":"During a game of hide-and-seek, a four-year-old stands in the open with her hands over her eyes and calls out, ‘You can’t see me now!’ Piaget would explain this mainly as:","options":["Absence of object permanence when eyes are shut","Animism","Centration on a single dimension of the game","Egocentrism: assuming others see what she sees"],"answer":3,"explanation":"Pre-operational egocentrism is the difficulty of separating one’s own point of view from another’s. She knows she still exists, so object permanence is not the issue.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"छुपम-छुपाई के खेल में चार वर्ष की एक बच्ची खुले में खड़ी होकर अपनी आँखों पर हाथ रख लेती है और पुकारती है, ‘तुम अब मुझे नहीं देख सकते!’ पियाजे इसे मुख्यतः कैसे समझाते?","optionsHi":["आँखें बंद होने पर वस्तु स्थायित्व का अभाव","सजीववाद","खेल के किसी एक आयाम पर केंद्रीकरण","अहंकेंद्रिता: यह मानना कि दूसरे वही देखते हैं जो वह देखती है"],"explanationHi":"पूर्व-संक्रियात्मक अहंकेंद्रिता अपने दृष्टिकोण को दूसरे के दृष्टिकोण से अलग करने की कठिनाई है। वह जानती है कि वह अब भी मौजूद है, इसलिए वस्तु स्थायित्व मुद्दा नहीं है।"},
  {"id":"cdp-child-development-364","question":"A five-year-old watches a pencil standing upright fall flat on the table. Asked to draw what happened, she draws only the upright pencil and the flat pencil, nothing in between. Piaget would say this reflects her tendency to:","options":["Focus on states rather than on transformations","Reason transductively from one particular to another","Use reciprocity in place of inversion","Attribute life to moving objects"],"answer":0,"explanation":"Pre-operational children attend to the start and end states and ignore the transformation linking them. This is one reason they fail conservation tasks.","difficulty":"hard","source":"CTET · State TETs","questionHi":"पाँच वर्ष की एक बच्ची खड़ी पेंसिल को मेज़ पर सपाट गिरते देखती है। यह बनाने को कहे जाने पर कि क्या हुआ, वह केवल खड़ी पेंसिल और सपाट पेंसिल बनाती है, बीच में कुछ नहीं। पियाजे कहेंगे कि यह उसकी किस प्रवृत्ति को दर्शाता है?","optionsHi":["रूपांतरणों की बजाय अवस्थाओं पर ध्यान देना","एक विशिष्ट बात से दूसरी विशिष्ट बात की ओर अनुप्रेरक रूप से तर्क करना","प्रतिलोमन की जगह पारस्परिकता का उपयोग करना","गतिशील वस्तुओं में जीवन आरोपित करना"],"explanationHi":"पूर्व-संक्रियात्मक बच्चे आरंभिक और अंतिम अवस्थाओं पर ध्यान देते हैं और उन्हें जोड़ने वाले रूपांतरण की अनदेखी करते हैं। यह संरक्षण कार्यों में उनकी विफलता का एक कारण है।"},
  {"id":"cdp-child-development-365","question":"A two-and-a-half-year-old holds a banana to her ear and says, ‘Hello, Nani!’ In Piaget’s theory this behaviour is significant because it shows:","options":["A tertiary circular reaction, varying actions to see results","The symbolic (semiotic) function that marks the pre-operational stage","Egocentric speech that will later go inward as inner speech","Conservation of identity of the banana"],"answer":1,"explanation":"Using one object to stand for another shows the child can now represent things mentally with symbols, which marks the pre-operational stage. Linking such speech to inner speech is Vygotsky’s idea, not the point here.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"ढाई वर्ष की एक बच्ची केला अपने कान से लगाकर कहती है, ‘हैलो, नानी!’ पियाजे के सिद्धांत में यह व्यवहार महत्वपूर्ण है क्योंकि यह दर्शाता है:","optionsHi":["तृतीयक वृत्तीय प्रतिक्रिया, परिणाम देखने के लिए क्रियाओं को बदलना","प्रतीकात्मक (सांकेतिक) प्रकार्य जो पूर्व-संक्रियात्मक अवस्था की पहचान है","अहंकेंद्रित वाक् जो बाद में आंतरिक वाक् के रूप में भीतर चली जाएगी","केले की तादात्म्य संरक्षण"],"explanationHi":"एक वस्तु को दूसरी के लिए प्रयोग करना दिखाता है कि बच्ची अब प्रतीकों से चीज़ों का मानसिक निरूपण कर सकती है, जो पूर्व-संक्रियात्मक अवस्था की पहचान है। ऐसी वाक् को आंतरिक वाक् से जोड़ना वाइगोत्स्की का विचार है, यहाँ मुद्दा वह नहीं है।"},
  {"id":"cdp-child-development-366","question":"How many of these statements about Piaget’s formal operational stage are correct? I. All adolescents show formal reasoning in every subject by about 15 years. II. Even adults may use formal reasoning mainly in areas they know well. III. Schooling and culture influence whether formal operational reasoning is shown. IV. Thinking about one’s own thinking and about hypothetical possibilities develops in this stage.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"II, III and IV are correct. Later research, which Piaget himself accepted in 1972, showed formal operations are neither universal nor applied evenly; many adults use them only in familiar domains, so I is false.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"पियाजे की औपचारिक संक्रियात्मक अवस्था के बारे में इनमें से कितने कथन सही हैं? I. सभी किशोर लगभग 15 वर्ष की आयु तक हर विषय में औपचारिक तर्क दिखाते हैं। II. वयस्क भी औपचारिक तर्क मुख्यतः उन्हीं क्षेत्रों में उपयोग कर सकते हैं जिन्हें वे अच्छी तरह जानते हैं। III. विद्यालयी शिक्षा और संस्कृति प्रभावित करती हैं कि औपचारिक संक्रियात्मक तर्क दिखाया जाता है या नहीं। IV. अपने चिंतन के बारे में सोचना और काल्पनिक संभावनाओं के बारे में सोचना इसी अवस्था में विकसित होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"II, III और IV सही हैं। बाद के शोध ने, जिसे पियाजे ने स्वयं 1972 में स्वीकार किया, दिखाया कि औपचारिक संक्रियाएँ न तो सार्वभौमिक हैं न समान रूप से लागू होती हैं; कई वयस्क उन्हें केवल परिचित क्षेत्रों में प्रयोग करते हैं, इसलिए I गलत है।"},
  {"id":"cdp-child-development-367","question":"Step 1: Meena, who believed that every sea animal with fins is a fish, learns that whales breathe air and feed milk to their young, and revises her idea. Step 2: Later she reads that dolphins do the same and immediately calls them mammals. In Piaget’s terms, Steps 1 and 2 are respectively:","options":["Assimilation and accommodation","Equilibration and disequilibrium","Accommodation and assimilation","Accommodation and accommodation"],"answer":2,"explanation":"In Step 1 she changes her schema to fit a new fact (accommodation). In Step 2 the new information fits the revised schema without change (assimilation).","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"चरण 1: मीना, जो मानती थी कि पंखों वाला हर समुद्री जीव मछली है, सीखती है कि व्हेल हवा में साँस लेती हैं और अपने बच्चों को दूध पिलाती हैं, और अपना विचार संशोधित करती है। चरण 2: बाद में वह पढ़ती है कि डॉल्फ़िन भी ऐसा ही करती हैं और तुरंत उन्हें स्तनधारी कहती है। पियाजे की शब्दावली में चरण 1 और 2 क्रमशः क्या हैं?","optionsHi":["आत्मसात्करण और समायोजन","साम्यधारण और असाम्य","समायोजन और आत्मसात्करण","समायोजन और समायोजन"],"explanationHi":"चरण 1 में वह नए तथ्य के अनुरूप अपनी स्कीमा बदलती है (समायोजन)। चरण 2 में नई सूचना बिना परिवर्तन के संशोधित स्कीमा में बैठ जाती है (आत्मसात्करण)।"},
  {"id":"cdp-child-development-368","question":"A teacher keeps a notebook of the wrong answers children give and asks them, ‘How did you get that?’, because she finds that children of the same age make the same kinds of mistakes. This practice most closely follows the approach of:","options":["Skinner, who treated errors as behaviour to be extinguished","Thorndike, who saw errors as part of blind trial and error","Pavlov, who studied conditioned responses in learning","Piaget, who saw consistent errors as windows into thinking"],"answer":3,"explanation":"Piaget’s interest in cognition grew from noticing that children of the same age made similar wrong answers on intelligence tests; his clinical method probes the reasoning behind answers. Behaviourists treat errors as responses to be weakened.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"एक शिक्षिका बच्चों द्वारा दिए गए गलत उत्तरों की एक कॉपी रखती है और उनसे पूछती है, ‘यह तुमने कैसे निकाला?’, क्योंकि उसे लगता है कि समान आयु के बच्चे एक ही तरह की गलतियाँ करते हैं। यह अभ्यास सबसे अधिक किसके उपागम का अनुसरण करता है?","optionsHi":["स्किनर, जो त्रुटियों को ऐसे व्यवहार मानते थे जिन्हें विलुप्त किया जाना है","थॉर्नडाइक, जो त्रुटियों को अंधे प्रयास और त्रुटि का हिस्सा मानते थे","पावलोव, जिन्होंने अधिगम में अनुबंधित अनुक्रियाओं का अध्ययन किया","पियाजे, जो सुसंगत त्रुटियों को चिंतन में झरोखा मानते थे"],"explanationHi":"संज्ञान में पियाजे की रुचि इस बात को देखने से बढ़ी कि समान आयु के बच्चे बुद्धि परीक्षणों में एक जैसे गलत उत्तर देते हैं; उनकी नैदानिक विधि उत्तरों के पीछे के तर्क की जाँच करती है। व्यवहारवादी त्रुटियों को ऐसी अनुक्रियाएँ मानते हैं जिन्हें कमज़ोर किया जाना है।"},
  {"id":"cdp-child-development-369","question":"A 20-month-old wants a chain out of a matchbox that is open only a slit. She stops, looks at the slit, slowly opens and closes her own mouth, and then pushes the box open wider. Piaget saw such behaviour as evidence of:","options":["Secondary circular reactions repeating an interesting effect","Simple reflexes being modified by experience","Mental representation: inner combination of actions before acting","Tertiary circular reactions based on open trial and error with the box"],"answer":2,"explanation":"In the final sensorimotor substage (18 to 24 months) the child begins to think out a solution internally before acting, here shown by the mouth movement imitating the opening. Tertiary reactions involve overt trial and error instead.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"20 माह की एक बच्ची माचिस की डिब्बी से ज़ंजीर निकालना चाहती है जो केवल एक दरार जितनी खुली है। वह रुकती है, दरार को देखती है, धीरे-धीरे अपना मुँह खोलती और बंद करती है, और फिर डिब्बी को और चौड़ा धकेलकर खोल देती है। पियाजे ऐसे व्यवहार को किसका प्रमाण मानते?","optionsHi":["द्वितीयक वृत्तीय प्रतिक्रियाएँ जो रोचक प्रभाव को दोहराती हैं","अनुभव से संशोधित सरल प्रतिवर्त","मानसिक निरूपण: कार्य करने से पहले क्रियाओं का आंतरिक संयोजन","डिब्बी के साथ खुले प्रयास और त्रुटि पर आधारित तृतीयक वृत्तीय प्रतिक्रियाएँ"],"explanationHi":"अंतिम संवेदी-गामक उप-अवस्था (18 से 24 माह) में बच्ची कार्य करने से पहले आंतरिक रूप से समाधान सोचने लगती है, जो यहाँ खुलने की नकल करती मुँह की गति से दिखता है। तृतीयक प्रतिक्रियाओं में इसकी जगह प्रकट प्रयास और त्रुटि होती है।"},
  {"id":"cdp-child-development-370","question":"A six-year-old sorts leaves correctly by shape, but when asked why, says only, ‘It just looks right.’ She also judges quantities by how they look. Piaget would place her in the:","options":["Preconceptual sub-stage of the pre-operational period","Intuitive sub-stage of the pre-operational period","Concrete operational stage","Last substage of the sensorimotor period"],"answer":1,"explanation":"In the intuitive sub-stage (about 4 to 7 years) children solve some problems by perception and intuition but cannot explain the logic. The preconceptual sub-stage (2 to 4) is marked more by emerging symbols and play.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"छह वर्ष की एक बच्ची पत्तियों को आकार के अनुसार सही छाँटती है, पर क्यों पूछे जाने पर केवल कहती है, ‘बस सही लगता है।’ वह मात्राओं का निर्णय भी इस आधार पर करती है कि वे कैसी दिखती हैं। पियाजे उसे किसमें रखेंगे?","optionsHi":["पूर्व-संक्रियात्मक काल की पूर्व-प्रत्ययात्मक उप-अवस्था","पूर्व-संक्रियात्मक काल की अंतर्ज्ञानात्मक उप-अवस्था","मूर्त संक्रियात्मक अवस्था","संवेदी-गामक काल की अंतिम उप-अवस्था"],"explanationHi":"अंतर्ज्ञानात्मक उप-अवस्था (लगभग 4 से 7 वर्ष) में बच्चे कुछ समस्याएँ प्रत्यक्षण और अंतर्ज्ञान से हल करते हैं पर तर्क समझा नहीं सकते। पूर्व-प्रत्ययात्मक उप-अवस्था (2 से 4) उभरते प्रतीकों और खेल से अधिक पहचानी जाती है।"},
  {"id":"cdp-child-development-371","question":"Asked what ‘Empty vessels make the most noise’ means, a 9-year-old says that empty pots ring loudly when you hit them. A 14-year-old says that people who know little often talk the most. The difference reflects the shift from:","options":["Concrete operational to formal operational thinking","Pre-operational thinking to concrete operational thinking","Assimilation to accommodation","Private speech to inner speech"],"answer":0,"explanation":"Interpreting a proverb requires abstract, figurative thought, which is characteristic of formal operations. The concrete operational child stays with the literal, physical meaning.","difficulty":"hard","source":"CTET · State TETs","questionHi":"यह पूछे जाने पर कि ‘खाली बर्तन सबसे ज़्यादा शोर करते हैं’ का क्या अर्थ है, 9 वर्ष का एक बच्चा कहता है कि खाली बर्तनों को मारने पर वे ज़ोर से बजते हैं। 14 वर्ष का एक किशोर कहता है कि जो लोग कम जानते हैं वे अक्सर सबसे ज़्यादा बोलते हैं। यह अंतर किस बदलाव को दर्शाता है?","optionsHi":["मूर्त संक्रियात्मक से औपचारिक संक्रियात्मक चिंतन","पूर्व-संक्रियात्मक चिंतन से मूर्त संक्रियात्मक चिंतन","आत्मसात्करण से समायोजन","निजी वाक् से आंतरिक वाक्"],"explanationHi":"किसी कहावत की व्याख्या करने के लिए अमूर्त, आलंकारिक चिंतन चाहिए, जो औपचारिक संक्रियाओं की विशेषता है। मूर्त संक्रियात्मक बच्चा शाब्दिक, भौतिक अर्थ पर ही टिका रहता है।"},
  {"id":"cdp-child-development-372","question":"Assertion (A): Piaget regarded discussion among peers as especially useful for cognitive growth. Reason (R): Among equals, conflicting views create disequilibrium that the child must resolve herself, whereas an adult’s view tends to be accepted simply on authority.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Piaget valued socio-cognitive conflict between peers because it forces children to rethink. Disagreement with an adult tends to produce compliance rather than real accommodation.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"अभिकथन (A): पियाजे साथियों के बीच चर्चा को संज्ञानात्मक वृद्धि के लिए विशेष रूप से उपयोगी मानते थे। कारण (R): बराबर वालों के बीच, परस्पर विरोधी विचार असाम्य पैदा करते हैं जिसे बच्चे को स्वयं हल करना होता है, जबकि वयस्क का विचार प्रायः केवल अधिकार के कारण मान लिया जाता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"पियाजे साथियों के बीच सामाजिक-संज्ञानात्मक टकराव को महत्व देते थे क्योंकि वह बच्चों को पुनर्विचार के लिए बाध्य करता है। वयस्क से असहमति प्रायः वास्तविक समायोजन की बजाय अनुपालन पैदा करती है।"},
  {"id":"cdp-child-development-373","question":"A Class 3 teacher in Jaipur wants to teach fractions to children who are mostly in Piaget’s concrete operational stage. Which plan fits their thinking best?","options":["Begin with the rule for adding fractions with unlike denominators and then give practice sums","Discuss what fractions would mean in a world with no whole numbers","Ask them to learn the definitions of numerator and denominator by heart first","Let them fold paper strips and share rotis into equal parts before writing fraction symbols"],"answer":3,"explanation":"Concrete operational children reason logically about things they can see and handle. Abstract rules, rote definitions or hypothetical worlds suit formal operational thinkers.","difficulty":"moderate","source":"CTET · KVS · State TETs","questionHi":"जयपुर में कक्षा 3 की एक शिक्षिका उन बच्चों को भिन्न पढ़ाना चाहती है जो अधिकांशतः पियाजे की मूर्त संक्रियात्मक अवस्था में हैं। कौन-सी योजना उनके चिंतन के सबसे अनुकूल है?","optionsHi":["असमान हर वाली भिन्नों को जोड़ने के नियम से शुरू करना और फिर अभ्यास के सवाल देना","चर्चा करना कि पूर्ण संख्याओं के बिना किसी संसार में भिन्नों का क्या अर्थ होता","उनसे पहले अंश और हर की परिभाषाएँ रटवाना","भिन्न के चिह्न लिखने से पहले उन्हें कागज़ की पट्टियाँ मोड़ने और रोटियों को बराबर भागों में बाँटने देना"],"explanationHi":"मूर्त संक्रियात्मक बच्चे उन चीज़ों के बारे में तार्किक रूप से सोचते हैं जिन्हें वे देख और छू सकते हैं। अमूर्त नियम, रटी परिभाषाएँ या काल्पनिक संसार औपचारिक संक्रियात्मक चिंतकों के अनुकूल हैं।"},
  {"id":"cdp-child-development-374","question":"Which of these is NOT a characteristic of thinking in Piaget’s concrete operational stage?","options":["Decentration: attending to several features of a problem at once","Reversibility: mentally undoing an action to its start","Reasoning about hypothetical premises that contradict known facts","Seriation and class inclusion with real, concrete objects"],"answer":2,"explanation":"Reasoning from premises that contradict reality belongs to formal operations. Decentration, reversibility, seriation and class inclusion all emerge in the concrete operational stage.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"इनमें से कौन-सा पियाजे की मूर्त संक्रियात्मक अवस्था में चिंतन की विशेषता नहीं है?","optionsHi":["विकेंद्रण: किसी समस्या की कई विशेषताओं पर एक साथ ध्यान देना","उत्क्रमणीयता: किसी क्रिया को मन में उसकी शुरुआत तक पलटना","ज्ञात तथ्यों के विपरीत काल्पनिक आधार-वाक्यों के बारे में तर्क करना","वास्तविक, मूर्त वस्तुओं के साथ क्रमबद्धता और वर्ग-समावेशन"],"explanationHi":"वास्तविकता के विपरीत आधार-वाक्यों से तर्क करना औपचारिक संक्रियाओं का है। विकेंद्रण, उत्क्रमणीयता, क्रमबद्धता और वर्ग-समावेशन सभी मूर्त संक्रियात्मक अवस्था में उभरते हैं।"},
  {"id":"cdp-child-development-375","question":"A child sees that a short, fat clay ball and a long sausage made from it have ‘the same clay’. Piaget held that, of the following, the abilities that make this possible are:","options":["Centration and irreversibility","Decentration and reversibility","Animism and artificialism","Assimilation and egocentrism"],"answer":1,"explanation":"Conservation needs decentration (considering length and thickness together) and reversibility (mentally rolling the sausage back). Centration and irreversibility are exactly what cause pre-operational children to fail.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक बच्चा देखता है कि छोटी, मोटी मिट्टी की गेंद और उससे बनी लंबी सॉसेज में ‘उतनी ही मिट्टी’ है। पियाजे के अनुसार, निम्नलिखित में से वे क्षमताएँ कौन-सी हैं जो इसे संभव बनाती हैं?","optionsHi":["केंद्रीकरण और अनुत्क्रमणीयता","विकेंद्रण और उत्क्रमणीयता","सजीववाद और कृत्रिमवाद","आत्मसात्करण और अहंकेंद्रिता"],"explanationHi":"संरक्षण के लिए विकेंद्रण (लंबाई और मोटाई को साथ-साथ देखना) और उत्क्रमणीयता (सॉसेज को मन में वापस गेंद बनाना) चाहिए। केंद्रीकरण और अनुत्क्रमणीयता ठीक वही हैं जो पूर्व-संक्रियात्मक बच्चों को विफल करते हैं।"},
  {"id":"cdp-child-development-376","question":"Ms. Rekha and Mr. Imran give the same 10-item quiz on fractions to their Class 5 sections on the last day of the unit. Rekha enters the scores in the register as the unit grade and starts the next chapter. Imran groups the wrong answers by error type and spends the next two periods reteaching the error of ‘adding the denominators’ before moving on. Which conclusion is most defensible?","options":["Both used formative assessment, since a short quiz is a formative tool by its nature","Both used summative assessment, since the quiz came on the last day of the unit","Rekha used it summatively, Imran formatively; how evidence is used decides the function","Imran’s use is diagnostic rather than formative, because diagnosis can only follow a summative test"],"answer":2,"explanation":"Whether assessment is formative or summative depends on how the evidence is used, not on the tool or its timing. Imran fed the evidence back into teaching; Rekha only recorded a judgement.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"सुश्री रेखा और श्री इमरान इकाई के अंतिम दिन अपने कक्षा 5 के अनुभागों को भिन्नों पर वही 10-प्रश्नों की क्विज़ देते हैं। रेखा अंकों को रजिस्टर में इकाई के ग्रेड के रूप में दर्ज करती है और अगला अध्याय शुरू कर देती है। इमरान गलत उत्तरों को त्रुटि के प्रकार के अनुसार समूहित करता है और आगे बढ़ने से पहले अगले दो पीरियड ‘हरों को जोड़ने’ की त्रुटि को दोबारा पढ़ाने में लगाता है। कौन-सा निष्कर्ष सबसे सुरक्षित है?","optionsHi":["दोनों ने रचनात्मक आकलन किया, क्योंकि छोटी क्विज़ स्वभाव से ही रचनात्मक उपकरण है","दोनों ने योगात्मक आकलन किया, क्योंकि क्विज़ इकाई के अंतिम दिन आई","रेखा ने इसे योगात्मक रूप से और इमरान ने रचनात्मक रूप से उपयोग किया; साक्ष्य का उपयोग कैसे होता है, वही प्रकार्य तय करता है","इमरान का उपयोग रचनात्मक की बजाय निदानात्मक है, क्योंकि निदान केवल योगात्मक परीक्षण के बाद ही हो सकता है"],"explanationHi":"आकलन रचनात्मक है या योगात्मक, यह इस पर निर्भर करता है कि साक्ष्य का उपयोग कैसे होता है, न कि उपकरण या उसके समय पर। इमरान ने साक्ष्य को वापस शिक्षण में लगाया; रेखा ने केवल एक निर्णय दर्ज किया।"},
  {"id":"cdp-child-development-377","question":"After a practice test, a Class 8 teacher stops handing out the answer key. Instead, each student compares her own work with three worked exemplars, marks exactly where her reasoning broke down and writes one strategy she will try next time. The teacher is mainly trying to develop:","options":["Students’ ability to monitor and regulate their learning, i.e. assessment as learning","A more reliable record of achievement for the term report, i.e. assessment of learning","The teacher’s own evidence for regrouping the class, i.e. assessment for learning","A norm-referenced comparison of each student with the class average on the practice test"],"answer":0,"explanation":"In assessment as learning the student is the one who uses the evidence, checking work against criteria and adjusting strategy; that metacognitive self-regulation is the goal, not grading or the teacher’s planning.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"एक अभ्यास परीक्षण के बाद कक्षा 8 की एक शिक्षिका उत्तर-कुंजी बाँटना बंद कर देती है। इसके बजाय, प्रत्येक विद्यार्थी अपने कार्य की तुलना तीन हल किए गए आदर्श उदाहरणों से करती है, ठीक वहाँ चिह्नित करती है जहाँ उसका तर्क टूटा, और अगली बार आज़माने की एक युक्ति लिखती है। शिक्षिका मुख्यतः क्या विकसित करने का प्रयास कर रही है?","optionsHi":["अपने अधिगम की निगरानी और नियमन की विद्यार्थियों की क्षमता, यानी अधिगम के रूप में आकलन","सत्र की रिपोर्ट के लिए उपलब्धि का अधिक विश्वसनीय अभिलेख, यानी अधिगम का आकलन","कक्षा को पुनः समूहित करने के लिए शिक्षिका के अपने साक्ष्य, यानी अधिगम के लिए आकलन","अभ्यास परीक्षण में प्रत्येक विद्यार्थी की कक्षा के औसत से मानक-संदर्भित तुलना"],"explanationHi":"अधिगम के रूप में आकलन में विद्यार्थी स्वयं साक्ष्य का उपयोग करता है, कसौटियों के विरुद्ध कार्य जाँचता है और युक्ति समायोजित करता है; वह अधिसंज्ञानात्मक आत्म-नियमन ही लक्ष्य है, ग्रेडिंग या शिक्षिका की योजना नहीं।"},
  {"id":"cdp-child-development-378","question":"In a classroom trial, one group of Class 6 students gets only marks on their written work, a second group gets only specific written comments, and a third gets both marks and comments. Research on feedback (for example, Ruth Butler’s studies) most consistently predicts that on the next task:","options":["The marks-plus-comments group improves most, since it receives the most information","All three groups improve equally, since any kind of feedback motivates learners to try","The marks-only group improves most, since a number is clear, objective and easy to act on","The comments-only group improves most, since a mark draws attention away from comments"],"answer":3,"explanation":"When a grade is present, students focus on it and largely ignore the comment, so marks-plus-comments behaves much like marks alone; descriptive comments alone produced the most improvement.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT","questionHi":"एक कक्षा परीक्षण में कक्षा 6 के विद्यार्थियों के एक समूह को अपने लिखित कार्य पर केवल अंक मिलते हैं, दूसरे को केवल विशिष्ट लिखित टिप्पणियाँ, और तीसरे को अंक और टिप्पणियाँ दोनों। प्रतिपुष्टि पर शोध (उदाहरणतः रूथ बटलर के अध्ययन) अगले कार्य पर सबसे अधिक सुसंगत रूप से क्या पूर्वानुमान देता है?","optionsHi":["अंक-सहित-टिप्पणी वाला समूह सबसे अधिक सुधरता है, क्योंकि उसे सबसे अधिक सूचना मिलती है","तीनों समूह समान रूप से सुधरते हैं, क्योंकि किसी भी प्रकार की प्रतिपुष्टि अधिगमकर्ताओं को प्रयास के लिए प्रेरित करती है","केवल-अंक वाला समूह सबसे अधिक सुधरता है, क्योंकि संख्या स्पष्ट, वस्तुनिष्ठ और उस पर कार्य करना आसान है","केवल-टिप्पणी वाला समूह सबसे अधिक सुधरता है, क्योंकि अंक टिप्पणियों से ध्यान हटा देता है"],"explanationHi":"जब ग्रेड मौजूद हो, तो विद्यार्थी उसी पर ध्यान देते हैं और टिप्पणी की काफी हद तक अनदेखी करते हैं, इसलिए अंक-सहित-टिप्पणी लगभग केवल अंक जैसा व्यवहार करती है; केवल वर्णनात्मक टिप्पणियों ने सबसे अधिक सुधार दिया।"},
  {"id":"cdp-child-development-379","question":"Which teacher remark on a Class 4 child’s story is task-involving feedback rather than ego-involving feedback?","options":["‘You are the brightest child in this class, so I expect the best story from you.’","‘Your story has a clear beginning; now add a sentence showing how Meena felt.’","‘Better than last time, but Riya’s story is still the best in the class.’","‘Good work, here is a gold star for you to put on your chart.’"],"answer":1,"explanation":"Task-involving feedback points to the work and the next step; praise of the person, comparison with peers and stars draw attention to the self or to rank rather than to how to improve.","difficulty":"moderate","source":"CTET Paper I · State TET","questionHi":"कक्षा 4 के बच्चे की कहानी पर शिक्षक की कौन-सी टिप्पणी अहं-संलग्न प्रतिपुष्टि की बजाय कार्य-संलग्न प्रतिपुष्टि है?","optionsHi":["‘तुम इस कक्षा के सबसे होशियार बच्चे हो, इसलिए मैं तुमसे सबसे अच्छी कहानी की अपेक्षा करती हूँ।’","‘तुम्हारी कहानी की शुरुआत स्पष्ट है; अब एक वाक्य जोड़ो जो दिखाए कि मीना को कैसा लगा।’","‘पिछली बार से बेहतर, पर रिया की कहानी अब भी कक्षा में सबसे अच्छी है।’","‘अच्छा काम, यह लो तुम्हारे लिए सोने का सितारा, अपने चार्ट पर लगाने के लिए।’"],"explanationHi":"कार्य-संलग्न प्रतिपुष्टि कार्य और अगले कदम की ओर इंगित करती है; व्यक्ति की प्रशंसा, साथियों से तुलना और सितारे ध्यान को सुधार के तरीके की बजाय स्वयं या रैंक की ओर खींचते हैं।"},
  {"id":"cdp-child-development-380","question":"A Class 3 teacher notices several children writing 304 for ‘thirty-four’. Before planning remedial work she gives them a short set of tasks designed only to find whether the error comes from place-value confusion or from writing numbers the way they are spoken. This set of tasks is best called:","options":["A summative test, since it checks what children have learnt in the unit so far","A diagnostic test, since it pinpoints the cause of a learning difficulty","A prognostic test, since it forecasts future achievement in mathematics","A placement test, since it decides which section a child should join"],"answer":1,"explanation":"A diagnostic test probes the root cause of a known difficulty so that remedial teaching can target it; it neither grades achievement nor predicts future performance.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"कक्षा 3 की एक शिक्षिका देखती है कि कई बच्चे ‘चौंतीस’ के लिए 304 लिख रहे हैं। उपचारात्मक कार्य की योजना बनाने से पहले वह उन्हें कार्यों का एक छोटा समूह देती है जो केवल यह पता लगाने के लिए बना है कि त्रुटि स्थानीय मान के भ्रम से आती है या संख्याओं को वैसे लिखने से जैसे वे बोली जाती हैं। कार्यों के इस समूह को सबसे अच्छी तरह क्या कहेंगे?","optionsHi":["योगात्मक परीक्षण, क्योंकि यह जाँचता है कि बच्चों ने इकाई में अब तक क्या सीखा","निदानात्मक परीक्षण, क्योंकि यह अधिगम कठिनाई के कारण की पहचान करता है","पूर्वानुमानात्मक परीक्षण, क्योंकि यह गणित में भविष्य की उपलब्धि का पूर्वानुमान देता है","स्थान-निर्धारण परीक्षण, क्योंकि यह तय करता है कि बच्चे को किस अनुभाग में जाना चाहिए"],"explanationHi":"निदानात्मक परीक्षण किसी ज्ञात कठिनाई के मूल कारण की जाँच करता है ताकि उपचारात्मक शिक्षण उसे लक्षित कर सके; वह न उपलब्धि को ग्रेड देता है न भविष्य के प्रदर्शन का अनुमान लगाता है।"},
  {"id":"cdp-child-development-381","question":"Consider these statements: I. A summative assessment can be used formatively if its results guide the next term’s teaching. II. Formative assessment must always be informal and never recorded. III. Grading every formative task tends to weaken its formative function. IV. Summative assessment is necessarily norm-referenced. Which are correct?","options":["I and II only","II and IV only","I, III and IV only","I and III only"],"answer":3,"explanation":"Formative evidence can be structured and recorded (II is false), and summative judgements can be criterion-referenced, as in a competency test (IV is false). I and III are correct.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"इन कथनों पर विचार कीजिए: I. योगात्मक आकलन को रचनात्मक रूप से उपयोग किया जा सकता है यदि उसके परिणाम अगले सत्र के शिक्षण का मार्गदर्शन करें। II. रचनात्मक आकलन हमेशा अनौपचारिक होना चाहिए और कभी दर्ज नहीं किया जाना चाहिए। III. हर रचनात्मक कार्य को ग्रेड देने से उसका रचनात्मक प्रकार्य कमज़ोर होता है। IV. योगात्मक आकलन अनिवार्यतः मानक-संदर्भित होता है। कौन-से सही हैं?","optionsHi":["केवल I और II","केवल II और IV","केवल I, III और IV","केवल I और III"],"explanationHi":"रचनात्मक साक्ष्य संरचित और दर्ज किया जा सकता है (II गलत है), और योगात्मक निर्णय कसौटी-संदर्भित हो सकते हैं, जैसे दक्षता परीक्षण में (IV गलत है)। I और III सही हैं।"},
  {"id":"cdp-child-development-382","question":"Assertion (A): Giving marks after every classroom activity in the name of CCE can turn formative assessment into continuous summative testing. Reason (R): The value of formative assessment lies in a feedback loop that changes teaching and learning, not in the number of records kept.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Frequent marking without feedback only produces more summative judgements; R explains why: what makes assessment formative is that the evidence is used to change teaching and learning.","difficulty":"hard","source":"CTET · State TET","questionHi":"अभिकथन (A): CCE के नाम पर हर कक्षा गतिविधि के बाद अंक देना रचनात्मक आकलन को सतत योगात्मक परीक्षण में बदल सकता है। कारण (R): रचनात्मक आकलन का मूल्य उस प्रतिपुष्टि चक्र में है जो शिक्षण और अधिगम को बदलता है, न कि रखे गए अभिलेखों की संख्या में।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"प्रतिपुष्टि के बिना बार-बार अंक देना केवल और योगात्मक निर्णय पैदा करता है; R बताता है क्यों: आकलन को रचनात्मक वह बनाता है कि साक्ष्य का उपयोग शिक्षण और अधिगम बदलने में होता है।"},
  {"id":"cdp-child-development-383","question":"A state wants to know whether each Class 5 child can read a short paragraph with comprehension, regardless of how classmates perform. A test built for this purpose should be:","options":["Norm-referenced, ranking each child against a state-wide average score","Speeded, so that only quick readers are counted as successful readers","Criterion-referenced, judging each child against a set reading standard","Percentile-based, reporting the child’s position within her own class"],"answer":2,"explanation":"‘Can this child do X?’ is a criterion-referenced question; ranks and percentiles (norm-referencing) say where a child stands relative to others, not whether the standard has been met.","difficulty":"moderate","source":"KVS PRT · NVS","questionHi":"एक राज्य जानना चाहता है कि कक्षा 5 का प्रत्येक बच्चा बोध के साथ एक छोटा अनुच्छेद पढ़ सकता है या नहीं, चाहे सहपाठियों का प्रदर्शन कैसा भी हो। इस उद्देश्य से बनाया गया परीक्षण होना चाहिए:","optionsHi":["मानक-संदर्भित, जो प्रत्येक बच्चे को राज्य-स्तरीय औसत अंक के विरुद्ध क्रम देता है","गति-आधारित, ताकि केवल तेज़ पाठक ही सफल पाठक गिने जाएँ","कसौटी-संदर्भित, जो प्रत्येक बच्चे को निर्धारित पठन मानक के विरुद्ध परखता है","शतमक-आधारित, जो बच्चे की अपनी कक्षा के भीतर स्थिति बताता है"],"explanationHi":"‘क्या यह बच्चा X कर सकता है?’ कसौटी-संदर्भित प्रश्न है; रैंक और शतमक (मानक-संदर्भन) बताते हैं कि बच्चा दूसरों की तुलना में कहाँ खड़ा है, यह नहीं कि मानक पूरा हुआ या नहीं।"},
  {"id":"cdp-child-development-384","question":"A teacher decides that in every class test the top 10% of students will get grade A, the next 20% grade B, and so on, whatever the actual scores. In a section where every student has fully mastered the unit, this policy will:","options":["Correctly reward mastery, since the grading is criterion-referenced and fixed in advance","Still give lower grades to many who mastered it, because the grading is norm-referenced","Give every student grade A, since all of them have reached the required standard","Be unfair only if the test happens to be an objective-type test with one right answer"],"answer":1,"explanation":"Fixing proportions for each grade is relative (norm-referenced) grading: it reports rank, not mastery, so even students who have mastered the unit are pushed into B, C and lower grades.","difficulty":"very-hard","source":"DSSSB TGT · KVS TGT","questionHi":"एक शिक्षिका तय करती है कि हर कक्षा परीक्षण में शीर्ष 10% विद्यार्थियों को ग्रेड A मिलेगा, अगले 20% को ग्रेड B, और इसी तरह, वास्तविक अंक चाहे जो हों। जिस अनुभाग में हर विद्यार्थी ने इकाई में पूर्ण निपुणता प्राप्त कर ली है, वहाँ यह नीति:","optionsHi":["निपुणता को सही ढंग से पुरस्कृत करेगी, क्योंकि ग्रेडिंग कसौटी-संदर्भित है और पहले से निश्चित है","फिर भी निपुणता पाने वाले कई विद्यार्थियों को कम ग्रेड देगी, क्योंकि ग्रेडिंग मानक-संदर्भित है","हर विद्यार्थी को ग्रेड A देगी, क्योंकि सब आवश्यक मानक तक पहुँच चुके हैं","केवल तब अनुचित होगी जब परीक्षण संयोग से एक सही उत्तर वाला वस्तुनिष्ठ प्रकार का हो"],"explanationHi":"प्रत्येक ग्रेड के लिए अनुपात निश्चित करना सापेक्ष (मानक-संदर्भित) ग्रेडिंग है: वह रैंक बताती है, निपुणता नहीं, इसलिए जिन विद्यार्थियों ने इकाई में निपुणता पा ली है वे भी B, C और निम्न ग्रेड में धकेल दिए जाते हैं।"},
  {"id":"cdp-child-development-385","question":"A Class 6 English teacher keeps a writing portfolio for each child. Which practice would most weaken the portfolio as an assessment tool?","options":["Asking each child to write a short note on why she chose each piece for it","Including early drafts alongside the final versions of the same pieces","Filling it only with neat, teacher-corrected final copies chosen by the teacher","Using shared criteria to discuss the pieces with the child and her parents"],"answer":2,"explanation":"A portfolio’s value lies in showing growth over time and the learner’s own selection and reflection; a file of polished, teacher-chosen final copies shows neither progress nor student voice.","difficulty":"hard","source":"CTET Paper II · State TET","questionHi":"कक्षा 6 की एक अंग्रेजी शिक्षिका हर बच्चे के लिए एक लेखन पोर्टफोलियो रखती है। कौन-सी पद्धति पोर्टफोलियो को आकलन उपकरण के रूप में सबसे अधिक कमज़ोर करेगी?","optionsHi":["हर बच्चे से कहना कि वह लिखे कि उसने उसमें हर रचना क्यों चुनी","एक ही रचनाओं के अंतिम रूपों के साथ आरंभिक प्रारूप भी शामिल करना","उसे केवल साफ-सुथरी, शिक्षिका द्वारा सुधारी हुई अंतिम प्रतियों से भरना जो शिक्षिका ने चुनी हों","साझा कसौटियों का उपयोग करके बच्चे और उसके माता-पिता के साथ रचनाओं पर चर्चा करना"],"explanationHi":"पोर्टफोलियो का मूल्य समय के साथ वृद्धि और अधिगमकर्ता के अपने चयन तथा चिंतन को दिखाने में है; शिक्षिका द्वारा चुनी चमकदार अंतिम प्रतियों की फ़ाइल न प्रगति दिखाती है न विद्यार्थी की आवाज़।"},
  {"id":"cdp-child-development-386","question":"Which entry is the best example of a properly written anecdotal record?","options":["‘Raju is a naughty and aggressive boy who always troubles others in the games period.’","‘Raju seemed jealous of Sunil today, probably because of problems at home, I feel.’","‘Raju behaved badly in the games period today, as usual, and upset others.’","‘12 Aug, games: Raju pushed Sunil when Sunil took the ball; he said, “It was my turn.”’"],"answer":3,"explanation":"An anecdotal record is dated, specific and factual, with any interpretation kept separate; labels (‘naughty’), generalisations (‘always’, ‘as usual’) and guesses about causes make a record unreliable.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"कौन-सी प्रविष्टि सही ढंग से लिखे गए आख्यानात्मक अभिलेख का सबसे अच्छा उदाहरण है?","optionsHi":["‘राजू शरारती और आक्रामक लड़का है जो खेल के पीरियड में हमेशा दूसरों को परेशान करता है।’","‘राजू आज सुनील से ईर्ष्या करता लगा, शायद घर की समस्याओं के कारण, मुझे लगता है।’","‘राजू ने आज खेल के पीरियड में बुरा व्यवहार किया, हमेशा की तरह, और दूसरों को परेशान किया।’","‘12 अगस्त, खेल: जब सुनील ने गेंद ली तो राजू ने सुनील को धक्का दिया; उसने कहा, “मेरी बारी थी।”’"],"explanationHi":"आख्यानात्मक अभिलेख दिनांकित, विशिष्ट और तथ्यात्मक होता है, और किसी भी व्याख्या को अलग रखा जाता है; लेबल (‘शरारती’), सामान्यीकरण (‘हमेशा’, ‘हमेशा की तरह’) और कारणों के अनुमान अभिलेख को अविश्वसनीय बनाते हैं।"},
  {"id":"cdp-child-development-387","question":"Match each tool with what it records: P. Checklist  Q. Rating scale  R. Analytic rubric  S. Anecdotal record — 1. Whether a behaviour or feature is present or absent  2. The degree or frequency of a trait on a graded continuum  3. A description of each performance level for each separate criterion  4. A brief factual account of a significant incident","options":["P-2, Q-1, R-3, S-4","P-1, Q-3, R-2, S-4","P-1, Q-2, R-3, S-4","P-1, Q-2, R-4, S-3"],"answer":2,"explanation":"A checklist is yes/no, a rating scale records how much or how often, an analytic rubric describes levels for each criterion, and an anecdotal record narrates an incident.","difficulty":"hard","source":"CTET · DSSSB PRT","questionHi":"प्रत्येक उपकरण का मिलान उससे कीजिए जो वह दर्ज करता है: P. जाँच-सूची Q. निर्धारण मापनी R. विश्लेषणात्मक रूब्रिक S. आख्यानात्मक अभिलेख — 1. कोई व्यवहार या विशेषता उपस्थित है या अनुपस्थित 2. श्रेणीबद्ध सातत्य पर किसी गुण की मात्रा या आवृत्ति 3. प्रत्येक अलग कसौटी के लिए प्रत्येक प्रदर्शन-स्तर का वर्णन 4. किसी महत्वपूर्ण घटना का संक्षिप्त तथ्यात्मक विवरण","optionsHi":["P-2, Q-1, R-3, S-4","P-1, Q-3, R-2, S-4","P-1, Q-2, R-3, S-4","P-1, Q-2, R-4, S-3"],"explanationHi":"जाँच-सूची हाँ/नहीं है, निर्धारण मापनी कितना या कितनी बार दर्ज करती है, विश्लेषणात्मक रूब्रिक प्रत्येक कसौटी के लिए स्तरों का वर्णन करता है, और आख्यानात्मक अभिलेख किसी घटना का वर्णन करता है।"},
  {"id":"cdp-child-development-388","question":"While rating children on a five-point scale for ‘participation’, a teacher who does not want to seem either strict or soft rates almost every child 3. Earlier, she rated one child high on every trait simply because he is very polite. These two errors are respectively:","options":["Leniency error and logical error","Central tendency error and halo effect","Halo effect and central tendency error","Severity error and leniency error"],"answer":1,"explanation":"Bunching ratings in the middle is the central tendency error; letting one favourable trait (politeness) raise ratings on all traits is the halo effect.","difficulty":"very-hard","source":"DSSSB TGT · KVS TGT","questionHi":"‘सहभागिता’ के लिए बच्चों को पाँच-बिंदु मापनी पर निर्धारित करते समय, एक शिक्षिका जो न सख्त दिखना चाहती है न नरम, लगभग हर बच्चे को 3 अंक देती है। इससे पहले, उसने एक बच्चे को हर गुण पर ऊँचा निर्धारित किया क्योंकि वह बहुत विनम्र है। ये दोनों त्रुटियाँ क्रमशः क्या हैं?","optionsHi":["उदारता त्रुटि और तार्किक त्रुटि","केंद्रीय प्रवृत्ति त्रुटि और प्रभामंडल प्रभाव","प्रभामंडल प्रभाव और केंद्रीय प्रवृत्ति त्रुटि","कठोरता त्रुटि और उदारता त्रुटि"],"explanationHi":"निर्धारणों को बीच में इकट्ठा करना केंद्रीय प्रवृत्ति त्रुटि है; एक अनुकूल गुण (विनम्रता) को सभी गुणों पर निर्धारण ऊँचा करने देना प्रभामंडल प्रभाव है।"},
  {"id":"cdp-child-development-389","question":"A teacher must assess 40 short poems and also tell each child exactly which aspect, whether imagery, rhythm or word choice, needs work. Which rubric design suits this second goal, and why?","options":["An analytic rubric, since it scores each criterion separately and shows the weakness","A holistic rubric, because a single overall score is the most specific feedback","A holistic rubric, because it is always more reliable than an analytic one","No rubric, because creative writing cannot be judged against any fixed criteria"],"answer":0,"explanation":"A holistic rubric gives one overall judgement (quick but not diagnostic); an analytic rubric rates each criterion, so it tells the child which aspect to improve.","difficulty":"hard","source":"CTET Paper II · State TET","questionHi":"एक शिक्षिका को 40 छोटी कविताओं का आकलन करना है और प्रत्येक बच्चे को ठीक यह भी बताना है कि किस पहलू, बिंब, लय या शब्द-चयन, पर काम चाहिए। इस दूसरे लक्ष्य के लिए कौन-सा रूब्रिक डिज़ाइन उपयुक्त है, और क्यों?","optionsHi":["विश्लेषणात्मक रूब्रिक, क्योंकि वह प्रत्येक कसौटी को अलग अंक देता है और कमज़ोरी दिखाता है","समग्र रूब्रिक, क्योंकि एकल समग्र अंक सबसे विशिष्ट प्रतिपुष्टि है","समग्र रूब्रिक, क्योंकि वह हमेशा विश्लेषणात्मक से अधिक विश्वसनीय होता है","कोई रूब्रिक नहीं, क्योंकि सृजनात्मक लेखन को किसी निश्चित कसौटी पर नहीं आँका जा सकता"],"explanationHi":"समग्र रूब्रिक एक समग्र निर्णय देता है (त्वरित पर निदानात्मक नहीं); विश्लेषणात्मक रूब्रिक प्रत्येक कसौटी का निर्धारण करता है, इसलिए वह बच्चे को बताता है कि किस पहलू में सुधार करना है।"},
  {"id":"cdp-child-development-390","question":"A Class 7 social science test gives almost the same scores when repeated after a week, but all its questions are about dates and names, although the unit aimed at map reading and reasoning about causes. The test is best described as:","options":["Valid but not reliable","Neither valid nor reliable","Both reliable and valid, since consistent scores show validity","Reliable but low in content validity"],"answer":3,"explanation":"Consistent scores show reliability, but a test that ignores the unit’s main objectives does not measure what it should, so its content validity is low; consistency alone never proves validity.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT","questionHi":"कक्षा 7 की सामाजिक विज्ञान की एक परीक्षा एक सप्ताह बाद दोहराने पर लगभग समान अंक देती है, पर उसके सभी प्रश्न तिथियों और नामों के बारे में हैं, जबकि इकाई का उद्देश्य मानचित्र-पठन और कारणों के बारे में तर्क था। परीक्षा का सबसे अच्छा वर्णन है:","optionsHi":["वैध पर विश्वसनीय नहीं","न वैध न विश्वसनीय","विश्वसनीय और वैध दोनों, क्योंकि सुसंगत अंक वैधता दर्शाते हैं","विश्वसनीय पर विषयवस्तु वैधता में निम्न"],"explanationHi":"सुसंगत अंक विश्वसनीयता दर्शाते हैं, पर जो परीक्षण इकाई के मुख्य उद्देश्यों की अनदेखी करता है वह वह नहीं मापता जो उसे मापना चाहिए, इसलिए उसकी विषयवस्तु वैधता निम्न है; सुसंगतता अकेली वैधता सिद्ध नहीं करती।"},
  {"id":"cdp-child-development-391","question":"Which of these statements are correct? I. A test cannot be valid for a purpose unless it is reasonably reliable. II. A highly reliable test is necessarily valid. III. Adding more good items to a test generally increases its reliability. IV. Inter-rater reliability matters most for essay-type and performance tasks.","options":["I and II only","II, III and IV only","I, III and IV only","I, II, III and IV"],"answer":2,"explanation":"Reliability is necessary but not sufficient for validity, so II is false. Longer tests of good items sample more consistently, and scorer agreement matters most where marking involves judgement.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"इनमें से कौन-से कथन सही हैं? I. कोई परीक्षण किसी उद्देश्य के लिए तब तक वैध नहीं हो सकता जब तक वह उचित रूप से विश्वसनीय न हो। II. अत्यधिक विश्वसनीय परीक्षण अनिवार्यतः वैध होता है। III. परीक्षण में और अच्छे पद जोड़ने से सामान्यतः उसकी विश्वसनीयता बढ़ती है। IV. निबंध-प्रकार और निष्पादन कार्यों के लिए अंतर-मूल्यांकनकर्ता विश्वसनीयता सबसे अधिक मायने रखती है।","optionsHi":["केवल I और II","केवल II, III और IV","केवल I, III और IV","I, II, III और IV"],"explanationHi":"विश्वसनीयता वैधता के लिए आवश्यक है पर पर्याप्त नहीं, इसलिए II गलत है। अच्छे पदों वाले लंबे परीक्षण अधिक सुसंगत रूप से प्रतिचयन करते हैं, और अंककर्ताओं की सहमति वहाँ सबसे अधिक मायने रखती है जहाँ अंकन में निर्णय शामिल हो।"},
  {"id":"cdp-child-development-392","question":"A school uses a Class 8 aptitude test to advise students on taking science in Class 11. To check whether the test is worth using for this, the school compares the same students’ Class 8 scores with their Class 11 science results. It is examining the test’s:","options":["Content validity","Predictive validity","Test–retest reliability","Face validity"],"answer":1,"explanation":"Comparing test scores with a later criterion (future performance) checks predictive validity; test–retest reliability would compare the same test given twice.","difficulty":"hard","source":"KVS TGT · DSSSB TGT","questionHi":"एक विद्यालय कक्षा 8 के विद्यार्थियों को कक्षा 11 में विज्ञान लेने की सलाह देने के लिए कक्षा 8 की अभिक्षमता परीक्षा का उपयोग करता है। यह जाँचने के लिए कि परीक्षण इसके लिए उपयोग करने योग्य है या नहीं, विद्यालय उन्हीं विद्यार्थियों के कक्षा 8 के अंकों की तुलना उनके कक्षा 11 के विज्ञान परिणामों से करता है। वह परीक्षण की किसकी जाँच कर रहा है?","optionsHi":["विषयवस्तु वैधता","भविष्यसूचक वैधता","परीक्षण–पुनःपरीक्षण विश्वसनीयता","आभासी वैधता (फेस वैलिडिटी)"],"explanationHi":"परीक्षण अंकों की तुलना बाद के मानदंड (भविष्य के प्रदर्शन) से करना भविष्यसूचक वैधता की जाँच करता है; परीक्षण–पुनःपरीक्षण विश्वसनीयता में उसी परीक्षण को दो बार देकर तुलना की जाती।"},
  {"id":"cdp-child-development-393","question":"Parents complain that a new Class 4 maths test ‘does not look like a maths test’ because it has stories and pictures, though subject experts confirm that its items cover every learning outcome of the term. The test is:","options":["High in content validity, though perhaps low in face validity","Low in content validity, since parents find it unconvincing","High in face validity but low in content validity overall","Invalid, since a maths test should contain only numbers and sums"],"answer":0,"explanation":"Content validity is judged by how well items sample the intended outcomes; face validity is only how valid the test appears to lay observers, which may be low here.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"अभिभावक शिकायत करते हैं कि कक्षा 4 का नया गणित परीक्षण ‘गणित के परीक्षण जैसा नहीं दिखता’ क्योंकि उसमें कहानियाँ और चित्र हैं, जबकि विषय विशेषज्ञ पुष्टि करते हैं कि उसके पद सत्र के हर अधिगम-प्रतिफल को समेटते हैं। परीक्षण है:","optionsHi":["विषयवस्तु वैधता में उच्च, यद्यपि संभवतः आभासी वैधता में निम्न","विषयवस्तु वैधता में निम्न, क्योंकि अभिभावकों को वह अविश्वसनीय लगता है","कुल मिलाकर आभासी वैधता में उच्च पर विषयवस्तु वैधता में निम्न","अवैध, क्योंकि गणित के परीक्षण में केवल संख्याएँ और सवाल होने चाहिए"],"explanationHi":"विषयवस्तु वैधता का निर्णय इससे होता है कि पद इच्छित प्रतिफलों का कितना अच्छा प्रतिचयन करते हैं; आभासी वैधता केवल यह है कि परीक्षण सामान्य प्रेक्षकों को कितना वैध लगता है, जो यहाँ निम्न हो सकती है।"},
  {"id":"cdp-child-development-394","question":"A teacher scores the odd-numbered and even-numbered items of one test separately and finds that children who do well on one half also do well on the other. She has gathered evidence of the test’s:","options":["Predictive validity against later scores","Test–retest reliability across two sittings","Internal consistency (split-half)","Content validity of the two halves"],"answer":2,"explanation":"Correlating two halves of a single administration is the split-half method, a measure of internal consistency; test–retest needs two administrations at different times.","difficulty":"hard","source":"KVS TGT · DSSSB TGT","questionHi":"एक शिक्षिका एक परीक्षण के विषम-संख्या वाले और सम-संख्या वाले पदों को अलग-अलग अंक देती है और पाती है कि जो बच्चे एक आधे में अच्छा करते हैं वे दूसरे आधे में भी अच्छा करते हैं। उसने परीक्षण के किसके साक्ष्य जुटाए हैं?","optionsHi":["बाद के अंकों के विरुद्ध भविष्यसूचक वैधता","दो बैठकों में परीक्षण–पुनःपरीक्षण विश्वसनीयता","आंतरिक संगति (अर्ध-विभाजन)","दोनों आधों की विषयवस्तु वैधता"],"explanationHi":"एक ही प्रशासन के दो आधों का सहसंबंध निकालना अर्ध-विभाजन विधि है, जो आंतरिक संगति का एक माप है; परीक्षण–पुनःपरीक्षण के लिए अलग-अलग समय पर दो प्रशासन चाहिए।"},
  {"id":"cdp-child-development-395","question":"Which item best assesses competency rather than recall in Class 7 science?","options":["‘Define the term acid and give one example from daily life.’","‘Name two acids found in the kitchen and the foods they occur in.’","‘What colour does blue litmus paper turn when it is dipped in an acidic solution?’","‘Ant bites inject acid. Should you apply baking soda paste or lemon juice, and why?’"],"answer":3,"explanation":"A competency item asks the learner to apply a concept to a new real-life situation; choosing a base (baking soda) to neutralise an acid needs understanding, while the others need only recall.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"कक्षा 7 के विज्ञान में कौन-सा पद स्मरण की बजाय दक्षता का सबसे अच्छा आकलन करता है?","optionsHi":["‘अम्ल पद को परिभाषित कीजिए और दैनिक जीवन से एक उदाहरण दीजिए।’","‘रसोई में पाए जाने वाले दो अम्लों और उन खाद्य पदार्थों के नाम बताइए जिनमें वे होते हैं।’","‘नीला लिटमस पेपर अम्लीय विलयन में डुबोने पर कौन-सा रंग हो जाता है?’","‘चींटी के काटने से अम्ल शरीर में जाता है। आपको खाने के सोडे का लेप लगाना चाहिए या नींबू का रस, और क्यों?’"],"explanationHi":"दक्षता पद में अधिगमकर्ता से किसी अवधारणा को नई वास्तविक-जीवन स्थिति में लागू करने को कहा जाता है; अम्ल को निष्प्रभावी करने के लिए क्षार (खाने का सोडा) चुनने के लिए समझ चाहिए, जबकि अन्य में केवल स्मरण चाहिए।"},
  {"id":"cdp-child-development-396","question":"Which observation best captures the main criticism of how CCE was often implemented in schools after 2009?","options":["It made assessment too infrequent, as children were tested only at the end of the year","It often became mere record-keeping of grades, with little evidence used to improve teaching","It ignored co-scholastic areas such as attitudes, values, arts and health education","It replaced grades with raw marks, increasing examination stress among young children"],"answer":1,"explanation":"Critics noted that CCE was frequently reduced to mechanical record-keeping and frequent testing, adding to teachers’ workload without the feedback loop that makes evaluation formative.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"2009 के बाद विद्यालयों में CCE के क्रियान्वयन की मुख्य आलोचना को कौन-सा अवलोकन सबसे अच्छी तरह दर्शाता है?","optionsHi":["इसने आकलन को बहुत कम बार होने वाला बना दिया, क्योंकि बच्चों का परीक्षण केवल वर्ष के अंत में होता था","यह प्रायः केवल ग्रेडों का अभिलेख रखना बन गया, जिसमें शिक्षण सुधारने के लिए साक्ष्य का बहुत कम उपयोग हुआ","इसने दृष्टिकोण, मूल्य, कला और स्वास्थ्य शिक्षा जैसे सह-शैक्षिक क्षेत्रों की उपेक्षा की","इसने ग्रेडों की जगह कच्चे अंक रख दिए, जिससे छोटे बच्चों में परीक्षा का तनाव बढ़ा"],"explanationHi":"आलोचकों ने नोट किया कि CCE को प्रायः यांत्रिक अभिलेख-रखरखाव और बार-बार की परीक्षा तक सीमित कर दिया गया, जिसने शिक्षकों का कार्यभार बढ़ाया पर उस प्रतिपुष्टि चक्र के बिना जो मूल्यांकन को रचनात्मक बनाता है।"},
  {"id":"cdp-child-development-397","question":"A school says its evaluation is ‘comprehensive’. This claim is justified only if the school:","options":["Assesses scholastic and co-scholastic aspects such as attitudes, values and health","Assesses every chapter of every textbook at least twice a term in written tests","Uses a variety of question types, from MCQs to essays, in its written tests","Conducts tests regularly and frequently throughout the academic year"],"answer":0,"explanation":"In CCE, ‘comprehensive’ refers to covering all aspects of a child’s development, scholastic and co-scholastic; regular testing through the year relates to ‘continuous’, not ‘comprehensive’.","difficulty":"hard","source":"CTET Paper I · State TET","questionHi":"एक विद्यालय कहता है कि उसका मूल्यांकन ‘व्यापक’ है। यह दावा तभी उचित है जब विद्यालय:","optionsHi":["शैक्षिक और दृष्टिकोण, मूल्य तथा स्वास्थ्य जैसे सह-शैक्षिक पहलुओं का आकलन करे","लिखित परीक्षाओं में प्रत्येक पाठ्यपुस्तक के प्रत्येक अध्याय का प्रति सत्र कम से कम दो बार आकलन करे","अपनी लिखित परीक्षाओं में MCQ से निबंध तक विविध प्रकार के प्रश्नों का उपयोग करे","शैक्षणिक वर्ष भर नियमित और बार-बार परीक्षाएँ ले"],"explanationHi":"CCE में ‘व्यापक’ का अर्थ है बच्चे के विकास के सभी पहलुओं, शैक्षिक और सह-शैक्षिक, को समेटना; वर्ष भर नियमित परीक्षा ‘सतत’ से संबंधित है, ‘व्यापक’ से नहीं।"},
  {"id":"cdp-child-development-398","question":"Midway through a lesson on evaporation, a teacher asks one multiple-choice question in which each wrong option matches a known misconception, and all students show their choice at the same moment with their fingers. Her main purpose is to:","options":["Award marks for participation to every student who shows an answer in class","Rank the students on their understanding before the term test begins","Decide at once, from the answer pattern, whether to move on or reteach, and whom","Prepare students for the multiple-choice format of board examinations"],"answer":2,"explanation":"Such a ‘hinge’ question is an assessment-for-learning technique: the pattern of answers tells the teacher at once which misconception exists and who needs reteaching before moving on.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT","questionHi":"वाष्पीकरण के पाठ के बीच एक शिक्षिका एक बहुविकल्पी प्रश्न पूछती है जिसमें हर गलत विकल्प किसी ज्ञात भ्रांत धारणा से मेल खाता है, और सभी विद्यार्थी एक ही क्षण में उँगलियों से अपना चुनाव दिखाते हैं। उसका मुख्य उद्देश्य है:","optionsHi":["कक्षा में उत्तर दिखाने वाले हर विद्यार्थी को सहभागिता के अंक देना","सत्र परीक्षा शुरू होने से पहले विद्यार्थियों को उनकी समझ के आधार पर क्रमबद्ध करना","उत्तरों के प्रतिरूप से तुरंत तय करना कि आगे बढ़ना है या दोबारा पढ़ाना है, और किसे","विद्यार्थियों को बोर्ड परीक्षाओं के बहुविकल्पी प्रारूप के लिए तैयार करना"],"explanationHi":"ऐसा ‘हिंज’ प्रश्न अधिगम के लिए आकलन की तकनीक है: उत्तरों का प्रतिरूप शिक्षिका को तुरंत बताता है कि कौन-सी भ्रांत धारणा मौजूद है और आगे बढ़ने से पहले किसे दोबारा पढ़ाना है।"},
  {"id":"cdp-child-development-399","question":"Which is a key condition for peer assessment in Class 6 to support learning?","options":["Peers should award marks that count in the final result, so that they take it seriously","Only the best students should assess others’ work, as they know the right answers","Peers should compare each piece of work with that of the class topper","Students first understand clear shared criteria, then give specific suggestions"],"answer":3,"explanation":"Peer assessment helps learning when students understand the success criteria and give specific, usable suggestions; turning it into marking or ranking makes it threatening and unreliable.","difficulty":"moderate","source":"CTET · State TET","questionHi":"कक्षा 6 में सहपाठी आकलन के अधिगम में सहायक होने के लिए कौन-सी एक प्रमुख शर्त है?","optionsHi":["सहपाठी ऐसे अंक दें जो अंतिम परिणाम में गिने जाएँ, ताकि वे इसे गंभीरता से लें","केवल सबसे अच्छे विद्यार्थी दूसरों के कार्य का आकलन करें, क्योंकि वे सही उत्तर जानते हैं","सहपाठी हर कार्य की तुलना कक्षा के टॉपर के कार्य से करें","विद्यार्थी पहले स्पष्ट साझा कसौटियाँ समझें, फिर विशिष्ट सुझाव दें"],"explanationHi":"सहपाठी आकलन तब अधिगम में सहायक होता है जब विद्यार्थी सफलता की कसौटियाँ समझते हैं और विशिष्ट, उपयोगी सुझाव देते हैं; उसे अंकन या रैंकिंग बना देना उसे डरावना और अविश्वसनीय बना देता है।"},
  {"id":"cdp-child-development-400","question":"A teacher asks a question and, if no hand rises within about a second, answers it herself. Research on classroom questioning suggests that increasing the wait time to three to five seconds mainly:","options":["Increases the number and length of student responses and the quality of thinking","Wastes teaching time without changing how students respond to the question","Benefits only the fastest students, who answer before the others can think","Encourages indiscipline because the class becomes idle while it waits"],"answer":0,"explanation":"Studies of wait time found that a few extra seconds lead to longer, more reasoned answers and more students responding, giving the teacher better evidence of understanding.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"एक शिक्षिका प्रश्न पूछती है और यदि लगभग एक सेकंड में कोई हाथ नहीं उठता, तो स्वयं उत्तर दे देती है। कक्षा में प्रश्न पूछने पर शोध सुझाता है कि प्रतीक्षा-समय को तीन से पाँच सेकंड तक बढ़ाने से मुख्यतः:","optionsHi":["विद्यार्थी-उत्तरों की संख्या और लंबाई तथा चिंतन की गुणवत्ता बढ़ती है","शिक्षण समय व्यर्थ जाता है और विद्यार्थियों की प्रश्न पर प्रतिक्रिया नहीं बदलती","केवल सबसे तेज़ विद्यार्थियों को लाभ होता है, जो दूसरों के सोचने से पहले उत्तर दे देते हैं","अनुशासनहीनता को बढ़ावा मिलता है क्योंकि प्रतीक्षा करते समय कक्षा निष्क्रिय हो जाती है"],"explanationHi":"प्रतीक्षा-समय के अध्ययनों ने पाया कि कुछ अतिरिक्त सेकंड लंबे, अधिक तर्कपूर्ण उत्तरों और अधिक विद्यार्थियों के उत्तर देने की ओर ले जाते हैं, जिससे शिक्षिका को समझ का बेहतर साक्ष्य मिलता है।"},
  {"id":"cdp-child-development-401","question":"In a variation of Bandura's Bobo doll study, children who saw the adult model punished imitated the aggression least. Yet when all children were later offered attractive rewards to show what the model had done, those children reproduced the aggressive acts about as well as the others. What does this finding show?","options":["Punishment of a model prevents observers from learning the punished behaviour at all","Learning can occur by observation alone; consequences mainly affect whether it is performed","Children learn only behaviours that are directly reinforced in their own actions","Rewards create new learning that was not present before the rewards were offered"],"answer":1,"explanation":"The behaviour had been acquired by observation; the model's punishment only suppressed its performance. Bandura's learning–performance distinction is exactly this point.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"बंडूरा के बोबो डॉल अध्ययन के एक रूपांतर में, जिन बच्चों ने वयस्क आदर्श को दंडित होते देखा, उन्होंने आक्रामकता की सबसे कम नकल की। फिर भी जब बाद में सभी बच्चों को आकर्षक पुरस्कार देने की पेशकश की गई कि वे दिखाएँ कि आदर्श ने क्या किया था, तो उन बच्चों ने आक्रामक कृत्यों को लगभग उतनी ही अच्छी तरह दोहराया जितना अन्य ने। यह निष्कर्ष क्या दर्शाता है?","optionsHi":["आदर्श को दंड मिलना प्रेक्षकों को दंडित व्यवहार सीखने से बिल्कुल रोक देता है","अधिगम केवल अवलोकन से हो सकता है; परिणाम मुख्यतः यह प्रभावित करते हैं कि उसे प्रदर्शित किया जाता है या नहीं","बच्चे केवल वही व्यवहार सीखते हैं जिन्हें उनके अपने कार्यों में सीधे पुनर्बलित किया जाता है","पुरस्कार ऐसा नया अधिगम पैदा करते हैं जो पुरस्कार देने से पहले मौजूद नहीं था"],"explanationHi":"व्यवहार अवलोकन से अर्जित हो चुका था; आदर्श के दंड ने केवल उसके प्रदर्शन को दबाया। बंडूरा का अधिगम–निष्पादन भेद ठीक यही बिंदु है।"},
  {"id":"cdp-child-development-402","question":"In a Class 2 room, the teacher warmly praises Priya for drawing neat margins on her page. The next morning, many children who were not praised also draw careful margins. This change is best explained by:","options":["Vicarious reinforcement","Negative reinforcement","Stimulus generalisation","Law of readiness"],"answer":0,"explanation":"The other children saw a peer's behaviour being reinforced and increased the same behaviour themselves: vicarious reinforcement, a key idea in Bandura's social learning theory.","difficulty":"moderate","source":"CTET Paper 1 · REET","questionHi":"कक्षा 2 के कमरे में शिक्षिका प्रिया की पन्ने पर साफ हाशिए बनाने के लिए गर्मजोशी से प्रशंसा करती हैं। अगली सुबह कई बच्चे, जिनकी प्रशंसा नहीं हुई, वे भी सावधानी से हाशिए बनाते हैं। इस परिवर्तन को सबसे अच्छी तरह कौन-सा कारक समझाता है?","optionsHi":["प्रतिनिधिक पुनर्बलन","ऋणात्मक पुनर्बलन","उद्दीपक सामान्यीकरण","तत्परता का नियम"],"explanationHi":"अन्य बच्चों ने एक साथी के व्यवहार को पुनर्बलित होते देखा और स्वयं वही व्यवहार बढ़ा दिया: प्रतिनिधिक पुनर्बलन, जो बंडूरा के सामाजिक अधिगम सिद्धांत का एक प्रमुख विचार है।"},
  {"id":"cdp-child-development-403","question":"Aman watches his chemistry teacher demonstrate a titration with full attention, but the next day he cannot recall the sequence of steps. To strengthen the weak process in Bandura's model, the teacher should:","options":["Offer him a reward for performing the titration correctly next time","Ask him to watch the same demonstration again without any discussion","Have him put the steps into words or a flow chart and rehearse them","Tell him that the titration will be tested in the final examination"],"answer":2,"explanation":"He attended but did not retain. Bandura's retention process is helped by symbolic coding (verbal labels, images) and rehearsal; rewards or exam threats work on motivation, which is not the problem here.","difficulty":"hard","source":"KVS TGT · NVS TGT","questionHi":"अमन अपने रसायन शिक्षक का अनुमापन (टाइट्रेशन) प्रदर्शन पूरे ध्यान से देखता है, पर अगले दिन चरणों का क्रम याद नहीं कर पाता। बंडूरा के मॉडल में कमज़ोर प्रक्रिया को मज़बूत करने के लिए शिक्षक को क्या करना चाहिए?","optionsHi":["अगली बार अनुमापन सही करने पर उसे पुरस्कार देना","उसे बिना किसी चर्चा के वही प्रदर्शन फिर देखने को कहना","उससे चरणों को शब्दों में या प्रवाह-चार्ट में लिखवाना और उनका अभ्यास कराना","उसे बताना कि अनुमापन अंतिम परीक्षा में पूछा जाएगा"],"explanationHi":"उसने ध्यान दिया पर धारण नहीं किया। बंडूरा की धारण प्रक्रिया को प्रतीकात्मक कूटसंकेतन (शाब्दिक लेबल, प्रतिमाएँ) और पुनरावृत्ति से सहायता मिलती है; पुरस्कार या परीक्षा की धमकी अभिप्रेरणा पर काम करती है, जो यहाँ समस्या नहीं है।"},
  {"id":"cdp-child-development-404","question":"According to social learning research, which model is a Class 8 student most likely to imitate when learning to present a project confidently?","options":["A famous actor seen in an advertisement, whose life is very unlike his own","A much younger child who is praised by the teacher for at least trying","A strict adult who demonstrates the skill and then criticises the class","A classmate of similar background who is competent and visibly rewarded for it"],"answer":3,"explanation":"Imitation is more likely when the model is perceived as similar, competent and reinforced. Dissimilar or unrewarded models are less influential for a learner's own behaviour.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"सामाजिक अधिगम शोध के अनुसार, किसी परियोजना को आत्मविश्वास से प्रस्तुत करना सीखते समय कक्षा 8 का विद्यार्थी किस आदर्श की सबसे अधिक नकल करेगा?","optionsHi":["विज्ञापन में दिखा कोई प्रसिद्ध अभिनेता, जिसका जीवन उसके अपने जीवन से बहुत भिन्न है","बहुत छोटा बच्चा जिसकी शिक्षिका कम से कम प्रयास करने के लिए प्रशंसा करती है","कोई कठोर वयस्क जो कौशल का प्रदर्शन करता है और फिर कक्षा की आलोचना करता है","समान पृष्ठभूमि का कोई सहपाठी जो सक्षम है और उसके लिए स्पष्ट रूप से पुरस्कृत होता है"],"explanationHi":"नकल की संभावना तब अधिक होती है जब आदर्श को समान, सक्षम और पुनर्बलित माना जाए। असमान या अपुरस्कृत आदर्श अधिगमकर्ता के अपने व्यवहार पर कम प्रभावशाली होते हैं।"},
  {"id":"cdp-child-development-405","question":"Pooja believes she cannot speak English in front of the class. Her teacher wants to use a vicarious source of self-efficacy. Which plan is most likely to work?","options":["Let her watch a classmate from her village, once nervous too, give a short English talk","Show Pooja a video of a famous news anchor reading the news fluently in English","Tell Pooja every day, firmly and warmly, that she is a confident speaker","Teach Pooja to ignore her nervousness completely and simply start speaking"],"answer":0,"explanation":"Vicarious experience raises self-efficacy most when the model is similar to the observer ('if she can, I can'). A celebrity is too dissimilar; repeated telling is verbal persuasion, a different and weaker source.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"पूजा को विश्वास है कि वह कक्षा के सामने अंग्रेजी नहीं बोल सकती। उसकी शिक्षिका आत्म-प्रभावकारिता के एक प्रतिनिधिक स्रोत का उपयोग करना चाहती है। कौन-सी योजना सबसे अधिक कारगर होगी?","optionsHi":["उसे अपने गाँव की एक सहपाठी को, जो पहले स्वयं घबराती थी, अंग्रेजी में एक छोटा भाषण देते देखने देना","पूजा को किसी प्रसिद्ध समाचार वाचक का अंग्रेजी में धाराप्रवाह समाचार पढ़ते हुए वीडियो दिखाना","पूजा से हर दिन दृढ़ता और स्नेह से कहना कि वह आत्मविश्वासी वक्ता है","पूजा को सिखाना कि अपनी घबराहट को पूरी तरह अनदेखा करे और बस बोलना शुरू कर दे"],"explanationHi":"प्रतिनिधिक अनुभव आत्म-प्रभावकारिता तब सबसे अधिक बढ़ाता है जब आदर्श प्रेक्षक के समान हो (‘अगर वह कर सकती है, तो मैं भी’)। कोई सेलिब्रिटी बहुत भिन्न है; बार-बार कहना शाब्दिक प्रोत्साहन है, जो एक अलग और कमज़ोर स्रोत है।"},
  {"id":"cdp-child-development-406","question":"Isha is cheerful, popular and feels good about herself, yet she is sure she cannot write geometry proofs and avoids them. Which statement best explains this in Bandura's terms?","options":["High self-esteem always produces high self-efficacy, so her doubt must be temporary","Self-efficacy is task-specific, so it can be low for proofs even when overall self-worth is high","Self-efficacy depends only on intelligence, which is fixed for a subject like geometry","Her avoidance shows low self-esteem that she is hiding behind her cheerful manner"],"answer":1,"explanation":"Self-efficacy is a belief about one's ability to perform a particular task, while self-esteem is a general evaluation of self-worth. The two can differ widely for the same person.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"ईशा प्रसन्नचित्त और लोकप्रिय है और अपने बारे में अच्छा महसूस करती है, फिर भी उसे पक्का विश्वास है कि वह ज्यामिति के उपपत्ति नहीं लिख सकती और उनसे बचती है। बंडूरा के शब्दों में इसे कौन-सा कथन सबसे अच्छी तरह समझाता है?","optionsHi":["उच्च आत्म-सम्मान हमेशा उच्च आत्म-प्रभावकारिता पैदा करता है, इसलिए उसका संदेह अस्थायी होगा","आत्म-प्रभावकारिता कार्य-विशिष्ट है, इसलिए समग्र आत्म-मूल्य के उच्च होने पर भी वह उपपत्तियों के लिए निम्न हो सकती है","आत्म-प्रभावकारिता केवल बुद्धि पर निर्भर करती है, जो ज्यामिति जैसे विषय के लिए निश्चित है","उसकी बचाव प्रवृत्ति निम्न आत्म-सम्मान दर्शाती है जिसे वह अपने प्रसन्न स्वभाव के पीछे छिपा रही है"],"explanationHi":"आत्म-प्रभावकारिता किसी विशेष कार्य को करने की अपनी क्षमता के बारे में विश्वास है, जबकि आत्म-सम्मान आत्म-मूल्य का सामान्य मूल्यांकन है। एक ही व्यक्ति के लिए दोनों में बहुत अंतर हो सकता है।"},
  {"id":"cdp-child-development-407","question":"Shy Ravi avoids group work in Class 6. Because he rarely joins in, classmates stop inviting him, which makes him more convinced that he is disliked, so he withdraws further. Bandura's concept that best describes this cycle is:","options":["Law of effect","Vicarious punishment by peers","Reciprocal determinism","Spontaneous recovery"],"answer":2,"explanation":"Reciprocal determinism holds that personal factors (beliefs), behaviour and environment continually influence one another; here each strengthens the others in a cycle.","difficulty":"hard","source":"CTET · UPTET","questionHi":"शर्मीला रवि कक्षा 6 में समूह कार्य से बचता है। क्योंकि वह शायद ही कभी शामिल होता है, सहपाठी उसे आमंत्रित करना बंद कर देते हैं, जिससे उसे और विश्वास हो जाता है कि वह नापसंद किया जाता है, और वह और अधिक सिमट जाता है। बंडूरा की कौन-सी अवधारणा इस चक्र का सबसे अच्छा वर्णन करती है?","optionsHi":["प्रभाव का नियम","साथियों द्वारा प्रतिनिधिक दंड","पारस्परिक नियतत्ववाद","स्वतः पुनर्प्राप्ति"],"explanationHi":"पारस्परिक नियतत्ववाद कहता है कि व्यक्तिगत कारक (विश्वास), व्यवहार और पर्यावरण निरंतर एक-दूसरे को प्रभावित करते हैं; यहाँ प्रत्येक दूसरों को एक चक्र में सुदृढ़ करता है।"},
  {"id":"cdp-child-development-408","question":"According to Bandura, which of these are typical of students with high self-efficacy for a task? I. They choose more challenging versions of the task. II. They persist longer after setbacks. III. They tend to attribute failure to insufficient effort or strategy. IV. They avoid the task to protect their image.","options":["I and IV only","II and IV only","I, II and IV only","I, II and III only"],"answer":3,"explanation":"High self-efficacy leads to challenging choices, persistence and effort-based explanations of failure. Avoidance to protect one's image is typical of low self-efficacy.","difficulty":"hard","source":"KVS PRT · Super TET","questionHi":"बंडूरा के अनुसार, किसी कार्य के लिए उच्च आत्म-प्रभावकारिता वाले विद्यार्थियों की विशिष्ट बातें कौन-सी हैं? I. वे कार्य के अधिक चुनौतीपूर्ण रूप चुनते हैं। II. वे असफलताओं के बाद अधिक देर तक डटे रहते हैं। III. वे असफलता का कारण अपर्याप्त प्रयास या युक्ति को मानते हैं। IV. वे अपनी छवि बचाने के लिए कार्य से बचते हैं।","optionsHi":["केवल I और IV","केवल II और IV","केवल I, II और IV","केवल I, II और III"],"explanationHi":"उच्च आत्म-प्रभावकारिता चुनौतीपूर्ण चुनावों, दृढ़ता और असफलता की प्रयास-आधारित व्याख्याओं की ओर ले जाती है। अपनी छवि बचाने के लिए बचना निम्न आत्म-प्रभावकारिता की विशेषता है।"},
  {"id":"cdp-child-development-409","question":"Before her first oral test, Neha notices her heart pounding and concludes, ‘This proves I will fail.’ Her teacher explains that a racing heart is a normal sign of the body getting ready to perform. Which source of self-efficacy is the teacher working on?","options":["Mastery experiences of past success","Physiological and emotional states","Vicarious experience of peers","Social comparison of grades"],"answer":1,"explanation":"Bandura listed four sources: mastery experiences, vicarious experience, verbal persuasion and physiological/emotional states. Reinterpreting bodily arousal works on the last of these.","difficulty":"hard","source":"CTET Paper 2 · NVS TGT","questionHi":"अपने पहले मौखिक परीक्षण से पहले नेहा अपना दिल धड़कता महसूस करती है और निष्कर्ष निकालती है, ‘यह सिद्ध करता है कि मैं असफल होऊँगी।’ उसकी शिक्षिका समझाती हैं कि तेज़ धड़कन शरीर के प्रदर्शन के लिए तैयार होने का सामान्य संकेत है। शिक्षिका आत्म-प्रभावकारिता के किस स्रोत पर काम कर रही हैं?","optionsHi":["पिछली सफलता के निपुणता अनुभव","शारीरिक और भावनात्मक अवस्थाएँ","साथियों का प्रतिनिधिक अनुभव","ग्रेडों की सामाजिक तुलना"],"explanationHi":"बंडूरा ने चार स्रोत गिनाए: निपुणता अनुभव, प्रतिनिधिक अनुभव, शाब्दिक प्रोत्साहन और शारीरिक/भावनात्मक अवस्थाएँ। शारीरिक उत्तेजना की पुनर्व्याख्या अंतिम स्रोत पर काम करती है।"},
  {"id":"cdp-child-development-410","question":"Sana sets herself a goal of solving twenty sums before dinner and lets herself watch her favourite cartoon only after reaching it. In Bandura's theory this is an example of:","options":["Self-reinforcement within self-regulation","Vicarious reinforcement from a peer's success","Negative reinforcement by parents","Law of exercise through repeated sums"],"answer":0,"explanation":"Bandura described self-regulation: learners set standards, monitor themselves and reward themselves on meeting them. No outside agent is reinforcing her.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"सना अपने लिए रात के भोजन से पहले बीस सवाल हल करने का लक्ष्य रखती है और उसे पूरा करने के बाद ही अपना पसंदीदा कार्टून देखने देती है। बंडूरा के सिद्धांत में यह किसका उदाहरण है?","optionsHi":["आत्म-नियमन के भीतर आत्म-पुनर्बलन","साथी की सफलता से प्रतिनिधिक पुनर्बलन","माता-पिता द्वारा ऋणात्मक पुनर्बलन","बार-बार सवाल करने से अभ्यास का नियम"],"explanationHi":"बंडूरा ने आत्म-नियमन का वर्णन किया: अधिगमकर्ता मानक तय करते हैं, स्वयं की निगरानी करते हैं और उन्हें पूरा करने पर स्वयं को पुरस्कृत करते हैं। उसे कोई बाहरी कारक पुनर्बलित नहीं कर रहा।"},
  {"id":"cdp-child-development-411","question":"During a Class 9 test, students see a classmate copying openly without being caught or punished. Copying in the room then increases. According to Bandura, seeing that a forbidden act has no bad consequences produces:","options":["Response facilitation","Stimulus discrimination","A disinhibitory effect","An inhibitory effect"],"answer":2,"explanation":"Observing a model perform a prohibited act without punishment weakens observers' restraint: the disinhibitory effect. Seeing the model punished would produce an inhibitory effect.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"कक्षा 9 की परीक्षा के दौरान विद्यार्थी देखते हैं कि एक सहपाठी बिना पकड़े या दंडित हुए खुलेआम नकल कर रहा है। फिर कमरे में नकल बढ़ जाती है। बंडूरा के अनुसार, यह देखना कि किसी निषिद्ध कार्य का कोई बुरा परिणाम नहीं होता, क्या पैदा करता है?","optionsHi":["अनुक्रिया सुगमीकरण","उद्दीपक विभेदन","निषेध-मुक्ति प्रभाव (डिसइन्हिबिटरी इफ़ेक्ट)","निषेधात्मक प्रभाव (इन्हिबिटरी इफ़ेक्ट)"],"explanationHi":"किसी आदर्श को बिना दंड के निषिद्ध कार्य करते देखना प्रेक्षकों के संयम को कमज़ोर करता है: निषेध-मुक्ति प्रभाव। आदर्श को दंडित होते देखना निषेधात्मक प्रभाव पैदा करता।"},
  {"id":"cdp-child-development-412","question":"Assertion (A): Bandura's social learning theory is often described as a bridge between behaviourism and cognitive psychology. Reason (R): It gives a central place to mental processes such as attention and retention while still accepting that consequences influence behaviour.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Bandura kept reinforcement (from behaviourism) but added cognition: attention, retention, expectations and self-efficacy. That combination is why the theory is called a bridge, so R explains A.","difficulty":"hard","source":"CTET · HTET","questionHi":"अभिकथन (A): बंडूरा के सामाजिक अधिगम सिद्धांत को प्रायः व्यवहारवाद और संज्ञानात्मक मनोविज्ञान के बीच एक सेतु बताया जाता है। कारण (R): यह ध्यान और धारण जैसी मानसिक प्रक्रियाओं को केंद्रीय स्थान देता है, जबकि यह भी स्वीकार करता है कि परिणाम व्यवहार को प्रभावित करते हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"बंडूरा ने पुनर्बलन (व्यवहारवाद से) रखा पर संज्ञान जोड़ा: ध्यान, धारण, अपेक्षाएँ और आत्म-प्रभावकारिता। यही संयोजन सिद्धांत को सेतु कहलाने का कारण है, इसलिए R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-413","question":"A Class 7 teacher wants students to learn how to approach word problems. Which form of modelling suits social cognitive theory best?","options":["Solving a problem silently on the board and asking students to copy each step","Giving a list of rules for word problems for students to memorise at home","Showing only the final answers so that students can check their own work","Solving a problem while thinking aloud about what to look for, try and check"],"answer":3,"explanation":"Cognitive modelling (thinking aloud) makes the model's invisible thinking observable, so learners can attend to and retain the strategy, not just the final steps.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 का एक शिक्षक चाहता है कि विद्यार्थी शब्द-समस्याओं से निपटना सीखें। सामाजिक संज्ञानात्मक सिद्धांत के लिए आदर्श-प्रस्तुति का कौन-सा रूप सबसे उपयुक्त है?","optionsHi":["बोर्ड पर चुपचाप समस्या हल करना और विद्यार्थियों से हर चरण की नकल करने को कहना","शब्द-समस्याओं के नियमों की सूची देना जिसे विद्यार्थी घर पर याद करें","केवल अंतिम उत्तर दिखाना ताकि विद्यार्थी अपना कार्य स्वयं जाँचें","समस्या हल करते हुए ज़ोर से सोचना कि क्या देखना है, क्या आज़माना है और क्या जाँचना है"],"explanationHi":"संज्ञानात्मक आदर्श-प्रस्तुति (ज़ोर से सोचना) आदर्श के अदृश्य चिंतन को दृश्यमान बनाती है, ताकि अधिगमकर्ता केवल अंतिम चरणों पर नहीं बल्कि युक्ति पर ध्यान दे सकें और उसे याद रख सकें।"},
  {"id":"cdp-child-development-414","question":"A teacher loses her temper and shouts, ‘Stop shouting at each other!’ at a noisy Class 4. Social learning theory would predict that, over time, this habit is most likely to:","options":["Reduce shouting because children are punished for it","Teach children that shouting is a way to control others","Have no effect because children imitate only peers","Weaken the teacher's authority but not affect the children's behaviour"],"answer":1,"explanation":"Children learn from what adults do, not only from what they say. The teacher is modelling shouting as an effective means of control, which children may later imitate.","difficulty":"moderate","source":"CTET Paper 1 · UPTET","questionHi":"एक शिक्षिका आपा खो देती है और कक्षा 4 के शोर मचाते बच्चों पर चिल्लाती है, ‘एक-दूसरे पर चिल्लाना बंद करो!’ सामाजिक अधिगम सिद्धांत भविष्यवाणी करेगा कि समय के साथ यह आदत सबसे अधिक संभावना से:","optionsHi":["चिल्लाना घटाएगी क्योंकि बच्चों को उसके लिए दंडित किया जाता है","बच्चों को सिखाएगी कि चिल्लाना दूसरों को नियंत्रित करने का तरीका है","कोई प्रभाव नहीं डालेगी क्योंकि बच्चे केवल साथियों की नकल करते हैं","शिक्षिका का अधिकार कमज़ोर करेगी पर बच्चों के व्यवहार को प्रभावित नहीं करेगी"],"explanationHi":"बच्चे वयस्कों के कार्यों से सीखते हैं, केवल उनके कथनों से नहीं। शिक्षिका चिल्लाने को नियंत्रण के प्रभावी साधन के रूप में आदर्श-प्रस्तुत कर रही है, जिसकी बच्चे बाद में नकल कर सकते हैं।"},
  {"id":"cdp-child-development-415","question":"Which of the following is NOT a characteristic of insight learning as described by Gestalt psychologists?","options":["The solution appears suddenly after a period of exploration","The solution can be transferred to similar new problems","Errors fall gradually through many blind, random trials","The solution, once found, is retained well"],"answer":2,"explanation":"Insight is sudden, transferable and durable, and rests on perceiving relationships. Gradual reduction of errors through blind trials describes Thorndike's trial-and-error learning.","difficulty":"moderate","source":"CTET · REET","questionHi":"निम्नलिखित में से कौन-सी गेस्टाल्ट मनोवैज्ञानिकों द्वारा वर्णित अंतर्दृष्टि अधिगम की विशेषता नहीं है?","optionsHi":["खोजबीन की अवधि के बाद समाधान अचानक प्रकट होता है","समाधान को समान नई समस्याओं पर अंतरित किया जा सकता है","त्रुटियाँ अनेक अंधे, यादृच्छिक प्रयासों से धीरे-धीरे घटती हैं","समाधान, एक बार मिल जाने पर, अच्छी तरह धारण होता है"],"explanationHi":"अंतर्दृष्टि अचानक, अंतरणीय और टिकाऊ होती है, और संबंधों के प्रत्यक्षण पर आधारित होती है। अंधे प्रयासों से त्रुटियों का धीरे-धीरे घटना थॉर्नडाइक के प्रयास और त्रुटि अधिगम का वर्णन है।"},
  {"id":"cdp-child-development-416","question":"Kavya, in Class 6, stares at an L-shaped figure whose area she must find. Suddenly she sees that it can be split into two rectangles, solves it, and then at once applies the same idea to other irregular shapes. This is best described as:","options":["Trial-and-error learning with many shapes","Classical conditioning to the L-shape","Rote memorisation of an area formula","Insight through restructuring of the figure"],"answer":3,"explanation":"Kavya reorganised how she saw the figure, grasped the relationship, and transferred it immediately, which are hallmarks of Gestalt insight learning.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 6 की काव्या एक L-आकार की आकृति को घूर रही है जिसका क्षेत्रफल उसे निकालना है। अचानक उसे दिखता है कि उसे दो आयतों में बाँटा जा सकता है, वह हल कर लेती है, और फिर तुरंत वही विचार अन्य अनियमित आकृतियों पर लागू करती है। इसका सबसे अच्छा वर्णन है:","optionsHi":["अनेक आकृतियों के साथ प्रयास और त्रुटि अधिगम","L-आकार के प्रति शास्त्रीय अनुबंधन","क्षेत्रफल के सूत्र का रटा हुआ स्मरण","आकृति के पुनर्गठन द्वारा अंतर्दृष्टि"],"explanationHi":"काव्या ने आकृति को देखने का ढंग पुनर्गठित किया, संबंध को समझा, और उसे तुरंत अंतरित किया, जो गेस्टाल्ट अंतर्दृष्टि अधिगम की पहचान हैं।"},
  {"id":"cdp-child-development-417","question":"Köhler observed that his chimpanzees solved the banana problem far more readily when the stick and the banana were in view together than when the stick lay behind them. What does this imply for setting problems for children?","options":["All parts of a solution should be in the learner's view so relations can be seen","Problems should be hidden so that children learn by random trials and errors","Children should be rewarded for every incorrect attempt so that they keep trying","The teacher should give the solution first and the problem later, to save time"],"answer":0,"explanation":"Insight depends on perceiving relationships among parts of the situation; when the parts are visible together, restructuring is far easier. Hidden elements push the learner toward blind trial and error.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"कोहलर ने देखा कि उनके चिंपैंजी केले की समस्या तब कहीं अधिक आसानी से हल करते थे जब डंडा और केला एक साथ दृष्टि में हों, बनिस्बत जब डंडा उनके पीछे पड़ा हो। बच्चों के लिए समस्याएँ रखने के संबंध में इसका क्या निहितार्थ है?","optionsHi":["समाधान के सभी भाग अधिगमकर्ता की दृष्टि में होने चाहिए ताकि संबंध दिख सकें","समस्याएँ छिपाई जानी चाहिए ताकि बच्चे यादृच्छिक प्रयासों और त्रुटियों से सीखें","बच्चों को हर गलत प्रयास पर पुरस्कृत किया जाना चाहिए ताकि वे प्रयास करते रहें","शिक्षक को समय बचाने के लिए पहले समाधान और बाद में समस्या देनी चाहिए"],"explanationHi":"अंतर्दृष्टि स्थिति के भागों के बीच संबंधों के प्रत्यक्षण पर निर्भर करती है; जब भाग एक साथ दिखाई देते हैं, तो पुनर्गठन कहीं आसान होता है। छिपे तत्व अधिगमकर्ता को अंधे प्रयास और त्रुटि की ओर धकेलते हैं।"},
  {"id":"cdp-child-development-418","question":"A teacher writes the causes of the 1857 revolt in one tight cluster on the left of the board and the consequences in a separate cluster on the right, with clear space in between. Students immediately see two groups. Which Gestalt law is she using?","options":["Similarity","Closure","Proximity","Figure and ground"],"answer":2,"explanation":"Items placed close together are perceived as a group: the law of proximity. Similarity would need shared features such as the same colour or shape.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षिका 1857 के विद्रोह के कारणों को बोर्ड के बाईं ओर एक सघन समूह में और परिणामों को दाईं ओर एक अलग समूह में लिखती है, बीच में स्पष्ट जगह छोड़कर। विद्यार्थी तुरंत दो समूह देख लेते हैं। वह गेस्टाल्ट के किस नियम का उपयोग कर रही है?","optionsHi":["समानता","समापन","समीपता","आकृति और पृष्ठभूमि"],"explanationHi":"पास-पास रखी चीज़ें एक समूह के रूप में प्रत्यक्षित की जाती हैं: समीपता का नियम। समानता के लिए एक जैसा रंग या आकार जैसी साझा विशेषताएँ चाहिए।"},
  {"id":"cdp-child-development-419","question":"Match each Gestalt principle with the classroom practice that uses it. P. Similarity  Q. Closure  R. Figure–ground  S. Proximity. 1. Writing all verbs in a passage in green so they are seen as one class 2. Placing the key formula alone on a plain chart so it stands out 3. Leaving a diagram partly drawn so pupils mentally complete it 4. Seating each group's materials together on one table","options":["P-1, Q-3, R-2, S-4","P-1, Q-2, R-3, S-4","P-4, Q-3, R-2, S-1","P-3, Q-1, R-2, S-4"],"answer":0,"explanation":"Same colour groups by similarity; completing an incomplete figure is closure; making one item stand out from a plain background is figure–ground; physical nearness is proximity.","difficulty":"very-hard","source":"CTET · Super TET","questionHi":"प्रत्येक गेस्टाल्ट सिद्धांत का मिलान उस कक्षा-पद्धति से कीजिए जो उसका उपयोग करती है। P. समानता Q. समापन R. आकृति–पृष्ठभूमि S. समीपता। 1. किसी गद्यांश की सभी क्रियाओं को हरे रंग में लिखना ताकि वे एक वर्ग के रूप में दिखें 2. मुख्य सूत्र को सादे चार्ट पर अकेले रखना ताकि वह उभरे 3. किसी आरेख को आंशिक रूप से बना छोड़ देना ताकि विद्यार्थी उसे मन में पूरा करें 4. हर समूह की सामग्री को एक मेज़ पर साथ-साथ रखना","optionsHi":["P-1, Q-3, R-2, S-4","P-1, Q-2, R-3, S-4","P-4, Q-3, R-2, S-1","P-3, Q-1, R-2, S-4"],"explanationHi":"एक ही रंग समानता से समूहित करता है; अधूरी आकृति को पूरा करना समापन है; किसी एक वस्तु को सादी पृष्ठभूमि से उभारना आकृति–पृष्ठभूमि है; भौतिक निकटता समीपता है।"},
  {"id":"cdp-child-development-420","question":"A Class 5 teacher introducing a new poem first reads the entire poem aloud with expression and discusses its overall mood before taking up difficult words line by line. Which school of thought most directly supports this approach?","options":["Pavlov's classical conditioning","Gestalt psychology","Skinner's operant conditioning","Thorndike's connectionism"],"answer":1,"explanation":"Gestalt psychology stresses that the whole is more than the sum of its parts and is perceived first, so meaning is built by moving from the whole to the parts.","difficulty":"moderate","source":"CTET Paper 1 · REET","questionHi":"कक्षा 5 की एक शिक्षिका नई कविता का परिचय देते समय पहले पूरी कविता को भावपूर्ण ढंग से ज़ोर से पढ़ती है और उसके समग्र भाव पर चर्चा करती है, फिर कठिन शब्दों को पंक्ति-दर-पंक्ति लेती है। कौन-सा विचार-संप्रदाय इस उपागम का सबसे सीधे समर्थन करता है?","optionsHi":["पावलोव का शास्त्रीय अनुबंधन","गेस्टाल्ट मनोविज्ञान","स्किनर का क्रियाप्रसूत अनुबंधन","थॉर्नडाइक का संबंधवाद"],"explanationHi":"गेस्टाल्ट मनोविज्ञान बल देता है कि पूर्ण अपने भागों के योग से अधिक है और पहले प्रत्यक्षित होता है, इसलिए अर्थ का निर्माण पूर्ण से भागों की ओर बढ़ने से होता है।"},
  {"id":"cdp-child-development-421","question":"Köhler trained hens to peck grain from the darker of two grey papers. When then shown that same darker paper beside an even darker one, most hens pecked at the new, darker paper. What does this show?","options":["The hens had learnt a response to a particular absolute shade of grey","The hens had forgotten their training once a new paper appeared","The hens had learnt a relationship (‘the darker one’), not a specific shade","The hens were responding by chance, as birds cannot compare shades"],"answer":2,"explanation":"Transposition shows that the learner responds to the relationship between stimuli, a Gestalt argument against purely stimulus–response explanations based on absolute features.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"कोहलर ने मुर्गियों को दो स्लेटी कागज़ों में से गहरे वाले से दाना चुगने का प्रशिक्षण दिया। फिर जब वही गहरा कागज़ एक और भी गहरे कागज़ के बगल में दिखाया गया, तो अधिकांश मुर्गियों ने नए, और अधिक गहरे कागज़ पर चोंच मारी। यह क्या दर्शाता है?","optionsHi":["मुर्गियों ने स्लेटी रंग की किसी विशेष निरपेक्ष छाया के प्रति अनुक्रिया सीखी थी","नया कागज़ दिखते ही मुर्गियाँ अपना प्रशिक्षण भूल गईं","मुर्गियों ने एक संबंध (‘गहरे वाला’) सीखा था, किसी विशेष छाया को नहीं","मुर्गियाँ संयोगवश अनुक्रिया कर रही थीं, क्योंकि पक्षी छायाओं की तुलना नहीं कर सकते"],"explanationHi":"स्थानांतरण (ट्रांसपोज़िशन) दर्शाता है कि अधिगमकर्ता उद्दीपकों के बीच के संबंध पर अनुक्रिया करता है, जो निरपेक्ष विशेषताओं पर आधारित विशुद्ध उद्दीपक–अनुक्रिया व्याख्याओं के विरुद्ध गेस्टाल्ट का तर्क है।"},
  {"id":"cdp-child-development-422","question":"A wall chart on the water cycle is crowded with bright cartoons, borders and decorations, and most Class 4 children cannot find the main diagram. In Gestalt terms the chart fails mainly because of poor:","options":["Law of exercise and repetition","Insight","Closure","Figure–ground separation"],"answer":3,"explanation":"The key content (figure) must stand out from the background. Clutter makes the background compete with the figure, so the main diagram does not emerge.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"जलचक्र का एक दीवार चार्ट चमकीले कार्टूनों, किनारों और सजावटों से ठसाठस भरा है, और कक्षा 4 के अधिकांश बच्चे मुख्य आरेख नहीं ढूँढ पाते। गेस्टाल्ट की दृष्टि से चार्ट मुख्यतः किसकी कमी के कारण विफल है?","optionsHi":["अभ्यास और पुनरावृत्ति का नियम","अंतर्दृष्टि","समापन","आकृति–पृष्ठभूमि पृथक्करण"],"explanationHi":"मुख्य विषयवस्तु (आकृति) पृष्ठभूमि से उभरनी चाहिए। अव्यवस्था पृष्ठभूमि को आकृति से होड़ करवाती है, इसलिए मुख्य आरेख उभरकर नहीं आता।"},
  {"id":"cdp-child-development-423","question":"Which pairing of an explanation of learning with its typical evidence is INCORRECT?","options":["Trial and error – gradual, irregular fall in time taken across many trials","Insight – sudden solution that transfers to related problems","Classical conditioning – a voluntary response increased by consequences","Observational learning – new behaviour acquired by watching a model"],"answer":2,"explanation":"Voluntary behaviour strengthened by its consequences is operant conditioning. Classical conditioning pairs stimuli to evoke largely involuntary responses.","difficulty":"hard","source":"CTET · HTET","questionHi":"अधिगम की व्याख्या और उसके विशिष्ट साक्ष्य की कौन-सी जोड़ी गलत है?","optionsHi":["प्रयास और त्रुटि – अनेक प्रयासों में लगे समय में धीमी, अनियमित गिरावट","अंतर्दृष्टि – अचानक समाधान जो संबंधित समस्याओं पर अंतरित होता है","शास्त्रीय अनुबंधन – ऐच्छिक अनुक्रिया जिसे परिणामों से बढ़ाया जाता है","अवलोकनात्मक अधिगम – किसी आदर्श को देखकर अर्जित नया व्यवहार"],"explanationHi":"परिणामों से सुदृढ़ होने वाला ऐच्छिक व्यवहार क्रियाप्रसूत अनुबंधन है। शास्त्रीय अनुबंधन उद्दीपकों को जोड़कर मुख्यतः अनैच्छिक अनुक्रियाएँ उत्पन्न करता है।"},
  {"id":"cdp-child-development-424","question":"Assertion (A): Gestalt psychologists argued that breaking learning into isolated stimulus–response bonds misses how learners understand. Reason (R): For them, perception and learning are organised into meaningful wholes, and the whole has properties that its separate parts lack.","options":["A is false but R is true","A is true but R is false","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"Because Gestaltists held that the organised whole has its own properties, they rejected atomistic S–R explanations; R gives the reason for A.","difficulty":"hard","source":"CTET Paper 2 · UPTET","questionHi":"अभिकथन (A): गेस्टाल्ट मनोवैज्ञानिकों का तर्क था कि अधिगम को अलग-थलग उद्दीपक–अनुक्रिया बंधनों में तोड़ना यह चूक जाता है कि अधिगमकर्ता कैसे समझते हैं। कारण (R): उनके लिए प्रत्यक्षण और अधिगम सार्थक पूर्णों में संगठित होते हैं, और पूर्ण में ऐसे गुण होते हैं जो उसके अलग-अलग भागों में नहीं होते।","optionsHi":["A असत्य है परंतु R सत्य है","A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है"],"explanationHi":"चूँकि गेस्टाल्टवादियों का मत था कि संगठित पूर्ण के अपने गुण होते हैं, उन्होंने परमाणुवादी S–R व्याख्याओं को अस्वीकार किया; R, A का कारण देता है।"},
  {"id":"cdp-child-development-425","question":"Ms Rao notices that her Class 3 children start yawning and looking out of the window whenever one child does it first, even though no one is rewarded or punished. Bandura would classify this as:","options":["Response facilitation: a model prompts an already-known behaviour","Observational learning of an entirely new skill from a peer","A disinhibitory effect, as an unpunished prohibited act is copied","Higher-order conditioning"],"answer":0,"explanation":"Response facilitation occurs when a model's actions cue observers to perform behaviours they already know and that are not prohibited. Nothing new is learnt and no restraint is lifted.","difficulty":"very-hard","source":"KVS PRT · DSSSB PRT","questionHi":"सुश्री राव देखती हैं कि जब कोई एक बच्चा पहले जम्हाई लेता और खिड़की से बाहर देखता है तो कक्षा 3 के बच्चे भी जम्हाई लेने और बाहर देखने लगते हैं, जबकि किसी को पुरस्कृत या दंडित नहीं किया गया। बंडूरा इसे किस रूप में वर्गीकृत करते?","optionsHi":["अनुक्रिया सुगमीकरण: कोई आदर्श पहले से ज्ञात व्यवहार को प्रेरित करता है","किसी साथी से बिल्कुल नए कौशल का अवलोकनात्मक अधिगम","निषेध-मुक्ति प्रभाव, क्योंकि बिना दंड वाला निषिद्ध कार्य दोहराया जाता है","उच्च-क्रम अनुबंधन"],"explanationHi":"अनुक्रिया सुगमीकरण तब होता है जब किसी आदर्श के कार्य प्रेक्षकों को वे व्यवहार करने का संकेत देते हैं जो वे पहले से जानते हैं और जो निषिद्ध नहीं हैं। कुछ नया नहीं सीखा गया और कोई संयम नहीं हटा।"},
  {"id":"cdp-child-development-426","question":"A Class 1 teacher in Delhi says that children from a nearby settlement ‘come to school with no language at all’ because at home they speak a mix of Bhojpuri and Hindi. Which response is most in line with NCF 2005?","options":["She is right; such children must first be taught ‘proper’ Hindi before any other learning can begin","The children bring a full, rule-governed home language to use as a resource for school learning","Mixing languages shows confusion, so the children should be asked to speak only one language in school","The children should be referred for a language-delay assessment before formal teaching"],"answer":1,"explanation":"Every child entering school already has a rich, rule-governed language; NCF 2005 asks teachers to treat home languages and multilingualism as a resource. Calling a dialect or a language mix ‘no language’ is a deficit view.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"दिल्ली में कक्षा 1 की एक शिक्षिका कहती है कि पास की बस्ती के बच्चे ‘बिल्कुल बिना भाषा के स्कूल आते हैं’ क्योंकि घर पर वे भोजपुरी और हिंदी का मिश्रण बोलते हैं। NCF 2005 के सबसे अनुरूप प्रतिक्रिया कौन-सी है?","optionsHi":["वह सही है; ऐसे बच्चों को कोई और सीखना शुरू होने से पहले ‘सही’ हिंदी सिखाई जानी चाहिए","बच्चे अपने साथ एक पूर्ण, नियम-शासित घर की भाषा लाते हैं जिसे विद्यालयी अधिगम के लिए संसाधन के रूप में प्रयोग किया जा सकता है","भाषाओं का मिश्रण भ्रम दर्शाता है, इसलिए बच्चों से विद्यालय में केवल एक भाषा बोलने को कहा जाना चाहिए","औपचारिक शिक्षण से पहले बच्चों को भाषा-विलंब आकलन के लिए संदर्भित किया जाना चाहिए"],"explanationHi":"विद्यालय में प्रवेश करने वाले हर बच्चे के पास पहले से एक समृद्ध, नियम-शासित भाषा होती है; NCF 2005 शिक्षकों से घर की भाषाओं और बहुभाषिकता को संसाधन मानने को कहती है। बोली या भाषा-मिश्रण को ‘कोई भाषा नहीं’ कहना कमी का दृष्टिकोण है।"},
  {"id":"cdp-child-development-427","question":"Which of the following statements reflect the position of NCF 2005 on multilingualism? I. Multilingualism is a resource for the classroom. II. Research links bilingualism with cognitive flexibility and school achievement. III. A child’s home language should be dropped as early as possible so that the school language is learned faster. IV. Teachers may draw on several languages in the classroom to help children understand concepts.","options":["I, II and IV only","I and III only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"NCF 2005 calls multilingualism a resource, cites research linking bilingualism with cognitive flexibility and achievement, and supports using home languages; dropping the home language early (III) contradicts it.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"बहुभाषिकता पर NCF 2005 की स्थिति को इनमें से कौन-से कथन दर्शाते हैं? I. बहुभाषिकता कक्षा के लिए एक संसाधन है। II. शोध द्विभाषिकता को संज्ञानात्मक लचीलेपन और विद्यालयी उपलब्धि से जोड़ता है। III. बच्चे की घर की भाषा को यथाशीघ्र छोड़ देना चाहिए ताकि विद्यालय की भाषा जल्दी सीखी जा सके। IV. शिक्षक अवधारणाओं को समझने में बच्चों की मदद के लिए कक्षा में कई भाषाओं का उपयोग कर सकते हैं।","optionsHi":["केवल I, II और IV","केवल I और III","केवल II, III और IV","I, II, III और IV"],"explanationHi":"NCF 2005 बहुभाषिकता को संसाधन कहती है, द्विभाषिकता को संज्ञानात्मक लचीलेपन और उपलब्धि से जोड़ने वाले शोध का हवाला देती है, और घर की भाषाओं के उपयोग का समर्थन करती है; घर की भाषा को जल्दी छोड़ना (III) इसके विपरीत है।"},
  {"id":"cdp-child-development-428","question":"At the start of the session, a researcher tells a Class 3 teacher in Nagpur that five named children are ‘late bloomers’ who will show great progress this year; in fact the names were picked at random. By the year’s end these five have gained more than their classmates. This outcome illustrates:","options":["The halo effect in marking these five children","The Hawthorne effect of being studied","Regression towards the mean in their scores","A self-fulfilling prophecy of teacher expectations"],"answer":3,"explanation":"This is the design of Rosenthal and Jacobson’s ‘Pygmalion in the Classroom’ study: raised teacher expectations changed how the teacher treated the children, which in turn raised their performance.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"सत्र की शुरुआत में एक शोधकर्ता नागपुर में कक्षा 3 की एक शिक्षिका को बताता है कि पाँच नामित बच्चे ‘देर से खिलने वाले’ हैं जो इस वर्ष बड़ी प्रगति दिखाएँगे; वास्तव में नाम यादृच्छिक रूप से चुने गए थे। वर्ष के अंत तक इन पाँचों ने अपने सहपाठियों से अधिक प्रगति की। यह परिणाम क्या दर्शाता है?","optionsHi":["इन पाँच बच्चों के अंकन में प्रभामंडल प्रभाव","अध्ययन किए जाने का हॉथॉर्न प्रभाव","उनके अंकों में माध्य की ओर प्रतिगमन","शिक्षक की अपेक्षाओं की स्वयं-पूर्ति भविष्यवाणी"],"explanationHi":"यह रोज़ेंथल और जैकबसन के ‘पिग्मैलियन इन द क्लासरूम’ अध्ययन की रचना है: बढ़ी हुई शिक्षक अपेक्षाओं ने शिक्षिका के बच्चों के साथ व्यवहार को बदला, जिसने बदले में उनका प्रदर्शन बढ़ाया।"},
  {"id":"cdp-child-development-429","question":"Two equally able groups of Class 9 girls take the same mathematics test. One group is told, ‘This test usually shows that boys do better than girls’; the other is told the test is gender-neutral. The first group scores noticeably lower. This is best explained by:","options":["Stereotype threat","The Flynn effect","Gender constancy","Test–retest unreliability"],"answer":0,"explanation":"Stereotype threat is the anxiety of possibly confirming a negative stereotype about one’s group, which can lower performance on the very task the stereotype concerns, even when ability is the same.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"कक्षा 9 की लड़कियों के दो समान रूप से सक्षम समूह एक ही गणित परीक्षा देते हैं। एक समूह से कहा जाता है, ‘यह परीक्षा प्रायः दिखाती है कि लड़के लड़कियों से बेहतर करते हैं’; दूसरे से कहा जाता है कि परीक्षा लिंग-तटस्थ है। पहला समूह उल्लेखनीय रूप से कम अंक पाता है। इसे सबसे अच्छी तरह क्या समझाता है?","optionsHi":["रूढ़ि-खतरा (स्टीरियोटाइप थ्रेट)","फ्लिन प्रभाव","लिंग-स्थिरता (जेंडर कॉन्स्टेंसी)","परीक्षण–पुनःपरीक्षण अविश्वसनीयता"],"explanationHi":"रूढ़ि-खतरा अपने समूह के बारे में किसी नकारात्मक रूढ़ि की पुष्टि हो जाने की चिंता है, जो ठीक उसी कार्य पर प्रदर्शन घटा सकती है जिससे रूढ़ि संबंधित है, भले ही योग्यता समान हो।"},
  {"id":"cdp-child-development-430","question":"Assertion (A): Labelling a child as a ‘slow learner’ in Class 2 can lower her achievement in later years. Reason (R): Labels shape the teacher’s expectations and the child’s own self-concept, and both affect future learning.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Labels tend to be self-fulfilling: teachers give labelled children fewer challenges and less wait time, and the children come to see themselves as incapable, which depresses later achievement.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"अभिकथन (A): कक्षा 2 में किसी बच्ची को ‘मंद अधिगमकर्ता’ का लेबल देना बाद के वर्षों में उसकी उपलब्धि घटा सकता है। कारण (R): लेबल शिक्षक की अपेक्षाओं और बच्ची की अपनी आत्म-अवधारणा को आकार देते हैं, और दोनों भविष्य के अधिगम को प्रभावित करते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"लेबल स्वयं-पूर्ति करने वाले होते हैं: शिक्षक लेबल वाले बच्चों को कम चुनौतियाँ और कम प्रतीक्षा-समय देते हैं, और बच्चे स्वयं को अक्षम मानने लगते हैं, जो बाद की उपलब्धि को घटाता है।"},
  {"id":"cdp-child-development-431","question":"An intelligence test used in a rural block of Odisha includes picture items asking children to name an escalator, a lift button and a parking meter. Many children score low on these items. The most valid conclusion is that:","options":["The children have lower general intelligence than children from urban areas","The children have weak visual memory for pictured objects","The items carry cultural bias, measuring familiarity with urban objects","The test is valid because it measures what children ought to know"],"answer":2,"explanation":"Items that depend on experiences common in one group but rare in another measure exposure, not intelligence; low scores here reflect cultural bias in the test content.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"ओडिशा के एक ग्रामीण ब्लॉक में प्रयुक्त बुद्धि परीक्षण में चित्र-पद शामिल हैं जिनमें बच्चों से एस्केलेटर, लिफ्ट का बटन और पार्किंग मीटर का नाम बताने को कहा जाता है। कई बच्चे इन पदों पर कम अंक पाते हैं। सबसे वैध निष्कर्ष क्या है?","optionsHi":["बच्चों की सामान्य बुद्धि शहरी क्षेत्रों के बच्चों से कम है","बच्चों की चित्रित वस्तुओं के लिए दृश्य स्मृति कमज़ोर है","पदों में सांस्कृतिक पक्षपात है, जो शहरी वस्तुओं से परिचय को मापता है","परीक्षण वैध है क्योंकि वह मापता है कि बच्चों को क्या जानना चाहिए"],"explanationHi":"जो पद एक समूह में आम पर दूसरे में दुर्लभ अनुभवों पर निर्भर करते हैं, वे बुद्धि नहीं बल्कि संपर्क को मापते हैं; यहाँ कम अंक परीक्षण की विषयवस्तु में सांस्कृतिक पक्षपात को दर्शाते हैं।"},
  {"id":"cdp-child-development-432","question":"Which of these statements about ‘culture-fair’ intelligence tests such as Raven’s Progressive Matrices are correct? I. They reduce dependence on language and specific school knowledge. II. They use mainly non-verbal items such as patterns and figures. III. They are completely free of cultural influence. IV. Familiarity with test-taking and abstract patterns can still affect scores.","options":["I and III only","I, II and IV only","II and III only","I, II, III and IV"],"answer":1,"explanation":"Non-verbal tests reduce, but cannot remove, cultural influence: schooling and familiarity with abstract figures and timed tests still matter, so no test is truly ‘culture-free’ (statement III is false).","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"रेवेन की प्रोग्रेसिव मैट्रिसेस जैसे ‘संस्कृति-निरपेक्ष’ बुद्धि परीक्षणों के बारे में इनमें से कौन-से कथन सही हैं? I. वे भाषा और विशिष्ट विद्यालयी ज्ञान पर निर्भरता घटाते हैं। II. वे मुख्यतः प्रतिरूप और आकृतियों जैसे अशाब्दिक पदों का उपयोग करते हैं। III. वे सांस्कृतिक प्रभाव से पूरी तरह मुक्त हैं। IV. परीक्षा देने का अभ्यास और अमूर्त प्रतिरूपों से परिचय अब भी अंकों को प्रभावित कर सकते हैं।","optionsHi":["केवल I और III","केवल I, II और IV","केवल II और III","I, II, III और IV"],"explanationHi":"अशाब्दिक परीक्षण सांस्कृतिक प्रभाव को घटाते हैं, पर हटा नहीं सकते: विद्यालयी शिक्षा तथा अमूर्त आकृतियों और समयबद्ध परीक्षणों से परिचय अब भी मायने रखता है, इसलिए कोई परीक्षण वास्तव में ‘संस्कृति-मुक्त’ नहीं है (कथन III गलत है)।"},
  {"id":"cdp-child-development-433","question":"A textbook states that ‘the heritability of IQ in a certain population is about 0.5’. Which interpretation is correct?","options":["Half of each child’s IQ points come from genes and half from the environment","Any IQ difference between two different populations is half genetic in origin","IQ cannot be changed by more than 50% through education, however good it is","About half the variation in IQ within that population is linked to genetic differences"],"answer":3,"explanation":"Heritability describes the share of variation within a particular population linked to genetic variation; it says nothing about an individual’s IQ, does not fix the limits of change, and cannot be applied to differences between groups.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"एक पाठ्यपुस्तक कहती है कि ‘किसी विशेष जनसंख्या में IQ की आनुवंशिकता लगभग 0.5 है’। कौन-सी व्याख्या सही है?","optionsHi":["प्रत्येक बच्चे के IQ अंकों का आधा जीन से और आधा पर्यावरण से आता है","दो अलग-अलग जनसंख्याओं के बीच IQ का कोई भी अंतर आधा आनुवंशिक मूल का होता है","शिक्षा चाहे जितनी अच्छी हो, IQ को 50% से अधिक नहीं बदला जा सकता","उस जनसंख्या के भीतर IQ की लगभग आधी विविधता आनुवंशिक अंतरों से जुड़ी है"],"explanationHi":"आनुवंशिकता किसी विशेष जनसंख्या के भीतर उस विविधता का अंश बताती है जो आनुवंशिक विविधता से जुड़ा है; वह किसी व्यक्ति के IQ के बारे में कुछ नहीं कहती, परिवर्तन की सीमाएँ तय नहीं करती, और समूहों के बीच अंतरों पर लागू नहीं की जा सकती।"},
  {"id":"cdp-child-development-434","question":"Which teacher remark reflects ‘deficit thinking’ about children from low-income families?","options":["‘Munna works in the fields after school, so I give him class time to finish practice work.’","‘Children from that basti have no interest in studies; expecting much from them is pointless.’","‘Many of my students know a lot about crops and markets; I use that in my maths lessons.’","‘Some students have no books at home, so I keep a class library they can borrow from.’"],"answer":1,"explanation":"Deficit thinking blames the child’s home and community and lowers expectations. The other remarks recognise constraints or draw on children’s real knowledge while keeping expectations high.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"कौन-सी शिक्षक-टिप्पणी निम्न-आय परिवारों के बच्चों के बारे में ‘कमी-आधारित चिंतन’ को दर्शाती है?","optionsHi":["‘मुन्ना स्कूल के बाद खेतों में काम करता है, इसलिए मैं उसे अभ्यास कार्य पूरा करने के लिए कक्षा का समय देती हूँ।’","‘उस बस्ती के बच्चों की पढ़ाई में कोई रुचि नहीं होती; उनसे अधिक अपेक्षा करना व्यर्थ है।’","‘मेरे कई विद्यार्थी फसलों और बाज़ारों के बारे में बहुत जानते हैं; मैं उसका उपयोग अपने गणित के पाठों में करती हूँ।’","‘कुछ विद्यार्थियों के घर पर किताबें नहीं हैं, इसलिए मैं एक कक्षा पुस्तकालय रखती हूँ जिससे वे उधार ले सकें।’"],"explanationHi":"कमी-आधारित चिंतन बच्चे के घर और समुदाय को दोष देता है और अपेक्षाएँ घटाता है। अन्य टिप्पणियाँ सीमाओं को पहचानती हैं या अपेक्षाएँ ऊँची रखते हुए बच्चों के वास्तविक ज्ञान का उपयोग करती हैं।"},
  {"id":"cdp-child-development-435","question":"In a Mumbai school, children whose parents read English newspapers, take them to museums and talk at home in the style used by teachers seem to ‘fit’ school more easily and are often judged more able. The sociologist Pierre Bourdieu’s term for the advantage these children carry is:","options":["Emotional capital","Crystallised intelligence","Cultural capital","Social learning"],"answer":2,"explanation":"Cultural capital is familiarity with the dominant culture’s language, tastes and knowledge, which schools tend to reward as if it were natural ability, reproducing social inequality.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"मुंबई के एक विद्यालय में, जिन बच्चों के माता-पिता अंग्रेजी अखबार पढ़ते हैं, उन्हें संग्रहालय ले जाते हैं और घर पर शिक्षकों जैसी शैली में बात करते हैं, वे विद्यालय में अधिक आसानी से ‘फिट’ होते दिखते हैं और प्रायः अधिक सक्षम माने जाते हैं। इन बच्चों के पास जो लाभ है, उसके लिए समाजशास्त्री पियरे बॉर्दियो का पद क्या है?","optionsHi":["भावनात्मक पूँजी","मूर्त बुद्धि","सांस्कृतिक पूँजी","सामाजिक अधिगम"],"explanationHi":"सांस्कृतिक पूँजी प्रभुत्वशाली संस्कृति की भाषा, रुचियों और ज्ञान से परिचय है, जिसे विद्यालय ऐसे पुरस्कृत करते हैं मानो वह स्वाभाविक योग्यता हो, जिससे सामाजिक असमानता का पुनरुत्पादन होता है।"},
  {"id":"cdp-child-development-436","question":"Which of the following statements about individual differences are correct? I. They arise from the interaction of heredity and environment. II. A single child may be strong in some abilities and weak in others. III. All children of the same age in a class learn best at the same pace. IV. NCF 2005 recommends permanently streaming young children into ability groups.","options":["I and IV only","II and III only","I and II only","I, II and IV only"],"answer":2,"explanation":"Differences come from heredity–environment interaction and exist both between and within children. A uniform pace ignores these differences, and NCF 2005 cautions against rigid, permanent ability grouping.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"वैयक्तिक भिन्नताओं के बारे में इनमें से कौन-से कथन सही हैं? I. वे आनुवंशिकता और पर्यावरण की अंतःक्रिया से उत्पन्न होती हैं। II. एक ही बच्चा कुछ योग्यताओं में मज़बूत और कुछ में कमज़ोर हो सकता है। III. कक्षा में एक ही आयु के सभी बच्चे एक ही गति से सबसे अच्छा सीखते हैं। IV. NCF 2005 छोटे बच्चों को योग्यता-समूहों में स्थायी रूप से बाँटने की अनुशंसा करती है।","optionsHi":["केवल I और IV","केवल II और III","केवल I और II","केवल I, II और IV"],"explanationHi":"भिन्नताएँ आनुवंशिकता–पर्यावरण अंतःक्रिया से आती हैं और बच्चों के बीच तथा बच्चों के भीतर दोनों में होती हैं। एकसमान गति इन भिन्नताओं की अनदेखी करती है, और NCF 2005 कठोर, स्थायी योग्यता-समूहीकरण के प्रति आगाह करती है।"},
  {"id":"cdp-child-development-437","question":"Aarav, a Class 4 student, draws remarkably detailed maps of his village but reads much below his class level. The difference between his drawing and reading abilities is an example of:","options":["Inter-individual difference","Gender difference","Cultural difference","Intra-individual difference"],"answer":3,"explanation":"Intra-individual differences are variations among the abilities of the same person; inter-individual differences are differences between persons.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"कक्षा 4 का विद्यार्थी आरव अपने गाँव के उल्लेखनीय रूप से विस्तृत नक्शे बनाता है पर अपनी कक्षा के स्तर से बहुत नीचे पढ़ता है। उसकी चित्रकारी और पठन योग्यताओं के बीच का अंतर किसका उदाहरण है?","optionsHi":["अंतर-वैयक्तिक भिन्नता","लिंग भिन्नता","सांस्कृतिक भिन्नता","अंतः-वैयक्तिक भिन्नता"],"explanationHi":"अंतः-वैयक्तिक भिन्नताएँ एक ही व्यक्ति की योग्यताओं के बीच के अंतर हैं; अंतर-वैयक्तिक भिन्नताएँ व्यक्तियों के बीच के अंतर हैं।"},
  {"id":"cdp-child-development-438","question":"A Class 4 teacher in Hyderabad writes in a report card: ‘Lakshmi can read an unseen Telugu paragraph fluently and answer four of five comprehension questions correctly.’ This is an example of:","options":["Norm-referenced reporting","Criterion-referenced reporting","Ipsative ranking against peers","Percentile reporting"],"answer":1,"explanation":"Criterion-referenced reporting describes what a learner can do against a defined standard; norm-referenced reporting (such as percentiles or ranks) compares her with other learners.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"हैदराबाद में कक्षा 4 की एक शिक्षिका रिपोर्ट कार्ड में लिखती है: ‘लक्ष्मी एक अपरिचित तेलुगु अनुच्छेद धाराप्रवाह पढ़ सकती है और पाँच में से चार बोध प्रश्नों का सही उत्तर दे सकती है।’ यह किसका उदाहरण है?","optionsHi":["मानक-संदर्भित रिपोर्टिंग","कसौटी-संदर्भित रिपोर्टिंग","साथियों के विरुद्ध स्व-सापेक्ष (आइप्सेटिव) रैंकिंग","शतमक रिपोर्टिंग"],"explanationHi":"कसौटी-संदर्भित रिपोर्टिंग किसी परिभाषित मानक के विरुद्ध वर्णन करती है कि अधिगमकर्ता क्या कर सकता है; मानक-संदर्भित रिपोर्टिंग (जैसे शतमक या रैंक) उसकी तुलना अन्य अधिगमकर्ताओं से करती है।"},
  {"id":"cdp-child-development-439","question":"Which reform is most in line with NCF 2005’s recommendations on examinations?","options":["Making board exams longer so that they cover the whole syllabus in more detail","Adding more board-level exams from Class 5 onwards to raise standards across schools","Replacing all written tests with oral tests only, to remove the fear of writing","Shifting exams towards understanding and application, with less rote recall and stress"],"answer":3,"explanation":"NCF 2005 criticised exams that reward rote memory and cause stress, and called for questions testing understanding and application and for more flexible, less high-stakes examinations.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"परीक्षाओं पर NCF 2005 की अनुशंसाओं के सबसे अनुरूप सुधार कौन-सा है?","optionsHi":["बोर्ड परीक्षाओं को लंबा बनाना ताकि वे पूरे पाठ्यक्रम को अधिक विस्तार से समेटें","विद्यालयों में स्तर ऊँचा करने के लिए कक्षा 5 से आगे और बोर्ड-स्तरीय परीक्षाएँ जोड़ना","लिखने के भय को दूर करने के लिए सभी लिखित परीक्षाओं की जगह केवल मौखिक परीक्षाएँ रखना","परीक्षाओं को समझ और अनुप्रयोग की ओर मोड़ना, रटंत स्मरण और तनाव को घटाते हुए"],"explanationHi":"NCF 2005 ने उन परीक्षाओं की आलोचना की जो रटी हुई स्मृति को पुरस्कृत करती हैं और तनाव पैदा करती हैं, और समझ तथा अनुप्रयोग का परीक्षण करने वाले प्रश्नों और अधिक लचीली, कम उच्च-दाँव परीक्षाओं का आह्वान किया।"},
  {"id":"cdp-child-development-440","question":"A Class 7 science teacher in Kochi ends each lesson by asking students to write one thing they understood and one question they still have; she uses the slips to plan the next day’s lesson. This is best described as:","options":["Assessment of learning","Summative assessment","Assessment for learning","Norm-referenced testing"],"answer":2,"explanation":"Assessment for learning is ongoing and formative: the evidence is used to adjust teaching while learning is happening, not to grade or rank at the end.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कोच्चि में कक्षा 7 की एक विज्ञान शिक्षिका हर पाठ के अंत में विद्यार्थियों से एक बात लिखने को कहती है जो उन्होंने समझी और एक प्रश्न जो अब भी उनके पास है; वह इन पर्चियों का उपयोग अगले दिन के पाठ की योजना बनाने में करती है। इसका सबसे अच्छा वर्णन है:","optionsHi":["अधिगम का आकलन","योगात्मक आकलन","अधिगम के लिए आकलन","मानक-संदर्भित परीक्षण"],"explanationHi":"अधिगम के लिए आकलन सतत और रचनात्मक है: साक्ष्य का उपयोग अधिगम होते समय शिक्षण को समायोजित करने में होता है, अंत में ग्रेड देने या क्रम बनाने के लिए नहीं।"},
  {"id":"cdp-child-development-441","question":"A school plans to place Class 3 children into ‘bright’ and ‘dull’ sections on the basis of a single IQ test. Which is the most valid criticism?","options":["IQ tests sample few abilities, reflect language and background, and labels can self-fulfil","IQ tests are unreliable because a child's scores change randomly from day to day","IQ tests should be used only for older children; otherwise the plan is sound","Sectioning is fine but should be based on parents’ income and education instead"],"answer":0,"explanation":"A single score leaves out creativity, practical and other abilities, is shaped by language and opportunity, and fixed sections lower expectations for the ‘dull’ group, worsening the gap.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक विद्यालय एक ही IQ परीक्षण के आधार पर कक्षा 3 के बच्चों को ‘तेज़’ और ‘मंद’ अनुभागों में रखने की योजना बनाता है। सबसे वैध आलोचना कौन-सी है?","optionsHi":["IQ परीक्षण कुछ ही योग्यताओं का प्रतिचयन करते हैं, भाषा और पृष्ठभूमि को प्रतिबिंबित करते हैं, और लेबल स्वयं-पूर्ति कर सकते हैं","IQ परीक्षण अविश्वसनीय हैं क्योंकि बच्चे के अंक दिन-प्रतिदिन यादृच्छिक रूप से बदलते हैं","IQ परीक्षण केवल बड़े बच्चों के लिए उपयोग होने चाहिए; अन्यथा योजना ठीक है","अनुभाग बनाना ठीक है पर उसका आधार इसके बजाय माता-पिता की आय और शिक्षा होना चाहिए"],"explanationHi":"एक ही अंक सृजनशीलता, व्यावहारिक और अन्य योग्यताओं को छोड़ देता है, भाषा और अवसर से आकार लेता है, और निश्चित अनुभाग ‘मंद’ समूह की अपेक्षाएँ घटाते हैं, जिससे अंतर बढ़ता है।"},
  {"id":"cdp-child-development-442","question":"While checking answers on ‘causes of the 1857 revolt’, a teacher in Patna gives higher marks to students with neat handwriting and good behaviour in class, even when the content is similar to others’. This assessment error is called:","options":["The halo effect","The central tendency error","The recency effect","The Flynn effect"],"answer":0,"explanation":"The halo effect occurs when an overall impression or an unrelated trait (neatness, conduct) colours the judgement of a specific performance.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"‘1857 के विद्रोह के कारण’ पर उत्तर जाँचते समय, पटना का एक शिक्षक साफ लिखावट और कक्षा में अच्छे व्यवहार वाले विद्यार्थियों को अधिक अंक देता है, भले ही उनकी विषयवस्तु दूसरों जैसी ही हो। इस आकलन-त्रुटि को क्या कहते हैं?","optionsHi":["प्रभामंडल प्रभाव","केंद्रीय प्रवृत्ति त्रुटि","नवीनता प्रभाव","फ्लिन प्रभाव"],"explanationHi":"प्रभामंडल प्रभाव तब होता है जब कोई समग्र धारणा या असंबंधित गुण (सफाई, आचरण) किसी विशेष प्रदर्शन के निर्णय को रंग देता है।"},
  {"id":"cdp-child-development-443","question":"Sonamoni, whose home language is Santhali, takes a verbal IQ test in Hindi in her Jharkhand school and scores 78. What is the most defensible interpretation?","options":["She should be retested in Hindi after a month of coaching in test-taking skills","The score is valid but should be kept confidential so that she is not labelled","The test likely underestimates her; assess with non-verbal tasks or in Santhali first","The score suggests slow learning, so she needs extra remedial support in all subjects"],"answer":2,"explanation":"A verbal test in a language she has not mastered measures her Hindi, not her intelligence, so a fair, non-verbal or home-language assessment is needed. Retesting in Hindi after coaching is tempting but keeps the same language barrier in place.","difficulty":"very-hard","source":"CTET Paper 1 · State TET","questionHi":"सोनामणि, जिसकी घर की भाषा संथाली है, अपने झारखंड के विद्यालय में हिंदी में एक शाब्दिक IQ परीक्षण देती है और 78 अंक पाती है। सबसे उचित व्याख्या क्या है?","optionsHi":["परीक्षा देने के कौशल की एक माह की कोचिंग के बाद उसे हिंदी में दोबारा परखा जाना चाहिए","अंक वैध है पर गोपनीय रखा जाना चाहिए ताकि उस पर लेबल न लगे","परीक्षण संभवतः उसे कम आँकता है; पहले अशाब्दिक कार्यों से या संथाली में आकलन कीजिए","अंक धीमे अधिगम का संकेत देता है, इसलिए उसे सभी विषयों में अतिरिक्त उपचारात्मक सहायता चाहिए"],"explanationHi":"जिस भाषा में उसने निपुणता नहीं पाई है उसमें शाब्दिक परीक्षण उसकी हिंदी को मापता है, उसकी बुद्धि को नहीं, इसलिए निष्पक्ष, अशाब्दिक या घर की भाषा का आकलन चाहिए। कोचिंग के बाद हिंदी में दोबारा परखना आकर्षक है पर उसी भाषा-बाधा को बनाए रखता है।"},
  {"id":"cdp-child-development-444","question":"An observer in a co-educational Class 8 science class records that the teacher asks boys most of the follow-up ‘why’ questions, gives them longer wait time and more detailed feedback, while girls are mostly praised for neatness. This pattern is best described as:","options":["Fair treatment, since the teacher never says anything against girls","Assessment for learning tailored to each group","Evidence that boys are by nature more interested in science than girls","Gender bias working through the hidden curriculum of classroom talk"],"answer":3,"explanation":"Differences in questioning, wait time and type of feedback send unspoken messages about who is a ‘science person’; this is gender bias through the hidden curriculum even without any explicit statement.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"सह-शिक्षा वाली कक्षा 8 की विज्ञान कक्षा में एक प्रेक्षक दर्ज करता है कि शिक्षक अधिकांश अनुवर्ती ‘क्यों’ प्रश्न लड़कों से पूछता है, उन्हें लंबा प्रतीक्षा-समय और अधिक विस्तृत प्रतिपुष्टि देता है, जबकि लड़कियों की प्रशंसा अधिकतर साफ-सफाई के लिए की जाती है। इस प्रतिरूप का सबसे अच्छा वर्णन है:","optionsHi":["निष्पक्ष व्यवहार, क्योंकि शिक्षक कभी लड़कियों के विरुद्ध कुछ नहीं कहता","प्रत्येक समूह के अनुरूप ढाला गया अधिगम के लिए आकलन","इसका प्रमाण कि लड़के स्वभाव से लड़कियों की तुलना में विज्ञान में अधिक रुचि रखते हैं","कक्षा-बातचीत की छिपी पाठ्यचर्या के माध्यम से काम करता लिंग पक्षपात"],"explanationHi":"प्रश्न पूछने, प्रतीक्षा-समय और प्रतिपुष्टि के प्रकार में अंतर अनकहे संदेश देते हैं कि कौन ‘विज्ञान वाला व्यक्ति’ है; यह किसी स्पष्ट कथन के बिना भी छिपी पाठ्यचर्या के माध्यम से लिंग पक्षपात है।"},
  {"id":"cdp-child-development-445","question":"After being shown a picture of a woman flying a plane, a six-year-old later insists she saw ‘a man pilot’. Which theory best explains this memory distortion?","options":["Freud’s theory of identification with the same-sex parent during early childhood","Gender schema theory: children organise and distort information to fit gender categories","Piaget’s theory that object permanence is incomplete at six","Bandura's view that children copy only same-sex models they see"],"answer":1,"explanation":"Sandra Bem’s gender schema theory holds that children build mental categories of what fits each gender and tend to forget or distort information that does not fit them, as in remembering the pilot as a man.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"एक महिला के विमान उड़ाने का चित्र दिखाए जाने के बाद, छह वर्ष की एक बच्ची बाद में ज़ोर देती है कि उसने ‘एक पुरुष पायलट’ देखा था। कौन-सा सिद्धांत इस स्मृति-विकृति को सबसे अच्छी तरह समझाता है?","optionsHi":["फ्रायड का प्रारंभिक बाल्यावस्था में समान-लिंग माता-पिता के साथ तादात्मीकरण का सिद्धांत","लिंग स्कीमा सिद्धांत: बच्चे सूचना को लिंग श्रेणियों में फिट करने के लिए संगठित और विकृत करते हैं","पियाजे का सिद्धांत कि छह वर्ष की आयु में वस्तु स्थायित्व अधूरा होता है","बंडूरा का मत कि बच्चे केवल उन्हीं समान-लिंग आदर्शों की नकल करते हैं जिन्हें वे देखते हैं"],"explanationHi":"सैंड्रा बेम का लिंग स्कीमा सिद्धांत मानता है कि बच्चे इस बारे में मानसिक श्रेणियाँ बनाते हैं कि प्रत्येक लिंग में क्या फिट होता है और जो फिट नहीं होता उसे भूलने या विकृत करने की प्रवृत्ति रखते हैं, जैसे पायलट को पुरुष के रूप में याद करना।"},
  {"id":"cdp-child-development-446","question":"Four-year-old Rohan says, ‘I am a boy and I will grow up to be a man like Papa’, but also says that if he wore his sister’s frock he would become a girl. In Kohlberg’s account of gender understanding, Rohan has reached:","options":["Gender stability but not gender constancy","Gender identity only, without stability","Full gender constancy across all situations","No gender understanding at all"],"answer":0,"explanation":"Rohan knows his gender (identity) and that it stays the same over time (stability), but thinks it changes with clothes, so he lacks constancy (consistency across situations), usually reached around 5–7 years.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"चार वर्ष का रोहन कहता है, ‘मैं लड़का हूँ और बड़ा होकर पापा जैसा आदमी बनूँगा’, पर यह भी कहता है कि अगर वह अपनी बहन की फ्रॉक पहन ले तो लड़की बन जाएगा। कोहलबर्ग के लिंग-बोध के वर्णन में रोहन किस स्तर तक पहुँचा है?","optionsHi":["लिंग स्थिरता तक, पर लिंग अचलता (कॉन्स्टेंसी) तक नहीं","केवल लिंग पहचान तक, स्थिरता के बिना","सभी स्थितियों में पूर्ण लिंग अचलता तक","लिंग-बोध बिल्कुल नहीं"],"explanationHi":"रोहन अपना लिंग जानता है (पहचान) और यह कि वह समय के साथ वही रहता है (स्थिरता), पर सोचता है कि वह कपड़ों से बदलता है, इसलिए उसमें अचलता (स्थितियों में एकरूपता) नहीं है, जो सामान्यतः लगभग 5–7 वर्ष में प्राप्त होती है।"},
  {"id":"cdp-child-development-447","question":"Assertion (A): Children in all cultures master the complex grammar of their language within a few years, even though the speech they hear is often incomplete and full of errors. Reason (R): Noam Chomsky proposed that children have an inborn language acquisition device that supplies universal principles of grammar.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Chomsky’s ‘poverty of the stimulus’ argument says imperfect input cannot by itself explain rapid mastery of grammar, so an innate LAD with universal grammar is proposed as the explanation.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"अभिकथन (A): सभी संस्कृतियों के बच्चे कुछ ही वर्षों में अपनी भाषा के जटिल व्याकरण में निपुण हो जाते हैं, भले ही वे जो वाणी सुनते हैं वह प्रायः अधूरी और त्रुटियों से भरी होती है। कारण (R): नोम चॉम्स्की ने प्रस्तावित किया कि बच्चों में जन्मजात भाषा अर्जन युक्ति होती है जो व्याकरण के सार्वभौमिक सिद्धांत उपलब्ध कराती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"चॉम्स्की का ‘उद्दीपक की दरिद्रता’ तर्क कहता है कि अपूर्ण निवेश अकेले व्याकरण में तीव्र निपुणता को नहीं समझा सकता, इसलिए सार्वभौमिक व्याकरण के साथ जन्मजात LAD को व्याख्या के रूप में प्रस्तावित किया गया है।"},
  {"id":"cdp-child-development-448","question":"Which of the following statements is consistent with Vygotsky’s view of thought and language?","options":["Language is merely a reflection of thought and plays no role in shaping it","Thought and speech have different roots and merge around age two, so thought becomes verbal","Children first think in inner speech and only later begin to speak aloud to others","Speech is an inborn module that develops independently of social interaction"],"answer":1,"explanation":"Vygotsky argued that pre-linguistic thought and pre-intellectual speech develop separately and then join, after which language becomes a major tool of thinking; inner speech develops last, from social and private speech.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"निम्नलिखित में से कौन-सा कथन वाइगोत्स्की के चिंतन और भाषा के दृष्टिकोण के अनुरूप है?","optionsHi":["भाषा केवल चिंतन का प्रतिबिंब है और उसे आकार देने में कोई भूमिका नहीं निभाती","चिंतन और वाक् की जड़ें भिन्न हैं और लगभग दो वर्ष की आयु में मिल जाती हैं, जिससे चिंतन शाब्दिक हो जाता है","बच्चे पहले आंतरिक वाक् में सोचते हैं और बाद में ही दूसरों से ज़ोर से बोलना शुरू करते हैं","वाक् एक जन्मजात मॉड्यूल है जो सामाजिक अंतःक्रिया से स्वतंत्र रूप से विकसित होता है"],"explanationHi":"वाइगोत्स्की ने तर्क दिया कि भाषा-पूर्व चिंतन और बुद्धि-पूर्व वाक् अलग-अलग विकसित होते हैं और फिर जुड़ जाते हैं, जिसके बाद भाषा चिंतन का प्रमुख उपकरण बन जाती है; आंतरिक वाक् सबसे अंत में, सामाजिक और निजी वाक् से विकसित होती है।"},
  {"id":"cdp-child-development-449","question":"A Class 2 teacher in Indore says, ‘Teaching a child who cannot yet conserve the words “same amount” will not by itself make him understand that pouring water into a taller glass does not change the quantity.’ Her view is closest to:","options":["Vygotsky’s view that learning the words drives the formation of concepts","Chomsky’s view that grammar is innate and needs only exposure","Piaget’s view that language reflects thought, which follows cognitive growth","Skinner’s view that verbal behaviour is shaped by reinforcement"],"answer":2,"explanation":"Piaget held that language depends on and reflects the level of thought: a child can learn the words but not the concept until the underlying operations develop.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"इंदौर में कक्षा 2 की एक शिक्षिका कहती है, ‘जो बच्चा अभी संरक्षण नहीं कर सकता, उसे “समान मात्रा” शब्द सिखाने से अकेले उसे यह समझ नहीं आ जाएगा कि पानी को लंबे गिलास में उँडेलने से मात्रा नहीं बदलती।’ उसका मत सबसे अधिक किसके निकट है?","optionsHi":["वाइगोत्स्की का मत कि शब्द सीखना अवधारणाओं के निर्माण को संचालित करता है","चॉम्स्की का मत कि व्याकरण जन्मजात है और उसे केवल संपर्क चाहिए","पियाजे का मत कि भाषा चिंतन को प्रतिबिंबित करती है, जो संज्ञानात्मक वृद्धि के बाद आती है","स्किनर का मत कि शाब्दिक व्यवहार पुनर्बलन से आकार लेता है"],"explanationHi":"पियाजे का मत था कि भाषा चिंतन के स्तर पर निर्भर करती है और उसे प्रतिबिंबित करती है: बच्चा शब्द सीख सकता है पर अवधारणा तब तक नहीं जब तक अंतर्निहित संक्रियाएँ विकसित न हों।"},
  {"id":"cdp-child-development-450","question":"During daily picture-book time, a mother in Kolkata points and names objects, waits for her toddler to respond, and expands his ‘doggy run’ into ‘Yes, the dog is running fast’. Jerome Bruner called such patterned adult support for language learning the:","options":["Language Acquisition Device (LAD) in action","Zone of Proximal Development in language","Universal grammar","Language Acquisition Support System (LASS)"],"answer":3,"explanation":"Bruner proposed LASS to stress that adults scaffold language through routines, turn-taking and expansions, complementing Chomsky’s innate LAD.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"प्रतिदिन चित्र-पुस्तक के समय कोलकाता की एक माँ वस्तुओं की ओर इशारा करके नाम बताती है, अपने छोटे बच्चे के उत्तर देने की प्रतीक्षा करती है, और उसके ‘कुत्ता दौड़ा’ को ‘हाँ, कुत्ता तेज़ दौड़ रहा है’ में विस्तारित करती है। जेरोम ब्रूनर ने भाषा-अधिगम के लिए वयस्कों के ऐसे ढाँचागत सहारे को क्या कहा?","optionsHi":["क्रियाशील भाषा अर्जन युक्ति (LAD)","भाषा में निकटस्थ विकास का क्षेत्र","सार्वभौमिक व्याकरण","भाषा अर्जन सहायता प्रणाली (LASS)"],"explanationHi":"ब्रूनर ने LASS प्रस्तावित की यह बताने के लिए कि वयस्क दिनचर्याओं, बारी-बारी से बोलने और विस्तारणों के माध्यम से भाषा का पाड़ (scaffold) देते हैं, जो चॉम्स्की के जन्मजात LAD का पूरक है।"},
  {"id":"cdp-child-development-451","question":"During a maths test, a Class 4 teacher gives a child a series of graded hints whenever he gets stuck and records how many hints he needs before he succeeds. She uses this record to plan his next lessons. This approach is best described as:","options":["Summative assessment of what he has learnt by the end of the unit","Norm-referenced testing of the child against classmates","Dynamic assessment, estimating the child’s zone of proximal development","A purely diagnostic test for a specific learning disability"],"answer":2,"explanation":"Dynamic assessment builds on Vygotsky’s ZPD: it measures not only what a child can do alone but how much and what kind of help he needs. A static test captures only the independent level.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"गणित परीक्षण के दौरान कक्षा 4 की एक शिक्षिका बच्चे के अटकने पर उसे क्रमिक संकेत देती है और दर्ज करती है कि सफल होने से पहले उसे कितने संकेतों की आवश्यकता पड़ी। वह इस अभिलेख का उपयोग उसके अगले पाठों की योजना बनाने में करती है। इस उपागम का सबसे अच्छा वर्णन है:","optionsHi":["इकाई के अंत तक उसने जो सीखा उसका योगात्मक आकलन","बच्चे का सहपाठियों के विरुद्ध मानक-संदर्भित परीक्षण","गतिशील आकलन, जो बच्चे के निकटस्थ विकास के क्षेत्र का अनुमान लगाता है","किसी विशिष्ट अधिगम अक्षमता के लिए विशुद्ध निदानात्मक परीक्षण"],"explanationHi":"गतिशील आकलन वाइगोत्स्की के ZPD पर आधारित है: वह न केवल यह मापता है कि बच्चा अकेले क्या कर सकता है बल्कि यह भी कि उसे कितनी और किस प्रकार की सहायता चाहिए। स्थिर परीक्षण केवल स्वतंत्र स्तर पकड़ता है।"},
  {"id":"cdp-child-development-452","question":"A Class 4 child can add two-digit numbers alone, can add three-digit numbers with carrying only when the teacher prompts each step, and cannot do long division even with full help. According to Vygotsky, instruction for her should now focus on:","options":["Two-digit addition, until it is perfect and fully automatic","Three-digit addition with carrying, with support that is gradually withdrawn","Long division, because hard tasks speed up development","Whatever the rest of the class is doing, since the ZPD is the same for a whole age group"],"answer":1,"explanation":"Three-digit addition lies in her ZPD: beyond her independent level but within reach with help. Two-digit work is already mastered, long division is beyond even assisted performance, and ZPDs differ between children.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 की एक बच्ची दो-अंकीय संख्याएँ अकेले जोड़ सकती है, तीन-अंकीय संख्याएँ हासिल के साथ केवल तब जोड़ सकती है जब शिक्षिका हर चरण पर संकेत दे, और पूर्ण सहायता के साथ भी लंबा भाग नहीं कर सकती। वाइगोत्स्की के अनुसार अब उसके लिए अनुदेशन को किस पर केंद्रित होना चाहिए?","optionsHi":["दो-अंकीय जोड़ पर, जब तक वह पूर्ण और पूरी तरह स्वचालित न हो जाए","हासिल के साथ तीन-अंकीय जोड़ पर, ऐसी सहायता के साथ जो धीरे-धीरे हटाई जाए","लंबे भाग पर, क्योंकि कठिन कार्य विकास को तेज़ करते हैं","जो भी बाकी कक्षा कर रही हो, क्योंकि पूरे आयु-समूह के लिए ZPD समान होता है"],"explanationHi":"तीन-अंकीय जोड़ उसके ZPD में है: उसके स्वतंत्र स्तर से परे पर सहायता से पहुँच में। दो-अंकीय कार्य में वह पहले ही निपुण है, लंबा भाग सहायता-प्राप्त प्रदर्शन से भी परे है, और ZPD बच्चों में भिन्न होते हैं।"},
  {"id":"cdp-child-development-453","question":"Which sequence of teacher actions best shows scaffolding being faded correctly while a Class 5 child learns to write a paragraph?","options":["Child writes alone → teacher gives hints → teacher models the paragraph → teacher and child write together","Teacher models a paragraph → they write one together → teacher gives only hints → child writes alone","Teacher gives hints → child writes alone → teacher models the paragraph → teacher and child write together","Teacher models a paragraph → child writes alone → teacher and child write together → teacher gives hints"],"answer":1,"explanation":"Support should start high and be reduced step by step as competence grows, ending with independent performance. The other orders either begin without support or add it back after independence.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"जब कक्षा 5 का बच्चा अनुच्छेद लिखना सीख रहा है, तब शिक्षक की क्रियाओं का कौन-सा क्रम पाड़ (scaffolding) के सही ढंग से घटाए जाने को सबसे अच्छी तरह दर्शाता है?","optionsHi":["बच्चा अकेले लिखता है → शिक्षक संकेत देता है → शिक्षक अनुच्छेद का आदर्श प्रस्तुत करता है → शिक्षक और बच्चा साथ लिखते हैं","शिक्षक अनुच्छेद का आदर्श प्रस्तुत करता है → वे साथ मिलकर एक लिखते हैं → शिक्षक केवल संकेत देता है → बच्चा अकेले लिखता है","शिक्षक संकेत देता है → बच्चा अकेले लिखता है → शिक्षक अनुच्छेद का आदर्श प्रस्तुत करता है → शिक्षक और बच्चा साथ लिखते हैं","शिक्षक अनुच्छेद का आदर्श प्रस्तुत करता है → बच्चा अकेले लिखता है → शिक्षक और बच्चा साथ लिखते हैं → शिक्षक संकेत देता है"],"explanationHi":"सहायता ऊँची से शुरू होनी चाहिए और योग्यता बढ़ने के साथ चरण-दर-चरण घटाई जानी चाहिए, जो स्वतंत्र प्रदर्शन पर समाप्त हो। अन्य क्रम या तो बिना सहायता के शुरू होते हैं या स्वतंत्रता के बाद उसे फिर जोड़ देते हैं।"},
  {"id":"cdp-child-development-454","question":"How many of these statements about private speech are supported by Vygotsky’s theory and later research? I. Children use more private speech when a task is very easy than when it is challenging. II. Private speech gradually becomes silent inner speech. III. Children who talk to themselves on hard tasks are usually less capable than those who stay silent. IV. Private speech helps children plan and regulate their actions.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and IV are correct. I is reversed: private speech rises on moderately challenging tasks. III is a misconception: Berk and others found that children who use it often perform better.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"निजी वाक् के बारे में इनमें से कितने कथन वाइगोत्स्की के सिद्धांत और बाद के शोध द्वारा समर्थित हैं? I. जब कार्य बहुत आसान हो तब बच्चे चुनौतीपूर्ण कार्य की तुलना में अधिक निजी वाक् का उपयोग करते हैं। II. निजी वाक् धीरे-धीरे मौन आंतरिक वाक् बन जाती है। III. कठिन कार्यों पर स्वयं से बात करने वाले बच्चे प्रायः चुप रहने वालों की तुलना में कम सक्षम होते हैं। IV. निजी वाक् बच्चों को अपनी क्रियाओं की योजना बनाने और उन्हें नियंत्रित करने में मदद करती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"II और IV सही हैं। I उलटा है: निजी वाक् मध्यम चुनौतीपूर्ण कार्यों पर बढ़ती है। III एक भ्रांति है: बर्क और अन्य ने पाया कि जो बच्चे इसका प्रायः उपयोग करते हैं वे बेहतर प्रदर्शन करते हैं।"},
  {"id":"cdp-child-development-455","question":"A child uses the word ‘brother’ correctly at home but cannot say what a brother is. In school she learns ‘photosynthesis’ through a definition but cannot connect it to the plants on her windowsill. Vygotsky would call these respectively:","options":["Scientific concept and spontaneous concept","Elementary function and higher mental function","Spontaneous concept and scientific concept","Assimilated schema and accommodated schema"],"answer":2,"explanation":"Spontaneous concepts grow from everyday experience and are used without conscious awareness; scientific concepts are learnt systematically through instruction. Vygotsky argued that good teaching links the two so that each strengthens the other.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"एक बच्ची घर पर ‘भाई’ शब्द का सही प्रयोग करती है पर बता नहीं सकती कि भाई क्या होता है। विद्यालय में वह ‘प्रकाश-संश्लेषण’ एक परिभाषा के रूप में सीखती है पर उसे अपनी खिड़की के पौधों से जोड़ नहीं पाती। वाइगोत्स्की इन्हें क्रमशः क्या कहेंगे?","optionsHi":["वैज्ञानिक अवधारणा और स्वतःस्फूर्त अवधारणा","प्रारंभिक प्रकार्य और उच्च मानसिक प्रकार्य","स्वतःस्फूर्त अवधारणा और वैज्ञानिक अवधारणा","आत्मसात की गई स्कीमा और समायोजित स्कीमा"],"explanationHi":"स्वतःस्फूर्त अवधारणाएँ रोज़मर्रा के अनुभव से बढ़ती हैं और सचेत जागरूकता के बिना प्रयोग होती हैं; वैज्ञानिक अवधारणाएँ अनुदेशन द्वारा व्यवस्थित रूप से सीखी जाती हैं। वाइगोत्स्की का तर्क था कि अच्छा शिक्षण दोनों को जोड़ता है ताकि प्रत्येक दूसरे को मज़बूत करे।"},
  {"id":"cdp-child-development-456","question":"A grandmother ties a knot in the end of her dupatta so that she will remember to buy medicine on the way home. In Vygotsky’s terms, the knot is:","options":["A psychological tool (sign) that turns natural memory into mediated memory","A conditioned stimulus formed by repeated pairing of the knot with buying medicine","A schema that has been accommodated to fit the new information","An iconic representation of the medicine in Bruner’s sense"],"answer":0,"explanation":"Vygotsky used exactly such examples to show how people use signs to control their own mental processes. Mediated memory is a higher mental function, unlike unaided natural memory.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"एक दादी दवा खरीदना याद रखने के लिए घर लौटते समय के रास्ते में अपने दुपट्टे के सिरे में गाँठ बाँधती है। वाइगोत्स्की की शब्दावली में यह गाँठ है:","optionsHi":["मनोवैज्ञानिक उपकरण (संकेत) जो प्राकृतिक स्मृति को मध्यस्थित स्मृति में बदल देता है","अनुबंधित उद्दीपक जो गाँठ और दवा खरीदने के बार-बार जुड़ने से बना है","स्कीमा जिसे नई सूचना के अनुरूप समायोजित किया गया है","ब्रूनर के अर्थ में दवा का प्रतिबिंबात्मक निरूपण"],"explanationHi":"वाइगोत्स्की ने ठीक ऐसे उदाहरणों का उपयोग यह दिखाने के लिए किया कि लोग अपनी मानसिक प्रक्रियाओं को नियंत्रित करने के लिए संकेतों का उपयोग कैसे करते हैं। मध्यस्थित स्मृति एक उच्च मानसिक प्रकार्य है, बिना सहायता वाली प्राकृतिक स्मृति के विपरीत।"},
  {"id":"cdp-child-development-457","question":"Thirteen-year-old Kabir learns to use a new video-editing app from his nine-year-old sister, who shows him the steps and corrects his mistakes. From Vygotsky’s viewpoint, the sister is acting as:","options":["A peer who cannot teach Kabir, since a younger child is less developed","A model only for observational learning in Bandura’s sense","A source of disequilibrium in Piaget’s sense","The more knowledgeable other for this particular task"],"answer":3,"explanation":"The MKO is whoever knows more about the specific task, regardless of age or status. Her guiding and correcting goes beyond simple modelling.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"तेरह वर्ष का कबीर अपनी नौ वर्ष की बहन से एक नया वीडियो-संपादन ऐप इस्तेमाल करना सीखता है, जो उसे चरण दिखाती है और उसकी गलतियाँ सुधारती है। वाइगोत्स्की के दृष्टिकोण से बहन किस भूमिका में है?","optionsHi":["एक साथी जो कबीर को सिखा नहीं सकता, क्योंकि छोटा बच्चा कम विकसित होता है","केवल बंडूरा के अर्थ में अवलोकनात्मक अधिगम के लिए आदर्श","पियाजे के अर्थ में असाम्य का स्रोत","इस विशेष कार्य के लिए अधिक जानकार अन्य (MKO)"],"explanationHi":"MKO वह है जो किसी विशेष कार्य के बारे में अधिक जानता है, चाहे आयु या हैसियत कुछ भी हो। उसका मार्गदर्शन और सुधार करना साधारण आदर्श-प्रस्तुति से आगे जाता है।"},
  {"id":"cdp-child-development-458","question":"In ‘reciprocal teaching’ of reading, the teacher first models four strategies (summarising, questioning, clarifying and predicting) and then gradually lets students take turns leading the group discussion. The idea most directly behind this method is:","options":["Operant shaping through reinforcement of each strategy","Scaffolding within the zone of proximal development","Piaget’s concept of horizontal décalage in reading","Learning by insight into the text"],"answer":1,"explanation":"Reciprocal teaching, developed by Palincsar and Brown, transfers responsibility from teacher to students as they become competent, which is Vygotskian scaffolding in the ZPD.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"पठन के ‘पारस्परिक शिक्षण’ में शिक्षक पहले चार युक्तियों (सारांश, प्रश्न, स्पष्टीकरण और पूर्वानुमान) का आदर्श प्रस्तुत करता है और फिर धीरे-धीरे विद्यार्थियों को समूह चर्चा का नेतृत्व करने की बारी देता है। इस विधि के पीछे सबसे सीधा विचार क्या है?","optionsHi":["प्रत्येक युक्ति के पुनर्बलन द्वारा क्रियाप्रसूत आकारण","निकटस्थ विकास के क्षेत्र के भीतर पाड़ (scaffolding)","पठन में पियाजे की क्षैतिज विचलन की अवधारणा","पाठ में अंतर्दृष्टि द्वारा अधिगम"],"explanationHi":"पालिंक्सार और ब्राउन द्वारा विकसित पारस्परिक शिक्षण जिम्मेदारी को शिक्षक से विद्यार्थियों को तब अंतरित करता है जब वे सक्षम होते हैं, जो ZPD में वाइगोत्स्कीय पाड़ है।"},
  {"id":"cdp-child-development-459","question":"At first, a three-year-old counts mangoes only while her mother points to each one and counts aloud with her. Months later she points to each mango herself and whispers the numbers. Later still, she counts silently without pointing. Vygotsky would describe this as:","options":["Internalisation: what happens first between people later occurs within her","Assimilation of counting into an existing schema, then accommodation","Maturation unfolding at its own pace regardless of the mother’s help","Shaping by successive approximations, each reinforced by the mother"],"answer":0,"explanation":"Vygotsky’s general genetic law says every higher function appears twice, first socially and then individually. Counting moves from shared activity to whispered self-guidance to silent mental action.","difficulty":"hard","source":"CTET · State TETs","questionHi":"शुरू में तीन वर्ष की एक बच्ची आमों को तभी गिनती है जब उसकी माँ हर एक की ओर इशारा करती है और उसके साथ ज़ोर से गिनती करती है। महीनों बाद वह स्वयं हर आम की ओर इशारा करती है और संख्याएँ फुसफुसाती है। और बाद में वह बिना इशारा किए मौन रूप से गिनती है। वाइगोत्स्की इसे किस रूप में वर्णित करेंगे?","optionsHi":["आंतरीकरण: जो पहले लोगों के बीच होता है, वह बाद में उसके भीतर होता है","गिनती का मौजूदा स्कीमा में आत्मसात्करण, फिर समायोजन","परिपक्वता जो माँ की सहायता से परे अपनी गति से खुलती है","क्रमिक सन्निकटनों द्वारा आकारण, जिनमें से प्रत्येक को माँ ने पुनर्बलित किया"],"explanationHi":"वाइगोत्स्की का सामान्य आनुवंशिक नियम कहता है कि हर उच्च प्रकार्य दो बार प्रकट होता है, पहले सामाजिक रूप से और फिर वैयक्तिक रूप से। गिनती साझा गतिविधि से फुसफुसाए आत्म-मार्गदर्शन और फिर मौन मानसिक क्रिया की ओर बढ़ती है।"},
  {"id":"cdp-child-development-460","question":"Assertion (A): Vygotsky held that the only ‘good learning’ is that which runs ahead of development. Reason (R): Instruction aimed within the zone of proximal development awakens functions that are still in the process of maturing.","options":["Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"For Vygotsky, learning leads development: teaching aimed only at matured functions adds nothing new. R gives the reason, since instruction in the ZPD pulls developing functions forward.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"अभिकथन (A): वाइगोत्स्की का मत था कि केवल वही अधिगम ‘अच्छा अधिगम’ है जो विकास से आगे चलता है। कारण (R): निकटस्थ विकास के क्षेत्र के भीतर लक्षित अनुदेशन उन प्रकार्यों को जगाता है जो अभी परिपक्व होने की प्रक्रिया में हैं।","optionsHi":["A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है","A और R दोनों सत्य हैं, और R, A की सही व्याख्या है"],"explanationHi":"वाइगोत्स्की के लिए अधिगम विकास को आगे ले जाता है: केवल परिपक्व हो चुके प्रकार्यों पर लक्षित शिक्षण कुछ नया नहीं जोड़ता। R कारण देता है, क्योंकि ZPD में अनुदेशन विकसित हो रहे प्रकार्यों को आगे खींचता है।"},
  {"id":"cdp-child-development-461","question":"Children in a weaving community in Assam become skilled at estimating thread lengths and patterns, while children in a city school become skilled at written arithmetic. Which explanation fits Vygotsky’s theory best?","options":["Both groups pass through the same universal stages at exactly the same ages","Cognitive skills develop through the tools and activities a culture offers","Weaving children are less intelligent because they lack formal operations","The differences arise only from the maturation of the brain with age"],"answer":1,"explanation":"Vygotsky saw cognitive development as shaped by the cultural tools and practices children take part in. He did not propose universal, culture-free stages, and different skills are not proof of lower intelligence.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"असम के एक बुनकर समुदाय के बच्चे धागे की लंबाई और डिज़ाइन का अनुमान लगाने में कुशल हो जाते हैं, जबकि शहर के विद्यालय के बच्चे लिखित अंकगणित में कुशल हो जाते हैं। कौन-सा स्पष्टीकरण वाइगोत्स्की के सिद्धांत के सबसे अनुरूप है?","optionsHi":["दोनों समूह ठीक समान आयु पर समान सार्वभौमिक अवस्थाओं से गुज़रते हैं","संज्ञानात्मक कौशल उन उपकरणों और गतिविधियों के माध्यम से विकसित होते हैं जो संस्कृति प्रदान करती है","बुनकर बच्चे कम बुद्धिमान हैं क्योंकि उनमें औपचारिक संक्रियाओं का अभाव है","अंतर केवल आयु के साथ मस्तिष्क की परिपक्वता से उत्पन्न होते हैं"],"explanationHi":"वाइगोत्स्की संज्ञानात्मक विकास को उन सांस्कृतिक उपकरणों और प्रथाओं द्वारा आकारित मानते थे जिनमें बच्चे भाग लेते हैं। उन्होंने सार्वभौमिक, संस्कृति-मुक्त अवस्थाएँ प्रस्तावित नहीं कीं, और भिन्न कौशल कम बुद्धि का प्रमाण नहीं हैं।"},
  {"id":"cdp-child-development-462","question":"Teacher X gives every child the same full explanation whenever they ask for help. Teacher Y gives a more specific hint after a child makes an error, and less help after the child succeeds. Teacher Y’s approach is best described as:","options":["Inconsistent, since all children should get equal help from a fair teacher","Negative reinforcement of correct answers by withdrawing help","Contingent scaffolding, adjusting help to the learner’s ongoing performance","Discovery learning without any guidance from the teacher"],"answer":2,"explanation":"Effective scaffolding is contingent: more help when the learner struggles and less when she succeeds. Equal help for all ignores differences in each child’s ZPD.","difficulty":"hard","source":"CTET · DSSSB · State TETs","questionHi":"शिक्षक X हर बच्चे को मदद माँगने पर वही पूरी व्याख्या देता है। शिक्षिका Y बच्चे के गलती करने पर अधिक विशिष्ट संकेत देती है, और बच्चे के सफल होने पर कम सहायता। शिक्षिका Y के उपागम का सबसे अच्छा वर्णन है:","optionsHi":["असंगत, क्योंकि एक निष्पक्ष शिक्षक को सभी बच्चों को समान सहायता देनी चाहिए","सहायता हटाकर सही उत्तरों का ऋणात्मक पुनर्बलन","आकस्मिक पाड़ (कंटिन्जेंट स्कैफोल्डिंग), जो सहायता को अधिगमकर्ता के चल रहे प्रदर्शन के अनुसार समायोजित करता है","शिक्षक के बिना किसी मार्गदर्शन के अन्वेषण अधिगम"],"explanationHi":"प्रभावी पाड़ आकस्मिक होता है: अधिगमकर्ता के संघर्ष करने पर अधिक सहायता और सफल होने पर कम। सबके लिए समान सहायता प्रत्येक बच्चे के ZPD में अंतर की अनदेखी करती है।"},
  {"id":"cdp-child-development-463","question":"Consider these statements about Vygotsky’s zone of proximal development. 1. A child’s ZPD is fixed by her IQ and does not change. 2. Two children with the same independent level may have ZPDs of very different widths. 3. Once a task within the ZPD is mastered, the zone moves forward to new tasks. Which is/are correct?","options":["1 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The ZPD is dynamic: it shifts as learning occurs and differs between children with the same independent level. It is not a fixed trait like an IQ score.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"वाइगोत्स्की के निकटस्थ विकास के क्षेत्र के बारे में इन कथनों पर विचार कीजिए। 1. बच्चे का ZPD उसके IQ से निश्चित होता है और बदलता नहीं। 2. समान स्वतंत्र स्तर वाले दो बच्चों के ZPD की चौड़ाई बहुत भिन्न हो सकती है। 3. ZPD के भीतर का कोई कार्य सीख लिए जाने पर क्षेत्र नए कार्यों की ओर आगे बढ़ जाता है। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"ZPD गतिशील है: अधिगम होने पर वह खिसकता है और समान स्वतंत्र स्तर वाले बच्चों में भिन्न होता है। वह IQ अंक जैसा निश्चित गुण नहीं है।"},
  {"id":"cdp-child-development-464","question":"Drawing a picture, a five-year-old finds there is no blue crayon and says aloud, ‘Where’s the blue? No blue... I’ll make the sky with purple and wet it.’ How would Piaget and Vygotsky respectively view this speech?","options":["Piaget: socially directed speech; Vygotsky: speech that will soon disappear without use","Both would see it as egocentric speech with no function in solving the problem","Piaget: inner speech said aloud; Vygotsky: social speech meant for others","Piaget: egocentric speech of immature thought; Vygotsky: private speech to plan and solve"],"answer":3,"explanation":"Piaget saw such speech as a sign of egocentrism that fades away. Vygotsky showed it increases when an obstacle appears, because the child uses it to guide problem solving, and that it later becomes inner speech.","difficulty":"hard","source":"CTET · State TETs","questionHi":"चित्र बनाते समय पाँच वर्ष की एक बच्ची पाती है कि नीला क्रेयॉन नहीं है और ज़ोर से कहती है, ‘नीला कहाँ है? नीला नहीं… मैं आसमान बैंगनी से बनाऊँगी और उसे गीला कर दूँगी।’ पियाजे और वाइगोत्स्की इस वाक् को क्रमशः कैसे देखेंगे?","optionsHi":["पियाजे: सामाजिक रूप से निर्देशित वाक्; वाइगोत्स्की: वाक् जो उपयोग के बिना जल्द गायब हो जाएगी","दोनों इसे अहंकेंद्रित वाक् मानेंगे जिसका समस्या सुलझाने में कोई प्रकार्य नहीं है","पियाजे: ज़ोर से बोली गई आंतरिक वाक्; वाइगोत्स्की: दूसरों के लिए सामाजिक वाक्","पियाजे: अपरिपक्व चिंतन की अहंकेंद्रित वाक्; वाइगोत्स्की: योजना बनाने और हल करने के लिए निजी वाक्"],"explanationHi":"पियाजे ऐसी वाक् को अहंकेंद्रिता का संकेत मानते थे जो मिट जाती है। वाइगोत्स्की ने दिखाया कि बाधा आने पर वह बढ़ती है, क्योंकि बच्चा उसे समस्या समाधान का मार्गदर्शन करने के लिए प्रयोग करता है, और वह बाद में आंतरिक वाक् बन जाती है।"},
  {"id":"cdp-child-development-465","question":"How many of these statements reflect Vygotsky’s view of thought and language? I. Before about two years, thought and speech develop along separate lines. II. Later the two lines meet, so that thought becomes verbal and speech becomes rational. III. Language is merely a label for concepts the child has already formed. IV. Speech first serves to communicate with others and later to direct one’s own thinking.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are Vygotsky’s views. Statement III, that language only reflects concepts already formed, is closer to Piaget’s position.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"चिंतन और भाषा के बारे में वाइगोत्स्की के दृष्टिकोण को इनमें से कितने कथन दर्शाते हैं? I. लगभग दो वर्ष की आयु से पहले चिंतन और वाक् अलग-अलग रेखाओं पर विकसित होते हैं। II. बाद में दोनों रेखाएँ मिलती हैं, जिससे चिंतन शाब्दिक और वाक् तर्कसंगत हो जाती है। III. भाषा केवल उन अवधारणाओं का लेबल है जो बच्चा पहले ही बना चुका है। IV. वाक् पहले दूसरों से संवाद करने के काम आती है और बाद में अपने चिंतन को निर्देशित करने के।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV वाइगोत्स्की के विचार हैं। कथन III, कि भाषा केवल पहले से बनी अवधारणाओं को प्रतिबिंबित करती है, पियाजे की स्थिति के अधिक निकट है।"},
  {"id":"cdp-child-development-466","question":"Vygotsky compared a teacher who judges a child only by what she can do alone to a gardener who judges an orchard only by its ripe fruit. His point was that such assessment ignores:","options":["Functions still maturing, which show in what the child can do with help","The child’s physical health and nutrition, which also affect her growth","The child’s scores compared with the class average on the same task","Errors, which reveal the child’s egocentrism and immature logic"],"answer":0,"explanation":"Independent performance shows only matured functions (the fruit); the buds and flowers are the maturing functions visible in assisted performance. This is the case for assessing the ZPD.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"वाइगोत्स्की ने उस शिक्षक की तुलना, जो बच्चे को केवल इससे आँकता है कि वह अकेले क्या कर सकती है, उस माली से की जो बाग को केवल उसके पके फलों से आँकता है। उनका आशय यह था कि ऐसा आकलन किसकी उपेक्षा करता है?","optionsHi":["अभी परिपक्व हो रहे प्रकार्य, जो इसमें दिखते हैं कि बच्चा सहायता से क्या कर सकता है","बच्चे का शारीरिक स्वास्थ्य और पोषण, जो उसकी वृद्धि को भी प्रभावित करते हैं","उसी कार्य पर बच्चे के अंकों की कक्षा के औसत से तुलना","त्रुटियाँ, जो बच्चे की अहंकेंद्रिता और अपरिपक्व तर्क को प्रकट करती हैं"],"explanationHi":"स्वतंत्र प्रदर्शन केवल परिपक्व हो चुके प्रकार्य (फल) दिखाता है; कलियाँ और फूल परिपक्व हो रहे प्रकार्य हैं जो सहायता-प्राप्त प्रदर्शन में दिखते हैं। यही ZPD के आकलन का पक्ष है।"},
  {"id":"cdp-child-development-467","question":"Which teacher in a Class 2 lesson on subtraction is using a mediating tool in Vygotsky’s sense?","options":["One who gives a sweet each time a child answers a subtraction correctly","One who waits for children to reach the right stage before teaching subtraction","One who lets children use a bead string and a number line to count back","One who has the class chant subtraction tables aloud every day"],"answer":2,"explanation":"For Vygotsky, tools and signs such as a number line mediate thinking and are later internalised. Rewards and chanting are behaviourist techniques, and waiting for readiness is closer to Piaget.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"घटाव के कक्षा 2 के पाठ में कौन-सा शिक्षक वाइगोत्स्की के अर्थ में मध्यस्थता करने वाले उपकरण का उपयोग कर रहा है?","optionsHi":["जो हर बार बच्चे के घटाव सही करने पर मिठाई देता है","जो घटाव पढ़ाने से पहले बच्चों के सही अवस्था तक पहुँचने की प्रतीक्षा करता है","जो बच्चों को पीछे गिनने के लिए मनकों की माला और संख्या रेखा का उपयोग करने देता है","जो कक्षा से हर दिन घटाव की सारणियाँ ज़ोर से दोहरवाता है"],"explanationHi":"वाइगोत्स्की के लिए संख्या रेखा जैसे उपकरण और संकेत चिंतन में मध्यस्थता करते हैं और बाद में आंतरीकृत हो जाते हैं। पुरस्कार और रटना व्यवहारवादी तकनीकें हैं, और तत्परता की प्रतीक्षा पियाजे के अधिक निकट है।"},
  {"id":"cdp-child-development-468","question":"Consider these statements about ‘scaffolding’. 1. The term was introduced by Wood, Bruner and Ross (1976) to describe how a tutor helps a child, and it is closely linked with Vygotsky’s ZPD. 2. Vygotsky himself used the word ‘scaffolding’ throughout his writings on the ZPD. Which is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Wood, Bruner and Ross coined the metaphor in their 1976 study of tutoring; it is used to describe help within Vygotsky’s ZPD, but the word itself does not come from Vygotsky.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"‘पाड़’ (scaffolding) के बारे में इन कथनों पर विचार कीजिए। 1. यह पद वुड, ब्रूनर और रॉस (1976) ने यह वर्णन करने के लिए प्रस्तुत किया कि शिक्षक बच्चे की कैसे मदद करता है, और यह वाइगोत्स्की के ZPD से निकटता से जुड़ा है। 2. वाइगोत्स्की ने स्वयं ZPD पर अपने लेखन में ‘पाड़’ शब्द का उपयोग किया। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"वुड, ब्रूनर और रॉस ने 1976 में अपने शिक्षण-अध्ययन में यह रूपक गढ़ा; इसका उपयोग वाइगोत्स्की के ZPD के भीतर सहायता का वर्णन करने के लिए होता है, पर यह शब्द स्वयं वाइगोत्स्की से नहीं आता।"},
  {"id":"cdp-child-development-469","question":"In a pottery family in Khurja, a girl first fetches clay, then shapes small pots while her mother finishes the rims, and finally makes whole pots herself as the adults step back. This learning is best described by:","options":["Operant conditioning with a fixed schedule of reinforcement by adults","Guided participation in a cultural activity, a sociocultural idea","Piaget’s spontaneous discovery without adult involvement","Bruner’s symbolic mode of representation in craft"],"answer":1,"explanation":"She learns by taking increasing responsibility in a real activity alongside skilled adults, which is guided participation or apprenticeship in the sociocultural tradition. Adults are central here, so it is not solitary discovery.","difficulty":"hard","source":"CTET · State TETs","questionHi":"खुर्जा के एक कुम्हार परिवार में एक लड़की पहले मिट्टी लाती है, फिर छोटे बर्तन गढ़ती है जबकि उसकी माँ किनारे पूरे करती है, और अंत में पूरे बर्तन स्वयं बनाती है जब वयस्क पीछे हट जाते हैं। इस अधिगम का सबसे अच्छा वर्णन किससे होता है?","optionsHi":["वयस्कों द्वारा पुनर्बलन की निश्चित अनुसूची के साथ क्रियाप्रसूत अनुबंधन","सांस्कृतिक गतिविधि में निर्देशित सहभागिता, एक सामाजिक-सांस्कृतिक विचार","वयस्कों की भागीदारी के बिना पियाजे की स्वतःस्फूर्त खोज","शिल्प में ब्रूनर का सांकेतिक निरूपण-प्रकार"],"explanationHi":"वह कुशल वयस्कों के साथ एक वास्तविक गतिविधि में बढ़ती जिम्मेदारी लेकर सीखती है, जो सामाजिक-सांस्कृतिक परंपरा में निर्देशित सहभागिता या प्रशिक्षुता है। यहाँ वयस्क केंद्रीय हैं, इसलिए यह एकाकी खोज नहीं है।"},
  {"id":"cdp-child-development-470","question":"Which statement about Vygotsky’s theory is correct?","options":["It proposes four fixed, universal stages of cognitive development","It holds that development must be complete before learning can occur","It treats the child as a lone scientist who constructs knowledge without help","It predicts that children in different cultures may develop different skills"],"answer":3,"explanation":"Because development depends on cultural tools and social interaction, Vygotsky’s theory expects cultural differences in thinking. The other options describe Piaget or misstate both theories.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"वाइगोत्स्की के सिद्धांत के बारे में कौन-सा कथन सही है?","optionsHi":["यह संज्ञानात्मक विकास की चार निश्चित, सार्वभौमिक अवस्थाएँ प्रस्तावित करता है","यह मानता है कि अधिगम होने से पहले विकास पूर्ण होना चाहिए","यह बच्चे को अकेले वैज्ञानिक की तरह देखता है जो बिना सहायता के ज्ञान का निर्माण करता है","यह भविष्यवाणी करता है कि विभिन्न संस्कृतियों के बच्चे भिन्न कौशल विकसित कर सकते हैं"],"explanationHi":"चूँकि विकास सांस्कृतिक उपकरणों और सामाजिक अंतःक्रिया पर निर्भर करता है, वाइगोत्स्की का सिद्धांत चिंतन में सांस्कृतिक अंतरों की अपेक्षा करता है। अन्य विकल्प पियाजे का वर्णन करते हैं या दोनों सिद्धांतों को गलत ढंग से प्रस्तुत करते हैं।"},
  {"id":"cdp-child-development-471","question":"For a group activity on reading a map, which grouping would Vygotsky most likely recommend?","options":["Mixed groups where each child works with someone a little more skilled","Groups of children with identical ability, so that no one dominates the task","Each child working alone, so that the teacher can see individual effort","The best readers grouped together so that they are not held back by others"],"answer":0,"explanation":"Working with a slightly more capable peer lets a child perform within her ZPD with help. Equal-ability or solo grouping removes the more knowledgeable other.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"मानचित्र पढ़ने की एक समूह गतिविधि के लिए वाइगोत्स्की किस समूहीकरण की सबसे अधिक अनुशंसा करते?","optionsHi":["मिश्रित समूह जहाँ प्रत्येक बच्चा किसी थोड़े अधिक कुशल के साथ काम करे","समान योग्यता वाले बच्चों के समूह, ताकि कोई कार्य पर हावी न हो","प्रत्येक बच्चा अकेले काम करे, ताकि शिक्षक वैयक्तिक प्रयास देख सके","सबसे अच्छे पाठक एक साथ समूहित हों ताकि वे दूसरों से रुके न रहें"],"explanationHi":"थोड़े अधिक सक्षम साथी के साथ काम करना बच्चे को सहायता के साथ अपने ZPD के भीतर प्रदर्शन करने देता है। समान योग्यता या अकेले का समूहीकरण अधिक जानकार अन्य को हटा देता है।"},
  {"id":"cdp-child-development-472","question":"A Class 3 teacher shows children how to measure the classroom with a metre scale, then asks them to measure the corridor in pairs while she asks guiding questions, and finally asks each child to measure her own desk. Which statement best explains her approach?","options":["She is following Piaget, because she lets each child discover length alone from the start","She is using Skinner’s programmed learning with immediate reinforcement","She is using Bruner’s iconic mode only","She is moving the children from assisted to independent performance, as Vygotsky advised"],"answer":3,"explanation":"Modelling, then guided pair work, then independent work is the gradual transfer of responsibility at the heart of Vygotskian teaching. Nothing here involves reinforcement schedules or solitary discovery.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 3 की एक शिक्षिका बच्चों को मीटर पैमाने से कक्षा नापना दिखाती है, फिर उनसे जोड़ियों में गलियारा नापने को कहती है जबकि वह मार्गदर्शक प्रश्न पूछती है, और अंत में हर बच्चे से अपनी मेज़ नापने को कहती है। कौन-सा कथन उसके उपागम को सबसे अच्छी तरह समझाता है?","optionsHi":["वह पियाजे का अनुसरण कर रही है, क्योंकि वह शुरू से ही हर बच्चे को अकेले लंबाई खोजने देती है","वह तत्काल पुनर्बलन के साथ स्किनर के अभिक्रमित अधिगम का उपयोग कर रही है","वह केवल ब्रूनर के प्रतिबिंबात्मक प्रकार का उपयोग कर रही है","वह बच्चों को सहायता-प्राप्त से स्वतंत्र प्रदर्शन की ओर ले जा रही है, जैसा वाइगोत्स्की ने सुझाया"],"explanationHi":"आदर्श-प्रस्तुति, फिर निर्देशित जोड़ी कार्य, फिर स्वतंत्र कार्य जिम्मेदारी का वह क्रमिक अंतरण है जो वाइगोत्स्कीय शिक्षण के केंद्र में है। यहाँ पुनर्बलन अनुसूचियों या एकाकी खोज का कुछ नहीं है।"},
  {"id":"cdp-child-development-473","question":"A Class 7 student solves a long-division problem while muttering, ‘Bring down the 4... how many 7s in 34? four...’. The teacher asks the class to stay completely silent during practice, and her errors increase. From Vygotsky’s viewpoint, the most likely reason is that:","options":["Silence is always harmful to every kind of learning","She is still at the pre-operational stage of thought","Her private speech was regulating a multi-step task","The teacher should have given her a reward for speaking"],"answer":2,"explanation":"Older children and even adults return to audible private speech on demanding tasks; it organises their steps. Banning it can remove a useful self-regulation tool, which says nothing about her Piagetian stage.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 7 की एक विद्यार्थी लंबा भाग का सवाल हल करते हुए बुदबुदाती है, ‘4 नीचे लाओ… 34 में 7 कितनी बार? चार…’। शिक्षिका कक्षा से अभ्यास के दौरान पूरी तरह चुप रहने को कहती है, और उसकी गलतियाँ बढ़ जाती हैं। वाइगोत्स्की के दृष्टिकोण से सबसे संभावित कारण क्या है?","optionsHi":["हर प्रकार के अधिगम के लिए चुप्पी हमेशा हानिकारक होती है","वह अभी चिंतन की पूर्व-संक्रियात्मक अवस्था में है","उसकी निजी वाक् एक बहु-चरणीय कार्य का नियमन कर रही थी","शिक्षिका को उसे बोलने के लिए पुरस्कार देना चाहिए था"],"explanationHi":"बड़े बच्चे और वयस्क भी माँग वाले कार्यों पर श्रव्य निजी वाक् की ओर लौटते हैं; वह उनके चरणों को व्यवस्थित करती है। उस पर रोक एक उपयोगी आत्म-नियमन उपकरण हटा सकती है, जिसका उसकी पियाजेयाई अवस्था से कोई संबंध नहीं।"},
  {"id":"cdp-child-development-474","question":"Assertion (A): Vygotsky would see a teacher’s explanation as unhelpful if a child cannot use it even with prompting. Reason (R): Instruction that falls beyond the upper limit of a child’s zone of proximal development cannot be taken up by the child.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The ZPD has an upper boundary: tasks beyond what the child can do even with help are not yet learnable. So explanation pitched there does not help, which is why R explains A.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"अभिकथन (A): यदि बच्चा संकेत देने पर भी शिक्षक की व्याख्या का उपयोग नहीं कर पाता, तो वाइगोत्स्की उसे अनुपयोगी मानते। कारण (R): जो अनुदेशन बच्चे के निकटस्थ विकास के क्षेत्र की ऊपरी सीमा से परे पड़ता है, उसे बच्चा ग्रहण नहीं कर सकता।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"ZPD की एक ऊपरी सीमा होती है: जो कार्य बच्चा सहायता से भी नहीं कर सकता, वे अभी सीखने योग्य नहीं हैं। इसलिए वहाँ लक्षित व्याख्या मदद नहीं करती, इसीलिए R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-475","question":"Which classroom statement about language best reflects Vygotsky’s view?","options":["‘Children must master concepts first; the words can be taught after that.’","‘Talking about a problem with others helps children reorganise their thinking.’","‘Children should stay silent so that language does not interfere with thought.’","‘Language develops only from imitation and from reinforcement by adults.’"],"answer":1,"explanation":"For Vygotsky, language is the chief tool of thought, and dialogue reshapes how children think. The first option is closer to Piaget and the last to Skinner.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"भाषा के बारे में कक्षा का कौन-सा कथन वाइगोत्स्की के दृष्टिकोण को सबसे अच्छी तरह दर्शाता है?","optionsHi":["‘बच्चों को पहले अवधारणाओं में निपुण होना चाहिए; शब्द उसके बाद सिखाए जा सकते हैं।’","‘किसी समस्या पर दूसरों के साथ बात करना बच्चों को अपने चिंतन को पुनर्गठित करने में मदद करता है।’","‘बच्चों को चुप रहना चाहिए ताकि भाषा चिंतन में बाधा न डाले।’","‘भाषा केवल अनुकरण और वयस्कों द्वारा पुनर्बलन से विकसित होती है।’"],"explanationHi":"वाइगोत्स्की के लिए भाषा चिंतन का प्रमुख उपकरण है, और संवाद बच्चों के सोचने के ढंग को नया आकार देता है। पहला विकल्प पियाजे के अधिक निकट है और अंतिम स्किनर के।"},
  {"id":"cdp-child-development-476","question":"Discussing the Heinz dilemma in a Class 8 value-education period, four students argue that Heinz should steal the drug. Whose reasoning reflects Kohlberg’s Stage 3?","options":["Seema: ‘His wife will cook for him and look after him once she is well again, so it pays.’","Rohan: ‘A loving husband would do it; people would think him heartless if he let her die.’","Aditi: ‘The right to life comes before property, and any fair society should recognise that.’","Kunal: ‘If he lets her die he could land in trouble; the police might even question him.’"],"answer":1,"explanation":"Stage 3 reasoning centres on being a ‘good’ person in others’ eyes and on loving relationships. Seema’s is an exchange of favours (Stage 2), Kunal’s is avoiding punishment (Stage 1), Aditi’s appeals to rights (Stage 5).","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 के मूल्य-शिक्षा पीरियड में हाइंज की दुविधा पर चर्चा करते हुए चार विद्यार्थी तर्क देते हैं कि हाइंज को दवा चुरानी चाहिए। किसका तर्क कोहलबर्ग के चरण 3 को दर्शाता है?","optionsHi":["सीमा: ‘उसकी पत्नी ठीक होने के बाद उसके लिए खाना बनाएगी और उसकी देखभाल करेगी, इसलिए फायदा है।’","रोहन: ‘प्यार करने वाला पति ऐसा करेगा; अगर वह उसे मरने देता तो लोग उसे हृदयहीन समझते।’","अदिति: ‘जीवन का अधिकार संपत्ति से पहले आता है, और किसी भी न्यायपूर्ण समाज को यह मानना चाहिए।’","कुणाल: ‘अगर वह उसे मरने देता है तो मुसीबत में पड़ सकता है; पुलिस उससे पूछताछ भी कर सकती है।’"],"explanationHi":"चरण 3 का तर्क दूसरों की नज़र में ‘अच्छा’ व्यक्ति होने और प्रेमपूर्ण संबंधों पर केंद्रित होता है। सीमा का तर्क एहसानों का विनिमय है (चरण 2), कुणाल का दंड से बचना है (चरण 1), अदिति का अधिकारों की बात करता है (चरण 5)।"},
  {"id":"cdp-child-development-477","question":"A Class 10 student argues in the school council: ‘The rule that only boys can join the cricket team was made by agreement; rules exist to serve all students fairly, so we should vote to change it.’ In Kohlberg’s scheme this reasoning belongs to:","options":["Stage 4: law and order and social system","Stage 3: good boy–good girl orientation","Stage 5: social contract and rights","Stage 6: universal ethical principles"],"answer":2,"explanation":"Seeing rules as social agreements that should be revised democratically when they fail to serve people’s rights is Stage 5. Stage 4 would treat the existing rule as binding simply to maintain order.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 10 का एक विद्यार्थी विद्यालय परिषद में तर्क देता है: ‘केवल लड़के ही क्रिकेट टीम में शामिल हो सकते हैं, यह नियम सहमति से बना था; नियम सभी विद्यार्थियों की निष्पक्ष सेवा के लिए होते हैं, इसलिए हमें इसे बदलने के लिए मतदान करना चाहिए।’ कोहलबर्ग की योजना में यह तर्क किसका है?","optionsHi":["चरण 4: कानून और व्यवस्था तथा सामाजिक तंत्र","चरण 3: अच्छा लड़का–अच्छी लड़की अभिविन्यास","चरण 5: सामाजिक अनुबंध और अधिकार","चरण 6: सार्वभौमिक नैतिक सिद्धांत"],"explanationHi":"नियमों को ऐसे सामाजिक समझौते के रूप में देखना जिन्हें लोगों के अधिकारों की पूर्ति न करने पर लोकतांत्रिक ढंग से संशोधित किया जाना चाहिए, चरण 5 है। चरण 4 मौजूदा नियम को केवल व्यवस्था बनाए रखने के लिए बाध्यकारी मानता।"},
  {"id":"cdp-child-development-478","question":"A teacher grades her students’ moral development by counting how many said Heinz should NOT steal the drug: the more who said ‘no’, the higher she rates the class. What is the basic flaw, from Kohlberg’s standpoint?","options":["Kohlberg’s stages are judged by the reasoning given, not by the decision","Saying ‘steal’ is always the higher-stage answer to the Heinz dilemma","Moral development can only be measured by observing actual behaviour","The Heinz dilemma is meant for adults, not for adolescents in school"],"answer":0,"explanation":"The same decision can come from Stage 1 fear or Stage 4 respect for law; Kohlberg scored the justification. No answer, steal or not steal, is in itself higher.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"एक शिक्षिका अपने विद्यार्थियों के नैतिक विकास को यह गिनकर ग्रेड देती है कि कितनों ने कहा कि हाइंज को दवा नहीं चुरानी चाहिए: जितने अधिक ने ‘नहीं’ कहा, वह कक्षा को उतना ऊँचा आँकती है। कोहलबर्ग के दृष्टिकोण से मूल दोष क्या है?","optionsHi":["कोहलबर्ग के चरण दिए गए तर्क से आँके जाते हैं, निर्णय से नहीं","हाइंज की दुविधा में ‘चुराओ’ कहना हमेशा उच्च चरण का उत्तर है","नैतिक विकास केवल वास्तविक व्यवहार देखकर ही मापा जा सकता है","हाइंज की दुविधा वयस्कों के लिए है, विद्यालय के किशोरों के लिए नहीं"],"explanationHi":"एक ही निर्णय चरण 1 के भय या चरण 4 के कानून के सम्मान से आ सकता है; कोहलबर्ग ने औचित्य को अंक दिए। कोई भी उत्तर, चुराना या न चुराना, अपने आप में उच्च नहीं है।"},
  {"id":"cdp-child-development-479","question":"Following Kohlberg and the work of Blatt, a teacher wants to move a class that reasons mostly at Stage 2 to higher reasoning. Which strategy is most likely to work?","options":["Lecture them on Stage 6 universal principles of justice every day in assembly","Punish selfish behaviour strictly so that they learn the rules of the class","Reward obedient students with stars so that others copy their behaviour","Hold dilemma discussions where they meet reasoning one stage above their own"],"answer":3,"explanation":"Exposure to reasoning slightly above one’s own (‘plus one’) creates productive conflict and is understood; reasoning far above (Stage 6) is not grasped, and punishments or rewards only reinforce Stage 1–2 thinking.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कोहलबर्ग और ब्लैट के कार्य का अनुसरण करते हुए, एक शिक्षिका चरण 2 पर मुख्यतः तर्क करने वाली कक्षा को उच्चतर तर्क तक ले जाना चाहती है। कौन-सी रणनीति सबसे अधिक कारगर होगी?","optionsHi":["उन्हें हर दिन सभा में चरण 6 के न्याय के सार्वभौमिक सिद्धांतों पर व्याख्यान देना","स्वार्थी व्यवहार को कड़ाई से दंडित करना ताकि वे कक्षा के नियम सीखें","आज्ञाकारी विद्यार्थियों को सितारों से पुरस्कृत करना ताकि दूसरे उनके व्यवहार की नकल करें","दुविधा-चर्चाएँ आयोजित करना जिनमें वे अपने से एक चरण ऊपर के तर्क से मिलें"],"explanationHi":"अपने से थोड़ा ऊपर के तर्क के संपर्क में आना (‘प्लस वन’) उत्पादक टकराव पैदा करता है और समझा जाता है; बहुत ऊपर के तर्क (चरण 6) को ग्रहण नहीं किया जाता, और दंड या पुरस्कार केवल चरण 1–2 के चिंतन को पुष्ट करते हैं।"},
  {"id":"cdp-child-development-480","question":"Assertion (A): A student whose moral reasoning is at Stage 2 cannot move directly to Stage 4 without passing through Stage 3. Reason (R): Kohlberg held that his stages form an invariant sequence.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Kohlberg’s stages are hierarchical and invariant: each must be passed through in order, and none is skipped, so R explains A.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"अभिकथन (A): जिस विद्यार्थी का नैतिक तर्क चरण 2 पर है, वह चरण 3 से गुज़रे बिना सीधे चरण 4 तक नहीं जा सकता। कारण (R): कोहलबर्ग का मत था कि उनके चरण एक अपरिवर्तनीय क्रम बनाते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"कोहलबर्ग के चरण पदानुक्रमित और अपरिवर्तनीय हैं: प्रत्येक से क्रम में गुज़रना होता है, और कोई छोड़ा नहीं जाता, इसलिए R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-481","question":"In a dilemma discussion, Neha argues cogently that cheating is wrong because exams must be fair to everyone and rules keep the system running. A week later she copies during an unsupervised test. Which criticism of Kohlberg’s theory does this illustrate?","options":["The theory ignores the role of culture in moral thinking","Moral reasoning does not always predict moral behaviour","The stages do not follow an invariant sequence","The theory is based on a sample of girls only"],"answer":1,"explanation":"Kohlberg studied moral reasoning; critics note the gap between what people reason and what they actually do. The original sample was of boys, not girls.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक दुविधा-चर्चा में नेहा सुस्पष्टता से तर्क देती है कि नकल करना गलत है क्योंकि परीक्षाएँ सबके लिए निष्पक्ष होनी चाहिए और नियम व्यवस्था को चलाए रखते हैं। एक सप्ताह बाद वह बिना निगरानी वाली परीक्षा में नकल करती है। यह कोहलबर्ग के सिद्धांत की किस आलोचना को दर्शाता है?","optionsHi":["सिद्धांत नैतिक चिंतन में संस्कृति की भूमिका की उपेक्षा करता है","नैतिक तर्क हमेशा नैतिक व्यवहार का पूर्वानुमान नहीं देता","चरण एक अपरिवर्तनीय क्रम का पालन नहीं करते","सिद्धांत केवल लड़कियों के नमूने पर आधारित है"],"explanationHi":"कोहलबर्ग ने नैतिक तर्क का अध्ययन किया; आलोचक इस अंतर को नोट करते हैं कि लोग क्या तर्क करते हैं और वास्तव में क्या करते हैं। मूल नमूना लड़कों का था, लड़कियों का नहीं।"},
  {"id":"cdp-child-development-482","question":"Match the student statements with Kohlberg’s stages: P. ‘I returned the extra change so the shopkeeper would give me a discount next time.’ Q. ‘I returned it because a good student doesn’t keep what isn’t his; my parents would be ashamed.’ R. ‘I returned it because if people kept extra change, trust in trade would collapse.’ S. ‘I returned it because every person deserves to be treated honestly, whatever the law says.’","options":["P-2, Q-3, R-4, S-6","P-1, Q-3, R-5, S-6","P-2, Q-4, R-3, S-5","P-1, Q-2, R-4, S-5"],"answer":0,"explanation":"P is instrumental exchange (Stage 2), Q seeks approval as a ‘good’ person (Stage 3), R maintains the social system (Stage 4), S appeals to a self-chosen universal principle (Stage 6).","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"विद्यार्थियों के कथनों का मिलान कोहलबर्ग के चरणों से कीजिए: P. ‘मैंने अतिरिक्त खुले पैसे लौटा दिए ताकि दुकानदार अगली बार मुझे छूट दे।’ Q. ‘मैंने उन्हें इसलिए लौटाया क्योंकि अच्छा विद्यार्थी वह नहीं रखता जो उसका नहीं है; मेरे माता-पिता को शर्म आती।’ R. ‘मैंने उन्हें इसलिए लौटाया क्योंकि अगर लोग अतिरिक्त खुले पैसे रखने लगें, तो व्यापार में भरोसा ढह जाएगा।’ S. ‘मैंने उन्हें इसलिए लौटाया क्योंकि हर व्यक्ति के साथ ईमानदारी से व्यवहार होना चाहिए, कानून चाहे जो कहे।’","optionsHi":["P-2, Q-3, R-4, S-6","P-1, Q-3, R-5, S-6","P-2, Q-4, R-3, S-5","P-1, Q-2, R-4, S-5"],"explanationHi":"P साधनात्मक विनिमय है (चरण 2), Q ‘अच्छे’ व्यक्ति के रूप में स्वीकृति चाहता है (चरण 3), R सामाजिक तंत्र को बनाए रखता है (चरण 4), S स्वयं चुने सार्वभौमिक सिद्धांत की बात करता है (चरण 6)।"},
  {"id":"cdp-child-development-483","question":"A six-year-old says breaking his father’s phone was wrong ‘because Papa will beat me’. When asked if it would still be wrong if Papa never found out, he says, ‘Then it’s okay.’ This reasoning is typical of:","options":["Stage 2: instrumental exchange","Stage 3: interpersonal conformity","Stage 4: law and order","Stage 1: obedience and punishment"],"answer":3,"explanation":"At Stage 1 an act is wrong because it is punished; if no punishment follows, it is not seen as wrong. Stage 2 would weigh what the child gains in an exchange.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"छह वर्ष का एक बच्चा कहता है कि पापा का फोन तोड़ना गलत था ‘क्योंकि पापा मुझे मारेंगे’। यह पूछे जाने पर कि क्या यह तब भी गलत होता अगर पापा को कभी पता न चलता, वह कहता है, ‘तब तो ठीक है।’ यह तर्क किसकी विशिष्टता है?","optionsHi":["चरण 2: साधनात्मक विनिमय","चरण 3: पारस्परिक अनुरूपता","चरण 4: कानून और व्यवस्था","चरण 1: आज्ञापालन और दंड"],"explanationHi":"चरण 1 में कोई कार्य इसलिए गलत है क्योंकि उसके लिए दंड मिलता है; यदि कोई दंड नहीं मिलता, तो वह गलत नहीं माना जाता। चरण 2 में बच्चा विनिमय में अपने लाभ को तौलता।"},
  {"id":"cdp-child-development-484","question":"A Class 9 girl learns that her close friend took money from the class fund. She decides to tell the teacher: ‘The class fund works only if its rules apply to everyone; if friends cover for each other, the whole system fails.’ Her reasoning reflects:","options":["Stage 3, because she is concerned about her friend's character","Stage 5, because she is thinking of the welfare of all","Stage 4, because she upholds rules to maintain the system","Stage 2, because she gains nothing by staying silent"],"answer":2,"explanation":"Upholding rules because the system depends on them is Stage 4 (law and order). Stage 5 would treat rules as revisable agreements serving rights, which she does not mention.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"कक्षा 9 की एक लड़की को पता चलता है कि उसकी करीबी सहेली ने कक्षा-निधि से पैसे लिए। वह शिक्षिका को बताने का निर्णय लेती है: ‘कक्षा-निधि तभी चलती है जब उसके नियम सब पर लागू हों; अगर दोस्त एक-दूसरे को बचाएँ, तो पूरी व्यवस्था विफल हो जाती है।’ उसका तर्क किसे दर्शाता है?","optionsHi":["चरण 3, क्योंकि वह अपनी सहेली के चरित्र के बारे में चिंतित है","चरण 5, क्योंकि वह सबके कल्याण के बारे में सोच रही है","चरण 4, क्योंकि वह व्यवस्था बनाए रखने के लिए नियमों को कायम रखती है","चरण 2, क्योंकि चुप रहने से उसे कुछ हासिल नहीं होता"],"explanationHi":"नियमों को इसलिए कायम रखना क्योंकि व्यवस्था उन पर निर्भर है, चरण 4 (कानून और व्यवस्था) है। चरण 5 नियमों को अधिकारों की सेवा करने वाले संशोधन-योग्य समझौते मानता, जिसका वह उल्लेख नहीं करती।"},
  {"id":"cdp-child-development-485","question":"Which feature is common to Kohlberg’s Stages 3 and 4 and distinguishes them from Stages 1–2?","options":["Morality is judged by physical consequences such as punishment or reward","Moral standards are those of family, group or society, taken on and lived up to","Moral principles are self-chosen and may override the law of the land","Right action is whatever satisfies one’s own needs in a fair exchange"],"answer":1,"explanation":"At the conventional level (Stages 3–4) people conform to and uphold the expectations of family, group or society. Physical consequences and self-interest mark the preconventional level; self-chosen principles mark the postconventional.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कोहलबर्ग के चरण 3 और 4 में कौन-सी विशेषता साझा है जो उन्हें चरण 1–2 से अलग करती है?","optionsHi":["नैतिकता का निर्णय दंड या पुरस्कार जैसे भौतिक परिणामों से होता है","नैतिक मानक परिवार, समूह या समाज के होते हैं, जिन्हें अपनाया और निभाया जाता है","नैतिक सिद्धांत स्वयं चुने होते हैं और देश के कानून को भी अधिलंघित कर सकते हैं","सही कार्य वह है जो निष्पक्ष विनिमय में अपनी आवश्यकताएँ पूरी करे"],"explanationHi":"परंपरागत स्तर (चरण 3–4) पर लोग परिवार, समूह या समाज की अपेक्षाओं के अनुरूप चलते हैं और उन्हें कायम रखते हैं। भौतिक परिणाम और स्वार्थ पूर्व-परंपरागत स्तर की पहचान हैं; स्वयं चुने सिद्धांत उत्तर-परंपरागत स्तर की।"},
  {"id":"cdp-child-development-486","question":"A school wants to promote moral development along the lines Kohlberg recommended. Which practice fits best?","options":["Daily moral lectures and value slogans painted on the walls of every classroom","Strict punishment for every rule broken, so that students learn self-control","Discussing real dilemmas in which students justify views and hear others’ reasons","Prizes for the most obedient student of the month, announced at assembly"],"answer":2,"explanation":"Kohlberg saw moral growth as arising from cognitive conflict and perspective-taking, fostered by dilemma discussion and democratic ‘just community’ practices, not by preaching or reward and punishment.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक विद्यालय कोहलबर्ग द्वारा अनुशंसित ढंग से नैतिक विकास को बढ़ावा देना चाहता है। कौन-सी पद्धति सबसे अधिक उपयुक्त है?","optionsHi":["हर कक्षा की दीवारों पर रंगे दैनिक नैतिक व्याख्यान और मूल्य-नारे","हर टूटे नियम के लिए कठोर दंड, ताकि विद्यार्थी आत्म-नियंत्रण सीखें","वास्तविक दुविधाओं पर चर्चा करना जिनमें विद्यार्थी अपने विचारों का औचित्य बताएँ और दूसरों के कारण सुनें","माह के सबसे आज्ञाकारी विद्यार्थी को सभा में घोषित पुरस्कार"],"explanationHi":"कोहलबर्ग नैतिक वृद्धि को संज्ञानात्मक टकराव और दृष्टिकोण-ग्रहण से उत्पन्न मानते थे, जिसे दुविधा-चर्चा और लोकतांत्रिक ‘न्यायपूर्ण समुदाय’ प्रथाएँ बढ़ावा देती हैं, उपदेश या पुरस्कार-दंड से नहीं।"},
  {"id":"cdp-child-development-487","question":"Which of these statements about Kohlberg’s theory is INCORRECT?","options":["His original study interviewed boys using hypothetical dilemmas","He built on Piaget’s idea that moral reasoning depends on cognitive development","Most adults, he found, reason at the conventional level","A person’s stage is identified from the action he or she chooses in the dilemma"],"answer":3,"explanation":"Stage is identified from the reasoning, not the chosen action. The other three are accurate: a male sample, a Piagetian base, and most adults at Stages 3–4.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"कोहलबर्ग के सिद्धांत के बारे में इनमें से कौन-सा कथन गलत है?","optionsHi":["उनके मूल अध्ययन में काल्पनिक दुविधाओं का उपयोग करके लड़कों का साक्षात्कार लिया गया","उन्होंने पियाजे के इस विचार पर निर्माण किया कि नैतिक तर्क संज्ञानात्मक विकास पर निर्भर करता है","उन्होंने पाया कि अधिकांश वयस्क परंपरागत स्तर पर तर्क करते हैं","किसी व्यक्ति का चरण उस कार्य से पहचाना जाता है जो वह दुविधा में चुनता है"],"explanationHi":"चरण की पहचान तर्क से होती है, चुने गए कार्य से नहीं। अन्य तीन सही हैं: पुरुष नमूना, पियाजेयाई आधार, और अधिकांश वयस्क चरण 3–4 पर।"},
  {"id":"cdp-child-development-488","question":"A Class 11 student says, ‘If a law forces children to work in factories, it is unjust, and I would break it openly and accept the punishment, because the dignity of every human being matters more than any law.’ According to Kohlberg this is:","options":["Stage 6: universal ethical principles","Stage 4: law and social order","Stage 5: social contract and rights","Stage 3: good boy–good girl orientation"],"answer":0,"explanation":"Acting on a self-chosen universal principle of human dignity, even against the law, while accepting the penalty, is the hallmark of Stage 6. Stage 5 would work to change the law through agreed democratic means.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 11 का एक विद्यार्थी कहता है, ‘अगर कोई कानून बच्चों को कारखानों में काम करने को मजबूर करता है, तो वह अन्यायपूर्ण है, और मैं उसे खुलेआम तोड़ूँगा और सज़ा स्वीकार करूँगा, क्योंकि हर मानव की गरिमा किसी भी कानून से अधिक मायने रखती है।’ कोहलबर्ग के अनुसार यह है:","optionsHi":["चरण 6: सार्वभौमिक नैतिक सिद्धांत","चरण 4: कानून और सामाजिक व्यवस्था","चरण 5: सामाजिक अनुबंध और अधिकार","चरण 3: अच्छा लड़का–अच्छी लड़की अभिविन्यास"],"explanationHi":"मानव गरिमा के स्वयं चुने सार्वभौमिक सिद्धांत पर कार्य करना, कानून के विरुद्ध भी, और दंड को स्वीकार करना, चरण 6 की पहचान है। चरण 5 सहमत लोकतांत्रिक साधनों से कानून को बदलने का प्रयास करता।"},
  {"id":"cdp-child-development-489","question":"‘You helped me with my homework, so I’ll let you copy my drawing.’ ‘It’s fair if we both get the same.’ Such reasoning, common among primary children, belongs to:","options":["Kohlberg’s Stage 1, as the child simply obeys authority to avoid punishment","Kohlberg’s Stage 3, as the child wants to be seen as a good friend","Kohlberg’s Stage 2, as fairness is an equal exchange serving each one’s interest","Kohlberg’s Stage 5, as the child respects a social contract between friends"],"answer":2,"explanation":"Stage 2 treats fairness as a tit-for-tat deal serving each person’s own interests. A ‘contract’ here is not the Stage 5 social contract, which concerns rights and the welfare of society.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"‘तुमने मेरे गृहकार्य में मेरी मदद की, इसलिए मैं तुम्हें अपना चित्र उतारने दूँगा।’ ‘यह निष्पक्ष है अगर हम दोनों को बराबर मिले।’ प्राथमिक बच्चों में आम ऐसा तर्क किसका है?","optionsHi":["कोहलबर्ग का चरण 1, क्योंकि बच्चा दंड से बचने के लिए बस अधिकार का पालन करता है","कोहलबर्ग का चरण 3, क्योंकि बच्चा एक अच्छा मित्र दिखना चाहता है","कोहलबर्ग का चरण 2, क्योंकि निष्पक्षता एक बराबर विनिमय है जो प्रत्येक के हित की सेवा करता है","कोहलबर्ग का चरण 5, क्योंकि बच्चा मित्रों के बीच सामाजिक अनुबंध का सम्मान करता है"],"explanationHi":"चरण 2 निष्पक्षता को जैसे-को-तैसा सौदा मानता है जो प्रत्येक व्यक्ति के अपने हितों की सेवा करता है। यहाँ का ‘अनुबंध’ चरण 5 का सामाजिक अनुबंध नहीं है, जो अधिकारों और समाज के कल्याण से संबंधित है।"},
  {"id":"cdp-child-development-490","question":"Assertion (A): Kohlberg’s highest stages are seldom found in the reasoning of children in primary classes. Reason (R): Postconventional reasoning requires the ability to think abstractly about principles and hypothetical societies.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Kohlberg linked moral stages to cognitive development; principled reasoning needs abstract (formal operational) thought, which primary children generally lack.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"अभिकथन (A): कोहलबर्ग के उच्चतम चरण प्राथमिक कक्षाओं के बच्चों के तर्क में शायद ही पाए जाते हैं। कारण (R): उत्तर-परंपरागत तर्क के लिए सिद्धांतों और काल्पनिक समाजों के बारे में अमूर्त रूप से सोचने की योग्यता आवश्यक है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"कोहलबर्ग ने नैतिक चरणों को संज्ञानात्मक विकास से जोड़ा; सिद्धांत-आधारित तर्क के लिए अमूर्त (औपचारिक संक्रियात्मक) चिंतन चाहिए, जो प्राथमिक बच्चों में सामान्यतः नहीं होता।"},
  {"id":"cdp-child-development-491","question":"Two Class 7 students refuse to join a bunk. Ishaan: ‘My class teacher believes in me; I can’t let her down.’ Farhan: ‘School rules apply to all of us; if everyone bunked, the school couldn’t function.’ Their stages are respectively:","options":["Stage 2 and Stage 3","Stage 3 and Stage 4","Stage 3 and Stage 5","Stage 4 and Stage 3"],"answer":1,"explanation":"Ishaan seeks to live up to a trusted person’s expectations (Stage 3); Farhan upholds rules to keep the system working (Stage 4). Neither mentions rights or revisable agreements, so not Stage 5.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 के दो विद्यार्थी स्कूल से भागने (बंक) में शामिल होने से इनकार करते हैं। ईशान: ‘मेरी कक्षा-शिक्षिका मुझ पर विश्वास करती हैं; मैं उन्हें निराश नहीं कर सकता।’ फरहान: ‘स्कूल के नियम हम सब पर लागू होते हैं; अगर सब बंक करें, तो स्कूल चल नहीं पाएगा।’ उनके चरण क्रमशः हैं:","optionsHi":["चरण 2 और चरण 3","चरण 3 और चरण 4","चरण 3 और चरण 5","चरण 4 और चरण 3"],"explanationHi":"ईशान किसी विश्वसनीय व्यक्ति की अपेक्षाओं पर खरा उतरना चाहता है (चरण 3); फरहान व्यवस्था को चालू रखने के लिए नियमों को कायम रखता है (चरण 4)। दोनों में से कोई अधिकारों या संशोधन-योग्य समझौतों का उल्लेख नहीं करता, इसलिए चरण 5 नहीं।"},
  {"id":"cdp-child-development-492","question":"Which of these statements are correct according to Kohlberg? I. Each stage is a more adequate way of reasoning than the one before. II. A person usually reasons mostly at one stage, with some reasoning at adjacent stages. III. Moral education should directly teach the answers of Stage 6. IV. Reasoning develops through cognitive conflict and social interaction.","options":["I and III only","II and III only","I, II and IV only","I, III and IV only"],"answer":2,"explanation":"Higher stages are more adequate (I), reasoning clusters around one stage (II), and growth comes from conflict and interaction (IV). Stage 6 answers cannot be directly taught (III false); students cannot grasp reasoning far above their own.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कोहलबर्ग के अनुसार इनमें से कौन-से कथन सही हैं? I. प्रत्येक चरण पिछले चरण की तुलना में तर्क करने का अधिक पर्याप्त तरीका है। II. व्यक्ति सामान्यतः मुख्यतः एक चरण पर तर्क करता है, कुछ तर्क आसपास के चरणों पर। III. नैतिक शिक्षा में चरण 6 के उत्तर सीधे सिखाए जाने चाहिए। IV. तर्क संज्ञानात्मक टकराव और सामाजिक अंतःक्रिया से विकसित होता है।","optionsHi":["केवल I और III","केवल II और III","केवल I, II और IV","केवल I, III और IV"],"explanationHi":"उच्च चरण अधिक पर्याप्त हैं (I), तर्क एक चरण के आसपास गुच्छित होता है (II), और वृद्धि टकराव और अंतःक्रिया से आती है (IV)। चरण 6 के उत्तर सीधे नहीं सिखाए जा सकते (III गलत); विद्यार्थी अपने स्तर से बहुत ऊपर के तर्क को ग्रहण नहीं कर सकते।"},
  {"id":"cdp-child-development-493","question":"A Class 4 boy says he did not take another child’s eraser ‘because Sir is standing right there and I would get punished’. His teacher wants to nudge him upward in Kohlberg’s sequence. Which kind of reasoning should she present next in class discussion?","options":["Rules of society must be kept so that order is maintained","Respecting everyone’s rights is a universal principle","Taking without asking is wrong because the Constitution protects property","If you treat others fairly, they will treat you fairly too"],"answer":3,"explanation":"He is at Stage 1; the next stage is Stage 2 reciprocity (‘fair exchange’). Stage 4 or Stage 5–6 arguments are too far ahead for him to assimilate.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 का एक लड़का कहता है कि उसने दूसरे बच्चे का रबर इसलिए नहीं लिया ‘क्योंकि सर वहीं खड़े हैं और मुझे सज़ा मिलती’। उसकी शिक्षिका कोहलबर्ग के क्रम में उसे ऊपर की ओर प्रेरित करना चाहती है। कक्षा-चर्चा में उसे आगे किस तरह का तर्क प्रस्तुत करना चाहिए?","optionsHi":["समाज के नियमों का पालन होना चाहिए ताकि व्यवस्था बनी रहे","सबके अधिकारों का सम्मान एक सार्वभौमिक सिद्धांत है","बिना पूछे लेना गलत है क्योंकि संविधान संपत्ति की रक्षा करता है","अगर तुम दूसरों के साथ निष्पक्ष व्यवहार करोगे, तो वे भी तुम्हारे साथ निष्पक्ष व्यवहार करेंगे"],"explanationHi":"वह चरण 1 पर है; अगला चरण चरण 2 की पारस्परिकता (‘निष्पक्ष विनिमय’) है। चरण 4 या चरण 5–6 के तर्क उसके आत्मसात् करने के लिए बहुत आगे के हैं।"},
  {"id":"cdp-child-development-494","question":"Which of these is the most accurate statement about how Kohlberg collected his data?","options":["He observed children’s actual behaviour in real temptation situations","He presented hypothetical moral dilemmas and analysed the reasons participants gave","He gave children multiple-choice tests of moral knowledge","He used stories comparing accidental and intentional damage to find the age of moral realism"],"answer":1,"explanation":"Kohlberg used the clinical interview with dilemmas such as Heinz and probed reasons. Stories of accidental versus intentional damage were Piaget’s method.","difficulty":"moderate","source":"CTET Paper 2 · State TET","questionHi":"कोहलबर्ग ने अपने आँकड़े कैसे एकत्र किए, इस बारे में इनमें से कौन-सा कथन सबसे सटीक है?","optionsHi":["उन्होंने वास्तविक प्रलोभन की स्थितियों में बच्चों के वास्तविक व्यवहार का अवलोकन किया","उन्होंने काल्पनिक नैतिक दुविधाएँ प्रस्तुत कीं और प्रतिभागियों द्वारा दिए गए कारणों का विश्लेषण किया","उन्होंने बच्चों को नैतिक ज्ञान के बहुविकल्पी परीक्षण दिए","उन्होंने नैतिक यथार्थवाद की आयु जानने के लिए आकस्मिक और जानबूझकर हुए नुकसान की तुलना करने वाली कहानियों का उपयोग किया"],"explanationHi":"कोहलबर्ग ने हाइंज जैसी दुविधाओं के साथ नैदानिक साक्षात्कार का उपयोग किया और कारणों की जाँच की। आकस्मिक बनाम जानबूझकर नुकसान की कहानियाँ पियाजे की विधि थीं।"},
  {"id":"cdp-child-development-495","question":"A Class 12 student argues: ‘Speed limits are agreed by society to protect everyone’s life. A driver rushing a dying patient to hospital may break one, because the law’s own purpose is protecting life; but the rule itself should stand and be applied fairly.’ This shows:","options":["Stage 4, because he insists that the rule itself should stand and be applied fairly","Stage 3, because he is concerned for the patient and the driver","Stage 2, because the driver gains personally from breaking the rule","Stage 5, as he sees law as a social agreement serving people’s rights and welfare"],"answer":3,"explanation":"Judging the law by its purpose (protecting life and welfare) and seeing it as a social agreement is Stage 5. Wanting the rule to remain does not make it Stage 4, which treats rules as binding for order’s sake.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 12 का एक विद्यार्थी तर्क देता है: ‘गति-सीमाएँ समाज द्वारा सबके जीवन की रक्षा के लिए तय की जाती हैं। किसी मरते मरीज़ को अस्पताल पहुँचाने की जल्दी में कोई चालक उसे तोड़ सकता है, क्योंकि कानून का अपना उद्देश्य जीवन की रक्षा करना है; पर नियम स्वयं कायम रहना चाहिए और निष्पक्षता से लागू होना चाहिए।’ यह क्या दर्शाता है?","optionsHi":["चरण 4, क्योंकि वह आग्रह करता है कि नियम स्वयं कायम रहे और निष्पक्षता से लागू हो","चरण 3, क्योंकि वह मरीज़ और चालक के बारे में चिंतित है","चरण 2, क्योंकि नियम तोड़ने से चालक को व्यक्तिगत लाभ होता है","चरण 5, क्योंकि वह कानून को लोगों के अधिकारों और कल्याण की सेवा करने वाला सामाजिक समझौता मानता है"],"explanationHi":"कानून को उसके उद्देश्य (जीवन और कल्याण की रक्षा) से आँकना और उसे सामाजिक समझौता मानना चरण 5 है। नियम का बने रहना चाहना उसे चरण 4 नहीं बनाता, जो नियमों को व्यवस्था की खातिर बाध्यकारी मानता है।"},
  {"id":"cdp-child-development-496","question":"A teacher notices that most of her Class 9 students explain good behaviour with ‘What will people say?’ or ‘Our class has a good name to keep.’ What does Kohlberg’s theory suggest about this?","options":["They are morally backward and need counselling to correct their thinking","Conventional reasoning is normal for adolescents; dilemma discussions can help them grow","They have reached the highest stage possible for their age and nothing more can be done","They are at the postconventional level since they think about society’s view"],"answer":1,"explanation":"Adolescents and most adults reason at the conventional level (approval of others, social order); this is normal, and challenging discussions can nudge growth. Concern for the group’s name is not postconventional.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक शिक्षिका देखती है कि कक्षा 9 के अधिकांश विद्यार्थी अच्छे व्यवहार को ‘लोग क्या कहेंगे?’ या ‘हमारी कक्षा का एक अच्छा नाम बनाए रखना है’ से समझाते हैं। कोहलबर्ग का सिद्धांत इस बारे में क्या सुझाता है?","optionsHi":["वे नैतिक रूप से पिछड़े हैं और अपने चिंतन को सुधारने के लिए उन्हें परामर्श चाहिए","परंपरागत तर्क किशोरों के लिए सामान्य है; दुविधा-चर्चाएँ उन्हें बढ़ने में मदद कर सकती हैं","वे अपनी आयु के लिए संभव उच्चतम चरण तक पहुँच चुके हैं और इससे अधिक कुछ नहीं किया जा सकता","वे उत्तर-परंपरागत स्तर पर हैं क्योंकि वे समाज के दृष्टिकोण के बारे में सोचते हैं"],"explanationHi":"किशोर और अधिकांश वयस्क परंपरागत स्तर पर तर्क करते हैं (दूसरों की स्वीकृति, सामाजिक व्यवस्था); यह सामान्य है, और चुनौतीपूर्ण चर्चाएँ वृद्धि को प्रेरित कर सकती हैं। समूह के नाम की चिंता उत्तर-परंपरागत नहीं है।"},
  {"id":"cdp-child-development-497","question":"Which response to ‘Should Heinz steal the drug?’ is the clearest example of Stage 1 reasoning, whatever answer it gives?","options":["‘No, because the druggist worked hard and deserves to profit from his invention.’","‘Yes, because a husband has a duty to his wife that society expects him to fulfil.’","‘No, because he will be caught and sent to jail.’","‘Yes, because she will repay him by taking care of him later.’"],"answer":2,"explanation":"Stage 1 judges by punishment. Repayment is Stage 2 exchange, society’s expectation of a husband is conventional, and the druggist’s deserved profit reflects rights-based concerns rather than fear.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"‘क्या हाइंज को दवा चुरानी चाहिए?’ का कौन-सा उत्तर चरण 1 के तर्क का सबसे स्पष्ट उदाहरण है, चाहे वह कोई भी उत्तर दे?","optionsHi":["‘नहीं, क्योंकि दवा विक्रेता ने कड़ी मेहनत की और अपने आविष्कार से लाभ पाने का अधिकारी है।’","‘हाँ, क्योंकि पति का अपनी पत्नी के प्रति कर्तव्य है जिसे समाज उससे निभाने की अपेक्षा करता है।’","‘नहीं, क्योंकि वह पकड़ा जाएगा और जेल भेजा जाएगा।’","‘हाँ, क्योंकि वह बाद में उसकी देखभाल करके उसका एहसान चुकाएगी।’"],"explanationHi":"चरण 1 दंड से आँकता है। एहसान चुकाना चरण 2 का विनिमय है, पति से समाज की अपेक्षा परंपरागत है, और दवा विक्रेता का उचित लाभ भय की बजाय अधिकार-आधारित चिंताओं को दर्शाता है।"},
  {"id":"cdp-child-development-498","question":"Assertion (A): Kohlberg advocated running schools as ‘just communities’ where students and teachers make rules democratically. Reason (R): Kohlberg believed that moral development is primarily the result of rewards and punishments given by adults.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Kohlberg did promote just-community schools, but he saw moral growth as cognitive restructuring through participation and discussion, not as conditioning by rewards and punishments; R is false.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): कोहलबर्ग ने विद्यालयों को ‘न्यायपूर्ण समुदायों’ के रूप में चलाने की वकालत की जहाँ विद्यार्थी और शिक्षक लोकतांत्रिक ढंग से नियम बनाते हैं। कारण (R): कोहलबर्ग का मानना था कि नैतिक विकास मुख्यतः वयस्कों द्वारा दिए गए पुरस्कारों और दंडों का परिणाम है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"कोहलबर्ग ने न्यायपूर्ण-समुदाय विद्यालयों को बढ़ावा दिया, पर वे नैतिक वृद्धि को सहभागिता और चर्चा द्वारा संज्ञानात्मक पुनर्गठन मानते थे, पुरस्कार-दंड द्वारा अनुबंधन नहीं; R असत्य है।"},
  {"id":"cdp-child-development-499","question":"After a quarrel during a cricket match, the umpire in a Class 6 game gives a decision against his own team. Asked why, he says, ‘That’s the rule everyone signed up to; if umpires favour their friends, the game becomes meaningless.’ Which stage best fits?","options":["Stage 4","Stage 3","Stage 2","Stage 1"],"answer":0,"explanation":"Upholding the shared rule so that the system (the game) keeps working is Stage 4 law-and-order thinking. He sets aside friendship (Stage 3) and personal gain (Stage 2).","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"क्रिकेट मैच के दौरान झगड़े के बाद, कक्षा 6 के एक खेल में अंपायर अपनी ही टीम के विरुद्ध निर्णय देता है। कारण पूछे जाने पर वह कहता है, ‘यह वह नियम है जिस पर सबने हामी भरी थी; अगर अंपायर अपने दोस्तों का पक्ष लेने लगें, तो खेल निरर्थक हो जाता है।’ कौन-सा चरण सबसे अच्छी तरह मेल खाता है?","optionsHi":["चरण 4","चरण 3","चरण 2","चरण 1"],"explanationHi":"साझा नियम को इसलिए कायम रखना ताकि व्यवस्था (खेल) चलती रहे, चरण 4 का कानून-और-व्यवस्था चिंतन है। वह मित्रता (चरण 3) और व्यक्तिगत लाभ (चरण 2) को किनारे रखता है।"},
  {"id":"cdp-child-development-500","question":"Which of these best describes the difference between Kohlberg’s preconventional and postconventional levels, though both may sometimes reach the same decision to disobey a rule?","options":["Preconventional disobedience rests on self-interest or fear; postconventional, on justice or rights","Preconventional children never disobey rules, while postconventional adults always do","Both levels judge actions by social approval and the wish to be seen as good","Preconventional reasoning is based on abstract principles, while postconventional is based on fear"],"answer":0,"explanation":"A preconventional child may break a rule for personal gain; a postconventional thinker may break it out of principle. Same act, different reasoning, which is exactly what Kohlberg measured.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"इनमें से कौन-सा कोहलबर्ग के पूर्व-परंपरागत और उत्तर-परंपरागत स्तरों के बीच के अंतर का सबसे अच्छा वर्णन करता है, यद्यपि दोनों कभी-कभी किसी नियम की अवज्ञा करने के एक ही निर्णय पर पहुँच सकते हैं?","optionsHi":["पूर्व-परंपरागत अवज्ञा स्वार्थ या भय पर आधारित है; उत्तर-परंपरागत, न्याय या अधिकारों पर","पूर्व-परंपरागत बच्चे कभी नियमों की अवज्ञा नहीं करते, जबकि उत्तर-परंपरागत वयस्क हमेशा करते हैं","दोनों स्तर कार्यों का निर्णय सामाजिक स्वीकृति और अच्छा दिखने की इच्छा से करते हैं","पूर्व-परंपरागत तर्क अमूर्त सिद्धांतों पर आधारित है, जबकि उत्तर-परंपरागत भय पर"],"explanationHi":"पूर्व-परंपरागत बच्चा व्यक्तिगत लाभ के लिए नियम तोड़ सकता है; उत्तर-परंपरागत चिंतक सिद्धांत के कारण तोड़ सकता है। कार्य वही, तर्क भिन्न, और ठीक यही कोहलबर्ग ने मापा।"},
  {"id":"cdp-child-development-501","question":"Nikhil, in Class 7, has been assessed as having dyslexia. He understands science concepts well when they are discussed orally. Which arrangement for his term test is most appropriate?","options":["Extra time and a reader, with the paper testing the same competencies as the rest of the class","An easier paper with only one-word answers, since writing long answers is the main thing he finds hard","Exemption from the term test, with promotion decided on the basis of attendance and class conduct","A paper made entirely of multiple-choice questions, to be completed within the same time limit as others"],"answer":0,"explanation":"An accommodation removes the barrier (decoding print, speed) without lowering what is assessed; an easier paper changes the standard, exemption denies assessment, and MCQs still demand fast reading.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 7 के निखिल में डिस्लेक्सिया की पहचान हुई है। जब विज्ञान की अवधारणाओं पर मौखिक चर्चा होती है तो वह उन्हें अच्छी तरह समझ लेता है। उसकी सत्रांत परीक्षा के लिए कौन-सी व्यवस्था सबसे उपयुक्त है?","optionsHi":["अतिरिक्त समय और एक पाठक (रीडर), जबकि प्रश्नपत्र में कक्षा के अन्य बच्चों के समान ही दक्षताओं का परीक्षण हो","केवल एक-शब्द वाले उत्तरों वाला आसान प्रश्नपत्र, क्योंकि लंबे उत्तर लिखना ही उसके लिए सबसे कठिन है","सत्रांत परीक्षा से छूट, और अगली कक्षा में प्रोन्नति का निर्णय उपस्थिति तथा कक्षा में आचरण के आधार पर","पूरी तरह बहुविकल्पीय प्रश्नों वाला प्रश्नपत्र, जिसे अन्य बच्चों के बराबर समय-सीमा में हल करना हो"],"explanationHi":"समायोजन (अकोमोडेशन) बाधा (मुद्रित पाठ को पढ़ना, गति) को दूर करता है और जिसका आकलन हो रहा है उसका स्तर नहीं घटाता; आसान प्रश्नपत्र मानक बदल देता है, छूट आकलन से वंचित करती है, और बहुविकल्पीय प्रश्नों में भी तेज़ पढ़ना ज़रूरी होता है।"},
  {"id":"cdp-child-development-502","question":"Which of the following is a MODIFICATION of the curriculum rather than an accommodation?","options":["A child with intellectual disability works on two-digit addition with objects while the class learns long division","A child with low vision receives exactly the same question paper as the rest of the class, printed in a larger font size","A child with dysgraphia types his answers on a computer instead of writing them by hand on paper","A child with hearing impairment is seated in the front row near the teacher so that she can lip-read"],"answer":0,"explanation":"Accommodations change how a child learns or shows learning; a modification changes what is expected, as when a different, simpler learning goal replaces the class goal.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"निम्नलिखित में से कौन-सा पाठ्यचर्या का संशोधन (मॉडिफिकेशन) है, न कि समायोजन (अकोमोडेशन)?","optionsHi":["बौद्धिक अक्षमता वाला एक बच्चा वस्तुओं की सहायता से दो अंकों का जोड़ सीखता है, जबकि कक्षा लंबा भाग सीख रही है","अल्प दृष्टि वाले बच्चे को कक्षा के अन्य बच्चों जैसा ही प्रश्नपत्र मिलता है, पर बड़े आकार के अक्षरों में छपा हुआ","डिस्ग्राफिया वाला एक बच्चा अपने उत्तर कागज़ पर हाथ से लिखने के बजाय कंप्यूटर पर टाइप करता है","श्रवण-बाधित बच्ची को शिक्षक के पास अगली पंक्ति में बैठाया जाता है ताकि वह होंठों की गति पढ़ सके"],"explanationHi":"समायोजन यह बदलता है कि बच्चा कैसे सीखता है या अपना सीखना कैसे दिखाता है; संशोधन यह बदलता है कि बच्चे से क्या अपेक्षा की जाती है, जैसे कक्षा के लक्ष्य के स्थान पर कोई भिन्न, सरल अधिगम लक्ष्य रखा जाए।"},
  {"id":"cdp-child-development-503","question":"For a Class 2 child with dyslexia who cannot yet link letters with their sounds, which approach is best supported?","options":["Asking him to read harder books silently every day, so that greater exposure to print slowly builds his reading on its own","Making him memorise long lists of whole words by sight, so that he can skip the slow work of decoding sounds","Using coloured overlays on every page as the main remedy, since dyslexia is chiefly a visual problem with print","Explicit, systematic phonics taught multisensorily, such as seeing a letter, saying its sound and tracing it in sand"],"answer":3,"explanation":"Structured, multisensory phonics directly targets the weak sound–symbol link at the heart of dyslexia; more difficult reading, sight-word cramming or overlays do not teach decoding.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 2 के डिस्लेक्सिया से ग्रस्त एक बच्चे के लिए, जो अभी अक्षरों को उनकी ध्वनियों से नहीं जोड़ पाता, कौन-सा उपागम सबसे उपयुक्त है?","optionsHi":["उससे प्रतिदिन कठिन पुस्तकें चुपचाप पढ़ने को कहना, ताकि मुद्रित सामग्री से अधिक संपर्क से उसका पठन धीरे-धीरे अपने आप विकसित हो जाए","उसे पूरे शब्दों की लंबी सूचियाँ देखकर रटवाना, ताकि वह ध्वनियों को पहचानने (डिकोडिंग) का धीमा काम छोड़ सके","हर पृष्ठ पर रंगीन ओवरले को मुख्य उपचार बनाना, क्योंकि डिस्लेक्सिया मुख्यतः मुद्रित पाठ की दृश्य समस्या है","स्पष्ट, क्रमबद्ध ध्वनि-शिक्षण (फोनिक्स) बहु-संवेदी ढंग से कराना, जैसे अक्षर देखना, उसकी ध्वनि बोलना और उसे रेत में उकेरना"],"explanationHi":"संरचित, बहु-संवेदी फोनिक्स डिस्लेक्सिया के केंद्र में स्थित कमज़ोर ध्वनि-प्रतीक संबंध को सीधे लक्षित करता है; अधिक कठिन पठन, दृश्य-शब्द रटाना या ओवरले डिकोडिंग नहीं सिखाते।"},
  {"id":"cdp-child-development-504","question":"Tanvi, a Class 3 student with good vocabulary and reasoning, often bumps into furniture, struggles with buttons and scissors, cannot catch a ball in PE, and copies slowly from the board with poorly formed letters. Her pattern of difficulties most closely matches:","options":["Dyspraxia (developmental coordination disorder)","Dyslexia (specific learning disability in reading)","Dysphasia (developmental language disorder)","Dyscalculia (specific learning disability in mathematics)"],"answer":0,"explanation":"Difficulty in planning and coordinating movement across gross and fine motor tasks, with intact language and reasoning, indicates dyspraxia; poor handwriting here is one part of a wider motor problem.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 3 की तान्वी की शब्दावली और तर्कशक्ति अच्छी है, फिर भी वह प्रायः फर्नीचर से टकरा जाती है, बटन और कैंची चलाने में कठिनाई महसूस करती है, शारीरिक शिक्षा में गेंद नहीं पकड़ पाती और श्यामपट्ट से धीरे-धीरे तथा बिगड़े अक्षरों में नकल करती है। उसकी कठिनाइयों का यह स्वरूप किससे सबसे अधिक मेल खाता है?","optionsHi":["डिस्प्रैक्सिया (विकासात्मक समन्वय विकार)","डिस्लेक्सिया (पठन में विशिष्ट अधिगम अक्षमता)","डिस्फेसिया (विकासात्मक भाषा विकार)","डिस्कैल्कुलिया (गणित में विशिष्ट अधिगम अक्षमता)"],"explanationHi":"भाषा और तर्कशक्ति सामान्य होने पर भी स्थूल तथा सूक्ष्म गामक कार्यों में गति की योजना बनाने और समन्वय करने में कठिनाई डिस्प्रैक्सिया को दर्शाती है; यहाँ खराब लिखावट एक व्यापक गामक समस्या का ही एक भाग है।"},
  {"id":"cdp-child-development-505","question":"Assertion (A): A child can be gifted and also have a specific learning disability at the same time. Reason (R): Both giftedness and learning disability are defined by an IQ score above 130.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"‘Twice-exceptional’ children have high ability along with a learning disability, which often masks both; a learning disability is not defined by high IQ, so R is false.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"अभिकथन (A): कोई बच्चा प्रतिभाशाली होने के साथ-साथ विशिष्ट अधिगम अक्षमता से भी ग्रस्त हो सकता है। कारण (R): प्रतिभाशालिता और अधिगम अक्षमता दोनों 130 से ऊपर के बुद्धिलब्धि (IQ) अंक से परिभाषित होती हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"‘द्वि-असाधारण’ (ट्विस-एक्सेप्शनल) बच्चों में उच्च क्षमता के साथ अधिगम अक्षमता होती है, जो प्रायः दोनों को छिपा देती है; अधिगम अक्षमता उच्च IQ से परिभाषित नहीं होती, इसलिए R असत्य है।"},
  {"id":"cdp-child-development-506","question":"Which of these statements about educating gifted children are correct? I. Skipping a grade is a form of acceleration. II. Enrichment adds depth and breadth to learning without moving the child to a higher class. III. Giving a gifted child extra sums of the same kind after she finishes is meaningful enrichment.","options":["I only","II and III only","I, II and III","I and II only"],"answer":3,"explanation":"Grade skipping is acceleration and enrichment deepens or widens learning; more of the same work is just ‘more’, not enrichment, and gifted children often see it as a penalty for finishing early.","difficulty":"hard","source":"CTET · State TETs","questionHi":"प्रतिभाशाली बच्चों की शिक्षा के बारे में इनमें से कौन-से कथन सही हैं? I. कक्षा छोड़कर आगे बढ़ना त्वरण (एक्सेलरेशन) का एक रूप है। II. संवर्धन (एनरिचमेंट) बच्चे को उच्च कक्षा में भेजे बिना अधिगम में गहराई और विस्तार जोड़ता है। III. प्रतिभाशाली बच्ची के काम पूरा करने के बाद उसे उसी प्रकार के और अधिक प्रश्न देना सार्थक संवर्धन है।","optionsHi":["केवल I","केवल II और III","I, II और III","केवल I और II"],"explanationHi":"कक्षा छोड़ना त्वरण है और संवर्धन अधिगम को गहरा या विस्तृत करता है; उसी तरह का और काम देना केवल ‘अधिक’ काम है, संवर्धन नहीं, और प्रतिभाशाली बच्चे इसे प्रायः जल्दी काम पूरा करने का दंड मानते हैं।"},
  {"id":"cdp-child-development-507","question":"Raju scores about 65 on an IQ test, but he manages daily routines, money for small purchases, friendships and self-care as well as most children his age. Should he be labelled as having intellectual disability?","options":["No; diagnosis also needs significant limits in adaptive behaviour, so the score alone is not enough","Yes; any IQ score below 70 is enough on its own to confirm intellectual disability, whatever his daily functioning","Yes; once a standardised test score is available, adaptive skills no longer need to be considered","No; intellectual disability can only be formally identified after the child turns 18 years of age"],"answer":0,"explanation":"Intellectual disability requires significant limits in both intellectual functioning and adaptive behaviour, starting in the developmental period; a single score without adaptive deficits does not justify the label.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"राजू का IQ परीक्षण में लगभग 65 अंक आता है, परंतु वह दैनिक दिनचर्या, छोटी खरीदारी के लिए पैसों का उपयोग, मित्रता और स्वयं की देखभाल अपनी उम्र के अधिकांश बच्चों जितनी अच्छी तरह कर लेता है। क्या उसे बौद्धिक अक्षमता वाला कहा जाना चाहिए?","optionsHi":["नहीं; निदान के लिए अनुकूली व्यवहार में भी उल्लेखनीय सीमाएँ आवश्यक हैं, इसलिए केवल अंक पर्याप्त नहीं है","हाँ; 70 से कम कोई भी IQ अंक, उसके दैनिक कार्य-कलाप कैसे भी हों, अकेले बौद्धिक अक्षमता की पुष्टि के लिए पर्याप्त है","हाँ; मानकीकृत परीक्षण का अंक उपलब्ध होने पर अनुकूली कौशलों पर विचार करने की आवश्यकता नहीं रहती","नहीं; बौद्धिक अक्षमता की औपचारिक पहचान बच्चे के 18 वर्ष का होने के बाद ही हो सकती है"],"explanationHi":"बौद्धिक अक्षमता के लिए बौद्धिक कार्यप्रणाली तथा अनुकूली व्यवहार, दोनों में उल्लेखनीय सीमाएँ आवश्यक हैं, जो विकासात्मक अवधि में आरंभ हुई हों; अनुकूली कमियों के बिना केवल एक अंक से यह ठप्पा लगाना उचित नहीं है।"},
  {"id":"cdp-child-development-508","question":"In staff-room talk, a teacher refers to her students as ‘the blind one’ and ‘that ADHD boy’. Which response reflects sound inclusive practice?","options":["It is acceptable, since the labels are medically accurate and help colleagues identify which child is meant","It is acceptable as long as the children themselves never hear it, since staff-room talk is private","Teachers should use children's names and mention needs only when relevant, as labels can define a child","Teachers should use labels freely, since naming the condition is the first step to providing support"],"answer":2,"explanation":"Person-first thinking sees the child before the condition; labels used as identities shape how adults treat a child and can lower expectations, whereas needs can be described when they matter.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"स्टाफ-रूम की बातचीत में एक शिक्षिका अपने विद्यार्थियों को ‘वह अंधा बच्चा’ और ‘वह ADHD वाला लड़का’ कहकर संबोधित करती है। कौन-सी प्रतिक्रिया समावेशी शिक्षा के सही व्यवहार को दर्शाती है?","optionsHi":["यह स्वीकार्य है, क्योंकि ये लेबल चिकित्सा की दृष्टि से सटीक हैं और सहकर्मियों को यह पहचानने में मदद करते हैं कि किस बच्चे की बात हो रही है","यह तब तक स्वीकार्य है जब तक बच्चे स्वयं इसे न सुनें, क्योंकि स्टाफ-रूम की बातचीत निजी होती है","शिक्षकों को बच्चों के नाम का प्रयोग करना चाहिए और आवश्यकता होने पर ही उनकी विशेष ज़रूरतों का उल्लेख करना चाहिए, क्योंकि लेबल बच्चे की पहचान बन सकते हैं","शिक्षकों को लेबल खुलकर प्रयोग करने चाहिए, क्योंकि स्थिति का नाम लेना सहायता प्रदान करने का पहला कदम है"],"explanationHi":"व्यक्ति-प्रथम सोच स्थिति से पहले बच्चे को देखती है; पहचान के रूप में प्रयुक्त लेबल वयस्कों के व्यवहार को आकार देते हैं और अपेक्षाएँ घटा सकते हैं, जबकि आवश्यकताओं का वर्णन तब किया जा सकता है जब वे प्रासंगिक हों।"},
  {"id":"cdp-child-development-509","question":"In a village school, some parents ask that their children be seated apart from Dalit classmates during the midday meal. What should the head teacher do?","options":["Quietly agree to the request for now, to avoid conflict in the village and keep all parents sending their children","Let all children choose their own seats, so that the school cannot be blamed for whatever groups form","Serve the meal in two separate shifts, so that both groups of parents are satisfied and no child is forced to mix","Refuse, seat all children together, and explain to parents and the SMC that this discrimination is unconstitutional"],"answer":3,"explanation":"Untouchability is abolished and caste discrimination is prohibited; the school must actively prevent it, and ‘free choice’ or shifts would simply let the segregation continue.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"एक गाँव के विद्यालय में कुछ अभिभावक माँग करते हैं कि मध्याह्न भोजन के समय उनके बच्चों को दलित सहपाठियों से अलग बैठाया जाए। प्रधानाध्यापक को क्या करना चाहिए?","optionsHi":["गाँव में टकराव से बचने और सभी अभिभावकों को बच्चे भेजते रहने के लिए फ़िलहाल चुपचाप माँग मान लेना","सभी बच्चों को अपनी जगह स्वयं चुनने देना, ताकि जो भी समूह बनें उनके लिए विद्यालय को दोषी न ठहराया जा सके","भोजन दो अलग-अलग पालियों में परोसना, ताकि दोनों पक्षों के अभिभावक संतुष्ट रहें और किसी बच्चे को मिलकर बैठने को विवश न होना पड़े","माँग अस्वीकार करना, सभी बच्चों को साथ बैठाना, और अभिभावकों तथा SMC को समझाना कि यह भेदभाव असंवैधानिक है"],"explanationHi":"अस्पृश्यता का उन्मूलन हो चुका है और जातिगत भेदभाव निषिद्ध है; विद्यालय को इसे सक्रिय रूप से रोकना चाहिए, क्योंकि ‘स्वतंत्र चयन’ या पालियाँ अलगाव को ही जारी रहने देंगी।"},
  {"id":"cdp-child-development-510","question":"A Class 4 EVS textbook used in a tribal area of Odisha draws its examples from city life, such as escalators and shopping malls. Children seem disengaged. What should the teacher do?","options":["Teach the examples exactly as given, since the textbook is prescribed and the exam will follow it","Connect the same concepts to the children's own lives, such as forest produce and local festivals","Spend extra time explaining city life first, so that the children understand the textbook's examples","Conclude that tribal children learn more slowly, and reduce the content to suit their pace"],"answer":1,"explanation":"Learning builds on what children already know; drawing on their context makes concepts meaningful and values their culture, while a deficit view or rigid textbook-following alienates them.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"ओडिशा के एक जनजातीय क्षेत्र में प्रयुक्त कक्षा 4 की EVS की पाठ्यपुस्तक अपने उदाहरण शहरी जीवन से लेती है, जैसे एस्केलेटर और शॉपिंग मॉल। बच्चे उदासीन दिखते हैं। शिक्षक को क्या करना चाहिए?","optionsHi":["उदाहरण ठीक वैसे ही पढ़ाना जैसे दिए गए हैं, क्योंकि पाठ्यपुस्तक निर्धारित है और परीक्षा उसी के अनुसार होगी","उन्हीं अवधारणाओं को बच्चों के अपने जीवन से जोड़ना, जैसे वन-उपज और स्थानीय त्योहार","पहले शहरी जीवन समझाने में अतिरिक्त समय लगाना, ताकि बच्चे पाठ्यपुस्तक के उदाहरण समझ सकें","यह निष्कर्ष निकालना कि जनजातीय बच्चे धीमे सीखते हैं, और उनकी गति के अनुरूप सामग्री घटा देना"],"explanationHi":"अधिगम उस ज्ञान पर आधारित होता है जो बच्चों के पास पहले से है; उनके परिवेश से उदाहरण लेना अवधारणाओं को सार्थक बनाता है और उनकी संस्कृति का सम्मान करता है, जबकि अभावग्रस्त दृष्टि या पाठ्यपुस्तक का कठोर अनुसरण उन्हें पराया महसूस कराता है।"},
  {"id":"cdp-child-development-511","question":"In group activities, a Class 5 teacher always makes Sonu, who has an intellectual disability, the child who is helped, while others take turns to explain things to him. Which change would best promote inclusion?","options":["Seating Sonu separately with a helper, so that the groups can move faster and he gets individual attention","Rotating roles so that Sonu also helps others in tasks where he is strong, such as handling materials","Excusing Sonu from group work and giving him colouring, so that he is not stressed by difficult tasks","Letting the brightest child in each group do all the tasks, so that the group's work is of good quality"],"answer":1,"explanation":"Inclusion means being a valued member, not a permanent receiver of help; giving every child roles that use their strengths builds belonging and genuine cooperation.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"समूह गतिविधियों में कक्षा 5 की एक शिक्षिका बौद्धिक अक्षमता वाले सोनू को सदैव वही बच्चा बनाती है जिसकी मदद की जाती है, जबकि अन्य बच्चे बारी-बारी से उसे समझाते हैं। समावेशन को सबसे अधिक बढ़ावा कौन-सा परिवर्तन देगा?","optionsHi":["सोनू को सहायक के साथ अलग बैठाना, ताकि समूह तेज़ी से आगे बढ़ सकें और उसे व्यक्तिगत ध्यान मिले","भूमिकाओं को बारी-बारी से बदलना, ताकि सोनू भी उन कार्यों में दूसरों की मदद करे जिनमें वह सक्षम है, जैसे सामग्री सँभालना","सोनू को समूह कार्य से छूट देकर रंग भरने का काम देना, ताकि वह कठिन कार्यों के तनाव से बचा रहे","प्रत्येक समूह के सबसे होशियार बच्चे को सारे कार्य करने देना, ताकि समूह का कार्य अच्छी गुणवत्ता का हो"],"explanationHi":"समावेशन का अर्थ है मूल्यवान सदस्य होना, न कि स्थायी रूप से सहायता पाने वाला; प्रत्येक बच्चे को ऐसी भूमिकाएँ देना जो उसकी शक्तियों का उपयोग करें, अपनेपन और वास्तविक सहयोग को बढ़ाता है।"},
  {"id":"cdp-child-development-512","question":"Which of the following is the best-written goal for the Individualised Education Plan of a Class 3 child with a reading difficulty?","options":["Rohan will improve his reading a great deal this year and become a much more confident reader","By term end, Rohan will read aloud a 50-word Class 2 level passage with at most 3 errors in 2 of 3 trials","Rohan will try harder, pay attention in reading lessons and practise reading at home every evening","Rohan will complete the full Class 3 reading syllabus by the end of the year, just like his classmates"],"answer":1,"explanation":"A good IEP goal is specific, measurable and time-bound, so progress can be checked; vague hopes or effort-based goals give nothing to measure.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"पठन में कठिनाई वाले कक्षा 3 के बच्चे की वैयक्तिकृत शिक्षा योजना (IEP) के लिए निम्नलिखित में से कौन-सा लक्ष्य सबसे अच्छा लिखा गया है?","optionsHi":["रोहन इस वर्ष अपने पठन में बहुत सुधार करेगा और एक अधिक आत्मविश्वासी पाठक बन जाएगा","सत्र के अंत तक रोहन 50 शब्दों का कक्षा 2 स्तर का गद्यांश अधिकतम 3 त्रुटियों के साथ ज़ोर से पढ़ेगा, प्रयासों में 2 बार (कुल 3 में से)","रोहन अधिक प्रयास करेगा, पठन के पाठों में ध्यान देगा और प्रत्येक शाम घर पर पढ़ने का अभ्यास करेगा","रोहन अपने सहपाठियों की तरह वर्ष के अंत तक कक्षा 3 का पूरा पठन पाठ्यक्रम पूरा कर लेगा"],"explanationHi":"अच्छा IEP लक्ष्य विशिष्ट, मापने योग्य और समयबद्ध होता है, ताकि प्रगति की जाँच की जा सके; अस्पष्ट आशाएँ या प्रयास-आधारित लक्ष्य मापने के लिए कुछ नहीं देते।"},
  {"id":"cdp-child-development-513","question":"Over two terms, a Class 2 teacher notices that one child still struggles to match letters with sounds despite good classroom teaching, though he is quick in oral work. What is the most appropriate step?","options":["Wait until Class 5 before acting, since many children outgrow such early reading problems on their own","Record specific observations, give targeted support, discuss with parents and refer him for assessment","Announce to the class that he has dyslexia, so that his classmates are patient and do not tease him","Keep him back in Class 2 for another year, until he has properly learnt to read like the others"],"answer":1,"explanation":"Early identification with documented evidence and timely intervention is the expected approach; waiting loses precious time, public labelling harms, and retention does not address the cause.","difficulty":"hard","source":"CTET · State TETs","questionHi":"दो सत्रों में कक्षा 2 की शिक्षिका देखती है कि अच्छे कक्षा-शिक्षण के बावजूद एक बच्चा अब भी अक्षरों को ध्वनियों से मिलाने में कठिनाई महसूस करता है, जबकि वह मौखिक कार्य में तेज़ है। सबसे उपयुक्त कदम क्या है?","optionsHi":["कक्षा 5 तक कुछ न करना, क्योंकि कई बच्चे ऐसी प्रारंभिक पठन-समस्याओं से अपने आप उबर जाते हैं","विशिष्ट अवलोकन दर्ज करना, लक्षित सहायता देना, अभिभावकों से चर्चा करना और उसे आकलन के लिए भेजना","कक्षा में घोषणा करना कि उसे डिस्लेक्सिया है, ताकि सहपाठी धैर्य रखें और उसे चिढ़ाएँ नहीं","उसे कक्षा 2 में एक वर्ष और रोक देना, जब तक वह दूसरों की तरह ठीक से पढ़ना न सीख ले"],"explanationHi":"प्रमाणों के अभिलेख के साथ शीघ्र पहचान और समय पर हस्तक्षेप अपेक्षित तरीका है; प्रतीक्षा करने से बहुमूल्य समय नष्ट होता है, सार्वजनिक लेबल लगाना हानिकारक है, और रोके रखना (रिटेंशन) कारण का समाधान नहीं करता।"},
  {"id":"cdp-child-development-514","question":"A teacher is considering whether a child’s reading problem may be a specific learning disability. Which finding would make this LEAST likely and point first to another cause?","options":["The child's difficulty continues even after a full year of good, targeted teaching in small groups","The child missed most of the last two years of school because the family kept migrating for work","The child reasons well and speaks fluently in class but is far behind classmates in reading","The child has normal vision and hearing on screening and no history of any serious illness"],"answer":1,"explanation":"A specific learning disability is suspected when a difficulty is unexpected and persists despite adequate teaching; a long gap in schooling is a lack of opportunity to learn, which must be ruled out first.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक शिक्षक यह विचार कर रहा है कि बच्चे की पठन-समस्या विशिष्ट अधिगम अक्षमता हो सकती है या नहीं। कौन-सा निष्कर्ष इसकी संभावना को सबसे कम करेगा और सर्वप्रथम किसी अन्य कारण की ओर संकेत करेगा?","optionsHi":["एक पूरे वर्ष तक छोटे समूहों में अच्छे, लक्षित शिक्षण के बाद भी बच्चे की कठिनाई बनी रहती है","परिवार के काम के लिए लगातार पलायन करते रहने के कारण बच्चा पिछले दो वर्षों में अधिकांश समय विद्यालय नहीं जा सका","बच्चा तर्क अच्छा करता है और कक्षा में धाराप्रवाह बोलता है, पर पठन में सहपाठियों से बहुत पीछे है","जाँच में बच्चे की दृष्टि और श्रवण सामान्य हैं और किसी गंभीर बीमारी का इतिहास नहीं है"],"explanationHi":"विशिष्ट अधिगम अक्षमता का संदेह तब होता है जब कठिनाई अप्रत्याशित हो और पर्याप्त शिक्षण के बावजूद बनी रहे; विद्यालय से लंबी अनुपस्थिति सीखने के अवसर का अभाव है, जिसे पहले अलग करना चाहिए।"},
  {"id":"cdp-child-development-515","question":"During group discussions, Neha, who has a hearing impairment, keeps losing track of who is speaking. Which set of practices helps her most?","options":["Asking the group to speak louder and faster, so that the discussion finishes before she gets tired","Giving her a written summary of the discussion after class, so she can read what she missed","Seating the group in a circle, one speaker at a time after a raised hand, and key points on the board","Asking a friend sitting beside her to repeat everything the others say directly into her ear"],"answer":2,"explanation":"She needs to see each speaker's face and know who is talking; a circle, turn-taking signals and written key points give her real access, while noise and speed make it worse.","difficulty":"hard","source":"CTET · State TETs","questionHi":"समूह चर्चाओं के दौरान श्रवण-बाधित नेहा यह नहीं समझ पाती कि कौन बोल रहा है। कौन-सी प्रथाएँ उसकी सबसे अधिक सहायता करती हैं?","optionsHi":["समूह से ज़ोर से और तेज़ बोलने को कहना, ताकि उसके थकने से पहले चर्चा समाप्त हो जाए","कक्षा के बाद उसे चर्चा का लिखित सार देना, ताकि वह पढ़ सके कि उससे क्या छूट गया","समूह को गोलाकार बैठाना, हाथ उठाने के बाद एक समय में एक वक्ता का बोलना और मुख्य बिंदु श्यामपट्ट पर लिखना","उसके बगल में बैठे मित्र से कहना कि दूसरे जो कुछ कहें वह सब सीधे उसके कान में दोहराए"],"explanationHi":"उसे प्रत्येक वक्ता का चेहरा देखना और यह जानना आवश्यक है कि कौन बोल रहा है; गोला, बारी के संकेत और लिखित मुख्य बिंदु उसे वास्तविक पहुँच देते हैं, जबकि शोर और गति स्थिति को और बिगाड़ते हैं।"},
  {"id":"cdp-child-development-516","question":"Which teacher habit most disadvantages a blind student in a mathematics class?","options":["Asking the student to explain her method aloud to the class","Allowing extra time for her Braille work during tests and classwork","Pointing at the board and saying ‘this number plus this one gives that’","Reading out every number and symbol aloud as it is written on the board"],"answer":2,"explanation":"Words like ‘this’, ‘that’ and ‘here’ carry meaning only for those who can see the gesture; for a blind learner the teacher must say exactly what is written.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"गणित की कक्षा में शिक्षक की कौन-सी आदत दृष्टिबाधित विद्यार्थी को सबसे अधिक नुकसान पहुँचाती है?","optionsHi":["विद्यार्थी से कक्षा के सामने अपनी विधि ज़ोर से समझाने को कहना","परीक्षाओं और कक्षा-कार्य में उसके ब्रेल कार्य के लिए अतिरिक्त समय देना","श्यामपट्ट की ओर इशारा करके कहना ‘इस संख्या में इसे जोड़ने पर यह आता है’","श्यामपट्ट पर लिखी जा रही हर संख्या और चिह्न को लिखते समय ज़ोर से बोलना"],"explanationHi":"‘यह’, ‘वह’ और ‘यहाँ’ जैसे शब्द केवल उन्हीं के लिए अर्थपूर्ण हैं जो इशारा देख सकते हैं; दृष्टिबाधित अधिगमकर्ता के लिए शिक्षक को ठीक वही बोलना चाहिए जो लिखा गया है।"},
  {"id":"cdp-child-development-517","question":"Which of these statements about Braille are correct? I. Braille is a tactile code, not a separate language, so it can be used to write different languages such as Hindi and English. II. The basic Braille cell has six dot positions arranged in two columns of three. III. Once a blind child learns Braille, developing her listening skills is no longer important.","options":["I and III only","II only","II and III only","I and II only"],"answer":3,"explanation":"Braille is a six-dot code adapted for many scripts, including Bharati Braille for Indian languages; listening remains a key channel of learning for a blind child, so III is false.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"ब्रेल के बारे में इनमें से कौन-से कथन सही हैं? I. ब्रेल एक स्पर्श-आधारित कूट है, कोई अलग भाषा नहीं, इसलिए इसका उपयोग हिंदी और अंग्रेज़ी जैसी विभिन्न भाषाएँ लिखने में हो सकता है। II. मूल ब्रेल कोष्ठिका में छह बिंदु-स्थान होते हैं जो तीन-तीन के दो स्तंभों में व्यवस्थित होते हैं। III. जब कोई दृष्टिबाधित बच्ची ब्रेल सीख लेती है, तो उसके श्रवण कौशल का विकास करना महत्त्वपूर्ण नहीं रह जाता।","optionsHi":["केवल I और III","केवल II","केवल II और III","केवल I और II"],"explanationHi":"ब्रेल एक छह-बिंदु वाला कूट है जो अनेक लिपियों के अनुकूल बनाया गया है, जिसमें भारतीय भाषाओं के लिए भारती ब्रेल भी शामिल है; दृष्टिबाधित बच्चे के लिए सुनना सीखने का एक प्रमुख माध्यम बना रहता है, इसलिए III असत्य है।"},
  {"id":"cdp-child-development-518","question":"Which of the following is a misconception about sign language?","options":["Indian Sign Language has its own grammar, which differs from that of spoken Hindi or English","Sign language is a full language with its own vocabulary, not just a set of gestures","Deaf children benefit from early access to a fully accessible language such as sign language","Sign language is the same all over the world, so any deaf person can understand any other"],"answer":3,"explanation":"Sign languages differ from country to country and have their own grammar, like spoken languages; they are complete languages, and early accessible language supports a deaf child's development.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"सांकेतिक भाषा के बारे में निम्नलिखित में से कौन-सा एक भ्रांत धारणा है?","optionsHi":["भारतीय सांकेतिक भाषा का अपना व्याकरण है, जो बोली जाने वाली हिंदी या अंग्रेज़ी के व्याकरण से भिन्न है","सांकेतिक भाषा एक पूर्ण भाषा है जिसकी अपनी शब्दावली है, केवल भाव-भंगिमाओं का समूह नहीं","बधिर बच्चों को सांकेतिक भाषा जैसी पूर्णतः सुगम भाषा तक शीघ्र पहुँच से लाभ होता है","सांकेतिक भाषा पूरे विश्व में एक जैसी होती है, इसलिए कोई भी बधिर व्यक्ति किसी अन्य बधिर व्यक्ति को समझ सकता है"],"explanationHi":"सांकेतिक भाषाएँ देश-देश में भिन्न होती हैं और बोली जाने वाली भाषाओं की तरह उनका अपना व्याकरण होता है; वे पूर्ण भाषाएँ हैं, और सुगम भाषा तक शीघ्र पहुँच बधिर बच्चे के विकास में सहायक होती है।"},
  {"id":"cdp-child-development-519","question":"Ayaan, a Class 4 student with ADHD, often leaves classwork incomplete. His class teacher plans to keep him inside during recess every day to finish it. What is the best judgement?","options":["Unwise; losing activity tends to raise restlessness, so break the work into short chunks with movement breaks","A good plan, because it teaches him that unfinished work has consequences and builds a habit of completing it","A good plan if done only on alternate days, so that he still gets some play while learning to finish work","Unwise; since ADHD is a medical condition, he should simply be excused from completing classwork"],"answer":0,"explanation":"Children with ADHD need movement to regulate attention; taking away recess removes that outlet, whereas short tasks, movement breaks and immediate feedback help completion.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 का विद्यार्थी अयान ADHD से ग्रस्त है और प्रायः कक्षा-कार्य अधूरा छोड़ देता है। उसके कक्षा-शिक्षक उसे कार्य पूरा करने के लिए प्रतिदिन अवकाश में कक्षा के भीतर रोके रखने की योजना बनाते हैं। सर्वोत्तम निर्णय क्या है?","optionsHi":["अनुचित; गतिविधि छिनने से बेचैनी बढ़ती है, इसलिए कार्य को छोटे खंडों और गति-विश्रामों में बाँटें","अच्छी योजना, क्योंकि यह उसे सिखाती है कि अधूरे काम के परिणाम होते हैं और काम पूरा करने की आदत बनाती है","अच्छी योजना यदि केवल एकांतर दिनों में की जाए, ताकि उसे कार्य पूरा करना सीखते हुए कुछ खेल भी मिले","अनुचित; चूँकि ADHD एक चिकित्सीय स्थिति है, इसलिए उसे कक्षा-कार्य पूरा करने से बस छूट दे देनी चाहिए"],"explanationHi":"ADHD वाले बच्चों को ध्यान को नियंत्रित करने के लिए गति की आवश्यकता होती है; अवकाश छीनने से यह माध्यम समाप्त हो जाता है, जबकि छोटे कार्य, गति-विश्राम और तत्काल प्रतिपुष्टि कार्य पूरा करने में सहायता करते हैं।"},
  {"id":"cdp-child-development-520","question":"Next week Class 3 is going on a trip to a museum. Kavya, who is on the autism spectrum, finds new places and changes in routine very upsetting. What is the best preparation?","options":["Not telling her about the trip in advance, so that she does not spend the whole week before it worrying","Leaving her at school with another class for the day, so that her routine is not disturbed at all","Telling her firmly on the morning of the trip that she must behave well and stay with the group","Preparing her with photos of the museum, a step-by-step picture story and the trip on her visual schedule"],"answer":3,"explanation":"Predictability reduces anxiety for many autistic children; photos, a step-by-step story and a visual schedule prepare her to take part instead of being surprised or excluded.","difficulty":"moderate","source":"CTET · KVS · DSSSB","questionHi":"अगले सप्ताह कक्षा 3 संग्रहालय की यात्रा पर जा रही है। ऑटिज़्म स्पेक्ट्रम पर स्थित काव्या को नई जगहें और दिनचर्या में बदलाव बहुत परेशान करते हैं। सर्वोत्तम तैयारी क्या है?","optionsHi":["उसे यात्रा के बारे में पहले से न बताना, ताकि वह यात्रा से पहले का पूरा सप्ताह चिंता में न बिताए","उसे उस दिन किसी अन्य कक्षा के साथ विद्यालय में छोड़ देना, ताकि उसकी दिनचर्या बिल्कुल न बिगड़े","यात्रा की सुबह उसे दृढ़ता से कहना कि उसे अच्छा व्यवहार करना है और समूह के साथ रहना है","उसे संग्रहालय की तस्वीरों, चरण-दर-चरण चित्र-कथा और उसके दृश्य समय-सारणी में यात्रा को जोड़कर तैयार करना"],"explanationHi":"अनुमानित स्थिति कई ऑटिस्टिक बच्चों की चिंता घटाती है; तस्वीरें, चरण-दर-चरण कथा और दृश्य समय-सारणी उसे आश्चर्यचकित या बाहर किए जाने के बजाय भाग लेने के लिए तैयार करती हैं।"},
  {"id":"cdp-child-development-521","question":"Assertion (A): Inclusive education also benefits children without disabilities. Reason (R): Learning alongside diverse classmates develops empathy, acceptance of difference and varied ways of solving problems.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Inclusion is not a cost borne by other children; learning with diverse peers builds social understanding and flexible thinking, which is exactly why it benefits everyone.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"अभिकथन (A): समावेशी शिक्षा से अक्षमता-रहित बच्चों को भी लाभ होता है। कारण (R): विविध सहपाठियों के साथ सीखने से सहानुभूति, भिन्नता की स्वीकृति और समस्या हल करने के विविध तरीके विकसित होते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"समावेशन ऐसा खर्च नहीं है जिसे अन्य बच्चे वहन करें; विविध सहपाठियों के साथ सीखना सामाजिक समझ और लचीली सोच विकसित करता है, और यही कारण है कि इससे सभी को लाभ होता है।"},
  {"id":"cdp-child-development-522","question":"A school appoints a special educator who takes its children with disabilities to a resource room for every subject; they join their regular classes only for assembly and games. This arrangement is best described as:","options":["Full inclusion, because the children study in the same building and share assembly and games with others","Integration at a physical and social level, not inclusion, as regular-class teaching has not changed for them","Exclusion, because the children are completely denied their right to education by this arrangement","Universal Design for Learning, because specialised support is available to every child who needs it"],"answer":1,"explanation":"Sharing a building and games is placement, not inclusion; inclusion means the children learn in the regular class with adapted teaching, with resource-room help only as a supplement.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक विद्यालय एक विशेष शिक्षक की नियुक्ति करता है जो अक्षमता वाले अपने बच्चों को प्रत्येक विषय के लिए संसाधन-कक्ष में ले जाता है; वे अपनी नियमित कक्षाओं में केवल प्रार्थना-सभा और खेल के लिए शामिल होते हैं। इस व्यवस्था का सबसे सही वर्णन है:","optionsHi":["पूर्ण समावेशन, क्योंकि बच्चे एक ही भवन में पढ़ते हैं और दूसरों के साथ प्रार्थना-सभा तथा खेल में भाग लेते हैं","भौतिक और सामाजिक स्तर पर एकीकरण, समावेशन नहीं, क्योंकि उनके लिए नियमित कक्षा का शिक्षण बदला नहीं है","बहिष्करण, क्योंकि इस व्यवस्था से बच्चे शिक्षा के अपने अधिकार से पूरी तरह वंचित हैं","अधिगम का सार्वभौमिक अभिकल्प (UDL), क्योंकि विशेष सहायता हर उस बच्चे को उपलब्ध है जिसे उसकी आवश्यकता है"],"explanationHi":"एक भवन और खेल साझा करना केवल स्थान-निर्धारण है, समावेशन नहीं; समावेशन का अर्थ है कि बच्चे अनुकूलित शिक्षण के साथ नियमित कक्षा में सीखें, और संसाधन-कक्ष की सहायता केवल पूरक के रूप में हो।"},
  {"id":"cdp-child-development-523","question":"Which behaviour is LEAST reliable as a sign of giftedness in a child?","options":["Always having neat handwriting, obeying rules and finishing work on time","Asking probing questions that go well beyond what is taught in the lesson","Becoming bored quickly and restless with repetitive drill and practice work","Showing intense, long-lasting curiosity about a topic of personal interest"],"answer":0,"explanation":"Gifted children are often curious, questioning and impatient with repetition; neatness and compliance describe a ‘good student’, which is not the same as giftedness.","difficulty":"hard","source":"CTET · State TETs","questionHi":"किसी बच्चे में प्रतिभाशालिता के संकेत के रूप में कौन-सा व्यवहार सबसे कम विश्वसनीय है?","optionsHi":["हमेशा सुंदर लिखावट रखना, नियमों का पालन करना और काम समय पर पूरा करना","ऐसे गहन प्रश्न पूछना जो पाठ में पढ़ाई गई बातों से कहीं आगे जाते हों","दोहरावपूर्ण अभ्यास और अभ्यास-कार्य से शीघ्र ऊब जाना और बेचैन हो जाना","अपनी रुचि के किसी विषय में तीव्र और दीर्घकालिक जिज्ञासा दिखाना"],"explanationHi":"प्रतिभाशाली बच्चे प्रायः जिज्ञासु होते हैं, प्रश्न पूछते हैं और दोहराव से अधीर हो जाते हैं; साफ़ लिखावट और आज्ञापालन एक ‘अच्छे विद्यार्थी’ का वर्णन करते हैं, जो प्रतिभाशालिता के समान नहीं है।"},
  {"id":"cdp-child-development-524","question":"In a Class 7 class discussion, the boys answer most questions while the girls stay silent. Which strategy is most appropriate?","options":["Letting the boys continue answering, since forcing shy girls to speak in front of others may upset them","Asking only the girls questions for the next month, so that they get a fair share of classroom talk","Structured turn-taking such as think-pair-share, equal wait time, and rotating leadership roles among all","Holding separate discussion periods for boys and girls, so that girls can speak without feeling dominated"],"answer":2,"explanation":"Structured participation and equal wait time draw in quieter students without excluding anyone; doing nothing lets the pattern harden, and separating genders avoids rather than addresses it.","difficulty":"moderate","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 7 की कक्षा-चर्चा में अधिकांश प्रश्नों के उत्तर लड़के देते हैं जबकि लड़कियाँ चुप रहती हैं। कौन-सी युक्ति सबसे उपयुक्त है?","optionsHi":["लड़कों को उत्तर देते रहने देना, क्योंकि संकोची लड़कियों को दूसरों के सामने बोलने के लिए विवश करने से वे परेशान हो सकती हैं","अगले एक महीने तक केवल लड़कियों से प्रश्न पूछना, ताकि उन्हें कक्षा-वार्ता में उचित हिस्सा मिले","संरचित बारी-बारी जैसे सोचें-जोड़ी बनाएँ-साझा करें (थिंक-पेयर-शेयर), समान प्रतीक्षा-समय, और सभी के बीच नेतृत्व की भूमिकाओं का आवर्तन","लड़कों और लड़कियों के लिए अलग-अलग चर्चा-कालांश रखना, ताकि लड़कियाँ हावी महसूस किए बिना बोल सकें"],"explanationHi":"संरचित सहभागिता और समान प्रतीक्षा-समय शांत विद्यार्थियों को बिना किसी को बाहर किए जोड़ते हैं; कुछ न करने से यह स्वरूप पक्का हो जाता है, और लिंग के आधार पर अलग करना समस्या को सुलझाने के बजाय टालना है।"},
  {"id":"cdp-child-development-525","question":"A 10-year-old girl who has never attended school comes with her parents to seek admission to a government school. Under the RTE Act, 2009, what should the school do?","options":["Admit her in Class 1, since she cannot read yet and must start from the very beginning like others","Refuse admission until she passes an entrance test showing which class she is ready for","Admit her to an age-appropriate class and provide special training so that she can catch up","Ask her to come back at the start of the next academic session, when new admissions are made"],"answer":2,"explanation":"RTE requires an out-of-school child to be admitted to an age-appropriate class with special training to bring her on par; screening tests and denial of mid-year admission are not allowed.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"एक 10 वर्षीय बालिका, जो कभी विद्यालय नहीं गई, अपने माता-पिता के साथ किसी सरकारी विद्यालय में प्रवेश माँगने आती है। RTE अधिनियम, 2009 के अंतर्गत विद्यालय को क्या करना चाहिए?","optionsHi":["उसे कक्षा 1 में प्रवेश देना, क्योंकि वह अभी पढ़ नहीं सकती और उसे दूसरों की तरह बिल्कुल शुरू से आरंभ करना होगा","जब तक वह ऐसी प्रवेश परीक्षा उत्तीर्ण न कर ले जो बताए कि वह किस कक्षा के लिए तैयार है, तब तक प्रवेश से इनकार करना","उसे उसकी आयु के अनुरूप कक्षा में प्रवेश देना और विशेष प्रशिक्षण देना, ताकि वह बराबरी पर आ सके","उससे अगले शैक्षणिक सत्र के आरंभ में, जब नए प्रवेश होते हैं, आने को कहना"],"explanationHi":"RTE के अनुसार विद्यालय से बाहर रहे बच्चे को उसकी आयु के अनुरूप कक्षा में प्रवेश देना और बराबरी पर लाने के लिए विशेष प्रशिक्षण देना आवश्यक है; छँटनी परीक्षाएँ और सत्र के बीच में प्रवेश से इनकार अनुमत नहीं हैं।"},
  {"id":"cdp-child-development-526","question":"A Class 8 task reads: ‘Plan a week’s menu for your school hostel that stays within a fixed budget and meets the daily need for proteins, carbohydrates and vitamins.’ In the revised Bloom’s taxonomy (Anderson and Krathwohl), this task mainly targets:","options":["Understanding","Applying","Analysing","Creating"],"answer":3,"explanation":"In the revised taxonomy, ‘Create’ includes generating, planning and producing something new and coherent; designing an original menu under constraints is planning, the highest category.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"कक्षा 8 के एक कार्य में लिखा है: ‘अपने विद्यालय के छात्रावास के लिए एक सप्ताह का भोजन-तालिका बनाइए जो निश्चित बजट में रहे और प्रोटीन, कार्बोहाइड्रेट तथा विटामिन की दैनिक आवश्यकता पूरी करे।’ संशोधित ब्लूम वर्गीकरण (एंडरसन और क्रैथवोल) में यह कार्य मुख्यतः किसे लक्षित करता है?","optionsHi":["समझना","लागू करना","विश्लेषण करना","सृजन करना"],"explanationHi":"संशोधित वर्गीकरण में ‘सृजन’ में कुछ नया और सुसंगत उत्पन्न करना, योजना बनाना और रचना करना शामिल है; प्रतिबंधों के भीतर मौलिक भोजन-तालिका बनाना योजना बनाना है, जो सर्वोच्च श्रेणी है।"},
  {"id":"cdp-child-development-527","question":"Which of these statements about the revision of Bloom’s taxonomy by Anderson and Krathwohl (2001) are correct? I. Category names were changed from nouns (e.g. knowledge) to verbs (e.g. remembering). II. ‘Synthesis’ became ‘creating’ and was placed above ‘evaluating’. III. A separate knowledge dimension (factual, conceptual, procedural, metacognitive) was added. IV. ‘Application’ was dropped from the hierarchy.","options":["I and II only","I, II and III only","II and IV only","I, III and IV only"],"answer":1,"explanation":"The revision used verbs, put creating at the top above evaluating and added a knowledge dimension; ‘application’ survives as ‘applying’, so IV is false.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"एंडरसन और क्रैथवोल (2001) द्वारा ब्लूम वर्गीकरण के संशोधन के बारे में इनमें से कौन-से कथन सही हैं? I. श्रेणियों के नाम संज्ञाओं (जैसे ज्ञान) से क्रियाओं (जैसे याद करना) में बदले गए। II. ‘संश्लेषण’ ‘सृजन’ बन गया और उसे ‘मूल्यांकन’ के ऊपर रखा गया। III. एक पृथक ज्ञान-आयाम (तथ्यात्मक, संप्रत्ययात्मक, प्रक्रियात्मक, अधिसंज्ञानात्मक) जोड़ा गया। IV. ‘अनुप्रयोग’ को पदानुक्रम से हटा दिया गया।","optionsHi":["केवल I और II","केवल I, II और III","केवल II और IV","केवल I, III और IV"],"explanationHi":"संशोधन में क्रियाओं का प्रयोग हुआ, सृजन को मूल्यांकन के ऊपर शीर्ष पर रखा गया और ज्ञान-आयाम जोड़ा गया; ‘अनुप्रयोग’ ‘लागू करना’ के रूप में बना रहा, इसलिए IV असत्य है।"},
  {"id":"cdp-child-development-528","question":"A school redesigning its Class 4 report card in line with the holistic progress card of NEP 2020 is considering four changes. Which one goes AGAINST its spirit?","options":["Adding a section in which the child records what she enjoyed and what she found difficult","Including peer and teacher observations on teamwork and creativity","Printing each child’s class rank in every subject so that parents can compare children","Reporting progress in socio-emotional and physical domains along with the cognitive"],"answer":2,"explanation":"The holistic progress card is multidimensional and includes self- and peer-assessment to show each child’s own progress; ranking children against one another runs against that purpose.","difficulty":"hard","source":"CTET · KVS PRT","questionHi":"NEP 2020 के समग्र प्रगति-पत्र (होलिस्टिक प्रोग्रेस कार्ड) के अनुरूप अपना कक्षा 4 का रिपोर्ट कार्ड नए सिरे से तैयार कर रहा एक विद्यालय चार परिवर्तनों पर विचार कर रहा है। इनमें से कौन-सा उसकी भावना के विरुद्ध है?","optionsHi":["एक ऐसा खंड जोड़ना जिसमें बच्चा लिखे कि उसे क्या अच्छा लगा और क्या कठिन लगा","टीम-भावना और रचनात्मकता पर सहपाठियों तथा शिक्षकों के अवलोकन शामिल करना","हर विषय में प्रत्येक बच्चे की कक्षा-श्रेणी (रैंक) छापना, ताकि अभिभावक बच्चों की तुलना कर सकें","संज्ञानात्मक के साथ-साथ सामाजिक-भावनात्मक और शारीरिक क्षेत्रों में प्रगति की रिपोर्ट देना"],"explanationHi":"समग्र प्रगति-पत्र बहुआयामी होता है और इसमें प्रत्येक बच्चे की अपनी प्रगति दिखाने के लिए स्व- और सहपाठी-आकलन शामिल होता है; बच्चों को एक-दूसरे के विरुद्ध क्रमबद्ध करना इस उद्देश्य के विपरीत है।"},
  {"id":"cdp-child-development-529","question":"Which of these are proposals of NEP 2020 on school examinations? I. Board exams should test core capacities rather than months of coaching and memorisation. II. Students may be allowed to take board exams on up to two occasions in a school year. III. School examinations in Grades 3, 5 and 8, conducted by the appropriate authority, to track progress. IV. Board examinations at Grades 10 and 12 to be abolished.","options":["I and IV only","II and IV only","I, II and IV only","I, II and III only"],"answer":3,"explanation":"NEP 2020 keeps Grade 10 and 12 board exams but reforms them, allows up to two attempts a year, and proposes Grade 3, 5 and 8 examinations; it does not abolish board exams.","difficulty":"very-hard","source":"CTET · DSSSB TGT","questionHi":"विद्यालयी परीक्षाओं के बारे में NEP 2020 के प्रस्तावों में से कौन-से हैं? I. बोर्ड परीक्षाएँ महीनों की कोचिंग और रटंत के बजाय मूल क्षमताओं की जाँच करें। II. विद्यार्थियों को एक विद्यालयी वर्ष में दो बार तक बोर्ड परीक्षा देने की अनुमति दी जा सकती है। III. प्रगति पर नज़र रखने के लिए उपयुक्त प्राधिकारी द्वारा कक्षा 3, 5 और 8 में विद्यालयी परीक्षाएँ। IV. कक्षा 10 और 12 की बोर्ड परीक्षाएँ समाप्त कर दी जाएँ।","optionsHi":["केवल I और IV","केवल II और IV","केवल I, II और IV","केवल I, II और III"],"explanationHi":"NEP 2020 कक्षा 10 और 12 की बोर्ड परीक्षाएँ रखती है परंतु उनमें सुधार करती है, वर्ष में दो प्रयासों तक की अनुमति देती है और कक्षा 3, 5 तथा 8 की परीक्षाओं का प्रस्ताव करती है; वह बोर्ड परीक्षाएँ समाप्त नहीं करती।"},
  {"id":"cdp-child-development-530","question":"A Class 2 teacher wants her children to assess their own reading. Which method is most developmentally appropriate?","options":["A written self-evaluation essay on how their reading has progressed over the term","Asking each child to give herself marks out of 100 for her reading at the end of each week","Smiley or traffic-light cards against two or three simple ‘I can’ statements, discussed with the teacher","A wall chart on which children rank themselves against their classmates after each reading session"],"answer":2,"explanation":"Young children can self-assess when the criteria are few, concrete and visual and the result is talked over; essays, percentages and peer ranking are beyond their level or harmful to motivation.","difficulty":"moderate","source":"CTET Paper I · State TET","questionHi":"कक्षा 2 की एक शिक्षिका चाहती है कि उसके बच्चे अपने पठन का स्वयं आकलन करें। कौन-सी विधि विकासात्मक दृष्टि से सबसे उपयुक्त है?","optionsHi":["सत्र में उनके पठन में हुई प्रगति पर एक लिखित स्व-मूल्यांकन निबंध","प्रत्येक बच्चे से प्रति सप्ताह के अंत में अपने पठन के लिए स्वयं को 100 में से अंक देने को कहना","दो-तीन सरल ‘मैं कर सकता/सकती हूँ’ कथनों के सामने मुस्कान या ट्रैफ़िक-लाइट कार्ड, जिन पर शिक्षिका के साथ चर्चा हो","एक दीवार-चार्ट जिस पर बच्चे प्रत्येक पठन-सत्र के बाद स्वयं को सहपाठियों के मुकाबले क्रमबद्ध करें"],"explanationHi":"छोटे बच्चे स्व-आकलन कर सकते हैं जब मानदंड थोड़े, ठोस और दृश्य हों तथा परिणाम पर चर्चा हो; निबंध, प्रतिशत और सहपाठी-श्रेणीकरण उनके स्तर से परे हैं या अभिप्रेरणा के लिए हानिकारक हैं।"},
  {"id":"cdp-child-development-531","question":"Section 29 of the RTE Act, 2009 lists what the academic authority must take into account while laying down curriculum and evaluation procedure. Which of these is NOT among them?","options":["Learning through activities, discovery and exploration in a child-friendly and child-centred manner","Medium of instruction, as far as practicable, in the child’s mother tongue","Making the child free of fear, trauma and anxiety","Deciding promotion through a single written examination at the end of each year"],"answer":3,"explanation":"Section 29 calls for child-centred learning, mother-tongue instruction as far as practicable, freedom from fear and anxiety, and comprehensive and continuous evaluation, not a single year-end examination.","difficulty":"hard","source":"CTET · UPTET · REET","questionHi":"RTE अधिनियम, 2009 की धारा 29 उन बातों की सूची देती है जिन्हें शैक्षणिक प्राधिकारी को पाठ्यचर्या और मूल्यांकन प्रक्रिया निर्धारित करते समय ध्यान में रखना चाहिए। इनमें से कौन-सी उनमें शामिल नहीं है?","optionsHi":["बाल-अनुकूल और बाल-केंद्रित ढंग से गतिविधियों, खोज और अन्वेषण द्वारा सीखना","जहाँ तक व्यावहारिक हो, शिक्षा का माध्यम बच्चे की मातृभाषा हो","बच्चे को भय, आघात और चिंता से मुक्त रखना","प्रत्येक वर्ष के अंत में एक ही लिखित परीक्षा से प्रोन्नति का निर्णय करना"],"explanationHi":"धारा 29 बाल-केंद्रित अधिगम, जहाँ तक व्यावहारिक हो मातृभाषा में शिक्षा, भय और चिंता से मुक्ति तथा व्यापक एवं सतत मूल्यांकन की बात करती है, वर्ष के अंत की किसी एक परीक्षा की नहीं।"},
  {"id":"cdp-child-development-532","question":"Assertion (A): A test with high reliability may still be unfair to some groups of students. Reason (R): Reliability concerns the consistency of scores, not whether the test measures the intended ability equally well for all learners.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"A test can consistently measure the wrong thing for some groups (for example, through unfamiliar language or contexts); consistency says nothing about fairness or validity, which is exactly why A holds.","difficulty":"very-hard","source":"CTET Paper II · KVS PGT","questionHi":"अभिकथन (A): उच्च विश्वसनीयता वाला परीक्षण भी कुछ विद्यार्थी-समूहों के प्रति अनुचित हो सकता है। कारण (R): विश्वसनीयता अंकों की संगति से संबंधित है, इस बात से नहीं कि परीक्षण सभी अधिगमकर्ताओं में इच्छित क्षमता को समान रूप से मापता है या नहीं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"कोई परीक्षण कुछ समूहों के लिए (जैसे अपरिचित भाषा या संदर्भों के कारण) लगातार गलत चीज़ को माप सकता है; संगति से निष्पक्षता या वैधता के बारे में कुछ पता नहीं चलता, और इसी कारण A सही है।"},
  {"id":"cdp-child-development-533","question":"Before setting a Class 9 science test, a teacher prepares a two-way table showing how many marks will go to each chapter and to each objective (knowledge, understanding, application). This blueprint mainly protects the test’s:","options":["Predictive validity","Content validity","Inter-rater reliability","Face validity"],"answer":1,"explanation":"A blueprint makes the test sample the taught content and objectives in the intended proportion, which is what content validity means.","difficulty":"hard","source":"KVS TGT · DSSSB TGT","questionHi":"कक्षा 9 का विज्ञान परीक्षण बनाने से पहले एक शिक्षक द्विमार्गी तालिका तैयार करता है जिसमें दिखाया जाता है कि प्रत्येक अध्याय और प्रत्येक उद्देश्य (ज्ञान, बोध, अनुप्रयोग) को कितने अंक मिलेंगे। यह ब्लूप्रिंट मुख्यतः परीक्षण की किसकी रक्षा करता है?","optionsHi":["पूर्वकथनीय वैधता","विषय-वस्तु वैधता","अंतर-मूल्यांकनकर्ता विश्वसनीयता","आभासी वैधता"],"explanationHi":"ब्लूप्रिंट परीक्षण को पढ़ाई गई विषय-वस्तु और उद्देश्यों का इच्छित अनुपात में प्रतिदर्श लेने वाला बनाता है, और यही विषय-वस्तु वैधता का अर्थ है।"},
  {"id":"cdp-child-development-534","question":"Two teachers mark the same Class 6 answer sheets. On the objective section their scores are identical, but on the essay section their marks differ widely. Which step most directly improves the essay section?","options":["Replacing the essay with more multiple-choice items on facts, which can be marked objectively","Allowing the students more time to write the essays, so that their answers are more complete","A shared rubric with clear criteria and model answers, and joint moderation of a sample","Averaging the two teachers' marks for each sheet, so that individual differences cancel out"],"answer":2,"explanation":"Shared criteria and moderation raise inter-rater reliability while keeping the essay’s purpose; replacing essays with fact items would gain consistency but lose validity for writing skills.","difficulty":"hard","source":"CTET Paper II · State TET","questionHi":"दो शिक्षक कक्षा 6 की एक ही उत्तर-पुस्तिकाएँ जाँचते हैं। वस्तुनिष्ठ खंड में उनके अंक समान हैं, परंतु निबंध खंड में उनके अंकों में बहुत अंतर है। निबंध खंड को सबसे सीधे ढंग से कौन-सा कदम सुधारता है?","optionsHi":["निबंध को तथ्यों पर आधारित अधिक बहुविकल्पीय प्रश्नों से बदलना, जिन्हें वस्तुनिष्ठ ढंग से जाँचा जा सके","विद्यार्थियों को निबंध लिखने के लिए अधिक समय देना, ताकि उनके उत्तर अधिक पूर्ण हों","स्पष्ट मानदंडों और आदर्श उत्तरों वाला साझा रूब्रिक, तथा एक प्रतिदर्श का संयुक्त नियमन (मॉडरेशन)","प्रत्येक उत्तर-पुस्तिका के लिए दोनों शिक्षकों के अंकों का औसत लेना, ताकि व्यक्तिगत अंतर समाप्त हो जाएँ"],"explanationHi":"साझा मानदंड और नियमन निबंध के उद्देश्य को बनाए रखते हुए अंतर-मूल्यांकनकर्ता विश्वसनीयता बढ़ाते हैं; निबंध को तथ्य-प्रश्नों से बदलने पर संगति तो मिलेगी पर लेखन-कौशल के लिए वैधता खो जाएगी।"},
  {"id":"cdp-child-development-535","question":"In a Class 10 test, 40 students attempt an item and 30 answer it correctly. Of the 10 highest scorers on the whole test, 9 answer it correctly; of the 10 lowest scorers, 8 do. Which conclusion about the item is most accurate?","options":["It is a very difficult item that discriminates highly between high and low achievers","It is of moderate difficulty and discriminates well between high and low achievers","It is a very easy item that shows negative discrimination between the two groups","It is fairly easy and discriminates poorly between high and low achievers"],"answer":3,"explanation":"Difficulty index = 30/40 = 0.75 (fairly easy); discrimination = (9 − 8)/10 = 0.1, positive but very low, so the item hardly separates strong from weak students.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"कक्षा 10 की एक परीक्षा में 40 विद्यार्थी एक प्रश्न का प्रयास करते हैं और 30 उसका सही उत्तर देते हैं। पूरे परीक्षण में सबसे अधिक अंक पाने वाले 10 में से 9 सही उत्तर देते हैं; सबसे कम अंक पाने वाले 10 में से 8 देते हैं। इस प्रश्न के बारे में कौन-सा निष्कर्ष सबसे सटीक है?","optionsHi":["यह बहुत कठिन प्रश्न है जो उच्च और निम्न उपलब्धि वाले विद्यार्थियों में अत्यधिक विभेद करता है","यह मध्यम कठिनाई का प्रश्न है और उच्च तथा निम्न उपलब्धि वाले विद्यार्थियों में अच्छा विभेद करता है","यह बहुत आसान प्रश्न है जो दोनों समूहों के बीच ऋणात्मक विभेदन दिखाता है","यह काफ़ी आसान है और उच्च तथा निम्न उपलब्धि वाले विद्यार्थियों में कम विभेद करता है"],"explanationHi":"कठिनाई सूचकांक = 30/40 = 0.75 (काफ़ी आसान); विभेदन = (9 − 8)/10 = 0.1, जो धनात्मक है पर बहुत कम, इसलिए यह प्रश्न मज़बूत और कमज़ोर विद्यार्थियों को मुश्किल से अलग कर पाता है।"},
  {"id":"cdp-child-development-536","question":"Which feedback practice best fits the principle that feedback should help ‘close the gap’ between present and desired performance?","options":["Returning the draft with one specific improvement point and class time to revise before final submission","Returning fully corrected final copies at the end of term, each with a grade and a short comment","Displaying the marks of all students on the notice board so that each can see where they stand","Writing ‘See me’ on the work of weak students so that they come for a private discussion later"],"answer":0,"explanation":"Feedback closes the gap only if it is specific and the learner gets a chance to act on it; feedback given after the work is finished, or only as marks, cannot be used.","difficulty":"moderate","source":"CTET · KVS PRT","questionHi":"कौन-सी प्रतिपुष्टि पद्धति इस सिद्धांत के सबसे अनुरूप है कि प्रतिपुष्टि को वर्तमान और वांछित निष्पादन के बीच के ‘अंतर को पाटने’ में सहायक होना चाहिए?","optionsHi":["प्रारूप लौटाना, उसमें सुधार का एक विशिष्ट बिंदु देना और अंतिम प्रस्तुति से पहले संशोधन के लिए कक्षा का समय देना","सत्र के अंत में पूर्णतः सुधारी हुई अंतिम प्रतियाँ लौटाना, प्रत्येक पर एक ग्रेड और एक संक्षिप्त टिप्पणी के साथ","सभी विद्यार्थियों के अंक सूचना-पट्ट पर प्रदर्शित करना, ताकि प्रत्येक देख सके कि वह कहाँ खड़ा है","कमज़ोर विद्यार्थियों के कार्य पर ‘मिलें’ लिखना, ताकि वे बाद में निजी चर्चा के लिए आएँ"],"explanationHi":"प्रतिपुष्टि अंतर को तभी पाटती है जब वह विशिष्ट हो और अधिगमकर्ता को उस पर कार्य करने का अवसर मिले; कार्य समाप्त होने के बाद या केवल अंकों के रूप में दी गई प्रतिपुष्टि का उपयोग नहीं किया जा सकता।"},
  {"id":"cdp-child-development-537","question":"In a Class 7 section of 55 students with one teacher, which strategy gives the teacher the most information about everyone’s understanding in the least time?","options":["Calling on the two students who raise their hands first and judging from their answers","Asking ‘Have you all understood?’ and watching the class closely for nods and smiles","Exit slips with one diagnostic question, sorted after class into ‘got it / partly / not yet’","A detailed written test at the end of every week, covering all the topics that were taught that week"],"answer":2,"explanation":"Exit slips collect evidence from every student quickly and can be sorted to plan the next lesson; volunteers and nods give biased or unreliable evidence, and weekly tests come too late.","difficulty":"hard","source":"CTET Paper II · NVS TGT","questionHi":"एक शिक्षक वाली कक्षा 7 की 55 विद्यार्थियों की एक कक्षा में कौन-सी युक्ति सबसे कम समय में सभी के बोध के बारे में शिक्षक को सबसे अधिक जानकारी देती है?","optionsHi":["सबसे पहले हाथ उठाने वाले दो विद्यार्थियों को बुलाना और उनके उत्तरों से आकलन करना","‘क्या आप सब समझ गए?’ पूछना और सिर हिलाने तथा मुस्कुराने पर कक्षा को ध्यान से देखना","एक निदानात्मक प्रश्न वाली निर्गम-पर्चियाँ (एग्ज़िट स्लिप), जिन्हें कक्षा के बाद ‘समझ गए / कुछ-कुछ / अभी नहीं’ में छाँटा जाए","प्रत्येक सप्ताह के अंत में एक विस्तृत लिखित परीक्षा, जिसमें उस सप्ताह पढ़ाए गए सभी विषय हों"],"explanationHi":"निर्गम-पर्चियाँ प्रत्येक विद्यार्थी से शीघ्रता से प्रमाण एकत्र करती हैं और अगले पाठ की योजना के लिए छाँटी जा सकती हैं; स्वयंसेवक और सिर हिलाना पक्षपातपूर्ण या अविश्वसनीय प्रमाण देते हैं, और साप्ताहिक परीक्षाएँ बहुत देर से आती हैं।"},
  {"id":"cdp-child-development-538","question":"A teacher introduces open-book tests in Class 9 social science. For the change to be meaningful, the questions should be:","options":["Direct questions whose answers can be found and copied from a single page of the book","Questions requiring analysis, comparison and application of the text's ideas to new situations","Questions about page numbers, headings and figure titles, to check skill in using the book","Fill-in-the-blanks taken from the chapter-end summary, so that students revise key terms"],"answer":1,"explanation":"An open-book test removes the need to memorise, so it is worthwhile only if questions demand higher-order thinking; copy-able questions would test nothing.","difficulty":"moderate","source":"CTET Paper II · State TET","questionHi":"एक शिक्षक कक्षा 9 की सामाजिक विज्ञान में खुली-पुस्तक परीक्षाएँ आरंभ करता है। इस परिवर्तन के सार्थक होने के लिए प्रश्न कैसे होने चाहिए?","optionsHi":["सीधे प्रश्न जिनके उत्तर पुस्तक के एक ही पृष्ठ से खोजकर उतारे जा सकें","ऐसे प्रश्न जिनमें विश्लेषण, तुलना और पाठ के विचारों को नई स्थितियों में लागू करना आवश्यक हो","पृष्ठ-संख्या, शीर्षक और चित्रों के नामों के बारे में प्रश्न, ताकि पुस्तक के प्रयोग का कौशल जाँचा जाए","अध्याय के अंतिम सारांश से लिए गए रिक्त स्थान, ताकि विद्यार्थी मुख्य शब्दों का पुनरावर्तन करें"],"explanationHi":"खुली-पुस्तक परीक्षा रटने की आवश्यकता समाप्त करती है, इसलिए वह तभी सार्थक है जब प्रश्न उच्च-स्तरीय चिंतन माँगें; उतारे जा सकने वाले प्रश्न कुछ भी नहीं जाँचेंगे।"},
  {"id":"cdp-child-development-539","question":"Which of these statements about rubrics are correct? I. A rubric shared before the task can guide students’ work, not just the teacher’s marking. II. Rubric levels should describe the quality of performance rather than merely count features. III. A rubric guarantees a valid assessment even if its criteria ignore the learning goal.","options":["I and II only","I only","II and III only","I, II and III"],"answer":0,"explanation":"Shared rubrics clarify success criteria for learners and good level descriptors describe quality; but a rubric is only as valid as its criteria, so III is false.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT","questionHi":"रूब्रिक के बारे में इनमें से कौन-से कथन सही हैं? I. कार्य से पहले साझा किया गया रूब्रिक केवल शिक्षक के अंक देने में ही नहीं, विद्यार्थियों के कार्य में भी मार्गदर्शन कर सकता है। II. रूब्रिक के स्तरों को केवल विशेषताएँ गिनने के बजाय निष्पादन की गुणवत्ता का वर्णन करना चाहिए। III. रूब्रिक एक वैध आकलन की गारंटी देता है, भले ही उसके मानदंड अधिगम लक्ष्य की उपेक्षा करते हों।","optionsHi":["केवल I और II","केवल I","केवल II और III","I, II और III"],"explanationHi":"साझा रूब्रिक अधिगमकर्ताओं के लिए सफलता के मानदंड स्पष्ट करते हैं और अच्छे स्तर-विवरण गुणवत्ता का वर्णन करते हैं; परंतु रूब्रिक उतना ही वैध होता है जितने उसके मानदंड, इसलिए III असत्य है।"},
  {"id":"cdp-child-development-540","question":"A teacher asks Class 8 students to draw a concept map linking ‘sun, producer, consumer, decomposer, energy’. Such a map is especially useful for assessing:","options":["How quickly and accurately students can recall the textbook definitions of each of the five terms","Students' handwriting, neatness and their ability to draw clear diagrams","Their memory of the order in which the topics appear in the textbook chapter","How students understand the relationships among concepts, including misconceptions in their links"],"answer":3,"explanation":"A concept map makes visible the links a learner draws between ideas, so faulty links (misconceptions) show up in a way a definition test cannot reveal.","difficulty":"moderate","source":"CTET Paper II · KVS TGT","questionHi":"एक शिक्षक कक्षा 8 के विद्यार्थियों से ‘सूर्य, उत्पादक, उपभोक्ता, अपघटक, ऊर्जा’ को जोड़ता हुआ एक संप्रत्यय मानचित्र (कॉन्सेप्ट मैप) बनाने को कहता है। ऐसा मानचित्र किसके आकलन के लिए विशेष रूप से उपयोगी है?","optionsHi":["विद्यार्थी इन पाँचों शब्दों की पाठ्यपुस्तक-परिभाषाएँ कितनी शीघ्रता और सटीकता से याद कर सकते हैं","विद्यार्थियों की लिखावट, साफ़-सफ़ाई और स्पष्ट आरेख बनाने की क्षमता","पाठ्यपुस्तक के अध्याय में विषयों के क्रम की उनकी स्मृति","विद्यार्थी संप्रत्ययों के बीच संबंधों को कैसे समझते हैं, जिनमें उनके जोड़ों में निहित भ्रांतियाँ भी शामिल हैं"],"explanationHi":"संप्रत्यय मानचित्र अधिगमकर्ता द्वारा विचारों के बीच बनाए गए संबंधों को दृश्य बनाता है, इसलिए गलत संबंध (भ्रांतियाँ) ऐसे उजागर हो जाते हैं जैसे परिभाषा-परीक्षा से नहीं हो सकते।"},
  {"id":"cdp-child-development-541","question":"For a four-year-old in a Balvatika or anganwadi, which form of assessment fits the approach of NEP 2020 and the foundational-stage framework?","options":["Short written tests every month to check which letters and numbers the child has learnt","Observation of the child in play and daily activities, along with samples of her work","An oral examination with marks before promotion to Grade 1, to confirm school readiness","A standardised entrance test for school admission, to place the child in the right section"],"answer":1,"explanation":"At the foundational stage, assessment is through observation and children’s artefacts during play and activity; formal tests and marks are developmentally inappropriate.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"बालवाटिका या आँगनवाड़ी में चार वर्ष के बच्चे के लिए आकलन का कौन-सा रूप NEP 2020 और आधारभूत स्तर की रूपरेखा के उपागम के अनुरूप है?","optionsHi":["हर महीने छोटी लिखित परीक्षाएँ, यह जाँचने के लिए कि बच्चे ने कौन-से अक्षर और संख्याएँ सीखी हैं","खेल और दैनिक गतिविधियों में बच्चे का अवलोकन, उसके कार्य के नमूनों के साथ","कक्षा 1 में प्रोन्नति से पहले अंकों वाली मौखिक परीक्षा, यह पुष्टि करने के लिए कि वह विद्यालय के लिए तैयार है","विद्यालय में प्रवेश के लिए एक मानकीकृत प्रवेश परीक्षा, ताकि बच्चे को सही अनुभाग में रखा जा सके"],"explanationHi":"आधारभूत स्तर पर आकलन खेल और गतिविधि के दौरान बच्चों के अवलोकन और उनकी कृतियों के माध्यम से होता है; औपचारिक परीक्षाएँ और अंक विकास की दृष्टि से अनुपयुक्त हैं।"},
  {"id":"cdp-child-development-542","question":"A private unaided school holds a short interview of the child and parents before admission to Class 1 so as to choose ‘suitable’ children. Under the RTE Act, 2009, this is:","options":["Allowed, provided the interview is held in the child's mother tongue and the parents are put at ease","Allowed, but only for seats outside the 25% quota reserved for children from disadvantaged groups","Prohibited, as Section 13 bars any screening procedure for admission and penalises it with a fine","Prohibited only in government and aided schools, since unaided schools may set their own admission rules"],"answer":2,"explanation":"Section 13 forbids capitation fees and any screening procedure (any selection other than a random method) for admission in all schools covered by the Act, with fines for contravention.","difficulty":"hard","source":"CTET · DSSSB PRT","questionHi":"एक निजी गैर-सहायता प्राप्त विद्यालय ‘उपयुक्त’ बच्चों को चुनने के लिए कक्षा 1 में प्रवेश से पहले बच्चे और माता-पिता का एक छोटा साक्षात्कार लेता है। RTE अधिनियम, 2009 के अंतर्गत यह है:","optionsHi":["अनुमत, बशर्ते साक्षात्कार बच्चे की मातृभाषा में हो और माता-पिता को सहज रखा जाए","अनुमत, परंतु केवल उन सीटों के लिए जो वंचित समूहों के बच्चों के लिए आरक्षित 25% कोटे से बाहर हैं","निषिद्ध, क्योंकि धारा 13 प्रवेश के लिए किसी भी छँटनी प्रक्रिया को रोकती है और इसके लिए जुर्माने का दंड देती है","केवल सरकारी और सहायता प्राप्त विद्यालयों में निषिद्ध, क्योंकि गैर-सहायता प्राप्त विद्यालय अपने प्रवेश-नियम स्वयं बना सकते हैं"],"explanationHi":"धारा 13 अधिनियम के अंतर्गत आने वाले सभी विद्यालयों में प्रवेश के लिए कैपिटेशन शुल्क और किसी भी छँटनी प्रक्रिया (यादृच्छिक विधि के अतिरिक्त कोई चयन) को निषिद्ध करती है, और उल्लंघन पर जुर्माने का प्रावधान है।"},
  {"id":"cdp-child-development-543","question":"A teacher tells Neha, ‘Last month you read 20 words a minute; today you read 35.’ The teacher is judging Neha’s performance with reference to:","options":["Her own earlier performance (ipsative or self-referenced assessment)","Her classmates’ performance (norm-referenced assessment)","A fixed standard of reading fluency (criterion-referenced assessment)","A final certification of her level (summative assessment)"],"answer":0,"explanation":"Comparing a learner with her own earlier performance is ipsative assessment; it highlights personal growth, which supports motivation, especially for struggling readers.","difficulty":"hard","source":"CTET Paper I · State TET","questionHi":"एक शिक्षिका नेहा से कहती है, ‘पिछले महीने तुम एक मिनट में 20 शब्द पढ़ती थीं; आज 35 पढ़ती हो।’ शिक्षिका नेहा के निष्पादन का आकलन किसके संदर्भ में कर रही है?","optionsHi":["उसके अपने पूर्व निष्पादन के (स्व-संदर्भित आकलन)","उसके सहपाठियों के निष्पादन के (मानक-संदर्भित आकलन)","पठन-प्रवाह के किसी निश्चित मानक के (मानदंड-संदर्भित आकलन)","उसके स्तर के अंतिम प्रमाणन के (योगात्मक आकलन)"],"explanationHi":"किसी अधिगमकर्ता की तुलना उसके अपने पूर्व निष्पादन से करना स्व-संदर्भित (इप्सेटिव) आकलन है; यह व्यक्तिगत विकास को उजागर करता है, जो अभिप्रेरणा में सहायक है, विशेषकर पठन में संघर्ष कर रहे बच्चों के लिए।"},
  {"id":"cdp-child-development-544","question":"Which tool would give the most valid evidence of a Class 5 child’s cooperation with others?","options":["A written test with the question ‘Why is cooperation important?’ marked against a model answer","Systematic observation during group work over several weeks, recorded in a checklist or anecdotal notes","A true/false quiz on good manners and helping behaviour, given at the end of the term","The child's marks in moral science, since that subject directly covers values such as sharing and cooperation"],"answer":1,"explanation":"Cooperation is a behaviour, so the valid evidence is observed behaviour in real situations over time; written answers show only what the child knows to say.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"कक्षा 5 के बच्चे के दूसरों के साथ सहयोग के लिए कौन-सा उपकरण सबसे वैध प्रमाण देगा?","optionsHi":["‘सहयोग क्यों महत्त्वपूर्ण है?’ प्रश्न वाली लिखित परीक्षा, जिसे आदर्श उत्तर के आधार पर जाँचा जाए","कई सप्ताहों तक समूह-कार्य के दौरान व्यवस्थित अवलोकन, जिसे जाँच-सूची या किस्सागोई टिप्पणियों में दर्ज किया जाए","सत्र के अंत में दिया गया अच्छे शिष्टाचार और सहायता-व्यवहार पर सही/गलत प्रश्नोत्तरी","नैतिक शिक्षा में बच्चे के अंक, क्योंकि वह विषय साझा करने और सहयोग जैसे मूल्यों को सीधे समाहित करता है"],"explanationHi":"सहयोग एक व्यवहार है, इसलिए वैध प्रमाण समय के साथ वास्तविक स्थितियों में देखा गया व्यवहार है; लिखित उत्तर केवल यह दिखाते हैं कि बच्चा क्या कहना जानता है।"},
  {"id":"cdp-child-development-545","question":"Assertion (A): Continuous evaluation means testing children every week. Reason (R): Continuous evaluation aims at regular monitoring of learning and timely feedback during the teaching–learning process.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Continuity means assessment is woven into everyday teaching (observation, questioning, feedback), not frequent formal tests; equating it with weekly testing was the very distortion critics of CCE pointed out.","difficulty":"very-hard","source":"CTET · State TET","questionHi":"अभिकथन (A): सतत मूल्यांकन का अर्थ है बच्चों की प्रत्येक सप्ताह परीक्षा लेना। कारण (R): सतत मूल्यांकन का उद्देश्य शिक्षण-अधिगम प्रक्रिया के दौरान अधिगम की नियमित निगरानी और समय पर प्रतिपुष्टि है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"निरंतरता का अर्थ है कि आकलन रोज़मर्रा के शिक्षण (अवलोकन, प्रश्न, प्रतिपुष्टि) में गुँथा हो, न कि बार-बार औपचारिक परीक्षाएँ; इसे साप्ताहिक परीक्षा के बराबर मान लेना वही विकृति थी जिसकी ओर CCE के आलोचकों ने इशारा किया था।"},
  {"id":"cdp-child-development-546","question":"After a unit test, a Class 3 teacher finds that 70% of the class got the same item on subtraction with regrouping wrong. The most appropriate inference is:","options":["Most of the class is weak in mathematics and needs extra tuition after school hours","The item was too difficult for Class 3 and should be dropped from future tests","The concept may not have been taught effectively, so she should reteach it differently","The children did not revise the topic at home, so parents should be asked to supervise practice"],"answer":2,"explanation":"When most of a class makes the same error, the evidence points to the teaching rather than to the children; assessment data should first feed back into the teacher’s own practice.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"एक इकाई परीक्षा के बाद कक्षा 3 की शिक्षिका पाती है कि कक्षा के 70% बच्चों ने हासिल वाले घटाव का एक ही प्रश्न गलत किया। सबसे उपयुक्त अनुमान है:","optionsHi":["कक्षा के अधिकांश बच्चे गणित में कमज़ोर हैं और उन्हें विद्यालय के समय के बाद अतिरिक्त ट्यूशन की ज़रूरत है","प्रश्न कक्षा 3 के लिए बहुत कठिन था और उसे भविष्य की परीक्षाओं से हटा देना चाहिए","संभव है कि अवधारणा प्रभावी ढंग से नहीं पढ़ाई गई, इसलिए उसे इसे भिन्न ढंग से पुनः पढ़ाना चाहिए","बच्चों ने घर पर विषय का पुनरावर्तन नहीं किया, इसलिए अभिभावकों से अभ्यास की निगरानी करने को कहना चाहिए"],"explanationHi":"जब कक्षा के अधिकांश बच्चे एक ही त्रुटि करते हैं, तो प्रमाण बच्चों की नहीं बल्कि शिक्षण की ओर संकेत करते हैं; आकलन के आँकड़ों को पहले शिक्षक के अपने अभ्यास में प्रतिपुष्टि के रूप में लौटना चाहिए।"},
  {"id":"cdp-child-development-547","question":"In a Class 8 science practical examination, students are marked largely on the neatness of their diagrams and the length of their records. The main problem is that:","options":["Construct-irrelevant factors are influencing the scores, reducing validity","The examination has too high an inter-rater reliability for a practical test","The examination is criterion-referenced when it should be norm-referenced","The examination is formative in nature when it ought to be summative"],"answer":0,"explanation":"Scores should reflect scientific skills such as handling apparatus, observing and inferring; neatness and length are irrelevant to that construct, so they lower validity.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"कक्षा 8 की विज्ञान प्रायोगिक परीक्षा में विद्यार्थियों को मुख्यतः उनके आरेखों की साफ़-सफ़ाई और उनके अभिलेखों की लंबाई पर अंक दिए जाते हैं। मुख्य समस्या यह है कि:","optionsHi":["निर्माण-असंबद्ध कारक अंकों को प्रभावित कर रहे हैं, जिससे वैधता घटती है","प्रायोगिक परीक्षा के लिए परीक्षा की अंतर-मूल्यांकनकर्ता विश्वसनीयता बहुत अधिक है","परीक्षा मानदंड-संदर्भित है जबकि उसे मानक-संदर्भित होना चाहिए","परीक्षा रचनात्मक प्रकृति की है जबकि उसे योगात्मक होना चाहिए"],"explanationHi":"अंकों को उपकरण सँभालने, अवलोकन करने और निष्कर्ष निकालने जैसे वैज्ञानिक कौशलों को दर्शाना चाहिए; साफ़-सफ़ाई और लंबाई उस निर्मिति से असंबद्ध हैं, इसलिए वे वैधता घटाती हैं।"},
  {"id":"cdp-child-development-548","question":"At a parent–teacher meeting, a Class 6 child presents her portfolio to her parents, explains her goals and progress, and the teacher only facilitates. This student-led conference mainly:","options":["Shifts the responsibility for reporting from the teacher to the parents","Builds the child’s ownership of and reflection on her own learning","Removes the need for any assessment by the teacher","Suits only gifted children who speak confidently"],"answer":1,"explanation":"When children explain their own evidence and goals, they practise reflection and take ownership of learning; the teacher still assesses and guides.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"अभिभावक-शिक्षक बैठक में कक्षा 6 की एक बच्ची अपने माता-पिता के सामने अपना पोर्टफ़ोलियो प्रस्तुत करती है, अपने लक्ष्य और प्रगति समझाती है, और शिक्षक केवल सुगम बनाने का काम करता है। यह विद्यार्थी-नेतृत्व वाला सम्मेलन मुख्यतः:","optionsHi":["रिपोर्ट देने की ज़िम्मेदारी शिक्षक से माता-पिता पर डाल देता है","बच्ची में अपने अधिगम के प्रति स्वामित्व और चिंतन का भाव विकसित करता है","शिक्षक द्वारा किसी भी आकलन की आवश्यकता समाप्त कर देता है","केवल उन प्रतिभाशाली बच्चों के लिए उपयुक्त है जो आत्मविश्वास से बोलते हैं"],"explanationHi":"जब बच्चे अपने प्रमाण और लक्ष्य स्वयं समझाते हैं, तो वे चिंतन का अभ्यास करते हैं और अधिगम का स्वामित्व लेते हैं; शिक्षक फिर भी आकलन करता है और मार्गदर्शन देता है।"},
  {"id":"cdp-child-development-549","question":"Which is the best example of assessment OF learning being used appropriately?","options":["Grading a Class 6 student's first draft so that she knows her exact mark before she starts revising","Using a pre-test score at the start of the year to label a child ‘slow’ for the rest of the year","Certifying at the end of Class 8 which competencies each child has achieved, for parents and the next school","Giving marks for every homework task throughout the year so that students stay motivated to work"],"answer":2,"explanation":"Assessment of learning summarises achievement at the end of a period for reporting and certification; grading drafts or every homework, or labelling from a pre-test, misuses summative judgement.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"अधिगम का आकलन (असेसमेंट ऑफ़ लर्निंग) के उपयुक्त उपयोग का सर्वोत्तम उदाहरण कौन-सा है?","optionsHi":["कक्षा 6 की विद्यार्थी के पहले प्रारूप को अंक देना, ताकि संशोधन शुरू करने से पहले उसे अपने सटीक अंक पता हों","वर्ष के आरंभ में पूर्व-परीक्षण के अंक से किसी बच्चे को शेष वर्ष के लिए ‘धीमा’ घोषित करना","कक्षा 8 के अंत में अभिभावकों और अगले विद्यालय के लिए प्रमाणित करना कि प्रत्येक बच्चे ने कौन-सी दक्षताएँ प्राप्त की हैं","वर्ष भर प्रत्येक गृहकार्य पर अंक देना, ताकि विद्यार्थी काम करने के लिए प्रेरित रहें"],"explanationHi":"अधिगम का आकलन किसी अवधि के अंत में उपलब्धि को रिपोर्टिंग और प्रमाणन के लिए सारांशित करता है; प्रारूपों या हर गृहकार्य पर अंक देना, या पूर्व-परीक्षण से लेबल लगाना योगात्मक निर्णय का दुरुपयोग है।"},
  {"id":"cdp-child-development-550","question":"A teacher gives the same test to the same class on Monday and again on Tuesday and finds nearly identical scores. Why may this overstate the test’s reliability?","options":["Students may remember their Monday answers, which inflates agreement between the two sets of scores","One day is too long a gap, so genuine learning between the sittings has changed the scores","Test–retest reliability can be calculated only for essay-type tests, not for objective ones","Nearly identical scores on two sittings always indicate that the test has low validity"],"answer":0,"explanation":"With a very short gap, memory of the first sitting (carry-over effect) makes the scores agree more than the test’s true consistency warrants; very long gaps cause the opposite problem through real learning.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"एक शिक्षक एक ही कक्षा को सोमवार और फिर मंगलवार को वही परीक्षा देता है और लगभग एक जैसे अंक पाता है। इससे परीक्षण की विश्वसनीयता का अतिमूल्यांकन क्यों हो सकता है?","optionsHi":["विद्यार्थियों को सोमवार के अपने उत्तर याद हो सकते हैं, जिससे दोनों अंक-समूहों की सहमति बढ़ जाती है","एक दिन का अंतराल बहुत लंबा है, इसलिए दोनों बैठकों के बीच वास्तविक अधिगम ने अंकों को बदल दिया है","परीक्षण-पुनःपरीक्षण विश्वसनीयता केवल निबंध-प्रकार की परीक्षाओं के लिए गणना की जा सकती है, वस्तुनिष्ठ के लिए नहीं","दो बैठकों में लगभग एक जैसे अंक सदैव यह संकेत देते हैं कि परीक्षण की वैधता कम है"],"explanationHi":"बहुत छोटे अंतराल में पहली बैठक की स्मृति (अग्रवाहन प्रभाव) अंकों को परीक्षण की वास्तविक संगति से अधिक मिलाती है; बहुत लंबे अंतराल वास्तविक अधिगम के कारण उलटी समस्या पैदा करते हैं।"},
  {"id":"cdp-child-development-551","question":"Most Class 5 children in a Varanasi school say ‘heavy things sink and light things float’. The teacher floats a large wooden log in a tub and drops in a small iron nail, which sinks. The children look puzzled and begin to argue. In Piaget's terms, what is the teacher trying to bring about?","options":["Assimilation of the event into their existing idea, with no change to it","Disequilibrium that pushes children to accommodate, revising their idea","Conditioning of a new response through repeated pairing with the event","Rote memorisation of the rule of flotation through a vivid demonstration"],"answer":1,"explanation":"A discrepant event creates cognitive conflict (disequilibrium). To restore equilibrium the children must modify their schema, which Piaget called accommodation.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"वाराणसी के एक विद्यालय में कक्षा 5 के अधिकांश बच्चे कहते हैं ‘भारी चीज़ें डूबती हैं और हल्की चीज़ें तैरती हैं’। शिक्षक एक टब में लकड़ी का बड़ा लट्ठा तैराता है और एक छोटी लोहे की कील डालता है, जो डूब जाती है। बच्चे उलझन में पड़कर बहस करने लगते हैं। पियाजे के शब्दों में, शिक्षक क्या लाना चाहता है?","optionsHi":["घटना का उनके मौजूदा विचार में आत्मसात्करण, उसमें कोई परिवर्तन किए बिना","असंतुलन, जो बच्चों को समायोजन करके अपने विचार को संशोधित करने के लिए प्रेरित करे","घटना के साथ बार-बार जोड़ी बनाने से किसी नई अनुक्रिया का अनुबंधन","एक प्रभावशाली प्रदर्शन के माध्यम से प्लावन के नियम का रटंत स्मरण"],"explanationHi":"विसंगत घटना संज्ञानात्मक संघर्ष (असंतुलन) पैदा करती है। संतुलन पुनः पाने के लिए बच्चों को अपनी स्कीमा बदलनी पड़ती है, जिसे पियाजे ने समायोजन कहा।"},
  {"id":"cdp-child-development-552","question":"Two-year-old Chiku, who knows only ‘dog’, sees a calf and shouts ‘Big dog!’. His mother says, ‘No, that is a calf; see, it says moo and has hooves.’ After a few days Chiku correctly calls calves ‘calf’. Which part of this episode shows accommodation?","options":["Calling the calf a ‘big dog’ on first seeing it","The mother pointing at the calf and naming it for him","Forming a separate category for calves, distinct from dogs","Chiku continuing to call all the dogs he meets ‘dog’"],"answer":2,"explanation":"Fitting the calf into the existing dog schema was assimilation; creating a new schema for calves because the old one did not fit is accommodation.","difficulty":"hard","source":"CTET · UPTET","questionHi":"दो वर्ष का चीकू, जो केवल ‘कुत्ता’ जानता है, एक बछड़ा देखकर चिल्लाता है ‘बड़ा कुत्ता!’। उसकी माँ कहती है, ‘नहीं, यह बछड़ा है; देखो, यह म्याऊँ नहीं, रंभाता है और इसके खुर हैं।’ कुछ दिनों बाद चीकू बछड़ों को सही ढंग से ‘बछड़ा’ कहता है। इस प्रसंग का कौन-सा भाग समायोजन दर्शाता है?","optionsHi":["बछड़े को पहली बार देखने पर ‘बड़ा कुत्ता’ कहना","माँ द्वारा बछड़े की ओर इशारा करके उसका नाम बताना","बछड़ों के लिए कुत्तों से अलग एक पृथक श्रेणी बनाना","चीकू का मिलने वाले सभी कुत्तों को ‘कुत्ता’ कहते रहना"],"explanationHi":"बछड़े को मौजूदा कुत्ते की स्कीमा में बैठाना आत्मसात्करण था; पुरानी स्कीमा के उपयुक्त न होने पर बछड़ों के लिए नई स्कीमा बनाना समायोजन है।"},
  {"id":"cdp-child-development-553","question":"Which of these classroom practices is LEAST consistent with a constructivist view of learning?","options":["Asking children to predict what will happen before an experiment is done","Starting a topic by finding out what children already think about it","Letting groups compare and justify their different methods of solution","Dictating notes so that every child memorises the same correct answers"],"answer":3,"explanation":"Constructivism holds that learners build knowledge actively from experience and prior ideas. Dictated notes treat the learner as a passive receiver of ready-made knowledge.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"इनमें से कौन-सी कक्षा-प्रथा अधिगम के रचनावादी दृष्टिकोण से सबसे कम मेल खाती है?","optionsHi":["प्रयोग करने से पहले बच्चों से अनुमान लगवाना कि क्या होगा","किसी विषय की शुरुआत यह पता लगाकर करना कि बच्चे उसके बारे में पहले से क्या सोचते हैं","समूहों को अपनी भिन्न हल-विधियों की तुलना और औचित्य सिद्ध करने देना","श्रुतलेख द्वारा नोट्स लिखवाना, ताकि प्रत्येक बच्चा वही सही उत्तर रट ले"],"explanationHi":"रचनावाद मानता है कि अधिगमकर्ता अनुभव और पूर्व विचारों से सक्रिय रूप से ज्ञान का निर्माण करते हैं। श्रुतलेख वाले नोट्स अधिगमकर्ता को तैयार ज्ञान के निष्क्रिय ग्राहक के रूप में देखते हैं।"},
  {"id":"cdp-child-development-554","question":"Mohit, in Class 4, can add two-digit numbers on his own. With hints and a place-value chart he can add three-digit numbers with carrying, but even with help he cannot follow long division. Where should the teacher pitch her next lessons according to Vygotsky?","options":["Three-digit addition with carrying, with support she gradually withdraws","Two-digit addition, which he should keep practising until he is perfect at it","Long division, because a tougher challenge always speeds up development","Any topic at all, since maturation alone fixes the order in which he learns"],"answer":0,"explanation":"The Zone of Proximal Development lies between what a child can do alone and what he can do with help. Three-digit addition is in his ZPD; long division is beyond it even with support.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 का मोहित स्वयं दो अंकों की संख्याएँ जोड़ सकता है। संकेतों और स्थानीय मान तालिका की सहायता से वह हासिल वाला तीन अंकों का जोड़ कर सकता है, पर सहायता के साथ भी वह लंबा भाग नहीं समझ पाता। वाइगोत्स्की के अनुसार शिक्षिका को अपने अगले पाठ किस स्तर पर रखने चाहिए?","optionsHi":["हासिल वाला तीन अंकों का जोड़, ऐसी सहायता के साथ जिसे वह धीरे-धीरे हटाती जाए","दो अंकों का जोड़, जिसका अभ्यास वह तब तक करता रहे जब तक उसमें पूर्णता न आ जाए","लंबा भाग, क्योंकि कठिन चुनौती सदैव विकास को तेज़ करती है","कोई भी विषय, क्योंकि परिपक्वता अकेले उसके सीखने का क्रम तय करती है"],"explanationHi":"निकटस्थ विकास का क्षेत्र बच्चे के अकेले कर सकने और सहायता से कर सकने के बीच में स्थित होता है। तीन अंकों का जोड़ उसके ZPD में है; लंबा भाग सहायता के साथ भी उसके परे है।"},
  {"id":"cdp-child-development-555","question":"A teacher helping Class 3 children write a letter first gives a full template with sentence starters, then only headings, then just a checklist, and finally nothing. This gradual change mainly reflects which feature of scaffolding?","options":["Rewarding every correct sentence to strengthen it","Fading of support as competence grows","Assimilation of the new letter format into a schema","Moving from abstract rules to concrete examples"],"answer":1,"explanation":"Scaffolding is temporary: support is reduced step by step and handed over to the learner as she becomes able to do the task independently.","difficulty":"moderate","source":"CTET · REET","questionHi":"कक्षा 3 के बच्चों को पत्र लिखने में सहायता करते हुए एक शिक्षक पहले वाक्यारंभों सहित पूरा ढाँचा देता है, फिर केवल शीर्षक, फिर केवल एक जाँच-सूची, और अंत में कुछ नहीं। यह क्रमिक परिवर्तन मुख्यतः पाड़ (स्कैफ़ोल्डिंग) की किस विशेषता को दर्शाता है?","optionsHi":["प्रत्येक सही वाक्य को पुरस्कृत करके उसे सुदृढ़ करना","सक्षमता बढ़ने के साथ सहायता का क्रमशः कम होना","नए पत्र-प्रारूप का किसी स्कीमा में आत्मसात्करण","अमूर्त नियमों से ठोस उदाहरणों की ओर जाना"],"explanationHi":"पाड़ अस्थायी होता है: सहायता को चरण-दर-चरण घटाया जाता है और जैसे-जैसे अधिगमकर्ता कार्य को स्वतंत्र रूप से करने में सक्षम होता है, उसे उसे सौंप दिया जाता है।"},
  {"id":"cdp-child-development-556","question":"In a Class 6 reading period, the teacher and small groups take turns to lead the discussion of a passage. The leader asks the group to predict what comes next, frame questions, clear up confusing words and summarise each part. This approach is:","options":["Programmed instruction, based on Skinner's work","Discovery learning, based on Bruner's ideas","Reciprocal teaching, rooted in Vygotsky's ideas","Rote reading aloud, to build reading fluency"],"answer":2,"explanation":"Reciprocal teaching (Palincsar and Brown) uses four strategies: predicting, questioning, clarifying and summarising. The teacher models them and gradually hands over the leader role, as in Vygotsky's view of guided participation.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 के पठन कालांश में शिक्षक और छोटे समूह बारी-बारी से किसी गद्यांश की चर्चा का नेतृत्व करते हैं। नेता समूह से अनुमान लगवाता है कि आगे क्या आएगा, प्रश्न बनवाता है, भ्रमित करने वाले शब्द स्पष्ट करता है और प्रत्येक भाग का सारांश करवाता है। यह उपागम है:","optionsHi":["अभिक्रमित अनुदेशन, जो स्किनर के कार्य पर आधारित है","खोज द्वारा अधिगम, जो ब्रूनर के विचारों पर आधारित है","पारस्परिक शिक्षण, जिसकी जड़ें वाइगोत्स्की के विचारों में हैं","रटंत ज़ोर से पढ़ना, पठन-प्रवाह बनाने के लिए"],"explanationHi":"पारस्परिक शिक्षण (पैलिंक्सर और ब्राउन) चार युक्तियों का प्रयोग करता है: अनुमान लगाना, प्रश्न पूछना, स्पष्ट करना और सारांश बनाना। शिक्षक उनका प्रतिरूपण करता है और धीरे-धीरे नेता की भूमिका सौंप देता है, जैसा वाइगोत्स्की के निर्देशित सहभागिता के विचार में है।"},
  {"id":"cdp-child-development-557","question":"While solving a puzzle, Class 1 child Anu mutters, ‘This piece is blue... no, it goes at the top... now the corner.’ How would Vygotsky interpret this talk and what should the teacher do?","options":["It is egocentric speech showing she cannot take others' view; the teacher should stop it","It is a sign of a speech disorder; she should be referred for therapy","It is attention-seeking; the teacher should ignore it so it extinguishes","It is private speech that helps her guide her own thinking; the teacher should allow it"],"answer":3,"explanation":"For Vygotsky, private speech is a tool of self-regulation that later becomes inner speech, and it increases on harder tasks. Calling it merely egocentric is Piaget's view.","difficulty":"very-hard","source":"CTET Paper 1 · Super TET","questionHi":"पहेली हल करते समय कक्षा 1 की बच्ची अनु बुदबुदाती है, ‘यह टुकड़ा नीला है... नहीं, यह ऊपर जाएगा... अब कोना।’ वाइगोत्स्की इस बोलने की व्याख्या कैसे करते और शिक्षक को क्या करना चाहिए?","optionsHi":["यह अहंकेंद्रित वाणी है जो दर्शाती है कि वह दूसरों का दृष्टिकोण नहीं ले सकती; शिक्षक को इसे रोकना चाहिए","यह वाणी-विकार का संकेत है; उसे चिकित्सा के लिए भेजा जाना चाहिए","यह ध्यान आकर्षित करने की चेष्टा है; शिक्षक को इसे अनदेखा करना चाहिए ताकि यह समाप्त हो जाए","यह निजी वाणी है जो उसे अपनी सोच का मार्गदर्शन करने में सहायता करती है; शिक्षक को इसकी अनुमति देनी चाहिए"],"explanationHi":"वाइगोत्स्की के लिए निजी वाणी स्व-नियमन का एक उपकरण है जो बाद में आंतरिक वाणी बन जाती है, और कठिन कार्यों पर यह बढ़ जाती है। इसे केवल अहंकेंद्रित कहना पियाजे का मत है।"},
  {"id":"cdp-child-development-558","question":"Assertion (A): Vygotsky held that good instruction can run ahead of and lead development. Reason (R): Teaching within the Zone of Proximal Development awakens functions that are still in the process of maturing.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Unlike Piaget, who saw development as setting limits on learning, Vygotsky argued that instruction aimed at the ZPD pulls development forward; R is precisely why.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"अभिकथन (A): वाइगोत्स्की का मत था कि अच्छा अनुदेशन विकास से आगे चल सकता है और उसका नेतृत्व कर सकता है। कारण (R): निकटस्थ विकास के क्षेत्र में शिक्षण उन प्रकार्यों को जगाता है जो अभी परिपक्व होने की प्रक्रिया में हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"पियाजे के विपरीत, जो विकास को अधिगम की सीमाएँ तय करने वाला मानते थे, वाइगोत्स्की का तर्क था कि ZPD को लक्षित अनुदेशन विकास को आगे खींचता है; R ठीक यही कारण है।"},
  {"id":"cdp-child-development-559","question":"To introduce halves, a Class 2 teacher first has children fold and tear chapatis and paper, then draw pictures of shapes split into two equal parts, and only then write ½. Which theorist's sequence of representation is she following?","options":["Piaget's stages of cognitive development, from sensorimotor to formal","Bruner's enactive, iconic and symbolic modes of representation","Gagné's hierarchy of learning types, from signal learning upwards","Kohlberg's levels of moral reasoning, from pre- to post-conventional"],"answer":1,"explanation":"Bruner proposed three modes of representing knowledge: through action (enactive), images (iconic) and symbols (symbolic). Moving from folding to drawing to writing ½ follows this order.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"आधे की अवधारणा सिखाने के लिए कक्षा 2 की शिक्षिका पहले बच्चों से चपाती और कागज़ को मोड़वाती और फाड़वाती है, फिर दो बराबर भागों में बँटी आकृतियों के चित्र बनवाती है, और उसके बाद ही ½ लिखवाती है। वह किस सिद्धांतकार के निरूपण के क्रम का अनुसरण कर रही है?","optionsHi":["पियाजे के संज्ञानात्मक विकास की अवस्थाएँ, संवेदी-गामक से औपचारिक तक","ब्रूनर के निरूपण के क्रियात्मक, प्रतिबिंबात्मक और सांकेतिक पक्ष","गेने का अधिगम प्रकारों का पदानुक्रम, संकेत अधिगम से ऊपर की ओर","कोहलबर्ग के नैतिक चिंतन के स्तर, पूर्व- से उत्तर-रूढ़िगत तक"],"explanationHi":"ब्रूनर ने ज्ञान के निरूपण के तीन पक्ष बताए: क्रिया (क्रियात्मक), प्रतिबिंब (प्रतिबिंबात्मक) और प्रतीक (सांकेतिक)। मोड़ने से चित्र बनाने और फिर ½ लिखने की ओर जाना इसी क्रम का अनुसरण है।"},
  {"id":"cdp-child-development-560","question":"A school's science syllabus introduces ‘plants need water and light’ in Class 2, revisits it through simple experiments in Class 5, and returns to it as photosynthesis with equations in Class 10. This design reflects:","options":["Thorndike's law of exercise","Gestalt law of closure","Bruner's spiral curriculum","Skinner's linear programming"],"answer":2,"explanation":"In a spiral curriculum the same big ideas are revisited at increasing levels of depth and abstraction as children grow. Simple repetition (law of exercise) does not deepen the idea each time.","difficulty":"moderate","source":"CTET · HTET","questionHi":"एक विद्यालय का विज्ञान पाठ्यक्रम ‘पौधों को पानी और प्रकाश की आवश्यकता होती है’ को कक्षा 2 में प्रस्तुत करता है, कक्षा 5 में सरल प्रयोगों द्वारा पुनः देखता है, और कक्षा 10 में समीकरणों सहित प्रकाश-संश्लेषण के रूप में लौटता है। यह रचना दर्शाती है:","optionsHi":["थॉर्नडाइक का अभ्यास का नियम","गेस्टाल्ट का समापन का नियम","ब्रूनर की सर्पिल पाठ्यचर्या","स्किनर का रैखिक अभिक्रमण"],"explanationHi":"सर्पिल पाठ्यचर्या में बच्चों के बड़े होने के साथ वही बड़े विचार बढ़ती गहराई और अमूर्तता के स्तरों पर दोहराए जाते हैं। साधारण दोहराव (अभ्यास का नियम) हर बार विचार को गहरा नहीं करता।"},
  {"id":"cdp-child-development-561","question":"A teacher asks: what does research most firmly support about discovery learning for school children?","options":["Pure, unguided discovery is always better than any kind of teacher explanation","Discovery learning is unsuitable for primary school children, who need firm rules first","Telling children every rule first and then giving only practice works best for all","Guided discovery, with well-designed tasks and timely prompts, beats unguided discovery"],"answer":3,"explanation":"Children with little prior knowledge often flounder or form misconceptions in unguided discovery; structured tasks, prompts and feedback make discovery productive. Pure telling misses the benefits of active construction.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षक पूछता है: विद्यालयी बच्चों के लिए खोज-अधिगम के बारे में शोध सबसे दृढ़ता से क्या समर्थन करता है?","optionsHi":["शुद्ध, बिना निर्देशन की खोज सदैव शिक्षक की किसी भी व्याख्या से बेहतर है","खोज-अधिगम प्राथमिक विद्यालय के बच्चों के लिए अनुपयुक्त है, जिन्हें पहले पक्के नियम चाहिए","बच्चों को पहले हर नियम बताकर फिर केवल अभ्यास देना सभी के लिए सबसे अच्छा है","सुनियोजित कार्यों और समय पर संकेतों के साथ निर्देशित खोज, बिना निर्देशन की खोज से बेहतर है"],"explanationHi":"कम पूर्व ज्ञान वाले बच्चे बिना निर्देशन की खोज में प्रायः भटकते हैं या भ्रांतियाँ बना लेते हैं; संरचित कार्य, संकेत और प्रतिपुष्टि खोज को उत्पादक बनाते हैं। केवल बताना सक्रिय निर्माण के लाभ खो देता है।"},
  {"id":"cdp-child-development-562","question":"Before a lesson on rocks, a Class 7 teacher spends three minutes presenting a short overview: ‘All rocks form in one of three ways: by cooling, by settling in layers, or by being changed by heat and pressure.’ She then teaches each type. This overview is best described as:","options":["An advance organiser in Ausubel's meaningful reception learning","A discriminative stimulus that cues responses in operant conditioning","A spiral curriculum, as described in Bruner's theory of instruction","Shaping by successive approximation towards the full classification"],"answer":0,"explanation":"Ausubel's advance organiser is a brief, general framework given before new material so that new details can be anchored to an organised structure in the learner's mind.","difficulty":"hard","source":"KVS TGT · DSSSB TGT","questionHi":"चट्टानों पर पाठ से पहले कक्षा 7 की शिक्षिका तीन मिनट एक संक्षिप्त अवलोकन प्रस्तुत करती है: ‘सभी चट्टानें तीन में से किसी एक ढंग से बनती हैं: ठंडा होने से, परतों में जमने से, या ऊष्मा और दाब द्वारा बदल जाने से।’ फिर वह प्रत्येक प्रकार को पढ़ाती है। इस अवलोकन का सबसे सही वर्णन है:","optionsHi":["ऑसुबेल के सार्थक ग्रहणशील अधिगम में एक अग्र-व्यवस्थापक (एडवांस ऑर्गेनाइज़र)","संक्रियात्मक अनुबंधन में अनुक्रियाओं को संकेत देने वाला विभेदक उद्दीपक","सर्पिल पाठ्यचर्या, जैसा ब्रूनर के अनुदेशन सिद्धांत में वर्णित है","पूर्ण वर्गीकरण की ओर क्रमिक सन्निकटन द्वारा आकार-निर्धारण"],"explanationHi":"ऑसुबेल का अग्र-व्यवस्थापक नई सामग्री से पहले दिया गया एक संक्षिप्त, सामान्य ढाँचा है ताकि नए ब्योरों को अधिगमकर्ता के मन की संगठित संरचना में टिकाया जा सके।"},
  {"id":"cdp-child-development-563","question":"‘The most important single factor influencing learning is what the learner already knows; ascertain this and teach accordingly.’ Which classroom step most directly applies this idea of Ausubel?","options":["Giving a surprise test at the end of the chapter to see what was retained","Beginning a chapter by drawing out what the children already know and believe","Making children memorise the key terms before any discussion of them","Grouping children by age for every activity, so that levels are matched"],"answer":1,"explanation":"Ausubel stressed anchoring new learning to existing knowledge. Eliciting prior ideas at the start lets the teacher connect new material to them and spot misconceptions.","difficulty":"moderate","source":"CTET Paper 1 · REET","questionHi":"‘अधिगम को प्रभावित करने वाला सबसे महत्त्वपूर्ण एकल कारक यह है कि अधिगमकर्ता पहले से क्या जानता है; इसका पता लगाइए और उसी के अनुसार पढ़ाइए।’ ऑसुबेल के इस विचार को कक्षा का कौन-सा कदम सबसे सीधे लागू करता है?","optionsHi":["अध्याय के अंत में अचानक परीक्षा लेना, यह देखने के लिए कि क्या याद रहा","अध्याय का आरंभ यह निकलवाकर करना कि बच्चे पहले से क्या जानते और मानते हैं","चर्चा से पहले ही बच्चों को मुख्य शब्द रटवाना","प्रत्येक गतिविधि के लिए बच्चों को आयु के अनुसार समूहबद्ध करना, ताकि स्तर मिलते रहें"],"explanationHi":"ऑसुबेल ने नए अधिगम को मौजूदा ज्ञान से जोड़ने पर बल दिया। आरंभ में पूर्व विचारों को निकलवाने से शिक्षक नई सामग्री को उनसे जोड़ सकता है और भ्रांतियाँ पहचान सकता है।"},
  {"id":"cdp-child-development-564","question":"Two Class 4 children both score 40% on a test taken alone. With the same hints from the teacher, one rises to 80% and the other to 50%. A Vygotskian teacher would conclude that:","options":["Both children are at the same level, since their unaided scores are equal","The second child should simply be given harder work so that he catches up","The first child has a wider zone of proximal development and different needs","Hints spoil the validity of an assessment and so should never be given"],"answer":2,"explanation":"Dynamic assessment measures what a child can do with help as well as alone. Equal independent scores can hide very different ZPDs, which matter for planning instruction.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 4 के दो बच्चे अकेले दी गई परीक्षा में 40% अंक पाते हैं। शिक्षक के समान संकेतों के साथ एक के अंक 80% और दूसरे के 50% हो जाते हैं। वाइगोत्स्कीवादी शिक्षक निष्कर्ष निकालेगा कि:","optionsHi":["दोनों बच्चे समान स्तर पर हैं, क्योंकि उनके बिना-सहायता के अंक बराबर हैं","दूसरे बच्चे को कठिन कार्य दिया जाना चाहिए ताकि वह बराबरी पर आ जाए","पहले बच्चे का निकटस्थ विकास का क्षेत्र अधिक विस्तृत है और उसकी आवश्यकताएँ भिन्न हैं","संकेत आकलन की वैधता बिगाड़ते हैं और इसलिए कभी नहीं दिए जाने चाहिए"],"explanationHi":"गत्यात्मक आकलन यह मापता है कि बच्चा सहायता के साथ और अकेले क्या कर सकता है। समान स्वतंत्र अंक बहुत भिन्न ZPD को छिपा सकते हैं, जो अनुदेशन की योजना के लिए महत्त्वपूर्ण हैं।"},
  {"id":"cdp-child-development-565","question":"Which of these statements about the ‘more knowledgeable other’ in Vygotsky's theory are correct? I. It may be a classmate rather than an adult. II. It may be a younger person who knows more about a specific task. III. It must always be the class teacher. IV. Its help is most useful within the learner's zone of proximal development.","options":["I and III only","II and III only","I, III and IV only","I, II and IV only"],"answer":3,"explanation":"The MKO is anyone with greater skill in that particular task: a peer, a younger sibling who knows phones better, or an adult. Help works best when it targets the ZPD.","difficulty":"hard","source":"CTET · UPTET","questionHi":"वाइगोत्स्की के सिद्धांत में ‘अधिक ज्ञानी अन्य’ (मोर नॉलेजेबल अदर) के बारे में इनमें से कौन-से कथन सही हैं? I. यह वयस्क के बजाय कोई सहपाठी भी हो सकता है। II. यह कोई छोटा व्यक्ति भी हो सकता है जो किसी विशिष्ट कार्य के बारे में अधिक जानता हो। III. यह सदैव कक्षा-शिक्षक ही होना चाहिए। IV. इसकी सहायता अधिगमकर्ता के निकटस्थ विकास के क्षेत्र के भीतर सबसे अधिक उपयोगी होती है।","optionsHi":["केवल I और III","केवल II और III","केवल I, III और IV","केवल I, II और IV"],"explanationHi":"MKO वह कोई भी है जिसके पास उस विशेष कार्य में अधिक कौशल हो: सहपाठी, छोटा भाई-बहन जो फ़ोन बेहतर जानता हो, या कोई वयस्क। सहायता तब सबसे अच्छा काम करती है जब वह ZPD को लक्षित करे।"},
  {"id":"cdp-child-development-566","question":"Assertion (A): Simply telling Class 6 students the correct explanation of day and night often fails to remove their misconception that the Sun goes round the Earth. Reason (R): Learners tend to interpret new information through their existing ideas, so it can be bent to fit the old belief rather than replace it.","options":["Both A and R are true and R is the correct explanation of A","A is true but R is false","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":0,"explanation":"Constructivism predicts that new input is assimilated into prior schemas; without cognitive conflict and active reconstruction, misconceptions persist. R explains A.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"अभिकथन (A): कक्षा 6 के विद्यार्थियों को दिन और रात की सही व्याख्या केवल बता देने से प्रायः उनकी यह भ्रांति दूर नहीं होती कि सूर्य पृथ्वी के चारों ओर घूमता है। कारण (R): अधिगमकर्ता नई जानकारी की व्याख्या अपने मौजूदा विचारों के माध्यम से करते हैं, इसलिए उसे पुरानी मान्यता को बदलने के बजाय उसी में ढाल लिया जा सकता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A असत्य है परंतु R सत्य है"],"explanationHi":"रचनावाद पूर्वानुमान करता है कि नया निवेश पूर्व स्कीमाओं में आत्मसात् हो जाता है; संज्ञानात्मक संघर्ष और सक्रिय पुनर्निर्माण के बिना भ्रांतियाँ बनी रहती हैं। R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-567","question":"A Class 5 teacher forms groups for a mapping project. Which grouping best uses Vygotsky's ideas?","options":["All high achievers grouped together, so that they are not held back by others","Mixed-ability groups in which children explain and support one another","Each child working alone on the map, so that there is no copying at all","Groups chosen by roll number, with no thought given to ability or interest"],"answer":1,"explanation":"Mixed groups let more able children act as more knowledgeable others and let all children work within their ZPD through dialogue. Explaining also deepens the helper's own understanding.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक शिक्षिका मानचित्रण परियोजना के लिए समूह बनाती है। वाइगोत्स्की के विचारों का सबसे अच्छा उपयोग कौन-सा समूहन करता है?","optionsHi":["सभी उच्च उपलब्धि वाले बच्चों को साथ रखना, ताकि दूसरे उन्हें पीछे न खींचें","मिश्रित क्षमता वाले समूह जिनमें बच्चे एक-दूसरे को समझाएँ और सहयोग दें","प्रत्येक बच्चे का मानचित्र पर अकेले काम करना, ताकि नकल बिल्कुल न हो","क्रमांक के आधार पर चुने गए समूह, जिनमें क्षमता या रुचि पर कोई विचार न किया जाए"],"explanationHi":"मिश्रित समूह अधिक सक्षम बच्चों को अधिक ज्ञानी अन्य की भूमिका निभाने देते हैं और संवाद के माध्यम से सभी बच्चों को अपने ZPD के भीतर कार्य करने देते हैं। समझाने से सहायक की अपनी समझ भी गहरी होती है।"},
  {"id":"cdp-child-development-568","question":"Which statement about the teacher's role in a constructivist classroom is accurate?","options":["The teacher stays silent and leaves children entirely to discover everything","The teacher mainly transmits correct information as clearly and efficiently as possible","The teacher designs problems, probes children's thinking and guides their understanding","The teacher's role ends once the activity sheets have been handed out to groups"],"answer":2,"explanation":"Constructivist teachers are facilitators, not absent: they plan rich tasks, ask questions that reveal thinking, challenge misconceptions and support learners. Pure transmission is the opposite model.","difficulty":"moderate","source":"CTET · REET","questionHi":"रचनावादी कक्षा में शिक्षक की भूमिका के बारे में कौन-सा कथन सही है?","optionsHi":["शिक्षक चुप रहता है और बच्चों को सब कुछ पूरी तरह स्वयं खोजने के लिए छोड़ देता है","शिक्षक मुख्यतः सही जानकारी को यथासंभव स्पष्ट और कुशल ढंग से संप्रेषित करता है","शिक्षक समस्याएँ रचता है, बच्चों की सोच की पड़ताल करता है और उनकी समझ का मार्गदर्शन करता है","समूहों को गतिविधि-पत्र बाँट देने के बाद शिक्षक की भूमिका समाप्त हो जाती है"],"explanationHi":"रचनावादी शिक्षक सुगमकर्ता होते हैं, अनुपस्थित नहीं: वे समृद्ध कार्य नियोजित करते हैं, सोच प्रकट करने वाले प्रश्न पूछते हैं, भ्रांतियों को चुनौती देते हैं और अधिगमकर्ताओं की सहायता करते हैं। शुद्ध संप्रेषण इसका उलटा मॉडल है।"},
  {"id":"cdp-child-development-569","question":"Class 4 children in a Nashik village learn measurement by weighing vegetables at the weekly haat with a shopkeeper, estimating and checking weights, and recording prices. This most closely reflects:","options":["Programmed learning, in which the content is broken into small graded frames","Classical conditioning of number responses through repeated market experiences","Rote learning of the weights and measures tables through daily repetition","Situated learning, with knowledge built through participation in authentic activity"],"answer":3,"explanation":"Situated learning holds that knowledge is closely tied to the activity and context in which it is used; authentic participation makes concepts meaningful and transferable to life.","difficulty":"hard","source":"CTET Paper 1 · Super TET","questionHi":"नासिक के एक गाँव में कक्षा 4 के बच्चे साप्ताहिक हाट में दुकानदार के साथ सब्ज़ियाँ तौलकर, वज़न का अनुमान लगाकर और जाँचकर, तथा कीमतें दर्ज करके मापन सीखते हैं। यह सबसे अधिक किसको दर्शाता है?","optionsHi":["अभिक्रमित अधिगम, जिसमें सामग्री को छोटे श्रेणीबद्ध फ्रेमों में तोड़ा जाता है","बाज़ार के बार-बार के अनुभवों द्वारा संख्या-अनुक्रियाओं का शास्त्रीय अनुबंधन","दैनिक दोहराव द्वारा तौल और माप की सारणियों का रटंत अधिगम","स्थित अधिगम, जिसमें ज्ञान प्रामाणिक गतिविधि में भागीदारी से निर्मित होता है"],"explanationHi":"स्थित अधिगम मानता है कि ज्ञान उस गतिविधि और संदर्भ से गहराई से जुड़ा होता है जिसमें उसका उपयोग होता है; प्रामाणिक भागीदारी अवधारणाओं को सार्थक और जीवन में हस्तांतरणीय बनाती है।"},
  {"id":"cdp-child-development-570","question":"Which statement correctly contrasts how Piaget and Vygotsky viewed children's social interaction in learning?","options":["Piaget valued interaction among equals for the conflict it creates; Vygotsky stressed guidance from more capable others","Piaget believed that only adults can really teach children, while Vygotsky thought interaction with peers was useless","Both held that social interaction plays no real role in cognitive development, which is driven by maturation alone","Vygotsky valued only conflict and disagreement between peers, while Piaget stressed guidance from adults"],"answer":0,"explanation":"Piaget saw peer disagreement between equals as a trigger for disequilibrium; Vygotsky emphasised collaboration with a more knowledgeable other within the ZPD.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अधिगम में बच्चों की सामाजिक अंतःक्रिया को पियाजे और वाइगोत्स्की किस प्रकार देखते थे, इसकी सही तुलना कौन-सा कथन करता है?","optionsHi":["पियाजे ने बराबर वालों के बीच अंतःक्रिया को उससे उत्पन्न संघर्ष के कारण महत्त्व दिया; वाइगोत्स्की ने अधिक सक्षम अन्य से मार्गदर्शन पर बल दिया","पियाजे मानते थे कि केवल वयस्क ही बच्चों को वास्तव में सिखा सकते हैं, जबकि वाइगोत्स्की के अनुसार सहपाठियों के साथ अंतःक्रिया निरर्थक थी","दोनों मानते थे कि संज्ञानात्मक विकास में सामाजिक अंतःक्रिया की कोई वास्तविक भूमिका नहीं है, जो केवल परिपक्वता से संचालित होता है","वाइगोत्स्की केवल सहपाठियों के बीच संघर्ष और असहमति को महत्त्व देते थे, जबकि पियाजे ने वयस्कों के मार्गदर्शन पर बल दिया"],"explanationHi":"पियाजे बराबर वालों की असहमति को असंतुलन का प्रेरक मानते थे; वाइगोत्स्की ने ZPD के भीतर अधिक ज्ञानी अन्य के साथ सहयोग पर बल दिया।"},
  {"id":"cdp-child-development-571","question":"Students in a tribal area of Jharkhand discuss a science problem in their home language, Santhali, before writing their answers in Hindi. From Vygotsky's perspective, why is this valuable?","options":["It keeps the children quiet and disciplined, since they feel at ease in their own language","Language is a key tool for thinking, so a familiar language lets them reason more deeply","It allows the teacher to skip explaining the concept, since peers will explain it instead","It reduces the need for them to learn a second language such as Hindi or English later"],"answer":1,"explanation":"Vygotsky saw language as the main tool of thought. Talking through ideas in a language children command supports concept building; NCF 2005 also treats multilingualism as a resource.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"झारखंड के एक जनजातीय क्षेत्र के विद्यार्थी अपने उत्तर हिंदी में लिखने से पहले एक विज्ञान की समस्या पर अपनी घरेलू भाषा संथाली में चर्चा करते हैं। वाइगोत्स्की के दृष्टिकोण से यह मूल्यवान क्यों है?","optionsHi":["यह बच्चों को शांत और अनुशासित रखता है, क्योंकि वे अपनी भाषा में सहज महसूस करते हैं","भाषा चिंतन का एक प्रमुख उपकरण है, इसलिए परिचित भाषा उन्हें अधिक गहराई से तर्क करने देती है","इससे शिक्षक अवधारणा समझाना छोड़ सकता है, क्योंकि सहपाठी उसे समझा देंगे","इससे बाद में हिंदी या अंग्रेज़ी जैसी दूसरी भाषा सीखने की आवश्यकता घट जाती है"],"explanationHi":"वाइगोत्स्की ने भाषा को चिंतन का मुख्य उपकरण माना। जिस भाषा पर बच्चों की पकड़ है उसमें विचारों पर बात करना संप्रत्यय निर्माण में सहायक है; NCF 2005 भी बहुभाषिकता को एक संसाधन मानती है।"},
  {"id":"cdp-child-development-572","question":"Which of these ideas is shared by both Piaget and Vygotsky?","options":["Development proceeds through four universal stages in a fixed order","Learning can lead development and pull it forward ahead of maturation","Children are active constructors of knowledge, not passive receivers","Private speech disappears because it is merely egocentric and immature"],"answer":2,"explanation":"Both were constructivists who saw the child as active. Fixed stages and egocentric speech are Piagetian ideas; learning leading development is Vygotsky's.","difficulty":"hard","source":"CTET · HTET","questionHi":"इनमें से कौन-सा विचार पियाजे और वाइगोत्स्की दोनों में समान है?","optionsHi":["विकास चार सार्वभौमिक अवस्थाओं से एक निश्चित क्रम में होता है","अधिगम विकास का नेतृत्व कर सकता है और उसे परिपक्वता से आगे खींच सकता है","बच्चे ज्ञान के सक्रिय निर्माता हैं, निष्क्रिय ग्राहक नहीं","निजी वाणी समाप्त हो जाती है क्योंकि वह केवल अहंकेंद्रित और अपरिपक्व है"],"explanationHi":"दोनों रचनावादी थे जो बच्चे को सक्रिय मानते थे। निश्चित अवस्थाएँ और अहंकेंद्रित वाणी पियाजे के विचार हैं; अधिगम का विकास का नेतृत्व करना वाइगोत्स्की का है।"},
  {"id":"cdp-child-development-573","question":"A Class 8 teacher asks pupils to draw a concept map of ‘nutrition in plants’, linking terms with labelled arrows such as ‘needs’, ‘produces’ and ‘occurs in’. Which purpose does this serve best?","options":["It ensures that pupils memorise the textbook definitions word for word","It replaces the need for any experiments or observation of real plants","It is mainly a way of keeping fast learners busy while others catch up","It shows how pupils organise and relate ideas, revealing gaps and errors"],"answer":3,"explanation":"Concept maps (developed by Novak from Ausubel's ideas) make the learner's knowledge structure visible, so missing or wrong links can be spotted and discussed.","difficulty":"hard","source":"KVS TGT · NVS TGT","questionHi":"कक्षा 8 की एक शिक्षिका विद्यार्थियों से ‘पौधों में पोषण’ का संप्रत्यय मानचित्र बनवाती है, जिसमें शब्दों को ‘की आवश्यकता’, ‘उत्पन्न करता है’ और ‘में होता है’ जैसे नामांकित तीरों से जोड़ा जाता है। यह किस उद्देश्य को सबसे अच्छी तरह पूरा करता है?","optionsHi":["यह सुनिश्चित करता है कि विद्यार्थी पाठ्यपुस्तक की परिभाषाएँ शब्दशः रट लें","यह वास्तविक पौधों के किसी भी प्रयोग या अवलोकन की आवश्यकता को समाप्त कर देता है","यह मुख्यतः तेज़ सीखने वालों को व्यस्त रखने का तरीका है जबकि दूसरे बराबरी पर आते हैं","यह दिखाता है कि विद्यार्थी विचारों को कैसे व्यवस्थित और परस्पर संबद्ध करते हैं, जिससे कमियाँ और त्रुटियाँ उजागर होती हैं"],"explanationHi":"संप्रत्यय मानचित्र (जो नोवाक ने ऑसुबेल के विचारों से विकसित किए) अधिगमकर्ता की ज्ञान-संरचना को दृश्य बनाते हैं, ताकि छूटे या गलत संबंध पहचाने और उन पर चर्चा की जा सके।"},
  {"id":"cdp-child-development-574","question":"Which classroom practice best reflects the constructivist emphasis of the National Curriculum Framework 2005?","options":["Connecting classroom knowledge with children's life outside school, and letting them explore","Finishing the textbook early, so that more time is left for revision before the examinations","Treating the textbook as the only legitimate source of knowledge for the class to rely on","Giving children well-written model answers to learn thoroughly for their examinations"],"answer":0,"explanation":"NCF 2005 asks that knowledge be linked to life outside school, that learning move away from rote methods, and that children be active constructors of knowledge.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"राष्ट्रीय पाठ्यचर्या की रूपरेखा 2005 के रचनावादी बल को कक्षा की कौन-सी प्रथा सबसे अच्छी तरह दर्शाती है?","optionsHi":["कक्षा के ज्ञान को विद्यालय के बाहर के बच्चों के जीवन से जोड़ना और उन्हें अन्वेषण करने देना","पाठ्यपुस्तक जल्दी समाप्त करना, ताकि परीक्षा से पहले पुनरावर्तन के लिए अधिक समय बचे","पाठ्यपुस्तक को ज्ञान का एकमात्र वैध स्रोत मानना, जिस पर कक्षा निर्भर रहे","बच्चों को परीक्षाओं के लिए भली-भाँति सीखने हेतु अच्छे ढंग से लिखे आदर्श उत्तर देना"],"explanationHi":"NCF 2005 कहती है कि ज्ञान को विद्यालय के बाहर के जीवन से जोड़ा जाए, अधिगम रटंत विधियों से दूर जाए और बच्चे ज्ञान के सक्रिय निर्माता हों।"},
  {"id":"cdp-child-development-575","question":"A colleague says, ‘Fractions are far too abstract to start before Class 5.’ Which reply best reflects Jerome Bruner's position?","options":["She is right: abstract ideas must wait until the child reaches the formal operational stage","Fractions can be taught at any age, but only through rote drill of rules and symbols","Any subject can be taught honestly at any stage if matched to the child's mode of representation","Young children should learn mainly through rewards and punishments, not through ideas"],"answer":2,"explanation":"Bruner argued that the basic idea of any subject can be taught honestly to a child of any age, beginning with enactive and iconic forms and moving to symbols, which also underlies the spiral curriculum.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक सहकर्मी कहती है, ‘भिन्न कक्षा 5 से पहले शुरू करने के लिए बहुत अमूर्त हैं।’ जेरोम ब्रूनर के मत को कौन-सा उत्तर सबसे अच्छी तरह दर्शाता है?","optionsHi":["वह सही है: अमूर्त विचारों को तब तक रुकना चाहिए जब तक बच्चा औपचारिक संक्रियात्मक अवस्था में न पहुँच जाए","भिन्न किसी भी आयु में पढ़ाए जा सकते हैं, पर केवल नियमों और प्रतीकों के रटंत अभ्यास से","यदि बच्चे के निरूपण के पक्ष से मेल खाए तो किसी भी विषय को किसी भी अवस्था में ईमानदारी से पढ़ाया जा सकता है","छोटे बच्चों को मुख्यतः पुरस्कार और दंड से सीखना चाहिए, विचारों से नहीं"],"explanationHi":"ब्रूनर का तर्क था कि किसी भी विषय का मूल विचार किसी भी आयु के बच्चे को ईमानदारी से पढ़ाया जा सकता है, क्रियात्मक और प्रतिबिंबात्मक रूपों से शुरू करके प्रतीकों की ओर बढ़ते हुए, जो सर्पिल पाठ्यचर्या का भी आधार है।"},
  {"id":"cdp-child-development-576","question":"Match each child with the intelligence (Gardner) most clearly shown: 1. Tenzin sorts leaves, insects and seeds from the school garden into groups by their features 2. Fatima mentally rotates a folded paper and predicts where the holes will appear 3. Joseph keeps a diary of his moods and knows which tasks drain him 4. Kiran copies a dance step perfectly after seeing it once; a. Spatial b. Naturalist c. Bodily-kinaesthetic d. Intrapersonal","options":["1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d","1-b, 2-a, 3-d, 4-c","1-d, 2-a, 3-b, 4-c"],"answer":2,"explanation":"Classifying living things is naturalist, mental rotation is spatial, knowing one’s own moods is intrapersonal, and skilled body movement is bodily-kinaesthetic.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"प्रत्येक बच्चे का मिलान उस बुद्धि (गार्डनर) से कीजिए जो उसमें सबसे स्पष्ट दिखती है: 1. तेनज़िन विद्यालय की बगिया की पत्तियों, कीड़ों और बीजों को उनकी विशेषताओं के आधार पर समूहों में छाँटता है 2. फ़ातिमा मोड़े हुए कागज़ को मन में घुमाकर अनुमान लगाती है कि छेद कहाँ दिखेंगे 3. जोसेफ़ अपने मनोभावों की डायरी रखता है और जानता है कि कौन-से कार्य उसे थका देते हैं 4. किरण एक नृत्य-मुद्रा को एक बार देखकर उसकी पूरी नकल कर लेती है; a. स्थानिक b. प्रकृतिवादी c. शारीरिक-गतिबोधक d. अंतःवैयक्तिक","optionsHi":["1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d","1-b, 2-a, 3-d, 4-c","1-d, 2-a, 3-b, 4-c"],"explanationHi":"जीवित वस्तुओं का वर्गीकरण प्रकृतिवादी है, मन में घुमाना स्थानिक है, अपने मनोभावों को जानना अंतःवैयक्तिक है, और कुशल शारीरिक गति शारीरिक-गतिबोधक है।"},
  {"id":"cdp-child-development-577","question":"Which of the following is the most frequently raised scholarly criticism of Howard Gardner’s theory of multiple intelligences?","options":["It relies too heavily on IQ test scores to identify each of the separate intelligences","It claims that intelligence is entirely inherited and cannot be changed by schooling","It ignores music and bodily skill, treating only academic abilities as intelligence","Some ‘intelligences’ may be talents, and the theory has limited psychometric evidence"],"answer":3,"explanation":"Critics argue that abilities like music or movement are talents, and that the intelligences are not shown to be independent in test data. Gardner, in fact, rejected reliance on IQ tests and did include music and movement.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"हॉवर्ड गार्डनर के बहुबुद्धि सिद्धांत की सबसे अधिक उठाई जाने वाली विद्वत्तापूर्ण आलोचना निम्नलिखित में से कौन-सी है?","optionsHi":["यह प्रत्येक पृथक बुद्धि की पहचान के लिए IQ परीक्षण के अंकों पर बहुत अधिक निर्भर है","यह दावा करता है कि बुद्धि पूरी तरह वंशानुगत है और विद्यालयी शिक्षा से बदली नहीं जा सकती","यह संगीत और शारीरिक कौशल की उपेक्षा करता है और केवल शैक्षणिक क्षमताओं को ही बुद्धि मानता है","कुछ ‘बुद्धियाँ’ केवल प्रतिभाएँ हो सकती हैं, और सिद्धांत के मनोमितीय प्रमाण सीमित हैं"],"explanationHi":"आलोचकों का तर्क है कि संगीत या गति जैसी क्षमताएँ प्रतिभाएँ हैं, और परीक्षण-आँकड़ों में बुद्धियों का स्वतंत्र होना सिद्ध नहीं हुआ है। गार्डनर ने वास्तव में IQ परीक्षणों पर निर्भरता को अस्वीकार किया और संगीत तथा गति को शामिल किया।"},
  {"id":"cdp-child-development-578","question":"Assertion (A): Howard Gardner rejects the idea that a single general intelligence can adequately describe human abilities. Reason (R): Gardner holds that each person’s profile of intelligences is fixed at birth and cannot be developed.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Gardner proposes several relatively independent intelligences instead of one g, but he stresses that intelligences can be developed through culture and education, so R is false.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"अभिकथन (A): हॉवर्ड गार्डनर इस विचार को अस्वीकार करते हैं कि कोई एक सामान्य बुद्धि मानव क्षमताओं का पर्याप्त वर्णन कर सकती है। कारण (R): गार्डनर मानते हैं कि प्रत्येक व्यक्ति की बुद्धियों की रूपरेखा जन्म से निश्चित होती है और विकसित नहीं की जा सकती।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"गार्डनर एक g के बजाय कई अपेक्षाकृत स्वतंत्र बुद्धियाँ प्रस्तावित करते हैं, परंतु वे बल देते हैं कि बुद्धियाँ संस्कृति और शिक्षा द्वारा विकसित की जा सकती हैं, इसलिए R असत्य है।"},
  {"id":"cdp-child-development-579","question":"When a new type of puzzle appears in a maths olympiad, Nisha quickly works out a way to approach it; she has also practised long division so much that she does it almost without thought, freeing her mind for harder steps. Both abilities belong to which part of Sternberg’s triarchic theory?","options":["The componential subtheory","The experiential subtheory","The contextual subtheory","The two-factor theory"],"answer":1,"explanation":"Sternberg’s experiential subtheory deals with handling novelty and with automatising familiar processes; both are aspects of how experience relates to intelligent behaviour.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"गणित ओलंपियाड में नई तरह की पहेली आने पर निशा शीघ्र ही उसे हल करने का तरीका निकाल लेती है; उसने लंबे भाग का इतना अभ्यास किया है कि वह उसे लगभग बिना सोचे कर लेती है, जिससे उसका मन कठिन चरणों के लिए मुक्त रहता है। दोनों क्षमताएँ स्टर्नबर्ग के त्रितंत्रीय सिद्धांत के किस भाग से संबंधित हैं?","optionsHi":["घटकीय उप-सिद्धांत","अनुभवात्मक उप-सिद्धांत","संदर्भगत उप-सिद्धांत","द्वि-कारक सिद्धांत"],"explanationHi":"स्टर्नबर्ग का अनुभवात्मक उप-सिद्धांत नवीनता से निपटने और परिचित प्रक्रियाओं के स्वचालन से संबंधित है; दोनों इस बात के पहलू हैं कि अनुभव बुद्धिमत्तापूर्ण व्यवहार से कैसे जुड़ता है।"},
  {"id":"cdp-child-development-580","question":"Robert Sternberg’s idea of ‘successful intelligence’ is best described as:","options":["The ability to score consistently high on standard IQ tests and school achievement tests","Balancing analytical, creative and practical abilities to reach one's goals in one's context","Having high emotional intelligence together with a high IQ, as measured by standard tests","Excelling in at least one of Gardner's eight intelligences and using it in a chosen career"],"answer":1,"explanation":"Sternberg defines successful intelligence as balancing analytical, creative and practical abilities to adapt to, shape and select environments in line with personal goals, a broader idea than test success.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"रॉबर्ट स्टर्नबर्ग के ‘सफल बुद्धि’ के विचार का सबसे अच्छा वर्णन है:","optionsHi":["मानक IQ परीक्षणों और विद्यालयी उपलब्धि परीक्षणों में लगातार उच्च अंक लाने की योग्यता","अपने लक्ष्यों को अपने संदर्भ में प्राप्त करने के लिए विश्लेषणात्मक, रचनात्मक और व्यावहारिक क्षमताओं में संतुलन बनाना","उच्च भावनात्मक बुद्धि के साथ उच्च IQ होना, जैसा मानक परीक्षणों से मापा जाता है","गार्डनर की आठ बुद्धियों में से कम से कम एक में उत्कृष्ट होना और उसका उपयोग चुने हुए पेशे में करना"],"explanationHi":"स्टर्नबर्ग सफल बुद्धि को व्यक्तिगत लक्ष्यों के अनुरूप परिवेशों के साथ अनुकूलन करने, उन्हें आकार देने और चुनने के लिए विश्लेषणात्मक, रचनात्मक और व्यावहारिक क्षमताओं में संतुलन के रूप में परिभाषित करते हैं, जो परीक्षण-सफलता से व्यापक विचार है।"},
  {"id":"cdp-child-development-581","question":"Bunty can repeat long strings of digits and learn lists of state capitals by heart easily, but finds it hard to see the rule behind a series such as 2, 6, 12, 20, 30. In Arthur Jensen’s terms, he is strong in:","options":["Level II (conceptual) ability but weak in Level I (associative) ability","Fluid intelligence but weak in crystallised intelligence","Level I (associative) ability but weak in Level II (conceptual) ability","Divergent production but weak in convergent production"],"answer":2,"explanation":"Jensen’s Level I covers rote and associative learning such as digit span; Level II covers reasoning and abstract problem-solving, such as finding the rule n(n + 1) in a series.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"बंटी अंकों की लंबी शृंखलाएँ दोहरा सकता है और राज्यों की राजधानियों की सूचियाँ आसानी से कंठस्थ कर लेता है, परंतु 2, 6, 12, 20, 30 जैसी श्रृंखला के पीछे का नियम देखना उसे कठिन लगता है। आर्थर जेनसन के शब्दों में, वह किसमें सशक्त है?","optionsHi":["स्तर II (संप्रत्ययात्मक) क्षमता में, पर स्तर I (साहचर्यात्मक) क्षमता में कमज़ोर","तरल बुद्धि में, पर क्रिस्टलीकृत बुद्धि में कमज़ोर","स्तर I (साहचर्यात्मक) क्षमता में, पर स्तर II (संप्रत्ययात्मक) क्षमता में कमज़ोर","अपसारी उत्पादन में, पर अभिसारी उत्पादन में कमज़ोर"],"explanationHi":"जेनसन का स्तर I रटंत और साहचर्यात्मक अधिगम, जैसे अंक-स्मृति-विस्तार, को समाहित करता है; स्तर II तर्क और अमूर्त समस्या-समाधान को, जैसे श्रृंखला में नियम n(n + 1) खोजना।"},
  {"id":"cdp-child-development-582","question":"J. P. Guilford classified intellectual abilities along three dimensions. These are:","options":["Analytical, creative and practical abilities","General, specific and group factors","Abstract, mechanical and social abilities","Operations, contents and products"],"answer":3,"explanation":"Guilford’s structure-of-intellect model crosses operations (the kind of thinking), contents (the kind of information) and products (the form the result takes). The other options are Sternberg, Spearman/group-factor and Thorndike ideas.","difficulty":"hard","source":"CTET · DSSSB TGT","questionHi":"जे. पी. गिलफ़ोर्ड ने बौद्धिक क्षमताओं को तीन आयामों में वर्गीकृत किया। ये हैं:","optionsHi":["विश्लेषणात्मक, रचनात्मक और व्यावहारिक क्षमताएँ","सामान्य, विशिष्ट और समूह कारक","अमूर्त, यांत्रिक और सामाजिक क्षमताएँ","संक्रियाएँ, विषय-वस्तुएँ और उत्पाद"],"explanationHi":"गिलफ़ोर्ड का बुद्धि-संरचना मॉडल संक्रियाओं (चिंतन का प्रकार), विषय-वस्तुओं (सूचना का प्रकार) और उत्पादों (परिणाम का रूप) को आपस में गुणा करता है। अन्य विकल्प स्टर्नबर्ग, स्पीयरमैन/समूह-कारक और थॉर्नडाइक के विचार हैं।"},
  {"id":"cdp-child-development-583","question":"Guilford’s original structure-of-intellect model had 5 operations, 4 contents and 6 products. If the ‘figural’ content is later split into visual and auditory contents, with operations and products unchanged, how many distinct abilities does the model then describe?","options":["120","150","180","144"],"answer":1,"explanation":"Original: 5 × 4 × 6 = 120. Splitting figural gives 5 contents, so 5 × 5 × 6 = 150. The figure 180 arose only when memory was also split, giving 6 operations.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"गिलफ़ोर्ड के मूल बुद्धि-संरचना मॉडल में 5 संक्रियाएँ, 4 विषय-वस्तुएँ और 6 उत्पाद थे। यदि ‘आकृतिक’ विषय-वस्तु को बाद में दृश्य और श्रव्य विषय-वस्तुओं में बाँट दिया जाए, और संक्रियाएँ तथा उत्पाद अपरिवर्तित रहें, तो मॉडल तब कितनी विशिष्ट क्षमताओं का वर्णन करता है?","optionsHi":["120","150","180","144"],"explanationHi":"मूल: 5 × 4 × 6 = 120। आकृतिक को बाँटने पर 5 विषय-वस्तुएँ हो जाती हैं, इसलिए 5 × 5 × 6 = 150। आँकड़ा 180 तब आया जब स्मृति को भी बाँटा गया, जिससे 6 संक्रियाएँ हो गईं।"},
  {"id":"cdp-child-development-584","question":"Philip Vernon’s hierarchical model places ‘g’ at the top, with two major group factors below it. These are:","options":["Fluid (gf) and crystallised (gc) intelligence","Verbal–educational (v:ed) and practical–mechanical–spatial (k:m)","Level I (associative) and Level II (conceptual) learning abilities","Convergent and divergent thinking (production) abilities"],"answer":1,"explanation":"Vernon’s hierarchy puts g first, then the major group factors v:ed and k:m, which split into minor group factors and finally specific factors.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"फ़िलिप वर्नन का पदानुक्रमित मॉडल ‘g’ को शीर्ष पर रखता है, जिसके नीचे दो प्रमुख समूह कारक हैं। ये हैं:","optionsHi":["तरल (gf) और क्रिस्टलीकृत (gc) बुद्धि","शाब्दिक–शैक्षिक (v:ed) और व्यावहारिक–यांत्रिक–स्थानिक (k:m)","स्तर I (साहचर्यात्मक) और स्तर II (संप्रत्ययात्मक) अधिगम क्षमताएँ","अभिसारी और अपसारी चिंतन (उत्पादन) क्षमताएँ"],"explanationHi":"वर्नन का पदानुक्रम पहले g को रखता है, फिर प्रमुख समूह कारक v:ed और k:m, जो लघु समूह कारकों में और अंत में विशिष्ट कारकों में बँटते हैं।"},
  {"id":"cdp-child-development-585","question":"E. L. Thorndike rejected one unitary intelligence and distinguished three broad kinds of intelligence. They are:","options":["Abstract, mechanical and social intelligence","Linguistic, logical and spatial intelligence","Analytical, creative and practical intelligence","Verbal, numerical and perceptual intelligence"],"answer":0,"explanation":"Thorndike’s multifactor view separated abstract (ideas and symbols), mechanical (objects and tools) and social (people) intelligence; the analytical–creative–practical triad belongs to Sternberg.","difficulty":"hard","source":"CTET · State TET","questionHi":"ई. एल. थॉर्नडाइक ने एकल इकाई बुद्धि को अस्वीकार किया और तीन व्यापक प्रकार की बुद्धि में भेद किया। वे हैं:","optionsHi":["अमूर्त, यांत्रिक और सामाजिक बुद्धि","भाषिक, तार्किक और स्थानिक बुद्धि","विश्लेषणात्मक, रचनात्मक और व्यावहारिक बुद्धि","शाब्दिक, संख्यात्मक और प्रत्यक्षीकरणात्मक बुद्धि"],"explanationHi":"थॉर्नडाइक का बहु-कारक मत अमूर्त (विचार और प्रतीक), यांत्रिक (वस्तुएँ और औज़ार) तथा सामाजिक (लोग) बुद्धि में भेद करता है; विश्लेषणात्मक–रचनात्मक–व्यावहारिक त्रयी स्टर्नबर्ग की है।"},
  {"id":"cdp-child-development-586","question":"Which trait is most consistently associated with creative students in research on creativity?","options":["A strong need for the teacher's approval before trying anything new","A preference for questions that have one clear and correct answer","Tolerance for ambiguity and willingness to take intellectual risks","Avoidance of tasks that come without clear, step-by-step instructions"],"answer":2,"explanation":"Creative people tend to tolerate uncertainty, stay with open problems and risk being wrong; needing approval and preferring single answers point to convergent, conforming habits.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"सृजनात्मकता पर शोध में रचनात्मक विद्यार्थियों से कौन-सी विशेषता सबसे संगत रूप से जुड़ी पाई जाती है?","optionsHi":["कुछ भी नया करने से पहले शिक्षक की स्वीकृति की प्रबल आवश्यकता","उन प्रश्नों को वरीयता जिनका एक स्पष्ट और सही उत्तर हो","अस्पष्टता के प्रति सहनशीलता और बौद्धिक जोखिम लेने की इच्छा","उन कार्यों से बचना जो स्पष्ट, चरण-दर-चरण निर्देशों के बिना आते हैं"],"explanationHi":"रचनात्मक लोग अनिश्चितता सहन करते हैं, खुली समस्याओं के साथ टिके रहते हैं और गलत होने का जोखिम उठाते हैं; स्वीकृति की आवश्यकता और एकल उत्तर की वरीयता अभिसारी, अनुरूपता वाली आदतों की ओर संकेत करती है।"},
  {"id":"cdp-child-development-587","question":"During a brainstorming session on ‘How can our school save water?’, the teacher says ‘That won’t work’ and ‘That’s silly’ to several suggestions as they come. Which principle of brainstorming is she violating most directly?","options":["Aim for quantity of ideas","Defer judgement until all ideas are collected","Build on others’ ideas","Welcome unusual ideas only from the brightest students"],"answer":1,"explanation":"Brainstorming (Osborn) separates idea generation from evaluation; criticising ideas immediately makes students hold back and reduces both the number and the originality of ideas.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"‘हमारा विद्यालय पानी कैसे बचा सकता है?’ पर विचार-मंथन (ब्रेनस्टॉर्मिंग) सत्र के दौरान शिक्षिका कई सुझावों के आते ही कहती है ‘यह काम नहीं करेगा’ और ‘यह मूर्खतापूर्ण है’। वह विचार-मंथन के किस सिद्धांत का सबसे सीधे उल्लंघन कर रही है?","optionsHi":["विचारों की मात्रा का लक्ष्य रखना","सभी विचार एकत्र होने तक निर्णय को स्थगित रखना","दूसरों के विचारों पर आगे बढ़ना","असामान्य विचारों का स्वागत केवल सबसे होशियार विद्यार्थियों से करना"],"explanationHi":"विचार-मंथन (ऑसबर्न) विचारों के सृजन को मूल्यांकन से अलग करता है; विचारों की तुरंत आलोचना करने से विद्यार्थी पीछे हट जाते हैं और विचारों की संख्या तथा मौलिकता दोनों घट जाती हैं।"},
  {"id":"cdp-child-development-588","question":"In a Class 6 creativity task, 35 of 40 children say a newspaper can be used ‘to wrap things’. Only Devika says, ‘to make a sound-proof lining for the music room door’. On Torrance-type scoring, Devika’s answer earns credit mainly for:","options":["Fluency","Flexibility","Elaboration","Originality"],"answer":3,"explanation":"Originality is scored by how statistically rare a response is in the group; a single unusual answer counts as original, while fluency counts the number of ideas.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 6 के एक सृजनात्मकता कार्य में 40 में से 35 बच्चे कहते हैं कि अख़बार का उपयोग ‘चीज़ें लपेटने’ में हो सकता है। केवल देविका कहती है, ‘संगीत-कक्ष के दरवाज़े पर ध्वनिरोधी अस्तर बनाने के लिए’। टॉरेंस-प्रकार की अंकन विधि में देविका के उत्तर को मुख्यतः किसके लिए अंक मिलते हैं?","optionsHi":["प्रवाह","लचीलापन","विस्तारण","मौलिकता"],"explanationHi":"मौलिकता का अंकन इससे होता है कि समूह में कोई उत्तर सांख्यिकीय रूप से कितना दुर्लभ है; एक अकेला असामान्य उत्तर मौलिक गिना जाता है, जबकि प्रवाह विचारों की संख्या गिनता है।"},
  {"id":"cdp-child-development-589","question":"Asked to design a bird feeder, Ishaan gives only one idea, but describes it in great detail: the material, the size of the holes, the slope of the roof to drain rain and how to hang it away from cats. On divergent-thinking scoring, he would score highest on:","options":["Elaboration","Fluency","Flexibility","Originality"],"answer":0,"explanation":"Elaboration is the amount of detail used to develop an idea. With a single idea, his fluency and flexibility are low.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"पक्षियों का दाना-पात्र (बर्ड फ़ीडर) बनाने को कहे जाने पर ईशान केवल एक विचार देता है, पर उसका बहुत विस्तार से वर्णन करता है: सामग्री, छेदों का आकार, बारिश का पानी निकलने के लिए छत की ढलान और उसे बिल्लियों से दूर कैसे लटकाया जाए। अपसारी-चिंतन अंकन में उसे सबसे अधिक अंक किसमें मिलेंगे?","optionsHi":["विस्तारण","प्रवाह","लचीलापन","मौलिकता"],"explanationHi":"विस्तारण किसी विचार को विकसित करने में प्रयुक्त ब्योरे की मात्रा है। एक ही विचार होने से उसका प्रवाह और लचीलापन कम हैं।"},
  {"id":"cdp-child-development-590","question":"Assertion (A): A child who scores very high on an IQ test will always also score very high on creativity tests. Reason (R): Most traditional IQ tests mainly measure convergent thinking.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"IQ and creativity are only moderately related, so a high IQ does not guarantee high creativity. R is true: IQ items usually have one right answer, which is exactly why IQ tests miss much of divergent thinking.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): IQ परीक्षण में बहुत उच्च अंक पाने वाला बच्चा सृजनात्मकता परीक्षणों में भी सदैव बहुत उच्च अंक पाएगा। कारण (R): अधिकांश परंपरागत IQ परीक्षण मुख्यतः अभिसारी चिंतन को मापते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"IQ और सृजनात्मकता में केवल मध्यम संबंध है, इसलिए उच्च IQ उच्च सृजनात्मकता की गारंटी नहीं देता। R सत्य है: IQ के प्रश्नों का प्रायः एक ही सही उत्तर होता है, और इसी कारण IQ परीक्षण अपसारी चिंतन के बड़े भाग को छोड़ देते हैं।"},
  {"id":"cdp-child-development-591","question":"Which question would best promote divergent thinking in a Class 4 EVS lesson on rivers?","options":["Name five rivers that flow through India, and the states they pass through.","Why does the Ganga carry much more water during the monsoon than in summer?","Which river is the longest in India, and where does it begin and end?","If our village river dried up for a year, in how many ways might life here change?"],"answer":3,"explanation":"An open hypothetical question invites many varied answers; the other questions, even the ‘why’ question, lead towards one expected answer.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"नदियों पर कक्षा 4 के EVS पाठ में अपसारी चिंतन को कौन-सा प्रश्न सबसे अच्छी तरह बढ़ावा देगा?","optionsHi":["भारत से बहने वाली पाँच नदियों के नाम और उन राज्यों के नाम बताइए जिनसे वे गुज़रती हैं।","गंगा मानसून में गर्मियों की तुलना में बहुत अधिक पानी क्यों ले जाती है?","भारत की सबसे लंबी नदी कौन-सी है, और वह कहाँ से शुरू और कहाँ समाप्त होती है?","यदि हमारे गाँव की नदी एक वर्ष के लिए सूख जाए, तो यहाँ जीवन कितने तरीकों से बदल सकता है?"],"explanationHi":"एक खुला काल्पनिक प्रश्न अनेक और भिन्न उत्तरों को आमंत्रित करता है; अन्य प्रश्न, यहाँ तक कि ‘क्यों’ वाला प्रश्न भी, किसी एक अपेक्षित उत्तर की ओर ले जाते हैं।"},
  {"id":"cdp-child-development-592","question":"Parents want their gifted ten-year-old to skip from Class 5 to Class 7. Which concern about such acceleration should the school weigh most carefully along with academic readiness?","options":["Whether his social and emotional maturity will let him fit in with older classmates","Whether skipping a class could actually lower his IQ score over the next few years","Whether acceleration of a child across classes is illegal under the RTE Act, 2009","Whether gifted children ever benefit academically from any form of acceleration"],"answer":0,"explanation":"Research generally finds acceleration helps academically for well-chosen children; the main caution concerns individual social-emotional readiness, which should be judged case by case.","difficulty":"hard","source":"KVS PGT · DSSSB TGT","questionHi":"माता-पिता चाहते हैं कि उनका प्रतिभाशाली दस वर्षीय बच्चा कक्षा 5 से सीधे कक्षा 7 में चला जाए। शैक्षणिक तत्परता के साथ-साथ विद्यालय को इस त्वरण के बारे में किस चिंता को सबसे सावधानी से तौलना चाहिए?","optionsHi":["क्या उसकी सामाजिक और भावनात्मक परिपक्वता उसे बड़े सहपाठियों के साथ ढलने देगी","क्या कक्षा छोड़ने से अगले कुछ वर्षों में उसके IQ अंक वास्तव में घट सकते हैं","क्या बच्चे को कक्षाएँ लाँघाना RTE अधिनियम, 2009 के अंतर्गत अवैध है","क्या प्रतिभाशाली बच्चों को त्वरण के किसी भी रूप से कभी शैक्षणिक लाभ होता है"],"explanationHi":"शोध सामान्यतः पाता है कि सुविचारित चुने गए बच्चों के लिए त्वरण शैक्षणिक रूप से सहायक होता है; मुख्य सावधानी व्यक्तिगत सामाजिक-भावनात्मक तत्परता की है, जिसे प्रत्येक मामले में अलग से परखा जाना चाहिए।"},
  {"id":"cdp-child-development-593","question":"Megha, a very able Class 8 girl in Ranchi, deliberately gives wrong answers in class and stops taking part in the science quiz because her friends tease her as a ‘padhaku’. The most appropriate teacher response is to:","options":["Assume she has lost interest in science and remove her from the advanced group","Scold her in front of the class for not trying, so that she takes her studies seriously","Accept it, since it is natural for girls to hide their abilities during adolescence","Talk with her privately, build a culture that values effort, and challenge her discreetly"],"answer":3,"explanation":"Gifted students, especially adolescent girls, may underachieve to fit in with peers. Supportive private guidance, a classroom culture that respects achievement and suitable challenge address the cause instead of punishing or accepting it.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"राँची की कक्षा 8 की अत्यंत सक्षम छात्रा मेघा कक्षा में जान-बूझकर गलत उत्तर देती है और विज्ञान प्रश्नोत्तरी में भाग लेना बंद कर देती है, क्योंकि उसकी सहेलियाँ उसे ‘पढ़ाकू’ कहकर चिढ़ाती हैं। शिक्षक की सबसे उपयुक्त प्रतिक्रिया है:","optionsHi":["यह मान लेना कि उसकी विज्ञान में रुचि समाप्त हो गई है और उसे उन्नत समूह से हटा देना","कक्षा के सामने उसे प्रयास न करने के लिए डाँटना, ताकि वह पढ़ाई को गंभीरता से ले","इसे स्वीकार कर लेना, क्योंकि किशोरावस्था में लड़कियों का अपनी क्षमताएँ छिपाना स्वाभाविक है","उससे निजी तौर पर बात करना, प्रयास को महत्त्व देने वाली संस्कृति बनाना और उसे चुपचाप चुनौती देना"],"explanationHi":"प्रतिभाशाली विद्यार्थी, विशेषकर किशोर लड़कियाँ, साथियों में घुलने-मिलने के लिए कम प्रदर्शन कर सकती हैं। सहायक निजी मार्गदर्शन, उपलब्धि का सम्मान करने वाली कक्षा-संस्कृति और उपयुक्त चुनौती कारण का समाधान करती है, उसे दंडित या स्वीकार करने के बजाय।"},
  {"id":"cdp-child-development-594","question":"Which behaviour of a gifted child is most often misread by teachers as indiscipline?","options":["Finishing work slowly and very carefully, checking each step twice before handing it in","Asking probing ‘why’ questions and challenging rules that make no sense to them","Preferring to work in a group with friends rather than alone on most tasks","Copying all the board work neatly and colourfully into notebooks"],"answer":1,"explanation":"Gifted children often question authority, ask searching questions and get restless with repetition; teachers may see this as defiance, which can lead to the child’s ability being missed.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"प्रतिभाशाली बच्चे का कौन-सा व्यवहार शिक्षकों द्वारा प्रायः अनुशासनहीनता समझ लिया जाता है?","optionsHi":["काम धीरे और बहुत सावधानी से पूरा करना, जमा करने से पहले प्रत्येक चरण को दो बार जाँचना","गहन ‘क्यों’ वाले प्रश्न पूछना और उन नियमों को चुनौती देना जो उन्हें अर्थहीन लगते हैं","अधिकांश कार्यों में अकेले के बजाय मित्रों के साथ समूह में काम करना पसंद करना","श्यामपट्ट का सारा कार्य कॉपियों में सुंदर और रंगीन ढंग से उतारना"],"explanationHi":"प्रतिभाशाली बच्चे प्रायः सत्ता पर प्रश्न उठाते हैं, गहन प्रश्न पूछते हैं और दोहराव से बेचैन हो जाते हैं; शिक्षक इसे अवज्ञा समझ सकते हैं, जिससे बच्चे की क्षमता अनदेखी रह सकती है।"},
  {"id":"cdp-child-development-595","question":"Which of the following practices for identifying gifted children are sound? I. Using several sources such as observations, portfolios, teacher and peer nominations and tests. II. Using a single IQ cut-off as the only criterion. III. Looking for talent among children with disabilities and from disadvantaged groups. IV. Allowing children to show ability in their home language.","options":["I, III and IV only","I and II only","II and III only","I, II, III and IV"],"answer":0,"explanation":"Sound identification uses multiple measures and looks across groups and languages; a single IQ cut-off misses creative, practically talented and under-served children.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"प्रतिभाशाली बच्चों की पहचान की निम्नलिखित प्रथाओं में से कौन-सी उचित हैं? I. अवलोकन, पोर्टफ़ोलियो, शिक्षक और सहपाठी नामांकन तथा परीक्षणों जैसे अनेक स्रोतों का उपयोग। II. एकमात्र मानदंड के रूप में एक ही IQ कट-ऑफ़ का उपयोग। III. विकलांग बच्चों और वंचित समूहों के बच्चों में प्रतिभा की खोज करना। IV. बच्चों को अपनी घरेलू भाषा में क्षमता दिखाने की अनुमति देना।","optionsHi":["केवल I, III और IV","केवल I और II","केवल II और III","I, II, III और IV"],"explanationHi":"उचित पहचान अनेक मापों का उपयोग करती है और समूहों तथा भाषाओं में देखती है; एक ही IQ कट-ऑफ़ रचनात्मक, व्यावहारिक रूप से प्रतिभाशाली और उपेक्षित बच्चों को छोड़ देता है।"},
  {"id":"cdp-child-development-596","question":"Speakers of some languages, such as Guugu Yimithirr in Australia, describe locations using compass directions (‘the cup is north of the plate’) instead of ‘left’ and ‘right’, and they keep track of directions remarkably well. Such findings are usually cited as support for:","options":["The strong version of the Sapir–Whorf hypothesis, that language completely determines thought","Chomsky’s claim that all languages are identical in vocabulary","The weak version of the Sapir–Whorf hypothesis, that language can influence habits of thought","Piaget’s view that language has no influence at any stage of thinking"],"answer":2,"explanation":"Such studies show language can shape habitual attention and memory (linguistic relativity) without showing that speakers cannot think in other ways, so they support the weak, not the strong, version.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"ऑस्ट्रेलिया की गूगू यिमिथिर जैसी कुछ भाषाओं के बोलने वाले स्थानों का वर्णन ‘बाएँ’ और ‘दाएँ’ के बजाय दिशा-सूचक कंपास दिशाओं से करते हैं (‘प्याला प्लेट के उत्तर में है’), और वे दिशाओं का उल्लेखनीय ढंग से ध्यान रखते हैं। ऐसे निष्कर्षों को प्रायः किसके समर्थन में उद्धृत किया जाता है?","optionsHi":["सेपिर–वॉर्फ़ परिकल्पना के सशक्त रूप के, कि भाषा चिंतन को पूरी तरह निर्धारित करती है","चॉम्स्की के इस दावे के कि सभी भाषाएँ शब्दावली में समान हैं","सेपिर–वॉर्फ़ परिकल्पना के दुर्बल रूप के, कि भाषा चिंतन की आदतों को प्रभावित कर सकती है","पियाजे के इस मत के कि चिंतन की किसी भी अवस्था में भाषा का कोई प्रभाव नहीं होता"],"explanationHi":"ऐसे अध्ययन दिखाते हैं कि भाषा अभ्यस्त ध्यान और स्मृति को आकार दे सकती है (भाषिक सापेक्षता), बिना यह दिखाए कि बोलने वाले अन्य तरीकों से सोच नहीं सकते, इसलिए वे सशक्त नहीं, दुर्बल रूप का समर्थन करते हैं।"},
  {"id":"cdp-child-development-597","question":"A girl who was kept isolated with almost no exposure to language until about 13 years of age learned many words after rescue but never fully mastered grammar. Such cases are commonly cited in support of:","options":["The critical (or sensitive) period hypothesis for language acquisition","Skinner's view that language is learned only through reinforcement","The strong Sapir–Whorf hypothesis that language determines thought","Piaget's claim that early speech is egocentric and serves no social use"],"answer":0,"explanation":"Lenneberg’s critical period hypothesis holds that language, especially grammar, is acquired most easily during a biologically sensitive early period; cases like ‘Genie’ are often cited as evidence, though they involve other deprivations too.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"लगभग 13 वर्ष की आयु तक भाषा के लगभग किसी भी संपर्क के बिना अलग-थलग रखी गई एक बालिका ने बचाए जाने के बाद अनेक शब्द सीखे परंतु व्याकरण में कभी पूर्ण दक्षता नहीं पाई। ऐसे मामलों को प्रायः किसके समर्थन में उद्धृत किया जाता है?","optionsHi":["भाषा अर्जन की क्रांतिक (या संवेदनशील) अवधि परिकल्पना के","स्किनर के इस मत के कि भाषा केवल पुनर्बलन से सीखी जाती है","सशक्त सेपिर–वॉर्फ़ परिकल्पना के कि भाषा चिंतन को निर्धारित करती है","पियाजे के इस दावे के कि आरंभिक वाणी अहंकेंद्रित होती है और उसका कोई सामाजिक उपयोग नहीं होता"],"explanationHi":"लेनेबर्ग की क्रांतिक अवधि परिकल्पना मानती है कि भाषा, विशेषकर व्याकरण, एक जैविक रूप से संवेदनशील आरंभिक अवधि में सबसे आसानी से अर्जित होती है; ‘जीनी’ जैसे मामले प्रायः प्रमाण के रूप में उद्धृत होते हैं, यद्यपि उनमें अन्य वंचनाएँ भी शामिल थीं।"},
  {"id":"cdp-child-development-598","question":"Match the theorist with the view of language development: 1. B. F. Skinner 2. Noam Chomsky 3. Lev Vygotsky 4. Jean Piaget; a. Language develops through social interaction and becomes a tool of thought b. Language reflects the child’s level of cognitive development c. Language is verbal behaviour shaped by reinforcement d. Children have an inborn device for acquiring grammar","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a","1-a, 2-d, 3-c, 4-b"],"answer":0,"explanation":"Skinner: reinforcement of verbal behaviour; Chomsky: innate LAD; Vygotsky: social origin of speech and its role in thought; Piaget: language follows and reflects thought.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"सिद्धांतकार का मिलान भाषा-विकास के मत से कीजिए: 1. बी. एफ़. स्किनर 2. नोम चॉम्स्की 3. लेव वाइगोत्स्की 4. जीन पियाजे; a. भाषा सामाजिक अंतःक्रिया से विकसित होती है और चिंतन का उपकरण बन जाती है b. भाषा बच्चे के संज्ञानात्मक विकास के स्तर को प्रतिबिंबित करती है c. भाषा पुनर्बलन द्वारा आकार पाया हुआ शाब्दिक व्यवहार है d. बच्चों में व्याकरण अर्जित करने का एक जन्मजात उपकरण होता है","optionsHi":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a","1-a, 2-d, 3-c, 4-b"],"explanationHi":"स्किनर: शाब्दिक व्यवहार का पुनर्बलन; चॉम्स्की: जन्मजात LAD; वाइगोत्स्की: वाणी की सामाजिक उत्पत्ति और चिंतन में उसकी भूमिका; पियाजे: भाषा चिंतन के पीछे चलती है और उसे प्रतिबिंबित करती है।"},
  {"id":"cdp-child-development-599","question":"During a difficult subtraction exercise with borrowing, a Class 2 child in Shimla whispers to himself, ‘First the ones… can’t take 7 from 3… so borrow from the tens.’ The class rule is ‘work silently’. In the light of Vygotsky’s theory, the teacher should:","options":["Stop him, because talking to oneself shows that he is not yet ready for this topic","Allow it, because such private speech helps children regulate their thinking on hard tasks","Move him to an easier worksheet, so that he no longer needs to talk himself through it","Ask him to say it louder, so that the whole class can hear and benefit from his steps"],"answer":1,"explanation":"For Vygotsky, private speech is a self-regulating tool that increases with task difficulty and gradually becomes inner speech; suppressing it removes support the child is using to think.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"उधार लेने वाले एक कठिन घटाव के अभ्यास के दौरान शिमला का कक्षा 2 का एक बच्चा स्वयं से फुसफुसाता है, ‘पहले इकाई... 3 में से 7 नहीं घटा सकते... इसलिए दहाई से उधार लो।’ कक्षा का नियम है ‘चुपचाप काम करो’। वाइगोत्स्की के सिद्धांत के प्रकाश में शिक्षक को क्या करना चाहिए?","optionsHi":["उसे रोकना, क्योंकि स्वयं से बात करना दर्शाता है कि वह इस विषय के लिए अभी तैयार नहीं है","अनुमति देना, क्योंकि ऐसी निजी वाणी बच्चों को कठिन कार्यों पर अपनी सोच को नियंत्रित करने में सहायता करती है","उसे आसान कार्य-पत्रक पर ले जाना, ताकि उसे स्वयं को समझाने की आवश्यकता न रहे","उसे ज़ोर से बोलने को कहना, ताकि पूरी कक्षा उसके चरण सुन सके और लाभ उठा सके"],"explanationHi":"वाइगोत्स्की के लिए निजी वाणी एक स्व-नियामक उपकरण है जो कार्य की कठिनाई के साथ बढ़ता है और धीरे-धीरे आंतरिक वाणी बन जाता है; उसे दबाना उस सहारे को हटाना है जिसका उपयोग बच्चा सोचने के लिए कर रहा है।"},
  {"id":"cdp-child-development-600","question":"Which classroom practice best counters gender stereotyping in a primary school?","options":["Letting girls clean the classroom and boys carry the furniture, as each group prefers","Using only male examples in maths word problems, to keep boys motivated in the subject","Rotating all duties, from leading assembly to sweeping, among children of every gender","Seating boys and girls in separate rows, so that they do not distract one another"],"answer":2,"explanation":"Rotating every responsibility across genders breaks the hidden message that certain tasks belong to one gender; the other practices reinforce gendered roles.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"प्राथमिक विद्यालय में लैंगिक रूढ़िबद्ध धारणाओं का सबसे अच्छा प्रतिकार कौन-सी कक्षा-प्रथा करती है?","optionsHi":["लड़कियों को कक्षा की सफ़ाई और लड़कों को फ़र्नीचर उठाने देना, जैसा प्रत्येक समूह पसंद करे","गणित के शब्द-प्रश्नों में केवल पुरुष उदाहरणों का उपयोग करना, ताकि लड़के विषय में प्रेरित रहें","प्रार्थना-सभा के संचालन से लेकर झाड़ू लगाने तक सभी कर्तव्यों को प्रत्येक लिंग के बच्चों के बीच बारी-बारी से देना","लड़कों और लड़कियों को अलग-अलग पंक्तियों में बैठाना, ताकि वे एक-दूसरे का ध्यान न भटकाएँ"],"explanationHi":"प्रत्येक ज़िम्मेदारी को लिंगों में बारी-बारी से देना इस छिपे संदेश को तोड़ता है कि कुछ कार्य किसी एक लिंग के हैं; अन्य प्रथाएँ लैंगिक भूमिकाओं को सुदृढ़ करती हैं।"},
  {"id":"cdp-child-development-601","question":"To teach the idea of balance, a Class 3 teacher first has children sit on a seesaw and shift their positions, then shows a picture of a beam balance with weights, and finally writes 2 × 6 = 3 × 4 on the board to show why the two sides balance. In terms of Bruner’s modes, this sequence moves from:","options":["Iconic → enactive → symbolic","Symbolic → iconic → enactive","Enactive → iconic → symbolic","Enactive → symbolic → iconic"],"answer":2,"explanation":"Acting on the seesaw is enactive, the picture is iconic and the written statement is symbolic. Bruner advised this order for introducing new ideas to young learners.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"संतुलन की अवधारणा सिखाने के लिए कक्षा 3 की शिक्षिका पहले बच्चों को सी-सॉ पर बैठाकर अपनी स्थिति बदलवाती है, फिर भारों सहित एक तराज़ू की तस्वीर दिखाती है, और अंत में श्यामपट्ट पर 2 × 6 = 3 × 4 लिखती है यह दिखाने के लिए कि दोनों पक्ष क्यों संतुलित हैं। ब्रूनर के पक्षों के संदर्भ में यह क्रम किससे किस ओर जाता है?","optionsHi":["प्रतिबिंबात्मक → क्रियात्मक → सांकेतिक","सांकेतिक → प्रतिबिंबात्मक → क्रियात्मक","क्रियात्मक → प्रतिबिंबात्मक → सांकेतिक","क्रियात्मक → सांकेतिक → प्रतिबिंबात्मक"],"explanationHi":"सी-सॉ पर क्रिया करना क्रियात्मक है, तस्वीर प्रतिबिंबात्मक है और लिखा हुआ कथन सांकेतिक है। ब्रूनर ने छोटे अधिगमकर्ताओं को नए विचार सिखाने के लिए यही क्रम सुझाया।"},
  {"id":"cdp-child-development-602","question":"How many of these statements about Bruner’s modes of representation are correct? I. Each mode is tied to a fixed age range, as in Piaget’s stages. II. The symbolic mode completely replaces the earlier modes once it develops. III. A single concept can be represented in all three modes. IV. Language plays a central role in the symbolic mode.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"III and IV are correct. I and II are wrong: Bruner’s modes are not tied to fixed ages and they coexist throughout life, so an adult may still learn enactively and the symbolic mode does not replace the others.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"ब्रूनर के निरूपण के पक्षों के बारे में इनमें से कितने कथन सही हैं? I. प्रत्येक पक्ष किसी निश्चित आयु-सीमा से बँधा है, जैसे पियाजे की अवस्थाएँ। II. सांकेतिक पक्ष विकसित होने पर पहले के पक्षों को पूरी तरह प्रतिस्थापित कर देता है। III. एक ही संप्रत्यय को तीनों पक्षों में निरूपित किया जा सकता है। IV. सांकेतिक पक्ष में भाषा की केंद्रीय भूमिका होती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"III और IV सही हैं। I और II गलत हैं: ब्रूनर के पक्ष निश्चित आयु से बँधे नहीं हैं और जीवन भर साथ-साथ बने रहते हैं, इसलिए वयस्क भी क्रियात्मक ढंग से सीख सकता है और सांकेतिक पक्ष दूसरों को प्रतिस्थापित नहीं करता।"},
  {"id":"cdp-child-development-603","question":"Match each example with Bruner’s mode of representation. P. A girl ties her shoelaces quickly but cannot explain the steps in words. Q. A boy recalls the route to school as a mental picture of the lanes. R. A student writes H₂O for water. 1. Iconic 2. Symbolic 3. Enactive","options":["P-1, Q-3, R-2","P-3, Q-2, R-1","P-2, Q-1, R-3","P-3, Q-1, R-2"],"answer":3,"explanation":"Knowledge stored as action is enactive, knowledge as images is iconic, and knowledge as conventional signs such as formulae is symbolic.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"प्रत्येक उदाहरण का मिलान ब्रूनर के निरूपण के पक्ष से कीजिए। P. एक बच्ची तेज़ी से अपने जूतों के फीते बाँध लेती है पर चरणों को शब्दों में नहीं समझा सकती। Q. एक लड़का विद्यालय का रास्ता गलियों के मानसिक चित्र के रूप में याद करता है। R. एक विद्यार्थी पानी के लिए H₂O लिखता है। 1. प्रतिबिंबात्मक 2. सांकेतिक 3. क्रियात्मक","optionsHi":["P-1, Q-3, R-2","P-3, Q-2, R-1","P-2, Q-1, R-3","P-3, Q-1, R-2"],"explanationHi":"क्रिया के रूप में संचित ज्ञान क्रियात्मक है, चित्रों के रूप में ज्ञान प्रतिबिंबात्मक है, और सूत्रों जैसे परंपरागत चिह्नों के रूप में ज्ञान सांकेतिक है।"},
  {"id":"cdp-child-development-604","question":"A school claims to follow Bruner’s spiral curriculum because Classes 3, 4 and 5 each study the same chapter on plants with identical content and exercises. Why is this NOT a spiral curriculum?","options":["A spiral curriculum must cover each topic only once, in the class best suited to it","Each return to a topic in a spiral curriculum must go deeper, building on earlier learning","A spiral curriculum is meant only for the higher classes, where abstract thought is possible","Bruner said that plants should be taught only through the symbolic mode, not with real specimens"],"answer":1,"explanation":"Mere repetition is not a spiral. Each return to the idea should deepen it and connect with what was learnt before, for example moving from naming parts to how leaves make food.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"एक विद्यालय दावा करता है कि वह ब्रूनर की सर्पिल पाठ्यचर्या का पालन करता है क्योंकि कक्षा 3, 4 और 5 प्रत्येक में पौधों पर वही अध्याय समान सामग्री और अभ्यासों के साथ पढ़ाया जाता है। यह सर्पिल पाठ्यचर्या क्यों नहीं है?","optionsHi":["सर्पिल पाठ्यचर्या में प्रत्येक विषय केवल एक बार, उसके लिए सबसे उपयुक्त कक्षा में, पढ़ाना चाहिए","सर्पिल पाठ्यचर्या में किसी विषय पर प्रत्येक वापसी अधिक गहरी होनी चाहिए, जो पहले के अधिगम पर आधारित हो","सर्पिल पाठ्यचर्या केवल उच्च कक्षाओं के लिए है, जहाँ अमूर्त चिंतन संभव है","ब्रूनर ने कहा कि पौधों को केवल सांकेतिक पक्ष से पढ़ाना चाहिए, असली नमूनों से नहीं"],"explanationHi":"केवल दोहराव सर्पिल नहीं है। विचार पर प्रत्येक वापसी उसे गहरा करे और पहले सीखे हुए से जुड़े, जैसे अंगों के नाम बताने से पत्तियाँ भोजन कैसे बनाती हैं तक जाना।"},
  {"id":"cdp-child-development-605","question":"A Class 6 teacher asks students to cut out the three corners of a paper triangle and place them side by side on a straight line, trying several triangles, and then asks, ‘What do you notice?’ Which feature makes this Bruner’s discovery learning?","options":["The students find the general rule themselves from examples they handle","The teacher states the rule first and the students then verify it on paper","The students are rewarded with marks for every correct answer they give","The rule is memorised before the activity begins, so it can be applied"],"answer":0,"explanation":"In discovery learning learners infer the principle (the angles make a straight angle) from instances, guided by the teacher’s questions. Stating the rule first is expository teaching.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 6 की शिक्षिका विद्यार्थियों से कागज़ के त्रिभुज के तीनों कोने काटकर उन्हें एक सीधी रेखा पर साथ-साथ रखने को कहती है, कई त्रिभुजों के साथ प्रयास करने को कहती है, और फिर पूछती है, ‘तुम क्या देखते हो?’ कौन-सी विशेषता इसे ब्रूनर का खोज-अधिगम बनाती है?","optionsHi":["विद्यार्थी स्वयं संभाले हुए उदाहरणों से सामान्य नियम खोजते हैं","शिक्षिका पहले नियम बताती है और विद्यार्थी फिर उसे कागज़ पर सत्यापित करते हैं","विद्यार्थियों को उनके हर सही उत्तर के लिए अंक देकर पुरस्कृत किया जाता है","गतिविधि शुरू होने से पहले नियम रट लिया जाता है, ताकि उसे लागू किया जा सके"],"explanationHi":"खोज-अधिगम में अधिगमकर्ता शिक्षक के प्रश्नों के मार्गदर्शन में उदाहरणों से सिद्धांत (कोण मिलकर एक सरल कोण बनाते हैं) का अनुमान लगाते हैं। पहले नियम बताना व्याख्यात्मक शिक्षण है।"},
  {"id":"cdp-child-development-606","question":"Assertion (A): Bruner believed that a teacher need not simply wait for a child to become ‘ready’ for a subject. Reason (R): For Bruner, readiness can be nurtured by presenting ideas in a form that matches the child’s way of representing the world.","options":["Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"Bruner rejected passive waiting for readiness: by translating ideas into enactive or iconic forms, teachers can help children learn earlier. That is exactly why A holds.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"अभिकथन (A): ब्रूनर का मानना था कि शिक्षक को किसी विषय के लिए बच्चे के ‘तैयार’ होने की केवल प्रतीक्षा नहीं करनी चाहिए। कारण (R): ब्रूनर के लिए, विचारों को इस रूप में प्रस्तुत करके तत्परता का पोषण किया जा सकता है जो बच्चे के संसार को निरूपित करने के तरीके से मेल खाता हो।","optionsHi":["A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है","A और R दोनों सत्य हैं, और R, A की सही व्याख्या है"],"explanationHi":"ब्रूनर ने तत्परता की निष्क्रिय प्रतीक्षा को अस्वीकार किया: विचारों को क्रियात्मक या प्रतिबिंबात्मक रूपों में अनूदित करके शिक्षक बच्चों को पहले सीखने में सहायता कर सकते हैं। और इसी कारण A सही है।"},
  {"id":"cdp-child-development-607","question":"Bruner argued that teaching the basic structure of a subject (its fundamental ideas) rather than isolated facts helps students mainly because it:","options":["Reduces the need for any practice or revision once the main ideas are clear","Makes learning easier to remember and to transfer to new situations","Allows teachers to skip the enactive and iconic modes and go straight to symbols","Ensures that every student reaches formal operational thinking at an early age"],"answer":1,"explanation":"In ‘The Process of Education’ Bruner held that grasping structure makes a subject comprehensible, aids memory and allows transfer. It does not remove the need for practice or for concrete forms.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"ब्रूनर का तर्क था कि अलग-थलग तथ्यों के बजाय किसी विषय की मूल संरचना (उसके मौलिक विचार) पढ़ाना विद्यार्थियों की मुख्यतः इसलिए सहायता करता है क्योंकि वह:","optionsHi":["मुख्य विचार स्पष्ट होने के बाद अभ्यास या पुनरावर्तन की आवश्यकता घटा देता है","अधिगम को याद रखना और नई स्थितियों में हस्तांतरित करना आसान बनाता है","शिक्षकों को क्रियात्मक और प्रतिबिंबात्मक पक्ष छोड़कर सीधे प्रतीकों पर जाने देता है","यह सुनिश्चित करता है कि प्रत्येक विद्यार्थी छोटी आयु में औपचारिक संक्रियात्मक चिंतन तक पहुँच जाए"],"explanationHi":"‘द प्रोसेस ऑफ़ एजुकेशन’ में ब्रूनर का मत था कि संरचना को समझने से विषय बोधगम्य बनता है, स्मृति में सहायता मिलती है और हस्तांतरण संभव होता है। इससे अभ्यास या ठोस रूपों की आवश्यकता समाप्त नहीं होती।"},
  {"id":"cdp-child-development-608","question":"Before working out a sum, a Class 7 student quickly guesses, ‘The answer should be close to 200,’ and then checks it by calculation. Bruner’s view of such guessing is that:","options":["It is a bad habit that should be stopped, because it encourages careless work","It shows that the student is still stuck in the iconic mode of representation","It is a sign of test anxiety, and the student should be referred to a counsellor","Intuitive thinking is valuable and should be encouraged alongside checking"],"answer":3,"explanation":"Bruner valued intuitive thinking, the ability to make educated leaps, and felt schools neglected it. He wanted intuition to be tested by analytical thinking rather than suppressed.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कोई जोड़-घटाव का प्रश्न हल करने से पहले कक्षा 7 का विद्यार्थी शीघ्र अनुमान लगाता है, ‘उत्तर 200 के पास होना चाहिए,’ और फिर गणना से उसे जाँचता है। ऐसे अनुमान के बारे में ब्रूनर का मत है कि:","optionsHi":["यह एक बुरी आदत है जिसे रोका जाना चाहिए, क्योंकि यह लापरवाह कार्य को बढ़ावा देती है","यह दर्शाता है कि विद्यार्थी अब भी निरूपण के प्रतिबिंबात्मक पक्ष में अटका है","यह परीक्षा-चिंता का संकेत है, और विद्यार्थी को परामर्शदाता के पास भेजा जाना चाहिए","अंतर्ज्ञानात्मक चिंतन मूल्यवान है और उसे जाँच के साथ-साथ प्रोत्साहित किया जाना चाहिए"],"explanationHi":"ब्रूनर अंतर्ज्ञानात्मक चिंतन, यानी सुशिक्षित छलाँग लगाने की क्षमता, को मूल्यवान मानते थे और अनुभव करते थे कि विद्यालय इसकी उपेक्षा करते हैं। वे चाहते थे कि अंतर्ज्ञान को विश्लेषणात्मक चिंतन द्वारा परखा जाए, दबाया न जाए।"},
  {"id":"cdp-child-development-609","question":"A mother reads the same picture book with her toddler every evening: she points and asks, ‘What’s that?’, waits, and says, ‘Yes, it’s a cow!’ Over time she expects more words from the child. Bruner described such routine adult support for language as:","options":["A Language Acquisition Support System (LASS)","A Language Acquisition Device (LAD) at work","Holophrastic speech, using one word for a whole idea","Operant conditioning of verbal behaviour by praise"],"answer":0,"explanation":"Bruner proposed LASS to stress the role of structured social routines, in contrast to Chomsky’s inborn LAD. The adult raises expectations as the child grows, which is a form of scaffolding.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"एक माँ प्रतिदिन शाम को अपने शिशु के साथ वही चित्र-पुस्तक पढ़ती है: वह इशारा करके पूछती है, ‘वह क्या है?’, प्रतीक्षा करती है, और कहती है, ‘हाँ, वह गाय है!’ समय के साथ वह बच्चे से अधिक शब्दों की अपेक्षा करती है। भाषा के लिए ऐसे नियमित वयस्क सहयोग का ब्रूनर ने क्या वर्णन किया?","optionsHi":["भाषा अर्जन सहायता प्रणाली (LASS)","क्रियाशील भाषा अर्जन उपकरण (LAD)","एकपदीय वाणी, जिसमें पूरे विचार के लिए एक शब्द का प्रयोग होता है","प्रशंसा द्वारा शाब्दिक व्यवहार का संक्रियात्मक अनुबंधन"],"explanationHi":"ब्रूनर ने चॉम्स्की के जन्मजात LAD के विपरीत संरचित सामाजिक दिनचर्याओं की भूमिका पर बल देने के लिए LASS प्रस्तावित किया। बच्चे के बड़े होने पर वयस्क अपेक्षाएँ बढ़ाता है, जो पाड़ का एक रूप है।"},
  {"id":"cdp-child-development-610","question":"To teach place value, a Class 2 teacher in Bihar uses bundles of ten matchsticks, then has children draw bundles and loose sticks, and finally writes 34 as 3 tens 4 ones. The drawing step corresponds to Bruner’s:","options":["Enactive mode","Symbolic mode","Iconic mode","Formal operational mode"],"answer":2,"explanation":"Pictures and drawings are iconic representations. The common concrete-pictorial-abstract sequence in maths teaching follows Bruner’s enactive-iconic-symbolic order.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"स्थानीय मान सिखाने के लिए बिहार की कक्षा 2 की शिक्षिका दस-दस माचिस की तीलियों के बंडल इस्तेमाल करती है, फिर बच्चों से बंडल और खुली तीलियाँ बनवाती है, और अंत में 34 को 3 दहाई 4 इकाई के रूप में लिखती है। चित्र बनाने का चरण ब्रूनर के किस पक्ष से मेल खाता है?","optionsHi":["क्रियात्मक पक्ष","सांकेतिक पक्ष","प्रतिबिंबात्मक पक्ष","औपचारिक संक्रियात्मक पक्ष"],"explanationHi":"चित्र और रेखाचित्र प्रतिबिंबात्मक निरूपण हैं। गणित शिक्षण में प्रचलित मूर्त–चित्रात्मक–अमूर्त क्रम ब्रूनर के क्रियात्मक–प्रतिबिंबात्मक–सांकेतिक क्रम का अनुसरण करता है।"},
  {"id":"cdp-child-development-611","question":"A Class 1 teacher writes ‘3 + 2 = 5’ on the board and explains it, but many children cannot use it. Following Bruner, the best way to improve the lesson is to:","options":["Repeat the written statement more slowly and loudly until the children remember it","Start with children joining groups of real objects, then pictures, and then the written sum","Give a short test so that the weak children can be identified and sent for remedial help","Wait until the children reach the concrete operational stage before teaching addition"],"answer":1,"explanation":"Bruner held that young children grasp ideas best when they meet them first through action and images. He rejected simply waiting for readiness, which makes the last option a Piaget-style misreading.","difficulty":"moderate","source":"CTET · KVS · State TETs","questionHi":"कक्षा 1 की शिक्षिका श्यामपट्ट पर ‘3 + 2 = 5’ लिखकर उसे समझाती है, पर कई बच्चे उसका उपयोग नहीं कर पाते। ब्रूनर के अनुसार पाठ को सुधारने का सबसे अच्छा तरीका है:","optionsHi":["लिखे हुए कथन को और धीरे तथा ज़ोर से दोहराना जब तक बच्चे उसे याद न कर लें","वास्तविक वस्तुओं के समूहों को जोड़ने वाले बच्चों से शुरू करना, फिर चित्र, और फिर लिखा हुआ जोड़","कमज़ोर बच्चों की पहचान करके उपचारात्मक सहायता के लिए भेजने हेतु एक छोटी परीक्षा देना","जोड़ पढ़ाने से पहले बच्चों के मूर्त संक्रियात्मक अवस्था में पहुँचने तक प्रतीक्षा करना"],"explanationHi":"ब्रूनर का मत था कि छोटे बच्चे विचारों को सबसे अच्छी तरह तब ग्रहण करते हैं जब वे उनसे पहले क्रिया और छवियों के माध्यम से मिलें। उन्होंने केवल तत्परता की प्रतीक्षा करने को अस्वीकार किया, जिससे अंतिम विकल्प पियाजे-शैली की गलत व्याख्या बन जाता है।"},
  {"id":"cdp-child-development-612","question":"Consider these statements comparing Bruner with Piaget. 1. Bruner gave language and culture a stronger role in speeding up cognitive growth than Piaget did. 2. Bruner, like Piaget, held that the earlier modes of thinking disappear once a higher mode develops. 3. Both saw the learner as active rather than a passive receiver. Which is/are correct?","options":["1 and 3 only","2 and 3 only","1 and 2 only","3 only"],"answer":0,"explanation":"Bruner stressed language, culture and instruction more than Piaget, and both were constructivists. Statement 2 is wrong: Bruner’s modes coexist, and even in Piaget earlier abilities are integrated rather than lost.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"ब्रूनर की पियाजे से तुलना करने वाले इन कथनों पर विचार कीजिए। 1. ब्रूनर ने संज्ञानात्मक विकास को तेज़ करने में भाषा और संस्कृति को पियाजे से अधिक सशक्त भूमिका दी। 2. ब्रूनर ने, पियाजे की तरह, माना कि उच्चतर पक्ष विकसित होने पर चिंतन के पहले के पक्ष समाप्त हो जाते हैं। 3. दोनों ने अधिगमकर्ता को निष्क्रिय ग्राहक के बजाय सक्रिय माना। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 3","केवल 2 और 3","केवल 1 और 2","केवल 3"],"explanationHi":"ब्रूनर ने भाषा, संस्कृति और अनुदेशन पर पियाजे से अधिक बल दिया, और दोनों रचनावादी थे। कथन 2 गलत है: ब्रूनर के पक्ष साथ-साथ बने रहते हैं, और पियाजे में भी पहले की क्षमताएँ खोई नहीं जातीं बल्कि समाहित हो जाती हैं।"},
  {"id":"cdp-child-development-613","question":"While helping a child build a pyramid of wooden blocks, a tutor holds the lower blocks steady so that the child can concentrate on fitting the top piece. In Wood, Bruner and Ross’s account of scaffolding, this tutoring function is called:","options":["Recruitment of the child's interest","Frustration control during failures","Demonstration of an ideal solution","Reduction in degrees of freedom"],"answer":3,"explanation":"Reducing degrees of freedom means simplifying the task so the learner handles only a manageable part. Recruitment is getting the child interested, and frustration control is keeping failure from discouraging him.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक बच्चे को लकड़ी के ब्लॉकों का पिरामिड बनाने में सहायता करते हुए एक ट्यूटर निचले ब्लॉकों को स्थिर थामे रखता है ताकि बच्चा ऊपर का टुकड़ा बिठाने पर ध्यान दे सके। वुड, ब्रूनर और रॉस के पाड़ के वर्णन में इस ट्यूटरिंग प्रकार्य को क्या कहा जाता है?","optionsHi":["बच्चे की रुचि को भर्ती करना","असफलताओं के दौरान कुंठा का नियंत्रण","आदर्श समाधान का प्रदर्शन","स्वातंत्र्य-कोटियों में कमी"],"explanationHi":"स्वातंत्र्य-कोटियों में कमी का अर्थ कार्य को सरल बनाना है ताकि अधिगमकर्ता केवल एक प्रबंधनीय भाग सँभाले। भर्ती का अर्थ बच्चे की रुचि जगाना है, और कुंठा-नियंत्रण का अर्थ असफलता को उसे हतोत्साहित करने से रोकना है।"},
  {"id":"cdp-child-development-614","question":"A Class 5 teacher draws a labelled flow diagram of the water cycle on the board. Which mode of representation is she mainly using, and what should follow according to Bruner?","options":["Enactive; the next step should be a practical demonstration of evaporation","Iconic; it should lead on to children explaining the cycle in words and terms","Symbolic; nothing further is needed, since a diagram is already abstract","Enactive; the children should copy the diagram several times to fix it in memory"],"answer":1,"explanation":"A diagram is an iconic representation. Bruner’s sequence moves on to the symbolic mode, where children use language and terms like evaporation and condensation.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 5 की शिक्षिका श्यामपट्ट पर जल-चक्र का नामांकित प्रवाह-आरेख बनाती है। वह मुख्यतः निरूपण के किस पक्ष का उपयोग कर रही है, और ब्रूनर के अनुसार उसके बाद क्या आना चाहिए?","optionsHi":["क्रियात्मक; अगला चरण वाष्पीकरण का एक व्यावहारिक प्रदर्शन होना चाहिए","प्रतिबिंबात्मक; इसके बाद बच्चों को चक्र को शब्दों और पदों में समझाना चाहिए","सांकेतिक; और कुछ आवश्यक नहीं, क्योंकि आरेख पहले से अमूर्त है","क्रियात्मक; बच्चों को आरेख कई बार उतारना चाहिए ताकि वह स्मृति में बैठ जाए"],"explanationHi":"आरेख एक प्रतिबिंबात्मक निरूपण है। ब्रूनर का क्रम सांकेतिक पक्ष की ओर बढ़ता है, जहाँ बच्चे भाषा और वाष्पीकरण तथा संघनन जैसे पदों का प्रयोग करते हैं।"},
  {"id":"cdp-child-development-615","question":"How many of these are recognised limitations of pure, unguided discovery learning? I. It usually takes less time than direct instruction. II. Learners may ‘discover’ and keep wrong ideas if there is no guidance. III. It always reduces intrinsic motivation. IV. Learners with little prior knowledge may find it overwhelming.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and IV are real limitations. I is wrong: unguided discovery usually takes much more time than direct instruction. III is wrong: discovery tends to increase intrinsic motivation, as Bruner argued.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"शुद्ध, बिना निर्देशन के खोज-अधिगम की मान्य सीमाओं में से इनमें कितनी हैं? I. इसमें प्रायः प्रत्यक्ष अनुदेशन से कम समय लगता है। II. मार्गदर्शन के अभाव में अधिगमकर्ता गलत विचार ‘खोज’ सकते हैं और उन्हें बनाए रख सकते हैं। III. यह सदैव आंतरिक अभिप्रेरणा को घटाता है। IV. कम पूर्व ज्ञान वाले अधिगमकर्ताओं को यह भारी लग सकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"II और IV वास्तविक सीमाएँ हैं। I गलत है: बिना निर्देशन की खोज में प्रायः प्रत्यक्ष अनुदेशन से बहुत अधिक समय लगता है। III गलत है: खोज आंतरिक अभिप्रेरणा को बढ़ाती है, जैसा ब्रूनर ने तर्क दिया।"},
  {"id":"cdp-child-development-616","question":"In a Bruner-style discovery lesson on magnets, what is the main role of the teacher?","options":["To deliver the complete rule at the start and then test children's recall at the end","To stay completely away from the groups, so that children are not influenced at all","To set up a problem, provide materials and ask questions that lead to the principle","To award marks to each child who reaches the answer first, to keep interest high"],"answer":2,"explanation":"Bruner’s teacher designs the situation and guides through questions, rather than lecturing or withdrawing entirely. Racing for marks shifts motivation from understanding to reward.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"चुंबकों पर ब्रूनर-शैली के खोज-पाठ में शिक्षक की मुख्य भूमिका क्या है?","optionsHi":["आरंभ में पूरा नियम बताना और अंत में बच्चों की स्मृति की परीक्षा लेना","समूहों से पूरी तरह दूर रहना, ताकि बच्चे बिल्कुल प्रभावित न हों","कोई समस्या रचना, सामग्री उपलब्ध कराना और ऐसे प्रश्न पूछना जो सिद्धांत तक ले जाएँ","जो बच्चा सबसे पहले उत्तर तक पहुँचे उसे अंक देना, ताकि रुचि बनी रहे"],"explanationHi":"ब्रूनर का शिक्षक व्याख्यान देने या पूरी तरह हट जाने के बजाय स्थिति रचता है और प्रश्नों से मार्गदर्शन करता है। अंकों की दौड़ अभिप्रेरणा को समझ से पुरस्कार की ओर मोड़ देती है।"},
  {"id":"cdp-child-development-617","question":"Assertion (A): Bruner recommended that basic ideas be revisited again and again through the school years. Reason (R): A learner’s understanding of a concept deepens as she can represent it in increasingly powerful ways.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The spiral curriculum follows from the idea that the same concept can be understood at higher levels as the learner’s modes of representation develop. R therefore explains A.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"अभिकथन (A): ब्रूनर ने सिफ़ारिश की कि मूल विचारों को विद्यालयी वर्षों में बार-बार दोहराया जाए। कारण (R): जैसे-जैसे अधिगमकर्ता किसी संप्रत्यय को अधिकाधिक सशक्त ढंग से निरूपित कर पाती है, उसकी समझ गहरी होती जाती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"सर्पिल पाठ्यचर्या इस विचार से निकलती है कि अधिगमकर्ता के निरूपण के पक्षों के विकसित होने पर वही संप्रत्यय उच्चतर स्तरों पर समझा जा सकता है। इसलिए R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-618","question":"A Class 8 student plays a complex tabla rhythm perfectly but cannot describe it in words or draw it. In Bruner’s terms, this shows that:","options":["The student has not yet reached Piaget's concrete operational stage of thinking","Knowledge can be held enactively even by older learners with symbolic thought","The student's symbolic mode of representation has failed to develop normally","The skill was learnt purely through classical conditioning and not through thought"],"answer":1,"explanation":"Bruner’s modes are not confined to early childhood; motor skills often stay enactive. Lack of a verbal description does not mean the symbolic mode is absent.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 8 का एक विद्यार्थी एक जटिल तबला-ताल को पूर्णता से बजाता है पर उसे शब्दों में समझा या चित्र में बना नहीं सकता। ब्रूनर के शब्दों में, यह दर्शाता है कि:","optionsHi":["विद्यार्थी अभी तक पियाजे की मूर्त संक्रियात्मक चिंतन अवस्था तक नहीं पहुँचा है","सांकेतिक चिंतन वाले बड़े अधिगमकर्ताओं में भी ज्ञान क्रियात्मक रूप में धारण किया जा सकता है","विद्यार्थी का निरूपण का सांकेतिक पक्ष सामान्य रूप से विकसित होने में विफल रहा है","यह कौशल पूर्णतः शास्त्रीय अनुबंधन से सीखा गया था, चिंतन से नहीं"],"explanationHi":"ब्रूनर के पक्ष केवल बाल्यावस्था तक सीमित नहीं हैं; गामक कौशल प्रायः क्रियात्मक बने रहते हैं। शाब्दिक वर्णन का अभाव यह नहीं दर्शाता कि सांकेतिक पक्ष अनुपस्थित है।"},
  {"id":"cdp-child-development-619","question":"A teacher shows ‘yes’ examples (mango, pea pod, tomato, cucumber) and ‘no’ examples (potato, carrot, onion) of the concept ‘fruit’ in the botanical sense, without naming it, and asks students to work out what the ‘yes’ examples share. This concept attainment approach is based on the work of:","options":["Jerome Bruner","B. F. Skinner","Lawrence Kohlberg","Erik Erikson"],"answer":0,"explanation":"Bruner, Goodnow and Austin studied how people attain concepts by testing hypotheses about the attributes of positive and negative examples; the concept attainment teaching model grew from this work.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"एक शिक्षक वानस्पतिक अर्थ में ‘फल’ संप्रत्यय के ‘हाँ’ उदाहरण (आम, मटर की फली, टमाटर, खीरा) और ‘नहीं’ उदाहरण (आलू, गाजर, प्याज़) बिना उसका नाम बताए दिखाता है, और विद्यार्थियों से पता लगाने को कहता है कि ‘हाँ’ उदाहरणों में क्या समानता है। यह संप्रत्यय प्राप्ति उपागम किसके कार्य पर आधारित है?","optionsHi":["जेरोम ब्रूनर","बी. एफ़. स्किनर","लॉरेंस कोहलबर्ग","एरिक एरिक्सन"],"explanationHi":"ब्रूनर, गुडनाउ और ऑस्टिन ने अध्ययन किया कि लोग धनात्मक और ऋणात्मक उदाहरणों के गुणों के बारे में परिकल्पनाओं का परीक्षण करके संप्रत्यय कैसे प्राप्त करते हैं; संप्रत्यय प्राप्ति शिक्षण मॉडल इसी कार्य से उपजा।"},
  {"id":"cdp-child-development-620","question":"Which statement about Bruner’s discovery learning is most accurate?","options":["It means leaving students to find out everything with no teacher involvement","It applies only to science, and not to languages or the social studies","It is essentially rote learning of rules followed by plenty of practice","It aims to make students active problem solvers who find relationships themselves"],"answer":3,"explanation":"Discovery learning centres on learners finding structure and relationships. It is used across subjects, and in practice it works best as guided discovery rather than total withdrawal of the teacher.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"ब्रूनर के खोज-अधिगम के बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["इसका अर्थ है विद्यार्थियों को बिना शिक्षक की किसी भागीदारी के सब कुछ खोजने के लिए छोड़ देना","यह केवल विज्ञान पर लागू होता है, भाषाओं या सामाजिक अध्ययन पर नहीं","यह मूलतः नियमों का रटंत अधिगम है, जिसके बाद ढेर सारा अभ्यास होता है","इसका उद्देश्य विद्यार्थियों को सक्रिय समस्या-समाधानकर्ता बनाना है जो संबंधों को स्वयं खोजें"],"explanationHi":"खोज-अधिगम का केंद्र अधिगमकर्ताओं द्वारा संरचना और संबंधों की खोज है। यह सभी विषयों में प्रयुक्त होता है, और व्यवहार में यह निर्देशित खोज के रूप में सबसे अच्छा काम करता है, शिक्षक के पूरी तरह हट जाने के रूप में नहीं।"},
  {"id":"cdp-child-development-621","question":"A Class 4 teacher asks students to act out the movement of the Earth around the Sun, then sketch the orbit, and later explains it using the terms ‘rotation’ and ‘revolution’. A visiting teacher says, ‘Acting is a waste of time at this age.’ Bruner would reply that:","options":["The visitor is right, since Class 4 children already think only in symbols and words","Acting out gives an enactive base on which iconic and symbolic understanding can build","Acting out is useful only for children with disabilities, not for the whole class","Only the final explanation matters, since knowledge exists only in the form of symbols"],"answer":1,"explanation":"For Bruner, enactive and iconic experiences support the later symbolic understanding of an idea, especially when it is new. He did not regard any mode as useless.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 की शिक्षिका विद्यार्थियों से पृथ्वी की सूर्य के चारों ओर गति का अभिनय करवाती है, फिर कक्षा-पथ का रेखाचित्र बनवाती है, और बाद में ‘घूर्णन’ तथा ‘परिक्रमण’ शब्दों से उसे समझाती है। एक आगंतुक शिक्षक कहता है, ‘इस आयु में अभिनय समय की बर्बादी है।’ ब्रूनर इसके उत्तर में कहते कि:","optionsHi":["आगंतुक सही है, क्योंकि कक्षा 4 के बच्चे पहले से ही केवल प्रतीकों और शब्दों में सोचते हैं","अभिनय एक क्रियात्मक आधार देता है जिस पर प्रतिबिंबात्मक और सांकेतिक समझ निर्मित हो सकती है","अभिनय केवल विकलांग बच्चों के लिए उपयोगी है, पूरी कक्षा के लिए नहीं","केवल अंतिम व्याख्या मायने रखती है, क्योंकि ज्ञान केवल प्रतीकों के रूप में ही अस्तित्व में होता है"],"explanationHi":"ब्रूनर के लिए क्रियात्मक और प्रतिबिंबात्मक अनुभव किसी विचार की बाद की सांकेतिक समझ को सहारा देते हैं, विशेषकर जब वह नया हो। वे किसी भी पक्ष को व्यर्थ नहीं मानते थे।"},
  {"id":"cdp-child-development-622","question":"Which of the following pairs is correctly matched?","options":["Spiral curriculum: Vygotsky","Modes of representation: Piaget","Equilibration: Bruner","Discovery learning: Bruner"],"answer":3,"explanation":"Discovery learning, the spiral curriculum and the enactive-iconic-symbolic modes are Bruner’s ideas; equilibration is Piaget’s.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"निम्नलिखित में से कौन-सा युग्म सही मिलान वाला है?","optionsHi":["सर्पिल पाठ्यचर्या: वाइगोत्स्की","निरूपण के पक्ष: पियाजे","साम्यधारण: ब्रूनर","खोज-अधिगम: ब्रूनर"],"explanationHi":"खोज-अधिगम, सर्पिल पाठ्यचर्या और क्रियात्मक–प्रतिबिंबात्मक–सांकेतिक पक्ष ब्रूनर के विचार हैं; साम्यधारण पियाजे का है।"},
  {"id":"cdp-child-development-623","question":"Bruner held that discovery learning tends to shift students’ motivation from:","options":["Intrinsic reward towards dependence on the teacher's approval and praise","Extrinsic rewards such as marks to the satisfaction of finding things out","Natural curiosity towards anxiety about making mistakes in front of others","Shared group goals towards individual competition for the highest marks"],"answer":1,"explanation":"Bruner argued that the reward of discovery lies in the discovery itself, so learners become less dependent on external rewards. This is one of his main arguments for the method.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"ब्रूनर का मत था कि खोज-अधिगम विद्यार्थियों की अभिप्रेरणा को प्रायः किस ओर से किस ओर ले जाता है:","optionsHi":["आंतरिक पुरस्कार से शिक्षक की स्वीकृति और प्रशंसा पर निर्भरता की ओर","अंकों जैसे बाह्य पुरस्कारों से चीज़ें खोज निकालने की संतुष्टि की ओर","स्वाभाविक जिज्ञासा से दूसरों के सामने गलती करने की चिंता की ओर","साझे समूह-लक्ष्यों से सर्वाधिक अंकों के लिए व्यक्तिगत प्रतिस्पर्धा की ओर"],"explanationHi":"ब्रूनर का तर्क था कि खोज का पुरस्कार स्वयं खोज में निहित है, इसलिए अधिगमकर्ता बाह्य पुरस्कारों पर कम निर्भर हो जाते हैं। यह इस विधि के पक्ष में उनके मुख्य तर्कों में से एक है।"},
  {"id":"cdp-child-development-624","question":"A Class 9 student can solve 2x + 3 = 11 by rules but is confused when a problem is written in words. Her teacher shows a balance with a bag of unknown marbles plus 3 marbles on one side and 11 on the other, then a drawing of it. In Bruner’s terms, the teacher is:","options":["Lowering the standard, since students of Class 9 should work only with symbols","Using operant shaping, rewarding each step that brings her closer to the answer","Going back to enactive and iconic forms to give meaning to the symbolic rule","Applying Piaget's idea of horizontal décalage to the solving of linear equations"],"answer":2,"explanation":"Bruner held that any learner meeting a hard idea can benefit from enactive and iconic representations, which give meaning to symbols. Using them is not lowering the standard.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 9 की एक विद्यार्थी 2x + 3 = 11 को नियमों से हल कर सकती है, पर जब कोई समस्या शब्दों में लिखी हो तो उलझ जाती है। उसकी शिक्षिका एक तराज़ू दिखाती है जिसके एक पलड़े पर अज्ञात कंचों की एक थैली और 3 कंचे हैं और दूसरे पर 11, फिर उसका एक चित्र। ब्रूनर के शब्दों में, शिक्षिका क्या कर रही है?","optionsHi":["स्तर घटा रही है, क्योंकि कक्षा 9 के विद्यार्थियों को केवल प्रतीकों के साथ काम करना चाहिए","संक्रियात्मक आकार-निर्धारण का उपयोग कर रही है, उत्तर के निकट लाने वाले प्रत्येक चरण को पुरस्कृत करते हुए","सांकेतिक नियम को अर्थ देने के लिए क्रियात्मक और प्रतिबिंबात्मक रूपों की ओर लौट रही है","रैखिक समीकरणों को हल करने में पियाजे के क्षैतिज विस्थापन (हॉरिज़ॉन्टल डेकैलाज) के विचार को लागू कर रही है"],"explanationHi":"ब्रूनर का मत था कि कठिन विचार से मिल रहा कोई भी अधिगमकर्ता क्रियात्मक और प्रतिबिंबात्मक निरूपणों से लाभ उठा सकता है, जो प्रतीकों को अर्थ देते हैं। उनका उपयोग स्तर घटाना नहीं है।"},
  {"id":"cdp-child-development-625","question":"Which classroom practice best reflects Bruner’s idea that learners should ‘go beyond the information given’?","options":["Asking students to copy the worked notes exactly as they appear on the board","Giving a few examples of a pattern and asking students to predict and explain the rule","Reading the textbook aloud carefully while all the students follow along in their books","Asking students to memorise all the definitions given at the end of the chapter"],"answer":1,"explanation":"Bruner saw learning as forming categories and coding systems that allow inference beyond what is directly given. Copying and memorising stay within the information given.","difficulty":"hard","source":"CTET · DSSSB · State TETs","questionHi":"ब्रूनर के इस विचार को कि अधिगमकर्ताओं को ‘दी गई जानकारी से आगे जाना’ चाहिए, कक्षा की कौन-सी प्रथा सबसे अच्छी तरह दर्शाती है?","optionsHi":["विद्यार्थियों से श्यामपट्ट पर दिखे हल किए नोट्स को ठीक वैसा ही उतारने को कहना","किसी प्रतिरूप के कुछ उदाहरण देकर विद्यार्थियों से नियम का अनुमान लगाने और उसे समझाने को कहना","पाठ्यपुस्तक को ध्यानपूर्वक ज़ोर से पढ़ना जबकि सभी विद्यार्थी अपनी पुस्तकों में साथ-साथ देखते रहें","विद्यार्थियों से अध्याय के अंत में दी गई सभी परिभाषाएँ रटने को कहना"],"explanationHi":"ब्रूनर अधिगम को ऐसी श्रेणियाँ और कूट-प्रणालियाँ बनाने के रूप में देखते थे जो प्रत्यक्ष दी गई जानकारी से आगे अनुमान की अनुमति देती हैं। उतारना और रटना दी गई जानकारी की सीमा में ही रहते हैं।"},
  {"id":"cdp-child-development-626","question":"A teacher tells Class 1 two stories: Ravi broke twelve glasses by accident while helping his mother; Sonu broke one glass while secretly reaching for sweets. Most children say Ravi was naughtier. According to Piaget, these children are showing:","options":["Autonomous morality, because they consider the facts of each case carefully","Moral realism, judging the act by the damage done rather than the intention","Kohlberg's Stage 2 reasoning, because they weigh up costs against benefits","Moral relativism, because they are comparing the two cases with each other"],"answer":1,"explanation":"In heteronomous morality (moral realism), young children judge by objective consequences; twelve glasses outweigh one, regardless of intention. Older children shift to judging by intention.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक कक्षा 1 को दो कहानियाँ सुनाता है: रवि ने माँ की मदद करते हुए अनजाने में बारह गिलास तोड़ दिए; सोनू ने चुपके से मिठाई लेने की कोशिश में एक गिलास तोड़ा। अधिकांश बच्चे कहते हैं कि रवि अधिक शरारती था। पियाजे के अनुसार ये बच्चे क्या दर्शा रहे हैं?","optionsHi":["स्वायत्त नैतिकता, क्योंकि वे प्रत्येक मामले के तथ्यों पर ध्यानपूर्वक विचार करते हैं","नैतिक यथार्थवाद, कृत्य को इरादे के बजाय हुई क्षति से आँकना","कोहलबर्ग की अवस्था 2 का तर्क, क्योंकि वे लागत की तुलना लाभ से करते हैं","नैतिक सापेक्षवाद, क्योंकि वे दोनों मामलों की एक-दूसरे से तुलना कर रहे हैं"],"explanationHi":"विषम-नियमित नैतिकता (नैतिक यथार्थवाद) में छोटे बच्चे वस्तुनिष्ठ परिणामों से आँकते हैं; इरादे की परवाह किए बिना बारह गिलास एक से भारी पड़ते हैं। बड़े बच्चे इरादे से आँकने की ओर बढ़ते हैं।"},
  {"id":"cdp-child-development-627","question":"Asked about the same two stories, an eleven-year-old says, ‘Sonu was worse, because he was doing something he wasn’t supposed to; Ravi was only trying to help.’ In Piaget’s terms this child has moved to:","options":["Heteronomous morality (morality of constraint)","The premoral stage of rule-free play","Autonomous morality (morality of cooperation)","Immanent justice (automatic punishment)"],"answer":2,"explanation":"Weighing intentions above consequences marks the shift to autonomous morality, which Piaget placed at around ten years and beyond. Immanent justice is a belief of the younger, heteronomous child.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"उन्हीं दो कहानियों के बारे में पूछे जाने पर एक ग्यारह वर्ष का बच्चा कहता है, ‘सोनू बुरा था, क्योंकि वह ऐसा कुछ कर रहा था जो उसे नहीं करना चाहिए था; रवि तो केवल मदद करने की कोशिश कर रहा था।’ पियाजे के शब्दों में यह बच्चा किस ओर बढ़ चुका है?","optionsHi":["परतंत्र नैतिकता (अवरोध की नैतिकता)","नियम-रहित खेल की पूर्व-नैतिक अवस्था","स्वायत्त नैतिकता (सहयोग की नैतिकता)","अंतर्निहित न्याय (स्वतः दंड)"],"explanationHi":"परिणामों से ऊपर इरादों को तौलना स्वायत्त नैतिकता की ओर बढ़ने का चिह्न है, जिसे पियाजे ने लगभग दस वर्ष और उसके बाद की आयु पर रखा। अंतर्निहित न्याय छोटे, परतंत्र नैतिकता वाले बच्चे की मान्यता है।"},
  {"id":"cdp-child-development-628","question":"A seven-year-old who lied to his teacher in the morning trips on the way home and scrapes his knee. He tells his mother, ‘That happened because I lied.’ Piaget called this belief:","options":["Reciprocal punishment","Moral relativism","Egocentric speech","Immanent justice"],"answer":3,"explanation":"Immanent justice is the belief that wrongdoing is automatically punished by the world itself, typical of the heteronomous stage. Reciprocal punishment is a later idea that punishment should fit the wrong.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक सात वर्ष का बच्चा, जिसने सुबह शिक्षक से झूठ बोला था, घर लौटते समय फिसलकर घुटना छील लेता है। वह अपनी माँ से कहता है, ‘यह इसलिए हुआ क्योंकि मैंने झूठ बोला था।’ पियाजे ने इस विश्वास को क्या कहा?","optionsHi":["पारस्परिक दंड","नैतिक सापेक्षवाद","अहंकेंद्रित वाणी","अंतर्निहित न्याय"],"explanationHi":"अंतर्निहित न्याय यह विश्वास है कि गलत कार्य को संसार स्वयं स्वतः दंडित करता है, जो परतंत्र अवस्था की विशेषता है। पारस्परिक दंड बाद का विचार है कि दंड गलती के अनुरूप होना चाहिए।"},
  {"id":"cdp-child-development-629","question":"During a games period, Class 5 children agree among themselves to change the rules of kho-kho so that a younger child who has joined can also play fairly. According to Piaget, this shows that they:","options":["See rules as agreements that can be changed by mutual consent","Are still in moral realism, since they follow rules very strictly","Believe that rules come from adults and can never be altered","Are at Kohlberg's Stage 1, as they act mainly to avoid punishment"],"answer":0,"explanation":"Treating rules as mutual agreements open to change is the core of Piaget’s autonomous morality, which he observed in children’s games of marbles.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"खेल के कालांश में कक्षा 5 के बच्चे आपस में सहमत होते हैं कि खो-खो के नियम बदल दिए जाएँ ताकि जुड़ा हुआ एक छोटा बच्चा भी उचित ढंग से खेल सके। पियाजे के अनुसार यह दर्शाता है कि वे:","optionsHi":["नियमों को ऐसे समझौते मानते हैं जिन्हें आपसी सहमति से बदला जा सकता है","अब भी नैतिक यथार्थवाद में हैं, क्योंकि वे नियमों का बहुत कड़ाई से पालन करते हैं","मानते हैं कि नियम वयस्कों से आते हैं और कभी बदले नहीं जा सकते","कोहलबर्ग की अवस्था 1 पर हैं, क्योंकि वे मुख्यतः दंड से बचने के लिए कार्य करते हैं"],"explanationHi":"नियमों को बदले जा सकने वाले आपसी समझौते मानना पियाजे की स्वायत्त नैतिकता का मूल है, जिसे उन्होंने बच्चों के कंचों के खेल में देखा।"},
  {"id":"cdp-child-development-630","question":"A boy breaks a neighbour’s window with his ball. A six-year-old says he should ‘get a big beating’; a ten-year-old says he should ‘pay for the glass from his pocket money and say sorry’. Piaget would describe these two views respectively as:","options":["Reciprocal punishment and expiatory punishment","Expiatory punishment and reciprocal punishment","Immanent justice and moral realism","Autonomous and heteronomous morality"],"answer":1,"explanation":"Younger children favour severe, arbitrary (expiatory) punishment; older children prefer punishment that fits and repairs the wrong (reciprocal). The first option reverses them.","difficulty":"very-hard","source":"CTET Paper 1 · State TET","questionHi":"एक लड़का अपनी गेंद से पड़ोसी की खिड़की तोड़ देता है। एक छह वर्ष का बच्चा कहता है कि उसे ‘बड़ी मार पड़नी चाहिए’; एक दस वर्ष का बच्चा कहता है कि उसे ‘अपनी जेबखर्ची से शीशे के पैसे देने चाहिए और माफ़ी माँगनी चाहिए’। पियाजे इन दोनों मतों का क्रमशः क्या वर्णन करते?","optionsHi":["पारस्परिक दंड और प्रायश्चित्त दंड","प्रायश्चित्त दंड और पारस्परिक दंड","अंतर्निहित न्याय और नैतिक यथार्थवाद","स्वायत्त और परतंत्र नैतिकता"],"explanationHi":"छोटे बच्चे कठोर, मनमाने (प्रायश्चित्त) दंड का पक्ष लेते हैं; बड़े बच्चे ऐसा दंड पसंद करते हैं जो गलती के अनुरूप हो और उसे सुधारे (पारस्परिक)। पहला विकल्प इन्हें उलट देता है।"},
  {"id":"cdp-child-development-631","question":"Which experience did Piaget consider most important in moving children from heteronomous to autonomous morality?","options":["Strict discipline and close supervision by parents","Repeated moral instruction by teachers","Fear of punishment for breaking rules","Cooperative interaction with peers of equal status"],"answer":3,"explanation":"Piaget argued that relations of unilateral respect for adults sustain heteronomy, while give-and-take among equals shows rules to be mutual agreements. Adult control and fear work against autonomy.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"पियाजे ने किस अनुभव को बच्चों को परतंत्र नैतिकता से स्वायत्त नैतिकता की ओर ले जाने में सबसे महत्त्वपूर्ण माना?","optionsHi":["माता-पिता का कठोर अनुशासन और निकट पर्यवेक्षण","शिक्षकों द्वारा बार-बार नैतिक उपदेश","नियम तोड़ने पर दंड का भय","समान स्थिति वाले सहपाठियों के साथ सहयोगात्मक अंतःक्रिया"],"explanationHi":"पियाजे का तर्क था कि वयस्कों के प्रति एकपक्षीय सम्मान के संबंध परतंत्रता को बनाए रखते हैं, जबकि बराबर वालों के बीच लेन-देन दिखाता है कि नियम आपसी समझौते हैं। वयस्कों का नियंत्रण और भय स्वायत्तता के विरुद्ध काम करते हैं।"},
  {"id":"cdp-child-development-632","question":"Assertion (A): Piaget believed that cooperative peer interaction promotes autonomous morality. Reason (R): Among equals, children must negotiate, take others’ viewpoints and discover that rules are mutual agreements.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Peer interaction reduces egocentrism and shows rules as negotiated; that is precisely why Piaget saw it as driving autonomous morality.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"अभिकथन (A): पियाजे का मानना था कि सहपाठियों के साथ सहयोगात्मक अंतःक्रिया स्वायत्त नैतिकता को बढ़ावा देती है। कारण (R): बराबर वालों के बीच बच्चों को वार्ता करनी पड़ती है, दूसरों का दृष्टिकोण लेना पड़ता है और यह जानना पड़ता है कि नियम आपसी समझौते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"सहपाठी-अंतःक्रिया अहंकेंद्रिता को घटाती है और नियमों को वार्ता से तय होने वाला दिखाती है; यही कारण है कि पियाजे इसे स्वायत्त नैतिकता का प्रेरक मानते थे।"},
  {"id":"cdp-child-development-633","question":"In Class 2, children demand the same punishment for Meena, who spilt ink on a library book by accident, and Tara, who did it deliberately. What is the most appropriate response from the teacher?","options":["Punish both girls equally, since the children see that as the fair thing to do","Scold the class for being harsh and unforgiving towards their classmates","Ignore the issue, because moral thinking at this age cannot really be taught","Accept the view as age-typical and gently prompt them to consider each girl's intent"],"answer":3,"explanation":"Judging by outcome is age-typical moral realism; questions about intentions help children move toward autonomous judgment, while punishing equally reinforces the outcome-based view.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 में बच्चे मीना, जिसने अनजाने में पुस्तकालय की किताब पर स्याही गिरा दी, और तारा, जिसने जान-बूझकर ऐसा किया, के लिए एक जैसे दंड की माँग करते हैं। शिक्षिका की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["दोनों लड़कियों को समान दंड देना, क्योंकि बच्चे इसे उचित मानते हैं","कक्षा को अपने सहपाठियों के प्रति कठोर और अक्षमाशील होने के लिए डाँटना","इस मुद्दे को अनदेखा करना, क्योंकि इस आयु में नैतिक सोच वास्तव में सिखाई नहीं जा सकती","इस मत को आयु-सामान्य मानकर स्वीकार करना और उन्हें धीरे से प्रत्येक लड़की के इरादे पर विचार करने के लिए प्रेरित करना"],"explanationHi":"परिणाम से आँकना आयु-सामान्य नैतिक यथार्थवाद है; इरादों के बारे में प्रश्न बच्चों को स्वायत्त निर्णय की ओर बढ़ने में सहायता करते हैं, जबकि समान दंड देना परिणाम-आधारित दृष्टि को सुदृढ़ करता है।"},
  {"id":"cdp-child-development-634","question":"Which of these are features of Piaget’s heteronomous morality? I. Acts are judged by their consequences. II. Rules are seen as fixed and handed down by authorities. III. Punishment should fit the wrongdoing and repair the harm. IV. Belief that wrongdoing is automatically punished.","options":["I, II and IV only","I, II and III only","II, III and IV only","I and IV only"],"answer":0,"explanation":"Consequence-based judgment, fixed rules and immanent justice belong to the heteronomous stage; punishment that fits and repairs (reciprocity) belongs to autonomous morality.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"इनमें से कौन-सी पियाजे की परतंत्र नैतिकता की विशेषताएँ हैं? I. कृत्यों को उनके परिणामों से आँका जाता है। II. नियमों को स्थिर और अधिकारियों द्वारा सौंपा हुआ माना जाता है। III. दंड गलती के अनुरूप होना चाहिए और क्षति की भरपाई करे। IV. यह विश्वास कि गलत कार्य स्वतः दंडित होता है।","optionsHi":["केवल I, II और IV","केवल I, II और III","केवल II, III और IV","केवल I और IV"],"explanationHi":"परिणाम-आधारित निर्णय, स्थिर नियम और अंतर्निहित न्याय परतंत्र अवस्था के हैं; अनुरूप और भरपाई करने वाला दंड (पारस्परिकता) स्वायत्त नैतिकता का है।"},
  {"id":"cdp-child-development-635","question":"A five-year-old says that a boy who told his mother ‘I saw a dog as big as an elephant’ told a worse lie than a boy who falsely told her ‘I got good marks’ and was believed. An older child says the opposite. What does Piaget’s work suggest?","options":["The younger child judges the lie by intention, and the older child by its consequence","Both children are still in the stage of moral realism, judging by fixed rules","The younger child judges by how far it departs from reality, the older by intent to deceive","The older child is still in heteronomous morality, as he relies on whether the mother believed it"],"answer":2,"explanation":"Piaget found young children rate a lie as worse the more unbelievable it is, an objective standard; older children judge the intent to deceive, so the believed lie is worse.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक पाँच वर्ष का बच्चा कहता है कि जिस लड़के ने माँ से कहा ‘मैंने हाथी जितना बड़ा कुत्ता देखा’ उसने उस लड़के से बुरा झूठ बोला जिसने माँ से झूठ कहा ‘मुझे अच्छे अंक मिले’ और जिसकी बात मान ली गई। एक बड़ा बच्चा इसका उलटा कहता है। पियाजे का कार्य क्या सुझाता है?","optionsHi":["छोटा बच्चा झूठ को इरादे से आँकता है, और बड़ा बच्चा उसके परिणाम से","दोनों बच्चे अब भी नैतिक यथार्थवाद की अवस्था में हैं, स्थिर नियमों से आँकते हुए","छोटा बच्चा इस बात से आँकता है कि वह वास्तविकता से कितना दूर है, बड़ा बच्चा धोखा देने के इरादे से","बड़ा बच्चा अब भी परतंत्र नैतिकता में है, क्योंकि वह इस पर निर्भर करता है कि माँ ने उस पर विश्वास किया या नहीं"],"explanationHi":"पियाजे ने पाया कि छोटे बच्चे झूठ को जितना अविश्वसनीय हो उतना ही बुरा मानते हैं, जो एक वस्तुनिष्ठ मानक है; बड़े बच्चे धोखे के इरादे से आँकते हैं, इसलिए जिस झूठ पर विश्वास कर लिया गया वह अधिक बुरा है।"},
  {"id":"cdp-child-development-636","question":"In a Class 5 football game, a boy grabs the ball and refuses to pass it. The other children decide that he will not get to keep the ball during the next game. Piaget would call this:","options":["Expiatory (atoning) punishment","Immanent justice from the world","Moral realism about fixed rules","Punishment by reciprocity"],"answer":3,"explanation":"Reciprocal punishment is logically linked to the offence (misuse the ball, lose access to it); it marks autonomous morality, in contrast to arbitrary, painful expiatory punishment.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 5 के फ़ुटबॉल खेल में एक लड़का गेंद पकड़ लेता है और उसे पास देने से मना कर देता है। अन्य बच्चे तय करते हैं कि अगले खेल में उसे गेंद नहीं मिलेगी। पियाजे इसे क्या कहते?","optionsHi":["प्रायश्चित्त दंड","संसार से अंतर्निहित न्याय","स्थिर नियमों के बारे में नैतिक यथार्थवाद","पारस्परिकता द्वारा दंड"],"explanationHi":"पारस्परिक दंड तार्किक रूप से अपराध से जुड़ा होता है (गेंद का दुरुपयोग करो, उस तक पहुँच खोओ); यह स्वायत्त नैतिकता का चिह्न है, मनमाने, पीड़ादायक प्रायश्चित्त दंड के विपरीत।"},
  {"id":"cdp-child-development-637","question":"Why did Piaget call the younger child’s morality ‘moral realism’?","options":["Because the child thinks realistically about both the consequences and the intentions","Because rules are seen as real, fixed things existing independently of people's purposes","Because the child is very realistic about the chances of actually being caught","Because the child prefers real-life examples to imaginary stories when judging acts"],"answer":1,"explanation":"Rules are treated as objective realities, sacred and unchangeable, with right and wrong read off the letter of the rule and the visible outcome, not intention.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"पियाजे ने छोटे बच्चे की नैतिकता को ‘नैतिक यथार्थवाद’ क्यों कहा?","optionsHi":["क्योंकि बच्चा परिणामों और इरादों दोनों के बारे में यथार्थवादी ढंग से सोचता है","क्योंकि नियमों को वास्तविक, स्थिर वस्तुएँ माना जाता है जो लोगों के प्रयोजनों से स्वतंत्र रूप से विद्यमान हैं","क्योंकि बच्चा वास्तव में पकड़े जाने की संभावना के बारे में बहुत यथार्थवादी होता है","क्योंकि बच्चा कृत्यों को आँकते समय काल्पनिक कहानियों के बजाय वास्तविक जीवन के उदाहरण पसंद करता है"],"explanationHi":"नियमों को वस्तुनिष्ठ यथार्थ, पवित्र और अपरिवर्तनीय माना जाता है, और सही-गलत को इरादे से नहीं बल्कि नियम के अक्षर और दिखाई देने वाले परिणाम से पढ़ा जाता है।"},
  {"id":"cdp-child-development-638","question":"Asked whether Heinz should steal the drug, Anjali (Class 10) says, ‘Maybe he could talk to the druggist again, or borrow the money. If he steals and goes to jail, who will look after his wife?’ How would Carol Gilligan interpret this response?","options":["As a care orientation focused on relationships, no less mature than a justice orientation","As Stage 3 reasoning, showing that Anjali is morally less developed than her peers","As preconventional reasoning, because she avoids taking a clear position on stealing","As evidence that girls cannot really reason about rights and justice in the abstract"],"answer":0,"explanation":"Gilligan argued that such responses, often scored at Kohlberg’s Stage 3, reflect a different voice: an ethic of care that seeks to preserve relationships, not lower maturity.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"यह पूछे जाने पर कि क्या हाइंज़ को दवा चुरानी चाहिए, अंजलि (कक्षा 10) कहती है, ‘शायद वह दवा-विक्रेता से फिर बात कर सकता है, या पैसे उधार ले सकता है। यदि वह चोरी करे और जेल चला जाए, तो उसकी पत्नी की देखभाल कौन करेगा?’ कैरल गिलिगन इस उत्तर की व्याख्या कैसे करतीं?","optionsHi":["संबंधों पर केंद्रित देखभाल-अभिमुखता के रूप में, जो न्याय-अभिमुखता से कम परिपक्व नहीं है","अवस्था 3 के तर्क के रूप में, जो दर्शाता है कि अंजलि अपने साथियों से नैतिक रूप से कम विकसित है","पूर्व-रूढ़िगत तर्क के रूप में, क्योंकि वह चोरी पर स्पष्ट पक्ष लेने से बचती है","इस प्रमाण के रूप में कि लड़कियाँ अधिकारों और न्याय के बारे में अमूर्त रूप से तर्क नहीं कर सकतीं"],"explanationHi":"गिलिगन का तर्क था कि ऐसे उत्तर, जिन्हें प्रायः कोहलबर्ग की अवस्था 3 पर अंकित किया जाता है, एक भिन्न स्वर को दर्शाते हैं: संबंधों को बचाने की देखभाल की नीति, कम परिपक्वता नहीं।"},
  {"id":"cdp-child-development-639","question":"Which of these statements about Gilligan’s critique of Kohlberg are correct? I. Kohlberg’s original study was based on boys. II. His scoring tended to undervalue reasoning based on care, placing many women at Stage 3. III. Gilligan argued that women are morally inferior to men. IV. She proposed an ethic of care centred on relationships and responsibility.","options":["I and IV only","I, II and IV only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"I, II and IV describe her critique. III is the opposite of her claim: she argued the theory made women look less mature because it ignored the care perspective.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कोहलबर्ग की गिलिगन द्वारा आलोचना के बारे में इनमें से कौन-से कथन सही हैं? I. कोहलबर्ग का मूल अध्ययन लड़कों पर आधारित था। II. उनकी अंकन-पद्धति देखभाल पर आधारित तर्क को कम आँकती थी और कई महिलाओं को अवस्था 3 पर रखती थी। III. गिलिगन ने तर्क दिया कि महिलाएँ नैतिक रूप से पुरुषों से हीन हैं। IV. उन्होंने संबंधों और उत्तरदायित्व पर केंद्रित देखभाल की नीति प्रस्तावित की।","optionsHi":["केवल I और IV","केवल I, II और IV","केवल II, III और IV","I, II, III और IV"],"explanationHi":"I, II और IV उनकी आलोचना का वर्णन करते हैं। III उनके दावे का उलटा है: उन्होंने तर्क दिया कि सिद्धांत महिलाओं को कम परिपक्व दिखाता था क्योंकि वह देखभाल के दृष्टिकोण की उपेक्षा करता था।"},
  {"id":"cdp-child-development-640","question":"A woman explains a difficult decision: ‘I must think of my children, but I also have to look after myself; caring for myself is not selfish if it lets me keep caring for them.’ In Gilligan’s sequence this reflects:","options":["Orientation to individual survival","Goodness as self-sacrifice","Kohlberg's Stage 2, since she considers her own needs","Morality of non-violence (care for self and others)"],"answer":3,"explanation":"Gilligan’s highest level balances care for others with care for oneself (no one should be hurt, including the self). Self-sacrifice comes before it, and pure survival concern before that.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक महिला एक कठिन निर्णय समझाती है: ‘मुझे अपने बच्चों के बारे में सोचना है, पर मुझे अपना भी ध्यान रखना है; अपना ध्यान रखना स्वार्थ नहीं है यदि वह मुझे उनकी देखभाल करते रहने देता है।’ गिलिगन के क्रम में यह किसे दर्शाता है?","optionsHi":["व्यक्तिगत उत्तरजीविता की अभिमुखता","आत्म-त्याग के रूप में अच्छाई","कोहलबर्ग की अवस्था 2, क्योंकि वह अपनी आवश्यकताओं पर विचार करती है","अहिंसा की नैतिकता (स्वयं और दूसरों की देखभाल)"],"explanationHi":"गिलिगन का उच्चतम स्तर दूसरों की देखभाल को स्वयं की देखभाल के साथ संतुलित करता है (किसी को चोट नहीं पहुँचनी चाहिए, स्वयं को भी नहीं)। आत्म-त्याग इससे पहले आता है, और केवल उत्तरजीविता की चिंता उससे भी पहले।"},
  {"id":"cdp-child-development-641","question":"A Class 12 girl says, ‘A good daughter always puts the family first; I should drop my plan to study further so that my brother can go to college.’ In Gilligan’s terms she is at the level of:","options":["Goodness as self-sacrifice","Orientation to individual survival","Morality of non-violence","Postconventional justice"],"answer":0,"explanation":"Equating goodness with meeting others’ needs at the cost of one’s own is Gilligan’s second level; the mature level would also count her own needs as legitimate.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"कक्षा 12 की एक लड़की कहती है, ‘अच्छी बेटी हमेशा परिवार को पहले रखती है; मुझे आगे पढ़ने की अपनी योजना छोड़ देनी चाहिए ताकि मेरा भाई कॉलेज जा सके।’ गिलिगन के शब्दों में वह किस स्तर पर है?","optionsHi":["आत्म-त्याग के रूप में अच्छाई","व्यक्तिगत उत्तरजीविता की अभिमुखता","अहिंसा की नैतिकता","उत्तर-रूढ़िगत न्याय"],"explanationHi":"अपनी हानि पर भी दूसरों की आवश्यकताएँ पूरी करने को अच्छाई मानना गिलिगन का दूसरा स्तर है; परिपक्व स्तर में उसकी अपनी आवश्यकताएँ भी वैध गिनी जाएँगी।"},
  {"id":"cdp-child-development-642","question":"Later large reviews of research on Gilligan’s claim about gender and moral orientation found that:","options":["Women use only the care orientation and men use only the justice orientation","Gender differences are small; both sexes use care and justice reasoning","Men consistently score higher than women on Kohlberg's scale in every study","Moral orientation is fixed early by biological sex and cannot later change"],"answer":1,"explanation":"Meta-analyses found only small average differences; both men and women use both orientations, and real-life dilemmas involving relationships draw more care reasoning from everyone.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"लिंग और नैतिक अभिमुखता के बारे में गिलिगन के दावे पर शोध की बाद की बड़ी समीक्षाओं ने पाया कि:","optionsHi":["महिलाएँ केवल देखभाल-अभिमुखता का उपयोग करती हैं और पुरुष केवल न्याय-अभिमुखता का","लैंगिक अंतर छोटे हैं; दोनों लिंग देखभाल और न्याय का तर्क प्रयोग करते हैं","प्रत्येक अध्ययन में पुरुष कोहलबर्ग की मापनी पर महिलाओं से लगातार अधिक अंक पाते हैं","नैतिक अभिमुखता जैविक लिंग द्वारा आरंभ में ही निश्चित हो जाती है और बाद में बदली नहीं जा सकती"],"explanationHi":"मेटा-विश्लेषणों में केवल छोटे औसत अंतर मिले; पुरुष और महिलाएँ दोनों अभिमुखताओं का उपयोग करते हैं, और संबंधों वाली वास्तविक जीवन की दुविधाएँ सभी से अधिक देखभाल-तर्क निकलवाती हैं।"},
  {"id":"cdp-child-development-643","question":"Which pairing correctly contrasts Kohlberg’s and Gilligan’s emphases?","options":["Kohlberg: care and relationships in context; Gilligan: rights, rules and impartial principles","Kohlberg: punishment and reward; Gilligan: justice and the law","Kohlberg: justice and impartial principles; Gilligan: care and relationships in context","Kohlberg: emotions and feelings; Gilligan: cognition and logical reasoning"],"answer":2,"explanation":"Kohlberg’s scale is built on an ethic of justice applied impartially; Gilligan stressed an ethic of care sensitive to relationships and particular situations.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"कोहलबर्ग और गिलिगन के बलों की तुलना कौन-सा युग्मन सही ढंग से करता है?","optionsHi":["कोहलबर्ग: संदर्भ में देखभाल और संबंध; गिलिगन: अधिकार, नियम और निष्पक्ष सिद्धांत","कोहलबर्ग: दंड और पुरस्कार; गिलिगन: न्याय और कानून","कोहलबर्ग: न्याय और निष्पक्ष सिद्धांत; गिलिगन: संदर्भ में देखभाल और संबंध","कोहलबर्ग: संवेग और भावनाएँ; गिलिगन: संज्ञान और तार्किक चिंतन"],"explanationHi":"कोहलबर्ग की मापनी निष्पक्ष रूप से लागू होने वाली न्याय की नीति पर बनी है; गिलिगन ने संबंधों और विशिष्ट परिस्थितियों के प्रति संवेदनशील देखभाल की नीति पर बल दिया।"},
  {"id":"cdp-child-development-644","question":"A teacher designing a value-education unit wants it to reflect both Kohlberg’s and Gilligan’s insights. Which approach fits best?","options":["Use only Heinz-type dilemmas about rules and rights, as these are the standard measure","Present dilemmas of both fairness and care, and value both kinds of reasoning","Teach girls care-based values and boys justice-based values in separate sessions","Grade students by how closely their answers match Kohlberg's Stage 6 principles"],"answer":1,"explanation":"Both orientations are part of mature moral thinking and are used by both sexes; including real-life relational dilemmas and valuing care reasoning avoids the bias Gilligan identified.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"मूल्य-शिक्षा की एक इकाई बना रहा शिक्षक चाहता है कि वह कोहलबर्ग और गिलिगन दोनों की अंतर्दृष्टियों को दर्शाए। कौन-सा उपागम सबसे उपयुक्त है?","optionsHi":["केवल नियमों और अधिकारों वाली हाइंज़-प्रकार की दुविधाओं का उपयोग करना, क्योंकि वे मानक माप हैं","निष्पक्षता और देखभाल दोनों की दुविधाएँ प्रस्तुत करना, और दोनों प्रकार के तर्क को महत्त्व देना","लड़कियों को देखभाल-आधारित और लड़कों को न्याय-आधारित मूल्य अलग-अलग सत्रों में सिखाना","विद्यार्थियों को इस आधार पर अंक देना कि उनके उत्तर कोहलबर्ग की अवस्था 6 के सिद्धांतों से कितने मिलते हैं"],"explanationHi":"दोनों अभिमुखताएँ परिपक्व नैतिक चिंतन का भाग हैं और दोनों लिंगों द्वारा प्रयोग की जाती हैं; संबंध-आधारित वास्तविक जीवन की दुविधाओं को शामिल करना और देखभाल-तर्क को महत्त्व देना गिलिगन द्वारा पहचाने गए पूर्वाग्रह से बचाता है।"},
  {"id":"cdp-child-development-645","question":"Assertion (A): Gilligan argued that Kohlberg’s theory was biased against a care orientation. Reason (R): Kohlberg’s stages were originally derived from interviews with male participants only.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Gilligan traced the bias largely to the all-male sample from which the stages were built, which made justice reasoning the yardstick of maturity.","difficulty":"moderate","source":"CTET Paper 2 · State TET","questionHi":"अभिकथन (A): गिलिगन ने तर्क दिया कि कोहलबर्ग का सिद्धांत देखभाल-अभिमुखता के प्रति पक्षपाती था। कारण (R): कोहलबर्ग की अवस्थाएँ मूलतः केवल पुरुष प्रतिभागियों के साक्षात्कारों से निकाली गई थीं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"गिलिगन ने पक्षपात का मुख्य कारण उस केवल-पुरुष प्रतिदर्श को माना जिससे अवस्थाएँ बनाई गई थीं, जिसने न्याय-तर्क को परिपक्वता का मापदंड बना दिया।"},
  {"id":"cdp-child-development-646","question":"How does Kohlberg’s account of moral development most clearly differ from Piaget’s?","options":["Kohlberg ignored cognition entirely, while Piaget based his account of morality on it","Kohlberg described only two broad stages, while Piaget described six detailed ones","Kohlberg extended a more detailed sequence into adolescence and adulthood","Kohlberg studied only girls, while Piaget based his studies only on boys"],"answer":2,"explanation":"Kohlberg built on Piaget’s cognitive base but proposed three levels and six stages stretching into adulthood; Piaget’s main account covered two moralities in childhood. The second option swaps the numbers.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"नैतिक विकास का कोहलबर्ग का विवरण पियाजे के विवरण से सबसे स्पष्ट रूप से कैसे भिन्न है?","optionsHi":["कोहलबर्ग ने संज्ञान को पूरी तरह अनदेखा किया, जबकि पियाजे ने नैतिकता का अपना विवरण उसी पर आधारित किया","कोहलबर्ग ने केवल दो व्यापक अवस्थाएँ बताईं, जबकि पियाजे ने छह विस्तृत अवस्थाएँ बताईं","कोहलबर्ग ने अधिक विस्तृत क्रम को किशोरावस्था और वयस्कता तक बढ़ाया","कोहलबर्ग ने केवल लड़कियों का अध्ययन किया, जबकि पियाजे ने अपने अध्ययन केवल लड़कों पर आधारित किए"],"explanationHi":"कोहलबर्ग ने पियाजे के संज्ञानात्मक आधार पर निर्माण किया परंतु वयस्कता तक फैले तीन स्तर और छह अवस्थाएँ प्रस्तावित कीं; पियाजे का मुख्य विवरण बाल्यावस्था की दो नैतिकताओं तक था। दूसरा विकल्प संख्याओं की अदला-बदली करता है।"},
  {"id":"cdp-child-development-647","question":"A six-year-old insists that the rules of ludo ‘were made by God and the elders’ and refuses to let friends add a new rule even when all of them agree. A ten-year-old says, ‘If we all agree, we can play it the new way.’ Which statement best explains the difference?","options":["The younger child is in moral realism, viewing rules as sacred; the older sees them as agreements","The older child has no real respect for rules and is still in the premoral stage","Both children are at Kohlberg's Stage 4, as both are concerned with keeping rules","The younger child is more morally developed, since he shows greater respect for authority"],"answer":0,"explanation":"Piaget found younger children treat rules as fixed and from authority, while older children see rules as products of mutual consent that can be altered. Changing rules by agreement is not disrespect.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक छह वर्ष का बच्चा आग्रह करता है कि लूडो के नियम ‘भगवान और बड़ों ने बनाए थे’ और वह सभी के सहमत होने पर भी मित्रों को नया नियम जोड़ने नहीं देता। एक दस वर्ष का बच्चा कहता है, ‘यदि हम सब सहमत हों, तो हम इसे नए तरीके से खेल सकते हैं।’ अंतर को कौन-सा कथन सबसे अच्छी तरह समझाता है?","optionsHi":["छोटा बच्चा नैतिक यथार्थवाद में है और नियमों को पवित्र मानता है; बड़ा उन्हें समझौते मानता है","बड़े बच्चे में नियमों के प्रति कोई वास्तविक सम्मान नहीं है और वह अब भी पूर्व-नैतिक अवस्था में है","दोनों बच्चे कोहलबर्ग की अवस्था 4 पर हैं, क्योंकि दोनों नियमों के पालन को लेकर चिंतित हैं","छोटा बच्चा नैतिक रूप से अधिक विकसित है, क्योंकि वह सत्ता के प्रति अधिक सम्मान दिखाता है"],"explanationHi":"पियाजे ने पाया कि छोटे बच्चे नियमों को स्थिर और सत्ता से आए हुए मानते हैं, जबकि बड़े बच्चे उन्हें आपसी सहमति की उपज मानते हैं जो बदली जा सकती है। समझौते से नियम बदलना अनादर नहीं है।"},
  {"id":"cdp-child-development-648","question":"Gilligan described a transition ‘from selfishness to responsibility’. Which pair of levels does this transition link?","options":["Goodness as self-sacrifice to morality of non-violence","Orientation to individual survival to goodness as self-sacrifice","Morality of non-violence back to goodness as self-sacrifice","Kohlberg's preconventional level to his postconventional level"],"answer":1,"explanation":"The first transition moves from concern only for oneself (survival) to responsibility for others (self-sacrifice); the second, ‘from goodness to truth’, leads on to care for both self and others.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"गिलिगन ने ‘स्वार्थ से उत्तरदायित्व की ओर’ एक संक्रमण का वर्णन किया। यह संक्रमण स्तरों के किस युग्म को जोड़ता है?","optionsHi":["आत्म-त्याग के रूप में अच्छाई से अहिंसा की नैतिकता तक","व्यक्तिगत उत्तरजीविता की अभिमुखता से आत्म-त्याग के रूप में अच्छाई तक","अहिंसा की नैतिकता से वापस आत्म-त्याग के रूप में अच्छाई तक","कोहलबर्ग के पूर्व-रूढ़िगत स्तर से उसके उत्तर-रूढ़िगत स्तर तक"],"explanationHi":"पहला संक्रमण केवल स्वयं की चिंता (उत्तरजीविता) से दूसरों के प्रति उत्तरदायित्व (आत्म-त्याग) की ओर जाता है; दूसरा, ‘अच्छाई से सत्य की ओर’, स्वयं और दूसरों दोनों की देखभाल तक ले जाता है।"},
  {"id":"cdp-child-development-649","question":"Which of these correctly matches Piaget’s moral ideas with ages? P. Judging by consequences. Q. Judging by intentions. R. Belief in immanent justice. S. Reciprocal punishment.","options":["P and R: older children; Q and S: younger children","P and S: younger children; Q and R: older children","P, Q, R and S: all typical of children under seven","P and R: younger children; Q and S: older children"],"answer":3,"explanation":"Consequence-based judgment and immanent justice mark the younger, heteronomous child; intention-based judgment and reciprocal punishment mark the older, autonomous child.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"इनमें से कौन-सा पियाजे के नैतिक विचारों का आयु से सही मिलान करता है? P. परिणामों से आँकना। Q. इरादों से आँकना। R. अंतर्निहित न्याय में विश्वास। S. पारस्परिक दंड।","optionsHi":["P और R: बड़े बच्चे; Q और S: छोटे बच्चे","P और S: छोटे बच्चे; Q और R: बड़े बच्चे","P, Q, R और S: सभी सात वर्ष से छोटे बच्चों के लिए विशिष्ट","P और R: छोटे बच्चे; Q और S: बड़े बच्चे"],"explanationHi":"परिणाम-आधारित निर्णय और अंतर्निहित न्याय छोटे, परतंत्र बच्चे के चिह्न हैं; इरादे-आधारित निर्णय और पारस्परिक दंड बड़े, स्वायत्त बच्चे के चिह्न हैं।"},
  {"id":"cdp-child-development-650","question":"A Class 3 child says it is fine to hit a classmate ‘if Ma’am is not looking’, but in a later discussion argues that hitting is wrong ‘because the rule says so, and rules can never be broken’. Which statement is consistent with both Piaget and Kohlberg?","options":["Rule-bound, authority-based thinking is typical at this age and matures with cognition and experience","The child has reached autonomous morality, because he can clearly state the rule involved","The child is at Kohlberg's postconventional level, because he refers to rules and principles","Moral reasoning in children develops separately from, and is unrelated to, their cognitive development"],"answer":0,"explanation":"Both theorists see young children’s morality as authority- and consequence-oriented, with change driven by cognition and interaction; quoting a rule is not autonomy or principled thought.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 का एक बच्चा कहता है कि सहपाठी को मारना ठीक है ‘यदि मैडम नहीं देख रहीं’, पर बाद की चर्चा में तर्क देता है कि मारना गलत है ‘क्योंकि नियम ऐसा कहता है, और नियम कभी तोड़े नहीं जा सकते’। पियाजे और कोहलबर्ग दोनों से कौन-सा कथन संगत है?","optionsHi":["नियम-बद्ध, सत्ता-आधारित चिंतन इस आयु में विशिष्ट है और संज्ञान तथा अनुभव के साथ परिपक्व होता है","बच्चा स्वायत्त नैतिकता तक पहुँच गया है, क्योंकि वह संबंधित नियम को स्पष्ट रूप से बता सकता है","बच्चा कोहलबर्ग के उत्तर-रूढ़िगत स्तर पर है, क्योंकि वह नियमों और सिद्धांतों का संदर्भ देता है","बच्चों में नैतिक चिंतन उनके संज्ञानात्मक विकास से अलग विकसित होता है और उससे असंबद्ध है"],"explanationHi":"दोनों सिद्धांतकार छोटे बच्चों की नैतिकता को सत्ता- और परिणाम-उन्मुख मानते हैं, जिसमें परिवर्तन संज्ञान और अंतःक्रिया से चलता है; नियम उद्धृत करना स्वायत्तता या सिद्धांतनिष्ठ चिंतन नहीं है।"},
  {"id":"cdp-child-development-651","question":"Which of the following are among the specified disabilities listed in the Rights of Persons with Disabilities Act, 2016? I. Acid attack victims II. Thalassemia III. Dwarfism IV. Attention Deficit Hyperactivity Disorder","options":["I and II only","I, II and III only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"The Act's 21 specified disabilities include acid attack victims, thalassemia and dwarfism; ADHD is not named as a separate category in the list.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"दिव्यांगजन अधिकार अधिनियम, 2016 में सूचीबद्ध निर्दिष्ट दिव्यांगताओं में से निम्नलिखित में कौन-सी हैं? I. तेज़ाब हमले के पीड़ित II. थैलेसीमिया III. बौनापन IV. अवधान न्यूनता अतिसक्रियता विकार (ADHD)","optionsHi":["केवल I और II","केवल I, II और III","केवल II, III और IV","I, II, III और IV"],"explanationHi":"अधिनियम की 21 निर्दिष्ट दिव्यांगताओं में तेज़ाब हमले के पीड़ित, थैलेसीमिया और बौनापन शामिल हैं; ADHD सूची में अलग श्रेणी के रूप में नामित नहीं है।"},
  {"id":"cdp-child-development-652","question":"When the RPwD Act, 2016 replaced the Persons with Disabilities Act, 1995, which change did it bring that most affects schools?","options":["It reduced the number of recognised disabilities, to make certification simpler and faster for families","It made special schools compulsory for all children with disabilities, so that experts meet their needs","It widened the list from 7 to 21 disabilities, adding conditions such as autism and specific learning disabilities","It removed all disability-related duties of schools and passed them entirely to the health department"],"answer":2,"explanation":"The 2016 Act widened the list from seven to twenty-one disabilities, so teachers must now recognise and support children with conditions like autism and specific learning disabilities.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"जब RPwD अधिनियम, 2016 ने दिव्यांगजन अधिनियम, 1995 का स्थान लिया, तो इसने कौन-सा परिवर्तन किया जो विद्यालयों को सबसे अधिक प्रभावित करता है?","optionsHi":["इसने मान्य दिव्यांगताओं की संख्या घटा दी, ताकि परिवारों के लिए प्रमाणन सरल और तेज़ हो","इसने सभी दिव्यांग बच्चों के लिए विशेष विद्यालय अनिवार्य कर दिए, ताकि विशेषज्ञ उनकी आवश्यकताएँ पूरी करें","इसने सूची को 7 से बढ़ाकर 21 दिव्यांगताएँ कर दीं, जिनमें ऑटिज़्म और विशिष्ट अधिगम अक्षमताएँ जैसी स्थितियाँ जुड़ीं","इसने विद्यालयों के सभी दिव्यांगता-संबंधी कर्तव्य हटाकर पूरी तरह स्वास्थ्य विभाग को सौंप दिए"],"explanationHi":"2016 के अधिनियम ने सूची को सात से बढ़ाकर इक्कीस दिव्यांगताएँ कर दीं, इसलिए शिक्षकों को अब ऑटिज़्म और विशिष्ट अधिगम अक्षमताओं जैसी स्थितियों वाले बच्चों को पहचानना और सहयोग देना होगा।"},
  {"id":"cdp-child-development-653","question":"A Class 6 student with low vision is given a seat near the board, large-print worksheets and permission to photograph the board on a tablet. The principal calls these ‘special favours that are unfair to other students’. Which response is correct?","options":["These are reasonable accommodations: necessary adjustments that let her participate equally, not favours","The principal is right; fairness means every student must be treated in exactly the same way","The adjustments are permitted only if her certified disability is assessed at above 80 per cent","The adjustments are favours, and should be given only during examinations, not in daily lessons"],"answer":0,"explanation":"The RPwD Act defines reasonable accommodation as necessary and appropriate adjustment, without disproportionate or undue burden, to ensure rights equally with others; denying it is itself a form of discrimination.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 6 की अल्प-दृष्टि वाली एक विद्यार्थी को श्यामपट्ट के पास सीट, बड़े अक्षरों में छपे कार्य-पत्रक और टैबलेट पर श्यामपट्ट का चित्र लेने की अनुमति दी जाती है। प्रधानाचार्य इन्हें ‘विशेष कृपाएँ जो अन्य विद्यार्थियों के प्रति अनुचित हैं’ कहते हैं। कौन-सी प्रतिक्रिया सही है?","optionsHi":["ये उचित समायोजन हैं: आवश्यक संशोधन जो उसे बराबरी से भाग लेने देते हैं, कृपाएँ नहीं","प्रधानाचार्य सही हैं; निष्पक्षता का अर्थ है कि हर विद्यार्थी के साथ बिल्कुल एक जैसा व्यवहार हो","ये संशोधन तभी अनुमत हैं जब उसकी प्रमाणित दिव्यांगता 80 प्रतिशत से अधिक आँकी जाए","ये कृपाएँ हैं, और केवल परीक्षाओं के दौरान दी जानी चाहिए, दैनिक पाठों में नहीं"],"explanationHi":"RPwD अधिनियम उचित समायोजन को आवश्यक और उपयुक्त संशोधन के रूप में परिभाषित करता है, जो अनुपातहीन या अनुचित बोझ के बिना, दूसरों के बराबर अधिकार सुनिश्चित करे; इसे अस्वीकार करना स्वयं एक प्रकार का भेदभाव है।"},
  {"id":"cdp-child-development-654","question":"Under the RPwD Act, 2016, which of the following is NOT a duty of educational institutions funded or recognised by the government?","options":["Admitting children with disabilities without discrimination in any of its classes","Making buildings, campuses and facilities accessible to all children with disabilities","Detecting specific learning disabilities in children at the earliest and taking suitable steps","Placing children with disabilities in separate sections so that others' pace is not affected"],"answer":3,"explanation":"The Act requires non-discriminatory admission, accessibility, early detection of specific learning disabilities and individualised support towards full inclusion; separate sections would be segregation.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"RPwD अधिनियम, 2016 के अंतर्गत, सरकार द्वारा वित्तपोषित या मान्यता प्राप्त शिक्षण संस्थाओं का निम्नलिखित में से कौन-सा कर्तव्य नहीं है?","optionsHi":["दिव्यांग बच्चों को अपनी किसी भी कक्षा में बिना भेदभाव के प्रवेश देना","भवनों, परिसरों और सुविधाओं को सभी दिव्यांग बच्चों के लिए सुगम बनाना","विशिष्ट अधिगम अक्षमताओं का बच्चों में शीघ्रतम पता लगाना और उचित कदम उठाना","दिव्यांग बच्चों को अलग अनुभागों में रखना ताकि दूसरों की गति प्रभावित न हो"],"explanationHi":"अधिनियम भेदभाव-रहित प्रवेश, सुगम्यता, विशिष्ट अधिगम अक्षमताओं की शीघ्र पहचान और पूर्ण समावेशन की ओर वैयक्तिकृत सहयोग की माँग करता है; अलग अनुभाग अलगाव होंगे।"},
  {"id":"cdp-child-development-655","question":"Zoya, in Class 5, has cerebral palsy, uses a wheelchair and has unclear speech. Her new teacher assumes she cannot follow Class 5 work and gives her Class 2 worksheets. What is wrong with this decision?","options":["Nothing; children with cerebral palsy nearly always have an intellectual disability as well","CP mainly affects movement and posture; her understanding must first be assessed by accessible means","The teacher should have started with Class 1 worksheets, to be sure that she meets success first","Children with cerebral palsy are better placed in special schools, where such worksheets are designed"],"answer":1,"explanation":"Unclear speech and motor difficulty are not evidence of low intelligence; many children with cerebral palsy have typical cognition, so the teacher must find an accessible way for her to show what she knows.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 5 की ज़ोया को प्रमस्तिष्कीय पक्षाघात (सेरेब्रल पाल्सी) है, वह व्हीलचेयर का उपयोग करती है और उसकी वाणी अस्पष्ट है। उसकी नई शिक्षिका मान लेती है कि वह कक्षा 5 का कार्य नहीं समझ सकती और उसे कक्षा 2 के कार्य-पत्रक देती है। इस निर्णय में क्या गलत है?","optionsHi":["कुछ नहीं; प्रमस्तिष्कीय पक्षाघात वाले बच्चों में लगभग हमेशा बौद्धिक अक्षमता भी होती है","CP मुख्यतः गति और मुद्रा को प्रभावित करता है; उसकी समझ का आकलन पहले सुगम साधनों से किया जाना चाहिए","शिक्षिका को कक्षा 1 के कार्य-पत्रकों से शुरू करना चाहिए था, ताकि वह पहले सफलता पाए","प्रमस्तिष्कीय पक्षाघात वाले बच्चे विशेष विद्यालयों में बेहतर स्थित हैं, जहाँ ऐसे कार्य-पत्रक बनाए जाते हैं"],"explanationHi":"अस्पष्ट वाणी और गामक कठिनाई निम्न बुद्धि का प्रमाण नहीं हैं; प्रमस्तिष्कीय पक्षाघात वाले कई बच्चों में संज्ञान सामान्य होता है, इसलिए शिक्षिका को उसके लिए यह दिखाने का सुगम तरीका खोजना चाहिए कि वह क्या जानती है।"},
  {"id":"cdp-child-development-656","question":"Dinesh, in Class 4, learns slowly but steadily in every subject, is somewhat below average all round, and his measured IQ is in the 70–85 range. He does not show a sharp gap between one skill and the rest. He is best described as:","options":["A child with a specific learning disability","A child with intellectual disability","A slow learner","A gifted underachiever"],"answer":2,"explanation":"A general, even slowness with borderline ability fits a slow learner; a specific learning disability involves an unexpected weakness in one area, and intellectual disability needs significant limits in both intelligence and adaptive behaviour.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 4 का दिनेश प्रत्येक विषय में धीरे पर लगातार सीखता है, सभी में औसत से कुछ नीचे है, और उसका मापा गया IQ 70–85 के बीच है। उसमें किसी एक कौशल और शेष के बीच तीक्ष्ण अंतर नहीं दिखता। उसका सबसे अच्छा वर्णन है:","optionsHi":["विशिष्ट अधिगम अक्षमता वाला बच्चा","बौद्धिक अक्षमता वाला बच्चा","मंद अधिगमकर्ता (स्लो लर्नर)","प्रतिभाशाली कम-उपलब्धि वाला बच्चा"],"explanationHi":"सीमांत क्षमता के साथ सामान्य, एकसमान धीमापन मंद अधिगमकर्ता के अनुरूप है; विशिष्ट अधिगम अक्षमता में किसी एक क्षेत्र में अप्रत्याशित कमज़ोरी होती है, और बौद्धिक अक्षमता के लिए बुद्धि और अनुकूली व्यवहार दोनों में उल्लेखनीय सीमाएँ चाहिए।"},
  {"id":"cdp-child-development-657","question":"Which of these statements about gifted underachievers are correct? I. Underachievement can result from classwork that is too easy and repetitive. II. A hidden learning disability may mask a child’s high ability. III. Underachievement proves that the child was never really gifted.","options":["I only","I and III only","II and III only","I and II only"],"answer":3,"explanation":"Boredom, unchallenging work and a masking disability are common causes of underachievement; a gap between potential and performance does not cancel the potential.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"प्रतिभाशाली कम-उपलब्धि वाले बच्चों के बारे में इनमें से कौन-से कथन सही हैं? I. कम-उपलब्धि बहुत आसान और दोहराव वाले कक्षा-कार्य से हो सकती है। II. कोई छिपी अधिगम अक्षमता बच्चे की उच्च क्षमता को ढक सकती है। III. कम-उपलब्धि सिद्ध करती है कि बच्चा वास्तव में कभी प्रतिभाशाली नहीं था।","optionsHi":["केवल I","केवल I और III","केवल II और III","केवल I और II"],"explanationHi":"ऊब, चुनौतीहीन कार्य और ढकने वाली अक्षमता कम-उपलब्धि के सामान्य कारण हैं; क्षमता और निष्पादन के बीच का अंतर क्षमता को रद्द नहीं करता।"},
  {"id":"cdp-child-development-658","question":"While teaching photosynthesis, a Class 7 teacher gives all students the same key concept but three versions of the follow-up task: one with labelled diagrams to complete, one with guided questions, and one asking them to design an experiment. This strategy is called:","options":["Tracking","A tiered assignment","Curriculum compacting","Peer tutoring"],"answer":1,"explanation":"Tiered assignments keep the same core concept while varying complexity to match readiness; tracking places children permanently in ability streams, and compacting removes already-mastered content.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"प्रकाश-संश्लेषण पढ़ाते समय कक्षा 7 की शिक्षिका सभी विद्यार्थियों को वही मुख्य संप्रत्यय देती है परंतु अनुवर्ती कार्य के तीन संस्करण: एक जिसमें नामांकित आरेख पूरे करने हैं, एक निर्देशित प्रश्नों वाला, और एक जिसमें प्रयोग की रूपरेखा बनानी है। इस युक्ति को क्या कहते हैं?","optionsHi":["ट्रैकिंग (स्ट्रीमिंग)","श्रेणीबद्ध कार्य-निर्धारण (टायर्ड असाइनमेंट)","पाठ्यचर्या संघनन (कम्पैक्टिंग)","सहपाठी शिक्षण"],"explanationHi":"श्रेणीबद्ध कार्य-निर्धारण में मूल संप्रत्यय वही रहता है पर तत्परता के अनुसार जटिलता बदलती है; ट्रैकिंग बच्चों को स्थायी रूप से क्षमता-धाराओं में रखती है, और संघनन पहले से सीखी सामग्री को हटा देता है।"},
  {"id":"cdp-child-development-659","question":"A pre-test shows that Ananya, in Class 5, already knows about 90% of the coming unit on decimals. Her teacher lets her skip the parts she has mastered and use the saved time for an independent project on the use of decimals in sports. This is an example of:","options":["Curriculum compacting","Grade skipping (acceleration)","Ability tracking into streams","Remedial teaching of gaps"],"answer":0,"explanation":"Curriculum compacting tests what a learner already knows, drops the mastered content and replaces it with more challenging work, without moving her to a higher class.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक पूर्व-परीक्षण दिखाता है कि कक्षा 5 की अनन्या दशमलव की आने वाली इकाई का लगभग 90% पहले से जानती है। उसकी शिक्षिका उसे वे भाग छोड़ने देती है जिनमें वह निपुण है और बचे समय का उपयोग खेलों में दशमलव के प्रयोग पर एक स्वतंत्र परियोजना के लिए करने देती है। यह किसका उदाहरण है?","optionsHi":["पाठ्यचर्या संघनन (कम्पैक्टिंग)","कक्षा छोड़ना (त्वरण)","क्षमता के आधार पर धाराओं में बाँटना (ट्रैकिंग)","कमियों का उपचारात्मक शिक्षण"],"explanationHi":"पाठ्यचर्या संघनन परखता है कि अधिगमकर्ता पहले से क्या जानता है, निपुण की गई सामग्री हटा देता है और उसे अधिक चुनौतीपूर्ण कार्य से बदल देता है, उसे उच्च कक्षा में भेजे बिना।"},
  {"id":"cdp-child-development-660","question":"For a unit on ratios, a Class 6 teacher lets students choose to work with cricket scores, recipe quantities or rangoli patterns, while all of them learn the same ratio concept. She is differentiating mainly on the basis of:","options":["Readiness","Interest","Age","Learning disability status"],"answer":1,"explanation":"Letting students choose the context they care about is differentiation by interest; the concept and its level stay the same, so it is not based on readiness.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"अनुपात की एक इकाई के लिए कक्षा 6 की शिक्षिका विद्यार्थियों को क्रिकेट के स्कोर, व्यंजन की मात्राएँ या रंगोली के प्रतिरूपों में से चुनकर काम करने देती है, जबकि सभी वही अनुपात संप्रत्यय सीखते हैं। वह मुख्यतः किस आधार पर विभेदन कर रही है?","optionsHi":["तत्परता","रुचि","आयु","अधिगम अक्षमता की स्थिति"],"explanationHi":"विद्यार्थियों को वह संदर्भ चुनने देना जिसकी उन्हें परवाह है, रुचि के आधार पर विभेदन है; संप्रत्यय और उसका स्तर वही रहता है, इसलिए यह तत्परता पर आधारित नहीं है।"},
  {"id":"cdp-child-development-661","question":"To keep her Class 8 students motivated, a teacher offers a choice of project topics linked to local life, helps each student set a personal goal and lets them check their own progress against it. Which UDL principle does this mainly reflect?","options":["Multiple means of engagement","Multiple means of representation","Multiple means of action and expression","The theory of multiple intelligences"],"answer":0,"explanation":"Choice, relevance, goal-setting and self-monitoring sustain interest and effort, which is the engagement (‘why’) principle of UDL; representation concerns presenting content, and action-expression concerns showing learning.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"अपने कक्षा 8 के विद्यार्थियों को प्रेरित रखने के लिए एक शिक्षिका स्थानीय जीवन से जुड़े परियोजना-विषयों का विकल्प देती है, प्रत्येक विद्यार्थी को एक व्यक्तिगत लक्ष्य तय करने में सहायता करती है और उन्हें उसके विरुद्ध अपनी प्रगति स्वयं जाँचने देती है। यह मुख्यतः UDL के किस सिद्धांत को दर्शाता है?","optionsHi":["अभिसंलग्नता के बहुविध साधन","निरूपण के बहुविध साधन","क्रिया और अभिव्यक्ति के बहुविध साधन","बहुबुद्धि का सिद्धांत"],"explanationHi":"विकल्प, प्रासंगिकता, लक्ष्य-निर्धारण और स्व-निगरानी रुचि और प्रयास को बनाए रखते हैं, जो UDL का अभिसंलग्नता (‘क्यों’) सिद्धांत है; निरूपण सामग्री प्रस्तुत करने से संबंधित है, और क्रिया-अभिव्यक्ति अधिगम दिखाने से।"},
  {"id":"cdp-child-development-662","question":"Match the UDL principle with the aspect of learning it addresses. 1. Engagement 2. Representation 3. Action and expression; a. The ‘what’: how learners perceive and understand information b. The ‘how’: how learners plan and show what they know c. The ‘why’: learners’ interest, effort and self-regulation","options":["1-a, 2-b, 3-c","1-b, 2-a, 3-c","1-c, 2-b, 3-a","1-c, 2-a, 3-b"],"answer":3,"explanation":"Engagement is the why, representation the what, and action and expression the how of learning.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"UDL के सिद्धांत का मिलान उस अधिगम-पक्ष से कीजिए जिसे वह संबोधित करता है। 1. अभिसंलग्नता 2. निरूपण 3. क्रिया और अभिव्यक्ति; a. ‘क्या’: अधिगमकर्ता जानकारी को कैसे ग्रहण करते और समझते हैं b. ‘कैसे’: अधिगमकर्ता योजना कैसे बनाते हैं और जो जानते हैं उसे कैसे दिखाते हैं c. ‘क्यों’: अधिगमकर्ताओं की रुचि, प्रयास और स्व-नियमन","optionsHi":["1-a, 2-b, 3-c","1-b, 2-a, 3-c","1-c, 2-b, 3-a","1-c, 2-a, 3-b"],"explanationHi":"अभिसंलग्नता अधिगम का ‘क्यों’ है, निरूपण ‘क्या’ है, और क्रिया तथा अभिव्यक्ति ‘कैसे’ है।"},
  {"id":"cdp-child-development-663","question":"Assertion (A): Subtitles added to a classroom video for a deaf student also help many hearing students, such as those learning the language of instruction. Reason (R): Supports designed for accessibility often benefit a wide range of learners, which is a central idea of universal design.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Like a pavement ramp that helps wheelchair users and people with luggage alike, accessibility features such as subtitles benefit many learners, which explains A.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"अभिकथन (A): किसी बधिर विद्यार्थी के लिए कक्षा के वीडियो में जोड़े गए उपशीर्षक अनेक सुनने वाले विद्यार्थियों, जैसे शिक्षण-भाषा सीख रहे विद्यार्थियों, की भी सहायता करते हैं। कारण (R): सुगम्यता के लिए बनाए गए सहारे प्रायः अधिगमकर्ताओं की एक विस्तृत श्रेणी को लाभ पहुँचाते हैं, जो सार्वभौमिक अभिकल्प का एक केंद्रीय विचार है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"फुटपाथ की उस ढलान की तरह जो व्हीलचेयर वालों और सामान वाले लोगों दोनों की सहायता करती है, उपशीर्षक जैसी सुगम्यता सुविधाएँ अनेक अधिगमकर्ताओं को लाभ पहुँचाती हैं, जो A की व्याख्या करता है।"},
  {"id":"cdp-child-development-664","question":"During a lesson on occupations, a Class 3 child declares, ‘Girls can’t become pilots.’ What is the most appropriate teacher response?","options":["Ignoring the remark, since children will learn the truth on their own as they grow up","Scolding the child in front of the class, so that no one repeats such a rude remark","Showing real women pilots and asking the class where such ideas come from","Telling the girls in the class to choose jobs that are more suited to them instead"],"answer":2,"explanation":"Stereotypes are best challenged with counter-examples and discussion that helps children examine their beliefs; silence lets the idea stand, and scolding shuts down thinking.","difficulty":"moderate","source":"CTET · KVS · DSSSB","questionHi":"व्यवसायों पर एक पाठ के दौरान कक्षा 3 का एक बच्चा घोषित करता है, ‘लड़कियाँ पायलट नहीं बन सकतीं।’ शिक्षक की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["टिप्पणी को अनदेखा करना, क्योंकि बच्चे बड़े होने पर सच्चाई स्वयं सीख लेंगे","बच्चे को कक्षा के सामने डाँटना, ताकि कोई ऐसी अशिष्ट टिप्पणी न दोहराए","वास्तविक महिला पायलटों को दिखाना और कक्षा से पूछना कि ऐसे विचार कहाँ से आते हैं","कक्षा की लड़कियों से कहना कि वे इसके बजाय अपने लिए अधिक उपयुक्त नौकरियाँ चुनें"],"explanationHi":"रूढ़िबद्ध धारणाओं को सबसे अच्छी तरह प्रति-उदाहरणों और ऐसी चर्चा से चुनौती दी जाती है जो बच्चों को अपनी मान्यताओं की जाँच करने में सहायता करे; चुप्पी विचार को टिके रहने देती है, और डाँट चिंतन को बंद कर देती है।"},
  {"id":"cdp-child-development-665","question":"Classmates keep calling a Class 5 boy by a term linked to his family’s caste-based occupation. He has started avoiding school. What should the teacher do?","options":["Advise the boy to ignore the teasing, since bullies lose interest when they get no reaction","Move the boy quietly to another section, so that he is protected from the same group","Wait for the boy's parents to complain formally before taking any action on the matter","Stop it at once, make clear caste-based name-calling is unacceptable, and follow up with the class"],"answer":3,"explanation":"Caste-based humiliation is discrimination the school must actively stop; asking the victim to ignore it or moving him places the burden on the child who is harmed.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"सहपाठी कक्षा 5 के एक लड़के को उसके परिवार के जाति-आधारित व्यवसाय से जुड़े शब्द से पुकारते रहते हैं। उसने विद्यालय आने से बचना शुरू कर दिया है। शिक्षक को क्या करना चाहिए?","optionsHi":["लड़के को चिढ़ाने की उपेक्षा करने की सलाह देना, क्योंकि प्रतिक्रिया न मिलने पर धौंस जमाने वाले रुचि खो देते हैं","लड़के को चुपचाप किसी दूसरे अनुभाग में भेज देना, ताकि वह उसी समूह से बचा रहे","इस मामले में कोई कार्रवाई करने से पहले लड़के के माता-पिता के औपचारिक शिकायत करने की प्रतीक्षा करना","इसे तुरंत रोकना, स्पष्ट करना कि जाति-आधारित नाम पुकारना अस्वीकार्य है, और कक्षा के साथ अनुवर्ती कार्रवाई करना"],"explanationHi":"जाति-आधारित अपमान भेदभाव है जिसे विद्यालय को सक्रिय रूप से रोकना चाहिए; पीड़ित से इसे अनदेखा करने को कहना या उसे हटा देना बोझ उसी बच्चे पर डालता है जिसे हानि पहुँची है।"},
  {"id":"cdp-child-development-666","question":"In a Class 5 reading test, children from affluent families do much better than others on a passage about checking in at an airport, though the two groups do equally well on other passages. What is the most reasonable interpretation?","options":["Affluent children are generally more intelligent, and this passage simply revealed it","Children from poorer homes did not try their best on that particular passage","The passage drew on experiences familiar only to some children, so it is culturally biased","Reading comprehension tests are always free of bias, so the gap must reflect real ability"],"answer":2,"explanation":"Background knowledge strongly affects comprehension; when one passage alone shows a gap, its content, not the children's ability, is the likely cause.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 5 के पठन परीक्षण में संपन्न परिवारों के बच्चे हवाई अड्डे पर चेक-इन के बारे में एक गद्यांश पर दूसरों से बहुत बेहतर करते हैं, जबकि दोनों समूह अन्य गद्यांशों पर समान रूप से अच्छा करते हैं। सबसे उचित व्याख्या क्या है?","optionsHi":["संपन्न बच्चे सामान्यतः अधिक बुद्धिमान होते हैं, और इस गद्यांश ने बस यह प्रकट कर दिया","गरीब घरों के बच्चों ने उसी विशेष गद्यांश पर अपना सर्वश्रेष्ठ प्रयास नहीं किया","गद्यांश ऐसे अनुभवों पर आधारित था जो केवल कुछ बच्चों से परिचित हैं, इसलिए वह सांस्कृतिक रूप से पक्षपाती है","पठन-बोध परीक्षण सदैव पक्षपात से मुक्त होते हैं, इसलिए यह अंतर वास्तविक क्षमता को दर्शाता होगा"],"explanationHi":"पृष्ठभूमि का ज्ञान बोध को गहराई से प्रभावित करता है; जब केवल एक गद्यांश पर अंतर दिखे, तो संभावित कारण उसकी विषय-वस्तु है, बच्चों की क्षमता नहीं।"},
  {"id":"cdp-child-development-667","question":"Which teacher approach reflects an asset-based (rather than deficit-based) view of a Class 4 child from a fishing community?","options":["Using his knowledge of tides, boats and weighing the catch as a base for measurement lessons","Assuming he needs remedial work, since his home has few books and little print exposure","Advising his parents to stop involving him in family work so that he can focus on studies","Placing him with the weaker readers because of his background, to give him extra support"],"answer":0,"explanation":"An asset view treats the knowledge children bring from home as a resource for learning; a deficit view sees only what the home lacks and lowers expectations.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"मछुआरा समुदाय के कक्षा 4 के किसी बच्चे के प्रति शिक्षक का कौन-सा उपागम संपदा-आधारित (न कि अभाव-आधारित) दृष्टिकोण को दर्शाता है?","optionsHi":["उसके ज्वार-भाटे, नावों और पकड़ी मछलियों को तौलने के ज्ञान को मापन के पाठों का आधार बनाना","यह मान लेना कि उसे उपचारात्मक कार्य की आवश्यकता है, क्योंकि उसके घर में कम किताबें हैं और मुद्रित सामग्री से कम संपर्क है","उसके माता-पिता को सलाह देना कि उसे पारिवारिक कार्य में न लगाएँ ताकि वह पढ़ाई पर ध्यान दे सके","उसकी पृष्ठभूमि के कारण उसे कमज़ोर पाठकों के साथ रखना, ताकि उसे अतिरिक्त सहायता मिले"],"explanationHi":"संपदा-दृष्टि उस ज्ञान को, जो बच्चे घर से लाते हैं, अधिगम के संसाधन के रूप में देखती है; अभाव-दृष्टि केवल वही देखती है जो घर में नहीं है और अपेक्षाएँ घटा देती है।"},
  {"id":"cdp-child-development-668","question":"Assertion (A): Allowing Class 6 students in Bengaluru to discuss science in Kannada, Tamil or Urdu before writing answers in English will slow their learning of both English and science. Reason (R): Children can think and learn in only one language at a time.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","Both A and R are false"],"answer":3,"explanation":"Multilingual children draw on all their languages to build understanding, and talking in a familiar language deepens concepts that can then be expressed in English; both statements are false.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अभिकथन (A): बेंगलुरु में कक्षा 6 के विद्यार्थियों को अंग्रेज़ी में उत्तर लिखने से पहले कन्नड़, तमिल या उर्दू में विज्ञान पर चर्चा करने देने से अंग्रेज़ी और विज्ञान दोनों का उनका सीखना धीमा होगा। कारण (R): बच्चे एक समय में केवल एक ही भाषा में सोच और सीख सकते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A और R दोनों असत्य हैं"],"explanationHi":"बहुभाषी बच्चे समझ बनाने के लिए अपनी सभी भाषाओं का उपयोग करते हैं, और परिचित भाषा में बात करना उन संप्रत्ययों को गहरा करता है जिन्हें फिर अंग्रेज़ी में व्यक्त किया जा सकता है; दोनों कथन असत्य हैं।"},
  {"id":"cdp-child-development-669","question":"A head teacher argues that children from Gondi-speaking homes should be taught only in Hindi from the first day, since ‘early immersion is the fastest route’. Which counter-argument is best supported by NEP 2020 and research on multilingual learners?","options":["Children should not be taught Hindi at all until Class 8, so that their Gondi is fully protected first","Where possible, the home language should be the medium till at least Class 5, as a base for the second","Immersion is right, provided children are firmly discouraged from using any Gondi in the classroom","The medium of instruction makes no real difference to learning, so either choice is fine"],"answer":1,"explanation":"NEP 2020 recommends the home language or mother tongue as the medium wherever possible until at least Grade 5, preferably Grade 8, while other languages are still taught; it does not ban Hindi.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"एक प्रधानाध्यापक तर्क देता है कि गोंडी-भाषी घरों के बच्चों को पहले दिन से ही केवल हिंदी में पढ़ाया जाना चाहिए, क्योंकि ‘शीघ्र निमज्जन सबसे तेज़ मार्ग है’। NEP 2020 और बहुभाषी अधिगमकर्ताओं पर शोध द्वारा कौन-सा प्रत्युत्तर सबसे अच्छी तरह समर्थित है?","optionsHi":["बच्चों को कक्षा 8 तक हिंदी बिल्कुल नहीं पढ़ानी चाहिए, ताकि पहले उनकी गोंडी पूरी तरह सुरक्षित रहे","जहाँ संभव हो, घर की भाषा कम से कम कक्षा 5 तक माध्यम होनी चाहिए, दूसरी भाषा के आधार के रूप में","निमज्जन सही है, बशर्ते बच्चों को कक्षा में गोंडी का किसी भी प्रकार से प्रयोग करने से दृढ़ता से हतोत्साहित किया जाए","शिक्षा का माध्यम अधिगम में कोई वास्तविक अंतर नहीं डालता, इसलिए कोई भी विकल्प ठीक है"],"explanationHi":"NEP 2020 जहाँ भी संभव हो कम से कम कक्षा 5 तक, अधिमानतः कक्षा 8 तक, घर की भाषा या मातृभाषा को माध्यम बनाने की अनुशंसा करती है, जबकि अन्य भाषाएँ भी पढ़ाई जाती रहती हैं; वह हिंदी पर प्रतिबंध नहीं लगाती।"},
  {"id":"cdp-child-development-670","question":"Which observation is LEAST suggestive that a Class 2 child may have a hearing difficulty?","options":["She watches other children before following spoken instructions","She often asks for instructions to be repeated","She responds quickly when her name is called softly from behind her","She turns one ear towards the speaker and seems inattentive when not facing the teacher"],"answer":2,"explanation":"Responding to a soft call from behind, without visual cues, shows good hearing; copying others, frequent requests to repeat and turning an ear are typical warning signs.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कौन-सा अवलोकन इस बात का सबसे कम संकेत देता है कि कक्षा 2 की किसी बच्ची को सुनने में कठिनाई हो सकती है?","optionsHi":["वह मौखिक निर्देशों का पालन करने से पहले अन्य बच्चों को देखती है","वह प्रायः निर्देशों को दोहराने के लिए कहती है","जब उसके पीछे से धीरे से उसका नाम पुकारा जाता है तो वह तुरंत प्रतिक्रिया देती है","वह एक कान वक्ता की ओर मोड़ लेती है और शिक्षक की ओर मुख न होने पर असावधान दिखती है"],"explanationHi":"दृश्य संकेतों के बिना पीछे से धीमी पुकार पर प्रतिक्रिया देना अच्छी श्रवण-शक्ति दर्शाता है; दूसरों की नकल, बार-बार दोहराने को कहना और कान मोड़ना विशिष्ट चेतावनी-संकेत हैं।"},
  {"id":"cdp-child-development-671","question":"Pooja, in Class 4, holds her book very close, squints, often rubs her eyes, complains of headaches and makes many errors while copying from the board. Her teacher suspects dyslexia. What should be done first?","options":["Rule out a vision problem through eye screening, informing parents and seating her near the board","Begin intensive phonics remediation immediately, since her copying errors suggest dyslexia","Record her as careless and reduce marks for copying errors, so that she learns to be more careful","Refer her straight away for an IQ test, to check whether she has a general learning problem"],"answer":0,"explanation":"Her signs point to a possible visual problem, which must be ruled out before any learning disability is considered; teaching phonics would not correct poor eyesight.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 4 की पूजा अपनी किताब बहुत पास रखती है, आँखें सिकोड़ती है, प्रायः आँखें मलती है, सिरदर्द की शिकायत करती है और श्यामपट्ट से नकल करते समय बहुत त्रुटियाँ करती है। उसकी शिक्षिका को डिस्लेक्सिया का संदेह है। सबसे पहले क्या किया जाना चाहिए?","optionsHi":["नेत्र-जाँच द्वारा दृष्टि-समस्या को अलग करना, अभिभावकों को सूचित करना और उसे श्यामपट्ट के पास बैठाना","तुरंत गहन फोनिक्स उपचार शुरू करना, क्योंकि उसकी नकल की त्रुटियाँ डिस्लेक्सिया का संकेत देती हैं","उसे लापरवाह दर्ज करना और नकल की त्रुटियों पर अंक घटाना, ताकि वह अधिक सावधान होना सीखे","उसे सीधे IQ परीक्षण के लिए भेजना, यह जाँचने के लिए कि क्या उसे सामान्य अधिगम-समस्या है"],"explanationHi":"उसके संकेत संभावित दृष्टि-समस्या की ओर इशारा करते हैं, जिसे किसी भी अधिगम अक्षमता पर विचार करने से पहले अलग किया जाना चाहिए; फोनिक्स पढ़ाने से कमज़ोर दृष्टि ठीक नहीं होगी।"},
  {"id":"cdp-child-development-672","question":"A Class 3 child is restless and inattentive. Before anyone suspects ADHD, which of the following could also produce ADHD-like behaviour? I. An undetected hearing or vision problem II. Boredom because the work is far too easy III. Anxiety or stress at home IV. A learning difficulty that makes the work too hard","options":["I and II only","II and III only","I, III and IV only","I, II, III and IV"],"answer":3,"explanation":"All four can make a child appear inattentive or restless, which is why teachers should observe carefully and refer for professional assessment rather than label a child themselves.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 3 का एक बच्चा बेचैन और असावधान है। किसी के ADHD का संदेह करने से पहले, निम्नलिखित में से क्या ADHD जैसा व्यवहार भी उत्पन्न कर सकता है? I. कोई अज्ञात श्रवण या दृष्टि समस्या II. ऊब, क्योंकि कार्य बहुत आसान है III. घर पर चिंता या तनाव IV. कोई अधिगम कठिनाई जो कार्य को बहुत कठिन बना देती है","optionsHi":["केवल I और II","केवल II और III","केवल I, III और IV","I, II, III और IV"],"explanationHi":"चारों किसी बच्चे को असावधान या बेचैन दिखा सकते हैं, इसीलिए शिक्षकों को सावधानीपूर्वक अवलोकन करना चाहिए और स्वयं बच्चे पर लेबल लगाने के बजाय पेशेवर आकलन के लिए भेजना चाहिए।"},
  {"id":"cdp-child-development-673","question":"When asked, ‘Do you want water?’, Aarav, a Class 1 child on the autism spectrum, replies, ‘Do you want water?’ What is the most appropriate interpretation and response?","options":["He is mocking the teacher by repeating her words and should be corrected firmly","This is echolalia, common in autism; model the answer and offer picture choices","He has not heard the question properly and needs to be sent for a hearing test","He is too young to answer such questions and should not be asked them for now"],"answer":1,"explanation":"Repeating heard words (echolalia) is frequent in autism and may be a step in processing or communicating; modelling the response and offering visual choices helps him reply meaningfully.","difficulty":"hard","source":"CTET · State TETs","questionHi":"पूछे जाने पर, ‘क्या तुम्हें पानी चाहिए?’, कक्षा 1 का ऑटिज़्म स्पेक्ट्रम पर स्थित आरव उत्तर देता है, ‘क्या तुम्हें पानी चाहिए?’ सबसे उपयुक्त व्याख्या और प्रतिक्रिया क्या है?","optionsHi":["वह शिक्षिका के शब्द दोहराकर उसका मज़ाक उड़ा रहा है और उसे दृढ़ता से सुधारा जाना चाहिए","यह प्रतिध्वनिवाक् (इकोलेलिया) है, जो ऑटिज़्म में सामान्य है; उत्तर का प्रतिरूपण करें और चित्र-विकल्प दें","उसने प्रश्न ठीक से सुना नहीं है और उसे श्रवण परीक्षण के लिए भेजा जाना चाहिए","वह ऐसे प्रश्नों का उत्तर देने के लिए बहुत छोटा है और फ़िलहाल उससे ये प्रश्न नहीं पूछे जाने चाहिए"],"explanationHi":"सुने हुए शब्दों को दोहराना (इकोलेलिया) ऑटिज़्म में आम है और संसाधन या संप्रेषण का एक चरण हो सकता है; उत्तर का प्रतिरूपण और दृश्य विकल्प देने से वह सार्थक रूप से उत्तर दे पाता है।"},
  {"id":"cdp-child-development-674","question":"Assertion (A): When an autistic child has a meltdown because of sensory overload, the teacher should first reduce stimulation and help the child to a calm space, rather than lecture him about behaviour. Reason (R): A meltdown is a loss of control caused by being overwhelmed, not a deliberate attempt to get something.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because a meltdown is involuntary overwhelm, reasoning or punishment in the moment does not help; calming the environment first, then teaching coping strategies later, is the right sequence.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अभिकथन (A): जब कोई ऑटिस्टिक बच्चा संवेदी अतिभार के कारण मेल्टडाउन में आ जाए, तो शिक्षक को पहले उद्दीपन कम करना चाहिए और बच्चे को शांत स्थान तक पहुँचने में सहायता करनी चाहिए, न कि उसे व्यवहार पर भाषण देना चाहिए। कारण (R): मेल्टडाउन अभिभूत होने से उत्पन्न नियंत्रण की हानि है, कुछ पाने का जान-बूझकर किया गया प्रयास नहीं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"चूँकि मेल्टडाउन अनैच्छिक अभिभूतता है, उस क्षण तर्क करना या दंड देना सहायक नहीं होता; पहले परिवेश को शांत करना, फिर बाद में सामना करने की युक्तियाँ सिखाना सही क्रम है।"},
  {"id":"cdp-child-development-675","question":"Gopal, a Class 4 child with intellectual disability, counts money correctly in class but cannot pay or check change at the village shop. Which teaching strategy addresses this problem most directly?","options":["Giving him more worksheets on money in class until he gets every sum right","Moving on to a new topic, since he has clearly mastered money in the classroom","Practising with real coins in varied settings, including role-play and real shops","Asking his parents to handle all his purchases until he is old enough to manage"],"answer":2,"explanation":"Children with intellectual disability often find it hard to transfer skills to new settings, so skills should be practised in varied, real contexts until they generalise.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 4 का गोपाल, जिसमें बौद्धिक अक्षमता है, कक्षा में पैसे सही गिनता है पर गाँव की दुकान पर भुगतान नहीं कर पाता या खुले पैसे जाँच नहीं पाता। कौन-सी शिक्षण युक्ति इस समस्या को सबसे सीधे संबोधित करती है?","optionsHi":["कक्षा में पैसों पर और कार्य-पत्रक देना, जब तक वह हर प्रश्न सही न करने लगे","नए विषय पर आगे बढ़ना, क्योंकि उसने कक्षा में पैसों में स्पष्ट रूप से निपुणता पा ली है","वास्तविक सिक्कों के साथ विविध परिवेशों में अभ्यास कराना, जिनमें भूमिका-निर्वाह और वास्तविक दुकानें शामिल हों","उसके माता-पिता से कहना कि जब तक वह स्वयं सँभालने योग्य बड़ा न हो जाए, उसकी सारी खरीदारी वे ही करें"],"explanationHi":"बौद्धिक अक्षमता वाले बच्चों को प्रायः कौशल नए परिवेशों में हस्तांतरित करना कठिन लगता है, इसलिए कौशलों का अभ्यास विविध, वास्तविक संदर्भों में तब तक कराना चाहिए जब तक वे सामान्यीकृत न हो जाएँ।"},
  {"id":"cdp-child-development-676","question":"Inspired by ‘learning by doing’, a teacher lets her Class 6 children do whatever activities they like all day, without any planning, saying ‘every experience is learning’. John Dewey would most likely object because:","options":["He held that children learn best through strict drill under the teacher's direct control","Not every experience is educative; experiences must be chosen to lead to further growth","He wanted activity in school to be limited to manual crafts such as weaving and carpentry","He argued that the curriculum must always follow the sequence laid down in the textbook"],"answer":1,"explanation":"In ‘Experience and Education’ Dewey warned that some experiences are mis-educative; the teacher must organise experiences with continuity and interaction so that each leads to further growth. Progressive education was never ‘anything goes’.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"‘करके सीखने’ से प्रेरित होकर एक शिक्षिका अपने कक्षा 6 के बच्चों को बिना किसी योजना के पूरे दिन अपनी पसंद की गतिविधियाँ करने देती है, यह कहकर कि ‘हर अनुभव अधिगम है’। जॉन डेवी संभवतः आपत्ति क्यों करते?","optionsHi":["उनका मत था कि बच्चे शिक्षक के प्रत्यक्ष नियंत्रण में कठोर अभ्यास से सबसे अच्छा सीखते हैं","हर अनुभव शैक्षिक नहीं होता; अनुभवों को ऐसे चुना जाना चाहिए जो आगे के विकास की ओर ले जाएँ","वे चाहते थे कि विद्यालय में गतिविधि बुनाई और बढ़ईगिरी जैसे हस्तशिल्प तक सीमित रहे","उनका तर्क था कि पाठ्यचर्या को सदैव पाठ्यपुस्तक में निर्धारित क्रम का पालन करना चाहिए"],"explanationHi":"‘एक्सपीरियंस एंड एजुकेशन’ में डेवी ने चेताया कि कुछ अनुभव अशैक्षिक होते हैं; शिक्षक को अनुभवों को निरंतरता और अंतःक्रिया के साथ संगठित करना चाहिए ताकि प्रत्येक आगे के विकास की ओर ले जाए। प्रगतिशील शिक्षा कभी ‘कुछ भी चलेगा’ नहीं थी।"},
  {"id":"cdp-child-development-677","question":"Which of these ideas are associated with John Dewey? I. The school should be a miniature community reflecting the life of the wider society. II. Education is a process of living, not merely a preparation for future living. III. The mind is a blank slate to be filled through drill. IV. Thinking begins with a felt problem or difficulty.","options":["I and III only","II and III only","I, II and III only","I, II and IV only"],"answer":3,"explanation":"Dewey saw school as an embryonic community, education as life itself, and reflective thinking as starting from a felt difficulty; the blank-slate-and-drill view is the very tradition he opposed.","difficulty":"hard","source":"CTET · KVS TGT","questionHi":"इनमें से कौन-से विचार जॉन डेवी से जुड़े हैं? I. विद्यालय एक लघु समुदाय होना चाहिए जो व्यापक समाज के जीवन को प्रतिबिंबित करे। II. शिक्षा जीने की एक प्रक्रिया है, केवल भावी जीवन की तैयारी नहीं। III. मस्तिष्क एक कोरी पट्टिका है जिसे अभ्यास द्वारा भरा जाना है। IV. चिंतन एक अनुभव की गई समस्या या कठिनाई से शुरू होता है।","optionsHi":["केवल I और III","केवल II और III","केवल I, II और III","केवल I, II और IV"],"explanationHi":"डेवी विद्यालय को एक भ्रूणीय समुदाय, शिक्षा को स्वयं जीवन, और चिंतनशील सोच को अनुभव की गई कठिनाई से आरंभ होने वाला मानते थे; कोरी-पट्टिका-और-अभ्यास का दृष्टिकोण उसी परंपरा का है जिसका उन्होंने विरोध किया।"},
  {"id":"cdp-child-development-678","question":"Class 7 children notice stagnant water near their school breeding mosquitoes. With the teacher’s help they decide to survey the area, collect data from the local health centre, carry out the survey and present a plan to the panchayat, and finally judge what worked. This approach is the:","options":["Project method, developed by W. H. Kilpatrick from Dewey's ideas","Montessori method, based on self-correcting sensorial materials","Lecture-demonstration method, led and directed by the teacher","Programmed instruction, based on Skinner's operant conditioning"],"answer":0,"explanation":"Purposing, planning, executing and judging a real, learner-owned task are the steps of Kilpatrick’s project method, which grew out of Dewey’s pragmatism.","difficulty":"hard","source":"CTET Paper II · State TET","questionHi":"कक्षा 7 के बच्चे अपने विद्यालय के पास ठहरे हुए पानी में मच्छरों को पनपते देखते हैं। शिक्षक की सहायता से वे क्षेत्र का सर्वेक्षण करने, स्थानीय स्वास्थ्य केंद्र से आँकड़े जुटाने, सर्वेक्षण करने और पंचायत के सामने योजना प्रस्तुत करने का निर्णय लेते हैं, और अंत में आकलन करते हैं कि क्या कारगर रहा। यह उपागम है:","optionsHi":["प्रोजेक्ट पद्धति, जिसे डब्ल्यू. एच. किलपैट्रिक ने डेवी के विचारों से विकसित किया","मॉन्टेसरी पद्धति, जो स्व-सुधारक संवेदी सामग्री पर आधारित है","व्याख्यान-प्रदर्शन पद्धति, जो शिक्षक के नेतृत्व और निर्देशन में चलती है","अभिक्रमित अनुदेशन, जो स्किनर के संक्रियात्मक अनुबंधन पर आधारित है"],"explanationHi":"एक वास्तविक, अधिगमकर्ता-स्वामित्व वाले कार्य का प्रयोजन, योजना, निष्पादन और मूल्यांकन किलपैट्रिक की प्रोजेक्ट पद्धति के चरण हैं, जो डेवी के प्रयोजनवाद से उपजी।"},
  {"id":"cdp-child-development-679","question":"Dewey contrasted ‘reflective action’ with ‘routine action’. Which teacher behaviour is an example of routine action in his sense?","options":["Asking why a lesson failed and deliberately trying a different approach the next time","Seeking students' views on what helped them learn and adjusting the plan accordingly","Teaching a chapter the same way every year because it has always been done so","Reading research and talking to colleagues to understand a persistent classroom problem"],"answer":2,"explanation":"Routine action is guided by habit, tradition and authority; reflective action is careful, persistent examination of beliefs and practices in the light of evidence and consequences.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"डेवी ने ‘चिंतनशील कर्म’ की तुलना ‘रूढ़ कर्म’ से की। उनके अर्थ में शिक्षक का कौन-सा व्यवहार रूढ़ कर्म का उदाहरण है?","optionsHi":["यह पूछना कि कोई पाठ क्यों असफल रहा और अगली बार जान-बूझकर भिन्न उपागम आज़माना","विद्यार्थियों से उनके विचार जानना कि क्या सीखने में सहायक रहा और उसी के अनुसार योजना बदलना","हर वर्ष किसी अध्याय को उसी तरह पढ़ाना क्योंकि वह हमेशा से ऐसे ही होता आया है","शोध पढ़ना और सहकर्मियों से बात करना ताकि कक्षा की किसी निरंतर समस्या को समझा जा सके"],"explanationHi":"रूढ़ कर्म आदत, परंपरा और सत्ता से संचालित होता है; चिंतनशील कर्म प्रमाणों और परिणामों के प्रकाश में विश्वासों और प्रथाओं की सावधान, निरंतर जाँच है।"},
  {"id":"cdp-child-development-680","question":"A teacher is willing to consider that her favourite method may be wrong for this class (P), thinks carefully about the long-term consequences of her choices for her students (Q), and commits herself fully to improving despite setbacks (R). These match Dewey’s three attitudes for reflective teaching as:","options":["P-responsibility, Q-open-mindedness, R-wholeheartedness","P-wholeheartedness, Q-responsibility, R-open-mindedness","P-open-mindedness, Q-wholeheartedness, R-responsibility","P-open-mindedness, Q-responsibility, R-wholeheartedness"],"answer":3,"explanation":"Open-mindedness is readiness to consider other views and one’s own possible error; responsibility is weighing consequences; wholeheartedness is full commitment that keeps the other two going.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"एक शिक्षिका इस बात पर विचार करने को तैयार है कि उसकी पसंदीदा विधि इस कक्षा के लिए गलत हो सकती है (P), अपने विद्यार्थियों के लिए अपने चुनावों के दीर्घकालिक परिणामों के बारे में ध्यान से सोचती है (Q), और असफलताओं के बावजूद सुधार के लिए पूरी तरह प्रतिबद्ध है (R)। ये चिंतनशील शिक्षण के लिए डेवी के तीन दृष्टिकोणों से इस प्रकार मेल खाते हैं:","optionsHi":["P-उत्तरदायित्व, Q-खुला दृष्टिकोण, R-पूर्ण निष्ठा","P-पूर्ण निष्ठा, Q-उत्तरदायित्व, R-खुला दृष्टिकोण","P-खुला दृष्टिकोण, Q-पूर्ण निष्ठा, R-उत्तरदायित्व","P-खुला दृष्टिकोण, Q-उत्तरदायित्व, R-पूर्ण निष्ठा"],"explanationHi":"खुला दृष्टिकोण अन्य मतों और अपनी संभावित त्रुटि पर विचार करने की तत्परता है; उत्तरदायित्व परिणामों को तौलना है; पूर्ण निष्ठा वह पूर्ण प्रतिबद्धता है जो अन्य दो को चलाए रखती है।"},
  {"id":"cdp-child-development-681","question":"A Montessori-trained teacher notices a three-year-old pouring water from one jug to another, again and again, for twenty minutes. In keeping with Montessori’s ideas, she should:","options":["Stop the child and shift her to a reading lesson, since such repetition wastes valuable time","Not interrupt, since focused repetition of a chosen activity builds skill, order and focus","Give her a small reward each time she pours without spilling, to reinforce careful pouring","Show her the correct way repeatedly until she copies the adult's movements exactly"],"answer":1,"explanation":"Montessori valued deep, self-chosen concentration in ‘practical life’ work; the adult protects it rather than interrupting it or adding external rewards.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"मॉन्टेसरी-प्रशिक्षित एक शिक्षिका देखती है कि तीन वर्ष की एक बच्ची बीस मिनट तक एक घड़े से दूसरे में बार-बार पानी उँडेल रही है। मॉन्टेसरी के विचारों के अनुरूप उसे क्या करना चाहिए?","optionsHi":["बच्ची को रोककर पठन के पाठ में ले जाना, क्योंकि ऐसा दोहराव बहुमूल्य समय की बर्बादी है","बाधा न डालना, क्योंकि स्वयं चुनी गतिविधि का एकाग्र दोहराव कौशल, क्रम और एकाग्रता बनाता है","हर बार बिना छलके पानी उँडेलने पर उसे छोटा पुरस्कार देना, ताकि सावधानी से उँडेलना सुदृढ़ हो","उसे बार-बार सही तरीका दिखाना जब तक वह वयस्क की गतियों की ठीक नकल न कर ले"],"explanationHi":"मॉन्टेसरी ने ‘व्यावहारिक जीवन’ के कार्य में गहन, स्वयं चुनी एकाग्रता को महत्त्व दिया; वयस्क उसे बाधित करने या बाह्य पुरस्कार जोड़ने के बजाय उसकी रक्षा करता है।"},
  {"id":"cdp-child-development-682","question":"Montessori’s idea of ‘sensitive periods’ implies that a teacher of young children should:","options":["Watch for phases of intense interest, such as in order or language, and offer suitable activities","Delay all formal teaching until the child is seven, when the sensitive periods begin","Teach every child the same skill at the same chronological age, as the periods are fixed","Make children sensitive to criticism, so that they learn to correct their own errors quickly"],"answer":0,"explanation":"Montessori held that children pass through periods of special receptivity to particular kinds of learning; careful observation lets the teacher match materials to these phases instead of a fixed calendar.","difficulty":"hard","source":"CTET Paper I · State TET","questionHi":"मॉन्टेसरी का ‘संवेदनशील अवधियों’ का विचार यह संकेत देता है कि छोटे बच्चों के शिक्षक को:","optionsHi":["तीव्र रुचि के चरणों पर नज़र रखनी चाहिए, जैसे क्रम या भाषा में, और उपयुक्त गतिविधियाँ देनी चाहिए","सारी औपचारिक शिक्षा तब तक टालनी चाहिए जब तक बच्चा सात वर्ष का न हो, जब संवेदनशील अवधियाँ आरंभ होती हैं","प्रत्येक बच्चे को एक ही कालानुक्रमिक आयु पर एक ही कौशल सिखाना चाहिए, क्योंकि अवधियाँ निश्चित हैं","बच्चों को आलोचना के प्रति संवेदनशील बनाना चाहिए, ताकि वे अपनी त्रुटियाँ शीघ्र सुधारना सीखें"],"explanationHi":"मॉन्टेसरी का मत था कि बच्चे विशेष प्रकार के अधिगम के प्रति विशेष ग्रहणशीलता की अवधियों से गुज़रते हैं; सावधान अवलोकन शिक्षक को निश्चित कैलेंडर के बजाय इन चरणों के अनुसार सामग्री देने देता है।"},
  {"id":"cdp-child-development-683","question":"Which statement correctly contrasts Froebel and Montessori?","options":["Froebel rejected play as a waste of time, while Montessori made imaginative play central to her method","Montessori's materials were symbolic gifts expressing spiritual unity; Froebel's were self-correcting sensory apparatus","Froebel's gifts were symbolic and used in group play with songs; Montessori's were self-correcting, for individual work","Both educators left no real role for the teacher, who was expected simply to stay out of the way"],"answer":2,"explanation":"Froebel, an idealist, gave his gifts symbolic meaning and used them in teacher-led group play and songs; Montessori designed self-correcting didactic apparatus for individual work. Option B swaps the two.","difficulty":"very-hard","source":"KVS PRT · DSSSB PRT","questionHi":"फ्रोबेल और मॉन्टेसरी की तुलना कौन-सा कथन सही ढंग से करता है?","optionsHi":["फ्रोबेल ने खेल को समय की बर्बादी माना, जबकि मॉन्टेसरी ने कल्पनाशील खेल को अपनी पद्धति का केंद्र बनाया","मॉन्टेसरी की सामग्री आध्यात्मिक एकता को व्यक्त करने वाले प्रतीकात्मक उपहार थी; फ्रोबेल के स्व-सुधारक संवेदी उपकरण थे","फ्रोबेल के उपहार प्रतीकात्मक थे और गीतों के साथ समूह-खेल में प्रयुक्त होते थे; मॉन्टेसरी की सामग्री स्व-सुधारक थी, व्यक्तिगत कार्य के लिए","दोनों शिक्षाविदों ने शिक्षक के लिए कोई वास्तविक भूमिका नहीं छोड़ी, जिससे अपेक्षा थी कि वह बस रास्ते से हट जाए"],"explanationHi":"आदर्शवादी फ्रोबेल ने अपने उपहारों को प्रतीकात्मक अर्थ दिया और उन्हें शिक्षक-नेतृत्व वाले समूह-खेल और गीतों में प्रयुक्त किया; मॉन्टेसरी ने व्यक्तिगत कार्य के लिए स्व-सुधारक उपदेशात्मक उपकरण बनाए। विकल्प B दोनों को उलट देता है।"},
  {"id":"cdp-child-development-684","question":"Which image of the teacher best reflects Friedrich Froebel’s view?","options":["A drill master who moulds the child as a potter moulds clay into a set shape","A lecturer who transmits knowledge clearly to attentive but passive listeners","A judge who ranks children by achievement so that each knows where he stands","A gardener who provides conditions for the child's nature to unfold through play"],"answer":3,"explanation":"Froebel’s ‘kindergarten’ (children’s garden) pictured children as plants and the teacher as a gardener nurturing natural growth, not shaping it from outside.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"फ्रेडरिक फ्रोबेल के मत को शिक्षक की कौन-सी छवि सबसे अच्छी तरह दर्शाती है?","optionsHi":["एक कठोर अनुशासक जो बच्चे को वैसे ढालता है जैसे कुम्हार मिट्टी को निश्चित आकार में ढालता है","एक व्याख्याता जो ध्यान देने वाले पर निष्क्रिय श्रोताओं को ज्ञान स्पष्ट रूप से देता है","एक न्यायाधीश जो बच्चों को उपलब्धि के आधार पर क्रमबद्ध करता है ताकि प्रत्येक जाने कि वह कहाँ खड़ा है","एक माली जो खेल के माध्यम से बच्चे की प्रकृति के विकसित होने की परिस्थितियाँ प्रदान करता है"],"explanationHi":"फ्रोबेल का ‘किंडरगार्टन’ (बच्चों का बगीचा) बच्चों को पौधों और शिक्षक को माली के रूप में देखता था जो स्वाभाविक विकास का पोषण करता है, उसे बाहर से आकार नहीं देता।"},
  {"id":"cdp-child-development-685","question":"Assertion (A): Froebel regarded play as the highest expression of human development in early childhood. Reason (R): For Froebel, play is the free self-expression of the child’s inner nature, that is, self-activity.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Froebel valued play so highly precisely because he saw it as self-activity, the outward expression of the child’s inner nature; R therefore explains A.","difficulty":"very-hard","source":"CTET Paper I · State TET","questionHi":"अभिकथन (A): फ्रोबेल खेल को आरंभिक बाल्यावस्था में मानव विकास की सर्वोच्च अभिव्यक्ति मानते थे। कारण (R): फ्रोबेल के लिए, खेल बच्चे की आंतरिक प्रकृति की मुक्त आत्म-अभिव्यक्ति है, अर्थात् आत्म-क्रिया।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"फ्रोबेल खेल को इतना महत्त्व इसीलिए देते थे क्योंकि वे उसे आत्म-क्रिया, बच्चे की आंतरिक प्रकृति की बाह्य अभिव्यक्ति, मानते थे; इसलिए R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-686","question":"A common criticism of the Montessori method is that it:","options":["Gives too much importance to group singing, story-telling and make-believe games","Leaves little room for imaginative play and group activity, stressing individual work","Ignores the training of the senses in favour of early reading and writing","Depends entirely on rote memorisation of facts that the teacher dictates"],"answer":1,"explanation":"Critics argued that Montessori’s individual, material-bound work left little room for fantasy, free imaginative play and group social activity; sense training was in fact her strength.","difficulty":"hard","source":"KVS PRT · DSSSB PRT","questionHi":"मॉन्टेसरी पद्धति की एक आम आलोचना यह है कि वह:","optionsHi":["सामूहिक गायन, कहानी सुनाने और कल्पनात्मक खेलों को बहुत अधिक महत्त्व देती है","कल्पनात्मक खेल और समूह गतिविधि के लिए बहुत कम स्थान छोड़ती है, व्यक्तिगत कार्य पर बल देती है","प्रारंभिक पठन और लेखन के पक्ष में इंद्रियों के प्रशिक्षण की उपेक्षा करती है","पूरी तरह उन तथ्यों के रटंत स्मरण पर निर्भर है जो शिक्षक श्रुतलेख से लिखवाता है"],"explanationHi":"आलोचकों का तर्क था कि मॉन्टेसरी का व्यक्तिगत, सामग्री-बद्ध कार्य कल्पना, मुक्त कल्पनात्मक खेल और समूह सामाजिक गतिविधि के लिए कम स्थान छोड़ता है; इंद्रिय-प्रशिक्षण वास्तव में उनकी शक्ति था।"},
  {"id":"cdp-child-development-687","question":"Which classroom practice would John Dewey most strongly criticise?","options":["Children growing a kitchen garden and keeping careful records of how the plants grow","Discussing a local problem as a class and testing out possible solutions to it","Fixed subject periods in which children memorise facts unconnected with experience","Group work in which children share out tasks and work towards a common goal"],"answer":2,"explanation":"Dewey opposed isolated, memorised subject matter cut off from the child’s experience; gardening, problem-solving and shared purposeful activity were central to his school.","difficulty":"moderate","source":"CTET · State TET","questionHi":"जॉन डेवी किस कक्षा-प्रथा की सबसे अधिक आलोचना करते?","optionsHi":["बच्चों का रसोई-बगीचा उगाना और पौधों के बढ़ने का सावधान अभिलेख रखना","कक्षा के रूप में किसी स्थानीय समस्या पर चर्चा करना और उसके संभावित समाधानों को आज़माना","निश्चित विषय-कालांश जिनमें बच्चे अनुभव से असंबद्ध तथ्य रटते हैं","समूह कार्य जिसमें बच्चे कार्य बाँटते हैं और साझे लक्ष्य की ओर बढ़ते हैं"],"explanationHi":"डेवी ने बच्चे के अनुभव से कटी हुई अलग-थलग, रटी हुई विषय-वस्तु का विरोध किया; बागवानी, समस्या-समाधान और साझी उद्देश्यपूर्ण गतिविधि उनके विद्यालय के केंद्र में थे।"},
  {"id":"cdp-child-development-688","question":"In ‘Democracy and Education’ (1916), Dewey linked education and democracy mainly by arguing that:","options":["Only elected representatives should decide what is taught in the nation's schools","Democracy requires that children be trained to obey authority without questioning it","Schools should mainly prepare a small, capable elite for leadership in public life","Democracy needs schools where children share purposeful activity across differences"],"answer":3,"explanation":"For Dewey democracy is ‘a mode of associated living’; schools nurture it by being communities of shared, purposeful activity, not by drilling obedience or training an elite.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"‘डेमोक्रेसी एंड एजुकेशन’ (1916) में डेवी ने शिक्षा और लोकतंत्र को मुख्यतः यह तर्क देकर जोड़ा कि:","optionsHi":["केवल निर्वाचित प्रतिनिधियों को तय करना चाहिए कि देश के विद्यालयों में क्या पढ़ाया जाए","लोकतंत्र के लिए आवश्यक है कि बच्चों को बिना प्रश्न किए सत्ता का आज्ञापालन करने का प्रशिक्षण दिया जाए","विद्यालयों को मुख्यतः एक छोटे, सक्षम अभिजात वर्ग को सार्वजनिक जीवन में नेतृत्व के लिए तैयार करना चाहिए","लोकतंत्र को ऐसे विद्यालयों की आवश्यकता है जहाँ बच्चे भिन्नताओं के पार उद्देश्यपूर्ण गतिविधि साझा करें"],"explanationHi":"डेवी के लिए लोकतंत्र ‘सहचारी जीवन का एक ढंग’ है; विद्यालय उसे साझी, उद्देश्यपूर्ण गतिविधि के समुदाय बनकर पोषित करते हैं, आज्ञाकारिता का अभ्यास कराकर या अभिजात वर्ग को प्रशिक्षित करके नहीं।"},
  {"id":"cdp-child-development-689","question":"Match each educator with the institution linked to him or her: P. Maria Montessori  Q. Friedrich Froebel  R. Rabindranath Tagore  S. John Dewey — 1. Casa dei Bambini, Rome  2. The first kindergarten, Germany  3. Patha Bhavana, Santiniketan  4. Laboratory School, Chicago","options":["P-1, Q-2, R-3, S-4","P-2, Q-1, R-3, S-4","P-1, Q-2, R-4, S-3","P-4, Q-2, R-3, S-1"],"answer":0,"explanation":"Montessori opened the Casa dei Bambini in Rome (1907), Froebel founded the kindergarten in Germany (1837), Tagore began his school at Santiniketan (1901), and Dewey ran the Laboratory School in Chicago (1896).","difficulty":"hard","source":"CTET · KVS PRT","questionHi":"प्रत्येक शिक्षाविद का मिलान उससे जुड़ी संस्था से कीजिए: P. मारिया मॉन्टेसरी  Q. फ्रेडरिक फ्रोबेल  R. रवींद्रनाथ टैगोर  S. जॉन डेवी — 1. कासा देई बांबिनी, रोम  2. पहला किंडरगार्टन, जर्मनी  3. पाठ भवन, शांतिनिकेतन  4. प्रयोगशाला विद्यालय, शिकागो","optionsHi":["P-1, Q-2, R-3, S-4","P-2, Q-1, R-3, S-4","P-1, Q-2, R-4, S-3","P-4, Q-2, R-3, S-1"],"explanationHi":"मॉन्टेसरी ने रोम में कासा देई बांबिनी (1907) खोला, फ्रोबेल ने जर्मनी में किंडरगार्टन (1837) की स्थापना की, टैगोर ने शांतिनिकेतन में अपना विद्यालय (1901) आरंभ किया, और डेवी ने शिकागो में प्रयोगशाला विद्यालय (1896) चलाया।"},
  {"id":"cdp-child-development-690","question":"Dewey’s pragmatism implies which view of knowledge in the classroom?","options":["Knowledge is fixed and eternal, and should be handed on unchanged to each generation","Knowledge is tested by its consequences in experience and stays open to revision","Knowledge is found only in authoritative texts, which the teacher interprets for pupils","Knowledge is innate in the mind and is merely recalled through skilful questioning"],"answer":1,"explanation":"For the pragmatist, ideas are tools judged by how they work out in experience, so knowledge is provisional and built through inquiry, not received as fixed truth.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"डेवी का प्रयोजनवाद कक्षा में ज्ञान के किस दृष्टिकोण को दर्शाता है?","optionsHi":["ज्ञान स्थिर और शाश्वत है, और उसे प्रत्येक पीढ़ी को अपरिवर्तित रूप में सौंपा जाना चाहिए","ज्ञान की परख अनुभव में उसके परिणामों से होती है और वह संशोधन के लिए खुला रहता है","ज्ञान केवल प्रामाणिक ग्रंथों में मिलता है, जिनकी व्याख्या शिक्षक विद्यार्थियों के लिए करता है","ज्ञान मस्तिष्क में जन्मजात होता है और कुशल प्रश्नों द्वारा केवल स्मरण किया जाता है"],"explanationHi":"प्रयोजनवादी के लिए विचार उपकरण हैं जिन्हें इस आधार पर परखा जाता है कि वे अनुभव में कैसे कारगर होते हैं, इसलिए ज्ञान अस्थायी है और जाँच-पड़ताल से निर्मित होता है, स्थिर सत्य के रूप में प्राप्त नहीं होता।"},
  {"id":"cdp-child-development-691","question":"In a Montessori classroom the teacher is called a ‘directress’ because she:","options":["Directs every activity step by step, so that the materials are used correctly","Directs the class mainly through short lectures followed by guided practice","Prepares the environment, demonstrates materials, then observes and guides","Directs children to compete with one another for prizes and recognition"],"answer":2,"explanation":"The Montessori teacher’s main work is preparing the environment and observing; after a brief demonstration, the child works independently while the teacher guides unobtrusively.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"मॉन्टेसरी कक्षा में शिक्षिका को ‘निर्देशिका’ (डायरेक्ट्रेस) इसलिए कहा जाता है क्योंकि वह:","optionsHi":["प्रत्येक गतिविधि का चरण-दर-चरण निर्देशन करती है, ताकि सामग्री का सही उपयोग हो","कक्षा का निर्देशन मुख्यतः छोटे व्याख्यानों से करती है, जिनके बाद निर्देशित अभ्यास होता है","परिवेश तैयार करती है, सामग्री का प्रदर्शन करती है, फिर अवलोकन करती और मार्गदर्शन देती है","बच्चों को पुरस्कार और मान्यता के लिए एक-दूसरे से प्रतिस्पर्धा करने के लिए निर्देशित करती है"],"explanationHi":"मॉन्टेसरी शिक्षिका का मुख्य कार्य परिवेश तैयार करना और अवलोकन करना है; संक्षिप्त प्रदर्शन के बाद बच्चा स्वतंत्र रूप से कार्य करता है जबकि शिक्षिका अनाक्रामक ढंग से मार्गदर्शन करती है।"},
  {"id":"cdp-child-development-692","question":"Which of these statements about Maria Montessori are correct? I. She trained as a physician and first worked with children with intellectual disabilities. II. Mixed-age groups are a feature of Montessori classrooms. III. She favoured rewards and punishments to motivate children. IV. ‘Practical life’ activities such as buttoning and pouring develop independence and coordination.","options":["I and III only","II, III and IV only","I and IV only","I, II and IV only"],"answer":3,"explanation":"Montessori was a medical doctor, used mixed-age groups and practical-life work, and rejected rewards and punishments in favour of the satisfaction of the work itself, so III is false.","difficulty":"very-hard","source":"CTET Paper I · DSSSB PRT","questionHi":"मारिया मॉन्टेसरी के बारे में इनमें से कौन-से कथन सही हैं? I. उन्होंने चिकित्सक के रूप में प्रशिक्षण लिया और पहले बौद्धिक अक्षमता वाले बच्चों के साथ काम किया। II. मिश्रित-आयु समूह मॉन्टेसरी कक्षाओं की एक विशेषता हैं। III. वे बच्चों को प्रेरित करने के लिए पुरस्कार और दंड के पक्ष में थीं। IV. बटन लगाने और पानी उँडेलने जैसी ‘व्यावहारिक जीवन’ की गतिविधियाँ स्वतंत्रता और समन्वय विकसित करती हैं।","optionsHi":["केवल I और III","केवल II, III और IV","केवल I और IV","केवल I, II और IV"],"explanationHi":"मॉन्टेसरी एक चिकित्सक थीं, उन्होंने मिश्रित-आयु समूहों और व्यावहारिक जीवन के कार्य का उपयोग किया, और कार्य की स्वयं की संतुष्टि के पक्ष में पुरस्कार और दंड को अस्वीकार किया, इसलिए III असत्य है।"},
  {"id":"cdp-child-development-693","question":"Dewey argued that ‘interest’ and ‘effort’ are not opposites. In the classroom this means that:","options":["Tasks linked to the child's genuine purposes call out effort without outside pressure","Children should be given only tasks they find entertaining, so that effort is never needed","Effort must be compelled through punishment or rewards whenever interest is absent","Interest matters only in the early years; later, effort alone must carry the learner"],"answer":0,"explanation":"Dewey held that real interest in an end generates the effort needed to reach it; pure entertainment and forced effort are both failures to connect the task with the child’s purposes.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"डेवी का तर्क था कि ‘रुचि’ और ‘प्रयास’ विरोधी नहीं हैं। कक्षा में इसका अर्थ है कि:","optionsHi":["बच्चे के वास्तविक उद्देश्यों से जुड़े कार्य बाहरी दबाव के बिना प्रयास जगाते हैं","बच्चों को केवल वही कार्य दिए जाने चाहिए जिन्हें वे मनोरंजक पाएँ, ताकि प्रयास की कभी आवश्यकता न पड़े","जब भी रुचि न हो, प्रयास को दंड या पुरस्कार से विवश करना चाहिए","रुचि केवल आरंभिक वर्षों में महत्त्वपूर्ण है; बाद में अधिगमकर्ता को केवल प्रयास ही आगे ले जाना चाहिए"],"explanationHi":"डेवी का मत था कि किसी लक्ष्य में वास्तविक रुचि उसे पाने के लिए आवश्यक प्रयास उत्पन्न करती है; शुद्ध मनोरंजन और थोपा गया प्रयास दोनों कार्य को बच्चे के उद्देश्यों से जोड़ने में विफलताएँ हैं।"},
  {"id":"cdp-child-development-694","question":"A kindergarten teacher gives children a soft ball, then a sphere, a cube and a cylinder, followed by building blocks, and accompanies the play with songs and finger rhymes. She is following:","options":["Montessori’s self-correcting didactic apparatus","Pestalozzi’s object lessons","Froebel’s gifts and occupations","Skinner’s teaching machines"],"answer":2,"explanation":"The ball, the sphere-cube-cylinder set and building blocks are Froebel’s ‘gifts’, used with songs and rhymes; Pestalozzi’s object lessons used everyday objects to train observation and naming.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"एक किंडरगार्टन शिक्षिका बच्चों को एक नरम गेंद देती है, फिर एक गोला, एक घन और एक बेलन, उसके बाद निर्माण-ब्लॉक, और खेल के साथ गीत तथा अँगुली-कविताएँ गवाती है। वह किसका अनुसरण कर रही है?","optionsHi":["मॉन्टेसरी के स्व-सुधारक उपदेशात्मक उपकरण","पेस्टालॉज़ी के वस्तु-पाठ","फ्रोबेल के उपहार और व्यवसाय (गिफ्ट्स एंड ऑक्यूपेशंस)","स्किनर की शिक्षण-मशीनें"],"explanationHi":"गेंद, गोला-घन-बेलन का सेट और निर्माण-ब्लॉक फ्रोबेल के ‘उपहार’ हैं, जो गीतों और कविताओं के साथ प्रयुक्त होते हैं; पेस्टालॉज़ी के वस्तु-पाठ अवलोकन और नामकरण के प्रशिक्षण के लिए रोज़मर्रा की वस्तुओं का उपयोग करते थे।"},
  {"id":"cdp-child-development-695","question":"Arrange Dewey’s steps of reflective thinking as a Class 8 group investigates wilting plants: P. They notice the plants drooping and feel puzzled. Q. They test by moving one pot to the window and watering another more often. R. They pin down exactly what the problem is: only the plants on the dark side of the room droop. S. They suggest possible causes and reason out what each would predict.","options":["P, S, R, Q","P, R, S, Q","R, P, Q, S","P, Q, R, S"],"answer":1,"explanation":"Dewey’s sequence is felt difficulty, locating and defining it, suggesting solutions, reasoning out their implications, and testing by observation or experiment: P, R, S, Q.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT","questionHi":"जब कक्षा 8 का एक समूह मुरझाते पौधों की जाँच करता है, तो डेवी के चिंतनशील चिंतन के चरणों को व्यवस्थित कीजिए: P. वे पौधों को झुकते देखते हैं और उलझन महसूस करते हैं। Q. वे एक गमले को खिड़की के पास ले जाकर और दूसरे में अधिक बार पानी देकर परीक्षण करते हैं। R. वे ठीक-ठीक तय करते हैं कि समस्या क्या है: केवल कमरे के अँधेरे हिस्से के पौधे झुकते हैं। S. वे संभावित कारण सुझाते हैं और तर्क करते हैं कि प्रत्येक क्या भविष्यवाणी करेगा।","optionsHi":["P, S, R, Q","P, R, S, Q","R, P, Q, S","P, Q, R, S"],"explanationHi":"डेवी का क्रम है: अनुभव की गई कठिनाई, उसे खोजना और परिभाषित करना, समाधान सुझाना, उनके निहितार्थों पर तर्क करना, और अवलोकन या प्रयोग से परीक्षण करना: P, R, S, Q।"},
  {"id":"cdp-child-development-696","question":"Which feature is common to the educational ideas of Dewey, Montessori and Froebel?","options":["Reliance on firm corporal punishment to maintain classroom discipline","Strictly uniform pacing, so that all children move through work together","A child-centred view in which the child's own activity is central","Emphasis on memorising set texts and reciting them before the class"],"answer":2,"explanation":"Despite their differences, all three placed the active child at the centre: Dewey through experience, Montessori through self-education with materials and Froebel through self-activity in play.","difficulty":"moderate","source":"CTET · State TET","questionHi":"डेवी, मॉन्टेसरी और फ्रोबेल के शैक्षिक विचारों में कौन-सी विशेषता समान है?","optionsHi":["कक्षा में अनुशासन बनाए रखने के लिए कठोर शारीरिक दंड पर निर्भरता","पूर्णतः एकसमान गति, ताकि सभी बच्चे साथ-साथ कार्य करें","बाल-केंद्रित दृष्टि जिसमें बच्चे की अपनी गतिविधि केंद्रीय है","निर्धारित पाठों को रटने और कक्षा के सामने सुनाने पर बल"],"explanationHi":"अपने भेदों के बावजूद तीनों ने सक्रिय बच्चे को केंद्र में रखा: डेवी ने अनुभव के माध्यम से, मॉन्टेसरी ने सामग्री के साथ स्व-शिक्षा के माध्यम से और फ्रोबेल ने खेल में आत्म-क्रिया के माध्यम से।"},
  {"id":"cdp-child-development-697","question":"Assertion (A): Montessori recommended giving children stars and prizes for correct work. Reason (R): Montessori held that the satisfaction of the work itself, helped by self-correcting materials, is sufficient motivation.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Montessori rejected external rewards and punishments; she believed children find satisfaction in purposeful work and that the materials let them correct their own mistakes.","difficulty":"very-hard","source":"CTET Paper I · DSSSB PRT","questionHi":"अभिकथन (A): मॉन्टेसरी ने सही कार्य के लिए बच्चों को सितारे और पुरस्कार देने की सिफ़ारिश की। कारण (R): मॉन्टेसरी का मत था कि कार्य की अपनी संतुष्टि, स्व-सुधारक सामग्री की सहायता से, पर्याप्त अभिप्रेरणा है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"मॉन्टेसरी ने बाह्य पुरस्कारों और दंडों को अस्वीकार किया; उनका मानना था कि बच्चे उद्देश्यपूर्ण कार्य में संतुष्टि पाते हैं और सामग्री उन्हें अपनी गलतियाँ स्वयं सुधारने देती है।"},
  {"id":"cdp-child-development-698","question":"Froebel’s philosophy was rooted in idealism. Which belief follows from this?","options":["The child's mind is a blank slate on which experience writes everything it knows","Learning is nothing more than conditioning by rewards, so behaviour is shaped from outside","All things form a divine unity, and education helps the child's inner nature unfold","An idea is true only if it works in practice and leads to useful consequences"],"answer":2,"explanation":"Froebel, an idealist, saw a spiritual unity in nature, God and humanity and saw education as the unfolding of the child’s inner nature; the other options belong to empiricism, behaviourism and pragmatism.","difficulty":"hard","source":"KVS PRT · DSSSB PRT","questionHi":"फ्रोबेल का दर्शन आदर्शवाद में निहित था। इससे कौन-सा विश्वास निकलता है?","optionsHi":["बच्चे का मन एक कोरी पट्टिका है जिस पर अनुभव वह सब लिखता है जो वह जानता है","अधिगम पुरस्कार द्वारा अनुबंधन से अधिक कुछ नहीं है, इसलिए व्यवहार बाहर से आकार पाता है","सभी वस्तुएँ एक दैवी एकता बनाती हैं, और शिक्षा बच्चे की आंतरिक प्रकृति के विकसित होने में सहायक होती है","कोई विचार तभी सत्य है जब वह व्यवहार में कारगर हो और उपयोगी परिणामों की ओर ले जाए"],"explanationHi":"आदर्शवादी फ्रोबेल प्रकृति, ईश्वर और मानवता में आध्यात्मिक एकता देखते थे और शिक्षा को बच्चे की आंतरिक प्रकृति के प्रस्फुटन के रूप में देखते थे; अन्य विकल्प अनुभववाद, व्यवहारवाद और प्रयोजनवाद के हैं।"},
  {"id":"cdp-child-development-699","question":"Dewey called his school at the University of Chicago a ‘laboratory school’ because:","options":["It was a place to test and develop educational ideas through actual practice","It taught only science subjects, with most lessons held in its laboratories","It trained young people to work as laboratory assistants for local industry","It carried out controlled experiments on animal learning for the university"],"answer":0,"explanation":"Like a science laboratory, the school was a site where educational theory was tried out, observed and revised in practice with real children.","difficulty":"hard","source":"CTET · KVS TGT","questionHi":"डेवी ने शिकागो विश्वविद्यालय में अपने विद्यालय को ‘प्रयोगशाला विद्यालय’ इसलिए कहा क्योंकि:","optionsHi":["यह वास्तविक अभ्यास के माध्यम से शैक्षिक विचारों का परीक्षण और विकास करने का स्थान था","यह केवल विज्ञान विषय पढ़ाता था, जिसके अधिकांश पाठ प्रयोगशालाओं में होते थे","यह युवाओं को स्थानीय उद्योग के लिए प्रयोगशाला सहायकों के रूप में काम करने का प्रशिक्षण देता था","यह विश्वविद्यालय के लिए पशुओं के अधिगम पर नियंत्रित प्रयोग करता था"],"explanationHi":"विज्ञान प्रयोगशाला की तरह, विद्यालय एक ऐसा स्थान था जहाँ शैक्षिक सिद्धांत को वास्तविक बच्चों के साथ व्यवहार में आज़माया, देखा और संशोधित किया जाता था।"},
  {"id":"cdp-child-development-700","question":"Which of these are features of a good project in the project method? I. It arises from a purpose the learners genuinely feel. II. The learners plan and carry it out. III. The teacher fixes every step in advance. IV. It ends with the learners judging the outcome.","options":["I, II and III only","I, II and IV only","II and III only","I, III and IV only"],"answer":1,"explanation":"Kilpatrick’s project is a ‘wholehearted purposeful activity’: learners purpose, plan, execute and judge it; a teacher who fixes every step turns it into an assignment.","difficulty":"very-hard","source":"CTET Paper II · State TET","questionHi":"प्रोजेक्ट पद्धति में अच्छी परियोजना की विशेषताओं में से कौन-सी हैं? I. यह उस प्रयोजन से उत्पन्न होती है जिसे अधिगमकर्ता वास्तव में अनुभव करते हैं। II. अधिगमकर्ता उसकी योजना बनाते और उसे पूरा करते हैं। III. शिक्षक प्रत्येक चरण पहले से तय करता है। IV. यह अधिगमकर्ताओं द्वारा परिणाम का आकलन करने के साथ समाप्त होती है।","optionsHi":["केवल I, II और III","केवल I, II और IV","केवल II और III","केवल I, III और IV"],"explanationHi":"किलपैट्रिक की परियोजना एक ‘पूर्ण-मन से किया गया उद्देश्यपूर्ण कार्य’ है: अधिगमकर्ता उसका प्रयोजन तय करते हैं, योजना बनाते हैं, निष्पादन करते हैं और मूल्यांकन करते हैं; जो शिक्षक हर चरण तय कर दे वह उसे गृहकार्य बना देता है।"},
  {"id":"cdp-child-development-701","question":"A Class 3 teacher wants children to recall the order in which to solve a long-division sum, and she reads out all eleven steps at once. Most children manage only the first three or four. What is the best explanation and remedy?","options":["Long-term memory is already full; the children should rest before the lesson resumes","The children lack motivation; announce a prize for anyone who remembers all the steps","Working memory holds only a few items; give the steps in small sets with a step chart","Sensory memory lasts for hours; simply repeat all eleven steps again tomorrow"],"answer":2,"explanation":"Working (short-term) memory has a small capacity, roughly 7 ± 2 items for adults and fewer for children. Breaking information into small chunks and giving an external aid reduces the load.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक शिक्षिका चाहती है कि बच्चे लंबे भाग का प्रश्न हल करने का क्रम याद रखें, और वह सभी ग्यारह चरण एक साथ पढ़कर सुना देती है। अधिकांश बच्चे केवल पहले तीन या चार ही याद रख पाते हैं। सबसे अच्छी व्याख्या और उपचार क्या है?","optionsHi":["दीर्घकालिक स्मृति पहले से भरी है; पाठ फिर शुरू करने से पहले बच्चों को विश्राम करना चाहिए","बच्चों में अभिप्रेरणा की कमी है; जो सभी चरण याद रखे उसके लिए पुरस्कार घोषित करें","कार्यकारी स्मृति केवल कुछ मदें थामती है; चरणों को छोटे समूहों में दें और चरण-तालिका के साथ","संवेदी स्मृति घंटों तक रहती है; बस कल सभी ग्यारह चरण फिर दोहरा दें"],"explanationHi":"कार्यकारी (अल्पकालिक) स्मृति की क्षमता छोटी होती है, वयस्कों के लिए लगभग 7 ± 2 मदें और बच्चों के लिए कम। जानकारी को छोटे खंडों में बाँटने और बाह्य सहायता देने से भार घटता है।"},
  {"id":"cdp-child-development-702","question":"Sumit remembers his father's mobile number 9876543210 by saying it as ‘98765 – 43210’. Which memory process makes this easier?","options":["Chunking, which groups items into fewer meaningful units","Proactive interference from numbers learnt earlier","Decay of the sensory trace after a few seconds","Maintenance of iconic memory through visual imagery"],"answer":0,"explanation":"Chunking packs several items into a smaller number of meaningful units, so more information fits within the limited span of short-term memory.","difficulty":"moderate","source":"CTET · REET","questionHi":"सुमित अपने पिता का मोबाइल नंबर 9876543210 इसे ‘98765 – 43210’ के रूप में बोलकर याद रखता है। कौन-सी स्मृति प्रक्रिया इसे आसान बनाती है?","optionsHi":["खंडन (चंकिंग), जो मदों को कम अर्थपूर्ण इकाइयों में समूहित करता है","अग्रोन्मुख व्यवधान, पहले सीखी संख्याओं से","कुछ सेकंड बाद संवेदी चिह्न का क्षय","दृश्य कल्पना द्वारा प्रतिबिंबात्मक स्मृति का रखरखाव"],"explanationHi":"खंडन कई मदों को कम संख्या की अर्थपूर्ण इकाइयों में समेट देता है, जिससे अल्पकालिक स्मृति की सीमित अवधि में अधिक जानकारी समा जाती है।"},
  {"id":"cdp-child-development-703","question":"Three groups of Class 8 students see the same list of words. Group A says whether each word is in capital letters, Group B whether it rhymes with ‘tree’, and Group C whether it fits the sentence ‘She bought a ___ at the market.’ In a surprise recall test, which result is expected and why?","options":["Group A recalls most, because visual features are noticed first and stored most firmly","All groups recall equally, because the exposure time for the words was the same","Group B recalls most, because sound is the main code used by long-term memory","Group C recalls most, because meaning-based processing gives more durable memories"],"answer":3,"explanation":"Craik and Lockhart's levels-of-processing view holds that semantic (meaning) processing yields better retention than shallow structural or phonemic processing.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 के विद्यार्थियों के तीन समूह शब्दों की एक ही सूची देखते हैं। समूह A बताता है कि प्रत्येक शब्द बड़े अक्षरों में है या नहीं, समूह B बताता है कि वह ‘tree’ से तुकबंदी करता है या नहीं, और समूह C बताता है कि वह वाक्य ‘She bought a ___ at the market.’ में बैठता है या नहीं। अचानक स्मरण परीक्षा में कौन-सा परिणाम अपेक्षित है और क्यों?","optionsHi":["समूह A सबसे अधिक याद रखता है, क्योंकि दृश्य विशेषताएँ पहले ध्यान में आती हैं और सबसे दृढ़ता से संचित होती हैं","सभी समूह समान याद रखते हैं, क्योंकि शब्दों के संपर्क का समय समान था","समूह B सबसे अधिक याद रखता है, क्योंकि ध्वनि दीर्घकालिक स्मृति द्वारा प्रयुक्त मुख्य कूट है","समूह C सबसे अधिक याद रखता है, क्योंकि अर्थ-आधारित प्रसंस्करण अधिक टिकाऊ स्मृतियाँ देता है"],"explanationHi":"क्रेक और लॉकहार्ट का प्रसंस्करण-स्तर का मत है कि अर्थगत (अर्थ पर आधारित) प्रसंस्करण उथले संरचनात्मक या ध्वनिगत प्रसंस्करण की तुलना में बेहतर धारण देता है।"},
  {"id":"cdp-child-development-704","question":"Match each memory with its type. P. Knowing how to ride a bicycle  Q. Remembering the school trip to Agra in Class 4  R. Knowing that the Ganga rises at Gangotri  S. Feeling uneasy in a room where one once got scolded, without recalling why. 1. Episodic  2. Semantic  3. Procedural  4. Implicit emotional conditioning","options":["P-1, Q-3, R-2, S-4","P-3, Q-1, R-2, S-4","P-3, Q-2, R-1, S-4","P-4, Q-1, R-2, S-3"],"answer":1,"explanation":"Skills are procedural; personal events located in time are episodic; general facts are semantic; a conditioned emotional reaction without conscious recall is implicit memory.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"प्रत्येक स्मृति का मिलान उसके प्रकार से कीजिए। P. साइकिल चलाना जानना  Q. कक्षा 4 में आगरा की विद्यालयी यात्रा को याद करना  R. यह जानना कि गंगा गंगोत्री से निकलती है  S. उस कमरे में असहज महसूस करना जहाँ कभी डाँट पड़ी थी, बिना यह याद किए कि क्यों। 1. घटनात्मक  2. अर्थगत  3. प्रक्रियात्मक  4. अंतर्निहित भावनात्मक अनुबंधन","optionsHi":["P-1, Q-3, R-2, S-4","P-3, Q-1, R-2, S-4","P-3, Q-2, R-1, S-4","P-4, Q-1, R-2, S-3"],"explanationHi":"कौशल प्रक्रियात्मक हैं; समय में स्थित व्यक्तिगत घटनाएँ घटनात्मक हैं; सामान्य तथ्य अर्थगत हैं; सचेत स्मरण के बिना अनुबंधित भावनात्मक प्रतिक्रिया अंतर्निहित स्मृति है।"},
  {"id":"cdp-child-development-705","question":"In Baddeley's model of working memory, which component directs attention, decides what to focus on and coordinates the other subsystems while a Class 7 student solves a multi-step word problem?","options":["Phonological loop","Visuospatial sketchpad","Central executive","Sensory register"],"answer":2,"explanation":"The central executive is the attentional control system of working memory; the phonological loop holds speech-based information and the sketchpad holds visual and spatial information.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"बैडली के कार्यकारी स्मृति मॉडल में, कक्षा 7 का विद्यार्थी जब बहु-चरणीय शब्द-प्रश्न हल करता है तो कौन-सा घटक ध्यान को निर्देशित करता है, यह तय करता है कि किस पर ध्यान केंद्रित करना है और अन्य उप-प्रणालियों का समन्वय करता है?","optionsHi":["ध्वनिगत पाश","दृश्य-स्थानिक पटल","केंद्रीय कार्यकारी","संवेदी रजिस्टर"],"explanationHi":"केंद्रीय कार्यकारी कार्यकारी स्मृति की ध्यान-नियंत्रण प्रणाली है; ध्वनिगत पाश वाणी-आधारित जानकारी थामता है और पटल दृश्य तथा स्थानिक जानकारी।"},
  {"id":"cdp-child-development-706","question":"Assertion (A): In free recall of a word list, the advantage for the last few words disappears if students do 30 seconds of counting backwards before recalling. Reason (R): The last items are recalled well because they are still held in short-term memory, which is displaced by the distracting task.","options":["A is true but R is false","A is false but R is true","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"The recency effect depends on short-term memory, so a filled delay wipes it out, while the primacy effect (from extra rehearsal into long-term memory) survives.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): शब्द-सूची के मुक्त स्मरण में, यदि विद्यार्थी स्मरण से पहले 30 सेकंड उलटी गिनती करें तो अंतिम कुछ शब्दों का लाभ समाप्त हो जाता है। कारण (R): अंतिम मदें इसलिए अच्छी तरह याद आती हैं क्योंकि वे अभी भी अल्पकालिक स्मृति में हैं, जिसे ध्यान भटकाने वाला कार्य विस्थापित कर देता है।","optionsHi":["A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है"],"explanationHi":"नवीनता प्रभाव अल्पकालिक स्मृति पर निर्भर है, इसलिए भरा हुआ अंतराल उसे मिटा देता है, जबकि प्राथमिकता प्रभाव (दीर्घकालिक स्मृति में अतिरिक्त अभ्यास से) बचा रहता है।"},
  {"id":"cdp-child-development-707","question":"Nisha revised her history notes in her quiet bedroom and knew them well, but in the noisy, unfamiliar examination hall she could not recall several points that came back to her once she got home. This is best explained by:","options":["Decay of memory traces through disuse in the days between revision and the exam","Cue-dependent forgetting, as the retrieval cues present during learning were missing","Retroactive interference from other subjects she revised after her history notes","Repression of anxiety-provoking material, pushed out of awareness by exam stress"],"answer":1,"explanation":"The information was stored (it returned at home) but could not be retrieved without matching cues. Context-dependent, cue-dependent forgetting is a retrieval failure, not loss.","difficulty":"hard","source":"CTET · HTET","questionHi":"निशा ने अपने शांत शयन-कक्ष में अपने इतिहास के नोट्स दोहराए और उन्हें अच्छी तरह जानती थी, पर शोरगुल वाले, अपरिचित परीक्षा-कक्ष में वह कई बिंदु याद नहीं कर पाई जो घर पहुँचने पर वापस याद आ गए। इसकी सबसे अच्छी व्याख्या है:","optionsHi":["पुनरावर्तन और परीक्षा के बीच के दिनों में अनुपयोग से स्मृति-चिह्नों का क्षय","संकेत-निर्भर विस्मरण, क्योंकि सीखते समय उपस्थित पुनःप्राप्ति संकेत अनुपस्थित थे","इतिहास के नोट्स के बाद दोहराए गए अन्य विषयों से पश्चोन्मुख व्यवधान","चिंताजनक सामग्री का दमन, जिसे परीक्षा-तनाव ने चेतना से बाहर धकेल दिया"],"explanationHi":"जानकारी संचित थी (घर पर वह लौट आई) पर मेल खाते संकेतों के बिना पुनःप्राप्त नहीं की जा सकी। संदर्भ-निर्भर, संकेत-निर्भर विस्मरण पुनःप्राप्ति की विफलता है, हानि नहीं।"},
  {"id":"cdp-child-development-708","question":"Two Class 9 students have one hour before a science test next week. Asha re-reads her notes three times. Bilal reads once and then spends the rest of the time closing the book and writing down everything he can recall, checking gaps afterwards. Research on memory predicts that:","options":["Bilal will remember more a week later, because retrieval practice strengthens memory","Asha will remember more, because repeated reading builds strong familiarity with the notes","Both will remember equally, because the time they spent studying was exactly the same","Asha will remember more, because self-testing causes anxiety that blocks later recall"],"answer":0,"explanation":"The testing effect shows that actively retrieving information strengthens long-term retention more than re-reading, which mostly produces a feeling of familiarity.","difficulty":"hard","source":"CTET Paper 2 · NVS TGT","questionHi":"कक्षा 9 के दो विद्यार्थियों के पास अगले सप्ताह की विज्ञान परीक्षा से पहले एक घंटा है। आशा अपने नोट्स तीन बार दोबारा पढ़ती है। बिलाल एक बार पढ़ता है और फिर शेष समय किताब बंद करके जो कुछ याद आए वह सब लिखने में लगाता है, बाद में कमियाँ जाँचता है। स्मृति पर शोध क्या पूर्वानुमान करता है?","optionsHi":["बिलाल को एक सप्ताह बाद अधिक याद रहेगा, क्योंकि पुनःप्राप्ति अभ्यास स्मृति को सुदृढ़ करता है","आशा को अधिक याद रहेगा, क्योंकि बार-बार पढ़ना नोट्स से दृढ़ परिचय बनाता है","दोनों को समान याद रहेगा, क्योंकि उनके अध्ययन में लगा समय बिल्कुल बराबर था","आशा को अधिक याद रहेगा, क्योंकि स्व-परीक्षण चिंता उत्पन्न करता है जो बाद के स्मरण को रोकती है"],"explanationHi":"परीक्षण प्रभाव दिखाता है कि जानकारी को सक्रिय रूप से पुनःप्राप्त करना दोबारा पढ़ने की तुलना में दीर्घकालिक धारण को अधिक सुदृढ़ करता है, जो अधिकतर केवल परिचय का भाव उत्पन्न करता है।"},
  {"id":"cdp-child-development-709","question":"Rani studies spellings for 20 minutes a day for six days; Gauri studies the same spellings for two hours the night before the test. On a test given a month later, which is most likely?","options":["Gauri remembers more, because a long massed session builds stronger memory traces","Both remember the same amount, because their total study time was roughly equal","Rani remembers more, because distributed practice gives better long-term retention","Neither remembers anything, because spellings are almost always forgotten within a month"],"answer":2,"explanation":"The spacing effect: practice spread over time gives better long-term retention than the same amount crammed into one session, even if cramming helps a test the next morning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"रानी छह दिन तक प्रतिदिन 20 मिनट वर्तनी का अध्ययन करती है; गौरी परीक्षा से पहली रात उन्हीं वर्तनियों का दो घंटे अध्ययन करती है। एक महीने बाद ली गई परीक्षा में सबसे संभावित क्या है?","optionsHi":["गौरी को अधिक याद रहेगा, क्योंकि लंबा एकमुश्त सत्र अधिक सुदृढ़ स्मृति-चिह्न बनाता है","दोनों को समान याद रहेगा, क्योंकि उनका कुल अध्ययन-समय लगभग बराबर था","रानी को अधिक याद रहेगा, क्योंकि वितरित अभ्यास बेहतर दीर्घकालिक धारण देता है","किसी को कुछ याद नहीं रहेगा, क्योंकि वर्तनियाँ लगभग हमेशा एक महीने में भुला दी जाती हैं"],"explanationHi":"अंतरालन प्रभाव: समय में फैला अभ्यास उसी मात्रा के एक सत्र में ठूँसे गए अभ्यास से बेहतर दीर्घकालिक धारण देता है, भले ही ठूँसना अगली सुबह की परीक्षा में सहायक हो।"},
  {"id":"cdp-child-development-710","question":"Ebbinghaus's forgetting curve shows that forgetting is not steady over time. What does it imply for when a teacher should first review a new lesson?","options":["After about a month, when most of it is forgotten and relearning is quickest","Only just before the annual examination, so that it is fresh for the paper","Never, because whatever is forgotten was never really learnt in the first place","Soon after the lesson, such as the next day, since the steepest loss is early"],"answer":3,"explanation":"Most forgetting occurs shortly after learning and then levels off. An early review catches material before the steep drop, and later reviews can be spaced further apart.","difficulty":"hard","source":"CTET · UPTET","questionHi":"एबिंगहॉस का विस्मरण वक्र दर्शाता है कि विस्मरण समय के साथ एकसमान नहीं होता। शिक्षक को नए पाठ का पहला पुनरावर्तन कब करना चाहिए, इसके लिए इसका क्या अर्थ है?","optionsHi":["लगभग एक महीने बाद, जब अधिकांश भूल चुका हो और पुनः सीखना सबसे तेज़ हो","केवल वार्षिक परीक्षा से ठीक पहले, ताकि वह प्रश्नपत्र के लिए ताज़ा रहे","कभी नहीं, क्योंकि जो भुला दिया गया वह वास्तव में कभी सीखा ही नहीं गया था","पाठ के कुछ ही समय बाद, जैसे अगले दिन, क्योंकि सबसे तीव्र हानि शुरू में होती है"],"explanationHi":"अधिकांश विस्मरण सीखने के कुछ ही समय बाद होता है और फिर स्थिर हो जाता है। शीघ्र पुनरावर्तन सामग्री को तीव्र गिरावट से पहले पकड़ लेता है, और बाद के पुनरावर्तन अधिक अंतराल पर रखे जा सकते हैं।"},
  {"id":"cdp-child-development-711","question":"A man cannot recall a single line of a Sanskrit shloka he learnt as a child, yet he relearns it in far fewer repetitions than a similar shloka he has never studied. What does this demonstrate?","options":["The memory had completely decayed, so the quick relearning was only chance","Some trace remained in memory, as Ebbinghaus showed with the savings method","Proactive interference from the second shloka slowed down learning of that one","Childhood memories are stored only as procedural memory, not as verbal memory"],"answer":1,"explanation":"Ebbinghaus measured retention by savings: if relearning takes fewer trials than original learning, something was retained even when nothing could be recalled.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"एक व्यक्ति बचपन में सीखे संस्कृत श्लोक की एक भी पंक्ति याद नहीं कर पाता, फिर भी उसे वह किसी ऐसे समान श्लोक की तुलना में, जिसे उसने कभी नहीं पढ़ा, बहुत कम दोहराव में पुनः सीख लेता है। यह क्या दर्शाता है?","optionsHi":["स्मृति पूरी तरह क्षीण हो चुकी थी, इसलिए शीघ्र पुनः सीखना केवल संयोग था","स्मृति में कुछ चिह्न शेष रहा, जैसा एबिंगहॉस ने बचत विधि से दिखाया","दूसरे श्लोक के अग्रोन्मुख व्यवधान ने उसके सीखने को धीमा कर दिया","बचपन की स्मृतियाँ केवल प्रक्रियात्मक स्मृति के रूप में संचित होती हैं, शाब्दिक स्मृति के रूप में नहीं"],"explanationHi":"एबिंगहॉस ने धारण को बचत से मापा: यदि पुनः सीखने में मूल सीखने से कम प्रयास लगते हैं, तो कुछ अवश्य बचा रहा, भले ही कुछ भी याद न आ सके।"},
  {"id":"cdp-child-development-712","question":"The Sharma family changed their landline number six months ago, but when asked for the new number, Mrs Sharma keeps saying the old one. This is an example of:","options":["Proactive interference","Retroactive interference","Motivated forgetting","Decay of the sensory register"],"answer":0,"explanation":"In proactive interference, older learning disrupts the recall of newer learning. Here the old number intrudes on recall of the new one.","difficulty":"hard","source":"CTET Paper 1 · REET","questionHi":"शर्मा परिवार ने छह महीने पहले अपना लैंडलाइन नंबर बदला, पर नया नंबर पूछे जाने पर श्रीमती शर्मा पुराना ही बताती रहती हैं। यह किसका उदाहरण है?","optionsHi":["अग्रोन्मुख व्यवधान","पश्चोन्मुख व्यवधान","प्रेरित विस्मरण","संवेदी रजिस्टर का क्षय"],"explanationHi":"अग्रोन्मुख व्यवधान में पुराना सीखा हुआ नए सीखे हुए के स्मरण में बाधा डालता है। यहाँ पुराना नंबर नए के स्मरण में घुस आता है।"},
  {"id":"cdp-child-development-713","question":"A Class 8 student learns the reigns of the Mughal emperors in the first week and the Delhi Sultanate rulers in the second week. In the third week, when asked about the Mughals, he mixes in Sultanate names and dates. Which kind of forgetting is this?","options":["Proactive interference, since the Mughal rulers were the ones learnt first","Decay, since the Mughal learning is older and has faded with the passage of time","Retroactive interference, since newer learning disrupts recall of the earlier material","Repression, since history lessons are anxiety-provoking and pushed out of awareness"],"answer":2,"explanation":"What matters is which memory is being recalled: when later learning disrupts recall of earlier learning, it is retroactive interference. Recalling the Mughals (older) is disrupted by the Sultanate (newer).","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 का एक विद्यार्थी पहले सप्ताह में मुग़ल सम्राटों के शासनकाल और दूसरे सप्ताह में दिल्ली सल्तनत के शासक सीखता है। तीसरे सप्ताह में, मुग़लों के बारे में पूछे जाने पर वह सल्तनत के नाम और तिथियाँ मिला देता है। यह किस प्रकार का विस्मरण है?","optionsHi":["अग्रोन्मुख व्यवधान, क्योंकि मुग़ल शासक पहले सीखे गए थे","क्षय, क्योंकि मुग़लों का अधिगम पुराना है और समय बीतने से धुंधला पड़ गया है","पश्चोन्मुख व्यवधान, क्योंकि नया अधिगम पहले की सामग्री के स्मरण में बाधा डालता है","दमन, क्योंकि इतिहास के पाठ चिंताजनक होते हैं और चेतना से बाहर धकेल दिए जाते हैं"],"explanationHi":"महत्त्वपूर्ण यह है कि कौन-सी स्मृति याद की जा रही है: जब बाद का अधिगम पहले के अधिगम के स्मरण में बाधा डालता है, तो वह पश्चोन्मुख व्यवधान है। मुग़लों (पुराने) का स्मरण सल्तनत (नए) से बाधित होता है।"},
  {"id":"cdp-child-development-714","question":"During an oral quiz, Arnav is sure he knows the name of the river on which Hirakud dam is built; he says it begins with ‘Maha’ and is a long name, but cannot produce it until a classmate whispers it. This tip-of-the-tongue state shows that:","options":["The information was never properly encoded into memory in the first place","The information has decayed completely from long-term memory over time","He is unconsciously motivated to forget it because quizzes make him anxious","The information is stored but temporarily inaccessible: a retrieval failure"],"answer":3,"explanation":"Partial recall (the first part of the word) proves the word is in memory; the problem is retrieval. The cue from a classmate immediately unlocks it. (The river is the Mahanadi.)","difficulty":"moderate","source":"CTET · DSSSB PRT","questionHi":"मौखिक प्रश्नोत्तरी के दौरान अर्णव को पक्का पता है कि हीराकुंड बाँध किस नदी पर बना है; वह कहता है कि उसका नाम ‘महा’ से शुरू होता है और लंबा है, पर जब तक कोई सहपाठी फुसफुसाकर बता नहीं देता वह उसे बोल नहीं पाता। यह ज़बान पर होने की स्थिति दर्शाती है कि:","optionsHi":["जानकारी को पहले स्थान पर स्मृति में ठीक से संकेतित ही नहीं किया गया था","जानकारी दीर्घकालिक स्मृति से समय के साथ पूरी तरह क्षीण हो गई है","वह अचेतन रूप से उसे भूलने के लिए प्रेरित है क्योंकि प्रश्नोत्तरी उसे चिंतित करती है","जानकारी संचित है पर अस्थायी रूप से अप्राप्य है: पुनःप्राप्ति की विफलता"],"explanationHi":"आंशिक स्मरण (शब्द का पहला भाग) सिद्ध करता है कि शब्द स्मृति में है; समस्या पुनःप्राप्ति की है। सहपाठी का संकेत उसे तुरंत खोल देता है। (नदी महानदी है।)"},
  {"id":"cdp-child-development-715","question":"In a classic study, students who slept after learning nonsense syllables recalled more after eight hours than students who stayed awake and went about their daily activities. Which explanation of forgetting does this most support?","options":["Interference from intervening activity, rather than the simple passage of time","Decay, since an equal amount of time passed for both groups of students","Motivated forgetting of material that the waking students found unpleasant","Lack of initial encoding, since the awake group paid less attention while learning"],"answer":0,"explanation":"Jenkins and Dallenbach found less forgetting after sleep. If time alone caused decay both groups should be equal; the awake group forgot more because of interfering experiences.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"एक क्लासिक अध्ययन में, निरर्थक अक्षर-समूह सीखने के बाद सोने वाले विद्यार्थियों को आठ घंटे बाद, जागते रहने और दैनिक गतिविधियाँ करने वाले विद्यार्थियों से अधिक याद रहा। यह विस्मरण की किस व्याख्या का सबसे अधिक समर्थन करता है?","optionsHi":["मध्यवर्ती गतिविधि से व्यवधान, केवल समय के बीतने से नहीं","क्षय, क्योंकि दोनों समूहों के विद्यार्थियों के लिए समान समय बीता","उस सामग्री का प्रेरित विस्मरण जिसे जागने वाले विद्यार्थियों ने अप्रिय पाया","आरंभिक संकेतन का अभाव, क्योंकि जागने वाले समूह ने सीखते समय कम ध्यान दिया"],"explanationHi":"जेनकिंस और डैलेनबैक ने नींद के बाद कम विस्मरण पाया। यदि केवल समय से क्षय होता तो दोनों समूह बराबर होते; जागने वाला समूह हस्तक्षेप करने वाले अनुभवों के कारण अधिक भूला।"},
  {"id":"cdp-child-development-716","question":"While reading a passage, Class 6 student Lata stops, asks herself whether she has understood the paragraph, realises she has not, and decides to re-read it slowly and underline key words. This shows:","options":["Automaticity: reading fluently without needing conscious effort","Metacognition: monitoring and regulating one's own thinking","Proactive interference: earlier reading disrupting new reading","Classical conditioning: a learned response to a reading cue"],"answer":1,"explanation":"Metacognition (Flavell) is awareness and control of one's own cognitive processes: checking comprehension and changing strategy are its two core parts.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"गद्यांश पढ़ते समय कक्षा 6 की विद्यार्थी लता रुकती है, स्वयं से पूछती है कि क्या उसने अनुच्छेद समझा है, पाती है कि नहीं समझा, और उसे धीरे-धीरे दोबारा पढ़ने तथा मुख्य शब्दों को रेखांकित करने का निर्णय लेती है। यह दर्शाता है:","optionsHi":["स्वचालितता: बिना सचेत प्रयास के धाराप्रवाह पढ़ना","अधिसंज्ञान: अपनी स्वयं की सोच की निगरानी और नियमन करना","अग्रोन्मुख व्यवधान: पहले का पठन नए पठन में बाधा डालना","शास्त्रीय अनुबंधन: पठन-संकेत के प्रति सीखी हुई अनुक्रिया"],"explanationHi":"अधिसंज्ञान (फ्लावेल) अपनी संज्ञानात्मक प्रक्रियाओं की जागरूकता और नियंत्रण है: बोध की जाँच करना और युक्ति बदलना इसके दो मूल भाग हैं।"},
  {"id":"cdp-child-development-717","question":"Assertion (A): Children who still decode words letter by letter often understand little of what they read, even short passages. Reason (R): Slow decoding uses up most of the limited capacity of working memory, leaving little for comprehension.","options":["A is true but R is false","A is false but R is true","Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A"],"answer":2,"explanation":"When basic skills become automatic they need little working-memory capacity, freeing it for meaning. Effortful decoding consumes the capacity that comprehension needs.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): जो बच्चे अब भी शब्दों को अक्षर-दर-अक्षर डिकोड करते हैं, वे प्रायः जो पढ़ते हैं, यहाँ तक कि छोटे गद्यांश भी, उसमें से बहुत कम समझ पाते हैं। कारण (R): धीमी डिकोडिंग कार्यकारी स्मृति की सीमित क्षमता का अधिकांश भाग खर्च कर देती है, जिससे बोध के लिए बहुत कम क्षमता बचती है।","optionsHi":["A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है"],"explanationHi":"जब मूल कौशल स्वचालित हो जाते हैं तो उन्हें कम कार्यकारी स्मृति क्षमता चाहिए, जो अर्थ के लिए मुक्त हो जाती है। श्रमसाध्य डिकोडिंग वह क्षमता खा जाती है जो बोध को चाहिए।"},
  {"id":"cdp-child-development-718","question":"To remember that the French word ‘pain’ means bread, a student imagines a loaf of bread that causes him pain when it falls on his foot. Which memory aid is this?","options":["Method of loci","Acronym","Rote rehearsal","Keyword method"],"answer":3,"explanation":"The keyword method links a foreign word to a similar-sounding familiar word and an interactive image of its meaning. The method of loci places items in familiar locations; an acronym uses first letters.","difficulty":"hard","source":"KVS TGT · DSSSB TGT","questionHi":"फ्रेंच शब्द ‘pain’ का अर्थ रोटी है, यह याद रखने के लिए एक विद्यार्थी कल्पना करता है कि रोटी का एक टुकड़ा उसके पैर पर गिरने से उसे दर्द (pain) होता है। यह कौन-सी स्मरण-सहायता है?","optionsHi":["स्थान-विधि (मेथड ऑफ़ लोकाई)","संक्षिप्त नाम (एक्रोनिम)","रटंत पुनरावृत्ति","कुंजी-शब्द विधि (कीवर्ड मेथड)"],"explanationHi":"कुंजी-शब्द विधि किसी विदेशी शब्द को मिलते-जुलते उच्चारण वाले परिचित शब्द और उसके अर्थ की अंतःक्रियात्मक छवि से जोड़ती है। स्थान-विधि मदों को परिचित स्थानों में रखती है; संक्षिप्त नाम प्रथम अक्षरों का उपयोग करता है।"},
  {"id":"cdp-child-development-719","question":"After Class 3 children can say the table of 7 without error, the teacher continues short practice of it for a few more days. Psychologically, this extra practice:","options":["Is overlearning, which improves long-term retention and makes recall automatic","Is wasteful, since learning is complete at the very first error-free recall","Causes retroactive interference with the table of 6 learnt earlier in the term","Reduces children's motivation through boredom, and therefore weakens memory"],"answer":0,"explanation":"Practice beyond the point of first mastery (overlearning) slows forgetting and builds automaticity, especially for basic facts used repeatedly.","difficulty":"hard","source":"CTET · REET","questionHi":"कक्षा 3 के बच्चे जब 7 का पहाड़ा बिना त्रुटि बोलने लगते हैं, तो शिक्षिका कुछ और दिन उसका छोटा अभ्यास जारी रखती है। मनोवैज्ञानिक दृष्टि से यह अतिरिक्त अभ्यास:","optionsHi":["अतिशिक्षण (ओवरलर्निंग) है, जो दीर्घकालिक धारण सुधारता है और स्मरण को स्वचालित बनाता है","व्यर्थ है, क्योंकि पहली त्रुटिहीन स्मृति पर ही सीखना पूर्ण हो जाता है","सत्र में पहले सीखे गए 6 के पहाड़े के साथ पश्चोन्मुख व्यवधान उत्पन्न करता है","ऊब द्वारा बच्चों की अभिप्रेरणा घटाता है, और इसलिए स्मृति को कमज़ोर करता है"],"explanationHi":"पहली निपुणता के बिंदु के बाद का अभ्यास (अतिशिक्षण) विस्मरण को धीमा करता है और स्वचालितता बनाता है, विशेषकर उन मूल तथ्यों के लिए जिनका बार-बार उपयोग होता है।"},
  {"id":"cdp-child-development-720","question":"Many Class 6 students answer a multiple-choice item on the capital of Meghalaya correctly but leave the same question blank when it appears as a fill-in-the-blank. The most likely reason is that:","options":["Multiple-choice items really test a different subject from fill-in-the-blank items","Recognition needs less retrieval effort than recall, because the cue is supplied","Students forget faster when they are taking a fill-in-the-blank type of test","Recall tests measure only short-term memory, not what is held in long-term memory"],"answer":1,"explanation":"In recognition the correct answer is present as a cue, so a weaker trace can be enough; recall requires the learner to generate it unaided, so it is harder.","difficulty":"moderate","source":"CTET Paper 2 · NVS TGT","questionHi":"कक्षा 6 के कई विद्यार्थी मेघालय की राजधानी वाले बहुविकल्पीय प्रश्न का सही उत्तर देते हैं, पर वही प्रश्न रिक्त-स्थान पूर्ति के रूप में आने पर खाली छोड़ देते हैं। सबसे संभावित कारण है कि:","optionsHi":["बहुविकल्पीय प्रश्न वास्तव में रिक्त-स्थान प्रश्नों से भिन्न विषय की परीक्षा लेते हैं","पहचान को स्मरण से कम पुनःप्राप्ति प्रयास चाहिए, क्योंकि संकेत प्रदान किया गया होता है","रिक्त-स्थान प्रकार की परीक्षा देते समय विद्यार्थी अधिक तेज़ी से भूलते हैं","स्मरण परीक्षाएँ केवल अल्पकालिक स्मृति मापती हैं, दीर्घकालिक स्मृति में जो है उसे नहीं"],"explanationHi":"पहचान में सही उत्तर संकेत के रूप में उपस्थित होता है, इसलिए कमज़ोर चिह्न भी पर्याप्त हो सकता है; स्मरण में अधिगमकर्ता को उसे बिना सहायता के उत्पन्न करना होता है, इसलिए वह कठिन है।"},
  {"id":"cdp-child-development-721","question":"A Class 7 science worksheet shows a diagram of the heart with numbers 1–10, and the explanation of each numbered part is printed on the next page. Students struggle. What is the best change according to cognitive load research?","options":["Add more decorative pictures and colours to make the page more attractive","Ask students to memorise the ten numbers and their parts before the lesson","Place short labels and explanations directly next to the parts on the diagram","Remove the diagram altogether and keep only the written text explanations"],"answer":2,"explanation":"Splitting related information forces learners to hold one source in working memory while searching for the other (split-attention). Integrating labels with the diagram reduces this extraneous load.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"कक्षा 7 के विज्ञान कार्य-पत्रक में हृदय का आरेख है जिसमें 1–10 संख्याएँ हैं, और प्रत्येक संख्यांकित भाग की व्याख्या अगले पृष्ठ पर छपी है। विद्यार्थी संघर्ष करते हैं। संज्ञानात्मक भार संबंधी शोध के अनुसार सबसे अच्छा परिवर्तन क्या है?","optionsHi":["पृष्ठ को अधिक आकर्षक बनाने के लिए अधिक सजावटी चित्र और रंग जोड़ना","विद्यार्थियों से पाठ से पहले दस संख्याएँ और उनके भाग रटने को कहना","आरेख पर ही भागों के ठीक बगल में संक्षिप्त नामपट्टिकाएँ और व्याख्याएँ रखना","आरेख को पूरी तरह हटा देना और केवल लिखित पाठ-व्याख्याएँ रखना"],"explanationHi":"संबंधित जानकारी को बाँट देना अधिगमकर्ताओं को एक स्रोत कार्यकारी स्मृति में रखकर दूसरे को खोजने के लिए बाध्य करता है (विभक्त ध्यान)। नामपट्टिकाओं को आरेख के साथ एकीकृत करने से यह बाह्य भार घटता है।"},
  {"id":"cdp-child-development-722","question":"A teacher explains the water cycle while pointing to a simple labelled diagram, rather than using only words. Paivio's dual coding theory explains the benefit as follows:","options":["Pictures distract attention from the words, so they should generally be avoided","Images are processed only in short-term memory and never reach long-term memory","The diagram helps only the ‘visual learners’ in the class, not the others","Information coded both verbally and visually has two retrieval routes"],"answer":3,"explanation":"Dual coding theory holds that verbal and imaginal codes are separate but linked systems; encoding in both increases the chance of later retrieval for learners generally.","difficulty":"hard","source":"CTET · HTET","questionHi":"एक शिक्षक केवल शब्दों के बजाय एक सरल नामांकित आरेख की ओर इशारा करते हुए जल-चक्र समझाता है। पेइवियो का द्वि-कूटन सिद्धांत इसके लाभ को इस प्रकार समझाता है:","optionsHi":["चित्र शब्दों से ध्यान भटकाते हैं, इसलिए सामान्यतः उनसे बचना चाहिए","छवियों का प्रसंस्करण केवल अल्पकालिक स्मृति में होता है और वे कभी दीर्घकालिक स्मृति तक नहीं पहुँचतीं","आरेख केवल कक्षा के ‘दृश्य अधिगमकर्ताओं’ की सहायता करता है, दूसरों की नहीं","जो जानकारी शाब्दिक और दृश्य दोनों रूप में संकेतित होती है उसके पुनःप्राप्ति के दो मार्ग होते हैं"],"explanationHi":"द्वि-कूटन सिद्धांत मानता है कि शाब्दिक और कल्पनात्मक कूट पृथक पर परस्पर जुड़ी प्रणालियाँ हैं; दोनों में संकेतन करने से सामान्यतः अधिगमकर्ताओं के लिए बाद में पुनःप्राप्ति की संभावना बढ़ती है।"},
  {"id":"cdp-child-development-723","question":"According to the information processing model, which of these statements are correct? I. Information in the sensory register is lost within seconds unless it is attended to. II. Attention decides what moves from the sensory register into working memory. III. Long-term memory has a very small capacity of about seven items. IV. Elaborative encoding helps transfer information from working memory into long-term memory.","options":["I, II and IV only","I and III only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"The 7 ± 2 limit applies to short-term (working) memory; long-term memory is thought to have practically unlimited capacity, so III is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"सूचना प्रसंस्करण मॉडल के अनुसार, इनमें से कौन-से कथन सही हैं? I. संवेदी रजिस्टर में जानकारी, यदि उस पर ध्यान न दिया जाए, तो कुछ सेकंड में खो जाती है। II. ध्यान तय करता है कि संवेदी रजिस्टर से कार्यकारी स्मृति में क्या जाता है। III. दीर्घकालिक स्मृति की क्षमता बहुत छोटी, लगभग सात मदों की होती है। IV. विस्तारात्मक संकेतन जानकारी को कार्यकारी स्मृति से दीर्घकालिक स्मृति में स्थानांतरित करने में सहायता करता है।","optionsHi":["केवल I, II और IV","केवल I और III","केवल II, III और IV","I, II, III और IV"],"explanationHi":"7 ± 2 की सीमा अल्पकालिक (कार्यकारी) स्मृति पर लागू होती है; दीर्घकालिक स्मृति की क्षमता व्यावहारिक रूप से असीमित मानी जाती है, इसलिए III असत्य है।"},
  {"id":"cdp-child-development-724","question":"A teacher flashes a card with twelve letters for half a second. Children say they ‘saw them all’ but can report only four or five before the image fades. This illustrates the:","options":["Limited capacity of long-term memory for letters","Very brief duration of iconic (visual sensory) memory","Primacy effect favouring the first letters seen","Retroactive interference from the later letters"],"answer":1,"explanation":"Iconic memory briefly holds a large amount of visual information but fades in well under a second, so only what is attended to quickly can be reported.","difficulty":"moderate","source":"CTET Paper 1 · Super TET","questionHi":"एक शिक्षक बारह अक्षरों वाला कार्ड आधे सेकंड के लिए दिखाता है। बच्चे कहते हैं कि उन्होंने ‘सब देखे’ पर छवि के धुँधली होने से पहले केवल चार या पाँच ही बता पाते हैं। यह किसे दर्शाता है?","optionsHi":["अक्षरों के लिए दीर्घकालिक स्मृति की सीमित क्षमता","प्रतिबिंबात्मक (दृश्य संवेदी) स्मृति की बहुत संक्षिप्त अवधि","पहले देखे गए अक्षरों के पक्ष में प्राथमिकता प्रभाव","बाद के अक्षरों से पश्चोन्मुख व्यवधान"],"explanationHi":"प्रतिबिंबात्मक स्मृति थोड़ी देर के लिए बड़ी मात्रा में दृश्य जानकारी थामती है पर एक सेकंड से बहुत कम में धुँधली हो जाती है, इसलिए वही बताया जा सकता है जिस पर शीघ्रता से ध्यान दिया गया।"},
  {"id":"cdp-child-development-725","question":"Children forget an embarrassing incident in which they wet their clothes during a school function, though they remember the rest of the function clearly. Freud would explain this selective loss as:","options":["Proactive interference from earlier functions","Decay of the memory trace through disuse","Motivated forgetting, or repression","Cue overload from too many similar events"],"answer":2,"explanation":"Motivated forgetting (repression in Freudian terms) is the pushing of painful or anxiety-provoking memories out of awareness, which explains why only the embarrassing part is lost.","difficulty":"moderate","source":"CTET · UPTET","questionHi":"बच्चे विद्यालय के किसी समारोह में कपड़े गीले हो जाने की शर्मनाक घटना भूल जाते हैं, जबकि समारोह का शेष भाग स्पष्ट रूप से याद रखते हैं। फ्रायड इस चयनात्मक हानि की व्याख्या कैसे करते?","optionsHi":["पहले के समारोहों से अग्रोन्मुख व्यवधान","अनुपयोग से स्मृति-चिह्न का क्षय","प्रेरित विस्मरण, या दमन","बहुत-सी समान घटनाओं से संकेत-अतिभार"],"explanationHi":"प्रेरित विस्मरण (फ्रायडीय शब्दों में दमन) पीड़ादायक या चिंताजनक स्मृतियों को चेतना से बाहर धकेलना है, जो समझाता है कि केवल शर्मनाक भाग ही क्यों खोया।"},
  {"id":"cdp-child-development-726","question":"Mayer and Salovey’s ability model describes emotional intelligence in four branches. Which of the following is NOT one of these four branches?","options":["Perceiving emotions accurately","Using emotions to facilitate thinking","Self-motivation in the face of setbacks","Managing emotions in oneself and others"],"answer":2,"explanation":"The four branches are perceiving, using, understanding and managing emotions. ‘Motivation’ is one of the domains in Goleman’s popular mixed model, not a Mayer–Salovey branch.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"मेयर और सैलोवे का क्षमता मॉडल भावनात्मक बुद्धि को चार शाखाओं में वर्णित करता है। निम्नलिखित में से कौन-सी इन चार शाखाओं में नहीं है?","optionsHi":["भावनाओं को सटीक रूप से अवगत करना","चिंतन को सुगम बनाने के लिए भावनाओं का उपयोग करना","असफलताओं के सामने आत्म-अभिप्रेरणा","स्वयं और दूसरों में भावनाओं का प्रबंधन"],"explanationHi":"चार शाखाएँ हैं: भावनाओं को अवगत करना, उनका उपयोग करना, समझना और प्रबंधित करना। ‘अभिप्रेरणा’ गोलमैन के लोकप्रिय मिश्रित मॉडल के क्षेत्रों में से एक है, मेयर–सैलोवे की शाखा नहीं।"},
  {"id":"cdp-child-development-727","question":"Assertion (A): Schools can strengthen students’ emotional intelligence through planned social-emotional learning activities. Reason (R): Emotional intelligence is a fixed inborn trait that does not change with experience.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Skills such as recognising and regulating emotions and showing empathy can be taught and practised; if R were true, A would be impossible, so R is false.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"अभिकथन (A): विद्यालय नियोजित सामाजिक-भावनात्मक अधिगम गतिविधियों द्वारा विद्यार्थियों की भावनात्मक बुद्धि को सुदृढ़ कर सकते हैं। कारण (R): भावनात्मक बुद्धि एक निश्चित जन्मजात गुण है जो अनुभव से नहीं बदलता।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"भावनाओं को पहचानने और नियमित करने तथा सहानुभूति दिखाने जैसे कौशल सिखाए और अभ्यास किए जा सकते हैं; यदि R सत्य होता तो A असंभव होता, इसलिए R असत्य है।"},
  {"id":"cdp-child-development-728","question":"Riya notices that her friend Ayesha, usually chatty, has been silent since morning. Without being told, Riya guesses that something has upset her, sits beside her at lunch and listens. In Goleman’s model, Riya is mainly showing:","options":["Self-regulation","Empathy","Self-awareness","Self-motivation"],"answer":1,"explanation":"Empathy is sensing and understanding other people’s feelings; the other three domains in the options concern one’s own emotions and drive.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"रिया देखती है कि उसकी मित्र आयशा, जो सामान्यतः बातूनी है, सुबह से चुप है। बिना बताए रिया अनुमान लगाती है कि किसी बात ने उसे परेशान किया है, दोपहर के भोजन में उसके पास बैठती है और उसकी बात सुनती है। गोलमैन के मॉडल में रिया मुख्यतः क्या दिखा रही है?","optionsHi":["आत्म-नियमन","सहानुभूति","आत्म-जागरूकता","आत्म-अभिप्रेरणा"],"explanationHi":"सहानुभूति दूसरे लोगों की भावनाओं को भाँपना और समझना है; विकल्पों के अन्य तीन क्षेत्र अपनी भावनाओं और प्रेरणा से संबंधित हैं।"},
  {"id":"cdp-child-development-729","question":"On sports day in a Guwahati school, two house groups start quarrelling over a disputed relay result. The Class 10 captain calms both sides, gets them to agree on a re-run and keeps both teams in good spirits. In Goleman’s model of emotional intelligence, this mainly reflects:","options":["Self-awareness of his own feelings","Self-motivation towards his goals","Empathy alone, sensing others' moods","Social skills (managing relationships)"],"answer":3,"explanation":"Handling conflict, negotiating and influencing groups is Goleman’s social-skills domain; empathy is part of what makes it possible, but resolving the dispute goes beyond merely sensing others’ feelings.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"गुवाहाटी के एक विद्यालय में खेल दिवस पर दो सदन-समूह एक विवादित रिले परिणाम को लेकर झगड़ने लगते हैं। कक्षा 10 का कप्तान दोनों पक्षों को शांत करता है, उन्हें पुनः दौड़ के लिए सहमत कराता है और दोनों टीमों का उत्साह बनाए रखता है। गोलमैन के भावनात्मक बुद्धि मॉडल में यह मुख्यतः किसे दर्शाता है?","optionsHi":["अपनी भावनाओं की आत्म-जागरूकता","अपने लक्ष्यों की ओर आत्म-अभिप्रेरणा","केवल सहानुभूति, दूसरों के मनोभाव भाँपना","सामाजिक कौशल (संबंधों का प्रबंधन)"],"explanationHi":"संघर्ष सँभालना, समझौता कराना और समूहों को प्रभावित करना गोलमैन का सामाजिक कौशल क्षेत्र है; सहानुभूति इसे संभव बनाने का एक भाग है, पर विवाद सुलझाना केवल दूसरों की भावनाएँ भाँपने से आगे जाता है।"},
  {"id":"cdp-child-development-730","question":"Which of the following statements about Alfred Binet’s work are correct? I. The Binet–Simon scale (1905) was developed to identify children who needed special help in school. II. Binet introduced the idea of mental age. III. Binet held that intelligence is fixed and cannot be improved by education. IV. Binet himself coined the formula IQ = MA ÷ CA × 100.","options":["I and II only","I, II and III only","II and IV only","I, II and IV only"],"answer":0,"explanation":"Binet built his scale for the French schools to find children needing help and used the idea of mental age. He warned against seeing intelligence as fixed; the quotient idea came from William Stern and the ×100 form from Lewis Terman.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"अल्फ्रेड बिने के कार्य के बारे में निम्नलिखित में से कौन-से कथन सही हैं? I. बिने–साइमन मापनी (1905) उन बच्चों की पहचान के लिए बनाई गई थी जिन्हें विद्यालय में विशेष सहायता चाहिए थी। II. बिने ने मानसिक आयु का विचार प्रस्तुत किया। III. बिने का मत था कि बुद्धि निश्चित है और शिक्षा से सुधारी नहीं जा सकती। IV. बिने ने स्वयं सूत्र IQ = MA ÷ CA × 100 गढ़ा।","optionsHi":["केवल I और II","केवल I, II और III","केवल II और IV","केवल I, II और IV"],"explanationHi":"बिने ने अपनी मापनी फ्रांसीसी विद्यालयों के लिए सहायता की आवश्यकता वाले बच्चों को खोजने हेतु बनाई और मानसिक आयु के विचार का प्रयोग किया। उन्होंने बुद्धि को निश्चित मानने के प्रति चेताया; भागफल का विचार विलियम स्टर्न का था और ×100 रूप लुईस टर्मन का।"},
  {"id":"cdp-child-development-731","question":"Match the psychologist with the contribution: 1. William Stern 2. Lewis Terman 3. David Wechsler 4. Alfred Binet; a. Stanford–Binet test and the IQ multiplied by 100 b. Proposed the intelligence quotient as mental age divided by chronological age c. First practical intelligence scale with Simon d. Deviation IQ and separate verbal and performance scales","options":["1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d","1-b, 2-a, 3-d, 4-c","1-c, 2-a, 3-d, 4-b"],"answer":2,"explanation":"Stern proposed the quotient MA/CA, Terman revised Binet’s test at Stanford and multiplied by 100, Wechsler introduced the deviation IQ with verbal and performance sub-scales, and Binet and Simon built the first practical scale.","difficulty":"hard","source":"CTET · KVS PGT","questionHi":"मनोवैज्ञानिक का मिलान योगदान से कीजिए: 1. विलियम स्टर्न 2. लुईस टर्मन 3. डेविड वेश्लर 4. अल्फ्रेड बिने; a. स्टैनफ़ोर्ड–बिने परीक्षण और 100 से गुणा किया गया IQ b. बुद्धि-लब्धि को मानसिक आयु भाग कालानुक्रमिक आयु के रूप में प्रस्तावित किया c. साइमन के साथ पहली व्यावहारिक बुद्धि मापनी d. विचलन IQ और पृथक शाब्दिक तथा निष्पादन मापनियाँ","optionsHi":["1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d","1-b, 2-a, 3-d, 4-c","1-c, 2-a, 3-d, 4-b"],"explanationHi":"स्टर्न ने भागफल MA/CA प्रस्तावित किया, टर्मन ने स्टैनफ़ोर्ड में बिने का परीक्षण संशोधित किया और 100 से गुणा किया, वेश्लर ने शाब्दिक और निष्पादन उप-मापनियों के साथ विचलन IQ प्रस्तुत किया, और बिने तथा साइमन ने पहली व्यावहारिक मापनी बनाई।"},
  {"id":"cdp-child-development-732","question":"If the classic ratio-IQ formula is applied to a 32-year-old whose measured mental age is 16, it gives an IQ of 50. This result is misleading mainly because:","options":["Mental age, as these tests measure it, stops rising in late adolescence, so adults look less able","Adults always have higher mental ages than chronological ages, so the score should be above 100","The formula should multiply the two ages rather than divide one by the other to give the IQ","Intelligence tests cannot validly be given to adults at all, so any adult score is meaningless"],"answer":0,"explanation":"Mental-age scores level off around the mid to late teens, so the ratio falls steadily with age for everyone. The deviation IQ, which compares a person with others of the same age, removes this problem.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"यदि क्लासिक अनुपात-IQ सूत्र किसी 32 वर्ष के व्यक्ति पर लागू किया जाए जिसकी मापी गई मानसिक आयु 16 है, तो यह 50 का IQ देता है। यह परिणाम मुख्यतः भ्रामक क्यों है?","optionsHi":["इन परीक्षणों द्वारा मापी जाने वाली मानसिक आयु किशोरावस्था के अंत में बढ़ना बंद कर देती है, इसलिए वयस्क कम सक्षम दिखते हैं","वयस्कों की मानसिक आयु सदैव कालानुक्रमिक आयु से अधिक होती है, इसलिए अंक 100 से ऊपर होना चाहिए","IQ देने के लिए सूत्र में एक आयु को दूसरी से भाग देने के बजाय दोनों आयुओं को गुणा करना चाहिए","बुद्धि परीक्षण वयस्कों पर वैध रूप से दिए ही नहीं जा सकते, इसलिए कोई भी वयस्क अंक निरर्थक है"],"explanationHi":"मानसिक-आयु के अंक किशोरावस्था के मध्य से अंत के आसपास स्थिर हो जाते हैं, इसलिए अनुपात सभी के लिए आयु के साथ लगातार गिरता है। विचलन IQ, जो किसी व्यक्ति की तुलना समान आयु के अन्य लोगों से करता है, इस समस्या को दूर करता है।"},
  {"id":"cdp-child-development-733","question":"Arjun, 11, scores 68 on an individual intelligence test, but he manages money at his family’s shop, travels alone by bus, cooks simple meals and gets along well with others. Which conclusion is most appropriate?","options":["He must be classed as having intellectual disability, since his IQ score is below 70","He should be placed in a special school straight away, without any further assessment","The score is irrelevant, because IQ tests have no value at all in such decisions","An IQ score alone cannot establish it; significant adaptive limitations must also exist"],"answer":3,"explanation":"Standard definitions of intellectual disability require significant limitations in both intellectual functioning and adaptive behaviour, beginning in the developmental period; good adaptive functioning argues against the label and the score may also contain error.","difficulty":"very-hard","source":"CTET Paper 2 · KVS PGT","questionHi":"11 वर्ष का अर्जुन एक व्यक्तिगत बुद्धि परीक्षण में 68 अंक पाता है, पर वह अपने परिवार की दुकान पर पैसों का प्रबंधन करता है, अकेले बस से यात्रा करता है, सरल भोजन पकाता है और दूसरों के साथ अच्छी तरह घुल-मिल जाता है। कौन-सा निष्कर्ष सबसे उपयुक्त है?","optionsHi":["उसे बौद्धिक अक्षमता वाला माना जाना चाहिए, क्योंकि उसका IQ अंक 70 से कम है","उसे बिना किसी और आकलन के तुरंत विशेष विद्यालय में रखा जाना चाहिए","अंक अप्रासंगिक है, क्योंकि ऐसे निर्णयों में IQ परीक्षणों का कोई मूल्य नहीं है","केवल IQ अंक इसे स्थापित नहीं कर सकता; अनुकूली व्यवहार में उल्लेखनीय सीमाएँ भी होनी चाहिए"],"explanationHi":"बौद्धिक अक्षमता की मानक परिभाषाओं में बौद्धिक कार्यप्रणाली और अनुकूली व्यवहार दोनों में उल्लेखनीय सीमाएँ चाहिए, जो विकासात्मक अवधि में आरंभ हुई हों; अच्छा अनुकूली कार्य-व्यवहार इस लेबल के विरुद्ध तर्क देता है और अंक में त्रुटि भी हो सकती है।"},
  {"id":"cdp-child-development-734","question":"A school counsellor must decide whether one particular Class 3 child needs special educational support. Which type of intelligence test is most suitable, and why?","options":["A group verbal test, because it is quick, cheap and easy to score for any child","An individual test, since the examiner can observe the child and probe her answers","A group non-verbal test, because individual tests are always biased against children","No test at all, because intelligence cannot be measured in any meaningful way"],"answer":1,"explanation":"Group tests suit large-scale screening; decisions about one child need individual testing (along with other information), where the examiner can watch attention, anxiety and strategies.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक विद्यालय परामर्शदाता को तय करना है कि कक्षा 3 के किसी विशेष बच्चे को विशेष शैक्षिक सहायता की आवश्यकता है या नहीं। किस प्रकार का बुद्धि परीक्षण सबसे उपयुक्त है, और क्यों?","optionsHi":["समूह शाब्दिक परीक्षण, क्योंकि वह किसी भी बच्चे के लिए शीघ्र, सस्ता और अंक देने में आसान है","व्यक्तिगत परीक्षण, क्योंकि परीक्षक बच्ची को देख सकता है और उसके उत्तरों की पड़ताल कर सकता है","समूह अशाब्दिक परीक्षण, क्योंकि व्यक्तिगत परीक्षण बच्चों के विरुद्ध सदैव पक्षपाती होते हैं","कोई परीक्षण नहीं, क्योंकि बुद्धि को किसी सार्थक ढंग से मापा नहीं जा सकता"],"explanationHi":"समूह परीक्षण बड़े पैमाने की छँटनी के लिए उपयुक्त हैं; एक बच्चे के बारे में निर्णयों के लिए (अन्य जानकारी के साथ) व्यक्तिगत परीक्षण चाहिए, जहाँ परीक्षक ध्यान, चिंता और युक्तियों को देख सकता है।"},
  {"id":"cdp-child-development-735","question":"Bhatia’s Battery of Performance Tests, developed in India, would be especially suitable for assessing the intelligence of:","options":["A child who cannot read and has limited command of the test-giver's language","A college student applying for a merit scholarship in an English-medium course","A child who must be compared with classmates on reading speed and accuracy","A child already diagnosed using a verbal test, to confirm the same verbal score"],"answer":0,"explanation":"Performance tests use tasks such as block designs and pattern drawing that need little language or literacy, so they suit non-literate children or those with limited proficiency in the testing language.","difficulty":"very-hard","source":"KVS PGT · State TET","questionHi":"भारत में विकसित भाटिया की निष्पादन परीक्षण बैटरी किसकी बुद्धि के आकलन के लिए विशेष रूप से उपयुक्त होगी?","optionsHi":["ऐसे बच्चे की जो पढ़ नहीं सकता और परीक्षक की भाषा पर जिसकी पकड़ सीमित है","मेधा छात्रवृत्ति के लिए आवेदन कर रहे ऐसे कॉलेज विद्यार्थी की जो अंग्रेज़ी माध्यम के पाठ्यक्रम में है","ऐसे बच्चे की जिसकी तुलना सहपाठियों से पठन-गति और सटीकता पर करनी है","ऐसे बच्चे की जिसकी शाब्दिक परीक्षण से पहले ही पहचान हो चुकी है, उसी शाब्दिक अंक की पुष्टि के लिए"],"explanationHi":"निष्पादन परीक्षण ब्लॉक डिज़ाइन और प्रतिरूप चित्रण जैसे कार्यों का प्रयोग करते हैं जिनमें भाषा या साक्षरता की कम आवश्यकता होती है, इसलिए वे अनपढ़ बच्चों या परीक्षण-भाषा में सीमित दक्षता वाले बच्चों के लिए उपयुक्त हैं।"},
  {"id":"cdp-child-development-736","question":"Which statement about the stability of measured intelligence is best supported by research?","options":["Scores on infant developmental tests predict a person's adult IQ almost perfectly","IQ never changes at all once a child has started going to school","IQ scores are equally unstable at all ages, from infancy right through to adulthood","Infant scores predict later IQ poorly; scores grow more stable in the school years"],"answer":3,"explanation":"Infant tests measure mainly sensory and motor skills and predict later IQ weakly; stability increases through childhood, yet environments such as schooling and deprivation can still shift scores.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"मापी गई बुद्धि की स्थिरता के बारे में शोध द्वारा कौन-सा कथन सबसे अच्छी तरह समर्थित है?","optionsHi":["शिशु विकासात्मक परीक्षणों के अंक किसी व्यक्ति के वयस्क IQ का लगभग पूर्ण पूर्वानुमान करते हैं","बच्चे के विद्यालय जाना शुरू करने के बाद IQ कभी बिल्कुल नहीं बदलता","IQ अंक शैशव से लेकर वयस्कता तक सभी आयु में समान रूप से अस्थिर होते हैं","शिशु अंक बाद के IQ का कमज़ोर पूर्वानुमान करते हैं; विद्यालयी वर्षों में अंक अधिक स्थिर होते जाते हैं"],"explanationHi":"शिशु परीक्षण मुख्यतः संवेदी और गामक कौशल मापते हैं और बाद के IQ का कमज़ोर पूर्वानुमान करते हैं; बाल्यावस्था में स्थिरता बढ़ती है, फिर भी विद्यालय और वंचन जैसे परिवेश अंकों को बदल सकते हैं।"},
  {"id":"cdp-child-development-737","question":"In a well-known American study (Getzels and Jackson), students who were highly creative but not the highest in IQ were compared with students who had very high IQ but were less creative. What did teachers’ ratings reveal?","options":["Teachers clearly preferred the highly creative students for their original ideas","Teachers rated both groups equally, since their achievement was about the same","Teachers tended to prefer the high-IQ students, though both groups achieved similarly","Teachers could not tell the two groups apart in their ratings of the students"],"answer":2,"explanation":"The study found similar achievement in both groups but teachers favoured the high-IQ, more conforming students; creative students’ unusual ideas and humour were less welcomed, a caution for classrooms.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"एक प्रसिद्ध अमेरिकी अध्ययन (गेट्ज़ल्स और जैक्सन) में उन विद्यार्थियों की तुलना की गई जो अत्यंत रचनात्मक थे पर IQ में सर्वोच्च नहीं थे, उन विद्यार्थियों से जिनका IQ बहुत उच्च था पर जो कम रचनात्मक थे। शिक्षकों की रेटिंग ने क्या प्रकट किया?","optionsHi":["शिक्षकों ने स्पष्ट रूप से अत्यंत रचनात्मक विद्यार्थियों को उनके मौलिक विचारों के कारण पसंद किया","शिक्षकों ने दोनों समूहों को समान रेटिंग दी, क्योंकि उनकी उपलब्धि लगभग समान थी","शिक्षकों ने उच्च-IQ विद्यार्थियों को पसंद करने की प्रवृत्ति दिखाई, यद्यपि दोनों समूहों की उपलब्धि समान थी","शिक्षक विद्यार्थियों की अपनी रेटिंग में दोनों समूहों को अलग नहीं कर सके"],"explanationHi":"अध्ययन में दोनों समूहों में समान उपलब्धि मिली पर शिक्षकों ने उच्च-IQ, अधिक अनुरूप विद्यार्थियों को पसंद किया; रचनात्मक विद्यार्थियों के असामान्य विचारों और हास्य का कम स्वागत हुआ, जो कक्षाओं के लिए एक सावधानी है।"},
  {"id":"cdp-child-development-738","question":"A Class 7 teacher wants to assess a creative-writing task without killing originality. Which approach is most suitable?","options":["Award marks only if the piece closely matches the format of the sample answer given","Use a rubric with clear criteria that include credit for original ideas and good language","Give equal marks to every student, since creativity cannot really be assessed fairly","Mark only spelling and handwriting, since these can be checked objectively by anyone"],"answer":1,"explanation":"A transparent rubric that explicitly values originality alongside craft guides students without forcing a single model answer; the other options either punish originality or give no useful feedback.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"कक्षा 7 का एक शिक्षक मौलिकता को मारे बिना रचनात्मक-लेखन कार्य का आकलन करना चाहता है। कौन-सा उपागम सबसे उपयुक्त है?","optionsHi":["अंक केवल तब देना जब रचना दिए गए नमूना-उत्तर के प्रारूप से निकट मेल खाए","स्पष्ट मानदंडों वाला रूब्रिक प्रयोग करना जिसमें मौलिक विचारों और अच्छी भाषा के लिए अंक हों","प्रत्येक विद्यार्थी को समान अंक देना, क्योंकि रचनात्मकता का निष्पक्ष आकलन वास्तव में नहीं हो सकता","केवल वर्तनी और लिखावट पर अंक देना, क्योंकि इन्हें कोई भी वस्तुनिष्ठ रूप से जाँच सकता है"],"explanationHi":"एक पारदर्शी रूब्रिक जो शिल्प के साथ मौलिकता को भी स्पष्ट रूप से महत्त्व देता है, विद्यार्थियों का मार्गदर्शन करता है बिना किसी एक नमूना-उत्तर को थोपे; अन्य विकल्प या तो मौलिकता को दंडित करते हैं या कोई उपयोगी प्रतिपुष्टि नहीं देते।"},
  {"id":"cdp-child-development-739","question":"Given a candle, a box of drawing pins and matches, and asked to fix the candle to a soft board so it can burn without dripping on the floor, most Class 9 students cannot see that the empty pin box itself can be pinned up as a shelf. This block to creative problem-solving is called:","options":["Functional fixedness","Mental set built by reinforcement","Incubation","Divergent production"],"answer":0,"explanation":"Functional fixedness (Duncker’s candle problem) is the tendency to see an object only in its usual function, here a container for pins, which blocks a novel use.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"एक मोमबत्ती, ड्रॉइंग-पिनों का डिब्बा और माचिस देकर, और मोमबत्ती को नरम पट्टी पर इस तरह जमाने को कहे जाने पर कि वह फर्श पर टपके बिना जल सके, कक्षा 9 के अधिकांश विद्यार्थी यह नहीं देख पाते कि खाली पिन-डिब्बे को ही अलमारी की तरह टाँगा जा सकता है। रचनात्मक समस्या-समाधान में इस अवरोध को क्या कहते हैं?","optionsHi":["प्रकार्यात्मक स्थिरता","पुनर्बलन से बना मानसिक झुकाव","परिपक्वन (इन्क्यूबेशन)","अपसारी उत्पादन"],"explanationHi":"प्रकार्यात्मक स्थिरता (डंकर की मोमबत्ती समस्या) किसी वस्तु को केवल उसके सामान्य प्रकार्य में देखने की प्रवृत्ति है, यहाँ पिनों के लिए पात्र, जो नए उपयोग को रोकती है।"},
  {"id":"cdp-child-development-740","question":"Students solve five measuring problems with jars, each needing the same long sequence of steps. On the sixth problem, which can be solved in one simple step, most of them still use the long method. This illustrates:","options":["Functional fixedness about the jars","Insight into the problem's structure","Creativity in finding a new method","Mental set (Einstellung)"],"answer":3,"explanation":"A mental set is a habit of approaching problems in a way that worked before, which blinds the solver to simpler solutions (Luchins’s water-jar experiment). Functional fixedness concerns an object’s use, not a method.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"विद्यार्थी जार के साथ पाँच मापन-समस्याएँ हल करते हैं, जिनमें से प्रत्येक के लिए चरणों का वही लंबा क्रम चाहिए। छठी समस्या पर, जो एक सरल चरण में हल हो सकती है, उनमें से अधिकांश अब भी लंबी विधि का प्रयोग करते हैं। यह दर्शाता है:","optionsHi":["जारों के बारे में प्रकार्यात्मक स्थिरता","समस्या की संरचना की अंतर्दृष्टि","नई विधि खोजने में रचनात्मकता","मानसिक झुकाव (आइंस्टेलुंग)"],"explanationHi":"मानसिक झुकाव समस्याओं को उस तरीके से हल करने की आदत है जो पहले कारगर रहा, जो हल करने वाले को सरल समाधानों से अंधा कर देता है (लुचिन्स का पानी-जार प्रयोग)। प्रकार्यात्मक स्थिरता वस्तु के उपयोग से संबंधित है, विधि से नहीं।"},
  {"id":"cdp-child-development-741","question":"Lewis Terman’s long-term study of children with very high IQs found that, on average, these children:","options":["Were physically weaker and socially awkward, just as the popular stereotype claimed","Were as healthy and well-adjusted as their peers or better, contradicting the stereotype","All went on to become famous inventors, scientists or artists by middle adulthood","Lost their intellectual advantage over other children completely by adolescence"],"answer":1,"explanation":"Terman’s ‘Genetic Studies of Genius’ found gifted children generally healthy and well adjusted, contrary to the image of the frail, odd genius, though not all achieved eminence.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"बहुत उच्च IQ वाले बच्चों के बारे में लुईस टर्मन के दीर्घकालिक अध्ययन ने पाया कि औसतन ये बच्चे:","optionsHi":["शारीरिक रूप से कमज़ोर और सामाजिक रूप से बेढंगे थे, ठीक जैसा लोकप्रिय रूढ़िबद्ध धारणा कहती थी","अपने साथियों जितने या उनसे बेहतर स्वस्थ और सुसमायोजित थे, जो रूढ़िबद्ध धारणा का खंडन करता है","सभी मध्य वयस्कता तक प्रसिद्ध आविष्कारक, वैज्ञानिक या कलाकार बन गए","किशोरावस्था तक अन्य बच्चों पर अपनी बौद्धिक बढ़त पूरी तरह खो बैठे"],"explanationHi":"टर्मन के ‘जेनेटिक स्टडीज़ ऑफ़ जीनियस’ ने पाया कि प्रतिभाशाली बच्चे सामान्यतः स्वस्थ और सुसमायोजित थे, कमज़ोर, विचित्र प्रतिभाशाली की छवि के विपरीत, यद्यपि सभी ने ख्याति प्राप्त नहीं की।"},
  {"id":"cdp-child-development-742","question":"Which of these statements about gifted children are correct? I. Gifted children do not need any special help because they will succeed anyway. II. A gifted child’s intellectual, emotional and physical development may be uneven. III. Gifted children are found in all social, economic and cultural groups. IV. A gifted child always excels in every school subject.","options":["I and IV only","I, II and III only","II and IV only","II and III only"],"answer":3,"explanation":"Giftedness occurs in every group and development can be asynchronous; gifted children can underachieve without support, and many are strong in some areas but not all, so I and IV are myths.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"प्रतिभाशाली बच्चों के बारे में इनमें से कौन-से कथन सही हैं? I. प्रतिभाशाली बच्चों को किसी विशेष सहायता की आवश्यकता नहीं होती क्योंकि वे वैसे भी सफल होंगे। II. प्रतिभाशाली बच्चे का बौद्धिक, भावनात्मक और शारीरिक विकास असमान हो सकता है। III. प्रतिभाशाली बच्चे सभी सामाजिक, आर्थिक और सांस्कृतिक समूहों में पाए जाते हैं। IV. प्रतिभाशाली बच्चा विद्यालय के प्रत्येक विषय में सदैव उत्कृष्ट होता है।","optionsHi":["केवल I और IV","केवल I, II और III","केवल II और IV","केवल II और III"],"explanationHi":"प्रतिभाशालिता हर समूह में होती है और विकास असमकालिक हो सकता है; प्रतिभाशाली बच्चे सहायता के बिना कम प्रदर्शन कर सकते हैं, और कई कुछ क्षेत्रों में सशक्त होते हैं सभी में नहीं, इसलिए I और IV मिथक हैं।"},
  {"id":"cdp-child-development-743","question":"Before a unit on fractions, a teacher gives a pre-test and finds that Kabir already knows most of it. She lets him skip the practice he has already mastered and use that time for an independent project on ratios in Indian music. This strategy is called:","options":["Remedial teaching","Grade skipping","Curriculum compacting","Mastery learning for the whole class"],"answer":2,"explanation":"Curriculum compacting pre-assesses learners, removes what they have already mastered and replaces it with more challenging work; it is a form of differentiation, not grade skipping.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"भिन्नों की इकाई से पहले एक शिक्षिका पूर्व-परीक्षण देती है और पाती है कि कबीर पहले से अधिकांश जानता है। वह उसे उस अभ्यास को छोड़ने देती है जिसमें वह निपुण है और उस समय का उपयोग भारतीय संगीत में अनुपातों पर एक स्वतंत्र परियोजना के लिए करने देती है। इस युक्ति को क्या कहते हैं?","optionsHi":["उपचारात्मक शिक्षण","कक्षा छोड़ना","पाठ्यचर्या संघनन (कम्पैक्टिंग)","पूरी कक्षा के लिए निपुणता अधिगम"],"explanationHi":"पाठ्यचर्या संघनन अधिगमकर्ताओं का पूर्व-आकलन करता है, जिसमें वे पहले ही निपुण हैं उसे हटाता है और उसे अधिक चुनौतीपूर्ण कार्य से बदलता है; यह विभेदन का रूप है, कक्षा छोड़ना नहीं।"},
  {"id":"cdp-child-development-744","question":"A three-year-old correctly follows the instruction ‘Give the red ball that is under the chair to Didi’, but in her own speech says only short phrases like ‘ball chair’. Chomsky’s distinction that best describes the gap between what she knows and what she produces is between:","options":["Langue and parole","Surface structure and transformation","Holophrase and telegraphic speech","Competence and performance"],"answer":3,"explanation":"Chomsky separated competence, the underlying knowledge of language, from performance, the actual use of it, which is limited by memory, attention and motor skills. Langue/parole is Saussure’s distinction.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"एक तीन वर्ष की बच्ची निर्देश ‘कुर्सी के नीचे रखी लाल गेंद दीदी को दो’ का सही पालन करती है, पर अपनी वाणी में केवल ‘गेंद कुर्सी’ जैसे छोटे वाक्यांश बोलती है। चॉम्स्की का वह भेद जो उसके जानने और उसके उत्पादन के अंतर का सबसे अच्छा वर्णन करता है, किनके बीच है?","optionsHi":["भाषा-व्यवस्था (लांग) और भाषा-व्यवहार (पैरोल)","सतही संरचना और रूपांतरण","एकपदीय वाक्य और तार-शैली वाणी","भाषिक क्षमता (कॉम्पीटेंस) और भाषिक निष्पादन (परफ़ॉर्मेंस)"],"explanationHi":"चॉम्स्की ने क्षमता, भाषा के अंतर्निहित ज्ञान, को निष्पादन, उसके वास्तविक प्रयोग, से अलग किया, जो स्मृति, ध्यान और गामक कौशलों से सीमित होता है। लांग/पैरोल सोस्यूर का भेद है।"},
  {"id":"cdp-child-development-745","question":"A child knows from daily life that ‘things fall down’ but cannot explain why. In school, the teacher builds on this to introduce the idea of gravitational force. In Vygotsky’s terms, the teacher is linking:","options":["Spontaneous (everyday) concepts with scientific concepts","Egocentric speech with social speech used in class","Assimilation of the idea with accommodation of schemas","Fluid intelligence with crystallised intelligence"],"answer":0,"explanation":"Vygotsky distinguished spontaneous concepts formed in daily experience from systematic scientific concepts learned through instruction; good teaching connects the two, each strengthening the other.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"एक बच्चा दैनिक जीवन से जानता है कि ‘चीज़ें नीचे गिरती हैं’ पर क्यों गिरती हैं यह नहीं समझा सकता। विद्यालय में शिक्षिका इसके आधार पर गुरुत्वाकर्षण बल का विचार प्रस्तुत करती है। वाइगोत्स्की के शब्दों में शिक्षिका किसे जोड़ रही है?","optionsHi":["स्वतःस्फूर्त (रोज़मर्रा की) संप्रत्ययों को वैज्ञानिक संप्रत्ययों से","अहंकेंद्रित वाणी को कक्षा में प्रयुक्त सामाजिक वाणी से","विचार के आत्मसात्करण को स्कीमाओं के समायोजन से","तरल बुद्धि को क्रिस्टलीकृत बुद्धि से"],"explanationHi":"वाइगोत्स्की ने दैनिक अनुभव में बने स्वतःस्फूर्त संप्रत्ययों को अनुदेशन से सीखे गए व्यवस्थित वैज्ञानिक संप्रत्ययों से अलग किया; अच्छा शिक्षण दोनों को जोड़ता है, प्रत्येक दूसरे को सुदृढ़ करता है।"},
  {"id":"cdp-child-development-746","question":"Assertion (A): According to Vygotsky, a child’s private speech gradually turns into silent inner speech. Reason (R): Vygotsky held that higher mental functions appear first between people, on the social plane, and are later internalised by the individual.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Speech begins as social communication, is taken over as private speech to guide oneself, and is internalised as inner speech: a direct case of Vygotsky’s general law of internalisation from social to individual.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"अभिकथन (A): वाइगोत्स्की के अनुसार, बच्चे की निजी वाणी धीरे-धीरे मौन आंतरिक वाणी में बदल जाती है। कारण (R): वाइगोत्स्की का मत था कि उच्चतर मानसिक प्रकार्य पहले लोगों के बीच, सामाजिक धरातल पर प्रकट होते हैं, और बाद में व्यक्ति द्वारा आंतरिकीकृत किए जाते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"वाणी सामाजिक संप्रेषण के रूप में आरंभ होती है, स्वयं को निर्देशित करने के लिए निजी वाणी के रूप में अपनाई जाती है, और आंतरिक वाणी के रूप में आंतरिकीकृत होती है: यह वाइगोत्स्की के सामाजिक से व्यक्तिगत की ओर आंतरिकीकरण के सामान्य नियम का प्रत्यक्ष उदाहरण है।"},
  {"id":"cdp-child-development-747","question":"Linguist William Labov showed that African American Vernacular English, often dismissed as ‘broken’ speech, follows consistent grammatical rules. For Indian classrooms, the most direct implication of such work is that:","options":["Children who speak non-standard dialects have a cognitive deficit that must be corrected first","Only the standard language is precise enough to express logical and scientific thought","Home dialects are rule-governed, so the standard language should be added, not substituted","Dialect speakers should be placed in separate sections until their speech is standardised"],"answer":2,"explanation":"Labov’s work challenged deficit views of non-standard varieties; teachers should respect the logic of children’s home speech and build the standard school language on it (an additive approach).","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"भाषाविद् विलियम लेबोव ने दिखाया कि अफ़्रीकी अमेरिकी देशज अंग्रेज़ी, जिसे प्रायः ‘टूटी-फूटी’ बोली कहकर ख़ारिज किया जाता है, सुसंगत व्याकरणिक नियमों का पालन करती है। भारतीय कक्षाओं के लिए ऐसे कार्य का सबसे सीधा निहितार्थ यह है कि:","optionsHi":["गैर-मानक बोलियाँ बोलने वाले बच्चों में संज्ञानात्मक कमी होती है जिसे पहले सुधारा जाना चाहिए","केवल मानक भाषा ही तार्किक और वैज्ञानिक चिंतन को व्यक्त करने के लिए पर्याप्त सटीक है","घरेलू बोलियाँ नियम-शासित हैं, इसलिए मानक भाषा को जोड़ा जाना चाहिए, प्रतिस्थापित नहीं किया जाना चाहिए","बोली बोलने वालों को तब तक अलग अनुभागों में रखा जाना चाहिए जब तक उनकी वाणी मानकीकृत न हो जाए"],"explanationHi":"लेबोव के कार्य ने गैर-मानक रूपों के प्रति अभाव-दृष्टि को चुनौती दी; शिक्षकों को बच्चों की घरेलू वाणी के तर्क का सम्मान करना चाहिए और उस पर मानक विद्यालयी भाषा को निर्मित करना चाहिए (योगात्मक उपागम)।"},
  {"id":"cdp-child-development-748","question":"Which of the following is an example of GENDER rather than of biological sex?","options":["Girls generally reach puberty a year or two earlier than boys do","Only women can become pregnant and give birth to children","Boys' voices usually deepen noticeably during adolescence","A village belief that girls should stop playing cricket after Class 5"],"answer":3,"explanation":"Sex refers to biological differences; gender refers to socially constructed roles, norms and expectations, such as rules about which games girls may play.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"निम्नलिखित में से कौन-सा जैविक लिंग (सेक्स) का नहीं बल्कि जेंडर का उदाहरण है?","optionsHi":["लड़कियाँ सामान्यतः लड़कों से एक-दो वर्ष पहले यौवन में पहुँचती हैं","केवल महिलाएँ ही गर्भवती हो सकती हैं और बच्चों को जन्म दे सकती हैं","लड़कों की आवाज़ किशोरावस्था में प्रायः उल्लेखनीय रूप से भारी हो जाती है","एक ग्रामीण मान्यता कि लड़कियों को कक्षा 5 के बाद क्रिकेट खेलना बंद कर देना चाहिए"],"explanationHi":"सेक्स जैविक भेदों को दर्शाता है; जेंडर सामाजिक रूप से निर्मित भूमिकाओं, मानदंडों और अपेक्षाओं को, जैसे इस बारे में नियम कि लड़कियाँ कौन-से खेल खेल सकती हैं।"},
  {"id":"cdp-child-development-749","question":"Carol Gilligan criticised Kohlberg’s theory of moral development mainly because it:","options":["Ignored the role of cognitive development in moral reasoning, focusing only on feelings","Was built largely on males and ranked justice above care, so women seemed less developed","Placed too much importance on punishment and reward at every stage of development","Was based only on studies of children from India and other non-Western cultures"],"answer":1,"explanation":"Gilligan argued that Kohlberg’s scheme, derived from interviews with boys and men, privileged abstract justice and undervalued an ethic of care and relationships, producing a gender bias in scoring.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कैरल गिलिगन ने कोहलबर्ग के नैतिक विकास सिद्धांत की आलोचना मुख्यतः इसलिए की कि वह:","optionsHi":["नैतिक चिंतन में संज्ञानात्मक विकास की भूमिका को अनदेखा करता था, केवल भावनाओं पर ध्यान देता था","मुख्यतः पुरुषों पर आधारित था और न्याय को देखभाल से ऊपर रखता था, इसलिए महिलाएँ कम विकसित प्रतीत होती थीं","विकास की प्रत्येक अवस्था में दंड और पुरस्कार को बहुत अधिक महत्त्व देता था","केवल भारत और अन्य गैर-पश्चिमी संस्कृतियों के बच्चों के अध्ययनों पर आधारित था"],"explanationHi":"गिलिगन का तर्क था कि कोहलबर्ग की योजना, जो लड़कों और पुरुषों के साक्षात्कारों से निकली, अमूर्त न्याय को प्राथमिकता देती थी और देखभाल तथा संबंधों की नीति को कम आँकती थी, जिससे अंकन में लैंगिक पूर्वाग्रह उत्पन्न होता था।"},
  {"id":"cdp-child-development-750","question":"Match each idea with its theorist. P. Equilibration Q. Speech used aloud to guide one’s own actions R. Enactive representation S. Horizontal décalage; 1. Piaget 2. Vygotsky 3. Bruner","options":["P-1, Q-2, R-3, S-2","P-2, Q-1, R-3, S-1","P-1, Q-3, R-2, S-1","P-1, Q-2, R-3, S-1"],"answer":3,"explanation":"Equilibration and horizontal décalage are Piaget’s terms, private speech as self-guidance is Vygotsky’s, and enactive representation is Bruner’s.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"प्रत्येक विचार का मिलान उसके सिद्धांतकार से कीजिए। P. साम्यधारण Q. स्वयं के कार्यों का मार्गदर्शन करने के लिए ज़ोर से बोली जाने वाली वाणी R. क्रियात्मक निरूपण S. क्षैतिज विस्थापन (हॉरिज़ॉन्टल डेकैलाज); 1. पियाजे 2. वाइगोत्स्की 3. ब्रूनर","optionsHi":["P-1, Q-2, R-3, S-2","P-2, Q-1, R-3, S-1","P-1, Q-3, R-2, S-1","P-1, Q-2, R-3, S-1"],"explanationHi":"साम्यधारण और क्षैतिज विस्थापन पियाजे के शब्द हैं, स्व-मार्गदर्शन के रूप में निजी वाणी वाइगोत्स्की की है, और क्रियात्मक निरूपण ब्रूनर का है।"},
  {"id":"cdp-child-development-751","question":"A six-year-old fails a conservation-of-liquid task when tested alone, but succeeds when the teacher asks, ‘What if we pour it back?’ and ‘Did we add any water?’ Which comment would Vygotsky be most likely to make?","options":["She is simply not ready for conservation, since she failed the task when working alone","Conservation lies in her zone of proximal development and can be taught with such support","The questions spoiled the test, which should measure only what she can do independently","She is still in Bruner’s enactive mode, so she cannot yet handle a conservation task"],"answer":1,"explanation":"Success with help shows the ability is maturing, which is exactly what the ZPD captures. Judging only her solo failure, as in the first option, reflects a Piagetian readiness view.","difficulty":"hard","source":"CTET · State TETs","questionHi":"छह वर्ष की एक बच्ची अकेले परखे जाने पर द्रव के संरक्षण के कार्य में विफल होती है, पर शिक्षिका के यह पूछने पर सफल हो जाती है, ‘यदि हम इसे वापस उँडेल दें तो?’ और ‘क्या हमने पानी जोड़ा?’ वाइगोत्स्की सबसे संभवतः कौन-सी टिप्पणी करते?","optionsHi":["वह संरक्षण के लिए अभी तैयार ही नहीं है, क्योंकि अकेले काम करने पर वह कार्य में विफल रही","संरक्षण उसके निकटस्थ विकास के क्षेत्र में है और ऐसी सहायता से सिखाया जा सकता है","प्रश्नों ने परीक्षण बिगाड़ दिया, जिसे केवल यह मापना चाहिए कि वह स्वतंत्र रूप से क्या कर सकती है","वह अब भी ब्रूनर के क्रियात्मक पक्ष में है, इसलिए अभी संरक्षण का कार्य नहीं सँभाल सकती"],"explanationHi":"सहायता से सफलता दर्शाती है कि क्षमता परिपक्व हो रही है, जिसे ZPD ठीक पकड़ता है। केवल उसकी अकेली विफलता से आँकना, जैसा पहले विकल्प में है, पियाजेवादी तत्परता-दृष्टि को दर्शाता है।"},
  {"id":"cdp-child-development-752","question":"Which of these theorists would agree that well-designed instruction can actually speed up a child’s cognitive development?","options":["Piaget and Vygotsky only","Piaget and Bruner only","Vygotsky and Bruner","Piaget, Vygotsky and Bruner equally"],"answer":2,"explanation":"Vygotsky held that learning leads development and Bruner that readiness can be nurtured by suitable teaching. Piaget was sceptical of attempts to accelerate stages through instruction.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"इनमें से कौन-से सिद्धांतकार इस बात से सहमत होंगे कि सुनियोजित अनुदेशन वास्तव में बच्चे के संज्ञानात्मक विकास को तेज़ कर सकता है?","optionsHi":["केवल पियाजे और वाइगोत्स्की","केवल पियाजे और ब्रूनर","वाइगोत्स्की और ब्रूनर","पियाजे, वाइगोत्स्की और ब्रूनर समान रूप से"],"explanationHi":"वाइगोत्स्की का मत था कि अधिगम विकास का नेतृत्व करता है और ब्रूनर का कि उपयुक्त शिक्षण से तत्परता का पोषण किया जा सकता है। पियाजे अनुदेशन द्वारा अवस्थाओं को तेज़ करने के प्रयासों के प्रति संशयी थे।"},
  {"id":"cdp-child-development-753","question":"Match the role of the teacher with the theorist. P. Creates situations that challenge children’s present ideas and lets them resolve the conflict themselves. Q. Works alongside the child as a more knowledgeable partner, giving support that is withdrawn over time. R. Organises material so that learners find its structure, revisiting it at higher levels. 1. Bruner 2. Piaget 3. Vygotsky","options":["P-2, Q-3, R-1","P-3, Q-2, R-1","P-2, Q-1, R-3","P-1, Q-3, R-2"],"answer":0,"explanation":"Piaget’s teacher provokes disequilibrium, Vygotsky’s teacher scaffolds within the ZPD, and Bruner’s teacher structures discovery and the spiral curriculum.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"शिक्षक की भूमिका का मिलान सिद्धांतकार से कीजिए। P. ऐसी स्थितियाँ रचता है जो बच्चों के वर्तमान विचारों को चुनौती दें और उन्हें संघर्ष स्वयं सुलझाने देता है। Q. बच्चे के साथ अधिक ज्ञानी साझेदार के रूप में काम करता है और ऐसी सहायता देता है जो समय के साथ वापस ली जाती है। R. सामग्री को इस प्रकार संगठित करता है कि अधिगमकर्ता उसकी संरचना खोजें, और उसे उच्चतर स्तरों पर पुनः देखता है। 1. ब्रूनर 2. पियाजे 3. वाइगोत्स्की","optionsHi":["P-2, Q-3, R-1","P-3, Q-2, R-1","P-2, Q-1, R-3","P-1, Q-3, R-2"],"explanationHi":"पियाजे का शिक्षक असंतुलन उत्पन्न करता है, वाइगोत्स्की का शिक्षक ZPD के भीतर पाड़ देता है, और ब्रूनर का शिक्षक खोज तथा सर्पिल पाठ्यचर्या को संरचित करता है।"},
  {"id":"cdp-child-development-754","question":"How many of these are widely accepted criticisms of Piaget’s theory? I. He underestimated what infants and young children can do when tasks are simplified. II. He gave too much weight to social and cultural influences. III. He claimed that cognitive development is driven mainly by reinforcement. IV. He placed too much emphasis on language as the driver of thought.","options":["Only one","Only two","Only three","All four of them"],"answer":0,"explanation":"Only I is a standard criticism. Piaget is criticised for giving too little weight to social and cultural influences, he treated language as secondary to thought, and reinforcement-driven development is a behaviourist idea, not his.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"पियाजे के सिद्धांत की व्यापक रूप से स्वीकृत आलोचनाओं में इनमें से कितनी हैं? I. जब कार्य सरल किए जाते हैं तो शिशु और छोटे बच्चे जो कर सकते हैं, उसे उन्होंने कम आँका। II. उन्होंने सामाजिक और सांस्कृतिक प्रभावों को बहुत अधिक महत्त्व दिया। III. उन्होंने दावा किया कि संज्ञानात्मक विकास मुख्यतः पुनर्बलन से संचालित होता है। IV. उन्होंने चिंतन के चालक के रूप में भाषा पर बहुत अधिक बल दिया।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"केवल I एक मानक आलोचना है। पियाजे की आलोचना सामाजिक और सांस्कृतिक प्रभावों को बहुत कम महत्त्व देने के लिए होती है, उन्होंने भाषा को चिंतन के सापेक्ष गौण माना, और पुनर्बलन-चालित विकास एक व्यवहारवादी विचार है, उनका नहीं।"},
  {"id":"cdp-child-development-755","question":"Which statement is true of BOTH Piaget and Vygotsky?","options":["Both proposed four universal stages that every child passes through","Both held that language is the main source of thought from birth onward","Both rejected any meaningful role for the teacher in learning","Both saw children as active in constructing their own understanding"],"answer":3,"explanation":"Both were constructivists. Only Piaget proposed universal stages, only Vygotsky made language the central tool of thought, and both gave teachers a role, though a different one.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कौन-सा कथन पियाजे और वाइगोत्स्की दोनों के लिए सत्य है?","optionsHi":["दोनों ने चार सार्वभौमिक अवस्थाएँ प्रस्तावित कीं जिनसे प्रत्येक बच्चा गुज़रता है","दोनों का मत था कि जन्म से ही भाषा चिंतन का मुख्य स्रोत है","दोनों ने अधिगम में शिक्षक की किसी सार्थक भूमिका को अस्वीकार किया","दोनों ने बच्चों को अपनी समझ के निर्माण में सक्रिय माना"],"explanationHi":"दोनों रचनावादी थे। केवल पियाजे ने सार्वभौमिक अवस्थाएँ प्रस्तावित कीं, केवल वाइगोत्स्की ने भाषा को चिंतन का केंद्रीय उपकरण बनाया, और दोनों ने शिक्षकों को भूमिका दी, यद्यपि भिन्न।"},
  {"id":"cdp-child-development-756","question":"A Class 2 child in a Jharkhand village school speaks Santhali at home. While explaining a maths idea, the teacher lets her think and talk in Santhali before moving to Hindi terms. Which theoretical idea most strongly supports this practice?","options":["Vygotsky’s view that language is the main tool through which children think","Piaget’s idea that object permanence must be secured before any concept is taught","Skinner’s idea that negative reinforcement strengthens use of the school language","Bruner’s claim that only symbolic thinking in the school language counts as learning"],"answer":0,"explanation":"For Vygotsky, the child’s language mediates her thinking, so working in the familiar language supports concept formation. NCF 2005 also advises using the home language as a resource.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"झारखंड के एक गाँव के विद्यालय में कक्षा 2 की एक बच्ची घर पर संथाली बोलती है। गणित का कोई विचार समझाते हुए शिक्षिका उसे हिंदी शब्दों की ओर बढ़ने से पहले संथाली में सोचने और बोलने देती है। कौन-सा सैद्धांतिक विचार इस प्रथा का सबसे अधिक समर्थन करता है?","optionsHi":["वाइगोत्स्की का मत कि भाषा वह मुख्य उपकरण है जिससे बच्चे सोचते हैं","पियाजे का विचार कि किसी संप्रत्यय के पढ़ाए जाने से पहले वस्तु-स्थायित्व सुनिश्चित होना चाहिए","स्किनर का विचार कि नकारात्मक पुनर्बलन विद्यालयी भाषा के प्रयोग को सुदृढ़ करता है","ब्रूनर का दावा कि केवल विद्यालयी भाषा में सांकेतिक चिंतन ही अधिगम गिना जाता है"],"explanationHi":"वाइगोत्स्की के लिए बच्चे की भाषा उसके चिंतन में मध्यस्थता करती है, इसलिए परिचित भाषा में कार्य करना संप्रत्यय निर्माण में सहायक है। NCF 2005 भी घरेलू भाषा को संसाधन के रूप में प्रयोग करने की सलाह देती है।"},
  {"id":"cdp-child-development-757","question":"Group 1: two equally able Class 5 students who disagree argue about why a steel spoon sinks but a steel bowl floats until they test it. Group 2: a skilled student guides a weaker one through the steps of the same test. Which theorists would most value each group respectively?","options":["Group 1: Vygotsky; Group 2: Piaget","Group 1: Bruner; Group 2: Skinner","Group 1: Vygotsky; Group 2: Bruner","Group 1: Piaget; Group 2: Vygotsky"],"answer":3,"explanation":"Piaget valued conflict between equals because it produces disequilibrium that children resolve themselves. Vygotsky valued collaboration with a more capable peer who works within the learner’s ZPD.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"समूह 1: कक्षा 5 के दो समान रूप से सक्षम विद्यार्थी, जो असहमत हैं, इस पर बहस करते हैं कि स्टील का चम्मच क्यों डूबता है पर स्टील की कटोरी क्यों तैरती है, जब तक वे उसका परीक्षण न कर लें। समूह 2: एक कुशल विद्यार्थी एक कमज़ोर विद्यार्थी को उसी परीक्षण के चरणों से मार्गदर्शन देता है। किन सिद्धांतकारों द्वारा क्रमशः प्रत्येक समूह को सबसे अधिक महत्त्व दिया जाएगा?","optionsHi":["समूह 1: वाइगोत्स्की; समूह 2: पियाजे","समूह 1: ब्रूनर; समूह 2: स्किनर","समूह 1: वाइगोत्स्की; समूह 2: ब्रूनर","समूह 1: पियाजे; समूह 2: वाइगोत्स्की"],"explanationHi":"पियाजे ने बराबर वालों के बीच संघर्ष को महत्त्व दिया क्योंकि वह असंतुलन उत्पन्न करता है जिसे बच्चे स्वयं सुलझाते हैं। वाइगोत्स्की ने अधिक सक्षम सहपाठी के साथ सहयोग को महत्त्व दिया जो अधिगमकर्ता के ZPD के भीतर कार्य करता है।"},
  {"id":"cdp-child-development-758","question":"A Class 6 teacher in a Kendriya Vidyalaya first lets students test which objects float in water, then asks guiding questions as they record results in groups, and promises to return to the topic in Class 9 with the idea of density as mass divided by volume. Which part of her plan reflects Bruner most specifically?","options":["Letting students find out for themselves which objects float","Asking guiding questions during group work","Planning to revisit the topic later at a more formal level","Recording results in a table"],"answer":2,"explanation":"Returning to the same idea at a deeper, more symbolic level is Bruner’s spiral curriculum. Guided group questioning is more Vygotskian, and hands-on testing fits Piaget as well as Bruner.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"एक केंद्रीय विद्यालय में कक्षा 6 की शिक्षिका पहले विद्यार्थियों को परखने देती है कि कौन-सी वस्तुएँ पानी में तैरती हैं, फिर समूहों में परिणाम दर्ज करते समय मार्गदर्शक प्रश्न पूछती है, और वादा करती है कि द्रव्यमान भाग आयतन के रूप में घनत्व के विचार के साथ विषय पर कक्षा 9 में लौटेगी। उसकी योजना का कौन-सा भाग ब्रूनर को सबसे विशिष्ट रूप से दर्शाता है?","optionsHi":["विद्यार्थियों को स्वयं खोजने देना कि कौन-सी वस्तुएँ तैरती हैं","समूह कार्य के दौरान मार्गदर्शक प्रश्न पूछना","बाद में अधिक औपचारिक स्तर पर विषय को पुनः देखने की योजना बनाना","परिणामों को तालिका में दर्ज करना"],"explanationHi":"उसी विचार पर अधिक गहरे, अधिक सांकेतिक स्तर पर लौटना ब्रूनर की सर्पिल पाठ्यचर्या है। निर्देशित समूह-प्रश्न अधिक वाइगोत्स्कीय हैं, और प्रत्यक्ष परीक्षण पियाजे के साथ-साथ ब्रूनर के भी अनुकूल है।"},
  {"id":"cdp-child-development-759","question":"Which two theorists gave language a major role in driving cognitive growth?","options":["Piaget and Bruner","Vygotsky and Bruner","Piaget and Vygotsky","Piaget alone"],"answer":1,"explanation":"Vygotsky made language the chief psychological tool, and Bruner linked the symbolic mode and cognitive growth closely to language. Piaget saw language as reflecting thought rather than driving it.","difficulty":"hard","source":"CTET · State TETs","questionHi":"किन दो सिद्धांतकारों ने संज्ञानात्मक विकास को आगे बढ़ाने में भाषा को प्रमुख भूमिका दी?","optionsHi":["पियाजे और ब्रूनर","वाइगोत्स्की और ब्रूनर","पियाजे और वाइगोत्स्की","केवल पियाजे"],"explanationHi":"वाइगोत्स्की ने भाषा को मुख्य मनोवैज्ञानिक उपकरण बनाया, और ब्रूनर ने सांकेतिक पक्ष और संज्ञानात्मक विकास को भाषा से निकटता से जोड़ा। पियाजे ने भाषा को चिंतन को चलाने वाली नहीं, उसे प्रतिबिंबित करने वाली माना।"},
  {"id":"cdp-child-development-760","question":"A Class 4 child insists that heavier objects always fall faster. Which teacher response is most Piagetian?","options":["Correct her at once and give her the scientific rule to memorise for the next test","Let her drop a heavy and a light ball of equal size together, then discuss what she saw","Ask a brighter classmate to explain the right answer to her during the lesson","Ignore the error, since she will understand it naturally once she reaches the next stage"],"answer":1,"explanation":"Piaget favoured experiences that clash with the child’s belief, creating disequilibrium that she resolves by accommodation. Telling the answer gives no conflict, and Piaget did not advise doing nothing.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 4 की एक बच्ची आग्रह करती है कि भारी वस्तुएँ हमेशा तेज़ गिरती हैं। शिक्षक की कौन-सी प्रतिक्रिया सबसे अधिक पियाजेवादी है?","optionsHi":["उसे तुरंत सुधारना और अगली परीक्षा के लिए रटने हेतु वैज्ञानिक नियम देना","उसे समान आकार की एक भारी और एक हल्की गेंद साथ गिराने देना, फिर जो देखा उस पर चर्चा करना","कक्षा के दौरान किसी तेज़ सहपाठी से उसे सही उत्तर समझाने को कहना","त्रुटि को अनदेखा करना, क्योंकि अगली अवस्था में पहुँचने पर वह इसे स्वाभाविक रूप से समझ लेगी"],"explanationHi":"पियाजे ने ऐसे अनुभवों को प्राथमिकता दी जो बच्चे की मान्यता से टकराएँ, जिससे असंतुलन उत्पन्न होता है जिसे वह समायोजन द्वारा सुलझाती है। उत्तर बता देने से कोई संघर्ष नहीं होता, और पियाजे ने कुछ न करने की सलाह नहीं दी।"},
  {"id":"cdp-child-development-761","question":"Match each assessment approach with the theorist whose ideas it most reflects. P. Asking a child to explain her answers with open-ended follow-up questions (‘Why do you think so?’) Q. Measuring how much help a child needs to solve a problem R. Checking whether a child can show an idea with objects, with a picture and with symbols. 1. Bruner 2. Vygotsky 3. Piaget","options":["P-2, Q-3, R-1","P-3, Q-1, R-2","P-1, Q-2, R-3","P-3, Q-2, R-1"],"answer":3,"explanation":"Piaget’s clinical interview probes reasoning; dynamic assessment of assisted performance comes from Vygotsky’s ZPD; checking the three modes of representation follows Bruner.","difficulty":"hard","source":"CTET · DSSSB · State TETs","questionHi":"प्रत्येक आकलन उपागम का मिलान उस सिद्धांतकार से कीजिए जिसके विचारों को वह सबसे अधिक दर्शाता है। P. बच्ची से खुले अनुवर्ती प्रश्नों (‘तुम ऐसा क्यों सोचती हो?’) द्वारा अपने उत्तर समझाने को कहना Q. यह मापना कि बच्चे को समस्या हल करने के लिए कितनी सहायता चाहिए R. यह जाँचना कि बच्चा किसी विचार को वस्तुओं से, चित्र से और प्रतीकों से दिखा सकता है या नहीं। 1. ब्रूनर 2. वाइगोत्स्की 3. पियाजे","optionsHi":["P-2, Q-3, R-1","P-3, Q-1, R-2","P-1, Q-2, R-3","P-3, Q-2, R-1"],"explanationHi":"पियाजे का नैदानिक साक्षात्कार तर्क की पड़ताल करता है; सहायता प्राप्त निष्पादन का गत्यात्मक आकलन वाइगोत्स्की के ZPD से आता है; निरूपण के तीनों पक्षों की जाँच ब्रूनर का अनुसरण करती है।"},
  {"id":"cdp-child-development-762","question":"Consider these statements. 1. Piaget saw development as a series of qualitatively different stages. 2. Vygotsky described a fixed sequence of universal stages that all cultures pass through. 3. Bruner’s modes of representation are not strictly age-bound stages and remain available in adulthood. Which is/are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Piaget’s stages are qualitative and invariant in order; Bruner’s modes coexist. Vygotsky did not propose universal fixed stages; he stressed cultural and social variation.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"इन कथनों पर विचार कीजिए। 1. पियाजे ने विकास को गुणात्मक रूप से भिन्न अवस्थाओं की शृंखला के रूप में देखा। 2. वाइगोत्स्की ने सार्वभौमिक अवस्थाओं का एक निश्चित क्रम बताया जिससे सभी संस्कृतियाँ गुज़रती हैं। 3. ब्रूनर के निरूपण के पक्ष कठोर रूप से आयु-बद्ध अवस्थाएँ नहीं हैं और वयस्कता में भी उपलब्ध रहते हैं। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"पियाजे की अवस्थाएँ गुणात्मक हैं और क्रम में अपरिवर्तनीय; ब्रूनर के पक्ष साथ-साथ बने रहते हैं। वाइगोत्स्की ने सार्वभौमिक निश्चित अवस्थाएँ प्रस्तावित नहीं कीं; उन्होंने सांस्कृतिक और सामाजिक भिन्नता पर बल दिया।"},
  {"id":"cdp-child-development-763","question":"Assertion (A): Piaget was doubtful about trying to speed up children’s passage through the stages by direct training. Reason (R): For Piaget, logical operations must be built through the child’s own activity and equilibration, not simply transmitted by an adult.","options":["Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"Piaget called attempts to accelerate development ‘the American question’ and doubted their value, because operations are self-constructed. Telling or drilling cannot replace that construction.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"अभिकथन (A): पियाजे प्रत्यक्ष प्रशिक्षण द्वारा बच्चों के अवस्थाओं से गुज़रने को तेज़ करने के प्रयास के प्रति संदेह रखते थे। कारण (R): पियाजे के लिए तार्किक संक्रियाएँ बच्चे की अपनी गतिविधि और साम्यधारण से निर्मित होनी चाहिए, वयस्क द्वारा केवल संप्रेषित नहीं।","optionsHi":["A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है","A और R दोनों सत्य हैं, और R, A की सही व्याख्या है"],"explanationHi":"पियाजे ने विकास को तेज़ करने के प्रयासों को ‘अमेरिकी प्रश्न’ कहा और उनके मूल्य पर संदेह किया, क्योंकि संक्रियाएँ स्वयं निर्मित होती हैं। बताना या रटाना उस निर्माण का स्थान नहीं ले सकता।"},
  {"id":"cdp-child-development-764","question":"Which of these is NOT an educational implication of Piaget’s theory?","options":["Create cognitive conflict by showing results that clash with children’s predictions","Let peers debate their differing answers, as disagreement helps children decentre","Present the same content in the same way to all, so every child gets equal input","Avoid hurrying children through stages with intensive drill on advanced tasks"],"answer":2,"explanation":"Piaget stressed matching tasks to each child’s level of thinking, so identical teaching for all is not Piagetian. Peer debate may look Vygotskian, but Piaget valued peer disagreement for decentring, and he warned against accelerating stages.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"इनमें से कौन-सा पियाजे के सिद्धांत का शैक्षिक निहितार्थ नहीं है?","optionsHi":["ऐसे परिणाम दिखाकर संज्ञानात्मक संघर्ष उत्पन्न करना जो बच्चों के पूर्वानुमानों से टकराएँ","सहपाठियों को अपने भिन्न उत्तरों पर बहस करने देना, क्योंकि असहमति बच्चों को विकेंद्रित होने में सहायता करती है","सभी को वही सामग्री उसी तरह प्रस्तुत करना, ताकि प्रत्येक बच्चे को समान निवेश मिले","उन्नत कार्यों पर गहन अभ्यास कराकर बच्चों को अवस्थाओं से जल्दी गुज़ारने से बचना"],"explanationHi":"पियाजे ने कार्यों को प्रत्येक बच्चे के चिंतन के स्तर के अनुरूप रखने पर बल दिया, इसलिए सबके लिए एक जैसा शिक्षण पियाजेवादी नहीं है। सहपाठी-बहस वाइगोत्स्कीय लग सकती है, पर पियाजे ने विकेंद्रण के लिए सहपाठियों की असहमति को महत्त्व दिया, और उन्होंने अवस्थाओं को तेज़ करने के प्रति चेताया।"},
  {"id":"cdp-child-development-765","question":"Which of these is NOT consistent with Vygotsky’s ideas?","options":["Teachers should avoid helping children so that they discover everything alone","Peers as well as adults can act as the more knowledgeable other for a child","Support should be reduced step by step as the child becomes more competent","Language and dialogue with others help to shape the way children think"],"answer":0,"explanation":"Vygotsky saw help from others as essential to development; withholding all assistance contradicts his theory. The other three options follow directly from the ZPD and his view of language.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"इनमें से कौन-सा वाइगोत्स्की के विचारों से संगत नहीं है?","optionsHi":["शिक्षकों को बच्चों की सहायता करने से बचना चाहिए ताकि वे सब कुछ अकेले खोजें","सहपाठी भी वयस्कों की तरह बच्चे के लिए अधिक ज्ञानी अन्य की भूमिका निभा सकते हैं","जैसे-जैसे बच्चा अधिक सक्षम होता जाए, सहायता को चरण-दर-चरण घटाया जाना चाहिए","भाषा और दूसरों के साथ संवाद बच्चों की सोचने की पद्धति को आकार देने में सहायक होते हैं"],"explanationHi":"वाइगोत्स्की दूसरों की सहायता को विकास के लिए अनिवार्य मानते थे; सारी सहायता रोक लेना उनके सिद्धांत के विपरीत है। अन्य तीन विकल्प सीधे ZPD और भाषा के उनके दृष्टिकोण से निकलते हैं।"},
  {"id":"cdp-child-development-766","question":"A Class 3 teacher scolds children for counting on their fingers during subtraction. Drawing on Vygotsky and Bruner, the best advice for her is to:","options":["Continue the ban, so that children are pushed to think abstractly from the start","Allow finger counting as a support and encourage mental strategies as confidence grows","Allow finger counting only for the weakest children and shame the rest into stopping","Replace subtraction with rote learning of tables until children reach Class 5"],"answer":1,"explanation":"Fingers are an external, enactive aid that children later internalise; removing them too early takes away a support. The goal is gradual withdrawal, not a ban or shaming.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 3 की एक शिक्षिका घटाव के दौरान उँगलियों पर गिनने के लिए बच्चों को डाँटती है। वाइगोत्स्की और ब्रूनर के आधार पर उसके लिए सर्वोत्तम सलाह है:","optionsHi":["प्रतिबंध जारी रखना, ताकि बच्चे आरंभ से ही अमूर्त रूप से सोचने को विवश हों","उँगलियों से गिनने को सहारे के रूप में अनुमति देना और आत्मविश्वास बढ़ने पर मानसिक युक्तियों को प्रोत्साहित करना","उँगलियों से गिनने की अनुमति केवल सबसे कमज़ोर बच्चों को देना और शेष को शर्मिंदा करके रोकना","जब तक बच्चे कक्षा 5 तक न पहुँचें, घटाव के स्थान पर पहाड़ों का रटंत अधिगम कराना"],"explanationHi":"उँगलियाँ एक बाह्य, क्रियात्मक सहायक हैं जिन्हें बच्चे बाद में आंतरिकीकृत करते हैं; उन्हें बहुत जल्दी हटाना एक सहारा छीनना है। लक्ष्य क्रमिक वापसी है, प्रतिबंध या शर्मिंदा करना नहीं।"},
  {"id":"cdp-child-development-767","question":"‘What a child can do today with the help of others, she will be able to do by herself tomorrow.’ This idea is the basis of:","options":["Piaget’s concept of equilibration and self-regulation","Bruner’s spiral curriculum","Kohlberg’s stages of moral reasoning","Vygotsky’s zone of proximal development"],"answer":3,"explanation":"Vygotsky argued that assisted performance foreshadows independent performance; the space between the two levels is the ZPD.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"‘बच्चा आज जो दूसरों की सहायता से कर सकती है, कल वह स्वयं कर सकेगी।’ यह विचार किसका आधार है?","optionsHi":["पियाजे की साम्यधारण और स्व-नियमन की अवधारणा","ब्रूनर की सर्पिल पाठ्यचर्या","कोहलबर्ग की नैतिक चिंतन की अवस्थाएँ","वाइगोत्स्की का निकटस्थ विकास का क्षेत्र"],"explanationHi":"वाइगोत्स्की का तर्क था कि सहायता प्राप्त निष्पादन स्वतंत्र निष्पादन का पूर्वाभास देता है; दोनों स्तरों के बीच का अंतराल ZPD है।"},
  {"id":"cdp-child-development-768","question":"In a Class 9 science practical, many students change two factors at once when testing what affects the rate of evaporation. What is the most suitable response from a teacher who knows both Piaget’s and Vygotsky’s ideas?","options":["Conclude that the students are still pre-operational and should not do experiments yet","Assume that all 14-year-olds should already reason this way and give zero marks","Model a one-variable fair test, guide them through one, then let them design their own","Drop experiments and teach only from the textbook, since practicals confuse them"],"answer":2,"explanation":"Research shows formal reasoning such as controlling variables is not automatic in adolescence; modelling and guided practice scaffold it. The students are not pre-operational, and marking them down teaches nothing.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 9 के विज्ञान प्रयोग में, वाष्पीकरण की दर को क्या प्रभावित करता है इसका परीक्षण करते समय कई विद्यार्थी एक साथ दो कारक बदल देते हैं। पियाजे और वाइगोत्स्की दोनों के विचारों को जानने वाले शिक्षक की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["यह निष्कर्ष निकालना कि विद्यार्थी अब भी पूर्व-संक्रियात्मक हैं और उन्हें अभी प्रयोग नहीं करने चाहिए","मान लेना कि सभी 14 वर्ष के बच्चों को पहले से ही इस तरह तर्क करना चाहिए और शून्य अंक देना","एक-चर वाली निष्पक्ष परीक्षा का प्रतिरूपण करना, उन्हें एक के माध्यम से मार्गदर्शन देना, फिर उन्हें स्वयं अपना अभिकल्प बनाने देना","प्रयोग छोड़ देना और केवल पाठ्यपुस्तक से पढ़ाना, क्योंकि प्रायोगिक कार्य उन्हें भ्रमित करते हैं"],"explanationHi":"शोध दर्शाता है कि चरों को नियंत्रित करने जैसा औपचारिक तर्क किशोरावस्था में स्वतः नहीं आता; प्रतिरूपण और निर्देशित अभ्यास उसे पाड़ देते हैं। विद्यार्थी पूर्व-संक्रियात्मक नहीं हैं, और उन्हें कम अंक देने से कुछ नहीं सीखा जाता।"},
  {"id":"cdp-child-development-769","question":"Assertion (A): A teacher who follows Piaget and one who follows Vygotsky may both organise group work. Reason (R): Piaget saw peers as a source of cognitive conflict, while Vygotsky saw them as possible more knowledgeable others.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both theorists value peer interaction, but for different reasons. R gives those reasons and so explains why both kinds of teacher might use group work.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"अभिकथन (A): पियाजे का अनुसरण करने वाला शिक्षक और वाइगोत्स्की का अनुसरण करने वाला शिक्षक, दोनों समूह कार्य आयोजित कर सकते हैं। कारण (R): पियाजे ने सहपाठियों को संज्ञानात्मक संघर्ष का स्रोत माना, जबकि वाइगोत्स्की ने उन्हें संभावित अधिक ज्ञानी अन्य माना।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सिद्धांतकार सहपाठी-अंतःक्रिया को महत्त्व देते हैं, पर अलग कारणों से। R वे कारण देता है और इसलिए समझाता है कि दोनों प्रकार के शिक्षक समूह कार्य क्यों प्रयोग कर सकते हैं।"},
  {"id":"cdp-child-development-770","question":"Which theory most strongly suggests that a child’s level of thinking can be broadly predicted from her age?","options":["Vygotsky’s sociocultural theory","Piaget’s stage theory","Bruner’s theory of instruction","None, as all three reject any link with age"],"answer":1,"explanation":"Piaget linked his stages to approximate age ranges, although ages vary. Vygotsky focused on social context and Bruner’s modes are not strict age-stages.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कौन-सा सिद्धांत सबसे दृढ़ता से सुझाता है कि बच्ची के चिंतन के स्तर का मोटे तौर पर उसकी आयु से पूर्वानुमान किया जा सकता है?","optionsHi":["वाइगोत्स्की का सामाजिक-सांस्कृतिक सिद्धांत","पियाजे का अवस्था सिद्धांत","ब्रूनर का अनुदेशन सिद्धांत","कोई नहीं, क्योंकि तीनों आयु से किसी संबंध को अस्वीकार करते हैं"],"explanationHi":"पियाजे ने अपनी अवस्थाओं को अनुमानित आयु-सीमाओं से जोड़ा, यद्यपि आयु भिन्न होती है। वाइगोत्स्की ने सामाजिक संदर्भ पर ध्यान दिया और ब्रूनर के पक्ष कठोर आयु-अवस्थाएँ नहीं हैं।"},
  {"id":"cdp-child-development-771","question":"A teacher notices that a Class 1 child can sort buttons by colour but not by colour and size together, while a Class 4 child easily makes a 2 × 2 table sorting them by both. The ability the older child shows is called multiple classification. In Piaget’s theory it depends mainly on:","options":["Decentration, which lets a child attend to two attributes at once","Object permanence, which lets a child keep track of hidden objects","Private speech, which lets a child guide her own sorting aloud","Iconic representation alone, which lets a child picture the buttons"],"answer":0,"explanation":"Multiple classification needs the child to attend to two dimensions together, which becomes possible with decentration in the concrete operational stage. Object permanence and private speech are unrelated.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"एक शिक्षक देखता है कि कक्षा 1 का एक बच्चा बटनों को रंग के आधार पर छाँट सकता है पर रंग और आकार दोनों के आधार पर साथ-साथ नहीं, जबकि कक्षा 4 का एक बच्चा उन्हें दोनों के आधार पर छाँटते हुए आसानी से 2 × 2 की तालिका बना लेता है। बड़े बच्चे में दिखने वाली क्षमता बहुगुणी वर्गीकरण कहलाती है। पियाजे के सिद्धांत में यह मुख्यतः किस पर निर्भर करती है?","optionsHi":["विकेंद्रण, जो बच्चे को एक साथ दो गुणों पर ध्यान देने देता है","वस्तु-स्थायित्व, जो बच्चे को छिपी वस्तुओं का पता रखने देता है","निजी वाणी, जो बच्चे को ज़ोर से बोलकर अपनी छँटाई का मार्गदर्शन करने देती है","केवल प्रतिबिंबात्मक निरूपण, जो बच्चे को बटनों की छवि बनाने देता है"],"explanationHi":"बहुगुणी वर्गीकरण के लिए बच्चे को एक साथ दो आयामों पर ध्यान देना होता है, जो मूर्त संक्रियात्मक अवस्था में विकेंद्रण से संभव होता है। वस्तु-स्थायित्व और निजी वाणी असंबद्ध हैं।"},
  {"id":"cdp-child-development-772","question":"How many of these statements correctly compare the three theorists? I. Piaget: the child as a lone scientist; Vygotsky: the child as an apprentice in a culture. II. Bruner: the teacher should translate ideas into the learner’s way of viewing things. III. Vygotsky: development is the same in every culture, since it is driven by maturation. IV. Piaget: language reflects thought more than it shapes it.","options":["Only one","Only two","Only three","All four of them"],"answer":2,"explanation":"I, II and IV are accurate summaries. III is wrong: Vygotsky stressed cultural variation and social interaction rather than maturation alone.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"तीनों सिद्धांतकारों की तुलना करने वाले इनमें से कितने कथन सही हैं? I. पियाजे: बच्चा एकाकी वैज्ञानिक के रूप में; वाइगोत्स्की: बच्चा संस्कृति में प्रशिक्षु के रूप में। II. ब्रूनर: शिक्षक को विचारों का अनुवाद अधिगमकर्ता की चीज़ों को देखने की पद्धति में करना चाहिए। III. वाइगोत्स्की: विकास प्रत्येक संस्कृति में समान है, क्योंकि वह परिपक्वता से संचालित होता है। IV. पियाजे: भाषा चिंतन को आकार देने से अधिक उसे प्रतिबिंबित करती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"I, II और IV सटीक सार हैं। III गलत है: वाइगोत्स्की ने केवल परिपक्वता के बजाय सांस्कृतिक भिन्नता और सामाजिक अंतःक्रिया पर बल दिया।"},
  {"id":"cdp-child-development-773","question":"Before a lesson on fractions, a teacher asks the class, ‘Who can share 3 rotis equally among 4 friends?’ and lets them try with paper rotis. Which reason would BOTH a Piagetian and a Brunerian teacher give for this activity?","options":["It provides reinforcement for correct answers, so the right responses get strengthened","It removes the need for later symbolic work, since the concrete task is enough","It lets the teacher quickly identify the most able children in the class for grouping","It gives children active, concrete experience on which understanding can be built"],"answer":3,"explanation":"Both Piaget and Bruner favour active, concrete experience as the basis for understanding, with Bruner adding a planned move to iconic and symbolic forms. Reinforcement is a behaviourist reason.","difficulty":"moderate","source":"CTET · KVS · State TETs","questionHi":"भिन्नों के पाठ से पहले एक शिक्षक कक्षा से पूछता है, ‘3 रोटियाँ 4 मित्रों में बराबर कौन बाँट सकता है?’ और उन्हें कागज़ की रोटियों से प्रयास करने देता है। इस गतिविधि के लिए पियाजेवादी और ब्रूनरवादी, दोनों प्रकार के शिक्षक कौन-सा कारण देंगे?","optionsHi":["यह सही उत्तरों के लिए पुनर्बलन देता है, ताकि सही अनुक्रियाएँ सुदृढ़ हों","यह बाद के सांकेतिक कार्य की आवश्यकता समाप्त कर देता है, क्योंकि मूर्त कार्य पर्याप्त है","यह शिक्षक को समूह बनाने के लिए कक्षा के सबसे सक्षम बच्चों की शीघ्र पहचान करने देता है","यह बच्चों को सक्रिय, मूर्त अनुभव देता है जिस पर समझ निर्मित हो सकती है"],"explanationHi":"पियाजे और ब्रूनर दोनों समझ के आधार के रूप में सक्रिय, मूर्त अनुभव का समर्थन करते हैं, ब्रूनर प्रतिबिंबात्मक और सांकेतिक रूपों की ओर नियोजित गति भी जोड़ते हैं। पुनर्बलन एक व्यवहारवादी कारण है।"},
  {"id":"cdp-child-development-774","question":"In which situation is a teacher wrongly applying Piaget’s ideas?","options":["She gives Class 2 children counters to explore addition before writing sums","She gives a struggling Class 4 child no hints, saying he must reach the next stage alone","She asks a child to predict what will happen and then test the prediction","She plans hypothetical ‘what if’ debates for Class 10 to stretch abstract reasoning"],"answer":1,"explanation":"Piaget did not say teachers should withhold all help; he advised providing suitable experiences and challenges. The other options are sensible applications of his theory.","difficulty":"hard","source":"CTET · DSSSB · State TETs","questionHi":"किस स्थिति में शिक्षिका पियाजे के विचारों को गलत ढंग से लागू कर रही है?","optionsHi":["वह कक्षा 2 के बच्चों को जोड़ लिखने से पहले उसे परखने के लिए गिनतियाँ देती है","वह संघर्ष कर रहे कक्षा 4 के बच्चे को कोई संकेत नहीं देती, यह कहकर कि उसे अगली अवस्था तक अकेले पहुँचना होगा","वह बच्चे से अनुमान लगाने को कहती है कि क्या होगा और फिर उस अनुमान की परख करने को","वह अमूर्त तर्क को बढ़ाने के लिए कक्षा 10 के लिए काल्पनिक ‘क्या हो अगर’ बहसों की योजना बनाती है"],"explanationHi":"पियाजे ने यह नहीं कहा कि शिक्षकों को सारी सहायता रोक लेनी चाहिए; उन्होंने उपयुक्त अनुभव और चुनौतियाँ देने की सलाह दी। अन्य विकल्प उनके सिद्धांत के विवेकपूर्ण अनुप्रयोग हैं।"},
  {"id":"cdp-child-development-775","question":"A two-and-a-half-year-old insists on putting on his own chappals and pouring his own water. His grandmother always does it for him and scolds him loudly whenever he spills. According to Erikson, the child is at risk of developing:","options":["Basic mistrust","Guilt","Shame and doubt","A sense of inferiority"],"answer":2,"explanation":"Toddlers face autonomy versus shame and doubt; overprotection and ridicule of failed attempts breed doubt in their own abilities. Guilt belongs to the next stage (initiative, about 3–6 years).","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"ढाई वर्ष का एक बच्चा अपनी चप्पलें स्वयं पहनने और अपना पानी स्वयं उँडेलने पर अड़ा रहता है। उसकी दादी हमेशा यह उसके लिए कर देती हैं और जब भी वह पानी छलकाता है तो ज़ोर से डाँटती हैं। एरिक्सन के अनुसार बच्चे में किसके विकसित होने का जोखिम है?","optionsHi":["मूल अविश्वास","अपराध-बोध","लज्जा और संदेह","हीनता की भावना"],"explanationHi":"नन्हे बच्चे स्वायत्तता बनाम लज्जा और संदेह का सामना करते हैं; अति-संरक्षण और असफल प्रयासों का उपहास अपनी क्षमताओं में संदेह उत्पन्न करता है। अपराध-बोध अगली अवस्था (पहल, लगभग 3–6 वर्ष) का है।"},
  {"id":"cdp-child-development-776","question":"A 48-year-old teacher spends her weekends running a free library for village children and mentoring newly joined teachers. Erikson would see this as a healthy resolution of:","options":["Integrity versus despair","Intimacy versus isolation","Industry versus inferiority","Generativity versus stagnation"],"answer":3,"explanation":"Middle adulthood’s task is generativity: guiding and contributing to the next generation. Integrity versus despair is the late-life review of one’s life.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"48 वर्ष की एक शिक्षिका अपने सप्ताहांत गाँव के बच्चों के लिए निःशुल्क पुस्तकालय चलाने और नवनियुक्त शिक्षकों का मार्गदर्शन करने में बिताती है। एरिक्सन इसे किसके स्वस्थ समाधान के रूप में देखते?","optionsHi":["सत्यनिष्ठा बनाम निराशा","घनिष्ठता बनाम अलगाव","उद्यमिता बनाम हीनता","जननात्मकता बनाम ठहराव"],"explanationHi":"मध्य वयस्कता का कार्य जननात्मकता है: अगली पीढ़ी का मार्गदर्शन करना और उसमें योगदान देना। सत्यनिष्ठा बनाम निराशा जीवन के अंतिम चरण में अपने जीवन की समीक्षा है।"},
  {"id":"cdp-child-development-777","question":"A retired headmaster says, ‘I made mistakes, but on the whole my life was worthwhile, and I am at peace with it.’ Another says, ‘My life was wasted, and now there is no time left to fix anything.’ The two represent the poles of Erikson’s stage of:","options":["Integrity versus despair","Generativity versus stagnation","Identity versus role confusion","Intimacy versus isolation"],"answer":0,"explanation":"In late adulthood people review their lives; acceptance gives integrity (and wisdom), regret and bitterness give despair.","difficulty":"moderate","source":"KVS PRT · NVS","questionHi":"एक सेवानिवृत्त प्रधानाध्यापक कहता है, ‘मुझसे गलतियाँ हुईं, पर कुल मिलाकर मेरा जीवन सार्थक रहा, और मैं उससे शांत हूँ।’ दूसरा कहता है, ‘मेरा जीवन व्यर्थ गया, और अब कुछ सुधारने का समय नहीं बचा।’ दोनों एरिक्सन की किस अवस्था के दो ध्रुवों को दर्शाते हैं?","optionsHi":["सत्यनिष्ठा बनाम निराशा","जननात्मकता बनाम ठहराव","पहचान बनाम भूमिका-भ्रम","घनिष्ठता बनाम अलगाव"],"explanationHi":"उत्तर वयस्कता में लोग अपने जीवन की समीक्षा करते हैं; स्वीकृति सत्यनिष्ठा (और विवेक) देती है, पश्चाताप और कड़वाहट निराशा देती है।"},
  {"id":"cdp-child-development-778","question":"Match Erikson’s stages with the virtue (ego strength) each gives when favourably resolved: 1. Trust vs mistrust 2. Autonomy vs shame and doubt 3. Initiative vs guilt 4. Industry vs inferiority; a. Competence b. Will c. Hope d. Purpose","options":["1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-b, 2-c, 3-d, 4-a","1-c, 2-b, 3-a, 4-d"],"answer":0,"explanation":"Erikson’s virtues: trust gives hope, autonomy gives will, initiative gives purpose, industry gives competence.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एरिक्सन की अवस्थाओं का मिलान उस गुण (अहं-शक्ति) से कीजिए जो अनुकूल समाधान होने पर प्रत्येक देती है: 1. विश्वास बनाम अविश्वास 2. स्वायत्तता बनाम लज्जा और संदेह 3. पहल बनाम अपराध-बोध 4. उद्यमिता बनाम हीनता; a. सक्षमता b. इच्छा-शक्ति c. आशा d. उद्देश्य","optionsHi":["1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-b, 2-c, 3-d, 4-a","1-c, 2-b, 3-a, 4-d"],"explanationHi":"एरिक्सन के गुण: विश्वास से आशा, स्वायत्तता से इच्छा-शक्ति, पहल से उद्देश्य, उद्यमिता से सक्षमता मिलती है।"},
  {"id":"cdp-child-development-779","question":"Which statement correctly describes how Erikson’s theory differs from Freud’s?","options":["Erikson stressed the id and sexual drives even more strongly than Freud had","Erikson stressed society’s role in ego growth and extended the stages across the lifespan","Erikson ended development at puberty, while Freud extended his stages into old age","Erikson rejected developmental stages altogether in favour of continuous growth"],"answer":1,"explanation":"Erikson kept a stage approach but shifted the focus from psychosexual drives to psychosocial tasks shaped by society, and added stages through adulthood; Freud’s stages end with the genital stage at puberty.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"कौन-सा कथन सही ढंग से वर्णन करता है कि एरिक्सन का सिद्धांत फ्रायड से कैसे भिन्न है?","optionsHi":["एरिक्सन ने फ्रायड से भी अधिक दृढ़ता से इड और यौन प्रेरणाओं पर बल दिया","एरिक्सन ने अहं के विकास में समाज की भूमिका पर बल दिया और अवस्थाओं को पूरे जीवनकाल में फैलाया","एरिक्सन ने विकास को यौवन पर समाप्त कर दिया, जबकि फ्रायड ने अपनी अवस्थाएँ वृद्धावस्था तक बढ़ाईं","एरिक्सन ने सतत विकास के पक्ष में विकासात्मक अवस्थाओं को पूरी तरह अस्वीकार कर दिया"],"explanationHi":"एरिक्सन ने अवस्था-उपागम रखा पर ध्यान मनोलैंगिक प्रेरणाओं से हटाकर समाज द्वारा आकारित मनोसामाजिक कार्यों पर किया, और वयस्कता तक अवस्थाएँ जोड़ीं; फ्रायड की अवस्थाएँ यौवन पर जननेंद्रिय अवस्था के साथ समाप्त होती हैं।"},
  {"id":"cdp-child-development-780","question":"Erikson’s ‘epigenetic principle’ implies that:","options":["Personality is fixed by genes, so the stages unfold the same way whatever the experience","Each person creates his or her own order of stages according to personal needs","Each strength has its own time of ascendancy in a fixed sequence, building on earlier stages","The stages can be completed in any order, depending on what the culture demands first"],"answer":2,"explanation":"Borrowed from embryology, the principle means each psychosocial strength has a critical time of ascendancy within a fixed sequence, with later stages built on earlier resolutions; it does not mean genetic determinism.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एरिक्सन का ‘एपिजेनेटिक सिद्धांत’ यह संकेत देता है कि:","optionsHi":["व्यक्तित्व जीनों से निश्चित है, इसलिए अनुभव कैसा भी हो अवस्थाएँ उसी प्रकार प्रकट होती हैं","प्रत्येक व्यक्ति अपनी व्यक्तिगत आवश्यकताओं के अनुसार अवस्थाओं का अपना क्रम बनाता है","प्रत्येक शक्ति का एक निश्चित क्रम में अपना प्रभुत्व का समय होता है, जो पहले की अवस्थाओं पर निर्मित होता है","संस्कृति पहले क्या माँगती है इसके अनुसार अवस्थाएँ किसी भी क्रम में पूरी की जा सकती हैं"],"explanationHi":"भ्रूणविज्ञान से लिया गया यह सिद्धांत बताता है कि प्रत्येक मनोसामाजिक शक्ति का एक निश्चित क्रम में प्रभुत्व का क्रांतिक समय होता है, जिसमें बाद की अवस्थाएँ पहले के समाधानों पर निर्मित होती हैं; इसका अर्थ आनुवंशिक नियतिवाद नहीं है।"},
  {"id":"cdp-child-development-781","question":"Kartik, in Class 12, says firmly, ‘I will be a chartered accountant like my father; it was decided long ago.’ He has never considered any other option or asked himself what he enjoys. In Marcia’s extension of Erikson, his identity status is:","options":["Identity achievement","Moratorium","Identity diffusion","Foreclosure"],"answer":3,"explanation":"Foreclosure is commitment without exploration, often by adopting parents’ choices. Achievement requires commitment after a period of exploration.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 12 का कार्तिक दृढ़ता से कहता है, ‘मैं अपने पिता की तरह चार्टर्ड अकाउंटेंट बनूँगा; यह बहुत पहले तय हो चुका है।’ उसने कभी किसी अन्य विकल्प पर विचार नहीं किया है और न स्वयं से पूछा है कि उसे क्या अच्छा लगता है। एरिक्सन के मार्सिया-विस्तार में उसकी पहचान की स्थिति है:","optionsHi":["पहचान उपलब्धि","स्थगन (मोरेटोरियम)","पहचान विसरण","पूर्वनिर्धारण (फ़ोरक्लोज़र)"],"explanationHi":"पूर्वनिर्धारण अन्वेषण के बिना प्रतिबद्धता है, प्रायः माता-पिता के चुनावों को अपनाकर। उपलब्धि के लिए अन्वेषण की अवधि के बाद प्रतिबद्धता आवश्यक है।"},
  {"id":"cdp-child-development-782","question":"Simran, in Class 11, is attending career talks, doing a summer internship at a clinic and talking to designers and journalists, but has not yet decided what she wants to be. Her identity status, in Marcia’s terms, is:","options":["Foreclosure","Moratorium","Identity diffusion","Identity achievement"],"answer":1,"explanation":"Moratorium means active exploration without commitment yet; it is a healthy phase, not a disorder, and usually leads to identity achievement.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 11 की सिमरन करियर वार्ताओं में भाग ले रही है, एक क्लिनिक में ग्रीष्मकालीन इंटर्नशिप कर रही है और डिज़ाइनरों तथा पत्रकारों से बात कर रही है, पर उसने अभी तय नहीं किया है कि वह क्या बनना चाहती है। मार्सिया के शब्दों में उसकी पहचान की स्थिति है:","optionsHi":["पूर्वनिर्धारण","स्थगन (मोरेटोरियम)","पहचान विसरण","पहचान उपलब्धि"],"explanationHi":"स्थगन का अर्थ है अभी प्रतिबद्धता के बिना सक्रिय अन्वेषण; यह एक स्वस्थ चरण है, विकार नहीं, और प्रायः पहचान उपलब्धि की ओर ले जाता है।"},
  {"id":"cdp-child-development-783","question":"A Class 10 boy says, ‘I don’t know what I want and I don’t care; whatever happens will happen.’ He has not explored any options and has no plans. This identity status is:","options":["Identity diffusion","Moratorium","Foreclosure","Negative identity"],"answer":0,"explanation":"Diffusion is the absence of both exploration and commitment. Moratorium involves active exploration; foreclosure involves commitment without exploration.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"कक्षा 10 का एक लड़का कहता है, ‘मुझे नहीं पता मैं क्या चाहता हूँ और मुझे परवाह भी नहीं; जो होगा सो होगा।’ उसने कोई विकल्प नहीं टटोला है और उसकी कोई योजना नहीं है। यह पहचान की स्थिति है:","optionsHi":["पहचान विसरण","स्थगन (मोरेटोरियम)","पूर्वनिर्धारण (फ़ोरक्लोज़र)","नकारात्मक पहचान"],"explanationHi":"विसरण अन्वेषण और प्रतिबद्धता दोनों का अभाव है। स्थगन में सक्रिय अन्वेषण होता है; पूर्वनिर्धारण में अन्वेषण के बिना प्रतिबद्धता।"},
  {"id":"cdp-child-development-784","question":"Match the students with Marcia’s identity statuses. P: Explored science, arts and sports, then chose to become a teacher and is committed to it. Q: Became a doctor because the family decided, without exploring. R: Is still trying out options, undecided. S: Neither explores nor cares to decide.","options":["P-moratorium, Q-foreclosure, R-achievement, S-diffusion","P-achievement, Q-diffusion, R-moratorium, S-foreclosure","P-achievement, Q-foreclosure, R-moratorium, S-diffusion","P-foreclosure, Q-achievement, R-diffusion, S-moratorium"],"answer":2,"explanation":"Achievement is exploration then commitment; foreclosure is commitment without exploration; moratorium is exploration without commitment; diffusion is neither.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"विद्यार्थियों का मिलान मार्सिया की पहचान-स्थितियों से कीजिए। P: विज्ञान, कला और खेलों को टटोला, फिर शिक्षक बनना चुना और उसके प्रति प्रतिबद्ध है। Q: परिवार के निर्णय से बिना टटोले डॉक्टर बना। R: अब भी विकल्प आज़मा रहा है, अनिर्णीत। S: न टटोलता है और न तय करने की परवाह करता है।","optionsHi":["P-स्थगन, Q-पूर्वनिर्धारण, R-उपलब्धि, S-विसरण","P-उपलब्धि, Q-विसरण, R-स्थगन, S-पूर्वनिर्धारण","P-उपलब्धि, Q-पूर्वनिर्धारण, R-स्थगन, S-विसरण","P-पूर्वनिर्धारण, Q-उपलब्धि, R-विसरण, S-स्थगन"],"explanationHi":"उपलब्धि अन्वेषण के बाद प्रतिबद्धता है; पूर्वनिर्धारण अन्वेषण के बिना प्रतिबद्धता है; स्थगन प्रतिबद्धता के बिना अन्वेषण है; विसरण दोनों का अभाव है।"},
  {"id":"cdp-child-development-785","question":"A Class 4 child, after poor marks in two tests, says, ‘I am useless at everything.’ Which response by the teacher best fits Erikson’s view of this stage?","options":["Tell him to work harder because his classmates are doing better, to spur him on","Give him tasks he can succeed at, point out real progress, and avoid comparing him","Excuse him from tests for a while until he starts feeling better about himself","Tell him that marks do not matter at all at his age, so he need not worry"],"answer":1,"explanation":"Industry versus inferiority is resolved through experiences of real competence and recognition of effort; comparison deepens inferiority, while excusing him or dismissing marks gives no experience of mastery.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"दो परीक्षाओं में कम अंकों के बाद कक्षा 4 का एक बच्चा कहता है, ‘मैं हर चीज़ में बेकार हूँ।’ इस अवस्था के बारे में एरिक्सन के मत के सबसे अनुरूप शिक्षक की प्रतिक्रिया क्या है?","optionsHi":["उसे कठिन परिश्रम करने को कहना क्योंकि उसके सहपाठी बेहतर कर रहे हैं, ताकि उसे प्रोत्साहन मिले","उसे ऐसे कार्य देना जिनमें वह सफल हो सके, वास्तविक प्रगति की ओर संकेत करना, और उसकी तुलना से बचना","कुछ समय तक उसे परीक्षाओं से छूट देना जब तक वह अपने बारे में बेहतर महसूस न करने लगे","उसे बताना कि इस आयु में अंक बिल्कुल मायने नहीं रखते, इसलिए चिंता की आवश्यकता नहीं"],"explanationHi":"उद्यमिता बनाम हीनता का समाधान वास्तविक सक्षमता के अनुभवों और प्रयास की पहचान से होता है; तुलना हीनता को गहरा करती है, जबकि छूट देना या अंकों को नकारना निपुणता का कोई अनुभव नहीं देता।"},
  {"id":"cdp-child-development-786","question":"In one pre-school, children plan their own activity corners, take on roles in pretend play and try new ideas, while mess is calmly cleaned up together. In another, children who start their own activities are scolded for ‘creating nuisance’. In Erikson’s terms, the second pre-school risks fostering:","options":["Mistrust","Inferiority","Role confusion","Guilt"],"answer":3,"explanation":"Children of about 3–6 face initiative versus guilt; punishing self-started activity makes them feel guilty about their own plans and aims. Inferiority is the risk of the next, school-age stage.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"एक पूर्व-विद्यालय में बच्चे अपने गतिविधि-कोने स्वयं योजनाबद्ध करते हैं, दिखावटी खेल में भूमिकाएँ लेते हैं और नए विचार आज़माते हैं, जबकि गंदगी को शांति से मिलकर साफ़ किया जाता है। दूसरे में, स्वयं गतिविधि शुरू करने वाले बच्चों को ‘उपद्रव करने’ के लिए डाँटा जाता है। एरिक्सन के शब्दों में, दूसरे पूर्व-विद्यालय में किसके पनपने का जोखिम है?","optionsHi":["अविश्वास","हीनता","भूमिका-भ्रम","अपराध-बोध"],"explanationHi":"लगभग 3–6 वर्ष के बच्चे पहल बनाम अपराध-बोध का सामना करते हैं; स्वयं शुरू की गई गतिविधि को दंडित करने से वे अपनी योजनाओं और लक्ष्यों के बारे में अपराधी महसूस करते हैं। हीनता अगली, विद्यालय-आयु अवस्था का जोखिम है।"},
  {"id":"cdp-child-development-787","question":"According to Erikson, what most determines whether an infant develops basic trust?","options":["The quantity of food the infant receives each day","The infant’s inborn intelligence","The consistency, warmth and predictability of the care given","The number of toys and stimulating objects provided in the first year"],"answer":2,"explanation":"Trust grows from the quality of care: reliable, responsive caregiving that makes the world feel predictable. Erikson stressed quality of the relationship over quantity of food or stimulation.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एरिक्सन के अनुसार, किस बात से सबसे अधिक निर्धारित होता है कि शिशु में मूल विश्वास विकसित होता है या नहीं?","optionsHi":["शिशु को प्रतिदिन मिलने वाले भोजन की मात्रा","शिशु की जन्मजात बुद्धि","दी जाने वाली देखभाल की संगति, स्नेह और पूर्वानुमेयता","पहले वर्ष में दिए गए खिलौनों और उद्दीपक वस्तुओं की संख्या"],"explanationHi":"विश्वास देखभाल की गुणवत्ता से बढ़ता है: विश्वसनीय, संवेदनशील देखभाल जो संसार को पूर्वानुमेय बनाती है। एरिक्सन ने भोजन या उद्दीपन की मात्रा से अधिक संबंध की गुणवत्ता पर बल दिया।"},
  {"id":"cdp-child-development-788","question":"A Class 8 student, neglected in early childhood, finds it hard to trust teachers and assumes they mean her harm. Which statement is most consistent with Erikson’s theory?","options":["Her personality was fixed in infancy, so school can do little to change it now","Crises are never settled for good; warm, reliable adults now can help her rework trust","She is facing the trust versus mistrust stage again simply because she is an adolescent","Mistrust is always harmful, so the healthy goal is a child with no mistrust at all"],"answer":1,"explanation":"Erikson saw outcomes as a balance that can be revisited; later positive experiences can strengthen trust. Some mistrust is healthy; the goal is a favourable ratio, not its total absence.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 की एक विद्यार्थी, जिसकी प्रारंभिक बाल्यावस्था में उपेक्षा हुई थी, शिक्षकों पर विश्वास करना कठिन पाती है और मान लेती है कि वे उसका अहित चाहते हैं। एरिक्सन के सिद्धांत से कौन-सा कथन सबसे अधिक संगत है?","optionsHi":["उसका व्यक्तित्व शैशव में ही निश्चित हो गया था, इसलिए विद्यालय अब उसे बदलने के लिए बहुत कम कर सकता है","संकट कभी हमेशा के लिए नहीं सुलझते; अब स्नेही, विश्वसनीय वयस्क उसे विश्वास को पुनः गढ़ने में सहायता कर सकते हैं","वह किशोर होने के कारण ही विश्वास बनाम अविश्वास की अवस्था का फिर सामना कर रही है","अविश्वास सदैव हानिकारक है, इसलिए स्वस्थ लक्ष्य ऐसा बच्चा है जिसमें बिल्कुल अविश्वास न हो"],"explanationHi":"एरिक्सन परिणामों को एक संतुलन मानते थे जिस पर पुनः काम हो सकता है; बाद के सकारात्मक अनुभव विश्वास को सुदृढ़ कर सकते हैं। कुछ अविश्वास स्वस्थ है; लक्ष्य अनुकूल अनुपात है, उसका पूर्ण अभाव नहीं।"},
  {"id":"cdp-child-development-789","question":"Which school practice best supports the main psychosocial task Erikson identified for secondary students?","options":["Fixing each student’s stream in Class 8 on the basis of marks alone, to avoid confusion","Offering clubs, projects and community roles so students can explore who they are","Discouraging students from discussing their values, so they can focus on exams","Insisting that all students follow the same career path for discipline’s sake"],"answer":1,"explanation":"Adolescents face identity versus role confusion; varied, safe opportunities to explore roles and values help them form a coherent identity, whereas early fixing forces foreclosure.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"माध्यमिक विद्यार्थियों के लिए एरिक्सन द्वारा पहचाने गए मुख्य मनोसामाजिक कार्य का कौन-सी विद्यालयी प्रथा सबसे अच्छा समर्थन करती है?","optionsHi":["भ्रम से बचने के लिए केवल अंकों के आधार पर कक्षा 8 में प्रत्येक विद्यार्थी की धारा तय कर देना","क्लब, परियोजनाएँ और सामुदायिक भूमिकाएँ देना ताकि विद्यार्थी अन्वेषण कर सकें कि वे कौन हैं","विद्यार्थियों को अपने मूल्यों पर चर्चा करने से हतोत्साहित करना, ताकि वे परीक्षाओं पर ध्यान दें","अनुशासन के नाम पर सभी विद्यार्थियों से एक ही करियर-पथ अपनाने का आग्रह करना"],"explanationHi":"किशोर पहचान बनाम भूमिका-भ्रम का सामना करते हैं; भूमिकाओं और मूल्यों को टटोलने के विविध, सुरक्षित अवसर उन्हें सुसंगत पहचान बनाने में सहायता करते हैं, जबकि जल्दी निर्धारित कर देना पूर्वनिर्धारण को विवश करता है।"},
  {"id":"cdp-child-development-790","question":"Erikson used the term ‘psychosocial moratorium’ to describe:","options":["A permanent failure to form an identity, leaving the youth without direction","A punishment given to adolescents who break social rules, suspending privileges","A stage in early childhood when the child withdraws from others for a time","A period society allows youth to explore roles before adult commitments"],"answer":3,"explanation":"The moratorium is a socially sanctioned delay of adult duties, such as the years of higher education, in which youth can experiment with roles. Permanent failure would be role confusion.","difficulty":"very-hard","source":"CTET Paper 2 · State TET","questionHi":"एरिक्सन ने ‘मनोसामाजिक स्थगन (साइकोसोशल मोरेटोरियम)’ शब्द का प्रयोग किसका वर्णन करने के लिए किया?","optionsHi":["पहचान बनाने में स्थायी विफलता, जो किशोर को दिशाहीन छोड़ देती है","सामाजिक नियम तोड़ने वाले किशोरों को दिया गया दंड, जिसमें विशेषाधिकार निलंबित किए जाते हैं","प्रारंभिक बाल्यावस्था की एक अवस्था जब बच्चा कुछ समय के लिए दूसरों से हट जाता है","वह अवधि जो समाज किशोरों को वयस्क प्रतिबद्धताओं से पहले भूमिकाएँ टटोलने के लिए देता है"],"explanationHi":"स्थगन वयस्क कर्तव्यों की सामाजिक रूप से स्वीकृत देरी है, जैसे उच्च शिक्षा के वर्ष, जिसमें किशोर भूमिकाओं के साथ प्रयोग कर सकते हैं। स्थायी विफलता भूमिका-भ्रम होगी।"},
  {"id":"cdp-child-development-791","question":"Assertion (A): Erikson’s theory is called a psychosocial theory. Reason (R): He held that the crisis at each stage arises from the meeting of the individual’s maturing needs and abilities with the demands of society.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Each crisis is psychological and social at once: the growing person meets new social demands, which is exactly why the theory is psychosocial.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"अभिकथन (A): एरिक्सन के सिद्धांत को मनोसामाजिक सिद्धांत कहा जाता है। कारण (R): उनका मत था कि प्रत्येक अवस्था का संकट व्यक्ति की परिपक्व होती आवश्यकताओं और क्षमताओं के समाज की माँगों से मिलने से उत्पन्न होता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"प्रत्येक संकट एक साथ मनोवैज्ञानिक और सामाजिक है: बढ़ता हुआ व्यक्ति नई सामाजिक माँगों से मिलता है, और यही कारण है कि सिद्धांत मनोसामाजिक है।"},
  {"id":"cdp-child-development-792","question":"Assertion (A): Erikson believed that personality development is complete by the end of adolescence. Reason (R): Erikson proposed eight stages spanning the entire lifespan.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Erikson’s stages continue into young, middle and late adulthood, so development does not end in adolescence; A is false and R is true.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): एरिक्सन का मानना था कि किशोरावस्था के अंत तक व्यक्तित्व का विकास पूर्ण हो जाता है। कारण (R): एरिक्सन ने संपूर्ण जीवनकाल में फैली आठ अवस्थाएँ प्रस्तावित कीं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"एरिक्सन की अवस्थाएँ युवा, मध्य और उत्तर वयस्कता में जारी रहती हैं, इसलिए विकास किशोरावस्था में समाप्त नहीं होता; A असत्य है और R सत्य।"},
  {"id":"cdp-child-development-793","question":"For a typical child in Classes 3 to 5, which stage of Erikson coincides with which stage of Piaget?","options":["Initiative versus guilt with the pre-operational stage","Industry versus inferiority with the concrete operational stage","Identity versus role confusion with the formal operational stage","Autonomy versus shame with the concrete operational stage"],"answer":1,"explanation":"Children of about 8–11 are in Erikson’s industry stage and Piaget’s concrete operational stage; both point to hands-on, achievable tasks that build competence.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 3 से 5 के किसी सामान्य बच्चे के लिए, एरिक्सन की कौन-सी अवस्था पियाजे की किस अवस्था के साथ मेल खाती है?","optionsHi":["पहल बनाम अपराध-बोध, पूर्व-संक्रियात्मक अवस्था के साथ","उद्यमिता बनाम हीनता, मूर्त संक्रियात्मक अवस्था के साथ","पहचान बनाम भूमिका-भ्रम, औपचारिक संक्रियात्मक अवस्था के साथ","स्वायत्तता बनाम लज्जा, मूर्त संक्रियात्मक अवस्था के साथ"],"explanationHi":"लगभग 8–11 वर्ष के बच्चे एरिक्सन की उद्यमिता अवस्था और पियाजे की मूर्त संक्रियात्मक अवस्था में होते हैं; दोनों हाथ से करने वाले, प्राप्य कार्यों की ओर संकेत करते हैं जो सक्षमता बनाते हैं।"},
  {"id":"cdp-child-development-794","question":"A 24-year-old B.Ed trainee keeps everyone at a distance and avoids close friendships, fearing that closeness will mean losing himself. Erikson would locate his difficulty in the stage of:","options":["Identity versus role confusion","Generativity versus stagnation","Intimacy versus isolation","Trust versus mistrust"],"answer":2,"explanation":"Young adults face intimacy versus isolation; Erikson held that people with a shaky identity fear that intimacy will swallow it, so they withdraw into isolation.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"24 वर्ष का एक B.Ed प्रशिक्षु सबको दूर रखता है और घनिष्ठ मित्रता से बचता है, इस भय से कि निकटता का अर्थ स्वयं को खोना होगा। एरिक्सन उसकी कठिनाई को किस अवस्था में रखते?","optionsHi":["पहचान बनाम भूमिका-भ्रम","जननात्मकता बनाम ठहराव","घनिष्ठता बनाम अलगाव","विश्वास बनाम अविश्वास"],"explanationHi":"युवा वयस्क घनिष्ठता बनाम अलगाव का सामना करते हैं; एरिक्सन का मत था कि अस्थिर पहचान वाले लोग डरते हैं कि घनिष्ठता उसे निगल लेगी, इसलिए वे अलगाव में हट जाते हैं।"},
  {"id":"cdp-child-development-795","question":"A Class 9 group mocks and excludes students who dress, speak or think differently from them. How did Erikson explain such adolescent clannishness?","options":["As a sign of a fixed antisocial personality that will persist into adulthood","As a carry-over of the autonomy versus shame crisis left unresolved in toddlerhood","As purely the result of imitating the violence and bullying they see in the media","As a temporary defence against identity confusion, borrowing a self from the group"],"answer":3,"explanation":"Erikson saw adolescent intolerance and over-identification with cliques as a defence against identity confusion; teachers can widen belonging and challenge exclusion without labelling the students as antisocial.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 9 का एक समूह उन विद्यार्थियों का मज़ाक उड़ाता और उन्हें बाहर करता है जो उनसे भिन्न ढंग से कपड़े पहनते, बोलते या सोचते हैं। एरिक्सन ने किशोरों की ऐसी गुटबाज़ी की व्याख्या कैसे की?","optionsHi":["एक स्थायी असामाजिक व्यक्तित्व के संकेत के रूप में जो वयस्कता तक बना रहेगा","नन्हे बच्चे की अवस्था में अनसुलझे रह गए स्वायत्तता बनाम लज्जा संकट के अवशेष के रूप में","केवल मीडिया में देखी गई हिंसा और धौंस की नकल के परिणाम के रूप में","पहचान-भ्रम के विरुद्ध एक अस्थायी रक्षा के रूप में, समूह से एक स्वयं उधार लेते हुए"],"explanationHi":"एरिक्सन किशोरों की असहिष्णुता और गुटों के साथ अति-तादात्म्य को पहचान-भ्रम के विरुद्ध रक्षा मानते थे; शिक्षक विद्यार्थियों को असामाजिक ठप्पा लगाए बिना अपनेपन को व्यापक कर सकते हैं और बहिष्करण को चुनौती दे सकते हैं।"},
  {"id":"cdp-child-development-796","question":"Which of these statements about Erikson’s theory are correct? I. Each stage poses a crisis whose favourable resolution supports healthy development. II. Favourable resolution means the negative pole, e.g. mistrust, is completely eliminated. III. The stages span the whole life. IV. Social relationships are central at every stage.","options":["I, III and IV only","I and II only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"Erikson saw healthy outcomes as a favourable balance; some mistrust or doubt is adaptive, so II is false. The others are core features of the theory.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एरिक्सन के सिद्धांत के बारे में इनमें से कौन-से कथन सही हैं? I. प्रत्येक अवस्था एक संकट प्रस्तुत करती है जिसका अनुकूल समाधान स्वस्थ विकास को सहारा देता है। II. अनुकूल समाधान का अर्थ है नकारात्मक ध्रुव, जैसे अविश्वास, का पूर्ण उन्मूलन। III. अवस्थाएँ संपूर्ण जीवन में फैली हैं। IV. प्रत्येक अवस्था में सामाजिक संबंध केंद्रीय हैं।","optionsHi":["केवल I, III और IV","केवल I और II","केवल II, III और IV","I, II, III और IV"],"explanationHi":"एरिक्सन स्वस्थ परिणामों को अनुकूल संतुलन मानते थे; कुछ अविश्वास या संदेह अनुकूली है, इसलिए II असत्य है। अन्य सिद्धांत की मूल विशेषताएँ हैं।"},
  {"id":"cdp-child-development-797","question":"Which practice in a primary school is most likely to push children toward the negative pole of Erikson’s fourth stage?","options":["Grouping children for cooperative projects in which every member has a role","Displaying class rank lists publicly and calling out the lowest scorers","Praising specific efforts and strategies rather than marks alone","Giving tasks of graded difficulty so that all children can succeed"],"answer":1,"explanation":"The fourth stage is industry versus inferiority; public ranking and shaming make low achievers feel incompetent. The other practices build a sense of competence.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"प्राथमिक विद्यालय में कौन-सी प्रथा बच्चों को एरिक्सन की चौथी अवस्था के नकारात्मक ध्रुव की ओर धकेलने की सबसे अधिक संभावना रखती है?","optionsHi":["बच्चों को सहकारी परियोजनाओं के लिए समूहबद्ध करना जिनमें प्रत्येक सदस्य की भूमिका हो","कक्षा-श्रेणी सूचियाँ सार्वजनिक रूप से प्रदर्शित करना और सबसे कम अंक पाने वालों का नाम पुकारना","केवल अंकों के बजाय विशिष्ट प्रयासों और युक्तियों की प्रशंसा करना","श्रेणीबद्ध कठिनाई वाले कार्य देना ताकि सभी बच्चे सफल हो सकें"],"explanationHi":"चौथी अवस्था उद्यमिता बनाम हीनता है; सार्वजनिक श्रेणीकरण और शर्मिंदा करना कम उपलब्धि वालों को अक्षम महसूस कराता है। अन्य प्रथाएँ सक्षमता की भावना बनाती हैं।"},
  {"id":"cdp-child-development-798","question":"Having explored several sets of beliefs, a Class 12 student settles on her own values and stays loyal to them and to her friends even under pressure. Which virtue did Erikson link to a favourable resolution of the adolescent crisis?","options":["Hope","Will","Competence","Fidelity"],"answer":3,"explanation":"Resolving identity versus role confusion yields fidelity: the ability to sustain loyalties freely pledged. Hope comes from trust, will from autonomy, competence from industry.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"विश्वासों के कई समूहों को टटोलने के बाद कक्षा 12 की एक विद्यार्थी अपने मूल्य स्वयं तय करती है और दबाव में भी उनके प्रति और अपने मित्रों के प्रति निष्ठावान रहती है। किशोर संकट के अनुकूल समाधान से एरिक्सन ने किस गुण को जोड़ा?","optionsHi":["आशा","इच्छा-शक्ति","सक्षमता","निष्ठा"],"explanationHi":"पहचान बनाम भूमिका-भ्रम का समाधान निष्ठा देता है: स्वतंत्र रूप से प्रतिज्ञा की गई वफ़ादारियों को बनाए रखने की क्षमता। आशा विश्वास से, इच्छा-शक्ति स्वायत्तता से, सक्षमता उद्यमिता से आती है।"},
  {"id":"cdp-child-development-799","question":"A Class 8 boy who is always noticed only when he misbehaves begins to proudly call himself ‘the class troublemaker’ and lives up to the label. Erikson described this as:","options":["A negative identity, built from roles presented to him as undesirable","Identity achievement, since he now has a clear and confident sense of self","Industry, since he has found something he is good at and gets noticed for","Initiative, since he takes charge of situations and acts on his own plans"],"answer":0,"explanation":"Erikson noted that youth denied a positive, recognised role may embrace a negative identity built from the very roles adults warn against; giving him valued roles is the remedy. It is not achievement, which requires exploration and freely chosen commitment.","difficulty":"very-hard","source":"CTET Paper 2 · State TET","questionHi":"कक्षा 8 का एक लड़का, जिस पर केवल तभी ध्यान दिया जाता है जब वह शरारत करता है, गर्व से स्वयं को ‘कक्षा का उपद्रवी’ कहने लगता है और उस लेबल पर खरा उतरता है। एरिक्सन ने इसका वर्णन क्या किया?","optionsHi":["नकारात्मक पहचान, उन भूमिकाओं से बनी जो उसके सामने अवांछनीय के रूप में प्रस्तुत की गई थीं","पहचान उपलब्धि, क्योंकि अब उसमें स्वयं की स्पष्ट और आत्मविश्वासी भावना है","उद्यमिता, क्योंकि उसने ऐसा कुछ पाया है जिसमें वह अच्छा है और जिसके लिए उस पर ध्यान जाता है","पहल, क्योंकि वह परिस्थितियों की कमान सँभालता है और अपनी योजनाओं पर कार्य करता है"],"explanationHi":"एरिक्सन ने देखा कि जिन किशोरों को सकारात्मक, मान्य भूमिका से वंचित रखा जाता है वे नकारात्मक पहचान अपना सकते हैं जो उन्हीं भूमिकाओं से बनी होती है जिनसे वयस्क सावधान करते हैं; उसे मूल्यवान भूमिकाएँ देना उपचार है। यह उपलब्धि नहीं है, जिसके लिए अन्वेषण और स्वतंत्र रूप से चुनी प्रतिबद्धता चाहिए।"},
  {"id":"cdp-child-development-800","question":"During noisy group work, Class 5 student Irfan is fully absorbed in his own group's chart, yet he immediately turns when someone at the far end of the room says his name. What does this show about attention?","options":["Irfan was not really attending to his group's work, only pretending to","Unattended input is still monitored at some level for personally important cues","Attention works mainly through sight, so hearing his name was mere chance","Divided attention is equally effective for all tasks, so he heard everything"],"answer":1,"explanation":"This is the cocktail-party effect: while we focus on one stream, unattended input is still processed at some level, so highly relevant cues like one's name can capture attention.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"शोरगुल वाले समूह-कार्य के दौरान कक्षा 5 का विद्यार्थी इरफ़ान अपने समूह के चार्ट में पूरी तरह तल्लीन है, फिर भी जब कमरे के दूर कोने में कोई उसका नाम लेता है तो वह तुरंत मुड़ जाता है। यह ध्यान के बारे में क्या दर्शाता है?","optionsHi":["इरफ़ान वास्तव में अपने समूह के कार्य पर ध्यान नहीं दे रहा था, केवल दिखावा कर रहा था","ध्यान न दिए गए निवेश की भी व्यक्तिगत रूप से महत्त्वपूर्ण संकेतों के लिए किसी स्तर पर निगरानी होती रहती है","ध्यान मुख्यतः दृष्टि से काम करता है, इसलिए अपना नाम सुनना मात्र संयोग था","विभाजित ध्यान सभी कार्यों के लिए समान रूप से प्रभावी है, इसलिए उसने सब कुछ सुन लिया"],"explanationHi":"यह कॉकटेल-पार्टी प्रभाव है: जब हम एक धारा पर ध्यान केंद्रित करते हैं, तब भी ध्यान न दिए गए निवेश का किसी स्तर पर प्रसंस्करण होता रहता है, इसलिए अपने नाम जैसे अत्यंत प्रासंगिक संकेत ध्यान खींच सकते हैं।"},
  {"id":"cdp-child-development-801","question":"Which of the following is a subjective (internal) determinant of attention rather than an objective one?","options":["A child's keen interest in cricket","A sudden loud sound in the corridor","A brightly coloured moving picture","A sharp contrast between a red word and black text"],"answer":0,"explanation":"Objective determinants lie in the stimulus: intensity, movement, novelty, contrast, change. Subjective determinants lie in the learner: interests, needs, motives, mental set.","difficulty":"moderate","source":"CTET · REET","questionHi":"निम्नलिखित में से कौन-सा ध्यान का वस्तुनिष्ठ नहीं बल्कि व्यक्तिनिष्ठ (आंतरिक) निर्धारक है?","optionsHi":["क्रिकेट में बच्चे की प्रबल रुचि","गलियारे में अचानक तेज़ आवाज़","चटक रंग का चलता हुआ चित्र","लाल शब्द और काले पाठ के बीच तीव्र विषमता"],"explanationHi":"वस्तुनिष्ठ निर्धारक उद्दीपक में होते हैं: तीव्रता, गति, नवीनता, विषमता, परिवर्तन। व्यक्तिनिष्ठ निर्धारक अधिगमकर्ता में होते हैं: रुचियाँ, आवश्यकताएँ, अभिप्रेरक, मानसिक झुकाव।"},
  {"id":"cdp-child-development-802","question":"A Class 1 teacher finds that her children grow restless during a 35-minute continuous story reading. Which response best fits what is known about young children's attention?","options":["Insist on silence so the children learn to attend for the full 35 minutes","Shorten the period to 5 minutes and cancel the story reading altogether","Split it into short segments with changes such as acting, questioning and drawing","Read faster so that the story ends before the children grow restless"],"answer":2,"explanation":"Young children's span of sustained attention is short; planned variation of activity renews attention while keeping the learning goal intact.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 की एक शिक्षिका पाती है कि 35 मिनट की निरंतर कहानी-वाचन के दौरान उसके बच्चे बेचैन हो जाते हैं। छोटे बच्चों के ध्यान के बारे में ज्ञात तथ्यों से कौन-सी प्रतिक्रिया सबसे अधिक मेल खाती है?","optionsHi":["चुप्पी पर ज़ोर देना ताकि बच्चे पूरे 35 मिनट ध्यान देना सीखें","कालांश को 5 मिनट तक घटा देना और कहानी-वाचन पूरी तरह रद्द कर देना","इसे छोटे खंडों में बाँटना, जिनके बीच अभिनय, प्रश्न पूछना और चित्र बनाना जैसे बदलाव हों","तेज़ पढ़ना ताकि बच्चों के बेचैन होने से पहले कहानी समाप्त हो जाए"],"explanationHi":"छोटे बच्चों के निरंतर ध्यान की अवधि कम होती है; गतिविधि में नियोजित विविधता ध्यान को नवीन करती है और अधिगम-लक्ष्य अक्षुण्ण रखती है।"},
  {"id":"cdp-child-development-803","question":"Class 6 students are asked to copy long notes from the board while the teacher simultaneously explains a new and difficult concept. Most remember little of the explanation. The most accurate explanation is that:","options":["The students are simply not motivated, so they chose to ignore the explanation","Copying is a purely automatic skill, so it cannot interfere with listening","Listening to explanations is not possible for children under twelve","Both tasks need controlled attention, so dividing it lowers performance on each"],"answer":3,"explanation":"Divided attention works only when at least one task is highly automatic. Copying unfamiliar notes and processing new ideas both draw on limited attentional capacity.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 6 के विद्यार्थियों से श्यामपट्ट से लंबे नोट्स उतारने को कहा जाता है, जबकि शिक्षक साथ-साथ एक नया और कठिन संप्रत्यय समझा रहा है। अधिकांश को व्याख्या का बहुत कम याद रहता है। सबसे सटीक व्याख्या है कि:","optionsHi":["विद्यार्थी बस अभिप्रेरित नहीं हैं, इसलिए उन्होंने व्याख्या को अनदेखा करना चुना","उतारना पूरी तरह स्वचालित कौशल है, इसलिए वह सुनने में बाधा नहीं डाल सकता","बारह वर्ष से कम उम्र के बच्चों के लिए व्याख्याएँ सुनना संभव नहीं है","दोनों कार्यों को नियंत्रित ध्यान चाहिए, इसलिए उसे बाँटने से प्रत्येक पर निष्पादन घटता है"],"explanationHi":"विभाजित ध्यान तभी काम करता है जब कम से कम एक कार्य अत्यधिक स्वचालित हो। अपरिचित नोट्स उतारना और नए विचारों का प्रसंस्करण दोनों सीमित ध्यान-क्षमता का उपयोग करते हैं।"},
  {"id":"cdp-child-development-804","question":"Children stop noticing the steady hum of the ceiling fan, and in the same way they drift off when a teacher speaks in a flat monotone for a long time. When she suddenly lowers her voice to a whisper, all heads turn. This is explained by:","options":["Habituation to unchanging stimuli, and recapture of attention by change","Proactive interference, where earlier words block attention to new ones","Classical conditioning of the voice as a signal to stop listening","Learned helplessness, as children give up trying to follow the talk"],"answer":0,"explanation":"Attention habituates to constant stimuli; change, contrast and novelty are powerful objective determinants that recapture it.","difficulty":"moderate","source":"CTET · UPTET","questionHi":"बच्चे छत के पंखे की लगातार गूँज पर ध्यान देना बंद कर देते हैं, और उसी तरह जब शिक्षक लंबे समय तक सपाट एकस्वर में बोलती है तो वे ऊँघने लगते हैं। जब वह अचानक अपनी आवाज़ फुसफुसाहट तक धीमी कर देती है, तो सभी सिर मुड़ जाते हैं। इसकी व्याख्या है:","optionsHi":["अपरिवर्तित उद्दीपकों के प्रति अभ्यस्तता, और परिवर्तन द्वारा ध्यान की पुनः प्राप्ति","अग्रोन्मुख व्यवधान, जहाँ पहले के शब्द नए शब्दों पर ध्यान को रोकते हैं","आवाज़ का शास्त्रीय अनुबंधन, सुनना बंद करने के संकेत के रूप में","सीखी हुई असहायता, क्योंकि बच्चे वार्ता का अनुसरण करने का प्रयास छोड़ देते हैं"],"explanationHi":"ध्यान स्थिर उद्दीपकों के प्रति अभ्यस्त हो जाता है; परिवर्तन, विषमता और नवीनता शक्तिशाली वस्तुनिष्ठ निर्धारक हैं जो उसे पुनः प्राप्त करते हैं।"},
  {"id":"cdp-child-development-805","question":"Before a reading passage on the Chipko movement, a teacher says, ‘As you read, find three reasons why villagers hugged the trees.’ This instruction improves learning mainly because it:","options":["Rewards the students in advance, so that they read more willingly","Creates a mental set that directs attention to relevant information","Reduces the length of the passage that students actually have to read","Tests long-term memory directly by asking for facts from earlier lessons"],"answer":1,"explanation":"A purpose or mental set given in advance is a subjective determinant of attention; it guides readers to select and process the information that matters.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"चिपको आंदोलन पर पठन-गद्यांश से पहले शिक्षक कहता है, ‘पढ़ते समय पता लगाओ कि ग्रामीण पेड़ों से क्यों लिपटे, इसके तीन कारण।’ यह निर्देश अधिगम को मुख्यतः इसलिए सुधारता है क्योंकि वह:","optionsHi":["विद्यार्थियों को पहले से पुरस्कृत करता है, ताकि वे अधिक इच्छा से पढ़ें","एक मानसिक झुकाव बनाता है जो ध्यान को प्रासंगिक जानकारी की ओर निर्देशित करता है","विद्यार्थियों को वास्तव में पढ़ना पड़ने वाले गद्यांश की लंबाई घटा देता है","पहले के पाठों के तथ्य पूछकर दीर्घकालिक स्मृति की सीधे परीक्षा लेता है"],"explanationHi":"पहले से दिया गया प्रयोजन या मानसिक झुकाव ध्यान का व्यक्तिनिष्ठ निर्धारक है; वह पाठकों को उस जानकारी को चुनने और प्रसंस्कृत करने के लिए निर्देशित करता है जो मायने रखती है।"},
  {"id":"cdp-child-development-806","question":"Class 3 children who loved drawing in free time were promised and given a prize every time they drew for a class contest. Weeks after the contest ended, they spent much less free time drawing than children who had never been given prizes. This is best explained by:","options":["Spontaneous recovery of their earlier, weaker interest in drawing","Vicarious reinforcement from watching other children win prizes","Overjustification, where expected rewards undermine intrinsic interest","Negative reinforcement, since drawing became linked with contest stress"],"answer":2,"explanation":"When an expected, tangible reward is given for an activity already enjoyed, children may come to see the reward as the reason for doing it, so interest drops once rewards stop.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 3 के जिन बच्चों को खाली समय में चित्र बनाना पसंद था, उन्हें कक्षा-प्रतियोगिता के लिए हर बार चित्र बनाने पर पुरस्कार का वादा किया गया और दिया गया। प्रतियोगिता समाप्त होने के सप्ताहों बाद, उन्होंने उन बच्चों की तुलना में खाली समय में चित्र बनाने में बहुत कम समय लगाया जिन्हें कभी पुरस्कार नहीं दिए गए थे। इसकी सबसे अच्छी व्याख्या है:","optionsHi":["चित्र बनाने में उनकी पहले की, कमज़ोर रुचि की स्वतःस्फूर्त पुनःप्राप्ति","अन्य बच्चों को पुरस्कार जीतते देखने से प्रतिनिधिक पुनर्बलन","अति-औचित्य (ओवरजस्टिफ़िकेशन), जहाँ अपेक्षित पुरस्कार आंतरिक रुचि को कमज़ोर करते हैं","नकारात्मक पुनर्बलन, क्योंकि चित्र बनाना प्रतियोगिता के तनाव से जुड़ गया"],"explanationHi":"जब किसी ऐसी गतिविधि के लिए, जिसमें पहले से आनंद आता है, अपेक्षित, मूर्त पुरस्कार दिया जाता है, तो बच्चे पुरस्कार को उसे करने का कारण मानने लगते हैं, इसलिए पुरस्कार बंद होने पर रुचि घट जाती है।"},
  {"id":"cdp-child-development-807","question":"Which form of feedback is most likely to support a Class 6 child's intrinsic motivation, according to self-determination research?","options":["‘Good, you did exactly what I told you to do in the instructions.’","‘You must keep this up, or you will lose your star on the chart.’","‘You are the best in the class, far better than everyone else.’","‘The way you used dark colours for the storm really shows the mood.’"],"answer":3,"explanation":"Specific, informational feedback signals competence without control. Controlling or comparative praise shifts focus to pleasing others or to rank, which tends to lower intrinsic motivation.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"आत्म-निर्धारण शोध के अनुसार, कक्षा 6 के बच्चे की आंतरिक अभिप्रेरणा का समर्थन करने की सबसे अधिक संभावना किस प्रकार की प्रतिपुष्टि में है?","optionsHi":["‘अच्छा, तुमने ठीक वही किया जो मैंने निर्देशों में करने को कहा था।’","‘तुम्हें यह जारी रखना होगा, नहीं तो चार्ट पर तुम्हारा सितारा चला जाएगा।’","‘तुम कक्षा में सबसे अच्छे हो, बाकी सबसे कहीं बेहतर।’","‘तूफ़ान के लिए तुमने गहरे रंगों का जिस तरह उपयोग किया, वह वास्तव में मनोभाव दिखाता है।’"],"explanationHi":"विशिष्ट, सूचनात्मक प्रतिपुष्टि नियंत्रण के बिना सक्षमता का संकेत देती है। नियंत्रणकारी या तुलनात्मक प्रशंसा ध्यान को दूसरों को प्रसन्न करने या श्रेणी पर केंद्रित करती है, जो आंतरिक अभिप्रेरणा को घटाती है।"},
  {"id":"cdp-child-development-808","question":"A Class 8 teacher allows students to choose the topic of their science project from a list, lets them decide how to present it, and explains why the project matters. According to Deci and Ryan's self-determination theory, she is mainly supporting the need for:","options":["Autonomy","Safety","Physiological comfort","Competition"],"answer":0,"explanation":"Self-determination theory names three basic psychological needs: autonomy, competence and relatedness. Meaningful choice and a rationale support autonomy.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 की एक शिक्षिका विद्यार्थियों को एक सूची से अपनी विज्ञान परियोजना का विषय चुनने देती है, उन्हें स्वयं तय करने देती है कि उसे कैसे प्रस्तुत करें, और समझाती है कि परियोजना क्यों महत्त्वपूर्ण है। डेसी और रायन के आत्म-निर्धारण सिद्धांत के अनुसार, वह मुख्यतः किस आवश्यकता का समर्थन कर रही है?","optionsHi":["स्वायत्तता","सुरक्षा","शारीरिक आराम","प्रतिस्पर्धा"],"explanationHi":"आत्म-निर्धारण सिद्धांत तीन मूल मनोवैज्ञानिक आवश्यकताएँ बताता है: स्वायत्तता, सक्षमता और संबद्धता। सार्थक विकल्प और औचित्य स्वायत्तता का समर्थन करते हैं।"},
  {"id":"cdp-child-development-809","question":"Under which condition are tangible rewards LEAST likely to harm intrinsic motivation?","options":["When they are promised in advance for an activity that children already love","When they help children start a task that holds little initial interest for them","When they are given only if a child beats all of her classmates in the task","When offered just for taking part in an enjoyable activity, regardless of quality"],"answer":1,"explanation":"The undermining effect is strongest for expected rewards on already interesting tasks. Where initial interest is low, rewards can help children begin and discover competence or interest.","difficulty":"very-hard","source":"CTET Paper 2 · NVS TGT","questionHi":"किस स्थिति में मूर्त पुरस्कारों द्वारा आंतरिक अभिप्रेरणा को हानि पहुँचाने की सबसे कम संभावना है?","optionsHi":["जब उन्हें ऐसी गतिविधि के लिए पहले से वादा किया जाए जो बच्चों को पहले से पसंद है","जब वे बच्चों को ऐसा कार्य शुरू करने में सहायता करें जिसमें उनकी आरंभिक रुचि कम हो","जब वे केवल तब दिए जाएँ जब बच्चा कार्य में अपने सभी सहपाठियों को हरा दे","जब वे केवल गुणवत्ता की परवाह किए बिना किसी आनंददायक गतिविधि में भाग लेने के लिए दिए जाएँ"],"explanationHi":"कमज़ोर करने वाला प्रभाव पहले से रुचिकर कार्यों पर अपेक्षित पुरस्कारों के लिए सबसे प्रबल है। जहाँ आरंभिक रुचि कम है, पुरस्कार बच्चों को शुरू करने और सक्षमता या रुचि खोजने में सहायता कर सकते हैं।"},
  {"id":"cdp-child-development-810","question":"Gurpreet is bullied every day on the way to school and during break. He cannot concentrate on lessons and often says he has a stomach ache to avoid school. In Maslow's hierarchy, which need is most clearly unmet?","options":["Self-actualisation","Esteem","Safety","Aesthetic"],"answer":2,"explanation":"Fear of harm signals an unmet safety need. Maslow argued that lower deficiency needs must be reasonably met before higher needs such as learning-related esteem can motivate behaviour.","difficulty":"hard","source":"CTET · HTET","questionHi":"गुरप्रीत को विद्यालय के रास्ते में और अवकाश के दौरान प्रतिदिन धौंस दी जाती है। वह पाठों पर ध्यान केंद्रित नहीं कर पाता और विद्यालय से बचने के लिए प्रायः पेट दर्द की बात कहता है। मैस्लो के पदानुक्रम में, कौन-सी आवश्यकता सबसे स्पष्ट रूप से पूरी नहीं हुई है?","optionsHi":["आत्म-सिद्धि","सम्मान","सुरक्षा","सौंदर्यबोध"],"explanationHi":"हानि का भय अपूर्ण सुरक्षा-आवश्यकता का संकेत है। मैस्लो का तर्क था कि निचली अभाव-आवश्यकताएँ यथोचित रूप से पूरी होनी चाहिए, उसके बाद ही अधिगम से जुड़ा सम्मान जैसी उच्चतर आवश्यकताएँ व्यवहार को प्रेरित कर सकती हैं।"},
  {"id":"cdp-child-development-811","question":"Assertion (A): A child who feels unloved at home may misbehave in class to gain attention from the teacher and classmates. Reason (R): In Maslow's view, unmet belongingness and love needs dominate behaviour until they are reasonably satisfied.","options":["A is true but R is false","A is false but R is true","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"Maslow held that unmet lower needs drive behaviour; a child starved of affection seeks it, even through disruption. R explains A.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): घर पर अप्रिय महसूस करने वाला बच्चा शिक्षक और सहपाठियों का ध्यान पाने के लिए कक्षा में दुर्व्यवहार कर सकता है। कारण (R): मैस्लो के मत में, अपूर्ण संबद्धता और प्रेम की आवश्यकताएँ तब तक व्यवहार पर हावी रहती हैं जब तक वे यथोचित रूप से संतुष्ट न हो जाएँ।","optionsHi":["A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है"],"explanationHi":"मैस्लो का मत था कि अपूर्ण निचली आवश्यकताएँ व्यवहार को चलाती हैं; स्नेह से वंचित बच्चा उसे खोजता है, विघ्न के द्वारा भी। R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-812","question":"Which statement about Maslow's hierarchy is accurate?","options":["Self-actualisation is a growth need; the four lower needs are deficiency needs","Esteem needs come before safety needs, since respect matters most to children","All lower needs must be fully satisfied before any higher need can appear","Maslow placed knowledge and understanding at the very bottom of the hierarchy"],"answer":0,"explanation":"Maslow divided needs into deficiency needs (the lower four) and growth needs (self-actualisation). Lower needs must be reasonably, not completely, met before higher ones become dominant.","difficulty":"moderate","source":"CTET · REET","questionHi":"मैस्लो के पदानुक्रम के बारे में कौन-सा कथन सही है?","optionsHi":["आत्म-सिद्धि एक विकास आवश्यकता है; चार निचली आवश्यकताएँ अभाव आवश्यकताएँ हैं","सम्मान की आवश्यकताएँ सुरक्षा की आवश्यकताओं से पहले आती हैं, क्योंकि बच्चों के लिए आदर सबसे अधिक मायने रखता है","किसी भी उच्चतर आवश्यकता के प्रकट होने से पहले सभी निचली आवश्यकताएँ पूर्णतः संतुष्ट होनी चाहिए","मैस्लो ने ज्ञान और समझ को पदानुक्रम में सबसे नीचे रखा"],"explanationHi":"मैस्लो ने आवश्यकताओं को अभाव आवश्यकताओं (निचली चार) और विकास आवश्यकताओं (आत्म-सिद्धि) में बाँटा। निचली आवश्यकताएँ यथोचित, पूर्णतः नहीं, पूरी होनी चाहिए, उसके बाद उच्चतर प्रभावी बनती हैं।"},
  {"id":"cdp-child-development-813","question":"Riya failed her science test. Which of her explanations is internal, unstable and controllable in Weiner's attribution theory?","options":["‘I am just not intelligent enough for science.’","‘I did not revise the chapter properly.’","‘The paper was set too hard.’","‘I was unlucky with the questions that came.’"],"answer":1,"explanation":"Lack of effort is internal (about her), unstable (can change next time) and controllable. Ability is internal but stable and uncontrollable; task difficulty and luck are external.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"रिया विज्ञान की परीक्षा में अनुत्तीर्ण हो गई। वाइनर के आरोपण सिद्धांत में उसकी कौन-सी व्याख्या आंतरिक, अस्थिर और नियंत्रणीय है?","optionsHi":["‘मैं विज्ञान के लिए बस पर्याप्त बुद्धिमान नहीं हूँ।’","‘मैंने अध्याय का ठीक से पुनरावर्तन नहीं किया।’","‘प्रश्नपत्र बहुत कठिन बनाया गया था।’","‘जो प्रश्न आए उनमें मैं दुर्भाग्यशाली रही।’"],"explanationHi":"प्रयास की कमी आंतरिक (उसके बारे में), अस्थिर (अगली बार बदल सकती है) और नियंत्रणीय है। योग्यता आंतरिक पर स्थिर और अनियंत्रणीय है; कार्य की कठिनाई और भाग्य बाह्य हैं।"},
  {"id":"cdp-child-development-814","question":"After topping a test, Kunal tells friends, ‘I just got lucky with the questions.’ Why might a teacher worry about this attribution even though he succeeded?","options":["Luck is internal and stable, so he will become overconfident about the next test","Luck is controllable, so he will feel free to stop working before the next test","Luck is external and unstable, giving little pride or reason to expect success again","Attributing success to luck always raises self-efficacy, so he may get careless"],"answer":2,"explanation":"Weiner noted that external, unstable attributions for success give little pride and no basis for expecting success again, so they do not build motivation.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"परीक्षा में प्रथम आने के बाद कुणाल मित्रों से कहता है, ‘मैं प्रश्नों के मामले में बस भाग्यशाली रहा।’ सफल होने के बावजूद शिक्षक को इस आरोपण की चिंता क्यों हो सकती है?","optionsHi":["भाग्य आंतरिक और स्थिर है, इसलिए वह अगली परीक्षा के प्रति अति-आत्मविश्वासी हो जाएगा","भाग्य नियंत्रणीय है, इसलिए वह अगली परीक्षा से पहले काम करना बंद करने को स्वतंत्र महसूस करेगा","भाग्य बाह्य और अस्थिर है, जो गर्व और पुनः सफलता की अपेक्षा का बहुत कम कारण देता है","सफलता को भाग्य पर आरोपित करना सदैव आत्म-प्रभावकारिता बढ़ाता है, इसलिए वह लापरवाह हो सकता है"],"explanationHi":"वाइनर ने ध्यान दिलाया कि सफलता के बाह्य, अस्थिर आरोपण बहुत कम गर्व देते हैं और पुनः सफलता की अपेक्षा का कोई आधार नहीं देते, इसलिए वे अभिप्रेरणा नहीं बनाते।"},
  {"id":"cdp-child-development-815","question":"After Mehul fails an easy quiz, his teacher speaks to him with obvious pity and immediately offers help he did not ask for, while she reacts to other failing students with mild annoyance. According to attribution research, what message might Mehul draw?","options":["That he failed only because of bad luck","That the teacher thinks he did not try hard enough","That the quiz was unfair","That the teacher believes he lacks ability"],"answer":3,"explanation":"Research by Sandra Graham showed that sympathy and unsolicited help after failure on an easy task can signal that the teacher attributes failure to low ability, while mild anger signals that more effort was expected.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"जब मेहुल एक आसान प्रश्नोत्तरी में अनुत्तीर्ण हो जाता है, तो उसकी शिक्षिका स्पष्ट सहानुभूति के साथ उससे बात करती है और तुरंत ऐसी सहायता देती है जो उसने माँगी नहीं थी, जबकि अन्य अनुत्तीर्ण विद्यार्थियों पर वह हल्की झुँझलाहट से प्रतिक्रिया करती है। आरोपण शोध के अनुसार मेहुल क्या संदेश ले सकता है?","optionsHi":["कि वह केवल बुरे भाग्य के कारण अनुत्तीर्ण हुआ","कि शिक्षिका सोचती है कि उसने पर्याप्त कठिन प्रयास नहीं किया","कि प्रश्नोत्तरी अनुचित थी","कि शिक्षिका मानती है कि उसमें योग्यता की कमी है"],"explanationHi":"सैंड्रा ग्राहम के शोध ने दिखाया कि आसान कार्य में विफलता के बाद सहानुभूति और बिन माँगी सहायता यह संकेत दे सकती है कि शिक्षक विफलता का कारण कम योग्यता मानता है, जबकि हल्का क्रोध संकेत देता है कि अधिक प्रयास अपेक्षित था।"},
  {"id":"cdp-child-development-816","question":"Bhavna has failed maths tests repeatedly despite studying; now she does not even attempt problems, saying, ‘Whatever I do, I'll fail.’ This is best described as:","options":["Learned helplessness","Overjustification","Spontaneous recovery","Mastery goal orientation"],"answer":0,"explanation":"Seligman's learned helplessness arises when a person comes to believe outcomes do not depend on his actions, leading to passivity even when success is possible.","difficulty":"moderate","source":"CTET · UPTET","questionHi":"पढ़ाई करने के बावजूद भावना बार-बार गणित की परीक्षाओं में अनुत्तीर्ण हुई है; अब वह प्रश्नों का प्रयास भी नहीं करती, कहती है, ‘मैं कुछ भी करूँ, अनुत्तीर्ण ही होऊँगी।’ इसका सबसे अच्छा वर्णन है:","optionsHi":["सीखी हुई असहायता","अति-औचित्य","स्वतःस्फूर्त पुनःप्राप्ति","निपुणता लक्ष्य-अभिमुखता"],"explanationHi":"सेलिगमैन की सीखी हुई असहायता तब उत्पन्न होती है जब व्यक्ति यह मानने लगता है कि परिणाम उसके कार्यों पर निर्भर नहीं करते, जिससे सफलता संभव होने पर भी निष्क्रियता आ जाती है।"},
  {"id":"cdp-child-development-817","question":"In a ring-toss game, children may stand at any distance from the peg. According to Atkinson's theory of achievement motivation, a child high in need for achievement and low in fear of failure is most likely to:","options":["Stand right next to the peg, to be sure of success on every throw","Stand at a moderate distance where success is possible but uncertain","Stand very far away, where success is nearly impossible but impressive","Refuse to play at all, to avoid any chance of looking foolish"],"answer":1,"explanation":"Success-oriented people prefer tasks of moderate difficulty, where success depends on skill and brings satisfaction. Those dominated by fear of failure tend to pick very easy or very hard tasks.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"एक रिंग-टॉस खेल में बच्चे खूँटी से किसी भी दूरी पर खड़े हो सकते हैं। एटकिन्सन के उपलब्धि अभिप्रेरणा सिद्धांत के अनुसार, उपलब्धि की उच्च आवश्यकता और असफलता के निम्न भय वाले बच्चे के क्या करने की सबसे अधिक संभावना है?","optionsHi":["खूँटी के ठीक बगल में खड़ा होना, ताकि प्रत्येक फेंक में सफलता पक्की हो","मध्यम दूरी पर खड़ा होना जहाँ सफलता संभव पर अनिश्चित हो","बहुत दूर खड़ा होना, जहाँ सफलता लगभग असंभव पर प्रभावशाली हो","बिल्कुल न खेलना, ताकि मूर्ख दिखने की कोई संभावना न रहे"],"explanationHi":"सफलता-उन्मुख लोग मध्यम कठिनाई के कार्य पसंद करते हैं, जहाँ सफलता कौशल पर निर्भर करती है और संतुष्टि देती है। असफलता के भय से हावी लोग बहुत आसान या बहुत कठिन कार्य चुनते हैं।"},
  {"id":"cdp-child-development-818","question":"A teacher wants to encourage a growth mindset in Class 7 students. Which praise suits this aim best?","options":["‘You are so clever, you didn't even have to try to get these right.’","‘You are a natural at maths, just like your elder brother.’","‘You kept trying new methods until one worked; that's how you solved it.’","‘You got the highest marks in the class, so you must be gifted.’"],"answer":2,"explanation":"Dweck found that praising process (effort, strategy) fosters the belief that ability grows, while praising fixed traits makes children avoid challenges to protect their image.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षक कक्षा 7 के विद्यार्थियों में वृद्धि-मानसिकता (ग्रोथ माइंडसेट) को प्रोत्साहित करना चाहता है। इस उद्देश्य के लिए कौन-सी प्रशंसा सबसे उपयुक्त है?","optionsHi":["‘तुम इतने चतुर हो कि इन्हें सही करने के लिए तुम्हें प्रयास करने की भी ज़रूरत नहीं पड़ी।’","‘तुम गणित में स्वाभाविक रूप से कुशल हो, अपने बड़े भाई की तरह।’","‘तुम नई विधियाँ आज़माते रहे जब तक कोई कारगर नहीं हो गई; इसी तरह तुमने इसे हल किया।’","‘तुमने कक्षा में सर्वाधिक अंक पाए, इसलिए तुम प्रतिभाशाली होगे।’"],"explanationHi":"ड्वेक ने पाया कि प्रक्रिया (प्रयास, युक्ति) की प्रशंसा इस विश्वास को बढ़ावा देती है कि योग्यता बढ़ती है, जबकि निश्चित गुणों की प्रशंसा बच्चों को अपनी छवि बचाने के लिए चुनौतियों से बचने को प्रेरित करती है।"},
  {"id":"cdp-child-development-819","question":"Two Class 9 students study a history chapter. Ankit keeps asking, ‘Will this come in the exam?’ and studies only those parts. Seema keeps asking why events happened and reads extra stories. Which statement best describes them?","options":["Both have mastery goals, since both are working hard on the chapter","Ankit is intrinsically motivated and Seema is extrinsically motivated","Seema has a performance-avoidance goal, since she avoids exam-only study","Ankit shows a performance goal and Seema a mastery goal"],"answer":3,"explanation":"Mastery (learning) goals aim at understanding and improvement; performance goals aim at grades or looking competent. Mastery goals are linked with deeper learning strategies.","difficulty":"hard","source":"CTET · HTET","questionHi":"कक्षा 9 के दो विद्यार्थी इतिहास का एक अध्याय पढ़ते हैं। अंकित बार-बार पूछता है, ‘क्या यह परीक्षा में आएगा?’ और केवल उन्हीं भागों को पढ़ता है। सीमा बार-बार पूछती है कि घटनाएँ क्यों हुईं और अतिरिक्त कथाएँ पढ़ती है। कौन-सा कथन उनका सबसे अच्छा वर्णन करता है?","optionsHi":["दोनों के निपुणता लक्ष्य हैं, क्योंकि दोनों अध्याय पर कठिन परिश्रम कर रहे हैं","अंकित आंतरिक रूप से अभिप्रेरित है और सीमा बाह्य रूप से अभिप्रेरित","सीमा का निष्पादन-परिहार लक्ष्य है, क्योंकि वह केवल परीक्षा के लिए पढ़ने से बचती है","अंकित निष्पादन लक्ष्य दर्शाता है और सीमा निपुणता लक्ष्य"],"explanationHi":"निपुणता (अधिगम) लक्ष्य समझ और सुधार का उद्देश्य रखते हैं; निष्पादन लक्ष्य ग्रेड या सक्षम दिखने का। निपुणता लक्ष्य गहरी अधिगम युक्तियों से जुड़े हैं।"},
  {"id":"cdp-child-development-820","question":"According to the Yerkes–Dodson law, which situation is most likely to give the best performance on a difficult, unfamiliar reasoning test?","options":["A moderate-to-low level of arousal, since the optimum is lower for complex tasks","Very high arousal, since pressure always pushes people to their best performance","No arousal at all, since any level of arousal disturbs careful thinking","High arousal, since difficult tasks need the most stress to stay focused"],"answer":0,"explanation":"Performance rises with arousal up to an optimum and then falls (inverted U). For complex tasks the optimum lies at a lower level of arousal than for simple tasks.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"येर्क्स–डॉडसन नियम के अनुसार, किसी कठिन, अपरिचित तर्क-परीक्षण पर सर्वश्रेष्ठ निष्पादन देने की सबसे अधिक संभावना किस स्थिति में है?","optionsHi":["मध्यम से निम्न स्तर की उत्तेजना, क्योंकि जटिल कार्यों के लिए इष्टतम स्तर कम होता है","बहुत उच्च उत्तेजना, क्योंकि दबाव लोगों को सदैव उनके सर्वश्रेष्ठ निष्पादन तक धकेलता है","कोई उत्तेजना नहीं, क्योंकि उत्तेजना का कोई भी स्तर सावधान चिंतन को बाधित करता है","उच्च उत्तेजना, क्योंकि कठिन कार्यों को ध्यान केंद्रित रखने के लिए सर्वाधिक तनाव चाहिए"],"explanationHi":"निष्पादन उत्तेजना के साथ एक इष्टतम बिंदु तक बढ़ता है और फिर गिरता है (उलटा U)। जटिल कार्यों के लिए इष्टतम बिंदु सरल कार्यों की तुलना में उत्तेजना के निम्न स्तर पर होता है।"},
  {"id":"cdp-child-development-821","question":"Ravi believes he can easily do well in drawing but sees no point in it, while Sohan values maths highly but is sure he will fail whatever he does. According to expectancy–value theory, which prediction is correct?","options":["Ravi will be highly motivated in drawing, because his expectancy of success is high","Both may show low motivation, since motivation needs both expectancy and value","Sohan will be highly motivated in maths, because he values the subject so highly","Expectancy and value do not affect motivation; interest in the teacher does"],"answer":1,"explanation":"In expectancy–value theory motivation is roughly expectancy multiplied by value; if either is near zero, motivation is low, so both students may disengage.","difficulty":"hard","source":"KVS TGT · DSSSB TGT","questionHi":"रवि मानता है कि वह चित्रकला में आसानी से अच्छा कर सकता है पर उसे उसमें कोई अर्थ नहीं दिखता, जबकि सोहन गणित को बहुत महत्त्व देता है पर निश्चित है कि वह कुछ भी करे अनुत्तीर्ण होगा। अपेक्षा–मूल्य सिद्धांत के अनुसार कौन-सा पूर्वानुमान सही है?","optionsHi":["रवि चित्रकला में अत्यधिक अभिप्रेरित होगा, क्योंकि सफलता की उसकी अपेक्षा उच्च है","दोनों में कम अभिप्रेरणा दिख सकती है, क्योंकि अभिप्रेरणा के लिए अपेक्षा और मूल्य दोनों चाहिए","सोहन गणित में अत्यधिक अभिप्रेरित होगा, क्योंकि वह विषय को इतना अधिक महत्त्व देता है","अपेक्षा और मूल्य अभिप्रेरणा को प्रभावित नहीं करते; शिक्षक में रुचि करती है"],"explanationHi":"अपेक्षा–मूल्य सिद्धांत में अभिप्रेरणा लगभग अपेक्षा गुणा मूल्य है; यदि दोनों में से कोई शून्य के निकट हो तो अभिप्रेरणा कम होती है, इसलिए दोनों विद्यार्थी विमुख हो सकते हैं।"},
  {"id":"cdp-child-development-822","question":"A Class 4 teacher runs a weekly spelling contest in which only the top three are rewarded. After a few weeks, the weaker spellers stop trying. What is the best change?","options":["Increase the prizes for the top three so that everyone tries harder to win","Remove spelling from the timetable, since contests only discourage children","Let each child set and try to beat a personal target, recognising improvement","Publicly display every child's rank so the weaker ones feel pushed to improve"],"answer":2,"explanation":"Competition with fixed winners discourages those who never win. Self-referenced goals let every child experience success through improvement and keep effort linked to outcomes.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 की एक शिक्षिका साप्ताहिक वर्तनी प्रतियोगिता चलाती है जिसमें केवल शीर्ष तीन को पुरस्कृत किया जाता है। कुछ सप्ताह बाद कमज़ोर वर्तनी वाले बच्चे प्रयास करना बंद कर देते हैं। सबसे अच्छा परिवर्तन क्या है?","optionsHi":["शीर्ष तीन के पुरस्कार बढ़ाना ताकि सभी जीतने के लिए अधिक कठिन प्रयास करें","समय-सारणी से वर्तनी हटा देना, क्योंकि प्रतियोगिताएँ केवल बच्चों को हतोत्साहित करती हैं","प्रत्येक बच्चे को व्यक्तिगत लक्ष्य तय करने और उसे पार करने का प्रयास करने देना, सुधार को मान्यता देते हुए","प्रत्येक बच्चे की श्रेणी सार्वजनिक रूप से प्रदर्शित करना ताकि कमज़ोर बच्चे सुधार के लिए विवश महसूस करें"],"explanationHi":"निश्चित विजेताओं वाली प्रतिस्पर्धा उन्हें हतोत्साहित करती है जो कभी नहीं जीतते। स्व-संदर्भित लक्ष्य प्रत्येक बच्चे को सुधार के माध्यम से सफलता का अनुभव करने देते हैं और प्रयास को परिणामों से जोड़े रखते हैं।"},
  {"id":"cdp-child-development-823","question":"Match each need in Maslow's hierarchy with a school practice that addresses it. P. Physiological  Q. Safety  R. Belongingness  S. Esteem. 1. A strict anti-bullying policy 2. The mid-day meal scheme 3. Displaying each child's work and recognising progress 4. Buddy groups so that new children feel part of the class","options":["P-1, Q-2, R-4, S-3","P-2, Q-1, R-3, S-4","P-2, Q-4, R-1, S-3","P-2, Q-1, R-4, S-3"],"answer":3,"explanation":"Food meets physiological needs, protection from bullying meets safety, buddy groups meet belonging, and recognition of work meets esteem needs.","difficulty":"moderate","source":"CTET · REET","questionHi":"मैस्लो के पदानुक्रम की प्रत्येक आवश्यकता का मिलान उसे संबोधित करने वाली विद्यालयी प्रथा से कीजिए। P. शारीरिक Q. सुरक्षा R. संबद्धता S. सम्मान। 1. धौंस-विरोधी कठोर नीति 2. मध्याह्न भोजन योजना 3. प्रत्येक बच्चे के कार्य को प्रदर्शित करना और प्रगति को मान्यता देना 4. बडी समूह ताकि नए बच्चे कक्षा का भाग महसूस करें","optionsHi":["P-1, Q-2, R-4, S-3","P-2, Q-1, R-3, S-4","P-2, Q-4, R-1, S-3","P-2, Q-1, R-4, S-3"],"explanationHi":"भोजन शारीरिक आवश्यकताओं की पूर्ति करता है, धौंस से संरक्षण सुरक्षा की, बडी समूह संबद्धता की, और कार्य की मान्यता सम्मान की आवश्यकताओं की।"},
  {"id":"cdp-child-development-824","question":"Moumita joined a Pune school in Class 6 after her family moved from Assam. The work suits her level and she has choices in projects, yet her interest drops because she has no friends and feels the teacher hardly knows her. Which basic need from self-determination theory is most clearly unmet?","options":["Relatedness","Competence","Autonomy","Physiological"],"answer":0,"explanation":"Self-determination theory lists autonomy, competence and relatedness. The tasks fit her ability (competence) and she has choice (autonomy); what is missing is a sense of belonging and connection.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"मौमिता असम से अपने परिवार के स्थानांतरण के बाद कक्षा 6 में पुणे के एक विद्यालय में आई। कार्य उसके स्तर के अनुकूल है और परियोजनाओं में उसके पास विकल्प हैं, फिर भी उसकी रुचि घट जाती है क्योंकि उसका कोई मित्र नहीं है और उसे लगता है कि शिक्षिका उसे मुश्किल से जानती है। आत्म-निर्धारण सिद्धांत की कौन-सी मूल आवश्यकता सबसे स्पष्ट रूप से अपूर्ण है?","optionsHi":["संबद्धता","सक्षमता","स्वायत्तता","शारीरिक"],"explanationHi":"आत्म-निर्धारण सिद्धांत स्वायत्तता, सक्षमता और संबद्धता को गिनाता है। कार्य उसकी योग्यता के अनुकूल हैं (सक्षमता) और उसके पास विकल्प है (स्वायत्तता); जो कमी है वह अपनेपन और जुड़ाव की भावना की है।"},
  {"id":"cdp-child-development-825","question":"Rahul, a Class 4 child with autism, has a support aide who sits beside him all day, answers for him and completes his tasks so that he ‘keeps up’. Over months, his classmates hardly speak to him. What is the main concern?","options":["Rahul should be moved with his aide to a resource room for focused one-to-one help","The aide’s constant help breeds dependence and isolation, so it should be faded","Classmates should be given a talk on autism so that they accept Rahul better","The aide should be trained in autism-specific methods so her help is more expert"],"answer":1,"explanation":"The barrier is the amount and placement of adult support, which does the work and blocks peer contact, so it must be faded. An autism-awareness talk is well meant but leaves the aide still standing between Rahul and his classmates, and a resource room would deepen his isolation.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 4 के ऑटिज़्म से ग्रस्त बच्चे राहुल के पास एक सहायक सहायिका है जो पूरे दिन उसके बगल में बैठती है, उसकी ओर से उत्तर देती है और उसके कार्य पूरे करती है ताकि वह ‘साथ चल सके’। महीनों में उसके सहपाठी उससे मुश्किल से बात करते हैं। मुख्य चिंता क्या है?","optionsHi":["राहुल को सहायिका के साथ केंद्रित एक-से-एक सहायता के लिए संसाधन-कक्ष में ले जाना चाहिए","सहायिका की निरंतर सहायता निर्भरता और अलगाव पैदा करती है, इसलिए उसे क्रमशः घटाना चाहिए","सहपाठियों को ऑटिज़्म पर एक वार्ता दी जानी चाहिए ताकि वे राहुल को बेहतर स्वीकार करें","सहायिका को ऑटिज़्म-विशिष्ट विधियों में प्रशिक्षित किया जाना चाहिए ताकि उसकी सहायता अधिक विशेषज्ञतापूर्ण हो"],"explanationHi":"बाधा वयस्क सहायता की मात्रा और स्थान है, जो कार्य स्वयं कर देती है और सहपाठियों से संपर्क रोकती है, इसलिए उसे घटाना चाहिए। ऑटिज़्म-जागरूकता की वार्ता सद्भावनापूर्ण है पर सहायिका फिर भी राहुल और उसके सहपाठियों के बीच खड़ी रहती है, और संसाधन-कक्ष उसके अलगाव को गहरा करेगा।"},
  {"id":"cdp-child-development-826","question":"Match the support with the learner it mainly helps. 1. Screen-reading software 2. FM (radio) listening system 3. Picture communication board 4. Pencil grip and slanted writing board; a. A child with hearing impairment b. A child who is blind c. A child with fine-motor writing difficulty d. A non-speaking child with autism or cerebral palsy","options":["1-b, 2-a, 3-d, 4-c","1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d","1-d, 2-a, 3-b, 4-c"],"answer":0,"explanation":"Screen readers convert text to speech for blind users, FM systems carry the teacher's voice directly to hearing aids, picture boards give a non-speaking child a way to communicate, and grips and slant boards ease handwriting.","difficulty":"hard","source":"CTET · State TETs","questionHi":"सहायता का मिलान उस अधिगमकर्ता से कीजिए जिसकी वह मुख्यतः सहायता करती है। 1. स्क्रीन-रीडिंग सॉफ़्टवेयर 2. FM (रेडियो) श्रवण प्रणाली 3. चित्र संप्रेषण बोर्ड 4. पेंसिल ग्रिप और ढलवाँ लेखन-पटल; a. श्रवण-बाधित बच्चा b. दृष्टिबाधित बच्चा c. सूक्ष्म-गामक लेखन कठिनाई वाला बच्चा d. ऑटिज़्म या प्रमस्तिष्कीय पक्षाघात वाला अवाक् बच्चा","optionsHi":["1-b, 2-a, 3-d, 4-c","1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d","1-d, 2-a, 3-b, 4-c"],"explanationHi":"स्क्रीन रीडर पाठ को दृष्टिबाधित उपयोगकर्ताओं के लिए वाणी में बदलते हैं, FM प्रणालियाँ शिक्षक की आवाज़ सीधे श्रवण यंत्रों तक पहुँचाती हैं, चित्र बोर्ड अवाक् बच्चे को संप्रेषण का तरीका देते हैं, और ग्रिप तथा ढलवाँ पटल लिखावट को आसान बनाते हैं।"},
  {"id":"cdp-child-development-827","question":"Which of these statements reflect an inclusive view of disability? I. Attitudes of teachers and peers can be a bigger barrier than physical ones. II. A child should be placed in a regular class only after she becomes ‘ready’ to cope with it unaided. III. Barriers to learning lie in the school environment as much as in the child.","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":2,"explanation":"Inclusion sees barriers in attitudes, practices and the environment, which the school must remove; making entry conditional on the child becoming ‘ready’ is the old integration model.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"इनमें से कौन-से कथन अक्षमता के समावेशी दृष्टिकोण को दर्शाते हैं? I. शिक्षकों और सहपाठियों के दृष्टिकोण भौतिक बाधाओं से बड़ी बाधा हो सकते हैं। II. बच्ची को नियमित कक्षा में तभी रखा जाना चाहिए जब वह बिना सहायता के उसका सामना करने के लिए ‘तैयार’ हो जाए। III. अधिगम की बाधाएँ उतनी ही विद्यालय के परिवेश में हैं जितनी बच्ची में।","optionsHi":["केवल I और II","केवल II और III","केवल I और III","I, II और III"],"explanationHi":"समावेशन बाधाओं को दृष्टिकोणों, प्रथाओं और परिवेश में देखता है, जिन्हें विद्यालय को दूर करना चाहिए; प्रवेश को बच्चे के ‘तैयार’ होने पर सशर्त बनाना पुराना एकीकरण मॉडल है।"},
  {"id":"cdp-child-development-828","question":"A Class 7 wheelchair user cannot reach the school library on the first floor. A committee member says, ‘The problem is her legs; nothing can be done.’ Which statement correctly analyses this?","options":["This is the social model; it rightly locates the problem in the child’s body","This is the medical model; the social model would remove the barrier, e.g. with a ramp","This is the social model; it suggests the child should be taught at home instead","This is the medical model, which is the approach the RPwD Act itself requires"],"answer":1,"explanation":"The medical model sees disability as a defect in the person, while the social model sees disability arising from barriers in the environment; the rights-based law follows the social view.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 7 की एक व्हीलचेयर-उपयोगकर्ता पहली मंज़िल पर स्थित विद्यालय के पुस्तकालय तक नहीं पहुँच सकती। एक समिति-सदस्य कहता है, ‘समस्या उसके पैरों की है; कुछ नहीं किया जा सकता।’ कौन-सा कथन इसका सही विश्लेषण करता है?","optionsHi":["यह सामाजिक मॉडल है; वह समस्या को बच्ची के शरीर में सही स्थित करता है","यह चिकित्सीय मॉडल है; सामाजिक मॉडल बाधा को हटाएगा, जैसे ढलान बनाकर","यह सामाजिक मॉडल है; वह सुझाता है कि बच्ची को इसके बजाय घर पर पढ़ाया जाए","यह चिकित्सीय मॉडल है, जो वही उपागम है जिसकी RPwD अधिनियम स्वयं माँग करता है"],"explanationHi":"चिकित्सीय मॉडल अक्षमता को व्यक्ति में एक दोष के रूप में देखता है, जबकि सामाजिक मॉडल मानता है कि अक्षमता परिवेश की बाधाओं से उत्पन्न होती है; अधिकार-आधारित कानून सामाजिक दृष्टि का अनुसरण करता है।"},
  {"id":"cdp-child-development-829","question":"Which statement about dyslexia is correct?","options":["It is caused mainly by low intelligence, so it shows up across all subjects","It means the child literally sees letters backwards, so b/d reversal confirms it","It is usually a result of laziness and too little reading practice at home","A phonological difficulty that hampers decoding and spelling despite normal intelligence"],"answer":3,"explanation":"Dyslexia is chiefly a phonological processing difficulty unrelated to intelligence; letter reversals are common in all beginning writers and do not by themselves indicate dyslexia.","difficulty":"hard","source":"CTET · State TETs","questionHi":"डिस्लेक्सिया के बारे में कौन-सा कथन सही है?","optionsHi":["यह मुख्यतः निम्न बुद्धि से होता है, इसलिए यह सभी विषयों में दिखता है","इसका अर्थ है कि बच्चा अक्षरों को सचमुच उलटा देखता है, इसलिए b/d का उलटाव इसकी पुष्टि करता है","यह प्रायः आलस्य और घर पर पढ़ने के कम अभ्यास का परिणाम है","एक ध्वनिगत कठिनाई जो सामान्य बुद्धि के बावजूद डिकोडिंग और वर्तनी में बाधा डालती है"],"explanationHi":"डिस्लेक्सिया मुख्यतः बुद्धि से असंबद्ध ध्वनिगत प्रसंस्करण की कठिनाई है; अक्षरों का उलटाव सभी आरंभिक लेखकों में सामान्य है और अपने आप में डिस्लेक्सिया का संकेत नहीं है।"},
  {"id":"cdp-child-development-830","question":"Simran, in Class 3, has been found to have dyscalculia. Which approach is most suitable for teaching her place value?","options":["Moving from concrete bundles of sticks, to pictures, and only then to symbols","Making her recite multiplication tables loudly every morning until they stick","Giving her daily timed drills of written sums to build speed and confidence","Excusing her from mathematics so that she can focus on languages instead"],"answer":0,"explanation":"The concrete–representational–abstract sequence builds number meaning step by step, which is what children with dyscalculia lack; rote recitation and speed drills skip understanding and raise anxiety.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 3 की सिमरन में डिस्कैल्कुलिया पाया गया है। उसे स्थानीय मान सिखाने के लिए कौन-सा उपागम सबसे उपयुक्त है?","optionsHi":["तीलियों के मूर्त बंडलों से चित्रों की ओर, और उसके बाद ही प्रतीकों की ओर बढ़ना","उसे प्रतिदिन सुबह ज़ोर से पहाड़े दोहराने के लिए बाध्य करना जब तक वे बैठ न जाएँ","गति और आत्मविश्वास बनाने के लिए लिखित जोड़ों के दैनिक समयबद्ध अभ्यास देना","उसे गणित से छूट देना ताकि वह इसके बजाय भाषाओं पर ध्यान दे सके"],"explanationHi":"मूर्त–निरूपणात्मक–अमूर्त क्रम संख्या का अर्थ चरण-दर-चरण बनाता है, जिसकी डिस्कैल्कुलिया वाले बच्चों में कमी होती है; रटंत पाठ और गति-अभ्यास समझ को छोड़ देते हैं और चिंता बढ़ाते हैं।"},
  {"id":"cdp-child-development-831","question":"Which practice is LEAST helpful for a blind student who has just joined a Class 5 classroom?","options":["Taking him round the room so that he learns where the door, his desk and the shelves are","Announcing who is entering or leaving and speaking his name when addressing him","Rearranging desks and cupboards often for different activities without telling him","Keeping walkways clear and doors fully open or fully shut"],"answer":2,"explanation":"A blind child builds a mental map of the room for independent movement; unannounced rearrangement destroys that map and creates hazards, while orientation and clear walkways support it.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 5 के कक्ष में अभी आए दृष्टिबाधित विद्यार्थी के लिए कौन-सी प्रथा सबसे कम सहायक है?","optionsHi":["उसे कमरे में घुमाना ताकि वह जान सके कि दरवाज़ा, उसकी डेस्क और अलमारियाँ कहाँ हैं","यह घोषित करना कि कौन आ या जा रहा है और उसे संबोधित करते समय उसका नाम लेना","अलग-अलग गतिविधियों के लिए उसे बताए बिना डेस्क और अलमारियों को बार-बार बदलना","रास्तों को साफ़ रखना और दरवाज़ों को पूरा खुला या पूरा बंद रखना"],"explanationHi":"दृष्टिबाधित बच्चा स्वतंत्र गति के लिए कमरे का मानसिक मानचित्र बनाता है; बिना घोषणा के पुनर्व्यवस्था उस मानचित्र को नष्ट करती है और खतरे पैदा करती है, जबकि अभिविन्यास और साफ़ रास्ते उसका समर्थन करते हैं।"},
  {"id":"cdp-child-development-832","question":"A teacher of a deaf Class 2 child uses speech, Indian Sign Language, gestures, lip-reading, pictures and written words together, choosing whatever works best in each situation. This approach is known as:","options":["The oral-only approach","Total communication","The auditory-verbal-only approach","Finger-spelling only"],"answer":1,"explanation":"Total communication combines all available modes, signed, spoken, written and visual, to give the child full access; oral-only and auditory-verbal approaches rely on speech and hearing alone.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 2 के बधिर बच्चे की शिक्षिका वाणी, भारतीय सांकेतिक भाषा, भाव-भंगिमाएँ, होंठ-पठन, चित्र और लिखित शब्द एक साथ प्रयोग करती है, प्रत्येक स्थिति में जो सबसे अच्छा काम करे उसे चुनती हुई। यह उपागम किस नाम से जाना जाता है?","optionsHi":["केवल मौखिक उपागम","पूर्ण संप्रेषण (टोटल कम्युनिकेशन)","केवल श्रवण-शाब्दिक उपागम","केवल अँगुली-वर्तनी"],"explanationHi":"पूर्ण संप्रेषण सभी उपलब्ध माध्यमों, सांकेतिक, बोले गए, लिखित और दृश्य, को मिलाकर बच्चे को पूर्ण पहुँच देता है; केवल-मौखिक और श्रवण-शाब्दिक उपागम केवल वाणी और श्रवण पर निर्भर करते हैं।"},
  {"id":"cdp-child-development-833","question":"Asked to list uses of a brick, a Class 6 student writes 20 answers, but every one is a building use: a wall, a step, a pillar, a shelf base and so on. In terms of divergent thinking, her response shows:","options":["High originality and high flexibility","Low fluency and high flexibility","High elaboration and high originality","High fluency but low flexibility"],"answer":3,"explanation":"Fluency is the number of ideas, which is high; flexibility is the number of different categories, which is low because all answers fall in one category of use.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"ईंट के उपयोग सूचीबद्ध करने को कहे जाने पर कक्षा 6 की एक विद्यार्थी 20 उत्तर लिखती है, पर प्रत्येक निर्माण-संबंधी उपयोग है: दीवार, सीढ़ी, खंभा, अलमारी का आधार आदि। अपसारी चिंतन के संदर्भ में उसका उत्तर क्या दर्शाता है?","optionsHi":["उच्च मौलिकता और उच्च लचीलापन","निम्न प्रवाह और उच्च लचीलापन","उच्च विस्तारण और उच्च मौलिकता","उच्च प्रवाह पर निम्न लचीलापन"],"explanationHi":"प्रवाह विचारों की संख्या है, जो उच्च है; लचीलापन विभिन्न श्रेणियों की संख्या है, जो निम्न है क्योंकि सभी उत्तर उपयोग की एक ही श्रेणी में आते हैं।"},
  {"id":"cdp-child-development-834","question":"Mehak, a gifted Class 4 student, tears up her drawing or work sheet whenever she finds even a tiny error and refuses to start tasks she may not do perfectly. What is the most appropriate teacher response?","options":["Praising her as ‘the cleverest’ in class so that her confidence rises","Giving her only easy tasks so that she never has to face a mistake","Normalising mistakes and praising effort and strategy rather than flawless results","Asking her parents to be stricter so that she stops tearing up her work"],"answer":2,"explanation":"Perfectionism is common among gifted children; normalising mistakes and valuing process helps, whereas ‘cleverest’ praise and easy work reinforce the fear of failing.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 की प्रतिभाशाली विद्यार्थी मेहक, जब भी उसे एक छोटी-सी त्रुटि मिलती है, अपना चित्र या कार्य-पत्रक फाड़ देती है और उन कार्यों को शुरू करने से मना कर देती है जो वह पूर्णता से नहीं कर पाएगी। शिक्षक की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["उसे कक्षा की ‘सबसे चतुर’ कहकर सराहना, ताकि उसका आत्मविश्वास बढ़े","उसे केवल आसान कार्य देना ताकि उसे कभी गलती का सामना न करना पड़े","गलतियों को सामान्य बनाना और त्रुटिहीन परिणामों के बजाय प्रयास और युक्ति की प्रशंसा करना","उसके माता-पिता से अधिक कठोर होने को कहना ताकि वह अपना कार्य फाड़ना बंद कर दे"],"explanationHi":"प्रतिभाशाली बच्चों में पूर्णतावाद आम है; गलतियों को सामान्य बनाना और प्रक्रिया को महत्त्व देना सहायक है, जबकि ‘सबसे चतुर’ की प्रशंसा और आसान कार्य असफलता के भय को सुदृढ़ करते हैं।"},
  {"id":"cdp-child-development-835","question":"Gifted children from rural and poor families are often missed when schools identify giftedness. Which practice best reduces this?","options":["Using a single written test in English, the same for every child in the district","Identifying only those children whose parents put in a formal request","Selecting the children with the highest marks in the annual examination","Using varied sources such as observation, portfolios and non-verbal tasks"],"answer":3,"explanation":"Tests that depend on language, exposure or parental awareness favour advantaged children; multiple measures, including non-verbal tasks and observation, find ability wherever it lies.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"जब विद्यालय प्रतिभाशालिता की पहचान करते हैं तो ग्रामीण और गरीब परिवारों के प्रतिभाशाली बच्चे प्रायः छूट जाते हैं। कौन-सी प्रथा इसे सबसे अच्छी तरह घटाती है?","optionsHi":["अंग्रेज़ी में एकमात्र लिखित परीक्षा का प्रयोग, जो ज़िले के प्रत्येक बच्चे के लिए समान हो","केवल उन्हीं बच्चों की पहचान करना जिनके माता-पिता औपचारिक अनुरोध करें","वार्षिक परीक्षा में सर्वाधिक अंक पाने वाले बच्चों का चयन करना","अवलोकन, पोर्टफ़ोलियो और अशाब्दिक कार्यों जैसे विविध स्रोतों का उपयोग करना"],"explanationHi":"जो परीक्षण भाषा, अनुभव या अभिभावकों की जागरूकता पर निर्भर हैं वे सुविधा-संपन्न बच्चों का पक्ष लेते हैं; अशाब्दिक कार्यों और अवलोकन सहित अनेक माप क्षमता को जहाँ भी हो खोज लेते हैं।"},
  {"id":"cdp-child-development-836","question":"Varsha, a Class 3 child with ADHD, keeps blurting out answers before others can think. Which strategy best helps her while keeping the whole class involved?","options":["Having every child write an answer on a slate and show it together on a signal","Never asking her any questions, so that she learns to wait quietly","Sending her out of the room each time she calls out, to teach self-control","Letting her answer every question, since her eagerness should be rewarded"],"answer":0,"explanation":"Whole-class response methods give her an immediate way to respond while making everyone think and answer; ignoring, excluding or letting her dominate do not build self-control.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 3 की ADHD से ग्रस्त बच्ची वर्षा, दूसरों के सोचने से पहले ही उत्तर बोल देती है। कौन-सी युक्ति पूरी कक्षा को शामिल रखते हुए उसकी सबसे अधिक सहायता करती है?","optionsHi":["प्रत्येक बच्चे से स्लेट पर उत्तर लिखवाना और संकेत पर सब साथ दिखाना","उससे कभी कोई प्रश्न न पूछना, ताकि वह चुपचाप प्रतीक्षा करना सीखे","जब भी वह बोल पड़े तो उसे कमरे से बाहर भेजना, आत्म-नियंत्रण सिखाने के लिए","उसे हर प्रश्न का उत्तर देने देना, क्योंकि उसकी उत्सुकता को पुरस्कृत किया जाना चाहिए"],"explanationHi":"पूरी कक्षा की अनुक्रिया विधियाँ उसे प्रतिक्रिया देने का तत्काल तरीका देती हैं और सभी को सोचने तथा उत्तर देने को प्रेरित करती हैं; अनदेखा करना, बाहर करना या उसे हावी होने देना आत्म-नियंत्रण नहीं बनाते।"},
  {"id":"cdp-child-development-837","question":"Imran, a Class 5 boy on the autism spectrum, wants friends but talks only about trains and does not notice when others lose interest. Which approach is most appropriate?","options":["Banning him from talking about trains in school so that he learns other topics","Teaching turn-taking through role-play and using his train interest as a bridge","Leaving him to work out social rules by himself, as other children do","Seating him alone so that the other children are not bored by his talk"],"answer":1,"explanation":"Social rules that others pick up naturally often need to be taught directly to autistic children; using a strong interest as a bridge motivates him to interact.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 5 का ऑटिज़्म स्पेक्ट्रम पर स्थित लड़का इमरान मित्र चाहता है पर केवल रेलगाड़ियों के बारे में बात करता है और यह नहीं देखता कि दूसरे कब रुचि खो देते हैं। कौन-सा उपागम सबसे उपयुक्त है?","optionsHi":["उसे विद्यालय में रेलगाड़ियों की बात करने से रोकना ताकि वह अन्य विषय सीखे","भूमिका-निर्वाह द्वारा बारी-बारी से बोलना सिखाना और उसकी रेलगाड़ी-रुचि को सेतु के रूप में प्रयोग करना","उसे सामाजिक नियम स्वयं समझने के लिए छोड़ देना, जैसा अन्य बच्चे करते हैं","उसे अकेले बैठाना ताकि अन्य बच्चे उसकी बातों से ऊबें नहीं"],"explanationHi":"जो सामाजिक नियम दूसरे स्वाभाविक रूप से सीख लेते हैं, उन्हें ऑटिस्टिक बच्चों को प्रायः सीधे सिखाना पड़ता है; प्रबल रुचि को सेतु के रूप में प्रयोग करना उसे अंतःक्रिया के लिए प्रेरित करता है।"},
  {"id":"cdp-child-development-838","question":"A 13-year-old with moderate intellectual disability in an inclusive Class 6 is given nursery rhymes and baby toys because his reading level is around Class 1. Which principle does this violate?","options":["Task analysis, which breaks skills into small steps","Positive reinforcement, which rewards each success","Age-appropriateness of materials, even when content is simplified","Concrete-to-abstract sequencing, which starts with objects"],"answer":2,"explanation":"Content can be simplified without being childish; using age-appropriate topics and materials respects the learner and supports acceptance among his peers.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक समावेशी कक्षा 6 में मध्यम बौद्धिक अक्षमता वाले 13 वर्ष के लड़के को बाल-कविताएँ और बच्चों के खिलौने दिए जाते हैं क्योंकि उसका पठन-स्तर लगभग कक्षा 1 का है। यह किस सिद्धांत का उल्लंघन करता है?","optionsHi":["कार्य-विश्लेषण, जो कौशलों को छोटे चरणों में तोड़ता है","सकारात्मक पुनर्बलन, जो प्रत्येक सफलता को पुरस्कृत करता है","सामग्री की आयु-उपयुक्तता, तब भी जब विषय-वस्तु सरल की गई हो","मूर्त से अमूर्त की ओर क्रम, जो वस्तुओं से शुरू होता है"],"explanationHi":"विषय-वस्तु को बचकाना बनाए बिना सरल किया जा सकता है; आयु-उपयुक्त विषयों और सामग्री का प्रयोग अधिगमकर्ता का सम्मान करता है और उसके सहपाठियों में स्वीकृति का समर्थन करता है।"},
  {"id":"cdp-child-development-839","question":"Which of the following is an example of differentiating the LEARNING ENVIRONMENT?","options":["Setting up a quiet corner for some students and a discussion area for others","Giving advanced students harder problems on the same topic during the lesson","Letting students present their project either as a poster or as a speech","Teaching the same idea through both a story and a labelled diagram"],"answer":0,"explanation":"Changing where and in what conditions students work, such as seating, noise and space, is differentiation of the environment; the other options vary process, product or representation.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"निम्नलिखित में से कौन-सा अधिगम परिवेश के विभेदन का उदाहरण है?","optionsHi":["कुछ विद्यार्थियों के लिए एक शांत कोना और दूसरों के लिए चर्चा-क्षेत्र बनाना","पाठ के दौरान उन्नत विद्यार्थियों को उसी विषय पर कठिन प्रश्न देना","विद्यार्थियों को अपनी परियोजना पोस्टर या भाषण के रूप में प्रस्तुत करने देना","एक ही विचार को कहानी और नामांकित आरेख दोनों से पढ़ाना"],"explanationHi":"विद्यार्थी कहाँ और किन परिस्थितियों में काम करते हैं, जैसे बैठक, शोर और स्थान, उसे बदलना परिवेश का विभेदन है; अन्य विकल्प प्रक्रिया, उत्पाद या निरूपण को बदलते हैं।"},
  {"id":"cdp-child-development-840","question":"At the end of each lesson, a Class 6 teacher collects a one-question ‘exit slip’ from every student and uses it to decide next day’s groups. Why is this important for differentiated instruction?","options":["It provides regular marks that can be added to the term report card","It helps her rank students accurately for the school merit list","It replaces the need to teach the whole class together the next day","It tracks readiness, so groups and tasks can change as understanding changes"],"answer":3,"explanation":"Differentiation is driven by continuous formative assessment; quick checks such as exit slips let the teacher regroup flexibly instead of fixing students in permanent levels.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"प्रत्येक पाठ के अंत में कक्षा 6 की शिक्षिका प्रत्येक विद्यार्थी से एक-प्रश्न वाली ‘निर्गम-पर्ची’ एकत्र करती है और उसका उपयोग अगले दिन के समूह तय करने के लिए करती है। यह विभेदित अनुदेशन के लिए महत्त्वपूर्ण क्यों है?","optionsHi":["यह नियमित अंक देता है जिन्हें सत्र के रिपोर्ट कार्ड में जोड़ा जा सकता है","यह उसे विद्यालय की मेधा-सूची के लिए विद्यार्थियों को सटीक क्रम देने में सहायता करता है","यह अगले दिन पूरी कक्षा को एक साथ पढ़ाने की आवश्यकता को समाप्त कर देता है","यह तत्परता पर नज़र रखता है, ताकि समझ बदलने के साथ समूह और कार्य बदले जा सकें"],"explanationHi":"विभेदन सतत रचनात्मक आकलन से संचालित होता है; निर्गम-पर्चियों जैसी त्वरित जाँचें शिक्षक को विद्यार्थियों को स्थायी स्तरों में बाँधने के बजाय लचीले ढंग से पुनः समूहबद्ध करने देती हैं।"},
  {"id":"cdp-child-development-841","question":"Manoj, in Class 6, helps at his family’s tea stall before school and often arrives late and tired. What is the most appropriate response from his teacher?","options":["Marking him absent whenever he is late, to enforce discipline for all","Telling him that school will not help him if he keeps working at the stall","Helping him catch up and working with his parents and the SMC on attendance","Asking him to sit at the back so that his late entry does not disturb others"],"answer":2,"explanation":"Punishing a child for poverty-related constraints pushes him out of school; understanding, academic support and working with the family and community keep him enrolled and learning.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 6 का मनोज विद्यालय से पहले अपने परिवार की चाय की दुकान पर सहायता करता है और प्रायः देर से और थका हुआ आता है। उसके शिक्षक की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["जब भी वह देर से आए उसे अनुपस्थित अंकित करना, सबके लिए अनुशासन लागू करने के लिए","उसे बताना कि यदि वह दुकान पर काम करता रहा तो विद्यालय उसकी सहायता नहीं करेगा","उसे पढ़ाई में बराबरी पर लाने में सहायता करना और उपस्थिति पर उसके माता-पिता तथा SMC के साथ काम करना","उसे पीछे बैठने को कहना ताकि उसका देर से आना दूसरों को बाधित न करे"],"explanationHi":"गरीबी से जुड़ी बाध्यताओं के लिए बच्चे को दंडित करना उसे विद्यालय से बाहर धकेलता है; समझ, शैक्षणिक सहायता और परिवार तथा समुदाय के साथ काम करना उसे नामांकित और सीखता रखता है।"},
  {"id":"cdp-child-development-842","question":"Several Class 8 girls in a rural school are absent for a few days every month during menstruation. Which step by the school best addresses this?","options":["Marking these absences as excused, so the girls are not penalised","Ensuring private toilets with water and disposal, and openly normalising menstruation","Asking the girls to stay home during those days so that they are comfortable","Discussing the issue only privately with the girls’ mothers, to avoid embarrassment"],"answer":1,"explanation":"Absence often stems from lack of facilities and from stigma; proper sanitation and open information remove both barriers, whereas staying home or excusing absence accepts lost learning.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"एक ग्रामीण विद्यालय में कक्षा 8 की कई लड़कियाँ मासिक धर्म के दौरान हर महीने कुछ दिन अनुपस्थित रहती हैं। विद्यालय का कौन-सा कदम इसे सबसे अच्छी तरह संबोधित करता है?","optionsHi":["इन अनुपस्थितियों को क्षम्य अंकित करना, ताकि लड़कियों को दंड न मिले","जल और निपटान सहित निजी शौचालय सुनिश्चित करना, और मासिक धर्म को खुले तौर पर सामान्य बनाना","लड़कियों से उन दिनों घर पर रहने को कहना ताकि वे सहज रहें","इस मुद्दे पर केवल लड़कियों की माताओं से निजी तौर पर चर्चा करना, शर्मिंदगी से बचने के लिए"],"explanationHi":"अनुपस्थिति प्रायः सुविधाओं के अभाव और कलंक से उत्पन्न होती है; उचित स्वच्छता और खुली जानकारी दोनों बाधाओं को दूर करती है, जबकि घर पर रहना या अनुपस्थिति को क्षम्य मानना खोए हुए अधिगम को स्वीकार करता है।"},
  {"id":"cdp-child-development-843","question":"A child of seasonal migrant workers arrives mid-year at a government school in Maharashtra with no transfer certificate and no birth certificate. What does the RTE Act, 2009 require?","options":["Admission only after the previous school sends the transfer certificate","Admission only at the beginning of the next session, to avoid disruption","Admission into Class 1, since her previous learning cannot be verified","Immediate admission, since missing age proof or TC cannot deny or delay it"],"answer":3,"explanation":"RTE bars denial of admission for want of age proof and states that delay in producing a transfer certificate cannot delay or deny admission; she should join an age-appropriate class.","difficulty":"very-hard","source":"CTET · UPTET · State TETs","questionHi":"मौसमी प्रवासी श्रमिकों की एक बच्ची सत्र के बीच में महाराष्ट्र के एक सरकारी विद्यालय में बिना स्थानांतरण प्रमाण-पत्र और जन्म प्रमाण-पत्र के आती है। RTE अधिनियम, 2009 क्या अपेक्षा करता है?","optionsHi":["पिछले विद्यालय द्वारा स्थानांतरण प्रमाण-पत्र भेजे जाने के बाद ही प्रवेश","केवल अगले सत्र के आरंभ में प्रवेश, व्यवधान से बचने के लिए","कक्षा 1 में प्रवेश, क्योंकि उसके पूर्व अधिगम को सत्यापित नहीं किया जा सकता","तुरंत प्रवेश, क्योंकि आयु-प्रमाण या TC की अनुपस्थिति उसे अस्वीकार या विलंबित नहीं कर सकती"],"explanationHi":"RTE आयु-प्रमाण के अभाव में प्रवेश से इनकार पर रोक लगाता है और कहता है कि स्थानांतरण प्रमाण-पत्र प्रस्तुत करने में देरी प्रवेश को विलंबित या अस्वीकार नहीं कर सकती; उसे आयु के अनुरूप कक्षा में शामिल होना चाहिए।"},
  {"id":"cdp-child-development-844","question":"While reviewing a Class 3 book, a teacher finds these illustrations. Which one most reinforces a stereotype?","options":["A boy and a girl playing football together in the school ground","An elderly man cooking dinner for his grandchildren at home","Every doctor pictured is a man and every nurse pictured is a woman","A woman in a wheelchair working as a teacher in a classroom"],"answer":2,"explanation":"Repeated one-sided images teach children that some roles belong to one gender; the other illustrations deliberately counter common stereotypes.","difficulty":"moderate","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 3 की एक पुस्तक की समीक्षा करते हुए एक शिक्षक को ये चित्र मिलते हैं। इनमें से कौन-सा रूढ़िबद्ध धारणा को सबसे अधिक सुदृढ़ करता है?","optionsHi":["एक लड़का और एक लड़की विद्यालय के मैदान में साथ फ़ुटबॉल खेल रहे हैं","एक बुज़ुर्ग पुरुष घर पर अपने पोते-पोतियों के लिए रात का खाना पका रहे हैं","चित्रित प्रत्येक डॉक्टर पुरुष है और चित्रित प्रत्येक नर्स महिला है","एक व्हीलचेयर पर बैठी महिला कक्षा में शिक्षिका के रूप में काम कर रही है"],"explanationHi":"बार-बार एकतरफ़ा चित्र बच्चों को सिखाते हैं कि कुछ भूमिकाएँ एक लिंग की हैं; अन्य चित्र जान-बूझकर प्रचलित रूढ़िबद्ध धारणाओं का प्रतिकार करते हैं।"},
  {"id":"cdp-child-development-845","question":"Assertion (A): A school can teach discrimination even when nothing in its syllabus is discriminatory. Reason (R): Children learn values from daily routines, such as where they sit, who gets praised and which children are given leadership roles.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"This is the hidden curriculum: unwritten messages in school practices shape children's beliefs about who matters, which explains how discrimination can be taught without any written content.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): कोई विद्यालय भेदभाव सिखा सकता है, भले ही उसके पाठ्यक्रम में कुछ भी भेदभावपूर्ण न हो। कारण (R): बच्चे दैनिक दिनचर्याओं से मूल्य सीखते हैं, जैसे वे कहाँ बैठते हैं, किसकी प्रशंसा होती है और किन बच्चों को नेतृत्व की भूमिकाएँ दी जाती हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"यह छिपा हुआ पाठ्यक्रम है: विद्यालयी प्रथाओं में अलिखित संदेश बच्चों की इस बारे में मान्यताएँ आकार देते हैं कि कौन मायने रखता है, जो समझाता है कि बिना किसी लिखित सामग्री के भेदभाव कैसे सिखाया जा सकता है।"},
  {"id":"cdp-child-development-846","question":"Which assessment practice is most inclusive for a Class 4 class with children of varied abilities, languages and disabilities?","options":["One written test at the end of the term, the same for all children","Ranking children by marks so that each knows where they stand in class","Testing only reading and writing skills, since these are basic to all learning","Ongoing observation, portfolios, oral answers and projects in varied modes"],"answer":3,"explanation":"Varied, continuous assessment lets every child show what they have learnt and guides teaching; a single written test measures the barrier of the mode as much as the learning.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"विभिन्न क्षमताओं, भाषाओं और अक्षमताओं वाले बच्चों की कक्षा 4 के लिए कौन-सी आकलन प्रथा सबसे अधिक समावेशी है?","optionsHi":["सत्र के अंत में एक लिखित परीक्षा, सभी बच्चों के लिए समान","बच्चों को अंकों के आधार पर क्रम देना ताकि प्रत्येक जाने कि वह कक्षा में कहाँ है","केवल पठन और लेखन कौशल की परीक्षा, क्योंकि ये सभी अधिगम के लिए मूल हैं","निरंतर अवलोकन, पोर्टफ़ोलियो, मौखिक उत्तर और विविध माध्यमों में परियोजनाएँ"],"explanationHi":"विविध, सतत आकलन प्रत्येक बच्चे को दिखाने देता है कि उसने क्या सीखा है और शिक्षण का मार्गदर्शन करता है; एक लिखित परीक्षा अधिगम के साथ-साथ माध्यम की बाधा को भी मापती है।"},
  {"id":"cdp-child-development-847","question":"Assertion (A): Placing a child with a disability in a regular classroom is, by itself, enough to achieve inclusion. Reason (R): Inclusion requires changes in teaching, materials, attitudes and assessment so that the child participates and learns.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Physical placement without change is integration or ‘dumping’; inclusion needs active adaptation of the system, so A is false and R is true.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"अभिकथन (A): अक्षमता वाले बच्चे को नियमित कक्षा में रखना, अपने आप में, समावेशन प्राप्त करने के लिए पर्याप्त है। कारण (R): समावेशन के लिए शिक्षण, सामग्री, दृष्टिकोण और आकलन में परिवर्तन आवश्यक हैं ताकि बच्चा भाग ले और सीखे।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"बिना परिवर्तन के भौतिक स्थान-निर्धारण एकीकरण या ‘डंपिंग’ है; समावेशन के लिए व्यवस्था का सक्रिय अनुकूलन आवश्यक है, इसलिए A असत्य है और R सत्य।"},
  {"id":"cdp-child-development-848","question":"Before Eid, a Class 5 teacher in Hyderabad plans a lesson where children share how festivals are celebrated in their homes, including Eid, Bonalu, Christmas and Diwali, and finds similarities and differences. What is the main value of this activity for inclusion?","options":["It replaces the need to follow the syllabus during the festival season","It values each child’s culture equally and makes diversity feel normal","It helps the teacher find out which religion each child follows at home","It is useful only in schools where all children share one religion"],"answer":1,"explanation":"Drawing on all children's cultural experiences affirms their identities and builds respect across groups, which is central to an inclusive classroom.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"ईद से पहले हैदराबाद में कक्षा 5 की एक शिक्षिका ऐसा पाठ योजनाबद्ध करती है जिसमें बच्चे साझा करते हैं कि उनके घरों में त्योहार कैसे मनाए जाते हैं, जिनमें ईद, बोनालु, क्रिसमस और दिवाली शामिल हैं, और समानताएँ तथा भिन्नताएँ खोजते हैं। समावेशन के लिए इस गतिविधि का मुख्य मूल्य क्या है?","optionsHi":["यह त्योहारों के मौसम में पाठ्यक्रम का पालन करने की आवश्यकता को प्रतिस्थापित करती है","यह प्रत्येक बच्चे की संस्कृति को समान महत्त्व देती है और विविधता को सामान्य बनाती है","यह शिक्षक को यह पता लगाने में सहायता करती है कि प्रत्येक बच्चा घर पर किस धर्म का पालन करता है","यह केवल उन विद्यालयों में उपयोगी है जहाँ सभी बच्चे एक ही धर्म साझा करते हैं"],"explanationHi":"सभी बच्चों के सांस्कृतिक अनुभवों को आधार बनाना उनकी पहचान की पुष्टि करता है और समूहों के बीच सम्मान बनाता है, जो समावेशी कक्षा का केंद्र है।"},
  {"id":"cdp-child-development-849","question":"Laila, who is deaf-blind, is joining Class 1 of a regular school in Kerala. Which consideration is most important when planning her communication?","options":["Since she can neither see nor hear, she cannot be taught in a regular school","Consistent touch-based communication, like tactile signing and objects of reference","She should be taught Braille first, before any other form of communication","Loud speech close to her ear will be enough for her to follow the lessons"],"answer":1,"explanation":"Deaf-blindness needs touch-based communication used consistently by everyone around the child; the RPwD Act also requires education of children who are blind, deaf or both in the most appropriate modes.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"बधिर-दृष्टिहीन लैला केरल के एक नियमित विद्यालय की कक्षा 1 में प्रवेश ले रही है। उसके संप्रेषण की योजना बनाते समय कौन-सा विचार सबसे महत्त्वपूर्ण है?","optionsHi":["चूँकि वह न देख सकती है न सुन सकती है, उसे नियमित विद्यालय में नहीं पढ़ाया जा सकता","सुसंगत स्पर्श-आधारित संप्रेषण, जैसे स्पर्शीय संकेत और संदर्भ-वस्तुएँ","उसे किसी भी अन्य संप्रेषण से पहले ब्रेल सिखाई जानी चाहिए","उसके कान के पास ज़ोर से बोलना पाठों का अनुसरण करने के लिए पर्याप्त होगा"],"explanationHi":"बधिर-दृष्टिहीनता में स्पर्श-आधारित संप्रेषण चाहिए जिसे बच्चे के आसपास सभी सुसंगत रूप से प्रयोग करें; RPwD अधिनियम भी नेत्रहीन, बधिर या दोनों बच्चों की शिक्षा सबसे उपयुक्त माध्यमों में अपेक्षित करता है।"},
  {"id":"cdp-child-development-850","question":"In a Basic (Nai Talim) school, Class 4 children learn arithmetic by measuring and counting the yarn they spin, geography by finding where cotton is grown, and history through the story of handloom weaving in India. This technique of Basic Education is called:","options":["Integration of subjects through separate textbook units","Programmed learning in small, self-paced steps","Correlation of subjects with the craft and the environment","Ability grouping by children’s skill at spinning"],"answer":2,"explanation":"The Wardha scheme taught subjects by correlating them with three centres: the basic craft, the physical environment and the social environment, so knowledge grew out of productive activity.","difficulty":"hard","source":"CTET · UPTET · REET","questionHi":"एक बुनियादी (नई तालीम) विद्यालय में कक्षा 4 के बच्चे अपने काते हुए सूत को नापकर और गिनकर अंकगणित सीखते हैं, कपास कहाँ उगाई जाती है यह खोजकर भूगोल, और भारत में हथकरघा बुनाई की कहानी के माध्यम से इतिहास। बुनियादी शिक्षा की इस तकनीक को क्या कहते हैं?","optionsHi":["अलग पाठ्यपुस्तक इकाइयों के माध्यम से विषयों का समन्वय","छोटे, स्व-गति वाले चरणों में अभिक्रमित अधिगम","विषयों का शिल्प और परिवेश के साथ सहसंबंध","बच्चों की कताई-कौशल के आधार पर क्षमता-समूहन"],"explanationHi":"वर्धा योजना ने विषयों को तीन केंद्रों से सहसंबद्ध करके पढ़ाया: बुनियादी शिल्प, भौतिक परिवेश और सामाजिक परिवेश, जिससे ज्ञान उत्पादक गतिविधि से उपजा।"},
  {"id":"cdp-child-development-851","question":"Which of these were features of Gandhi’s scheme of Basic Education (Nai Talim)? I. Education centred on a productive craft. II. The mother tongue as the medium of instruction. III. English compulsory from the first class. IV. Education made partly self-supporting through the sale of craft products.","options":["I, II and IV only","I and III only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"Basic Education was craft-centred, taught through the mother tongue and meant to be partly self-supporting; it did not make English compulsory, so III is wrong.","difficulty":"very-hard","source":"CTET · State TET","questionHi":"गांधीजी की बुनियादी शिक्षा (नई तालीम) की योजना की विशेषताओं में से कौन-सी थीं? I. उत्पादक शिल्प पर केंद्रित शिक्षा। II. शिक्षा का माध्यम मातृभाषा। III. पहली कक्षा से अंग्रेज़ी अनिवार्य। IV. शिल्प-उत्पादों की बिक्री से शिक्षा को आंशिक रूप से स्वावलंबी बनाना।","optionsHi":["केवल I, II और IV","केवल I और III","केवल II, III और IV","I, II, III और IV"],"explanationHi":"बुनियादी शिक्षा शिल्प-केंद्रित थी, मातृभाषा के माध्यम से पढ़ाई जाती थी और आंशिक रूप से स्वावलंबी बनाने के लिए थी; उसने अंग्रेज़ी अनिवार्य नहीं की, इसलिए III गलत है।"},
  {"id":"cdp-child-development-852","question":"A school claims to follow Gandhi’s idea of education. Which of its practices contradicts that idea most?","options":["Linking daily lessons to work in the school’s vegetable garden","Teaching in the children’s mother tongue in the early classes","Stressing cleanliness, cooperation and self-reliance in daily routines","Treating literacy as the whole of education and testing only that"],"answer":3,"explanation":"Gandhi saw education as an all-round drawing out of the best in body, mind and spirit, and said literacy is neither the end nor even the beginning of education.","difficulty":"hard","source":"CTET · UPTET","questionHi":"एक विद्यालय दावा करता है कि वह गांधीजी के शिक्षा-विचार का पालन करता है। उसकी कौन-सी प्रथा उस विचार का सबसे अधिक खंडन करती है?","optionsHi":["दैनिक पाठों को विद्यालय की सब्ज़ी-बाड़ी के काम से जोड़ना","प्रारंभिक कक्षाओं में बच्चों की मातृभाषा में पढ़ाना","दैनिक दिनचर्या में स्वच्छता, सहयोग और आत्मनिर्भरता पर बल देना","साक्षरता को ही संपूर्ण शिक्षा मानना और केवल उसी की परीक्षा लेना"],"explanationHi":"गांधीजी शिक्षा को शरीर, मन और आत्मा में सर्वश्रेष्ठ के सर्वांगीण उद्घाटन के रूप में देखते थे, और कहते थे कि साक्षरता न शिक्षा का अंत है न आरंभ भी।"},
  {"id":"cdp-child-development-853","question":"Assertion (A): Gandhi’s Basic Education was meant mainly to train children as skilled labourers for factories. Reason (R): Gandhi saw craft as a medium for developing the whole personality: body, mind and spirit.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Craft in Nai Talim was a medium of education, not vocational training for industry; Gandhi meant it to develop head, hand and heart together and build self-reliant village communities.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"अभिकथन (A): गांधीजी की बुनियादी शिक्षा का उद्देश्य मुख्यतः बच्चों को कारख़ानों के लिए कुशल श्रमिक के रूप में प्रशिक्षित करना था। कारण (R): गांधीजी शिल्प को संपूर्ण व्यक्तित्व के विकास का माध्यम मानते थे: शरीर, मन और आत्मा।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"नई तालीम में शिल्प शिक्षा का माध्यम था, उद्योग के लिए व्यावसायिक प्रशिक्षण नहीं; गांधीजी का आशय था कि वह मस्तिष्क, हाथ और हृदय को साथ-साथ विकसित करे और आत्मनिर्भर ग्राम समुदाय बनाए।"},
  {"id":"cdp-child-development-854","question":"Which statement about the origin of Basic Education is correct?","options":["It was proposed by the Kothari Commission in 1966 and detailed by D. S. Kothari","It was discussed at Wardha in 1937 and detailed by a committee under Dr Zakir Husain","It was proposed by Tagore at Santiniketan in 1901 and detailed by Gijubhai Badheka","It was recommended by the NPE, 1986 and detailed by the Yash Pal committee"],"answer":1,"explanation":"Gandhi’s proposals were discussed at the Wardha conference (1937), and the Zakir Husain committee drew up the Wardha scheme of Basic Education.","difficulty":"moderate","source":"CTET · UPTET · REET","questionHi":"बुनियादी शिक्षा की उत्पत्ति के बारे में कौन-सा कथन सही है?","optionsHi":["इसे 1966 में कोठारी आयोग ने प्रस्तावित किया और डी. एस. कोठारी ने विस्तृत किया","इस पर 1937 में वर्धा में चर्चा हुई और डॉ. ज़ाकिर हुसैन की अध्यक्षता वाली समिति ने इसे विस्तृत किया","इसे 1901 में शांतिनिकेतन में टैगोर ने प्रस्तावित किया और गिजुभाई बधेका ने विस्तृत किया","इसकी अनुशंसा NPE, 1986 ने की और यश पाल समिति ने विस्तृत किया"],"explanationHi":"गांधीजी के प्रस्तावों पर वर्धा सम्मेलन (1937) में चर्चा हुई, और ज़ाकिर हुसैन समिति ने बुनियादी शिक्षा की वर्धा योजना तैयार की।"},
  {"id":"cdp-child-development-855","question":"NCF 2005’s focus on ‘work and education’ and NEP 2020’s call for vocational exposure from the middle stage both echo Gandhi’s Nai Talim mainly in their belief that:","options":["Work should be reserved only for children who fail in the academic subjects","Vocational training should fully replace academic subjects after Class 5","Productive work is a valid medium of learning, not walled off from academics","Children should be paid fair wages for the productive work they do in school"],"answer":2,"explanation":"Both documents treat work as a source of knowledge and values and reject a hard divide between vocational and academic learning, an idea at the heart of Nai Talim.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT","questionHi":"NCF 2005 का ‘कार्य और शिक्षा’ पर ध्यान और NEP 2020 का मध्य स्तर से व्यावसायिक अनुभव का आह्वान, दोनों गांधीजी की नई तालीम की प्रतिध्वनि मुख्यतः किस विश्वास में करते हैं?","optionsHi":["कार्य केवल उन बच्चों के लिए आरक्षित होना चाहिए जो शैक्षणिक विषयों में अनुत्तीर्ण होते हैं","कक्षा 5 के बाद व्यावसायिक प्रशिक्षण को शैक्षणिक विषयों का पूर्णतः स्थान लेना चाहिए","उत्पादक कार्य अधिगम का वैध माध्यम है, शैक्षणिक विषयों से दीवार बनाकर अलग नहीं","बच्चों को विद्यालय में किए गए उत्पादक कार्य के लिए उचित मज़दूरी दी जानी चाहिए"],"explanationHi":"दोनों दस्तावेज़ कार्य को ज्ञान और मूल्यों का स्रोत मानते हैं और व्यावसायिक तथा शैक्षणिक अधिगम के बीच कठोर विभाजन को अस्वीकार करते हैं, जो नई तालीम के केंद्र का विचार है।"},
  {"id":"cdp-child-development-856","question":"Tagore’s satirical story ‘The Parrot’s Training’ (Tota Kahini) is best read as a critique of:","options":["Schooling that crams pupils with lessons while killing their natural joy","The excessive freedom given to children in open-air nature schools","Teaching through the mother tongue instead of a classical language","A shortage of buildings, books and equipment in village schools"],"answer":0,"explanation":"In the story the parrot is caged in gold and force-fed pages until it dies; Tagore mocks lavish but lifeless schooling that values the apparatus over the living child.","difficulty":"hard","source":"CTET · State TET","questionHi":"टैगोर की व्यंग्यात्मक कहानी ‘तोता कहानी’ (द पैरट्स ट्रेनिंग) को सबसे अच्छी तरह किसकी आलोचना के रूप में पढ़ा जा सकता है?","optionsHi":["उस विद्यालयी शिक्षा की जो विद्यार्थियों को पाठों से ठूँसती है और उनके स्वाभाविक आनंद को मार देती है","खुली हवा वाले प्रकृति-विद्यालयों में बच्चों को दी गई अत्यधिक स्वतंत्रता की","शास्त्रीय भाषा के बजाय मातृभाषा के माध्यम से पढ़ाने की","ग्रामीण विद्यालयों में भवनों, पुस्तकों और उपकरणों की कमी की"],"explanationHi":"कहानी में तोते को सोने के पिंजरे में बंद करके तब तक पन्ने ठूँसे जाते हैं जब तक वह मर नहीं जाता; टैगोर उस भव्य पर निर्जीव विद्यालयी शिक्षा का उपहास करते हैं जो जीवित बच्चे से अधिक साज-सामान को महत्त्व देती है।"},
  {"id":"cdp-child-development-857","question":"At Santiniketan, Tagore held many classes in the open, under the trees. His main educational reason was that:","options":["The cost of school buildings had to be saved for books and teachers","Open-air classes made discipline easier to enforce among the children","Close contact with nature nourishes the child’s senses, freedom and joy","Open-air teaching was the surest protection against disease in Bengal"],"answer":2,"explanation":"Tagore believed that a child grows best in harmony with nature and in freedom; walls and rigid routines, he felt, cut the child off from the living world.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"शांतिनिकेतन में टैगोर कई कक्षाएँ खुले में, पेड़ों के नीचे लगाते थे। इसका उनका मुख्य शैक्षिक कारण था कि:","optionsHi":["विद्यालय-भवनों का खर्च पुस्तकों और शिक्षकों के लिए बचाना था","खुली हवा की कक्षाओं से बच्चों में अनुशासन लागू करना आसान होता था","प्रकृति से निकट संपर्क बच्चे की इंद्रियों, स्वतंत्रता और आनंद का पोषण करता है","खुले में शिक्षण बंगाल में रोगों से सबसे पक्की सुरक्षा थी"],"explanationHi":"टैगोर का विश्वास था कि बच्चा प्रकृति के साथ सामंजस्य और स्वतंत्रता में सबसे अच्छा विकसित होता है; उनके विचार में दीवारें और कठोर दिनचर्याएँ बच्चे को जीवंत संसार से काट देती हैं।"},
  {"id":"cdp-child-development-858","question":"Which of these statements about Rabindranath Tagore’s educational ideas are correct? I. He held that the mother tongue should be the medium of education. II. He founded Visva-Bharati with the internationalist ideal of a meeting of cultures. III. He regarded music, art and drama as frills to be kept out of the timetable. IV. Through Sriniketan he linked education with rural reconstruction.","options":["I, II and III only","I, II and IV only","II and IV only","I, III and IV only"],"answer":1,"explanation":"Tagore championed the mother tongue, internationalism (Visva-Bharati) and rural reconstruction (Sriniketan); the arts were central to his school, not frills, so III is false.","difficulty":"very-hard","source":"CTET · DSSSB TGT","questionHi":"रवींद्रनाथ टैगोर के शैक्षिक विचारों के बारे में इनमें से कौन-से कथन सही हैं? I. उनका मत था कि शिक्षा का माध्यम मातृभाषा होनी चाहिए। II. उन्होंने संस्कृतियों के मिलन के अंतर्राष्ट्रीयतावादी आदर्श के साथ विश्व-भारती की स्थापना की। III. वे संगीत, कला और नाटक को ऐसी सजावट मानते थे जिन्हें समय-सारणी से बाहर रखा जाए। IV. श्रीनिकेतन के माध्यम से उन्होंने शिक्षा को ग्रामीण पुनर्निर्माण से जोड़ा।","optionsHi":["केवल I, II और III","केवल I, II और IV","केवल II और IV","केवल I, III और IV"],"explanationHi":"टैगोर ने मातृभाषा, अंतर्राष्ट्रीयता (विश्व-भारती) और ग्रामीण पुनर्निर्माण (श्रीनिकेतन) का समर्थन किया; कलाएँ उनके विद्यालय का केंद्र थीं, सजावट नहीं, इसलिए III असत्य है।"},
  {"id":"cdp-child-development-859","question":"In Gijubhai Badheka’s ‘Divaswapna’, the teacher Lakshmishankar spends the first days of term telling stories and playing games before starting formal lessons. The idea behind this is that:","options":["Formal teaching is unnecessary in primary school, so lessons can wait","Stories and games should permanently replace the prescribed syllabus","Children should be kept busy so that the headmaster is satisfied","A bond of trust and interest must come before meaningful learning"],"answer":3,"explanation":"Lakshmishankar first wins the children’s trust, attention and joy through stories and games, and then builds language and other learning on that foundation.","difficulty":"hard","source":"CTET Paper I · State TET","questionHi":"गिजुभाई बधेका की ‘दिवास्वप्न’ में शिक्षक लक्ष्मीशंकर औपचारिक पाठ शुरू करने से पहले सत्र के पहले दिन कहानियाँ सुनाने और खेल खेलने में बिताते हैं। इसके पीछे विचार यह है कि:","optionsHi":["प्राथमिक विद्यालय में औपचारिक शिक्षण अनावश्यक है, इसलिए पाठ प्रतीक्षा कर सकते हैं","कहानियों और खेलों को निर्धारित पाठ्यक्रम का स्थायी स्थान लेना चाहिए","बच्चों को व्यस्त रखना चाहिए ताकि प्रधानाध्यापक संतुष्ट रहें","सार्थक अधिगम से पहले विश्वास और रुचि का बंधन बनना चाहिए"],"explanationHi":"लक्ष्मीशंकर पहले कहानियों और खेलों के माध्यम से बच्चों का विश्वास, ध्यान और आनंद जीतते हैं, और फिर उस आधार पर भाषा तथा अन्य अधिगम निर्मित करते हैं।"},
  {"id":"cdp-child-development-860","question":"Which of these statements about Gijubhai Badheka are correct? I. He adapted Montessori’s ideas to Indian conditions and founded a Bal Mandir at Bhavnagar. II. He wrote a large body of stories and literature for children. III. He opposed fear, punishment and rote examinations in primary schools. IV. He headed the committee that drafted the Wardha scheme.","options":["I, II and III only","I and IV only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"Gijubhai founded the Dakshinamurti Bal Mandir, wrote widely for children and fought fear-based teaching; the Wardha scheme committee was headed by Zakir Husain, so IV is false.","difficulty":"very-hard","source":"CTET Paper I · UPTET","questionHi":"गिजुभाई बधेका के बारे में इनमें से कौन-से कथन सही हैं? I. उन्होंने मॉन्टेसरी के विचारों को भारतीय परिस्थितियों के अनुकूल बनाया और भावनगर में बाल मंदिर की स्थापना की। II. उन्होंने बच्चों के लिए कहानियों और साहित्य का विशाल संग्रह लिखा। III. उन्होंने प्राथमिक विद्यालयों में भय, दंड और रटंत परीक्षाओं का विरोध किया। IV. उन्होंने वर्धा योजना का मसौदा तैयार करने वाली समिति की अध्यक्षता की।","optionsHi":["केवल I, II और III","केवल I और IV","केवल II, III और IV","I, II, III और IV"],"explanationHi":"गिजुभाई ने दक्षिणामूर्ति बाल मंदिर की स्थापना की, बच्चों के लिए व्यापक लेखन किया और भय-आधारित शिक्षण से संघर्ष किया; वर्धा योजना समिति की अध्यक्षता ज़ाकिर हुसैन ने की, इसलिए IV असत्य है।"},
  {"id":"cdp-child-development-861","question":"Match each thinker with the idea most closely linked to him: P. Gandhi  Q. Tagore  R. Gijubhai Badheka  S. Dewey — 1. Craft-centred education of the head, heart and hand  2. Harmony with nature, freedom and internationalism  3. Bal Mandir and joyful, fear-free primary teaching through stories  4. The school as an embryonic democratic community","options":["P-2, Q-1, R-3, S-4","P-1, Q-2, R-4, S-3","P-1, Q-2, R-3, S-4","P-3, Q-2, R-1, S-4"],"answer":2,"explanation":"Gandhi stressed craft and 3H education, Tagore nature, freedom and internationalism, Gijubhai joyful teaching in his Bal Mandir, and Dewey the school as a democratic community.","difficulty":"hard","source":"CTET · KVS PRT","questionHi":"प्रत्येक विचारक का मिलान उस विचार से कीजिए जो उससे सबसे निकटता से जुड़ा है: P. गांधी  Q. टैगोर  R. गिजुभाई बधेका  S. डेवी — 1. मस्तिष्क, हृदय और हाथ की शिल्प-केंद्रित शिक्षा  2. प्रकृति के साथ सामंजस्य, स्वतंत्रता और अंतर्राष्ट्रीयता  3. बाल मंदिर और कहानियों के माध्यम से आनंदपूर्ण, भय-मुक्त प्राथमिक शिक्षण  4. विद्यालय एक भ्रूणीय लोकतांत्रिक समुदाय के रूप में","optionsHi":["P-2, Q-1, R-3, S-4","P-1, Q-2, R-4, S-3","P-1, Q-2, R-3, S-4","P-3, Q-2, R-1, S-4"],"explanationHi":"गांधी ने शिल्प और 3H शिक्षा पर बल दिया, टैगोर ने प्रकृति, स्वतंत्रता और अंतर्राष्ट्रीयता पर, गिजुभाई ने अपने बाल मंदिर में आनंदपूर्ण शिक्षण पर, और डेवी ने विद्यालय को लोकतांत्रिक समुदाय के रूप में।"},
  {"id":"cdp-child-development-862","question":"Both Gandhi’s Nai Talim and Dewey’s progressive education:","options":["Rejected the mother tongue as the medium of instruction in schools","Saw purposeful work linked to community life as the core of learning","Made religious instruction the centre of the school curriculum","Aimed mainly to train children for regular factory employment"],"answer":1,"explanation":"Both made purposeful, socially useful activity the starting point of learning and tied the school to community life; neither centred on religious instruction or factory training.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"गांधी की नई तालीम और डेवी की प्रगतिशील शिक्षा, दोनों:","optionsHi":["ने विद्यालयों में शिक्षा के माध्यम के रूप में मातृभाषा को अस्वीकार किया","ने समुदाय के जीवन से जुड़े उद्देश्यपूर्ण कार्य को अधिगम का केंद्र माना","ने धार्मिक शिक्षा को विद्यालयी पाठ्यचर्या का केंद्र बनाया","का उद्देश्य मुख्यतः बच्चों को नियमित कारख़ाना-रोज़गार के लिए प्रशिक्षित करना था"],"explanationHi":"दोनों ने उद्देश्यपूर्ण, सामाजिक रूप से उपयोगी गतिविधि को अधिगम का आरंभ-बिंदु बनाया और विद्यालय को समुदाय-जीवन से जोड़ा; किसी ने धार्मिक शिक्षा या कारख़ाना-प्रशिक्षण को केंद्र नहीं बनाया।"},
  {"id":"cdp-child-development-863","question":"A frequent criticism of Basic Education as originally proposed was that:","options":["It ignored the mother tongue and taught mainly in English","It gave no place to manual work or productive craft","It was designed only for urban elite schools, not for villages","Its self-supporting aim risked putting craft sales above learning"],"answer":3,"explanation":"Critics feared that the self-supporting aim could make output, not learning, the goal; the scheme was in fact mother-tongue based, craft-centred and aimed at village children.","difficulty":"hard","source":"CTET · UPTET","questionHi":"मूल रूप से प्रस्तावित बुनियादी शिक्षा की एक बार-बार दोहराई जाने वाली आलोचना यह थी कि:","optionsHi":["उसने मातृभाषा की उपेक्षा की और मुख्यतः अंग्रेज़ी में पढ़ाया","उसमें शारीरिक कार्य या उत्पादक शिल्प के लिए कोई स्थान नहीं था","वह केवल शहरी अभिजात विद्यालयों के लिए बनी थी, गाँवों के लिए नहीं","उसका स्वावलंबी लक्ष्य शिल्प-बिक्री को अधिगम से ऊपर रखने का जोखिम रखता था"],"explanationHi":"आलोचकों को भय था कि स्वावलंबी लक्ष्य उत्पादन को, अधिगम को नहीं, लक्ष्य बना सकता है; योजना वास्तव में मातृभाषा-आधारित, शिल्प-केंद्रित थी और ग्रामीण बच्चों के लिए थी।"},
  {"id":"cdp-child-development-864","question":"A school inspired by Tagore would most likely include:","options":["Music, dance, drama and nature walks woven into daily learning","Long hours of copy-writing in silent rows to build discipline","Uniform textbooks and weekly ranking tests for every class","A ban on festivals and celebrations to save teaching time"],"answer":0,"explanation":"Tagore placed the arts, festivals and nature at the heart of learning at Santiniketan; mechanical copying and competitive ranking were what he rejected.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"टैगोर से प्रेरित विद्यालय में सबसे संभावित रूप से क्या शामिल होगा?","optionsHi":["संगीत, नृत्य, नाटक और प्रकृति-भ्रमण जो दैनिक अधिगम में बुने हों","अनुशासन बनाने के लिए चुप पंक्तियों में प्रतिलिपि-लेखन के लंबे घंटे","प्रत्येक कक्षा के लिए एकसमान पाठ्यपुस्तकें और साप्ताहिक श्रेणीकरण परीक्षाएँ","शिक्षण-समय बचाने के लिए त्योहारों और उत्सवों पर प्रतिबंध"],"explanationHi":"टैगोर ने शांतिनिकेतन में कलाओं, उत्सवों और प्रकृति को अधिगम के केंद्र में रखा; यांत्रिक प्रतिलिपि और प्रतिस्पर्धी श्रेणीकरण वे थे जिन्हें उन्होंने अस्वीकार किया।"},
  {"id":"cdp-child-development-865","question":"Tagore criticised the education of his time chiefly because it was:","options":["Too practical and too closely tied to village life and its crafts","Given too much in the mother tongue rather than in English","Foreign-medium, cut off from the child’s surroundings and exam-driven","Too generous in the freedom and play it allowed young children"],"answer":2,"explanation":"Tagore attacked colonial schooling as foreign-medium, bookish, examination-driven and divorced from the child’s life and nature; he wanted the very opposite of options A, B and D.","difficulty":"very-hard","source":"CTET Paper II · State TET","questionHi":"टैगोर ने अपने समय की शिक्षा की आलोचना मुख्यतः इसलिए की क्योंकि वह थी:","optionsHi":["बहुत व्यावहारिक और ग्रामीण जीवन तथा उसके शिल्पों से बहुत निकटता से जुड़ी","अंग्रेज़ी के बजाय मातृभाषा में बहुत अधिक दी जाने वाली","विदेशी माध्यम वाली, बच्चे के परिवेश से कटी हुई और परीक्षा-चालित","छोटे बच्चों को दी गई स्वतंत्रता और खेल में बहुत उदार"],"explanationHi":"टैगोर ने औपनिवेशिक विद्यालयी शिक्षा पर प्रहार किया क्योंकि वह विदेशी माध्यम वाली, किताबी, परीक्षा-चालित और बच्चे के जीवन तथा प्रकृति से विच्छिन्न थी; वे विकल्प A, B और D का ठीक उलटा चाहते थे।"},
  {"id":"cdp-child-development-866","question":"A teacher in a village school in Rajasthan teaches measurement by making clay pots with a local potter, uses folk songs and stories to teach rhythm and counting, and keeps her class free of fear. Which pair of Indian thinkers’ ideas does she most clearly draw on?","options":["Vivekananda (man-making education) and Aurobindo (integral education)","Gandhi (craft-centred learning) and Gijubhai Badheka (fear-free learning)","Macaulay (downward filtration) and Charles Wood (graded schools)","Rousseau (negative education) and Locke (the mind as a blank slate)"],"answer":1,"explanation":"Learning through a local craft reflects Nai Talim, while joyful, fear-free teaching through songs and stories is Gijubhai’s hallmark.","difficulty":"hard","source":"CTET · REET","questionHi":"राजस्थान के एक ग्रामीण विद्यालय की शिक्षिका एक स्थानीय कुम्हार के साथ मिट्टी के घड़े बनाकर मापन सिखाती है, लय और गिनती सिखाने के लिए लोकगीतों और कहानियों का प्रयोग करती है, और अपनी कक्षा को भय से मुक्त रखती है। वह किन दो भारतीय विचारकों के विचारों को सबसे स्पष्ट रूप से अपनाती है?","optionsHi":["विवेकानंद (मनुष्य-निर्माणकारी शिक्षा) और अरविंद (समग्र शिक्षा)","गांधी (शिल्प-केंद्रित अधिगम) और गिजुभाई बधेका (भय-मुक्त अधिगम)","मैकाले (अधोमुखी निस्यंदन) और चार्ल्स वुड (श्रेणीबद्ध विद्यालय)","रूसो (नकारात्मक शिक्षा) और लॉक (मन कोरी पट्टिका के रूप में)"],"explanationHi":"स्थानीय शिल्प के माध्यम से सीखना नई तालीम को दर्शाता है, जबकि गीतों और कहानियों के माध्यम से आनंदपूर्ण, भय-मुक्त शिक्षण गिजुभाई की पहचान है।"},
  {"id":"cdp-child-development-867","question":"Assertion (A): Gijubhai Badheka held that strict examinations are necessary to make young children study. Reason (R): He believed that joy, freedom and interest are the basis of learning in the early years.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Gijubhai opposed fear, punishment and examination pressure on young children; he built learning on interest, play and stories, so A is false while R is true.","difficulty":"very-hard","source":"CTET Paper I · UPTET","questionHi":"अभिकथन (A): गिजुभाई बधेका का मत था कि छोटे बच्चों को पढ़ने के लिए बाध्य करने हेतु कठोर परीक्षाएँ आवश्यक हैं। कारण (R): उनका विश्वास था कि आरंभिक वर्षों में आनंद, स्वतंत्रता और रुचि ही अधिगम का आधार हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"गिजुभाई ने छोटे बच्चों पर भय, दंड और परीक्षा के दबाव का विरोध किया; उन्होंने अधिगम रुचि, खेल और कहानियों पर निर्मित किया, इसलिए A असत्य है जबकि R सत्य।"},
  {"id":"cdp-child-development-868","question":"Under the Wardha scheme of Basic Education, free and compulsory education was to be given for:","options":["5 years, for ages 6 to 11","8 years, for ages 6 to 14","7 years, for ages 7 to 14","10 years, for ages 6 to 16"],"answer":2,"explanation":"The 1937 scheme proposed seven years of free and compulsory education (7 to 14); the 6 to 14 range belongs to the RTE Act, 2009, a common mix-up.","difficulty":"hard","source":"CTET · UPTET · REET","questionHi":"बुनियादी शिक्षा की वर्धा योजना के अंतर्गत निःशुल्क और अनिवार्य शिक्षा कितनी अवधि के लिए दी जानी थी?","optionsHi":["5 वर्ष, 6 से 11 वर्ष की आयु के लिए","8 वर्ष, 6 से 14 वर्ष की आयु के लिए","7 वर्ष, 7 से 14 वर्ष की आयु के लिए","10 वर्ष, 6 से 16 वर्ष की आयु के लिए"],"explanationHi":"1937 की योजना ने सात वर्ष की निःशुल्क और अनिवार्य शिक्षा (7 से 14) प्रस्तावित की; 6 से 14 का दायरा RTE अधिनियम, 2009 का है, जो एक आम भ्रम है।"},
  {"id":"cdp-child-development-869","question":"The Dakshinamurti Bal Mandir set up by Gijubhai Badheka at Bhavnagar adapted the ideas of which educator, and with what change?","options":["Maria Montessori, swapping costly apparatus for local materials and stories","J. F. Herbart, introducing his five formal steps of lesson planning","B. F. Skinner, using teaching machines with immediate reinforcement","John Locke, emphasising discipline through habit formation and drill"],"answer":0,"explanation":"Gijubhai was deeply influenced by Montessori but Indianised her method, using inexpensive local materials, folk songs, games and stories.","difficulty":"hard","source":"CTET Paper I · State TET","questionHi":"गिजुभाई बधेका द्वारा भावनगर में स्थापित दक्षिणामूर्ति बाल मंदिर ने किस शिक्षाविद् के विचारों को अपनाया, और किस परिवर्तन के साथ?","optionsHi":["मारिया मॉन्टेसरी, महँगे उपकरणों के स्थान पर स्थानीय सामग्री और कहानियों के साथ","जे. एफ़. हर्बार्ट, पाठ-योजना के उनके पाँच औपचारिक सोपानों को लाते हुए","बी. एफ़. स्किनर, तात्कालिक पुनर्बलन वाली शिक्षण-मशीनों का प्रयोग करते हुए","जॉन लॉक, आदत-निर्माण और अभ्यास द्वारा अनुशासन पर बल देते हुए"],"explanationHi":"गिजुभाई मॉन्टेसरी से गहराई से प्रभावित थे पर उन्होंने उनकी पद्धति को भारतीय बनाया, सस्ती स्थानीय सामग्री, लोकगीतों, खेलों और कहानियों का प्रयोग करके।"},
  {"id":"cdp-child-development-870","question":"Which practice would Tagore most have objected to?","options":["Children composing and performing songs about the changing seasons","Lessons held in the open, among the trees, in every season","Students from different countries and cultures studying together","Memorising answers for exams in a language children barely understand"],"answer":3,"explanation":"Tagore criticised rote, examination-centred learning through a foreign medium; creativity, nature and internationalism were things he actively promoted.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"टैगोर किस प्रथा पर सबसे अधिक आपत्ति करते?","optionsHi":["बच्चों द्वारा बदलती ऋतुओं पर गीत रचना और प्रस्तुत करना","हर ऋतु में पेड़ों के बीच खुले में पाठ आयोजित होना","विभिन्न देशों और संस्कृतियों के विद्यार्थियों का साथ पढ़ना","ऐसी भाषा में परीक्षा के उत्तर रटना जिसे बच्चे मुश्किल से समझते हैं"],"explanationHi":"टैगोर ने विदेशी माध्यम में रटंत, परीक्षा-केंद्रित अधिगम की आलोचना की; रचनात्मकता, प्रकृति और अंतर्राष्ट्रीयता वे थीं जिन्हें उन्होंने सक्रिय रूप से बढ़ावा दिया।"},
  {"id":"cdp-child-development-871","question":"Assertion (A): Gandhi insisted that Basic Education should be given through the mother tongue. Reason (R): He believed that learning through a foreign medium causes strain, encourages cramming and cuts children off from their own surroundings.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Gandhi’s case for the mother tongue rested on exactly these arguments: a foreign medium strains the child, breeds rote learning and alienates him from home and community.","difficulty":"very-hard","source":"CTET · DSSSB PRT","questionHi":"अभिकथन (A): गांधीजी का आग्रह था कि बुनियादी शिक्षा मातृभाषा के माध्यम से दी जानी चाहिए। कारण (R): उनका विश्वास था कि विदेशी माध्यम से सीखना तनाव पैदा करता है, रटंत को बढ़ावा देता है और बच्चों को उनके अपने परिवेश से काट देता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"मातृभाषा के पक्ष में गांधीजी का तर्क ठीक इन्हीं बातों पर टिका था: विदेशी माध्यम बच्चे पर बोझ डालता है, रटंत सीखने को जन्म देता है और उसे घर तथा समुदाय से अलग कर देता है।"},
  {"id":"cdp-child-development-872","question":"For Tagore, a teacher can truly teach only if he or she:","options":["Has memorised the entire syllabus along with its standard answers","Follows the prescribed timetable strictly, without any deviation","Keeps learning, as a lamp lights another only while its own flame burns","Keeps a careful distance from students so as to preserve his or her authority"],"answer":2,"explanation":"Tagore’s image of the lamp says a teacher who has stopped learning can only pass on dead information; living teaching comes from a teacher who keeps growing.","difficulty":"hard","source":"CTET · KVS TGT","questionHi":"टैगोर के लिए, कोई शिक्षक वास्तव में तभी पढ़ा सकता है जब वह:","optionsHi":["संपूर्ण पाठ्यक्रम को उसके मानक उत्तरों सहित रट चुका हो","निर्धारित समय-सारणी का बिना किसी विचलन के कठोरता से पालन करे","स्वयं सीखता रहे, जैसे दीपक दूसरे को तभी जलाता है जब उसकी अपनी लौ जलती हो","अपने अधिकार को बनाए रखने के लिए विद्यार्थियों से सावधानीपूर्वक दूरी रखे"],"explanationHi":"टैगोर का दीपक का बिंब कहता है कि जिस शिक्षक ने सीखना बंद कर दिया है वह केवल मृत जानकारी दे सकता है; जीवंत शिक्षण उस शिक्षक से आता है जो बढ़ता रहता है।"},
  {"id":"cdp-child-development-873","question":"Which NEP 2020 proposal most directly echoes Tagore’s and Gandhi’s insistence on the mother tongue?","options":["English as the compulsory medium of instruction from Grade 1 in all schools","The home language or mother tongue as medium wherever possible, at least till Grade 5","A single national language as the medium of instruction in every state and board","The medium of instruction to be chosen by each student freely, but only after Grade 10"],"answer":1,"explanation":"NEP 2020 recommends the home language or mother tongue as the medium wherever possible, at least till Grade 5 and preferably till Grade 8 and beyond, in line with both thinkers.","difficulty":"hard","source":"CTET · KVS PRT","questionHi":"NEP 2020 का कौन-सा प्रस्ताव टैगोर और गांधी के मातृभाषा के आग्रह की सबसे सीधी प्रतिध्वनि है?","optionsHi":["सभी विद्यालयों में कक्षा 1 से अंग्रेज़ी को अनिवार्य शिक्षा-माध्यम बनाना","जहाँ संभव हो, घर की भाषा या मातृभाषा को माध्यम बनाना, कम से कम कक्षा 5 तक","प्रत्येक राज्य और बोर्ड में एक राष्ट्रीय भाषा को शिक्षा का माध्यम बनाना","शिक्षा का माध्यम प्रत्येक विद्यार्थी द्वारा स्वतंत्र रूप से चुना जाना, पर केवल कक्षा 10 के बाद"],"explanationHi":"NEP 2020 जहाँ संभव हो घर की भाषा या मातृभाषा को माध्यम बनाने की अनुशंसा करती है, कम से कम कक्षा 5 तक और अधिमानतः कक्षा 8 तथा उसके बाद भी, जो दोनों विचारकों के अनुरूप है।"},
  {"id":"cdp-child-development-874","question":"Which statement about the aim of Nai Talim is MOST accurate?","options":["To prepare educated clerks for government service in the towns","To build self-reliant people rooted in village life through productive work","To prepare children well for competitive examinations and higher studies abroad","To spread English-medium education to children in the villages of India"],"answer":1,"explanation":"Nai Talim aimed at self-reliant, socially useful citizens of a non-exploitative village society; it was a reaction against clerk-producing colonial education.","difficulty":"moderate","source":"CTET · UPTET","questionHi":"नई तालीम के उद्देश्य के बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["कस्बों में सरकारी सेवा के लिए शिक्षित क्लर्क तैयार करना","उत्पादक कार्य के माध्यम से ग्राम-जीवन में जड़ें रखने वाले आत्मनिर्भर लोगों का निर्माण करना","बच्चों को प्रतियोगी परीक्षाओं और विदेश में उच्च अध्ययन के लिए भली-भाँति तैयार करना","भारत के गाँवों के बच्चों में अंग्रेज़ी-माध्यम शिक्षा का प्रसार करना"],"explanationHi":"नई तालीम का उद्देश्य एक शोषण-रहित ग्राम-समाज के आत्मनिर्भर, सामाजिक रूप से उपयोगी नागरिक बनाना था; वह क्लर्क पैदा करने वाली औपनिवेशिक शिक्षा की प्रतिक्रिया थी।"},
  {"id":"cdp-child-development-875","question":"How does NCF 2005 recommend that gender concerns be addressed in the school curriculum?","options":["Through a separate chapter on women’s issues in the Class 8 social science book","As a concern cutting across all subjects, textbooks and school practices","By offering separate subjects for boys and girls at the secondary stage","Only through special talks and events held on International Women’s Day"],"answer":1,"explanation":"NCF 2005 treats gender as a cross-cutting concern: it must shape content, illustrations, examples, classroom interaction and school culture, not sit in one isolated lesson or event.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"NCF 2005 विद्यालयी पाठ्यचर्या में जेंडर संबंधी चिंताओं को संबोधित करने की अनुशंसा किस प्रकार करती है?","optionsHi":["कक्षा 8 की सामाजिक विज्ञान की पुस्तक में महिलाओं के मुद्दों पर एक अलग अध्याय के माध्यम से","एक ऐसी चिंता के रूप में जो सभी विषयों, पाठ्यपुस्तकों और विद्यालयी प्रथाओं में व्याप्त हो","माध्यमिक स्तर पर लड़कों और लड़कियों के लिए अलग विषय देकर","केवल अंतर्राष्ट्रीय महिला दिवस पर आयोजित विशेष वार्ताओं और कार्यक्रमों के माध्यम से"],"explanationHi":"NCF 2005 जेंडर को एक अंतर-क्षेत्रीय चिंता मानती है: उसे विषय-वस्तु, चित्रों, उदाहरणों, कक्षा की अंतःक्रिया और विद्यालय-संस्कृति को आकार देना चाहिए, किसी एक अलग-थलग पाठ या कार्यक्रम में नहीं बैठना चाहिए।"},
  {"id":"cdp-child-development-876","question":"Assertion (A): A school can pass on gender stereotypes to its students even when its written syllabus never mentions gender. Reason (R): Much of what children learn in school comes through the hidden curriculum of routines, interactions, seating, duties and illustrations.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Stereotypes travel through who is asked to lead, who cleans, which pictures appear and how children are spoken to, all parts of the hidden curriculum, which is exactly why A holds.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): कोई विद्यालय अपने विद्यार्थियों को लैंगिक रूढ़िबद्ध धारणाएँ दे सकता है, भले ही उसका लिखित पाठ्यक्रम कभी जेंडर का उल्लेख न करे। कारण (R): बच्चे विद्यालय में जो कुछ सीखते हैं उसका बड़ा भाग दिनचर्याओं, अंतःक्रियाओं, बैठक, कर्तव्यों और चित्रों के छिपे हुए पाठ्यचर्या से आता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"रूढ़िबद्ध धारणाएँ इस रास्ते चलती हैं कि किससे नेतृत्व करने को कहा जाता है, कौन सफ़ाई करता है, कौन-से चित्र आते हैं और बच्चों से कैसे बात की जाती है, जो सब छिपे हुए पाठ्यक्रम के भाग हैं, और इसी कारण A सही है।"},
  {"id":"cdp-child-development-877","question":"Every birthday, three-year-old Anu receives dolls and kitchen sets from relatives, while her brother receives toy cars and cricket bats; both are praised for playing ‘properly’ with their own toys. This is mainly an example of:","options":["Biological maturation of gender differences","Gender constancy","Gender-role socialisation within the family","Gender identity disorder"],"answer":2,"explanation":"Families shape gender roles by the toys, praise and activities they offer to boys and girls; the differences here are taught, not biologically determined.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"हर जन्मदिन पर तीन वर्ष की अनु को रिश्तेदारों से गुड़ियाँ और रसोई के सेट मिलते हैं, जबकि उसके भाई को खिलौना कारें और क्रिकेट के बल्ले; दोनों की अपने खिलौनों से ‘ठीक से’ खेलने के लिए प्रशंसा की जाती है। यह मुख्यतः किसका उदाहरण है?","optionsHi":["जेंडर अंतरों की जैविक परिपक्वता","जेंडर स्थायित्व","परिवार में जेंडर-भूमिका समाजीकरण","जेंडर पहचान विकार"],"explanationHi":"परिवार लड़कों और लड़कियों को दिए जाने वाले खिलौनों, प्रशंसा और गतिविधियों से जेंडर भूमिकाओं को आकार देते हैं; यहाँ के अंतर सिखाए गए हैं, जैविक रूप से निर्धारित नहीं।"},
  {"id":"cdp-child-development-878","question":"Seven-year-old Pinky often watches television advertisements in which only women cook and clean and only men drive cars and run offices. In play she now insists that ‘ladies cook, men go to office’. Which theory most directly explains how she acquired this belief?","options":["Social learning theory, through observing and imitating models","Classical conditioning, by pairing two stimuli over and over again","Chomsky’s nativist theory of an inborn language device","Freud’s theory of the Oedipus complex and identification"],"answer":0,"explanation":"Bandura’s social learning theory explains gender roles as learned by observing models (in the family and media) and by seeing which behaviours are rewarded.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"सात वर्ष की पिंकी प्रायः टेलीविज़न के ऐसे विज्ञापन देखती है जिनमें केवल महिलाएँ खाना पकाती और सफ़ाई करती हैं और केवल पुरुष कारें चलाते और दफ़्तर चलाते हैं। खेल में अब वह आग्रह करती है कि ‘औरतें खाना पकाती हैं, आदमी दफ़्तर जाते हैं’। कौन-सा सिद्धांत सबसे सीधे समझाता है कि उसने यह विश्वास कैसे पाया?","optionsHi":["सामाजिक अधिगम सिद्धांत, आदर्शों को देखकर और उनकी नकल करके","शास्त्रीय अनुबंधन, दो उद्दीपकों को बार-बार जोड़कर","चॉम्स्की का जन्मजात भाषा-उपकरण का नेटिविस्ट सिद्धांत","फ्रायड का ईडिपस ग्रंथि और तादात्म्य का सिद्धांत"],"explanationHi":"बंडूरा का सामाजिक अधिगम सिद्धांत जेंडर भूमिकाओं की व्याख्या आदर्शों (परिवार और मीडिया में) को देखकर और यह देखकर करता है कि कौन-से व्यवहार पुरस्कृत होते हैं।"},
  {"id":"cdp-child-development-879","question":"A Class 7 teacher replaces words like ‘chairman’, ‘policeman’ and ‘mankind’ in her worksheets with ‘chairperson’, ‘police officer’ and ‘humankind’. The best psychological justification for this change is that:","options":["Gender-neutral words are shorter, simpler and much easier for young children to spell","Always-male role words can shape children’s ideas of who belongs in those roles","Textbook writers and boards have officially banned the older words","The change is only cosmetic and has no real effect on children’s thinking"],"answer":1,"explanation":"Research on generic masculine terms shows they make people imagine mainly men, in line with weak linguistic relativity; neutral terms help children see all roles as open to everyone.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"कक्षा 7 की एक शिक्षिका अपने कार्य-पत्रकों में ‘चेयरमैन’, ‘पुलिसमैन’ और ‘मैनकाइंड’ जैसे शब्दों के स्थान पर ‘चेयरपर्सन’, ‘पुलिस ऑफ़िसर’ और ‘ह्यूमनकाइंड’ रखती है। इस परिवर्तन का सबसे अच्छा मनोवैज्ञानिक औचित्य है कि:","optionsHi":["लिंग-तटस्थ शब्द छोटे, सरल और छोटे बच्चों के लिए वर्तनी में कहीं आसान हैं","सदैव पुरुष-सूचक भूमिका-शब्द बच्चों के इस विचार को आकार दे सकते हैं कि उन भूमिकाओं में कौन फिट बैठता है","पाठ्यपुस्तक-लेखकों और बोर्डों ने पुराने शब्दों पर आधिकारिक प्रतिबंध लगा दिया है","यह परिवर्तन केवल दिखावटी है और बच्चों की सोच पर कोई वास्तविक प्रभाव नहीं डालता"],"explanationHi":"सामान्यीकृत पुल्लिंग शब्दों पर शोध दर्शाता है कि वे लोगों से मुख्यतः पुरुषों की कल्पना करवाते हैं, जो दुर्बल भाषिक सापेक्षता के अनुरूप है; तटस्थ शब्द बच्चों को सभी भूमिकाएँ सबके लिए खुली देखने में सहायता करते हैं।"},
  {"id":"cdp-child-development-880","question":"After a maths test, a teacher tells boys who failed, ‘You didn’t put in enough effort’, but tells girls who failed, ‘Maybe maths just isn’t your thing.’ What long-term effect is most likely?","options":["Girls will try harder, because ability feedback motivates more than effort feedback","Both groups will be equally unaffected, since feedback has little impact","Boys will become helpless, because effort is something they cannot control","Girls will tend to blame low ability, give up, and show learned helplessness"],"answer":3,"explanation":"Attributing failure to a stable, uncontrollable cause (ability) leads to helplessness, while effort attributions keep students trying; such gendered feedback can steer girls away from mathematics.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"गणित की परीक्षा के बाद एक शिक्षिका अनुत्तीर्ण लड़कों से कहती है, ‘तुमने पर्याप्त प्रयास नहीं किया’, पर अनुत्तीर्ण लड़कियों से कहती है, ‘शायद गणित बस तुम्हारा विषय नहीं है।’ दीर्घकाल में सबसे संभावित प्रभाव क्या है?","optionsHi":["लड़कियाँ अधिक प्रयास करेंगी, क्योंकि योग्यता प्रतिपुष्टि प्रयास प्रतिपुष्टि से अधिक प्रेरित करती है","दोनों समूह समान रूप से अप्रभावित रहेंगे, क्योंकि प्रतिपुष्टि का बहुत कम प्रभाव होता है","लड़के असहाय हो जाएँगे, क्योंकि प्रयास ऐसी चीज़ है जिसे वे नियंत्रित नहीं कर सकते","लड़कियाँ कम योग्यता को दोष देने, हार मान लेने और सीखी हुई असहायता दिखाने की प्रवृत्ति रखेंगी"],"explanationHi":"विफलता को स्थिर, अनियंत्रणीय कारण (योग्यता) पर आरोपित करना असहायता की ओर ले जाता है, जबकि प्रयास के आरोपण विद्यार्थियों को प्रयास करते रखते हैं; ऐसी लैंगिक प्रतिपुष्टि लड़कियों को गणित से दूर कर सकती है।"},
  {"id":"cdp-child-development-881","question":"Tanvi is assertive and competitive in inter-school debates, and is also gentle and nurturing while helping juniors with homework. Sandra Bem would describe a person who combines strong traditionally ‘masculine’ and ‘feminine’ traits in this way as:","options":["Androgynous","Gender-typed","Undifferentiated","Gender-constant"],"answer":0,"explanation":"Bem’s measure scored masculine and feminine traits separately; high scores on both indicate androgyny, which she argued allows more flexible behaviour across situations.","difficulty":"hard","source":"KVS PGT · DSSSB TGT","questionHi":"तान्वी अंतर-विद्यालय वाद-विवादों में दृढ़ और प्रतिस्पर्धी है, और छोटे बच्चों की गृहकार्य में सहायता करते समय कोमल और पोषणकारी भी है। सैंड्रा बेम ऐसे व्यक्ति का, जो प्रबल पारंपरिक रूप से ‘पुरुषोचित’ और ‘स्त्रियोचित’ गुणों को इस प्रकार जोड़ता है, कैसे वर्णन करतीं?","optionsHi":["उभयलिंगी (एंड्रोजिनस)","जेंडर-प्रारूपित","अविभेदित","जेंडर-स्थायी"],"explanationHi":"बेम की माप ने पुरुषोचित और स्त्रियोचित गुणों को अलग-अलग अंकित किया; दोनों में उच्च अंक उभयलिंगिता दर्शाते हैं, जिसके बारे में उन्होंने तर्क दिया कि वह स्थितियों में अधिक लचीले व्यवहार की अनुमति देती है।"},
  {"id":"cdp-child-development-882","question":"Girls from several villages stop attending a secondary school in Rajasthan after Class 8. Which measure addresses the problem at its structural roots instead of blaming the girls or their families?","options":["Lecturing parents at meetings on the value of educating their daughters well","Marking the girls as ‘dropouts’ and removing their names from the rolls","Telling the girls that marriage should wait until they finish school","Safe transport, usable toilets and a timetable that fits local work seasons"],"answer":3,"explanation":"Distance, safety, sanitation and household work are major structural barriers to girls’ schooling; removing them is more effective than blaming individuals.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"राजस्थान में कई गाँवों की लड़कियाँ कक्षा 8 के बाद एक माध्यमिक विद्यालय में आना बंद कर देती हैं। कौन-सा उपाय समस्या को लड़कियों या उनके परिवारों को दोष दिए बिना उसकी संरचनात्मक जड़ों पर संबोधित करता है?","optionsHi":["बैठकों में अभिभावकों को अपनी बेटियों को शिक्षित करने के मूल्य पर भाषण देना","लड़कियों को ‘ड्रॉपआउट’ अंकित करना और रजिस्टर से उनके नाम हटाना","लड़कियों को बताना कि विवाह उनके विद्यालय पूरा करने तक रुकना चाहिए","सुरक्षित परिवहन, उपयोग-योग्य शौचालय और ऐसी समय-सारणी जो स्थानीय कार्य-ऋतुओं के अनुरूप हो"],"explanationHi":"दूरी, सुरक्षा, स्वच्छता और घरेलू कार्य लड़कियों की विद्यालयी शिक्षा की प्रमुख संरचनात्मक बाधाएँ हैं; उन्हें हटाना व्यक्तियों को दोष देने से अधिक प्रभावी है।"},
  {"id":"cdp-child-development-883","question":"Which of the following statements are consistent with the view that gender is a social construct? I. Gender roles differ from one culture to another. II. Gender roles can change over time within the same society. III. Differences in boys’ and girls’ school abilities are mostly fixed by hormones. IV. Schools can either reproduce or challenge existing gender roles.","options":["I and II only","I, II and IV only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"Variation across cultures and time, and the school’s power to shape roles, follow from gender being socially constructed; III claims biological fixity, which this view rejects.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"निम्नलिखित में से कौन-से कथन इस मत से संगत हैं कि जेंडर एक सामाजिक निर्मिति है? I. जेंडर भूमिकाएँ एक संस्कृति से दूसरी में भिन्न होती हैं। II. जेंडर भूमिकाएँ एक ही समाज में समय के साथ बदल सकती हैं। III. लड़कों और लड़कियों की विद्यालयी क्षमताओं के अंतर अधिकतर हार्मोनों द्वारा निश्चित होते हैं। IV. विद्यालय मौजूदा जेंडर भूमिकाओं को पुनरुत्पादित या चुनौती दे सकते हैं।","optionsHi":["केवल I और II","केवल I, II और IV","केवल II, III और IV","I, II, III और IV"],"explanationHi":"संस्कृतियों और समय के पार भिन्नता, और भूमिकाओं को आकार देने की विद्यालय की शक्ति, जेंडर के सामाजिक रूप से निर्मित होने से निकलती हैं; III जैविक स्थिरता का दावा करता है, जिसे यह मत अस्वीकार करता है।"},
  {"id":"cdp-child-development-884","question":"Which statement best captures a balanced critical view of labelling children (for example, ‘learning disabled’ or ‘slow learner’)?","options":["Labels are always harmful and should never be used for any purpose at all","Labels are always useful, because they explain everything about a child","Labels can unlock support but also stigmatise, so focus on each child’s needs","Labels matter only to doctors and specialists, and have no effect inside classrooms"],"answer":2,"explanation":"Diagnosis can open access to support, yet labels risk stereotyping and self-fulfilling expectations; a needs-based, person-first approach keeps the benefits and limits the harm.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"बच्चों को लेबल देने (जैसे ‘अधिगम-अक्षम’ या ‘मंद अधिगमकर्ता’) के बारे में कौन-सा कथन संतुलित आलोचनात्मक दृष्टिकोण को सबसे अच्छी तरह पकड़ता है?","optionsHi":["लेबल सदैव हानिकारक हैं और उनका किसी भी प्रयोजन के लिए कभी उपयोग नहीं करना चाहिए","लेबल सदैव उपयोगी हैं, क्योंकि वे बच्चे के बारे में सब कुछ समझाते हैं","लेबल सहायता तक पहुँच खोल सकते हैं पर कलंकित भी करते हैं, इसलिए प्रत्येक बच्चे की आवश्यकताओं पर ध्यान दें","लेबल केवल डॉक्टरों और विशेषज्ञों के लिए मायने रखते हैं, और कक्षाओं के भीतर उनका कोई प्रभाव नहीं होता"],"explanationHi":"निदान सहायता तक पहुँच खोल सकता है, फिर भी लेबल रूढ़िबद्धता और स्व-पूर्ति अपेक्षाओं का जोखिम रखते हैं; आवश्यकता-आधारित, व्यक्ति-प्रथम उपागम लाभ रखता है और हानि सीमित करता है।"},
  {"id":"cdp-child-development-885","question":"A school creates permanent ‘A’ and ‘D’ sections in Class 3 based on a test. Two years later the gap between the sections has widened. Which explanation is best supported by research on ability grouping?","options":["The lower section got less demanding teaching and lower expectations","The test correctly identified children whose abilities were fixed from birth","Children in the higher section were naturally gifted and would have progressed anyway","The gap widened only because of differences in their parents’ income levels"],"answer":0,"explanation":"Rigid tracking tends to give lower groups a thinner curriculum and lower expectations, so initial differences grow; this is why NCF 2005 cautions against early, fixed streaming.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक विद्यालय कक्षा 3 में एक परीक्षा के आधार पर स्थायी ‘A’ और ‘D’ अनुभाग बनाता है। दो वर्ष बाद अनुभागों के बीच का अंतर बढ़ गया है। क्षमता-समूहन पर शोध द्वारा कौन-सी व्याख्या सबसे अच्छी तरह समर्थित है?","optionsHi":["निचले अनुभाग को कम माँग वाला शिक्षण और कम अपेक्षाएँ मिलीं","परीक्षा ने उन बच्चों की सही पहचान की जिनकी क्षमताएँ जन्म से निश्चित थीं","उच्च अनुभाग के बच्चे स्वाभाविक रूप से प्रतिभाशाली थे और वैसे भी आगे बढ़ते","अंतर केवल उनके अभिभावकों की आय के स्तरों में भिन्नता के कारण बढ़ा"],"explanationHi":"कठोर ट्रैकिंग प्रायः निचले समूहों को पतला पाठ्यक्रम और कम अपेक्षाएँ देती है, जिससे आरंभिक अंतर बढ़ते हैं; इसीलिए NCF 2005 जल्दी, निश्चित धाराओं के प्रति सावधान करती है।"},
  {"id":"cdp-child-development-886","question":"To raise its Class 10 board results, a school in Kota stops art, games and library periods for Class 9 and 10 and devotes the time to drilling past board papers. This is an example of:","options":["Formative assessment that guides improvement in learning","Mastery learning through repeated practice","Enrichment of the core board syllabus","Curriculum narrowing caused by high-stakes testing"],"answer":3,"explanation":"When results on a high-stakes exam drive decisions, schools tend to ‘teach to the test’ and drop untested areas, shrinking the curriculum, which NCF 2005 criticises.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"अपने कक्षा 10 के बोर्ड परिणाम सुधारने के लिए कोटा का एक विद्यालय कक्षा 9 और 10 के लिए कला, खेल और पुस्तकालय के कालांश बंद कर देता है और उस समय को पिछले बोर्ड प्रश्नपत्रों के अभ्यास में लगाता है। यह किसका उदाहरण है?","optionsHi":["रचनात्मक आकलन जो अधिगम में सुधार का मार्गदर्शन करता है","बार-बार अभ्यास द्वारा निपुणता अधिगम","मूल बोर्ड पाठ्यक्रम का संवर्धन","उच्च-दाँव वाली परीक्षा के कारण पाठ्यचर्या का संकुचन"],"explanationHi":"जब उच्च-दाँव वाली परीक्षा के परिणाम निर्णय चलाते हैं, तो विद्यालय ‘परीक्षा के लिए पढ़ाने’ और अपरीक्षित क्षेत्रों को छोड़ने की प्रवृत्ति रखते हैं, जिससे पाठ्यचर्या सिकुड़ती है, जिसकी NCF 2005 आलोचना करती है।"},
  {"id":"cdp-child-development-887","question":"A teacher tells Shabnam, ‘In July you read 20 words a minute; today you read 35 with fewer mistakes,’ without comparing her to classmates. This kind of assessment is called:","options":["Ipsative assessment","Norm-referenced assessment","Summative assessment","Diagnostic testing"],"answer":0,"explanation":"Ipsative assessment compares a learner with her own earlier performance, focusing on progress rather than rank, which supports motivation, especially for struggling learners.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षिका शबनम से कहती है, ‘जुलाई में तुम एक मिनट में 20 शब्द पढ़ती थीं; आज तुम कम गलतियों के साथ 35 पढ़ती हो,’ बिना उसकी तुलना सहपाठियों से किए। इस प्रकार के आकलन को क्या कहते हैं?","optionsHi":["स्व-संदर्भित (इप्सेटिव) आकलन","मानक-संदर्भित आकलन","योगात्मक आकलन","निदानात्मक परीक्षण"],"explanationHi":"स्व-संदर्भित आकलन अधिगमकर्ता की तुलना उसके अपने पूर्व निष्पादन से करता है, श्रेणी के बजाय प्रगति पर ध्यान देता है, जो अभिप्रेरणा का समर्थन करता है, विशेषकर संघर्ष कर रहे अधिगमकर्ताओं के लिए।"},
  {"id":"cdp-child-development-888","question":"Which feature of the holistic progress card proposed in the National Education Policy 2020 marks a shift away from marks-only reporting?","options":["It reports only the student’s rank in the class, along with the class average","It is filled in only once, at the end of Class 10, for board admission","It records only marks in the five main subjects, leaving out co-scholastic areas","It is 360-degree, with self, peer and teacher assessment across many domains"],"answer":3,"explanation":"NEP 2020 describes a 360-degree, multidimensional progress card covering many domains and including self and peer assessment, instead of marks and ranks alone.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"राष्ट्रीय शिक्षा नीति 2020 में प्रस्तावित समग्र प्रगति-पत्र की कौन-सी विशेषता केवल-अंकों की रिपोर्टिंग से हटकर बदलाव को दर्शाती है?","optionsHi":["यह केवल विद्यार्थी की कक्षा-श्रेणी और कक्षा का औसत रिपोर्ट करता है","इसे केवल एक बार, कक्षा 10 के अंत में, बोर्ड-प्रवेश के लिए भरा जाता है","यह केवल पाँच मुख्य विषयों के अंक दर्ज करता है, सह-शैक्षणिक क्षेत्रों को छोड़कर","यह 360-डिग्री है, जिसमें अनेक क्षेत्रों में स्व-, सहपाठी और शिक्षक आकलन हैं"],"explanationHi":"NEP 2020 एक 360-डिग्री, बहुआयामी प्रगति-पत्र का वर्णन करती है जो अनेक क्षेत्रों को समाहित करता है और केवल अंकों तथा श्रेणियों के बजाय स्व- और सहपाठी आकलन को शामिल करता है।"},
  {"id":"cdp-child-development-889","question":"A Class 6 maths test in a Tamil-medium school consists of long, complex English word problems. Many students who solve the same problems easily when they are given in Tamil fail the test. The main problem with this test is its:","options":["Reliability, because the scores would change if the same test were repeated","Objectivity, because different examiners would mark the answers differently","Validity, as it measures English reading as much as mathematical ability","Practicability, because it takes too long to administer in a single period"],"answer":2,"explanation":"Validity is whether a test measures what it claims to measure. A test can give consistent (reliable) scores and still be invalid if language proficiency, not mathematics, drives those scores.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"तमिल-माध्यम विद्यालय में कक्षा 6 की गणित परीक्षा में अंग्रेज़ी के लंबे, जटिल शब्द-प्रश्न हैं। कई विद्यार्थी जो वही प्रश्न तमिल में दिए जाने पर आसानी से हल कर लेते हैं, परीक्षा में अनुत्तीर्ण हो जाते हैं। इस परीक्षा की मुख्य समस्या उसकी क्या है?","optionsHi":["विश्वसनीयता, क्योंकि यदि वही परीक्षा दोहराई जाए तो अंक बदल जाएँगे","वस्तुनिष्ठता, क्योंकि भिन्न परीक्षक उत्तरों को भिन्न ढंग से जाँचेंगे","वैधता, क्योंकि यह गणितीय योग्यता के साथ-साथ अंग्रेज़ी पठन को भी मापती है","व्यवहार्यता, क्योंकि एक कालांश में इसे संचालित करने में बहुत समय लगता है"],"explanationHi":"वैधता यह है कि परीक्षा वही मापती है या नहीं जो वह दावा करती है। कोई परीक्षा संगत (विश्वसनीय) अंक दे सकती है और फिर भी अवैध हो सकती है यदि गणित नहीं, भाषा-दक्षता उन अंकों को चलाए।"},
  {"id":"cdp-child-development-890","question":"Twelve-year-old Raju sells vegetables in a market and accurately calculates change mentally for customers, yet in school he fails written subtraction sums with the same numbers. This is best interpreted as showing that:","options":["Raju has low intelligence, which only shows up in a school setting","Market calculation is mere habit and does not involve real mathematical thinking","Raju must be getting help or cheating with the change in the market","Knowledge is tied to context, so schools should build on his street maths"],"answer":3,"explanation":"Studies of ‘street mathematics’ show children can be competent in practical settings but fail school formats; the gap reflects context and representation, not lack of ability.","difficulty":"very-hard","source":"CTET Paper 2 · KVS PGT","questionHi":"बारह वर्ष का राजू बाज़ार में सब्ज़ियाँ बेचता है और ग्राहकों के लिए मन ही मन सही ढंग से खुले पैसे की गणना करता है, फिर भी विद्यालय में वही संख्याएँ होने पर लिखित घटाव के प्रश्नों में अनुत्तीर्ण हो जाता है। इसकी सबसे अच्छी व्याख्या यह दर्शाती है कि:","optionsHi":["राजू की बुद्धि कम है, जो केवल विद्यालयी परिवेश में प्रकट होती है","बाज़ार की गणना मात्र आदत है और उसमें वास्तविक गणितीय चिंतन शामिल नहीं है","राजू को बाज़ार में खुले पैसों में सहायता मिल रही होगी या वह नकल कर रहा होगा","ज्ञान संदर्भ से बँधा होता है, इसलिए विद्यालयों को उसकी सड़क-गणित पर निर्माण करना चाहिए"],"explanationHi":"‘सड़क गणित’ के अध्ययन दर्शाते हैं कि बच्चे व्यावहारिक परिवेश में सक्षम हो सकते हैं पर विद्यालयी प्रारूपों में असफल; यह अंतर संदर्भ और निरूपण को दर्शाता है, योग्यता की कमी को नहीं।"},
  {"id":"cdp-child-development-891","question":"In Herman Witkin’s terms, a student who easily picks out a simple shape hidden within a complex figure, prefers to work independently and structures problems on her own is described as having which cognitive style?","options":["Field-dependent","Field-independent","Impulsive","Convergent thinking"],"answer":1,"explanation":"Field-independent learners separate details from the surrounding field (as in the Embedded Figures Test) and impose their own structure; field-dependent learners are influenced more by context and social cues.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"हर्मन विटकिन के शब्दों में, जो विद्यार्थी जटिल आकृति में छिपी सरल आकृति को आसानी से पहचान लेती है, स्वतंत्र रूप से काम करना पसंद करती है और समस्याओं को स्वयं संरचित करती है, उसे कौन-सी संज्ञानात्मक शैली वाला बताया जाता है?","optionsHi":["क्षेत्र-निर्भर","क्षेत्र-स्वतंत्र","आवेगी","अभिसारी चिंतन"],"explanationHi":"क्षेत्र-स्वतंत्र अधिगमकर्ता ब्योरों को उनके आसपास के क्षेत्र से अलग करते हैं (जैसे समाविष्ट आकृति परीक्षण में) और अपनी संरचना थोपते हैं; क्षेत्र-निर्भर अधिगमकर्ता संदर्भ और सामाजिक संकेतों से अधिक प्रभावित होते हैं।"},
  {"id":"cdp-child-development-892","question":"A training module tells teachers to test each child’s ‘learning style’ (visual, auditory or kinaesthetic) and teach every child only in that style. Which response is most consistent with research evidence?","options":["Studies do not show that matching teaching to such styles improves learning","The method is well proven and should be applied in every class from now on","Learning styles are fixed at birth, so matching is the only way children learn","Only kinaesthetic teaching works for primary children, so it should dominate"],"answer":0,"explanation":"Reviews of the evidence find little support for the ‘meshing’ claim that teaching in a child’s preferred style improves outcomes; children have preferences, but varied, content-appropriate teaching helps all.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"एक प्रशिक्षण मॉड्यूल शिक्षकों से कहता है कि प्रत्येक बच्चे की ‘अधिगम शैली’ (दृश्य, श्रव्य या गतिबोधक) की जाँच करें और प्रत्येक बच्चे को केवल उसी शैली में पढ़ाएँ। शोध-प्रमाण से कौन-सी प्रतिक्रिया सबसे अधिक संगत है?","optionsHi":["अध्ययन नहीं दिखाते कि शिक्षण को ऐसी शैलियों से मिलाने से अधिगम सुधरता है","यह विधि भली-भाँति सिद्ध है और अब से प्रत्येक कक्षा में लागू होनी चाहिए","अधिगम शैलियाँ जन्म से निश्चित हैं, इसलिए मिलान ही बच्चों के सीखने का एकमात्र तरीका है","केवल गतिबोधक शिक्षण प्राथमिक बच्चों के लिए काम करता है, इसलिए उसे प्रमुख होना चाहिए"],"explanationHi":"प्रमाणों की समीक्षाएँ इस ‘मेशिंग’ दावे के लिए कम समर्थन पाती हैं कि बच्चे की पसंदीदा शैली में पढ़ाने से परिणाम सुधरते हैं; बच्चों की पसंद होती है, पर विविध, विषय-वस्तु के अनुरूप शिक्षण सभी की सहायता करता है।"},
  {"id":"cdp-child-development-893","question":"In a Pune Class 5 science class, a teacher lets students explain ideas in a mix of Marathi and English and then helps them restate key terms in English. This practice is best supported because:","options":["It lets students avoid learning English altogether in science lessons","Using all their languages helps students make meaning and link new ideas","Mixing languages shows confusion, so it should be allowed only once a week","It reduces the teacher’s workload in explaining difficult science terms"],"answer":1,"explanation":"Drawing on the full linguistic repertoire (code-switching or translanguaging) supports understanding and participation, in line with NCF 2005’s view of multilingualism as a resource.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"पुणे की कक्षा 5 की विज्ञान कक्षा में एक शिक्षिका विद्यार्थियों को मराठी और अंग्रेज़ी के मिश्रण में विचार समझाने देती है और फिर प्रमुख शब्दों को अंग्रेज़ी में पुनः कहने में उनकी सहायता करती है। इस प्रथा का समर्थन सबसे अच्छी तरह इसलिए होता है क्योंकि:","optionsHi":["यह विद्यार्थियों को विज्ञान के पाठों में अंग्रेज़ी सीखने से पूरी तरह बचने देती है","अपनी सभी भाषाओं का प्रयोग विद्यार्थियों को अर्थ बनाने और नए विचारों को जोड़ने में सहायता करता है","भाषाएँ मिलाना भ्रम दर्शाता है, इसलिए इसे सप्ताह में केवल एक बार अनुमत किया जाना चाहिए","यह कठिन विज्ञान शब्दों को समझाने में शिक्षिका का कार्यभार घटाती है"],"explanationHi":"पूरे भाषिक भंडार का उपयोग (कोड-स्विचिंग या ट्रांसलैंग्वेजिंग) समझ और भागीदारी का समर्थन करता है, NCF 2005 के बहुभाषिकता को संसाधन मानने के दृष्टिकोण के अनुरूप।"},
  {"id":"cdp-child-development-894","question":"Four preschoolers sit together; each talks about his own drawing, and no one responds to what the others say, though they appear to be ‘conversing’. Piaget called this:","options":["Inner (silent) speech","Social speech","Collective monologue","Telegraphic speech"],"answer":2,"explanation":"Piaget described collective monologue as a form of egocentric speech in which children talk in each other’s presence without adapting to or answering one another.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"चार पूर्व-विद्यालयी बच्चे साथ बैठे हैं; प्रत्येक अपने चित्र के बारे में बोलता है, और कोई भी दूसरों की बात का उत्तर नहीं देता, यद्यपि वे ‘बातचीत’ करते प्रतीत होते हैं। पियाजे ने इसे क्या कहा?","optionsHi":["आंतरिक (मौन) वाणी","सामाजिक वाणी","सामूहिक एकालाप","तार-शैली वाणी"],"explanationHi":"पियाजे ने सामूहिक एकालाप को अहंकेंद्रित वाणी का एक रूप बताया जिसमें बच्चे एक-दूसरे की उपस्थिति में बोलते हैं बिना एक-दूसरे के अनुसार ढले या उत्तर दिए।"},
  {"id":"cdp-child-development-895","question":"Assertion (A): Piaget held that egocentric speech declines and disappears as children become less egocentric. Reason (R): Vygotsky held that egocentric (private) speech does not disappear but goes underground as inner speech.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both statements correctly describe each thinker’s view, but they are rival accounts; Vygotsky’s position cannot explain Piaget’s, so R is not an explanation of A.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"अभिकथन (A): पियाजे का मत था कि जैसे-जैसे बच्चे कम अहंकेंद्रित होते हैं, अहंकेंद्रित वाणी घटती और समाप्त हो जाती है। कारण (R): वाइगोत्स्की का मत था कि अहंकेंद्रित (निजी) वाणी समाप्त नहीं होती बल्कि आंतरिक वाणी के रूप में भीतर चली जाती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों कथन प्रत्येक विचारक के मत का सही वर्णन करते हैं, पर वे प्रतिद्वंद्वी विवरण हैं; वाइगोत्स्की की स्थिति पियाजे की व्याख्या नहीं कर सकती, इसलिए R, A की व्याख्या नहीं है।"},
  {"id":"cdp-child-development-896","question":"Which of the following is a well-founded criticism of a purely nativist (Chomskyan) account of language development?","options":["It cannot explain why children everywhere learn language at similar ages","It gives too much importance to parents’ reinforcement of correct speech","It underplays social interaction; children rarely learn a language from TV alone","It claims that language is learned only through imitation of adults’ sentences"],"answer":2,"explanation":"Interactionists accept some innate capacity but stress that language grows through responsive conversation; passive exposure without interaction is a poor teacher, a point nativism downplays.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"भाषा-विकास के विशुद्ध नेटिविस्ट (चॉम्स्कीय) विवरण की निम्नलिखित में से कौन-सी एक सुस्थापित आलोचना है?","optionsHi":["यह नहीं समझा सकता कि हर जगह बच्चे समान आयु में भाषा क्यों सीखते हैं","यह माता-पिता द्वारा सही वाणी के पुनर्बलन को बहुत अधिक महत्त्व देता है","यह सामाजिक अंतःक्रिया को कम आँकता है; बच्चे शायद ही कभी केवल टीवी से भाषा सीखते हैं","यह दावा करता है कि भाषा केवल वयस्कों के वाक्यों की नकल से सीखी जाती है"],"explanationHi":"अंतःक्रियावादी कुछ जन्मजात क्षमता स्वीकार करते हैं पर बल देते हैं कि भाषा संवेदनशील संवाद से बढ़ती है; अंतःक्रिया के बिना निष्क्रिय संपर्क एक कमज़ोर शिक्षक है, जिस बात को नेटिविज़्म कम महत्त्व देता है।"},
  {"id":"cdp-child-development-897","question":"Deaf children who have not been exposed to any sign language still classify objects, solve practical problems and often invent their own gesture systems (‘home sign’). This evidence most directly argues against:","options":["The weak version of linguistic relativity about language and thought","Vygotsky’s idea that private speech guides children’s problem-solving","Gardner’s idea of a separate spatial intelligence in children","The claim that thought is impossible without spoken language"],"answer":3,"explanation":"Reasoning and communication without spoken language show that thought does not wholly depend on it, contradicting strong linguistic determinism; they are compatible with weaker relativity claims.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"जिन बधिर बच्चों को किसी सांकेतिक भाषा का संपर्क नहीं मिला, वे फिर भी वस्तुओं का वर्गीकरण करते हैं, व्यावहारिक समस्याएँ सुलझाते हैं और प्रायः अपनी भाव-भंगिमा प्रणालियाँ (‘होम साइन’) गढ़ लेते हैं। यह प्रमाण सबसे सीधे किसके विरुद्ध तर्क देता है?","optionsHi":["भाषा और चिंतन के बारे में भाषिक सापेक्षता के दुर्बल रूप के","वाइगोत्स्की के इस विचार के कि निजी वाणी बच्चों की समस्या-समाधान का मार्गदर्शन करती है","बच्चों में पृथक स्थानिक बुद्धि के गार्डनर के विचार के","इस दावे के कि बोली गई भाषा के बिना चिंतन असंभव है"],"explanationHi":"बोली गई भाषा के बिना तर्क और संप्रेषण दिखाते हैं कि चिंतन पूरी तरह उस पर निर्भर नहीं है, जो सशक्त भाषिक नियतिवाद का खंडन करता है; वे दुर्बल सापेक्षता के दावों के अनुकूल हैं।"},
  {"id":"cdp-child-development-898","question":"In Ainsworth’s Strange Situation, a one-year-old explores the room freely while his mother is present, gets upset when she leaves, and on her return quickly goes to her, is comforted and returns to play. His attachment is classified as:","options":["Insecure-avoidant","Insecure-resistant (ambivalent)","Disorganised","Secure"],"answer":3,"explanation":"Using the mother as a secure base, mild-to-moderate distress at separation and easy comfort at reunion define secure attachment. Distress alone does not mean insecurity.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एन्सवर्थ की स्ट्रेंज सिचुएशन में, एक वर्ष का बच्चा माँ की उपस्थिति में कमरे को स्वतंत्र रूप से टटोलता है, माँ के जाने पर परेशान हो जाता है, और उसके लौटने पर शीघ्र उसके पास जाता है, सांत्वना पाता है और खेल में लौट जाता है। उसका लगाव किस श्रेणी में आता है?","optionsHi":["असुरक्षित-परिहारी","असुरक्षित-प्रतिरोधी (द्विभावी)","अव्यवस्थित","सुरक्षित"],"explanationHi":"माँ को सुरक्षित आधार के रूप में प्रयोग करना, वियोग पर हल्का-से-मध्यम कष्ट और पुनर्मिलन पर आसान सांत्वना सुरक्षित लगाव को परिभाषित करते हैं। अकेला कष्ट असुरक्षा नहीं दर्शाता।"},
  {"id":"cdp-child-development-899","question":"In the Strange Situation, an infant shows little distress when the mother leaves and actively ignores or turns away from her when she returns, playing with toys instead. A teacher-trainee concludes the baby is ‘very independent and securely attached’. What is the error?","options":["It is insecure-avoidant; indifference at reunion signals insecure attachment","There is no error; lack of distress shows a secure and confident attachment","The pattern is disorganised, as the child is confused about the mother","The pattern is insecure-resistant, as the child resists the mother’s return"],"answer":0,"explanation":"Avoidant infants suppress attachment behaviour and avoid the caregiver at reunion, often after repeated rejection of their bids for comfort; it is not healthy independence.","difficulty":"very-hard","source":"CTET Paper 1 · State TET","questionHi":"स्ट्रेंज सिचुएशन में, कोई शिशु माँ के जाने पर कम कष्ट दिखाता है और उसके लौटने पर उसे सक्रिय रूप से अनदेखा करता है या उससे मुँह फेर लेता है, बजाय इसके खिलौनों से खेलता है। एक शिक्षक-प्रशिक्षु निष्कर्ष निकालता है कि बच्चा ‘बहुत स्वतंत्र और सुरक्षित रूप से जुड़ा हुआ’ है। त्रुटि क्या है?","optionsHi":["यह असुरक्षित-परिहारी है; पुनर्मिलन पर उदासीनता असुरक्षित लगाव का संकेत है","कोई त्रुटि नहीं; कष्ट का अभाव सुरक्षित और आत्मविश्वासी लगाव दर्शाता है","यह प्रतिरूप अव्यवस्थित है, क्योंकि बच्चा माँ के बारे में भ्रमित है","यह प्रतिरूप असुरक्षित-प्रतिरोधी है, क्योंकि बच्चा माँ के लौटने का प्रतिरोध करता है"],"explanationHi":"परिहारी शिशु लगाव-व्यवहार को दबाते हैं और पुनर्मिलन पर देखभालकर्ता से बचते हैं, प्रायः सांत्वना की अपनी माँगों के बार-बार अस्वीकार होने के बाद; यह स्वस्थ स्वतंत्रता नहीं है।"},
  {"id":"cdp-child-development-900","question":"An infant clings to the mother and barely explores, is extremely upset when she leaves, and on her return alternates between clinging to her and angrily pushing her away, staying hard to comfort. This is:","options":["Secure attachment","Insecure-avoidant attachment","Insecure-resistant attachment","Disorganised/disoriented attachment"],"answer":2,"explanation":"Ambivalence at reunion (seeking contact yet resisting it with anger) together with poor exploration marks resistant attachment, often linked to inconsistent caregiving.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिशु माँ से चिपका रहता है और मुश्किल से टटोलता है, उसके जाने पर अत्यंत परेशान होता है, और उसके लौटने पर उससे चिपकने और क्रोध से उसे दूर धकेलने के बीच बदलता रहता है, सांत्वना पाना कठिन बना रहता है। यह है:","optionsHi":["सुरक्षित लगाव","असुरक्षित-परिहारी लगाव","असुरक्षित-प्रतिरोधी लगाव","अव्यवस्थित/दिशाहीन लगाव"],"explanationHi":"पुनर्मिलन पर द्विभाविता (संपर्क खोजना पर क्रोध से उसका प्रतिरोध करना) और कम टटोलना प्रतिरोधी लगाव का चिह्न है, जो प्रायः असंगत देखभाल से जुड़ा होता है।"},
  {"id":"cdp-child-development-901","question":"At reunion in the Strange Situation, a toddler approaches the mother with her face turned away, then freezes with a dazed expression. Which pattern did Main and Solomon describe that fits this?","options":["Secure","Disorganised","Insecure-avoidant","Insecure-resistant"],"answer":1,"explanation":"Contradictory, confused behaviours such as approaching while looking away or freezing mark disorganised attachment, added later to Ainsworth’s three patterns and often linked to frightening care.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"स्ट्रेंज सिचुएशन में पुनर्मिलन पर एक नन्ही बच्ची मुँह फेरकर माँ के पास आती है, फिर भौचक्के भाव के साथ जड़ हो जाती है। मेन और सॉलोमन ने कौन-सा प्रतिरूप वर्णित किया जो इससे मेल खाता है?","optionsHi":["सुरक्षित","अव्यवस्थित","असुरक्षित-परिहारी","असुरक्षित-प्रतिरोधी"],"explanationHi":"विरोधाभासी, भ्रमित व्यवहार, जैसे दूसरी ओर देखते हुए पास आना या जड़ हो जाना, अव्यवस्थित लगाव के चिह्न हैं, जिसे बाद में एन्सवर्थ के तीन प्रतिरूपों में जोड़ा गया और जो प्रायः डरावनी देखभाल से जुड़ा होता है।"},
  {"id":"cdp-child-development-902","question":"In Harlow’s experiments, infant monkeys spent most of their time clinging to a soft cloth ‘mother’ that gave no milk, going to a wire ‘mother’ only to feed. What did this mainly show?","options":["Attachment develops mainly because the mother is the source of food","Monkeys cannot form real attachments to any mother figure at all","Contact comfort matters more than feeding in forming attachment","Wire mothers are better for building early independence"],"answer":2,"explanation":"Harlow’s findings undermined the ‘cupboard love’ view that attachment arises from being fed, showing the importance of contact comfort and security.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"हार्लो के प्रयोगों में शिशु बंदर अपना अधिकांश समय एक मुलायम कपड़े की ‘माँ’ से चिपके रहे जो दूध नहीं देती थी, और तार की ‘माँ’ के पास केवल दूध पीने जाते थे। इसने मुख्यतः क्या दिखाया?","optionsHi":["लगाव मुख्यतः इसलिए विकसित होता है क्योंकि माँ भोजन का स्रोत है","बंदर किसी भी माँ-समान आकृति से वास्तविक लगाव नहीं बना सकते","लगाव बनाने में स्पर्श-सुख भोजन कराने से अधिक महत्त्वपूर्ण है","तार की माँएँ प्रारंभिक स्वतंत्रता बनाने के लिए बेहतर हैं"],"explanationHi":"हार्लो के निष्कर्षों ने इस ‘अलमारी-प्रेम’ दृष्टि को कमज़ोर किया कि लगाव भोजन मिलने से उपजता है, और स्पर्श-सुख तथा सुरक्षा का महत्त्व दिखाया।"},
  {"id":"cdp-child-development-903","question":"Bowlby proposed that through early relationships a child builds an ‘internal working model’. In a Class 3 classroom, this concept would best explain why:","options":["A child who found adults dependable expects his new teacher to help him","A child learns multiplication tables quickly through daily repetition in class","A child grows noticeably taller and stronger during the school year","A child learns to write from left to right in Hindi and English"],"answer":0,"explanation":"The internal working model is a mental template of self and others drawn from early care; it shapes expectations of later relationships, e.g. whether teachers can be trusted.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"बॉल्बी ने प्रस्ताव रखा कि आरंभिक संबंधों के माध्यम से बच्चा एक ‘आंतरिक कार्यकारी मॉडल’ बनाता है। कक्षा 3 में यह अवधारणा किसे सबसे अच्छी तरह समझाएगी?","optionsHi":["वह बच्चा जिसने वयस्कों को भरोसेमंद पाया, अपेक्षा करता है कि उसकी नई शिक्षिका उसकी सहायता करेगी","वह बच्चा जो कक्षा में दैनिक दोहराव से पहाड़े शीघ्र सीख लेता है","वह बच्चा जो विद्यालयी वर्ष में उल्लेखनीय रूप से लंबा और सशक्त हो जाता है","वह बच्चा जो हिंदी और अंग्रेज़ी में बाएँ से दाएँ लिखना सीखता है"],"explanationHi":"आंतरिक कार्यकारी मॉडल आरंभिक देखभाल से बनी स्वयं और दूसरों की एक मानसिक रूपरेखा है; वह बाद के संबंधों की अपेक्षाओं को आकार देती है, जैसे यह कि शिक्षकों पर भरोसा किया जा सकता है या नहीं।"},
  {"id":"cdp-child-development-904","question":"A study of Scottish infants by Schaffer and Emerson found that many babies formed attachments to several people, and that the strongest attachment was often not to the person who fed and bathed them most. What best predicted the strongest attachment?","options":["Who spent the most hours each day with the baby","Who fed and bathed the baby most often","Who was the baby’s biological mother","Who responded most sensitively to the baby"],"answer":3,"explanation":"Sensitive responsiveness and interaction, not the amount of physical care or time, predicted the main attachment figure; this also shows multiple attachments are normal, as in Indian joint families.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"शेफ़र और एमर्सन के स्कॉटलैंड के शिशुओं के अध्ययन ने पाया कि कई शिशुओं ने अनेक लोगों से लगाव बनाया, और सबसे प्रबल लगाव प्रायः उस व्यक्ति से नहीं था जो उन्हें सबसे अधिक खिलाता और नहलाता था। सबसे प्रबल लगाव का सबसे अच्छा पूर्वानुमान क्या करता था?","optionsHi":["किसने प्रतिदिन शिशु के साथ सबसे अधिक घंटे बिताए","किसने शिशु को सबसे अधिक बार खिलाया और नहलाया","कौन शिशु की जैविक माँ थी","किसने शिशु को सबसे संवेदनशीलता से प्रतिक्रिया दी"],"explanationHi":"संवेदनशील अनुक्रियाशीलता और अंतःक्रिया ने, न कि शारीरिक देखभाल की मात्रा या समय ने, मुख्य लगाव-व्यक्ति का पूर्वानुमान किया; यह यह भी दिखाता है कि अनेक लगाव सामान्य हैं, जैसे भारतीय संयुक्त परिवारों में।"},
  {"id":"cdp-child-development-905","question":"An eight-month-old who happily went to anyone a few months ago now cries and clings to her mother when a new neighbour tries to pick her up. What does this most likely indicate?","options":["A developmental disorder needing professional help","Spoiling caused by too much affection at home","Normal stranger anxiety after a specific attachment","Insecure-avoidant attachment to the mother"],"answer":2,"explanation":"Wariness of strangers appearing in the second half of the first year accompanies the formation of clear-cut attachments to particular people; it is a normal developmental sign.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"आठ महीने की एक शिशु, जो कुछ महीने पहले किसी के भी पास खुशी से चली जाती थी, अब रोती और माँ से चिपक जाती है जब कोई नया पड़ोसी उसे उठाने की कोशिश करता है। यह सबसे संभवतः क्या दर्शाता है?","optionsHi":["विकासात्मक विकार जिसके लिए पेशेवर सहायता चाहिए","घर पर अत्यधिक स्नेह से बिगाड़","किसी विशिष्ट लगाव के बाद सामान्य अजनबी-चिंता","माँ के प्रति असुरक्षित-परिहारी लगाव"],"explanationHi":"पहले वर्ष के उत्तरार्ध में प्रकट होने वाली अजनबियों के प्रति सतर्कता विशिष्ट लोगों से स्पष्ट लगाव बनने के साथ आती है; यह एक सामान्य विकासात्मक संकेत है।"},
  {"id":"cdp-child-development-906","question":"Goslings followed the first moving object they saw after hatching, even Konrad Lorenz himself, and this happened only in a short window after hatching. Which concept does this most directly illustrate?","options":["Imprinting during a critical period","Operant conditioning by food rewards","Secure base behaviour","Internal working model"],"answer":0,"explanation":"Imprinting is rapid, early-formed following that occurs during a brief critical period; Bowlby drew on such ethological work, though human attachment develops more gradually.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"हंस के बच्चे अंडे से निकलने के बाद देखी पहली चलती वस्तु के पीछे चले, स्वयं कोनराड लोरेंज़ के भी, और यह केवल अंडे से निकलने के बाद की एक छोटी अवधि में हुआ। यह किस संप्रत्यय को सबसे सीधे दर्शाता है?","optionsHi":["क्रांतिक अवधि में छापन (इम्प्रिंटिंग)","भोजन के पुरस्कार द्वारा संक्रियात्मक अनुबंधन","सुरक्षित आधार व्यवहार","आंतरिक कार्यकारी मॉडल"],"explanationHi":"छापन एक संक्षिप्त क्रांतिक अवधि के दौरान होने वाला त्वरित, प्रारंभ में बना अनुसरण है; बॉल्बी ने ऐसे नीतिशास्त्रीय कार्य का सहारा लिया, यद्यपि मानव लगाव अधिक धीरे-धीरे विकसित होता है।"},
  {"id":"cdp-child-development-907","question":"Assertion (A): A securely attached toddler explores a new playroom more confidently when his mother is present. Reason (R): A secure attachment figure acts as a safe base from which the child explores and to which he returns when stressed.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The secure-base concept (Ainsworth) explains why secure children explore more when the caregiver is nearby; security supports, not reduces, exploration.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"अभिकथन (A): एक सुरक्षित रूप से जुड़ा नन्हा बच्चा नए खेल-कक्ष को तब अधिक आत्मविश्वास से टटोलता है जब उसकी माँ उपस्थित हो। कारण (R): सुरक्षित लगाव-व्यक्ति एक सुरक्षित आधार का काम करता है जहाँ से बच्चा टटोलता है और तनाव में जहाँ वह लौटता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"सुरक्षित-आधार की अवधारणा (एन्सवर्थ) समझाती है कि देखभालकर्ता के निकट होने पर सुरक्षित बच्चे अधिक अन्वेषण क्यों करते हैं; सुरक्षा अन्वेषण को घटाती नहीं, सहारा देती है।"},
  {"id":"cdp-child-development-908","question":"A Class 1 child cries and clings to his father at the school gate for the first two weeks. Which response from the teacher fits what attachment research suggests?","options":["Tell the father to slip away without saying goodbye so the child doesn’t notice","Welcome him warmly, keep a steady routine, and let the father say a brief goodbye","Point out to the class that he is crying, so that embarrassment makes him stop","Send the child home and readmit him only when he is ready to come in on his own"],"answer":1,"explanation":"Separation distress is normal; a consistent, warm teacher and predictable routines provide a new secure base, while sneaking away or shaming increases insecurity.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 का एक बच्चा पहले दो सप्ताह विद्यालय के फाटक पर रोता है और अपने पिता से चिपकता है। लगाव-शोध जो सुझाता है उसके अनुरूप शिक्षक की कौन-सी प्रतिक्रिया है?","optionsHi":["पिता से कहना कि बिना अलविदा कहे चुपके से निकल जाएँ ताकि बच्चे को पता न चले","उसका गर्मजोशी से स्वागत करना, स्थिर दिनचर्या रखना और पिता को संक्षिप्त अलविदा कहने देना","कक्षा के सामने बताना कि वह रो रहा है, ताकि शर्मिंदगी से वह रुक जाए","बच्चे को घर भेज देना और केवल तभी दोबारा प्रवेश देना जब वह स्वयं भीतर आने को तैयार हो"],"explanationHi":"वियोग का कष्ट सामान्य है; एक सुसंगत, स्नेही शिक्षक और पूर्वानुमेय दिनचर्याएँ नया सुरक्षित आधार देती हैं, जबकि चुपके से निकल जाना या शर्मिंदा करना असुरक्षा बढ़ाता है।"},
  {"id":"cdp-child-development-909","question":"Which of these statements about attachment are correct? I. Infants can form attachments to several caregivers, not only the mother. II. Attachment forms mainly because the caregiver satisfies hunger. III. Early attachment quality can influence later relationships. IV. Insecure attachment in infancy fixes a child’s fate for life, whatever happens later.","options":["I and II only","I and III only","II and IV only","I, III and IV only"],"answer":1,"explanation":"Multiple attachments are common (I) and early bonds shape later relationships (III). Feeding is not the main cause (II false, as Harlow showed), and later sensitive care can change outcomes (IV false).","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"लगाव के बारे में इनमें से कौन-से कथन सही हैं? I. शिशु केवल माँ से नहीं, कई देखभालकर्ताओं से लगाव बना सकते हैं। II. लगाव मुख्यतः इसलिए बनता है क्योंकि देखभालकर्ता भूख मिटाता है। III. आरंभिक लगाव की गुणवत्ता बाद के संबंधों को प्रभावित कर सकती है। IV. शैशव में असुरक्षित लगाव बच्चे का भाग्य जीवन भर के लिए तय कर देता है, बाद में कुछ भी हो।","optionsHi":["केवल I और II","केवल I और III","केवल II और IV","केवल I, III और IV"],"explanationHi":"अनेक लगाव सामान्य हैं (I) और आरंभिक बंधन बाद के संबंधों को आकार देते हैं (III)। भोजन मुख्य कारण नहीं है (II असत्य, जैसा हार्लो ने दिखाया), और बाद की संवेदनशील देखभाल परिणाम बदल सकती है (IV असत्य)।"},
  {"id":"cdp-child-development-910","question":"Children adopted from severely deprived orphanages into loving families showed substantial recovery, most completely in those adopted early. What does this most strongly suggest?","options":["Early deprivation has no lasting effect whatsoever on development","Development is fully fixed in the first year and cannot be changed","Only heredity matters for how well the children recovered","Early experience matters, yet development remains plastic"],"answer":3,"explanation":"Large adoption studies show early deprivation can harm development, yet good later care brings much recovery, more so when early; this supports plasticity along with sensitive periods.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"गंभीर रूप से वंचित अनाथालयों से स्नेही परिवारों में गोद लिए गए बच्चों ने पर्याप्त सुधार दिखाया, सबसे पूर्ण उनमें जिन्हें जल्दी गोद लिया गया। यह सबसे दृढ़ता से क्या सुझाता है?","optionsHi":["आरंभिक वंचन का विकास पर कोई स्थायी प्रभाव बिल्कुल नहीं पड़ता","विकास पहले वर्ष में पूरी तरह निश्चित हो जाता है और बदला नहीं जा सकता","बच्चों के सुधार में केवल आनुवंशिकता मायने रखती है","आरंभिक अनुभव मायने रखता है, फिर भी विकास सुनम्य बना रहता है"],"explanationHi":"बड़े गोद-लेने के अध्ययन दिखाते हैं कि आरंभिक वंचन विकास को हानि पहुँचा सकता है, फिर भी बाद की अच्छी देखभाल बहुत सुधार लाती है, जल्दी हो तो अधिक; यह संवेदनशील अवधियों के साथ सुनम्यता का समर्थन करता है।"},
  {"id":"cdp-child-development-911","question":"The district education office decides to cut the library budget of a village school, and the Class 5 children there no longer get new storybooks. The children have never been to that office. In Bronfenbrenner’s model, the office is part of their:","options":["Microsystem","Mesosystem","Exosystem","Macrosystem"],"answer":2,"explanation":"The exosystem includes settings the child does not take part in, such as an administrative office, which affect the child indirectly through settings like the school. It is not the macrosystem, which is broad culture, values and laws.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"ज़िला शिक्षा कार्यालय एक ग्रामीण विद्यालय का पुस्तकालय बजट घटा देता है, और वहाँ कक्षा 5 के बच्चों को अब नई कहानी की किताबें नहीं मिलतीं। बच्चे उस कार्यालय में कभी नहीं गए। ब्रॉनफ़ेनब्रेनर के मॉडल में कार्यालय उनके किसका भाग है?","optionsHi":["सूक्ष्म-तंत्र (माइक्रोसिस्टम)","मध्य-तंत्र (मेसोसिस्टम)","बाह्य-तंत्र (एक्ज़ोसिस्टम)","वृहत-तंत्र (मैक्रोसिस्टम)"],"explanationHi":"बाह्य-तंत्र में वे परिवेश आते हैं जिनमें बच्चा भाग नहीं लेता, जैसे कोई प्रशासनिक कार्यालय, जो विद्यालय जैसे परिवेशों के माध्यम से बच्चे को अप्रत्यक्ष रूप से प्रभावित करते हैं। यह वृहत-तंत्र नहीं है, जो व्यापक संस्कृति, मूल्य और कानून है।"},
  {"id":"cdp-child-development-912","question":"Mrs. Kaur, a Class 2 teacher, holds regular friendly meetings with parents, and they agree on a common way of helping children read at home and at school. Bronfenbrenner would describe this as strengthening the:","options":["Microsystem","Mesosystem","Exosystem","Chronosystem"],"answer":1,"explanation":"The mesosystem is the set of links between the child’s microsystems, here home and school; strong, consistent links support development.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 की शिक्षिका श्रीमती कौर अभिभावकों के साथ नियमित मित्रवत बैठकें करती हैं, और वे घर तथा विद्यालय में बच्चों को पढ़ने में सहायता करने के साझा तरीके पर सहमत होते हैं। ब्रॉनफ़ेनब्रेनर इसे किसे सुदृढ़ करना कहते?","optionsHi":["सूक्ष्म-तंत्र","मध्य-तंत्र","बाह्य-तंत्र","कालिक-तंत्र (क्रोनोसिस्टम)"],"explanationHi":"मध्य-तंत्र बच्चे के सूक्ष्म-तंत्रों के बीच के संबंधों का समूह है, यहाँ घर और विद्यालय; मज़बूत, सुसंगत संबंध विकास का समर्थन करते हैं।"},
  {"id":"cdp-child-development-913","question":"Widely shared cultural beliefs in a society, for example that girls’ education matters less than boys’, shape how families and schools treat children. In Bronfenbrenner’s model these beliefs belong to the:","options":["Macrosystem","Exosystem","Mesosystem","Microsystem"],"answer":0,"explanation":"The macrosystem is the overarching pattern of culture, values, laws and ideology that shapes all the inner systems.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"किसी समाज में व्यापक रूप से साझा सांस्कृतिक विश्वास, उदाहरण के लिए कि लड़कियों की शिक्षा लड़कों की शिक्षा से कम महत्त्वपूर्ण है, परिवार और विद्यालय बच्चों के साथ कैसे व्यवहार करते हैं इसे आकार देते हैं। ब्रॉनफ़ेनब्रेनर के मॉडल में ये विश्वास किसके अंतर्गत आते हैं?","optionsHi":["वृहत-तंत्र","बाह्य-तंत्र","मध्य-तंत्र","सूक्ष्म-तंत्र"],"explanationHi":"वृहत-तंत्र संस्कृति, मूल्यों, कानूनों और विचारधारा का व्यापक प्रतिरूप है जो सभी भीतरी तंत्रों को आकार देता है।"},
  {"id":"cdp-child-development-914","question":"A Class 6 child’s parents divorce when he is eleven; the effects on him differ from what they would have been at age three. Bronfenbrenner captured the importance of such timing and change over time in the:","options":["Exosystem","Macrosystem","Mesosystem","Chronosystem"],"answer":3,"explanation":"The chronosystem adds the dimension of time: life transitions and historical events, and how their effects depend on when they occur in the child’s life.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 के एक बच्चे के माता-पिता का तलाक तब होता है जब वह ग्यारह वर्ष का है; उस पर प्रभाव उससे भिन्न हैं जो तीन वर्ष की आयु में होते। ब्रॉनफ़ेनब्रेनर ने ऐसे समय और समय के साथ परिवर्तन के महत्त्व को किसमें पकड़ा?","optionsHi":["बाह्य-तंत्र","वृहत-तंत्र","मध्य-तंत्र","कालिक-तंत्र"],"explanationHi":"कालिक-तंत्र समय का आयाम जोड़ता है: जीवन-संक्रमण और ऐतिहासिक घटनाएँ, और यह कि उनके प्रभाव इस पर निर्भर करते हैं कि वे बच्चे के जीवन में कब घटित होती हैं।"},
  {"id":"cdp-child-development-915","question":"Match the following for a Class 4 child in Bronfenbrenner’s model: 1. His classroom and teacher 2. Meetings between his parents and teacher 3. His father’s office transfer policy 4. National laws such as the RTE Act; a. Exosystem b. Microsystem c. Macrosystem d. Mesosystem","options":["1-b, 2-a, 3-d, 4-c","1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-a, 4-c","1-b, 2-d, 3-c, 4-a"],"answer":2,"explanation":"The classroom is a microsystem, the parent–teacher link a mesosystem, a parent’s workplace policy an exosystem, and broad laws and cultural values the macrosystem.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"ब्रॉनफ़ेनब्रेनर के मॉडल में कक्षा 4 के बच्चे के लिए निम्नलिखित का मिलान कीजिए: 1. उसकी कक्षा और शिक्षक 2. उसके माता-पिता और शिक्षक की बैठकें 3. उसके पिता की कार्यालय स्थानांतरण नीति 4. RTE अधिनियम जैसे राष्ट्रीय कानून; a. बाह्य-तंत्र b. सूक्ष्म-तंत्र c. वृहत-तंत्र d. मध्य-तंत्र","optionsHi":["1-b, 2-a, 3-d, 4-c","1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-a, 4-c","1-b, 2-d, 3-c, 4-a"],"explanationHi":"कक्षा सूक्ष्म-तंत्र है, अभिभावक–शिक्षक संपर्क मध्य-तंत्र, किसी अभिभावक के कार्यस्थल की नीति बाह्य-तंत्र, और व्यापक कानून तथा सांस्कृतिक मूल्य वृहत-तंत्र।"},
  {"id":"cdp-child-development-916","question":"In Bronfenbrenner’s view, a temperamentally irritable child who makes her parents more impatient, whose impatience in turn makes her more irritable, illustrates that:","options":["Microsystem influences are two-way: the child shapes others as they shape her","The child is a passive receiver of whatever forces the environment applies","Only the macrosystem of culture and values really affects development","Heredity has no role in development, since the parents create the irritability"],"answer":0,"explanation":"Bronfenbrenner stressed reciprocal, two-way interactions within microsystems; the child’s own characteristics shape how others respond.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"ब्रॉनफ़ेनब्रेनर के मत में, एक स्वभाव से चिड़चिड़ी बच्ची जो अपने माता-पिता को अधिक अधीर बनाती है, जिनकी अधीरता बदले में उसे और चिड़चिड़ा बनाती है, क्या दर्शाती है?","optionsHi":["सूक्ष्म-तंत्र के प्रभाव द्विपक्षीय हैं: बच्चा दूसरों को वैसे ही आकार देता है जैसे वे उसे","बच्चा पर्यावरण द्वारा लगाए गए किसी भी बल का निष्क्रिय ग्राहक है","विकास को वास्तव में केवल संस्कृति और मूल्यों का वृहत-तंत्र प्रभावित करता है","आनुवंशिकता की विकास में कोई भूमिका नहीं, क्योंकि माता-पिता चिड़चिड़ापन पैदा करते हैं"],"explanationHi":"ब्रॉनफ़ेनब्रेनर ने सूक्ष्म-तंत्रों के भीतर पारस्परिक, द्विपक्षीय अंतःक्रियाओं पर बल दिया; बच्चे की अपनी विशेषताएँ आकार देती हैं कि दूसरे कैसे प्रतिक्रिया करते हैं।"},
  {"id":"cdp-child-development-917","question":"Assertion (A): In Bronfenbrenner’s model, the exosystem can influence a child even though the child never participates in it directly. Reason (R): The exosystem acts on the child through its effects on people and settings in the child’s microsystem.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Decisions in a parent’s workplace or the local school board reach the child indirectly through the parents or teachers; R gives the mechanism behind A.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"अभिकथन (A): ब्रॉनफ़ेनब्रेनर के मॉडल में, बाह्य-तंत्र बच्चे को प्रभावित कर सकता है, भले ही बच्चा उसमें प्रत्यक्ष रूप से कभी भाग न ले। कारण (R): बाह्य-तंत्र बच्चे के सूक्ष्म-तंत्र के लोगों और परिवेशों पर अपने प्रभावों के माध्यम से बच्चे पर कार्य करता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"किसी अभिभावक के कार्यस्थल या स्थानीय विद्यालय बोर्ड के निर्णय अभिभावकों या शिक्षकों के माध्यम से बच्चे तक अप्रत्यक्ष रूप से पहुँचते हैं; R, A के पीछे की क्रियाविधि देता है।"},
  {"id":"cdp-child-development-918","question":"A student’s parents shout at him over homework while his teacher gently encourages the same work; the two never communicate and give him conflicting messages. Which Bronfenbrenner layer is weak, and what would most help?","options":["The microsystem; the teacher should counsel the boy alone so he copes with both styles","The mesosystem; set up regular parent–teacher talks to agree on shared goals for him","The exosystem; link the family to a community counsellor who can ease stress at home","The chronosystem; give him time, as conflicting messages fade as children mature"],"answer":1,"explanation":"The problem lies in the missing link between two microsystems (home and school), which is the mesosystem, so parent–teacher dialogue fixes it directly. Counselling the boy alone is tempting but leaves the two settings still pulling against each other.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक विद्यार्थी के माता-पिता गृहकार्य पर उस पर चिल्लाते हैं जबकि उसकी शिक्षिका उसी कार्य के लिए उसे कोमलता से प्रोत्साहित करती है; दोनों कभी संवाद नहीं करते और उसे विरोधी संदेश देते हैं। ब्रॉनफ़ेनब्रेनर की कौन-सी परत कमज़ोर है, और क्या सबसे अधिक सहायक होगा?","optionsHi":["सूक्ष्म-तंत्र; शिक्षिका को लड़के को अकेले परामर्श देना चाहिए ताकि वह दोनों शैलियों का सामना कर सके","मध्य-तंत्र; उसके लिए साझा लक्ष्य तय करने हेतु नियमित अभिभावक–शिक्षक वार्ताएँ स्थापित करना","बाह्य-तंत्र; परिवार को किसी सामुदायिक परामर्शदाता से जोड़ना जो घर पर तनाव कम कर सके","कालिक-तंत्र; उसे समय देना, क्योंकि जैसे-जैसे बच्चे परिपक्व होते हैं विरोधी संदेश धुँधले पड़ जाते हैं"],"explanationHi":"समस्या दो सूक्ष्म-तंत्रों (घर और विद्यालय) के बीच के संबंध के अभाव में है, जो मध्य-तंत्र है, इसलिए अभिभावक–शिक्षक संवाद उसे सीधे ठीक करता है। लड़के को अकेले परामर्श देना आकर्षक है पर दोनों परिवेश फिर भी एक-दूसरे के विरुद्ध खिंचते रहेंगे।"},
  {"id":"cdp-child-development-919","question":"Which statement about Bronfenbrenner’s ecological systems theory is INCORRECT?","options":["The child is at the centre of nested systems that interact with one another","Development is affected by settings in which the child does not directly take part","The theory considers only the immediate family as relevant to development","Time and historical change are part of the model through the chronosystem"],"answer":2,"explanation":"Bronfenbrenner’s whole point is that development is shaped by many interacting layers, from family and school to culture and history, not by the immediate family alone.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"ब्रॉनफ़ेनब्रेनर के पारिस्थितिक तंत्र सिद्धांत के बारे में कौन-सा कथन गलत है?","optionsHi":["बच्चा उन अंतर्निहित तंत्रों के केंद्र में है जो एक-दूसरे के साथ अंतःक्रिया करते हैं","विकास उन परिवेशों से प्रभावित होता है जिनमें बच्चा प्रत्यक्ष रूप से भाग नहीं लेता","सिद्धांत विकास के लिए केवल निकट परिवार को प्रासंगिक मानता है","समय और ऐतिहासिक परिवर्तन कालिक-तंत्र के माध्यम से मॉडल का भाग हैं"],"explanationHi":"ब्रॉनफ़ेनब्रेनर का पूरा मुद्दा ही यह है कि विकास परिवार और विद्यालय से लेकर संस्कृति और इतिहास तक अनेक अंतःक्रियात्मक परतों से आकार पाता है, केवल निकट परिवार से नहीं।"},
  {"id":"cdp-child-development-920","question":"A child grows up during the Covid-19 school closures, when classes moved online for long periods, while his elder brother had gone to school normally at the same age. Which Bronfenbrenner layer best explains how this historical event changed his development compared with his brother’s?","options":["Mesosystem","Exosystem","Microsystem","Chronosystem"],"answer":3,"explanation":"The chronosystem includes socio-historical events and their timing in a child’s life, so the same family can raise children whose development differs because they grew up at different times.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक बच्चा Covid-19 के दौरान विद्यालय-बंदी में बड़ा होता है, जब कक्षाएँ लंबी अवधियों के लिए ऑनलाइन हो गईं, जबकि उसका बड़ा भाई उसी आयु में सामान्य रूप से विद्यालय गया था। ब्रॉनफ़ेनब्रेनर की कौन-सी परत सबसे अच्छी तरह समझाती है कि इस ऐतिहासिक घटना ने उसके भाई की तुलना में उसके विकास को कैसे बदला?","optionsHi":["मध्य-तंत्र","बाह्य-तंत्र","सूक्ष्म-तंत्र","कालिक-तंत्र"],"explanationHi":"कालिक-तंत्र में सामाजिक-ऐतिहासिक घटनाएँ और बच्चे के जीवन में उनका समय शामिल है, इसलिए एक ही परिवार ऐसे बच्चे पाल सकता है जिनका विकास इसलिए भिन्न होता है क्योंकि वे अलग समय में बड़े हुए।"},
  {"id":"cdp-child-development-921","question":"A newly-joined Class 1 child keeps checking that his teacher is nearby while he explores the activity corner, and runs to her when a loud noise startles him. In attachment terms, the teacher is acting as:","options":["A secure base and safe haven","A source of stranger anxiety","An exosystem influence","A model for vicarious reinforcement"],"answer":0,"explanation":"He explores from the teacher as a secure base and returns to her for comfort as a safe haven, the two key functions of an attachment figure.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 1 में नया आया एक बच्चा गतिविधि-कोने को टटोलते समय बार-बार जाँचता रहता है कि उसकी शिक्षिका पास है, और तेज़ आवाज़ से चौंकने पर उसके पास दौड़ जाता है। लगाव के शब्दों में, शिक्षिका क्या कर रही है?","optionsHi":["सुरक्षित आधार और सुरक्षित शरण-स्थल","अजनबी-चिंता का स्रोत","बाह्य-तंत्र का प्रभाव","प्रतिनिधिक पुनर्बलन के लिए आदर्श"],"explanationHi":"वह शिक्षिका को सुरक्षित आधार बनाकर टटोलता है और सांत्वना के लिए उसके पास सुरक्षित शरण-स्थल के रूप में लौटता है, जो लगाव-व्यक्ति के दो प्रमुख प्रकार्य हैं।"},
  {"id":"cdp-child-development-922","question":"Bowlby claimed that breaking the mother–child bond in early years leads to lasting harm. Michael Rutter refined this by distinguishing two situations. Which distinction did he draw?","options":["Between attachment to mothers and attachment to fathers and siblings","Between deprivation (a bond formed then lost) and privation (no bond ever formed)","Between secure and insecure attachment as measured in the Strange Situation","Between imprinting in birds and the slower attachment seen in humans"],"answer":1,"explanation":"Rutter argued that much of the severe harm Bowlby attributed to separation came from privation, never forming a bond at all, while loss of an existing bond (deprivation) usually had less lasting effect.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"बॉल्बी ने दावा किया कि आरंभिक वर्षों में माँ–बच्चे के बंधन का टूटना स्थायी हानि की ओर ले जाता है। माइकल रटर ने दो स्थितियों में भेद करके इसे परिष्कृत किया। उन्होंने कौन-सा भेद किया?","optionsHi":["माँओं से लगाव और पिताओं तथा भाई-बहनों से लगाव के बीच","वंचन (एक बंधन जो बना और खो गया) और अभाव (कोई बंधन कभी बना ही नहीं) के बीच","स्ट्रेंज सिचुएशन में मापे गए सुरक्षित और असुरक्षित लगाव के बीच","पक्षियों में छापन और मनुष्यों में देखे गए धीमे लगाव के बीच"],"explanationHi":"रटर का तर्क था कि बॉल्बी ने वियोग के लिए जिस गंभीर हानि को उत्तरदायी माना उसका बहुत भाग अभाव से आया, यानी बंधन कभी बनने से, जबकि किसी मौजूदा बंधन की हानि (वंचन) का प्रभाव प्रायः कम स्थायी था।"},
  {"id":"cdp-child-development-923","question":"Asked why the sun is called ‘sun’, a four-year-old says, ‘Because it is hot and round and yellow,’ and insists it could not have been given any other name. Piaget called this belief that names belong to things themselves:","options":["Nominal realism","Artificialism","Transductive reasoning","Conservation of identity"],"answer":0,"explanation":"Nominal realism treats a word as a real property of the object, a form of pre-operational realism. Artificialism concerns who made natural things, not their names.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"यह पूछे जाने पर कि सूरज को ‘सूरज’ क्यों कहते हैं, एक चार वर्ष का बच्चा कहता है, ‘क्योंकि वह गरम और गोल और पीला है,’ और आग्रह करता है कि उसे कोई और नाम नहीं दिया जा सकता था। पियाजे ने इस विश्वास को, कि नाम वस्तुओं के ही होते हैं, क्या कहा?","optionsHi":["नामात्मक यथार्थवाद","कृत्रिमवाद","पारगामी तर्क","पहचान का संरक्षण"],"explanationHi":"नामात्मक यथार्थवाद शब्द को वस्तु का वास्तविक गुण मानता है, जो पूर्व-संक्रियात्मक यथार्थवाद का एक रूप है। कृत्रिमवाद इससे संबंधित है कि प्राकृतिक वस्तुएँ किसने बनाईं, उनके नामों से नहीं।"},
  {"id":"cdp-child-development-924","question":"A four-year-old wakes up and tells her mother, ‘There was a lion in my room; you saw it too, didn’t you?’ She believes her dream happened outside her and that others could see it. Piaget would describe this as:","options":["Object permanence, knowing objects exist when unseen","Realism: treating mental events as real, external things","Formal operational imagination about possible worlds","Private speech, talking aloud to guide her own actions"],"answer":1,"explanation":"Pre-operational realism confuses psychological events such as dreams with physical reality. Young children often think dreams come from outside and can be seen by others.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"चार वर्ष की एक बच्ची जागकर अपनी माँ से कहती है, ‘मेरे कमरे में एक शेर था; आपने भी उसे देखा था न?’ वह मानती है कि उसका सपना उसके बाहर घटा और दूसरे उसे देख सकते थे। पियाजे इसका वर्णन क्या करते?","optionsHi":["वस्तु-स्थायित्व, अनदेखी वस्तुओं के अस्तित्व को जानना","यथार्थवाद: मानसिक घटनाओं को वास्तविक, बाह्य वस्तुएँ मानना","औपचारिक संक्रियात्मक कल्पना, संभावित संसारों के बारे में","निजी वाणी, अपने कार्यों का मार्गदर्शन करने के लिए ज़ोर से बोलना"],"explanationHi":"पूर्व-संक्रियात्मक यथार्थवाद सपनों जैसी मनोवैज्ञानिक घटनाओं को भौतिक यथार्थ से गड्डमड्ड कर देता है। छोटे बच्चे प्रायः सोचते हैं कि सपने बाहर से आते हैं और दूसरे उन्हें देख सकते हैं।"},
  {"id":"cdp-child-development-925","question":"A seven-year-old says that a bicycle is alive when it is moving but not when it is parked, while a tree is ‘not alive because it doesn’t walk’. This reasoning is best described as:","options":["A mature, biological understanding of what living things are","Artificialism, the belief that people made nature","Hypothetico-deductive reasoning about life","Animism in a reduced form, linking life with movement"],"answer":3,"explanation":"Piaget found that animism narrows with age: young children call almost anything alive, then only things that move, and later only things that move by themselves. Treating the tree as non-living shows the concept is still immature.","difficulty":"hard","source":"CTET · State TETs","questionHi":"सात वर्ष का एक बच्चा कहता है कि साइकिल चलते समय सजीव है पर खड़ी होने पर नहीं, जबकि पेड़ ‘सजीव नहीं है क्योंकि वह चलता नहीं’। इस तर्क का सबसे अच्छा वर्णन है:","optionsHi":["सजीव वस्तुएँ क्या हैं इसकी परिपक्व, जैविक समझ","कृत्रिमवाद, यह विश्वास कि मनुष्यों ने प्रकृति बनाई","जीवन के बारे में परिकल्पित-निगमनात्मक तर्क","संकुचित रूप में सजीववाद (एनिमिज़्म), जीवन को गति से जोड़ते हुए"],"explanationHi":"पियाजे ने पाया कि सजीववाद आयु के साथ संकुचित होता है: छोटे बच्चे लगभग किसी भी चीज़ को सजीव कहते हैं, फिर केवल चलने वाली को, और बाद में केवल स्वयं चलने वाली को। पेड़ को निर्जीव मानना दिखाता है कि संप्रत्यय अब भी अपरिपक्व है।"},
  {"id":"cdp-child-development-926","question":"In a Class 1 classroom, two rows of six laddoos are placed side by side and then one row is spread out. A child counts both rows, says ‘six’ and ‘six’, and still insists the longer row has more. This shows that:","options":["Counting does not yet ensure conservation; perceived length still dominates","The child cannot count accurately and needs more drill in counting to six","The child has mastered conservation but simply misheard the question","The child has already reached the formal operational stage of thinking"],"answer":0,"explanation":"Counting is a skill; conservation requires understanding that number stays the same despite changes in appearance. Centration on row length overrides the count.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 1 में लड्डुओं की छह-छह की दो पंक्तियाँ साथ-साथ रखी जाती हैं और फिर एक पंक्ति को फैला दिया जाता है। एक बच्चा दोनों पंक्तियाँ गिनता है, ‘छह’ और ‘छह’ कहता है, और फिर भी आग्रह करता है कि लंबी पंक्ति में अधिक हैं। यह दर्शाता है कि:","optionsHi":["गिनती अभी संरक्षण सुनिश्चित नहीं करती; प्रत्यक्ष लंबाई अब भी हावी है","बच्चा सटीक गिनती नहीं कर सकता और उसे छह तक गिनती में और अभ्यास की आवश्यकता है","बच्चे ने संरक्षण में निपुणता पा ली है पर प्रश्न ग़लत सुन लिया","बच्चा चिंतन की औपचारिक संक्रियात्मक अवस्था तक पहले ही पहुँच चुका है"],"explanationHi":"गिनती एक कौशल है; संरक्षण के लिए यह समझना आवश्यक है कि रूप में परिवर्तन के बावजूद संख्या वही रहती है। पंक्ति की लंबाई पर केंद्रण गिनती पर हावी हो जाता है।"},
  {"id":"cdp-child-development-927","question":"Asked to arrange ten sticks from shortest to longest, Child A tries pairs at random and makes many corrections, while Child B picks the shortest stick, then the shortest of those left, and so on, finishing without errors. According to Piaget, Child B’s method shows:","options":["Pre-operational intuitive judgement based on how the sticks look","Operational seriation, typical of the concrete operational stage","A tertiary circular reaction, experimenting to see what happens","Bruner’s iconic mode, picturing the sticks in order"],"answer":1,"explanation":"Systematic seriation treats each stick as longer than those before it and shorter than those after it, an operational relation. Trial-and-error ordering is typical of the pre-operational stage.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"दस डंडियों को सबसे छोटी से सबसे लंबी तक क्रम में लगाने को कहे जाने पर बच्चा A यादृच्छिक जोड़ियाँ आज़माता है और बहुत सुधार करता है, जबकि बच्चा B सबसे छोटी डंडी उठाता है, फिर बची हुई में से सबसे छोटी, और इसी तरह, बिना त्रुटि के पूरा कर देता है। पियाजे के अनुसार बच्चे B की विधि क्या दर्शाती है?","optionsHi":["डंडियों के दिखने के आधार पर पूर्व-संक्रियात्मक अंतर्ज्ञानात्मक निर्णय","संक्रियात्मक क्रमबद्धता (सीरिएशन), जो मूर्त संक्रियात्मक अवस्था की विशिष्टता है","तृतीयक वृत्तीय प्रतिक्रिया, यह देखने के लिए प्रयोग करना कि क्या होता है","ब्रूनर का प्रतिबिंबात्मक पक्ष, डंडियों को क्रम में कल्पना करना"],"explanationHi":"व्यवस्थित क्रमबद्धता प्रत्येक डंडी को अपने से पहले वालों से लंबी और बाद वालों से छोटी मानती है, जो एक संक्रियात्मक संबंध है। प्रयास-और-त्रुटि से क्रम लगाना पूर्व-संक्रियात्मक अवस्था की विशिष्टता है।"},
  {"id":"cdp-child-development-928","question":"A child is shown two identical green fields, each with a cow and the same number of small houses. In one field the houses are bunched in a corner; in the other they are scattered. She says the cow in the bunched field has more grass to eat. She has not yet acquired:","options":["Object permanence","Seriation","Conservation of area","Hierarchical class inclusion"],"answer":2,"explanation":"The uncovered area is equal in both fields, but scattered houses look as if they cover more. Conservation of area is normally acquired in the concrete operational stage.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"एक बच्ची को दो एक जैसे हरे खेत दिखाए जाते हैं, प्रत्येक में एक गाय और छोटे घरों की समान संख्या है। एक खेत में घर एक कोने में सटे हैं; दूसरे में बिखरे हैं। वह कहती है कि सटे हुए घरों वाले खेत की गाय के पास खाने को अधिक घास है। उसने अभी तक क्या अर्जित नहीं किया है?","optionsHi":["वस्तु-स्थायित्व","क्रमबद्धता","क्षेत्रफल का संरक्षण","पदानुक्रमित वर्ग-समावेशन"],"explanationHi":"दोनों खेतों में खुला क्षेत्रफल बराबर है, पर बिखरे घर ऐसे दिखते हैं मानो अधिक घेरते हों। क्षेत्रफल का संरक्षण सामान्यतः मूर्त संक्रियात्मक अवस्था में अर्जित होता है।"},
  {"id":"cdp-child-development-929","question":"A Class 2 child knows that 7 + 5 = 12, but when asked 12 − 5, she starts counting back on her fingers from 12 and does not see the link. Piaget would say she has not yet fully developed:","options":["Animistic thinking","Object permanence","Seriation of numbers","Reversibility"],"answer":3,"explanation":"Reversibility means seeing that one operation can be undone by its inverse, so that 12 − 5 must give back 7. Without it, each fact is treated separately.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 2 की एक बच्ची जानती है कि 7 + 5 = 12, पर जब उससे 12 − 5 पूछा जाता है तो वह उँगलियों पर 12 से उलटी गिनती शुरू कर देती है और संबंध नहीं देखती। पियाजे कहते कि उसमें अभी पूर्ण रूप से क्या विकसित नहीं हुआ है?","optionsHi":["सजीववादी चिंतन","वस्तु-स्थायित्व","संख्याओं की क्रमबद्धता","उत्क्रमणीयता (रिवर्सिबिलिटी)"],"explanationHi":"उत्क्रमणीयता का अर्थ है यह देखना कि एक संक्रिया को उसकी विलोम संक्रिया से पूर्ववत् किया जा सकता है, ताकि 12 − 5 से 7 वापस मिलना चाहिए। इसके बिना प्रत्येक तथ्य को अलग माना जाता है।"},
  {"id":"cdp-child-development-930","question":"Asked, ‘Are you a Delhiite and an Indian at the same time?’, a five-year-old says, ‘No, I’m from Delhi, not India.’ A nine-year-old says, ‘Yes, because Delhi is in India.’ The difference best reflects the development of:","options":["Class inclusion","Conservation of volume","Object permanence","Deferred imitation"],"answer":0,"explanation":"Piaget found that young children cannot place one class (Delhi) within a larger one (India); understanding nested categories develops with concrete operations.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"यह पूछे जाने पर, ‘क्या तुम एक ही समय में दिल्लीवासी और भारतीय हो?’, पाँच वर्ष का बच्चा कहता है, ‘नहीं, मैं दिल्ली से हूँ, भारत से नहीं।’ नौ वर्ष का बच्चा कहता है, ‘हाँ, क्योंकि दिल्ली भारत में है।’ यह अंतर सबसे अच्छी तरह किसके विकास को दर्शाता है?","optionsHi":["वर्ग-समावेशन","आयतन का संरक्षण","वस्तु-स्थायित्व","विलंबित अनुकरण"],"explanationHi":"पियाजे ने पाया कि छोटे बच्चे एक वर्ग (दिल्ली) को बड़े वर्ग (भारत) के भीतर नहीं रख पाते; अंतर्निहित श्रेणियों की समझ मूर्त संक्रियाओं के साथ विकसित होती है।"},
  {"id":"cdp-child-development-931","question":"A 15-year-old in a Class 10 debate passionately describes how India would be with no pollution and no corruption, and criticises adults for not making it happen. In Piaget’s cognitive theory, this mainly reflects:","options":["Pre-operational egocentrism, unable to see others’ views","A failure of conservation when ideas change their form","A new ability to reason about ideals beyond reality","Concrete operational seriation of social problems"],"answer":2,"explanation":"Formal operations let adolescents reason about hypothetical worlds, which often shows up as idealism and criticism of the real world. It is not pre-operational egocentrism.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 10 की वाद-विवाद प्रतियोगिता में 15 वर्ष का एक किशोर जोश से वर्णन करता है कि बिना प्रदूषण और भ्रष्टाचार के भारत कैसा होता, और वयस्कों की आलोचना करता है कि वे ऐसा नहीं कर पाए। पियाजे के संज्ञानात्मक सिद्धांत में यह मुख्यतः क्या दर्शाता है?","optionsHi":["पूर्व-संक्रियात्मक अहंकेंद्रिता, दूसरों के दृष्टिकोण न देख पाना","संरक्षण की विफलता जब विचार अपना रूप बदलते हैं","यथार्थ से परे आदर्शों के बारे में तर्क करने की नई क्षमता","सामाजिक समस्याओं की मूर्त संक्रियात्मक क्रमबद्धता"],"explanationHi":"औपचारिक संक्रियाएँ किशोरों को काल्पनिक संसारों के बारे में तर्क करने देती हैं, जो प्रायः आदर्शवाद और वास्तविक संसार की आलोचना के रूप में दिखाई देता है। यह पूर्व-संक्रियात्मक अहंकेंद्रिता नहीं है।"},
  {"id":"cdp-child-development-932","question":"A 16-year-old rides his scooter without a helmet, saying, ‘Accidents happen to others, not to me.’ David Elkind, building on Piaget’s formal operational stage, called this belief:","options":["The imaginary audience","Transductive reasoning","Centration","The personal fable"],"answer":3,"explanation":"The personal fable is the adolescent belief that one’s experiences are unique and that one is invulnerable. The imaginary audience is the belief that everyone is watching oneself.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"16 वर्ष का एक किशोर बिना हेलमेट के अपना स्कूटर चलाता है, यह कहकर कि ‘दुर्घटनाएँ दूसरों के साथ होती हैं, मेरे साथ नहीं।’ डेविड एल्किंड ने, पियाजे की औपचारिक संक्रियात्मक अवस्था पर निर्माण करते हुए, इस विश्वास को क्या कहा?","optionsHi":["काल्पनिक दर्शक (इमेजिनरी ऑडिएंस)","पारगामी तर्क","केंद्रण","व्यक्तिगत कथा (पर्सनल फ़ेबल)"],"explanationHi":"व्यक्तिगत कथा किशोर का यह विश्वास है कि उसके अनुभव अद्वितीय हैं और वह अभेद्य है। काल्पनिक दर्शक यह विश्वास है कि सब उसे देख रहे हैं।"},
  {"id":"cdp-child-development-933","question":"On a balance beam, a 9-year-old balances weights by trial and error. A 14-year-old explains, ‘Two weights here at distance 3 will balance three weights at distance 2, because 2 × 3 = 3 × 2.’ The older child is using:","options":["Proportional reasoning, a formal operational scheme","Seriation, a concrete operational scheme for ordering","A secondary circular reaction repeated for its effect","Bruner’s enactive mode of representing by action"],"answer":0,"explanation":"Understanding that weight and distance trade off in proportion is one of the formal operational schemes Piaget and Inhelder described. The younger child’s trial and error lacks this.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"एक तुला-दंड पर 9 वर्ष का बच्चा प्रयास-और-त्रुटि से भार संतुलित करता है। 14 वर्ष का बच्चा समझाता है, ‘यहाँ दूरी 3 पर दो भार दूरी 2 पर तीन भार को संतुलित करेंगे, क्योंकि 2 × 3 = 3 × 2।’ बड़ा बच्चा क्या प्रयोग कर रहा है?","optionsHi":["आनुपातिक तर्क, एक औपचारिक संक्रियात्मक स्कीमा","क्रमबद्धता, क्रम लगाने की एक मूर्त संक्रियात्मक स्कीमा","द्वितीयक वृत्तीय प्रतिक्रिया जो उसके प्रभाव के लिए दोहराई जाती है","ब्रूनर का क्रियात्मक पक्ष, क्रिया द्वारा निरूपण"],"explanationHi":"यह समझना कि भार और दूरी अनुपात में एक-दूसरे के बदले आते हैं, पियाजे और इन्हेल्डर द्वारा वर्णित औपचारिक संक्रियात्मक स्कीमाओं में से एक है। छोटे बच्चे के प्रयास-और-त्रुटि में इसका अभाव है।"},
  {"id":"cdp-child-development-934","question":"Consider these statements. 1. Concrete operational children reason mainly from specific experiences towards a general rule. 2. Formal operational thinkers can reason from a general premise to specific conclusions, even about things they have never seen. 3. Concrete operational children cannot reason logically at all. Which is/are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Concrete operational children do reason logically, but about concrete, familiar content and mostly inductively. Hypothetico-deductive reasoning belongs to formal operations, so statement 3 is false.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"इन कथनों पर विचार कीजिए। 1. मूर्त संक्रियात्मक बच्चे मुख्यतः विशिष्ट अनुभवों से सामान्य नियम की ओर तर्क करते हैं। 2. औपचारिक संक्रियात्मक चिंतक सामान्य आधार-वाक्य से विशिष्ट निष्कर्षों तक तर्क कर सकते हैं, उन चीज़ों के बारे में भी जो उन्होंने कभी नहीं देखी। 3. मूर्त संक्रियात्मक बच्चे तार्किक रूप से बिल्कुल तर्क नहीं कर सकते। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 2","केवल 1 और 3","1, 2 और 3"],"explanationHi":"मूर्त संक्रियात्मक बच्चे तार्किक रूप से तर्क करते हैं, पर मूर्त, परिचित विषय-वस्तु के बारे में और अधिकतर आगमनात्मक रूप से। परिकल्पित-निगमनात्मक तर्क औपचारिक संक्रियाओं का है, इसलिए कथन 3 असत्य है।"},
  {"id":"cdp-child-development-935","question":"A baby who has been breastfed tries to suck milk from a spoon in the same way, then slowly changes the shape of her lips to sip from it. Piaget would say that this shows:","options":["Only assimilation, since the same sucking schema is being used","Only accommodation, since the shape of the lips is changing","Equilibration without any adaptation, as the schema stays fixed","Assimilation and accommodation working together in adaptation"],"answer":3,"explanation":"Applying the sucking schema to the spoon is assimilation; adjusting the lips is accommodation. Piaget held that both are present in every act of adaptation, in varying balance.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"माँ का दूध पीने वाली एक शिशु उसी तरह चम्मच से दूध चूसने की कोशिश करती है, फिर धीरे-धीरे अपने होंठों का आकार बदलकर उससे घूँट लेती है। पियाजे कहते कि यह दर्शाता है:","optionsHi":["केवल आत्मसात्करण, क्योंकि उसी चूसने की स्कीमा का प्रयोग हो रहा है","केवल समायोजन, क्योंकि होंठों का आकार बदल रहा है","बिना किसी अनुकूलन के साम्यधारण, क्योंकि स्कीमा स्थिर रहती है","अनुकूलन में आत्मसात्करण और समायोजन का साथ-साथ कार्य करना"],"explanationHi":"चूसने की स्कीमा को चम्मच पर लागू करना आत्मसात्करण है; होंठों को समायोजित करना समायोजन है। पियाजे का मत था कि अनुकूलन के हर कार्य में दोनों उपस्थित होते हैं, भिन्न संतुलन में।"},
  {"id":"cdp-child-development-936","question":"A four-month-old learns to look at a rattle and to grasp it as two separate actions. A few weeks later she looks at the rattle and reaches out to grasp it in one smooth action. Piaget’s term for combining separate schemas into a more complex system is:","options":["Accommodation","Organisation","Conservation","Decentration"],"answer":1,"explanation":"Organisation is the tendency to integrate schemas into higher-order structures. Adaptation, made up of assimilation and accommodation, is the other basic function in Piaget’s theory.","difficulty":"hard","source":"CTET · State TETs","questionHi":"चार महीने की एक शिशु खड़खड़ाहट को देखना और उसे पकड़ना दो अलग क्रियाओं के रूप में सीखती है। कुछ सप्ताह बाद वह खड़खड़ाहट को देखती है और एक सहज क्रिया में पकड़ने को हाथ बढ़ाती है। पृथक स्कीमाओं को अधिक जटिल प्रणाली में जोड़ने के लिए पियाजे का शब्द है:","optionsHi":["समायोजन","संगठन","संरक्षण","विकेंद्रण"],"explanationHi":"संगठन स्कीमाओं को उच्चतर संरचनाओं में एकीकृत करने की प्रवृत्ति है। अनुकूलन, जो आत्मसात्करण और समायोजन से बना है, पियाजे के सिद्धांत का दूसरा मूल प्रकार्य है।"},
  {"id":"cdp-child-development-937","question":"In Piaget’s view, how are play and imitation related to assimilation and accommodation?","options":["Play is mainly accommodation; imitation is mainly assimilation","Both are pure accommodation to the demands of reality","Play is mainly assimilation; imitation is mainly accommodation","Both are unrelated to adaptation and serve only for fun"],"answer":2,"explanation":"In symbolic play a stick becomes a horse because the child fits reality to her schemas, so assimilation dominates. In imitation the child changes her own actions to copy a model, so accommodation dominates.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"पियाजे के मत में, खेल और अनुकरण का आत्मसात्करण और समायोजन से क्या संबंध है?","optionsHi":["खेल मुख्यतः समायोजन है; अनुकरण मुख्यतः आत्मसात्करण","दोनों यथार्थ की माँगों के प्रति शुद्ध समायोजन हैं","खेल मुख्यतः आत्मसात्करण है; अनुकरण मुख्यतः समायोजन","दोनों अनुकूलन से असंबद्ध हैं और केवल मनोरंजन के काम आते हैं"],"explanationHi":"प्रतीकात्मक खेल में एक डंडा घोड़ा बन जाता है क्योंकि बच्चा यथार्थ को अपनी स्कीमाओं में ढालता है, इसलिए आत्मसात्करण हावी है। अनुकरण में बच्चा किसी आदर्श की नकल करने के लिए अपने कार्य बदलता है, इसलिए समायोजन हावी है।"},
  {"id":"cdp-child-development-938","question":"Consider these statements about Piaget’s stages. 1. The order of the stages is the same for all children. 2. Each stage begins at exactly the same age for every child. 3. With good teaching a child can skip the concrete operational stage. Which is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Piaget held the sequence of stages to be invariant, while the ages are only approximate and vary with experience. No stage can be skipped, because each builds on the one before.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"पियाजे की अवस्थाओं के बारे में इन कथनों पर विचार कीजिए। 1. अवस्थाओं का क्रम सभी बच्चों के लिए समान है। 2. प्रत्येक अवस्था प्रत्येक बच्चे के लिए ठीक उसी आयु में आरंभ होती है। 3. अच्छे शिक्षण से बच्चा मूर्त संक्रियात्मक अवस्था को छोड़ सकता है। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"पियाजे अवस्थाओं के क्रम को अपरिवर्तनीय मानते थे, जबकि आयु केवल अनुमानित है और अनुभव के साथ बदलती है। कोई अवस्था छोड़ी नहीं जा सकती, क्योंकि प्रत्येक पिछली पर निर्मित होती है।"},
  {"id":"cdp-child-development-939","question":"Retelling a story in Class 1, a child says, ‘Then he went there and he hit him and it fell down,’ without naming anyone or explaining what ‘it’ was, as if the listener already knew. Piaget would see this as a sign of:","options":["A language disorder needing therapy","Formal operational thought","The concrete operational stage","Egocentrism in communication"],"answer":3,"explanation":"Pre-operational children often fail to take the listener’s perspective, assuming others know what they know. This is normal egocentric communication, not a disorder.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 1 में कहानी दोबारा सुनाते हुए एक बच्चा कहता है, ‘फिर वह वहाँ गया और उसने उसे मारा और वह गिर गया,’ बिना किसी का नाम लिए या यह समझाए कि ‘वह’ क्या था, मानो श्रोता पहले से जानता हो। पियाजे इसे किसका संकेत मानते?","optionsHi":["भाषा-विकार जिसके लिए चिकित्सा चाहिए","औपचारिक संक्रियात्मक चिंतन","मूर्त संक्रियात्मक अवस्था","संप्रेषण में अहंकेंद्रिता"],"explanationHi":"पूर्व-संक्रियात्मक बच्चे प्रायः श्रोता का दृष्टिकोण लेने में विफल रहते हैं, यह मानते हुए कि दूसरे वह जानते हैं जो वे जानते हैं। यह सामान्य अहंकेंद्रित संप्रेषण है, विकार नहीं।"},
  {"id":"cdp-child-development-940","question":"Studies of children from pottery-making families found that they understood conservation of substance with clay earlier than other children of the same age. What does this finding most directly suggest?","options":["Piaget’s stages do not exist at all in other cultures","Experience can affect when a given conservation appears","Conservation depends only on brain maturation, not on experience","Pottery children skip the pre-operational stage entirely"],"answer":1,"explanation":"Familiar materials and activities can bring forward the age at which a concept is shown, which supports the role of experience. It does not show that stages are skipped or absent.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"मिट्टी के बर्तन बनाने वाले परिवारों के बच्चों के अध्ययनों ने पाया कि वे मिट्टी के साथ पदार्थ के संरक्षण को उसी आयु के अन्य बच्चों से पहले समझ गए। यह निष्कर्ष सबसे सीधे क्या सुझाता है?","optionsHi":["पियाजे की अवस्थाएँ अन्य संस्कृतियों में बिल्कुल नहीं होतीं","अनुभव किसी संरक्षण के प्रकट होने के समय को प्रभावित कर सकता है","संरक्षण केवल मस्तिष्क की परिपक्वता पर निर्भर है, अनुभव पर नहीं","मिट्टी के बर्तन वाले बच्चे पूर्व-संक्रियात्मक अवस्था को पूरी तरह छोड़ देते हैं"],"explanationHi":"परिचित सामग्री और गतिविधियाँ उस आयु को पहले ला सकती हैं जिस पर कोई संप्रत्यय दिखाया जाता है, जो अनुभव की भूमिका का समर्थन करता है। यह नहीं दिखाता कि अवस्थाएँ छोड़ी जाती हैं या अनुपस्थित हैं।"},
  {"id":"cdp-child-development-941","question":"A teacher shows a five-year-old a box of crayons and asks what is inside. The child says ‘crayons’, but the box actually holds candles. Asked what his friend who has not looked inside will think is in the box, he says ‘candles’. Piaget would relate this mainly to:","options":["Conservation of number","Seriation by size","Egocentric thinking","Object permanence"],"answer":2,"explanation":"The child assumes the friend knows what he himself now knows. Piaget described this inability to take another’s perspective as egocentrism; later researchers studied it under ‘theory of mind’.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"एक शिक्षक पाँच वर्ष के बच्चे को क्रेयॉन का डिब्बा दिखाकर पूछता है कि उसमें क्या है। बच्चा कहता है ‘क्रेयॉन’, पर डिब्बे में वास्तव में मोमबत्तियाँ हैं। यह पूछे जाने पर कि उसका जिस मित्र ने भीतर नहीं देखा वह क्या सोचेगा कि डिब्बे में है, वह कहता है ‘मोमबत्तियाँ’। पियाजे इसे मुख्यतः किससे जोड़ते?","optionsHi":["संख्या का संरक्षण","आकार के आधार पर क्रमबद्धता","अहंकेंद्रित चिंतन","वस्तु-स्थायित्व"],"explanationHi":"बच्चा मान लेता है कि मित्र वही जानता है जो वह स्वयं अब जानता है। पियाजे ने दूसरे का दृष्टिकोण न ले पाने की इस असमर्थता को अहंकेंद्रिता कहा; बाद के शोधकर्ताओं ने इसका अध्ययन ‘मन का सिद्धांत’ के अंतर्गत किया।"},
  {"id":"cdp-child-development-942","question":"In a Class 5 EVS lesson, a child correctly answers that a long thin glass and a short wide glass with water poured from the same bottle hold the same amount, but cannot yet predict whether a clay ball and a flattened clay roti will push up water by the same amount when dropped in a beaker. This is consistent with Piaget because:","options":["Volume displacement is conserved years after liquid quantity","Children of this age should already conserve displaced volume easily","Conservation of liquid is a formal operational skill, not a concrete one","The child has lost her earlier ability to conserve under pressure"],"answer":0,"explanation":"Conservation of volume in the sense of displacement typically appears around 11 to 12 years, well after liquid quantity. This is a further example of horizontal décalage.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"कक्षा 5 के EVS पाठ में एक बच्चा सही उत्तर देता है कि एक ही बोतल से पानी डालने पर एक लंबा पतला गिलास और एक छोटा चौड़ा गिलास समान मात्रा थामते हैं, पर अभी यह पूर्वानुमान नहीं कर पाता कि मिट्टी की गेंद और चपटी की हुई मिट्टी की रोटी बीकर में डालने पर पानी को समान मात्रा में ऊपर उठाएँगी या नहीं। यह पियाजे से संगत क्यों है?","optionsHi":["विस्थापित आयतन का संरक्षण द्रव मात्रा के वर्षों बाद आता है","इस आयु के बच्चों को विस्थापित आयतन का संरक्षण पहले से आसानी से करना चाहिए","द्रव का संरक्षण औपचारिक संक्रियात्मक कौशल है, मूर्त नहीं","बच्चे ने दबाव में संरक्षण करने की अपनी पहले की क्षमता खो दी है"],"explanationHi":"विस्थापन के अर्थ में आयतन का संरक्षण सामान्यतः लगभग 11 से 12 वर्ष की आयु में आता है, द्रव मात्रा के काफ़ी बाद। यह क्षैतिज विस्थापन का एक और उदाहरण है।"},
  {"id":"cdp-child-development-943","question":"Which classroom question would a typical Class 2 child (in the late pre-operational or early concrete operational period) find hardest?","options":["‘Which of these two pencils is longer, the red or the blue?’","‘Sort these leaves into big ones and small ones.’","‘Count the mangoes in the basket and tell me.’","‘If all fish could fly and Golu is a fish, can Golu fly?’"],"answer":3,"explanation":"Reasoning from a premise contrary to fact requires formal operational thought. The other tasks need perception, simple classification or counting, which are within reach of young children.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 2 के एक सामान्य बच्चे (उत्तर पूर्व-संक्रियात्मक या आरंभिक मूर्त संक्रियात्मक अवधि में) को कक्षा का कौन-सा प्रश्न सबसे कठिन लगेगा?","optionsHi":["‘इन दो पेंसिलों में से कौन-सी लंबी है, लाल या नीली?’","‘इन पत्तियों को बड़ी और छोटी में छाँटो।’","‘टोकरी में आम गिनो और मुझे बताओ।’","‘यदि सभी मछलियाँ उड़ सकें और गोलू एक मछली है, तो क्या गोलू उड़ सकता है?’"],"explanationHi":"तथ्य-विरुद्ध आधार-वाक्य से तर्क करने के लिए औपचारिक संक्रियात्मक चिंतन चाहिए। अन्य कार्यों में प्रत्यक्षण, सरल वर्गीकरण या गिनती चाहिए, जो छोटे बच्चों की पहुँच में हैं।"},
  {"id":"cdp-child-development-944","question":"A child believes all heavy things sink. When she sees a huge steel ship floating in the harbour, she says, ‘It floats because it is tired and wants to rest on the water.’ In Piaget’s terms, she has:","options":["Accommodated her schema successfully to fit the floating ship","Assimilated it into existing ideas without changing her schema","Reached formal operations, since she explains an exception to a rule","Used reversibility to undo her earlier belief"],"answer":1,"explanation":"She explains away the conflicting event with an animistic idea instead of revising her schema, so she assimilates rather than accommodates. Disequilibrium is not resolved by real change here.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"एक बच्ची मानती है कि सभी भारी चीज़ें डूबती हैं। जब वह बंदरगाह में तैरता हुआ विशाल स्टील का जहाज़ देखती है, तो कहती है, ‘वह इसलिए तैरता है क्योंकि वह थक गया है और पानी पर आराम करना चाहता है।’ पियाजे के शब्दों में, उसने क्या किया है?","optionsHi":["तैरते जहाज़ के अनुरूप अपनी स्कीमा को सफलतापूर्वक समायोजित किया","उसे अपनी स्कीमा बदले बिना मौजूदा विचारों में आत्मसात् किया","औपचारिक संक्रियाओं तक पहुँच गई, क्योंकि वह किसी नियम के अपवाद की व्याख्या करती है","अपने पहले के विश्वास को पूर्ववत् करने के लिए उत्क्रमणीयता का प्रयोग किया"],"explanationHi":"वह स्कीमा को संशोधित करने के बजाय विरोधी घटना को सजीववादी विचार से टाल देती है, इसलिए वह समायोजित नहीं बल्कि आत्मसात् करती है। यहाँ वास्तविक परिवर्तन से असंतुलन सुलझा नहीं।"},
  {"id":"cdp-child-development-945","question":"Assertion (A): A Class 7 teacher should not assume that all students can follow a purely verbal, abstract explanation of algebraic identities. Reason (R): Many 12-year-olds are still moving from concrete to formal operational thinking.","options":["A is false, but R is true","A is true, but R is false","Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"Around 11 to 12 years, children are only beginning formal operations, and many still need concrete or pictorial support. That is precisely why purely abstract teaching may fail.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"अभिकथन (A): कक्षा 7 के शिक्षक को यह नहीं मान लेना चाहिए कि सभी विद्यार्थी बीजीय सर्वसमिकाओं की विशुद्ध शाब्दिक, अमूर्त व्याख्या का अनुसरण कर सकते हैं। कारण (R): बहुत-से 12 वर्ष के बच्चे अब भी मूर्त से औपचारिक संक्रियात्मक चिंतन की ओर बढ़ रहे होते हैं।","optionsHi":["A असत्य है, परंतु R सत्य है","A सत्य है, परंतु R असत्य है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं, और R, A की सही व्याख्या है"],"explanationHi":"लगभग 11 से 12 वर्ष की आयु में बच्चे औपचारिक संक्रियाओं की केवल शुरुआत कर रहे होते हैं, और कई को अब भी मूर्त या चित्रात्मक सहारा चाहिए। इसीलिए विशुद्ध अमूर्त शिक्षण विफल हो सकता है।"},
  {"id":"cdp-child-development-946","question":"How many of these behaviours would Piaget expect in the pre-operational stage? I. Calling the moon ‘alive’ because it follows you. II. Arranging sticks by length systematically on the first try. III. Using a box as a car in pretend play. IV. Judging that a squashed ball of dough has less dough.","options":["Only one","Only two","Only three","All four of them"],"answer":2,"explanation":"I (animism), III (symbolic play) and IV (non-conservation) are pre-operational. Systematic seriation in II belongs to the concrete operational stage.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"इनमें से कितने व्यवहारों की पियाजे पूर्व-संक्रियात्मक अवस्था में अपेक्षा करते? I. चंद्रमा को ‘सजीव’ कहना क्योंकि वह आपके पीछे चलता है। II. पहले ही प्रयास में डंडियों को लंबाई के अनुसार व्यवस्थित रूप से लगाना। III. दिखावटी खेल में डिब्बे को कार के रूप में प्रयोग करना। IV. यह निर्णय देना कि मसली हुई आटे की गोली में आटा कम है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"I (सजीववाद), III (प्रतीकात्मक खेल) और IV (संरक्षण का अभाव) पूर्व-संक्रियात्मक हैं। II में व्यवस्थित क्रमबद्धता मूर्त संक्रियात्मक अवस्था की है।"},
  {"id":"cdp-child-development-947","question":"In a pre-primary class in Chennai, a four-year-old cries that her brother has ‘more juice’ after equal amounts are poured into a tall glass for him and a short wide glass for her. What should the teacher understand from this?","options":["The child is being greedy and should be scolded for comparing glasses","Typical pre-operational centration on height, not a behaviour problem","The child probably has a visual problem and needs an eye test soon","The child has learnt to conserve but is pretending otherwise for attention"],"answer":1,"explanation":"Young children judge quantity by one striking dimension such as height and cannot yet conserve. Understanding this helps the teacher respond calmly rather than treating it as misbehaviour.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"चेन्नई की एक पूर्व-प्राथमिक कक्षा में चार वर्ष की एक बच्ची रोती है कि उसके भाई के पास ‘ज़्यादा जूस’ है, जबकि उसके लिए ऊँचे गिलास में और उसके लिए छोटे चौड़े गिलास में बराबर मात्रा डाली गई थी। शिक्षक को इससे क्या समझना चाहिए?","optionsHi":["बच्ची लालची है और गिलासों की तुलना करने के लिए उसे डाँटना चाहिए","ऊँचाई पर विशिष्ट पूर्व-संक्रियात्मक केंद्रण, व्यवहार की समस्या नहीं","बच्ची को संभवतः दृष्टि की समस्या है और उसे शीघ्र नेत्र-परीक्षण चाहिए","बच्ची ने संरक्षण करना सीख लिया है पर ध्यान आकर्षित करने के लिए अन्यथा दिखावा कर रही है"],"explanationHi":"छोटे बच्चे ऊँचाई जैसे एक आकर्षक आयाम से मात्रा आँकते हैं और अभी संरक्षण नहीं कर पाते। यह समझना शिक्षक को इसे कुव्यवहार मानने के बजाय शांति से प्रतिक्रिया देने में सहायता करता है।"},
  {"id":"cdp-child-development-948","question":"A school plans to test every child for a ‘visual’, ‘auditory’ or ‘kinaesthetic’ learning style and then teach each child only in that style. What does research most firmly say about this ‘matching’ idea?","options":["It is strongly proven to raise achievement in all subjects and classes","It helps only in primary classes, where children’s styles are clearest","Good studies find little evidence that such matching improves learning","It works only if each child is retested twice a year to confirm the style"],"answer":2,"explanation":"Children do have preferences, but carefully designed studies have not supported the 'meshing' hypothesis that teaching in a learner's preferred style produces better learning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक विद्यालय प्रत्येक बच्चे की ‘दृश्य’, ‘श्रव्य’ या ‘गतिसंवेदी (काइनेस्थेटिक)’ अधिगम शैली की जाँच करने और फिर प्रत्येक बच्चे को केवल उसी शैली में पढ़ाने की योजना बनाता है। इस ‘मिलान’ विचार के बारे में शोध सबसे दृढ़ता से क्या कहता है?","optionsHi":["यह सभी विषयों और कक्षाओं में उपलब्धि बढ़ाने के लिए दृढ़ता से सिद्ध है","यह केवल प्राथमिक कक्षाओं में सहायक है, जहाँ बच्चों की शैलियाँ सबसे स्पष्ट हैं","अच्छे अध्ययन ऐसे मिलान से अधिगम सुधरने का बहुत कम प्रमाण पाते हैं","यह तभी काम करता है जब शैली की पुष्टि के लिए प्रत्येक बच्चे का वर्ष में दो बार पुनः परीक्षण हो"],"explanationHi":"बच्चों की पसंद होती है, पर सावधानी से बनाए गए अध्ययनों ने इस ‘मेशिंग’ परिकल्पना का समर्थन नहीं किया है कि अधिगमकर्ता की पसंदीदा शैली में पढ़ाने से बेहतर अधिगम होता है।"},
  {"id":"cdp-child-development-949","question":"A teacher labels Rahul a ‘kinaesthetic learner’ and therefore gives him only hands-on tasks, excusing him from reading and listening activities. What is the main concern with this practice?","options":["Hands-on tasks are never useful for learning beyond the early classes","It narrows his learning and may hold back his reading and listening","Kinaesthetic learners cannot learn science through hands-on tasks","He will learn too quickly with hands-on tasks and become bored"],"answer":1,"explanation":"Fixing a child into one style restricts exposure to the varied modes that school learning requires. Activity-based tasks help, but not as a replacement for literacy and listening.","difficulty":"hard","source":"CTET · HTET","questionHi":"एक शिक्षक राहुल को ‘गतिबोधक अधिगमकर्ता’ का लेबल देती है और इसलिए उसे केवल हाथ से करने वाले कार्य देती है, उसे पठन और श्रवण गतिविधियों से छूट देते हुए। इस प्रथा की मुख्य चिंता क्या है?","optionsHi":["हाथ से करने वाले कार्य आरंभिक कक्षाओं के बाद अधिगम के लिए कभी उपयोगी नहीं होते","यह उसके अधिगम को संकुचित करता है और उसके पठन तथा श्रवण को पीछे रोक सकता है","गतिबोधक अधिगमकर्ता हाथ से करने वाले कार्यों से विज्ञान नहीं सीख सकते","वह हाथ से करने वाले कार्यों से बहुत तेज़ सीख लेगा और ऊब जाएगा"],"explanationHi":"बच्चे को एक शैली में बाँध देना उन विविध माध्यमों के संपर्क को सीमित करता है जो विद्यालयी अधिगम को चाहिए। गतिविधि-आधारित कार्य सहायक हैं, पर साक्षरता और श्रवण के विकल्प के रूप में नहीं।"},
  {"id":"cdp-child-development-950","question":"Assertion (A): Children often differ in the ways they prefer information to be presented. Reason (R): Therefore, teaching each child only in his or her preferred mode reliably improves achievement.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true","A is true but R is false"],"answer":3,"explanation":"Preferences are real, but the claim that teaching only to them reliably raises achievement is not supported by good evidence, so R is false.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"अभिकथन (A): बच्चे प्रायः इस बात में भिन्न होते हैं कि वे जानकारी को किस प्रकार प्रस्तुत किया जाना पसंद करते हैं। कारण (R): इसलिए प्रत्येक बच्चे को केवल उसके पसंदीदा माध्यम में पढ़ाने से उपलब्धि विश्वसनीय रूप से सुधरती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A असत्य है परंतु R सत्य है","A सत्य है परंतु R असत्य है"],"explanationHi":"पसंद वास्तविक हैं, पर यह दावा कि केवल उन्हीं के अनुसार पढ़ाने से उपलब्धि विश्वसनीय रूप से बढ़ती है, अच्छे प्रमाणों से समर्थित नहीं है, इसलिए R असत्य है।"},
  {"id":"cdp-child-development-951","question":"Which approach to modality is best supported for a whole class?","options":["Fit the mode to the content for all, e.g. maps by sight, pronunciation by ear","Split the class by style and teach map reading by listening to the auditory group","Teach everything only through lectures so that all children get equal treatment","Avoid pictures, since they distract the auditory learners in the class"],"answer":0,"explanation":"Evidence favours matching the mode of presentation to the nature of the content, and using multiple representations, for all learners rather than to each learner's supposed style.","difficulty":"moderate","source":"CTET · REET","questionHi":"पूरी कक्षा के लिए माध्यम (मोडैलिटी) के बारे में कौन-सा उपागम सबसे अच्छी तरह समर्थित है?","optionsHi":["सभी के लिए माध्यम को विषय-वस्तु के अनुरूप रखना, जैसे मानचित्र दृष्टि से, उच्चारण कान से","कक्षा को शैली के आधार पर बाँटना और श्रव्य समूह को सुनकर मानचित्र-पठन सिखाना","सब कुछ केवल व्याख्यानों से पढ़ाना ताकि सभी बच्चों से समान व्यवहार हो","चित्रों से बचना, क्योंकि वे कक्षा के श्रव्य अधिगमकर्ताओं का ध्यान भटकाते हैं"],"explanationHi":"प्रमाण प्रस्तुति के माध्यम को विषय-वस्तु की प्रकृति से मिलाने, और अनेक निरूपणों का उपयोग करने के पक्ष में हैं, सभी अधिगमकर्ताओं के लिए, न कि प्रत्येक की कथित शैली के लिए।"},
  {"id":"cdp-child-development-952","question":"Which statement about learning styles is most defensible for a teacher?","options":["Each child has one fixed learning style that does not change with age","Varied representations such as words, pictures and models help most learners","Style questionnaires reliably identify the way in which each child learns best","Learning styles and Gardner's multiple intelligences are the same idea"],"answer":1,"explanation":"Varied, meaningful representations support understanding for most learners. Styles are not fixed traits, questionnaires measure preference rather than effectiveness, and Gardner's theory is about kinds of ability, not modes of input.","difficulty":"hard","source":"KVS TGT · NVS TGT","questionHi":"अधिगम शैलियों के बारे में शिक्षक के लिए कौन-सा कथन सबसे अधिक रक्षणीय है?","optionsHi":["प्रत्येक बच्चे की एक निश्चित अधिगम शैली होती है जो आयु के साथ नहीं बदलती","शब्दों, चित्रों और मॉडलों जैसे विविध निरूपण अधिकांश अधिगमकर्ताओं की सबसे अधिक सहायता करते हैं","शैली-प्रश्नावलियाँ विश्वसनीय रूप से पहचानती हैं कि प्रत्येक बच्चा किस प्रकार सबसे अच्छा सीखता है","अधिगम शैलियाँ और गार्डनर की बहुबुद्धि एक ही विचार हैं"],"explanationHi":"विविध, सार्थक निरूपण अधिकांश अधिगमकर्ताओं के लिए समझ का समर्थन करते हैं। शैलियाँ निश्चित गुण नहीं हैं, प्रश्नावलियाँ प्रभावशीलता के बजाय पसंद मापती हैं, और गार्डनर का सिद्धांत क्षमता के प्रकारों के बारे में है, निवेश के माध्यमों के नहीं।"},
  {"id":"cdp-child-development-953","question":"Asked which is greater, 0.25 or 0.5, most Class 5 children in a Bhopal school choose 0.25. What does this error most likely reveal and what should the teacher do?","options":["Carelessness; give a written warning to read the questions slowly","Poor memory; make them memorise that ‘0.5 is greater than 0.25’","Lack of intelligence; move them to an easier section for maths","Whole-number thinking; use grids or money models to compare decimals"],"answer":3,"explanation":"Such a widespread error is systematic: children apply a whole-number rule to decimals. Representations like 10×10 grids or ₹0.50 vs ₹0.25 help them see place value.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"यह पूछे जाने पर कि 0.25 और 0.5 में कौन-सा बड़ा है, भोपाल के एक विद्यालय में कक्षा 5 के अधिकांश बच्चे 0.25 चुनते हैं। यह त्रुटि सबसे संभवतः क्या प्रकट करती है और शिक्षक को क्या करना चाहिए?","optionsHi":["लापरवाही; प्रश्न धीरे पढ़ने की लिखित चेतावनी दें","कमज़ोर स्मृति; उन्हें रटवाएँ कि ‘0.5, 0.25 से बड़ा है’","बुद्धि की कमी; उन्हें गणित के लिए आसान अनुभाग में भेज दें","पूर्ण-संख्या चिंतन; दशमलवों की तुलना के लिए ग्रिड या पैसे के मॉडल प्रयोग करें"],"explanationHi":"ऐसी व्यापक त्रुटि व्यवस्थित होती है: बच्चे दशमलवों पर पूर्ण-संख्या का नियम लागू करते हैं। 10×10 ग्रिड या ₹0.50 बनाम ₹0.25 जैसे निरूपण उन्हें स्थानीय मान देखने में सहायता करते हैं।"},
  {"id":"cdp-child-development-954","question":"When asked to write ‘two hundred and five’, Class 2 student Sonu writes 2005. What is the most useful interpretation?","options":["He writes numbers as he hears them, not yet grasping place value","He has a visual processing disorder that reverses the digits","He is not paying attention and needs to be more careful","He has learnt the wrong number names from his family at home"],"answer":0,"explanation":"He records '200' and then '5' side by side as they sound. The error reveals a gap in understanding place value, which can be addressed with place-value cards and bundles of sticks.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"‘दो सौ पाँच’ लिखने को कहे जाने पर कक्षा 2 का विद्यार्थी सोनू 2005 लिखता है। सबसे उपयोगी व्याख्या क्या है?","optionsHi":["वह संख्याएँ वैसे ही लिखता है जैसे सुनता है, अभी स्थानीय मान को नहीं समझ पाया","उसे दृश्य-प्रसंस्करण विकार है जो अंकों को उलट देता है","वह ध्यान नहीं दे रहा और उसे अधिक सावधान होना चाहिए","उसने घर पर परिवार से गलत संख्या-नाम सीखे हैं"],"explanationHi":"वह ‘200’ और फिर ‘5’ को वैसे ही साथ-साथ लिखता है जैसे वे सुनाई देते हैं। त्रुटि स्थानीय मान की समझ में कमी दर्शाती है, जिसे स्थानीय-मान कार्डों और तीलियों के बंडलों से दूर किया जा सकता है।"},
  {"id":"cdp-child-development-955","question":"A four-year-old who earlier said ‘went’ and ‘mice’ correctly now says ‘goed’ and ‘mouses’. How should this be interpreted?","options":["As regression in language that needs speech therapy","As imitation of the speech of adults around the child","As overregularisation of a newly found grammar rule","As an early sign of a specific learning disability"],"answer":2,"explanation":"Children never hear adults say 'goed'; the error shows active rule construction (add -ed, add -s). It is a normal step before irregular forms are relearnt.","difficulty":"hard","source":"CTET · UPTET","questionHi":"चार वर्ष का एक बच्चा, जो पहले ‘went’ और ‘mice’ सही कहता था, अब ‘goed’ और ‘mouses’ कहता है। इसकी व्याख्या कैसे की जानी चाहिए?","optionsHi":["भाषा में प्रतिगमन के रूप में जिसके लिए वाणी-चिकित्सा चाहिए","बच्चे के आसपास के वयस्कों की वाणी की नकल के रूप में","एक नए पाए गए व्याकरण-नियम के अतिनियमितीकरण के रूप में","विशिष्ट अधिगम अक्षमता के आरंभिक संकेत के रूप में"],"explanationHi":"बच्चे वयस्कों को कभी ‘goed’ कहते नहीं सुनते; त्रुटि सक्रिय नियम-निर्माण दिखाती है (-ed जोड़ो, -s जोड़ो)। अनियमित रूपों को फिर से सीखने से पहले यह एक सामान्य कदम है।"},
  {"id":"cdp-child-development-956","question":"Many Class 6 students write 3/4 + 1/2 = 4/6. Which teacher response best treats the error as a window into thinking?","options":["Mark it wrong and ask them to do twenty more sums of the same kind","Repeat the rule for finding a common denominator, more slowly and loudly","Ask how they got 4/6, then check with fraction strips whether it can be right","Ignore it for now, since they will meet fraction addition again in Class 8"],"answer":2,"explanation":"Probing reveals the misconception (adding numerators and denominators as whole numbers). A concrete check shows that the sum must be greater than 3/4, creating cognitive conflict that motivates the correct method.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 के कई विद्यार्थी 3/4 + 1/2 = 4/6 लिखते हैं। किस शिक्षक-प्रतिक्रिया में त्रुटि को चिंतन की खिड़की के रूप में सबसे अच्छी तरह लिया गया है?","optionsHi":["उसे गलत अंकित करना और उसी प्रकार के बीस और प्रश्न करने को कहना","उभयनिष्ठ हर निकालने का नियम और धीरे तथा ज़ोर से दोहराना","पूछना कि उन्हें 4/6 कैसे मिला, फिर भिन्न-पट्टियों से जाँचना कि क्या यह सही हो सकता है","अभी इसे अनदेखा करना, क्योंकि उन्हें भिन्नों का जोड़ कक्षा 8 में फिर मिलेगा"],"explanationHi":"पड़ताल भ्रांति को प्रकट करती है (अंशों और हरों को पूर्ण संख्याओं की तरह जोड़ना)। मूर्त जाँच दिखाती है कि योग 3/4 से अधिक होना चाहिए, जो संज्ञानात्मक संघर्ष उत्पन्न करता है और सही विधि के लिए प्रेरित करता है।"},
  {"id":"cdp-child-development-957","question":"A Class 6 student predicts that 8 × 0.5 will be ‘more than 8’, and is puzzled when the answer is 4. Which misconception has she most likely formed, and from where?","options":["‘Decimals are always larger than whole numbers’, picked up from money","‘Multiplication always makes bigger’, overgeneralised from whole numbers","‘Zero is not really a number’, picked up from early counting","‘Division always makes bigger’, carried over from work with fractions"],"answer":1,"explanation":"With whole numbers greater than 1, multiplying always increased the result, so the child over-generalised. Multiplying by a number less than 1 gives a smaller result.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 6 की एक विद्यार्थी पूर्वानुमान करती है कि 8 × 0.5 ‘8 से अधिक’ होगा, और जब उत्तर 4 आता है तो उलझ जाती है। उसने सबसे संभवतः कौन-सी भ्रांति बनाई है, और कहाँ से?","optionsHi":["‘दशमलव सदैव पूर्ण संख्याओं से बड़े होते हैं’, पैसों से सीखी हुई","‘गुणा सदैव बड़ा बनाता है’, पूर्ण संख्याओं से अति-सामान्यीकृत","‘शून्य वास्तव में संख्या नहीं है’, आरंभिक गिनती से सीखी हुई","‘भाग सदैव बड़ा बनाता है’, भिन्नों के कार्य से आगे लाई हुई"],"explanationHi":"1 से बड़ी पूर्ण संख्याओं के साथ गुणा सदैव परिणाम बढ़ाता था, इसलिए बच्ची ने अति-सामान्यीकरण किया। 1 से कम संख्या से गुणा करने पर परिणाम छोटा आता है।"},
  {"id":"cdp-child-development-958","question":"In a Class 1 writing activity, Neeraj writes ‘I go to skool on my sykl.’ What is the most appropriate view of these spellings?","options":["They show he has failed to learn spelling and needs heavy correction in red","They point to a visual memory problem that needs a specialist","They should be ignored entirely, as spelling will sort itself out","Invented spellings that show growing sound awareness, to be built on"],"answer":3,"explanation":"Invented spellings map sounds to letters logically ('skool', 'sykl'), revealing phonemic knowledge. Teachers build on this while steadily introducing standard spellings.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 की लेखन गतिविधि में नीरज लिखता है ‘I go to skool on my sykl.’ इन वर्तनियों का सबसे उपयुक्त दृष्टिकोण क्या है?","optionsHi":["वे दिखाती हैं कि वह वर्तनी सीखने में विफल रहा है और उसे लाल स्याही से भारी सुधार चाहिए","वे दृश्य-स्मृति की समस्या की ओर संकेत करती हैं जिसके लिए विशेषज्ञ चाहिए","उन्हें पूरी तरह अनदेखा किया जाना चाहिए, क्योंकि वर्तनी अपने आप ठीक हो जाएगी","आविष्कृत वर्तनियाँ जो बढ़ती ध्वनि-जागरूकता दर्शाती हैं, जिन पर निर्माण किया जाना चाहिए"],"explanationHi":"आविष्कृत वर्तनियाँ ध्वनियों को अक्षरों से तार्किक रूप से जोड़ती हैं (‘skool’, ‘sykl’), जो ध्वनिग्राम-ज्ञान प्रकट करता है। शिक्षक इस पर निर्माण करते हुए मानक वर्तनियों को क्रमशः लाते हैं।"},
  {"id":"cdp-child-development-959","question":"Which of the following errors most deserves careful diagnostic follow-up by a teacher?","options":["A child who makes the same kind of mistake across many similar sums","A child who gets many sums wrong in one test, each with a different slip","A child who leaves the last few sums blank because the period ran out","A child who makes several errors in a test taken on a day she was unwell"],"answer":0,"explanation":"A consistent, repeated error points to one faulty rule or misconception that diagnosis can uncover and correct. Many errors of different kinds look more alarming but suggest haste or inattention rather than a single underlying misconception.","difficulty":"very-hard","source":"CTET Paper 1 · Super TET","questionHi":"निम्नलिखित में से किस त्रुटि पर शिक्षक द्वारा सावधान निदानात्मक अनुवर्ती कार्रवाई की सबसे अधिक आवश्यकता है?","optionsHi":["वह बच्चा जो अनेक समान प्रश्नों में एक ही प्रकार की गलती करता है","वह बच्चा जो एक परीक्षा में अनेक प्रश्न गलत करता है, प्रत्येक में भिन्न चूक के साथ","वह बच्चा जो अंतिम कुछ प्रश्न खाली छोड़ता है क्योंकि कालांश समाप्त हो गया","वह बच्चा जो उस दिन दी गई परीक्षा में कई त्रुटियाँ करता है जब वह अस्वस्थ थी"],"explanationHi":"एक संगत, दोहराई गई त्रुटि किसी एक दोषपूर्ण नियम या भ्रांति की ओर संकेत करती है जिसे निदान खोजकर सुधार सकता है। भिन्न प्रकार की अनेक त्रुटियाँ अधिक चिंताजनक दिखती हैं पर किसी एक अंतर्निहित भ्रांति के बजाय जल्दबाज़ी या असावधानी सुझाती हैं।"},
  {"id":"cdp-child-development-960","question":"According to the National Curriculum Framework 2005, which of these views of children's errors are correct? I. Errors are a natural part of the learning process. II. Errors can reveal how a child is thinking. III. Errors show that a child cannot learn the topic. IV. Teachers should use errors to plan further teaching rather than only penalise them.","options":["I and III only","II and III only","I, II and IV only","I, II, III and IV"],"answer":2,"explanation":"NCF 2005 describes errors as windows into children's thinking and encourages using them diagnostically. An error does not show inability to learn, so III is false.","difficulty":"moderate","source":"CTET · REET","questionHi":"राष्ट्रीय पाठ्यचर्या की रूपरेखा 2005 के अनुसार, बच्चों की त्रुटियों के इन दृष्टिकोणों में से कौन-से सही हैं? I. त्रुटियाँ अधिगम प्रक्रिया का स्वाभाविक भाग हैं। II. त्रुटियाँ प्रकट कर सकती हैं कि बच्चा कैसे सोच रहा है। III. त्रुटियाँ दिखाती हैं कि बच्चा विषय सीख नहीं सकता। IV. शिक्षकों को केवल दंडित करने के बजाय त्रुटियों का उपयोग आगे के शिक्षण की योजना बनाने में करना चाहिए।","optionsHi":["केवल I और III","केवल II और III","केवल I, II और IV","I, II, III और IV"],"explanationHi":"NCF 2005 त्रुटियों को बच्चों की सोच की खिड़कियाँ बताती है और उन्हें निदानात्मक रूप से उपयोग करने को प्रोत्साहित करती है। त्रुटि सीखने की असमर्थता नहीं दिखाती, इसलिए III असत्य है।"},
  {"id":"cdp-child-development-961","question":"Many Class 6 children say that plants get their food from the soil through their roots. What is the best way to address this alternative conception?","options":["Tell them they are wrong and dictate the definition of photosynthesis","Give a test on photosynthesis and deduct marks whenever the wrong idea appears","Avoid discussing it, since the topic will be repeated in Class 10","Explore their reasons and test the idea with plants kept in light and dark"],"answer":3,"explanation":"Alternative conceptions are reasonable to the child and resist mere telling. Making them explicit and testing them with evidence creates conflict that supports conceptual change.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 के कई बच्चे कहते हैं कि पौधे अपना भोजन जड़ों के माध्यम से मिट्टी से पाते हैं। इस वैकल्पिक धारणा को संबोधित करने का सबसे अच्छा तरीका क्या है?","optionsHi":["उन्हें बताना कि वे गलत हैं और प्रकाश-संश्लेषण की परिभाषा लिखवाना","प्रकाश-संश्लेषण पर परीक्षा देना और जब भी गलत विचार दिखे अंक काटना","इस पर चर्चा से बचना, क्योंकि विषय कक्षा 10 में दोहराया जाएगा","उनके कारणों की पड़ताल करना और प्रकाश तथा अँधेरे में रखे पौधों से विचार की परख करना"],"explanationHi":"वैकल्पिक धारणाएँ बच्चे को तर्कसंगत लगती हैं और केवल बता देने से नहीं हटतीं। उन्हें स्पष्ट करना और प्रमाणों से परखना संघर्ष उत्पन्न करता है जो संप्रत्ययात्मक परिवर्तन का समर्थन करता है।"},
  {"id":"cdp-child-development-962","question":"Class 3 student Fatima says, ‘The moon changes shape because clouds cover different parts of it.’ What should the teacher do first?","options":["Ask her reasoning, then have the class observe the moon for a month","Correct her immediately so that others don't pick up the wrong idea","Tell her the topic is beyond her age and will come in later classes","Praise her creativity warmly and move on to the next question"],"answer":0,"explanation":"Her idea is a reasoned explanation from experience. Understanding the reasoning and providing observation that challenges it helps her reconstruct a better explanation.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की विद्यार्थी फ़ातिमा कहती है, ‘चाँद का आकार इसलिए बदलता है क्योंकि बादल उसके अलग-अलग भागों को ढक लेते हैं।’ शिक्षक को सबसे पहले क्या करना चाहिए?","optionsHi":["उसके तर्क के बारे में पूछना, फिर कक्षा से एक महीने तक चाँद का अवलोकन कराना","उसे तुरंत सुधारना ताकि दूसरे गलत विचार न अपनाएँ","उसे बताना कि विषय उसकी आयु से परे है और बाद की कक्षाओं में आएगा","उसकी रचनात्मकता की गर्मजोशी से प्रशंसा करके अगले प्रश्न पर बढ़ जाना"],"explanationHi":"उसका विचार अनुभव से किया गया तर्कसंगत स्पष्टीकरण है। तर्क को समझना और उसे चुनौती देने वाला अवलोकन उपलब्ध कराना उसे बेहतर व्याख्या पुनर्निर्मित करने में सहायता करता है।"},
  {"id":"cdp-child-development-963","question":"Match each factor affecting learning with its category. P. Maturation of fine motor muscles  Q. Noise from a nearby construction site  R. Use of activity-based methods  S. Test anxiety. 1. Environmental  2. Instructional (teacher-related)  3. Learner-related physical  4. Learner-related psychological","options":["P-3, Q-2, R-1, S-4","P-3, Q-1, R-2, S-4","P-4, Q-1, R-2, S-3","P-1, Q-3, R-2, S-4"],"answer":1,"explanation":"Motor maturation is a physical factor in the learner; outside noise is environmental; teaching method is instructional; anxiety is a psychological factor in the learner.","difficulty":"moderate","source":"CTET · DSSSB PRT","questionHi":"अधिगम को प्रभावित करने वाले प्रत्येक कारक का मिलान उसकी श्रेणी से कीजिए। P. सूक्ष्म गामक पेशियों की परिपक्वता  Q. पास के निर्माण-स्थल का शोर  R. गतिविधि-आधारित विधियों का उपयोग  S. परीक्षा-चिंता। 1. पर्यावरणीय  2. अनुदेशनात्मक (शिक्षक-संबंधी)  3. अधिगमकर्ता-संबंधी शारीरिक  4. अधिगमकर्ता-संबंधी मनोवैज्ञानिक","optionsHi":["P-3, Q-2, R-1, S-4","P-3, Q-1, R-2, S-4","P-4, Q-1, R-2, S-3","P-1, Q-3, R-2, S-4"],"explanationHi":"गामक परिपक्वता अधिगमकर्ता का शारीरिक कारक है; बाहरी शोर पर्यावरणीय है; शिक्षण-विधि अनुदेशनात्मक है; चिंता अधिगमकर्ता का मनोवैज्ञानिक कारक है।"},
  {"id":"cdp-child-development-964","question":"Parents of a three-year-old insist on daily practice in joined-up (cursive) writing, but the child cannot form the letters despite weeks of drill. The most accurate explanation is that:","options":["The child lacks motivation and needs rewards for each attempt","The child has a learning disability such as dysgraphia","Fine motor control is not yet mature, and drill cannot replace readiness","Cursive writing is not taught in Indian schools, so it confuses the child"],"answer":2,"explanation":"Learning depends on maturation: skills that need certain neuromuscular development cannot be produced by drill before that development has taken place.","difficulty":"hard","source":"CTET Paper 1 · Super TET","questionHi":"तीन वर्ष के बच्चे के माता-पिता जुड़े हुए (कर्सिव) लेखन के दैनिक अभ्यास पर ज़ोर देते हैं, पर सप्ताहों के अभ्यास के बावजूद बच्चा अक्षर नहीं बना पाता। सबसे सटीक व्याख्या है कि:","optionsHi":["बच्चे में अभिप्रेरणा की कमी है और उसे प्रत्येक प्रयास पर पुरस्कार चाहिए","बच्चे में डिस्ग्राफिया जैसी अधिगम अक्षमता है","सूक्ष्म गामक नियंत्रण अभी परिपक्व नहीं है, और अभ्यास तत्परता का विकल्प नहीं हो सकता","भारतीय विद्यालयों में कर्सिव लेखन नहीं पढ़ाया जाता, इसलिए वह बच्चे को भ्रमित करता है"],"explanationHi":"अधिगम परिपक्वता पर निर्भर करता है: जिन कौशलों के लिए निश्चित तंत्रिका-पेशीय विकास चाहिए, वे उस विकास के होने से पहले अभ्यास द्वारा उत्पन्न नहीं किए जा सकते।"},
  {"id":"cdp-child-development-965","question":"A student who has learnt to ride a bicycle finds it easier to learn to ride a scooter, but a driver used to driving on the left in India keeps drifting to the wrong side when driving abroad on the right. These are examples of:","options":["Negative transfer and positive transfer respectively","Zero transfer in both cases","Bilateral transfer and zero transfer","Positive transfer and negative transfer respectively"],"answer":3,"explanation":"Earlier learning that helps new learning (balance on bicycle to scooter) is positive transfer; earlier learning that interferes with new learning (left-side habit) is negative transfer.","difficulty":"moderate","source":"CTET · UPTET","questionHi":"जिस विद्यार्थी ने साइकिल चलाना सीख लिया है उसे स्कूटर चलाना सीखना आसान लगता है, पर भारत में बाईं ओर चलाने का अभ्यस्त एक चालक दाईं ओर चलाने वाले विदेश में गाड़ी चलाते समय गलत ओर बहकता रहता है। ये क्रमशः किसके उदाहरण हैं?","optionsHi":["क्रमशः ऋणात्मक अंतरण और धनात्मक अंतरण","दोनों मामलों में शून्य अंतरण","द्विपक्षीय अंतरण और शून्य अंतरण","क्रमशः धनात्मक अंतरण और ऋणात्मक अंतरण"],"explanationHi":"पहले का अधिगम जो नए अधिगम में सहायक है (साइकिल का संतुलन स्कूटर के लिए) धनात्मक अंतरण है; पहले का अधिगम जो नए अधिगम में बाधा डालता है (बाईं ओर की आदत) ऋणात्मक अंतरण है।"},
  {"id":"cdp-child-development-966","question":"In Judd's classic study, two groups of boys practised throwing darts at a target under water. Only one group was taught the principle of refraction. When the depth of the target was changed, that group adjusted much faster. Which theory of transfer does this support?","options":["Generalisation: transfer occurs when learners grasp an underlying principle","Identical elements: transfer occurs only with identical stimuli and responses","Formal discipline: any hard practice trains the mind","Law of disuse"],"answer":0,"explanation":"Judd's theory of generalisation holds that understanding general principles enables transfer to new situations, which the refraction group showed when conditions changed.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"जड के क्लासिक अध्ययन में, लड़कों के दो समूहों ने पानी के नीचे एक लक्ष्य पर डार्ट फेंकने का अभ्यास किया। केवल एक समूह को अपवर्तन का सिद्धांत सिखाया गया। जब लक्ष्य की गहराई बदली गई, तो उस समूह ने बहुत तेज़ी से समायोजन किया। यह अंतरण के किस सिद्धांत का समर्थन करता है?","optionsHi":["सामान्यीकरण: अंतरण तब होता है जब अधिगमकर्ता अंतर्निहित सिद्धांत समझते हैं","समान तत्व: अंतरण केवल समान उद्दीपकों और अनुक्रियाओं के साथ होता है","औपचारिक अनुशासन: कोई भी कठिन अभ्यास मन को प्रशिक्षित करता है","अनुपयोग का नियम"],"explanationHi":"जड का सामान्यीकरण सिद्धांत मानता है कि सामान्य सिद्धांतों की समझ नई स्थितियों में अंतरण को संभव बनाती है, जो अपवर्तन वाले समूह ने परिस्थितियाँ बदलने पर दिखाया।"},
  {"id":"cdp-child-development-967","question":"A principal argues that every child should study hard grammar and geometry because ‘they train the mind's faculties of memory and reasoning, which will then improve every other subject’. This reflects which theory, and what is its status?","options":["Theory of identical elements, which is widely accepted by researchers","Formal discipline, which Thorndike's experiments largely failed to support","Gestalt theory of transposition, which has been fully proven in classrooms","Theory of generalisation, which says any study improves all faculties"],"answer":1,"explanation":"Formal discipline treats the mind as muscles trained by tough subjects. Thorndike's studies found little general improvement; transfer depends on shared elements or principles.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक प्रधानाचार्य तर्क देता है कि प्रत्येक बच्चे को कठिन व्याकरण और ज्यामिति पढ़नी चाहिए क्योंकि ‘वे मन की स्मृति और तर्क की क्षमताओं को प्रशिक्षित करते हैं, जो फिर हर अन्य विषय को सुधारेंगी’। यह किस सिद्धांत को दर्शाता है, और उसकी स्थिति क्या है?","optionsHi":["समान तत्वों का सिद्धांत, जो शोधकर्ताओं द्वारा व्यापक रूप से स्वीकृत है","औपचारिक अनुशासन, जिसे थॉर्नडाइक के प्रयोग बड़े पैमाने पर समर्थित नहीं कर पाए","गेस्टाल्ट का स्थानांतरण सिद्धांत, जो कक्षाओं में पूर्णतः सिद्ध हो चुका है","सामान्यीकरण का सिद्धांत, जो कहता है कि कोई भी अध्ययन सभी क्षमताओं को सुधारता है"],"explanationHi":"औपचारिक अनुशासन मन को पेशियों की तरह मानता है जो कठिन विषयों से प्रशिक्षित होती हैं। थॉर्नडाइक के अध्ययनों में बहुत कम सामान्य सुधार मिला; अंतरण साझा तत्वों या सिद्धांतों पर निर्भर करता है।"},
  {"id":"cdp-child-development-968","question":"Which teaching practice is most likely to promote transfer of learning to new situations?","options":["Practising one type of example many times in exactly the same form","Teaching facts in isolation and testing them word for word for accuracy","Teaching principles and practising them in varied, real-life contexts","Avoiding discussion of how a concept applies outside the textbook"],"answer":2,"explanation":"Transfer is helped by understanding principles, varied practice and explicit links to new contexts; narrow, identical practice tends to produce knowledge tied to one setting.","difficulty":"hard","source":"CTET · HTET","questionHi":"कौन-सी शिक्षण प्रथा अधिगम के नई स्थितियों में अंतरण को बढ़ावा देने की सबसे अधिक संभावना रखती है?","optionsHi":["एक ही प्रकार के उदाहरण का ठीक उसी रूप में कई बार अभ्यास करना","तथ्यों को अलग-थलग पढ़ाना और सटीकता के लिए उन्हें शब्दशः परखना","सिद्धांत पढ़ाना और उनका विविध, वास्तविक जीवन संदर्भों में अभ्यास कराना","इस पर चर्चा से बचना कि कोई संप्रत्यय पाठ्यपुस्तक के बाहर कैसे लागू होता है"],"explanationHi":"अंतरण सिद्धांतों की समझ, विविध अभ्यास और नए संदर्भों से स्पष्ट संबंधों से सहायता पाता है; संकीर्ण, समान अभ्यास एक ही परिवेश से बँधे ज्ञान को जन्म देता है।"},
  {"id":"cdp-child-development-969","question":"Many children in a tribal block of Madhya Pradesh who speak Bhili at home struggle in Class 1 lessons taught only in English. Which factor affecting learning is most directly involved, and what do NCF 2005 and NEP 2020 recommend?","options":["Low intelligence; place them in remedial classes until they catch up","Lack of parental interest; hold parent meetings to motivate the families","Poor eyesight; arrange eye check-ups for all children in the class","Home–school language mismatch; use the home language in early years"],"answer":3,"explanation":"Learning is hindered when instruction is in a language the child does not understand. Both NCF 2005 and NEP 2020 recommend the home language or mother tongue as medium in the early years where possible.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"मध्य प्रदेश के एक जनजातीय खंड में घर पर भीली बोलने वाले कई बच्चे केवल अंग्रेज़ी में पढ़ाए जाने वाले कक्षा 1 के पाठों में संघर्ष करते हैं। अधिगम को प्रभावित करने वाला कौन-सा कारक सबसे सीधे शामिल है, और NCF 2005 तथा NEP 2020 क्या अनुशंसा करती हैं?","optionsHi":["निम्न बुद्धि; उन्हें तब तक उपचारात्मक कक्षाओं में रखें जब तक वे बराबरी पर न आ जाएँ","अभिभावकों की रुचि का अभाव; परिवारों को प्रेरित करने के लिए अभिभावक-बैठकें करें","कमज़ोर नज़र; कक्षा के सभी बच्चों के लिए नेत्र-जाँच की व्यवस्था करें","घर–विद्यालय की भाषा का बेमेल; आरंभिक वर्षों में घर की भाषा का उपयोग करें"],"explanationHi":"जब शिक्षण ऐसी भाषा में होता है जिसे बच्चा नहीं समझता तो अधिगम बाधित होता है। NCF 2005 और NEP 2020 दोनों आरंभिक वर्षों में जहाँ संभव हो घर की भाषा या मातृभाषा को माध्यम बनाने की अनुशंसा करती हैं।"},
  {"id":"cdp-child-development-970","question":"Rekha understands percentages well at home but freezes in maths tests, making errors she would not otherwise make. Research suggests that maths anxiety mainly harms performance by:","options":["Filling working memory with worry, leaving less room for the problem","Erasing what is stored in long-term memory about percentages and rules","Lowering the child's measured intelligence permanently over time","Raising her speed so much that accuracy drops a little"],"answer":0,"explanation":"Anxious, intrusive thoughts compete for limited working memory, so complex problems suffer most; the knowledge itself is still present, as her performance at home shows.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"रेखा घर पर प्रतिशत भली-भाँति समझती है पर गणित की परीक्षाओं में जम जाती है, ऐसी त्रुटियाँ करती है जो वह अन्यथा नहीं करती। शोध सुझाता है कि गणित-चिंता मुख्यतः निष्पादन को इस प्रकार हानि पहुँचाती है:","optionsHi":["कार्यकारी स्मृति को चिंता से भरकर, जिससे समस्या के लिए कम स्थान बचता है","प्रतिशतों और नियमों के बारे में दीर्घकालिक स्मृति में संचित को मिटाकर","समय के साथ बच्चे की मापी गई बुद्धि को स्थायी रूप से घटाकर","उसकी गति को इतना बढ़ाकर कि सटीकता थोड़ी गिर जाए"],"explanationHi":"चिंताजनक, अनधिकार विचार सीमित कार्यकारी स्मृति के लिए प्रतिस्पर्धा करते हैं, इसलिए जटिल प्रश्न सबसे अधिक प्रभावित होते हैं; ज्ञान स्वयं अब भी मौजूद है, जैसा घर पर उसके निष्पादन से दिखता है।"},
  {"id":"cdp-child-development-971","question":"After weeks of practising writing with his right hand, a student finds that his left-hand writing has also improved somewhat, though he never practised with it. This is called:","options":["Negative transfer","Zero transfer","Retroactive interference","Bilateral transfer"],"answer":3,"explanation":"Bilateral transfer is transfer of a skill from one side of the body to the other, showing that some of what is learnt is central rather than tied to a particular limb.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"अपने दाएँ हाथ से लिखने के सप्ताहों के अभ्यास के बाद एक विद्यार्थी पाता है कि उसके बाएँ हाथ का लेखन भी कुछ सुधर गया है, यद्यपि उसने उससे कभी अभ्यास नहीं किया। इसे क्या कहते हैं?","optionsHi":["ऋणात्मक अंतरण","शून्य अंतरण","पश्चोन्मुख व्यवधान","द्विपक्षीय अंतरण"],"explanationHi":"द्विपक्षीय अंतरण शरीर के एक ओर से दूसरी ओर कौशल का अंतरण है, जो दर्शाता है कि जो सीखा गया उसका कुछ भाग केंद्रीय है, किसी विशेष अंग से बँधा नहीं।"},
  {"id":"cdp-child-development-972","question":"Several Class 2 children in a Bihar school become drowsy and inattentive by mid-morning. A health check finds many are anaemic. Which statement best captures the link to learning?","options":["Anaemia affects only physical growth, not attention or learning","Health and nutrition directly affect attention, energy and learning","Drowsiness shows that the children are not interested in studies","The teacher should give more homework to improve concentration"],"answer":1,"explanation":"Health and nutrition, including iron deficiency, affect alertness and cognitive functioning. Addressing them, for example through the mid-day meal and supplementation, supports learning.","difficulty":"moderate","source":"CTET · REET","questionHi":"बिहार के एक विद्यालय में कक्षा 2 के कई बच्चे सुबह के मध्य तक ऊँघने लगते और असावधान हो जाते हैं। स्वास्थ्य जाँच में पाया जाता है कि कई रक्ताल्पता से ग्रस्त हैं। अधिगम से संबंध को कौन-सा कथन सबसे अच्छी तरह पकड़ता है?","optionsHi":["रक्ताल्पता केवल शारीरिक वृद्धि को प्रभावित करती है, ध्यान या अधिगम को नहीं","स्वास्थ्य और पोषण ध्यान, ऊर्जा और अधिगम को सीधे प्रभावित करते हैं","ऊँघना दर्शाता है कि बच्चों की पढ़ाई में रुचि नहीं है","एकाग्रता सुधारने के लिए शिक्षक को अधिक गृहकार्य देना चाहिए"],"explanationHi":"स्वास्थ्य और पोषण, जिसमें लौह की कमी भी शामिल है, सतर्कता और संज्ञानात्मक कार्यप्रणाली को प्रभावित करते हैं। इन्हें संबोधित करना, जैसे मध्याह्न भोजन और पूरकता से, अधिगम का समर्थन करता है।"},
  {"id":"cdp-child-development-973","question":"Parents of a Class 1 child with a benchmark disability want her to study in their neighbourhood school. The school insists that she ‘belongs in a special school’. Which position matches the RPwD Act, 2016?","options":["The family chooses: a neighbourhood school or a special school, free of cost","The school decides, since it knows best what support it can give her","A medical board must decide which type of school she attends","She may attend the neighbourhood school only if her disability is below 60%"],"answer":0,"explanation":"The Act gives every child with a benchmark disability aged 6–18 the right to free education in a neighbourhood school or a special school of her choice, so the school cannot push her out.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"बेंचमार्क दिव्यांगता वाली कक्षा 1 की एक बच्ची के अभिभावक चाहते हैं कि वह उनके पड़ोस के विद्यालय में पढ़े। विद्यालय आग्रह करता है कि वह ‘विशेष विद्यालय की है’। RPwD अधिनियम, 2016 से कौन-सी स्थिति मेल खाती है?","optionsHi":["परिवार चुनता है: निःशुल्क पड़ोस का विद्यालय या विशेष विद्यालय","विद्यालय निर्णय करता है, क्योंकि वह सबसे अच्छी तरह जानता है कि वह उसे कैसी सहायता दे सकता है","एक चिकित्सा बोर्ड तय करे कि वह किस प्रकार के विद्यालय में पढ़ेगी","वह पड़ोस के विद्यालय में तभी पढ़ सकती है जब उसकी दिव्यांगता 60% से कम हो"],"explanationHi":"अधिनियम 6–18 आयु के बेंचमार्क दिव्यांगता वाले प्रत्येक बच्चे को पड़ोस के विद्यालय या अपनी पसंद के विशेष विद्यालय में निःशुल्क शिक्षा का अधिकार देता है, इसलिए विद्यालय उसे बाहर नहीं धकेल सकता।"},
  {"id":"cdp-child-development-974","question":"To ‘build his confidence’, a Class 4 teacher makes Karan, who has dyslexia, read a new passage aloud in front of the class every day. He now pretends to be ill on reading days. What would be a better practice?","options":["Letting him preview and practise the passage, and join choral reading","Continuing daily public reading, since avoidance must not be rewarded","Stopping all reading practice for him until he feels ready","Asking classmates to correct each error aloud so that he learns faster"],"answer":0,"explanation":"Unprepared public reading exposes a child's disability and creates anxiety and avoidance; preparation, private practice and choral reading build fluency without humiliation.","difficulty":"hard","source":"CTET · State TETs","questionHi":"‘उसका आत्मविश्वास बढ़ाने’ के लिए कक्षा 4 का शिक्षक डिस्लेक्सिया वाले करण से प्रतिदिन कक्षा के सामने एक नया गद्यांश ज़ोर से पढ़वाता है। अब वह पठन के दिनों पर बीमार होने का बहाना बनाता है। बेहतर प्रथा क्या होगी?","optionsHi":["उसे गद्यांश पहले देखने और अभ्यास करने देना, और समवेत पठन में शामिल करना","प्रतिदिन सार्वजनिक पठन जारी रखना, क्योंकि परिहार को पुरस्कृत नहीं किया जाना चाहिए","जब तक वह तैयार न हो उसके लिए सारा पठन-अभ्यास रोक देना","सहपाठियों से प्रत्येक त्रुटि को ज़ोर से सुधारने को कहना ताकि वह तेज़ी से सीखे"],"explanationHi":"बिना तैयारी का सार्वजनिक पठन बच्चे की अक्षमता को उजागर करता है और चिंता तथा परिहार उत्पन्न करता है; तैयारी, निजी अभ्यास और समवेत पठन अपमान के बिना प्रवाह बनाते हैं।"},
  {"id":"cdp-child-development-975","question":"Sameer, in Class 6, stammers. When he answers, classmates giggle and the teacher often completes his sentences to save time. Which teacher behaviour is most appropriate?","options":["Waiting calmly for him to finish, and addressing the giggling with the class","Telling him each time to slow down and take a deep breath before he speaks","Avoiding asking him questions in class so that he is not embarrassed","Finishing his words for him, so that he is not left stuck in front of others"],"answer":0,"explanation":"Patient, natural listening reduces pressure on a child who stammers; repeated advice to slow down, finishing his words or never asking him all signal that his speech is a problem and reduce participation.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 6 का समीर हकलाता है। जब वह उत्तर देता है तो सहपाठी हँसते हैं और शिक्षक समय बचाने के लिए प्रायः उसके वाक्य पूरे कर देता है। शिक्षक का कौन-सा व्यवहार सबसे उपयुक्त है?","optionsHi":["उसके समाप्त करने तक शांति से प्रतीक्षा करना, और कक्षा के साथ हँसी की बात संबोधित करना","हर बार उससे कहना कि बोलने से पहले धीमा हो जाए और गहरी साँस ले","कक्षा में उससे प्रश्न पूछने से बचना ताकि वह शर्मिंदा न हो","उसके शब्द उसके लिए पूरे कर देना, ताकि वह दूसरों के सामने अटका न रह जाए"],"explanationHi":"धैर्यपूर्ण, स्वाभाविक श्रवण हकलाने वाले बच्चे पर दबाव घटाता है; धीमा होने की बार-बार सलाह, उसके शब्द पूरे करना या उससे कभी न पूछना, सब संकेत देते हैं कि उसकी वाणी एक समस्या है और भागीदारी घटाते हैं।"},
  {"id":"cdp-child-development-976","question":"Which of these statements about hearing aids in the classroom are correct? I. A hearing aid restores normal hearing, just as glasses restore clear vision. II. Hearing aids amplify background noise too, so classroom noise control matters. III. A child with hearing aids should be seated away from noisy fans, windows facing the road and corridors.","options":["II and III only","I and II only","I and III only","All of I, II and III"],"answer":0,"explanation":"Hearing aids amplify sound but do not restore normal hearing, and they make background noise louder too; so seating away from noise and keeping the room quiet are essential.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा में श्रवण यंत्रों के बारे में इनमें से कौन-से कथन सही हैं? I. श्रवण यंत्र सामान्य श्रवण वापस लाता है, जैसे चश्मा स्पष्ट दृष्टि लौटाता है। II. श्रवण यंत्र पृष्ठभूमि के शोर को भी बढ़ाते हैं, इसलिए कक्षा के शोर पर नियंत्रण महत्त्वपूर्ण है। III. श्रवण यंत्र वाले बच्चे को शोर वाले पंखों, सड़क की ओर खुलने वाली खिड़कियों और गलियारों से दूर बैठाना चाहिए।","optionsHi":["केवल II और III","केवल I और II","केवल I और III","I, II और III सभी"],"explanationHi":"श्रवण यंत्र ध्वनि को बढ़ाते हैं पर सामान्य श्रवण नहीं लौटाते, और वे पृष्ठभूमि के शोर को भी तेज़ करते हैं; इसलिए शोर से दूर बैठाना और कक्ष को शांत रखना आवश्यक है।"},
  {"id":"cdp-child-development-977","question":"Asked about an elephant, Ravi, a blind Class 3 student, gives a fluent description copied from a story (‘huge, grey, with a trunk like a snake’), but on questioning he has no real idea of its size or shape. This is called verbalism. What is the best remedy?","options":["Making him memorise more precise definitions of each animal","Giving him hands-on experience with models and real objects","Avoiding topics about things he cannot touch for himself","Asking him to stop using colour words he cannot understand"],"answer":1,"explanation":"Verbalism is using words without the underlying experience; blind children need concrete, tactile and real experiences so that concepts have meaning, not more memorised descriptions.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"हाथी के बारे में पूछे जाने पर कक्षा 3 का दृष्टिबाधित विद्यार्थी रवि एक कहानी से उतारा हुआ धाराप्रवाह वर्णन देता है (‘विशाल, भूरा, साँप जैसी सूँड़ वाला’), पर पूछताछ करने पर उसे उसके आकार या आकृति का कोई वास्तविक विचार नहीं है। इसे शब्दाडंबर (वर्बलिज़्म) कहते हैं। सबसे अच्छा उपचार क्या है?","optionsHi":["उसे प्रत्येक पशु की अधिक सटीक परिभाषाएँ रटवाना","उसे मॉडलों और वास्तविक वस्तुओं के साथ हाथ से करने का अनुभव देना","उन विषयों से बचना जिन्हें वह स्वयं छूकर नहीं जान सकता","उसे उन रंग-शब्दों का प्रयोग बंद करने को कहना जिन्हें वह समझ नहीं सकता"],"explanationHi":"शब्दाडंबर अंतर्निहित अनुभव के बिना शब्दों का प्रयोग है; दृष्टिबाधित बच्चों को मूर्त, स्पर्शीय और वास्तविक अनुभव चाहिए ताकि संप्रत्ययों का अर्थ हो, अधिक रटे हुए वर्णन नहीं।"},
  {"id":"cdp-child-development-978","question":"Parents of Bunty, a 9-year-old with intellectual disability, dress him, feed him and carry his bag, saying ‘he cannot do it’. In school he waits for adults to do everything. What should the teacher do?","options":["Continue doing tasks for him in school too, since that is what he is used to","Report the parents to the authorities for overprotecting their child","Teach self-help skills step by step, and have parents practise them at home","Leave him alone to struggle so that he learns through failure"],"answer":2,"explanation":"Overprotection can produce learned helplessness; systematic teaching of self-help skills, shared with the family for consistency, builds independence.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"बौद्धिक अक्षमता वाले 9 वर्ष के बंटी के माता-पिता उसे कपड़े पहनाते हैं, खिलाते हैं और उसका बस्ता उठाते हैं, यह कहकर कि ‘वह नहीं कर सकता’। विद्यालय में वह वयस्कों के सब कुछ करने की प्रतीक्षा करता है। शिक्षक को क्या करना चाहिए?","optionsHi":["विद्यालय में भी उसके लिए कार्य करते रहना, क्योंकि वह उसका अभ्यस्त है","माता-पिता की अपने बच्चे के अति-संरक्षण के लिए अधिकारियों को शिकायत करना","स्व-सहायता कौशल चरण-दर-चरण सिखाना, और माता-पिता से घर पर उनका अभ्यास कराना","उसे अकेला छोड़ देना ताकि वह असफलता से सीखे"],"explanationHi":"अति-संरक्षण सीखी हुई असहायता उत्पन्न कर सकता है; स्व-सहायता कौशलों की व्यवस्थित शिक्षा, संगति के लिए परिवार के साथ साझा, स्वतंत्रता बनाती है।"},
  {"id":"cdp-child-development-979","question":"Aditi, in Class 4, solves Class 7 level mathematics but is emotionally young and is happy with friends of her age. Which provision is most suitable for her?","options":["Subject acceleration or enrichment in maths, staying with age-peers otherwise","Promoting her straight to Class 7 in all subjects, to match her maths level","Giving her more Class 4 sums to keep her busy and practised","Waiting until she is older and more mature before offering any challenge"],"answer":0,"explanation":"Her advanced ability is in one subject and she is socially young; subject-specific acceleration or enrichment meets her need without the social cost of a full grade skip.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 4 की अदिति कक्षा 7 स्तर का गणित हल करती है पर भावनात्मक रूप से छोटी है और अपनी आयु के मित्रों के साथ प्रसन्न है। उसके लिए कौन-सा प्रावधान सबसे उपयुक्त है?","optionsHi":["गणित में विषय-त्वरण या संवर्धन, अन्यथा आयु-साथियों के साथ रहना","उसके गणित-स्तर से मेल खाने के लिए सभी विषयों में सीधे कक्षा 7 में प्रोन्नत करना","उसे व्यस्त और अभ्यस्त रखने के लिए कक्षा 4 के और प्रश्न देना","कोई भी चुनौती देने से पहले उसके बड़े और अधिक परिपक्व होने तक प्रतीक्षा करना"],"explanationHi":"उसकी उन्नत क्षमता एक विषय में है और वह सामाजिक रूप से छोटी है; विषय-विशिष्ट त्वरण या संवर्धन पूरी कक्षा लाँघने की सामाजिक कीमत के बिना उसकी आवश्यकता पूरी करता है।"},
  {"id":"cdp-child-development-980","question":"Asked how a city could reduce traffic jams, a Class 6 student suggests staggering school and office timings. The teacher marks it wrong because the textbook lists only ‘build flyovers’ and ‘use public transport’. What is the main concern?","options":["The student should have copied the textbook answer as given","The teacher should give zero marks to discourage guessing in exams","Such answers should be accepted only from toppers who know the basics","Rejecting a sound, original answer discourages divergent thinking"],"answer":3,"explanation":"Creative and gifted learners often give valid answers outside the book; treating only textbook answers as correct suppresses originality.","difficulty":"hard","source":"CTET · State TETs","questionHi":"यह पूछे जाने पर कि कोई शहर यातायात जाम कैसे घटा सकता है, कक्षा 6 का एक विद्यार्थी विद्यालयों और कार्यालयों के समय अलग-अलग करने का सुझाव देता है। शिक्षक उसे गलत अंकित करता है क्योंकि पाठ्यपुस्तक में केवल ‘फ़्लाईओवर बनाओ’ और ‘सार्वजनिक परिवहन प्रयोग करो’ सूचीबद्ध हैं। मुख्य चिंता क्या है?","optionsHi":["विद्यार्थी को पाठ्यपुस्तक का उत्तर जैसा दिया है वैसा उतारना चाहिए था","शिक्षक को शून्य अंक देने चाहिए ताकि परीक्षाओं में अनुमान लगाना हतोत्साहित हो","ऐसे उत्तर केवल उन अव्वल विद्यार्थियों से स्वीकार किए जाने चाहिए जो मूल बातें जानते हैं","किसी सही, मौलिक उत्तर को अस्वीकार करना अपसारी चिंतन को हतोत्साहित करता है"],"explanationHi":"रचनात्मक और प्रतिभाशाली अधिगमकर्ता प्रायः पुस्तक से बाहर के वैध उत्तर देते हैं; केवल पाठ्यपुस्तक के उत्तरों को सही मानना मौलिकता को दबाता है।"},
  {"id":"cdp-child-development-981","question":"Which statement correctly describes the relationship between Universal Design for Learning (UDL) and differentiated instruction (DI)?","options":["They are the same thing, simply described under different names","UDL is used only for students with disabilities, DI only for the gifted","UDL builds in options for all at planning; DI responds to known students","DI replaces UDL once the teacher has got to know her students well"],"answer":2,"explanation":"UDL is proactive design for learner variability, and DI is responsive adjustment for known students; good teachers use both, for all learners.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"अधिगम के सार्वभौमिक अभिकल्प (UDL) और विभेदित अनुदेशन (DI) के बीच के संबंध का कौन-सा कथन सही वर्णन करता है?","optionsHi":["वे एक ही चीज़ हैं, बस अलग नामों से वर्णित","UDL केवल अक्षमता वाले विद्यार्थियों के लिए प्रयुक्त होता है, DI केवल प्रतिभाशाली विद्यार्थियों के लिए","UDL नियोजन के समय सभी के लिए विकल्प बनाता है; DI ज्ञात विद्यार्थियों के प्रति अनुक्रिया करता है","शिक्षक द्वारा अपने विद्यार्थियों को भली-भाँति जान लेने के बाद DI, UDL का स्थान ले लेता है"],"explanationHi":"UDL अधिगमकर्ता-विविधता के लिए पूर्वसक्रिय अभिकल्प है, और DI ज्ञात विद्यार्थियों के लिए अनुक्रियात्मक समायोजन; अच्छे शिक्षक दोनों का प्रयोग सभी अधिगमकर्ताओं के लिए करते हैं।"},
  {"id":"cdp-child-development-982","question":"In a school examination, Arjun, who is blind, is given a scribe. While writing, the scribe rephrases Arjun’s answers into better language and adds a point Arjun missed. Which statement is correct?","options":["This is acceptable, since the scribe is only helping Arjun express his ideas better","The scribe must write exactly what Arjun dictates, adding or improving nothing","The scribe should write only the main points, to save examination time","This is acceptable as long as the teacher is informed about it later"],"answer":1,"explanation":"A scribe removes the barrier of writing, not of knowing; adding or improving content changes what is being assessed and is unfair to the candidate and others.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक विद्यालयी परीक्षा में दृष्टिबाधित अर्जुन को लेखक (स्क्राइब) दिया गया है। लिखते समय लेखक अर्जुन के उत्तरों को बेहतर भाषा में पुनः व्यक्त करता है और एक ऐसा बिंदु जोड़ देता है जो अर्जुन से छूट गया था। कौन-सा कथन सही है?","optionsHi":["यह स्वीकार्य है, क्योंकि लेखक केवल अर्जुन को अपने विचार बेहतर व्यक्त करने में सहायता कर रहा है","लेखक को ठीक वही लिखना चाहिए जो अर्जुन बोलकर लिखवाए, कुछ जोड़े या सुधारे बिना","लेखक को परीक्षा-समय बचाने के लिए केवल मुख्य बिंदु लिखने चाहिए","यह तब तक स्वीकार्य है जब तक शिक्षक को बाद में इसकी सूचना दे दी जाए"],"explanationHi":"लेखक लिखने की बाधा हटाता है, जानने की नहीं; विषय-वस्तु जोड़ना या सुधारना जिसका आकलन हो रहा है उसे बदल देता है और परीक्षार्थी तथा अन्य के प्रति अनुचित है।"},
  {"id":"cdp-child-development-983","question":"A Class 2 teacher promises Rohit, who has ADHD, a reward at the end of the month if he stays in his seat. The plan fails. Which change is most likely to work?","options":["Making the reward bigger and keeping it at the end of the month","Removing all rewards, since they spoil children and lower effort","Small, immediate rewards after each short task, gradually spaced out","Punishing him each time he leaves his seat, so he learns the rule"],"answer":2,"explanation":"Children with ADHD find delayed rewards hard to work for; immediate, frequent reinforcement shapes behaviour, after which reinforcement can be thinned.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 2 की एक शिक्षिका ADHD वाले रोहित से वादा करती है कि यदि वह अपनी सीट पर बैठा रहा तो माह के अंत में उसे पुरस्कार मिलेगा। योजना विफल हो जाती है। कौन-सा परिवर्तन सबसे संभवतः कारगर होगा?","optionsHi":["पुरस्कार को बड़ा करना और माह के अंत में ही रखना","सभी पुरस्कार हटा देना, क्योंकि वे बच्चों को बिगाड़ते हैं और प्रयास घटाते हैं","प्रत्येक छोटे कार्य के बाद छोटे, तत्काल पुरस्कार, जिन्हें क्रमशः अंतराल पर किया जाए","उसके सीट छोड़ने पर हर बार उसे दंडित करना ताकि वह नियम सीखे"],"explanationHi":"ADHD वाले बच्चों को विलंबित पुरस्कारों के लिए काम करना कठिन लगता है; तत्काल, बार-बार का पुनर्बलन व्यवहार को आकार देता है, जिसके बाद पुनर्बलन को घटाया जा सकता है।"},
  {"id":"cdp-child-development-984","question":"Kiran, a Class 1 child with autism, refuses writing tasks but loves building blocks. The teacher shows a card with two pictures: ‘First: writing → Then: blocks’. Why does this strategy work?","options":["It punishes him for refusing to do the writing task","It removes the writing task from his day altogether","It is a form of acceleration for an able learner","It is visual and uses a liked activity to motivate"],"answer":3,"explanation":"A ‘first–then’ board gives clear visual structure and links a non-preferred task to a preferred one (the Premack principle), which suits many autistic learners.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 1 का ऑटिज़्म से ग्रस्त बच्चा किरण लेखन के कार्यों से मना करता है पर निर्माण-ब्लॉक से प्रेम करता है। शिक्षिका दो चित्रों वाला कार्ड दिखाती है: ‘पहले: लिखना → फिर: ब्लॉक’। यह युक्ति क्यों काम करती है?","optionsHi":["यह उसे लेखन-कार्य करने से इनकार के लिए दंडित करती है","यह लेखन-कार्य को उसके दिन से पूरी तरह हटा देती है","यह एक सक्षम अधिगमकर्ता के लिए त्वरण का रूप है","यह दृश्य है और प्रेरित करने के लिए पसंदीदा गतिविधि का उपयोग करती है"],"explanationHi":"‘पहले–फिर’ पटल स्पष्ट दृश्य संरचना देता है और अप्रिय कार्य को प्रिय कार्य से जोड़ता है (प्रीमैक सिद्धांत), जो अनेक ऑटिस्टिक अधिगमकर्ताओं के अनुकूल है।"},
  {"id":"cdp-child-development-985","question":"Which of these statements about autism are correct? I. Autism is caused by cold, unaffectionate parenting. II. Autism is a spectrum, so autistic children differ widely from one another. III. Many autistic children have uneven profiles, with strong skills in some areas. IV. Childhood vaccines cause autism.","options":["I and II only","II and III only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"The spectrum and uneven profiles are well established; the ‘cold parenting’ and vaccine claims are myths rejected by research.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"ऑटिज़्म के बारे में इनमें से कौन-से कथन सही हैं? I. ऑटिज़्म ठंडे, स्नेहहीन पालन-पोषण से होता है। II. ऑटिज़्म एक स्पेक्ट्रम है, इसलिए ऑटिस्टिक बच्चे एक-दूसरे से बहुत भिन्न होते हैं। III. अनेक ऑटिस्टिक बच्चों की प्रोफ़ाइल असमान होती है, कुछ क्षेत्रों में प्रबल कौशल के साथ। IV. बचपन के टीके ऑटिज़्म का कारण बनते हैं।","optionsHi":["केवल I और II","केवल II और III","केवल II, III और IV","I, II, III और IV"],"explanationHi":"स्पेक्ट्रम और असमान प्रोफ़ाइल सुस्थापित हैं; ‘ठंडे पालन-पोषण’ और टीके के दावे मिथक हैं जिन्हें शोध अस्वीकार करता है।"},
  {"id":"cdp-child-development-986","question":"Durga, a Class 5 girl with low vision, belongs to a Scheduled Tribe and lives in a remote hamlet far from school. Her teacher plans support only for her vision. What is the main weakness of this plan?","options":["It ignores how distance, gender, language and poverty add to her disability","It gives her too much support compared with other children in the class","Disability support is not a teacher’s job but a specialist’s","Children from tribal communities need no special support beyond what others get"],"answer":0,"explanation":"Disadvantages overlap and compound; a girl with a disability from a marginalised, remote community needs support for transport, language and social barriers too, not just vision.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 5 की अल्प-दृष्टि वाली बालिका दुर्गा अनुसूचित जनजाति से है और विद्यालय से बहुत दूर एक दूरस्थ बस्ती में रहती है। उसकी शिक्षिका केवल उसकी दृष्टि के लिए सहायता की योजना बनाती है। इस योजना की मुख्य कमज़ोरी क्या है?","optionsHi":["यह अनदेखा करती है कि दूरी, जेंडर, भाषा और गरीबी उसकी अक्षमता के साथ मिलकर कठिनाइयाँ कैसे बढ़ाते हैं","यह उसे कक्षा के अन्य बच्चों की तुलना में बहुत अधिक सहायता देती है","अक्षमता-सहायता शिक्षक का काम नहीं बल्कि विशेषज्ञ का है","जनजातीय समुदायों के बच्चों को दूसरों को मिलने वाली सहायता के अतिरिक्त किसी विशेष सहायता की आवश्यकता नहीं"],"explanationHi":"वंचनाएँ परस्पर जुड़ती और बढ़ती हैं; हाशिये के, दूरस्थ समुदाय की अक्षमता वाली बालिका को केवल दृष्टि के लिए नहीं, परिवहन, भाषा और सामाजिक बाधाओं के लिए भी सहायता चाहिए।"},
  {"id":"cdp-child-development-987","question":"Teacher P gives every child the same book and the same 20 minutes for a reading task. Teacher Q gives the same book to all, but adds a large-print copy for a child with low vision, extra time for a child with dyslexia and a picture glossary for a new Hindi learner. Which statement is correct?","options":["P is fair and Q is unfair, since Q treats the children differently","Both are equally fair, since all children get the very same book","Both are unfair, since no child should ever get extra help","P gives equality of treatment; Q gives equity of support"],"answer":3,"explanation":"Equality gives everyone the same; equity adjusts support so that every child has a fair chance to reach the shared goal, which is the basis of inclusion.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"शिक्षक P प्रत्येक बच्चे को पठन-कार्य के लिए वही पुस्तक और वही 20 मिनट देता है। शिक्षक Q सभी को वही पुस्तक देता है, पर अल्प-दृष्टि वाले बच्चे के लिए बड़े अक्षरों की प्रति, डिस्लेक्सिया वाले बच्चे के लिए अतिरिक्त समय और हिंदी सीख रहे नए बच्चे के लिए चित्र-शब्दावली जोड़ता है। कौन-सा कथन सही है?","optionsHi":["P निष्पक्ष है और Q अनुचित, क्योंकि Q बच्चों से भिन्न व्यवहार करता है","दोनों समान रूप से निष्पक्ष हैं, क्योंकि सभी बच्चों को बिल्कुल वही पुस्तक मिलती है","दोनों अनुचित हैं, क्योंकि किसी बच्चे को कभी अतिरिक्त सहायता नहीं मिलनी चाहिए","P व्यवहार की समानता देता है; Q सहायता की समता (इक्विटी) देता है"],"explanationHi":"समानता सभी को वही देती है; समता सहायता को इस प्रकार समायोजित करती है कि प्रत्येक बच्चे को साझा लक्ष्य तक पहुँचने का उचित अवसर मिले, जो समावेशन का आधार है।"},
  {"id":"cdp-child-development-988","question":"Rani, from a village in Bihar, speaks Hindi with Bhojpuri features. Her teacher often says in class, ‘That is wrong Hindi; speak properly.’ What is the most appropriate view?","options":["The teacher is right, because dialects are incorrect forms of the language","Rani should be asked to stop speaking in class until her Hindi improves","Respect her rule-governed dialect and add standard Hindi alongside it","The teacher should switch to teaching only in Bhojpuri for her sake"],"answer":2,"explanation":"Calling a child's home speech ‘wrong’ hurts identity and participation; dialects follow their own rules, and standard forms are best added alongside them.","difficulty":"hard","source":"CTET · State TETs","questionHi":"बिहार के एक गाँव की रानी भोजपुरी विशेषताओं वाली हिंदी बोलती है। उसकी शिक्षिका कक्षा में प्रायः कहती है, ‘यह गलत हिंदी है; ठीक से बोलो।’ सबसे उपयुक्त दृष्टिकोण क्या है?","optionsHi":["शिक्षिका सही है, क्योंकि बोलियाँ भाषा के गलत रूप हैं","रानी को तब तक कक्षा में बोलना बंद करने को कहना चाहिए जब तक उसकी हिंदी सुधर न जाए","उसकी नियम-शासित बोली का सम्मान करना और उसके साथ मानक हिंदी जोड़ना","शिक्षिका को उसकी खातिर केवल भोजपुरी में पढ़ाने पर आ जाना चाहिए"],"explanationHi":"बच्चे की घरेलू वाणी को ‘गलत’ कहना पहचान और भागीदारी को चोट पहुँचाता है; बोलियाँ अपने नियमों का पालन करती हैं, और मानक रूपों को उनके साथ जोड़ना सबसे अच्छा है।"},
  {"id":"cdp-child-development-989","question":"Many parents of first-generation learners in a school are daily-wage workers who never attend parent–teacher meetings held at 11 a.m. on working days. Teachers conclude that ‘these parents don’t care’. Which step is most appropriate?","options":["Sending more written circulars insisting that the parents attend","Meeting at flexible times, visiting homes, and talking rather than writing","Stopping communication with these parents until they show interest","Reporting low attendance at meetings in the children’s report cards"],"answer":1,"explanation":"The barrier is timing and literacy, not lack of care; flexible scheduling and oral or face-to-face contact make partnership possible.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"एक विद्यालय में प्रथम-पीढ़ी के अधिगमकर्ताओं के अनेक माता-पिता दिहाड़ी मज़दूर हैं जो कार्य-दिवसों में सुबह 11 बजे होने वाली अभिभावक–शिक्षक बैठकों में कभी नहीं आते। शिक्षक निष्कर्ष निकालते हैं कि ‘इन अभिभावकों को परवाह नहीं’। कौन-सा कदम सबसे उपयुक्त है?","optionsHi":["अभिभावकों के उपस्थित होने पर बल देने वाले और अधिक लिखित परिपत्र भेजना","लचीले समय पर मिलना, घरों पर जाना, और लिखने के बजाय बात करना","इन अभिभावकों से तब तक संवाद बंद करना जब तक वे रुचि न दिखाएँ","बच्चों के रिपोर्ट कार्ड में बैठकों में कम उपस्थिति की सूचना देना"],"explanationHi":"बाधा समय और साक्षरता की है, परवाह की कमी नहीं; लचीला कार्यक्रम और मौखिक या आमने-सामने का संपर्क साझेदारी को संभव बनाता है।"},
  {"id":"cdp-child-development-990","question":"Many children in a Class 5 class live in one-room homes in a nearby slum and have no space or light to study in the evening. Which school-level step is most helpful?","options":["Giving them more homework so that they get used to studying at home","Opening a school room for supervised study after school hours","Advising parents to buy study tables and lamps for their children","Lowering expectations for these children in tests and homework"],"answer":1,"explanation":"Providing a space to study removes a concrete barrier created by poverty; more homework or lower expectations would only widen the gap.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 5 की एक कक्षा के कई बच्चे पास की झुग्गी में एक-कमरे के घरों में रहते हैं और शाम को पढ़ने के लिए उनके पास स्थान या रोशनी नहीं है। विद्यालय-स्तर का कौन-सा कदम सबसे अधिक सहायक है?","optionsHi":["उन्हें अधिक गृहकार्य देना ताकि वे घर पर पढ़ने के अभ्यस्त हो जाएँ","विद्यालय समय के बाद पर्यवेक्षित अध्ययन के लिए विद्यालय का एक कमरा खोलना","अभिभावकों को सलाह देना कि वे अपने बच्चों के लिए अध्ययन-मेज़ और लैंप खरीदें","इन बच्चों के लिए परीक्षाओं और गृहकार्य में अपेक्षाएँ घटाना"],"explanationHi":"पढ़ने के लिए स्थान देना गरीबी से उत्पन्न ठोस बाधा को दूर करता है; अधिक गृहकार्य या कम अपेक्षाएँ केवल अंतर को बढ़ाएँगी।"},
  {"id":"cdp-child-development-991","question":"A Class 6 teacher notices that she mostly calls on the same few ‘bright’ students and moves on quickly when others hesitate. Which practice best makes her questioning equitable?","options":["Picking students at random, e.g. with name sticks, and giving all wait time","Asking only those who raise their hands, so no one feels pressured","Asking low achievers only easy recall questions to build their confidence","Giving the bright students harder questions so that the rest can listen and learn"],"answer":0,"explanation":"Random selection and adequate wait time signal that every student is expected to think and answer; taking only volunteers or easy questions for some lowers expectations.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 6 की एक शिक्षिका देखती है कि वह प्रायः उन्हीं कुछ ‘होशियार’ विद्यार्थियों को बुलाती है और जब अन्य हिचकिचाते हैं तो जल्दी आगे बढ़ जाती है। कौन-सी प्रथा उसके प्रश्न पूछने को सबसे अच्छी तरह समतापूर्ण बनाती है?","optionsHi":["विद्यार्थियों को यादृच्छिक रूप से चुनना, जैसे नाम-पर्चियों से, और सभी को प्रतीक्षा-समय देना","केवल उन्हीं से पूछना जो हाथ उठाएँ, ताकि किसी पर दबाव न पड़े","कमज़ोर विद्यार्थियों से केवल आसान स्मरण-प्रश्न पूछना ताकि उनका आत्मविश्वास बने","होशियार विद्यार्थियों को कठिन प्रश्न देना ताकि बाकी सुनकर सीखें"],"explanationHi":"यादृच्छिक चयन और पर्याप्त प्रतीक्षा-समय संकेत देते हैं कि प्रत्येक विद्यार्थी से सोचने और उत्तर देने की अपेक्षा है; केवल स्वयंसेवकों या कुछ के लिए आसान प्रश्न लेने से अपेक्षाएँ घटती हैं।"},
  {"id":"cdp-child-development-992","question":"For the annual day drama, a Class 5 teacher gives Hari, who is blind, only a singing role, explaining that ‘blind people are naturally musical’. How should this be judged?","options":["It is appropriate, since it makes good use of his natural gift","It is appropriate, since blind children cannot act on a stage safely","It is acceptable, provided Hari agrees to sing rather than act","It is a ‘positive’ stereotype; his own interests should decide the role"],"answer":3,"explanation":"Assuming a talent because of a disability is still stereotyping; a blind child can act with orientation and cues, and his own interest should decide his role.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"वार्षिक दिवस के नाटक के लिए कक्षा 5 की एक शिक्षिका दृष्टिबाधित हरि को केवल गायन की भूमिका देती है, यह समझाते हुए कि ‘नेत्रहीन लोग स्वाभाविक रूप से संगीतप्रेमी होते हैं’। इसे कैसे आँका जाना चाहिए?","optionsHi":["यह उपयुक्त है, क्योंकि यह उसकी स्वाभाविक प्रतिभा का अच्छा उपयोग करता है","यह उपयुक्त है, क्योंकि दृष्टिबाधित बच्चे मंच पर सुरक्षित रूप से अभिनय नहीं कर सकते","यह स्वीकार्य है, बशर्ते हरि अभिनय के बजाय गाने पर सहमत हो","यह एक ‘सकारात्मक’ रूढ़िबद्ध धारणा है; भूमिका उसकी अपनी रुचियों से तय होनी चाहिए"],"explanationHi":"अक्षमता के कारण किसी प्रतिभा को मान लेना भी रूढ़िबद्धता है; दृष्टिबाधित बच्चा अभिविन्यास और संकेतों के साथ अभिनय कर सकता है, और उसकी भूमिका उसकी अपनी रुचि से तय होनी चाहिए।"},
  {"id":"cdp-child-development-993","question":"Some parents learn that a Class 3 child is living with HIV and demand that he be removed from the class. What should the school do?","options":["Remove the child quietly to avoid conflict with other parents","Seat the child separately and give him his own utensils, as a precaution","Keep him in class, keep it confidential, and correct the parents’ fears","Ask the child’s parents to move him to another school for his own good"],"answer":2,"explanation":"HIV does not spread through sharing classrooms, play or food, and the law prohibits discrimination in education against persons living with HIV; separating him would be discrimination.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कुछ अभिभावकों को पता चलता है कि कक्षा 3 का एक बच्चा HIV के साथ जी रहा है और वे माँग करते हैं कि उसे कक्षा से हटाया जाए। विद्यालय को क्या करना चाहिए?","optionsHi":["अन्य अभिभावकों से टकराव से बचने के लिए बच्चे को चुपचाप हटा देना","बच्चे को अलग बैठाना और एहतियात के तौर पर उसे अपने बर्तन देना","उसे कक्षा में रखना, इसे गोपनीय रखना और अभिभावकों के भय को सुधारना","बच्चे के माता-पिता से उसके अपने भले के लिए उसे किसी अन्य विद्यालय में ले जाने को कहना"],"explanationHi":"HIV कक्षाएँ, खेल या भोजन साझा करने से नहीं फैलता, और कानून शिक्षा में HIV के साथ जी रहे व्यक्तियों के प्रति भेदभाव को निषिद्ध करता है; उसे अलग करना भेदभाव होगा।"},
  {"id":"cdp-child-development-994","question":"Bablu, a Class 4 child with epilepsy, has a seizure during class, falling and jerking. What should the teacher do?","options":["Hold his limbs firmly to stop the jerking and prevent injury","Cushion his head, turn him on his side, and put nothing in his mouth","Put a spoon in his mouth so that he does not bite his tongue","Splash water on his face to bring him round as quickly as possible"],"answer":1,"explanation":"Safe seizure first aid protects the child from injury and keeps the airway clear; restraining him or putting objects in the mouth can cause harm.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 4 के मिर्गी वाले बच्चे बबलू को कक्षा के दौरान दौरा पड़ता है, वह गिर जाता है और उसे झटके आते हैं। शिक्षक को क्या करना चाहिए?","optionsHi":["झटके रोकने और चोट से बचाने के लिए उसके अंगों को कसकर पकड़ना","उसके सिर के नीचे गद्दी रखना, उसे करवट दिलाना और मुँह में कुछ न डालना","जीभ काटने से बचाने के लिए उसके मुँह में चम्मच डालना","उसे जल्दी से होश में लाने के लिए उसके चेहरे पर पानी के छींटे मारना"],"explanationHi":"दौरे की सुरक्षित प्राथमिक चिकित्सा बच्चे को चोट से बचाती है और वायुमार्ग साफ़ रखती है; उसे जकड़ना या मुँह में वस्तुएँ डालना हानि पहुँचा सकता है।"},
  {"id":"cdp-child-development-995","question":"To teach Neeraj, a child with intellectual disability, to tie his shoelaces, the teacher first does every step herself except the last, which Neeraj completes; then she leaves the last two steps to him, and so on. This technique is called:","options":["Forward chaining","Shaping","Fading of prompts","Backward chaining"],"answer":3,"explanation":"Backward chaining teaches the final step first, so the child always completes the task and experiences success; forward chaining starts with the first step.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"बौद्धिक अक्षमता वाले बच्चे नीरज को जूते के फीते बाँधना सिखाने के लिए शिक्षिका पहले अंतिम चरण को छोड़कर हर चरण स्वयं करती है, जिसे नीरज पूरा करता है; फिर वह अंतिम दो चरण उस पर छोड़ती है, और इसी तरह आगे। इस तकनीक को क्या कहते हैं?","optionsHi":["अग्र शृंखलन (फ़ॉरवर्ड चेनिंग)","आकार-निर्धारण (शेपिंग)","संकेतों का क्रमिक हटाना (फ़ेडिंग)","पश्च शृंखलन (बैकवर्ड चेनिंग)"],"explanationHi":"पश्च शृंखलन पहले अंतिम चरण सिखाता है, ताकि बच्चा सदैव कार्य पूरा करे और सफलता का अनुभव करे; अग्र शृंखलन पहले चरण से शुरू होता है।"},
  {"id":"cdp-child-development-996","question":"Assertion (A): When students in a Class 7 project choose different products, such as a model, a skit or a report, the teacher should assess all of them against the same learning goals. Reason (R): The product is only a means of showing learning; the learning outcome is what is being assessed.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Choice of product is a differentiation of how learning is shown; a common rubric tied to the learning goals keeps assessment fair across different products.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): जब कक्षा 7 की परियोजना में विद्यार्थी भिन्न उत्पाद चुनते हैं, जैसे मॉडल, नुक्कड़ नाटिका या रिपोर्ट, तो शिक्षक को सभी का आकलन समान अधिगम लक्ष्यों के विरुद्ध करना चाहिए। कारण (R): उत्पाद केवल अधिगम दिखाने का माध्यम है; अधिगम-परिणाम ही आकलन का विषय है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"उत्पाद का चुनाव इस बात का विभेदन है कि अधिगम कैसे दिखाया जाए; अधिगम लक्ष्यों से जुड़ा साझा रूब्रिक भिन्न उत्पादों में आकलन को निष्पक्ष रखता है।"},
  {"id":"cdp-child-development-997","question":"In a Class 4 class in Assam with Bodo, Assamese and Bengali speakers, the teacher puts up a science word wall showing each new term in all three languages, along with pictures. What is the main benefit of this practice?","options":["It lets the teacher avoid teaching the standard scientific terms","It is useful only for children who are weak in their studies","It uses home languages as resources to link new terms to known words","It slows down learning, since children get confused by multiple languages"],"answer":2,"explanation":"Using several languages visibly values every child's language and helps concept learning; multilingualism is a resource, not a source of confusion.","difficulty":"moderate","source":"CTET · KVS · DSSSB","questionHi":"असम में बोडो, असमिया और बांग्ला भाषियों वाली कक्षा 4 में शिक्षक विज्ञान की शब्द-दीवार लगाता है जिसमें प्रत्येक नया पद तीनों भाषाओं में चित्रों के साथ दिखाया जाता है। इस प्रथा का मुख्य लाभ क्या है?","optionsHi":["यह शिक्षक को मानक वैज्ञानिक पद पढ़ाने से बचने देती है","यह केवल उन बच्चों के लिए उपयोगी है जो पढ़ाई में कमज़ोर हैं","यह घरेलू भाषाओं को संसाधन के रूप में प्रयोग कर नए पदों को ज्ञात शब्दों से जोड़ती है","यह अधिगम को धीमा करती है, क्योंकि बच्चे अनेक भाषाओं से भ्रमित हो जाते हैं"],"explanationHi":"अनेक भाषाओं का दिखाई देने वाला प्रयोग प्रत्येक बच्चे की भाषा को महत्त्व देता है और संप्रत्यय-अधिगम में सहायता करता है; बहुभाषिकता एक संसाधन है, भ्रम का स्रोत नहीं।"},
  {"id":"cdp-child-development-998","question":"In a Class 5 lesson on fractions, which activity draws MAINLY on interpersonal intelligence in Gardner’s sense?","options":["Students sort fraction cards into equivalent groups on their own","In pairs, students argue out which fraction is larger until they agree","Students fold paper strips to make halves, quarters and eighths","Students write a short reflection on what they found confusing today"],"answer":1,"explanation":"Interpersonal intelligence concerns understanding and working with others; pair explanation and resolving disagreements uses it most. Folding draws on spatial and bodily skills, and private reflection on intrapersonal intelligence.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"भिन्नों पर कक्षा 5 के पाठ में कौन-सी गतिविधि मुख्यतः गार्डनर के अर्थ में अंतर्वैयक्तिक बुद्धि का उपयोग करती है?","optionsHi":["विद्यार्थी भिन्न-कार्डों को अपने आप तुल्य समूहों में छाँटते हैं","जोड़ियों में, विद्यार्थी बहस करते हैं कि कौन-सा भिन्न बड़ा है जब तक वे सहमत न हों","विद्यार्थी कागज़ की पट्टियाँ मोड़कर आधे, चौथाई और आठवें भाग बनाते हैं","विद्यार्थी आज उन्हें क्या भ्रमित करने वाला लगा इस पर एक संक्षिप्त चिंतन लिखते हैं"],"explanationHi":"अंतर्वैयक्तिक बुद्धि दूसरों को समझने और उनके साथ काम करने से संबंधित है; जोड़ी में समझाना और असहमतियाँ सुलझाना उसका सबसे अधिक उपयोग करते हैं। मोड़ना स्थानिक और शारीरिक कौशलों पर, और निजी चिंतन अंतःवैयक्तिक बुद्धि पर निर्भर है।"},
  {"id":"cdp-child-development-999","question":"Gardner defines an intelligence as a biopsychological potential to process information that can be activated in a cultural setting to solve problems or create products that are valued in a culture. Which part of this definition most clearly departs from the traditional IQ view?","options":["The idea that intelligence involves processing information of many kinds","The idea that intelligence has a biological basis in the brain","The idea that it includes creating products valued in a culture","The idea that intelligence can be measured by a single number"],"answer":2,"explanation":"Traditional IQ views focus on solving test problems and largely ignore cultural context; Gardner’s inclusion of culturally valued products (a song, a map, a crafted object) is the key departure. The last option is the traditional view itself.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"गार्डनर बुद्धि को सूचना-प्रसंस्करण की एक जैव-मनोवैज्ञानिक क्षमता के रूप में परिभाषित करते हैं जिसे किसी सांस्कृतिक परिवेश में समस्याएँ सुलझाने या ऐसे उत्पाद रचने के लिए सक्रिय किया जा सकता है जो किसी संस्कृति में मूल्यवान हों। इस परिभाषा का कौन-सा भाग पारंपरिक IQ दृष्टि से सबसे स्पष्ट रूप से भिन्न है?","optionsHi":["यह विचार कि बुद्धि में अनेक प्रकार की जानकारी का प्रसंस्करण शामिल है","यह विचार कि बुद्धि का मस्तिष्क में जैविक आधार है","यह विचार कि उसमें किसी संस्कृति में मूल्यवान उत्पाद रचना शामिल है","यह विचार कि बुद्धि को एक ही संख्या से मापा जा सकता है"],"explanationHi":"पारंपरिक IQ दृष्टि परीक्षण-समस्याएँ हल करने पर केंद्रित है और सांस्कृतिक संदर्भ की काफ़ी हद तक उपेक्षा करती है; गार्डनर का सांस्कृतिक रूप से मूल्यवान उत्पादों (गीत, मानचित्र, शिल्प-वस्तु) को शामिल करना मुख्य विचलन है। अंतिम विकल्प स्वयं पारंपरिक दृष्टि है।"},
  {"id":"cdp-child-development-1000","question":"A Bharatanatyam student in Chennai performs a dance-drama that tells a story from the Ramayana, keeping rhythm with the music, moving across the stage space and expressing the characters’ emotions. In Gardner’s framework, this is best described as:","options":["Pure bodily-kinaesthetic intelligence, with no other intelligence involved","An activity that mainly shows logical-mathematical intelligence at work","Evidence that one general intelligence controls all of her performance","Several intelligences working together, e.g. bodily, musical, spatial"],"answer":3,"explanation":"Gardner stresses that intelligences are relatively independent but usually work in combination in real tasks; a dance-drama blends movement, rhythm, use of space and understanding of characters.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"चेन्नई की एक भरतनाट्यम की विद्यार्थी रामायण की एक कथा सुनाने वाला नृत्य-नाटक प्रस्तुत करती है, संगीत के साथ लय बनाए रखती है, मंच के स्थान में गति करती है और पात्रों की भावनाएँ व्यक्त करती है। गार्डनर की रूपरेखा में इसका सबसे अच्छा वर्णन है:","optionsHi":["शुद्ध शारीरिक-गतिबोधक बुद्धि, जिसमें कोई अन्य बुद्धि शामिल नहीं","एक गतिविधि जो मुख्यतः तार्किक-गणितीय बुद्धि को कार्य करता दिखाती है","इस बात का प्रमाण कि एक सामान्य बुद्धि उसके सारे निष्पादन को नियंत्रित करती है","अनेक बुद्धियों का साथ मिलकर काम करना, जैसे शारीरिक, संगीतात्मक, स्थानिक"],"explanationHi":"गार्डनर बल देते हैं कि बुद्धियाँ अपेक्षाकृत स्वतंत्र हैं पर वास्तविक कार्यों में प्रायः संयोजन में काम करती हैं; नृत्य-नाटक गति, लय, स्थान के उपयोग और पात्रों की समझ को मिलाता है।"},
  {"id":"cdp-child-development-1001","question":"Following Gardner’s idea of ‘intelligence-fair’ assessment, which is the most suitable way to assess a Class 4 child’s spatial intelligence?","options":["Ask her to find a spot in the school using a sketch map, or build a model from a picture","Ask her to write a detailed paragraph describing the layout of her house and the street outside","Give her a multiple-choice vocabulary test on the names and properties of shapes","Ask her to recite the eight directions in order and explain each one aloud"],"answer":0,"explanation":"Gardner argued that intelligences should be assessed through their own medium rather than through language and logic; reading a map or building from a picture taps spatial ability directly.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"गार्डनर के ‘बुद्धि-निष्पक्ष’ आकलन के विचार के अनुसार, कक्षा 4 की किसी बालिका की स्थानिक बुद्धि का आकलन करने का सबसे उपयुक्त तरीका कौन-सा है?","optionsHi":["उससे रेखाचित्र वाले नक्शे की सहायता से विद्यालय में कोई स्थान ढूँढ़ने को कहना, या चित्र देखकर कोई मॉडल बनाने को कहना","उससे अपने घर और बाहर की गली की बनावट का वर्णन करते हुए एक विस्तृत अनुच्छेद लिखने को कहना","उसे आकृतियों के नामों और गुणों पर बहुविकल्पीय शब्दावली परीक्षण देना","उससे आठ दिशाओं को क्रम से सुनाने और हर एक को ज़ोर से समझाने को कहना"],"explanationHi":"गार्डनर का तर्क था कि बुद्धियों का आकलन भाषा और तर्क के बजाय उनके अपने माध्यम से होना चाहिए; नक्शा पढ़ना या चित्र देखकर कुछ बनाना सीधे स्थानिक योग्यता को परखता है।"},
  {"id":"cdp-child-development-1002","question":"Bhanwar, 13, from a village near Jaisalmer, sells handicrafts to tourists, bargains skilfully in three languages and keeps accurate accounts, yet scores below average on a standard IQ test. According to Sternberg, the most likely reason is that:","options":["His real intelligence is low, and the bargaining skill is merely a habit picked up through repetition","Conventional IQ tests mainly tap analytical ability and miss the practical intelligence he uses daily","IQ tests mainly measure creative intelligence, and his trade relies on routine rather than creativity","He has high emotional intelligence, and strong emotional skills tend to pull IQ scores down"],"answer":1,"explanation":"Sternberg argued that IQ tests concentrate on analytical problems with one right answer and neglect practical (and creative) intelligence, which predicts success in everyday contexts.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"जैसलमेर के पास के एक गाँव का 13 वर्षीय भँवर पर्यटकों को हस्तशिल्प बेचता है, तीन भाषाओं में कुशलता से मोलभाव करता है और हिसाब-किताब सही रखता है, फिर भी मानक IQ परीक्षण में औसत से कम अंक पाता है। स्टर्नबर्ग के अनुसार इसका सबसे संभावित कारण है कि:","optionsHi":["उसकी वास्तविक बुद्धि कम है, और मोलभाव का कौशल केवल दोहराव से सीखी गई आदत है","परंपरागत IQ परीक्षण मुख्यतः विश्लेषणात्मक योग्यता को मापते हैं और उस व्यावहारिक बुद्धि को नहीं पकड़ पाते जिसका वह रोज़ उपयोग करता है","IQ परीक्षण मुख्यतः सृजनात्मक बुद्धि को मापते हैं, और उसका व्यापार सृजनात्मकता के बजाय नियमित कार्य पर निर्भर है","उसकी भावनात्मक बुद्धि उच्च है, और प्रबल भावनात्मक कौशल IQ अंकों को घटा देते हैं"],"explanationHi":"स्टर्नबर्ग का तर्क था कि IQ परीक्षण एक सही उत्तर वाली विश्लेषणात्मक समस्याओं पर केंद्रित होते हैं और व्यावहारिक (तथा सृजनात्मक) बुद्धि की उपेक्षा करते हैं, जो रोज़मर्रा के संदर्भों में सफलता का पूर्वानुमान देती है।"},
  {"id":"cdp-child-development-1003","question":"A newly appointed teacher in a Shillong school gradually learns, without anyone telling her directly, how to talk to anxious parents, which senior colleague to approach for leave and how to calm a restless class after lunch. Sternberg would call this kind of unspoken, experience-based know-how:","options":["Crystallised intelligence","Metacomponents","Tacit knowledge","Convergent thinking"],"answer":2,"explanation":"Sternberg’s research on practical intelligence highlights tacit knowledge: action-oriented knowledge acquired from experience, usually not formally taught or even put into words.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"शिलांग के एक विद्यालय में नियुक्त हुई एक नई शिक्षिका बिना किसी के सीधे बताए धीरे-धीरे सीख जाती है कि चिंतित अभिभावकों से कैसे बात करनी है, छुट्टी के लिए किस वरिष्ठ सहकर्मी के पास जाना है और भोजनावकाश के बाद बेचैन कक्षा को कैसे शांत करना है। स्टर्नबर्ग इस प्रकार के अनकहे, अनुभव-आधारित व्यावहारिक ज्ञान को क्या कहेंगे?","optionsHi":["मूर्त बुद्धि (क्रिस्टलीकृत बुद्धि)","मेटा-घटक","अंतर्निहित ज्ञान (टैसिट नॉलेज)","अभिसारी चिंतन"],"explanationHi":"स्टर्नबर्ग का व्यावहारिक बुद्धि पर शोध अंतर्निहित ज्ञान को रेखांकित करता है: यह क्रिया-उन्मुख ज्ञान है जो अनुभव से प्राप्त होता है और प्रायः न औपचारिक रूप से सिखाया जाता है, न शब्दों में कहा जाता है।"},
  {"id":"cdp-child-development-1004","question":"Assertion (A): When Thurstone’s primary mental abilities were tested in larger groups, the abilities were found to be positively correlated with one another. Reason (R): Such correlations among abilities lend some support to the existence of a general factor of intelligence.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true: the primary abilities did correlate, and Thurstone accepted a second-order general factor. But R is a conclusion drawn from A, not the explanation of why A happened.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"अभिकथन (A): जब थर्स्टन की प्राथमिक मानसिक योग्यताओं का परीक्षण बड़े समूहों में किया गया, तो पाया गया कि योग्यताएँ एक-दूसरे से धनात्मक रूप से सहसंबद्ध थीं। कारण (R): योग्यताओं के बीच ऐसे सहसंबंध बुद्धि के किसी सामान्य कारक के अस्तित्व का कुछ समर्थन करते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं: प्राथमिक योग्यताएँ सहसंबद्ध थीं और थर्स्टन ने द्वितीय-क्रम के एक सामान्य कारक को स्वीकार किया। परंतु R, A से निकला निष्कर्ष है, यह नहीं बताता कि A क्यों हुआ।"},
  {"id":"cdp-child-development-1005","question":"Which statement about the relation between IQ and school achievement is most accurate?","options":["IQ scores predict school marks almost perfectly, so other factors add very little to the prediction","IQ and school achievement are unrelated, since marks depend only on effort and teaching","IQ is the only factor that schools need to consider when grouping and guiding students","IQ correlates moderately with achievement, so motivation, teaching and home support also matter"],"answer":3,"explanation":"IQ is one of the better single predictors of school performance, but a moderate correlation leaves most of the variation to effort, interest, teaching quality, health and home conditions.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"IQ और विद्यालयी उपलब्धि के संबंध के बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["IQ अंक विद्यालयी अंकों का लगभग पूर्ण पूर्वानुमान देते हैं, इसलिए अन्य कारक पूर्वानुमान में बहुत कम जोड़ते हैं","IQ और विद्यालयी उपलब्धि असंबद्ध हैं, क्योंकि अंक केवल प्रयास और शिक्षण पर निर्भर करते हैं","विद्यार्थियों को समूहबद्ध करने और मार्गदर्शन देने में विद्यालयों को केवल IQ पर विचार करना चाहिए","IQ उपलब्धि से मध्यम रूप से सहसंबद्ध है, इसलिए अभिप्रेरणा, शिक्षण और घर का सहयोग भी महत्त्वपूर्ण हैं"],"explanationHi":"IQ विद्यालयी प्रदर्शन के बेहतर एकल पूर्वानुमानकों में से एक है, परंतु मध्यम सहसंबंध का अर्थ है कि अधिकांश भिन्नता प्रयास, रुचि, शिक्षण की गुणवत्ता, स्वास्थ्य और घर की परिस्थितियों पर छूट जाती है।"},
  {"id":"cdp-child-development-1006","question":"Which practice most directly builds emotional literacy among Class 2 children?","options":["Using a feelings chart where children name how they feel and discuss what helps when angry or sad","Telling children that crying in school is a weakness so that they learn to control themselves","Keeping emotions out of class and focusing on the syllabus so that children stay calm and busy","Punishing children who show anger in class so that the others learn which feelings are unacceptable"],"answer":0,"explanation":"Emotional literacy starts with recognising and naming feelings and learning strategies to manage them; suppressing or punishing emotions teaches avoidance, not regulation.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"कक्षा 2 के बच्चों में भावनात्मक साक्षरता विकसित करने में कौन-सा अभ्यास सबसे प्रत्यक्ष रूप से सहायक है?","optionsHi":["भावना-तालिका का प्रयोग, जिसमें बच्चे बताएँ कि वे कैसा महसूस कर रहे हैं और चर्चा करें कि क्रोधित या उदास होने पर क्या मदद करता है","बच्चों से कहना कि विद्यालय में रोना कमज़ोरी है, ताकि वे स्वयं पर नियंत्रण करना सीखें","कक्षा में भावनाओं को दूर रखकर पाठ्यक्रम पर ध्यान देना, ताकि बच्चे शांत और व्यस्त रहें","कक्षा में क्रोध दिखाने वाले बच्चों को दंडित करना, ताकि अन्य बच्चे जानें कि कौन-सी भावनाएँ अस्वीकार्य हैं"],"explanationHi":"भावनात्मक साक्षरता भावनाओं को पहचानने और नाम देने तथा उन्हें सँभालने की युक्तियाँ सीखने से शुरू होती है; भावनाओं को दबाना या दंडित करना बचने की प्रवृत्ति सिखाता है, भावना-नियमन नहीं।"},
  {"id":"cdp-child-development-1007","question":"Which of the following statements about creativity are correct? I. Creativity is limited to the arts such as painting and music. II. Creativity can be fostered through suitable teaching and classroom climate. III. A creative product is usually both novel and appropriate or useful in its context. IV. Only a few geniuses are creative.","options":["II and III only","I and IV only","I, II and III only","II, III and IV only"],"answer":0,"explanation":"Creativity appears in every field, including science and everyday problem-solving, and in all children to some degree; it can be nurtured, and it requires both novelty and appropriateness.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"सृजनात्मकता के बारे में निम्नलिखित में से कौन-से कथन सही हैं? I. सृजनात्मकता चित्रकला और संगीत जैसी कलाओं तक सीमित है। II. उपयुक्त शिक्षण और कक्षा-वातावरण द्वारा सृजनात्मकता को बढ़ावा दिया जा सकता है। III. सृजनात्मक उत्पाद प्रायः अपने संदर्भ में नवीन और उपयुक्त या उपयोगी दोनों होता है। IV. केवल कुछ प्रतिभाशाली लोग ही सृजनशील होते हैं।","optionsHi":["केवल II और III","केवल I और IV","केवल I, II और III","केवल II, III और IV"],"explanationHi":"सृजनात्मकता विज्ञान और रोज़मर्रा की समस्या-समाधान सहित हर क्षेत्र में तथा कुछ-न-कुछ सभी बच्चों में पाई जाती है; इसे पोषित किया जा सकता है, और इसके लिए नवीनता तथा उपयुक्तता दोनों आवश्यक हैं।"},
  {"id":"cdp-child-development-1008","question":"For a science fair, a Class 8 group first lists twenty possible projects on reducing plastic waste and then judges them on cost, time and safety to choose the single most practical one. The second step mainly involves:","options":["Divergent thinking","Incubation","Convergent thinking","Functional fixedness"],"answer":2,"explanation":"Creative problem-solving alternates: divergent thinking generates many options, and convergent thinking evaluates them to choose the best one. Choosing a single project is the convergent phase.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"एक विज्ञान मेले के लिए कक्षा 8 का एक समूह पहले प्लास्टिक कचरा घटाने पर बीस संभावित परियोजनाओं की सूची बनाता है और फिर लागत, समय और सुरक्षा के आधार पर उन्हें परखकर सबसे व्यावहारिक एक परियोजना चुनता है। दूसरे चरण में मुख्यतः क्या शामिल है?","optionsHi":["अपसारी चिंतन","उद्भवन (इन्क्यूबेशन)","अभिसारी चिंतन","कार्यात्मक स्थिरता"],"explanationHi":"सृजनात्मक समस्या-समाधान में दोनों बारी-बारी से चलते हैं: अपसारी चिंतन अनेक विकल्प उत्पन्न करता है और अभिसारी चिंतन उनका मूल्यांकन करके सर्वोत्तम चुनता है। एकमात्र परियोजना चुनना अभिसारी चरण है।"},
  {"id":"cdp-child-development-1009","question":"A school announces large cash prizes for the ‘most creative’ collage, to be judged strictly by a panel, and repeatedly reminds students that they will be judged. What does research on motivation and creativity (for example, Teresa Amabile’s work) suggest?","options":["Expected evaluation and rewards reliably increase creativity, because children try much harder for prizes","Rewards affect effort on routine tasks but have no effect at all on creative work","Creativity depends mainly on IQ, so the prizes and judging will make little difference either way","Heavy emphasis on expected evaluation and reward can lower creativity; intrinsic interest supports it"],"answer":3,"explanation":"Amabile’s research found that working mainly for expected evaluation or reward often reduces the creativity of the products, whereas intrinsic motivation, enjoyment of the task itself, supports it.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"एक विद्यालय ‘सबसे सृजनात्मक’ कोलाज के लिए बड़े नकद पुरस्कारों की घोषणा करता है, जिसका निर्णय एक पैनल कड़ाई से करेगा, और बार-बार याद दिलाता है कि विद्यार्थियों का मूल्यांकन होगा। अभिप्रेरणा और सृजनात्मकता पर शोध (उदाहरण के लिए टेरेसा अमाबाइल का कार्य) क्या सुझाता है?","optionsHi":["अपेक्षित मूल्यांकन और पुरस्कार सृजनात्मकता को निश्चित रूप से बढ़ाते हैं, क्योंकि बच्चे पुरस्कार के लिए बहुत अधिक प्रयास करते हैं","पुरस्कार नियमित कार्यों में प्रयास को प्रभावित करते हैं, पर सृजनात्मक कार्य पर इनका कोई प्रभाव नहीं पड़ता","सृजनात्मकता मुख्यतः IQ पर निर्भर करती है, इसलिए पुरस्कारों और निर्णय से दोनों ही स्थितियों में बहुत अंतर नहीं पड़ेगा","अपेक्षित मूल्यांकन और पुरस्कार पर अत्यधिक बल सृजनात्मकता को घटा सकता है; आंतरिक रुचि इसे सहारा देती है"],"explanationHi":"अमाबाइल के शोध में पाया गया कि मुख्यतः अपेक्षित मूल्यांकन या पुरस्कार के लिए काम करना प्रायः उत्पादों की सृजनात्मकता को घटाता है, जबकि आंतरिक अभिप्रेरणा, यानी कार्य में ही आनंद, उसे सहारा देती है।"},
  {"id":"cdp-child-development-1010","question":"In Françoys Gagné’s model of giftedness and talent, what is the difference between a ‘gift’ and a ‘talent’?","options":["A gift is excellence acquired through schooling, while a talent is an inborn ability present from birth","A gift is outstanding natural ability; a talent is outstanding skill developed from it through learning","Both terms mean the same thing, since Gagné used them interchangeably for very high ability","A gift refers to ability in academic subjects, while a talent refers only to sports and the arts"],"answer":1,"explanation":"Gagné’s model separates natural abilities (gifts) from systematically developed skills (talents); the development depends on learning, motivation and environment, so a gift does not automatically become a talent.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"फ्रांस्वा गैन्ये के प्रतिभाशालिता और प्रतिभा के मॉडल में ‘उपहार’ (gift) और ‘प्रतिभा’ (talent) में क्या अंतर है?","optionsHi":["उपहार विद्यालयी शिक्षा से अर्जित उत्कृष्टता है, जबकि प्रतिभा जन्म से मौजूद जन्मजात योग्यता है","उपहार असाधारण प्राकृतिक योग्यता है; प्रतिभा उससे अधिगम के द्वारा विकसित असाधारण कौशल है","दोनों शब्दों का अर्थ एक ही है, क्योंकि गैन्ये ने अत्यंत उच्च योग्यता के लिए इनका परस्पर बदलकर प्रयोग किया","उपहार शैक्षिक विषयों में योग्यता को दर्शाता है, जबकि प्रतिभा केवल खेल और कलाओं को दर्शाती है"],"explanationHi":"गैन्ये का मॉडल प्राकृतिक योग्यताओं (उपहार) को व्यवस्थित रूप से विकसित कौशलों (प्रतिभा) से अलग करता है; यह विकास अधिगम, अभिप्रेरणा और वातावरण पर निर्भर करता है, इसलिए उपहार अपने-आप प्रतिभा नहीं बन जाता।"},
  {"id":"cdp-child-development-1011","question":"In a mixed-ability Class 7 classroom, a teacher gives all students the same topic, the water cycle, but three versions of the task: labelling a diagram, explaining the process in a flow chart, and predicting the effect of deforestation on local rainfall. This strategy is called:","options":["Tiered assignments","Grade skipping","Rote drill","Norm-referenced grouping"],"answer":0,"explanation":"Tiered assignments keep the same core content but vary complexity, letting gifted and struggling learners work at suitable levels of challenge within one class.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की मिश्रित-योग्यता वाली कक्षा में एक शिक्षक सभी विद्यार्थियों को एक ही विषय, जलचक्र, देता है, परंतु कार्य के तीन रूपों में: आरेख पर नाम लिखना, प्रवाह-चित्र में प्रक्रिया समझाना, और वनों की कटाई का स्थानीय वर्षा पर प्रभाव अनुमानित करना। इस युक्ति को कहते हैं:","optionsHi":["स्तरीकृत असाइनमेंट (टियर्ड असाइनमेंट)","कक्षा छोड़कर आगे बढ़ाना (ग्रेड स्किपिंग)","रटंत अभ्यास","मानक-संदर्भित समूहीकरण"],"explanationHi":"स्तरीकृत असाइनमेंट में मूल विषयवस्तु वही रहती है पर जटिलता बदलती है, जिससे प्रतिभाशाली और संघर्ष कर रहे अधिगमकर्ता एक ही कक्षा में उपयुक्त चुनौती-स्तर पर कार्य कर पाते हैं।"},
  {"id":"cdp-child-development-1012","question":"Which of the following statements about poverty-related factors and children’s learning are supported by research? I. Chronic malnutrition in early childhood can affect cognitive development. II. Midday meals can improve attendance and attention in class. III. Children from poor families are less intelligent by birth. IV. Stress and lack of learning materials at home can depress school performance.","options":["I and III only","II and III only","I, II and IV only","I, II, III and IV"],"answer":2,"explanation":"Nutrition, school meals, stress and home resources affect learning; but lower average scores reflect these conditions, not an inborn lack of intelligence, so III is false.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"निर्धनता से जुड़े कारकों और बच्चों के अधिगम के बारे में शोध द्वारा समर्थित कौन-से कथन हैं? I. बचपन में दीर्घकालिक कुपोषण संज्ञानात्मक विकास को प्रभावित कर सकता है। II. मध्याह्न भोजन उपस्थिति और कक्षा में ध्यान को बेहतर कर सकता है। III. गरीब परिवारों के बच्चे जन्म से कम बुद्धिमान होते हैं। IV. घर पर तनाव और अधिगम-सामग्री का अभाव विद्यालयी प्रदर्शन को गिरा सकता है।","optionsHi":["केवल I और III","केवल II और III","केवल I, II और IV","I, II, III और IV"],"explanationHi":"पोषण, विद्यालयी भोजन, तनाव और घर के संसाधन अधिगम को प्रभावित करते हैं; परंतु कम औसत अंक इन्हीं परिस्थितियों को दर्शाते हैं, जन्मजात बुद्धि की कमी को नहीं, इसलिए III असत्य है।"},
  {"id":"cdp-child-development-1013","question":"Most children in a Class 3 in rural Madhya Pradesh are first-generation learners whose parents have not been to school. Which homework practice is most appropriate?","options":["Set homework that needs parents’ help every evening, so that families become closely involved in learning","Give tasks children can do alone, linked to daily life, with in-school support for those who need it","Give no homework at all, since these children have nobody at home who can guide their learning","Punish children who come without homework, so that they develop regular study habits early"],"answer":1,"explanation":"Homework that assumes educated parents disadvantages first-generation learners; independent, meaningful tasks plus in-school support keep expectations high without penalising home circumstances.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"मध्य प्रदेश के ग्रामीण क्षेत्र की कक्षा 3 के अधिकांश बच्चे पहली पीढ़ी के अधिगमकर्ता हैं, जिनके माता-पिता कभी विद्यालय नहीं गए। कौन-सा गृहकार्य अभ्यास सबसे उपयुक्त है?","optionsHi":["हर शाम ऐसा गृहकार्य देना जिसमें माता-पिता की मदद चाहिए, ताकि परिवार अधिगम में निकटता से जुड़ें","ऐसे कार्य देना जो बच्चे अकेले कर सकें, दैनिक जीवन से जुड़े हों, और जिन्हें ज़रूरत हो उन्हें विद्यालय में सहायता मिले","कोई गृहकार्य न देना, क्योंकि इन बच्चों के घर पर उनके अधिगम का मार्गदर्शन करने वाला कोई नहीं है","गृहकार्य के बिना आने वाले बच्चों को दंडित करना, ताकि उनमें नियमित अध्ययन की आदतें जल्दी विकसित हों"],"explanationHi":"शिक्षित माता-पिता मानकर दिया गया गृहकार्य पहली पीढ़ी के अधिगमकर्ताओं को हानि पहुँचाता है; स्वतंत्र, अर्थपूर्ण कार्य और विद्यालय में सहायता, घर की परिस्थितियों को दंडित किए बिना ऊँची अपेक्षाएँ बनाए रखते हैं।"},
  {"id":"cdp-child-development-1014","question":"In a village school, a few children from a particular caste group are made to sit separately and are rarely asked questions. Which statement best describes the teacher’s responsibility?","options":["Follow local custom on seating to avoid trouble in the village, while teaching them the same lessons","Seat these children separately but give them extra homework so that they can catch up on their own","Wait for the parents to complain formally before acting, since seating is a community matter","Ensure they sit with everyone and take full part, since such discrimination violates the RTE Act"],"answer":3,"explanation":"The RTE Act requires that children from weaker and disadvantaged groups not be discriminated against; segregation also teaches all children that some deserve less, damaging self-esteem and learning.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"एक ग्रामीण विद्यालय में किसी विशेष जाति-समूह के कुछ बच्चों को अलग बैठाया जाता है और उनसे शायद ही कभी प्रश्न पूछे जाते हैं। शिक्षक के उत्तरदायित्व को कौन-सा कथन सबसे अच्छी तरह बताता है?","optionsHi":["गाँव में झगड़ा टालने के लिए बैठने की स्थानीय प्रथा का पालन करना, और उन्हें वही पाठ पढ़ाना","इन बच्चों को अलग बैठाना, परंतु उन्हें अतिरिक्त गृहकार्य देना ताकि वे स्वयं बराबरी कर लें","अभिभावकों की औपचारिक शिकायत की प्रतीक्षा करना, क्योंकि बैठने की व्यवस्था समुदाय का विषय है","यह सुनिश्चित करना कि वे सबके साथ बैठें और पूरी भागीदारी करें, क्योंकि ऐसा भेदभाव RTE अधिनियम का उल्लंघन है"],"explanationHi":"RTE अधिनियम की अपेक्षा है कि कमज़ोर और वंचित वर्गों के बच्चों के साथ भेदभाव न हो; अलगाव सभी बच्चों को यह भी सिखाता है कि कुछ लोग कम के पात्र हैं, जिससे आत्म-सम्मान और अधिगम को क्षति पहुँचती है।"},
  {"id":"cdp-child-development-1015","question":"Ji-woo, a Korean child, joined a Delhi school a year ago. She chats easily in English with classmates in the playground but struggles to understand her science textbook and write answers in English. In Jim Cummins’s terms, she has developed:","options":["Cognitive academic language proficiency (CALP), but not yet basic interpersonal communicative skills (BICS)","Neither BICS nor CALP","Native-like proficiency in all areas","Basic interpersonal communicative skills (BICS) but not yet cognitive academic language proficiency (CALP)"],"answer":3,"explanation":"Cummins found that everyday conversational fluency (BICS) develops within about 1–2 years, while the academic language needed for textbooks and writing (CALP) takes several more years.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"जी-वू, एक कोरियाई बालिका, एक वर्ष पहले दिल्ली के विद्यालय में आई। वह खेल के मैदान में सहपाठियों से अंग्रेज़ी में सहजता से बातचीत करती है, पर अपनी विज्ञान की पाठ्यपुस्तक समझने और अंग्रेज़ी में उत्तर लिखने में कठिनाई महसूस करती है। जिम कमिंस की शब्दावली में, उसने विकसित किया है:","optionsHi":["संज्ञानात्मक शैक्षिक भाषा दक्षता (CALP), परंतु अभी आधारभूत अंतर्वैयक्तिक संप्रेषण कौशल (BICS) नहीं","न BICS, न CALP","सभी क्षेत्रों में मातृभाषी जैसी दक्षता","आधारभूत अंतर्वैयक्तिक संप्रेषण कौशल (BICS), परंतु अभी संज्ञानात्मक शैक्षिक भाषा दक्षता (CALP) नहीं"],"explanationHi":"कमिंस ने पाया कि रोज़मर्रा की बातचीत की धाराप्रवाहता (BICS) लगभग 1–2 वर्षों में विकसित हो जाती है, जबकि पाठ्यपुस्तकों और लेखन के लिए आवश्यक शैक्षिक भाषा (CALP) में कई और वर्ष लगते हैं।"},
  {"id":"cdp-child-development-1016","question":"Jim Cummins’s ‘linguistic interdependence’ hypothesis is most often used to support which educational practice?","options":["Banning the home language in school so that children are pushed to learn the second language faster","Teaching only in the home language throughout schooling and never introducing a second language","Strong mother-tongue-based early education, since concepts and literacy built in the first language transfer","Postponing all reading until children are fluent in English, so that literacy starts in a single strong language"],"answer":2,"explanation":"Cummins proposed a common underlying proficiency: knowledge and literacy built in the first language support learning in the second, so strengthening the home language helps, rather than hinders, second-language learning.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"जिम कमिंस की ‘भाषाई अंतरनिर्भरता’ परिकल्पना का उपयोग प्रायः किस शैक्षिक अभ्यास के समर्थन में किया जाता है?","optionsHi":["विद्यालय में घर की भाषा पर रोक लगाना, ताकि बच्चे दूसरी भाषा जल्दी सीखने को विवश हों","पूरी स्कूली शिक्षा में केवल घर की भाषा में पढ़ाना और दूसरी भाषा कभी न लाना","सशक्त मातृभाषा-आधारित प्रारंभिक शिक्षा, क्योंकि पहली भाषा में बनी अवधारणाएँ और साक्षरता स्थानांतरित होती हैं","सभी पठन को तब तक टालना जब तक बच्चे अंग्रेज़ी में धाराप्रवाह न हो जाएँ, ताकि साक्षरता एक ही सशक्त भाषा में शुरू हो"],"explanationHi":"कमिंस ने एक सामान्य अंतर्निहित दक्षता का प्रस्ताव रखा: पहली भाषा में निर्मित ज्ञान और साक्षरता दूसरी भाषा में अधिगम को सहारा देती है, इसलिए घर की भाषा को सशक्त करना दूसरी भाषा के अधिगम में बाधक नहीं, सहायक होता है।"},
  {"id":"cdp-child-development-1017","question":"Gond children in a residential school are fined for speaking their own language. Within a few years many can no longer talk comfortably with their grandparents, though their Hindi is still weak. In Wallace Lambert’s terms, this is:","options":["Subtractive bilingualism","Additive bilingualism","Balanced bilingualism","Simultaneous bilingualism"],"answer":0,"explanation":"In subtractive bilingualism a second language replaces the first, often with cultural and cognitive costs; additive bilingualism adds a new language while the first is maintained and valued.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"एक आवासीय विद्यालय में गोंड बच्चों पर अपनी भाषा बोलने के लिए जुर्माना लगाया जाता है। कुछ वर्षों में उनमें से कई अपने दादा-दादी से सहजता से बात नहीं कर पाते, जबकि उनकी हिंदी अब भी कमज़ोर है। वैलेस लैम्बर्ट की शब्दावली में, यह है:","optionsHi":["ह्रासी द्विभाषिकता (सब्ट्रैक्टिव बाइलिंगुअलिज़्म)","योगात्मक द्विभाषिकता (एडिटिव बाइलिंगुअलिज़्म)","संतुलित द्विभाषिकता","एक साथ अर्जित द्विभाषिकता"],"explanationHi":"ह्रासी द्विभाषिकता में दूसरी भाषा पहली भाषा का स्थान ले लेती है, जिसकी प्रायः सांस्कृतिक और संज्ञानात्मक कीमत चुकानी पड़ती है; योगात्मक द्विभाषिकता में पहली भाषा बनी और सम्मानित रहती है तथा नई भाषा जुड़ती है।"},
  {"id":"cdp-child-development-1018","question":"Basil Bernstein distinguished a ‘restricted code’ and an ‘elaborated code’ of speech, linking them to social class. What is the most common criticism of how these ideas were used in education?","options":["They showed that children of all social classes use language in essentially the same way","They were used to portray working-class children’s speech as deficient rather than merely different","They proved that working-class children are unable to learn abstract concepts at school","They led schools to teach only in children’s home dialects and to drop the standard language altogether"],"answer":1,"explanation":"Critics such as Labov argued that treating the restricted code as inferior confused difference with deficit and blamed children’s language for school failure that came from school practices.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"बेसिल बर्नस्टीन ने भाषण के ‘सीमित कूट’ और ‘विस्तृत कूट’ में भेद किया और उन्हें सामाजिक वर्ग से जोड़ा। शिक्षा में इन विचारों के प्रयोग की सबसे आम आलोचना क्या है?","optionsHi":["उन्होंने दिखाया कि सभी सामाजिक वर्गों के बच्चे भाषा का उपयोग मूलतः एक ही तरह से करते हैं","उनका उपयोग श्रमिक वर्ग के बच्चों की भाषा को केवल भिन्न मानने के बजाय दोषपूर्ण दिखाने के लिए किया गया","उन्होंने सिद्ध कर दिया कि श्रमिक वर्ग के बच्चे विद्यालय में अमूर्त अवधारणाएँ सीखने में असमर्थ हैं","उनके कारण विद्यालयों ने केवल बच्चों की घरेलू बोलियों में पढ़ाना और मानक भाषा को पूरी तरह छोड़ना शुरू कर दिया"],"explanationHi":"लेबोव जैसे आलोचकों ने तर्क दिया कि सीमित कूट को हीन मानना भिन्नता को कमी समझ लेना था और विद्यालयी असफलता का दोष बच्चों की भाषा पर डालना था, जबकि उसका कारण विद्यालय की प्रथाएँ थीं।"},
  {"id":"cdp-child-development-1019","question":"Neha, who loves physics and does well in it, is told by the school counsellor before Class 11 to take humanities because ‘science is too demanding for girls and humanities suits them’. The most appropriate evaluation is that:","options":["The advice is sound because girls generally find physics harder and less suited to their natural interests","The advice is neutral, because the counsellor only suggested an option and did not force her","The advice reflects gender stereotyping; Neha’s interests, aptitude and goals should guide her choice","The advice is correct because careers in science and engineering are not suitable for women"],"answer":2,"explanation":"Steering students by gender rather than interest and ability narrows their options and reproduces stereotypes; guidance should be based on the individual.","difficulty":"moderate","source":"CTET Paper 2 · State TET","questionHi":"नेहा, जिसे भौतिकी पसंद है और जो उसमें अच्छा करती है, से कक्षा 11 से पहले विद्यालय परामर्शदाता कहते हैं कि वह मानविकी ले, क्योंकि ‘विज्ञान लड़कियों के लिए बहुत कठिन है और मानविकी उन्हें सूट करती है’। सबसे उपयुक्त मूल्यांकन यह है कि:","optionsHi":["सलाह सही है क्योंकि लड़कियों को सामान्यतः भौतिकी कठिन लगती है और वह उनकी प्राकृतिक रुचियों के अनुकूल नहीं है","सलाह तटस्थ है, क्योंकि परामर्शदाता ने केवल एक विकल्प सुझाया, उस पर दबाव नहीं डाला","सलाह लैंगिक रूढ़िबद्ध धारणा को दर्शाती है; नेहा की रुचियों, अभिक्षमता और लक्ष्यों को उसके चयन का आधार होना चाहिए","सलाह सही है क्योंकि विज्ञान और इंजीनियरिंग के करियर महिलाओं के लिए उपयुक्त नहीं हैं"],"explanationHi":"रुचि और योग्यता के बजाय लिंग के आधार पर विद्यार्थियों को दिशा देना उनके विकल्पों को सीमित करता है और रूढ़िबद्ध धारणाओं को दोहराता है; मार्गदर्शन व्यक्ति के आधार पर होना चाहिए।"},
  {"id":"cdp-child-development-1020","question":"Which of the following is NOT one of the five guiding principles of the National Curriculum Framework 2005?","options":["Connecting knowledge to life outside the school","Making the textbook the sole basis of teaching and assessment so that standards stay uniform","Making examinations more flexible and integrated with classroom life","Enriching the curriculum to provide for the overall development of children rather than remaining textbook-centric"],"answer":1,"explanation":"NCF 2005 explicitly wants the curriculum to move beyond textbooks; its other principles are shifting learning away from rote methods and nurturing an identity informed by caring concerns within the democratic polity.","difficulty":"hard","source":"CTET · KVS PRT","questionHi":"निम्नलिखित में से कौन-सा राष्ट्रीय पाठ्यचर्या की रूपरेखा 2005 (NCF 2005) के पाँच मार्गदर्शक सिद्धांतों में से एक नहीं है?","optionsHi":["ज्ञान को विद्यालय के बाहर के जीवन से जोड़ना","पाठ्यपुस्तक को शिक्षण और आकलन का एकमात्र आधार बनाना, ताकि मानक एक-से बने रहें","परीक्षाओं को अधिक लचीला बनाना और उन्हें कक्षा-जीवन से एकीकृत करना","पाठ्यचर्या को समृद्ध करना ताकि वह पाठ्यपुस्तक-केंद्रित रहने के बजाय बच्चों के समग्र विकास की व्यवस्था करे"],"explanationHi":"NCF 2005 स्पष्ट रूप से चाहती है कि पाठ्यचर्या पाठ्यपुस्तकों से आगे बढ़े; इसके अन्य सिद्धांत हैं रटंत विधियों से अधिगम को हटाना और लोकतांत्रिक राजनीतिक व्यवस्था में संवेदनशील चिंताओं से युक्त पहचान का पोषण करना।"},
  {"id":"cdp-child-development-1021","question":"A teacher says, ‘My job is to pour knowledge into children, who come to me as empty vessels.’ NCF 2005 would counter this mainly by holding that:","options":["Children should learn only from their peers, since teachers’ explanations make them passive","Teachers should never explain anything and should leave children to discover everything alone","Knowledge is fixed, and the teacher’s role is to transmit it as efficiently and completely as possible to all","Children actively construct knowledge by linking new ideas to experience, and the teacher facilitates"],"answer":3,"explanation":"NCF 2005 takes a constructivist view: the child is an active constructor of knowledge, not a passive receiver, and the teacher is a facilitator, which does not mean giving up explanation altogether.","difficulty":"moderate","source":"CTET Paper I · State TET","questionHi":"एक शिक्षक कहता है, ‘मेरा काम बच्चों में ज्ञान उँडेलना है, जो मेरे पास खाली बर्तन की तरह आते हैं।’ NCF 2005 इसका प्रतिवाद मुख्यतः यह मानकर करेगी कि:","optionsHi":["बच्चों को केवल अपने साथियों से सीखना चाहिए, क्योंकि शिक्षकों की व्याख्याएँ उन्हें निष्क्रिय बना देती हैं","शिक्षकों को कभी कुछ नहीं समझाना चाहिए और सब कुछ बच्चों को अकेले खोजने के लिए छोड़ देना चाहिए","ज्ञान स्थिर है, और शिक्षक की भूमिका उसे सभी तक यथासंभव कुशलता और पूर्णता से पहुँचाना है","बच्चे नए विचारों को अनुभव से जोड़कर ज्ञान का सक्रिय रूप से निर्माण करते हैं, और शिक्षक सुगमकर्ता है"],"explanationHi":"NCF 2005 का दृष्टिकोण रचनावादी है: बच्चा ज्ञान का सक्रिय निर्माता है, निष्क्रिय ग्राही नहीं, और शिक्षक सुगमकर्ता है; इसका अर्थ व्याख्या को पूरी तरह छोड़ देना नहीं है।"},
  {"id":"cdp-child-development-1022","question":"According to NCF 2005, the main goal of mathematics education in school is:","options":["Mathematisation of the child’s thinking: the ability to handle abstraction, reasoning and problem-solving","Speed in computation and memorising multiplication tables, as the foundation of all later work","Preparing every child for higher mathematics at university, since mathematics is the gateway to most careers","Scoring high marks in board examinations, which open doors to further education and careers"],"answer":0,"explanation":"NCF 2005 calls ‘useful’ numeracy the narrow aim and the mathematisation of the child’s thought processes the higher aim; computation speed is only a small part of it.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT","questionHi":"NCF 2005 के अनुसार विद्यालय में गणित शिक्षा का मुख्य लक्ष्य है:","optionsHi":["बच्चे की सोच का गणितीकरण: अमूर्तन, तर्क और समस्या-समाधान को सँभालने की क्षमता","गणना में गति और पहाड़े याद करना, जो आगे के सभी कार्य की नींव है","हर बच्चे को विश्वविद्यालय में उच्च गणित के लिए तैयार करना, क्योंकि गणित अधिकांश करियर का प्रवेश-द्वार है","बोर्ड परीक्षाओं में उच्च अंक लाना, जो आगे की शिक्षा और करियर के द्वार खोलते हैं"],"explanationHi":"NCF 2005 ‘उपयोगी’ संख्या-ज्ञान को संकीर्ण उद्देश्य और बच्चे की चिंतन-प्रक्रियाओं के गणितीकरण को उच्च उद्देश्य कहती है; गणना की गति उसका केवल एक छोटा भाग है।"},
  {"id":"cdp-child-development-1023","question":"In a Class 3 classroom in Delhi, children speak Bhojpuri, Bengali, Haryanvi and Hindi at home. In line with NCF 2005, the teacher should:","options":["Ban home languages in class so that children pick up standard Hindi faster","Allow home languages only during the lunch break, keeping lessons in Hindi","Use the children’s languages as a resource, letting them compare words across languages","Place children in separate sections by home language so each group is taught easily"],"answer":2,"explanation":"NCF 2005 treats multilingualism as a resource for learning and identity; suppressing home languages silences children and slows learning of the school language itself.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"दिल्ली की कक्षा 3 में बच्चे घर पर भोजपुरी, बांग्ला, हरियाणवी और हिंदी बोलते हैं। NCF 2005 के अनुरूप शिक्षक को चाहिए कि वह:","optionsHi":["कक्षा में घर की भाषाओं पर रोक लगाए, ताकि बच्चे मानक हिंदी जल्दी सीखें","घर की भाषाओं को केवल भोजनावकाश में अनुमति दे और पाठ हिंदी में ही रखे","बच्चों की भाषाओं को संसाधन के रूप में प्रयोग करे और उन्हें भाषाओं के बीच शब्दों की तुलना करने दे","घर की भाषा के आधार पर बच्चों को अलग-अलग वर्गों में रखे ताकि हर समूह को आसानी से पढ़ाया जा सके"],"explanationHi":"NCF 2005 बहुभाषिकता को अधिगम और पहचान के लिए संसाधन मानती है; घर की भाषाओं को दबाने से बच्चे मौन हो जाते हैं और विद्यालय की भाषा सीखने की गति भी धीमी पड़ती है।"},
  {"id":"cdp-child-development-1024","question":"How does NCF 2005 recommend environmental studies (EVS) be handled at the primary stage?","options":["As separate science and social science textbooks from Class 1, so that subject concepts are built from the start","Within language and maths in Classes 1–2, and as integrated EVS (science plus social science) in Classes 3–5","Not taught at all until Class 6, as young children first need to master reading and arithmetic","Only as an activity period, without any textbook or assessment, from Class 1 right up to Class 5"],"answer":1,"explanation":"NCF 2005 integrates EVS concerns into language and maths in Classes 1–2 and teaches EVS as an integrated area of science and social science in Classes 3–5; separate subjects begin later.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT","questionHi":"NCF 2005 प्राथमिक स्तर पर पर्यावरण अध्ययन (EVS) को किस प्रकार संचालित करने की अनुशंसा करती है?","optionsHi":["कक्षा 1 से विज्ञान और सामाजिक विज्ञान की अलग-अलग पाठ्यपुस्तकों के रूप में, ताकि आरंभ से विषयगत अवधारणाएँ बनें","कक्षा 1–2 में भाषा और गणित के भीतर, तथा कक्षा 3–5 में एकीकृत EVS (विज्ञान और सामाजिक विज्ञान) के रूप में","कक्षा 6 तक बिल्कुल न पढ़ाना, क्योंकि छोटे बच्चों को पहले पढ़ना और अंकगणित सीखना चाहिए","कक्षा 1 से कक्षा 5 तक केवल गतिविधि-कालांश के रूप में, बिना पाठ्यपुस्तक या आकलन के"],"explanationHi":"NCF 2005 कक्षा 1–2 में EVS संबंधी चिंताओं को भाषा और गणित में समाहित करती है और कक्षा 3–5 में EVS को विज्ञान तथा सामाजिक विज्ञान के एकीकृत क्षेत्र के रूप में पढ़ाती है; अलग विषय बाद में शुरू होते हैं।"},
  {"id":"cdp-child-development-1025","question":"Several Class 5 children say that heavier objects always fall faster. NCF 2005 would view this answer as:","options":["A sign of carelessness that should be corrected firmly so it is not repeated","An error to be marked wrong and quickly replaced with the correct statement","Evidence that these children are not yet ready to learn science concepts","A window into their thinking that the teacher can build on through activities"],"answer":3,"explanation":"NCF 2005 sees children’s errors and alternative ideas as starting points for teaching; simply marking them wrong leaves the misconception untouched.","difficulty":"moderate","source":"CTET Paper I · State TET","questionHi":"कक्षा 5 के कई बच्चे कहते हैं कि भारी वस्तुएँ हमेशा तेज़ गिरती हैं। NCF 2005 इस उत्तर को किस रूप में देखेगी?","optionsHi":["लापरवाही का संकेत, जिसे सख्ती से सुधारा जाए ताकि दोहराया न जाए","एक त्रुटि, जिसे गलत अंकित कर शीघ्र सही कथन से बदल दिया जाए","इस बात का प्रमाण कि ये बच्चे अभी विज्ञान की अवधारणाएँ सीखने के लिए तैयार नहीं हैं","उनकी सोच की एक खिड़की, जिस पर शिक्षक गतिविधियों के माध्यम से आगे बढ़ सकता है"],"explanationHi":"NCF 2005 बच्चों की त्रुटियों और वैकल्पिक विचारों को शिक्षण के आरंभ-बिंदु मानती है; उन्हें केवल गलत अंकित करने से भ्रांति अछूती रह जाती है।"},
  {"id":"cdp-child-development-1026","question":"Assertion (A): NCF 2005 recommends that the textbook should not be treated as the only source of knowledge. Reason (R): NCF 2005 sees learning as connected to children’s local environment, experiences and many sources beyond the book.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because NCF 2005 links learning to life outside school and to varied sources, it rejects textbook-centric teaching; R gives the reason for A.","difficulty":"very-hard","source":"CTET · DSSSB PRT","questionHi":"अभिकथन (A): NCF 2005 अनुशंसा करती है कि पाठ्यपुस्तक को ज्ञान का एकमात्र स्रोत नहीं माना जाना चाहिए। कारण (R): NCF 2005 अधिगम को बच्चों के स्थानीय परिवेश, अनुभवों और पुस्तक से परे अनेक स्रोतों से जुड़ा मानती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"क्योंकि NCF 2005 अधिगम को विद्यालय के बाहर के जीवन और विविध स्रोतों से जोड़ती है, वह पाठ्यपुस्तक-केंद्रित शिक्षण को अस्वीकार करती है; R, A का कारण बताता है।"},
  {"id":"cdp-child-development-1027","question":"The Yash Pal Committee report ‘Learning Without Burden’ (1993), on which NCF 2005 drew, argued that the real burden on children is:","options":["The physical weight of the school bag, which harms children’s posture and health","The burden of not understanding: too much information with too little comprehension","The number of school holidays, which breaks the continuity of learning through the year","Too many periods of games and PE, which leave little time for academic study"],"answer":1,"explanation":"The report pointed beyond the heavy bag to the deeper burden of non-comprehension, where children are made to memorise information they do not understand.","difficulty":"hard","source":"CTET · KVS TGT","questionHi":"यशपाल समिति की रिपोर्ट ‘बोझ के बिना शिक्षा’ (1993), जिसका NCF 2005 ने आधार लिया, ने तर्क दिया कि बच्चों पर असली बोझ है:","optionsHi":["स्कूल बैग का भौतिक वज़न, जो बच्चों की मुद्रा और स्वास्थ्य को हानि पहुँचाता है","न समझने का बोझ: बहुत अधिक जानकारी और बहुत कम बोध","विद्यालयी छुट्टियों की संख्या, जो वर्ष भर अधिगम की निरंतरता तोड़ती है","खेलकूद और शारीरिक शिक्षा के बहुत अधिक कालांश, जो शैक्षिक अध्ययन के लिए कम समय छोड़ते हैं"],"explanationHi":"रिपोर्ट ने भारी बैग से आगे बढ़कर न समझ पाने के गहरे बोझ की ओर संकेत किया, जहाँ बच्चों से ऐसी जानकारी रटवाई जाती है जिसे वे समझते नहीं।"},
  {"id":"cdp-child-development-1028","question":"Which of these reflect NCF 2005’s approach to the social sciences? I. Including the perspectives of marginalised groups such as women, Dalits and Adivasis. II. Teaching the subject as a collection of facts and dates to be memorised. III. Treating gender as a concern that cuts across all topics. IV. Helping students think critically about democratic institutions.","options":["I and II only","II and III only","I, III and IV only","I, II, III and IV"],"answer":2,"explanation":"NCF 2005 wants social science to be inclusive, gender-sensitive and critical; it rejects the fact-and-date memorisation approach, so II is wrong.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"इनमें से कौन-से NCF 2005 के सामाजिक विज्ञान के प्रति दृष्टिकोण को दर्शाते हैं? I. महिलाओं, दलितों और आदिवासियों जैसे हाशिये के समूहों के दृष्टिकोणों को शामिल करना। II. विषय को याद करने योग्य तथ्यों और तिथियों के संग्रह के रूप में पढ़ाना। III. लिंग को ऐसी चिंता मानना जो सभी विषयों में व्याप्त है। IV. विद्यार्थियों को लोकतांत्रिक संस्थाओं के बारे में आलोचनात्मक रूप से सोचने में सहायता देना।","optionsHi":["केवल I और II","केवल II और III","केवल I, III और IV","I, II, III और IV"],"explanationHi":"NCF 2005 सामाजिक विज्ञान को समावेशी, लिंग-संवेदनशील और आलोचनात्मक बनाना चाहती है; वह तथ्य-तिथि रटने वाले दृष्टिकोण को अस्वीकार करती है, इसलिए II गलत है।"},
  {"id":"cdp-child-development-1029","question":"In a Class 8 civics lesson, a teacher invites students to discuss why women in their area are paid less than men for farm work and what could be done about it. NCF 2005 supports this as an example of:","options":["Critical pedagogy, which helps learners examine social realities and their own experience","Behaviourist drill on civic facts, reinforced by repeating correct answers until they stick","Indoctrination, since the teacher is steering students towards a single political opinion","Rote learning of constitutional articles on equality, applied to a local example"],"answer":0,"explanation":"NCF 2005 favours critical pedagogy: learners discuss real social issues from multiple viewpoints and connect them to their lives, rather than receiving fixed answers.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"कक्षा 8 के नागरिक शास्त्र के पाठ में एक शिक्षक विद्यार्थियों को चर्चा के लिए आमंत्रित करता है कि उनके क्षेत्र में खेती के काम के लिए महिलाओं को पुरुषों से कम मज़दूरी क्यों मिलती है और इसके लिए क्या किया जा सकता है। NCF 2005 इसका समर्थन किसके उदाहरण के रूप में करती है?","optionsHi":["आलोचनात्मक शिक्षणशास्त्र, जो अधिगमकर्ताओं को सामाजिक वास्तविकताओं और अपने अनुभव की जाँच करने में सहायता करता है","नागरिक तथ्यों पर व्यवहारवादी अभ्यास, जो सही उत्तरों की पुनरावृत्ति से तब तक पुष्ट किया जाता है जब तक वे याद न हो जाएँ","विचारधारा थोपना, क्योंकि शिक्षक विद्यार्थियों को किसी एक राजनीतिक मत की ओर ले जा रहा है","समानता पर संवैधानिक अनुच्छेदों का रटना, जिन्हें किसी स्थानीय उदाहरण पर लागू किया गया है"],"explanationHi":"NCF 2005 आलोचनात्मक शिक्षणशास्त्र का समर्थन करती है: अधिगमकर्ता वास्तविक सामाजिक मुद्दों पर अनेक दृष्टिकोणों से चर्चा करते हैं और उन्हें अपने जीवन से जोड़ते हैं, न कि तैयार उत्तर पाते हैं।"},
  {"id":"cdp-child-development-1030","question":"NCF 2005 recommended that board examinations should:","options":["Be made harder and more selective in order to maintain national academic standards","Be introduced at Class 5 as well, so that children get used to examinations early","Continue to test mainly recall of textbook facts, since this is the fairest method","Test understanding and application rather than rote memory, and cause less stress"],"answer":3,"explanation":"NCF 2005’s examination reform aims at questions that test understanding and competencies and at reducing the fear and stress linked to boards.","difficulty":"moderate","source":"CTET · State TET","questionHi":"NCF 2005 ने बोर्ड परीक्षाओं के बारे में अनुशंसा की कि वे:","optionsHi":["राष्ट्रीय शैक्षिक मानक बनाए रखने के लिए अधिक कठिन और अधिक चयनात्मक बनाई जाएँ","कक्षा 5 में भी शुरू की जाएँ, ताकि बच्चे परीक्षाओं के अभ्यस्त हो जाएँ","मुख्यतः पाठ्यपुस्तक के तथ्यों के स्मरण की ही जाँच करती रहें, क्योंकि यह सबसे निष्पक्ष तरीका है","रटने के बजाय समझ और अनुप्रयोग की जाँच करें, और कम तनाव उत्पन्न करें"],"explanationHi":"NCF 2005 का परीक्षा-सुधार ऐसे प्रश्नों का लक्ष्य रखता है जो समझ और दक्षताओं की जाँच करें तथा बोर्ड परीक्षाओं से जुड़े भय और तनाव को घटाएँ।"},
  {"id":"cdp-child-development-1031","question":"A teacher believes that a good classroom is one where children sit silently and never speak unless asked. NCF 2005 would argue that:","options":["Such a silent classroom is ideal in every subject, since it lets all children concentrate fully on the teacher","Fear-imposed silence stifles questioning; discipline should be participatory and respect children’s agency","Children should be free to do whatever they wish, since any rule restricts their natural growth","Discipline is mainly the job of parents, so teachers should focus only on teaching content"],"answer":1,"explanation":"NCF 2005 links learning to dialogue and questioning and calls for participatory rather than authoritarian discipline; this is not the same as having no order at all.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"एक शिक्षक मानता है कि अच्छी कक्षा वह है जहाँ बच्चे चुपचाप बैठें और पूछे बिना कभी न बोलें। NCF 2005 तर्क देगी कि:","optionsHi":["ऐसी शांत कक्षा हर विषय में आदर्श है, क्योंकि इससे सभी बच्चे शिक्षक पर पूरा ध्यान दे पाते हैं","भय से थोपी गई चुप्पी प्रश्न पूछने को दबाती है; अनुशासन सहभागितापूर्ण होना चाहिए और बच्चों की कर्तृत्व-शक्ति का सम्मान करना चाहिए","बच्चों को जो चाहें करने की स्वतंत्रता होनी चाहिए, क्योंकि कोई भी नियम उनकी स्वाभाविक वृद्धि को बाधित करता है","अनुशासन मुख्यतः अभिभावकों का काम है, इसलिए शिक्षकों को केवल विषयवस्तु पढ़ाने पर ध्यान देना चाहिए"],"explanationHi":"NCF 2005 अधिगम को संवाद और प्रश्न पूछने से जोड़ती है और अधिनायकवादी के बजाय सहभागितापूर्ण अनुशासन की माँग करती है; इसका अर्थ किसी भी प्रकार की व्यवस्था का न होना नहीं है।"},
  {"id":"cdp-child-development-1032","question":"NCF 2005’s position on art education is that it should be:","options":["An optional hobby for talented children, offered outside regular school hours","Taught mainly in Classes 9 and 10, where it can add to board examination marks","A curricular subject at all stages, covering music, dance, visual arts and theatre","Replaced by extra mathematics periods, since art has little value for later careers"],"answer":2,"explanation":"NCF 2005 recommends art education as a regular subject at every stage, valued for aesthetic and cultural development, not as an extra for the gifted.","difficulty":"moderate","source":"CTET · KVS PRT","questionHi":"कला शिक्षा के बारे में NCF 2005 का मत है कि वह होनी चाहिए:","optionsHi":["प्रतिभाशाली बच्चों के लिए एक वैकल्पिक शौक, जो नियमित विद्यालय-समय के बाहर कराया जाए","मुख्यतः कक्षा 9 और 10 में पढ़ाई जाए, जहाँ वह बोर्ड परीक्षा के अंकों में जुड़ सकती है","सभी स्तरों पर एक पाठ्यचर्या विषय, जिसमें संगीत, नृत्य, दृश्य कलाएँ और रंगमंच शामिल हों","अतिरिक्त गणित कालांशों से बदल दी जाए, क्योंकि कला का आगे के करियर के लिए कम महत्त्व है"],"explanationHi":"NCF 2005 कला शिक्षा को हर स्तर पर नियमित विषय के रूप में अनुशंसित करती है, जो सौंदर्यबोधी और सांस्कृतिक विकास के लिए मूल्यवान है, न कि प्रतिभाशाली बच्चों के लिए अतिरिक्त गतिविधि।"},
  {"id":"cdp-child-development-1033","question":"Match each curricular area with the NCF 2005 recommendation for it: P. Language  Q. Mathematics  R. Science  S. Work and education — 1. Multilingualism as a resource  2. Mathematisation of thought  3. Engaging children in inquiry and in the processes of generating knowledge, linked to their environment  4. Productive work as a medium of learning","options":["P-2, Q-1, R-3, S-4","P-1, Q-3, R-2, S-4","P-4, Q-2, R-3, S-1","P-1, Q-2, R-3, S-4"],"answer":3,"explanation":"NCF 2005 links language with multilingualism, mathematics with mathematisation, science with inquiry and the environment, and work education with productive work as pedagogy.","difficulty":"hard","source":"CTET Paper II · DSSSB TGT","questionHi":"प्रत्येक पाठ्यचर्या क्षेत्र का मिलान उसके लिए NCF 2005 की अनुशंसा से कीजिए: P. भाषा Q. गणित R. विज्ञान S. कार्य और शिक्षा — 1. बहुभाषिकता एक संसाधन के रूप में 2. चिंतन का गणितीकरण 3. बच्चों को पूछताछ और अपने परिवेश से जुड़ी ज्ञान-निर्माण की प्रक्रियाओं में संलग्न करना 4. उत्पादक कार्य अधिगम के माध्यम के रूप में","optionsHi":["P-2, Q-1, R-3, S-4","P-1, Q-3, R-2, S-4","P-4, Q-2, R-3, S-1","P-1, Q-2, R-3, S-4"],"explanationHi":"NCF 2005 भाषा को बहुभाषिकता से, गणित को गणितीकरण से, विज्ञान को पूछताछ और परिवेश से, तथा कार्य-शिक्षा को शिक्षणशास्त्र के रूप में उत्पादक कार्य से जोड़ती है।"},
  {"id":"cdp-child-development-1034","question":"NCF 2005 lists criteria for judging a science curriculum. A Class 7 lesson pitched at a level the children can understand has ‘cognitive validity’. A lesson that engages them in observing, experimenting and drawing conclusions to generate knowledge has:","options":["Process validity","Historical validity","Ethical validity","Environmental validity"],"answer":0,"explanation":"Process validity means the curriculum engages learners in the methods by which scientific knowledge is generated; historical validity concerns how science has evolved, ethical validity values such as honesty, and environmental validity the learner’s surroundings.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT","questionHi":"NCF 2005 विज्ञान पाठ्यचर्या को परखने के मानदंड बताती है। कक्षा 7 का वह पाठ जो उस स्तर पर रखा गया है जिसे बच्चे समझ सकें, ‘संज्ञानात्मक वैधता’ रखता है। वह पाठ जो उन्हें ज्ञान उत्पन्न करने के लिए अवलोकन, प्रयोग और निष्कर्ष निकालने में संलग्न करता है, रखता है:","optionsHi":["प्रक्रिया वैधता","ऐतिहासिक वैधता","नैतिक वैधता","पर्यावरणीय वैधता"],"explanationHi":"प्रक्रिया वैधता का अर्थ है कि पाठ्यचर्या अधिगमकर्ताओं को उन विधियों में संलग्न करती है जिनसे वैज्ञानिक ज्ञान उत्पन्न होता है; ऐतिहासिक वैधता विज्ञान के विकास से, नैतिक वैधता ईमानदारी जैसे मूल्यों से और पर्यावरणीय वैधता अधिगमकर्ता के परिवेश से संबंधित है।"},
  {"id":"cdp-child-development-1035","question":"A teacher always asks boys to carry benches and girls to decorate the classroom. In line with NCF 2005’s concern for gender equality, she should:","options":["Continue, since these tasks suit the natural strengths and interests of each sex","Rotate all tasks among all children regardless of gender and discuss the stereotype","Let parents decide which tasks their children do, to respect family values","Ask only volunteers to do these tasks, so that no child feels forced into one"],"answer":1,"explanation":"NCF 2005 asks teachers to challenge gender stereotypes in everyday school practice; rotating tasks and discussing the issue does both.","difficulty":"hard","source":"CTET Paper I · State TET","questionHi":"एक शिक्षिका सदैव लड़कों से बेंच उठवाती है और लड़कियों से कक्षा सजवाती है। NCF 2005 की लैंगिक समानता की चिंता के अनुरूप उसे चाहिए कि वह:","optionsHi":["यही जारी रखे, क्योंकि ये कार्य हर लिंग की स्वाभाविक शक्तियों और रुचियों के अनुकूल हैं","लिंग का विचार किए बिना सभी कार्य सभी बच्चों में बारी-बारी से बाँटे और रूढ़िबद्ध धारणा पर चर्चा करे","यह निर्णय अभिभावकों पर छोड़े कि उनके बच्चे कौन-से कार्य करें, ताकि पारिवारिक मूल्यों का सम्मान हो","ये कार्य केवल स्वयंसेवकों से करवाए, ताकि कोई बच्चा किसी एक कार्य में बाध्य महसूस न करे"],"explanationHi":"NCF 2005 शिक्षकों से अपेक्षा करती है कि वे रोज़मर्रा की विद्यालयी प्रथाओं में लैंगिक रूढ़िबद्ध धारणाओं को चुनौती दें; कार्यों को बारी-बारी से बाँटना और इस पर चर्चा करना दोनों करता है।"},
  {"id":"cdp-child-development-1036","question":"Assertion (A): NCF 2005 recommends that the curriculum should connect school knowledge with community knowledge. Reason (R): NCF 2005 holds that knowledge produced in schools is superior to local knowledge and should replace it.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"NCF 2005 wants local and community knowledge brought into the classroom and valued, not replaced, so A is true and R contradicts its stance.","difficulty":"very-hard","source":"CTET · KVS PRT","questionHi":"अभिकथन (A): NCF 2005 अनुशंसा करती है कि पाठ्यचर्या विद्यालयी ज्ञान को सामुदायिक ज्ञान से जोड़े। कारण (R): NCF 2005 मानती है कि विद्यालयों में उत्पन्न ज्ञान स्थानीय ज्ञान से श्रेष्ठ है और उसे प्रतिस्थापित कर देना चाहिए।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"NCF 2005 चाहती है कि स्थानीय और सामुदायिक ज्ञान को कक्षा में लाया जाए और उसे महत्त्व दिया जाए, प्रतिस्थापित न किया जाए; इसलिए A सत्य है और R उसके रुख़ के विपरीत है।"},
  {"id":"cdp-child-development-1037","question":"Peace education in NCF 2005 is meant to be:","options":["A perspective infused across subjects and school life, not just a separate subject","A separate examination subject from Class 1, with its own textbook, periods and marks","Moral lectures given in the morning assembly by the principal and teachers","Meant only for schools in regions affected by conflict or communal violence"],"answer":0,"explanation":"NCF 2005 treats education for peace as a perspective running through the curriculum, teaching methods and school ethos.","difficulty":"hard","source":"CTET Paper II · State TET","questionHi":"NCF 2005 में शांति शिक्षा का आशय है:","optionsHi":["विषयों और विद्यालयी जीवन में समाया हुआ एक दृष्टिकोण, केवल एक अलग विषय नहीं","कक्षा 1 से एक अलग परीक्षा विषय, जिसकी अपनी पाठ्यपुस्तक, कालांश और अंक हों","प्रातःकालीन सभा में प्रधानाचार्य और शिक्षकों द्वारा दिए जाने वाले नैतिक प्रवचन","केवल संघर्ष या सांप्रदायिक हिंसा से प्रभावित क्षेत्रों के विद्यालयों के लिए"],"explanationHi":"NCF 2005 शांति के लिए शिक्षा को पाठ्यचर्या, शिक्षण-विधियों और विद्यालय के परिवेश में व्याप्त दृष्टिकोण मानती है।"},
  {"id":"cdp-child-development-1038","question":"According to NCF 2005, environmental education is best handled by:","options":["Making it a separate subject with its own board examination from Class 6","Holding a special lecture and rally every year on World Environment Day","Leaving it entirely to science teachers, as it is mainly a science topic","Infusing it across subjects and linking it to children’s own surroundings"],"answer":3,"explanation":"NCF 2005 (‘habitat and learning’) favours infusing environmental concerns across the curriculum and grounding them in the child’s local environment.","difficulty":"hard","source":"CTET · KVS PRT","questionHi":"NCF 2005 के अनुसार पर्यावरण शिक्षा को सबसे अच्छी तरह कैसे संचालित किया जा सकता है?","optionsHi":["कक्षा 6 से इसे अपनी बोर्ड परीक्षा वाला अलग विषय बनाकर","हर वर्ष विश्व पर्यावरण दिवस पर एक विशेष व्याख्यान और रैली आयोजित करके","इसे पूरी तरह विज्ञान शिक्षकों पर छोड़कर, क्योंकि यह मुख्यतः विज्ञान का विषय है","इसे सभी विषयों में समाहित करके और बच्चों के अपने परिवेश से जोड़कर"],"explanationHi":"NCF 2005 (‘पर्यावास और अधिगम’) पर्यावरणीय चिंताओं को पूरी पाठ्यचर्या में समाहित करने और उन्हें बच्चे के स्थानीय परिवेश में आधारित करने का पक्ष लेती है।"},
  {"id":"cdp-child-development-1039","question":"Which statement about NCF 2005 and health and physical education is correct?","options":["It may be used as a free period for other subjects in the weeks before examinations","It should be compulsory, as essential to development as the academic subjects","It applies mainly to students selected for school sports teams","It should begin only at the secondary stage, once children are older"],"answer":1,"explanation":"NCF 2005 treats health and physical education as a compulsory curricular area for all children, not as a dispensable period.","difficulty":"hard","source":"CTET · State TET","questionHi":"NCF 2005 और स्वास्थ्य एवं शारीरिक शिक्षा के बारे में कौन-सा कथन सही है?","optionsHi":["परीक्षा से पूर्व के सप्ताहों में इसके कालांश को अन्य विषयों के लिए खाली कालांश के रूप में उपयोग किया जा सकता है","यह अनिवार्य होनी चाहिए, क्योंकि यह विकास के लिए उतनी ही आवश्यक है जितने शैक्षिक विषय","यह मुख्यतः विद्यालय की खेल टीमों के लिए चुने गए विद्यार्थियों पर लागू होती है","इसे केवल माध्यमिक स्तर पर शुरू किया जाना चाहिए, जब बच्चे बड़े हो जाएँ"],"explanationHi":"NCF 2005 स्वास्थ्य और शारीरिक शिक्षा को सभी बच्चों के लिए अनिवार्य पाठ्यचर्या क्षेत्र मानती है, न कि छोड़े जा सकने वाले कालांश के रूप में।"},
  {"id":"cdp-child-development-1040","question":"‘Nurturing an overriding identity informed by caring concerns within the democratic polity of the country’ is a guiding principle of NCF 2005. Which classroom practice best reflects it?","options":["Celebrating mainly the festivals of the majority community, so that a shared national identity is built","Having students memorise the Preamble word for word and recite it in a test","Discussing a local case of discrimination with empathy, in the light of constitutional equality","Ranking students by their marks in civics to reward good citizenship"],"answer":2,"explanation":"The principle is about caring, empathy and constitutional values lived and examined in real situations; memorising the Preamble is recall, not a caring democratic identity.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"‘देश की लोकतांत्रिक राजनीतिक व्यवस्था के भीतर संवेदनशील चिंताओं से युक्त सर्वोपरि पहचान का पोषण करना’ NCF 2005 का एक मार्गदर्शक सिद्धांत है। कौन-सा कक्षा-अभ्यास इसे सबसे अच्छी तरह दर्शाता है?","optionsHi":["मुख्यतः बहुसंख्यक समुदाय के त्योहार मनाना, ताकि साझा राष्ट्रीय पहचान बने","विद्यार्थियों से प्रस्तावना शब्दशः याद करवाना और परीक्षा में सुनवाना","संवैधानिक समानता के प्रकाश में, सहानुभूति के साथ भेदभाव के किसी स्थानीय मामले पर चर्चा करना","अच्छी नागरिकता को पुरस्कृत करने के लिए विद्यार्थियों को नागरिक शास्त्र के अंकों के आधार पर श्रेणीबद्ध करना"],"explanationHi":"यह सिद्धांत वास्तविक परिस्थितियों में जिए और परखे गए संवेदनशीलता, सहानुभूति और संवैधानिक मूल्यों के बारे में है; प्रस्तावना को याद करना केवल स्मरण है, संवेदनशील लोकतांत्रिक पहचान नहीं।"},
  {"id":"cdp-child-development-1041","question":"A Class 4 teacher in Assam teaches about local bamboo crafts with the help of an artisan from the village. This practice is best described as:","options":["Bringing community knowledge into the classroom, as NCF 2005 recommends","A diversion from the prescribed syllabus, which NCF 2005 discourages","Vocational training, which NCF 2005 reserves for Class 11","An activity suitable only for children weak in academics"],"answer":0,"explanation":"NCF 2005 values local knowledge and community members as learning resources and links them with the school curriculum.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"असम की कक्षा 4 का एक शिक्षक गाँव के एक कारीगर की सहायता से स्थानीय बाँस-शिल्प के बारे में पढ़ाता है। इस अभ्यास का सबसे उचित वर्णन है:","optionsHi":["सामुदायिक ज्ञान को कक्षा में लाना, जैसा NCF 2005 अनुशंसित करती है","निर्धारित पाठ्यक्रम से भटकाव, जिसे NCF 2005 हतोत्साहित करती है","व्यावसायिक प्रशिक्षण, जिसे NCF 2005 कक्षा 11 के लिए आरक्षित करती है","एक गतिविधि जो केवल शैक्षिक रूप से कमज़ोर बच्चों के लिए उपयुक्त है"],"explanationHi":"NCF 2005 स्थानीय ज्ञान और समुदाय के सदस्यों को अधिगम-संसाधन के रूप में महत्त्व देती है और उन्हें विद्यालयी पाठ्यचर्या से जोड़ती है।"},
  {"id":"cdp-child-development-1042","question":"Which of these are consistent with the NCF 2005 view of learning? I. Learning takes place both within and outside school. II. Learning is an active and social process. III. Children’s mistakes should be avoided at any cost. IV. Children’s prior experiences should be the starting point of teaching.","options":["I and III only","I, II and IV only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"NCF 2005 sees learning as active, social and rooted in experience inside and outside school; mistakes are a natural part of learning, so III is wrong.","difficulty":"very-hard","source":"CTET · DSSSB PRT","questionHi":"इनमें से कौन-से कथन NCF 2005 के अधिगम-संबंधी दृष्टिकोण के अनुरूप हैं? I. अधिगम विद्यालय के भीतर और बाहर दोनों जगह होता है। II. अधिगम एक सक्रिय और सामाजिक प्रक्रिया है। III. बच्चों की गलतियों से हर कीमत पर बचना चाहिए। IV. बच्चों के पूर्व अनुभव शिक्षण का आरंभ-बिंदु होने चाहिए।","optionsHi":["केवल I और III","केवल I, II और IV","केवल II, III और IV","I, II, III और IV"],"explanationHi":"NCF 2005 अधिगम को सक्रिय, सामाजिक और विद्यालय के भीतर-बाहर अनुभव में निहित मानती है; गलतियाँ अधिगम का स्वाभाविक भाग हैं, इसलिए III गलत है।"},
  {"id":"cdp-child-development-1043","question":"NCF 2005 recommends that English be taught:","options":["Through grammar-translation drills from Class 1 to build accuracy early","Only from Class 6 onwards, once the home language is fully secure","As a replacement for the mother tongue as the medium of instruction as early as possible","Within a multilingual approach, alongside the home language, not replacing it"],"answer":3,"explanation":"NCF 2005 places English within a multilingual framework, building on the child’s home language rather than replacing it.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"NCF 2005 अनुशंसा करती है कि अंग्रेज़ी पढ़ाई जाए:","optionsHi":["कक्षा 1 से व्याकरण-अनुवाद अभ्यासों द्वारा, ताकि आरंभ में ही शुद्धता बने","केवल कक्षा 6 से, जब घर की भाषा पूरी तरह सुदृढ़ हो जाए","जितनी जल्दी हो सके शिक्षण माध्यम के रूप में मातृभाषा के स्थान पर","बहुभाषिक दृष्टिकोण के भीतर, घर की भाषा के साथ-साथ, उसे बदलते हुए नहीं"],"explanationHi":"NCF 2005 अंग्रेज़ी को बहुभाषिक ढाँचे में रखती है, जो बच्चे की घर की भाषा पर आधारित होता है, उसे बदलता नहीं।"},
  {"id":"cdp-child-development-1044","question":"Which statement reflects NCF 2005’s stance on inclusion?","options":["Children with disabilities should study only in special schools with trained staff","Inclusion means placing all children physically in one room, which by itself is enough to meet their needs","The school should adapt curriculum, teaching and assessment so every child takes part meaningfully","Inclusion is optional and depends on whether the school has resources to spare"],"answer":2,"explanation":"Inclusion in NCF 2005 means the system changes to meet diverse needs; mere physical placement without adaptation is integration at best.","difficulty":"hard","source":"CTET · KVS PRT","questionHi":"समावेशन के प्रति NCF 2005 के रुख़ को कौन-सा कथन दर्शाता है?","optionsHi":["विकलांग बच्चों को केवल प्रशिक्षित स्टाफ वाले विशेष विद्यालयों में पढ़ना चाहिए","समावेशन का अर्थ सभी बच्चों को एक कमरे में रखना है, जो अपने आप में उनकी आवश्यकताओं को पूरा करने के लिए पर्याप्त है","विद्यालय को पाठ्यचर्या, शिक्षण और आकलन को इस प्रकार ढालना चाहिए कि हर बच्चा सार्थक रूप से भाग ले सके","समावेशन वैकल्पिक है और इस पर निर्भर करता है कि विद्यालय के पास अतिरिक्त संसाधन हैं या नहीं"],"explanationHi":"NCF 2005 में समावेशन का अर्थ है कि व्यवस्था विविध आवश्यकताओं को पूरा करने के लिए स्वयं को बदले; बिना अनुकूलन केवल भौतिक रूप से साथ बैठाना अधिक से अधिक एकीकरण है।"},
  {"id":"cdp-child-development-1045","question":"Aarav’s parents set clear rules about screen time and homework, explain why the rules matter, listen to his point of view and sometimes adjust a rule after discussion, while remaining warm and affectionate. In Baumrind’s terms, their style is:","options":["Authoritarian","Permissive","Authoritative","Uninvolved"],"answer":2,"explanation":"High warmth plus high, reasoned demands with two-way communication is authoritative parenting. Clear rules alone do not make it authoritarian; authoritarian parents demand obedience without explanation or warmth.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"आरव के माता-पिता स्क्रीन-समय और गृहकार्य के स्पष्ट नियम बनाते हैं, उन नियमों का कारण समझाते हैं, उसकी बात सुनते हैं और चर्चा के बाद कभी-कभी कोई नियम बदल देते हैं, जबकि स्नेहशील और प्रेमपूर्ण भी बने रहते हैं। बॉमरिंड की शब्दावली में उनकी शैली है:","optionsHi":["सत्तावादी (अधिनायकवादी)","अनुमतिदायक (उदार)","अधिकारपूर्ण-लोकतांत्रिक (प्राधिकारी)","उपेक्षापूर्ण (अनासक्त)"],"explanationHi":"उच्च स्नेह के साथ तर्कसंगत उच्च अपेक्षाएँ और द्विपक्षीय संवाद अधिकारपूर्ण-लोकतांत्रिक पालन-पोषण है। केवल स्पष्ट नियम उसे सत्तावादी नहीं बनाते; सत्तावादी माता-पिता बिना स्पष्टीकरण या स्नेह के आज्ञापालन की माँग करते हैं।"},
  {"id":"cdp-child-development-1046","question":"A father enforces strict rules with ‘Because I said so’, punishes disobedience harshly and rarely shows affection or asks his daughter’s views. Research on this style most commonly links it with children who are:","options":["Self-reliant, cheerful and socially confident in new situations","Impulsive and demanding, because they have been given too much freedom","Highly creative and willing to take intellectual risks in class","Obedient but often anxious, withdrawn or lacking in self-reliance"],"answer":3,"explanation":"Authoritarian parenting (high control, low warmth) tends to produce compliance with anxiety and weaker self-direction. Impulsiveness is the typical outcome of permissive parenting.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"एक पिता ‘क्योंकि मैंने कहा’ कहकर कड़े नियम लागू करता है, अवज्ञा पर कठोर दंड देता है और बेटी के प्रति शायद ही स्नेह दिखाता है या उसकी राय पूछता है। इस शैली पर शोध प्रायः इसे किन बच्चों से जोड़ता है?","optionsHi":["आत्मनिर्भर, प्रसन्नचित्त और नई परिस्थितियों में सामाजिक रूप से आत्मविश्वासी","आवेगी और माँग करने वाले, क्योंकि उन्हें बहुत अधिक स्वतंत्रता दी गई है","अत्यंत सृजनशील और कक्षा में बौद्धिक जोखिम लेने को तत्पर","आज्ञाकारी, परंतु प्रायः चिंतित, अंतर्मुखी या आत्मनिर्भरता में कमज़ोर"],"explanationHi":"सत्तावादी पालन-पोषण (उच्च नियंत्रण, कम स्नेह) प्रायः चिंता के साथ अनुपालन और कमज़ोर आत्म-निर्देशन उत्पन्न करता है। आवेगशीलता अनुमतिदायक पालन-पोषण का विशिष्ट परिणाम है।"},
  {"id":"cdp-child-development-1047","question":"Very loving parents of a Class 4 boy make almost no demands, let him decide his own bedtime and food, and rarely correct misbehaviour. A teacher notices he struggles to follow class rules and gives up quickly. These patterns are most typical of which parenting style?","options":["Permissive (indulgent)","Authoritative","Authoritarian","Uninvolved (neglectful)"],"answer":0,"explanation":"Permissive parents are warm but low in demands and control, which is linked with poor self-control and impulsivity. Uninvolved parents are low in warmth as well.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के एक बालक के अत्यंत स्नेही माता-पिता लगभग कोई माँग नहीं करते, उसे अपना सोने का समय और भोजन स्वयं तय करने देते हैं और बुरे व्यवहार को शायद ही सुधारते हैं। शिक्षक देखता है कि उसे कक्षा के नियमों का पालन करने में कठिनाई होती है और वह जल्दी हार मान लेता है। ये प्रतिरूप किस पालन-पोषण शैली के सबसे विशिष्ट हैं?","optionsHi":["अनुमतिदायक (उदार)","अधिकारपूर्ण-लोकतांत्रिक (प्राधिकारी)","सत्तावादी (अधिनायकवादी)","उपेक्षापूर्ण (अनासक्त)"],"explanationHi":"अनुमतिदायक माता-पिता स्नेही होते हैं पर माँग और नियंत्रण में कम, जो कमज़ोर आत्म-नियंत्रण और आवेगशीलता से जुड़ा है। उपेक्षापूर्ण माता-पिता स्नेह में भी कम होते हैं।"},
  {"id":"cdp-child-development-1048","question":"On the two dimensions of responsiveness (warmth) and demandingness (control), which combination defines the parenting style most consistently linked with the poorest outcomes for children?","options":["High responsiveness, low demandingness","Low responsiveness, high demandingness","Low responsiveness, low demandingness","High responsiveness, high demandingness"],"answer":2,"explanation":"Low on both is the uninvolved (neglectful) style added by Maccoby and Martin, consistently associated with the worst outcomes. High on both is authoritative.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अनुक्रियाशीलता (स्नेह) और माँगशीलता (नियंत्रण) के दो आयामों पर, कौन-सा संयोजन उस पालन-पोषण शैली को परिभाषित करता है जो बच्चों के सबसे निम्न परिणामों से सर्वाधिक संगत रूप से जुड़ी है?","optionsHi":["उच्च अनुक्रियाशीलता, निम्न माँगशीलता","निम्न अनुक्रियाशीलता, उच्च माँगशीलता","निम्न अनुक्रियाशीलता, निम्न माँगशीलता","उच्च अनुक्रियाशीलता, उच्च माँगशीलता"],"explanationHi":"दोनों में निम्न होना उपेक्षापूर्ण (अनासक्त) शैली है, जिसे मैकोबी और मार्टिन ने जोड़ा, और जो सबसे बुरे परिणामों से लगातार जुड़ी है। दोनों में उच्च होना अधिकारपूर्ण-लोकतांत्रिक शैली है।"},
  {"id":"cdp-child-development-1049","question":"Which statement about agents of socialisation is most accurate?","options":["The school is the primary agent, as children spend most of their waking time there","The family is usually the primary agent; school, peers and media are key secondary agents","Socialisation is complete by the time a child enters school at about age six","Media cannot act as an agent of socialisation, since it is not a person or a group the child interacts with"],"answer":1,"explanation":"Primary socialisation, the first learning of language, values and roles, happens mainly in the family; school, peers and media shape secondary socialisation, which continues throughout life.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"समाजीकरण के कारकों (अभिकर्ताओं) के बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["विद्यालय प्राथमिक कारक है, क्योंकि बच्चे अपने जागने का अधिकांश समय वहीं बिताते हैं","परिवार प्रायः प्राथमिक कारक है; विद्यालय, सहपाठी और मीडिया प्रमुख द्वितीयक कारक हैं","लगभग छह वर्ष की आयु में विद्यालय में प्रवेश तक समाजीकरण पूर्ण हो जाता है","मीडिया समाजीकरण का कारक नहीं हो सकता, क्योंकि वह कोई व्यक्ति या समूह नहीं है जिससे बच्चा अंतःक्रिया करता हो"],"explanationHi":"प्राथमिक समाजीकरण, यानी भाषा, मूल्यों और भूमिकाओं की पहली सीख, मुख्यतः परिवार में होता है; विद्यालय, सहपाठी और मीडिया द्वितीयक समाजीकरण को आकार देते हैं, जो जीवन भर चलता रहता है।"},
  {"id":"cdp-child-development-1050","question":"In a co-educational school, girls are always asked to decorate the class board and serve snacks at functions, while boys are asked to carry benches and manage the sound system. No textbook says girls and boys should do this. What is this an example of?","options":["The formal curriculum teaching gender equality through daily practice","Biological differences determining children’s interests","Peer pressure among students shaping who volunteers for which task","The hidden curriculum, socialising students into gender stereotypes"],"answer":3,"explanation":"Unstated messages carried by routines and practices form the hidden curriculum; here the school itself socialises gender roles. Rotating all tasks among all students would counter it.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"एक सह-शिक्षा विद्यालय में लड़कियों से हमेशा कक्षा का बोर्ड सजाने और समारोहों में अल्पाहार परोसने को कहा जाता है, जबकि लड़कों से बेंच उठाने और ध्वनि-व्यवस्था सँभालने को। किसी पाठ्यपुस्तक में नहीं लिखा कि लड़के-लड़कियाँ ऐसा करें। यह किसका उदाहरण है?","optionsHi":["औपचारिक पाठ्यचर्या का दैनिक व्यवहार के माध्यम से लैंगिक समानता सिखाना","जैविक भिन्नताओं द्वारा बच्चों की रुचियों का निर्धारण","विद्यार्थियों के बीच समवयस्क दबाव का यह तय करना कि कौन-सा कार्य कौन स्वेच्छा से करे","छिपी हुई पाठ्यचर्या, जो विद्यार्थियों का लैंगिक रूढ़िबद्ध धारणाओं में समाजीकरण करती है"],"explanationHi":"दिनचर्या और प्रथाओं द्वारा दिए गए अनकहे संदेश छिपी हुई पाठ्यचर्या बनाते हैं; यहाँ विद्यालय स्वयं लैंगिक भूमिकाओं का समाजीकरण कर रहा है। सभी कार्यों को सभी विद्यार्थियों में बारी-बारी से बाँटना इसका प्रतिकार करेगा।"},
  {"id":"cdp-child-development-1051","question":"In Bandura’s Bobo doll studies, children who saw a model punished for hitting the doll imitated less. But when later offered rewards for showing what the model had done, they reproduced the aggression as much as other children. What does this demonstrate?","options":["Seeing the model punished stopped the children from learning the behaviour in the first place","Children learn only those behaviours for which they themselves have been directly and personally reinforced","Observation can produce learning without reinforcement; consequences affect whether it is performed","Aggression is largely inherited, so watching the model made no real difference to what they learnt"],"answer":2,"explanation":"Seeing the model punished suppressed performance, not learning: the children had acquired the behaviour and displayed it once given an incentive. This is Bandura’s learning–performance distinction.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"बैंडूरा के बोबो गुड़िया अध्ययनों में, जिन बच्चों ने किसी आदर्श (मॉडल) को गुड़िया को मारने के लिए दंडित होते देखा, उन्होंने कम अनुकरण किया। परंतु जब बाद में उन्हें आदर्श द्वारा किया गया दिखाने पर पुरस्कार दिए गए, तो उन्होंने आक्रामकता को उतना ही दोहराया जितना अन्य बच्चों ने। यह क्या दर्शाता है?","optionsHi":["आदर्श को दंडित होते देखने से बच्चों ने उस व्यवहार को सीखा ही नहीं","बच्चे केवल वही व्यवहार सीखते हैं जिनके लिए उन्हें स्वयं प्रत्यक्ष और व्यक्तिगत रूप से पुनर्बलन मिला हो","अवलोकन से पुनर्बलन के बिना भी अधिगम हो सकता है; परिणाम इस पर असर डालते हैं कि व्यवहार प्रदर्शित होगा या नहीं","आक्रामकता काफ़ी हद तक आनुवंशिक है, इसलिए आदर्श को देखने से उन्होंने जो सीखा उस पर कोई वास्तविक अंतर नहीं पड़ा"],"explanationHi":"आदर्श को दंडित होते देखने ने प्रदर्शन को दबाया, अधिगम को नहीं: बच्चों ने व्यवहार सीख लिया था और प्रोत्साहन मिलने पर उसे दिखाया। यह बैंडूरा का अधिगम और प्रदर्शन का भेद है।"},
  {"id":"cdp-child-development-1052","question":"After watching a wrestling show, several Class 3 boys copy the moves on smaller children during recess. Which response by the teacher is most in line with social learning theory and good practice?","options":["Discuss what was seen and why it hurts in real life, and model and praise safer ways to play","Ignore it, since children soon forget what they see on TV and the copying will fade by itself","Punish the boys publicly so that the rest of the class sees the cost and never tries it","Tell the parents to stop all TV at home, since media has only harmful effects on children"],"answer":0,"explanation":"Children imitate models; teachers can build media literacy, offer and reinforce alternative models. Public punishment models aggression itself, and media can also have positive effects.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कुश्ती का कार्यक्रम देखने के बाद कक्षा 3 के कई लड़के मध्यावकाश में छोटे बच्चों पर वही दाँव-पेंच आज़माते हैं। सामाजिक अधिगम सिद्धांत और अच्छे अभ्यास के अनुरूप शिक्षक की कौन-सी प्रतिक्रिया सबसे उपयुक्त है?","optionsHi":["जो देखा और वास्तविक जीवन में उससे चोट क्यों लगती है, इस पर चर्चा करना, तथा खेलने के सुरक्षित तरीकों का आदर्श प्रस्तुत करना और उनकी सराहना करना","अनदेखा करना, क्योंकि बच्चे टीवी पर जो देखते हैं उसे जल्दी भूल जाते हैं और यह नकल अपने आप खत्म हो जाएगी","लड़कों को सबके सामने दंडित करना, ताकि शेष कक्षा कीमत देख ले और कभी ऐसा न करे","अभिभावकों से घर पर सारा टीवी बंद करने को कहना, क्योंकि मीडिया का बच्चों पर केवल हानिकारक प्रभाव होता है"],"explanationHi":"बच्चे आदर्शों की नकल करते हैं; शिक्षक मीडिया साक्षरता बढ़ा सकते हैं, वैकल्पिक आदर्श प्रस्तुत कर उन्हें पुष्ट कर सकते हैं। सार्वजनिक दंड स्वयं आक्रामकता का आदर्श बनता है, और मीडिया के सकारात्मक प्रभाव भी हो सकते हैं।"},
  {"id":"cdp-child-development-1053","question":"Bandura found that children who watched a model being rewarded for a behaviour were more likely to copy it. This effect on the observer is called:","options":["Vicarious reinforcement","Negative reinforcement","Classical conditioning","Shaping"],"answer":0,"explanation":"Seeing a model rewarded increases the observer’s tendency to perform the behaviour: vicarious reinforcement. Negative reinforcement is removal of an unpleasant stimulus after the learner’s own response.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"बैंडूरा ने पाया कि जिन बच्चों ने किसी आदर्श को किसी व्यवहार के लिए पुरस्कृत होते देखा, वे उसकी नकल करने की अधिक संभावना रखते थे। पर्यवेक्षक पर इस प्रभाव को कहते हैं:","optionsHi":["प्रतिनिधिक (विकारियस) पुनर्बलन","नकारात्मक पुनर्बलन","शास्त्रीय अनुबंधन","आकार देना (शेपिंग)"],"explanationHi":"आदर्श को पुरस्कृत होते देखना पर्यवेक्षक की उस व्यवहार को करने की प्रवृत्ति बढ़ाता है: प्रतिनिधिक पुनर्बलन। नकारात्मक पुनर्बलन अधिगमकर्ता की अपनी अनुक्रिया के बाद किसी अप्रिय उद्दीपक को हटाना है।"},
  {"id":"cdp-child-development-1054","question":"A teacher keeps telling her class, ‘Speak softly and politely to each other,’ but she herself shouts at children when annoyed. According to research on modelling, what is most likely?","options":["Children will follow her instructions, since words matter more than actions","Children will ignore both her words and her actions","Children are likely to imitate what she does more than what she says","Children will speak politely only to her and shout at each other"],"answer":2,"explanation":"Studies on modelling show that when words and actions conflict, children tend to copy the model’s actions; teachers socialise more by example than by preaching.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक शिक्षिका अपनी कक्षा से बार-बार कहती है, ‘एक-दूसरे से धीरे और विनम्रता से बोलो,’ परंतु स्वयं नाराज़ होने पर बच्चों पर चिल्लाती है। आदर्श-अनुकरण पर शोध के अनुसार सबसे संभावित क्या है?","optionsHi":["बच्चे उसके निर्देशों का पालन करेंगे, क्योंकि शब्द कर्मों से अधिक महत्त्वपूर्ण होते हैं","बच्चे उसके शब्द और कर्म दोनों की उपेक्षा करेंगे","बच्चे उसके कहने से अधिक उसके करने की नकल करने की संभावना रखते हैं","बच्चे केवल उससे विनम्रता से बोलेंगे और आपस में चिल्लाएँगे"],"explanationHi":"आदर्श-अनुकरण पर अध्ययन दिखाते हैं कि जब शब्द और कर्म में टकराव हो, तो बच्चे आदर्श के कर्मों की नकल करते हैं; शिक्षक उपदेश से अधिक उदाहरण द्वारा समाजीकरण करते हैं।"},
  {"id":"cdp-child-development-1055","question":"A Class 5 teacher wants to use peer influence positively. Which practice is most suitable?","options":["Seating the weakest students together so that they do not feel embarrassed in front of others","Ranking students publicly so that peer competition pushes every child to work much harder each week","Forbidding students to talk to each other in class so that they are not distracted by peers","Peer tutoring and cooperative tasks where students share responsibility for each other’s learning"],"answer":3,"explanation":"Peers are a powerful agent of socialisation; structured cooperation and peer tutoring channel that influence toward learning and prosocial behaviour. Public ranking breeds rivalry and inferiority.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक शिक्षिका समवयस्क प्रभाव का सकारात्मक उपयोग करना चाहती है। कौन-सा अभ्यास सबसे उपयुक्त है?","optionsHi":["सबसे कमज़ोर विद्यार्थियों को साथ बैठाना, ताकि वे दूसरों के सामने शर्मिंदा महसूस न करें","विद्यार्थियों को सार्वजनिक रूप से क्रमबद्ध करना, ताकि समवयस्क प्रतिस्पर्धा हर सप्ताह हर बच्चे को बहुत अधिक परिश्रम के लिए प्रेरित करे","कक्षा में विद्यार्थियों को आपस में बात करने से रोकना, ताकि साथियों से उनका ध्यान न भटके","सहपाठी शिक्षण और सहकारी कार्य, जहाँ विद्यार्थी एक-दूसरे के अधिगम की ज़िम्मेदारी साझा करें"],"explanationHi":"समवयस्क समाजीकरण का शक्तिशाली कारक हैं; संरचित सहयोग और सहपाठी शिक्षण उस प्रभाव को अधिगम और समाज-हितैषी व्यवहार की ओर मोड़ते हैं। सार्वजनिक श्रेणीकरण प्रतिद्वंद्विता और हीनभावना पैदा करता है।"},
  {"id":"cdp-child-development-1056","question":"Which of these statements about the role of peers in development are correct? I. Peer interaction among equals helps children take others’ perspectives. II. Peer groups give a sense of belonging and identity. III. Peers influence only negative behaviour. IV. Children can learn to negotiate and resolve conflicts through peer play.","options":["I, II and IV only","I and III only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"Peers foster perspective-taking, belonging and social skills; their influence can be positive or negative, so III is false.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"विकास में समवयस्कों की भूमिका के बारे में इनमें से कौन-से कथन सही हैं? I. बराबरी वालों के बीच अंतःक्रिया बच्चों को दूसरों का दृष्टिकोण समझने में सहायता करती है। II. समवयस्क समूह अपनेपन और पहचान की भावना देते हैं। III. समवयस्क केवल नकारात्मक व्यवहार को प्रभावित करते हैं। IV. बच्चे समवयस्कों के साथ खेल से बातचीत करना और विवाद सुलझाना सीख सकते हैं।","optionsHi":["केवल I, II और IV","केवल I और III","केवल II, III और IV","I, II, III और IV"],"explanationHi":"समवयस्क दृष्टिकोण-ग्रहण, अपनापन और सामाजिक कौशलों को बढ़ावा देते हैं; उनका प्रभाव सकारात्मक या नकारात्मक हो सकता है, इसलिए III असत्य है।"},
  {"id":"cdp-child-development-1057","question":"At the start of the year, a teacher is told (wrongly) that certain students are ‘late bloomers’ likely to make big gains. By the year’s end these students have gained more than others. Which phenomenon does this illustrate?","options":["Halo effect","Self-fulfilling prophecy (Pygmalion effect) through teacher expectations","Hawthorne effect, as the students knew they were being observed and studied","Regression to the mean"],"answer":1,"explanation":"Teachers’ expectations change how they treat students (attention, feedback, warmth), which can bring about the expected gains, as in Rosenthal and Jacobson’s study. The students did not know of the label, so it is not a Hawthorne effect.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"वर्ष के आरंभ में एक शिक्षक को (गलत ढंग से) बताया जाता है कि कुछ विद्यार्थी ‘देर से खिलने वाले’ हैं जिनमें बड़ी प्रगति की संभावना है। वर्ष के अंत तक इन विद्यार्थियों ने दूसरों से अधिक प्रगति की। यह किस परिघटना को दर्शाता है?","optionsHi":["प्रभामंडल प्रभाव","शिक्षक की अपेक्षाओं के माध्यम से स्व-पूर्ति भविष्यवाणी (पिग्मेलियन प्रभाव)","हॉथोर्न प्रभाव, क्योंकि विद्यार्थियों को पता था कि उन्हें देखा और अध्ययन किया जा रहा है","माध्य की ओर प्रत्यावर्तन"],"explanationHi":"शिक्षकों की अपेक्षाएँ उनके विद्यार्थियों से व्यवहार (ध्यान, प्रतिक्रिया, स्नेह) को बदल देती हैं, जिससे अपेक्षित प्रगति हो सकती है, जैसा रोज़ेंथल और जैकबसन के अध्ययन में हुआ। विद्यार्थियों को इस लेबल का पता नहीं था, इसलिए यह हॉथोर्न प्रभाव नहीं है।"},
  {"id":"cdp-child-development-1058","question":"From early childhood, Meera’s relatives give her dolls and kitchen sets and praise her for being ‘quiet and helpful’, while her brother gets cars and bats and is praised for being ‘brave’. By age five she says, ‘Cricket is for boys.’ Which statement best explains this?","options":["Gender preferences are fixed at birth, so her experiences at home have had little effect on them","Gender roles are learnt largely through socialisation by the family and others around the child","The pre-primary school has caused the belief, since home influences are weak at this age","Meera is in Kohlberg’s Stage 1 and accepts the rule because she fears being punished"],"answer":1,"explanation":"Differential toys, praise and expectations from the family socialise gender stereotypes early; teachers can counter them by offering all activities to all children.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"बचपन से ही मीरा के रिश्तेदार उसे गुड़ियाँ और रसोई के खिलौने देते हैं और उसे ‘शांत और मददगार’ होने के लिए सराहते हैं, जबकि उसके भाई को गाड़ियाँ और बल्ले मिलते हैं और उसे ‘बहादुर’ कहकर सराहा जाता है। पाँच वर्ष की आयु तक वह कहती है, ‘क्रिकेट लड़कों के लिए है।’ इसे कौन-सा कथन सबसे अच्छी तरह समझाता है?","optionsHi":["लैंगिक पसंद जन्म से निश्चित होती है, इसलिए घर के उसके अनुभवों का उन पर कम प्रभाव पड़ा है","लैंगिक भूमिकाएँ काफ़ी हद तक परिवार और बच्चे के आसपास के अन्य लोगों द्वारा समाजीकरण से सीखी जाती हैं","पूर्व-प्राथमिक विद्यालय ने यह विश्वास पैदा किया है, क्योंकि इस आयु में घर का प्रभाव कमज़ोर होता है","मीरा कोहलबर्ग के चरण 1 में है और नियम इसलिए मानती है कि उसे दंड का भय है"],"explanationHi":"परिवार से मिलने वाले भिन्न खिलौने, प्रशंसा और अपेक्षाएँ लैंगिक रूढ़िबद्ध धारणाओं का आरंभ में ही समाजीकरण करती हैं; शिक्षक सभी बच्चों को सभी गतिविधियाँ देकर इनका प्रतिकार कर सकते हैं।"},
  {"id":"cdp-child-development-1059","question":"Assertion (A): Children raised in joint families often have several adult models and caregivers. Reason (R): Socialisation in a joint family is carried out only by the mother.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A joint family offers grandparents, uncles, aunts and cousins as models and caregivers; this contradicts R, so A is true and R is false.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"अभिकथन (A): संयुक्त परिवारों में पले बच्चों के प्रायः कई वयस्क आदर्श और देखभालकर्ता होते हैं। कारण (R): संयुक्त परिवार में समाजीकरण केवल माँ द्वारा किया जाता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"संयुक्त परिवार में दादा-दादी, चाचा-चाची, बुआ और चचेरे भाई-बहन आदर्श और देखभालकर्ता के रूप में मिलते हैं; यह R के विपरीत है, इसलिए A सत्य है और R असत्य।"},
  {"id":"cdp-child-development-1060","question":"Several Class 9 girls stop eating lunch, saying they want to look like actresses on social media. What is the most suitable response from the school?","options":["Ban phones in school, since social media is the only real cause of such eating problems among girls","Tell the girls firmly that their worries are silly and that they must eat their lunch","Run media-literacy talks on edited images and body diversity, involving parents and counsellors","Ignore it, since such dieting is a passing fad among teenagers that soon fades by itself"],"answer":2,"explanation":"Media is a strong agent of socialisation in adolescence; building critical viewing, healthy self-image and adult support addresses it, while dismissing or banning alone does not.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 9 की कई लड़कियाँ दोपहर का भोजन करना बंद कर देती हैं, यह कहकर कि वे सोशल मीडिया की अभिनेत्रियों जैसी दिखना चाहती हैं। विद्यालय की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["विद्यालय में फ़ोन पर प्रतिबंध लगाना, क्योंकि लड़कियों में ऐसी खान-पान की समस्याओं का एकमात्र वास्तविक कारण सोशल मीडिया है","लड़कियों से दृढ़ता से कहना कि उनकी चिंताएँ मूर्खतापूर्ण हैं और उन्हें दोपहर का भोजन करना ही होगा","संपादित छवियों और शारीरिक विविधता पर मीडिया-साक्षरता वार्ताएँ आयोजित करना, जिसमें अभिभावकों और परामर्शदाताओं को शामिल किया जाए","अनदेखा करना, क्योंकि किशोरों में ऐसा डाइटिंग एक क्षणिक चलन है जो अपने आप खत्म हो जाता है"],"explanationHi":"किशोरावस्था में मीडिया समाजीकरण का सशक्त कारक है; आलोचनात्मक दृष्टि, स्वस्थ आत्म-छवि और वयस्कों का सहयोग इसे संबोधित करते हैं, जबकि केवल टालना या प्रतिबंध लगाना नहीं।"},
  {"id":"cdp-child-development-1061","question":"A shy child makes her parents speak more softly and cautiously, while her outgoing brother draws louder, more playful interactions from the same parents. This shows that socialisation is:","options":["A one-way process in which parents shape the child, who simply absorbs it","Entirely determined by each child’s heredity, regardless of how parents behave","Fixed once the child enters school and peers take over","A two-way process in which children also influence their socialising agents"],"answer":3,"explanation":"Children’s temperament shapes how parents treat them, which in turn shapes the children; socialisation is bidirectional.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक संकोची बालिका अपने माता-पिता को अधिक धीरे और सतर्कता से बोलने के लिए प्रेरित करती है, जबकि उसका मिलनसार भाई उन्हीं माता-पिता से अधिक ऊँची आवाज़ वाली और खिलंदड़ी अंतःक्रियाएँ पाता है। यह दर्शाता है कि समाजीकरण है:","optionsHi":["एकतरफ़ा प्रक्रिया, जिसमें माता-पिता बच्चे को आकार देते हैं और बच्चा केवल ग्रहण करता है","पूर्णतः प्रत्येक बच्चे की आनुवंशिकता से निर्धारित, चाहे माता-पिता कैसा भी व्यवहार करें","विद्यालय में प्रवेश के बाद स्थिर हो जाने वाला, जब समवयस्क उसका स्थान ले लेते हैं","द्विपक्षीय प्रक्रिया, जिसमें बच्चे भी अपने समाजीकरण के कारकों को प्रभावित करते हैं"],"explanationHi":"बच्चों का स्वभाव माता-पिता के उनके साथ व्यवहार को आकार देता है, जो फिर बच्चों को आकार देता है; समाजीकरण द्विदिशीय है।"},
  {"id":"cdp-child-development-1062","question":"On a sociogram of Class 6, Ravi is named by nobody as a friend and also by nobody as someone they dislike; Kunal is named by many as someone they dislike and by almost none as a friend. In the sociometric categories, they are respectively:","options":["Rejected and neglected","Neglected and rejected","Controversial and rejected","Neglected and controversial"],"answer":1,"explanation":"Neglected children receive few positive and few negative nominations; rejected ones receive many negative and few positive. Controversial children get many of both.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 6 के एक समाजमिति-आरेख (सोशियोग्राम) में रवि को कोई मित्र के रूप में नहीं चुनता और कोई नापसंद के रूप में भी नहीं चुनता; कुणाल को कई लोग नापसंद करने वाले के रूप में चुनते हैं और लगभग कोई मित्र के रूप में नहीं। समाजमितीय श्रेणियों में वे क्रमशः हैं:","optionsHi":["अस्वीकृत और उपेक्षित","उपेक्षित और अस्वीकृत","विवादास्पद और अस्वीकृत","उपेक्षित और विवादास्पद"],"explanationHi":"उपेक्षित बच्चों को कम सकारात्मक और कम नकारात्मक नामांकन मिलते हैं; अस्वीकृत बच्चों को अनेक नकारात्मक और कम सकारात्मक। विवादास्पद बच्चों को दोनों प्रकार के अनेक नामांकन मिलते हैं।"},
  {"id":"cdp-child-development-1063","question":"Using the sociogram, the teacher finds two neglected and three rejected children in Class 6. Which plan is most appropriate?","options":["Display the sociogram so that the class can see who is left out and make an effort to include them","Tell the rejected children privately that being disliked is a result of their own behaviour","Seat the rejected children apart from others to avoid conflict during group activities","Keep the results confidential and plan groupings, roles and social-skill support to include them"],"answer":3,"explanation":"Sociometric data should be confidential and used to restructure interaction; rejected children especially need social-skill support and inclusive grouping, not exposure or isolation.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"समाजमिति-आरेख से शिक्षक को कक्षा 6 में दो उपेक्षित और तीन अस्वीकृत बच्चे मिलते हैं। कौन-सी योजना सबसे उपयुक्त है?","optionsHi":["आरेख प्रदर्शित करना ताकि कक्षा देख सके कि कौन छूटा हुआ है और उन्हें शामिल करने का प्रयास करे","अस्वीकृत बच्चों को निजी तौर पर बताना कि नापसंद किया जाना उनके अपने व्यवहार का परिणाम है","समूह गतिविधियों में विवाद से बचने के लिए अस्वीकृत बच्चों को दूसरों से अलग बैठाना","परिणामों को गोपनीय रखना और उन्हें शामिल करने के लिए समूह, भूमिकाएँ और सामाजिक-कौशल सहायता की योजना बनाना"],"explanationHi":"समाजमितीय आँकड़े गोपनीय रहने चाहिए और अंतःक्रिया को पुनर्गठित करने में काम आने चाहिए; अस्वीकृत बच्चों को विशेषकर सामाजिक-कौशल सहायता और समावेशी समूहीकरण की आवश्यकता है, उजागर करने या अलग करने की नहीं।"},
  {"id":"cdp-child-development-1064","question":"Which of these statements about media as an agent of socialisation is most defensible?","options":["Media teaches mainly violence and consumerism and has no real positive effects on children","Media can teach both prosocial and antisocial behaviour, and adult guidance shapes its effect","Media has little influence on children younger than ten, as they cannot yet follow its messages","Media affects mainly adults, since children treat what they watch as only entertainment"],"answer":1,"explanation":"Children learn from both aggressive and prosocial media content; co-viewing and discussion by adults moderate its effects.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"समाजीकरण के कारक के रूप में मीडिया के बारे में इनमें से कौन-सा कथन सबसे तर्कसंगत है?","optionsHi":["मीडिया मुख्यतः हिंसा और उपभोक्तावाद सिखाता है और बच्चों पर उसका कोई वास्तविक सकारात्मक प्रभाव नहीं होता","मीडिया समाज-हितैषी और समाज-विरोधी दोनों व्यवहार सिखा सकता है, और वयस्कों का मार्गदर्शन उसके प्रभाव को आकार देता है","मीडिया का दस वर्ष से छोटे बच्चों पर कम प्रभाव होता है, क्योंकि वे अभी उसके संदेश नहीं समझ सकते","मीडिया मुख्यतः वयस्कों को प्रभावित करता है, क्योंकि बच्चे जो देखते हैं उसे केवल मनोरंजन मानते हैं"],"explanationHi":"बच्चे आक्रामक और समाज-हितैषी दोनों प्रकार की मीडिया-सामग्री से सीखते हैं; वयस्कों द्वारा साथ देखना और चर्चा करना उसके प्रभावों को संतुलित करता है।"},
  {"id":"cdp-child-development-1065","question":"Assertion (A): Children of authoritative parents tend to show better self-regulation and social competence. Reason (R): Authoritative parents combine warmth with clear, reasoned limits that children come to understand and internalise.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Reasoned limits within a warm relationship are internalised as self-control, which is why authoritative parenting predicts self-regulation and competence.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"अभिकथन (A): अधिकारपूर्ण-लोकतांत्रिक माता-पिता के बच्चे प्रायः बेहतर आत्म-नियमन और सामाजिक सक्षमता दिखाते हैं। कारण (R): अधिकारपूर्ण-लोकतांत्रिक माता-पिता स्नेह को स्पष्ट, तर्कसंगत सीमाओं के साथ जोड़ते हैं, जिन्हें बच्चे समझने और आत्मसात करने लगते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"स्नेहपूर्ण संबंध में तर्कसंगत सीमाएँ आत्म-नियंत्रण के रूप में आत्मसात होती हैं, इसीलिए अधिकारपूर्ण-लोकतांत्रिक पालन-पोषण आत्म-नियमन और सक्षमता का पूर्वानुमान देता है।"},
  {"id":"cdp-child-development-1066","question":"A teacher notices that her Class 10 students follow friends on clothes, music and slang, but still rely on parents on decisions about further studies and core values. What does research on adolescent socialisation suggest?","options":["Parents lose almost all influence once a child reaches adolescence, so peers now guide everything","Peers decide everything for adolescents, including career choices and basic values","Peers matter more for everyday choices; parents stay influential on long-term values and plans","Adolescents are equally influenced by peers and by parents on every kind of matter"],"answer":2,"explanation":"Studies find parents and peers influence different domains: peers more for immediate, social choices; parents more for education, careers and basic values.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षिका देखती है कि उसकी कक्षा 10 के विद्यार्थी कपड़ों, संगीत और बोलचाल के लहजे में मित्रों का अनुसरण करते हैं, पर आगे की पढ़ाई और मूल मूल्यों के निर्णयों के लिए अब भी माता-पिता पर निर्भर रहते हैं। किशोरावस्था में समाजीकरण पर शोध क्या सुझाता है?","optionsHi":["किशोरावस्था में पहुँचते ही माता-पिता का लगभग सारा प्रभाव समाप्त हो जाता है, अब सब कुछ समवयस्क तय करते हैं","समवयस्क किशोरों के लिए सब कुछ तय करते हैं, करियर के चयन और मूल मूल्यों सहित","रोज़मर्रा के चयनों में समवयस्क अधिक मायने रखते हैं; दीर्घकालिक मूल्यों और योजनाओं पर माता-पिता प्रभावशाली बने रहते हैं","किशोर हर प्रकार के विषय में समवयस्कों और माता-पिता से समान रूप से प्रभावित होते हैं"],"explanationHi":"अध्ययन बताते हैं कि माता-पिता और समवयस्क अलग-अलग क्षेत्रों को प्रभावित करते हैं: तात्कालिक, सामाजिक चयनों में समवयस्क अधिक; शिक्षा, करियर और मूल मूल्यों में माता-पिता अधिक।"},
  {"id":"cdp-child-development-1067","question":"When a Class 2 child snatches a toy, Teacher A says, ‘Give it back now or no recess!’ Teacher B says, ‘Look, Priya is crying; she was playing with it. How would you feel if someone took yours?’ According to Hoffman, Teacher B’s approach, called induction, is more likely to:","options":["Make the child fear the teacher, which ensures good behaviour","Build empathy and help the child internalise moral standards","Have no effect, since young children cannot understand others’ feelings","Make the child more aggressive"],"answer":1,"explanation":"Inductive discipline points to the effects of the act on others, arousing empathy and fostering internalised morality; power assertion (Teacher A) tends to produce compliance only under surveillance.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"जब कक्षा 2 का एक बच्चा खिलौना छीन लेता है, तो शिक्षिका A कहती है, ‘अभी वापस करो वरना मध्यावकाश नहीं!’ शिक्षिका B कहती है, ‘देखो, प्रिया रो रही है; वह इससे खेल रही थी। अगर कोई तुम्हारा खिलौना ले ले तो तुम्हें कैसा लगेगा?’ हॉफमैन के अनुसार शिक्षिका B का दृष्टिकोण, जिसे प्रेरण (इंडक्शन) कहते हैं, किसकी अधिक संभावना रखता है?","optionsHi":["बच्चे को शिक्षिका से भयभीत करना, जिससे अच्छा व्यवहार सुनिश्चित हो","सहानुभूति विकसित करना और बच्चे को नैतिक मानकों को आत्मसात करने में सहायता देना","कोई प्रभाव न डालना, क्योंकि छोटे बच्चे दूसरों की भावनाएँ नहीं समझ सकते","बच्चे को और अधिक आक्रामक बनाना"],"explanationHi":"प्रेरणात्मक अनुशासन दूसरों पर कृत्य के प्रभावों की ओर इंगित करता है, जिससे सहानुभूति जागती है और आत्मसात नैतिकता पनपती है; शक्ति-प्रयोग (शिक्षिका A) प्रायः केवल निगरानी में अनुपालन उत्पन्न करता है।"},
  {"id":"cdp-child-development-1068","question":"During team games like kabaddi, Class 4 children must take turns, follow agreed rules, accept the umpire’s decision and work for the team. In terms of socialisation, such play mainly helps children:","options":["Learn cooperation, rule-following and their roles within a group","Develop only physical strength and stamina, as games have no social value","Become more egocentric, as they focus on winning","Learn rules only from adults, not from each other"],"answer":0,"explanation":"Organised games are a key medium of socialisation; children learn to coordinate roles, follow shared rules and cooperate, which Piaget and Mead both highlighted.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"कबड्डी जैसे टीम खेलों में कक्षा 4 के बच्चों को बारी लेनी होती है, तय नियमों का पालन करना होता है, निर्णायक का निर्णय मानना होता है और टीम के लिए खेलना होता है। समाजीकरण की दृष्टि से, ऐसा खेल मुख्यतः बच्चों को क्या सीखने में सहायता करता है?","optionsHi":["सहयोग, नियम-पालन और समूह में अपनी भूमिकाएँ सीखना","केवल शारीरिक शक्ति और सहनशक्ति विकसित करना, क्योंकि खेलों का कोई सामाजिक मूल्य नहीं है","अधिक अहंकेंद्रित बनना, क्योंकि वे जीतने पर ध्यान देते हैं","नियम केवल वयस्कों से सीखना, एक-दूसरे से नहीं"],"explanationHi":"संगठित खेल समाजीकरण का प्रमुख माध्यम हैं; बच्चे भूमिकाओं में समन्वय, साझा नियमों का पालन और सहयोग सीखते हैं, जिस पर पियाजे और मीड दोनों ने बल दिया।"},
  {"id":"cdp-child-development-1069","question":"Which of these statements about socialisation are correct? I. It continues throughout life. II. Its goals and methods vary across cultures. III. It is complete by the age of six. IV. The school can reinforce or counter what is learnt at home.","options":["I and III only","II and III only","I, II and IV only","I, II, III and IV"],"answer":2,"explanation":"Socialisation is lifelong, culture-specific, and the school can strengthen or challenge home learning, e.g. on gender roles; III is false because it does not end in early childhood.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"समाजीकरण के बारे में इनमें से कौन-से कथन सही हैं? I. यह जीवन भर चलता रहता है। II. इसके लक्ष्य और तरीके संस्कृतियों में भिन्न होते हैं। III. यह छह वर्ष की आयु तक पूर्ण हो जाता है। IV. विद्यालय घर पर सीखी बातों को पुष्ट कर सकता है या उनका प्रतिकार कर सकता है।","optionsHi":["केवल I और III","केवल II और III","केवल I, II और IV","I, II, III और IV"],"explanationHi":"समाजीकरण आजीवन चलता है, संस्कृति-विशिष्ट है, और विद्यालय घर की सीख को, जैसे लैंगिक भूमिकाओं पर, सुदृढ़ या चुनौतीपूर्ण बना सकता है; III असत्य है क्योंकि यह प्रारंभिक बाल्यावस्था में समाप्त नहीं होता।"},
  {"id":"cdp-child-development-1070","question":"A Class 6 teacher wants to scaffold students who find it hard to write an argumentative essay. Which plan is the best example of scaffolding?","options":["Give a planning frame for claim, reasons and conclusion, and withdraw it once they can plan alone","Write a model essay for weak students so that they can copy it out neatly and learn the expected form","Give extra marks to students who write long essays, so that others try to write more","Ask students to keep rewriting the essay on their own until they get it fully correct"],"answer":0,"explanation":"Scaffolding is temporary, adjustable support that lets learners do what they cannot yet do alone and is withdrawn as they improve. Writing it for them removes the learning, and rewriting alone gives no support.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 6 की एक शिक्षिका उन विद्यार्थियों को पाड़ (स्कैफोल्डिंग) देना चाहती है जिन्हें तर्कपूर्ण निबंध लिखना कठिन लगता है। कौन-सी योजना पाड़ का सर्वोत्तम उदाहरण है?","optionsHi":["दावे, कारणों और निष्कर्ष के लिए एक योजना-ढाँचा देना, और जब वे अकेले योजना बना सकें तो उसे हटा लेना","कमज़ोर विद्यार्थियों के लिए एक आदर्श निबंध लिख देना, ताकि वे उसे सफाई से उतारकर अपेक्षित रूप सीख लें","लंबे निबंध लिखने वाले विद्यार्थियों को अतिरिक्त अंक देना, ताकि दूसरे अधिक लिखने का प्रयास करें","विद्यार्थियों से कहना कि वे निबंध को स्वयं तब तक दोबारा लिखते रहें जब तक वह पूर्णतः सही न हो जाए"],"explanationHi":"पाड़ अस्थायी, समायोज्य सहायता है जो अधिगमकर्ताओं को वह करने देती है जो वे अभी अकेले नहीं कर सकते, और सुधार के साथ हटा ली जाती है। उनके लिए लिख देना अधिगम को समाप्त करता है, और अकेले दोबारा लिखना कोई सहायता नहीं देता।"},
  {"id":"cdp-child-development-1071","question":"A Class 5 student’s homework is always perfect because his tuition teacher solves each step for him, but in class tests he cannot do similar problems alone. A Vygotskian explanation is that:","options":["The help exceeded what he needed, so he never took over the steps himself and could not work alone","He is still in the pre-operational stage and so cannot yet handle written sums on his own","Homework should never involve adult help, since any help at all weakens independent learning","He lacks reinforcement in class, as the tuition teacher praises him but the class teacher does not"],"answer":0,"explanation":"Help leads to development only when the learner actively takes over the task and support is faded. Doing the task for him produces finished work but no internalisation.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 5 के एक विद्यार्थी का गृहकार्य हमेशा परिपूर्ण होता है क्योंकि उसका ट्यूशन शिक्षक हर चरण उसके लिए हल कर देता है, पर कक्षा-परीक्षाओं में वह वैसी ही समस्याएँ अकेले नहीं कर पाता। वाइगोत्स्की के अनुसार इसकी व्याख्या है कि:","optionsHi":["सहायता उसकी आवश्यकता से अधिक थी, इसलिए उसने चरणों को स्वयं कभी अपने हाथ में नहीं लिया और अकेले कार्य नहीं कर सका","वह अभी पूर्व-संक्रियात्मक अवस्था में है, इसलिए अभी स्वयं लिखित योग नहीं कर सकता","गृहकार्य में कभी वयस्क की सहायता नहीं होनी चाहिए, क्योंकि कोई भी सहायता स्वतंत्र अधिगम को कमज़ोर करती है","कक्षा में उसे पुनर्बलन नहीं मिलता, क्योंकि ट्यूशन शिक्षक उसकी प्रशंसा करता है पर कक्षा शिक्षक नहीं"],"explanationHi":"सहायता तभी विकास की ओर ले जाती है जब अधिगमकर्ता सक्रिय रूप से कार्य अपने हाथ में ले और सहायता धीरे-धीरे हटाई जाए। उसके लिए कार्य कर देना पूर्ण किया हुआ काम देता है, पर आंतरिकीकरण नहीं।"},
  {"id":"cdp-child-development-1072","question":"Vygotsky argued that the main problem for a child with a disability is often not the physical condition itself but its social consequences, and that alternative cultural tools can open other routes to development. Which school practice follows most directly from this view?","options":["Placing the child in a separate school so that she is not compared with others","Waiting for the child to outgrow or overcome the disability before teaching her the full curriculum","Providing tools such as Braille or sign language and full participation in class activities","Reducing the curriculum to self-care skills, since academic goals are unrealistic for her"],"answer":2,"explanation":"Vygotsky’s work on disability stressed compensation through alternative tools and inclusion in social activity. Segregation and low expectations deepen the social consequences he warned against.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"वाइगोत्स्की ने तर्क दिया कि विकलांगता वाले बच्चे की मुख्य समस्या प्रायः शारीरिक स्थिति स्वयं नहीं बल्कि उसके सामाजिक परिणाम हैं, और वैकल्पिक सांस्कृतिक उपकरण विकास के अन्य मार्ग खोल सकते हैं। इस दृष्टिकोण से सबसे प्रत्यक्ष रूप से कौन-सा विद्यालयी अभ्यास निकलता है?","optionsHi":["बच्ची को अलग विद्यालय में रखना, ताकि उसकी दूसरों से तुलना न हो","बच्ची को पूरा पाठ्यक्रम पढ़ाने से पहले इंतज़ार करना कि वह विकलांगता से उबर जाए","ब्रेल या सांकेतिक भाषा जैसे उपकरण उपलब्ध कराना और कक्षा-गतिविधियों में पूर्ण भागीदारी देना","पाठ्यक्रम को केवल स्वयं की देखभाल के कौशलों तक सीमित करना, क्योंकि उसके लिए शैक्षिक लक्ष्य अव्यावहारिक हैं"],"explanationHi":"विकलांगता पर वाइगोत्स्की का कार्य वैकल्पिक उपकरणों द्वारा क्षतिपूर्ति और सामाजिक गतिविधि में समावेशन पर बल देता है। अलगाव और कम अपेक्षाएँ उन्हीं सामाजिक परिणामों को गहरा करती हैं जिनके प्रति उसने चेताया था।"},
  {"id":"cdp-child-development-1073","question":"According to Vygotsky, which of the following is a higher mental function rather than an elementary one?","options":["Turning the head towards a sudden loud noise in the corridor during a lesson","The startle reflex of a newborn","Remembering a list by deliberately grouping the items into categories","Blinking when dust enters the eye"],"answer":2,"explanation":"Higher mental functions are deliberate, mediated by signs and culturally shaped, like voluntary, organised memory. Involuntary attention and reflexes are elementary functions given by biology.","difficulty":"very-hard","source":"CTET · KVS · State TETs","questionHi":"वाइगोत्स्की के अनुसार, निम्नलिखित में से कौन उच्चतर मानसिक प्रकार्य है, प्रारंभिक नहीं?","optionsHi":["पाठ के दौरान गलियारे में अचानक तेज़ आवाज़ की ओर सिर घुमाना","नवजात शिशु का चौंकने का प्रतिवर्त","वस्तुओं को जानबूझकर श्रेणियों में समूहित करके सूची याद रखना","आँख में धूल जाने पर पलक झपकाना"],"explanationHi":"उच्चतर मानसिक प्रकार्य जानबूझकर किए गए, संकेतों द्वारा मध्यस्थ और संस्कृति द्वारा निर्मित होते हैं, जैसे ऐच्छिक, संगठित स्मृति। अनैच्छिक ध्यान और प्रतिवर्त जैविक रूप से प्रदत्त प्रारंभिक प्रकार्य हैं।"},
  {"id":"cdp-child-development-1074","question":"A unit test in which each child works alone, with no hints or help, measures mainly which level in Vygotsky’s terms?","options":["The upper limit of the zone of proximal development","The actual (independent) developmental level","The level of potential development","The zone of proximal development as a whole"],"answer":1,"explanation":"Unassisted performance shows functions that have already matured. The potential level, and therefore the ZPD, can only be seen when help is given.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"एक इकाई परीक्षण, जिसमें प्रत्येक बच्चा अकेले, बिना संकेत या सहायता के कार्य करता है, वाइगोत्स्की की शब्दावली में मुख्यतः किस स्तर को मापता है?","optionsHi":["निकटस्थ विकास के क्षेत्र की ऊपरी सीमा","वास्तविक (स्वतंत्र) विकास स्तर","संभावित विकास स्तर","संपूर्ण निकटस्थ विकास का क्षेत्र"],"explanationHi":"बिना सहायता का प्रदर्शन उन प्रकार्यों को दिखाता है जो पहले ही परिपक्व हो चुके हैं। संभावित स्तर, और इसलिए निकटस्थ विकास का क्षेत्र (ZPD), केवल तब दिखता है जब सहायता दी जाए।"},
  {"id":"cdp-child-development-1075","question":"A Class 4 child is stuck on a word problem. Which teacher response is the best example of scaffolding?","options":["Telling him the answer quickly so that he does not get frustrated and give up","Asking, ‘What do we already know? What do we need to find? Which operation links them?’","Giving him a star only if he gets it right on the next attempt without any help","Moving him to an easier worksheet without discussion, so that he can succeed at once and stay motivated"],"answer":1,"explanation":"Guiding questions direct attention to the key features of the task while leaving the thinking to the child. Telling the answer or switching tasks removes the chance to work within his ZPD.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 4 का एक बच्चा शब्द-समस्या पर अटक गया है। शिक्षक की कौन-सी प्रतिक्रिया पाड़ (स्कैफोल्डिंग) का सर्वोत्तम उदाहरण है?","optionsHi":["उसे जल्दी उत्तर बता देना, ताकि वह निराश होकर हार न माने","पूछना, ‘हम पहले से क्या जानते हैं? हमें क्या ज्ञात करना है? कौन-सी संक्रिया दोनों को जोड़ती है?’","उसे स्टार केवल तब देना जब वह अगली बार बिना किसी सहायता के सही करे","बिना चर्चा के उसे आसान कार्यपत्रक पर ले जाना, ताकि वह तुरंत सफल हो और अभिप्रेरित रहे"],"explanationHi":"मार्गदर्शक प्रश्न कार्य की मुख्य विशेषताओं की ओर ध्यान दिलाते हैं जबकि चिंतन बच्चे पर छोड़ते हैं। उत्तर बता देना या कार्य बदल देना उसके ZPD में कार्य करने का अवसर छीन लेता है।"},
  {"id":"cdp-child-development-1076","question":"Students who have practised for years on an abacus often solve sums mentally by picturing the beads moving, without any abacus in front of them. In Vygotsky’s terms, this best shows:","options":["A cultural tool that has been internalised and now shapes mental activity","An elementary mental function that is given by heredity and present from birth","Egocentric thought","Bruner’s enactive mode only"],"answer":0,"explanation":"Vygotsky held that external cultural tools, once internalised, become means of thinking. The imagined abacus is a mediating tool now working inside the mind.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"जो विद्यार्थी वर्षों से अबेकस पर अभ्यास करते हैं, वे प्रायः सामने अबेकस न होने पर भी मोतियों के हिलने की कल्पना करके योग मन ही मन हल कर लेते हैं। वाइगोत्स्की की शब्दावली में यह सबसे अच्छी तरह दर्शाता है:","optionsHi":["एक सांस्कृतिक उपकरण जो आत्मसात हो चुका है और अब मानसिक गतिविधि को आकार देता है","आनुवंशिकता से प्रदत्त और जन्म से विद्यमान एक प्रारंभिक मानसिक प्रकार्य","अहंकेंद्रित चिंतन","केवल ब्रूनर का क्रियात्मक रूप"],"explanationHi":"वाइगोत्स्की का मानना था कि बाहरी सांस्कृतिक उपकरण आत्मसात होने पर चिंतन के साधन बन जाते हैं। कल्पित अबेकस एक मध्यस्थ उपकरण है जो अब मन के भीतर कार्य कर रहा है।"},
  {"id":"cdp-child-development-1077","question":"In a single-teacher multigrade school in rural Rajasthan, children of Classes 1 to 4 learn in one room and older children often help younger ones. From a Vygotskian viewpoint, the main advantage of this arrangement is that:","options":["Younger children learn to obey older children, which keeps the crowded room orderly","The teacher has less work to do and can focus on the oldest class","Older children automatically reach formal operations by teaching the younger ones","Older children can act as more knowledgeable others within younger children’s ZPD"],"answer":3,"explanation":"Mixed-age groups give younger children many more capable partners, and the older children also consolidate their learning by explaining. The point is guided learning, not obedience.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"ग्रामीण राजस्थान के एक एकल-शिक्षक बहु-कक्षा विद्यालय में कक्षा 1 से 4 के बच्चे एक कमरे में पढ़ते हैं और बड़े बच्चे प्रायः छोटों की सहायता करते हैं। वाइगोत्स्की के दृष्टिकोण से इस व्यवस्था का मुख्य लाभ यह है कि:","optionsHi":["छोटे बच्चे बड़ों की आज्ञा मानना सीखते हैं, जिससे भीड़-भरा कमरा व्यवस्थित रहता है","शिक्षक का कार्य कम होता है और वह सबसे बड़ी कक्षा पर ध्यान दे सकता है","बड़े बच्चे छोटों को पढ़ाकर अपने आप औपचारिक संक्रियाओं तक पहुँच जाते हैं","बड़े बच्चे छोटे बच्चों के ZPD में अधिक जानकार अन्य के रूप में कार्य कर सकते हैं"],"explanationHi":"मिश्रित-आयु समूह छोटे बच्चों को कहीं अधिक सक्षम साथी देते हैं, और बड़े बच्चे समझाकर अपने अधिगम को भी सुदृढ़ करते हैं। मुद्दा निर्देशित अधिगम है, आज्ञाकारिता नहीं।"},
  {"id":"cdp-child-development-1078","question":"A child has always said wet clothes ‘just dry in the sun’. After learning about evaporation in Class 5, she explains that water from the clothes turns into vapour faster when it is warm and windy. Vygotsky would see this as:","options":["Replacement of a scientific concept by an everyday one drawn from her experience at home","A school-taught scientific concept giving structure and awareness to an everyday one","Accommodation through her own discovery, without any real role for instruction","An iconic representation becoming enactive as she pictures the clothes drying"],"answer":1,"explanation":"Vygotsky argued that scientific concepts introduced by instruction reorganise spontaneous concepts, while everyday experience gives scientific concepts concrete meaning. The two develop in interaction.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"एक बच्ची हमेशा कहती थी कि गीले कपड़े ‘बस धूप में सूख जाते हैं’। कक्षा 5 में वाष्पीकरण के बारे में सीखने के बाद वह समझाती है कि कपड़ों से पानी गरम और हवादार मौसम में तेज़ी से वाष्प बन जाता है। वाइगोत्स्की इसे किस रूप में देखेंगे?","optionsHi":["घर के अपने अनुभव से आई रोज़मर्रा की अवधारणा द्वारा वैज्ञानिक अवधारणा का प्रतिस्थापन","विद्यालय में सिखाई गई वैज्ञानिक अवधारणा द्वारा रोज़मर्रा की अवधारणा को संरचना और जागरूकता देना","शिक्षण की किसी वास्तविक भूमिका के बिना, अपनी खोज द्वारा समायोजन","आइकॉनिक निरूपण का क्रियात्मक बन जाना, जब वह कपड़ों के सूखने की कल्पना करती है"],"explanationHi":"वाइगोत्स्की का तर्क था कि निर्देश द्वारा लाई गई वैज्ञानिक अवधारणाएँ स्वतःस्फूर्त अवधारणाओं को पुनर्गठित करती हैं, जबकि रोज़मर्रा का अनुभव वैज्ञानिक अवधारणाओं को ठोस अर्थ देता है। दोनों परस्पर क्रिया में विकसित होती हैं।"},
  {"id":"cdp-child-development-1079","question":"Which statement about inner speech, in Vygotsky’s account, is correct?","options":["It is the first form of speech to appear in infancy, well before any speech addressed to others","It has exactly the same structure as speech addressed to others, only without sound","It is a sign of mental disorder when it continues into adolescence or adulthood","It is abbreviated compared with social speech, because the speaker already knows the context"],"answer":3,"explanation":"Vygotsky described inner speech as highly abbreviated, keeping mainly the predicate, since the subject is already known to the thinker. It develops last, from social speech through private speech.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"वाइगोत्स्की के विवरण में आंतरिक वाक् के बारे में कौन-सा कथन सही है?","optionsHi":["यह शैशवावस्था में प्रकट होने वाला भाषण का पहला रूप है, दूसरों को संबोधित किसी भी भाषण से बहुत पहले","इसकी संरचना दूसरों को संबोधित भाषण जैसी ही होती है, केवल ध्वनि के बिना","यदि यह किशोरावस्था या वयस्कता तक जारी रहे तो यह मानसिक विकार का संकेत है","यह सामाजिक भाषण की तुलना में संक्षिप्त होता है, क्योंकि वक्ता को संदर्भ पहले से ज्ञात होता है"],"explanationHi":"वाइगोत्स्की ने आंतरिक वाक् को अत्यंत संक्षिप्त बताया, जिसमें मुख्यतः विधेय बचता है, क्योंकि उद्देश्य चिंतक को पहले से ज्ञात होता है। यह सबसे अंत में, सामाजिक वाक् से निजी वाक् के माध्यम से विकसित होता है।"},
  {"id":"cdp-child-development-1080","question":"In an English class for students whose home language is Marathi, the teacher gives sentence frames such as ‘I think ___ because ___’ for a discussion, and stops providing them once students speak confidently. This is an example of:","options":["Scaffolding language use within the zone of proximal development","Rote memorisation of fixed phrases to be recalled in tests","Negative reinforcement, since the frames are removed when students improve","Horizontal décalage across different language tasks"],"answer":0,"explanation":"Sentence frames are temporary supports that let learners take part in discussion beyond their independent level; removing them as competence grows is scaffolding.","difficulty":"moderate","source":"CTET · KVS · State TETs","questionHi":"उन विद्यार्थियों की अंग्रेज़ी कक्षा में, जिनकी घर की भाषा मराठी है, शिक्षक चर्चा के लिए ‘I think ___ because ___’ जैसे वाक्य-ढाँचे देता है और जब विद्यार्थी आत्मविश्वास से बोलने लगते हैं तो उन्हें देना बंद कर देता है। यह किसका उदाहरण है?","optionsHi":["निकटस्थ विकास के क्षेत्र में भाषा-प्रयोग को पाड़ देना","परीक्षाओं में याद करने के लिए निश्चित वाक्यांशों की रटंत","नकारात्मक पुनर्बलन, क्योंकि विद्यार्थियों के सुधरने पर ढाँचे हटा लिए जाते हैं","विभिन्न भाषा-कार्यों में क्षैतिज डेकैलाज"],"explanationHi":"वाक्य-ढाँचे अस्थायी सहायताएँ हैं जो अधिगमकर्ताओं को उनके स्वतंत्र स्तर से आगे चर्चा में भाग लेने देती हैं; दक्षता बढ़ने पर उन्हें हटाना पाड़ देना है।"},
  {"id":"cdp-child-development-1081","question":"A teacher who has never used a new attendance app mutters, ‘First tap the class... then the date... where is the save button?’ as she uses it. This most clearly supports Vygotsky’s claim that:","options":["Private speech belongs only to young children and disappears completely","Adults are still at the pre-operational stage","Private speech can reappear at any age when a task is new or difficult","Speech and thought are unrelated in adults"],"answer":2,"explanation":"Inner speech can return to an audible form when adults face difficult or unfamiliar tasks, because speaking aloud helps regulate action. It is not a sign of a lower stage.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षिका, जिसने कभी नए उपस्थिति ऐप का उपयोग नहीं किया, उसे चलाते हुए बुदबुदाती है, ‘पहले कक्षा पर टैप करो... फिर तिथि... सेव बटन कहाँ है?’ यह वाइगोत्स्की के किस दावे का सबसे स्पष्ट समर्थन करता है?","optionsHi":["निजी वाक् केवल छोटे बच्चों में होता है और पूरी तरह लुप्त हो जाता है","वयस्क अब भी पूर्व-संक्रियात्मक अवस्था में हैं","जब कार्य नया या कठिन हो तो निजी वाक् किसी भी आयु में फिर प्रकट हो सकता है","वयस्कों में भाषण और चिंतन असंबद्ध हैं"],"explanationHi":"आंतरिक वाक् तब श्रव्य रूप में लौट सकता है जब वयस्कों को कठिन या अपरिचित कार्यों का सामना करना पड़ता है, क्योंकि ज़ोर से बोलना क्रिया को नियमित करने में सहायक होता है। यह निचली अवस्था का संकेत नहीं है।"},
  {"id":"cdp-child-development-1082","question":"A Class 3 child cannot follow even step-by-step help from the teacher on solving quadratic equations. What would Vygotsky conclude?","options":["The child needs more drill on quadratic equations until the procedure becomes automatic","The task lies beyond the upper limit of his ZPD, so a task nearer his present level is needed","The child lacks intelligence and should be placed in a lower class with easier work","The help was not detailed enough, so the teacher should explain each step even more slowly"],"answer":1,"explanation":"The ZPD covers only what a learner can do with help. If even full help does not work, the task is outside the zone and instruction there cannot be taken up.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 3 का एक बच्चा द्विघात समीकरण हल करने में शिक्षक की चरण-दर-चरण सहायता भी नहीं समझ पाता। वाइगोत्स्की क्या निष्कर्ष निकालेंगे?","optionsHi":["बच्चे को द्विघात समीकरणों पर और अभ्यास चाहिए जब तक प्रक्रिया स्वचालित न हो जाए","कार्य उसके ZPD की ऊपरी सीमा से परे है, इसलिए उसके वर्तमान स्तर के निकट का कार्य चाहिए","बच्चे में बुद्धि की कमी है और उसे आसान कार्य वाली निचली कक्षा में रखना चाहिए","सहायता पर्याप्त विस्तृत नहीं थी, इसलिए शिक्षक को हर चरण और भी धीरे समझाना चाहिए"],"explanationHi":"ZPD केवल उसी को समाहित करता है जो अधिगमकर्ता सहायता के साथ कर सकता है। यदि पूर्ण सहायता भी काम नहीं करती, तो कार्य उस क्षेत्र के बाहर है और वहाँ शिक्षण ग्रहण नहीं किया जा सकता।"},
  {"id":"cdp-child-development-1083","question":"Vygotsky described how a baby’s unsuccessful reach towards an object becomes a pointing gesture once the mother responds by handing the object over. This example was used to show that:","options":["Pointing is an inborn reflex that appears on schedule whatever the mother does","Gestures are learnt only through operant conditioning, with the object acting as the reward each time","Infants already have full formal operations and plan their gestures deliberately","An action’s meaning first arises in interaction with others and is then taken over by the child"],"answer":3,"explanation":"The reach acquires meaning as a request because another person interprets it, and the child then uses it deliberately. This illustrates Vygotsky’s view that higher functions have a social origin.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"वाइगोत्स्की ने वर्णन किया कि किसी वस्तु की ओर शिशु का असफल हाथ बढ़ाना इंगित करने का संकेत कैसे बन जाता है जब माँ वस्तु को सौंपकर प्रतिक्रिया देती है। इस उदाहरण का उपयोग यह दिखाने के लिए किया गया कि:","optionsHi":["इंगित करना जन्मजात प्रतिवर्त है जो माँ के व्यवहार की परवाह किए बिना समय पर प्रकट होता है","संकेत केवल क्रियाप्रसूत अनुबंधन से सीखे जाते हैं, जिसमें हर बार वस्तु पुरस्कार का काम करती है","शिशुओं में पहले से पूर्ण औपचारिक संक्रियाएँ होती हैं और वे अपने संकेतों की सोच-समझकर योजना बनाते हैं","किसी क्रिया का अर्थ पहले दूसरों के साथ अंतःक्रिया में उत्पन्न होता है और फिर बच्चा उसे अपना लेता है"],"explanationHi":"हाथ बढ़ाना अनुरोध के रूप में अर्थ ग्रहण करता है क्योंकि कोई दूसरा व्यक्ति उसकी व्याख्या करता है, और फिर बच्चा उसे जानबूझकर प्रयोग करता है। यह वाइगोत्स्की के इस मत को दर्शाता है कि उच्चतर प्रकार्यों का मूल सामाजिक होता है।"},
  {"id":"cdp-child-development-1084","question":"A computer-based maths program gives a student a general hint after a wrong answer, a more specific hint after a second error, and a worked step after a third, while reducing hints as the student improves. This design is an application of:","options":["Contingent scaffolding based on Vygotsky’s ZPD","Classical conditioning of correct answers to hints","Piaget’s idea of animism","Bruner’s enactive mode of representation"],"answer":0,"explanation":"Help that grows when the learner struggles and shrinks when she succeeds is contingent scaffolding. The program adjusts to the learner’s zone rather than giving a fixed reward.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कंप्यूटर आधारित गणित कार्यक्रम गलत उत्तर के बाद विद्यार्थी को सामान्य संकेत देता है, दूसरी त्रुटि के बाद अधिक विशिष्ट संकेत, और तीसरी के बाद एक हल किया हुआ चरण, जबकि विद्यार्थी के सुधरने पर संकेत घटाता जाता है। यह अभिकल्प किसका अनुप्रयोग है?","optionsHi":["वाइगोत्स्की के ZPD पर आधारित आकस्मिक (अनुक्रियाशील) पाड़","संकेतों के प्रति सही उत्तरों का शास्त्रीय अनुबंधन","पियाजे की जीववाद की अवधारणा","ब्रूनर का निरूपण का क्रियात्मक रूप"],"explanationHi":"वह सहायता जो अधिगमकर्ता के संघर्ष करने पर बढ़ती है और सफल होने पर घटती है, आकस्मिक पाड़ है। कार्यक्रम निश्चित पुरस्कार देने के बजाय अधिगमकर्ता के क्षेत्र के अनुसार स्वयं को समायोजित करता है।"},
  {"id":"cdp-child-development-1085","question":"How many of these practices are consistent with Vygotsky’s theory? I. Waiting until children are developmentally ready before teaching a concept. II. Allowing children to talk to themselves while solving problems. III. Assessing only what children can do alone. IV. Teaching the language and symbols of a subject alongside activities.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and IV follow from his views on private speech and cultural tools. I is inconsistent: for Vygotsky learning leads development, so teaching in the ZPD should not wait for readiness. III ignores the ZPD by assessing only independent work.","difficulty":"hard","source":"CTET · DSSSB · State TETs","questionHi":"इनमें से कितने अभ्यास वाइगोत्स्की के सिद्धांत के अनुरूप हैं? I. किसी अवधारणा को पढ़ाने से पहले इंतज़ार करना कि बच्चे विकास की दृष्टि से तैयार हों। II. समस्याएँ हल करते समय बच्चों को स्वयं से बात करने देना। III. केवल वही आकलित करना जो बच्चे अकेले कर सकते हैं। IV. गतिविधियों के साथ-साथ विषय की भाषा और प्रतीक सिखाना।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"II और IV निजी वाक् और सांस्कृतिक उपकरणों पर उनके विचारों से निकलते हैं। I असंगत है: वाइगोत्स्की के लिए अधिगम विकास का नेतृत्व करता है, इसलिए ZPD में शिक्षण को तैयारी की प्रतीक्षा नहीं करनी चाहिए। III केवल स्वतंत्र कार्य का आकलन करके ZPD की उपेक्षा करता है।"},
  {"id":"cdp-child-development-1086","question":"Two Class 2 children, Pinky and Sumit, both read simple words alone. With the teacher’s prompts, Pinky reads a whole short story, while Sumit manages only a few more words. Which instructional decision follows from Vygotsky?","options":["Give both children exactly the same reading task, since they have the same independent level","Give both the story, since all children of the same age have the same potential","Plan different next steps, since their zones of proximal development differ","Wait until both reach the same level on their own"],"answer":2,"explanation":"Equal independent performance can hide different ZPDs. Instruction should match each child’s assisted level, so Pinky is ready for more challenging reading than Sumit.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 2 के दो बच्चे, पिंकी और सुमित, दोनों अकेले सरल शब्द पढ़ते हैं। शिक्षक के संकेतों की सहायता से पिंकी एक पूरी छोटी कहानी पढ़ लेती है, जबकि सुमित केवल कुछ और शब्द पढ़ पाता है। वाइगोत्स्की से कौन-सा शिक्षण-निर्णय निकलता है?","optionsHi":["दोनों बच्चों को ठीक वही पठन-कार्य देना, क्योंकि उनका स्वतंत्र स्तर समान है","दोनों को कहानी देना, क्योंकि समान आयु के सभी बच्चों की क्षमता समान होती है","अगले अलग-अलग चरण तय करना, क्योंकि उनके निकटस्थ विकास के क्षेत्र भिन्न हैं","प्रतीक्षा करना जब तक दोनों स्वयं समान स्तर पर न पहुँच जाएँ"],"explanationHi":"समान स्वतंत्र प्रदर्शन भिन्न ZPD को छिपा सकता है। शिक्षण को प्रत्येक बच्चे के सहायता-प्राप्त स्तर से मेल खाना चाहिए, इसलिए पिंकी सुमित से अधिक चुनौतीपूर्ण पठन के लिए तैयार है।"},
  {"id":"cdp-child-development-1087","question":"Assertion (A): Giving children only tasks they can already do on their own does little to advance their development. Reason (R): Such tasks lie below the zone of proximal development, where no new functions are being formed.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Tasks at the independent level only use matured functions. Development is stimulated by tasks just beyond that level, within the ZPD, so R explains A.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"अभिकथन (A): बच्चों को केवल वही कार्य देना जो वे पहले से अकेले कर सकते हैं, उनके विकास को आगे बढ़ाने में बहुत कम योगदान देता है। कारण (R): ऐसे कार्य निकटस्थ विकास के क्षेत्र से नीचे होते हैं, जहाँ कोई नए प्रकार्य नहीं बन रहे होते।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"स्वतंत्र स्तर के कार्य केवल परिपक्व हो चुके प्रकार्यों का उपयोग करते हैं। विकास को उस स्तर से ठीक आगे, ZPD के भीतर, के कार्यों से प्रेरणा मिलती है, इसलिए R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-1088","question":"In an anganwadi, a worker plays with toddlers, names the objects they touch, asks simple questions and extends their short phrases (‘Ball... yes, a red ball!’). From a Vygotskian view, this is valuable mainly because:","options":["It keeps the children quiet and busy, so that they cause less trouble later","It provides language and social interaction through which children’s thinking develops","It trains children to imitate adult speech exactly, which is how all language is learnt","It speeds up physical growth through extra movement and play"],"answer":1,"explanation":"For Vygotsky, adult talk during shared activity provides the language tools that children later use for thinking. Expanding phrases also scaffolds the child’s own speech.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"एक आँगनवाड़ी में कार्यकर्ता नन्हे बच्चों के साथ खेलती है, उनके छूने वाली वस्तुओं के नाम बताती है, सरल प्रश्न पूछती है और उनके छोटे वाक्यांशों को विस्तार देती है (‘गेंद... हाँ, लाल गेंद!’)। वाइगोत्स्की के दृष्टिकोण से यह मुख्यतः मूल्यवान क्यों है?","optionsHi":["यह बच्चों को शांत और व्यस्त रखता है, ताकि वे आगे कम परेशानी खड़ी करें","यह भाषा और सामाजिक अंतःक्रिया उपलब्ध कराता है जिनसे बच्चों का चिंतन विकसित होता है","यह बच्चों को वयस्कों के भाषण की हू-ब-हू नकल करना सिखाता है, जिस तरह सारी भाषा सीखी जाती है","यह अतिरिक्त गति और खेल से शारीरिक वृद्धि तेज़ करता है"],"explanationHi":"वाइगोत्स्की के लिए साझा गतिविधि के दौरान वयस्क की बातचीत वे भाषाई उपकरण देती है जिनका बच्चे बाद में चिंतन के लिए उपयोग करते हैं। वाक्यांशों का विस्तार बच्चे के अपने भाषण को भी पाड़ देता है।"},
  {"id":"cdp-child-development-1089","question":"Which classroom situation shows a misunderstanding of the ‘more knowledgeable other’ in Vygotsky’s theory?","options":["A student who knows a regional song teaches it to the whole class, including the teacher","A teacher refuses to let a peer help, saying, ‘Only an adult can be a proper guide’","A computer tutor gives step-by-step hints","An elder sister guides a younger child in using a dictionary"],"answer":1,"explanation":"The MKO can be a peer, a younger person or even a computer program, as long as it knows more about the task. Restricting it to adults misreads Vygotsky.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कौन-सी कक्षा-स्थिति वाइगोत्स्की के सिद्धांत में ‘अधिक जानकार अन्य’ की गलत समझ दर्शाती है?","optionsHi":["एक क्षेत्रीय गीत जानने वाला विद्यार्थी उसे पूरी कक्षा को, शिक्षक सहित, सिखाता है","एक शिक्षक किसी साथी को मदद करने से यह कहकर मना करता है, ‘केवल वयस्क ही उचित मार्गदर्शक हो सकता है’","एक कंप्यूटर ट्यूटर चरण-दर-चरण संकेत देता है","एक बड़ी बहन छोटे बच्चे को शब्दकोश का उपयोग करना सिखाती है"],"explanationHi":"अधिक जानकार अन्य कोई साथी, कोई छोटा व्यक्ति या कंप्यूटर कार्यक्रम भी हो सकता है, यदि वह कार्य के बारे में अधिक जानता हो। इसे वयस्कों तक सीमित करना वाइगोत्स्की को गलत समझना है।"},
  {"id":"cdp-child-development-1090","question":"Consider these statements. 1. For Vygotsky, the ZPD is a property of the interaction between a learner and a helper on a particular task, not a fixed trait. 2. Vygotsky held that all learning must wait for the matching stage of development to be complete. 3. Vygotsky saw schooling as an important source of new psychological tools. Which is/are correct?","options":["1 and 3 only","1 and 2 only","2 only","1, 2 and 3"],"answer":0,"explanation":"The ZPD depends on the task and on the help available, and schools introduce tools such as writing and scientific concepts. Statement 2 is Piaget’s position, which Vygotsky rejected.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"इन कथनों पर विचार कीजिए। 1. वाइगोत्स्की के लिए ZPD किसी विशेष कार्य पर अधिगमकर्ता और सहायक की अंतःक्रिया का गुण है, निश्चित लक्षण नहीं। 2. वाइगोत्स्की मानते थे कि सारे अधिगम को विकास की संबंधित अवस्था के पूर्ण होने की प्रतीक्षा करनी चाहिए। 3. वाइगोत्स्की विद्यालयी शिक्षा को नए मनोवैज्ञानिक उपकरणों का महत्त्वपूर्ण स्रोत मानते थे। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2","1, 2 और 3"],"explanationHi":"ZPD कार्य और उपलब्ध सहायता पर निर्भर करता है, और विद्यालय लेखन तथा वैज्ञानिक अवधारणाओं जैसे उपकरण प्रस्तुत करते हैं। कथन 2 पियाजे की स्थिति है, जिसे वाइगोत्स्की ने अस्वीकार किया।"},
  {"id":"cdp-child-development-1091","question":"A Class 8 teacher assigns a group project. The group finishes well, but she later finds that two members only coloured the charts and learnt nothing about the topic. Which Vygotskian principle was most neglected?","options":["Children should never work in groups, since some members will always leave the real work to others","Group learning works only if each member takes part in the shared thinking and can internalise it","Groups should contain only children of identical ability, so that everyone contributes equally","Teachers should not monitor group work, so that children learn to manage on their own"],"answer":1,"explanation":"Social interaction leads to development only when learners participate in the joint problem solving. Passive members have nothing to internalise, so careful role design and monitoring matter.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 8 की एक शिक्षिका समूह परियोजना देती है। समूह अच्छी तरह पूरा करता है, पर बाद में उसे पता चलता है कि दो सदस्यों ने केवल चार्ट में रंग भरे और विषय के बारे में कुछ नहीं सीखा। वाइगोत्स्की का कौन-सा सिद्धांत सबसे अधिक उपेक्षित हुआ?","optionsHi":["बच्चों को कभी समूह में कार्य नहीं करना चाहिए, क्योंकि कुछ सदस्य हमेशा असली काम दूसरों पर छोड़ देंगे","समूह अधिगम तभी काम करता है जब प्रत्येक सदस्य साझा चिंतन में भाग ले और उसे आत्मसात कर सके","समूहों में केवल समान योग्यता वाले बच्चे होने चाहिए, ताकि सब बराबर योगदान दें","शिक्षकों को समूह कार्य की निगरानी नहीं करनी चाहिए, ताकि बच्चे स्वयं प्रबंधन करना सीखें"],"explanationHi":"सामाजिक अंतःक्रिया विकास की ओर तभी ले जाती है जब अधिगमकर्ता संयुक्त समस्या-समाधान में भाग लें। निष्क्रिय सदस्यों के पास आत्मसात करने को कुछ नहीं होता, इसलिए भूमिकाओं का सावधान अभिकल्प और निगरानी मायने रखती है।"},
  {"id":"cdp-child-development-1092","question":"Which of the following best describes ‘mediation’ in Vygotsky’s theory?","options":["Settling quarrels between children in class so that cooperative learning can go on","Rewarding correct responses immediately so that the link between task and answer is strengthened","The child’s mind adjusting to new information on its own, without any outside help","Using tools and signs, often supplied by others, that stand between the child and the task"],"answer":3,"explanation":"For Vygotsky, human thinking is mediated by cultural tools such as language, numbers and diagrams. The term has nothing to do with resolving quarrels or reinforcement.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"वाइगोत्स्की के सिद्धांत में ‘मध्यस्थता’ का सबसे अच्छा वर्णन निम्नलिखित में से कौन-सा है?","optionsHi":["कक्षा में बच्चों के झगड़े सुलझाना, ताकि सहकारी अधिगम चलता रहे","सही अनुक्रियाओं को तुरंत पुरस्कृत करना, ताकि कार्य और उत्तर के बीच संबंध सुदृढ़ हो","बच्चे के मन का बिना किसी बाहरी सहायता के नई सूचना के अनुसार स्वयं को समायोजित करना","उपकरणों और संकेतों का उपयोग, जो प्रायः दूसरों द्वारा दिए जाते हैं, और बच्चे तथा कार्य के बीच खड़े होते हैं"],"explanationHi":"वाइगोत्स्की के लिए मानवीय चिंतन सांस्कृतिक उपकरणों, जैसे भाषा, संख्याओं और आरेखों, द्वारा मध्यस्थ होता है। इस शब्द का झगड़े सुलझाने या पुनर्बलन से कोई संबंध नहीं है।"},
  {"id":"cdp-child-development-1093","question":"A Class 3 child learns subtraction by first using a number line with the teacher, then using it alone, then imagining it, and finally solving sums mentally. The step ‘imagining it’ illustrates:","options":["The tool moving from an external support to an internal mental tool","A regression to the sensorimotor stage under the pressure of subtraction","Bruner’s claim that the enactive mode is unnecessary","Operant extinction of the number line"],"answer":0,"explanation":"Vygotsky’s internalisation describes how external aids become inner tools of thought. The imagined number line is a halfway point between using the real one and pure mental calculation.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 3 का एक बच्चा घटाना पहले शिक्षक के साथ संख्या-रेखा के प्रयोग से, फिर अकेले उसके प्रयोग से, फिर उसकी कल्पना करके, और अंत में मन ही मन योग हल करके सीखता है। ‘उसकी कल्पना करना’ चरण दर्शाता है:","optionsHi":["उपकरण का बाहरी सहारे से आंतरिक मानसिक उपकरण में बदलना","घटाने के दबाव में संवेदी-गामक अवस्था की ओर प्रतिगमन","ब्रूनर का यह दावा कि क्रियात्मक रूप अनावश्यक है","संख्या-रेखा का क्रियाप्रसूत विलोपन"],"explanationHi":"वाइगोत्स्की का आंतरिकीकरण बताता है कि बाहरी सहायक साधन चिंतन के आंतरिक उपकरण कैसे बनते हैं। कल्पित संख्या-रेखा वास्तविक रेखा के प्रयोग और शुद्ध मानसिक गणना के बीच का मध्य बिंदु है।"},
  {"id":"cdp-child-development-1094","question":"Which of the following would Vygotsky most likely criticise?","options":["A teacher who asks open questions during group work instead of simply handing out the answers herself","A child who explains a problem to a friend who has not yet understood it","A report labelling a child ‘weak’ from one unaided test, without seeing what she can do with help","A parent who reads stories aloud and talks about them with a child at bedtime every night"],"answer":2,"explanation":"Vygotsky argued that static, unaided testing shows only the actual level and misses the ZPD. The other practices involve the social interaction he valued.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"वाइगोत्स्की सबसे अधिक किसकी आलोचना करते?","optionsHi":["उस शिक्षिका की जो समूह कार्य के दौरान स्वयं उत्तर बाँटने के बजाय खुले प्रश्न पूछती है","उस बच्चे की जो किसी मित्र को, जो अभी समझा नहीं है, समस्या समझाता है","उस रिपोर्ट की जो एक बिना सहायता वाले परीक्षण के आधार पर बच्चे को ‘कमज़ोर’ का लेबल देती है, बिना यह देखे कि सहायता से वह क्या कर सकती है","उस अभिभावक की जो हर रात सोने के समय बच्चे को कहानियाँ पढ़कर सुनाता है और उन पर बात करता है"],"explanationHi":"वाइगोत्स्की का तर्क था कि स्थिर, बिना सहायता वाला परीक्षण केवल वास्तविक स्तर दिखाता है और ZPD को चूक जाता है। अन्य अभ्यासों में वह सामाजिक अंतःक्रिया है जिसे वे महत्त्व देते थे।"},
  {"id":"cdp-child-development-1095","question":"In Tolman's maze experiments, rats that ran the maze for ten days without any food reward made many errors, but once food was introduced on day eleven they almost immediately performed as well as rats rewarded from the start. What does this show?","options":["Learning occurs only when every response is reinforced, so the first ten days produced no learning at all","Rats learn by sudden insight rather than by gradual experience of the maze","Food reward creates the learning on the very day it is introduced, through rapid conditioning","Learning can occur without reinforcement and show in performance only when there is a reason to use it"],"answer":3,"explanation":"Tolman called this latent learning: the rats had formed a cognitive map while exploring, and the reward merely gave them a reason to display what they already knew.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"टोलमैन के भूलभुलैया प्रयोगों में, जिन चूहों ने दस दिन बिना किसी भोजन-पुरस्कार के भूलभुलैया दौड़ी, उन्होंने बहुत त्रुटियाँ कीं, पर ग्यारहवें दिन भोजन देने पर उन्होंने लगभग तुरंत उतना ही अच्छा प्रदर्शन किया जितना शुरू से पुरस्कृत चूहों ने। यह क्या दर्शाता है?","optionsHi":["अधिगम तभी होता है जब हर अनुक्रिया को पुनर्बलन मिले, इसलिए पहले दस दिनों में कोई अधिगम हुआ ही नहीं","चूहे भूलभुलैया के क्रमिक अनुभव के बजाय अचानक सूझ से सीखते हैं","भोजन का पुरस्कार जिस दिन दिया जाता है उसी दिन तीव्र अनुबंधन द्वारा अधिगम पैदा करता है","अधिगम बिना पुनर्बलन के हो सकता है और प्रदर्शन में तभी दिखता है जब उसे उपयोग करने का कारण हो"],"explanationHi":"टोलमैन ने इसे गुप्त अधिगम कहा: चूहों ने खोज करते समय संज्ञानात्मक मानचित्र बना लिया था, और पुरस्कार ने केवल उन्हें अपना पहले से जाना हुआ दिखाने का कारण दिया।"},
  {"id":"cdp-child-development-1096","question":"The main corridor of a school is closed for repairs. Class 5 student Divya, who has explored the building for years, immediately takes an unfamiliar route through the library and back stairs to reach the art room. Tolman would explain her behaviour by her:","options":["Cognitive map of the school","Conditioned response to the corridor","Law of exercise","Vicarious reinforcement"],"answer":0,"explanation":"A cognitive map is a mental representation of the layout of an environment; it allows flexible new routes rather than a fixed chain of responses.","difficulty":"hard","source":"CTET · DSSSB PRT","questionHi":"विद्यालय का मुख्य गलियारा मरम्मत के लिए बंद है। कक्षा 5 की विद्यार्थी दिव्या, जो वर्षों से भवन में घूमती रही है, कला-कक्ष तक पहुँचने के लिए तुरंत पुस्तकालय और पिछली सीढ़ियों से होकर एक अपरिचित रास्ता लेती है। टोलमैन उसके व्यवहार की व्याख्या किससे करेंगे?","optionsHi":["विद्यालय के उसके संज्ञानात्मक मानचित्र से","गलियारे के प्रति अनुबंधित अनुक्रिया से","अभ्यास के नियम से","प्रतिनिधिक पुनर्बलन से"],"explanationHi":"संज्ञानात्मक मानचित्र किसी परिवेश की बनावट का मानसिक निरूपण है; वह अनुक्रियाओं की निश्चित शृंखला के बजाय लचीले नए रास्तों की अनुमति देता है।"},
  {"id":"cdp-child-development-1097","question":"Class 7 students behave perfectly when the principal is in the corridor but become noisy the moment she leaves, although they are never punished in either case by the class teacher. In operant terms, the principal's presence acts as:","options":["An unconditioned stimulus that naturally produces quiet, orderly behaviour","A discriminative stimulus signalling when certain behaviour will be reinforced or punished","A primary reinforcer, since her presence is rewarding in itself to the students","A neutral stimulus, since she herself neither rewards nor punishes the students in any way"],"answer":1,"explanation":"A discriminative stimulus signals that a particular consequence is available. Behaviour then comes under stimulus control and occurs mainly when that signal is present.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"कक्षा 7 के विद्यार्थी जब प्रधानाचार्या गलियारे में होती हैं तो बिल्कुल ठीक व्यवहार करते हैं, पर उनके जाते ही शोर करने लगते हैं, जबकि कक्षा शिक्षक उन्हें किसी भी स्थिति में दंडित नहीं करता। क्रियाप्रसूत शब्दों में, प्रधानाचार्या की उपस्थिति कार्य करती है:","optionsHi":["अनुबंधित उद्दीपक के रूप में जो स्वाभाविक रूप से शांत, व्यवस्थित व्यवहार उत्पन्न करता है","विभेदक उद्दीपक के रूप में, जो संकेत देता है कि कुछ व्यवहार कब पुनर्बलित या दंडित होगा","प्राथमिक पुनर्बलक के रूप में, क्योंकि उनकी उपस्थिति विद्यार्थियों के लिए स्वयं में पुरस्कृत है","तटस्थ उद्दीपक के रूप में, क्योंकि वे स्वयं विद्यार्थियों को न पुरस्कृत करती हैं, न दंडित"],"explanationHi":"विभेदक उद्दीपक संकेत देता है कि कोई विशेष परिणाम उपलब्ध है। तब व्यवहार उद्दीपक नियंत्रण में आ जाता है और मुख्यतः तभी होता है जब वह संकेत मौजूद हो।"},
  {"id":"cdp-child-development-1098","question":"In one school, a long ring of the bell is always followed by lunch break, while a short ring is followed only by a change of period. Soon children start packing tiffin boxes only at the long ring. This illustrates:","options":["Stimulus generalisation","Spontaneous recovery","Stimulus discrimination","Higher-order conditioning"],"answer":2,"explanation":"Children have learnt to respond to one stimulus (long ring) and not to a similar one (short ring) because only the first is paired with lunch: stimulus discrimination.","difficulty":"hard","source":"CTET Paper 1 · REET","questionHi":"एक विद्यालय में घंटी की लंबी ध्वनि के बाद सदैव भोजनावकाश होता है, जबकि छोटी ध्वनि के बाद केवल कालांश बदलता है। जल्दी ही बच्चे केवल लंबी घंटी पर ही टिफिन के डिब्बे निकालने लगते हैं। यह दर्शाता है:","optionsHi":["उद्दीपक सामान्यीकरण","स्वतः पुनर्प्राप्ति","उद्दीपक विभेदन","उच्चतर-क्रम अनुबंधन"],"explanationHi":"बच्चों ने एक उद्दीपक (लंबी घंटी) पर अनुक्रिया करना और समान उद्दीपक (छोटी घंटी) पर न करना सीख लिया है क्योंकि केवल पहली का भोजन से संबंध है: उद्दीपक विभेदन।"},
  {"id":"cdp-child-development-1099","question":"To teach a child with an intellectual disability to tie his shoelaces, a teacher first does all the steps herself except the last tightening pull, which the child completes and is praised for. Gradually she leaves the last two, then the last three steps to him. This method is called:","options":["Forward chaining","Shaping by spontaneous recovery","Fixed-interval reinforcement","Backward chaining"],"answer":3,"explanation":"In backward chaining the learner first masters the final step, which is immediately followed by task completion and reinforcement, and then earlier steps are added one by one.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"बौद्धिक अक्षमता वाले बच्चे को जूते के फीते बाँधना सिखाने के लिए एक शिक्षिका पहले सारे चरण स्वयं करती है, केवल अंतिम कसने वाला खिंचाव छोड़कर, जिसे बच्चा पूरा करता है और सराहा जाता है। धीरे-धीरे वह अंतिम दो, फिर अंतिम तीन चरण उस पर छोड़ती है। इस विधि को कहते हैं:","optionsHi":["अग्र शृंखलन","स्वतः पुनर्प्राप्ति द्वारा आकार देना","स्थिर-अंतराल पुनर्बलन","पश्च शृंखलन"],"explanationHi":"पश्च शृंखलन में अधिगमकर्ता पहले अंतिम चरण में निपुण होता है, जिसके तुरंत बाद कार्य की पूर्णता और पुनर्बलन आता है, और फिर पहले के चरण एक-एक करके जोड़े जाते हैं।"},
  {"id":"cdp-child-development-1100","question":"A teacher sends a disruptive Class 4 child out of the room for ‘time-out’ each time he misbehaves, but his misbehaviour increases. He dislikes the maths lesson. What is the likely reason?","options":["Leaving the lesson removes something he dislikes, so time-out negatively reinforces misbehaving","Time-out always increases behaviour, because any attention from the teacher acts as a reward","The child is showing spontaneous recovery of a behaviour that had earlier been extinguished","Time-out is a form of positive reinforcement, as the teacher adds attention by sending him out"],"answer":0,"explanation":"Time-out works only if the classroom is more rewarding than being outside it. If the lesson is aversive, escaping it strengthens the misbehaviour through negative reinforcement.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक शिक्षिका कक्षा 4 के उद्दंड बच्चे को हर बार कुव्यवहार करने पर ‘टाइम-आउट’ के लिए कमरे से बाहर भेजती है, पर उसका कुव्यवहार बढ़ता जाता है। उसे गणित का पाठ नापसंद है। संभावित कारण क्या है?","optionsHi":["पाठ छोड़ने से उसकी नापसंद की चीज़ हट जाती है, इसलिए टाइम-आउट कुव्यवहार को नकारात्मक रूप से पुनर्बलित करता है","टाइम-आउट हमेशा व्यवहार बढ़ाता है, क्योंकि शिक्षिका का कोई भी ध्यान पुरस्कार का काम करता है","बच्चा उस व्यवहार की स्वतः पुनर्प्राप्ति दिखा रहा है जो पहले विलुप्त हो चुका था","टाइम-आउट सकारात्मक पुनर्बलन का रूप है, क्योंकि शिक्षिका उसे बाहर भेजकर ध्यान जोड़ती है"],"explanationHi":"टाइम-आउट तभी काम करता है जब कक्षा बाहर रहने से अधिक पुरस्कृत हो। यदि पाठ अरुचिकर है, तो उससे बच निकलना नकारात्मक पुनर्बलन द्वारा कुव्यवहार को सुदृढ़ करता है।"},
  {"id":"cdp-child-development-1101","question":"Which of these correctly contrasts classical and operant conditioning? I. In classical conditioning the response is mostly elicited by a stimulus; in operant conditioning it is emitted by the learner. II. In operant conditioning the consequence of a response determines whether it is repeated. III. Classical conditioning mainly involves voluntary actions. IV. Skinner called classically conditioned responses ‘respondent’ behaviour.","options":["I and III only","I, II and IV only","II and III only","I, II, III and IV"],"answer":1,"explanation":"Classical conditioning involves largely involuntary, elicited (respondent) responses, so III is false. Operant behaviour is emitted and controlled by its consequences.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"इनमें से कौन-सा शास्त्रीय और क्रियाप्रसूत अनुबंधन के बीच सही अंतर बताता है? I. शास्त्रीय अनुबंधन में अनुक्रिया मुख्यतः उद्दीपक द्वारा उत्पन्न होती है; क्रियाप्रसूत अनुबंधन में वह अधिगमकर्ता द्वारा स्वयं उत्सर्जित होती है। II. क्रियाप्रसूत अनुबंधन में अनुक्रिया का परिणाम तय करता है कि वह दोहराई जाएगी या नहीं। III. शास्त्रीय अनुबंधन में मुख्यतः ऐच्छिक क्रियाएँ शामिल होती हैं। IV. स्किनर ने शास्त्रीय अनुबंधन से बनी अनुक्रियाओं को ‘प्रतिवादी’ व्यवहार कहा।","optionsHi":["केवल I और III","केवल I, II और IV","केवल II और III","I, II, III और IV"],"explanationHi":"शास्त्रीय अनुबंधन में मुख्यतः अनैच्छिक, उद्दीपक-जनित (प्रतिवादी) अनुक्रियाएँ होती हैं, इसलिए III असत्य है। क्रियाप्रसूत व्यवहार उत्सर्जित होता है और अपने परिणामों द्वारा नियंत्रित होता है।"},
  {"id":"cdp-child-development-1102","question":"Praise for good behaviour given by a Class 1 teacher at the end of the week, rather than immediately, has little effect on the children. The most likely reason is that:","options":["Praise is not a real reinforcer for young children, who respond mainly to tangible rewards","Young children need punishment for misbehaviour rather than praise for good behaviour","For young children, reinforcement works far better when it closely follows the behaviour","Weekly praise is a variable-ratio schedule, which works only with older students"],"answer":2,"explanation":"The closer the consequence to the behaviour, the stronger the connection; young children especially have difficulty linking delayed consequences to earlier actions.","difficulty":"moderate","source":"CTET · REET","questionHi":"कक्षा 1 की शिक्षिका द्वारा अच्छे व्यवहार की प्रशंसा तुरंत करने के बजाय सप्ताह के अंत में करने का बच्चों पर बहुत कम प्रभाव पड़ता है। सबसे संभावित कारण यह है कि:","optionsHi":["प्रशंसा छोटे बच्चों के लिए वास्तविक पुनर्बलक नहीं है, वे मुख्यतः ठोस पुरस्कारों पर प्रतिक्रिया करते हैं","छोटे बच्चों को अच्छे व्यवहार की प्रशंसा की बजाय कुव्यवहार पर दंड की आवश्यकता होती है","छोटे बच्चों के लिए पुनर्बलन तब कहीं अधिक प्रभावी होता है जब वह व्यवहार के निकट आए","साप्ताहिक प्रशंसा परिवर्ती-अनुपात अनुसूची है, जो केवल बड़े विद्यार्थियों पर काम करती है"],"explanationHi":"परिणाम जितना व्यवहार के निकट होता है, संबंध उतना ही मज़बूत होता है; छोटे बच्चों को विशेष रूप से विलंबित परिणामों को पहले की क्रियाओं से जोड़ने में कठिनाई होती है।"},
  {"id":"cdp-child-development-1103","question":"Each time Monu wanders around the class, his teacher loudly scolds him in front of everyone, but his wandering keeps increasing. A behaviourist would point out that:","options":["The scolding is negative reinforcement, since it removes his freedom to roam freely around the classroom","The scolding is acting as punishment, and the increase is only a temporary extinction burst","Monu’s wandering is caused by spontaneous recovery of a habit extinguished earlier","For an attention-seeking child, the teacher’s attention may be acting as positive reinforcement"],"answer":3,"explanation":"Whether a consequence is a reinforcer or a punisher depends on its effect. If wandering increases, the scolding, which gives attention, is functioning as a reinforcer.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"जब भी मोनू कक्षा में घूमता है, उसकी शिक्षिका सबके सामने उसे ज़ोर से डाँटती है, पर उसका घूमना बढ़ता ही जाता है। व्यवहारवादी इंगित करेगा कि:","optionsHi":["डाँट नकारात्मक पुनर्बलन है, क्योंकि वह कक्षा में स्वतंत्र रूप से घूमने की उसकी आज़ादी हटा देती है","डाँट दंड का काम कर रही है, और वृद्धि केवल अस्थायी विलोप-विस्फोट है","मोनू का घूमना पहले विलुप्त हुई आदत की स्वतः पुनर्प्राप्ति के कारण है","ध्यान चाहने वाले बच्चे के लिए शिक्षिका का ध्यान सकारात्मक पुनर्बलन का काम कर सकता है"],"explanationHi":"कोई परिणाम पुनर्बलक है या दंड, यह उसके प्रभाव पर निर्भर करता है। यदि घूमना बढ़ रहा है, तो डाँट, जो ध्यान देती है, पुनर्बलक के रूप में कार्य कर रही है।"},
  {"id":"cdp-child-development-1104","question":"A Class 8 teacher cancels a test whenever the class whines loudly about it. Whining increases, and the teacher finds herself giving in more often. How does operant conditioning explain the teacher's own behaviour?","options":["Giving in is negatively reinforced, because it ends the unpleasant whining","Giving in is positively punished by the students, who whine louder each time she refuses","The teacher’s behaviour is classically conditioned salivation","The teacher is showing latent learning"],"answer":0,"explanation":"The students are positively reinforced (the test is cancelled after whining), while the teacher is negatively reinforced: her giving in removes the aversive whining, so she gives in more.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 की एक शिक्षिका जब भी कक्षा ज़ोर से किसी परीक्षा पर शिकायत करती है, परीक्षा रद्द कर देती है। शिकायत बढ़ती है और शिक्षिका स्वयं को अधिक बार झुकते हुए पाती है। क्रियाप्रसूत अनुबंधन शिक्षिका के अपने व्यवहार की व्याख्या कैसे करता है?","optionsHi":["झुकना नकारात्मक रूप से पुनर्बलित होता है, क्योंकि वह अप्रिय शिकायत को समाप्त करता है","झुकना विद्यार्थियों द्वारा सकारात्मक रूप से दंडित होता है, जो हर बार उसके मना करने पर और ज़ोर से शिकायत करते हैं","शिक्षिका का व्यवहार शास्त्रीय रूप से अनुबंधित लार-स्राव है","शिक्षिका गुप्त अधिगम दिखा रही है"],"explanationHi":"विद्यार्थी सकारात्मक रूप से पुनर्बलित होते हैं (शिकायत के बाद परीक्षा रद्द), जबकि शिक्षिका नकारात्मक रूप से पुनर्बलित होती है: उसका झुकना अप्रिय शिकायत को हटाता है, इसलिए वह और झुकती है।"},
  {"id":"cdp-child-development-1105","question":"A library programme gives a child one sticker for every five books read. Teachers notice that children often take a short break from reading right after getting a sticker. This schedule and pattern are:","options":["Variable ratio, with steady responding and no pauses","Fixed ratio, with a pause after each reinforcement","Fixed interval, with scalloping","Continuous reinforcement, with rapid extinction"],"answer":1,"explanation":"Reinforcement after a fixed number of responses is a fixed-ratio schedule; it typically produces high responding with a brief post-reinforcement pause.","difficulty":"hard","source":"CTET · HTET","questionHi":"एक पुस्तकालय कार्यक्रम में हर पाँच पुस्तकें पढ़ने पर बच्चे को एक स्टिकर मिलता है। शिक्षक देखते हैं कि स्टिकर पाने के ठीक बाद बच्चे प्रायः पढ़ने से थोड़ा विराम लेते हैं। यह अनुसूची और प्रतिरूप है:","optionsHi":["परिवर्ती अनुपात, जिसमें अनुक्रिया स्थिर रहती है और विराम नहीं आते","स्थिर अनुपात, जिसमें हर पुनर्बलन के बाद विराम आता है","स्थिर अंतराल, जिसमें खंडित (स्कैलपिंग) प्रतिरूप बनता है","सतत पुनर्बलन, जिसमें तीव्र विलोपन होता है"],"explanationHi":"निश्चित संख्या में अनुक्रियाओं के बाद पुनर्बलन स्थिर-अनुपात अनुसूची है; यह प्रायः उच्च अनुक्रिया-दर के साथ पुनर्बलन के बाद संक्षिप्त विराम उत्पन्न करती है।"},
  {"id":"cdp-child-development-1106","question":"Only the maths teacher praises Rohan for raising his hand, yet he begins raising his hand before speaking in every class, including those where it is not praised. This spread of the behaviour is:","options":["Stimulus discrimination between maths and other classes","Extinction","Operant generalisation to similar situations","Latent learning"],"answer":2,"explanation":"Behaviour reinforced in one setting tends to occur in similar settings: generalisation. If it later continues only in maths class, discrimination will have occurred.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"केवल गणित की शिक्षिका रोहन को हाथ उठाने पर सराहती है, फिर भी वह हर कक्षा में बोलने से पहले हाथ उठाने लगता है, उन कक्षाओं में भी जहाँ उसकी प्रशंसा नहीं होती। व्यवहार का यह फैलाव है:","optionsHi":["गणित और अन्य कक्षाओं के बीच उद्दीपक विभेदन","विलोपन","समान स्थितियों में क्रियाप्रसूत सामान्यीकरण","गुप्त अधिगम"],"explanationHi":"किसी एक परिस्थिति में पुनर्बलित व्यवहार समान परिस्थितियों में भी होने लगता है: सामान्यीकरण। यदि वह बाद में केवल गणित की कक्षा में ही जारी रहे, तो विभेदन हुआ होगा।"},
  {"id":"cdp-child-development-1107","question":"Which of these is the most widely accepted criticism of strict behaviourism as an account of children's learning?","options":["It ignores the effect of rewards and punishments on how often a behaviour is repeated later","It overemphasises thinking and understanding and pays too little attention to behaviour","It explains the creativity of children’s language better than any other theory can","It neglects mental processes and cannot easily explain how children produce new sentences"],"answer":3,"explanation":"Behaviourism studies observable behaviour and associations; critics such as Chomsky argued it cannot explain the creativity of language, and cognitive psychologists stressed internal processes.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"बच्चों के अधिगम के विवरण के रूप में कठोर व्यवहारवाद की सबसे व्यापक रूप से स्वीकृत आलोचना इनमें से कौन-सी है?","optionsHi":["यह पुरस्कारों और दंडों के प्रभाव की उपेक्षा करता है कि बाद में व्यवहार कितनी बार दोहराया जाता है","यह चिंतन और समझ पर अत्यधिक बल देता है और व्यवहार पर बहुत कम ध्यान देता है","यह बच्चों की भाषा की सृजनात्मकता को किसी भी अन्य सिद्धांत से बेहतर समझाता है","यह मानसिक प्रक्रियाओं की उपेक्षा करता है और यह आसानी से नहीं समझा पाता कि बच्चे नए वाक्य कैसे बनाते हैं"],"explanationHi":"व्यवहारवाद प्रेक्षणीय व्यवहार और साहचर्यों का अध्ययन करता है; चॉम्स्की जैसे आलोचकों ने तर्क दिया कि यह भाषा की सृजनात्मकता नहीं समझा सकता, और संज्ञानात्मक मनोवैज्ञानिकों ने आंतरिक प्रक्रियाओं पर बल दिया।"},
  {"id":"cdp-child-development-1108","question":"Assertion (A): When a teacher praises a child for a correct answer, the child is more likely to answer in that way again. Reason (R): According to Thorndike, a connection followed by a satisfying state of affairs is strengthened.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"This is a direct application of Thorndike's law of effect: satisfying consequences strengthen the stimulus–response bond.","difficulty":"moderate","source":"CTET · UPTET","questionHi":"अभिकथन (A): जब शिक्षिका किसी बच्चे को सही उत्तर के लिए सराहती है, तो बच्चे द्वारा फिर उसी प्रकार उत्तर देने की संभावना बढ़ जाती है। कारण (R): थॉर्नडाइक के अनुसार, जिस संबंध के बाद संतोषजनक स्थिति आती है, वह सुदृढ़ हो जाता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"यह थॉर्नडाइक के प्रभाव के नियम का सीधा अनुप्रयोग है: संतोषजनक परिणाम उद्दीपक-अनुक्रिया बंधन को सुदृढ़ करते हैं।"},
  {"id":"cdp-child-development-1109","question":"In Watson's ‘Little Albert’ study, a child conditioned to fear a white rat also became afraid of a white rabbit and a fur coat. What is the main lesson for teachers?","options":["Fear cannot be learnt through experience; it is inherited and appears on its own with age","Frightening early experiences in a subject can produce fears that spread to related situations","Children’s fears always extinguish quickly by themselves, so teachers need not worry about them","Fear is learnt only by watching others being frightened, never through direct experience"],"answer":1,"explanation":"Watson showed that emotional responses can be classically conditioned and generalise to similar stimuli. A child shamed in one maths class may come to fear maths in general.","difficulty":"hard","source":"CTET Paper 1 · Super TET","questionHi":"वॉटसन के ‘लिटिल अल्बर्ट’ अध्ययन में, एक बच्चा जो सफ़ेद चूहे से डरने के लिए अनुबंधित किया गया, वह सफ़ेद खरगोश और फर के कोट से भी डरने लगा। शिक्षकों के लिए मुख्य सीख क्या है?","optionsHi":["भय अनुभव से नहीं सीखा जा सकता; वह वंशानुगत है और आयु के साथ अपने आप प्रकट होता है","किसी विषय में आरंभिक भयावह अनुभव ऐसे भय उत्पन्न कर सकते हैं जो संबंधित परिस्थितियों में फैल जाते हैं","बच्चों के भय हमेशा अपने आप जल्दी विलुप्त हो जाते हैं, इसलिए शिक्षकों को उनकी चिंता नहीं करनी चाहिए","भय केवल दूसरों को डरते हुए देखकर सीखा जाता है, प्रत्यक्ष अनुभव से कभी नहीं"],"explanationHi":"वॉटसन ने दिखाया कि भावनात्मक अनुक्रियाएँ शास्त्रीय रूप से अनुबंधित हो सकती हैं और समान उद्दीपकों में सामान्यीकृत हो जाती हैं। गणित की किसी एक कक्षा में अपमानित बच्चा सामान्यतः गणित से डरने लगे, यह संभव है।"},
  {"id":"cdp-child-development-1110","question":"Instead of scolding Simran each time she leaves her seat, the teacher deliberately praises her whenever she is seated and working. Her wandering decreases. This strategy is best described as:","options":["Negative punishment of wandering","Positive punishment of wandering, using praise as the punisher","Reinforcing an incompatible behaviour","Classical extinction"],"answer":2,"explanation":"Sitting and working cannot occur at the same time as wandering, so reinforcing it reduces wandering without punishment. This is differential reinforcement of incompatible behaviour.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"सिमरन के हर बार अपनी सीट छोड़ने पर डाँटने के बजाय, शिक्षिका जानबूझकर उसे तभी सराहती है जब वह बैठी और काम करती है। उसका घूमना घट जाता है। इस युक्ति का सबसे अच्छा वर्णन है:","optionsHi":["घूमने का नकारात्मक दंड","घूमने का सकारात्मक दंड, जिसमें प्रशंसा दंडक का काम करती है","असंगत व्यवहार का पुनर्बलन","शास्त्रीय विलोपन"],"explanationHi":"बैठना और काम करना घूमने के साथ एक ही समय में नहीं हो सकता, इसलिए उसे पुनर्बलित करने से बिना दंड के घूमना घटता है। यह असंगत व्यवहार का विभेदक पुनर्बलन है।"},
  {"id":"cdp-child-development-1111","question":"According to Gagné's hierarchy of learning types, before Class 3 children can learn the rule ‘a sentence begins with a capital letter and ends with a full stop’, they must already have learnt:","options":["Problem solving","Signal learning only, since rules are simple stimulus-response links","Classical conditioning of writing","The concepts of ‘sentence’, ‘capital letter’ and ‘full stop’"],"answer":3,"explanation":"In Gagné's hierarchy, principle (rule) learning requires the relevant concepts to be learnt first; a rule is a relation between concepts.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"गैग्ने के अधिगम-प्रकारों के पदानुक्रम के अनुसार, कक्षा 3 के बच्चे यह नियम ‘वाक्य बड़े अक्षर से शुरू होता है और पूर्ण विराम पर समाप्त होता है’ सीख पाएँ, इससे पहले उन्हें पहले से सीख लेना चाहिए:","optionsHi":["समस्या-समाधान","केवल संकेत अधिगम, क्योंकि नियम सरल उद्दीपक-अनुक्रिया संबंध हैं","लेखन का शास्त्रीय अनुबंधन","‘वाक्य’, ‘बड़ा अक्षर’ और ‘पूर्ण विराम’ की अवधारणाएँ"],"explanationHi":"गैग्ने के पदानुक्रम में सिद्धांत (नियम) अधिगम के लिए संबंधित अवधारणाओं का पहले सीखा जाना आवश्यक है; नियम अवधारणाओं के बीच का संबंध है।"},
  {"id":"cdp-child-development-1112","question":"In a self-learning computer programme, a student who chooses a wrong option is sent to an extra explanatory frame before returning to the main sequence, while correct answerers move on directly. This is:","options":["Branching programming, associated with Norman Crowder","Linear programming, associated with Skinner’s teaching machines","Classical conditioning","Discovery learning"],"answer":0,"explanation":"Skinner's linear programmes have every learner follow the same small steps; Crowder's branching programmes route learners to different frames depending on their answers.","difficulty":"very-hard","source":"CTET Paper 2 · NVS TGT","questionHi":"एक स्व-अधिगम कंप्यूटर कार्यक्रम में, गलत विकल्प चुनने वाले विद्यार्थी को मुख्य क्रम में लौटने से पहले एक अतिरिक्त व्याख्यात्मक फ़्रेम पर भेजा जाता है, जबकि सही उत्तर देने वाले सीधे आगे बढ़ते हैं। यह है:","optionsHi":["शाखीय अभिक्रमित अनुदेशन, जो नॉर्मन क्राउडर से जुड़ा है","रेखीय अभिक्रमित अनुदेशन, जो स्किनर की शिक्षण मशीनों से जुड़ा है","शास्त्रीय अनुबंधन","खोज अधिगम"],"explanationHi":"स्किनर के रेखीय कार्यक्रमों में हर अधिगमकर्ता एक ही छोटे चरणों का अनुसरण करता है; क्राउडर के शाखीय कार्यक्रम अधिगमकर्ताओं को उनके उत्तरों के अनुसार अलग-अलग फ़्रेम पर भेजते हैं।"},
  {"id":"cdp-child-development-1113","question":"Assertion (A): A gold star that increases homework completion for one child may not be a reinforcer at all for another. Reason (R): In operant theory a reinforcer is defined by its effect on the behaviour it follows, not by how pleasant it seems to the teacher.","options":["A is true but R is false","Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":1,"explanation":"A consequence is a reinforcer only if it increases the behaviour. Because children value different things, the same star may reinforce one child and not another.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"अभिकथन (A): सुनहरा तारा जो एक बच्चे में गृहकार्य पूरा करना बढ़ाता है, दूसरे बच्चे के लिए पुनर्बलक बिल्कुल न हो, ऐसा संभव है। कारण (R): क्रियाप्रसूत सिद्धांत में पुनर्बलक की परिभाषा उस व्यवहार पर उसके प्रभाव से होती है जिसके बाद वह आता है, इस पर नहीं कि वह शिक्षक को कितना सुखद लगता है।","optionsHi":["A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A असत्य है परंतु R सत्य है"],"explanationHi":"कोई परिणाम पुनर्बलक तभी है जब वह व्यवहार को बढ़ाए। क्योंकि बच्चे भिन्न चीज़ों को महत्त्व देते हैं, वही तारा एक बच्चे को पुनर्बलित कर सकता है और दूसरे को नहीं।"},
  {"id":"cdp-child-development-1114","question":"Which statements about reinforcement schedules are correct? I. Fixed-ratio schedules often produce a short pause after each reinforcement. II. Variable-interval schedules produce a steady, moderate rate of response. III. Behaviour learnt under continuous reinforcement extinguishes faster than behaviour learnt under intermittent reinforcement. IV. Fixed-interval schedules produce a perfectly steady rate throughout the interval.","options":["I and IV only","II and IV only","I, II and III only","I, II, III and IV"],"answer":2,"explanation":"Fixed-interval schedules produce a 'scallop', with little responding early and a burst near the end of the interval, so IV is false. The rest are standard findings.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"पुनर्बलन अनुसूचियों के बारे में कौन-से कथन सही हैं? I. स्थिर-अनुपात अनुसूचियाँ प्रायः हर पुनर्बलन के बाद छोटा विराम उत्पन्न करती हैं। II. परिवर्ती-अंतराल अनुसूचियाँ अनुक्रिया की स्थिर, मध्यम दर उत्पन्न करती हैं। III. सतत पुनर्बलन में सीखा गया व्यवहार सविराम पुनर्बलन में सीखे गए व्यवहार की तुलना में अधिक शीघ्र विलुप्त होता है। IV. स्थिर-अंतराल अनुसूचियाँ पूरे अंतराल में पूर्णतः स्थिर दर उत्पन्न करती हैं।","optionsHi":["केवल I और IV","केवल II और IV","केवल I, II और III","I, II, III और IV"],"explanationHi":"स्थिर-अंतराल अनुसूचियाँ ‘स्कैलप’ बनाती हैं, जिसमें अंतराल के आरंभ में कम अनुक्रिया और अंत के निकट तेज़ वृद्धि होती है, इसलिए IV असत्य है। शेष मानक निष्कर्ष हैं।"},
  {"id":"cdp-child-development-1115","question":"A pre-primary teacher greets children warmly, plays songs and offers a favourite activity at the start of each day so that the school gate itself comes to evoke happy feelings. Which principle is she mainly using?","options":["Operant shaping of punctual arrival at school","Law of readiness","Insight learning","Classical conditioning of positive emotions"],"answer":3,"explanation":"Repeatedly pairing the school setting with pleasant experiences makes the setting a conditioned stimulus for positive feelings, reducing separation anxiety.","difficulty":"moderate","source":"CTET · REET","questionHi":"एक पूर्व-प्राथमिक शिक्षिका हर दिन आरंभ में बच्चों का स्नेहपूर्वक स्वागत करती है, गीत बजाती है और उनकी पसंदीदा गतिविधि देती है, ताकि विद्यालय का द्वार ही सुखद भावनाएँ जगाने लगे। वह मुख्यतः किस सिद्धांत का उपयोग कर रही है?","optionsHi":["विद्यालय में समय पर आने का क्रियाप्रसूत आकार देना","तत्परता का नियम","अंतर्दृष्टि अधिगम","सकारात्मक भावनाओं का शास्त्रीय अनुबंधन"],"explanationHi":"विद्यालय के परिवेश को सुखद अनुभवों से बार-बार जोड़ने से वह परिवेश सकारात्मक भावनाओं का अनुबंधित उद्दीपक बन जाता है, जिससे वियोग-चिंता घटती है।"},
  {"id":"cdp-child-development-1116","question":"A coach teaches a nervous Class 6 girl the long jump by first praising a clean run-up, then a run-up with take-off from the board, then a take-off with a good arm swing, and finally the full jump with landing. How does this differ from simple trial and error?","options":["The coach reinforces closer and closer approximations instead of waiting for the full jump by chance","It does not really differ, since both rely on the learner’s random attempts until one finally succeeds","The coach relies on sudden insight into the whole jump rather than on any reinforcement","The coach uses negative reinforcement, removing praise at each step until the jump is complete"],"answer":0,"explanation":"Shaping builds a complex skill through planned reinforcement of successive approximations; in trial and error the learner tries responses until one happens to succeed.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक प्रशिक्षक घबराई हुई कक्षा 6 की बालिका को लंबी कूद पहले साफ़ दौड़ की प्रशंसा करके, फिर बोर्ड से उछाल वाली दौड़ की, फिर अच्छे भुजा-झूले के साथ उछाल की, और अंत में लैंडिंग सहित पूरी कूद की प्रशंसा करके सिखाता है। यह सरल प्रयास-और-त्रुटि से कैसे भिन्न है?","optionsHi":["प्रशिक्षक पूरी कूद के संयोगवश होने की प्रतीक्षा करने के बजाय निकट-से-निकटतर सन्निकटनों को पुनर्बलित करता है","यह वास्तव में भिन्न नहीं है, क्योंकि दोनों अधिगमकर्ता के यादृच्छिक प्रयासों पर निर्भर करते हैं जब तक कोई सफल न हो","प्रशिक्षक किसी पुनर्बलन पर नहीं, बल्कि पूरी कूद की अचानक अंतर्दृष्टि पर निर्भर करता है","प्रशिक्षक नकारात्मक पुनर्बलन का उपयोग करता है, कूद पूरी होने तक हर चरण पर प्रशंसा हटाता जाता है"],"explanationHi":"आकार देना जटिल कौशल को क्रमिक सन्निकटनों के नियोजित पुनर्बलन से बनाता है; प्रयास-और-त्रुटि में अधिगमकर्ता अनुक्रियाएँ तब तक आज़माता है जब तक कोई संयोग से सफल न हो जाए।"},
  {"id":"cdp-child-development-1117","question":"A teacher wants Class 2 children to stop confusing the letters b and d. She shows pairs and praises responses only when the child correctly names the letter, never when b is called d. What process is she trying to build?","options":["Generalisation","Discrimination","Spontaneous recovery","Higher-order conditioning"],"answer":1,"explanation":"Discrimination is learning to respond differently to similar stimuli; reinforcing the correct response to each and not to the other sharpens this distinction.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षिका चाहती है कि कक्षा 2 के बच्चे अक्षरों b और d को आपस में उलझाना बंद करें। वह जोड़े दिखाती है और केवल तब सराहती है जब बच्चा अक्षर का नाम सही बताए, जब b को d कहा जाए तब कभी नहीं। वह किस प्रक्रिया को विकसित करने का प्रयास कर रही है?","optionsHi":["सामान्यीकरण","विभेदन","स्वतः पुनर्प्राप्ति","उच्चतर-क्रम अनुबंधन"],"explanationHi":"विभेदन समान उद्दीपकों पर भिन्न अनुक्रिया करना सीखना है; प्रत्येक के लिए सही अनुक्रिया को पुनर्बलित करना और दूसरे के लिए नहीं, इस भेद को तीक्ष्ण करता है।"},
  {"id":"cdp-child-development-1118","question":"A boy taught by Thorndike-style drill can recite ‘7 × 8 = 56’ instantly but cannot solve a word problem asking for the cost of 7 packets at ₹8 each. Which statement best explains this?","options":["Drill has caused retroactive interference, so later learning has wiped out the table facts","He has a problem of attention and simply did not read the word problem carefully enough to solve it","Rote S–R bonds may not transfer to new situations unless he understands what multiplication means","He has reached the formal operational stage early and now finds concrete problems too easy"],"answer":2,"explanation":"Rote S–R bonds are tied to the trained form. Without understanding what multiplication means, the learner cannot recognise when to use it in a new context.","difficulty":"hard","source":"CTET Paper 1 · Super TET","questionHi":"थॉर्नडाइक-शैली के अभ्यास से सिखाया गया एक लड़का ‘7 × 8 = 56’ तुरंत सुना सकता है, पर ₹8 वाले 7 पैकेटों की कीमत पूछने वाली शब्द-समस्या हल नहीं कर पाता। इसे कौन-सा कथन सबसे अच्छी तरह समझाता है?","optionsHi":["अभ्यास ने पश्चलक्षी व्यतिकरण पैदा किया है, इसलिए बाद के अधिगम ने पहाड़े के तथ्य मिटा दिए","उसे ध्यान की समस्या है और उसने शब्द-समस्या को हल करने लायक ध्यान से पढ़ा ही नहीं","रटे हुए उद्दीपक-अनुक्रिया बंधन नई परिस्थितियों में स्थानांतरित नहीं हो सकते जब तक वह न समझे कि गुणन का क्या अर्थ है","वह औपचारिक संक्रियात्मक अवस्था में जल्दी पहुँच गया है और अब मूर्त समस्याएँ उसे बहुत आसान लगती हैं"],"explanationHi":"रटे हुए उद्दीपक-अनुक्रिया बंधन प्रशिक्षित रूप से बँधे होते हैं। गुणन का अर्थ समझे बिना, अधिगमकर्ता नहीं पहचान पाता कि उसे नए संदर्भ में कब प्रयोग करना है।"},
  {"id":"cdp-child-development-1119","question":"Which of the following is the best example of negative reinforcement in a classroom?","options":["A child loses break time for not finishing work, so she starts finishing her work more often","A child is scolded for talking in class, which removes the talking that the teacher found unpleasant","A child receives a sticker for neat work, and the sticker is taken away if work gets messy","A child who finishes classwork early is excused from that day’s homework and finishes early more often"],"answer":3,"explanation":"Negative reinforcement increases a behaviour by removing something unpleasant (homework). Losing break time is negative punishment, scolding is positive punishment, and a sticker is positive reinforcement.","difficulty":"moderate","source":"CTET · DSSSB PRT","questionHi":"कक्षा में नकारात्मक पुनर्बलन का सर्वोत्तम उदाहरण निम्नलिखित में से कौन-सा है?","optionsHi":["काम पूरा न करने पर एक बालिका का मध्यावकाश का समय छिन जाता है, इसलिए वह अपना काम अधिक बार पूरा करने लगती है","कक्षा में बात करने के लिए बच्चे को डाँटा जाता है, जिससे वह बातचीत हट जाती है जो शिक्षक को अप्रिय लगती थी","साफ़ काम के लिए बच्चे को स्टिकर मिलता है, और काम गंदा होने पर स्टिकर वापस ले लिया जाता है","जो बच्चा कक्षा-कार्य जल्दी पूरा कर लेता है उसे उस दिन के गृहकार्य से छूट मिलती है और वह अधिक बार जल्दी पूरा करने लगता है"],"explanationHi":"नकारात्मक पुनर्बलन किसी अप्रिय चीज़ (गृहकार्य) को हटाकर व्यवहार बढ़ाता है। मध्यावकाश खोना नकारात्मक दंड है, डाँटना सकारात्मक दंड है, और स्टिकर सकारात्मक पुनर्बलन है।"},
  {"id":"cdp-child-development-1120","question":"A school proudly reports that every child with a disability in its area is enrolled. Observation shows that these children rarely take part in class activities, and nobody tracks what they are learning. Which aspects of inclusion are missing?","options":["Presence only","Participation and achievement","Presence and participation","None, since enrolment is the measure of inclusion"],"answer":1,"explanation":"Inclusion means presence, participation and achievement; the children are present, but without taking part and making tracked progress, the school has only achieved enrolment.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक विद्यालय गर्व से बताता है कि उसके क्षेत्र का हर विकलांग बच्चा नामांकित है। अवलोकन से पता चलता है कि ये बच्चे कक्षा-गतिविधियों में शायद ही भाग लेते हैं और कोई नहीं देखता कि वे क्या सीख रहे हैं। समावेशन के कौन-से पहलू अनुपस्थित हैं?","optionsHi":["केवल उपस्थिति","सहभागिता और उपलब्धि","उपस्थिति और सहभागिता","कोई नहीं, क्योंकि नामांकन ही समावेशन का मापक है"],"explanationHi":"समावेशन का अर्थ है उपस्थिति, सहभागिता और उपलब्धि; बच्चे उपस्थित हैं, परंतु भाग लिए बिना और अनुवर्ती प्रगति के बिना, विद्यालय ने केवल नामांकन प्राप्त किया है।"},
  {"id":"cdp-child-development-1121","question":"A school builds a ramp at its main gate for a wheelchair user, but the toilets have narrow doors and a step, and the drinking-water point is up a flight of stairs. What does this show about accessibility?","options":["The next step is a ramp at her classroom door, since the classroom matters most","A classmate should be assigned to help her reach the toilet and water point daily","Access must cover all daily needs such as toilets and water, not just the entry","She should get a ground-floor classroom near the gate so she has less to travel"],"answer":2,"explanation":"Accessibility means the child can use every facility independently, so toilets, water and play areas must be barrier-free too. A peer helper is kind but makes her dependent and leaves the barriers in place, which accessibility law does not accept.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक विद्यालय व्हीलचेयर उपयोगकर्ता बालिका के लिए मुख्य द्वार पर रैंप बनाता है, पर शौचालयों के द्वार संकरे हैं और सीढ़ी है, और पीने के पानी का स्थान सीढ़ियाँ चढ़कर है। यह सुगम्यता के बारे में क्या दर्शाता है?","optionsHi":["अगला कदम उसकी कक्षा के द्वार पर रैंप है, क्योंकि कक्षा सबसे अधिक मायने रखती है","एक सहपाठी को नियुक्त किया जाए जो रोज़ उसे शौचालय और पानी के स्थान तक पहुँचाने में सहायता करे","सुगम्यता को शौचालय और पानी जैसी सभी दैनिक आवश्यकताओं को शामिल करना चाहिए, केवल प्रवेश को नहीं","उसे द्वार के पास भूतल की कक्षा मिलनी चाहिए ताकि उसे कम दूरी तय करनी पड़े"],"explanationHi":"सुगम्यता का अर्थ है कि बच्ची हर सुविधा का स्वतंत्र रूप से उपयोग कर सके, इसलिए शौचालय, पानी और खेल के क्षेत्र भी बाधा-मुक्त होने चाहिए। सहपाठी की सहायता दयालु है पर उसे निर्भर बनाती है और बाधाओं को बनाए रखती है, जिसे सुगम्यता संबंधी कानून स्वीकार नहीं करता।"},
  {"id":"cdp-child-development-1122","question":"Despite good teaching, Pinku in Class 4 still confuses short and long matras (ि/ी, ु/ू), cannot read conjunct letters, reads word by word very slowly, and makes the same spelling errors repeatedly. Yet he understands stories read aloud very well. What should the teacher consider?","options":["That he is lazy about reading and needs more homework and daily copying practice","That he may have a specific reading difficulty such as dyslexia and needs structured support and assessment","That he has an intellectual disability, since he still cannot read at his grade level","That Hindi script is too hard for him and he should be moved to an English-medium section from next year"],"answer":1,"explanation":"Persistent decoding and spelling problems, despite good teaching and with strong listening comprehension, are a classic pattern of dyslexia, which also occurs in Indian scripts.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"अच्छे शिक्षण के बावजूद कक्षा 4 का पिंकू अब भी छोटी और बड़ी मात्राओं (ि/ी, ु/ू) में गड़बड़ करता है, संयुक्ताक्षर नहीं पढ़ पाता, शब्द-दर-शब्द बहुत धीरे पढ़ता है और वही वर्तनी की गलतियाँ बार-बार करता है। फिर भी वह सुनाई गई कहानियाँ बहुत अच्छी तरह समझता है। शिक्षक को क्या विचार करना चाहिए?","optionsHi":["वह पढ़ने में आलसी है और उसे अधिक गृहकार्य तथा रोज़ नकल का अभ्यास चाहिए","उसे डिस्लेक्सिया जैसी विशिष्ट पठन-कठिनाई हो सकती है और उसे संरचित सहायता तथा आकलन चाहिए","उसे बौद्धिक अक्षमता है, क्योंकि वह अब भी अपनी कक्षा के स्तर पर नहीं पढ़ सकता","हिंदी लिपि उसके लिए बहुत कठिन है और अगले वर्ष से उसे अंग्रेज़ी-माध्यम वाले वर्ग में भेज देना चाहिए"],"explanationHi":"अच्छे शिक्षण के बावजूद और सुनकर समझने की सशक्त क्षमता के साथ, लगातार डिकोडिंग और वर्तनी की समस्याएँ डिस्लेक्सिया का विशिष्ट प्रतिरूप हैं, जो भारतीय लिपियों में भी होता है।"},
  {"id":"cdp-child-development-1123","question":"Which of these statements about dyscalculia are correct? I. Dyscalculia can occur together with dyslexia in the same child. II. Maths anxiety can lower performance but is not the same as dyscalculia. III. Children with dyscalculia can never learn mathematics.","options":["I and III only","II and III only","I, II and III","I and II only"],"answer":3,"explanation":"Learning disabilities often co-occur, and anxiety is a separate (though related) factor; with suitable teaching, children with dyscalculia do make progress, so III is false.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"डिस्कैलकुलिया (गणित अधिगम अक्षमता) के बारे में इनमें से कौन-से कथन सही हैं? I. डिस्कैलकुलिया एक ही बच्चे में डिस्लेक्सिया के साथ हो सकता है। II. गणित-चिंता प्रदर्शन घटा सकती है, पर वह डिस्कैलकुलिया के समान नहीं है। III. डिस्कैलकुलिया वाले बच्चे गणित कभी नहीं सीख सकते।","optionsHi":["केवल I और III","केवल II और III","I, II और III","केवल I और II"],"explanationHi":"अधिगम अक्षमताएँ प्रायः साथ-साथ होती हैं, और चिंता एक अलग (यद्यपि संबंधित) कारक है; उपयुक्त शिक्षण से डिस्कैलकुलिया वाले बच्चे प्रगति करते हैं, इसलिए III असत्य है।"},
  {"id":"cdp-child-development-1124","question":"Tarun, a Class 7 student with ADHD, often forgets homework, loses worksheets and misses deadlines, though he understands the lessons. Which support is most appropriate?","options":["External organising aids such as a daily checklist, colour-coded folders and a planner reviewed daily","Lowering his marks each time he forgets so that he learns responsibility for his own work","Telling him firmly to try harder to remember, since he clearly understands the lessons and can do it","Excusing him from all homework and deadlines, since ADHD makes organisation impossible for him"],"answer":0,"explanation":"ADHD often involves weak executive functions such as planning and organising; external structure compensates and builds habits, whereas penalties and exhortation do not create the missing skill.","difficulty":"hard","source":"CTET · State TETs","questionHi":"तरुण, कक्षा 7 का ADHD वाला विद्यार्थी, प्रायः गृहकार्य भूल जाता है, कार्यपत्रक खो देता है और समय-सीमाएँ चूक जाता है, जबकि वह पाठ समझता है। कौन-सी सहायता सबसे उपयुक्त है?","optionsHi":["बाह्य संगठन-साधन, जैसे दैनिक जाँच-सूची, रंग-कोडित फ़ोल्डर और प्रतिदिन देखी जाने वाली योजना-पुस्तिका","जब भी वह भूले, उसके अंक घटाना ताकि वह अपने काम की ज़िम्मेदारी सीखे","उसे दृढ़ता से कहना कि याद रखने का और प्रयास करे, क्योंकि वह स्पष्टतः पाठ समझता है और कर सकता है","उसे सारे गृहकार्य और समय-सीमाओं से छूट देना, क्योंकि ADHD उसके लिए संगठन असंभव बना देता है"],"explanationHi":"ADHD में प्रायः नियोजन और संगठन जैसे कार्यकारी प्रकार्य कमज़ोर होते हैं; बाह्य संरचना क्षतिपूर्ति करती है और आदतें बनाती है, जबकि दंड और उपदेश वह कौशल नहीं बनाते जो अनुपस्थित है।"},
  {"id":"cdp-child-development-1125","question":"Sneha, a Class 2 child on the autism spectrum, becomes upset when an activity ends suddenly. Which practice will help her most?","options":["Changing activities without warning so that she gradually gets used to surprises and copes better later","Giving advance notice of transitions, such as a five-minute warning with a visual timer and schedule","Letting her continue her preferred activity all day so that she never has to face an ending","Removing her from the class during transitions and bringing her back once the new activity starts"],"answer":1,"explanation":"Advance warnings and visual cues make transitions predictable, which reduces anxiety for many autistic children; sudden change or avoidance does not build coping.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"स्नेहा, कक्षा 2 की ऑटिज़्म स्पेक्ट्रम वाली बालिका, किसी गतिविधि के अचानक समाप्त होने पर परेशान हो जाती है। कौन-सा अभ्यास उसकी सबसे अधिक सहायता करेगा?","optionsHi":["बिना चेतावनी के गतिविधियाँ बदलना, ताकि वह धीरे-धीरे आश्चर्यों की आदी हो जाए और बाद में बेहतर सामना कर सके","संक्रमण की पहले से सूचना देना, जैसे दृश्य टाइमर और समय-सारणी के साथ पाँच मिनट की चेतावनी","उसे पूरे दिन अपनी पसंदीदा गतिविधि जारी रखने देना ताकि उसे कभी समाप्ति का सामना न करना पड़े","संक्रमण के समय उसे कक्षा से हटा देना और नई गतिविधि शुरू होने पर वापस ले आना"],"explanationHi":"पहले से चेतावनी और दृश्य संकेत संक्रमण को पूर्वानुमेय बनाते हैं, जिससे अनेक ऑटिस्टिक बच्चों की चिंता घटती है; अचानक परिवर्तन या टालना सामना करना नहीं सिखाता।"},
  {"id":"cdp-child-development-1126","question":"Classmates laugh when Yash, an autistic Class 3 student, flaps his hands when excited. A teacher wants to stop the flapping. Which view is most appropriate?","options":["The flapping should be stopped firmly, since it looks odd and will keep inviting teasing from classmates","Yash should sit at the back so that others cannot see him flap and the laughing stops","Flapping helps many autistic children self-regulate; the teacher should build classmates’ acceptance","Yash should be sent out whenever he flaps, so that the lesson is not disturbed for others"],"answer":2,"explanation":"Harmless self-regulating movements need not be suppressed; the barrier is peers' lack of understanding, which the teacher can address through age-appropriate discussion of differences.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"जब कक्षा 3 का ऑटिस्टिक विद्यार्थी यश उत्साहित होने पर हाथ फड़फड़ाता है तो सहपाठी हँसते हैं। एक शिक्षक फड़फड़ाना रोकना चाहता है। कौन-सा दृष्टिकोण सबसे उपयुक्त है?","optionsHi":["फड़फड़ाना दृढ़ता से रोका जाए, क्योंकि वह अजीब दिखता है और सहपाठियों के चिढ़ाने को निमंत्रण देता रहेगा","यश को पीछे बैठाया जाए ताकि दूसरे उसे फड़फड़ाते न देख सकें और हँसी रुक जाए","फड़फड़ाना अनेक ऑटिस्टिक बच्चों को आत्म-नियमन में सहायता करता है; शिक्षक को सहपाठियों की स्वीकृति बढ़ानी चाहिए","जब भी यश फड़फड़ाए उसे बाहर भेज दिया जाए, ताकि दूसरों का पाठ न बिगड़े"],"explanationHi":"हानिरहित आत्म-नियमन करने वाली गतिविधियों को दबाना आवश्यक नहीं है; बाधा समवयस्कों की समझ की कमी है, जिसे शिक्षक भिन्नताओं पर आयु-उपयुक्त चर्चा से दूर कर सकता है।"},
  {"id":"cdp-child-development-1127","question":"Assertion (A): Blind students writing examinations in Braille should be given extra time. Reason (R): Reading and writing in Braille, and exploring tactile diagrams, generally take longer than reading print by sight.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Extra time compensates for the slower pace of tactile reading and writing, so the test measures knowledge rather than speed of the medium.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): ब्रेल में परीक्षा देने वाले दृष्टिबाधित विद्यार्थियों को अतिरिक्त समय मिलना चाहिए। कारण (R): ब्रेल में पढ़ने-लिखने और स्पर्श-आरेखों को टटोलने में सामान्यतः दृष्टि से मुद्रित पाठ पढ़ने की तुलना में अधिक समय लगता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"अतिरिक्त समय स्पर्श-आधारित पठन और लेखन की धीमी गति की क्षतिपूर्ति करता है, ताकि परीक्षा ज्ञान को मापे, माध्यम की गति को नहीं।"},
  {"id":"cdp-child-development-1128","question":"Leena, a Class 5 student with low vision, struggles to read the board on sunny afternoons. Which change is most helpful?","options":["Seating her facing the window so that more daylight falls directly on her book and on the board","Seating her with light from beside or behind her, and writing in large, high-contrast letters","Asking her to wear dark glasses in class so that the bright sunlight does not trouble her eyes","Moving her to the last row so that she can see the whole board at once without turning her head"],"answer":1,"explanation":"Glare from facing a bright window reduces usable vision; side or back light and high-contrast writing make the most of her remaining sight.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"लीना, कक्षा 5 की अल्प-दृष्टि वाली विद्यार्थी, धूप वाली दोपहरों में बोर्ड पढ़ने में कठिनाई महसूस करती है। कौन-सा परिवर्तन सबसे सहायक है?","optionsHi":["उसे खिड़की की ओर मुँह करके बैठाना ताकि उसकी पुस्तक और बोर्ड पर अधिक दिन का प्रकाश सीधे पड़े","उसे ऐसे बैठाना कि प्रकाश उसके बगल से या पीछे से आए, और बड़े, उच्च-विपर्यास अक्षरों में लिखना","कक्षा में उसे काला चश्मा पहनने को कहना ताकि तेज़ धूप उसकी आँखों को परेशान न करे","उसे अंतिम पंक्ति में भेजना ताकि वह सिर घुमाए बिना पूरा बोर्ड एक साथ देख सके"],"explanationHi":"तेज़ खिड़की की ओर मुँह करने से चौंध उसकी उपयोगी दृष्टि घटाती है; बगल या पीछे का प्रकाश और उच्च-विपर्यास लेखन उसकी शेष दृष्टि का सर्वोत्तम उपयोग कराते हैं।"},
  {"id":"cdp-child-development-1129","question":"Assertion (A): Many deaf children find it hard to learn to read in a spoken language such as Hindi or English. Reason (R): Deaf children have lower intelligence than hearing children.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Reading maps print onto a spoken language that deaf children may have had limited access to, which is why reading can be hard; deafness itself does not lower intelligence.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"अभिकथन (A): अनेक बधिर बच्चों को हिंदी या अंग्रेज़ी जैसी बोली जाने वाली भाषा में पढ़ना सीखना कठिन लगता है। कारण (R): बधिर बच्चों की बुद्धि श्रवणसक्षम बच्चों से कम होती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"पठन मुद्रित पाठ को उस बोली जाने वाली भाषा से जोड़ता है जिस तक बधिर बच्चों की सीमित पहुँच रही हो, इसीलिए पढ़ना कठिन हो सकता है; बधिरता स्वयं बुद्धि को कम नहीं करती।"},
  {"id":"cdp-child-development-1130","question":"How should the progress of Mohan, a Class 5 child with moderate intellectual disability in an inclusive class, mainly be judged?","options":["By ranking him with the rest of the class on the same tests and marking scheme","By whether he passes the regular Class 5 exam","By comparing him with other children with disabilities in the district, using common tests","Against the goals set in his individualised plan, recording his own growth over time"],"answer":3,"explanation":"For a child working towards individual goals, progress is best measured against those goals; comparison with class norms would only record failure and hide genuine learning.","difficulty":"hard","source":"CTET · State TETs","questionHi":"समावेशी कक्षा में मध्यम बौद्धिक अक्षमता वाले कक्षा 5 के बच्चे मोहन की प्रगति को मुख्यतः कैसे आँका जाना चाहिए?","optionsHi":["उसी परीक्षा और अंकन-योजना पर शेष कक्षा के साथ उसे श्रेणीबद्ध करके","इस आधार पर कि वह नियमित कक्षा 5 की परीक्षा उत्तीर्ण करता है या नहीं","सामान्य परीक्षणों से जिले के अन्य विकलांग बच्चों से उसकी तुलना करके","उसकी वैयक्तिकृत योजना में निर्धारित लक्ष्यों के विरुद्ध, समय के साथ उसकी अपनी वृद्धि दर्ज करके"],"explanationHi":"व्यक्तिगत लक्ष्यों की ओर बढ़ते बच्चे के लिए प्रगति को उन्हीं लक्ष्यों के विरुद्ध मापना सर्वोत्तम है; कक्षा-मानकों से तुलना केवल असफलता दर्ज करेगी और वास्तविक अधिगम को छिपा देगी।"},
  {"id":"cdp-child-development-1131","question":"A gifted Class 5 student has finished the chapter on water and its conservation well ahead of others. Which task extends her thinking most?","options":["Copying the chapter summary neatly into her notebook so that she can revise it later","Answering more textbook questions from the same exercise to make her mastery even more secure","Designing a rainwater harvesting plan for the school, estimating water saved and defending her choices","Reading and memorising the definitions in the next chapter so that she stays ahead of the class all year"],"answer":2,"explanation":"Gifted learners need tasks at higher levels of thinking, such as creating and evaluating in real contexts; more of the same or copying gives no new challenge.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 5 की एक प्रतिभाशाली विद्यार्थी ने जल और उसके संरक्षण का अध्याय दूसरों से बहुत पहले अच्छी तरह पूरा कर लिया है। कौन-सा कार्य उसके चिंतन को सबसे अधिक विस्तार देता है?","optionsHi":["अध्याय का सारांश साफ़-साफ़ अपनी कॉपी में उतारना ताकि वह बाद में दोहरा सके","उसी अभ्यास से और पाठ्यपुस्तक प्रश्न हल करना ताकि उसकी निपुणता और पक्की हो जाए","विद्यालय के लिए वर्षा जल संचयन की योजना बनाना, बचाए गए जल का अनुमान लगाना और अपने चयनों का बचाव करना","अगले अध्याय की परिभाषाएँ पढ़कर याद करना ताकि वह पूरे वर्ष कक्षा से आगे रहे"],"explanationHi":"प्रतिभाशाली अधिगमकर्ताओं को चिंतन के उच्च स्तर वाले कार्य चाहिए, जैसे वास्तविक संदर्भों में सृजन और मूल्यांकन; उसी का और अभ्यास या नकल करना कोई नई चुनौती नहीं देता।"},
  {"id":"cdp-child-development-1132","question":"The goal of a Class 3 lesson is that children can describe their village. The teacher’s task says ‘Write a paragraph about your village’. A child with dysgraphia and a new Hindi learner cannot show what they know. Following Universal Design for Learning, what is the best fix?","options":["Letting children describe their village by speaking, writing, drawing or recording","Keeping the written task for everyone but giving these two children lower marks for fairness","Giving these two children an easier topic to write about, such as their family","Excusing these two children from the task until their writing and Hindi improve enough"],"answer":0,"explanation":"When the goal is description, insisting on handwriting adds a barrier unrelated to the goal; UDL offers flexible means of expression while keeping the same goal for all.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 3 के पाठ का लक्ष्य है कि बच्चे अपने गाँव का वर्णन कर सकें। शिक्षक का कार्य कहता है, ‘अपने गाँव के बारे में एक अनुच्छेद लिखो।’ डिसग्राफिया वाला एक बच्चा और हिंदी सीखने वाला एक नया बच्चा जो जानते हैं वह दिखा नहीं पाते। अधिगम के लिए सार्वभौमिक अभिकल्प (UDL) के अनुसार सर्वोत्तम समाधान क्या है?","optionsHi":["बच्चों को अपने गाँव का वर्णन बोलकर, लिखकर, चित्र बनाकर या रिकॉर्ड करके करने देना","सबके लिए लिखित कार्य रखना, पर निष्पक्षता के नाम पर इन दो बच्चों को कम अंक देना","इन दो बच्चों को लिखने के लिए आसान विषय देना, जैसे उनका परिवार","इन दो बच्चों को तब तक कार्य से छूट देना जब तक उनका लेखन और हिंदी पर्याप्त न सुधर जाए"],"explanationHi":"जब लक्ष्य वर्णन है, तब हस्तलेखन का आग्रह लक्ष्य से असंबंधित बाधा जोड़ता है; UDL सभी के लिए एक ही लक्ष्य रखते हुए अभिव्यक्ति के लचीले साधन प्रदान करता है।"},
  {"id":"cdp-child-development-1133","question":"Assertion (A): Once students have been grouped by readiness in April, the groups should stay the same for the whole year. Reason (R): A student’s readiness varies from topic to topic and changes with learning.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Because readiness differs across topics and grows over time, groups must be flexible; fixing them for a year turns differentiation into tracking.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): एक बार अप्रैल में विद्यार्थियों को तैयारी (रेडीनेस) के आधार पर समूहबद्ध कर देने के बाद, समूह पूरे वर्ष वही रहने चाहिए। कारण (R): विद्यार्थी की तैयारी विषय-विषय पर बदलती है और अधिगम के साथ बदलती रहती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"क्योंकि तैयारी विषयों में भिन्न होती है और समय के साथ बढ़ती है, समूह लचीले होने चाहिए; उन्हें एक वर्ष के लिए स्थिर करना विभेदीकरण को ट्रैकिंग (स्थायी वर्गीकरण) में बदल देता है।"},
  {"id":"cdp-child-development-1134","question":"Children from a community that has long been stereotyped as ‘thieves’ join a Class 4 class. Some classmates repeat this label and refuse to sit with them. What is the most appropriate response?","options":["Seating these children together in one corner so that the others feel comfortable for now","Ignoring the remarks, since young children repeat such words from home without meaning them seriously","Telling the new children to prove their honesty through good behaviour so the label fades","Stating that the label is unacceptable, discussing stereotypes and forming mixed working groups"],"answer":3,"explanation":"Community stereotypes must be confronted directly; working together in mixed groups builds real relationships, whereas isolating or burdening the stereotyped children deepens exclusion.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"एक ऐसे समुदाय के बच्चे, जिन्हें लंबे समय से ‘चोर’ की रूढ़िबद्ध धारणा से देखा गया है, कक्षा 4 में आते हैं। कुछ सहपाठी यह लेबल दोहराते हैं और उनके साथ बैठने से मना करते हैं। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["इन बच्चों को एक कोने में साथ बैठाना ताकि अन्य अभी सहज महसूस करें","टिप्पणियों को अनदेखा करना, क्योंकि छोटे बच्चे ऐसे शब्द घर से दोहराते हैं और गंभीरता से नहीं कहते","नए बच्चों से कहना कि वे अच्छे व्यवहार से अपनी ईमानदारी सिद्ध करें ताकि लेबल मिट जाए","यह स्पष्ट करना कि लेबल अस्वीकार्य है, रूढ़िबद्ध धारणाओं पर चर्चा करना और मिश्रित कार्य-समूह बनाना"],"explanationHi":"सामुदायिक रूढ़िबद्ध धारणाओं का सीधा सामना होना चाहिए; मिश्रित समूहों में साथ काम करना वास्तविक संबंध बनाता है, जबकि रूढ़िबद्ध धारणा वाले बच्चों को अलग करना या उन पर बोझ डालना बहिष्कार को गहरा करता है।"},
  {"id":"cdp-child-development-1135","question":"Sam, a Class 6 student, prefers to dress and be addressed as a girl. Some classmates bully her and refuse to let her use the girls’ line. What should the school do?","options":["Ask the child to dress and behave according to the sex recorded at admission, so as to avoid further trouble","Stop the bullying, respect her identity and safety in school spaces, and involve the counsellor and family","Shift the child to another section so that she is separated from the bullies for good","Treat the matter as private to the family and take no action unless parents complain"],"answer":1,"explanation":"Gender identity is to be respected and every child has a right to a safe, non-discriminatory school; the school must act against bullying rather than move or blame the victim.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 6 की विद्यार्थी सैम लड़की की तरह कपड़े पहनना और उसी रूप में संबोधित किया जाना पसंद करती है। कुछ सहपाठी उसे परेशान करते हैं और उसे लड़कियों की कतार में खड़े होने नहीं देते। विद्यालय को क्या करना चाहिए?","optionsHi":["बच्चे से कहना कि प्रवेश के समय दर्ज लिंग के अनुसार कपड़े पहने और व्यवहार करे, ताकि आगे परेशानी से बचा जा सके","उत्पीड़न रोकना, विद्यालय के स्थानों में उसकी पहचान और सुरक्षा का सम्मान करना, और परामर्शदाता तथा परिवार को शामिल करना","बच्चे को दूसरे वर्ग में भेजना ताकि वह उत्पीड़कों से सदा के लिए अलग हो जाए","मामले को परिवार का निजी विषय मानकर अभिभावकों के शिकायत करने तक कोई कार्रवाई न करना"],"explanationHi":"लैंगिक पहचान का सम्मान किया जाना चाहिए और हर बच्चे को सुरक्षित, भेदभाव-रहित विद्यालय का अधिकार है; विद्यालय को पीड़ित को स्थानांतरित करने या दोष देने के बजाय उत्पीड़न के विरुद्ध कार्रवाई करनी चाहिए।"},
  {"id":"cdp-child-development-1136","question":"A Class 5 teacher praises girls for neat handwriting and good behaviour, and praises boys for clever ideas and solving hard problems. What is the main problem?","options":["Praise should not be used in class at all, since it makes children dependent on approval","Girls should receive more praise than boys, since they generally behave better in class","There is no problem as long as the praise is sincere and each child is praised for genuine strengths","The pattern teaches that intelligence belongs to boys and neatness to girls, reinforcing stereotypes"],"answer":3,"explanation":"Differential feedback silently shapes children's self-image; praise should target ideas and effort for all children equally.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 5 की एक शिक्षिका लड़कियों की साफ़ लिखावट और अच्छे व्यवहार की प्रशंसा करती है, और लड़कों की चतुर विचारों तथा कठिन समस्याएँ हल करने की। मुख्य समस्या क्या है?","optionsHi":["कक्षा में प्रशंसा का उपयोग बिल्कुल नहीं करना चाहिए, क्योंकि वह बच्चों को स्वीकृति पर निर्भर बनाती है","लड़कियों को लड़कों से अधिक प्रशंसा मिलनी चाहिए, क्योंकि वे कक्षा में सामान्यतः बेहतर व्यवहार करती हैं","कोई समस्या नहीं है, जब तक प्रशंसा सच्ची है और हर बच्चे की वास्तविक शक्तियों के लिए की गई है","यह प्रतिरूप सिखाता है कि बुद्धि लड़कों की है और सफ़ाई लड़कियों की, जिससे रूढ़िबद्ध धारणाएँ पुष्ट होती हैं"],"explanationHi":"भिन्न-भिन्न प्रतिक्रिया चुपचाप बच्चों की आत्म-छवि को आकार देती है; प्रशंसा सभी बच्चों के लिए समान रूप से विचारों और प्रयास पर केंद्रित होनी चाहिए।"},
  {"id":"cdp-child-development-1137","question":"Assertion (A): A child who mixes Hindi and English in one sentence is confused about both languages. Reason (R): Bilingual children draw on both their languages flexibly and strategically to express meaning.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Code-switching is a normal, rule-governed skill of bilinguals, not a sign of confusion; so A is false while R is true.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): जो बच्चा एक वाक्य में हिंदी और अंग्रेज़ी मिलाता है, वह दोनों भाषाओं के बारे में भ्रमित है। कारण (R): द्विभाषी बच्चे अर्थ व्यक्त करने के लिए अपनी दोनों भाषाओं का लचीले और रणनीतिक ढंग से उपयोग करते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"कोड-स्विचिंग द्विभाषियों का सामान्य, नियम-शासित कौशल है, भ्रम का संकेत नहीं; इसलिए A असत्य है जबकि R सत्य है।"},
  {"id":"cdp-child-development-1138","question":"Students in a rural Class 8, mostly first-generation learners, believe that further study is ‘not for people like us’. Which step by the teacher is most likely to raise their aspirations?","options":["Bringing in role models from similar backgrounds and showing real pathways to further study","Telling them that only toppers should think of higher studies, so that expectations stay realistic","Avoiding the topic, since aspirations come mainly from home and cannot be changed by school","Advising them to choose the jobs their parents do, since these are secure and familiar"],"answer":0,"explanation":"Seeing people like themselves succeed, with clear routes forward, counters the belief that education is not for them; avoiding the topic leaves low expectations in place.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"ग्रामीण कक्षा 8 के विद्यार्थी, जिनमें अधिकांश पहली पीढ़ी के अधिगमकर्ता हैं, मानते हैं कि आगे की पढ़ाई ‘हम जैसे लोगों के लिए नहीं है’। शिक्षक का कौन-सा कदम उनकी आकांक्षाओं को बढ़ाने की सबसे अधिक संभावना रखता है?","optionsHi":["समान पृष्ठभूमि वाले आदर्श व्यक्तियों को बुलाना और आगे की पढ़ाई के वास्तविक मार्ग दिखाना","उन्हें बताना कि केवल अव्वल रहने वालों को उच्च अध्ययन के बारे में सोचना चाहिए, ताकि अपेक्षाएँ यथार्थवादी रहें","विषय से बचना, क्योंकि आकांक्षाएँ मुख्यतः घर से आती हैं और विद्यालय उन्हें नहीं बदल सकता","उन्हें वही नौकरियाँ चुनने की सलाह देना जो उनके माता-पिता करते हैं, क्योंकि वे सुरक्षित और परिचित हैं"],"explanationHi":"स्वयं जैसे लोगों को स्पष्ट मार्गों के साथ सफल होते देखना इस धारणा का प्रतिकार करता है कि शिक्षा उनके लिए नहीं है; विषय से बचना कम अपेक्षाओं को बनाए रखता है।"},
  {"id":"cdp-child-development-1139","question":"Classmates mimic the limp of Raju, a Class 6 student with a locomotor disability. Which response is most effective?","options":["Punishing the children who mimic, firmly and at once, without any further class discussion","Advising Raju to stay inside the classroom during breaks so that he is not exposed to more teasing","Clear rules and consequences for the mimicking, whole-class work on empathy, and support for Raju","Telling Raju that it is only a joke and that he should learn not to mind such teasing"],"answer":2,"explanation":"Bullying of children with disabilities needs a whole-class approach: firm rules and consequences together with building empathy, while supporting the child without restricting him.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 6 के विद्यार्थी राजू, जिसे गमन-संबंधी विकलांगता है, के लँगड़ाने की सहपाठी नकल करते हैं। कौन-सी प्रतिक्रिया सबसे प्रभावी है?","optionsHi":["नकल करने वाले बच्चों को दृढ़ता से और तुरंत दंडित करना, बिना किसी और कक्षा-चर्चा के","राजू को सलाह देना कि वह मध्यावकाश में कक्षा के भीतर रहे ताकि और चिढ़ाए जाने से बचे","नकल के लिए स्पष्ट नियम और परिणाम, सहानुभूति पर पूरी कक्षा के साथ कार्य, और राजू के लिए सहायता","राजू से कहना कि यह केवल मज़ाक है और उसे ऐसी छेड़छाड़ का बुरा न मानना सीखना चाहिए"],"explanationHi":"विकलांग बच्चों के उत्पीड़न के लिए पूरी कक्षा का दृष्टिकोण चाहिए: सहानुभूति का निर्माण करने के साथ कड़े नियम और परिणाम, और बच्चे को प्रतिबंधित किए बिना सहायता देना।"},
  {"id":"cdp-child-development-1140","question":"A teacher gives a four-step spoken instruction: ‘Take out your book, open page 20, read the first paragraph and underline the verbs.’ Ramesh, who has intellectual disability, completes only the first step. What is the best adjustment?","options":["Repeating all four steps more loudly and slowly so that he can hear every one clearly","Telling him to listen more carefully next time and to ask a friend whenever he forgets a step","Asking a classmate to do the remaining steps for him so that he does not fall behind","Giving one instruction at a time, with a demonstration or picture cue, and checking each step"],"answer":3,"explanation":"Limited working memory makes multi-step oral instructions hard to hold; breaking them into single steps with visual cues lets him complete the full task.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"एक शिक्षक चार चरणों वाला मौखिक निर्देश देता है: ‘अपनी पुस्तक निकालो, पृष्ठ 20 खोलो, पहला अनुच्छेद पढ़ो और क्रियाओं को रेखांकित करो।’ बौद्धिक अक्षमता वाला रमेश केवल पहला चरण पूरा करता है। सर्वोत्तम समायोजन क्या है?","optionsHi":["चारों चरण और ज़ोर से तथा धीरे दोहराना ताकि वह हर एक स्पष्ट सुन सके","उसे कहना कि अगली बार अधिक ध्यान से सुने और कोई चरण भूलने पर मित्र से पूछे","किसी सहपाठी से उसके शेष चरण करवाना ताकि वह पीछे न रह जाए","एक बार में एक निर्देश देना, प्रदर्शन या चित्र-संकेत के साथ, और हर चरण की जाँच करना"],"explanationHi":"सीमित कार्यकारी स्मृति बहु-चरण मौखिक निर्देशों को धारण करना कठिन बनाती है; उन्हें दृश्य संकेतों के साथ एकल चरणों में बाँटना उसे पूरा कार्य करने देता है।"},
  {"id":"cdp-child-development-1141","question":"Under the RPwD Act, 2016, which of the following situations amounts to discrimination by denial of reasonable accommodation?","options":["A school refuses to shift Class 7 to an available ground-floor room for its wheelchair-using student","A school arranges a scribe for a student with a fractured hand while writing the annual examinations","A school seats a child with a hearing impairment in the front row, close to the teacher","A school gives large-print question papers to a child with low vision during all tests"],"answer":0,"explanation":"Discrimination on the basis of disability includes denial of reasonable accommodation; moving a class to an available ground-floor room is a simple adjustment without undue burden.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"RPwD अधिनियम, 2016 के अंतर्गत, निम्नलिखित में से कौन-सी स्थिति उचित समायोजन से इनकार द्वारा भेदभाव के अंतर्गत आती है?","optionsHi":["एक विद्यालय अपने व्हीलचेयर-प्रयोगकर्ता विद्यार्थी के लिए कक्षा 7 को उपलब्ध भूतल के कमरे में स्थानांतरित करने से इनकार करता है","एक विद्यालय वार्षिक परीक्षाओं के दौरान हाथ में फ्रैक्चर वाले विद्यार्थी के लिए लेखक की व्यवस्था करता है","एक विद्यालय श्रवण-बाधित बच्चे को शिक्षक के निकट अगली पंक्ति में बैठाता है","एक विद्यालय सभी परीक्षाओं में अल्प-दृष्टि वाले बच्चे को बड़े अक्षरों वाले प्रश्न-पत्र देता है"],"explanationHi":"विकलांगता के आधार पर भेदभाव में उचित समायोजन से इनकार शामिल है; किसी कक्षा को उपलब्ध भूतल के कमरे में ले जाना बिना अनुचित बोझ का साधारण समायोजन है।"},
  {"id":"cdp-child-development-1142","question":"Which teacher belief best supports inclusive education?","options":["I should treat every child exactly alike so that no child ever feels singled out","Every child can learn; if a child is not learning, I should change how I teach","Children with special needs should get easier work so that they never feel failure","A child with a disability should first catch up in a special class, then join mine"],"answer":1,"explanation":"Inclusion locates the barrier in teaching and the environment, so the teacher adapts her practice. Treating everyone exactly alike sounds fair but ignores that equity needs different supports, and easier work or a ‘catch up first’ rule lowers expectations or delays inclusion.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कौन-सी शिक्षक-मान्यता समावेशी शिक्षा का सबसे अच्छा समर्थन करती है?","optionsHi":["मुझे हर बच्चे के साथ बिल्कुल एक-सा व्यवहार करना चाहिए ताकि कोई बच्चा कभी अलग न महसूस करे","हर बच्चा सीख सकता है; यदि कोई बच्चा नहीं सीख रहा, तो मुझे अपना पढ़ाने का तरीका बदलना चाहिए","विशेष आवश्यकता वाले बच्चों को आसान कार्य मिलना चाहिए ताकि वे कभी विफलता न अनुभव करें","विकलांग बच्चे को पहले विशेष कक्षा में बराबरी कर लेनी चाहिए, फिर मेरी कक्षा में आना चाहिए"],"explanationHi":"समावेशन बाधा को शिक्षण और परिवेश में देखता है, इसलिए शिक्षक अपने अभ्यास को ढालता है। सबके साथ बिल्कुल एक-सा व्यवहार निष्पक्ष लगता है पर यह अनदेखा करता है कि समता के लिए भिन्न सहायता चाहिए, और आसान कार्य या ‘पहले बराबरी करो’ का नियम अपेक्षाएँ घटाता है या समावेशन टालता है।"},
  {"id":"cdp-child-development-1143","question":"In a Class 4 PE period, Tanya, who has dyspraxia, cannot manage skipping with a rope and has begun avoiding PE altogether. What is the most appropriate response?","options":["Excusing her permanently from PE so that she is spared repeated failure in front of others","Making her practise skipping in front of the class until she gets it, to build confidence","Giving her a lower PE grade without changing anything, so that assessment stays the same for all","Breaking the skill into small steps, offering adapted equipment and valuing her participation"],"answer":3,"explanation":"Dyspraxia affects motor planning, so skills need to be broken down and adapted; inclusion in PE means participation with support, not exemption or public failure.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 4 के शारीरिक शिक्षा कालांश में तान्या, जिसे डिस्प्रैक्सिया है, रस्सी कूदना नहीं कर पाती और शारीरिक शिक्षा से पूरी तरह बचने लगी है। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["उसे शारीरिक शिक्षा से स्थायी छूट देना ताकि दूसरों के सामने बार-बार असफलता से बचे","उसे कक्षा के सामने तब तक कूदने का अभ्यास कराना जब तक वह सीख न जाए, ताकि आत्मविश्वास बने","कुछ बदले बिना उसे शारीरिक शिक्षा में कम ग्रेड देना, ताकि आकलन सबके लिए एक-सा रहे","कौशल को छोटे चरणों में बाँटना, अनुकूलित उपकरण देना और उसकी भागीदारी को महत्त्व देना"],"explanationHi":"डिस्प्रैक्सिया गामक नियोजन को प्रभावित करता है, इसलिए कौशलों को बाँटकर अनुकूलित करना चाहिए; शारीरिक शिक्षा में समावेशन का अर्थ सहायता के साथ भागीदारी है, छूट या सार्वजनिक असफलता नहीं।"},
  {"id":"cdp-child-development-1144","question":"Assertion (A): In peer tutoring, the student who tutors also gains in understanding. Reason (R): Explaining a concept to someone else requires the tutor to organise and clarify his own knowledge.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Teaching others forces the tutor to restructure and clarify ideas, which deepens his own learning; this is why peer tutoring benefits both partners in an inclusive class.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"अभिकथन (A): सहपाठी शिक्षण में पढ़ाने वाले विद्यार्थी की भी समझ बढ़ती है। कारण (R): किसी और को अवधारणा समझाने में शिक्षक-विद्यार्थी को अपने ज्ञान को व्यवस्थित और स्पष्ट करना पड़ता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दूसरों को सिखाना सिखाने वाले को विचारों को पुनर्गठित और स्पष्ट करने को बाध्य करता है, जिससे उसका अपना अधिगम गहरा होता है; इसीलिए समावेशी कक्षा में सहपाठी शिक्षण दोनों साझेदारों को लाभ पहुँचाता है।"},
  {"id":"cdp-child-development-1145","question":"How many of these statements are correct? I. Spearman used factor analysis of test scores to argue for a general factor. II. Thurstone proposed seven primary mental abilities. III. In Guilford’s model, divergent production is one of the operations. IV. Raymond Cattell proposed the g and s factors.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The g and s factors belong to Spearman; Cattell proposed fluid and crystallised intelligence, so IV is false.","difficulty":"hard","source":"CTET · DSSSB TGT","questionHi":"इनमें से कितने कथन सही हैं? I. स्पीयरमैन ने परीक्षण-अंकों के कारक विश्लेषण से सामान्य कारक का तर्क दिया। II. थर्स्टन ने सात प्राथमिक मानसिक योग्यताएँ प्रस्तावित कीं। III. गिलफोर्ड के मॉडल में अपसारी उत्पादन संक्रियाओं में से एक है। IV. रेमंड कैटेल ने g और s कारक प्रस्तावित किए।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"I, II और III सही हैं। g और s कारक स्पीयरमैन के हैं; कैटेल ने तरल और मूर्त (क्रिस्टलीकृत) बुद्धि प्रस्तावित की, इसलिए IV असत्य है।"},
  {"id":"cdp-child-development-1146","question":"A boy aged exactly 10 years has a mental age of 13 years 6 months. What is his ratio IQ?","options":["74","130","135","123"],"answer":2,"explanation":"Ratio IQ = MA ÷ CA × 100 = 13.5 ÷ 10 × 100 = 135. Ignoring the six months gives 130, and inverting the ratio gives about 74.","difficulty":"moderate","source":"CTET Paper 2 · State TET","questionHi":"ठीक 10 वर्ष की आयु के एक लड़के की मानसिक आयु 13 वर्ष 6 माह है। उसका अनुपात IQ क्या है?","optionsHi":["74","130","135","123"],"explanationHi":"अनुपात IQ = MA ÷ CA × 100 = 13.5 ÷ 10 × 100 = 135। छह माह को छोड़ देने पर 130 मिलता है, और अनुपात को उलट देने पर लगभग 74।"},
  {"id":"cdp-child-development-1147","question":"A girl aged 7 years 6 months has a ratio IQ of 120. What is her mental age?","options":["6 years 3 months","9 years","9 years 6 months","8 years 8 months"],"answer":1,"explanation":"MA = IQ × CA ÷ 100 = 1.2 × 7.5 = 9 years. Dividing instead of multiplying gives 7.5 ÷ 1.2 = 6.25 years (6 years 3 months).","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"7 वर्ष 6 माह की एक बालिका का अनुपात IQ 120 है। उसकी मानसिक आयु क्या है?","optionsHi":["6 वर्ष 3 माह","9 वर्ष","9 वर्ष 6 माह","8 वर्ष 8 माह"],"explanationHi":"MA = IQ × CA ÷ 100 = 1.2 × 7.5 = 9 वर्ष। गुणा करने के बजाय भाग देने पर 7.5 ÷ 1.2 = 6.25 वर्ष (6 वर्ष 3 माह) आता है।"},
  {"id":"cdp-child-development-1148","question":"Which popular claim about emotional intelligence is NOT supported by research evidence?","options":["Emotional skills such as recognising and naming feelings can be taught to children in school","EI matters far more than IQ for success in every field, by a fixed margin such as ‘twice as much’","The ability to manage emotions is linked with better relationships and well-being","Emotional intelligence includes perceiving emotions accurately in other people’s faces and voices"],"answer":1,"explanation":"Sweeping claims that EI outweighs IQ by some fixed amount come from popular writing, not research; studies find EI adds modest prediction for some outcomes, while the other statements are well supported.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"भावनात्मक बुद्धि के बारे में कौन-सा लोकप्रिय दावा शोध-प्रमाणों द्वारा समर्थित नहीं है?","optionsHi":["भावनाओं को पहचानने और नाम देने जैसे भावनात्मक कौशल विद्यालय में बच्चों को सिखाए जा सकते हैं","सफलता के लिए हर क्षेत्र में EI, IQ से कहीं अधिक महत्त्वपूर्ण है, किसी निश्चित अनुपात में जैसे ‘दोगुना’","भावनाओं को सँभालने की क्षमता बेहतर संबंधों और कल्याण से जुड़ी है","भावनात्मक बुद्धि में दूसरे लोगों के चेहरों और आवाज़ों में भावनाओं को सटीक रूप से भाँपना शामिल है"],"explanationHi":"EI के IQ से किसी निश्चित मात्रा में अधिक होने के व्यापक दावे लोकप्रिय लेखन से आते हैं, शोध से नहीं; अध्ययन बताते हैं कि EI कुछ परिणामों के लिए मामूली पूर्वानुमान जोड़ती है, जबकि अन्य कथन भली-भाँति समर्थित हैं।"},
  {"id":"cdp-child-development-1149","question":"Kabir, a Class 10 student, often asks questions like ‘Why are we born?’ and ‘What happens after death?’ and enjoys discussing the meaning of life. Gardner discussed such ability as possible ‘existential intelligence’. What is its status in his theory?","options":["It was one of the original seven intelligences he proposed in 1983","It replaced intrapersonal intelligence in later versions of the theory","Gardner rejected the idea completely and never discussed it in any of his writing","Gardner treats it as a strong candidate but has not fully added it to his list"],"answer":3,"explanation":"Gardner added naturalist intelligence and discussed existential intelligence as a candidate, famously speaking of ‘eight and a half’ intelligences, without fully confirming it.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"कक्षा 10 का विद्यार्थी कबीर प्रायः ‘हम क्यों जन्म लेते हैं?’ और ‘मृत्यु के बाद क्या होता है?’ जैसे प्रश्न पूछता है और जीवन के अर्थ पर चर्चा करना पसंद करता है। गार्डनर ने ऐसी क्षमता को संभावित ‘अस्तित्वपरक बुद्धि’ के रूप में चर्चित किया। उनके सिद्धांत में इसकी स्थिति क्या है?","optionsHi":["यह उन मूल सात बुद्धियों में से एक थी जो उन्होंने 1983 में प्रस्तावित कीं","सिद्धांत के बाद के संस्करणों में इसने अंतर्वैयक्तिक बुद्धि का स्थान ले लिया","गार्डनर ने इस विचार को पूरी तरह अस्वीकार कर दिया और अपने किसी लेखन में कभी इसकी चर्चा नहीं की","गार्डनर इसे सशक्त उम्मीदवार मानते हैं, परंतु उन्होंने इसे अपनी सूची में पूरी तरह नहीं जोड़ा है"],"explanationHi":"गार्डनर ने प्रकृतिवादी बुद्धि जोड़ी और अस्तित्वपरक बुद्धि को उम्मीदवार के रूप में चर्चित किया, ‘साढ़े आठ’ बुद्धियों की प्रसिद्ध बात कही, पर उसे पूरी तरह पुष्ट नहीं किया।"},
  {"id":"cdp-child-development-1150","question":"Assertion (A): Both Sternberg’s and Gardner’s theories go beyond the traditional view of intelligence as what IQ tests measure. Reason (R): Both theories hold that intelligence consists of exactly three abilities.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Both theories broaden the idea of intelligence beyond IQ, but only Sternberg proposes three aspects (analytical, creative, practical); Gardner proposes eight or more intelligences.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"अभिकथन (A): स्टर्नबर्ग और गार्डनर दोनों के सिद्धांत बुद्धि के उस परंपरागत दृष्टिकोण से आगे जाते हैं जिसमें बुद्धि वही है जिसे IQ परीक्षण मापते हैं। कारण (R): दोनों सिद्धांत मानते हैं कि बुद्धि ठीक तीन योग्यताओं से बनी है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सिद्धांत बुद्धि की धारणा को IQ से आगे बढ़ाते हैं, पर केवल स्टर्नबर्ग तीन पहलू (विश्लेषणात्मक, सृजनात्मक, व्यावहारिक) प्रस्तावित करते हैं; गार्डनर आठ या अधिक बुद्धियाँ प्रस्तावित करते हैं।"},
  {"id":"cdp-child-development-1151","question":"A test asks students to find one word that links ‘cottage’, ‘Swiss’ and ‘cake’ (answer: cheese). The test is based on Sarnoff Mednick’s view that creativity involves:","options":["Combining remote associative elements into new, useful connections","Remembering lists of words by rote","Choosing the one correct option from a set of four","Repeating the teacher’s explanation in one’s own words without adding anything"],"answer":0,"explanation":"Mednick’s associative theory and his Remote Associates Test treat creativity as the ability to link distant ideas; creative people have flatter association hierarchies and reach remote associations more readily.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"एक परीक्षण विद्यार्थियों से एक ऐसा शब्द खोजने को कहता है जो ‘cottage’, ‘Swiss’ और ‘cake’ को जोड़े (उत्तर: cheese)। यह परीक्षण सारनॉफ़ मेडनिक के इस मत पर आधारित है कि सृजनात्मकता में शामिल है:","optionsHi":["दूरस्थ साहचर्य तत्त्वों को नए, उपयोगी संबंधों में जोड़ना","शब्दों की सूचियाँ रटकर याद रखना","चार में से एक सही विकल्प चुनना","बिना कुछ जोड़े शिक्षक की व्याख्या को अपने शब्दों में दोहराना"],"explanationHi":"मेडनिक का साहचर्य सिद्धांत और उनका दूरस्थ साहचर्य परीक्षण सृजनात्मकता को दूर के विचारों को जोड़ने की क्षमता मानते हैं; सृजनशील लोगों की साहचर्य-श्रेणियाँ अधिक समतल होती हैं और वे दूरस्थ साहचर्यों तक अधिक सहजता से पहुँचते हैं।"},
  {"id":"cdp-child-development-1152","question":"E. Paul Torrance offered principles for teachers to encourage creative thinking. Which of the following runs AGAINST them?","options":["Treating unusual questions with respect","Showing children that their ideas have value, even unusual ones","Allowing periods of practice and exploration without the threat of evaluation","Evaluating every attempt immediately so children learn the right answer fast"],"answer":3,"explanation":"Torrance urged respect for unusual questions and imaginative ideas and time to explore without constant evaluation; immediate judgement of every attempt discourages risk-taking.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"ई. पॉल टॉरेंस ने सृजनात्मक चिंतन को प्रोत्साहित करने के लिए शिक्षकों हेतु सिद्धांत दिए। निम्नलिखित में से कौन-सा इनके विरुद्ध है?","optionsHi":["असामान्य प्रश्नों का सम्मान करना","बच्चों को दिखाना कि उनके विचारों का मूल्य है, चाहे वे असामान्य ही क्यों न हों","मूल्यांकन के भय के बिना अभ्यास और अन्वेषण के समय की अनुमति देना","हर प्रयास का तुरंत मूल्यांकन करना ताकि बच्चे सही उत्तर जल्दी सीखें"],"explanationHi":"टॉरेंस ने असामान्य प्रश्नों और कल्पनाशील विचारों के सम्मान तथा निरंतर मूल्यांकन के बिना अन्वेषण के समय पर बल दिया; हर प्रयास का तुरंत निर्णय जोखिम लेने को हतोत्साहित करता है।"},
  {"id":"cdp-child-development-1153","question":"A district selects children for its talent programme only through teacher nominations. Very few girls and rural children are selected. The most likely explanation is that:","options":["Girls and rural children are less often gifted, so the low numbers simply reflect real ability","Teacher nominations alone can reflect stereotypes and miss talent that doesn’t fit the usual image","Teachers are accurate judges of talent, since they observe their children closely every day in class","Rural children and their families rarely want to join such programmes held away from home"],"answer":1,"explanation":"Giftedness occurs in all groups; under-representation signals biased identification. Multiple measures, non-verbal tasks and local norms help find overlooked talent.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"एक जिला अपने प्रतिभा-कार्यक्रम के लिए बच्चों का चयन केवल शिक्षकों के नामांकन से करता है। बहुत कम लड़कियाँ और ग्रामीण बच्चे चुने जाते हैं। सबसे संभावित व्याख्या यह है कि:","optionsHi":["लड़कियाँ और ग्रामीण बच्चे कम प्रतिभाशाली होते हैं, इसलिए कम संख्या केवल वास्तविक क्षमता को दर्शाती है","केवल शिक्षकों के नामांकन रूढ़िबद्ध धारणाओं को दर्शा सकते हैं और उस प्रतिभा को चूक सकते हैं जो सामान्य छवि में नहीं बैठती","शिक्षक प्रतिभा के सटीक निर्णायक होते हैं, क्योंकि वे कक्षा में रोज़ अपने बच्चों को निकटता से देखते हैं","ग्रामीण बच्चे और उनके परिवार घर से दूर होने वाले ऐसे कार्यक्रमों में शायद ही शामिल होना चाहते हैं"],"explanationHi":"प्रतिभाशालिता सभी समूहों में होती है; कम प्रतिनिधित्व पक्षपातपूर्ण पहचान का संकेत है। अनेक मापक, अशाब्दिक कार्य और स्थानीय मानक अनदेखी प्रतिभा को खोजने में सहायक हैं।"},
  {"id":"cdp-child-development-1154","question":"Eight-year-old Advait reads books meant for Class 8 and discusses planets like an adult, but he cries and throws the board when he loses a game of ludo. The best interpretation is that:","options":["His intellectual ability must be overrated, since truly gifted children are always emotionally mature","He is being deliberately difficult to get attention and should be punished to stop the habit","His development is asynchronous: his intellect is ahead of his emotional development, which needs support","His advanced reading level is itself caused by emotional problems that make him withdraw into books all day"],"answer":2,"explanation":"Gifted children often show asynchronous development, with cognitive skills far ahead of emotional and social skills; adults should not expect adult-like emotional control just because of advanced intellect.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"आठ वर्षीय अद्वैत कक्षा 8 की पुस्तकें पढ़ता है और वयस्क की तरह ग्रहों पर चर्चा करता है, पर लूडो हारने पर रोता है और बोर्ड फेंक देता है। सर्वोत्तम व्याख्या यह है कि:","optionsHi":["उसकी बौद्धिक क्षमता बढ़ा-चढ़ाकर आँकी गई होगी, क्योंकि वास्तव में प्रतिभाशाली बच्चे सदैव भावनात्मक रूप से परिपक्व होते हैं","वह ध्यान पाने के लिए जानबूझकर परेशान कर रहा है और आदत छुड़ाने के लिए उसे दंडित करना चाहिए","उसका विकास असमकालिक है: उसकी बुद्धि उसके भावनात्मक विकास से आगे है, जिसे सहायता चाहिए","उसका उन्नत पठन-स्तर स्वयं भावनात्मक समस्याओं के कारण है, जो उसे दिन भर पुस्तकों में छिपने को बाध्य करती हैं"],"explanationHi":"प्रतिभाशाली बच्चों में प्रायः असमकालिक विकास दिखता है, जिसमें संज्ञानात्मक कौशल भावनात्मक और सामाजिक कौशलों से बहुत आगे होते हैं; उन्नत बुद्धि के कारण वयस्कों जैसे भावनात्मक नियंत्रण की अपेक्षा नहीं करनी चाहिए।"},
  {"id":"cdp-child-development-1155","question":"Gifted Class 6 student Mehr refuses to begin a drawing or an essay unless she is sure it will be perfect, and tears up work with small mistakes. The most helpful teacher response is to:","options":["Praise only her perfect final products, so that she sees her high standards are rewarded","Value effort, drafts and the learning process, and show that mistakes are a normal part of learning","Exempt her from any task she finds difficult, so that she does not become anxious","Tell her that gifted children should never make mistakes, so she must check her work more carefully"],"answer":1,"explanation":"Unhealthy perfectionism is common in gifted children; stressing process, revision and learning from errors reduces fear of failure, while praising only perfect results feeds it.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"कक्षा 6 की प्रतिभाशाली विद्यार्थी मेहर कोई चित्र या निबंध तब तक शुरू करने से मना करती है जब तक उसे विश्वास न हो कि वह परिपूर्ण होगा, और छोटी गलतियों वाला काम फाड़ देती है। शिक्षक की सबसे सहायक प्रतिक्रिया है:","optionsHi":["केवल उसके परिपूर्ण अंतिम उत्पादों की प्रशंसा करना, ताकि वह देखे कि उसके ऊँचे मानकों को पुरस्कार मिलता है","प्रयास, मसौदों और अधिगम-प्रक्रिया को महत्त्व देना, और दिखाना कि गलतियाँ अधिगम का सामान्य भाग हैं","उसे हर उस कार्य से छूट देना जो उसे कठिन लगे, ताकि वह चिंतित न हो","उससे कहना कि प्रतिभाशाली बच्चों को कभी गलती नहीं करनी चाहिए, इसलिए उसे अपना काम और ध्यान से जाँचना चाहिए"],"explanationHi":"अस्वस्थ पूर्णतावाद प्रतिभाशाली बच्चों में आम है; प्रक्रिया, संशोधन और त्रुटियों से सीखने पर बल असफलता का भय घटाता है, जबकि केवल परिपूर्ण परिणामों की प्रशंसा उसे पोषित करती है।"},
  {"id":"cdp-child-development-1156","question":"The ‘reaction range’ concept describes heredity and environment as working together in which way?","options":["Heredity sets a range of possible outcomes; environment influences where in that range one ends up","Environment sets the range of possible outcomes, and heredity then decides the exact point reached","Heredity alone fixes the exact level of a trait, and environment only affects how it is shown","Heredity and environment each contribute exactly 50 per cent to every trait in every individual"],"answer":0,"explanation":"A genotype allows a range of outcomes; enriched or deprived environments push development towards the upper or lower part of that range, so the same genes can produce different results.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"‘प्रतिक्रिया-परास’ (रिएक्शन रेंज) की अवधारणा आनुवंशिकता और पर्यावरण के साथ मिलकर काम करने को किस प्रकार बताती है?","optionsHi":["आनुवंशिकता संभावित परिणामों की एक परास निर्धारित करती है; पर्यावरण प्रभावित करता है कि व्यक्ति उस परास में कहाँ पहुँचता है","पर्यावरण संभावित परिणामों की परास निर्धारित करता है, और आनुवंशिकता फिर तय करती है कि ठीक कौन-सा बिंदु प्राप्त होगा","आनुवंशिकता अकेले किसी लक्षण का ठीक स्तर तय करती है, और पर्यावरण केवल प्रभावित करता है कि वह कैसे दिखता है","आनुवंशिकता और पर्यावरण हर व्यक्ति में हर लक्षण में ठीक 50 प्रतिशत योगदान देते हैं"],"explanationHi":"जीनोटाइप परिणामों की एक परास की अनुमति देता है; समृद्ध या वंचित परिवेश विकास को उस परास के ऊपरी या निचले भाग की ओर धकेलते हैं, इसलिए वही जीन भिन्न परिणाम दे सकते हैं।"},
  {"id":"cdp-child-development-1157","question":"Which pair of findings together shows that BOTH heredity and environment influence measured intelligence?","options":["Identical twins reared apart are no more alike than strangers; adopted children never change in their IQ","Siblings are more alike in IQ than strangers are; brothers are on average taller than their sisters","Identical twins reared apart are still quite similar in IQ; adoption into enriched homes raises scores","IQ scores never change over the lifespan, and all children in a family have exactly the same IQ"],"answer":2,"explanation":"Similarity of identical twins reared apart points to genetic influence, while IQ gains among children adopted into enriched homes point to environmental influence.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"निष्कर्षों का कौन-सा जोड़ा मिलकर दिखाता है कि मापी गई बुद्धि को आनुवंशिकता और पर्यावरण दोनों प्रभावित करते हैं?","optionsHi":["अलग-अलग पाले गए समरूप जुड़वाँ अजनबियों से अधिक समान नहीं होते; गोद लिए गए बच्चों का IQ कभी नहीं बदलता","भाई-बहन अजनबियों से IQ में अधिक समान होते हैं; भाई औसतन अपनी बहनों से लंबे होते हैं","अलग-अलग पाले गए समरूप जुड़वाँ फिर भी IQ में काफ़ी समान होते हैं; समृद्ध घरों में गोद लिए जाने से अंक बढ़ते हैं","IQ अंक जीवनकाल में कभी नहीं बदलते, और परिवार के सभी बच्चों का IQ बिल्कुल समान होता है"],"explanationHi":"अलग पाले गए समरूप जुड़वाँ की समानता आनुवंशिक प्रभाव की ओर संकेत करती है, जबकि समृद्ध घरों में गोद लिए बच्चों के IQ में वृद्धि पर्यावरणीय प्रभाव की ओर।"},
  {"id":"cdp-child-development-1158","question":"A survey finds that on average, children from higher-income families in a city score higher on a reading test than children from lower-income families. Which inference IS justified?","options":["Any low-income child in the class will score lower than any high-income child on this same reading test","The difference must be genetic, since all the children took exactly the same reading test under the same conditions","Income itself makes children more intelligent, so raising family income will raise every child’s score","Income-linked circumstances such as books, nutrition and schooling may contribute to the average difference"],"answer":3,"explanation":"Group averages say nothing certain about individuals, and a correlation does not show genetic cause; differences in resources and opportunities are a plausible explanation that further study can test.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक सर्वेक्षण पाता है कि औसतन, किसी शहर के उच्च-आय वाले परिवारों के बच्चे निम्न-आय वाले परिवारों के बच्चों से पठन-परीक्षण में अधिक अंक पाते हैं। कौन-सा निष्कर्ष उचित है?","optionsHi":["कक्षा का कोई भी निम्न-आय वाला बच्चा इसी पठन-परीक्षण में किसी भी उच्च-आय वाले बच्चे से कम अंक पाएगा","अंतर आनुवंशिक ही होगा, क्योंकि सभी बच्चों ने समान परिस्थितियों में ठीक वही पठन-परीक्षण दिया","आय स्वयं बच्चों को अधिक बुद्धिमान बनाती है, इसलिए पारिवारिक आय बढ़ाने से हर बच्चे के अंक बढ़ेंगे","पुस्तकें, पोषण और विद्यालयी शिक्षा जैसी आय-संबद्ध परिस्थितियाँ औसत अंतर में योगदान दे सकती हैं"],"explanationHi":"समूह औसत व्यक्तियों के बारे में निश्चित कुछ नहीं कहते, और सहसंबंध आनुवंशिक कारण सिद्ध नहीं करता; संसाधनों और अवसरों में अंतर एक संभावित व्याख्या है जिसे आगे के अध्ययन से परखा जा सकता है।"},
  {"id":"cdp-child-development-1159","question":"Cross-cultural research on how communities define ‘intelligence’ shows that:","options":["All cultures define intelligence in exactly the same way, as speed in solving abstract puzzles and problems","Only Western cultures have a clear concept of intelligence; others think mainly of character","Cultures that value social skills have no concept of reasoning or problem-solving ability at all","Many communities count social qualities such as responsibility, cooperation and wisdom as intelligence"],"answer":3,"explanation":"Studies in Africa and Asia, for example, find that ideas of intelligence often include social responsibility and getting along with others, not just quick abstract reasoning, which is why tests from one culture may not fit another.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"समुदाय ‘बुद्धि’ को कैसे परिभाषित करते हैं, इस पर अंतर-सांस्कृतिक शोध दर्शाता है कि:","optionsHi":["सभी संस्कृतियाँ बुद्धि को बिल्कुल एक ही तरह परिभाषित करती हैं, अमूर्त पहेलियों और समस्याओं को हल करने की गति के रूप में","केवल पश्चिमी संस्कृतियों में बुद्धि की स्पष्ट अवधारणा है; अन्य मुख्यतः चरित्र के बारे में सोचती हैं","जो संस्कृतियाँ सामाजिक कौशलों को महत्त्व देती हैं उनमें तर्क या समस्या-समाधान क्षमता की कोई अवधारणा ही नहीं होती","अनेक समुदाय उत्तरदायित्व, सहयोग और विवेक जैसे सामाजिक गुणों को बुद्धि मानते हैं"],"explanationHi":"उदाहरण के लिए अफ़्रीका और एशिया में हुए अध्ययन पाते हैं कि बुद्धि की धारणा में प्रायः केवल तीव्र अमूर्त तर्क नहीं, बल्कि सामाजिक उत्तरदायित्व और दूसरों के साथ निभाना भी शामिल होता है; इसीलिए एक संस्कृति के परीक्षण दूसरी में उपयुक्त नहीं हो सकते।"},
  {"id":"cdp-child-development-1160","question":"A school builds ramps, keeps a lift working, places a wheelchair user’s class on the ground floor and adapts its PE activities, so that Arnav, who uses a wheelchair, takes part fully. This approach reflects:","options":["The medical model, which treats disability as a problem located within the individual child","The social model, which sees disability as created largely by barriers in the environment","The charity model, which sees disabled children mainly as objects of pity and donation","The deficit model, which seeks only to correct the child rather than change the school"],"answer":1,"explanation":"The social model holds that people are disabled mainly by inaccessible environments and attitudes, so removing barriers enables participation; this view also underlies inclusive education.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक विद्यालय रैंप बनाता है, लिफ़्ट चालू रखता है, व्हीलचेयर-प्रयोगकर्ता की कक्षा को भूतल पर रखता है और अपनी शारीरिक शिक्षा गतिविधियों को ढालता है, ताकि व्हीलचेयर का उपयोग करने वाला अर्णव पूरी तरह भाग ले सके। यह दृष्टिकोण दर्शाता है:","optionsHi":["चिकित्सीय प्रतिरूप, जो विकलांगता को व्यक्तिगत बच्चे के भीतर की समस्या मानता है","सामाजिक प्रतिरूप, जो विकलांगता को काफ़ी हद तक परिवेश की बाधाओं से निर्मित मानता है","दान-प्रतिरूप, जो विकलांग बच्चों को मुख्यतः दया और दान का पात्र मानता है","कमी-प्रतिरूप, जो विद्यालय को बदलने के बजाय केवल बच्चे को सुधारना चाहता है"],"explanationHi":"सामाजिक प्रतिरूप मानता है कि लोग मुख्यतः दुर्गम परिवेश और दृष्टिकोणों से विकलांग होते हैं, इसलिए बाधाएँ हटाने से भागीदारी संभव होती है; यही दृष्टि समावेशी शिक्षा का आधार भी है।"},
  {"id":"cdp-child-development-1161","question":"Two groups of students obtain different average scores on an aptitude test. Which statement is most accurate from a measurement point of view?","options":["Unequal averages alone do not prove bias; bias means the test measures or predicts differently for groups","The difference proves that the lower-scoring group has less of the ability being measured","The difference proves that the test is biased against the lower-scoring group in some way","Tests can never be biased once they have been carefully standardised on a large, representative national sample"],"answer":0,"explanation":"Mean differences may reflect real differences in opportunity or skill; test bias concerns whether the items and scores mean the same thing for different groups. Standardisation alone does not guarantee fairness.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"विद्यार्थियों के दो समूह अभिक्षमता परीक्षण पर भिन्न औसत अंक पाते हैं। मापन की दृष्टि से कौन-सा कथन सबसे सटीक है?","optionsHi":["केवल असमान औसत पक्षपात सिद्ध नहीं करते; पक्षपात का अर्थ है कि परीक्षण समूहों के लिए भिन्न रूप से मापता या पूर्वानुमान देता है","अंतर सिद्ध करता है कि कम अंक पाने वाले समूह में मापी जा रही योग्यता कम है","अंतर सिद्ध करता है कि परीक्षण किसी तरह कम अंक पाने वाले समूह के विरुद्ध पक्षपाती है","बड़े, प्रतिनिधि राष्ट्रीय प्रतिदर्श पर सावधानी से मानकीकृत होने के बाद परीक्षण कभी पक्षपाती नहीं हो सकते"],"explanationHi":"औसत में अंतर अवसर या कौशल के वास्तविक अंतर को दर्शा सकते हैं; परीक्षण-पक्षपात का संबंध इससे है कि प्रश्नों और अंकों का अर्थ भिन्न समूहों के लिए समान है या नहीं। केवल मानकीकरण निष्पक्षता की गारंटी नहीं देता।"},
  {"id":"cdp-child-development-1162","question":"The National Education Policy 2020 proposes changes to board examinations. Which of the following reflects its stated direction?","options":["Board exams that test core capacities and competencies rather than coaching and memorisation","Adding board exams at the end of every class from Class 1, so that learning is tracked very closely","Making board exams more difficult so that only the best-prepared students pass them","Abolishing all assessment until Class 12 so that children learn without any pressure"],"answer":0,"explanation":"NEP 2020 aims to make board exams ‘easier’ in the sense of testing core concepts and competencies, reducing the need for coaching and rote learning.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"राष्ट्रीय शिक्षा नीति 2020 बोर्ड परीक्षाओं में परिवर्तन प्रस्तावित करती है। निम्नलिखित में से कौन-सा उसकी घोषित दिशा को दर्शाता है?","optionsHi":["बोर्ड परीक्षाएँ जो कोचिंग और रटंत के बजाय मूल क्षमताओं और दक्षताओं की जाँच करें","कक्षा 1 से हर कक्षा के अंत में बोर्ड परीक्षाएँ जोड़ना, ताकि अधिगम पर बहुत निकट से नज़र रखी जाए","बोर्ड परीक्षाओं को अधिक कठिन बनाना ताकि केवल सबसे अच्छी तैयारी वाले विद्यार्थी उत्तीर्ण हों","कक्षा 12 तक सारा आकलन समाप्त करना ताकि बच्चे बिना किसी दबाव के सीखें"],"explanationHi":"NEP 2020 का उद्देश्य बोर्ड परीक्षाओं को इस अर्थ में ‘आसान’ बनाना है कि वे मूल अवधारणाओं और दक्षताओं की जाँच करें, जिससे कोचिंग और रटंत अधिगम की आवश्यकता घटे।"},
  {"id":"cdp-child-development-1163","question":"Vygotsky argued that to study the relation between thought and speech, one must take a unit that keeps the properties of both. Which unit did he propose?","options":["The phoneme","The grammatical sentence","The conditioned reflex","Word meaning"],"answer":3,"explanation":"For Vygotsky, word meaning is at once a linguistic and an intellectual phenomenon (a generalisation), so it is the unit of verbal thought; meanings develop as children’s concepts develop.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"वाइगोत्स्की ने तर्क दिया कि चिंतन और भाषण के संबंध का अध्ययन करने के लिए ऐसी इकाई लेनी चाहिए जो दोनों के गुणों को बनाए रखे। उन्होंने कौन-सी इकाई प्रस्तावित की?","optionsHi":["स्वनिम","व्याकरणिक वाक्य","अनुबंधित प्रतिवर्त","शब्द का अर्थ"],"explanationHi":"वाइगोत्स्की के लिए शब्द का अर्थ एक साथ भाषाई और बौद्धिक परिघटना (एक सामान्यीकरण) है, इसलिए वह शाब्दिक चिंतन की इकाई है; अर्थ बच्चों की अवधारणाओं के विकास के साथ विकसित होते हैं।"},
  {"id":"cdp-child-development-1164","question":"‘The hunter shot the tiger’ and ‘The tiger was shot by the hunter’ look different but mean the same. In Chomsky’s early transformational grammar, they share the same:","options":["Deep structure, with different surface structures","Surface structure, with different deep structures","Phonology and morphology","Holophrase"],"answer":0,"explanation":"Chomsky distinguished the underlying deep structure (meaning relations) from the surface structure (actual word order); transformations such as the passive map one onto the other.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"‘शिकारी ने बाघ को मारा’ और ‘बाघ शिकारी द्वारा मारा गया’ देखने में भिन्न हैं पर अर्थ में समान हैं। चॉम्स्की के आरंभिक रूपांतरणात्मक व्याकरण में ये किसमें समान हैं?","optionsHi":["गहन संरचना में, भिन्न सतही संरचनाओं के साथ","सतही संरचना में, भिन्न गहन संरचनाओं के साथ","स्वनिमविज्ञान और रूपविज्ञान में","एकशब्द-वाक्य (होलोफ्रेज़)"],"explanationHi":"चॉम्स्की ने अंतर्निहित गहन संरचना (अर्थ-संबंध) को सतही संरचना (वास्तविक शब्द-क्रम) से अलग किया; कर्मवाच्य जैसे रूपांतरण एक को दूसरे में बदलते हैं।"},
  {"id":"cdp-child-development-1165","question":"Talking to her baby, a mother in Lucknow uses short sentences, a higher pitch, exaggerated intonation, many repetitions and frequent pauses for the baby’s turn. Interactionist theorists view such child-directed speech as:","options":["Harmful, because it gives the child an incorrect, babyish model of how adult language really works","Irrelevant, because grammar is entirely innate and simply unfolds whatever the input","Helpful, because it holds attention and makes language structure easier for the child to pick up","A form of punishment and reward that gradually shapes correct speech in the baby"],"answer":2,"explanation":"Interactionists argue that child-directed speech supports learning by holding attention, highlighting words and boundaries and inviting turn-taking, while not denying innate capacities.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"लखनऊ की एक माँ अपने शिशु से बात करते समय छोटे वाक्यों, ऊँचे स्वर, अतिरंजित उतार-चढ़ाव, अनेक दोहराव और शिशु की बारी के लिए बार-बार विराम का प्रयोग करती है। अंतःक्रियावादी सिद्धांतकार ऐसे शिशु-निर्देशित भाषण को किस रूप में देखते हैं?","optionsHi":["हानिकारक, क्योंकि वह बच्चे को वयस्क भाषा के वास्तविक रूप का गलत, बचकाना आदर्श देता है","अप्रासंगिक, क्योंकि व्याकरण पूरी तरह जन्मजात है और निवेश चाहे जो हो, स्वयं प्रकट होता है","सहायक, क्योंकि वह ध्यान बनाए रखता है और भाषा की संरचना को बच्चे के लिए पकड़ना आसान बनाता है","दंड और पुरस्कार का एक रूप जो धीरे-धीरे शिशु के सही भाषण को आकार देता है"],"explanationHi":"अंतःक्रियावादी तर्क देते हैं कि शिशु-निर्देशित भाषण ध्यान बनाए रखकर, शब्दों और सीमाओं को उभारकर और बारी-बारी से बोलने को आमंत्रित करके अधिगम में सहायक है, जबकि जन्मजात क्षमताओं को नकारे बिना।"},
  {"id":"cdp-child-development-1166","question":"A teacher says, ‘The Inuit have hundreds of words for snow, so they literally see snow differently from us; this proves language determines thought.’ Which evaluation is soundest?","options":["Correct: it is strong proof of linguistic determinism, since words decide what people are able to perceive","The snow-word count is exaggerated, and vocabulary mainly reflects what a group needs to talk about","Correct, because English speakers cannot tell different kinds of snow apart without the words","Incorrect, because language never influences thought in any way; perception is the same for all"],"answer":1,"explanation":"The snow example is widely overstated; skiers and others develop special terms when they need them. Vocabulary follows needs and can draw attention, but it does not prevent perceiving distinctions.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"एक शिक्षक कहता है, ‘इनुइट के पास बर्फ़ के लिए सैकड़ों शब्द हैं, इसलिए वे सचमुच हमसे अलग बर्फ़ देखते हैं; यह सिद्ध करता है कि भाषा चिंतन को निर्धारित करती है।’ कौन-सा मूल्यांकन सबसे ठोस है?","optionsHi":["सही: यह भाषाई निर्धारणवाद का सशक्त प्रमाण है, क्योंकि शब्द तय करते हैं कि लोग क्या देख सकते हैं","बर्फ़ के शब्दों की गिनती बढ़ा-चढ़ाकर बताई गई है, और शब्दावली मुख्यतः इस पर निर्भर करती है कि समूह को किस बारे में बात करनी होती है","सही, क्योंकि अंग्रेज़ी बोलने वाले शब्दों के बिना बर्फ़ के भिन्न प्रकारों में अंतर नहीं कर सकते","गलत, क्योंकि भाषा कभी किसी भी रूप में चिंतन को प्रभावित नहीं करती; प्रत्यक्षीकरण सबके लिए समान है"],"explanationHi":"बर्फ़ का उदाहरण व्यापक रूप से अतिरंजित है; स्कीइंग करने वाले और अन्य लोग आवश्यकता पड़ने पर विशेष शब्द विकसित कर लेते हैं। शब्दावली आवश्यकताओं का अनुसरण करती है और ध्यान आकर्षित कर सकती है, पर वह भेदों को देखने से रोकती नहीं।"},
  {"id":"cdp-child-development-1167","question":"A Class 6 science teacher notices that every scientist pictured in the textbook is a man. Which step best addresses the resulting gender message?","options":["Add stories and pictures of women scientists, including Indian ones, and invite women professionals","Tell students that science careers have mostly been for men, so the pictures are simply accurate","Ignore it, because pictures in a textbook do not really affect what children learn or come to believe","Remove all pictures of scientists from the classroom so that no one feels left out"],"answer":0,"explanation":"Counter-stereotypical role models broaden children’s ideas of who can do science; materials that show only men send a hidden message about who belongs in the field.","difficulty":"moderate","source":"CTET Paper 2 · State TET","questionHi":"कक्षा 6 का विज्ञान शिक्षक देखता है कि पाठ्यपुस्तक में चित्रित हर वैज्ञानिक पुरुष है। परिणामी लैंगिक संदेश को कौन-सा कदम सबसे अच्छी तरह संबोधित करता है?","optionsHi":["भारतीय सहित महिला वैज्ञानिकों की कहानियाँ और चित्र जोड़ना, और महिला पेशेवरों को आमंत्रित करना","विद्यार्थियों को बताना कि विज्ञान के करियर अधिकतर पुरुषों के लिए रहे हैं, इसलिए चित्र केवल सटीक हैं","अनदेखा करना, क्योंकि पाठ्यपुस्तक के चित्र बच्चों के सीखने या मानने को वास्तव में प्रभावित नहीं करते","कक्षा से वैज्ञानिकों के सभी चित्र हटा देना ताकि कोई छूटा हुआ महसूस न करे"],"explanationHi":"रूढ़ि-विरोधी आदर्श व्यक्ति बच्चों की इस धारणा को व्यापक बनाते हैं कि कौन विज्ञान कर सकता है; केवल पुरुषों को दिखाने वाली सामग्री इस क्षेत्र में किसकी जगह है, इस बारे में छिपा संदेश देती है।"},
  {"id":"cdp-child-development-1168","question":"After a popular cartoon showed its hero solving problems by hitting others, a Class 2 teacher notices several children copying the same blows and catchphrases in the playground. Bandura would explain this as learning from:","options":["A live model through direct reinforcement","Classical conditioning to the television","A symbolic model presented through media","Trial and error"],"answer":2,"explanation":"Bandura described live models, verbal instructions and symbolic models (characters in films, books, television). Children can acquire behaviour from symbolic models without being reinforced themselves.","difficulty":"moderate","source":"CTET Paper 1 · REET","questionHi":"एक लोकप्रिय कार्टून के बाद, जिसमें उसका नायक दूसरों को मारकर समस्याएँ सुलझाता है, कक्षा 2 की शिक्षिका देखती है कि कई बच्चे खेल के मैदान में वही प्रहार और तकिया-कलाम दोहरा रहे हैं। बैंडूरा इसे किससे सीखना कहेंगे?","optionsHi":["प्रत्यक्ष पुनर्बलन के साथ किसी जीवंत आदर्श से","टेलीविज़न के प्रति शास्त्रीय अनुबंधन से","मीडिया द्वारा प्रस्तुत किसी प्रतीकात्मक आदर्श से","प्रयास और त्रुटि से"],"explanationHi":"बैंडूरा ने जीवंत आदर्श, मौखिक निर्देश और प्रतीकात्मक आदर्श (फ़िल्मों, पुस्तकों, टेलीविज़न के पात्र) बताए। बच्चे स्वयं पुनर्बलित हुए बिना प्रतीकात्मक आदर्शों से व्यवहार अर्जित कर सकते हैं।"},
  {"id":"cdp-child-development-1169","question":"Children weak in subtraction were given the same 42-page workbook. One group was asked to aim for six pages each day; another was asked only to finish all 42 pages by the end of a week. Research by Bandura and Schunk predicts that the first group will show:","options":["Lower self-efficacy, because daily targets create pressure and constant fear of failure","No difference in outcome, since the total amount of work and time is exactly the same","Greater dependence on the teacher, who must check their pages every day","Greater self-efficacy and skill, because near goals give frequent evidence of progress"],"answer":3,"explanation":"Proximal (near) goals provide regular signals of mastery, which raise self-efficacy and motivation; distant goals give little feedback along the way.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"घटाने में कमज़ोर बच्चों को एक ही 42-पृष्ठ की कार्यपुस्तिका दी गई। एक समूह से कहा गया कि प्रतिदिन छह पृष्ठ का लक्ष्य रखे; दूसरे से केवल यह कि एक सप्ताह के अंत तक सभी 42 पृष्ठ पूरे करे। बैंडूरा और शंक का शोध पूर्वानुमान देता है कि पहला समूह दिखाएगा:","optionsHi":["कम आत्म-प्रभावकारिता, क्योंकि दैनिक लक्ष्य दबाव और असफलता का निरंतर भय पैदा करते हैं","परिणाम में कोई अंतर नहीं, क्योंकि कुल कार्य और समय ठीक वही है","शिक्षक पर अधिक निर्भरता, जिसे उनके पृष्ठ हर दिन जाँचने होंगे","अधिक आत्म-प्रभावकारिता और कौशल, क्योंकि निकट लक्ष्य प्रगति के बारे में बार-बार प्रमाण देते हैं"],"explanationHi":"निकटस्थ (पास के) लक्ष्य निपुणता के नियमित संकेत देते हैं, जो आत्म-प्रभावकारिता और अभिप्रेरणा बढ़ाते हैं; दूर के लक्ष्य रास्ते में बहुत कम प्रतिक्रिया देते हैं।"},
  {"id":"cdp-child-development-1170","question":"Which statement about verbal persuasion as a source of self-efficacy is most accurate?","options":["It works best when encouragement is realistic and followed by tasks the learner can succeed at","It is the strongest of the four sources Bandura described, stronger even than past success","It works even when the learner keeps failing, as long as the encouragement is repeated often","It has no effect on self-efficacy at all, since only one’s own direct experience counts for anything"],"answer":0,"explanation":"Persuasion can boost self-efficacy, but its effect is weaker than mastery experiences and collapses if not confirmed by success, so it should be realistic and linked to achievable tasks.","difficulty":"hard","source":"CTET · HTET","questionHi":"आत्म-प्रभावकारिता के स्रोत के रूप में मौखिक समझाइश (प्रेरणा-वचन) के बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["यह तब सबसे अच्छा काम करती है जब प्रोत्साहन यथार्थवादी हो और उसके बाद ऐसे कार्य हों जिनमें अधिगमकर्ता सफल हो सके","यह बैंडूरा द्वारा बताए चार स्रोतों में सबसे सशक्त है, पिछली सफलता से भी अधिक","यह तब भी काम करती है जब अधिगमकर्ता बार-बार असफल होता रहे, यदि प्रोत्साहन अक्सर दोहराया जाए","इसका आत्म-प्रभावकारिता पर कोई प्रभाव नहीं पड़ता, क्योंकि केवल अपने प्रत्यक्ष अनुभव का ही कुछ मूल्य है"],"explanationHi":"समझाइश आत्म-प्रभावकारिता बढ़ा सकती है, परंतु उसका प्रभाव निपुणता-अनुभवों से कमज़ोर है और सफलता से पुष्टि न होने पर ढह जाता है, इसलिए वह यथार्थवादी और साध्य कार्यों से जुड़ी होनी चाहिए।"},
  {"id":"cdp-child-development-1171","question":"In front of the whole class, a student caught copying is made to retake the test after school. Over the next weeks other students copy less, although they themselves were never punished. This is an example of:","options":["Vicarious reinforcement","Vicarious punishment","Negative reinforcement","Response facilitation"],"answer":1,"explanation":"Observing a model's behaviour being punished reduces the observer's tendency to perform it; this is vicarious punishment, the counterpart of vicarious reinforcement.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"पूरी कक्षा के सामने नकल करते पकड़े गए विद्यार्थी को स्कूल के बाद परीक्षा दोबारा देनी पड़ती है। अगले कुछ सप्ताहों में अन्य विद्यार्थी कम नकल करते हैं, यद्यपि उन्हें स्वयं कभी दंडित नहीं किया गया था। यह उदाहरण है:","optionsHi":["प्रतिनिधिक पुनर्बलन","प्रतिनिधिक दंड","नकारात्मक पुनर्बलन","अनुक्रिया सुगमीकरण"],"explanationHi":"किसी आदर्श के व्यवहार को दंडित होते देखना पर्यवेक्षक की उसे करने की प्रवृत्ति घटाता है; यह प्रतिनिधिक दंड है, प्रतिनिधिक पुनर्बलन का प्रतिरूप।"},
  {"id":"cdp-child-development-1172","question":"For a group of Class 8 students who are anxious about solving equations, which peer demonstration is most likely to raise their self-efficacy?","options":["A classmate who solves every problem instantly and without any error, to show it is easy","A recorded expert who explains the method very fast, covering every type of problem","A classmate who shows some confusion, explains how he copes, then solves them step by step","No model at all, since anxious students learn best by working through problems alone"],"answer":2,"explanation":"Schunk's work showed that coping models, who show difficulty and then overcome it, are often more effective than flawless mastery models for anxious or low-achieving learners, because they seem more similar.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"कक्षा 8 के उन विद्यार्थियों के समूह के लिए, जो समीकरण हल करने को लेकर चिंतित हैं, कौन-सा सहपाठी-प्रदर्शन उनकी आत्म-प्रभावकारिता बढ़ाने की सबसे अधिक संभावना रखता है?","optionsHi":["एक सहपाठी जो हर समस्या तुरंत और बिना किसी त्रुटि के हल करता है, यह दिखाने को कि यह आसान है","एक रिकॉर्ड किया हुआ विशेषज्ञ जो हर प्रकार की समस्या को कवर करते हुए विधि बहुत तेज़ी से समझाता है","एक सहपाठी जो कुछ उलझन दिखाता है, बताता है कि वह कैसे सँभालता है, फिर चरण-दर-चरण हल करता है","कोई आदर्श नहीं, क्योंकि चिंतित विद्यार्थी समस्याओं को अकेले हल करके सबसे अच्छा सीखते हैं"],"explanationHi":"शंक के कार्य ने दिखाया कि चिंतित या कम-उपलब्धि वाले अधिगमकर्ताओं के लिए सामना करने वाले आदर्श, जो कठिनाई दिखाकर उसे पार करते हैं, प्रायः दोषरहित निपुण आदर्शों से अधिक प्रभावी होते हैं, क्योंकि वे अधिक समान लगते हैं।"},
  {"id":"cdp-child-development-1173","question":"Just before a physics test, a teacher remarks to the class, ‘Girls usually find physics harder than boys.’ Girls who had done well in practice score lower on the test. Which explanation is most consistent with research?","options":["Girls lack real ability in physics, and the test simply revealed this more clearly than practice did","The test was harder than the practice papers, which explains everyone’s lower scores on it","Girls were not motivated, since the test did not count towards their final marks","Stereotype threat: a reminder of a negative group stereotype can raise anxiety and lower performance"],"answer":3,"explanation":"Stereotype threat studies show that activating a negative stereotype about one's group can impair performance on a challenging test by adding worry, independent of real ability.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"भौतिकी परीक्षा से ठीक पहले एक शिक्षक कक्षा से टिप्पणी करता है, ‘लड़कियों को भौतिकी प्रायः लड़कों से कठिन लगती है।’ जिन लड़कियों ने अभ्यास में अच्छा किया था, वे परीक्षा में कम अंक पाती हैं। शोध के अनुरूप कौन-सी व्याख्या सबसे संगत है?","optionsHi":["लड़कियों में भौतिकी की वास्तविक योग्यता नहीं है, और परीक्षा ने यह अभ्यास की तुलना में अधिक स्पष्ट कर दिया","परीक्षा अभ्यास-पत्रों से कठिन थी, जो सबके कम अंकों की व्याख्या करता है","लड़कियाँ अभिप्रेरित नहीं थीं, क्योंकि परीक्षा के अंक उनके अंतिम अंकों में नहीं गिने जाने थे","रूढ़िबद्ध धारणा का भय: किसी नकारात्मक समूह-रूढ़ि की याद चिंता बढ़ा सकती है और प्रदर्शन घटा सकती है"],"explanationHi":"रूढ़िबद्ध धारणा के भय संबंधी अध्ययन दिखाते हैं कि अपने समूह के बारे में किसी नकारात्मक रूढ़ि को सक्रिय करना चिंता जोड़कर चुनौतीपूर्ण परीक्षा में प्रदर्शन को बिगाड़ सकता है, वास्तविक योग्यता से स्वतंत्र रूप से।"},
  {"id":"cdp-child-development-1174","question":"A teacher poses a question, gives children a minute to think silently, then asks them to discuss with a partner before sharing with the class. This strategy mainly reflects:","options":["Social constructivism: understanding built through dialogue","Classical conditioning of answers to the teacher’s question","Programmed instruction through small, fixed steps","Rote learning through repetition with a partner"],"answer":0,"explanation":"Think–pair–share lets learners first form their own ideas and then refine them through talk with a peer, an application of the social construction of knowledge.","difficulty":"moderate","source":"CTET · REET","questionHi":"एक शिक्षक प्रश्न पूछता है, बच्चों को एक मिनट चुपचाप सोचने का समय देता है, फिर उनसे कक्षा में साझा करने से पहले साथी से चर्चा करने को कहता है। यह युक्ति मुख्यतः किसे दर्शाती है?","optionsHi":["सामाजिक रचनावाद: संवाद द्वारा निर्मित समझ","शिक्षक के प्रश्न के प्रति उत्तरों का शास्त्रीय अनुबंधन","छोटे, निश्चित चरणों द्वारा अभिक्रमित अनुदेशन","साथी के साथ दोहराव द्वारा रटंत अधिगम"],"explanationHi":"सोचो–जोड़ी बनाओ–साझा करो (थिंक–पेयर–शेयर) अधिगमकर्ताओं को पहले अपने विचार बनाने और फिर किसी साथी से बातचीत द्वारा उन्हें परिष्कृत करने देता है, जो ज्ञान के सामाजिक निर्माण का अनुप्रयोग है।"},
  {"id":"cdp-child-development-1175","question":"Which question by a Class 6 science teacher is most likely to encourage children to construct understanding?","options":["‘What is the boiling point of water, and in which unit is it measured?’","‘What would happen to the boiling point if we added salt, and how could we find out?’","‘Who discovered the thermometer, and in which year was it invented?’","‘Write the definition of evaporation from the textbook and learn it by heart for tomorrow’s test.’"],"answer":1,"explanation":"Open, investigative questions ask children to predict, reason and design ways to test ideas, which engages them in constructing knowledge rather than recalling facts.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 के विज्ञान शिक्षक का कौन-सा प्रश्न बच्चों को समझ का निर्माण करने के लिए सबसे अधिक प्रोत्साहित करने की संभावना रखता है?","optionsHi":["‘पानी का क्वथनांक क्या है और वह किस इकाई में मापा जाता है?’","‘यदि हम नमक मिला दें तो क्वथनांक का क्या होगा, और हम यह कैसे पता कर सकते हैं?’","‘थर्मामीटर की खोज किसने की, और वह किस वर्ष आविष्कृत हुआ?’","‘पाठ्यपुस्तक से वाष्पीकरण की परिभाषा लिखो और कल की परीक्षा के लिए उसे रट लो।’"],"explanationHi":"खुले, अन्वेषणात्मक प्रश्न बच्चों से अनुमान लगाने, तर्क करने और विचारों को परखने के तरीके बनाने को कहते हैं, जो उन्हें तथ्य याद करने के बजाय ज्ञान-निर्माण में संलग्न करता है।"},
  {"id":"cdp-child-development-1176","question":"Class 7 students in a Rajasthan village survey water use in their homes, design a model rooftop rainwater harvesting system, and present it to the panchayat. Which approach and principle does this best illustrate?","options":["Programmed learning, since the project work is broken into small sequential frames","Behaviourist drill, since survey and model skills are repeated until fluent","Project-based learning rooted in constructivism, linking knowledge to real problems","Formal discipline, since hard and lengthy work trains the faculties of the mind"],"answer":2,"explanation":"Project-based learning engages learners in authentic, extended investigations; they construct knowledge by applying ideas to a real community problem, as NCF 2005 recommends.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"राजस्थान के एक गाँव में कक्षा 7 के विद्यार्थी अपने घरों में जल-उपयोग का सर्वेक्षण करते हैं, छत पर वर्षा जल संचयन प्रणाली का मॉडल बनाते हैं और उसे पंचायत के सामने प्रस्तुत करते हैं। यह किस उपागम और सिद्धांत को सबसे अच्छी तरह दर्शाता है?","optionsHi":["अभिक्रमित अधिगम, क्योंकि परियोजना-कार्य छोटे क्रमिक फ़्रेमों में बाँटा गया है","व्यवहारवादी अभ्यास, क्योंकि सर्वेक्षण और मॉडल-निर्माण के कौशल धाराप्रवाह होने तक दोहराए जाते हैं","रचनावाद में निहित परियोजना-आधारित अधिगम, जो ज्ञान को वास्तविक समस्याओं से जोड़ता है","औपचारिक अनुशासन, क्योंकि कठिन और लंबा कार्य मन की शक्तियों को प्रशिक्षित करता है"],"explanationHi":"परियोजना-आधारित अधिगम अधिगमकर्ताओं को प्रामाणिक, विस्तृत अन्वेषणों में संलग्न करता है; वे विचारों को किसी वास्तविक सामुदायिक समस्या पर लागू करके ज्ञान का निर्माण करते हैं, जैसा NCF 2005 अनुशंसित करती है।"},
  {"id":"cdp-child-development-1177","question":"In a jigsaw activity on the freedom struggle, each member of a group studies one movement with members of other groups who have the same movement, then returns to teach it to the home group. Why does this work well?","options":["Each child learns only one movement, so the workload is lighter and the whole topic is covered much faster","The teacher’s role is removed, so students become fully independent of adult guidance","Children compete for the highest marks, since each one’s piece is tested separately","It creates positive interdependence: every member’s part is needed and each must explain it to others"],"answer":3,"explanation":"Jigsaw makes each learner responsible for a piece the group needs; explaining to peers deepens understanding and every member's contribution matters.","difficulty":"hard","source":"CTET · HTET","questionHi":"स्वतंत्रता संग्राम पर एक जिगसॉ गतिविधि में, समूह का प्रत्येक सदस्य अन्य समूहों के उन सदस्यों के साथ, जिनके पास वही आंदोलन है, एक आंदोलन का अध्ययन करता है, फिर अपने मूल समूह को सिखाने लौटता है। यह अच्छी तरह कार्य क्यों करता है?","optionsHi":["प्रत्येक बच्चा केवल एक आंदोलन सीखता है, इसलिए कार्यभार हल्का होता है और पूरा विषय बहुत तेज़ी से पूरा होता है","शिक्षक की भूमिका समाप्त हो जाती है, इसलिए विद्यार्थी वयस्क मार्गदर्शन से पूरी तरह स्वतंत्र हो जाते हैं","बच्चे सर्वोच्च अंकों के लिए प्रतिस्पर्धा करते हैं, क्योंकि प्रत्येक का भाग अलग से परखा जाता है","यह सकारात्मक अंतरनिर्भरता पैदा करता है: प्रत्येक सदस्य का भाग आवश्यक है और प्रत्येक को उसे दूसरों को समझाना होता है"],"explanationHi":"जिगसॉ हर अधिगमकर्ता को समूह के लिए आवश्यक एक भाग का उत्तरदायी बनाता है; साथियों को समझाना समझ गहरी करता है और प्रत्येक सदस्य का योगदान मायने रखता है।"},
  {"id":"cdp-child-development-1178","question":"Which sequence correctly describes how, for Piaget, a child's understanding changes?","options":["Equilibrium → disequilibrium → assimilation and accommodation → a new, higher equilibrium","Accommodation → reinforcement → assimilation → extinction of the earlier idea","Disequilibrium → conditioning → imitation of adult models → return to the original equilibrium","Equilibrium → punishment for errors → disequilibrium → memorisation of the answer"],"answer":0,"explanation":"Equilibration is the self-regulating process: experiences that do not fit cause disequilibrium, which is resolved by assimilation and accommodation into a more advanced balance.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"पियाजे के अनुसार बच्चे की समझ कैसे बदलती है, इसका सही क्रम कौन-सा बताता है?","optionsHi":["साम्यावस्था → असंतुलन → आत्मसात्करण और समायोजन → एक नई, उच्चतर साम्यावस्था","समायोजन → पुनर्बलन → आत्मसात्करण → पहले के विचार का विलोपन","असंतुलन → अनुबंधन → वयस्क आदर्शों की नकल → मूल साम्यावस्था में वापसी","साम्यावस्था → त्रुटियों पर दंड → असंतुलन → उत्तर का रटना"],"explanationHi":"साम्य-स्थापन (इक्विलिब्रेशन) स्व-नियामक प्रक्रिया है: जो अनुभव फिट नहीं बैठते वे असंतुलन उत्पन्न करते हैं, जिसे आत्मसात्करण और समायोजन द्वारा अधिक उन्नत संतुलन में सुलझाया जाता है।"},
  {"id":"cdp-child-development-1179","question":"Which form of assessment fits a constructivist classroom best?","options":["A single end-of-year test of memorised answers, marked strictly against the answer key","Portfolios and open-ended tasks that show how children’s thinking develops over time","Rapid oral drills marked right or wrong, to check that facts are firmly fixed","Copying exercises checked for neatness and accuracy of the copied text"],"answer":1,"explanation":"Constructivist assessment looks at the process and growth of understanding, using portfolios, projects and open tasks, in line with continuous and comprehensive evaluation.","difficulty":"moderate","source":"CTET · REET","questionHi":"रचनावादी कक्षा के लिए कौन-सा आकलन-रूप सबसे उपयुक्त है?","optionsHi":["वर्ष के अंत की एक एकल परीक्षा जिसमें रटे हुए उत्तर होते हैं, और उत्तर-कुंजी के अनुसार कठोरता से अंक दिए जाते हैं","पोर्टफ़ोलियो और खुले-अंत वाले कार्य जो दिखाते हैं कि समय के साथ बच्चों की सोच कैसे विकसित होती है","तेज़ मौखिक अभ्यास जिनमें सही-गलत अंकित किया जाता है, ताकि तथ्य दृढ़ता से स्थापित हों","नकल करने के अभ्यास जिनमें नकल किए पाठ की साफ़-सफ़ाई और शुद्धता जाँची जाती है"],"explanationHi":"रचनावादी आकलन समझ की प्रक्रिया और वृद्धि को देखता है, पोर्टफ़ोलियो, परियोजनाओं और खुले कार्यों का उपयोग करके, जो सतत एवं व्यापक मूल्यांकन के अनुरूप है।"},
  {"id":"cdp-child-development-1180","question":"At age four, Ayesha solves jigsaw puzzles with her mother, who says things like ‘Find the edges first; look for the blue sky.’ At five she mutters the same hints to herself while working; at seven she solves puzzles silently. Which idea of Vygotsky does this sequence show?","options":["Assimilation followed by accommodation, as she adjusts her puzzle schema through experience","Overjustification","Learned helplessness","Internalisation: a function appears first between people, then within the child"],"answer":3,"explanation":"Vygotsky held that higher mental functions appear first on the social (interpsychological) plane and then on the individual (intrapsychological) plane, via private speech that becomes inner speech.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"चार वर्ष की उम्र में आयशा अपनी माँ के साथ जिगसॉ पहेलियाँ हल करती है, जो कहती हैं, ‘पहले किनारे ढूँढ़ो; नीले आसमान को देखो।’ पाँच वर्ष की उम्र में वह काम करते समय वही संकेत स्वयं से बुदबुदाती है; सात वर्ष की उम्र में वह पहेलियाँ चुपचाप हल करती है। यह क्रम वाइगोत्स्की के किस विचार को दर्शाता है?","optionsHi":["आत्मसात्करण के बाद समायोजन, क्योंकि वह अनुभव से अपनी पहेली-स्कीमा को ढालती है","अतिऔचित्य (ओवरजस्टिफ़िकेशन)","सीखी हुई असहायता","आंतरिकीकरण: प्रकार्य पहले लोगों के बीच प्रकट होता है, फिर बच्चे के भीतर"],"explanationHi":"वाइगोत्स्की का मानना था कि उच्चतर मानसिक प्रकार्य पहले सामाजिक (अंतर-मनोवैज्ञानिक) धरातल पर और फिर वैयक्तिक (अंतःमनोवैज्ञानिक) धरातल पर प्रकट होते हैं, निजी वाक् के माध्यम से जो आंतरिक वाक् बन जाता है।"},
  {"id":"cdp-child-development-1181","question":"Which statement correctly relates the zone of proximal development and scaffolding?","options":["They are two names for the same thing, both introduced by Vygotsky to describe teaching","Scaffolding is the region of potential learning, and the ZPD is the help given by the adult or peer","The ZPD is the range of tasks a child can do with help; scaffolding is the support given within it","Both refer to what a child can already do completely alone, without any help"],"answer":2,"explanation":"The ZPD (Vygotsky) is a region of potential development; scaffolding (a term introduced by Wood, Bruner and Ross) is the temporary, adjustable support that helps the learner work within it.","difficulty":"hard","source":"CTET Paper 1 · Super TET","questionHi":"कौन-सा कथन निकटस्थ विकास के क्षेत्र (ZPD) और पाड़ (स्कैफोल्डिंग) का सही संबंध बताता है?","optionsHi":["ये एक ही चीज़ के दो नाम हैं, दोनों वाइगोत्स्की द्वारा शिक्षण का वर्णन करने के लिए प्रस्तुत किए गए","पाड़ संभावित अधिगम का क्षेत्र है, और ZPD वयस्क या साथी द्वारा दी गई सहायता है","ZPD उन कार्यों की परास है जो बच्चा सहायता से कर सकता है; पाड़ उसके भीतर दी जाने वाली सहायता है","दोनों उसे दर्शाते हैं जो बच्चा बिना किसी सहायता के पहले से पूरी तरह अकेले कर सकता है"],"explanationHi":"ZPD (वाइगोत्स्की) संभावित विकास का क्षेत्र है; पाड़ (वुड, ब्रूनर और रॉस द्वारा प्रस्तुत शब्द) वह अस्थायी, समायोज्य सहायता है जो अधिगमकर्ता को उसके भीतर कार्य करने में सहायता देती है।"},
  {"id":"cdp-child-development-1182","question":"A teacher says, ‘Constructivism means every child's answer is equally correct, because each child builds his own knowledge.’ Which reply is most accurate?","options":["She is right; constructivism rejects any standard of correctness, since all knowledge is purely personal","Constructivism applies only to primary classes, so it says nothing about correctness in later years","Constructivism holds that knowledge is transmitted, so only the teacher’s answer is correct","Children build knowledge actively, but ideas are still tested against evidence, and some are more valid"],"answer":3,"explanation":"Constructivism describes how knowledge is built, not that all ideas are equally valid. Teachers help children test and revise their ideas against evidence and shared knowledge.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक शिक्षिका कहती है, ‘रचनावाद का अर्थ है कि हर बच्चे का उत्तर समान रूप से सही है, क्योंकि प्रत्येक बच्चा अपना ज्ञान स्वयं बनाता है।’ कौन-सा उत्तर सबसे सटीक है?","optionsHi":["वह सही है; रचनावाद शुद्धता के किसी भी मानक को अस्वीकार करता है, क्योंकि सारा ज्ञान पूर्णतः व्यक्तिगत है","रचनावाद केवल प्राथमिक कक्षाओं पर लागू होता है, इसलिए वह बाद के वर्षों में शुद्धता के बारे में कुछ नहीं कहता","रचनावाद मानता है कि ज्ञान का संचरण होता है, इसलिए केवल शिक्षक का उत्तर सही है","बच्चे सक्रिय रूप से ज्ञान का निर्माण करते हैं, पर विचारों को फिर भी प्रमाणों पर परखा जाता है, और कुछ अधिक वैध होते हैं"],"explanationHi":"रचनावाद बताता है कि ज्ञान कैसे बनता है, यह नहीं कि सभी विचार समान रूप से वैध हैं। शिक्षक बच्चों को प्रमाणों और साझा ज्ञान के आधार पर अपने विचारों को परखने और संशोधित करने में सहायता करते हैं।"},
  {"id":"cdp-child-development-1183","question":"When Class 5 student Arif says that a heavier ball falls faster, the teacher asks, ‘If you tie a heavy ball to a light one, would the pair fall faster or slower than the heavy ball alone?’ Arif hesitates and starts rethinking. The teacher is using:","options":["Socratic questioning that leads him to a contradiction in his own idea","Negative reinforcement, removing his wrong idea by asking a question","Rote drill of the law of falling bodies","Programmed instruction that breaks the idea into small graded steps"],"answer":0,"explanation":"By a question that reveals a contradiction (the light ball should both slow and speed the pair), the teacher prompts Arif to reconstruct his idea himself rather than be told.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"जब कक्षा 5 का विद्यार्थी आरिफ़ कहता है कि भारी गेंद तेज़ गिरती है, तो शिक्षक पूछता है, ‘यदि तुम किसी भारी गेंद को हल्की गेंद से बाँध दो, तो जोड़ी अकेली भारी गेंद से तेज़ गिरेगी या धीमी?’ आरिफ़ हिचकिचाता है और फिर से सोचने लगता है। शिक्षक उपयोग कर रहा है:","optionsHi":["सुकराती प्रश्न-विधि, जो उसे उसके अपने विचार के विरोधाभास तक ले जाती है","नकारात्मक पुनर्बलन, जो प्रश्न पूछकर उसका गलत विचार हटा देता है","गिरते पिंडों के नियम का रटंत अभ्यास","अभिक्रमित अनुदेशन जो विचार को छोटे श्रेणीबद्ध चरणों में बाँटता है"],"explanationHi":"ऐसे प्रश्न से जो विरोधाभास उजागर करता है (हल्की गेंद को जोड़ी को धीमा भी करना चाहिए और तेज़ भी), शिक्षक आरिफ़ को बताने के बजाय स्वयं अपने विचार का पुनर्निर्माण करने को प्रेरित करता है।"},
  {"id":"cdp-child-development-1184","question":"Vygotsky wrote that in play a child behaves ‘a head taller’ than himself. Which classroom implication follows?","options":["Play should be removed from school to make more time for serious academic learning","Pretend play with roles and rules creates a ZPD where children practise self-control","Play is useful mainly for physical exercise and letting off energy between lessons","Only free play without any rules supports development, since rules restrict imagination"],"answer":1,"explanation":"In make-believe play children follow the rules of roles and use objects symbolically, functioning above their everyday level; Vygotsky saw play itself as creating a ZPD.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"वाइगोत्स्की ने लिखा कि खेल में बच्चा स्वयं से ‘एक सिर ऊँचा’ व्यवहार करता है। इससे कक्षा के लिए कौन-सा निहितार्थ निकलता है?","optionsHi":["गंभीर शैक्षिक अधिगम के लिए अधिक समय बनाने हेतु खेल को विद्यालय से हटा देना चाहिए","भूमिकाओं और नियमों वाला कल्पनात्मक खेल एक ZPD बनाता है जहाँ बच्चे आत्म-नियंत्रण का अभ्यास करते हैं","खेल मुख्यतः शारीरिक व्यायाम और पाठों के बीच ऊर्जा निकालने के लिए उपयोगी है","केवल बिना किसी नियम का मुक्त खेल विकास में सहायक है, क्योंकि नियम कल्पना को बाधित करते हैं"],"explanationHi":"काल्पनिक खेल में बच्चे भूमिकाओं के नियमों का पालन करते हैं और वस्तुओं का प्रतीकात्मक उपयोग करते हैं, अपने दैनिक स्तर से ऊपर कार्य करते हैं; वाइगोत्स्की ने खेल को स्वयं ZPD बनाने वाला माना।"},
  {"id":"cdp-child-development-1185","question":"A young apprentice at a potter's workshop in Khurja first watches the master, then makes small pots with the master guiding his hands, receives less and less help over months, and is finally left to work alone while the master only checks. This sequence best matches:","options":["Classical conditioning of hand movements to the sight of the spinning wheel","Learned helplessness","Cognitive apprenticeship: modelling, coaching, scaffolding and fading","Formal discipline"],"answer":2,"explanation":"Cognitive apprenticeship applies Vygotskian ideas: the expert models, coaches and scaffolds, then fades support so the learner becomes independent.","difficulty":"hard","source":"CTET · HTET","questionHi":"खुर्जा की कुम्हार की कार्यशाला में एक युवा प्रशिक्षु पहले उस्ताद को देखता है, फिर उस्ताद के उसके हाथों को मार्गदर्शन देने के साथ छोटे बर्तन बनाता है, महीनों में कम से कम सहायता पाता है, और अंत में अकेले काम करने को छोड़ दिया जाता है जबकि उस्ताद केवल जाँच करता है। यह क्रम सबसे अच्छी तरह मेल खाता है:","optionsHi":["घूमते चाक को देखकर हाथ की गतियों का शास्त्रीय अनुबंधन","सीखी हुई असहायता","संज्ञानात्मक शिक्षुता: आदर्श प्रस्तुत करना, प्रशिक्षण, पाड़ और सहायता का क्रमिक हटाना","औपचारिक अनुशासन"],"explanationHi":"संज्ञानात्मक शिक्षुता वाइगोत्स्की के विचारों को लागू करती है: विशेषज्ञ आदर्श प्रस्तुत करता है, प्रशिक्षण और पाड़ देता है, फिर सहायता को क्रमशः हटाता है ताकि अधिगमकर्ता स्वतंत्र हो जाए।"},
  {"id":"cdp-child-development-1186","question":"Before a unit on birds, a Class 4 teacher makes a chart with three columns: ‘What we Know’, ‘What we Want to know’, and later ‘What we Learnt’. The first column mainly serves to:","options":["Find out who is the most intelligent child in the class before the teaching begins","Test children’s memory of the definitions they learnt last year","Replace the lesson plan with whatever the children want to learn","Activate and reveal prior knowledge so that new learning can be linked to it"],"answer":3,"explanation":"A KWL chart begins by surfacing what children already know or believe, which lets the teacher connect new ideas to it and spot misconceptions.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"पक्षियों की इकाई से पहले कक्षा 4 का शिक्षक तीन स्तंभों वाला चार्ट बनाता है: ‘हम क्या जानते हैं’, ‘हम क्या जानना चाहते हैं’, और बाद में ‘हमने क्या सीखा’। पहला स्तंभ मुख्यतः किसलिए है?","optionsHi":["शिक्षण शुरू होने से पहले कक्षा का सबसे बुद्धिमान बच्चा पता लगाने के लिए","पिछले वर्ष सीखी परिभाषाओं की बच्चों की स्मृति परखने के लिए","पाठ-योजना को इस बात से बदलने के लिए कि बच्चे जो भी सीखना चाहें","पूर्व ज्ञान को सक्रिय करने और प्रकट करने के लिए ताकि नया अधिगम उससे जोड़ा जा सके"],"explanationHi":"KWL चार्ट की शुरुआत इस बात को सामने लाने से होती है कि बच्चे पहले से क्या जानते या मानते हैं, जिससे शिक्षक नए विचारों को उससे जोड़ सकता है और भ्रांतियों को पहचान सकता है।"},
  {"id":"cdp-child-development-1187","question":"Assertion (A): Piaget was sceptical of attempts to push children through his stages faster by direct training. Reason (R): For Piaget, a child's developmental level sets limits on what he can understand from instruction.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because Piaget saw development as preceding learning, he called acceleration 'the American question' and doubted its value; instruction can help only when the child is developmentally ready.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): पियाजे प्रत्यक्ष प्रशिक्षण द्वारा बच्चों को उनकी अवस्थाओं से जल्दी गुज़ारने के प्रयासों के प्रति संशयी थे। कारण (R): पियाजे के लिए बच्चे का विकासात्मक स्तर इस पर सीमाएँ लगाता है कि वह निर्देश से क्या समझ सकता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"क्योंकि पियाजे विकास को अधिगम से पहले आने वाला मानते थे, उन्होंने त्वरण को ‘अमेरिकी प्रश्न’ कहा और उसके मूल्य पर संदेह किया; निर्देश तभी सहायक हो सकता है जब बच्चा विकासात्मक रूप से तैयार हो।"},
  {"id":"cdp-child-development-1188","question":"Why do constructivist teachers often ask children to explain an answer in their own words rather than repeat the textbook line?","options":["To reduce the time spent on the topic, since textbook lines take longer to copy out","To test their handwriting and spelling in addition to their knowledge of the topic","Because explaining makes learners reorganise ideas and shows what they have really understood","Because textbook language is usually wrong or far too difficult for children to be trusted at all"],"answer":2,"explanation":"Putting ideas in one's own words is elaborative processing that builds understanding, and it shows the teacher whether the concept, not just the wording, has been grasped.","difficulty":"moderate","source":"CTET · UPTET","questionHi":"रचनावादी शिक्षक प्रायः बच्चों से पाठ्यपुस्तक की पंक्ति दोहराने के बजाय उत्तर को अपने शब्दों में समझाने को क्यों कहते हैं?","optionsHi":["विषय पर लगने वाला समय घटाने के लिए, क्योंकि पाठ्यपुस्तक की पंक्तियाँ उतारने में अधिक समय लगता है","विषय के ज्ञान के साथ उनकी लिखावट और वर्तनी भी परखने के लिए","क्योंकि समझाने से अधिगमकर्ता विचारों को पुनर्गठित करते हैं और दिखता है कि उन्होंने वास्तव में क्या समझा है","क्योंकि पाठ्यपुस्तक की भाषा प्रायः गलत होती है या बच्चों के लिए इतनी कठिन कि उस पर भरोसा नहीं किया जा सकता"],"explanationHi":"विचारों को अपने शब्दों में रखना विस्तारी प्रसंस्करण है जो समझ का निर्माण करता है, और शिक्षक को दिखाता है कि केवल शब्द नहीं, अवधारणा भी समझी गई है।"},
  {"id":"cdp-child-development-1189","question":"Which statement about Ausubel's view of reception learning is correct?","options":["Reception learning is always rote and should be avoided in favour of pure discovery","Learning by being told can be meaningful if it is related to relevant ideas the learner already has","Only discovery learning can be meaningful, since being told leaves the learner passive","Ausubel rejected advance organisers because they give away the content before the lesson has even begun"],"answer":1,"explanation":"Ausubel argued that reception (expository) learning is not necessarily rote; it becomes meaningful when new information is anchored to existing cognitive structure, often via advance organisers.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"ऑसुबेल के ग्रहणात्मक अधिगम के दृष्टिकोण के बारे में कौन-सा कथन सही है?","optionsHi":["ग्रहणात्मक अधिगम सदैव रटंत होता है और शुद्ध खोज के पक्ष में उससे बचना चाहिए","बताकर सीखना तब सार्थक हो सकता है जब उसे अधिगमकर्ता के पास पहले से उपलब्ध प्रासंगिक विचारों से जोड़ा जाए","केवल खोज अधिगम सार्थक हो सकता है, क्योंकि बताने से अधिगमकर्ता निष्क्रिय रहता है","ऑसुबेल ने अग्रिम संगठकों को अस्वीकार किया क्योंकि वे पाठ आरंभ होने से पहले ही सामग्री बता देते हैं"],"explanationHi":"ऑसुबेल ने तर्क दिया कि ग्रहणात्मक (व्याख्यात्मक) अधिगम आवश्यक रूप से रटंत नहीं है; वह तब सार्थक बनता है जब नई सूचना को मौजूदा संज्ञानात्मक संरचना से जोड़ा जाए, प्रायः अग्रिम संगठकों के माध्यम से।"},
  {"id":"cdp-child-development-1190","question":"Students must lift a small weight using a ruler, a pencil and a few books, but most cannot think of using the ruler as a lever because they see it only as a measuring tool. Gestalt psychologists call this obstacle to insight:","options":["Spontaneous recovery","Proactive interference","Overlearning","Functional fixedness"],"answer":3,"explanation":"Functional fixedness (Duncker) is the tendency to see objects only in their usual function, which blocks restructuring of the problem and the insight needed to solve it.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"विद्यार्थियों को एक पटरी, एक पेंसिल और कुछ पुस्तकों से एक छोटा भार उठाना है, पर अधिकांश पटरी को उत्तोलक के रूप में उपयोग करने की नहीं सोच पाते क्योंकि वे उसे केवल मापन का उपकरण मानते हैं। गेस्टाल्ट मनोवैज्ञानिक अंतर्दृष्टि की इस बाधा को क्या कहते हैं?","optionsHi":["स्वतः पुनर्प्राप्ति","अग्रलक्षी व्यतिकरण","अति-अधिगम","कार्यात्मक स्थिरता"],"explanationHi":"कार्यात्मक स्थिरता (डंकर) वस्तुओं को केवल उनके सामान्य कार्य में देखने की प्रवृत्ति है, जो समस्या के पुनर्गठन और हल के लिए आवश्यक अंतर्दृष्टि को रोकती है।"},
  {"id":"cdp-child-development-1191","question":"In a social constructivist Class 3 maths period, two children disagree about whether 1/3 of a chapati is bigger than 1/4. What should the teacher do?","options":["Let them justify their views and test them with real chapatis or paper circles","Tell them the correct answer immediately to save time for the rest of the lesson","Separate them so that the disagreement does not turn into a quarrel","Give a mark to whoever is right, so that both learn to be careful"],"answer":0,"explanation":"Disagreement is an opportunity for reasoning and evidence. Testing ideas with concrete material and discussing them helps both children construct the idea that more equal parts means smaller parts.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"सामाजिक रचनावादी कक्षा 3 के गणित कालांश में, दो बच्चे इस बात पर असहमत हैं कि चपाती का 1/3 भाग 1/4 भाग से बड़ा है या नहीं। शिक्षक को क्या करना चाहिए?","optionsHi":["उन्हें अपने मत के पक्ष में तर्क देने दे और असली चपातियों या कागज़ के वृत्तों से उन्हें परखने दे","पाठ के शेष भाग के लिए समय बचाने हेतु उन्हें तुरंत सही उत्तर बता दे","उन्हें अलग कर दे ताकि असहमति झगड़े में न बदले","जो सही हो उसे अंक दे, ताकि दोनों सावधान रहना सीखें"],"explanationHi":"असहमति तर्क और प्रमाण का अवसर है। ठोस सामग्री से विचारों को परखना और उन पर चर्चा करना दोनों बच्चों को यह विचार गढ़ने में सहायता देता है कि अधिक बराबर भाग का अर्थ छोटे भाग हैं।"},
  {"id":"cdp-child-development-1192","question":"Which of these statements about insight learning are correct? I. It involves perceiving the relationships among the parts of a problem. II. Once achieved, the solution is usually remembered and can be repeated easily. III. It depends on the learner's past experience as well as on how the problem is presented. IV. It occurs only in humans and never in animals.","options":["I and IV only","I, II and III only","II and IV only","I, II, III and IV"],"answer":1,"explanation":"Köhler demonstrated insight in chimpanzees, so IV is false. Insight rests on perceiving relationships, is well retained, and is influenced by both experience and the arrangement of the problem.","difficulty":"hard","source":"CTET · REET","questionHi":"अंतर्दृष्टि अधिगम के बारे में इनमें से कौन-से कथन सही हैं? I. इसमें समस्या के भागों के बीच संबंधों को देखना शामिल है। II. एक बार प्राप्त हो जाने पर समाधान प्रायः याद रहता है और आसानी से दोहराया जा सकता है। III. यह अधिगमकर्ता के पिछले अनुभव के साथ-साथ इस पर भी निर्भर करता है कि समस्या कैसे प्रस्तुत की गई है। IV. यह केवल मनुष्यों में होता है, पशुओं में कभी नहीं।","optionsHi":["केवल I और IV","केवल I, II और III","केवल II और IV","I, II, III और IV"],"explanationHi":"कोहलर ने चिम्पैंज़ियों में अंतर्दृष्टि प्रदर्शित की, इसलिए IV असत्य है। अंतर्दृष्टि संबंधों को देखने पर आधारित है, भली-भाँति याद रहती है, और अनुभव तथा समस्या की व्यवस्था दोनों से प्रभावित होती है।"},
  {"id":"cdp-child-development-1193","question":"A Class 10 boy races his motorbike without a helmet and tells his worried teacher, ‘Accidents happen to other people. Nothing will happen to me.’ Elkind would explain this belief as:","options":["Imaginary audience","Personal fable","Moral realism","Identity foreclosure"],"answer":1,"explanation":"The personal fable is the adolescent’s belief that he is unique and invulnerable, which feeds risk-taking. The imaginary audience is the belief that everyone is watching and judging him.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 10 का एक लड़का बिना हेलमेट के अपनी मोटरबाइक दौड़ाता है और चिंतित शिक्षक से कहता है, ‘दुर्घटनाएँ दूसरों के साथ होती हैं। मेरे साथ कुछ नहीं होगा।’ एल्किंड इस विश्वास की व्याख्या किससे करेंगे?","optionsHi":["काल्पनिक दर्शक","व्यक्तिगत गाथा (पर्सनल फ़ेबल)","नैतिक यथार्थवाद","पहचान का पूर्वनिर्धारण (आइडेंटिटी फ़ोरक्लोज़र)"],"explanationHi":"व्यक्तिगत गाथा किशोर का यह विश्वास है कि वह अद्वितीय और अजेय है, जो जोखिम लेने को बढ़ावा देता है। काल्पनिक दर्शक यह विश्वास है कि हर कोई उसे देख और परख रहा है।"},
  {"id":"cdp-child-development-1194","question":"After a break-up, a Class 11 girl writes in her diary, ‘Nobody in the world has ever felt pain like mine; my parents could never understand.’ Which aspect of adolescent egocentrism does this show?","options":["Imaginary audience","Centration","Personal fable","Animism"],"answer":2,"explanation":"Feeling that one’s experiences are so unique that no one else can understand them is the uniqueness side of the personal fable. Centration and animism belong to pre-operational thinking.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"संबंध टूटने के बाद कक्षा 11 की एक लड़की अपनी डायरी में लिखती है, ‘संसार में किसी ने कभी मेरे जैसा दर्द नहीं सहा; मेरे माता-पिता कभी नहीं समझ सकते।’ यह किशोर अहंकेंद्रिता के किस पहलू को दर्शाता है?","optionsHi":["काल्पनिक दर्शक","केंद्रीकरण","व्यक्तिगत गाथा","जीववाद"],"explanationHi":"यह अनुभव करना कि अपने अनुभव इतने अनोखे हैं कि कोई और उन्हें समझ नहीं सकता, व्यक्तिगत गाथा का अद्वितीयता वाला पक्ष है। केंद्रीकरण और जीववाद पूर्व-संक्रियात्मक चिंतन से संबंधित हैं।"},
  {"id":"cdp-child-development-1195","question":"Match the adolescent statements with Elkind’s concepts: P. ‘Everyone in the assembly noticed my new haircut and is laughing.’ Q. ‘I can smoke; I won’t get addicted like others.’ R. ‘I’m sure the whole class is talking about my spot.’ S. ‘My feelings are too special for anyone to understand.’","options":["P-imaginary audience, Q-personal fable, R-imaginary audience, S-personal fable","P-personal fable, Q-imaginary audience, R-personal fable, S-imaginary audience","P-imaginary audience, Q-imaginary audience, R-personal fable, S-personal fable","P-personal fable, Q-personal fable, R-imaginary audience, S-imaginary audience"],"answer":0,"explanation":"Feeling observed and judged (P, R) is the imaginary audience; feeling invulnerable or uniquely special (Q, S) is the personal fable.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"किशोरों के कथनों का एल्किंड की अवधारणाओं से मिलान कीजिए: P. ‘सभा में सबने मेरा नया हेयरकट देखा और हँस रहे हैं।’ Q. ‘मैं धूम्रपान कर सकता हूँ; मुझे दूसरों की तरह लत नहीं लगेगी।’ R. ‘मुझे यकीन है कि पूरी कक्षा मेरे मुँहासे के बारे में बात कर रही है।’ S. ‘मेरी भावनाएँ इतनी विशेष हैं कि कोई उन्हें समझ नहीं सकता।’","optionsHi":["P-काल्पनिक दर्शक, Q-व्यक्तिगत गाथा, R-काल्पनिक दर्शक, S-व्यक्तिगत गाथा","P-व्यक्तिगत गाथा, Q-काल्पनिक दर्शक, R-व्यक्तिगत गाथा, S-काल्पनिक दर्शक","P-काल्पनिक दर्शक, Q-काल्पनिक दर्शक, R-व्यक्तिगत गाथा, S-व्यक्तिगत गाथा","P-व्यक्तिगत गाथा, Q-व्यक्तिगत गाथा, R-काल्पनिक दर्शक, S-काल्पनिक दर्शक"],"explanationHi":"देखे और परखे जाने का एहसास (P, R) काल्पनिक दर्शक है; अजेय या अद्वितीय रूप से विशेष होने का एहसास (Q, S) व्यक्तिगत गाथा है।"},
  {"id":"cdp-child-development-1196","question":"G. Stanley Hall described adolescence as a period of inevitable ‘storm and stress’. Margaret Mead’s studies in Samoa were taken to challenge this by suggesting that:","options":["Adolescence is stormier in simple societies than in industrial ones, because of early marriage and work","Puberty is delayed in some societies, so adolescence and its stresses never really occur there","The degree of adolescent turmoil depends greatly on culture, so storm and stress is not universal","Adolescents everywhere go through the same emotional crises, whatever their culture"],"answer":2,"explanation":"Mead argued that Samoan adolescents passed through puberty relatively smoothly, so cultural context shapes adolescent experience. Modern research agrees that serious turmoil is not universal, though conflict and mood swings are more common than in childhood.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"जी. स्टैनली हॉल ने किशोरावस्था को अपरिहार्य ‘झंझावात और तनाव’ का काल बताया। मार्गरेट मीड के समोआ अध्ययनों को इसे यह सुझाकर चुनौती देने वाला माना गया कि:","optionsHi":["सरल समाजों में किशोरावस्था औद्योगिक समाजों से अधिक तूफ़ानी होती है, क्योंकि वहाँ जल्दी विवाह और कार्य होता है","कुछ समाजों में यौवनारंभ विलंबित होता है, इसलिए वहाँ किशोरावस्था और उसके तनाव कभी होते ही नहीं","किशोर उथल-पुथल की मात्रा संस्कृति पर बहुत निर्भर करती है, इसलिए झंझावात और तनाव सार्वभौमिक नहीं है","किशोर हर जगह एक-से भावनात्मक संकटों से गुज़रते हैं, उनकी संस्कृति कोई भी हो"],"explanationHi":"मीड ने तर्क दिया कि समोआ के किशोर यौवनारंभ से अपेक्षाकृत सहजता से गुज़रे, इसलिए सांस्कृतिक संदर्भ किशोर-अनुभव को आकार देता है। आधुनिक शोध भी मानता है कि गंभीर उथल-पुथल सार्वभौमिक नहीं है, यद्यपि बाल्यावस्था की तुलना में संघर्ष और मनोदशा-परिवर्तन अधिक आम हैं।"},
  {"id":"cdp-child-development-1197","question":"Research shows adolescents take far more risks in a driving game when friends are watching than when alone, while adults are not affected this way. Which explanation is best supported?","options":["Adolescents simply cannot understand risks at all, whether friends are present or not","Adolescents are deliberately disobedient by nature and like to break adult rules","The adolescent brain is already fully mature, so the behaviour is purely a matter of social pressure","Reward systems mature before prefrontal self-control systems, so peers boost the pull of rewards"],"answer":3,"explanation":"Reward-related systems become highly responsive around puberty while prefrontal control matures into the twenties; peers heighten the reward value of risky choices. Adolescents often know the risks but act differently in emotionally charged settings.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"शोध दर्शाता है कि किशोर ड्राइविंग खेल में मित्रों के देखते समय अकेले होने की तुलना में कहीं अधिक जोखिम लेते हैं, जबकि वयस्क इस तरह प्रभावित नहीं होते। कौन-सी व्याख्या सबसे अच्छी तरह समर्थित है?","optionsHi":["किशोर जोखिमों को बिल्कुल समझ ही नहीं सकते, चाहे मित्र उपस्थित हों या न हों","किशोर स्वभाव से जानबूझकर अवज्ञाकारी होते हैं और वयस्कों के नियम तोड़ना पसंद करते हैं","किशोर मस्तिष्क पहले से पूर्णतः परिपक्व है, इसलिए यह व्यवहार पूरी तरह सामाजिक दबाव का विषय है","पुरस्कार-तंत्र प्रीफ्रंटल आत्म-नियंत्रण तंत्रों से पहले परिपक्व होते हैं, इसलिए साथी पुरस्कारों के आकर्षण को बढ़ा देते हैं"],"explanationHi":"पुरस्कार-संबंधी तंत्र यौवनारंभ के आसपास अत्यंत संवेदनशील हो जाते हैं जबकि प्रीफ्रंटल नियंत्रण बीसवें वर्ष तक परिपक्व होता है; साथी जोखिम भरे चयनों के पुरस्कार-मूल्य को बढ़ा देते हैं। किशोर प्रायः जोखिम जानते हैं पर भावनात्मक रूप से आवेशित परिस्थितियों में भिन्न व्यवहार करते हैं।"},
  {"id":"cdp-child-development-1198","question":"Before a school trip, a Class 11 teacher wants to reduce risky behaviour. In the light of research on adolescent decision-making, what is likely to work best?","options":["Giving a detailed lecture on the dangers of risky behaviour, since facts alone change behaviour","Framing rules with students, ensuring supervision and planning for peer-driven risky moments","Leaving them completely free, as adolescents must learn from their own mistakes","Threatening severe punishment for any misbehaviour, without explaining the reasons"],"answer":1,"explanation":"Adolescents often know the facts but act on emotion with peers; shared rule-making respects their autonomy, while structure and supervision limit high-risk ‘hot’ situations.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"विद्यालय-यात्रा से पहले, कक्षा 11 का शिक्षक जोखिम भरे व्यवहार को घटाना चाहता है। किशोरों के निर्णय-निर्माण पर शोध के प्रकाश में, क्या सबसे अच्छा काम करने की संभावना रखता है?","optionsHi":["जोखिम भरे व्यवहार के खतरों पर विस्तृत व्याख्यान देना, क्योंकि केवल तथ्य व्यवहार बदल देते हैं","विद्यार्थियों के साथ नियम बनाना, पर्यवेक्षण सुनिश्चित करना और साथियों द्वारा प्रेरित जोखिम भरे क्षणों की योजना बनाना","उन्हें पूरी तरह स्वतंत्र छोड़ना, क्योंकि किशोरों को अपनी गलतियों से ही सीखना चाहिए","कारण बताए बिना किसी भी दुर्व्यवहार पर कठोर दंड की धमकी देना"],"explanationHi":"किशोर प्रायः तथ्य जानते हैं पर साथियों के साथ भावना पर कार्य करते हैं; साझा नियम-निर्माण उनकी स्वायत्तता का सम्मान करता है, जबकि संरचना और पर्यवेक्षण उच्च-जोखिम वाली ‘उत्तेजित’ परिस्थितियों को सीमित करते हैं।"},
  {"id":"cdp-child-development-1199","question":"Class 9 students angrily point out that adults preach honesty yet bribe officials, and some draw up plans for a ‘perfect’ society. Which response best fits their developmental stage?","options":["Treat it as disrespect towards elders and punish it so that it does not spread","Tell them idealism is childish and that they will grow out of it once they start working","Channel it into debates and community projects that test ideals against practical constraints","Avoid all discussion of social issues in class, since it distracts from the syllabus and exams"],"answer":2,"explanation":"Formal operational thought lets adolescents imagine ideal possibilities and spot inconsistencies; constructive outlets build reasoning and civic sense instead of suppressing a normal developmental trait.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 9 के विद्यार्थी क्रोध में कहते हैं कि वयस्क ईमानदारी का उपदेश देते हैं फिर भी अधिकारियों को रिश्वत देते हैं, और कुछ ‘आदर्श’ समाज की योजनाएँ बनाते हैं। उनकी विकासात्मक अवस्था के लिए कौन-सी प्रतिक्रिया सबसे उपयुक्त है?","optionsHi":["इसे बड़ों के प्रति अनादर मानकर दंडित करना ताकि यह फैले नहीं","उनसे कहना कि आदर्शवाद बचकाना है और काम शुरू करने पर वे इससे बाहर आ जाएँगे","इसे वाद-विवादों और सामुदायिक परियोजनाओं में लगाना जो आदर्शों को व्यावहारिक बाधाओं पर परखें","कक्षा में सामाजिक मुद्दों की सारी चर्चा से बचना, क्योंकि वह पाठ्यक्रम और परीक्षाओं से ध्यान भटकाती है"],"explanationHi":"औपचारिक संक्रियात्मक चिंतन किशोरों को आदर्श संभावनाओं की कल्पना करने और असंगतियाँ पहचानने देता है; रचनात्मक माध्यम एक सामान्य विकासात्मक लक्षण को दबाने के बजाय तर्क और नागरिक-बोध का निर्माण करते हैं।"},
  {"id":"cdp-child-development-1200","question":"In Class 6, a girl who has entered puberty much earlier than her classmates is teased about her body, has started mixing with much older students and seems unhappy with her appearance. What does research on pubertal timing suggest?","options":["Early-maturing girls are at greater risk of low mood and body dissatisfaction, so she may need support","Early maturation is always an advantage for girls, as they quickly gain status and popularity among classmates","Pubertal timing has no real effect on adjustment, so her unhappiness must have another cause","She should be moved to a higher class to be with peers of her own size and maturity level"],"answer":0,"explanation":"Early maturation in girls is consistently linked with greater risk of emotional and behavioural difficulties, partly because they are out of step with peers; discreet support and stopping teasing help.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 6 में, एक लड़की जिसने अपने सहपाठियों से बहुत पहले यौवनारंभ में प्रवेश किया है, उसके शरीर को लेकर चिढ़ाई जाती है, बहुत बड़े विद्यार्थियों के साथ घुलने-मिलने लगी है और अपनी शक्ल से अप्रसन्न लगती है। यौवनारंभ के समय पर शोध क्या सुझाता है?","optionsHi":["जल्दी परिपक्व होने वाली लड़कियों में उदास मनोदशा और शारीरिक असंतोष का अधिक खतरा होता है, इसलिए उसे सहायता की आवश्यकता हो सकती है","जल्दी परिपक्वता लड़कियों के लिए सदैव लाभ है, क्योंकि वे सहपाठियों में शीघ्र प्रतिष्ठा और लोकप्रियता पाती हैं","यौवनारंभ का समय समायोजन पर कोई वास्तविक प्रभाव नहीं डालता, इसलिए उसकी अप्रसन्नता का कोई और कारण होगा","उसे उच्च कक्षा में भेज देना चाहिए ताकि वह अपने जैसे आकार और परिपक्वता-स्तर के साथियों के साथ रहे"],"explanationHi":"लड़कियों में जल्दी परिपक्वता भावनात्मक और व्यवहारगत कठिनाइयों के अधिक खतरे से लगातार जुड़ी है, आंशिक रूप से इसलिए कि वे साथियों से कदम नहीं मिला पातीं; विवेकपूर्ण सहायता और चिढ़ाना रोकना मदद करते हैं।"},
  {"id":"cdp-child-development-1201","question":"Which statement about pubertal timing in boys is best supported by research?","options":["Late-maturing boys usually enjoy the highest peer status, since they stay children for longer and seem carefree","Early-maturing boys tend to gain status and confidence, though they also show some higher risks","Pubertal timing affects only girls; for boys it makes no difference to adjustment","Late maturation in boys is a medical disorder that always needs hormonal treatment"],"answer":1,"explanation":"Early-maturing boys are often seen as more mature and athletic, gaining status, though they also show some higher risk-taking; late maturers may feel less confident. Late maturation within the normal range is not a disorder.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"लड़कों में यौवनारंभ के समय के बारे में कौन-सा कथन शोध द्वारा सबसे अच्छी तरह समर्थित है?","optionsHi":["देर से परिपक्व होने वाले लड़के प्रायः सबसे ऊँची समवयस्क प्रतिष्ठा पाते हैं, क्योंकि वे अधिक समय तक बच्चे रहते हैं और बेफ़िक्र दिखते हैं","जल्दी परिपक्व होने वाले लड़कों में प्रतिष्ठा और आत्मविश्वास बढ़ने की प्रवृत्ति होती है, यद्यपि उनमें कुछ अधिक जोखिम भी दिखते हैं","यौवनारंभ का समय केवल लड़कियों को प्रभावित करता है; लड़कों के लिए समायोजन में इससे कोई अंतर नहीं पड़ता","लड़कों में देर से परिपक्वता एक चिकित्सीय विकार है जिसके लिए सदैव हार्मोनल उपचार चाहिए"],"explanationHi":"जल्दी परिपक्व होने वाले लड़के प्रायः अधिक परिपक्व और खिलाड़ी माने जाते हैं और प्रतिष्ठा पाते हैं, यद्यपि उनमें कुछ अधिक जोखिम लेना भी दिखता है; देर से परिपक्व होने वाले कम आत्मविश्वासी महसूस कर सकते हैं। सामान्य परास के भीतर देर से परिपक्वता विकार नहीं है।"},
  {"id":"cdp-child-development-1202","question":"A Class 11 teacher complains that many students are drowsy in the first period despite being ‘told to sleep early’. What is the best developmental explanation?","options":["Their heavy study load leaves too little time for sleep, so homework should be cut","Late-night screen use is the cause, so a talk on mobile habits will fix the drowsiness","Growth spurts drain their energy, so they need a nutritious breakfast before school","Puberty shifts the body clock later, so they cannot fall asleep early and lose sleep"],"answer":3,"explanation":"Puberty delays the circadian rhythm (later melatonin release), so adolescents cannot fall asleep early, which is why simply telling them to sleep early fails. A growth spurt raises energy needs but does not explain drowsiness tied to the first period; study load and screens are habits and circumstances, not the developmental cause asked for.","difficulty":"very-hard","source":"CTET Paper 2 · State TET","questionHi":"कक्षा 11 का एक शिक्षक शिकायत करता है कि ‘जल्दी सोने को कहे जाने’ के बावजूद कई विद्यार्थी पहले कालांश में ऊँघते हैं। सर्वोत्तम विकासात्मक व्याख्या क्या है?","optionsHi":["उनके अध्ययन का भारी बोझ नींद के लिए बहुत कम समय छोड़ता है, इसलिए गृहकार्य कम करना चाहिए","देर रात स्क्रीन का उपयोग कारण है, इसलिए मोबाइल की आदतों पर बातचीत से ऊँघना ठीक हो जाएगा","वृद्धि-उछाल उनकी ऊर्जा खींच लेते हैं, इसलिए उन्हें विद्यालय से पहले पौष्टिक नाश्ता चाहिए","यौवनारंभ शरीर की जैविक घड़ी को देर की ओर खिसका देता है, इसलिए वे जल्दी सो नहीं पाते और नींद खो देते हैं"],"explanationHi":"यौवनारंभ दैनिक लय (सर्केडियन रिदम) को विलंबित कर देता है (मेलाटोनिन देर से निकलता है), इसलिए किशोर जल्दी सो नहीं पाते, इसीलिए उन्हें केवल जल्दी सोने को कहना विफल होता है। वृद्धि-उछाल ऊर्जा की आवश्यकता बढ़ाता है पर पहले कालांश से जुड़ी ऊँघ को नहीं समझाता; अध्ययन का बोझ और स्क्रीन आदतें और परिस्थितियाँ हैं, पूछा गया विकासात्मक कारण नहीं।"},
  {"id":"cdp-child-development-1203","question":"In Classes 6 and 7, many girls are taller than boys of the same age, but by Class 10 this is usually reversed. The best explanation is that:","options":["Girls on average begin their adolescent growth spurt about two years earlier than boys","Boys are less well nourished than girls in early adolescence, so their growth starts later","Girls stop growing completely at about age twelve, while boys keep growing","Height depends entirely on environment, which changes between Class 6 and Class 10"],"answer":0,"explanation":"Girls typically enter the growth spurt earlier; boys start later but grow for longer and more, so they overtake girls in mid-adolescence.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 6 और 7 में कई लड़कियाँ समान आयु के लड़कों से लंबी होती हैं, पर कक्षा 10 तक यह प्रायः उलट जाता है। सर्वोत्तम व्याख्या यह है कि:","optionsHi":["लड़कियाँ औसतन लड़कों से लगभग दो वर्ष पहले अपना किशोर वृद्धि-उछाल शुरू करती हैं","प्रारंभिक किशोरावस्था में लड़कों को लड़कियों से कम पोषण मिलता है, इसलिए उनकी वृद्धि देर से शुरू होती है","लड़कियाँ लगभग बारह वर्ष की आयु में पूरी तरह बढ़ना बंद कर देती हैं, जबकि लड़के बढ़ते रहते हैं","ऊँचाई पूरी तरह पर्यावरण पर निर्भर है, जो कक्षा 6 और कक्षा 10 के बीच बदलता है"],"explanationHi":"लड़कियाँ प्रायः वृद्धि-उछाल में पहले प्रवेश करती हैं; लड़के देर से शुरू करते हैं पर अधिक समय तक और अधिक बढ़ते हैं, इसलिए वे किशोरावस्था के मध्य में लड़कियों से आगे निकल जाते हैं।"},
  {"id":"cdp-child-development-1204","question":"Over the past century, the average age of first menstruation has fallen in many countries, including India. This trend is mainly attributed to:","options":["Television and cinema","Changes in the human genome over a few generations","Better nutrition and health","Earlier admission to school"],"answer":2,"explanation":"The ‘secular trend’ toward earlier puberty is linked mainly to improved nutrition and health; genes cannot change so quickly across a few generations.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"पिछली एक सदी में, भारत सहित अनेक देशों में पहले मासिक धर्म की औसत आयु घटी है। इस प्रवृत्ति का मुख्य कारण माना जाता है:","optionsHi":["टेलीविज़न और सिनेमा","कुछ पीढ़ियों में मानव जीनोम में परिवर्तन","बेहतर पोषण और स्वास्थ्य","विद्यालय में जल्दी प्रवेश"],"explanationHi":"‘सेक्युलर ट्रेंड’ (शताब्दी-प्रवृत्ति) में यौवनारंभ का पहले होना मुख्यतः बेहतर पोषण और स्वास्थ्य से जुड़ा है; जीन कुछ पीढ़ियों में इतनी तेज़ी से नहीं बदल सकते।"},
  {"id":"cdp-child-development-1205","question":"A school plans sessions on puberty and reproductive health under the Adolescence Education Programme, but some parents object. What is the most appropriate approach?","options":["Cancel the sessions, as such topics belong only at home and parents’ wishes must come first","Hold the sessions quietly without informing parents, since students need the information in any case","Leave students to learn from the internet, where they can read privately without embarrassment","Explain the age-appropriate, accurate content to parents, address their concerns and involve them"],"answer":3,"explanation":"Adolescents need accurate information and life skills; engaging parents transparently builds support. Silence or the internet leaves them to myths and risky sources.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक विद्यालय किशोरावस्था शिक्षा कार्यक्रम के अंतर्गत यौवनारंभ और प्रजनन स्वास्थ्य पर सत्र आयोजित करने की योजना बनाता है, पर कुछ अभिभावक आपत्ति करते हैं। सबसे उपयुक्त दृष्टिकोण क्या है?","optionsHi":["सत्र रद्द करना, क्योंकि ऐसे विषय केवल घर के हैं और अभिभावकों की इच्छा सर्वोपरि है","अभिभावकों को बताए बिना चुपचाप सत्र चलाना, क्योंकि विद्यार्थियों को वैसे भी जानकारी चाहिए","विद्यार्थियों को इंटरनेट से सीखने के लिए छोड़ देना, जहाँ वे बिना संकोच निजी तौर पर पढ़ सकते हैं","अभिभावकों को आयु-उपयुक्त, सटीक सामग्री समझाना, उनकी चिंताओं को संबोधित करना और उन्हें शामिल करना"],"explanationHi":"किशोरों को सटीक जानकारी और जीवन-कौशल चाहिए; अभिभावकों को पारदर्शी रूप से जोड़ना समर्थन बनाता है। चुप्पी या इंटरनेट उन्हें मिथकों और जोखिम भरे स्रोतों पर छोड़ देता है।"},
  {"id":"cdp-child-development-1206","question":"A Class 8 student is cheerful one moment and irritable or tearful the next, and her teacher calls her ‘moody and rebellious’ in front of the class. Which view is most accurate?","options":["Mood swings are common in early adolescence; the teacher should respond with empathy and privacy","The student clearly has a psychiatric disorder that needs immediate referral and medical treatment","Public labelling will help her notice her moods and learn to control them quickly","Mood changes are caused only by poor upbringing, so the parents should be called in at once"],"answer":0,"explanation":"Emotional ups and downs are common as bodies and relationships change; public labelling feeds the imaginary audience and resentment, whereas empathy and a private talk help. Persistent distress would need referral.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"कक्षा 8 की एक विद्यार्थी एक क्षण प्रसन्न और अगले क्षण चिड़चिड़ी या रुआँसी होती है, और उसकी शिक्षिका कक्षा के सामने उसे ‘मनमौजी और विद्रोही’ कहती है। कौन-सा दृष्टिकोण सबसे सटीक है?","optionsHi":["प्रारंभिक किशोरावस्था में मनोदशा-परिवर्तन आम हैं; शिक्षिका को सहानुभूति और गोपनीयता के साथ प्रतिक्रिया देनी चाहिए","विद्यार्थी को स्पष्टतः कोई मनोरोग है जिसके लिए तत्काल चिकित्सीय रेफ़रल और उपचार चाहिए","सार्वजनिक लेबल लगाने से उसे अपनी मनोदशाएँ पहचानने और शीघ्र नियंत्रित करना सीखने में मदद मिलेगी","मनोदशा-परिवर्तन केवल खराब पालन-पोषण के कारण होते हैं, इसलिए माता-पिता को तुरंत बुलाना चाहिए"],"explanationHi":"शरीर और संबंध बदलते समय भावनात्मक उतार-चढ़ाव आम हैं; सार्वजनिक लेबल काल्पनिक दर्शक और आक्रोश को बढ़ाता है, जबकि सहानुभूति और निजी बातचीत मदद करती है। लगातार बनी रहने वाली पीड़ा के लिए रेफ़रल की आवश्यकता होगी।"},
  {"id":"cdp-child-development-1207","question":"A Class 10 teacher finds students resisting rules imposed without discussion. Which practice best meets adolescents’ growing need for autonomy while keeping order?","options":["Removing all rules from the classroom so that students feel fully trusted","Imposing stricter rules with harsher penalties so that resistance stops quickly","Involving students in setting class norms and giving choices, within clear limits","Letting the class monitor decide everything, since students accept a peer more readily"],"answer":2,"explanation":"Supporting autonomy through participation and choice within clear limits reduces conflict and builds responsibility; having no rules or harsher rules ignores either the need for structure or the need for autonomy.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 10 का एक शिक्षक पाता है कि विद्यार्थी बिना चर्चा के थोपे गए नियमों का विरोध करते हैं। किशोरों की स्वायत्तता की बढ़ती आवश्यकता को पूरा करते हुए व्यवस्था बनाए रखने के लिए कौन-सा अभ्यास सबसे उपयुक्त है?","optionsHi":["कक्षा से सारे नियम हटा देना ताकि विद्यार्थी पूरी तरह विश्वसनीय महसूस करें","कड़े दंडों के साथ और कठोर नियम थोपना ताकि विरोध जल्दी रुके","विद्यार्थियों को कक्षा के मानदंड तय करने में शामिल करना और स्पष्ट सीमाओं के भीतर विकल्प देना","कक्षा-मॉनिटर को सब कुछ तय करने देना, क्योंकि विद्यार्थी किसी साथी को अधिक सहजता से स्वीकारते हैं"],"explanationHi":"स्पष्ट सीमाओं के भीतर सहभागिता और विकल्प द्वारा स्वायत्तता का समर्थन टकराव घटाता और उत्तरदायित्व बनाता है; कोई नियम न होना या कठोर नियम होना संरचना की आवश्यकता या स्वायत्तता की आवश्यकता में से किसी एक की उपेक्षा करता है।"},
  {"id":"cdp-child-development-1208","question":"Which of these statements about adolescence are correct? I. The capacity for abstract and hypothetical thinking emerges. II. The peer group becomes more important. III. All adolescents necessarily pass through severe emotional turmoil. IV. The search for a personal identity becomes central.","options":["I, II and III only","I, II and IV only","II and IV only","I, II, III and IV"],"answer":1,"explanation":"Abstract thought, stronger peer ties and identity formation are characteristic; severe turmoil is not universal, so III is false.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"किशोरावस्था के बारे में इनमें से कौन-से कथन सही हैं? I. अमूर्त और परिकल्पनात्मक चिंतन की क्षमता उभरती है। II. समवयस्क समूह अधिक महत्त्वपूर्ण हो जाता है। III. सभी किशोर अनिवार्य रूप से गंभीर भावनात्मक उथल-पुथल से गुज़रते हैं। IV. व्यक्तिगत पहचान की खोज केंद्रीय हो जाती है।","optionsHi":["केवल I, II और III","केवल I, II और IV","केवल II और IV","I, II, III और IV"],"explanationHi":"अमूर्त चिंतन, सशक्त साथी-संबंध और पहचान-निर्माण इसकी विशेषताएँ हैं; गंभीर उथल-पुथल सार्वभौमिक नहीं है, इसलिए III असत्य है।"},
  {"id":"cdp-child-development-1209","question":"Assertion (A): Adolescents often argue with parents and teachers about rules they used to accept. Reason (R): Their developing ability to think hypothetically lets them imagine alternatives and notice inconsistencies in adults’ reasoning.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Formal operational thinking enables adolescents to question existing rules by imagining how things could be; R explains A.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"अभिकथन (A): किशोर प्रायः माता-पिता और शिक्षकों से उन नियमों पर बहस करते हैं जिन्हें वे पहले स्वीकार करते थे। कारण (R): परिकल्पनात्मक रूप से सोचने की उनकी विकसित होती क्षमता उन्हें विकल्पों की कल्पना करने और वयस्कों के तर्कों में असंगतियाँ देखने देती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"औपचारिक संक्रियात्मक चिंतन किशोरों को यह कल्पना करके कि चीज़ें कैसी हो सकती हैं, मौजूदा नियमों पर प्रश्न उठाने में सक्षम बनाता है; R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-1210","question":"Assertion (A): The imaginary audience makes many young adolescents intensely self-conscious. Reason (R): Young adolescents are unable to think about other people’s thoughts at all.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Adolescents CAN think about others’ thoughts; the error is assuming others are as focused on them as they are on themselves. So A is true but R is false.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): काल्पनिक दर्शक कई छोटे किशोरों को अत्यंत आत्म-सचेत बना देता है। कारण (R): छोटे किशोर दूसरे लोगों के विचारों के बारे में सोचने में बिल्कुल असमर्थ होते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"किशोर दूसरों के विचारों के बारे में सोच सकते हैं; त्रुटि यह मान लेना है कि दूसरे उन पर उतना ही ध्यान केंद्रित कर रहे हैं जितना वे स्वयं पर। इसलिए A सत्य है पर R असत्य।"},
  {"id":"cdp-child-development-1211","question":"A school wants to prevent tobacco and drug use among its Class 8–10 students. Which approach is best supported by evidence?","options":["Showing frightening images and stories once a year, so that the fear itself keeps students away from drugs","Life-skills sessions where students practise refusing offers, with accurate facts about real peer norms","Expelling any student found experimenting, so that others see the cost and stay away","Avoiding the topic altogether so as not to give students ideas they had not thought of"],"answer":1,"explanation":"Programmes that build refusal and decision-making skills and correct exaggerated beliefs about how many peers use substances work better than scare tactics, which adolescents often dismiss through the personal fable.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक विद्यालय अपने कक्षा 8–10 के विद्यार्थियों में तंबाकू और नशीली दवाओं का सेवन रोकना चाहता है। प्रमाणों द्वारा सबसे अच्छी तरह समर्थित दृष्टिकोण कौन-सा है?","optionsHi":["वर्ष में एक बार डरावने चित्र और कहानियाँ दिखाना, ताकि भय ही विद्यार्थियों को नशे से दूर रखे","जीवन-कौशल सत्र जहाँ विद्यार्थी प्रस्तावों को ठुकराने का अभ्यास करें, और समवयस्क मानदंडों के बारे में सटीक तथ्य जानें","प्रयोग करते पाए जाने वाले किसी भी विद्यार्थी को निष्कासित करना, ताकि अन्य कीमत देखें और दूर रहें","विषय से पूरी तरह बचना ताकि विद्यार्थियों को वे विचार न मिलें जो उन्होंने सोचे ही नहीं थे"],"explanationHi":"जो कार्यक्रम इनकार और निर्णय-क्षमता के कौशल बनाते हैं और इस बारे में बढ़ा-चढ़ाकर बनी धारणाओं को सुधारते हैं कि कितने साथी नशा करते हैं, वे डराने वाली युक्तियों से बेहतर काम करते हैं, जिन्हें किशोर प्रायः व्यक्तिगत गाथा से ख़ारिज कर देते हैं।"},
  {"id":"cdp-child-development-1212","question":"A Class 8 student is caught passing notes. Which disciplinary approach is most suitable for an adolescent, given what we know about the imaginary audience?","options":["Read the note aloud to the class so that others learn","Make the student stand outside the class for the rest of the period as a warning","Speak to the student privately, stating the problem clearly and respectfully","Ignore all such incidents in adolescence"],"answer":2,"explanation":"Public humiliation is magnified by adolescents’ sense of being watched and breeds resentment; a private, respectful talk addresses the behaviour while protecting dignity.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 का एक विद्यार्थी पर्चियाँ आगे बढ़ाते पकड़ा जाता है। काल्पनिक दर्शक को देखते हुए, किशोर के लिए कौन-सा अनुशासनात्मक दृष्टिकोण सबसे उपयुक्त है?","optionsHi":["पर्ची कक्षा के सामने पढ़कर सुनाना ताकि दूसरे सीखें","विद्यार्थी को चेतावनी के रूप में शेष कालांश कक्षा के बाहर खड़ा करना","विद्यार्थी से निजी तौर पर बात करना, समस्या को स्पष्ट और सम्मानपूर्वक बताते हुए","किशोरावस्था में ऐसी सभी घटनाओं को अनदेखा करना"],"explanationHi":"किशोरों में देखे जाने का एहसास सार्वजनिक अपमान को कई गुना बढ़ा देता है और आक्रोश पैदा करता है; निजी, सम्मानपूर्ण बातचीत गरिमा की रक्षा करते हुए व्यवहार को संबोधित करती है।"},
  {"id":"cdp-child-development-1213","question":"A Class 9 girl wants to skip physical education during her periods and is embarrassed to tell the male PE teacher. What is the most appropriate school response?","options":["Insist she participate fully like everyone else, without any discussion, so that no exceptions are ever made","Excuse all girls from PE permanently, so that no girl ever has to raise the issue at all","Announce in class that she cannot take part because she is menstruating, so that others understand","Create a private way to communicate, offer suitable options and teach all students facts about menstruation"],"answer":3,"explanation":"Respecting privacy and providing accurate menstrual education removes stigma; announcing it publicly or excluding girls altogether reinforces shame and inequity.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"कक्षा 9 की एक लड़की मासिक धर्म के दौरान शारीरिक शिक्षा छोड़ना चाहती है और पुरुष शारीरिक शिक्षा शिक्षक को बताने में संकोच करती है। विद्यालय की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["बिना किसी चर्चा के उस पर सबकी तरह पूरी तरह भाग लेने पर ज़ोर देना, ताकि कभी कोई अपवाद न हो","सभी लड़कियों को शारीरिक शिक्षा से स्थायी छूट देना, ताकि किसी लड़की को यह मुद्दा उठाना ही न पड़े","कक्षा में घोषणा करना कि वह मासिक धर्म के कारण भाग नहीं ले सकती, ताकि दूसरे समझें","संवाद का एक निजी तरीका बनाना, उपयुक्त विकल्प देना और सभी विद्यार्थियों को मासिक धर्म के बारे में तथ्य सिखाना"],"explanationHi":"गोपनीयता का सम्मान और सटीक मासिक धर्म शिक्षा कलंक को हटाती है; सार्वजनिक घोषणा करना या लड़कियों को पूरी तरह बाहर रखना शर्म और असमानता को पुष्ट करता है।"},
  {"id":"cdp-child-development-1214","question":"Before Class 11 stream selection, a student who loves biology is being pushed by his family to take commerce. What is the most appropriate role for the teacher?","options":["Tell him to obey his parents without question, since they know what is best for him","Decide the stream for him on the basis of his marks, since marks are the most objective guide","Tell the parents they have no right to advise him, since the choice is his alone","Help him weigh his interests and aptitudes and facilitate a discussion with his parents"],"answer":3,"explanation":"Guidance supports informed, self-owned choice: identity achievement needs exploration. The teacher facilitates rather than imposing a decision or setting the student against his family.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 11 में विषय-चयन से पहले, जीव विज्ञान से प्रेम करने वाले एक विद्यार्थी पर उसका परिवार वाणिज्य लेने का दबाव डाल रहा है। शिक्षक की सबसे उपयुक्त भूमिका क्या है?","optionsHi":["उससे कहना कि बिना सवाल अपने माता-पिता की बात माने, क्योंकि वे जानते हैं कि उसके लिए क्या सबसे अच्छा है","उसके अंकों के आधार पर उसके लिए विषय तय करना, क्योंकि अंक सबसे वस्तुनिष्ठ मार्गदर्शक हैं","माता-पिता से कहना कि उन्हें उसे सलाह देने का कोई अधिकार नहीं, क्योंकि चयन केवल उसका है","उसे अपनी रुचियों और अभिक्षमताओं को तौलने में सहायता करना और उसके माता-पिता से चर्चा कराना"],"explanationHi":"मार्गदर्शन सुविज्ञ, स्व-स्वामित्व वाले चयन का समर्थन करता है: पहचान की प्राप्ति के लिए अन्वेषण आवश्यक है। शिक्षक निर्णय थोपने या विद्यार्थी को उसके परिवार के विरुद्ध खड़ा करने के बजाय सुगमकर्ता का कार्य करता है।"},
  {"id":"cdp-child-development-1215","question":"Which change in friendships is most characteristic of adolescence compared with middle childhood?","options":["Friendships become based mainly on sharing toys, games and playing near each other in the lane","Friendships become based more on intimacy, loyalty and sharing of thoughts and feelings","Adolescents stop forming close friendships and rely only on family","Friendships are chosen mainly by parents"],"answer":1,"explanation":"Adolescent friendships centre on self-disclosure, loyalty and emotional support; play-based friendships are typical of younger children.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"मध्य बाल्यावस्था की तुलना में किशोरावस्था में मित्रता में कौन-सा परिवर्तन सबसे विशिष्ट है?","optionsHi":["मित्रता मुख्यतः खिलौने, खेल साझा करने और गली में साथ-साथ खेलने पर आधारित हो जाती है","मित्रता अधिक अंतरंगता, निष्ठा और विचारों-भावनाओं को साझा करने पर आधारित हो जाती है","किशोर घनिष्ठ मित्र बनाना बंद कर देते हैं और केवल परिवार पर निर्भर रहते हैं","मित्र मुख्यतः माता-पिता द्वारा चुने जाते हैं"],"explanationHi":"किशोर मित्रता आत्म-प्रकटीकरण, निष्ठा और भावनात्मक सहयोग पर केंद्रित होती है; खेल-आधारित मित्रता छोटे बच्चों की विशिष्टता है।"},
  {"id":"cdp-child-development-1216","question":"Elkind held that adolescent egocentrism declines by mid-to-late adolescence. Which experience is most likely to help it decline?","options":["Close peer interaction, in which they discover that others are absorbed in their own similar concerns","Isolation from peers for a while, so as to avoid embarrassment and protect self-esteem","Strict rules from adults about how to behave in public, so that self-consciousness fades","Repeated public correction of their behaviour, so that they learn exactly how other people really see them"],"answer":0,"explanation":"Through intimate peer exchange, adolescents learn that others share similar worries and are not constantly watching them, which reduces both the imaginary audience and the personal fable.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एल्किंड मानते थे कि किशोर अहंकेंद्रिता किशोरावस्था के मध्य से अंत तक घटती है। कौन-सा अनुभव इसे घटाने में सबसे अधिक सहायक होने की संभावना रखता है?","optionsHi":["घनिष्ठ समवयस्क अंतःक्रिया, जिसमें वे पाते हैं कि दूसरे अपनी समान चिंताओं में डूबे हैं","कुछ समय के लिए साथियों से अलगाव, ताकि शर्मिंदगी से बचा जाए और आत्म-सम्मान सुरक्षित रहे","सार्वजनिक आचरण पर वयस्कों के कड़े नियम, ताकि आत्म-सजगता मिट जाए","उनके व्यवहार का बार-बार सार्वजनिक सुधार, ताकि वे ठीक-ठीक सीखें कि दूसरे उन्हें वास्तव में कैसे देखते हैं"],"explanationHi":"घनिष्ठ समवयस्क आदान-प्रदान के माध्यम से किशोर सीखते हैं कि दूसरे भी समान चिंताएँ रखते हैं और उन्हें निरंतर नहीं देख रहे, जो काल्पनिक दर्शक और व्यक्तिगत गाथा दोनों को घटाता है।"},
  {"id":"cdp-child-development-1217","question":"Given a pendulum and asked what determines how fast it swings, a Class 9 student changes only the string length while keeping the weight and the push the same, then repeats for each factor. In Piaget’s terms this shows:","options":["Concrete operational trial and error, since he works with real objects only","Hypothetico-deductive reasoning, a mark of formal operational thought","Pre-operational centration","Sensorimotor exploration"],"answer":1,"explanation":"Forming hypotheses and systematically isolating variables is hypothetico-deductive reasoning; concrete operational children tend to vary several factors at once without system.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"एक लोलक दिया गया है और पूछा गया है कि उसके झूलने की गति किससे तय होती है। कक्षा 9 का विद्यार्थी केवल डोरी की लंबाई बदलता है, जबकि भार और धक्का समान रखता है, फिर हर कारक के लिए दोहराता है। पियाजे की शब्दावली में यह दर्शाता है:","optionsHi":["मूर्त संक्रियात्मक प्रयास और त्रुटि, क्योंकि वह केवल वास्तविक वस्तुओं के साथ कार्य करता है","परिकल्पनात्मक-निगमनात्मक तर्कण, जो औपचारिक संक्रियात्मक चिंतन की पहचान है","पूर्व-संक्रियात्मक केंद्रीकरण","संवेदी-गामक अन्वेषण"],"explanationHi":"परिकल्पनाएँ बनाना और चरों को व्यवस्थित रूप से अलग करना परिकल्पनात्मक-निगमनात्मक तर्कण है; मूर्त संक्रियात्मक बच्चे प्रायः व्यवस्था के बिना एक साथ कई कारक बदल देते हैं।"},
  {"id":"cdp-child-development-1218","question":"A child lines up ten pebbles and counts them from left to right, then from right to left, then arranges them in a circle and counts again. Each time she gets ten and exclaims that the number stays the same however she counts. Piaget would call the knowledge she has constructed:","options":["Physical knowledge, abstracted from the properties of the pebbles themselves","Social-conventional knowledge, passed on by adults","Logico-mathematical knowledge, built by reflecting on her own actions","Iconic knowledge, stored as images"],"answer":2,"explanation":"That number is independent of the order of counting is not a property of pebbles; it comes from coordinating her own actions. Piaget called this logico-mathematical knowledge.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"एक बच्ची दस कंकड़ एक पंक्ति में लगाती है और उन्हें बाएँ से दाएँ गिनती है, फिर दाएँ से बाएँ, फिर उन्हें गोले में सजाकर फिर गिनती है। हर बार उसे दस ही मिलता है और वह उत्साह से कहती है कि संख्या वही रहती है चाहे वह जैसे भी गिने। पियाजे उसके द्वारा निर्मित ज्ञान को क्या कहेंगे?","optionsHi":["भौतिक ज्ञान, जो स्वयं कंकड़ों के गुणों से अमूर्त किया गया","सामाजिक-रूढ़िगत ज्ञान, जो वयस्कों द्वारा सौंपा गया","तार्किक-गणितीय ज्ञान, जो अपनी क्रियाओं पर चिंतन से निर्मित हुआ","आइकॉनिक ज्ञान, जो चित्रों के रूप में संचित है"],"explanationHi":"संख्या का गिनती के क्रम से स्वतंत्र होना कंकड़ों का गुण नहीं है; यह उसकी अपनी क्रियाओं के समन्वय से आता है। पियाजे ने इसे तार्किक-गणितीय ज्ञान कहा।"},
  {"id":"cdp-child-development-1219","question":"In Piaget’s classification of knowledge, which of these can a child acquire ONLY by being told by other people?","options":["That a ball rolls but a cube does not","That 5 + 3 always gives the same total as 3 + 5, whatever the objects","That a heavier stone needs more force to lift than a lighter one","That the festival of lights is called ‘Diwali’ in most of India"],"answer":3,"explanation":"Names and customs are social-conventional knowledge, arbitrary and transmitted by others. The rolling and lifting examples are physical knowledge, and commutativity is logico-mathematical.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"पियाजे के ज्ञान-वर्गीकरण में, इनमें से बच्चा क्या केवल दूसरे लोगों द्वारा बताए जाने से ही अर्जित कर सकता है?","optionsHi":["कि गेंद लुढ़कती है पर घन नहीं लुढ़कता","कि 5 + 3 का योग हमेशा 3 + 5 के योग के बराबर आता है, वस्तुएँ चाहे जो हों","कि भारी पत्थर को उठाने में हल्के पत्थर से अधिक बल लगता है","कि प्रकाश-पर्व को भारत के अधिकांश भागों में ‘दीवाली’ कहा जाता है"],"explanationHi":"नाम और रीतियाँ सामाजिक-रूढ़िगत ज्ञान हैं, जो मनमाने होते हैं और दूसरों द्वारा हस्तांतरित किए जाते हैं। लुढ़कने और उठाने के उदाहरण भौतिक ज्ञान हैं, और क्रमविनिमेयता तार्किक-गणितीय है।"},
  {"id":"cdp-child-development-1220","question":"Arrange the sensorimotor substages in Piaget’s order: P. Coordination of secondary circular reactions Q. Primary circular reactions R. Reflexes S. Tertiary circular reactions T. Secondary circular reactions U. Beginnings of mental representation","options":["R, Q, T, P, S, U","R, T, Q, P, S, U","Q, R, T, S, P, U","R, Q, P, T, S, U"],"answer":0,"explanation":"The six substages run from reflexes, through primary, secondary and coordinated secondary reactions, to tertiary reactions and finally mental representation at about 18 to 24 months.","difficulty":"hard","source":"CTET · DSSSB · State TETs","questionHi":"पियाजे के क्रम में संवेदी-गामक उप-अवस्थाओं को व्यवस्थित कीजिए: P. द्वितीयक वृत्तीय अनुक्रियाओं का समन्वय Q. प्राथमिक वृत्तीय अनुक्रियाएँ R. प्रतिवर्त S. तृतीयक वृत्तीय अनुक्रियाएँ T. द्वितीयक वृत्तीय अनुक्रियाएँ U. मानसिक निरूपण का आरंभ","optionsHi":["R, Q, T, P, S, U","R, T, Q, P, S, U","Q, R, T, S, P, U","R, Q, P, T, S, U"],"explanationHi":"छह उप-अवस्थाएँ प्रतिवर्तों से आरंभ होकर प्राथमिक, द्वितीयक और समन्वित द्वितीयक अनुक्रियाओं से होते हुए तृतीयक अनुक्रियाओं तक और अंत में लगभग 18 से 24 माह पर मानसिक निरूपण तक चलती हैं।"},
  {"id":"cdp-child-development-1221","question":"A two-month-old accidentally gets his thumb in his mouth, and then keeps bringing it back to suck again and again. Piaget would classify this as:","options":["A secondary circular reaction","A tertiary circular reaction","Deferred imitation","A primary circular reaction"],"answer":3,"explanation":"Primary circular reactions (about 1 to 4 months) repeat chance actions centred on the infant’s own body. Secondary reactions involve effects on external objects.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"दो माह के एक शिशु का अँगूठा संयोग से मुँह में चला जाता है, और फिर वह उसे बार-बार चूसने के लिए मुँह में लाता रहता है। पियाजे इसे किस श्रेणी में रखेंगे?","optionsHi":["द्वितीयक वृत्तीय अनुक्रिया","तृतीयक वृत्तीय अनुक्रिया","विलंबित अनुकरण","प्राथमिक वृत्तीय अनुक्रिया"],"explanationHi":"प्राथमिक वृत्तीय अनुक्रियाएँ (लगभग 1 से 4 माह) शिशु के अपने शरीर पर केंद्रित संयोगवश हुई क्रियाओं को दोहराती हैं। द्वितीयक अनुक्रियाओं में बाहरी वस्तुओं पर प्रभाव शामिल होते हैं।"},
  {"id":"cdp-child-development-1222","question":"Infants of about 8 to 12 months often squeal with delight when a parent hides her face behind a dupatta and then reappears. In Piaget’s terms, the game is enjoyable at this age mainly because:","options":["The infant has mastered conservation and knows the face stays the same size when hidden","Object permanence is developing, so the infant expects the face to be there and enjoys its return","The infant is showing animism, treating the dupatta as a living thing that moves and hides by itself","The infant is using the symbolic mode, pretending that the dupatta is something else"],"answer":1,"explanation":"Once infants begin to represent objects that are out of sight, the hidden face sets up an expectation that is confirmed on reappearance. Much younger infants do not search for what disappears.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"लगभग 8 से 12 माह के शिशु प्रायः तब खुशी से किलकारी मारते हैं जब माता-पिता अपना चेहरा दुपट्टे के पीछे छिपाकर फिर प्रकट करते हैं। पियाजे की शब्दावली में, इस आयु में यह खेल मुख्यतः क्यों आनंददायक होता है?","optionsHi":["शिशु ने संरक्षण में निपुणता पा ली है और जानता है कि छिपने पर भी चेहरा उसी आकार का रहता है","वस्तु-स्थायित्व विकसित हो रहा है, इसलिए शिशु चेहरे के वहाँ होने की अपेक्षा करता है और उसके लौटने का आनंद लेता है","शिशु जीववाद दिखा रहा है, दुपट्टे को ऐसी सजीव वस्तु मान रहा है जो स्वयं हिलती और छिपती है","शिशु प्रतीकात्मक रूप का उपयोग कर रहा है, मानो दुपट्टा कुछ और हो"],"explanationHi":"जब शिशु दृष्टि से ओझल वस्तुओं का निरूपण करने लगते हैं, तो छिपा चेहरा एक अपेक्षा बनाता है जो पुनः प्रकट होने पर पुष्ट होती है। बहुत छोटे शिशु उस चीज़ को नहीं खोजते जो ओझल हो जाती है।"},
  {"id":"cdp-child-development-1223","question":"Which question in a Class 10 history lesson most clearly calls for formal operational thinking?","options":["‘In which year did the Dandi March take place, and on which date did it reach Dandi?’","‘Name the leader of the Dandi March and list the places where the marchers halted.’","‘If the salt tax had never existed, what other symbol might the movement have chosen, and why?’","‘Draw a map showing the full route of the march from Sabarmati Ashram to the sea coast at Dandi.’"],"answer":2,"explanation":"Reasoning about a counterfactual situation and its consequences requires hypothetical thinking. The other questions call for recall or representation of concrete facts.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 10 के इतिहास पाठ में कौन-सा प्रश्न सबसे स्पष्ट रूप से औपचारिक संक्रियात्मक चिंतन की माँग करता है?","optionsHi":["‘डांडी मार्च किस वर्ष हुआ, और वह किस तिथि को डांडी पहुँचा?’","‘डांडी मार्च के नेता का नाम बताइए और उन स्थानों की सूची बनाइए जहाँ यात्री रुके।’","‘यदि नमक कर कभी न होता, तो आंदोलन कौन-सा अन्य प्रतीक चुन सकता था, और क्यों?’","‘साबरमती आश्रम से डांडी के समुद्र तट तक मार्च का पूरा मार्ग दिखाने वाला मानचित्र बनाइए।’"],"explanationHi":"किसी प्रतिकूल-तथ्यात्मक स्थिति और उसके परिणामों पर तर्क करने के लिए परिकल्पनात्मक चिंतन चाहिए। अन्य प्रश्न ठोस तथ्यों के स्मरण या निरूपण की माँग करते हैं।"},
  {"id":"cdp-child-development-1224","question":"A Class 4 teacher shows that a solid block of ice floats on water, although the children believe all solids sink. The main purpose of such a discrepant event, in Piaget’s terms, is to:","options":["Create disequilibrium that motivates children to revise their schemas","Entertain children with a surprise so that they pay attention to the lesson","Reinforce children’s existing belief","Test their memory of facts"],"answer":0,"explanation":"A surprising result that contradicts a belief upsets equilibrium and pushes children to accommodate. Mere entertainment or recall is not the aim.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 4 का शिक्षक दिखाता है कि बर्फ़ का ठोस टुकड़ा पानी पर तैरता है, जबकि बच्चे मानते हैं कि सभी ठोस डूबते हैं। पियाजे की शब्दावली में ऐसी विसंगतिपूर्ण घटना का मुख्य उद्देश्य है:","optionsHi":["असंतुलन पैदा करना जो बच्चों को अपनी स्कीमा संशोधित करने के लिए प्रेरित करे","बच्चों को आश्चर्य से मनोरंजन देना ताकि वे पाठ पर ध्यान दें","बच्चों की मौजूदा मान्यता को दृढ़ करना","उनकी तथ्यों की स्मृति परखना"],"explanationHi":"किसी मान्यता का खंडन करने वाला आश्चर्यजनक परिणाम साम्यावस्था को बिगाड़ता है और बच्चों को समायोजन की ओर धकेलता है। केवल मनोरंजन या स्मरण उद्देश्य नहीं है।"},
  {"id":"cdp-child-development-1225","question":"A teacher wants to challenge a Class 3 child’s belief that bigger things are always heavier. Which experience is MOST likely to lead to real accommodation?","options":["A lecture on density with formulae, so that she learns the correct scientific idea","Lifting a large inflated balloon and then a small marble-sized stone, and comparing them","Being told clearly that the belief is wrong, and then moving on to the next topic","Watching a video on atomic structure that explains why some materials are heavier than others"],"answer":1,"explanation":"Piaget’s idea is that conflict should be just beyond the child’s schema and directly experienced. A formula or atomic structure is too far from her thinking to be assimilated.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"एक शिक्षक कक्षा 3 की बालिका की इस मान्यता को चुनौती देना चाहता है कि बड़ी चीज़ें हमेशा भारी होती हैं। कौन-सा अनुभव वास्तविक समायोजन की ओर ले जाने की सबसे अधिक संभावना रखता है?","optionsHi":["सूत्रों के साथ घनत्व पर व्याख्यान, ताकि वह सही वैज्ञानिक विचार सीखे","एक बड़ा फुलाया गुब्बारा और फिर एक कंचे जितना छोटा पत्थर उठाना और उनकी तुलना करना","उसे स्पष्ट रूप से बताया जाना कि मान्यता गलत है, और फिर अगले विषय पर बढ़ जाना","परमाणु-संरचना पर एक वीडियो देखना जो समझाता है कि कुछ पदार्थ क्यों भारी होते हैं"],"explanationHi":"पियाजे का विचार है कि विरोध बच्चे की स्कीमा से ठीक आगे का और सीधे अनुभव किया हुआ होना चाहिए। सूत्र या परमाणु-संरचना उसकी सोच से बहुत दूर हैं और आत्मसात नहीं किए जा सकते।"},
  {"id":"cdp-child-development-1226","question":"A teacher trains Class 1 children to answer ‘same’ in conservation tasks. They now say ‘same’, but when asked ‘Why?’ they reply, ‘Because you told us.’ Piaget would say that:","options":["They have truly acquired conservation, since they give the right answer","Conservation is a formal operational skill, so they could not acquire it yet","Their answer without a logical justification does not show real conservation","Training has helped them skip the pre-operational stage altogether"],"answer":2,"explanation":"Piaget counted a child as conserving only if she could justify the answer through identity, reversibility or compensation. A taught verbal response is not an operation.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक शिक्षक कक्षा 1 के बच्चों को संरक्षण कार्यों में ‘समान’ उत्तर देने का प्रशिक्षण देता है। अब वे ‘समान’ कहते हैं, पर ‘क्यों?’ पूछने पर कहते हैं, ‘क्योंकि आपने बताया था।’ पियाजे कहेंगे कि:","optionsHi":["उन्होंने वास्तव में संरक्षण अर्जित कर लिया है, क्योंकि वे सही उत्तर देते हैं","संरक्षण औपचारिक संक्रियात्मक कौशल है, इसलिए वे अभी उसे अर्जित नहीं कर सकते थे","तार्किक औचित्य के बिना उनका उत्तर वास्तविक संरक्षण नहीं दर्शाता","प्रशिक्षण ने उन्हें पूर्व-संक्रियात्मक अवस्था को पूरी तरह लाँघने में मदद की है"],"explanationHi":"पियाजे बच्चे को तभी संरक्षक मानते थे जब वह तादात्म्य, उत्क्रमणीयता या क्षतिपूर्ति के माध्यम से उत्तर का औचित्य दे सके। सिखाया हुआ मौखिक उत्तर संक्रिया नहीं है।"},
  {"id":"cdp-child-development-1227","question":"Which of the following is an ‘operation’ in Piaget’s sense?","options":["Kicking a ball again and again to watch how it rolls away across the floor each time","Calling the moon alive because it seems to move along with the child","Copying a word written on the board accurately into one’s own notebook","Understanding that adding 4 and then taking away 4 brings you back to the start"],"answer":3,"explanation":"Operations are internalised mental actions that can be reversed and form logical systems. Repetitive kicking is sensorimotor, animism is pre-operational, and copying is not an operation.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"निम्नलिखित में से कौन-सा पियाजे के अर्थ में ‘संक्रिया’ है?","optionsHi":["गेंद को बार-बार लात मारकर देखना कि वह हर बार फ़र्श पर कैसे लुढ़कती है","चंद्रमा को सजीव कहना क्योंकि वह बच्चे के साथ चलता प्रतीत होता है","बोर्ड पर लिखे शब्द को अपनी कॉपी में सटीक उतारना","यह समझना कि 4 जोड़ने और फिर 4 घटाने से आप शुरुआत पर लौट आते हैं"],"explanationHi":"संक्रियाएँ आंतरिक मानसिक क्रियाएँ हैं जो उत्क्रमणीय होती हैं और तार्किक प्रणालियाँ बनाती हैं। बार-बार लात मारना संवेदी-गामक है, जीववाद पूर्व-संक्रियात्मक है, और नकल करना संक्रिया नहीं है।"},
  {"id":"cdp-child-development-1228","question":"A Class 9 student says, ‘I notice I always panic in maths tests and make silly mistakes, so I now check my work twice before handing it in.’ This ability to reflect on one’s own thinking develops mainly in Piaget’s:","options":["Pre-operational stage","Formal operational stage","Sensorimotor stage","Concrete operational stage"],"answer":1,"explanation":"Formal operations bring the ability to treat one’s own thoughts as objects of thinking. This underlies the planning and self-monitoring described here.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 9 का एक विद्यार्थी कहता है, ‘मैंने देखा है कि मैं गणित की परीक्षाओं में हमेशा घबरा जाता हूँ और मूर्खतापूर्ण गलतियाँ करता हूँ, इसलिए अब जमा करने से पहले दो बार जाँचता हूँ।’ अपने ही चिंतन पर विचार करने की यह क्षमता मुख्यतः पियाजे की किस अवस्था में विकसित होती है?","optionsHi":["पूर्व-संक्रियात्मक अवस्था","औपचारिक संक्रियात्मक अवस्था","संवेदी-गामक अवस्था","मूर्त संक्रियात्मक अवस्था"],"explanationHi":"औपचारिक संक्रियाएँ अपने विचारों को चिंतन का विषय बनाने की क्षमता लाती हैं। यही यहाँ वर्णित नियोजन और आत्म-निगरानी का आधार है।"},
  {"id":"cdp-child-development-1229","question":"Asked to draw a map of their village, Class 1 children draw the temple, school and their own houses as large separate pictures without correct directions or distances, while Class 5 children place them in their correct positions relative to one another. The difference reflects:","options":["Coordinated spatial representation developing in the concrete operational stage","A decline in creativity and imagination as children grow older and begin to conform","Bruner’s claim that maps are enactive and drawn mainly through movement","The appearance of the personal fable, making each child draw his own world"],"answer":0,"explanation":"Concrete operational children can mentally coordinate positions and distances to form a cognitive map. Young children represent landmarks without integrating their spatial relationships.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"अपने गाँव का नक्शा बनाने को कहने पर, कक्षा 1 के बच्चे मंदिर, विद्यालय और अपने घर बड़े अलग-अलग चित्रों के रूप में बनाते हैं, बिना सही दिशाओं या दूरियों के, जबकि कक्षा 5 के बच्चे उन्हें एक-दूसरे के सापेक्ष सही स्थानों पर रखते हैं। यह अंतर दर्शाता है:","optionsHi":["मूर्त संक्रियात्मक अवस्था में समन्वित स्थानिक निरूपण का विकास","बच्चों के बड़े होने और अनुरूपता अपनाने पर सृजनात्मकता और कल्पना में गिरावट","ब्रूनर का यह दावा कि मानचित्र क्रियात्मक हैं और मुख्यतः गति से बनाए जाते हैं","व्यक्तिगत गाथा का प्रकट होना, जिससे हर बच्चा अपना संसार बनाता है"],"explanationHi":"मूर्त संक्रियात्मक बच्चे संज्ञानात्मक मानचित्र बनाने के लिए स्थितियों और दूरियों का मानसिक समन्वय कर सकते हैं। छोटे बच्चे स्थल-चिह्नों को उनके स्थानिक संबंधों को जोड़े बिना निरूपित करते हैं।"},
  {"id":"cdp-child-development-1230","question":"Two toy cars move along parallel tracks for the same length of time. Car A starts well ahead of car B, and although car B covers a much longer distance, car A stops just ahead of it. A five-year-old says car A was faster ‘because it ended up in front’. This shows:","options":["Mature understanding of speed, distance and time","Formal operational proportional reasoning about distance and time","Centration on the end point, ignoring the starting point and time","Accommodation of the speed schema after seeing the race"],"answer":2,"explanation":"Piaget found that young children judge speed by who finishes ahead, ignoring distance covered and time. This is centration on one striking feature.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"दो खिलौना गाड़ियाँ समान समय तक समानांतर पटरियों पर चलती हैं। गाड़ी A गाड़ी B से बहुत आगे से शुरू होती है, और यद्यपि गाड़ी B बहुत अधिक दूरी तय करती है, गाड़ी A उससे ठीक आगे रुकती है। पाँच वर्ष का बच्चा कहता है कि गाड़ी A तेज़ थी ‘क्योंकि वह आगे पहुँची’। यह दर्शाता है:","optionsHi":["चाल, दूरी और समय की परिपक्व समझ","दूरी और समय का औपचारिक संक्रियात्मक आनुपातिक तर्कण","अंतिम बिंदु पर केंद्रीकरण, आरंभ बिंदु और समय की उपेक्षा","दौड़ देखने के बाद चाल की स्कीमा का समायोजन"],"explanationHi":"पियाजे ने पाया कि छोटे बच्चे चाल का निर्णय इस आधार पर करते हैं कि कौन आगे पहुँचा, तय की गई दूरी और समय की उपेक्षा करते हुए। यह एक प्रभावशाली विशेषता पर केंद्रीकरण है।"},
  {"id":"cdp-child-development-1231","question":"Assertion (A): A teacher should not make fun of a Class 1 child who says the moon follows her home. Reason (R): Such ideas are normal features of pre-operational thinking and give the teacher insight into how the child reasons.","options":["Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"Animistic and egocentric ideas are typical at this age and reveal the child’s reasoning. Ridicule would discourage expression without changing the thinking.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"अभिकथन (A): शिक्षक को कक्षा 1 की उस बालिका का उपहास नहीं करना चाहिए जो कहती है कि चंद्रमा उसके साथ घर तक आता है। कारण (R): ऐसे विचार पूर्व-संक्रियात्मक चिंतन की सामान्य विशेषताएँ हैं और शिक्षक को बच्चे के तर्क करने के ढंग की अंतर्दृष्टि देते हैं।","optionsHi":["A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है","A और R दोनों सत्य हैं, और R, A की सही व्याख्या है"],"explanationHi":"जीववादी और अहंकेंद्रित विचार इस आयु में विशिष्ट हैं और बच्चे के तर्क को प्रकट करते हैं। उपहास चिंतन को बदले बिना अभिव्यक्ति को हतोत्साहित करेगा।"},
  {"id":"cdp-child-development-1232","question":"A teacher wants to introduce the idea of democracy. Which approach best suits Class 4 children according to Piaget?","options":["Ask them to compare democracy with other systems of government in purely abstract terms","Give them a definition of democracy to memorise","Hold a class election for monitor, with voting, counting and discussion of fairness","Discuss hypothetical constitutions for imaginary countries and compare them"],"answer":2,"explanation":"Concrete operational children grasp ideas best through real, familiar experiences. Abstract comparisons and imaginary constitutions call for formal operations.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"एक शिक्षक लोकतंत्र का विचार प्रस्तुत करना चाहता है। पियाजे के अनुसार कक्षा 4 के बच्चों के लिए कौन-सा उपागम सबसे उपयुक्त है?","optionsHi":["उनसे विशुद्ध अमूर्त शब्दों में लोकतंत्र की तुलना अन्य शासन-प्रणालियों से करने को कहना","उन्हें याद करने के लिए लोकतंत्र की परिभाषा देना","कक्षा-नायक के लिए कक्षा चुनाव कराना, जिसमें मतदान, मतगणना और निष्पक्षता पर चर्चा हो","काल्पनिक देशों के काल्पनिक संविधानों पर चर्चा करना और उनकी तुलना करना"],"explanationHi":"मूर्त संक्रियात्मक बच्चे वास्तविक, परिचित अनुभवों से विचारों को सबसे अच्छी तरह समझते हैं। अमूर्त तुलनाओं और काल्पनिक संविधानों के लिए औपचारिक संक्रियाएँ चाहिए।"},
  {"id":"cdp-child-development-1233","question":"Piaget believed that interaction with peers helps young children overcome egocentrism mainly because:","options":["Peers reward each other for correct answers","Peers always know the right answer","Interaction with peers is less important than interaction with adults for decentring","Disagreements with peers force children to notice that others see things differently"],"answer":3,"explanation":"Conflicting views from equals make the child aware of other perspectives, which promotes decentration. Piaget actually saw peers as more useful than adults for this.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"पियाजे मानते थे कि समवयस्कों के साथ अंतःक्रिया छोटे बच्चों को अहंकेंद्रिता से उबरने में मुख्यतः इसलिए सहायता करती है कि:","optionsHi":["साथी सही उत्तरों के लिए एक-दूसरे को पुरस्कृत करते हैं","साथी हमेशा सही उत्तर जानते हैं","विकेंद्रण के लिए वयस्कों के साथ अंतःक्रिया की तुलना में साथियों के साथ अंतःक्रिया कम महत्त्वपूर्ण है","साथियों के साथ असहमतियाँ बच्चों को यह देखने के लिए विवश करती हैं कि दूसरे चीज़ों को भिन्न रूप में देखते हैं"],"explanationHi":"बराबर वालों के परस्पर विरोधी विचार बच्चे को अन्य दृष्टिकोणों से अवगत कराते हैं, जो विकेंद्रण को बढ़ावा देता है। पियाजे वास्तव में इस हेतु साथियों को वयस्कों से अधिक उपयोगी मानते थे।"},
  {"id":"cdp-child-development-1234","question":"Two equal rotis are made; one is cut into eight pieces. An eight-year-old says, ‘It is still the same amount to eat; you only cut it, you didn’t add any.’ The child is reasoning with:","options":["The identity argument, typical of the concrete operational stage","Transductive reasoning","Animism","Hypothetico-deductive logic, testing each piece against a hypothesis"],"answer":0,"explanation":"Noting that nothing was added or taken away is the identity justification for conservation. It typically appears in the concrete operational stage.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"दो समान रोटियाँ बनाई जाती हैं; एक को आठ टुकड़ों में काटा जाता है। आठ वर्ष का बच्चा कहता है, ‘खाने को तो अब भी उतनी ही है; आपने बस काटा है, कुछ जोड़ा तो नहीं।’ बच्चा तर्क कर रहा है:","optionsHi":["तादात्म्य के तर्क से, जो मूर्त संक्रियात्मक अवस्था की विशेषता है","संक्रमणात्मक तर्कण से","जीववाद से","परिकल्पनात्मक-निगमनात्मक तर्क से, प्रत्येक टुकड़े को परिकल्पना के विरुद्ध परखते हुए"],"explanationHi":"यह बताना कि कुछ न जोड़ा गया न हटाया गया, संरक्षण का तादात्म्य-औचित्य है। यह प्रायः मूर्त संक्रियात्मक अवस्था में प्रकट होता है।"},
  {"id":"cdp-child-development-1235","question":"A toddler can find her way from her bedroom to the kitchen without any difficulty, but only years later can she draw a plan of the house. Piaget called the reappearance, at a higher level, of a skill already mastered at a lower level:","options":["Horizontal décalage","Vertical décalage","Assimilation","Equilibrium"],"answer":1,"explanation":"Vertical décalage is the reconstruction of the same content at a higher level of thought, here moving from practical action to representation. Horizontal décalage concerns unevenness within one stage.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"एक नन्ही बालिका बिना कठिनाई के अपने शयनकक्ष से रसोई तक का रास्ता ढूँढ़ लेती है, पर वर्षों बाद ही घर की योजना बना पाती है। पियाजे ने निम्न स्तर पर पहले से निपुण कौशल के उच्च स्तर पर फिर प्रकट होने को क्या कहा?","optionsHi":["क्षैतिज डेकैलाज","ऊर्ध्वाधर डेकैलाज","आत्मसात्करण","साम्यावस्था"],"explanationHi":"ऊर्ध्वाधर डेकैलाज उसी विषयवस्तु का चिंतन के उच्च स्तर पर पुनर्निर्माण है, यहाँ व्यावहारिक क्रिया से निरूपण की ओर जाते हुए। क्षैतिज डेकैलाज एक ही अवस्था के भीतर असमानता से संबंधित है।"},
  {"id":"cdp-child-development-1236","question":"Which instruction style best suits a group of pre-operational children in a Class 1 classroom?","options":["Long verbal explanations of all the rules before any activity, so that nothing is missed","Short steps with demonstrations and objects to handle, checking understanding as they go","Abstract written instructions on the board for children to read and follow","Debates on hypothetical situations"],"answer":1,"explanation":"Pre-operational children have limited attention and rely on perception and action. Short, demonstrated steps with concrete materials match their thinking.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 1 के पूर्व-संक्रियात्मक बच्चों के समूह के लिए कौन-सी निर्देश-शैली सबसे उपयुक्त है?","optionsHi":["किसी गतिविधि से पहले सभी नियमों की लंबी मौखिक व्याख्या, ताकि कुछ छूटे नहीं","प्रदर्शन और हाथ में लेने योग्य वस्तुओं के साथ छोटे चरण, साथ-साथ समझ की जाँच करते हुए","बोर्ड पर अमूर्त लिखित निर्देश जिन्हें बच्चे पढ़ें और पालन करें","काल्पनिक परिस्थितियों पर वाद-विवाद"],"explanationHi":"पूर्व-संक्रियात्मक बच्चों का ध्यान सीमित होता है और वे प्रत्यक्षण और क्रिया पर निर्भर करते हैं। ठोस सामग्री के साथ प्रदर्शित छोटे चरण उनके चिंतन से मेल खाते हैं।"},
  {"id":"cdp-child-development-1237","question":"How many of these statements are correct according to Piaget? I. Schemas exist even in infants, in the form of action patterns such as sucking and grasping. II. Assimilation changes existing schemas, while accommodation leaves them unchanged. III. Adaptation includes both assimilation and accommodation. IV. Organisation and adaptation are lifelong functions, while stages change.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are correct. Statement II reverses the terms: accommodation changes schemas, while assimilation fits new experience into existing ones.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"पियाजे के अनुसार इनमें से कितने कथन सही हैं? I. स्कीमाएँ शिशुओं में भी मौजूद होती हैं, चूसने और पकड़ने जैसे क्रिया-प्रतिरूपों के रूप में। II. आत्मसात्करण मौजूदा स्कीमाओं को बदलता है, जबकि समायोजन उन्हें अपरिवर्तित छोड़ता है। III. अनुकूलन में आत्मसात्करण और समायोजन दोनों शामिल हैं। IV. संगठन और अनुकूलन आजीवन प्रकार्य हैं, जबकि अवस्थाएँ बदलती हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"I, III और IV सही हैं। कथन II शब्दों को उलट देता है: समायोजन स्कीमाओं को बदलता है, जबकि आत्मसात्करण नए अनुभव को मौजूदा स्कीमाओं में बैठाता है।"},
  {"id":"cdp-child-development-1238","question":"A Class 6 student treats the letter in ‘a + b = b + a’ as standing for one particular number and cannot see that it holds for all numbers. In Piaget’s terms, the difficulty mainly arises because:","options":["Seeing letters as general variables needs formal operational thinking, which is only beginning now","The student is still in the sensorimotor stage and cannot use symbols at all","The student lacks object permanence, so the letter seems to stand for a hidden object","Algebra is purely social-conventional knowledge, so the meaning of the letters must simply be told to him"],"answer":0,"explanation":"Treating a symbol as standing for any number is an abstract generalisation typical of formal operations. Many students at 11 to 12 are still in transition, so concrete examples help.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 6 का विद्यार्थी ‘a + b = b + a’ में अक्षर को किसी एक विशेष संख्या का प्रतिनिधि मानता है और नहीं देख पाता कि यह सभी संख्याओं के लिए सत्य है। पियाजे की शब्दावली में कठिनाई मुख्यतः इसलिए उत्पन्न होती है कि:","optionsHi":["अक्षरों को सामान्य चर के रूप में देखने के लिए औपचारिक संक्रियात्मक चिंतन चाहिए, जो अभी आरंभ ही हो रहा है","विद्यार्थी अभी संवेदी-गामक अवस्था में है और प्रतीकों का बिल्कुल उपयोग नहीं कर सकता","विद्यार्थी में वस्तु-स्थायित्व नहीं है, इसलिए अक्षर किसी छिपी वस्तु का प्रतिनिधि लगता है","बीजगणित पूर्णतः सामाजिक-रूढ़िगत ज्ञान है, इसलिए अक्षरों का अर्थ उसे बस बता दिया जाना चाहिए"],"explanationHi":"किसी प्रतीक को किसी भी संख्या का प्रतिनिधि मानना औपचारिक संक्रियाओं की विशिष्ट अमूर्त सामान्यीकरण क्षमता है। 11 से 12 वर्ष के अनेक विद्यार्थी अभी संक्रमण में हैं, इसलिए ठोस उदाहरण सहायक होते हैं।"},
  {"id":"cdp-child-development-1239","question":"A Class 2 child shown a picture puzzle can find the hidden animals by looking carefully at details, but when asked how many legs all the animals have together, she counts each animal separately and loses track. Which teaching support is best suited to her stage?","options":["Ask her to imagine a formula for the total and apply it in her head","Let her mark each animal’s legs with counters and group them","Tell her the answer and move on to the next puzzle","Give her a timed test on multiplication tables to build speed with groups"],"answer":1,"explanation":"Concrete markers let her keep track physically and see the grouping, matching her need for concrete support. A formula is too abstract and a timed test adds pressure without understanding.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 2 की एक बालिका, जिसे चित्र-पहेली दिखाई गई है, ब्योरों को ध्यान से देखकर छिपे पशु ढूँढ़ सकती है, पर जब पूछा जाता है कि सभी पशुओं के कुल कितने पैर हैं, तो वह हर पशु को अलग-अलग गिनती है और हिसाब खो देती है। उसकी अवस्था के अनुकूल कौन-सी शिक्षण-सहायता सबसे उपयुक्त है?","optionsHi":["उससे कुल के लिए सूत्र की कल्पना करने और उसे मन में लागू करने को कहना","उसे हर पशु के पैर गिनतियों (काउंटरों) से चिह्नित करने और समूह बनाने देना","उसे उत्तर बता देना और अगली पहेली पर बढ़ जाना","समूहों के साथ गति बढ़ाने के लिए उसे पहाड़ों का समयबद्ध परीक्षण देना"],"explanationHi":"ठोस चिह्नक उसे भौतिक रूप से हिसाब रखने और समूहन देखने देते हैं, जो ठोस सहायता की उसकी आवश्यकता से मेल खाता है। सूत्र बहुत अमूर्त है, और समयबद्ध परीक्षण समझ के बिना दबाव जोड़ता है।"},
  {"id":"cdp-child-development-1240","question":"Which statement about object permanence is in line with Piaget’s account?","options":["It is present at birth, as shown when newborns follow a moving face with their eyes","It develops only in the concrete operational stage, along with the conservation of number and length","It is learnt only through reinforcement by parents during games such as peek-a-boo","It develops across the sensorimotor period, complete when the child can infer unseen moves"],"answer":3,"explanation":"Piaget saw object permanence developing across the sensorimotor substages, completed when the child can imagine where an object went even without seeing it move, around 18 to 24 months.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"वस्तु-स्थायित्व के बारे में कौन-सा कथन पियाजे के विवरण के अनुरूप है?","optionsHi":["यह जन्म से मौजूद है, जैसा तब दिखता है जब नवजात आँखों से किसी गतिमान चेहरे का पीछा करते हैं","यह केवल मूर्त संक्रियात्मक अवस्था में विकसित होता है, संख्या और लंबाई के संरक्षण के साथ","यह केवल लुका-छिपी जैसे खेलों में माता-पिता द्वारा पुनर्बलन से सीखा जाता है","यह संवेदी-गामक काल में विकसित होता है, और तब पूर्ण होता है जब बच्चा अदृश्य गतियों का अनुमान लगा सके"],"explanationHi":"पियाजे वस्तु-स्थायित्व को संवेदी-गामक उप-अवस्थाओं में विकसित होता मानते थे, जो तब पूर्ण होता है जब बच्चा बिना देखे भी कल्पना कर सके कि वस्तु कहाँ गई, लगभग 18 से 24 माह पर।"},
  {"id":"cdp-child-development-1241","question":"Piaget believed that when an adult teaches a child something too early, the adult may keep the child from inventing it herself. Which classroom practice best reflects this concern?","options":["Giving children problems to explore before showing them the standard method","Starting every lesson with the formula and worked examples, then practice","Asking children to memorise results before doing the experiments themselves","Discouraging questions until the end of the year"],"answer":0,"explanation":"Piaget valued the child’s own construction of knowledge; letting children explore first gives them the chance to invent methods. Showing the formula first replaces their thinking.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"पियाजे मानते थे कि जब कोई वयस्क बच्चे को कुछ बहुत जल्दी सिखा देता है, तो वह बच्चे को उसे स्वयं खोजने से रोक सकता है। कौन-सा कक्षा-अभ्यास इस चिंता को सबसे अच्छी तरह दर्शाता है?","optionsHi":["मानक विधि दिखाने से पहले बच्चों को समस्याएँ अन्वेषण के लिए देना","हर पाठ को सूत्र और हल किए उदाहरणों से शुरू करना, फिर अभ्यास","बच्चों को स्वयं प्रयोग करने से पहले परिणाम याद करने को कहना","वर्ष के अंत तक प्रश्न पूछने को हतोत्साहित करना"],"explanationHi":"पियाजे बच्चे द्वारा स्वयं ज्ञान-निर्माण को महत्त्व देते थे; बच्चों को पहले अन्वेषण करने देना उन्हें विधियाँ खोजने का अवसर देता है। पहले सूत्र दिखाना उनके चिंतन का स्थान ले लेता है।"},
  {"id":"cdp-child-development-1242","question":"Assertion (A): A child who has reached the concrete operational stage may still fail a task that requires conservation of weight. Reason (R): Piaget held that all conservation tasks are mastered at the same moment.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Different conservations appear at different ages even within the concrete stage (horizontal décalage), so A is true. R is false because Piaget did not claim they all arrive together.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"अभिकथन (A): मूर्त संक्रियात्मक अवस्था तक पहुँचा बच्चा फिर भी ऐसे कार्य में असफल हो सकता है जिसमें भार का संरक्षण चाहिए। कारण (R): पियाजे मानते थे कि सभी संरक्षण कार्य एक ही क्षण में अर्जित हो जाते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"भिन्न संरक्षण मूर्त अवस्था के भीतर भी भिन्न आयु में प्रकट होते हैं (क्षैतिज डेकैलाज), इसलिए A सत्य है। R असत्य है क्योंकि पियाजे ने यह दावा नहीं किया कि वे सब साथ-साथ आते हैं।"},
  {"id":"cdp-child-development-1243","question":"Salma, aged 11, had never been to school. Under the RTE Act she is admitted to Class 5 with special training. She turns 14 while studying in Class 7. What is her position under the Act?","options":["Her right ends at 14, and the school may charge her fees for Classes 7 and 8 from then on","She must leave the school and join open schooling, since the Act covers only children aged 6 to 14","She stays entitled to free education till she completes elementary education, even after 14","She must be moved back to Class 5 to repeat the years she missed before her admission"],"answer":2,"explanation":"Section 4 provides that a child admitted to an age-appropriate class is entitled to free education till the completion of elementary education even after 14; the right does not stop mid-course.","difficulty":"very-hard","source":"CTET · UPTET · REET","questionHi":"11 वर्ष की सलमा कभी विद्यालय नहीं गई थी। RTE अधिनियम के अंतर्गत उसे विशेष प्रशिक्षण के साथ कक्षा 5 में प्रवेश दिया जाता है। कक्षा 7 में पढ़ते हुए वह 14 वर्ष की हो जाती है। अधिनियम के अंतर्गत उसकी स्थिति क्या है?","optionsHi":["उसका अधिकार 14 पर समाप्त हो जाता है, और तब से विद्यालय कक्षा 7 और 8 के लिए उससे शुल्क ले सकता है","उसे विद्यालय छोड़कर मुक्त विद्यालयी शिक्षा में जाना होगा, क्योंकि अधिनियम केवल 6 से 14 वर्ष के बच्चों को कवर करता है","14 के बाद भी वह प्रारंभिक शिक्षा पूरी होने तक निःशुल्क शिक्षा की पात्र रहती है","उसे प्रवेश से पहले छूटे वर्षों को दोहराने के लिए वापस कक्षा 5 में भेजा जाना चाहिए"],"explanationHi":"धारा 4 प्रावधान करती है कि आयु-उपयुक्त कक्षा में प्रवेश पाने वाला बच्चा 14 के बाद भी प्रारंभिक शिक्षा पूरी होने तक निःशुल्क शिक्षा का पात्र है; अधिकार बीच में नहीं रुकता।"},
  {"id":"cdp-child-development-1244","question":"A migrant worker’s seven-year-old son arrives in Pune in November without a birth certificate. The local government school says it cannot admit him because he has no proof of age and admissions closed in July. Under the RTE Act:","options":["Neither reason is valid: lack of age proof or a late request cannot bar admission","The school is right on both counts, as rules on age proof and admission dates protect order","He may be admitted only after his family obtains a birth certificate from the authorities","He can be admitted only at the start of the next academic year, in April or July"],"answer":0,"explanation":"Section 14 bars denial of admission for want of age proof, and Section 15 says no child shall be denied admission even if it is sought after the extended admission period.","difficulty":"very-hard","source":"CTET · DSSSB PRT","questionHi":"एक प्रवासी मज़दूर का सात वर्ष का पुत्र नवंबर में बिना जन्म प्रमाणपत्र के पुणे आता है। स्थानीय सरकारी विद्यालय कहता है कि वह उसे प्रवेश नहीं दे सकता क्योंकि उसके पास आयु-प्रमाण नहीं है और जुलाई में प्रवेश बंद हो चुके हैं। RTE अधिनियम के अंतर्गत:","optionsHi":["दोनों कारण अमान्य हैं: आयु-प्रमाण का अभाव या विलंबित अनुरोध प्रवेश को नहीं रोक सकता","विद्यालय दोनों बातों पर सही है, क्योंकि आयु-प्रमाण और प्रवेश-तिथियों के नियम व्यवस्था की रक्षा करते हैं","उसे तभी प्रवेश दिया जा सकता है जब उसका परिवार अधिकारियों से जन्म प्रमाणपत्र प्राप्त कर ले","उसे केवल अगले शैक्षणिक वर्ष के आरंभ में, अप्रैल या जुलाई में, प्रवेश दिया जा सकता है"],"explanationHi":"धारा 14 आयु-प्रमाण के अभाव में प्रवेश से इनकार को रोकती है, और धारा 15 कहती है कि विस्तारित प्रवेश-अवधि के बाद माँगे जाने पर भी किसी बच्चे को प्रवेश से वंचित नहीं किया जाएगा।"},
  {"id":"cdp-child-development-1245","question":"A Class 6 teacher calls a student ‘duffer’ in front of the whole class and makes him stand outside for the period, without touching him. A colleague says this is allowed under the RTE Act because no physical punishment was given. This view is:","options":["Correct, because Section 17 bans only physical punishment and says nothing else","Correct, provided the parents have agreed to such measures in writing","Incorrect only if the child is below ten years of age; older children can be disciplined so","Incorrect, because Section 17 prohibits mental harassment as well as physical punishment"],"answer":3,"explanation":"Section 17 says no child shall be subjected to physical punishment or mental harassment; public humiliation and exclusion are forms of harassment, not acceptable alternatives.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"कक्षा 6 का एक शिक्षक पूरी कक्षा के सामने एक विद्यार्थी को ‘मंदबुद्धि’ कहता है और उसे कालांश भर कक्षा के बाहर खड़ा करता है, बिना उसे छुए। एक सहकर्मी कहता है कि RTE अधिनियम के अंतर्गत यह अनुमत है क्योंकि कोई शारीरिक दंड नहीं दिया गया। यह मत है:","optionsHi":["सही, क्योंकि धारा 17 केवल शारीरिक दंड पर रोक लगाती है और अन्य कुछ नहीं कहती","सही, यदि अभिभावकों ने ऐसे उपायों के लिए लिखित सहमति दी हो","केवल तभी गलत जब बच्चा दस वर्ष से छोटा हो; बड़े बच्चों को ऐसे अनुशासित किया जा सकता है","गलत, क्योंकि धारा 17 शारीरिक दंड के साथ-साथ मानसिक उत्पीड़न को भी प्रतिबंधित करती है"],"explanationHi":"धारा 17 कहती है कि किसी बच्चे को शारीरिक दंड या मानसिक उत्पीड़न नहीं दिया जाएगा; सार्वजनिक अपमान और बहिष्कार उत्पीड़न के रूप हैं, स्वीकार्य विकल्प नहीं।"},
  {"id":"cdp-child-development-1246","question":"Under Section 17 of the RTE Act, a teacher who contravenes the ban on physical punishment and mental harassment of children is:","options":["Dismissed automatically, without any inquiry","Liable to disciplinary action under the service rules applicable to him or her","Exempt if the act was meant to improve discipline","Liable only to pay compensation to the child’s parents, not to any service action"],"answer":1,"explanation":"Section 17(2) makes the contravention punishable through disciplinary action under the applicable service rules; good intentions are no defence.","difficulty":"hard","source":"CTET · UPTET","questionHi":"RTE अधिनियम की धारा 17 के अंतर्गत, जो शिक्षक बच्चों के शारीरिक दंड और मानसिक उत्पीड़न पर रोक का उल्लंघन करता है, वह है:","optionsHi":["बिना किसी जाँच के स्वतः बर्खास्त","अपने पर लागू सेवा नियमों के अंतर्गत अनुशासनात्मक कार्रवाई के लिए उत्तरदायी","छूट-प्राप्त, यदि कार्य अनुशासन सुधारने के लिए था","केवल बच्चे के अभिभावकों को क्षतिपूर्ति देने के लिए उत्तरदायी, किसी सेवा-कार्रवाई के लिए नहीं"],"explanationHi":"धारा 17(2) उल्लंघन को लागू सेवा नियमों के अंतर्गत अनुशासनात्मक कार्रवाई द्वारा दंडनीय बनाती है; अच्छी मंशा कोई बचाव नहीं है।"},
  {"id":"cdp-child-development-1247","question":"Assertion (A): Supporters of the no-detention provision argued that holding children back increases dropouts without improving learning. Reason (R): The no-detention provision meant that children would not be assessed at all.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"No detention was paired with continuous and comprehensive evaluation, so children were to be assessed all the time; R confuses ‘no failing’ with ‘no assessment’.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"अभिकथन (A): अनुत्तीर्ण न करने (नो-डिटेंशन) के प्रावधान के समर्थकों ने तर्क दिया कि बच्चों को रोक देने से अधिगम सुधरे बिना विद्यालय छोड़ने वाले बढ़ते हैं। कारण (R): नो-डिटेंशन प्रावधान का अर्थ था कि बच्चों का कोई आकलन ही नहीं होगा।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"नो-डिटेंशन को सतत एवं व्यापक मूल्यांकन के साथ जोड़ा गया था, इसलिए बच्चों का आकलन निरंतर होना था; R ‘अनुत्तीर्ण न करने’ को ‘आकलन न करने’ से भ्रमित करता है।"},
  {"id":"cdp-child-development-1248","question":"Which argument was made by critics of the original no-detention provision of the RTE Act?","options":["Detention lowers dropout among poor children, because repeating a class helps them catch up with the rest","Holding children back raises their self-esteem, since they then do well among younger classmates","No detention made the RTE Act unconstitutional, because it overrode states’ power over exams","Without effective CCE and remedial help, automatic promotion let many reach Class 8 without basic skills"],"answer":3,"explanation":"Critics blamed weak implementation: with CCE poorly done and no remedial help, children moved up without learning; this debate led to the 2019 amendment allowing states to hold exams in Classes 5 and 8.","difficulty":"hard","source":"CTET · KVS TGT","questionHi":"RTE अधिनियम के मूल नो-डिटेंशन प्रावधान के आलोचकों ने कौन-सा तर्क दिया?","optionsHi":["रोके जाने से गरीब बच्चों में विद्यालय छोड़ना घटता है, क्योंकि कक्षा दोहराने से वे बाकी बच्चों के बराबर आ जाते हैं","रोके जाने से बच्चों का आत्म-सम्मान बढ़ता है, क्योंकि तब वे छोटे सहपाठियों में अच्छा करते हैं","नो-डिटेंशन ने RTE अधिनियम को असंवैधानिक बना दिया, क्योंकि उसने परीक्षाओं पर राज्यों की शक्ति को निरस्त किया","प्रभावी CCE और उपचारात्मक सहायता के बिना, स्वचालित पदोन्नति ने अनेक को बुनियादी कौशलों के बिना कक्षा 8 तक पहुँचा दिया"],"explanationHi":"आलोचकों ने कमज़ोर क्रियान्वयन को दोषी ठहराया: CCE के ख़राब ढंग से होने और उपचारात्मक सहायता के अभाव में बच्चे सीखे बिना ऊपर बढ़ते गए; इस बहस से 2019 का संशोधन आया जिसने राज्यों को कक्षा 5 और 8 में परीक्षाएँ आयोजित करने की अनुमति दी।"},
  {"id":"cdp-child-development-1249","question":"A government upper primary school (Classes 6–8) has 210 students. Applying the RTE norm of at least one teacher for every 35 children at this stage, the minimum number of teachers, not counting the head teacher, is:","options":["3","6","7","9"],"answer":1,"explanation":"Upper primary norm is 35:1, so 210 ÷ 35 = 6 teachers. Using the primary-stage ratio 30:1 gives 7, using the NEP target of 25:1 for disadvantaged areas gives 9, and quoting only the minimum of one teacher each for science-maths, social studies and languages gives 3.","difficulty":"hard","source":"CTET · DSSSB PRT","questionHi":"एक सरकारी उच्च प्राथमिक विद्यालय (कक्षा 6–8) में 210 विद्यार्थी हैं। इस स्तर पर प्रत्येक 35 बच्चों पर कम-से-कम एक शिक्षक के RTE मानक को लागू करते हुए, प्रधानाध्यापक को छोड़कर शिक्षकों की न्यूनतम संख्या है:","optionsHi":["3","6","7","9"],"explanationHi":"उच्च प्राथमिक मानक 35:1 है, इसलिए 210 ÷ 35 = 6 शिक्षक। प्राथमिक-स्तर का अनुपात 30:1 लेने पर 7 आता है, वंचित क्षेत्रों के लिए NEP का लक्ष्य 25:1 लेने पर 9 आता है, और केवल विज्ञान-गणित, सामाजिक अध्ययन तथा भाषाओं के लिए एक-एक शिक्षक का न्यूनतम लेने पर 3 आता है।"},
  {"id":"cdp-child-development-1250","question":"The district office asks primary teachers to: I. help with the decennial population census; II. conduct a household survey for a private company; III. do election duty for the state assembly; IV. do relief work during floods; V. collect electricity bills. Under Section 27 of the RTE Act, teachers may be deployed for:","options":["I, III and IV only","I, II and III only","III and V only","I, III, IV and V"],"answer":0,"explanation":"Section 27 bars deploying teachers for non-educational work except the decennial census, disaster relief and elections to local bodies, state legislatures or Parliament.","difficulty":"very-hard","source":"CTET · UPTET · REET","questionHi":"जिला कार्यालय प्राथमिक शिक्षकों से कहता है कि: I. दशकीय जनगणना में सहायता करें; II. किसी निजी कंपनी के लिए घरेलू सर्वेक्षण करें; III. राज्य विधानसभा के लिए चुनाव-ड्यूटी करें; IV. बाढ़ के दौरान राहत-कार्य करें; V. बिजली के बिल एकत्र करें। RTE अधिनियम की धारा 27 के अंतर्गत शिक्षकों को किसमें लगाया जा सकता है?","optionsHi":["केवल I, III और IV","केवल I, II और III","केवल III और V","I, III, IV और V"],"explanationHi":"धारा 27 शिक्षकों को गैर-शैक्षिक कार्य में लगाने पर रोक लगाती है, सिवाय दशकीय जनगणना, आपदा राहत और स्थानीय निकायों, राज्य विधानमंडलों या संसद के चुनावों के।"},
  {"id":"cdp-child-development-1251","question":"A government school teacher in Lucknow runs paid evening tuition classes for students of his own school, outside school hours. Under the RTE Act this is:","options":["Allowed, because it takes place outside school hours in the teacher's own time","Prohibited, because Section 28 bars teachers from private tuition","Allowed, provided the classes are only for Classes 6–8 and are optional","Prohibited only if the students come from his own section of the class"],"answer":1,"explanation":"Section 28 flatly prohibits teachers from private tuition or private teaching activity; the timing or the class does not matter.","difficulty":"moderate","source":"CTET · State TET","questionHi":"लखनऊ का एक सरकारी विद्यालय शिक्षक अपने ही विद्यालय के विद्यार्थियों के लिए, विद्यालय-समय के बाहर, शुल्क लेकर शाम की ट्यूशन कक्षाएँ चलाता है। RTE अधिनियम के अंतर्गत यह है:","optionsHi":["अनुमत, क्योंकि यह विद्यालय-समय के बाहर शिक्षक के अपने समय में होता है","प्रतिबंधित, क्योंकि धारा 28 शिक्षकों को निजी ट्यूशन से रोकती है","अनुमत, यदि कक्षाएँ केवल कक्षा 6–8 के लिए और वैकल्पिक हों","केवल तब प्रतिबंधित, जब विद्यार्थी उसकी अपनी कक्षा के अनुभाग से आते हों"],"explanationHi":"धारा 28 शिक्षकों को निजी ट्यूशन या निजी शिक्षण गतिविधि से स्पष्ट रूप से रोकती है; समय या कक्षा से कोई अंतर नहीं पड़ता।"},
  {"id":"cdp-child-development-1252","question":"A School Management Committee is being formed under Section 21 of the RTE Act. Which composition meets the Act?","options":["Mostly teachers and local officials, with two parents to represent the community","Three-fourths parents or guardians, but with no requirement for women members","Equal numbers of teachers, local officials and parents, with a woman chairperson","Three-fourths parents, proportionate seats for the disadvantaged, half women"],"answer":3,"explanation":"Section 21 requires at least three-fourths of the SMC to be parents or guardians, proportionate representation for disadvantaged groups and half the members to be women.","difficulty":"very-hard","source":"CTET · DSSSB PRT","questionHi":"RTE अधिनियम की धारा 21 के अंतर्गत विद्यालय प्रबंधन समिति का गठन हो रहा है। कौन-सी संरचना अधिनियम को पूरा करती है?","optionsHi":["अधिकांशतः शिक्षक और स्थानीय अधिकारी, समुदाय के प्रतिनिधित्व के लिए दो अभिभावकों के साथ","तीन-चौथाई अभिभावक या संरक्षक, पर महिला सदस्यों की कोई आवश्यकता नहीं","शिक्षकों, स्थानीय अधिकारियों और अभिभावकों की समान संख्या, महिला अध्यक्ष के साथ","तीन-चौथाई अभिभावक, वंचित वर्गों के लिए आनुपातिक स्थान, आधी महिलाएँ"],"explanationHi":"धारा 21 के अनुसार SMC के कम-से-कम तीन-चौथाई सदस्य अभिभावक या संरक्षक हों, वंचित समूहों का आनुपातिक प्रतिनिधित्व हो और आधे सदस्य महिलाएँ हों।"},
  {"id":"cdp-child-development-1253","question":"Which of these is a function of the School Management Committee under the RTE Act?","options":["Appointing and dismissing the teachers working in the school","Setting the question papers for the Class 10 and 12 board examinations","Monitoring the school's working and preparing the School Development Plan","Fixing the fee structure that parents will pay to the school every year"],"answer":2,"explanation":"The SMC monitors the school, monitors use of grants and prepares the School Development Plan (Sections 21–22); it does not appoint teachers or set papers.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"RTE अधिनियम के अंतर्गत विद्यालय प्रबंधन समिति का कार्य इनमें से कौन-सा है?","optionsHi":["विद्यालय में कार्यरत शिक्षकों की नियुक्ति और बर्खास्तगी","कक्षा 10 और 12 की बोर्ड परीक्षाओं के प्रश्न-पत्र बनाना","विद्यालय के कार्य की निगरानी करना और विद्यालय विकास योजना तैयार करना","माता-पिता द्वारा हर वर्ष विद्यालय को दिया जाने वाला शुल्क-ढाँचा तय करना"],"explanationHi":"SMC विद्यालय की निगरानी करती है, अनुदानों के उपयोग की निगरानी करती है और विद्यालय विकास योजना तैयार करती है (धाराएँ 21–22); वह न शिक्षक नियुक्त करती है, न प्रश्न-पत्र बनाती है।"},
  {"id":"cdp-child-development-1254","question":"Which of these are listed among a teacher’s duties under Section 24 of the RTE Act? I. Maintain regularity and punctuality in attending school. II. Complete the curriculum within the specified time. III. Assess the learning ability of each child and give additional instruction as required. IV. Hold regular meetings with parents and guardians.","options":["I, II, III and IV","I, II and III only","I and IV only","II, III and IV only"],"answer":0,"explanation":"Section 24 includes all four: regularity and punctuality, completing the curriculum, assessing each child and supplementing instruction, and regular meetings with parents.","difficulty":"very-hard","source":"CTET · UPTET","questionHi":"RTE अधिनियम की धारा 24 के अंतर्गत शिक्षक के कर्तव्यों में इनमें से कौन-से सूचीबद्ध हैं? I. विद्यालय आने में नियमितता और समय की पाबंदी बनाए रखना। II. निर्धारित समय में पाठ्यक्रम पूरा करना। III. प्रत्येक बच्चे की अधिगम-क्षमता का आकलन करना और आवश्यकतानुसार अतिरिक्त शिक्षण देना। IV. अभिभावकों और संरक्षकों के साथ नियमित बैठकें करना।","optionsHi":["I, II, III और IV","केवल I, II और III","केवल I और IV","केवल II, III और IV"],"explanationHi":"धारा 24 में चारों शामिल हैं: नियमितता और समय की पाबंदी, पाठ्यक्रम पूरा करना, प्रत्येक बच्चे का आकलन और शिक्षण का पूरक देना, और अभिभावकों के साथ नियमित बैठकें।"},
  {"id":"cdp-child-development-1255","question":"Section 30 of the RTE Act deals with examinations and the completion certificate. Which statement is correct?","options":["No Board exam is required till elementary education is complete, and a certificate is given on completion","Board examinations are compulsory at Classes 5 and 8, and a certificate is given only on passing them","There is a Board examination at Class 8 only, and no certificate is issued on completing elementary school","No assessment of any kind is allowed in school, and a certificate is issued at the time of admission"],"answer":0,"explanation":"Section 30 says no child shall be required to pass a Board examination till completion of elementary education, and every child completing it gets a certificate.","difficulty":"hard","source":"CTET · REET","questionHi":"RTE अधिनियम की धारा 30 परीक्षाओं और पूर्णता प्रमाणपत्र से संबंधित है। कौन-सा कथन सही है?","optionsHi":["प्रारंभिक शिक्षा पूर्ण होने तक कोई बोर्ड परीक्षा आवश्यक नहीं है, और पूर्णता पर प्रमाणपत्र दिया जाता है","कक्षा 5 और 8 में बोर्ड परीक्षाएँ अनिवार्य हैं, और प्रमाणपत्र केवल उन्हें उत्तीर्ण करने पर दिया जाता है","केवल कक्षा 8 में बोर्ड परीक्षा है, और प्रारंभिक विद्यालय पूर्ण करने पर कोई प्रमाणपत्र जारी नहीं होता","विद्यालय में किसी भी प्रकार का आकलन अनुमत नहीं है, और प्रवेश के समय प्रमाणपत्र जारी होता है"],"explanationHi":"धारा 30 कहती है कि प्रारंभिक शिक्षा पूर्ण होने तक किसी बच्चे को बोर्ड परीक्षा उत्तीर्ण करने की आवश्यकता नहीं होगी, और उसे पूरा करने वाले हर बच्चे को प्रमाणपत्र मिलेगा।"},
  {"id":"cdp-child-development-1256","question":"Consider: I. Article 21A was inserted by the 86th Constitutional Amendment Act, 2002. II. The same amendment added a fundamental duty on parents or guardians to provide opportunities for education to their children aged 6 to 14. III. The same amendment recast Article 45 to focus on early childhood care and education for children below six. IV. The RTE Act came into force on 1 April 2010. Which are correct?","options":["I and IV only","I, II and IV only","I, II, III and IV","II and III only"],"answer":2,"explanation":"The 86th Amendment added Article 21A and Article 51A(k) and reworded Article 45 for children under six; the RTE Act, which gives effect to Article 21A, came into force on 1 April 2010.","difficulty":"very-hard","source":"CTET · DSSSB TGT","questionHi":"विचार कीजिए: I. अनुच्छेद 21A 86वें संविधान संशोधन अधिनियम, 2002 द्वारा जोड़ा गया। II. उसी संशोधन ने 6 से 14 वर्ष के अपने बच्चों को शिक्षा के अवसर प्रदान करने का माता-पिता या संरक्षकों पर एक मूल कर्तव्य जोड़ा। III. उसी संशोधन ने अनुच्छेद 45 को छह वर्ष से कम के बच्चों की प्रारंभिक बाल्यावस्था देखभाल और शिक्षा पर केंद्रित करके पुनर्लिखित किया। IV. RTE अधिनियम 1 अप्रैल 2010 को लागू हुआ। कौन-से सही हैं?","optionsHi":["केवल I और IV","केवल I, II और IV","I, II, III और IV","केवल II और III"],"explanationHi":"86वें संशोधन ने अनुच्छेद 21A और अनुच्छेद 51A(k) जोड़े तथा छह वर्ष से कम के बच्चों के लिए अनुच्छेद 45 को पुनः शब्दबद्ध किया; RTE अधिनियम, जो अनुच्छेद 21A को प्रभावी बनाता है, 1 अप्रैल 2010 को लागू हुआ।"},
  {"id":"cdp-child-development-1257","question":"Under Section 12(1)(c), a private unaided school must admit at least 25% of its entry-level class from weaker sections and disadvantaged groups and give them free education. Who bears the cost?","options":["The parents, who pay a reduced fee fixed by the school management committee","The school, permanently from its own funds as a social obligation","The other parents, through a small increase in their own fees","The State, reimbursing per-child cost or the fee, whichever is less"],"answer":3,"explanation":"Section 12(2) provides reimbursement by the State at the per-child expenditure in government schools or the actual fee, whichever is less.","difficulty":"very-hard","source":"CTET · DSSSB PRT","questionHi":"धारा 12(1)(c) के अंतर्गत, निजी गैर-सहायता-प्राप्त विद्यालय को अपनी प्रवेश-स्तर की कक्षा का कम-से-कम 25% कमज़ोर वर्गों और वंचित समूहों से प्रवेश देना होगा और उन्हें निःशुल्क शिक्षा देनी होगी। लागत कौन वहन करता है?","optionsHi":["माता-पिता, जो विद्यालय प्रबंधन समिति द्वारा तय घटा हुआ शुल्क देते हैं","विद्यालय, सामाजिक दायित्व के रूप में अपने कोष से स्थायी रूप से","अन्य अभिभावक, अपने शुल्क में थोड़ी वृद्धि के माध्यम से","राज्य, प्रति-बच्चा लागत या शुल्क, जो भी कम हो, की प्रतिपूर्ति करके"],"explanationHi":"धारा 12(2) राज्य द्वारा सरकारी विद्यालयों में प्रति-बच्चा व्यय या वास्तविक शुल्क, जो भी कम हो, पर प्रतिपूर्ति का प्रावधान करती है।"},
  {"id":"cdp-child-development-1258","question":"A government school says that tuition is free but requires parents to pay a ‘development charge’ without which the child cannot attend. Under Section 3(2) of the RTE Act:","options":["This is allowed, since tuition is free and the charge is only for development, not teaching","Not allowed: no child pays any charge that may prevent completing elementary education","Charges are allowed up to a limit set by the SMC for the upkeep of the school","Only children from below-poverty-line families are exempt from such charges"],"answer":1,"explanation":"‘Free’ under the Act covers not just tuition but any fee, charge or expense that could keep a child from completing elementary education.","difficulty":"hard","source":"CTET · UPTET","questionHi":"एक सरकारी विद्यालय कहता है कि शिक्षण निःशुल्क है पर अभिभावकों से ‘विकास शुल्क’ देने की माँग करता है, जिसके बिना बच्चा उपस्थित नहीं हो सकता। RTE अधिनियम की धारा 3(2) के अंतर्गत:","optionsHi":["यह अनुमत है, क्योंकि शिक्षण निःशुल्क है और शुल्क केवल विकास के लिए है, पढ़ाने के लिए नहीं","अनुमत नहीं: किसी बच्चे से कोई ऐसा शुल्क नहीं लिया जाएगा जो उसे प्रारंभिक शिक्षा पूरी करने से रोक सके","शुल्क विद्यालय के रखरखाव के लिए SMC द्वारा निर्धारित सीमा तक अनुमत हैं","केवल गरीबी रेखा से नीचे के परिवारों के बच्चे ऐसे शुल्कों से मुक्त हैं"],"explanationHi":"अधिनियम के अंतर्गत ‘निःशुल्क’ में केवल शिक्षण नहीं, बल्कि कोई भी शुल्क, प्रभार या व्यय शामिल है जो बच्चे को प्रारंभिक शिक्षा पूरी करने से रोक सके।"},
  {"id":"cdp-child-development-1259","question":"Under the Schedule to the RTE Act, the minimum working days and instructional hours per academic year are:","options":["200 days and 800 hours for primary; 220 days and 1000 hours for upper primary","220 days and 1000 hours for primary; 200 days and 800 hours for upper primary","180 days and 720 hours for both stages","240 days and 1200 hours for both stages"],"answer":0,"explanation":"The Schedule prescribes 200 working days and 800 instructional hours for Classes 1–5 and 220 days and 1000 hours for Classes 6–8; option B swaps the two.","difficulty":"very-hard","source":"CTET · DSSSB PRT","questionHi":"RTE अधिनियम की अनुसूची के अंतर्गत, प्रति शैक्षणिक वर्ष न्यूनतम कार्य-दिवस और अनुदेश-घंटे हैं:","optionsHi":["प्राथमिक के लिए 200 दिन और 800 घंटे; उच्च प्राथमिक के लिए 220 दिन और 1000 घंटे","प्राथमिक के लिए 220 दिन और 1000 घंटे; उच्च प्राथमिक के लिए 200 दिन और 800 घंटे","दोनों स्तरों के लिए 180 दिन और 720 घंटे","दोनों स्तरों के लिए 240 दिन और 1200 घंटे"],"explanationHi":"अनुसूची कक्षा 1–5 के लिए 200 कार्य-दिवस और 800 अनुदेश-घंटे तथा कक्षा 6–8 के लिए 220 दिन और 1000 घंटे निर्धारित करती है; विकल्प B इन दोनों को आपस में बदल देता है।"},
  {"id":"cdp-child-development-1260","question":"A Class 7 student in a private school is caught stealing repeatedly, and the principal wants to expel him. Under the RTE Act, as amended in 2019:","options":["Expulsion is allowed after three written warnings to the child and parents","Expulsion is allowed for serious misconduct with the SMC’s approval","No child can be expelled till completion of elementary education","Expulsion is allowed, but only in private unaided schools"],"answer":2,"explanation":"The 2019 amendment let states hold back children after exams in Classes 5 and 8, but it kept the bar on expelling any child till elementary education is complete.","difficulty":"hard","source":"CTET · KVS TGT","questionHi":"निजी विद्यालय में कक्षा 7 का एक विद्यार्थी बार-बार चोरी करते पकड़ा जाता है, और प्रधानाचार्य उसे निष्कासित करना चाहते हैं। 2019 में संशोधित RTE अधिनियम के अंतर्गत:","optionsHi":["बच्चे और अभिभावकों को तीन लिखित चेतावनियों के बाद निष्कासन अनुमत है","गंभीर कदाचार के लिए SMC की स्वीकृति से निष्कासन अनुमत है","प्रारंभिक शिक्षा पूर्ण होने तक किसी बच्चे को निष्कासित नहीं किया जा सकता","निष्कासन अनुमत है, पर केवल निजी गैर-सहायता-प्राप्त विद्यालयों में"],"explanationHi":"2019 के संशोधन ने राज्यों को कक्षा 5 और 8 में परीक्षा के बाद बच्चों को रोकने की अनुमति दी, पर प्रारंभिक शिक्षा पूर्ण होने तक किसी भी बच्चे को निष्कासित करने पर रोक बनाए रखी।"},
  {"id":"cdp-child-development-1261","question":"Under the RTE Act, which body has been given the task of examining and reviewing the safeguards for children’s rights provided by the Act and recommending measures for their effective implementation?","options":["The NCERT, as the national academic body for school curriculum","The NCTE, as the regulator of teacher education and qualifications","The CBSE, as the board that affiliates and inspects schools","The NCPCR, along with the State Commissions (SCPCRs)"],"answer":3,"explanation":"Section 31 assigns monitoring of the right to education to the NCPCR and the SCPCRs; NCERT and NCTE are academic bodies and CBSE is an examining board.","difficulty":"hard","source":"CTET · UPTET","questionHi":"RTE अधिनियम के अंतर्गत, किस निकाय को अधिनियम द्वारा प्रदत्त बाल अधिकारों के रक्षोपायों की जाँच और समीक्षा करने तथा उनके प्रभावी क्रियान्वयन के उपाय सुझाने का कार्य सौंपा गया है?","optionsHi":["NCERT, विद्यालयी पाठ्यचर्या की राष्ट्रीय शैक्षिक संस्था के रूप में","NCTE, शिक्षक शिक्षा और योग्यताओं के नियामक के रूप में","CBSE, विद्यालयों को संबद्धता देने और निरीक्षण करने वाले बोर्ड के रूप में","NCPCR, राज्य आयोगों (SCPCR) के साथ"],"explanationHi":"धारा 31 शिक्षा के अधिकार की निगरानी NCPCR और SCPCR को सौंपती है; NCERT और NCTE शैक्षिक निकाय हैं और CBSE एक परीक्षा बोर्ड है।"},
  {"id":"cdp-child-development-1262","question":"A child moves from a school in Bihar to one in Delhi. The old school delays issuing the transfer certificate, and the new school refuses admission until it arrives. Under the RTE Act:","options":["The refusal is valid, as the new school needs the certificate for its own records","Delay in the transfer certificate cannot be a ground to delay or deny admission","The child must wait for one term before being admitted in the new school","The child must first pass an entrance test to prove the class level reached"],"answer":1,"explanation":"Section 5 gives the child a right to transfer and says delay in producing the transfer certificate shall not be a ground for delaying or denying admission.","difficulty":"moderate","source":"CTET · DSSSB PRT","questionHi":"एक बच्चा बिहार के विद्यालय से दिल्ली के विद्यालय में जाता है। पुराना विद्यालय स्थानांतरण प्रमाणपत्र जारी करने में देर करता है, और नया विद्यालय उसके आने तक प्रवेश से मना करता है। RTE अधिनियम के अंतर्गत:","optionsHi":["इनकार वैध है, क्योंकि नए विद्यालय को अपने रिकॉर्ड के लिए प्रमाणपत्र चाहिए","स्थानांतरण प्रमाणपत्र में देरी प्रवेश में देरी या इनकार का आधार नहीं हो सकती","बच्चे को नए विद्यालय में प्रवेश से पहले एक सत्र प्रतीक्षा करनी होगी","बच्चे को पहुँची हुई कक्षा का स्तर सिद्ध करने के लिए पहले प्रवेश परीक्षा उत्तीर्ण करनी होगी"],"explanationHi":"धारा 5 बच्चे को स्थानांतरण का अधिकार देती है और कहती है कि स्थानांतरण प्रमाणपत्र प्रस्तुत करने में देरी प्रवेश में देरी या इनकार का आधार नहीं होगी।"},
  {"id":"cdp-child-development-1263","question":"Assertion (A): Under the RTE Act, the medium of instruction must in every case be the child’s mother tongue. Reason (R): Section 29 says the medium of instruction shall, as far as practicable, be in the child’s mother tongue.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"The words ‘as far as practicable’ make the provision a guideline rather than an absolute rule, so A overstates what R actually says.","difficulty":"hard","source":"CTET · REET","questionHi":"अभिकथन (A): RTE अधिनियम के अंतर्गत शिक्षण का माध्यम प्रत्येक स्थिति में बच्चे की मातृभाषा होना चाहिए। कारण (R): धारा 29 कहती है कि शिक्षण का माध्यम, जहाँ तक व्यावहारिक हो, बच्चे की मातृभाषा में होगा।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"‘जहाँ तक व्यावहारिक हो’ शब्द इस प्रावधान को निरपेक्ष नियम के बजाय मार्गदर्शक सिद्धांत बनाते हैं, इसलिए A उसे बढ़ा-चढ़ाकर कहता है जो R वास्तव में कहता है।"},
  {"id":"cdp-child-development-1264","question":"A state wants to recruit Class 1–5 teachers without requiring them to pass a Teacher Eligibility Test. Why does this conflict with the RTE framework?","options":["Because the NCTE, the Section 23 academic authority, made a TET pass a minimum qualification","Because the NCERT alone has the power to recruit teachers for all government schools","Because the RTE Act fixes teachers' salaries and recruitment rules directly in its own Schedule","Because the CBSE conducts all teacher recruitment for Classes 1–5 across India"],"answer":0,"explanation":"Section 23 lets an academic authority notified by the Centre, the NCTE, lay down minimum qualifications, and the NCTE included passing a TET for teachers of Classes 1–8.","difficulty":"hard","source":"CTET · UPTET · REET","questionHi":"एक राज्य कक्षा 1–5 के शिक्षकों की भर्ती शिक्षक पात्रता परीक्षा उत्तीर्ण करने की आवश्यकता के बिना करना चाहता है। यह RTE ढाँचे से क्यों टकराता है?","optionsHi":["क्योंकि NCTE ने, जो धारा 23 का शैक्षिक प्राधिकरण है, TET उत्तीर्ण करना न्यूनतम योग्यता बनाया है","क्योंकि केवल NCERT को सभी सरकारी विद्यालयों के लिए शिक्षक भर्ती करने की शक्ति है","क्योंकि RTE अधिनियम अपनी अनुसूची में शिक्षकों के वेतन और भर्ती-नियम सीधे निर्धारित करता है","क्योंकि CBSE पूरे भारत में कक्षा 1–5 की सारी शिक्षक भर्ती आयोजित करता है"],"explanationHi":"धारा 23 केंद्र द्वारा अधिसूचित शैक्षिक प्राधिकरण, NCTE, को न्यूनतम योग्यताएँ तय करने देती है, और NCTE ने कक्षा 1–8 के शिक्षकों के लिए TET उत्तीर्ण करना शामिल किया।"},
  {"id":"cdp-child-development-1265","question":"Which statement about Section 11 of the RTE Act (pre-school education) is accurate?","options":["It makes pre-school education a fundamental right, enforceable for every child aged 3 to 6","It lets the appropriate government arrange pre-school education for children above three","It bans pre-school classes in government schools to keep the focus on Classes 1–8","It makes Class 1 admission conditional on the child having attended pre-school"],"answer":1,"explanation":"Section 11 is enabling (‘may’), not a justiciable right: it allows governments to provide pre-school education and ECCE for children from three to six years.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT","questionHi":"RTE अधिनियम की धारा 11 (पूर्व-विद्यालयी शिक्षा) के बारे में कौन-सा कथन सटीक है?","optionsHi":["यह पूर्व-विद्यालयी शिक्षा को मौलिक अधिकार बनाती है, जो 3 से 6 वर्ष के हर बच्चे के लिए प्रवर्तनीय है","यह उपयुक्त सरकार को तीन वर्ष से अधिक आयु के बच्चों के लिए पूर्व-विद्यालयी शिक्षा की व्यवस्था करने देती है","यह कक्षा 1–8 पर ध्यान बनाए रखने के लिए सरकारी विद्यालयों में पूर्व-विद्यालयी कक्षाओं पर रोक लगाती है","यह कक्षा 1 के प्रवेश को इस शर्त पर निर्भर बनाती है कि बच्चे ने पूर्व-विद्यालय में उपस्थिति दी हो"],"explanationHi":"धारा 11 सक्षमकारी (‘कर सकती है’) है, न्यायोचित अधिकार नहीं: यह सरकारों को तीन से छह वर्ष के बच्चों के लिए पूर्व-विद्यालयी शिक्षा और ECCE उपलब्ध कराने की अनुमति देती है।"},
  {"id":"cdp-child-development-1266","question":"Which statement best captures what ‘compulsory’ means in the RTE Act?","options":["Parents who do not send their children to school are fined or sent to jail by the state","Children are forced to attend school daily under threat of punishment for any absence","Attendance stays optional for parents, but schools must keep a seat open for each child","The government must ensure admission, attendance and completion for all aged 6 to 14"],"answer":3,"explanation":"Under Section 8, ‘compulsory education’ places the obligation on the government, not a penalty on children or parents.","difficulty":"hard","source":"CTET · State TET","questionHi":"RTE अधिनियम में ‘अनिवार्य’ का अर्थ कौन-सा कथन सबसे अच्छी तरह बताता है?","optionsHi":["जो माता-पिता अपने बच्चों को विद्यालय नहीं भेजते उन पर राज्य जुर्माना लगाता है या उन्हें जेल भेजता है","किसी भी अनुपस्थिति पर दंड की धमकी देकर बच्चों को रोज़ विद्यालय जाने को विवश किया जाता है","माता-पिता के लिए उपस्थिति वैकल्पिक रहती है, पर विद्यालयों को प्रत्येक बच्चे के लिए एक स्थान रिक्त रखना होगा","सरकार को 6 से 14 वर्ष के सभी बच्चों के लिए प्रवेश, उपस्थिति और पूर्णता सुनिश्चित करनी होगी"],"explanationHi":"धारा 8 के अंतर्गत, ‘अनिवार्य शिक्षा’ दायित्व सरकार पर रखती है, बच्चों या माता-पिता पर दंड नहीं।"},
  {"id":"cdp-child-development-1267","question":"A Class 2 child keeps coming late to school. To ‘teach him a lesson’, the teacher plans to make him kneel in the corridor. In keeping with the RTE Act and child-friendly practice, the best course is to:","options":["Make him kneel briefly, as a mild punishment that builds discipline","Mark him absent for the day so that he learns the cost of lateness","Talk with him and his parents to find the cause and solve it together","Report the matter to the police so that the parents take it seriously"],"answer":2,"explanation":"Kneeling is physical punishment banned under Section 17; understanding the cause (distance, chores, illness) and involving parents addresses the problem.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"कक्षा 2 का एक बच्चा विद्यालय देर से आता रहता है। ‘उसे सबक सिखाने’ के लिए शिक्षक उसे गलियारे में घुटनों के बल बैठाने की योजना बनाता है। RTE अधिनियम और बाल-हितैषी अभ्यास के अनुरूप सर्वोत्तम तरीका है:","optionsHi":["उसे थोड़ी देर घुटनों के बल बैठाना, हल्के दंड के रूप में जो अनुशासन बनाता है","उसे उस दिन अनुपस्थित अंकित करना ताकि वह देर से आने की कीमत सीखे","उससे और उसके माता-पिता से बात करके कारण जानना और साथ मिलकर समाधान करना","मामले की पुलिस को रिपोर्ट करना ताकि माता-पिता इसे गंभीरता से लें"],"explanationHi":"घुटनों के बल बैठाना शारीरिक दंड है जिस पर धारा 17 के अंतर्गत रोक है; कारण (दूरी, घरेलू कार्य, बीमारी) समझना और माता-पिता को शामिल करना समस्या को संबोधित करता है।"},
  {"id":"cdp-child-development-1268","question":"While reading that ‘camels can go for days without water’, Class 6 students are asked to stop after each fact and answer, ‘Why would that be true, given what you know?’ Compared with simply reading, this practice tends to:","options":["Slow reading down and so reduce recall, because attention is split between tasks","Improve memory and understanding, as explaining why links facts to prior knowledge","Help only students labelled as auditory learners, who learn best by talking","Cause proactive interference, since earlier facts block the recall of new ones"],"answer":1,"explanation":"Elaborative interrogation and self-explanation make learners connect new facts to prior knowledge, producing deeper processing and better retention.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"‘ऊँट बिना पानी के कई दिन रह सकते हैं’ पढ़ते समय, कक्षा 6 के विद्यार्थियों से कहा जाता है कि हर तथ्य के बाद रुकें और उत्तर दें, ‘जो तुम जानते हो उसके आधार पर यह सच क्यों होगा?’ केवल पढ़ने की तुलना में यह अभ्यास प्रवृत्त करता है:","optionsHi":["पठन को धीमा करके स्मरण घटाने की ओर, क्योंकि ध्यान दो कार्यों में बँट जाता है","स्मृति और समझ को बेहतर बनाने की ओर, क्योंकि ‘क्यों’ समझाना तथ्यों को पूर्व ज्ञान से जोड़ता है","केवल उन विद्यार्थियों की सहायता की ओर जिन्हें श्रवण-अधिगमकर्ता कहा जाता है, जो बोलकर सबसे अच्छा सीखते हैं","अग्रलक्षी व्यतिकरण उत्पन्न करने की ओर, क्योंकि पहले के तथ्य नए के स्मरण को रोकते हैं"],"explanationHi":"विस्तारी प्रश्नोत्तर और स्व-व्याख्या अधिगमकर्ताओं को नए तथ्यों को पूर्व ज्ञान से जोड़ने को प्रेरित करते हैं, जिससे गहन प्रसंस्करण और बेहतर धारण होता है।"},
  {"id":"cdp-child-development-1269","question":"A Class 7 teacher has students practise area, perimeter and volume problems mixed together in each set, rather than one complete set for each type in turn. Pupils find it harder at first. What does research predict?","options":["Mixed practice will give poorer long-term results, because early errors become habits","There will be no difference, since the same number of problems is practised overall","Blocked practice will give better transfer, as each method is mastered before moving on","Mixed practice will give better long-term results, as students learn to pick the method"],"answer":3,"explanation":"Interleaving feels harder and may lower performance during practice, but it improves later performance because learners must discriminate between problem types and choose a strategy.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"कक्षा 7 का एक शिक्षक विद्यार्थियों से क्षेत्रफल, परिमाप और आयतन की समस्याओं का अभ्यास हर प्रकार के लिए पूरा अलग समूह बारी-बारी से कराने के बजाय प्रत्येक सेट में मिलाकर कराता है। छात्रों को आरंभ में यह कठिन लगता है। शोध क्या पूर्वानुमान देता है?","optionsHi":["मिश्रित अभ्यास से दीर्घकालिक परिणाम खराब होंगे, क्योंकि प्रारंभिक त्रुटियाँ आदत बन जाती हैं","कोई अंतर नहीं होगा, क्योंकि कुल मिलाकर समान संख्या में समस्याओं का अभ्यास होता है","खंडित (ब्लॉक्ड) अभ्यास से बेहतर स्थानांतरण होगा, क्योंकि आगे बढ़ने से पहले प्रत्येक विधि में निपुणता आती है","मिश्रित अभ्यास से दीर्घकालिक परिणाम बेहतर होंगे, क्योंकि विद्यार्थी विधि चुनना सीखते हैं"],"explanationHi":"अंतर्ग्रथन (इंटरलीविंग) कठिन लगता है और अभ्यास के दौरान प्रदर्शन घटा सकता है, पर बाद के प्रदर्शन को सुधारता है क्योंकि अधिगमकर्ताओं को समस्या-प्रकारों में भेद करना और रणनीति चुनना होता है।"},
  {"id":"cdp-child-development-1270","question":"Most adults who handle ₹10 coins daily cannot correctly draw what is on either side of one. The best explanation is that:","options":["The details were never properly encoded because they were not attended to","The memory decayed through disuse, since people rarely look closely at coins","Retroactive interference from other coins erased the stored details","They are showing motivated forgetting of details they find unimportant"],"answer":0,"explanation":"We attend only to features needed to use the coin, so the other details never pass into long-term memory: encoding failure, not forgetting of stored information.","difficulty":"hard","source":"CTET · HTET","questionHi":"अधिकांश वयस्क, जो रोज़ ₹10 के सिक्के संभालते हैं, उसके किसी भी पहलू पर क्या बना है, यह सही नहीं बना पाते। सर्वोत्तम व्याख्या यह है कि:","optionsHi":["ब्योरों का कभी ठीक से कूटन नहीं हुआ क्योंकि उन पर ध्यान नहीं दिया गया","स्मृति उपयोग के अभाव में क्षीण हो गई, क्योंकि लोग सिक्कों को शायद ही ध्यान से देखते हैं","अन्य सिक्कों के पश्चलक्षी व्यतिकरण ने संचित ब्योरे मिटा दिए","वे उन ब्योरों का प्रेरित विस्मरण दिखा रहे हैं जिन्हें वे अनावश्यक मानते हैं"],"explanationHi":"हम केवल उन्हीं विशेषताओं पर ध्यान देते हैं जो सिक्के के उपयोग के लिए आवश्यक हैं, इसलिए अन्य ब्योरे दीर्घकालिक स्मृति में पहुँचते ही नहीं: यह कूटन की विफलता है, संचित सूचना का विस्मरण नहीं।"},
  {"id":"cdp-child-development-1271","question":"A teacher writes a list of fifteen words on the board in black, but writes the word ‘volcano’ in large red letters. Later most children recall ‘volcano’. Which memory effect is this?","options":["The serial position effect, as recall depends on where a word sits in the list","Elaborative rehearsal, as a vivid word gets linked to more meaning","The isolation (von Restorff) effect, as one item stands out from the rest","Flashbulb memory, as a striking stimulus leaves a vivid, lasting imprint"],"answer":2,"explanation":"Only ‘volcano’ was made perceptually different, so its recall reflects distinctiveness (von Restorff), not its list position or any extra rehearsal. Flashbulb memory is tempting but refers to vivid memories of emotionally significant events, not one red word in a list.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षक बोर्ड पर पंद्रह शब्दों की सूची काले रंग में लिखता है, पर ‘volcano’ शब्द को बड़े लाल अक्षरों में लिखता है। बाद में अधिकांश बच्चे ‘volcano’ याद रखते हैं। यह कौन-सा स्मृति प्रभाव है?","optionsHi":["क्रमिक स्थिति प्रभाव, क्योंकि स्मरण इस पर निर्भर करता है कि शब्द सूची में कहाँ है","विस्तारी पुनरावृत्ति, क्योंकि प्रभावशाली शब्द अधिक अर्थ से जुड़ जाता है","विलगन (वॉन रेस्टोर्फ़) प्रभाव, क्योंकि एक मद शेष से अलग दिखता है","फ़्लैशबल्ब स्मृति, क्योंकि कोई प्रभावशाली उद्दीपक स्पष्ट, स्थायी छाप छोड़ता है"],"explanationHi":"केवल ‘volcano’ को प्रत्यक्षात्मक रूप से भिन्न बनाया गया था, इसलिए उसका स्मरण विशिष्टता (वॉन रेस्टोर्फ़) को दर्शाता है, सूची में स्थिति या अतिरिक्त पुनरावृत्ति को नहीं। फ़्लैशबल्ब स्मृति आकर्षक विकल्प है, पर वह भावनात्मक रूप से महत्त्वपूर्ण घटनाओं की स्पष्ट स्मृतियों के लिए है, सूची में एक लाल शब्द के लिए नहीं।"},
  {"id":"cdp-child-development-1272","question":"In Bartlett's studies, English participants retold an unfamiliar Native American folk tale several times. Their versions became shorter and changed unfamiliar details into familiar ones. What does this show about memory?","options":["Memory is an exact recording of what was experienced and heard","Memory is reconstructive, shaped by existing schemas and culture","Only short-term memory is affected by the listener's culture","Stories are never remembered beyond a week, whatever their content"],"answer":1,"explanation":"Bartlett showed that remembering is an active reconstruction in which schemas fill in and alter details, so recall bends towards what is familiar to the learner.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"बार्टलेट के अध्ययनों में, अंग्रेज़ प्रतिभागियों ने एक अपरिचित मूल अमेरिकी लोककथा को कई बार दोबारा सुनाया। उनके संस्करण छोटे होते गए और अपरिचित ब्योरे परिचित ब्योरों में बदल गए। यह स्मृति के बारे में क्या दर्शाता है?","optionsHi":["स्मृति जो अनुभव किया और सुना गया उसकी सटीक रिकॉर्डिंग है","स्मृति पुनर्रचनात्मक है, जो मौजूदा स्कीमाओं और संस्कृति से आकार पाती है","केवल अल्पकालिक स्मृति श्रोता की संस्कृति से प्रभावित होती है","कहानियाँ विषय चाहे जो हो, एक सप्ताह के बाद कभी याद नहीं रहतीं"],"explanationHi":"बार्टलेट ने दिखाया कि याद करना एक सक्रिय पुनर्रचना है जिसमें स्कीमाएँ ब्योरे भरती और बदलती हैं, इसलिए स्मरण अधिगमकर्ता के परिचित की ओर झुक जाता है।"},
  {"id":"cdp-child-development-1273","question":"Group A reads a list of word pairs such as ‘hot – cold’. Group B sees ‘hot – c_ _ _’ and must fill in the word. On a later test, Group B recalls more. This is called the:","options":["Serial position effect","Spacing effect","Overjustification effect","Generation effect"],"answer":3,"explanation":"Information that learners produce themselves is remembered better than information they simply read, because generating it requires deeper processing.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"समूह A ‘hot – cold’ जैसे शब्द-युग्मों की सूची पढ़ता है। समूह B ‘hot – c_ _ _’ देखता है और शब्द भरना होता है। बाद के परीक्षण में समूह B अधिक याद रखता है। इसे कहते हैं:","optionsHi":["क्रमिक स्थिति प्रभाव","अंतरालन (स्पेसिंग) प्रभाव","अतिऔचित्य प्रभाव","जनन (जनरेशन) प्रभाव"],"explanationHi":"जो सूचना अधिगमकर्ता स्वयं उत्पन्न करते हैं, वह केवल पढ़ी गई सूचना से बेहतर याद रहती है, क्योंकि उसे उत्पन्न करने में गहरा प्रसंस्करण लगता है।"},
  {"id":"cdp-child-development-1274","question":"A teacher tells a Class 4 child a seven-digit phone number to deliver to the office, and the child is stopped on the way by a friend who chats about a match. On arriving the child has forgotten the number. This happened because:","options":["Short-term memory fades in about 30 seconds without rehearsal, which the chat prevented","Long-term memory was already full, so the new number could not be stored there at all","The number went into procedural memory, which cannot hold digits for long periods","The child probably has a learning disability that affects memory for numbers"],"answer":0,"explanation":"Short-term memory holds unrehearsed information for only around 15–30 seconds; the distracting conversation blocked rehearsal and displaced the digits.","difficulty":"hard","source":"CTET · REET","questionHi":"एक शिक्षक कक्षा 4 के बच्चे को कार्यालय पहुँचाने के लिए सात अंकों का फ़ोन नंबर बताता है, और रास्ते में एक मित्र उसे रोककर किसी मैच के बारे में बातें करता है। पहुँचने पर बच्चा नंबर भूल चुका है। ऐसा इसलिए हुआ क्योंकि:","optionsHi":["अल्पकालिक स्मृति बिना पुनरावृत्ति के लगभग 30 सेकंड में क्षीण हो जाती है, जिसे बातचीत ने रोका","दीर्घकालिक स्मृति पहले ही भर चुकी थी, इसलिए नया नंबर वहाँ संचित हो ही नहीं सका","नंबर प्रक्रियात्मक स्मृति में चला गया, जो अंकों को लंबे समय तक नहीं रख सकती","बच्चे को संभवतः अधिगम अक्षमता है जो अंकों की स्मृति को प्रभावित करती है"],"explanationHi":"अल्पकालिक स्मृति बिना दोहराई सूचना को केवल लगभग 15–30 सेकंड तक रखती है; ध्यान भटकाने वाली बातचीत ने पुनरावृत्ति रोक दी और अंकों को विस्थापित कर दिया।"},
  {"id":"cdp-child-development-1275","question":"A student not paying attention is asked a question and says, ‘Sorry, what?’ and then, a second later, answers correctly before the teacher repeats it. Which memory store made this possible?","options":["Iconic memory, which holds visual images for an instant","Long-term semantic memory, which stores general facts","Echoic memory, which holds sounds for a few seconds","Procedural memory, which stores skills and routines"],"answer":2,"explanation":"Echoic (auditory sensory) memory retains sounds for a few seconds, longer than iconic memory, so a just-missed question can still be recovered if attention is turned to it quickly.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"ध्यान न दे रहे विद्यार्थी से प्रश्न पूछा जाता है और वह कहता है, ‘क्षमा कीजिए, क्या?’ और फिर एक सेकंड बाद, शिक्षक के दोहराने से पहले ही, सही उत्तर देता है। किस स्मृति-भंडार ने यह संभव किया?","optionsHi":["आइकॉनिक स्मृति, जो दृश्य चित्रों को क्षण भर रखती है","दीर्घकालिक अर्थगत स्मृति, जो सामान्य तथ्य संचित करती है","ध्वनि-स्मृति (इकोइक मेमोरी), जो ध्वनियों को कुछ सेकंड तक रखती है","प्रक्रियात्मक स्मृति, जो कौशल और दिनचर्याएँ संचित करती है"],"explanationHi":"ध्वनि-स्मृति (श्रवण संवेदी स्मृति) ध्वनियों को कुछ सेकंड तक रखती है, आइकॉनिक स्मृति से अधिक देर, इसलिए अभी-अभी छूटा प्रश्न फिर भी पुनः प्राप्त किया जा सकता है यदि ध्यान जल्दी उधर लौट आए।"},
  {"id":"cdp-child-development-1276","question":"While looking at a drawing of a cube with no shading, a child notices that it ‘flips’ between two views every few seconds, even when she tries to hold one. What does this illustrate?","options":["Learned helplessness after failing to hold one view","Fluctuation of attention and perceptual organisation","Spontaneous recovery of an earlier extinguished response","Divided attention between two separate tasks at once"],"answer":1,"explanation":"Ambiguous figures such as the Necker cube show that attention and perceptual organisation naturally fluctuate; it is difficult to keep attention fixed on one interpretation.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"बिना छाया वाले घन के रेखाचित्र को देखते हुए, एक बच्ची देखती है कि वह हर कुछ सेकंड में दो दृश्यों के बीच ‘पलट’ जाता है, तब भी जब वह एक को पकड़े रखने की कोशिश करती है। यह क्या दर्शाता है?","optionsHi":["एक दृश्य को पकड़ने में विफल होने के बाद सीखी हुई असहायता","ध्यान और प्रत्यक्षणात्मक संगठन में उतार-चढ़ाव","पहले विलुप्त हुई अनुक्रिया की स्वतः पुनर्प्राप्ति","एक साथ दो अलग कार्यों के बीच विभाजित ध्यान"],"explanationHi":"नेकर घन जैसी द्वि-अर्थी आकृतियाँ दिखाती हैं कि ध्यान और प्रत्यक्षणात्मक संगठन स्वाभाविक रूप से उतार-चढ़ाव करते हैं; ध्यान को एक ही व्याख्या पर टिकाए रखना कठिन होता है।"},
  {"id":"cdp-child-development-1277","question":"A teacher begins a Class 8 lesson by asking, ‘Why can't we see stars in the daytime, though they are still there?’ Several students who were bored start arguing. This opening mainly works by:","options":["Offering an extrinsic reward for whoever answers the question first","Creating fear of failure so that students pay closer attention","Reducing the difficulty of the topic by starting with everyday facts","Creating a knowledge gap that arouses curiosity, an intrinsic motive"],"answer":3,"explanation":"Curiosity arises when learners sense a gap between what they know and what they want to know; a puzzling question sparks intrinsic motivation to resolve it.","difficulty":"moderate","source":"CTET · UPTET","questionHi":"कक्षा 8 का एक शिक्षक पाठ यह पूछकर शुरू करता है, ‘तारे तो दिन में भी वहीं होते हैं, फिर हम उन्हें दिन में क्यों नहीं देख पाते?’ कई ऊबे हुए विद्यार्थी बहस करने लगते हैं। यह आरंभ मुख्यतः किससे काम करता है?","optionsHi":["सबसे पहले प्रश्न का उत्तर देने वाले को बाह्य पुरस्कार देने से","असफलता का भय पैदा करने से ताकि विद्यार्थी अधिक ध्यान दें","रोज़मर्रा के तथ्यों से शुरू करके विषय की कठिनाई घटाने से","ज्ञान-अंतराल पैदा करने से जो जिज्ञासा जगाता है, जो एक आंतरिक अभिप्रेरक है"],"explanationHi":"जिज्ञासा तब उठती है जब अधिगमकर्ता जो जानते हैं और जो जानना चाहते हैं, उसके बीच अंतराल महसूस करते हैं; पहेली-जैसा प्रश्न उसे सुलझाने के लिए आंतरिक अभिप्रेरणा जगाता है।"},
  {"id":"cdp-child-development-1278","question":"According to Weiner, which emotional reactions are likely when a student attributes failure to (a) lack of effort and (b) lack of ability?","options":["(a) Guilt, with resolve to try harder; (b) shame and hopelessness","(a) Shame and hopelessness; (b) guilt, with resolve to try harder","(a) Pride in honesty; (b) gratitude towards the teacher for help","Both lead to the same feeling of anger directed at the teacher"],"answer":0,"explanation":"Effort is controllable, so failure leads to guilt and can energise effort; ability is uncontrollable and stable, so failure brings shame and low expectations.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"वीनर के अनुसार, जब कोई विद्यार्थी असफलता का श्रेय (a) प्रयास की कमी और (b) योग्यता की कमी को देता है, तो कौन-सी भावनात्मक प्रतिक्रियाएँ संभावित हैं?","optionsHi":["(a) अपराध-बोध, अधिक प्रयास करने के संकल्प के साथ; (b) शर्म और निराशा","(a) शर्म और निराशा; (b) अपराध-बोध, अधिक प्रयास करने के संकल्प के साथ","(a) ईमानदारी पर गर्व; (b) सहायता के लिए शिक्षक के प्रति कृतज्ञता","दोनों से एक ही प्रकार का शिक्षक के प्रति निर्देशित क्रोध उत्पन्न होता है"],"explanationHi":"प्रयास नियंत्रणीय है, इसलिए असफलता अपराध-बोध की ओर ले जाती है और प्रयास को ऊर्जा दे सकती है; योग्यता अनियंत्रणीय और स्थिर है, इसलिए असफलता शर्म और निम्न अपेक्षाएँ लाती है।"},
  {"id":"cdp-child-development-1279","question":"Assertion (A): A student who believes she failed because the subject is ‘always too hard for her’ will expect to fail again. Reason (R): In Weiner's theory, the stability dimension of an attribution mainly affects expectations of future success or failure.","options":["A is true but R is false","A is false but R is true","Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A"],"answer":2,"explanation":"Attributing an outcome to a stable cause leads one to expect the same outcome in future; unstable causes allow expectations to change. R explains A.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): जो विद्यार्थी मानती है कि वह इसलिए असफल हुई क्योंकि विषय ‘उसके लिए हमेशा बहुत कठिन’ है, वह फिर से असफल होने की अपेक्षा करेगी। कारण (R): वीनर के सिद्धांत में, कारणारोपण का स्थिरता आयाम मुख्यतः भविष्य की सफलता या असफलता की अपेक्षाओं को प्रभावित करता है।","optionsHi":["A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है"],"explanationHi":"किसी परिणाम का श्रेय स्थिर कारण को देने से भविष्य में वही परिणाम अपेक्षित होता है; अस्थिर कारण अपेक्षाओं को बदलने देते हैं। R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-1280","question":"Varun, in Class 10, keeps painting and taking part in art camps although his parents warn it will not help his marks; he says that through art he feels he is becoming the person he wants to be. In Maslow's terms, he is driven mainly by:","options":["Safety needs, seeking a secure future","Physiological needs for rest and relief","Esteem needs, seeking praise from others","The need for self-actualisation"],"answer":3,"explanation":"Self-actualisation is the growth need to fulfil one's potential. Varun's motive is personal growth through art, not marks or outside recognition.","difficulty":"moderate","source":"CTET · REET","questionHi":"कक्षा 10 का वरुण चित्रकारी करता और कला शिविरों में भाग लेता रहता है, यद्यपि उसके माता-पिता चेताते हैं कि इससे उसके अंकों में मदद नहीं होगी; वह कहता है कि कला के माध्यम से उसे लगता है कि वह वह व्यक्ति बन रहा है जो वह बनना चाहता है। मैस्लो की शब्दावली में, वह मुख्यतः प्रेरित है:","optionsHi":["सुरक्षा आवश्यकताओं से, सुरक्षित भविष्य चाहते हुए","विश्राम और राहत की शारीरिक आवश्यकताओं से","सम्मान आवश्यकताओं से, दूसरों से प्रशंसा चाहते हुए","आत्म-सिद्धि की आवश्यकता से"],"explanationHi":"आत्म-सिद्धि अपनी क्षमता को पूर्ण करने की वृद्धि-आवश्यकता है। वरुण का उद्देश्य कला के माध्यम से व्यक्तिगत विकास है, अंक या बाहरी मान्यता नहीं।"},
  {"id":"cdp-child-development-1281","question":"A teacher lavishly praises a Class 8 student for solving a very easy sum, while giving only brief comments to others who solve hard ones. What unintended message might the student draw?","options":["That he is the most able student in the class, as he gets the most praise","That the teacher thinks he has low ability, as he is praised for an easy task","That effort is unimportant, since praise comes regardless of how hard he tries","That the teacher simply prefers easy sums to hard ones in the classroom"],"answer":1,"explanation":"Attribution research shows that praise for success on easy tasks can signal that the teacher expected little of the student, lowering his view of his own ability.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक शिक्षक कक्षा 8 के विद्यार्थी की बहुत आसान योग हल करने पर खुलकर प्रशंसा करता है, जबकि कठिन योग हल करने वाले अन्य विद्यार्थियों को केवल संक्षिप्त टिप्पणी देता है। विद्यार्थी कौन-सा अनपेक्षित संदेश ग्रहण कर सकता है?","optionsHi":["कि वह कक्षा का सबसे योग्य विद्यार्थी है, क्योंकि उसे सबसे अधिक प्रशंसा मिलती है","कि शिक्षक उसकी योग्यता कम समझता है, क्योंकि उसे आसान कार्य के लिए सराहा जाता है","कि प्रयास महत्त्वहीन है, क्योंकि वह कितना भी प्रयास करे, प्रशंसा मिलती है","कि शिक्षक को कक्षा में कठिन योगों की तुलना में आसान योग पसंद हैं"],"explanationHi":"कारणारोपण शोध दिखाता है कि आसान कार्यों में सफलता की प्रशंसा यह संकेत दे सकती है कि शिक्षक को विद्यार्थी से कम अपेक्षा थी, जिससे उसकी अपनी योग्यता की धारणा घटती है।"},
  {"id":"cdp-child-development-1282","question":"Neel deliberately does not prepare for an important test and tells friends he stayed up watching a film. If he fails, he can blame lack of study rather than lack of ability. This strategy is called:","options":["Self-handicapping to protect one's sense of self-worth","Mastery goal orientation, focusing on learning over marks","Learned helplessness after repeated failures in tests","Self-actualisation through choosing his own priorities"],"answer":0,"explanation":"Self-handicapping creates an excuse in advance so that failure is not blamed on low ability, a self-worth protection strategy (Covington) linked to fear of failure.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"नील जानबूझकर एक महत्त्वपूर्ण परीक्षा की तैयारी नहीं करता और मित्रों से कहता है कि वह रात भर फ़िल्म देखता रहा। यदि वह असफल हो, तो वह योग्यता की कमी के बजाय पढ़ाई की कमी को दोष दे सकता है। इस रणनीति को कहते हैं:","optionsHi":["स्व-बाधा (सेल्फ़-हैंडिकैपिंग), जो अपने आत्म-मूल्य की रक्षा करती है","निपुणता लक्ष्य-अभिमुखता, जो अंकों से अधिक सीखने पर ध्यान देती है","परीक्षाओं में बार-बार असफलता के बाद सीखी हुई असहायता","अपनी प्राथमिकताएँ चुनकर आत्म-सिद्धि"],"explanationHi":"स्व-बाधा पहले से बहाना बना देती है ताकि असफलता का दोष कम योग्यता पर न डाला जाए; यह आत्म-मूल्य की रक्षा की रणनीति है (कोविंग्टन) जो असफलता के भय से जुड़ी है।"},
  {"id":"cdp-child-development-1283","question":"Which of these statements about extrinsic motivation are correct? I. It can help students begin tasks that they do not yet find interesting. II. It always destroys intrinsic motivation. III. Over time some extrinsically motivated behaviour can become valued by the learner as important to him. IV. Informational feedback is a form of external input that can support intrinsic motivation.","options":["I and II only","II and IV only","I, III and IV only","I, II, III and IV"],"answer":2,"explanation":"Extrinsic motivation is not always harmful: it can start engagement, behaviour can become internalised, and informational feedback supports competence. Statement II is too absolute.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"बाह्य अभिप्रेरणा के बारे में इनमें से कौन-से कथन सही हैं? I. यह विद्यार्थियों को ऐसे कार्य शुरू करने में सहायता कर सकती है जो उन्हें अभी रोचक नहीं लगते। II. यह सदैव आंतरिक अभिप्रेरणा को नष्ट कर देती है। III. समय के साथ कुछ बाह्य रूप से प्रेरित व्यवहार अधिगमकर्ता द्वारा स्वयं के लिए महत्त्वपूर्ण माना जाने लगता है। IV. सूचनात्मक प्रतिक्रिया बाह्य निवेश का एक रूप है जो आंतरिक अभिप्रेरणा को सहारा दे सकती है।","optionsHi":["केवल I और II","केवल II और IV","केवल I, III और IV","I, II, III और IV"],"explanationHi":"बाह्य अभिप्रेरणा सदैव हानिकारक नहीं होती: वह संलग्नता शुरू कर सकती है, व्यवहार आत्मसात हो सकता है, और सूचनात्मक प्रतिक्रिया सक्षमता को सहारा देती है। कथन II अत्यधिक निरपेक्ष है।"},
  {"id":"cdp-child-development-1284","question":"After a poor result, Simran says, ‘The teacher just doesn't like me, so she gives me low marks; there's no point trying.’ In Rotter's terms she shows:","options":["An internal locus of control","High self-efficacy","A mastery orientation","An external locus of control"],"answer":3,"explanation":"An external locus of control means believing outcomes are controlled by outside forces such as others or luck, which reduces effort; an internal locus links outcomes to one's own actions.","difficulty":"hard","source":"CTET · HTET","questionHi":"खराब परिणाम के बाद सिमरन कहती है, ‘शिक्षिका को बस मैं पसंद नहीं हूँ, इसलिए वे मुझे कम अंक देती हैं; प्रयास करने का कोई लाभ नहीं।’ रॉटर की शब्दावली में वह दर्शाती है:","optionsHi":["आंतरिक नियंत्रण-स्थल","उच्च आत्म-प्रभावकारिता","निपुणता-अभिमुखता","बाह्य नियंत्रण-स्थल"],"explanationHi":"बाह्य नियंत्रण-स्थल का अर्थ है यह मानना कि परिणाम दूसरों या भाग्य जैसी बाहरी शक्तियों से नियंत्रित होते हैं, जो प्रयास घटाता है; आंतरिक नियंत्रण-स्थल परिणामों को अपनी क्रियाओं से जोड़ता है।"},
  {"id":"cdp-child-development-1285","question":"A teacher introduces percentages to cricket-loving Class 7 students by asking them to calculate players' strike rates and team win percentages from recent matches. Which motivational principle is she using?","options":["Making the task relevant to students' interests, raising its value","Negative reinforcement, removing boring examples from lessons","Fear of failure, since cricket fans want to avoid looking foolish","Overlearning, by repeating percentage sums with familiar data"],"answer":0,"explanation":"Connecting content to students' interests raises the perceived value of the task, which increases motivation according to expectancy–value theory.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक शिक्षिका क्रिकेट-प्रेमी कक्षा 7 के विद्यार्थियों को हाल के मैचों से खिलाड़ियों की स्ट्राइक रेट और टीम की जीत का प्रतिशत निकालने को कहकर प्रतिशत से परिचित कराती है। वह कौन-सा अभिप्रेरणात्मक सिद्धांत प्रयोग कर रही है?","optionsHi":["कार्य को विद्यार्थियों की रुचियों से प्रासंगिक बनाना, जिससे उसका मूल्य बढ़ता है","नकारात्मक पुनर्बलन, जो पाठों से उबाऊ उदाहरण हटाता है","असफलता का भय, क्योंकि क्रिकेट-प्रेमी मूर्ख दिखने से बचना चाहते हैं","अति-अधिगम, परिचित आँकड़ों के साथ प्रतिशत के योगों को दोहराकर"],"explanationHi":"विषयवस्तु को विद्यार्थियों की रुचियों से जोड़ना कार्य के अनुभूत मूल्य को बढ़ाता है, जो अपेक्षा-मूल्य सिद्धांत के अनुसार अभिप्रेरणा बढ़ाता है।"},
  {"id":"cdp-child-development-1286","question":"Payal repeats a list of new Sanskrit words again and again under her breath without thinking about their meanings. She can say them at the end of the period but forgets most by the next day. Why?","options":["She used elaborative rehearsal, which only helps short-term memory and not long-term","Maintenance rehearsal keeps items active briefly but builds weak long-term memories","Her sensory memory was overloaded by too many new words at once","Repetition causes proactive interference with words learnt the next day"],"answer":1,"explanation":"Mere repetition (maintenance rehearsal) keeps items active; linking them to meaning or other knowledge (elaborative rehearsal) is what supports long-term retention.","difficulty":"hard","source":"CTET · UPTET","questionHi":"पायल नए संस्कृत शब्दों की सूची उनके अर्थों के बारे में सोचे बिना बार-बार धीमे स्वर में दोहराती है। वह कालांश के अंत में उन्हें बोल सकती है पर अगले दिन अधिकांश भूल जाती है। क्यों?","optionsHi":["उसने विस्तारी पुनरावृत्ति की, जो केवल अल्पकालिक स्मृति में सहायक है, दीर्घकालिक में नहीं","अनुरक्षण पुनरावृत्ति मदों को कुछ देर सक्रिय रखती है पर दुर्बल दीर्घकालिक स्मृतियाँ बनाती है","एक साथ बहुत सारे नए शब्दों से उसकी संवेदी स्मृति पर अत्यधिक बोझ पड़ गया","पुनरावृत्ति अगले दिन सीखे जाने वाले शब्दों के साथ अग्रलक्षी व्यतिकरण पैदा करती है"],"explanationHi":"केवल दोहराना (अनुरक्षण पुनरावृत्ति) मदों को सक्रिय रखता है; उन्हें अर्थ या अन्य ज्ञान से जोड़ना (विस्तारी पुनरावृत्ति) दीर्घकालिक धारण को सहारा देता है।"},
  {"id":"cdp-child-development-1287","question":"A teacher gives Class 3 children twenty picture words to remember. One group gets them in random order; the other gets them grouped under ‘fruits’, ‘animals’, ‘tools’ and ‘vehicles’. The grouped list is recalled better because:","options":["Grouped lists are shorter, so there are fewer items to remember","Random order causes the primacy effect, which weakens later recall","Meaningful categories give a structure that aids storage and retrieval","Grouping makes children rely only on iconic memory for the pictures"],"answer":2,"explanation":"Organisation helps memory: category labels act as retrieval cues and help chunk items, so recall improves even though the number of items is the same.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक कक्षा 3 के बच्चों को याद करने के लिए बीस चित्र-शब्द देता है। एक समूह को वे यादृच्छिक क्रम में मिलते हैं; दूसरे को ‘फल’, ‘पशु’, ‘औज़ार’ और ‘वाहन’ के अंतर्गत समूहबद्ध मिलते हैं। समूहबद्ध सूची बेहतर याद रहती है क्योंकि:","optionsHi":["समूहबद्ध सूचियाँ छोटी होती हैं, इसलिए याद रखने के लिए कम मद होते हैं","यादृच्छिक क्रम आद्यता प्रभाव उत्पन्न करता है, जो बाद के स्मरण को कमज़ोर करता है","अर्थपूर्ण श्रेणियाँ एक संरचना देती हैं जो संचयन और पुनर्प्राप्ति में सहायक होती है","समूहीकरण से बच्चे चित्रों के लिए केवल आइकॉनिक स्मृति पर निर्भर करते हैं"],"explanationHi":"संगठन स्मृति में सहायक होता है: श्रेणी-लेबल पुनर्प्राप्ति-संकेत का काम करते हैं और मदों को खंडों में बाँटने में मदद करते हैं, इसलिए मदों की संख्या समान होने पर भी स्मरण बेहतर होता है।"},
  {"id":"cdp-child-development-1288","question":"Information processing research explains improvement in children's memory performance between ages 5 and 12 mainly by:","options":["A sudden increase in the number of brain cells around age 7, adding storage","The disappearance of sensory memory, which reduces distraction","A decline in rehearsal, which frees capacity for other mental work","Faster processing, better strategies, more knowledge and better metacognition"],"answer":3,"explanation":"Older children process faster, use strategies spontaneously, know more (which aids encoding) and monitor their own memory better, all of which improve performance.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"सूचना-प्रसंस्करण शोध 5 और 12 वर्ष की आयु के बीच बच्चों के स्मृति-प्रदर्शन में सुधार की व्याख्या मुख्यतः किससे करता है?","optionsHi":["लगभग 7 वर्ष की आयु में मस्तिष्क-कोशिकाओं की संख्या में अचानक वृद्धि, जो संचयन बढ़ाती है","संवेदी स्मृति का लुप्त हो जाना, जो विकर्षण घटाता है","पुनरावृत्ति में कमी, जो अन्य मानसिक कार्य के लिए क्षमता मुक्त करती है","तेज़ प्रसंस्करण, बेहतर रणनीतियाँ, अधिक ज्ञान और बेहतर अधिसंज्ञान"],"explanationHi":"बड़े बच्चे तेज़ी से प्रसंस्करण करते हैं, रणनीतियों का स्वतः उपयोग करते हैं, अधिक जानते हैं (जो कूटन में सहायक है) और अपनी स्मृति की बेहतर निगरानी करते हैं, ये सब प्रदर्शन सुधारते हैं।"},
  {"id":"cdp-child-development-1289","question":"Ebbinghaus used nonsense syllables such as ‘DAX’ and ‘BOK’ to study memory. Why does a teacher see much slower forgetting of a meaningful story than his curves suggest?","options":["Meaningful material links to existing knowledge, so it is retained much better","Stories are stored only in sensory memory, which does not fade in the same way","His curves apply only to adults, while children forget at a slower rate","Stories are retold so often that they are never forgotten at all"],"answer":0,"explanation":"Ebbinghaus deliberately used meaningless material to exclude prior associations. Meaningful material can be organised and connected to existing schemas, so it is forgotten more slowly.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एबिंगहॉस ने स्मृति के अध्ययन के लिए ‘DAX’ और ‘BOK’ जैसे निरर्थक अक्षर-समूहों का उपयोग किया। एक शिक्षक अर्थपूर्ण कहानी के विस्मरण को उसके वक्रों से सुझाए गए की तुलना में बहुत धीमा क्यों पाता है?","optionsHi":["अर्थपूर्ण सामग्री मौजूदा ज्ञान से जुड़ती है, इसलिए वह कहीं बेहतर याद रहती है","कहानियाँ केवल संवेदी स्मृति में संचित होती हैं, जो उसी तरह क्षीण नहीं होती","उसके वक्र केवल वयस्कों पर लागू होते हैं, जबकि बच्चे धीमी दर से भूलते हैं","कहानियाँ इतनी बार दोहराई जाती हैं कि वे कभी बिल्कुल नहीं भूली जातीं"],"explanationHi":"एबिंगहॉस ने पूर्व साहचर्यों को हटाने के लिए जानबूझकर निरर्थक सामग्री ली। अर्थपूर्ण सामग्री को व्यवस्थित किया और मौजूदा स्कीमाओं से जोड़ा जा सकता है, इसलिए वह धीमे भूली जाती है।"},
  {"id":"cdp-child-development-1290","question":"A Class 6 teacher notices that students drift off mostly in the middle of a long lecture but are alert at its start and end. Which plan best uses principles of attention and memory?","options":["Speak louder throughout so that drifting students are pulled back to the lecture","Insert short recall or pair tasks at intervals to create more ‘beginnings and ends’","Give the whole lecture twice so that the middle part is heard again","Remove the beginning and end to save time for the important middle part"],"answer":1,"explanation":"Attention and recall are highest at the beginning and end of a session; breaking a long lesson into shorter segments with active tasks creates more of these high points.","difficulty":"hard","source":"CTET · DSSSB PRT","questionHi":"कक्षा 6 का शिक्षक देखता है कि लंबे व्याख्यान के बीच में विद्यार्थी अधिकतर ध्यान खो देते हैं, पर आरंभ और अंत में सतर्क रहते हैं। कौन-सी योजना ध्यान और स्मृति के सिद्धांतों का सबसे अच्छा उपयोग करती है?","optionsHi":["पूरे समय ज़ोर से बोलना ताकि भटके विद्यार्थी व्याख्यान में लौट आएँ","अंतराल पर संक्षिप्त स्मरण या जोड़ी-कार्य रखना ताकि अधिक ‘आरंभ और अंत’ बनें","पूरा व्याख्यान दो बार देना ताकि बीच का भाग फिर सुना जाए","महत्त्वपूर्ण बीच के भाग के लिए समय बचाने हेतु आरंभ और अंत हटा देना"],"explanationHi":"ध्यान और स्मरण सत्र के आरंभ और अंत में सबसे अधिक होते हैं; लंबे पाठ को सक्रिय कार्यों के साथ छोटे खंडों में बाँटने से ऐसे अधिक उच्च बिंदु बनते हैं।"},
  {"id":"cdp-child-development-1291","question":"Which practice best helps Class 5 children remember a science lesson for the long term?","options":["Reading the chapter many times in one sitting until it feels familiar","Copying notes neatly from the board and reading them through every night","Highlighting the key lines on each page in bright colours","Short quizzes over later weeks that ask them to recall and explain"],"answer":3,"explanation":"Retrieval practice spaced over time combines the testing effect and the spacing effect, two of the most robust findings on long-term retention; re-reading, copying and highlighting are comparatively weak.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चों को विज्ञान का पाठ लंबे समय तक याद रखने में कौन-सा अभ्यास सबसे अधिक सहायक है?","optionsHi":["अध्याय को एक ही बैठक में कई बार पढ़ना जब तक वह परिचित न लगने लगे","बोर्ड से सफ़ाई से नोट्स उतारना और हर रात उन्हें पढ़ना","हर पृष्ठ की मुख्य पंक्तियों को चटक रंगों से रेखांकित करना","बाद के सप्ताहों में छोटी प्रश्नोत्तरी जिनमें वे याद करें और समझाएँ"],"explanationHi":"समय में फैला पुनर्प्राप्ति-अभ्यास परीक्षण प्रभाव और अंतरालन प्रभाव को जोड़ता है, जो दीर्घकालिक धारण पर दो सबसे सुदृढ़ निष्कर्ष हैं; दोबारा पढ़ना, उतारना और रेखांकित करना तुलनात्मक रूप से कमज़ोर हैं।"},
  {"id":"cdp-child-development-1292","question":"A timetable planner wants to reduce interference in memory for Class 8 students who study in two back-to-back self-study periods. Which pairing is most likely to cause the greatest confusion between the two sets of material?","options":["Geometry theorems followed by a painting activity in the art room","Physical exercise followed by memorising important history dates","Hindi words followed by Marathi words that look very similar","Music practice followed by map work on the states of India"],"answer":2,"explanation":"Interference, both proactive and retroactive, is greatest when the two sets of material are similar; dissimilar activities interfere very little.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक समय-सारणी बनाने वाला कक्षा 8 के उन विद्यार्थियों के लिए स्मृति में व्यतिकरण घटाना चाहता है जो दो लगातार स्व-अध्ययन कालांशों में पढ़ते हैं। कौन-सा जोड़ा दोनों सामग्रियों के बीच सबसे अधिक भ्रम पैदा करने की संभावना रखता है?","optionsHi":["ज्यामिति के प्रमेय, उसके बाद कला-कक्ष में चित्रकला की गतिविधि","शारीरिक व्यायाम, उसके बाद महत्त्वपूर्ण ऐतिहासिक तिथियाँ याद करना","हिंदी के शब्द, उसके बाद मराठी के ऐसे शब्द जो बहुत मिलते-जुलते दिखते हैं","संगीत अभ्यास, उसके बाद भारत के राज्यों का मानचित्र-कार्य"],"explanationHi":"व्यतिकरण, अग्रलक्षी और पश्चलक्षी दोनों, तब सबसे अधिक होता है जब दोनों सामग्रियाँ समान हों; असमान गतिविधियाँ बहुत कम व्यतिकरण करती हैं।"},
  {"id":"cdp-child-development-1293","question":"Match the learning difficulty with a typical classroom sign. 1. Dyslexia 2. Dysgraphia 3. Dyscalculia 4. Dyspraxia; a. Cannot tell whether 15 or 51 is larger and mixes up place value b. Spells words correctly aloud but writes them in cramped, barely legible script c. Struggles with buttons, scissors and catching, and bumps into things d. Reads ‘was’ as ‘saw’ and decodes new words very slowly","options":["1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-a, 4-c","1-d, 2-b, 3-c, 4-a"],"answer":1,"explanation":"Decoding problems point to dyslexia, a gap between oral spelling and handwriting to dysgraphia, number-magnitude confusion to dyscalculia, and general motor clumsiness to dyspraxia.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"अधिगम-कठिनाई का मिलान किसी विशिष्ट कक्षा-संकेत से कीजिए। 1. डिस्लेक्सिया 2. डिसग्राफिया 3. डिस्कैलकुलिया 4. डिस्प्रैक्सिया; a. यह नहीं बता पाता कि 15 या 51 बड़ा है और स्थानीय मान गड़बड़ाता है b. शब्दों की वर्तनी मौखिक रूप से सही बताता है पर उन्हें सिकुड़ी, मुश्किल से पढ़ने योग्य लिखावट में लिखता है c. बटन, कैंची और पकड़ने में संघर्ष करता है और चीज़ों से टकराता है d. ‘was’ को ‘saw’ पढ़ता है और नए शब्दों को बहुत धीमे डिकोड करता है","optionsHi":["1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-a, 4-c","1-d, 2-b, 3-c, 4-a"],"explanationHi":"डिकोडिंग की समस्याएँ डिस्लेक्सिया की ओर, मौखिक वर्तनी और हस्तलेखन के बीच अंतर डिसग्राफिया की ओर, संख्या-परिमाण की उलझन डिस्कैलकुलिया की ओर, और सामान्य गामक अनाड़ीपन डिस्प्रैक्सिया की ओर संकेत करता है।"},
  {"id":"cdp-child-development-1294","question":"Assertion (A): The RPwD Act, 2016 requires educational institutions to detect specific learning disabilities in children at the earliest. Reason (R): Dyslexia is the most common specific learning disability.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both statements are true, but early detection is required because timely support prevents years of failure, not because dyslexia happens to be the most common learning disability.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अभिकथन (A): RPwD अधिनियम, 2016 शैक्षिक संस्थानों से अपेक्षा करता है कि वे बच्चों में विशिष्ट अधिगम अक्षमताओं की जल्द-से-जल्द पहचान करें। कारण (R): डिस्लेक्सिया सबसे आम विशिष्ट अधिगम अक्षमता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों कथन सत्य हैं, पर जल्दी पहचान इसलिए आवश्यक है कि समय पर सहायता वर्षों की असफलता को रोकती है, इसलिए नहीं कि डिस्लेक्सिया सबसे आम अधिगम अक्षमता है।"},
  {"id":"cdp-child-development-1295","question":"Assertion (A): Children with ADHD usually benefit from clear, predictable routines in class. Reason (R): ADHD is caused by a lack of discipline at home.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Structure and routine compensate for weak self-regulation, so A is true; ADHD is a neurodevelopmental condition, not the result of lax parenting, so R is false.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): ADHD वाले बच्चों को प्रायः कक्षा में स्पष्ट, पूर्वानुमेय दिनचर्याओं से लाभ होता है। कारण (R): ADHD घर पर अनुशासन की कमी के कारण होता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"संरचना और दिनचर्या कमज़ोर आत्म-नियमन की क्षतिपूर्ति करती हैं, इसलिए A सत्य है; ADHD एक तंत्रिका-विकासात्मक स्थिति है, ढीले पालन-पोषण का परिणाम नहीं, इसलिए R असत्य है।"},
  {"id":"cdp-child-development-1296","question":"Which of these practices are consistent with Universal Design for Learning? I. Making text-to-speech available to every student who wants it. II. Designing one standard lesson and later preparing separate worksheets only for children with disabilities. III. Offering students options for checking and reflecting on their own progress.","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":2,"explanation":"UDL builds options for all learners into the design, such as text-to-speech and self-assessment; retrofitting separate material after a one-size lesson is the approach UDL aims to replace.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"इनमें से कौन-से अभ्यास अधिगम के लिए सार्वभौमिक अभिकल्प (UDL) के अनुरूप हैं? I. हर उस विद्यार्थी के लिए टेक्स्ट-टू-स्पीच उपलब्ध कराना जो चाहे। II. एक मानक पाठ बनाना और बाद में केवल विकलांग बच्चों के लिए अलग कार्यपत्रक तैयार करना। III. विद्यार्थियों को अपनी प्रगति जाँचने और उस पर विचार करने के विकल्प देना।","optionsHi":["केवल I और II","केवल II और III","केवल I और III","I, II और III"],"explanationHi":"UDL अभिकल्प में ही सभी अधिगमकर्ताओं के लिए विकल्प बनाता है, जैसे टेक्स्ट-टू-स्पीच और स्व-आकलन; सबके लिए एक-जैसे पाठ के बाद अलग सामग्री जोड़ना वह उपागम है जिसे UDL बदलना चाहता है।"},
  {"id":"cdp-child-development-1297","question":"A Class 4 class of 40 includes a child with low vision, a child with ADHD and two newly arrived Odia-speaking children. The teacher is planning a lesson on reading a map of the school. Which plan best reflects Universal Design for Learning?","options":["Explaining clearly from the textbook map and giving a written test at the end to check","Preparing separate worksheets for the four children while the rest follow the textbook","Seating the four children together at the back with a helper so the class is not slowed","A big high-contrast map, a walk-on floor map, gestures and pictures, and an Odia-speaking buddy"],"answer":3,"explanation":"A large high-contrast map, a movement-based floor map, visual explanation and a language buddy give every learner several ways to access and engage with the same goal, which is the heart of UDL.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 4 की 40 बच्चों की कक्षा में अल्प-दृष्टि वाला एक बच्चा, ADHD वाला एक बच्चा और दो नए आए ओड़िया-भाषी बच्चे हैं। शिक्षक विद्यालय का नक्शा पढ़ने पर एक पाठ की योजना बना रहा है। कौन-सी योजना अधिगम के लिए सार्वभौमिक अभिकल्प (UDL) को सबसे अच्छी तरह दर्शाती है?","optionsHi":["पाठ्यपुस्तक के नक्शे से स्पष्ट समझाना और अंत में जाँच के लिए लिखित परीक्षा देना","इन चार बच्चों के लिए अलग कार्यपत्रक तैयार करना जबकि शेष पाठ्यपुस्तक का अनुसरण करें","इन चार बच्चों को एक सहायक के साथ पीछे बैठाना ताकि कक्षा धीमी न हो","बड़ा, उच्च-विपर्यास वाला नक्शा, चलकर देखने योग्य फ़र्श का नक्शा, इशारे और चित्र, और एक ओड़िया-भाषी साथी"],"explanationHi":"बड़ा उच्च-विपर्यास नक्शा, गति-आधारित फ़र्श का नक्शा, दृश्य व्याख्या और भाषा-साथी हर अधिगमकर्ता को एक ही लक्ष्य तक पहुँचने और उससे जुड़ने के कई तरीके देते हैं, जो UDL का सार है।"},
  {"id":"cdp-child-development-1298","question":"Assertion (A): Inclusive education requires that all special schools be closed at once. Reason (R): Inclusion rests on the right of children with disabilities to learn in regular schools with the support they need.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"The right to learn in regular schools with support is the basis of inclusion, but the RPwD Act still lets families choose a special school, and special schools can act as resource centres; so A is false.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अभिकथन (A): समावेशी शिक्षा के लिए सभी विशेष विद्यालयों को तुरंत बंद करना आवश्यक है। कारण (R): समावेशन विकलांग बच्चों के उस अधिकार पर आधारित है कि वे आवश्यक सहायता के साथ सामान्य विद्यालयों में सीखें।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"सहायता के साथ सामान्य विद्यालयों में सीखने का अधिकार समावेशन का आधार है, पर RPwD अधिनियम अब भी परिवारों को विशेष विद्यालय चुनने देता है, और विशेष विद्यालय संसाधन-केंद्र का कार्य कर सकते हैं; इसलिए A असत्य है।"},
  {"id":"cdp-child-development-1299","question":"Which of these are commonly seen in gifted children? I. Uneven development, with thinking far ahead of emotional or physical maturity. II. Intense sensitivity and a strong sense of fairness. III. Being always popular and socially well adjusted.","options":["I and II only","I only","II and III only","I, II and III"],"answer":0,"explanation":"Asynchronous development and emotional intensity are often reported in gifted children; social popularity is not a feature of giftedness, and some gifted children feel isolated.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"प्रतिभाशाली बच्चों में इनमें से क्या प्रायः देखा जाता है? I. असमान विकास, जिसमें चिंतन भावनात्मक या शारीरिक परिपक्वता से बहुत आगे हो। II. तीव्र संवेदनशीलता और निष्पक्षता की प्रबल भावना। III. सदैव लोकप्रिय और सामाजिक रूप से भली-भाँति समायोजित होना।","optionsHi":["केवल I और II","केवल I","केवल II और III","I, II और III"],"explanationHi":"प्रतिभाशाली बच्चों में असमकालिक विकास और भावनात्मक तीव्रता प्रायः बताई जाती है; सामाजिक लोकप्रियता प्रतिभाशालिता की विशेषता नहीं है, और कुछ प्रतिभाशाली बच्चे अलग-थलग महसूस करते हैं।"},
  {"id":"cdp-child-development-1300","question":"Nandini, a very able Class 7 student, has started giving wrong answers on purpose and hiding her scores, because classmates tease her as a ‘know-all’ and say ‘girls who study too much are boring’. What should the teacher do?","options":["Praise her loudly in front of the class every time she does well, to boost her","Value effort and ideas for all, give her challenge discreetly, and tackle the teasing","Ignore it, since her marks are still above average and she will grow out of it","Tell her parents that she is becoming lazy and needs closer watching at home"],"answer":1,"explanation":"Gifted girls often hide ability to fit in; a safe culture that values thinking, discreet challenge and action against teasing let her use her ability without social cost, while loud public praise worsens the teasing.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"नंदिनी, कक्षा 7 की अत्यंत योग्य विद्यार्थी, जानबूझकर गलत उत्तर देने लगी है और अपने अंक छिपाती है, क्योंकि सहपाठी उसे ‘सब कुछ जानने वाली’ कहकर चिढ़ाते हैं और कहते हैं ‘जो लड़कियाँ बहुत पढ़ती हैं वे उबाऊ होती हैं’। शिक्षक को क्या करना चाहिए?","optionsHi":["जब भी वह अच्छा करे, कक्षा के सामने उसकी ज़ोर से प्रशंसा करना, ताकि उसका हौसला बढ़े","सभी के लिए प्रयास और विचारों को महत्त्व देना, उसे चुपचाप चुनौती देना, और चिढ़ाने से निपटना","अनदेखा करना, क्योंकि उसके अंक अब भी औसत से ऊपर हैं और वह इससे उबर जाएगी","उसके माता-पिता को बताना कि वह आलसी हो रही है और घर पर उस पर और निगरानी चाहिए"],"explanationHi":"प्रतिभाशाली लड़कियाँ प्रायः घुलने-मिलने के लिए अपनी योग्यता छिपाती हैं; सोच को महत्त्व देने वाली सुरक्षित संस्कृति, विवेकपूर्ण चुनौती और चिढ़ाने के विरुद्ध कार्रवाई उसे बिना सामाजिक कीमत के अपनी योग्यता का उपयोग करने देते हैं, जबकि ज़ोरदार सार्वजनिक प्रशंसा चिढ़ाना और बढ़ाती है।"},
  {"id":"cdp-child-development-1301","question":"Bobby, a Class 2 child on the autism spectrum, constantly crashes into walls, jumps and seeks tight hugs, and settles down after carrying heavy books to the library. What does this suggest, and what should the teacher do?","options":["He is seeking sensory input; planned movement breaks and ‘heavy work’ jobs can help","He is being deliberately naughty and should lose play time until he learns to behave","He needs to sit still all day, so that he gradually learns self-control","He is bored, so more worksheets will keep his hands and mind busy"],"answer":0,"explanation":"Some autistic children are under-responsive to body sensations and seek strong input; meeting this need through structured movement and heavy work calms them better than restriction.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 2 का ऑटिज़्म स्पेक्ट्रम वाला बच्चा बॉबी लगातार दीवारों से टकराता है, कूदता है और कसकर गले लगना चाहता है, और पुस्तकालय तक भारी किताबें ले जाने के बाद शांत हो जाता है। यह क्या सुझाता है, और शिक्षक को क्या करना चाहिए?","optionsHi":["वह संवेदी निवेश खोज रहा है; नियोजित गति-विराम और ‘भारी काम’ के कार्य सहायक हो सकते हैं","वह जानबूझकर शरारत कर रहा है और जब तक सुधरे उसका खेल का समय छीन लिया जाना चाहिए","उसे पूरे दिन स्थिर बैठे रहना चाहिए, ताकि वह धीरे-धीरे आत्म-नियंत्रण सीखे","वह ऊब गया है, इसलिए और कार्यपत्रक उसके हाथों और मन को व्यस्त रखेंगे"],"explanationHi":"कुछ ऑटिस्टिक बच्चे शारीरिक संवेदनाओं के प्रति कम संवेदी होते हैं और तीव्र निवेश खोजते हैं; संरचित गति और भारी कार्य द्वारा इस आवश्यकता को पूरा करना प्रतिबंध की तुलना में उन्हें बेहतर शांत करता है।"},
  {"id":"cdp-child-development-1302","question":"Gauri, in Class 4, is quiet and well-behaved but often stares out of the window, misses parts of instructions, loses her things and leaves work half done. Teachers call her ‘dreamy’. What should her teacher consider?","options":["That she is lazy and needs stricter supervision and extra homework to build better study habits","That she is gifted and bored, so no action is needed beyond harder work","That she may have inattentive-type attention difficulties needing support and assessment","That she definitely has a hearing loss, since she misses spoken instructions"],"answer":2,"explanation":"Inattentive-type attention difficulties are less visible than hyperactivity and are frequently overlooked, especially in girls; observation, supports and referral are better than labels like ‘lazy’.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 4 की गौरी शांत और सुव्यवहारी है पर प्रायः खिड़की से बाहर घूरती रहती है, निर्देशों के कुछ भाग चूक जाती है, अपना सामान खो देती है और काम अधूरा छोड़ देती है। शिक्षक उसे ‘सपनों में खोई’ कहते हैं। उसकी शिक्षिका को क्या विचार करना चाहिए?","optionsHi":["कि वह आलसी है और बेहतर अध्ययन-आदतें बनाने के लिए उसे कड़ी निगरानी और अतिरिक्त गृहकार्य चाहिए","कि वह प्रतिभाशाली और ऊबी हुई है, इसलिए कठिन कार्य के अलावा किसी कार्रवाई की आवश्यकता नहीं","कि उसे असावधानी-प्रधान ध्यान संबंधी कठिनाइयाँ हो सकती हैं जिनके लिए सहायता और आकलन चाहिए","कि उसे निश्चित रूप से श्रवण-हानि है, क्योंकि वह बोले गए निर्देश चूक जाती है"],"explanationHi":"असावधानी-प्रधान ध्यान कठिनाइयाँ अतिसक्रियता की तुलना में कम दिखती हैं और प्रायः अनदेखी रह जाती हैं, विशेषकर लड़कियों में; ‘आलसी’ जैसे लेबल के बजाय अवलोकन, सहायता और रेफ़रल बेहतर हैं।"},
  {"id":"cdp-child-development-1303","question":"Isha, in Class 5, hears well only with her left ear. The teacher usually teaches from the front of the room. Where should Isha be seated?","options":["At the front, towards the left side of the room as she faces the board","At the back, in the middle of the room, so that she hears the whole class","Next to the window, where the room is quieter and the light is better","At the front, towards the right side of the room as she faces the board"],"answer":3,"explanation":"Sitting at the front on the right side places the teacher and most classmates to her left, towards her better ear; the left side would turn her hearing ear towards the wall.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 5 की ईशा केवल अपने बाएँ कान से अच्छा सुनती है। शिक्षक प्रायः कक्षा के आगे से पढ़ाता है। ईशा को कहाँ बैठाया जाना चाहिए?","optionsHi":["आगे, कक्षा के बाएँ ओर जब वह बोर्ड की ओर मुँह करे","पीछे, कक्षा के बीच में, ताकि वह पूरी कक्षा को सुन सके","खिड़की के पास, जहाँ कमरा अधिक शांत और प्रकाश बेहतर है","आगे, कक्षा के दाएँ ओर जब वह बोर्ड की ओर मुँह करे"],"explanationHi":"आगे दाईं ओर बैठने से शिक्षक और अधिकांश सहपाठी उसके बाएँ ओर, उसके बेहतर कान की दिशा में होते हैं; बाईं ओर बैठने पर उसका सुनने वाला कान दीवार की ओर हो जाता।"},
  {"id":"cdp-child-development-1304","question":"A Class 8 science exam includes a question asking students to label a diagram of the human heart. How should the school adapt this for a blind student?","options":["A tactile (raised) diagram to label, or an equivalent question in words","Skipping the question and giving him full marks so he is not disadvantaged","Skipping the question and giving him zero, as it cannot be answered fairly","Letting a sighted classmate label the diagram and give both of them marks"],"answer":0,"explanation":"Adaptation should test the same learning through an accessible format; free marks, zero marks or a proxy all distort the assessment.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 8 की विज्ञान परीक्षा में एक प्रश्न विद्यार्थियों से मानव हृदय के आरेख पर नाम लिखने को कहता है। विद्यालय को दृष्टिहीन विद्यार्थी के लिए इसे कैसे अनुकूलित करना चाहिए?","optionsHi":["नाम लिखने के लिए स्पर्श-योग्य (उभरा हुआ) आरेख, या शब्दों में समकक्ष प्रश्न","प्रश्न छोड़कर उसे पूरे अंक देना ताकि वह वंचित न हो","प्रश्न छोड़कर उसे शून्य देना, क्योंकि उसका निष्पक्ष उत्तर संभव नहीं","एक दृष्टिमान सहपाठी से आरेख पर नाम लिखवाना और दोनों को अंक देना"],"explanationHi":"अनुकूलन को सुलभ प्रारूप के माध्यम से वही अधिगम परखना चाहिए; मुफ़्त अंक, शून्य अंक या किसी और को माध्यम बनाना आकलन को विकृत करते हैं।"},
  {"id":"cdp-child-development-1305","question":"Assertion (A): A child with a specific learning disability may have average or above-average intelligence. Reason (R): Specific learning disabilities are difficulties in particular processes such as reading or calculation that are not explained by intellectual disability.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because a specific learning disability is defined as a particular processing difficulty not due to low general ability, a child with one can have normal or high intelligence.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"अभिकथन (A): विशिष्ट अधिगम अक्षमता वाले बच्चे की बुद्धि औसत या औसत से ऊपर हो सकती है। कारण (R): विशिष्ट अधिगम अक्षमताएँ पढ़ने या गणना जैसी विशेष प्रक्रियाओं में कठिनाइयाँ हैं जिन्हें बौद्धिक अक्षमता द्वारा नहीं समझाया जा सकता।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"क्योंकि विशिष्ट अधिगम अक्षमता को निम्न सामान्य योग्यता के कारण न होने वाली किसी विशेष प्रसंस्करण कठिनाई के रूप में परिभाषित किया गया है, इसलिए उससे ग्रस्त बच्चे की बुद्धि सामान्य या उच्च हो सकती है।"},
  {"id":"cdp-child-development-1306","question":"Some Class 8 students complain that hostels and scholarships for Scheduled Caste and Scheduled Tribe students are ‘unfair to the rest’. How should the teacher help them understand this?","options":["By agreeing that every student should get exactly the same support, whatever the need","By telling them not to discuss such sensitive topics in school at all","By explaining that such measures aim at equity, offsetting long-standing disadvantage","By saying that these students are less able and so need extra help"],"answer":2,"explanation":"Targeted support corrects historical disadvantage so that opportunity is real, not just formal; framing it as charity for ‘less able’ students reinforces the very stereotype it should remove.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 8 के कुछ विद्यार्थी शिकायत करते हैं कि अनुसूचित जाति और अनुसूचित जनजाति के विद्यार्थियों के लिए छात्रावास और छात्रवृत्तियाँ ‘शेष के लिए अनुचित’ हैं। शिक्षक उन्हें इसे समझने में कैसे सहायता करे?","optionsHi":["यह मानकर कि हर विद्यार्थी को ठीक एक-सी सहायता मिलनी चाहिए, आवश्यकता चाहे जो हो","उनसे कहकर कि विद्यालय में ऐसे संवेदनशील विषयों पर बिल्कुल चर्चा न करें","यह समझाकर कि ऐसे उपाय समता का लक्ष्य रखते हैं, दीर्घकालिक वंचना की भरपाई करते हैं","यह कहकर कि ये विद्यार्थी कम योग्य हैं और इसलिए उन्हें अतिरिक्त सहायता चाहिए"],"explanationHi":"लक्षित सहायता ऐतिहासिक वंचना को सुधारती है ताकि अवसर केवल औपचारिक नहीं, वास्तविक हो; इसे ‘कम योग्य’ विद्यार्थियों के लिए दान बताना उसी रूढ़िबद्ध धारणा को पुष्ट करता है जिसे हटाना चाहिए।"},
  {"id":"cdp-child-development-1307","question":"Before an important maths test, a teacher wants to reduce stereotype threat among students from groups often believed to be ‘weak at maths’. Which step is most appropriate?","options":["Reminding the class which groups usually score low, so that those groups try harder","Framing it as a chance to learn that ability grows, with no group comparisons","Asking students to write their caste and gender at the top of the paper","Telling those groups that the test will be made easy especially for them"],"answer":1,"explanation":"Stereotype threat is triggered when group identity and its stereotype are made salient; a growth framing without group comparisons reduces it, while recording identity on the paper can trigger it.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"महत्त्वपूर्ण गणित परीक्षा से पहले एक शिक्षक उन समूहों के विद्यार्थियों में रूढ़िबद्ध धारणा का भय घटाना चाहता है जिन्हें प्रायः ‘गणित में कमज़ोर’ माना जाता है। कौन-सा कदम सबसे उपयुक्त है?","optionsHi":["कक्षा को याद दिलाना कि कौन-से समूह प्रायः कम अंक पाते हैं, ताकि वे समूह अधिक प्रयास करें","इसे इस अवसर के रूप में प्रस्तुत करना कि योग्यता बढ़ती है, बिना किसी समूह-तुलना के","विद्यार्थियों से प्रश्नपत्र के ऊपर अपनी जाति और लिंग लिखने को कहना","उन समूहों को बताना कि परीक्षा विशेष रूप से उनके लिए आसान बनाई जाएगी"],"explanationHi":"रूढ़िबद्ध धारणा का भय तब उत्पन्न होता है जब समूह-पहचान और उसकी रूढ़ि प्रमुख बनाई जाए; समूह-तुलना के बिना वृद्धि-आधारित प्रस्तुति उसे घटाती है, जबकि प्रश्नपत्र पर पहचान दर्ज कराना उसे जगा सकता है।"},
  {"id":"cdp-child-development-1308","question":"Biru, a Ho-speaking child, joined a Hindi-medium Class 2 three months ago. He follows routines and smiles but says almost nothing in class. What is the most appropriate interpretation?","options":["He may be in a ‘silent period’; let him respond through gestures and pictures","He has a speech disorder and should be referred to a specialist at once","He is shy and should be made to speak in front of the class daily to build confidence","He is unwilling to learn Hindi and needs firmer handling at school and home"],"answer":0,"explanation":"Many second-language learners listen for a long time before speaking; low-pressure ways to participate support them, whereas forced speaking raises anxiety.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"हो भाषा बोलने वाला बच्चा बिरू तीन माह पहले हिंदी-माध्यम की कक्षा 2 में आया। वह दिनचर्या का पालन करता है और मुस्कुराता है, पर कक्षा में लगभग कुछ नहीं बोलता। सबसे उपयुक्त व्याख्या क्या है?","optionsHi":["वह ‘मौन अवधि’ में हो सकता है; उसे इशारों और चित्रों से प्रतिक्रिया देने दें","उसे वाक्-विकार है और तुरंत विशेषज्ञ के पास भेजा जाना चाहिए","वह संकोची है और आत्मविश्वास बनाने के लिए उसे रोज़ कक्षा के सामने बोलने को विवश किया जाना चाहिए","वह हिंदी सीखने को तैयार नहीं है और विद्यालय तथा घर में उससे कठोरता से निपटना चाहिए"],"explanationHi":"अनेक द्वितीय-भाषा अधिगमकर्ता बोलने से पहले लंबे समय तक सुनते हैं; दबाव-रहित भागीदारी के तरीके उनकी सहायता करते हैं, जबकि विवश करके बुलवाना चिंता बढ़ाता है।"},
  {"id":"cdp-child-development-1309","question":"Children who studied in Marathi until last year now take a Class 6 science test written in Hindi. Many score poorly, though in oral discussion they explain the concepts well. Which conclusion is most sound?","options":["They have weak scientific understanding, which their poor scores reveal","They should be placed in Class 5 again until their scores improve","The test result reflects their science knowledge accurately, as written work is more reliable","The written Hindi test confuses language with science; oral answers would be fairer"],"answer":3,"explanation":"When the language of a test is a barrier, the score measures language rather than the subject; oral evidence of understanding shows the gap is linguistic.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"जो बच्चे पिछले वर्ष तक मराठी में पढ़ते थे, वे अब हिंदी में लिखा कक्षा 6 का विज्ञान परीक्षण देते हैं। अनेक कम अंक पाते हैं, यद्यपि मौखिक चर्चा में वे अवधारणाएँ अच्छी तरह समझाते हैं। कौन-सा निष्कर्ष सबसे ठोस है?","optionsHi":["उनकी वैज्ञानिक समझ कमज़ोर है, जो उनके कम अंक दर्शाते हैं","उन्हें अंक सुधरने तक फिर से कक्षा 5 में रखना चाहिए","परीक्षा-परिणाम उनके विज्ञान-ज्ञान को सटीक दर्शाता है, क्योंकि लिखित कार्य अधिक विश्वसनीय होता है","लिखित हिंदी परीक्षण भाषा को विज्ञान से भ्रमित करता है; मौखिक उत्तर अधिक निष्पक्ष होंगे"],"explanationHi":"जब परीक्षण की भाषा बाधा हो, तो अंक विषय के बजाय भाषा को मापता है; समझ के मौखिक प्रमाण दिखाते हैं कि अंतर भाषाई है।"},
  {"id":"cdp-child-development-1310","question":"A Class 3 teacher assigns the same caring, high-achieving girl as the permanent ‘buddy’ of a classmate with a disability. By mid-year the buddy looks tired and her own work has slipped. What is the best change?","options":["Telling the buddy that helping is her duty and will build her character","Removing all peer support, so the child with a disability relies on the teacher alone","Rotating buddies, setting limited roles, and keeping the teacher’s support primary","Asking the buddy’s parents to encourage her more and help with her own work"],"answer":2,"explanation":"Peer support works when it is shared and bounded; resting it on one child burdens her and makes the other child's inclusion fragile.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 3 की शिक्षिका एक ही सहृदय, उच्च-उपलब्धि वाली बालिका को एक विकलांग सहपाठी की स्थायी ‘साथी’ बना देती है। सत्र के मध्य तक साथी थकी दिखती है और उसका अपना कार्य गिर गया है। सर्वोत्तम परिवर्तन क्या है?","optionsHi":["साथी से कहना कि मदद करना उसका कर्तव्य है और इससे उसका चरित्र बनेगा","सारी सहपाठी-सहायता हटा देना, ताकि विकलांग बच्चा केवल शिक्षक पर निर्भर रहे","साथियों को बारी-बारी से बदलना, सीमित भूमिकाएँ तय करना, और शिक्षक की सहायता को प्राथमिक रखना","साथी के माता-पिता से कहना कि वे उसे और प्रोत्साहित करें और उसके अपने कार्य में मदद करें"],"explanationHi":"सहपाठी-सहायता तब काम करती है जब वह साझा और सीमित हो; उसे एक बच्चे पर टिकाना उस पर बोझ डालता है और दूसरे बच्चे के समावेशन को नाज़ुक बना देता है।"},
  {"id":"cdp-child-development-1311","question":"Which of these statements about differentiated instruction are correct? I. It means writing a separate lesson plan for each child. II. It can use whole-class, small-group and individual work. III. It means lowering expectations for struggling learners. IV. Every group’s task should be equally engaging and meaningful.","options":["I and III only","I, II and IV only","II and IV only","II, III and IV only"],"answer":2,"explanation":"Differentiation mixes groupings and gives every learner respectful, engaging work towards high goals; it does not need a plan per child or lower expectations.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"विभेदित अनुदेशन के बारे में इनमें से कौन-से कथन सही हैं? I. इसका अर्थ है प्रत्येक बच्चे के लिए अलग पाठ-योजना लिखना। II. यह पूरी कक्षा, छोटे समूह और व्यक्तिगत कार्य का उपयोग कर सकता है। III. इसका अर्थ है संघर्ष कर रहे अधिगमकर्ताओं की अपेक्षाएँ घटाना। IV. प्रत्येक समूह का कार्य समान रूप से रोचक और सार्थक होना चाहिए।","optionsHi":["केवल I और III","केवल I, II और IV","केवल II और IV","केवल II, III और IV"],"explanationHi":"विभेदन समूहीकरण को मिलाता है और प्रत्येक अधिगमकर्ता को ऊँचे लक्ष्यों की ओर सम्मानजनक, रोचक कार्य देता है; इसमें प्रति बच्चा योजना या कम अपेक्षाएँ आवश्यक नहीं।"},
  {"id":"cdp-child-development-1312","question":"In a Class 6 class, the ‘advanced’ group regularly designs projects and debates ideas, while the ‘struggling’ group fills in worksheets every day. Which principle of differentiation is being violated?","options":["Flexible use of time, as the groups get unequal amounts of class time daily","Respectful tasks: every learner gets engaging work needing real thinking","Curriculum compacting, since the advanced group skips content it knows","Learning-profile grouping, as groups should match learning styles"],"answer":1,"explanation":"Differentiation adjusts the level of support, not the quality of thinking; giving one group only drill while another does rich tasks widens the gap.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 6 की एक कक्षा में ‘उन्नत’ समूह नियमित रूप से परियोजनाएँ बनाता और विचारों पर बहस करता है, जबकि ‘संघर्षरत’ समूह रोज़ कार्यपत्रक भरता है। विभेदन का कौन-सा सिद्धांत भंग हो रहा है?","optionsHi":["समय का लचीला उपयोग, क्योंकि समूहों को रोज़ असमान कक्षा-समय मिलता है","सम्मानजनक कार्य: हर अधिगमकर्ता को वास्तविक चिंतन माँगने वाला रोचक कार्य मिले","पाठ्यक्रम संक्षिप्तीकरण, क्योंकि उन्नत समूह वह सामग्री छोड़ देता है जो वह जानता है","अधिगम-प्रोफ़ाइल समूहीकरण, क्योंकि समूह अधिगम-शैलियों से मेल खाने चाहिए"],"explanationHi":"विभेदन सहायता का स्तर समायोजित करता है, चिंतन की गुणवत्ता नहीं; एक समूह को केवल अभ्यास देना जबकि दूसरा समृद्ध कार्य करता है, अंतर को बढ़ाता है।"},
  {"id":"cdp-child-development-1313","question":"A Class 5 teacher seats children from poorer families on the back benches so that ‘the bright ones can sit in front’. What is the most likely effect?","options":["It helps every child concentrate better, since the able ones set the pace in front","It has no effect on learning, as all children hear the same lesson","It improves the performance of the back-bench children through healthy competition","Back-bench children get less attention and sense low expectations, lowering participation"],"answer":3,"explanation":"Seating by background signals worth and reduces teacher contact, feeding a self-fulfilling cycle of low expectation and low performance.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 5 की एक शिक्षिका निर्धन परिवारों के बच्चों को पीछे की बेंचों पर बैठाती है ताकि ‘होशियार बच्चे आगे बैठ सकें’। सबसे संभावित प्रभाव क्या है?","optionsHi":["यह हर बच्चे को बेहतर एकाग्र होने में मदद करता है, क्योंकि योग्य बच्चे आगे गति तय करते हैं","इसका अधिगम पर कोई प्रभाव नहीं पड़ता, क्योंकि सभी बच्चे एक ही पाठ सुनते हैं","यह स्वस्थ प्रतिस्पर्धा से पीछे की बेंच के बच्चों का प्रदर्शन सुधारता है","पीछे की बेंच के बच्चों पर कम ध्यान जाता है और वे कम अपेक्षाएँ भाँपते हैं, जिससे भागीदारी घटती है"],"explanationHi":"पृष्ठभूमि के आधार पर बैठाना मूल्य का संकेत देता है और शिक्षक का संपर्क घटाता है, जिससे कम अपेक्षा और कम प्रदर्शन का स्व-पूर्ति चक्र चलता है।"},
  {"id":"cdp-child-development-1314","question":"A Class 4 teacher slaps Mahi, who has dyscalculia, for ‘careless’ errors in subtraction. Which statement best evaluates this?","options":["It is doubly wrong: physical punishment is banned, and her errors need support","It is acceptable if done rarely and lightly, as a reminder to be more careful","It is acceptable because careless children need discipline to build good habits","It is wrong only because the parents may complain to the school authorities"],"answer":0,"explanation":"RTE bans physical punishment and mental harassment, and treating a disability as carelessness misreads the cause; she needs concrete support in place value and procedures.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 की एक शिक्षिका डिस्कैलकुलिया वाली माही को घटाने की ‘लापरवाह’ गलतियों के लिए थप्पड़ मारती है। इसका सबसे अच्छा मूल्यांकन कौन-सा कथन है?","optionsHi":["यह दोहरे रूप से गलत है: शारीरिक दंड प्रतिबंधित है, और उसकी गलतियों के लिए सहायता की आवश्यकता है","यह स्वीकार्य है यदि यह कभी-कभार और हल्के ढंग से हो, अधिक सावधान होने की याद दिलाने के रूप में","यह स्वीकार्य है क्योंकि लापरवाह बच्चों को अच्छी आदतें बनाने के लिए अनुशासन चाहिए","यह केवल इसलिए गलत है कि अभिभावक विद्यालय के अधिकारियों से शिकायत कर सकते हैं"],"explanationHi":"RTE शारीरिक दंड और मानसिक उत्पीड़न पर रोक लगाता है, और विकलांगता को लापरवाही मानना कारण को गलत समझना है; उसे स्थानीय मान और प्रक्रियाओं में ठोस सहायता चाहिए।"},
  {"id":"cdp-child-development-1315","question":"Sabina joined a Hindi-medium school a year ago. She now chats fluently in Hindi in the playground but struggles with textbook passages and written answers. Her teacher suspects a learning disability. Which idea best explains the situation?","options":["Playground fluency proves her academic Hindi should also be strong, so she must have a disability","Conversational language develops much faster than academic language; she needs language support","She is not trying hard enough in class and needs more pressure to read","She has forgotten her first language, and this loss is causing the problem in reading"],"answer":1,"explanation":"Cummins distinguished basic conversational skills, acquired in a year or two, from academic language, which takes years longer; mistaking this gap for a disability leads to wrong labelling.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"सबीना एक वर्ष पहले हिंदी-माध्यम विद्यालय में आई। वह अब खेल के मैदान में हिंदी में धाराप्रवाह बातचीत करती है पर पाठ्यपुस्तक के अंशों और लिखित उत्तरों में संघर्ष करती है। उसकी शिक्षिका को अधिगम अक्षमता का संदेह है। कौन-सा विचार इस स्थिति को सबसे अच्छी तरह समझाता है?","optionsHi":["खेल के मैदान की धाराप्रवाहता सिद्ध करती है कि उसकी शैक्षिक हिंदी भी सशक्त होनी चाहिए, इसलिए उसे अक्षमता है","बातचीत की भाषा शैक्षिक भाषा से कहीं तेज़ विकसित होती है; उसे भाषा-सहायता चाहिए","वह कक्षा में पर्याप्त प्रयास नहीं कर रही और पढ़ने के लिए उस पर और दबाव चाहिए","वह अपनी पहली भाषा भूल गई है, और यह हानि पढ़ने में समस्या पैदा कर रही है"],"explanationHi":"कमिंस ने आधारभूत बातचीत के कौशलों, जो एक-दो वर्ष में अर्जित होते हैं, को शैक्षिक भाषा से अलग किया, जिसमें कई और वर्ष लगते हैं; इस अंतर को अक्षमता मान लेने से गलत लेबल लगता है।"},
  {"id":"cdp-child-development-1316","question":"A Class 6 teacher marks correct answers with green ticks and wrong ones with red crosses, and colours a bar graph using only red and green. One student keeps misreading them. He has red-green colour vision deficiency. Which change helps most?","options":["Using brighter shades of red and green so the difference is more visible","Asking him to guess the meaning from how light or dark each shade is","Using symbols, labels or patterns along with colour, never colour alone","Excusing him from graph work, as it is too hard to adapt for him"],"answer":2,"explanation":"Information carried only by colour excludes students with colour vision deficiency; pairing colour with symbols, labels or patterns is a simple universal-design fix.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 6 की एक शिक्षिका सही उत्तरों को हरे टिक से और गलत उत्तरों को लाल क्रॉस से अंकित करती है, और एक दंड-आलेख (बार ग्राफ़) केवल लाल और हरे रंग से रंगती है। एक विद्यार्थी उन्हें बार-बार गलत पढ़ता है। उसे लाल-हरे रंग की दृष्टि-कमी है। कौन-सा परिवर्तन सबसे अधिक सहायक है?","optionsHi":["लाल और हरे के अधिक चमकीले शेड प्रयोग करना ताकि अंतर अधिक दिखे","उससे कहना कि हर शेड के हल्के या गहरे होने से अर्थ का अनुमान लगाए","रंग के साथ प्रतीकों, लेबलों या पैटर्नों का प्रयोग करना, कभी केवल रंग नहीं","उसे आलेख-कार्य से छूट देना, क्योंकि उसके लिए अनुकूलन बहुत कठिन है"],"explanationHi":"केवल रंग से दी गई सूचना रंग-दृष्टि की कमी वाले विद्यार्थियों को बाहर कर देती है; रंग को प्रतीकों, लेबलों या पैटर्नों के साथ जोड़ना सार्वभौमिक अभिकल्प का सरल उपाय है।"},
  {"id":"cdp-child-development-1317","question":"Varun, in Class 6, has muscular dystrophy, a condition that gradually weakens the muscles. He tires quickly while writing and walking between floors. Which plan is most appropriate?","options":["Treating him exactly like everyone else, since adjustments would make him dependent","Advising his parents to shift him to home study at once, for his safety","Waiting until he can no longer walk before making any changes to his routine","Planning ahead: ground-floor classes, rest breaks, a scribe or typing, reviewed regularly"],"answer":3,"explanation":"A progressive condition needs supports that anticipate and track changing needs; reasonable accommodation keeps him learning in his school without waiting for a crisis.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 6 के वरुण को मस्कुलर डिस्ट्रॉफ़ी है, एक स्थिति जो मांसपेशियों को धीरे-धीरे कमज़ोर करती है। वह लिखने और मंज़िलों के बीच चलने में जल्दी थक जाता है। कौन-सी योजना सबसे उपयुक्त है?","optionsHi":["उसके साथ ठीक सबके जैसा व्यवहार करना, क्योंकि समायोजन उसे निर्भर बना देंगे","उसके माता-पिता को उसकी सुरक्षा के लिए तुरंत घर पर पढ़ाई कराने की सलाह देना","उसकी दिनचर्या में कोई परिवर्तन करने से पहले तब तक प्रतीक्षा करना जब तक वह चल न सके","पहले से योजना बनाना: भूतल की कक्षाएँ, विश्राम-विराम, लेखक या टंकण, नियमित समीक्षा के साथ"],"explanationHi":"प्रगतिशील स्थिति को ऐसी सहायता चाहिए जो बदलती आवश्यकताओं का पूर्वानुमान और अनुसरण करे; उचित समायोजन उसे संकट की प्रतीक्षा किए बिना अपने विद्यालय में सीखते रहने देता है।"},
  {"id":"cdp-child-development-1318","question":"A head teacher, citing Gardner, orders that every lesson in every subject must include eight activities, one for each intelligence. Which response is most consistent with Gardner’s own views?","options":["The order is correct, since each child learns only through his or her dominant intelligence","The order is correct, since Gardner’s theory is mainly a lesson-planning template","The theory forbids the use of language when teaching mathematics to children","Gardner urges several meaningful entry points to key ideas, not all eight in every lesson"],"answer":3,"explanation":"Gardner has said the theory is not a recipe; teachers should present key ideas in several ways where this aids understanding, and mechanically covering all eight intelligences in each lesson trivialises both the theory and the subject.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"एक प्रधानाध्यापक, गार्डनर का हवाला देकर, आदेश देता है कि हर विषय के हर पाठ में आठ गतिविधियाँ होनी चाहिए, प्रत्येक बुद्धि के लिए एक। गार्डनर के अपने विचारों के सबसे अनुरूप प्रतिक्रिया कौन-सी है?","optionsHi":["आदेश सही है, क्योंकि प्रत्येक बच्चा केवल अपनी प्रमुख बुद्धि से सीखता है","आदेश सही है, क्योंकि गार्डनर का सिद्धांत मुख्यतः पाठ-योजना का साँचा है","सिद्धांत बच्चों को गणित पढ़ाते समय भाषा के प्रयोग की मनाही करता है","गार्डनर प्रमुख विचारों तक पहुँचने के कई सार्थक मार्गों का आग्रह करते हैं, हर पाठ में आठों का नहीं"],"explanationHi":"गार्डनर ने कहा है कि सिद्धांत कोई नुस्ख़ा नहीं है; जहाँ समझ में सहायक हो, शिक्षकों को प्रमुख विचार कई तरह से प्रस्तुत करने चाहिए, और हर पाठ में यांत्रिक रूप से आठों बुद्धियों को कवर करना सिद्धांत और विषय दोनों को सतही बनाता है।"},
  {"id":"cdp-child-development-1319","question":"Sameer looks at a flat net of six squares and immediately says which faces will be opposite each other when it is folded into a cube. In Gardner’s framework, this mainly reflects:","options":["Logical-mathematical intelligence","Spatial intelligence","Bodily-kinaesthetic intelligence","Naturalist intelligence"],"answer":1,"explanation":"Mentally folding and rotating forms is the core of spatial intelligence. Logical-mathematical intelligence concerns reasoning with numbers and abstract patterns, a common confusion because nets appear in maths lessons.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"छह वर्गों के चपटे जाल (नेट) को देखकर समीर तुरंत बता देता है कि घन में मोड़ने पर कौन-से फलक आमने-सामने होंगे। गार्डनर के ढाँचे में यह मुख्यतः दर्शाता है:","optionsHi":["तार्किक-गणितीय बुद्धि","स्थानिक बुद्धि","शारीरिक-गतिबोधक बुद्धि","प्रकृतिवादी बुद्धि"],"explanationHi":"आकृतियों को मन में मोड़ना और घुमाना स्थानिक बुद्धि का मूल है। तार्किक-गणितीय बुद्धि संख्याओं और अमूर्त प्रतिरूपों के साथ तर्क से संबंधित है, एक सामान्य भ्रम, क्योंकि जाल गणित के पाठों में आते हैं।"},
  {"id":"cdp-child-development-1320","question":"For a Class 7 science exhibition, Lalita explains photosynthesis through a poster painted in the Warli tribal art style, an approach no one in her school has tried before. In Sternberg’s theory, she is showing mainly:","options":["Analytical intelligence","Practical intelligence","Creative intelligence","Crystallised intelligence"],"answer":2,"explanation":"Sternberg’s creative intelligence (the experiential subtheory) is the ability to deal with novelty and combine ideas in new ways; fusing a folk-art form with science content is a novel combination.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की विज्ञान प्रदर्शनी के लिए, ललिता प्रकाश-संश्लेषण को वारली जनजातीय कला शैली में बने पोस्टर से समझाती है, एक ऐसा उपागम जो उसके विद्यालय में किसी ने नहीं आज़माया। स्टर्नबर्ग के सिद्धांत में, वह मुख्यतः दर्शा रही है:","optionsHi":["विश्लेषणात्मक बुद्धि","व्यावहारिक बुद्धि","सृजनात्मक बुद्धि","मूर्त (क्रिस्टलीकृत) बुद्धि"],"explanationHi":"स्टर्नबर्ग की सृजनात्मक बुद्धि (अनुभवात्मक उप-सिद्धांत) नवीनता से निपटने और विचारों को नए ढंग से मिलाने की क्षमता है; लोक-कला रूप को विज्ञान की सामग्री से जोड़ना एक नवीन संयोजन है।"},
  {"id":"cdp-child-development-1321","question":"A Class 8 teacher plans three tasks on a chapter about Mughal architecture to develop Sternberg’s three abilities. Which task targets PRACTICAL intelligence?","options":["Compare the features of the Taj Mahal and Humayun’s Tomb and explain the key differences","Design an imaginary building that blends Mughal and modern features","Write a poem from the point of view of a stone carver","Suggest a realistic plan by which your town could protect and promote a local monument"],"answer":3,"explanation":"Practical tasks apply knowledge to real-life settings; comparing and explaining is analytical, and designing or imagining new forms is creative.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"कक्षा 8 का शिक्षक मुग़ल स्थापत्य के अध्याय पर स्टर्नबर्ग की तीन योग्यताओं को विकसित करने के लिए तीन कार्य योजनाबद्ध करता है। कौन-सा कार्य व्यावहारिक बुद्धि को लक्षित करता है?","optionsHi":["ताजमहल और हुमायूँ के मकबरे की विशेषताओं की तुलना कीजिए और मुख्य अंतर समझाइए","मुग़ल और आधुनिक विशेषताओं को मिलाने वाली एक काल्पनिक इमारत की रूपरेखा बनाइए","पत्थर तराशने वाले कारीगर के दृष्टिकोण से एक कविता लिखिए","एक यथार्थवादी योजना सुझाइए जिससे आपका नगर किसी स्थानीय स्मारक की रक्षा और प्रचार कर सके"],"explanationHi":"व्यावहारिक कार्य ज्ञान को वास्तविक जीवन की परिस्थितियों में लागू करते हैं; तुलना करना और समझाना विश्लेषणात्मक है, और नए रूपों की रूपरेखा बनाना या कल्पना करना सृजनात्मक है।"},
  {"id":"cdp-child-development-1322","question":"IQ scores in a large school of 1,200 students follow a normal distribution with a mean of 100 and a standard deviation of 15. About how many students would be expected to score between 85 and 115?","options":["About 600","About 820","About 1,140","About 410"],"answer":1,"explanation":"About 68% of a normal distribution lies within one SD of the mean, and 0.68 × 1,200 ≈ 820. About 1,140 would be the two-SD range (95%), and 410 is only one side (34%).","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"1,200 विद्यार्थियों वाले एक बड़े विद्यालय में IQ अंक माध्य 100 और मानक विचलन 15 के साथ सामान्य बंटन का अनुसरण करते हैं। लगभग कितने विद्यार्थियों के 85 और 115 के बीच अंक पाने की अपेक्षा की जाएगी?","optionsHi":["लगभग 600","लगभग 820","लगभग 1,140","लगभग 410"],"explanationHi":"सामान्य बंटन का लगभग 68% माध्य से एक मानक विचलन के भीतर होता है, और 0.68 × 1,200 ≈ 820। लगभग 1,140 दो-मानक-विचलन परास (95%) होगी, और 410 केवल एक ओर (34%) है।"},
  {"id":"cdp-child-development-1323","question":"In a district with 50,000 children of the same age, IQ is normally distributed with a mean of 100 and a standard deviation of 15. About how many children would be expected to score above 130?","options":["About 7,500","About 2,500","About 1,100","About 50"],"answer":2,"explanation":"130 is two SDs above the mean; about 2.3% of scores lie beyond +2 SD, and 0.023 × 50,000 ≈ 1,100. ‘2,500’ wrongly uses 5%, which is both tails together.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"समान आयु के 50,000 बच्चों वाले जिले में IQ माध्य 100 और मानक विचलन 15 के साथ सामान्य रूप से बँटा है। लगभग कितने बच्चों के 130 से ऊपर अंक पाने की अपेक्षा की जाएगी?","optionsHi":["लगभग 7,500","लगभग 2,500","लगभग 1,100","लगभग 50"],"explanationHi":"130 माध्य से दो मानक विचलन ऊपर है; लगभग 2.3% अंक +2 मानक विचलन से परे होते हैं, और 0.023 × 50,000 ≈ 1,100। ‘2,500’ गलती से 5% लेता है, जो दोनों छोरों का संयुक्त है।"},
  {"id":"cdp-child-development-1324","question":"A psychologist reports a child’s IQ as ‘98, probably between 93 and 103’ instead of simply ‘98’. The main reason for giving a range is that:","options":["Every score has some measurement error, so a band is a more honest estimate","The child may have two different IQs, one verbal and one non-verbal","Ranges are required by law only when reporting on gifted children","IQ changes by about five points every week, so one single number would mislead"],"answer":0,"explanation":"No test is perfectly reliable; reporting a confidence band based on the standard error of measurement reminds users that small differences between scores may not be meaningful.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक मनोवैज्ञानिक बच्चे का IQ केवल ‘98’ बताने के बजाय ‘98, संभवतः 93 और 103 के बीच’ बताता है। परास देने का मुख्य कारण है कि:","optionsHi":["प्रत्येक अंक में कुछ मापन-त्रुटि होती है, इसलिए एक पट्टी अधिक ईमानदार अनुमान है","बच्चे के दो भिन्न IQ हो सकते हैं, एक शाब्दिक और एक अशाब्दिक","परास केवल प्रतिभाशाली बच्चों की रिपोर्टिंग पर कानूनन आवश्यक है","IQ हर सप्ताह लगभग पाँच अंक बदलता है, इसलिए एक संख्या भ्रामक होगी"],"explanationHi":"कोई परीक्षण पूर्णतः विश्वसनीय नहीं होता; मापन की मानक त्रुटि पर आधारित विश्वास-पट्टी बताना उपयोगकर्ताओं को याद दिलाता है कि अंकों के बीच के छोटे अंतर अर्थपूर्ण नहीं हो सकते।"},
  {"id":"cdp-child-development-1325","question":"Assertion (A): A single IQ test score should not be the sole basis for deciding a child’s school placement. Reason (R): Every test score contains measurement error, and a single test samples only a limited set of abilities.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because one score is imprecise and narrow, important decisions need several sources of information; R gives exactly the reason why A is sound practice.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"अभिकथन (A): किसी एक IQ परीक्षण-अंक को बच्चे के विद्यालयी स्थान-निर्धारण का एकमात्र आधार नहीं होना चाहिए। कारण (R): प्रत्येक परीक्षण-अंक में मापन-त्रुटि होती है, और एक परीक्षण योग्यताओं के केवल सीमित समुच्चय का नमूना लेता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"क्योंकि एक अंक अपरिशुद्ध और संकीर्ण है, महत्त्वपूर्ण निर्णयों को सूचना के कई स्रोत चाहिए; R ठीक वही कारण देता है कि A अच्छा व्यवहार क्यों है।"},
  {"id":"cdp-child-development-1326","question":"Before her board exam, Ritika realises that her irritation with her younger brother comes from tiredness and anxiety, not from anything he did, and she decides to rest before revising. In Goleman’s model, the first part, recognising the real source of her feeling, is mainly:","options":["Empathy","Social skills","Self-awareness","Self-motivation"],"answer":2,"explanation":"Self-awareness is recognising one’s own emotions and their causes as they happen; deciding to rest then moves into self-regulation.","difficulty":"moderate","source":"CTET Paper 2 · State TET","questionHi":"बोर्ड परीक्षा से पहले रितिका को एहसास होता है कि अपने छोटे भाई के प्रति उसकी चिड़चिड़ाहट थकान और चिंता से आती है, उसके किसी कृत्य से नहीं, और वह दोहराने से पहले आराम करने का निर्णय लेती है। गोलमैन के प्रतिरूप में, पहला भाग, अपनी भावना के वास्तविक स्रोत को पहचानना, मुख्यतः है:","optionsHi":["समानुभूति (सहानुभूति)","सामाजिक कौशल","आत्म-जागरूकता","आत्म-अभिप्रेरणा"],"explanationHi":"आत्म-जागरूकता अपनी भावनाओं और उनके कारणों को उसी क्षण पहचानना है; फिर आराम करने का निर्णय लेना आत्म-नियमन में आता है।"},
  {"id":"cdp-child-development-1327","question":"E. P. Torrance reported that many children’s scores on creativity tests dip around Class 4. What is the most reasonable implication for teachers?","options":["Creativity is biologically lost around the age of nine and cannot be revived by teaching","Children of this age should not be given open-ended tasks, as they find them confusing","The dip is permanent, so any creativity training should wait until adolescence begins","Pressure to give ‘correct’ answers may suppress creativity, so keep open-ended thinking alive"],"answer":3,"explanation":"Torrance linked this ‘fourth-grade slump’ partly to increasing demands for conformity; it is not a fixed biological loss, and supportive teaching can counter it.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"ई. पी. टॉरेंस ने बताया कि सृजनात्मकता परीक्षणों में कई बच्चों के अंक कक्षा 4 के आसपास गिरते हैं। शिक्षकों के लिए सबसे उचित निहितार्थ क्या है?","optionsHi":["सृजनात्मकता जैविक रूप से लगभग नौ वर्ष की आयु में खो जाती है और शिक्षण से पुनर्जीवित नहीं हो सकती","इस आयु के बच्चों को खुले-अंत वाले कार्य नहीं देने चाहिए, क्योंकि उन्हें वे भ्रमित करते हैं","यह गिरावट स्थायी है, इसलिए सृजनात्मकता-प्रशिक्षण को किशोरावस्था शुरू होने तक रुकना चाहिए","‘सही’ उत्तर देने का दबाव सृजनात्मकता को दबा सकता है, इसलिए खुले चिंतन को जीवित रखें"],"explanationHi":"टॉरेंस ने इस ‘चौथी कक्षा की गिरावट’ को आंशिक रूप से अनुरूपता की बढ़ती माँगों से जोड़ा; यह निश्चित जैविक क्षति नहीं है, और सहायक शिक्षण इसका प्रतिकार कर सकता है।"},
  {"id":"cdp-child-development-1328","question":"A four-year-old rides a stick around the courtyard as if it were a horse. Vygotsky saw such pretend play as important for later abstract thought mainly because:","options":["The child separates the meaning ‘horse’ from the real object, using a substitute","It keeps the child physically active, which builds the brain for later abstract thinking","It is a way of getting rid of excess energy so the child can focus later","It shows the child cannot yet tell reality from fantasy, a stage to outgrow"],"answer":0,"explanation":"For Vygotsky, in play a child acts in an imagined situation where meaning is separated from the object, a step towards thinking with symbols and concepts; play also creates its own zone of proximal development.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"चार वर्ष का बच्चा आँगन में एक डंडे पर घोड़े की तरह सवारी करता है। वाइगोत्स्की ने ऐसे काल्पनिक खेल को आगे के अमूर्त चिंतन के लिए मुख्यतः क्यों महत्त्वपूर्ण माना?","optionsHi":["बच्चा ‘घोड़े’ के अर्थ को वास्तविक वस्तु से अलग करता है, एक विकल्प का उपयोग करते हुए","यह बच्चे को शारीरिक रूप से सक्रिय रखता है, जो आगे के अमूर्त चिंतन के लिए मस्तिष्क बनाता है","यह अतिरिक्त ऊर्जा निकालने का तरीका है ताकि बच्चा बाद में ध्यान केंद्रित कर सके","यह दिखाता है कि बच्चा अभी वास्तविकता और कल्पना में भेद नहीं कर सकता, एक अवस्था जिससे आगे बढ़ना है"],"explanationHi":"वाइगोत्स्की के लिए खेल में बच्चा कल्पित स्थिति में कार्य करता है जहाँ अर्थ वस्तु से अलग हो जाता है, जो प्रतीकों और अवधारणाओं के साथ चिंतन की ओर एक कदम है; खेल अपना ही निकटस्थ विकास का क्षेत्र भी बनाता है।"},
  {"id":"cdp-child-development-1329","question":"Testing shows that Ishita, in Class 7, has very high reasoning ability, yet she is failing most subjects. What should the teacher do first?","options":["Conclude that the test was wrong and ignore it, since marks show true ability","Conclude that she is lazy and give her extra homework to build discipline","Move her to a lower section so that she can cope and regain confidence","Look into causes such as boredom, emotional issues, a learning disability or peers first"],"answer":3,"explanation":"Underachievement in a capable student has many possible causes; diagnosis must come before intervention, and a lower section would only reduce challenge further.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"परीक्षण दिखाता है कि कक्षा 7 की ईशिता की तर्क-क्षमता बहुत उच्च है, फिर भी वह अधिकांश विषयों में असफल हो रही है। शिक्षक को सबसे पहले क्या करना चाहिए?","optionsHi":["निष्कर्ष निकालना कि परीक्षण गलत था और उसे अनदेखा करना, क्योंकि अंक सच्ची योग्यता दर्शाते हैं","निष्कर्ष निकालना कि वह आलसी है और अनुशासन बनाने के लिए उसे अतिरिक्त गृहकार्य देना","उसे निचले अनुभाग में भेजना ताकि वह सामना कर सके और आत्मविश्वास पा सके","पहले कारणों की जाँच करना, जैसे ऊब, भावनात्मक मुद्दे, अधिगम अक्षमता या साथी"],"explanationHi":"सक्षम विद्यार्थी की अल्प-उपलब्धि के अनेक संभावित कारण होते हैं; हस्तक्षेप से पहले निदान होना चाहिए, और निचला अनुभाग चुनौती को और घटाएगा।"},
  {"id":"cdp-child-development-1330","question":"In Joseph Renzulli’s Enrichment Triad Model, ‘Type III’ enrichment refers to:","options":["General exploratory activities that expose students to new topics and interests","Group training in thinking, research and communication skills for all students","Remedial lessons for students who are behind, to bring them up to grade level","Individual or small-group investigation of real problems, producing original products"],"answer":3,"explanation":"Type I is general exploration, Type II is training in process skills, and Type III is first-hand investigation of real problems, where students act as practising professionals.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"जोसेफ़ रेनज़ुली के संवर्धन त्रिक प्रतिरूप (एनरिचमेंट ट्रायड मॉडल) में, ‘प्रकार III’ संवर्धन का अर्थ है:","optionsHi":["सामान्य अन्वेषणात्मक गतिविधियाँ जो विद्यार्थियों को नए विषयों और रुचियों से परिचित कराती हैं","सभी विद्यार्थियों के लिए चिंतन, अनुसंधान और संप्रेषण कौशलों का समूह प्रशिक्षण","पिछड़े विद्यार्थियों के लिए उपचारात्मक पाठ, उन्हें कक्षा-स्तर तक लाने के लिए","वास्तविक समस्याओं की वैयक्तिक या छोटे-समूह की जाँच, मौलिक उत्पाद बनाते हुए"],"explanationHi":"प्रकार I सामान्य अन्वेषण है, प्रकार II प्रक्रिया-कौशलों का प्रशिक्षण है, और प्रकार III वास्तविक समस्याओं की प्रत्यक्ष जाँच है, जहाँ विद्यार्थी अभ्यासरत पेशेवरों की तरह कार्य करते हैं।"},
  {"id":"cdp-child-development-1331","question":"In a Class 3 in Kokrajhar, Assam, the children speak Bodo, Assamese and Bengali at home, while the school language is Assamese. During a story lesson, which practice best uses this diversity?","options":["Allow only Assamese to be spoken in class, so that every child is treated equally","Let groups retell the story in home languages, then bridge key ideas into Assamese","Seat children from each language group separately for the whole year to avoid confusion","Skip the story, because not all children yet understand Assamese well enough"],"answer":1,"explanation":"Allowing home languages builds comprehension and confidence and gives a bridge to the school language; banning them or segregating children wastes their linguistic resources.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"असम के कोकराझार की कक्षा 3 में बच्चे घर पर बोडो, असमिया और बांग्ला बोलते हैं, जबकि विद्यालय की भाषा असमिया है। कहानी के पाठ के दौरान, कौन-सा अभ्यास इस विविधता का सबसे अच्छा उपयोग करता है?","optionsHi":["कक्षा में केवल असमिया बोलने की अनुमति देना, ताकि हर बच्चे के साथ समान व्यवहार हो","समूहों को कहानी घर की भाषाओं में दोबारा सुनाने देना, फिर प्रमुख विचारों को असमिया से जोड़ना","भ्रम से बचने के लिए हर भाषा-समूह के बच्चों को पूरे वर्ष अलग बैठाना","कहानी छोड़ देना, क्योंकि सभी बच्चे अभी असमिया इतनी अच्छी तरह नहीं समझते"],"explanationHi":"घर की भाषाओं की अनुमति बोध और आत्मविश्वास बनाती है और विद्यालय की भाषा के लिए पुल देती है; उन पर रोक लगाना या बच्चों को अलग करना उनके भाषाई संसाधनों को व्यर्थ करता है।"},
  {"id":"cdp-child-development-1332","question":"In a well-known classroom study (Ray Rist), a kindergarten teacher seated children at ‘fast’ and ‘slow’ tables within the first days of school, largely on the basis of dress, speech and family background, and these groupings persisted for years. This study mainly illustrates:","options":["How social-class-based expectations can become lasting gaps in opportunity","That children’s abilities are already fully visible by the eighth day of school","That ability grouping always raises achievement for every child in the class","That young children learn better sitting in rows than at shared tables"],"answer":0,"explanation":"Rist found that early placements based on social-class cues shaped the attention and instruction children received, so the groupings became self-perpetuating.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"एक प्रसिद्ध कक्षा-अध्ययन (रे रिस्ट) में, एक किंडरगार्टन शिक्षिका ने विद्यालय के पहले दिनों में ही बच्चों को मुख्यतः पोशाक, बोली और पारिवारिक पृष्ठभूमि के आधार पर ‘तेज़’ और ‘धीमी’ मेज़ों पर बैठाया, और ये समूह वर्षों तक बने रहे। यह अध्ययन मुख्यतः क्या दर्शाता है?","optionsHi":["सामाजिक-वर्ग-आधारित अपेक्षाएँ कैसे अवसर में स्थायी अंतर बन सकती हैं","कि विद्यालय के आठवें दिन तक बच्चों की योग्यताएँ पूरी तरह दिखाई दे चुकी होती हैं","कि योग्यता-समूहीकरण हमेशा कक्षा के हर बच्चे की उपलब्धि बढ़ाता है","कि छोटे बच्चे साझा मेज़ों की तुलना में पंक्तियों में बैठकर बेहतर सीखते हैं"],"explanationHi":"रिस्ट ने पाया कि सामाजिक-वर्ग के संकेतों पर आधारित आरंभिक स्थान-निर्धारण ने बच्चों को मिलने वाले ध्यान और शिक्षण को आकार दिया, इसलिए समूह स्वयं को बनाए रखने वाले बन गए।"},
  {"id":"cdp-child-development-1333","question":"Lhamo, from a community that values cooperation and modesty, rarely raises her hand to answer before her classmates, though she helps them quietly in group work. Her new teacher concludes she ‘lacks confidence and ability’. Which is the best evaluation?","options":["The teacher is right, because confident and able children always answer first","She may be misread: a cultural norm of not outshining peers is not low ability","Lhamo should be referred for counselling, since such shyness signals a problem","Lhamo should be made to answer first every day until she changes her habit"],"answer":1,"explanation":"Cultural norms about competition and self-display shape classroom behaviour; judging ability through a single participation style can mislabel children from communities that value cooperation.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"ल्हामो, एक ऐसे समुदाय से जो सहयोग और विनम्रता को महत्त्व देता है, अपने सहपाठियों से पहले उत्तर देने के लिए शायद ही हाथ उठाती है, यद्यपि वह समूह-कार्य में चुपचाप उनकी सहायता करती है। उसकी नई शिक्षिका निष्कर्ष निकालती है कि उसमें ‘आत्मविश्वास और योग्यता की कमी’ है। सर्वोत्तम मूल्यांकन क्या है?","optionsHi":["शिक्षिका सही है, क्योंकि आत्मविश्वासी और योग्य बच्चे हमेशा पहले उत्तर देते हैं","उसे गलत समझा जा रहा हो सकता है: साथियों से आगे न दिखने का सांस्कृतिक मानदंड कम योग्यता नहीं है","ल्हामो को परामर्श के लिए भेजा जाना चाहिए, क्योंकि ऐसा संकोच किसी समस्या का संकेत है","ल्हामो को हर दिन पहले उत्तर देने को विवश किया जाना चाहिए जब तक वह अपनी आदत न बदल ले"],"explanationHi":"प्रतिस्पर्धा और आत्म-प्रदर्शन के सांस्कृतिक मानदंड कक्षा के व्यवहार को आकार देते हैं; भागीदारी की एक ही शैली से योग्यता का निर्णय करना सहयोग को महत्त्व देने वाले समुदायों के बच्चों पर गलत लेबल लगा सकता है।"},
  {"id":"cdp-child-development-1334","question":"In studies by Hermine Sinclair, children who could not yet conserve were trained to use the comparative words that conserving children use (such as ‘longer but thinner’). Most still failed to conserve. These results support the view that:","options":["Language determines thought completely, so more word training is all that is needed","Conservation is learned only through reinforcement, not through words","Grammar is innate and thought is not, so words cannot shape reasoning","Learning a concept’s words does not by itself create the cognitive operation"],"answer":3,"explanation":"The studies, from Piaget’s Geneva school, showed that verbal training alone rarely produced conservation, supporting Piaget’s position that thought drives language more than the reverse.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"हर्माइन सिनक्लेयर के अध्ययनों में, जो बच्चे अभी संरक्षण नहीं कर सकते थे उन्हें वे तुलनात्मक शब्द प्रयोग करने का प्रशिक्षण दिया गया जो संरक्षण करने वाले बच्चे प्रयोग करते हैं (जैसे ‘लंबा पर पतला’)। अधिकांश फिर भी संरक्षण में असफल रहे। ये परिणाम किस मत का समर्थन करते हैं?","optionsHi":["भाषा चिंतन को पूरी तरह निर्धारित करती है, इसलिए केवल और शब्द-प्रशिक्षण चाहिए","संरक्षण केवल पुनर्बलन से सीखा जाता है, शब्दों से नहीं","व्याकरण जन्मजात है और चिंतन नहीं, इसलिए शब्द तर्कण को आकार नहीं दे सकते","किसी अवधारणा के शब्द सीख लेना अपने आप संज्ञानात्मक संक्रिया नहीं बनाता"],"explanationHi":"पियाजे के जेनेवा संप्रदाय के इन अध्ययनों ने दिखाया कि केवल शाब्दिक प्रशिक्षण से शायद ही संरक्षण उत्पन्न हुआ, जो पियाजे के इस मत का समर्थन करता है कि चिंतन भाषा को उसके उलट से अधिक संचालित करता है।"},
  {"id":"cdp-child-development-1335","question":"According to Vygotsky’s studies of concept formation, children sort objects for a long time into ‘complexes’ joined by changing, concrete links. At what period did he say genuine concepts finally develop?","options":["In infancy, with the first words","Around the age of three","In adolescence","Only in adulthood, after formal education ends"],"answer":2,"explanation":"Vygotsky held that thinking in complexes and pseudo-concepts dominates childhood, and that true abstract concepts are formed only in adolescence, supported by school instruction.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"वाइगोत्स्की के अवधारणा-निर्माण के अध्ययनों के अनुसार, बच्चे लंबे समय तक वस्तुओं को बदलती, ठोस कड़ियों से जुड़े ‘संकुलों’ (कॉम्प्लेक्स) में छाँटते हैं। उन्होंने कहा कि वास्तविक अवधारणाएँ अंततः किस काल में विकसित होती हैं?","optionsHi":["शैशवावस्था में, पहले शब्दों के साथ","लगभग तीन वर्ष की आयु में","किशोरावस्था में","केवल वयस्कता में, औपचारिक शिक्षा समाप्त होने के बाद"],"explanationHi":"वाइगोत्स्की का मत था कि संकुलों और छद्म-अवधारणाओं में चिंतन बाल्यावस्था में हावी रहता है, और सच्ची अमूर्त अवधारणाएँ केवल किशोरावस्था में बनती हैं, विद्यालयी शिक्षण के सहारे।"},
  {"id":"cdp-child-development-1336","question":"If Chomsky is right that children acquire the grammar of their home language with the help of an innate capacity, what is the most sensible implication for early language teaching?","options":["Children need daily drill in grammar rules before they can speak their language correctly","Grammar mistakes in young children should be corrected strictly every time","Provide rich, meaningful language use such as stories and talk, not formal grammar drills","Language need not be taught or used deliberately in school at all"],"answer":2,"explanation":"Children acquire grammatical competence largely from meaningful exposure; early teaching should immerse them in rich language, while explicit grammar suits later, reflective study.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"यदि चॉम्स्की सही हैं कि बच्चे जन्मजात क्षमता की सहायता से अपनी घर की भाषा का व्याकरण अर्जित करते हैं, तो प्रारंभिक भाषा-शिक्षण के लिए सबसे समझदार निहितार्थ क्या है?","optionsHi":["बच्चों को अपनी भाषा सही बोलने से पहले व्याकरण के नियमों का दैनिक अभ्यास चाहिए","छोटे बच्चों की व्याकरण की गलतियाँ हर बार कड़ाई से सुधारनी चाहिए","कहानियों और बातचीत जैसा समृद्ध, अर्थपूर्ण भाषा-प्रयोग उपलब्ध कराएँ, औपचारिक व्याकरण अभ्यास नहीं","विद्यालय में भाषा को जानबूझकर सिखाने या प्रयोग करने की कोई आवश्यकता नहीं"],"explanationHi":"बच्चे व्याकरणिक सक्षमता मुख्यतः अर्थपूर्ण संपर्क से अर्जित करते हैं; प्रारंभिक शिक्षण को उन्हें समृद्ध भाषा में डुबोना चाहिए, जबकि स्पष्ट व्याकरण बाद के चिंतनशील अध्ययन के अनुकूल है।"},
  {"id":"cdp-child-development-1337","question":"Which statement about age and second-language learning is best supported by research?","options":["Late starters usually keep an accent but can still master vocabulary and grammar","Adults cannot learn any new language after the age of 12, as the brain has set","Age has no effect at all on second-language learning, since only practice matters","Children always learn a second language faster than adults in every aspect"],"answer":0,"explanation":"Early starters tend to reach native-like pronunciation, but older learners can learn quickly and reach high proficiency in vocabulary and grammar; the age effect is strongest for accent.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"आयु और द्वितीय-भाषा अधिगम के बारे में कौन-सा कथन शोध द्वारा सबसे अच्छी तरह समर्थित है?","optionsHi":["देर से शुरू करने वाले प्रायः लहजा बनाए रखते हैं, पर शब्दावली और व्याकरण में निपुण हो सकते हैं","वयस्क 12 वर्ष की आयु के बाद कोई नई भाषा नहीं सीख सकते, क्योंकि मस्तिष्क स्थिर हो जाता है","आयु का द्वितीय-भाषा अधिगम पर कोई प्रभाव नहीं पड़ता, क्योंकि केवल अभ्यास मायने रखता है","बच्चे हमेशा हर पहलू में वयस्कों से तेज़ी से द्वितीय भाषा सीखते हैं"],"explanationHi":"जल्दी शुरू करने वाले मातृभाषी जैसा उच्चारण प्राप्त करते हैं, पर बड़े अधिगमकर्ता तेज़ी से सीख सकते हैं और शब्दावली व व्याकरण में उच्च दक्षता पा सकते हैं; आयु का प्रभाव लहजे में सबसे प्रबल है।"},
  {"id":"cdp-child-development-1338","question":"Russian has two basic colour words for what English calls ‘blue’: one for light blue and one for dark blue. Experiments found Russian speakers slightly faster at telling shades apart when they crossed this boundary. Such a finding supports:","options":["The strong version of linguistic determinism, as English speakers cannot see the difference","The weak version of linguistic relativity, as language shapes perception in small ways","Chomsky’s claim that colour vocabulary is innate and the same in all languages","Piaget’s claim that language has no effect on any cognitive process at all"],"answer":1,"explanation":"English speakers can obviously see the difference, so the strong version fails; but a small speed advantage linked to language categories supports a weak relativity effect.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"रूसी भाषा में उसके लिए दो मूल रंग-शब्द हैं जिसे अंग्रेज़ी ‘blue’ कहती है: एक हल्के नीले के लिए और एक गहरे नीले के लिए। प्रयोगों में पाया गया कि रूसी बोलने वाले इस सीमा को पार करने पर शेडों में भेद करने में थोड़े तेज़ थे। ऐसा निष्कर्ष किसका समर्थन करता है?","optionsHi":["भाषाई निर्धारणवाद का प्रबल रूप, क्योंकि अंग्रेज़ी बोलने वाले अंतर देख नहीं सकते","भाषाई सापेक्षता का दुर्बल रूप, क्योंकि भाषा प्रत्यक्षण को छोटे ढंग से आकार देती है","चॉम्स्की का यह दावा कि रंग-शब्दावली जन्मजात है और सभी भाषाओं में एक-सी है","पियाजे का यह दावा कि भाषा का किसी भी संज्ञानात्मक प्रक्रिया पर कोई प्रभाव नहीं पड़ता"],"explanationHi":"अंग्रेज़ी बोलने वाले स्पष्टतः अंतर देख सकते हैं, इसलिए प्रबल रूप विफल होता है; पर भाषाई श्रेणियों से जुड़ा थोड़ा-सा गति-लाभ दुर्बल सापेक्षता प्रभाव का समर्थन करता है।"},
  {"id":"cdp-child-development-1339","question":"A teacher regularly writes ‘Very neat!’ on girls’ notebooks and ‘Excellent reasoning!’ on boys’, even when the work is similar. The most likely effect on girls is that they learn:","options":["That their thinking is valued as much as boys’, since both get praise","That neatness, rather than intellectual quality, is what is expected of them","That feedback has no real meaning, since it is the same for everyone","That they are better at reasoning than boys, as their work looks better"],"answer":1,"explanation":"Feedback signals what is valued. Praising girls for appearance and boys for ideas is a subtle gender bias that can shape self-concepts and later subject choices.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"एक शिक्षिका नियमित रूप से लड़कियों की कॉपियों पर ‘बहुत साफ़!’ और लड़कों की कॉपियों पर ‘उत्कृष्ट तर्क!’ लिखती है, तब भी जब कार्य समान हो। लड़कियों पर सबसे संभावित प्रभाव यह है कि वे सीखती हैं:","optionsHi":["कि उनके चिंतन को लड़कों जितना ही महत्त्व दिया जाता है, क्योंकि दोनों को प्रशंसा मिलती है","कि उनसे बौद्धिक गुणवत्ता के बजाय सफ़ाई की अपेक्षा की जाती है","कि प्रतिक्रिया का कोई वास्तविक अर्थ नहीं है, क्योंकि वह सबके लिए समान है","कि वे लड़कों से तर्क में बेहतर हैं, क्योंकि उनका कार्य बेहतर दिखता है"],"explanationHi":"प्रतिक्रिया संकेत देती है कि क्या महत्त्वपूर्ण है। लड़कियों की रूप के लिए और लड़कों की विचारों के लिए प्रशंसा सूक्ष्म लैंगिक पूर्वाग्रह है जो आत्म-अवधारणाओं और आगे के विषय-चयन को आकार दे सकता है।"},
  {"id":"cdp-child-development-1340","question":"During recess in a Bhubaneswar school, boys’ cricket occupies the whole playground and girls sit at the edges. Which response best promotes gender equity?","options":["Leave it as it is, since boys naturally need more open space to run and play","Ban cricket during recess so that nobody can occupy the whole ground","Tell girls to play indoor games instead, where they will feel safer","Schedule fair shared use of the ground and encourage mixed and girls’ teams"],"answer":3,"explanation":"Use of space is part of the hidden curriculum; fair scheduling and mixed participation give girls equal access to physical activity without punishing boys.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"भुवनेश्वर के एक विद्यालय में मध्यावकाश के दौरान लड़कों का क्रिकेट पूरे खेल के मैदान पर कब्ज़ा कर लेता है और लड़कियाँ किनारों पर बैठती हैं। कौन-सी प्रतिक्रिया लैंगिक समता को सबसे अच्छी तरह बढ़ावा देती है?","optionsHi":["जैसा है वैसा रहने देना, क्योंकि लड़कों को स्वाभाविक रूप से दौड़ने और खेलने के लिए अधिक खुली जगह चाहिए","मध्यावकाश में क्रिकेट पर रोक लगाना ताकि कोई पूरे मैदान पर कब्ज़ा न कर सके","लड़कियों से इनडोर खेल खेलने को कहना, जहाँ वे अधिक सुरक्षित महसूस करेंगी","मैदान के साझा उपयोग का न्यायसंगत समय-निर्धारण करना और मिश्रित तथा लड़कियों की टीमों को प्रोत्साहित करना"],"explanationHi":"स्थान का उपयोग छिपी हुई पाठ्यचर्या का भाग है; न्यायसंगत समय-निर्धारण और मिश्रित भागीदारी लड़कों को दंडित किए बिना लड़कियों को शारीरिक गतिविधि तक समान पहुँच देते हैं।"},
  {"id":"cdp-child-development-1341","question":"Two-and-a-half-year-old Mahi says, ‘I am a girl’, but when asked what she will be when she grows up, she says, ‘A papa’. In Kohlberg’s sequence, she has reached:","options":["Gender identity, but not yet gender stability","Gender stability, but not yet gender identity","Gender constancy","Androgyny"],"answer":0,"explanation":"Correctly labelling her own gender is gender identity; understanding that gender stays the same over time (stability) comes later, followed by constancy across situations.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"ढाई वर्ष की माही कहती है, ‘मैं लड़की हूँ’, पर जब पूछा जाता है कि बड़ी होकर वह क्या बनेगी, तो कहती है, ‘पापा’। कोहलबर्ग के क्रम में वह किस स्तर पर पहुँची है?","optionsHi":["लैंगिक पहचान, पर अभी लैंगिक स्थिरता नहीं","लैंगिक स्थिरता, पर अभी लैंगिक पहचान नहीं","लैंगिक स्थायित्व (जेंडर कॉन्स्टेंसी)","उभयलिंगता"],"explanationHi":"अपने लिंग को सही नाम देना लैंगिक पहचान है; यह समझना कि लिंग समय के साथ वही रहता है (स्थिरता) बाद में आता है, और उसके बाद परिस्थितियों में स्थायित्व।"},
  {"id":"cdp-child-development-1342","question":"After two months of intensive coaching for an entrance test, students’ scores rise substantially, but their performance on related school tasks changes little. The most reasonable interpretation is that:","options":["Their underlying ability roughly doubled during two months of intensive coaching","Coaching has no effect on test scores, so the rise must be due to chance","Scores partly reflect practice with the test format, not just underlying ability","Entrance tests measure only creativity, which coaching has managed to raise"],"answer":2,"explanation":"Score gains from coaching on a particular format show that scores include test-specific skills; this is one reason NCF 2005 and NEP 2020 warn against assessment systems that reward coaching.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"प्रवेश परीक्षा के लिए दो माह की सघन कोचिंग के बाद विद्यार्थियों के अंक काफ़ी बढ़ जाते हैं, पर संबंधित विद्यालयी कार्यों में उनका प्रदर्शन बहुत कम बदलता है। सबसे उचित व्याख्या यह है कि:","optionsHi":["सघन कोचिंग के दो माह में उनकी अंतर्निहित योग्यता लगभग दोगुनी हो गई","कोचिंग का परीक्षा-अंकों पर कोई प्रभाव नहीं पड़ता, इसलिए वृद्धि संयोग से है","अंक आंशिक रूप से परीक्षा-प्रारूप के अभ्यास को दर्शाते हैं, केवल अंतर्निहित योग्यता को नहीं","प्रवेश परीक्षाएँ केवल सृजनात्मकता को मापती हैं, जिसे कोचिंग ने बढ़ा दिया"],"explanationHi":"किसी विशेष प्रारूप पर कोचिंग से मिली अंक-वृद्धि दिखाती है कि अंकों में परीक्षा-विशिष्ट कौशल शामिल होते हैं; यही एक कारण है कि NCF 2005 और NEP 2020 कोचिंग को पुरस्कृत करने वाली आकलन-प्रणालियों के प्रति चेताती हैं।"},
  {"id":"cdp-child-development-1343","question":"Jaspreet performs poorly in timed written tests but builds excellent models and gives clear explanations in projects. Which assessment approach would give the fullest picture of her learning?","options":["A single end-of-year written exam, which is the fairest common measure","A portfolio of projects, drafts, observations and tests over time","Ranking her against the class on test marks to show where she stands","Oral tests only, since she explains well when she speaks"],"answer":1,"explanation":"A portfolio draws on varied evidence across time and formats, capturing learning that a single format misses, in line with comprehensive assessment.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"जसप्रीत समयबद्ध लिखित परीक्षाओं में खराब प्रदर्शन करती है पर परियोजनाओं में उत्कृष्ट मॉडल बनाती है और स्पष्ट व्याख्याएँ देती है। कौन-सा आकलन उपागम उसके अधिगम का सबसे पूर्ण चित्र देगा?","optionsHi":["वर्ष के अंत की एक लिखित परीक्षा, जो सबसे निष्पक्ष सामान्य मापक है","समय के साथ परियोजनाओं, मसौदों, अवलोकनों और परीक्षणों का पोर्टफ़ोलियो","परीक्षा-अंकों पर कक्षा में उसे श्रेणीबद्ध करना, यह दिखाने के लिए कि वह कहाँ खड़ी है","केवल मौखिक परीक्षाएँ, क्योंकि वह बोलकर अच्छा समझाती है"],"explanationHi":"पोर्टफ़ोलियो समय और प्रारूपों में विविध प्रमाणों का उपयोग करता है, उस अधिगम को पकड़ता है जिसे कोई एक प्रारूप चूक जाता है, जो व्यापक आकलन के अनुरूप है।"},
  {"id":"cdp-child-development-1344","question":"Children who start Class 1 as weak readers read less, learn fewer new words and fall further behind each year, while good readers read more and pull ahead. Keith Stanovich called this pattern:","options":["The halo effect","The Flynn effect","The Matthew effect","The Hawthorne effect"],"answer":2,"explanation":"The Matthew effect (‘the rich get richer’) describes how early advantages and disadvantages in reading compound over time, which is why early support matters and why early labelling can be harmful.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"जो बच्चे कक्षा 1 कमज़ोर पाठक के रूप में शुरू करते हैं, वे कम पढ़ते हैं, कम नए शब्द सीखते हैं और हर वर्ष और पीछे रह जाते हैं, जबकि अच्छे पाठक अधिक पढ़ते हैं और आगे निकल जाते हैं। कीथ स्टैनोविच ने इस प्रतिरूप को क्या कहा?","optionsHi":["प्रभामंडल प्रभाव","फ़्लिन प्रभाव","मैथ्यू प्रभाव","हॉथोर्न प्रभाव"],"explanationHi":"मैथ्यू प्रभाव (‘धनी और धनी होते हैं’) वर्णन करता है कि पठन में आरंभिक लाभ और हानियाँ समय के साथ बढ़ती जाती हैं, इसीलिए प्रारंभिक सहायता मायने रखती है और आरंभ में लेबल लगाना हानिकारक हो सकता है।"},
  {"id":"cdp-child-development-1345","question":"Which of these pairings of theorist and concept are correct? 1. Kohlberg – just community school 2. Gilligan – ethic of care 3. Piaget – immanent justice 4. Erikson – internal working model","options":["1, 2 and 3 only","2 and 3 only","1, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"The internal working model is Bowlby’s attachment concept, not Erikson’s; the other three pairings are correct.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"सिद्धांतकार और अवधारणा के इनमें से कौन-से जोड़े सही हैं? 1. कोहलबर्ग – न्यायपूर्ण समुदाय विद्यालय 2. गिलिगन – देखभाल की नैतिकता 3. पियाजे – अंतर्निहित न्याय 4. एरिक्सन – आंतरिक कार्यकारी प्रतिरूप","optionsHi":["केवल 1, 2 और 3","केवल 2 और 3","केवल 1, 3 और 4","1, 2, 3 और 4"],"explanationHi":"आंतरिक कार्यकारी प्रतिरूप (इंटरनल वर्किंग मॉडल) बॉल्बी की आसक्ति-संबंधी अवधारणा है, एरिक्सन की नहीं; शेष तीनों जोड़े सही हैं।"},
  {"id":"cdp-child-development-1346","question":"A B.Ed lecturer says, ‘The heritability of intelligence is about 0.5, so half of each child’s IQ comes from genes and half from the environment.’ What is wrong with this statement?","options":["Heritability of intelligence is actually zero, so all of IQ comes from the environment","Heritability is about differences in a population, not the split within one child","Heritability applies only to physical traits like height, never to intelligence","Nothing is wrong; heritability gives each person’s exact genetic share of a trait"],"answer":1,"explanation":"Heritability is a population statistic about differences between people, not a recipe for one person; within an individual, genes and environment interact inseparably.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक B.Ed व्याख्याता कहता है, ‘बुद्धि की आनुवंशिकता लगभग 0.5 है, इसलिए प्रत्येक बच्चे के IQ का आधा जीन से और आधा पर्यावरण से आता है।’ इस कथन में क्या गलत है?","optionsHi":["बुद्धि की आनुवंशिकता वास्तव में शून्य है, इसलिए पूरा IQ पर्यावरण से आता है","आनुवंशिकता किसी जनसंख्या में अंतरों के बारे में है, किसी एक बच्चे के भीतर के विभाजन के बारे में नहीं","आनुवंशिकता केवल ऊँचाई जैसे शारीरिक लक्षणों पर लागू होती है, बुद्धि पर कभी नहीं","कुछ भी गलत नहीं; आनुवंशिकता किसी लक्षण में प्रत्येक व्यक्ति का ठीक आनुवंशिक हिस्सा बताती है"],"explanationHi":"आनुवंशिकता लोगों के बीच अंतरों के बारे में जनसंख्या-सांख्यिकी है, किसी एक व्यक्ति का नुस्ख़ा नहीं; किसी व्यक्ति के भीतर जीन और पर्यावरण अविभाज्य रूप से परस्पर क्रिया करते हैं।"},
  {"id":"cdp-child-development-1347","question":"Height is highly heritable, yet average heights in many countries rose noticeably within a few generations. What does this show?","options":["Height is not influenced by genes at all, only by food and exercise","Genes changed rapidly in those countries through new marriages over a few generations","Even a highly heritable trait can change when the environment, e.g. diet, improves","Heritability estimates are always wrong and should be ignored by scientists"],"answer":2,"explanation":"High heritability within a population does not mean a trait is fixed; improved nutrition and health raised average height across the population.","difficulty":"very-hard","source":"CTET Paper 2 · State TET","questionHi":"ऊँचाई की आनुवंशिकता उच्च है, फिर भी अनेक देशों में औसत ऊँचाई कुछ ही पीढ़ियों में उल्लेखनीय रूप से बढ़ी है। यह क्या दर्शाता है?","optionsHi":["ऊँचाई जीन से बिल्कुल प्रभावित नहीं होती, केवल भोजन और व्यायाम से","उन देशों में नए विवाहों के माध्यम से कुछ पीढ़ियों में जीन तेज़ी से बदले","अत्यधिक आनुवंशिक लक्षण भी तब बदल सकता है जब पर्यावरण, जैसे आहार, सुधरे","आनुवंशिकता के अनुमान हमेशा गलत होते हैं और वैज्ञानिकों को उन्हें अनदेखा करना चाहिए"],"explanationHi":"किसी जनसंख्या के भीतर उच्च आनुवंशिकता का अर्थ यह नहीं कि लक्षण स्थिर है; बेहतर पोषण और स्वास्थ्य ने पूरी जनसंख्या की औसत ऊँचाई बढ़ाई।"},
  {"id":"cdp-child-development-1348","question":"Identical twins raised in the same home have the same genes and many shared experiences, yet one becomes outgoing and the other reserved. Which explanation is best supported by behaviour-genetic research?","options":["One twin must secretly have been adopted, since identical twins always match","Personality is fixed at birth, so the difference is only an illusion","Their shared home environment caused the difference between them","Non-shared experiences such as different friends, teachers or illnesses"],"answer":3,"explanation":"Since genes and shared family environment are the same, differences arise from non-shared environmental influences unique to each twin.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक ही घर में पले समरूप जुड़वाँ के जीन समान हैं और अनुभव भी कई साझा हैं, फिर भी एक मिलनसार बनता है और दूसरा संकोची। व्यवहार-आनुवंशिक शोध द्वारा कौन-सी व्याख्या सबसे अच्छी तरह समर्थित है?","optionsHi":["एक जुड़वाँ को चुपचाप गोद लिया गया होगा, क्योंकि समरूप जुड़वाँ हमेशा मेल खाते हैं","व्यक्तित्व जन्म से निश्चित है, इसलिए अंतर केवल भ्रम है","उनके साझा घरेलू परिवेश ने उनके बीच अंतर पैदा किया","असाझा अनुभव, जैसे भिन्न मित्र, शिक्षक या बीमारियाँ"],"explanationHi":"चूँकि जीन और साझा पारिवारिक परिवेश समान हैं, अंतर प्रत्येक जुड़वाँ के लिए अद्वितीय असाझा पर्यावरणीय प्रभावों से उत्पन्न होते हैं।"},
  {"id":"cdp-child-development-1349","question":"In a twin study, identical (MZ) twins turn out to be no more alike on a trait than fraternal (DZ) twins of the same sex raised together. What is the most reasonable conclusion about that trait?","options":["Genes contribute little to it; shared environment probably matters more","It is entirely genetic, since both kinds of twins share genes and families","MZ twins must have different genes from each other for this trait","The trait cannot be studied scientifically because twins are too similar"],"answer":0,"explanation":"If doubling genetic similarity (DZ about 50% to MZ 100%) adds no extra resemblance, genes explain little of the variation; similarity then comes mainly from the shared environment.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक जुड़वाँ-अध्ययन में, समरूप (MZ) जुड़वाँ किसी लक्षण पर एक साथ पले समान-लिंग के भ्रातृ (DZ) जुड़वाँ से अधिक समान नहीं पाए जाते। उस लक्षण के बारे में सबसे उचित निष्कर्ष क्या है?","optionsHi":["जीन उसमें कम योगदान देते हैं; साझा पर्यावरण संभवतः अधिक मायने रखता है","वह पूरी तरह आनुवंशिक है, क्योंकि दोनों प्रकार के जुड़वाँ जीन और परिवार साझा करते हैं","इस लक्षण के लिए MZ जुड़वाँ के जीन एक-दूसरे से भिन्न होंगे","इस लक्षण का वैज्ञानिक अध्ययन नहीं हो सकता क्योंकि जुड़वाँ बहुत समान हैं"],"explanationHi":"यदि आनुवंशिक समानता को दोगुना करने (DZ लगभग 50% से MZ 100%) पर अतिरिक्त समानता नहीं बढ़ती, तो जीन भिन्नता को कम समझाते हैं; तब समानता मुख्यतः साझा परिवेश से आती है।"},
  {"id":"cdp-child-development-1350","question":"A child who suffers damage to the left side of the brain at age three regains much of her language ability, whereas an adult with similar damage often has lasting difficulty. Which principle does this best illustrate?","options":["Development is fixed and unchangeable once brain damage occurs","The developing brain shows greater plasticity in early life","Language is not located in the brain but learnt from others","Heredity alone determines how well a person recovers"],"answer":1,"explanation":"The young brain can reorganise functions to other areas more readily; plasticity is greatest early, though it continues to some extent throughout life.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"तीन वर्ष की आयु में मस्तिष्क के बाएँ भाग को क्षति झेलने वाली बच्ची अपनी भाषा-क्षमता का बड़ा भाग पुनः पा लेती है, जबकि समान क्षति वाले वयस्क को प्रायः स्थायी कठिनाई रहती है। यह किस सिद्धांत को सबसे अच्छी तरह दर्शाता है?","optionsHi":["मस्तिष्क-क्षति होने पर विकास निश्चित और अपरिवर्तनीय हो जाता है","विकसित हो रहा मस्तिष्क जीवन के आरंभ में अधिक प्लास्टिसिटी (नम्यता) दर्शाता है","भाषा मस्तिष्क में स्थित नहीं है बल्कि दूसरों से सीखी जाती है","केवल आनुवंशिकता तय करती है कि कोई व्यक्ति कितना ठीक होता है"],"explanationHi":"युवा मस्तिष्क प्रकार्यों को अन्य क्षेत्रों में अधिक आसानी से पुनर्गठित कर सकता है; नम्यता आरंभ में सर्वाधिक होती है, यद्यपि कुछ हद तक जीवन भर बनी रहती है।"},
  {"id":"cdp-child-development-1351","question":"Parents of a three-year-old want the pre-school to make him write full sentences in a notebook every day. Which principle should the teacher explain to them?","options":["Writing depends only on practice, so the more sentences he writes daily, the better","Children learn best through rote copying from the earliest possible age","Fine motor control matures gradually; pushing before readiness causes frustration","Children of three can master all adult skills if trained early enough"],"answer":2,"explanation":"Maturation sets readiness; three-year-olds still lack the fine motor control and perceptual skills for sustained writing, so drawing, play and large movements come first.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"तीन वर्ष के बच्चे के माता-पिता चाहते हैं कि पूर्व-विद्यालय उससे हर दिन कॉपी में पूरे वाक्य लिखवाए। शिक्षक को उन्हें कौन-सा सिद्धांत समझाना चाहिए?","optionsHi":["लेखन केवल अभ्यास पर निर्भर है, इसलिए वह रोज़ जितने अधिक वाक्य लिखे, उतना बेहतर","बच्चे सबसे जल्दी से जल्दी रटकर नकल करने से सबसे अच्छा सीखते हैं","सूक्ष्म गामक नियंत्रण धीरे-धीरे परिपक्व होता है; तैयारी से पहले ज़ोर देने से निराशा होती है","तीन वर्ष के बच्चे पर्याप्त जल्दी प्रशिक्षण मिलने पर सभी वयस्क कौशलों में निपुण हो सकते हैं"],"explanationHi":"परिपक्वता तत्परता तय करती है; तीन वर्ष के बच्चों में अभी निरंतर लेखन के लिए सूक्ष्म गामक नियंत्रण और प्रत्यक्षण-कौशल नहीं होते, इसलिए चित्रकारी, खेल और बड़ी गतियाँ पहले आती हैं।"},
  {"id":"cdp-child-development-1352","question":"Which of these changes depends mostly on maturation rather than learning?","options":["Reading Hindi fluently by Class 3","Riding a bicycle without training wheels","Using table manners at a family meal","Sitting without support in infancy"],"answer":3,"explanation":"Sitting unsupported appears in a predictable sequence given minimal ordinary opportunity; reading, cycling and manners need specific teaching or practice.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"इनमें से कौन-सा परिवर्तन अधिगम की अपेक्षा मुख्यतः परिपक्वता पर निर्भर करता है?","optionsHi":["कक्षा 3 तक हिंदी धाराप्रवाह पढ़ना","सहायक पहियों के बिना साइकिल चलाना","पारिवारिक भोजन में भोजन-शिष्टाचार का प्रयोग","शैशवावस्था में बिना सहारे बैठना"],"explanationHi":"बिना सहारे बैठना न्यूनतम सामान्य अवसर दिए जाने पर पूर्वानुमेय क्रम में प्रकट होता है; पढ़ने, साइकिल चलाने और शिष्टाचार के लिए विशिष्ट शिक्षण या अभ्यास चाहिए।"},
  {"id":"cdp-child-development-1353","question":"Assertion (A): Imprinting in goslings is usually described as occurring in a critical period, whereas language learning in humans is better described as having a sensitive period. Reason (R): A critical period is a fixed window outside which the development normally cannot occur, while a sensitive period is an optimal time outside which development is possible but harder.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Imprinting has a narrow, near-absolute window, while people can learn languages later, though less easily; the definitions in R explain why the two cases are labelled differently.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): गोस्लिंगों (बत्तख के बच्चों) में छाप (इंप्रिंटिंग) को प्रायः क्रांतिक अवधि में होने वाला बताया जाता है, जबकि मनुष्यों में भाषा-अधिगम को संवेदनशील अवधि वाला बताना बेहतर है। कारण (R): क्रांतिक अवधि निश्चित खिड़की है जिसके बाहर विकास सामान्यतः नहीं हो सकता, जबकि संवेदनशील अवधि इष्टतम समय है जिसके बाहर विकास संभव पर कठिन होता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"छाप की एक संकरी, लगभग निरपेक्ष खिड़की होती है, जबकि लोग भाषाएँ बाद में भी सीख सकते हैं, यद्यपि कम सहजता से; R की परिभाषाएँ बताती हैं कि दोनों मामलों को भिन्न नाम क्यों दिए जाते हैं।"},
  {"id":"cdp-child-development-1354","question":"Match the theorists with their main position on development: 1. Arnold Gesell 2. John B. Watson 3. Jean Piaget 4. Urie Bronfenbrenner; a. Development shaped by nested environmental systems interacting with the child b. Development is unfolding of maturation c. Development is shaped by environment and conditioning d. Child actively constructs knowledge through interaction of maturation and experience","options":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-a, 4-d","1-b, 2-c, 3-d, 4-a","1-d, 2-c, 3-b, 4-a"],"answer":2,"explanation":"Gesell stressed maturation, Watson environmental conditioning, Piaget active construction through interaction, and Bronfenbrenner nested ecological systems.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"सिद्धांतकारों का विकास पर उनके मुख्य मत से मिलान कीजिए: 1. आर्नल्ड गेसेल 2. जॉन बी. वॉटसन 3. जीन पियाजे 4. यूरी ब्रॉन्फ़ेनब्रेनर; a. विकास बच्चे के साथ परस्पर क्रिया करने वाली अंतर्निहित (नेस्टेड) पर्यावरणीय प्रणालियों से आकार पाता है b. विकास परिपक्वता का प्रकटीकरण है c. विकास पर्यावरण और अनुबंधन से आकार पाता है d. बच्चा परिपक्वता और अनुभव की अंतःक्रिया से सक्रिय रूप से ज्ञान का निर्माण करता है","optionsHi":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-a, 4-d","1-b, 2-c, 3-d, 4-a","1-d, 2-c, 3-b, 4-a"],"explanationHi":"गेसेल ने परिपक्वता, वॉटसन ने पर्यावरणीय अनुबंधन, पियाजे ने अंतःक्रिया द्वारा सक्रिय निर्माण, और ब्रॉन्फ़ेनब्रेनर ने अंतर्निहित पारिस्थितिक प्रणालियों पर बल दिया।"},
  {"id":"cdp-child-development-1355","question":"Which group of theorists all describe development mainly as a series of qualitatively distinct stages (a discontinuous view)?","options":["Watson, Skinner and Bandura","Piaget, Erikson and Kohlberg","Skinner, Thorndike and Pavlov","Bandura, Watson and Thorndike"],"answer":1,"explanation":"Piaget, Erikson and Kohlberg propose stage theories with qualitative shifts; behaviourists and social learning theorists see development as gradual, continuous accumulation of learning.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"सिद्धांतकारों का कौन-सा समूह विकास का वर्णन मुख्यतः गुणात्मक रूप से भिन्न अवस्थाओं की श्रृंखला (असतत दृष्टिकोण) के रूप में करता है?","optionsHi":["वॉटसन, स्किनर और बैंडूरा","पियाजे, एरिक्सन और कोहलबर्ग","स्किनर, थॉर्नडाइक और पावलोव","बैंडूरा, वॉटसन और थॉर्नडाइक"],"explanationHi":"पियाजे, एरिक्सन और कोहलबर्ग गुणात्मक परिवर्तनों वाले अवस्था-सिद्धांत प्रस्तावित करते हैं; व्यवहारवादी और सामाजिक अधिगम सिद्धांतकार विकास को अधिगम का क्रमिक, सतत संचय मानते हैं।"},
  {"id":"cdp-child-development-1356","question":"Adopted siblings raised in the same home are somewhat alike in IQ in early childhood, but by adolescence their scores are hardly more similar than those of unrelated children raised apart. What does this pattern most suggest?","options":["Shared family influence on IQ fades with age while genetic influence grows more evident","The shared family environment becomes stronger with age as children spend more time at home","Adopted children have no genes in common with anyone in the family, so they differ","IQ is affected by neither genes nor environment, so the scores simply drift"],"answer":0,"explanation":"Behaviour-genetic studies find that shared-environment effects on IQ fade by adolescence while heritability rises, partly as young people increasingly choose their own environments.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक ही घर में पले गोद लिए भाई-बहन प्रारंभिक बाल्यावस्था में IQ में कुछ समान होते हैं, पर किशोरावस्था तक उनके अंक अलग-अलग पले असंबंधित बच्चों से शायद ही अधिक समान होते हैं। यह प्रतिरूप सबसे अधिक क्या सुझाता है?","optionsHi":["IQ पर साझा पारिवारिक प्रभाव आयु के साथ क्षीण होता है जबकि आनुवंशिक प्रभाव अधिक स्पष्ट होता है","साझा पारिवारिक परिवेश आयु के साथ सशक्त होता है, क्योंकि बच्चे घर पर अधिक समय बिताते हैं","गोद लिए बच्चों के जीन परिवार में किसी से मेल नहीं खाते, इसलिए वे भिन्न होते हैं","IQ न जीन से प्रभावित होता है न पर्यावरण से, इसलिए अंक बस भटकते रहते हैं"],"explanationHi":"व्यवहार-आनुवंशिक अध्ययन पाते हैं कि IQ पर साझा-परिवेश के प्रभाव किशोरावस्था तक क्षीण हो जाते हैं जबकि आनुवंशिकता बढ़ती है, आंशिक रूप से इसलिए कि युवा अपने परिवेश स्वयं अधिकाधिक चुनते हैं।"},
  {"id":"cdp-child-development-1357","question":"Which of these statements reflect the lifespan perspective on development? I. Development continues throughout life. II. It involves both gains and losses. III. It retains some plasticity at all ages. IV. It is shaped by historical and cultural context.","options":["I and II only","I, II and III only","II, III and IV only","I, II, III and IV"],"answer":3,"explanation":"The lifespan view (Baltes) holds that development is lifelong, multidirectional, plastic and embedded in history and culture; all four statements fit.","difficulty":"very-hard","source":"CTET Paper 2 · State TET","questionHi":"इनमें से कौन-से कथन विकास के जीवन-अवधि दृष्टिकोण को दर्शाते हैं? I. विकास जीवन भर जारी रहता है। II. इसमें लाभ और हानि दोनों शामिल हैं। III. यह सभी आयु में कुछ नम्यता बनाए रखता है। IV. यह ऐतिहासिक और सांस्कृतिक संदर्भ से आकार पाता है।","optionsHi":["केवल I और II","केवल I, II और III","केवल II, III और IV","I, II, III और IV"],"explanationHi":"जीवन-अवधि दृष्टिकोण (बाल्टेस) मानता है कि विकास आजीवन, बहुदिशात्मक, नम्य और इतिहास तथा संस्कृति में निहित है; चारों कथन उपयुक्त हैं।"},
  {"id":"cdp-child-development-1358","question":"For a typical Class 9 student, which combination of stages is most likely?","options":["Erikson: industry vs inferiority; Kohlberg: preconventional; Piaget: concrete operational","Erikson: initiative vs guilt; Kohlberg: postconventional; Piaget: formal operational","Erikson: identity vs role confusion; Kohlberg: conventional; Piaget: formal operational","Erikson: intimacy vs isolation; Kohlberg: Stage 6; Piaget: concrete operational"],"answer":2,"explanation":"Fourteen- to fifteen-year-olds face the identity crisis, typically reason conventionally (Stages 3–4) and are developing formal operations.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 9 के एक सामान्य विद्यार्थी के लिए अवस्थाओं का कौन-सा संयोजन सबसे संभावित है?","optionsHi":["एरिक्सन: उद्यमशीलता बनाम हीनता; कोहलबर्ग: पूर्व-रूढ़िगत; पियाजे: मूर्त संक्रियात्मक","एरिक्सन: पहल बनाम अपराध-बोध; कोहलबर्ग: उत्तर-रूढ़िगत; पियाजे: औपचारिक संक्रियात्मक","एरिक्सन: पहचान बनाम भूमिका-भ्रम; कोहलबर्ग: रूढ़िगत; पियाजे: औपचारिक संक्रियात्मक","एरिक्सन: घनिष्ठता बनाम अलगाव; कोहलबर्ग: चरण 6; पियाजे: मूर्त संक्रियात्मक"],"explanationHi":"चौदह से पंद्रह वर्ष के किशोर पहचान के संकट का सामना करते हैं, सामान्यतः रूढ़िगत ढंग से तर्क करते हैं (चरण 3–4) और औपचारिक संक्रियाएँ विकसित कर रहे होते हैं।"},
  {"id":"cdp-child-development-1359","question":"Assertion (A): Piaget’s heteronomous morality corresponds broadly to Kohlberg’s preconventional level. Reason (R): In both, young children judge right and wrong by authority, rules imposed by adults and the consequences that follow.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both describe young children’s externally controlled morality, judged by authority and consequences; Kohlberg built on Piaget, which is why they line up.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"अभिकथन (A): पियाजे की परतंत्र नैतिकता मोटे तौर पर कोहलबर्ग के पूर्व-रूढ़िगत स्तर से मेल खाती है। कारण (R): दोनों में छोटे बच्चे सही और गलत का निर्णय अधिकार, वयस्कों द्वारा थोपे नियमों और उसके बाद आने वाले परिणामों से करते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों छोटे बच्चों की बाह्य रूप से नियंत्रित नैतिकता का वर्णन करते हैं, जिसका निर्णय अधिकार और परिणामों से होता है; कोहलबर्ग ने पियाजे पर निर्माण किया, इसीलिए वे मेल खाते हैं।"},
  {"id":"cdp-child-development-1360","question":"Children from poor families who attended a high-quality pre-school programme showed better school readiness, and some long-term studies found fewer dropouts and better adult outcomes. Which principle of development do such findings most support?","options":["Development is fixed by heredity, so early programmes cannot have any lasting effect","Only experiences in adolescence matter for adult outcomes, not early ones","Development is cumulative, so enriched early settings can have lasting effects","Pre-school education harms children by pushing them into academics too early"],"answer":2,"explanation":"Early experience lays the foundation for later learning; quality early childhood care and education, like the aim of ICDS and NEP’s focus on ECCE, can change developmental trajectories.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"जो गरीब परिवारों के बच्चे उच्च-गुणवत्ता वाले पूर्व-विद्यालयी कार्यक्रम में गए, उन्होंने बेहतर विद्यालय-तत्परता दिखाई, और कुछ दीर्घकालिक अध्ययनों ने विद्यालय छोड़ने की कम दर और बेहतर वयस्क परिणाम पाए। ऐसे निष्कर्ष विकास के किस सिद्धांत का सबसे अधिक समर्थन करते हैं?","optionsHi":["विकास आनुवंशिकता से निश्चित है, इसलिए प्रारंभिक कार्यक्रमों का कोई स्थायी प्रभाव नहीं हो सकता","वयस्क परिणामों के लिए केवल किशोरावस्था के अनुभव मायने रखते हैं, आरंभिक नहीं","विकास संचयी है, इसलिए समृद्ध प्रारंभिक परिवेशों के स्थायी प्रभाव हो सकते हैं","पूर्व-विद्यालयी शिक्षा बच्चों को बहुत जल्दी शैक्षिक कार्य में धकेलकर उन्हें हानि पहुँचाती है"],"explanationHi":"प्रारंभिक अनुभव आगे के अधिगम की नींव रखता है; उच्च-गुणवत्ता वाली प्रारंभिक बाल्यावस्था देखभाल और शिक्षा, ICDS के उद्देश्य और ECCE पर NEP के बल की तरह, विकास-पथ बदल सकती है।"},
  {"id":"cdp-child-development-1361","question":"A teacher says, ‘Intelligence is inherited, so remedial teaching for slow learners is a waste of time.’ Which is the strongest reply based on child development research?","options":["She is right, since heredity fixes all mental abilities from the moment of birth","Heredity sets broad potential, but teaching strongly affects how much is realised","Intelligence is wholly environmental, so heredity is irrelevant to the debate","Remedial teaching works only for children with high IQ, not slow learners"],"answer":1,"explanation":"Genetic influence does not mean unchangeability; learning opportunities and good teaching substantially affect achievement. Rejecting heredity entirely is the opposite error.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"एक शिक्षिका कहती है, ‘बुद्धि वंशानुगत है, इसलिए मंद अधिगमकर्ताओं के लिए उपचारात्मक शिक्षण समय की बर्बादी है।’ बाल विकास शोध पर आधारित सबसे सशक्त उत्तर क्या है?","optionsHi":["वह सही है, क्योंकि आनुवंशिकता जन्म के क्षण से ही सभी मानसिक योग्यताओं को निश्चित कर देती है","आनुवंशिकता व्यापक क्षमता निर्धारित करती है, पर शिक्षण दृढ़ता से प्रभावित करता है कि कितनी साकार होती है","बुद्धि पूर्णतः पर्यावरणीय है, इसलिए आनुवंशिकता बहस के लिए अप्रासंगिक है","उपचारात्मक शिक्षण केवल उच्च IQ वाले बच्चों पर काम करता है, मंद अधिगमकर्ताओं पर नहीं"],"explanationHi":"आनुवंशिक प्रभाव का अर्थ अपरिवर्तनीयता नहीं है; अधिगम के अवसर और अच्छा शिक्षण उपलब्धि को काफ़ी प्रभावित करते हैं। आनुवंशिकता को पूरी तरह अस्वीकार करना उलटी त्रुटि है।"},
  {"id":"cdp-child-development-1362","question":"A child’s first drawings are scribbles, then circles and lines, then ‘tadpole’ figures, and only later realistic human figures with body parts in proportion. Which principle does this sequence mainly show?","options":["Development is unpredictable and random, varying from child to child","Development proceeds from simple and general to complex and specific","Development depends only on heredity, as drawing is an inborn talent","Development proceeds from specific details to general wholes"],"answer":1,"explanation":"Drawing moves from undifferentiated scribbles to differentiated, detailed forms, illustrating the simple-to-complex, general-to-specific direction of development.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"बच्चे की पहली आकृतियाँ आड़ी-तिरछी रेखाएँ होती हैं, फिर वृत्त और रेखाएँ, फिर ‘टैडपोल’ आकृतियाँ, और बहुत बाद में अनुपात में शरीर के अंगों वाली यथार्थवादी मानव आकृतियाँ। यह क्रम मुख्यतः किस सिद्धांत को दर्शाता है?","optionsHi":["विकास अप्रत्याशित और यादृच्छिक है, बच्चे-बच्चे में बदलता है","विकास सरल और सामान्य से जटिल और विशिष्ट की ओर बढ़ता है","विकास केवल आनुवंशिकता पर निर्भर है, क्योंकि चित्रकारी जन्मजात प्रतिभा है","विकास विशिष्ट ब्योरों से सामान्य पूर्णों की ओर बढ़ता है"],"explanationHi":"चित्रकारी अविभेदित आड़ी-तिरछी रेखाओं से विभेदित, विस्तृत रूपों की ओर जाती है, जो विकास की सरल-से-जटिल, सामान्य-से-विशिष्ट दिशा को दर्शाती है।"},
  {"id":"cdp-child-development-1363","question":"A Class 3 teacher introduces fractions by sharing rotis and folding paper strips before writing symbols such as 1/2 and 3/4. Which principle of development guides her?","options":["Development proceeds from concrete to abstract","Development proceeds from abstract to concrete","Development is cephalocaudal","Development is reversible"],"answer":0,"explanation":"Children of this age think best with concrete, manipulable experiences; abstract symbols are introduced after concrete understanding is built.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक शिक्षिका 1/2 और 3/4 जैसे प्रतीक लिखने से पहले रोटियाँ बाँटकर और कागज़ की पट्टियाँ मोड़कर भिन्नों से परिचित कराती है। कौन-सा विकास-सिद्धांत उसका मार्गदर्शन करता है?","optionsHi":["विकास मूर्त से अमूर्त की ओर बढ़ता है","विकास अमूर्त से मूर्त की ओर बढ़ता है","विकास शीर्षाभिमुख (सेफ़ालोकॉडल) है","विकास उत्क्रमणीय है"],"explanationHi":"इस आयु के बच्चे मूर्त, हाथ से सँभाले जा सकने वाले अनुभवों से सबसे अच्छा सोचते हैं; अमूर्त प्रतीक मूर्त समझ बनने के बाद प्रस्तुत किए जाते हैं।"},
  {"id":"cdp-child-development-1364","question":"Which statement about heredity and environment is most accurate?","options":["Heredity determines physical traits, environment determines psychological traits","Their effects can be simply added up, e.g. 60% + 40%, for each individual","Heredity is important only before birth, environment only after birth","Heredity and environment interact; the effect of one often depends on the other"],"answer":3,"explanation":"Genes and environment interact: the same environment affects children with different genes differently and vice versa, so neat percentage splits for an individual are meaningless. Physical traits are also affected by environment, e.g. nutrition.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"आनुवंशिकता और पर्यावरण के बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["आनुवंशिकता शारीरिक लक्षण निर्धारित करती है, पर्यावरण मनोवैज्ञानिक लक्षण","उनके प्रभाव प्रत्येक व्यक्ति के लिए सीधे जोड़े जा सकते हैं, जैसे 60% + 40%","आनुवंशिकता केवल जन्म से पहले महत्त्वपूर्ण है, पर्यावरण केवल जन्म के बाद","आनुवंशिकता और पर्यावरण परस्पर क्रिया करते हैं; एक का प्रभाव प्रायः दूसरे पर निर्भर करता है"],"explanationHi":"जीन और पर्यावरण परस्पर क्रिया करते हैं: एक ही पर्यावरण भिन्न जीन वाले बच्चों को भिन्न रूप से प्रभावित करता है और इसका उलटा भी, इसलिए किसी व्यक्ति के लिए साफ़ प्रतिशत विभाजन अर्थहीन है। शारीरिक लक्षण भी पर्यावरण से प्रभावित होते हैं, जैसे पोषण।"},
  {"id":"cdp-child-development-1365","question":"Assertion (A): Children of the same age in a class differ widely in height, temperament and learning pace. Reason (R): Each child has a unique combination of heredity and environment.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Individual differences arise because no two children (except identical twins in genes) share the same heredity and environment; R explains A.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"अभिकथन (A): कक्षा में समान आयु के बच्चे ऊँचाई, स्वभाव और अधिगम की गति में बहुत भिन्न होते हैं। कारण (R): प्रत्येक बच्चे में आनुवंशिकता और पर्यावरण का अद्वितीय संयोजन होता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"वैयक्तिक भिन्नताएँ इसलिए उत्पन्न होती हैं कि कोई दो बच्चे (जीन में समरूप जुड़वाँ को छोड़कर) एक ही आनुवंशिकता और पर्यावरण साझा नहीं करते; R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-1366","question":"Which observation is the strongest evidence that development is directed by an inner timetable as well as by experience?","options":["Children in different cultures learn to speak quite different languages from an early age","Children everywhere sit, stand and walk in the same order, at slightly different ages","Children of literate parents usually learn to read earlier than other children","Children who practise cricket regularly bat better than those who do not"],"answer":1,"explanation":"A common motor sequence across cultures points to maturation; the differences in age reflect environment and individual variation. The other options show the effect of experience.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कौन-सा अवलोकन इस बात का सबसे मज़बूत प्रमाण है कि विकास अनुभव के साथ-साथ किसी आंतरिक समय-सारणी द्वारा भी निर्देशित होता है?","optionsHi":["विभिन्न संस्कृतियों के बच्चे बहुत भिन्न भाषाएँ बोलना आरंभ से ही सीखते हैं","हर जगह बच्चे एक ही क्रम में बैठते, खड़े होते और चलते हैं, थोड़े भिन्न आयु पर","साक्षर माता-पिता के बच्चे प्रायः अन्य बच्चों से जल्दी पढ़ना सीखते हैं","जो बच्चे नियमित क्रिकेट का अभ्यास करते हैं वे नहीं करने वालों से बेहतर बल्लेबाज़ी करते हैं"],"explanationHi":"संस्कृतियों में एक-सा गामक क्रम परिपक्वता की ओर संकेत करता है; आयु में अंतर पर्यावरण और वैयक्तिक भिन्नता को दर्शाते हैं। अन्य विकल्प अनुभव का प्रभाव दिखाते हैं।"},
  {"id":"cdp-child-development-1367","question":"A child is born with a genetic tendency toward shyness. In one family she is gently encouraged to join new activities and grows into a moderately outgoing teenager; in another she is overprotected and becomes very withdrawn. This illustrates that:","options":["Temperament is entirely learnt, since the two outcomes differ so much from each other","Genetic tendencies are unaffected by parenting, whatever the family does","Environment can only make traits more extreme, never soften them","A genetic tendency’s outcome depends on how the environment responds to it"],"answer":3,"explanation":"Thomas and Chess’s idea of goodness of fit: development depends on the match between a child’s temperament and the demands and responses of the environment.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक बच्ची जन्म से संकोच की आनुवंशिक प्रवृत्ति के साथ पैदा होती है। एक परिवार में उसे नई गतिविधियों में शामिल होने के लिए कोमलता से प्रोत्साहित किया जाता है और वह मध्यम रूप से मिलनसार किशोरी बनती है; दूसरे में उसकी अतिरक्षा की जाती है और वह बहुत अंतर्मुखी बन जाती है। यह दर्शाता है कि:","optionsHi":["स्वभाव पूर्णतः सीखा जाता है, क्योंकि दोनों परिणाम एक-दूसरे से बहुत भिन्न हैं","आनुवंशिक प्रवृत्तियाँ पालन-पोषण से अप्रभावित रहती हैं, परिवार जो भी करे","पर्यावरण केवल लक्षणों को अधिक चरम बना सकता है, कभी नरम नहीं कर सकता","आनुवंशिक प्रवृत्ति का परिणाम इस पर निर्भर करता है कि पर्यावरण उस पर कैसी प्रतिक्रिया देता है"],"explanationHi":"थॉमस और चेस का सुयोग्यता (गुडनेस ऑफ़ फ़िट) का विचार: विकास बच्चे के स्वभाव और पर्यावरण की माँगों तथा प्रतिक्रियाओं के बीच मेल पर निर्भर करता है।"},
  {"id":"cdp-child-development-1368","question":"Which of these classroom practices best respects the principle that the rate of development differs across children while its sequence is similar?","options":["Same worksheet at the same pace for all, and repeating the year for any who lag","Different syllabi for each child, with no shared goals for the class","Common goals in a sensible sequence, with flexible pacing and varied support","Grouping children by age alone and expecting identical progress from all"],"answer":2,"explanation":"Keep the developmental sequence but vary pace and support: differentiation within common goals fits both a common sequence and individual rates.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"इस सिद्धांत का कि विकास की दर बच्चों में भिन्न होती है जबकि उसका क्रम समान रहता है, कौन-सा कक्षा-अभ्यास सबसे अच्छी तरह सम्मान करता है?","optionsHi":["सबके लिए एक ही कार्यपत्रक एक ही गति से, और पिछड़ने वालों का वर्ष दोहराना","प्रत्येक बच्चे के लिए भिन्न पाठ्यक्रम, कक्षा के लिए कोई साझा लक्ष्य नहीं","समझदार क्रम में साझा लक्ष्य, लचीली गति और विविध सहायता के साथ","बच्चों को केवल आयु के आधार पर समूहबद्ध करना और सबसे समान प्रगति की अपेक्षा करना"],"explanationHi":"विकासात्मक क्रम बनाए रखें पर गति और सहायता बदलें: साझा लक्ष्यों के भीतर विभेदन साझा क्रम और वैयक्तिक दरों दोनों के अनुरूप है।"},
  {"id":"cdp-child-development-1369","question":"Thomas and Chess classified infant temperament into ‘easy’, ‘difficult’ and ‘slow-to-warm-up’. A Class 1 child takes a long time to join new activities, watches quietly first and then participates well. What is the best teacher response?","options":["Push her into every activity immediately, so that she builds up confidence quickly","Give her time to observe, introduce new things gradually and encourage gently","Label her as having a learning difficulty and refer her for testing","Leave her alone permanently, as she clearly prefers to watch others"],"answer":1,"explanation":"Slow-to-warm-up children adapt well when given time; patient, gradual exposure provides a good fit, while pressure or neglect makes adjustment harder.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"थॉमस और चेस ने शिशु स्वभाव को ‘सहज’, ‘कठिन’ और ‘देर से खुलने वाले’ में वर्गीकृत किया। कक्षा 1 की एक बच्ची नई गतिविधियों में शामिल होने में बहुत समय लेती है, पहले चुपचाप देखती है और फिर अच्छी तरह भाग लेती है। शिक्षक की सर्वोत्तम प्रतिक्रिया क्या है?","optionsHi":["उसे हर गतिविधि में तुरंत धकेलना, ताकि वह जल्दी आत्मविश्वास बनाए","उसे देखने का समय देना, नई चीज़ें धीरे-धीरे प्रस्तुत करना और कोमलता से प्रोत्साहित करना","उसे अधिगम कठिनाई वाली का लेबल देना और जाँच के लिए भेजना","उसे स्थायी रूप से अकेला छोड़ देना, क्योंकि वह स्पष्टतः दूसरों को देखना पसंद करती है"],"explanationHi":"देर से खुलने वाले बच्चे समय दिए जाने पर अच्छी तरह अनुकूलित हो जाते हैं; धैर्यपूर्ण, क्रमिक संपर्क अच्छा सुयोग्य मेल देता है, जबकि दबाव या उपेक्षा समायोजन कठिन बनाती है।"},
  {"id":"cdp-child-development-1370","question":"How many of these did Bruner list as features that a theory of instruction should specify? I. The experiences that predispose a learner to learn. II. How a body of knowledge should be structured so that the learner can grasp it. III. The most effective sequences in which to present material. IV. The nature and pacing of rewards and feedback.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"In ‘Toward a Theory of Instruction’ Bruner named all four: predisposition, structure, sequence, and the nature and pacing of reinforcement. Each is a design choice for the teacher.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"इनमें से कितने को ब्रूनर ने उन विशेषताओं के रूप में सूचीबद्ध किया जिन्हें अनुदेशन के सिद्धांत को निर्दिष्ट करना चाहिए? I. वे अनुभव जो अधिगमकर्ता को सीखने के लिए प्रवृत्त करते हैं। II. ज्ञान-समूह को कैसे संरचित किया जाए कि अधिगमकर्ता उसे समझ सके। III. सामग्री प्रस्तुत करने के सबसे प्रभावी क्रम। IV. पुरस्कारों और प्रतिक्रिया की प्रकृति और गति।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"‘टुवर्ड ए थ्योरी ऑफ़ इंस्ट्रक्शन’ में ब्रूनर ने चारों का नाम लिया: पूर्वप्रवृत्ति, संरचना, क्रम, तथा पुनर्बलन की प्रकृति और गति। प्रत्येक शिक्षक के लिए अभिकल्प-निर्णय है।"},
  {"id":"cdp-child-development-1371","question":"Bruner described learning a subject as involving three almost simultaneous processes. A Class 8 student reads about Newton’s laws (P), applies them to explain why passengers lurch forward when a bus brakes (Q), and checks whether her explanation fits the facts (R). These are respectively:","options":["Acquisition, transformation and evaluation","Assimilation, accommodation and equilibration","Enactive, iconic and symbolic representation","Transformation, evaluation and acquisition"],"answer":0,"explanation":"Bruner’s three processes are acquiring new information, transforming it to fit new tasks, and evaluating whether the handling is adequate. The Piagetian terms describe adaptation, not these processes.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"ब्रूनर ने किसी विषय के अधिगम को तीन लगभग एक साथ होने वाली प्रक्रियाओं से जुड़ा बताया। कक्षा 8 की एक विद्यार्थी न्यूटन के नियमों के बारे में पढ़ती है (P), उन्हें यह समझाने में लागू करती है कि बस के ब्रेक लगाने पर यात्री आगे क्यों झुकते हैं (Q), और जाँचती है कि उसकी व्याख्या तथ्यों से मेल खाती है या नहीं (R)। ये क्रमशः हैं:","optionsHi":["अर्जन, रूपांतरण और मूल्यांकन","आत्मसात्करण, समायोजन और साम्य-स्थापन","क्रियात्मक, आइकॉनिक और प्रतीकात्मक निरूपण","रूपांतरण, मूल्यांकन और अर्जन"],"explanationHi":"ब्रूनर की तीन प्रक्रियाएँ हैं नई सूचना अर्जित करना, उसे नए कार्यों के अनुरूप रूपांतरित करना, और मूल्यांकन करना कि उसका संचालन पर्याप्त है या नहीं। पियाजे की शब्दावली अनुकूलन का वर्णन करती है, इन प्रक्रियाओं का नहीं।"},
  {"id":"cdp-child-development-1372","question":"A Class 7 social science teacher teaches the Mughal period through the life stories of a farmer, a merchant and a court painter, inviting students to imagine their choices. Bruner described this way of making sense of experience through stories of human intentions as:","options":["The paradigmatic (logical-scientific) mode","The enactive mode","The narrative mode","Operant shaping"],"answer":2,"explanation":"Bruner later distinguished the paradigmatic mode, which seeks logical proof, from the narrative mode, which organises experience as stories about people and intentions. Both are ways of thinking that schools should develop.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"कक्षा 7 का एक सामाजिक विज्ञान शिक्षक मुग़ल काल को एक किसान, एक व्यापारी और एक दरबारी चित्रकार की जीवन-कथाओं के माध्यम से पढ़ाता है, विद्यार्थियों को उनके विकल्पों की कल्पना करने को आमंत्रित करते हुए। ब्रूनर ने मानवीय आशयों की कहानियों के माध्यम से अनुभव को समझने के इस तरीके को क्या कहा?","optionsHi":["प्रतिमानात्मक (तार्किक-वैज्ञानिक) विधा","क्रियात्मक विधा","वर्णनात्मक (नैरेटिव) विधा","क्रियाप्रसूत आकार देना"],"explanationHi":"ब्रूनर ने बाद में प्रतिमानात्मक विधा, जो तार्किक प्रमाण खोजती है, को वर्णनात्मक विधा से अलग किया, जो अनुभव को लोगों और आशयों की कहानियों के रूप में संगठित करती है। दोनों चिंतन के ढंग हैं जिन्हें विद्यालयों को विकसित करना चाहिए।"},
  {"id":"cdp-child-development-1373","question":"Which pairing correctly contrasts Bruner and Ausubel?","options":["Bruner: rote memorisation of facts and rules; Ausubel: pure discovery learning","Bruner: discovery learning; Ausubel: meaningful reception with advance organisers","Both: learning mainly by conditioning and reinforcing correct responses","Bruner: advance organisers before lessons; Ausubel: spiral curriculum and discovery"],"answer":1,"explanation":"Bruner favoured learners discovering structure from instances, while Ausubel held that well-organised expository teaching, introduced with advance organisers, produces meaningful learning. Neither supported rote learning.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कौन-सा जोड़ा ब्रूनर और ऑसुबेल की सही तुलना करता है?","optionsHi":["ब्रूनर: तथ्यों और नियमों की रटंत; ऑसुबेल: शुद्ध खोज अधिगम","ब्रूनर: खोज अधिगम; ऑसुबेल: अग्रिम संगठकों के साथ सार्थक ग्रहणात्मक अधिगम","दोनों: मुख्यतः अनुबंधन और सही अनुक्रियाओं के पुनर्बलन से अधिगम","ब्रूनर: पाठों से पहले अग्रिम संगठक; ऑसुबेल: सर्पिल पाठ्यचर्या और खोज"],"explanationHi":"ब्रूनर ने अधिगमकर्ताओं द्वारा उदाहरणों से संरचना खोजने का पक्ष लिया, जबकि ऑसुबेल का मत था कि अग्रिम संगठकों से आरंभ किया गया सुसंगठित व्याख्यात्मक शिक्षण सार्थक अधिगम उत्पन्न करता है। दोनों में से किसी ने रटंत अधिगम का समर्थन नहीं किया।"},
  {"id":"cdp-child-development-1374","question":"In the NCERT mathematics sequence, children meet ‘half’ and ‘quarter’ by sharing objects in early classes, add and subtract fractions later, and study rational numbers in Class 8. This design follows:","options":["Bruner’s spiral curriculum","Piaget’s horizontal décalage","Skinner’s programmed instruction","Vygotsky’s private speech"],"answer":0,"explanation":"Revisiting a concept at increasing depth and formality across years is the spiral curriculum. Programmed instruction is about small, reinforced steps within a single sequence.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"NCERT की गणित शृंखला में, बच्चे आरंभिक कक्षाओं में वस्तुएँ बाँटकर ‘आधा’ और ‘चौथाई’ से परिचित होते हैं, बाद में भिन्नों को जोड़ते-घटाते हैं और कक्षा 8 में परिमेय संख्याओं का अध्ययन करते हैं। यह अभिकल्प किसका अनुसरण करता है?","optionsHi":["ब्रूनर की सर्पिल पाठ्यचर्या","पियाजे का क्षैतिज डेकैलाज","स्किनर का अभिक्रमित अनुदेशन","वाइगोत्स्की का निजी वाक्"],"explanationHi":"किसी अवधारणा को वर्षों में बढ़ती गहराई और औपचारिकता के साथ फिर-फिर देखना सर्पिल पाठ्यचर्या है। अभिक्रमित अनुदेशन एक ही क्रम के भीतर छोटे, पुनर्बलित चरणों के बारे में है।"},
  {"id":"cdp-child-development-1375","question":"A teacher says, ‘Class 2 children are too young for any idea of probability.’ How would Bruner most likely respond?","options":["Agree, since probability is purely symbolic and must wait until Class 10 or later","Agree, since young children cannot learn anything abstract at all before Class 6","Disagree, but only for gifted children who already think symbolically","Disagree: it can be taught honestly, e.g. through ‘more likely, less likely’ games"],"answer":3,"explanation":"Bruner’s hypothesis is that any subject can be introduced in some intellectually honest form at any age by matching the child’s mode of thinking. Simple chance games are such a form.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"एक शिक्षक कहता है, ‘कक्षा 2 के बच्चे प्रायिकता के किसी भी विचार के लिए बहुत छोटे हैं।’ ब्रूनर सबसे संभवतः कैसे उत्तर देंगे?","optionsHi":["सहमत होते, क्योंकि प्रायिकता विशुद्ध प्रतीकात्मक है और कक्षा 10 या उसके बाद तक रुकनी चाहिए","सहमत होते, क्योंकि छोटे बच्चे कक्षा 6 से पहले कोई अमूर्त चीज़ नहीं सीख सकते","असहमत होते, पर केवल प्रतिभाशाली बच्चों के लिए जो पहले से प्रतीकात्मक चिंतन करते हैं","असहमत होते: इसे ईमानदारी से पढ़ाया जा सकता है, जैसे ‘अधिक संभावित, कम संभावित’ खेलों से"],"explanationHi":"ब्रूनर की परिकल्पना है कि बच्चे के चिंतन की विधा से मेल बिठाकर किसी भी आयु में किसी भी विषय को किसी बौद्धिक रूप से ईमानदार रूप में प्रस्तुत किया जा सकता है। सरल संयोग-खेल ऐसा ही एक रूप हैं।"},
  {"id":"cdp-child-development-1376","question":"In a variation of the water-pouring task, children were asked to predict the water level and say whether the amount would be the same while the glasses were hidden behind a screen. Many more young children gave conserving answers than in the standard task. Bruner used such findings to argue that:","options":["Conservation depends only on maturation, so the screen should have made no difference","Young children already have formal operations, which the screen simply revealed","The look of the glasses (iconic) can override reasoning, which language can help fix","The screen created the disequilibrium that Piaget had predicted for this age"],"answer":2,"explanation":"Bruner suggested that young children are dominated by visual appearance; when it is removed and they rely on verbal reasoning, they conserve more. He linked growth to the symbolic mode and language.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"जल उँडेलने के कार्य के एक रूपांतर में, बच्चों से जल-स्तर का पूर्वानुमान लगाने और यह बताने को कहा गया कि गिलास पर्दे के पीछे छिपे होने पर मात्रा समान रहेगी या नहीं। मानक कार्य की तुलना में कहीं अधिक छोटे बच्चों ने संरक्षण वाले उत्तर दिए। ब्रूनर ने ऐसे निष्कर्षों का उपयोग यह तर्क देने के लिए किया कि:","optionsHi":["संरक्षण केवल परिपक्वता पर निर्भर है, इसलिए पर्दे से कोई अंतर नहीं पड़ना चाहिए था","छोटे बच्चों में पहले से औपचारिक संक्रियाएँ हैं, जिन्हें पर्दे ने बस प्रकट कर दिया","गिलासों का दिखना (आइकॉनिक) तर्कण को दबा सकता है, जिसे भाषा ठीक करने में सहायक हो सकती है","पर्दे ने वह असंतुलन पैदा किया जिसका पियाजे ने इस आयु के लिए पूर्वानुमान किया था"],"explanationHi":"ब्रूनर ने सुझाया कि छोटे बच्चों पर दृश्य रूप-रंग हावी रहता है; उसे हटाने और उनके शाब्दिक तर्कण पर निर्भर होने पर वे अधिक संरक्षण करते हैं। उन्होंने वृद्धि को प्रतीकात्मक विधा और भाषा से जोड़ा।"},
  {"id":"cdp-child-development-1377","question":"During a guided discovery lesson, Class 6 students conclude that ‘all even numbers are divisible by 4’ after checking 4, 8, 12 and 16. The best next move for a Bruner-style teacher is to:","options":["Accept the rule, since discovery must never be corrected by the teacher","Ask them to test it with 6 and 10 and decide whether their rule must change","Tell them the correct rule straight away and move on to the next topic","Give them marks for discovering a rule, to reward their effort and initiative"],"answer":1,"explanation":"In guided discovery the teacher supplies examples or questions that challenge over-generalisations so that students refine the rule themselves. Simply telling the answer ends their discovery.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"निर्देशित खोज वाले पाठ के दौरान, कक्षा 6 के विद्यार्थी 4, 8, 12 और 16 को जाँचने के बाद निष्कर्ष निकालते हैं कि ‘सभी सम संख्याएँ 4 से विभाज्य हैं’। ब्रूनर-शैली के शिक्षक के लिए सर्वोत्तम अगला कदम है:","optionsHi":["नियम स्वीकार करना, क्योंकि खोज को शिक्षक द्वारा कभी सुधारा नहीं जाना चाहिए","उनसे इसे 6 और 10 से परखने और तय करने को कहना कि उनका नियम बदलना होगा या नहीं","उन्हें तुरंत सही नियम बता देना और अगले विषय पर बढ़ जाना","नियम खोजने के लिए अंक देना, उनके प्रयास और पहल को पुरस्कृत करने के लिए"],"explanationHi":"निर्देशित खोज में शिक्षक ऐसे उदाहरण या प्रश्न देता है जो अति-सामान्यीकरणों को चुनौती दें ताकि विद्यार्थी स्वयं नियम को परिष्कृत करें। केवल उत्तर बता देना उनकी खोज समाप्त कर देता है।"},
  {"id":"cdp-child-development-1378","question":"Why did Bruner regard the symbolic mode as especially powerful?","options":["It lets ideas be held compactly and handled by rules, even when things are absent","It is the only mode infants can use, so it underlies all later thinking","It does not depend on language at all, so it works for every learner","It removes the need for any concrete experience at all once a child reaches school"],"answer":0,"explanation":"Symbols such as words and numbers are arbitrary, compact and rule-governed, allowing reasoning about absent and abstract things. Bruner still saw enactive and iconic forms as useful foundations.","difficulty":"hard","source":"CTET · State TETs","questionHi":"ब्रूनर प्रतीकात्मक विधा को विशेष रूप से शक्तिशाली क्यों मानते थे?","optionsHi":["यह वस्तुओं के अनुपस्थित होने पर भी विचारों को संक्षिप्त रूप से धारण करने और नियमों से संचालित करने देती है","यह एकमात्र विधा है जिसका शिशु उपयोग कर सकते हैं, इसलिए सभी आगे के चिंतन का आधार है","यह भाषा पर बिल्कुल निर्भर नहीं है, इसलिए हर अधिगमकर्ता के लिए काम करती है","यह बच्चे के विद्यालय पहुँचने पर किसी भी ठोस अनुभव की आवश्यकता को समाप्त कर देती है"],"explanationHi":"शब्द और संख्याएँ जैसे प्रतीक मनमाने, संक्षिप्त और नियम-शासित होते हैं, जो अनुपस्थित और अमूर्त चीज़ों के बारे में तर्कण की अनुमति देते हैं। ब्रूनर फिर भी क्रियात्मक और आइकॉनिक रूपों को उपयोगी नींव मानते थे।"},
  {"id":"cdp-child-development-1379","question":"Consider these statements. 1. Bruner, like Vygotsky, gave adults and culture a central role in children’s learning. 2. Bruner introduced the idea of scaffolding with colleagues in a study of tutoring. 3. Bruner held that children must wait for the right stage before any subject can be introduced. Which is/are correct?","options":["1 only","1 and 3 only","1 and 2 only","2 and 3 only"],"answer":2,"explanation":"Bruner was strongly influenced by Vygotsky and co-authored the 1976 tutoring study that introduced scaffolding. Statement 3 is the opposite of his view on readiness.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"इन कथनों पर विचार कीजिए। 1. ब्रूनर ने, वाइगोत्स्की की तरह, बच्चों के अधिगम में वयस्कों और संस्कृति को केंद्रीय भूमिका दी। 2. ब्रूनर ने सहकर्मियों के साथ ट्यूटरिंग के एक अध्ययन में पाड़ का विचार प्रस्तुत किया। 3. ब्रूनर का मत था कि किसी भी विषय को प्रस्तुत करने से पहले बच्चों को सही अवस्था की प्रतीक्षा करनी चाहिए। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 3","केवल 1 और 2","केवल 2 और 3"],"explanationHi":"ब्रूनर वाइगोत्स्की से गहराई से प्रभावित थे और उन्होंने 1976 के ट्यूटरिंग अध्ययन का सह-लेखन किया जिसने पाड़ का विचार प्रस्तुत किया। कथन 3 तत्परता पर उनके मत के विपरीत है।"},
  {"id":"cdp-child-development-1380","question":"Match the Bruner idea with its description. P. Spiral curriculum Q. LASS R. Discovery learning S. Enactive mode; 1. Knowing through action 2. Learners find principles from examples 3. Adult routines that support a child’s language 4. Revisiting topics at higher levels","options":["P-4, Q-3, R-1, S-2","P-3, Q-4, R-2, S-1","P-4, Q-2, R-3, S-1","P-4, Q-3, R-2, S-1"],"answer":3,"explanation":"The spiral curriculum revisits topics, LASS refers to supportive adult routines, discovery learning means finding principles from instances, and the enactive mode represents knowledge through action.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"ब्रूनर के विचार का उसके वर्णन से मिलान कीजिए। P. सर्पिल पाठ्यचर्या Q. LASS R. खोज अधिगम S. क्रियात्मक विधा; 1. क्रिया के माध्यम से जानना 2. अधिगमकर्ता उदाहरणों से सिद्धांत खोजते हैं 3. वयस्कों की दिनचर्याएँ जो बच्चे की भाषा को सहारा देती हैं 4. विषयों को उच्चतर स्तरों पर फिर-फिर देखना","optionsHi":["P-4, Q-3, R-1, S-2","P-3, Q-4, R-2, S-1","P-4, Q-2, R-3, S-1","P-4, Q-3, R-2, S-1"],"explanationHi":"सर्पिल पाठ्यचर्या विषयों को फिर-फिर देखती है, LASS सहायक वयस्क दिनचर्याओं को कहता है, खोज अधिगम का अर्थ उदाहरणों से सिद्धांत खोजना है, और क्रियात्मक विधा ज्ञान को क्रिया के माध्यम से निरूपित करती है।"},
  {"id":"cdp-child-development-1381","question":"Class 7 students in a Kendriya Vidyalaya can find the area of rectangles in textbook exercises, but cannot work out how many tiles are needed for their classroom floor. Bruner would say that the most likely cause is:","options":["They learnt procedures, not the idea’s underlying structure, so transfer fails","They are still in the sensorimotor stage and so cannot think about real spaces","Tiling problems need formal operations, which no Class 7 student has yet","They have not had sufficient reinforcement for solving the textbook exercises"],"answer":0,"explanation":"Bruner argued that understanding the fundamental structure of a subject is what makes transfer to new situations possible. Memorised procedures stay tied to their original form.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"केंद्रीय विद्यालय में कक्षा 7 के विद्यार्थी पाठ्यपुस्तक के अभ्यासों में आयतों का क्षेत्रफल निकाल सकते हैं, पर अपनी कक्षा के फ़र्श के लिए कितनी टाइलें चाहिए यह नहीं निकाल पाते। ब्रूनर कहेंगे कि सबसे संभावित कारण है:","optionsHi":["उन्होंने प्रक्रियाएँ सीखीं, विचार की अंतर्निहित संरचना नहीं, इसलिए स्थानांतरण विफल होता है","वे अभी संवेदी-गामक अवस्था में हैं और इसलिए वास्तविक स्थानों के बारे में सोच नहीं सकते","टाइल बिछाने की समस्याओं के लिए औपचारिक संक्रियाएँ चाहिए, जो अभी कक्षा 7 के किसी विद्यार्थी में नहीं हैं","पाठ्यपुस्तक के अभ्यास हल करने के लिए उन्हें पर्याप्त पुनर्बलन नहीं मिला है"],"explanationHi":"ब्रूनर ने तर्क दिया कि किसी विषय की मूल संरचना को समझना ही नई परिस्थितियों में स्थानांतरण को संभव बनाता है। रटी हुई प्रक्रियाएँ अपने मूल रूप से बँधी रहती हैं।"},
  {"id":"cdp-child-development-1382","question":"A child building a block tower is about to give up after it falls twice. The tutor says, ‘You’ve already got the first three right; let’s just try the top one together.’ In Wood, Bruner and Ross’s account, this tutoring function is:","options":["Demonstration","Reduction in degrees of freedom","Frustration control","Recruitment"],"answer":2,"explanation":"Frustration control keeps the learner from becoming discouraged, so that errors do not end the attempt. Recruitment is first engaging the child’s interest in the task.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"ब्लॉकों से मीनार बनाता एक बच्चा दो बार गिरने के बाद हार मानने वाला है। ट्यूटर कहता है, ‘तुमने पहले तीन सही कर लिए हैं; चलो बस ऊपर वाला साथ में आज़माते हैं।’ वुड, ब्रूनर और रॉस के विवरण में, यह ट्यूटरिंग प्रकार्य है:","optionsHi":["प्रदर्शन","स्वातंत्र्य-कोटियों में कमी","निराशा-नियंत्रण","भर्ती (रिक्रूटमेंट)"],"explanationHi":"निराशा-नियंत्रण अधिगमकर्ता को हतोत्साहित होने से रोकता है, ताकि त्रुटियाँ प्रयास को समाप्त न कर दें। भर्ती का अर्थ है पहले कार्य में बच्चे की रुचि जगाना।"},
  {"id":"cdp-child-development-1383","question":"While a child fits pieces into a puzzle, the tutor points out, ‘Look, this edge is straight but the space here is curved.’ This tutoring function, highlighting the difference between what the child has done and what is needed, is called:","options":["Direction maintenance","Marking critical features","Recruitment","Reduction in degrees of freedom"],"answer":1,"explanation":"Marking critical features draws the learner’s attention to discrepancies that matter for success. Direction maintenance keeps the learner pursuing the goal.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"जब बच्चा पहेली में टुकड़े बैठा रहा है, ट्यूटर इंगित करता है, ‘देखो, यह किनारा सीधा है पर यहाँ की जगह मुड़ी हुई है।’ यह ट्यूटरिंग प्रकार्य, जो बच्चे द्वारा किए गए और आवश्यक के बीच के अंतर को उभारता है, कहलाता है:","optionsHi":["दिशा-अनुरक्षण","निर्णायक विशेषताओं को चिह्नित करना","भर्ती","स्वातंत्र्य-कोटियों में कमी"],"explanationHi":"निर्णायक विशेषताओं को चिह्नित करना अधिगमकर्ता का ध्यान उन विसंगतियों की ओर खींचता है जो सफलता के लिए मायने रखती हैं। दिशा-अनुरक्षण अधिगमकर्ता को लक्ष्य का पीछा करते रखता है।"},
  {"id":"cdp-child-development-1384","question":"Which classroom remark best reflects Bruner’s view of the learner?","options":["‘Children are empty vessels to be filled with facts by the class teacher.’","‘Children learn only when their correct answers are rewarded.’","‘Children learn best by actively finding relationships and structure.’","‘Children must not ask questions until they know the basic facts.’"],"answer":2,"explanation":"Bruner saw learners as active problem solvers who discover structure. The other remarks reflect transmission or behaviourist views.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कौन-सी कक्षा-टिप्पणी ब्रूनर के अधिगमकर्ता-संबंधी दृष्टिकोण को सबसे अच्छी तरह दर्शाती है?","optionsHi":["‘बच्चे खाली बर्तन हैं जिन्हें कक्षा-शिक्षक तथ्यों से भरेगा।’","‘बच्चे तभी सीखते हैं जब उनके सही उत्तरों को पुरस्कृत किया जाए।’","‘बच्चे संबंधों और संरचना को सक्रिय रूप से खोजकर सबसे अच्छा सीखते हैं।’","‘बच्चों को तब तक प्रश्न नहीं पूछने चाहिए जब तक वे बुनियादी तथ्य न जान लें।’"],"explanationHi":"ब्रूनर अधिगमकर्ताओं को सक्रिय समस्या-समाधानकर्ता मानते थे जो संरचना खोजते हैं। अन्य टिप्पणियाँ संचरण या व्यवहारवादी दृष्टिकोण को दर्शाती हैं।"},
  {"id":"cdp-child-development-1385","question":"Assertion (A): Bruner held that a learner of any age meeting an unfamiliar idea may benefit from enactive and iconic experiences. Reason (R): Bruner’s modes of representation are strict age-bound stages that cannot be revisited.","options":["Both A and R are true, and R is the correct explanation of A","A is true, but R is false","A is false, but R is true","Both A and R are true, but R is not the correct explanation of A"],"answer":1,"explanation":"Bruner’s modes remain available throughout life, which is exactly why older learners can use action and images for new ideas. R wrongly describes them as fixed stages.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"अभिकथन (A): ब्रूनर का मत था कि किसी भी आयु का अधिगमकर्ता जो अपरिचित विचार से मिलता है, उसे क्रियात्मक और आइकॉनिक अनुभवों से लाभ हो सकता है। कारण (R): ब्रूनर की निरूपण-विधाएँ कठोर आयु-बद्ध अवस्थाएँ हैं जिन्हें फिर नहीं देखा जा सकता।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है"],"explanationHi":"ब्रूनर की विधाएँ जीवन भर उपलब्ध रहती हैं, यही कारण है कि बड़े अधिगमकर्ता नए विचारों के लिए क्रिया और चित्रों का उपयोग कर सकते हैं। R उन्हें गलती से निश्चित अवस्थाएँ बताता है।"},
  {"id":"cdp-child-development-1386","question":"A teacher using discovery learning finds that the lesson took three periods instead of one, and a few students still drew wrong conclusions. Which response is most consistent with research on discovery learning?","options":["Abandon discovery entirely and use only lectures, which are quicker and safer","Use full discovery for every topic regardless of time, as struggle builds learning","Make discovery lessons silent and individual so that each child finds the rule","Use guided discovery: plan key questions and examples, then sum up the principle"],"answer":3,"explanation":"Guided discovery keeps the active element while reducing wasted time and misconceptions. Neither abandoning it nor using it for everything is supported.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"खोज अधिगम का उपयोग करने वाला एक शिक्षक पाता है कि पाठ में एक के बजाय तीन कालांश लगे और कुछ विद्यार्थियों ने फिर भी गलत निष्कर्ष निकाले। खोज अधिगम पर शोध के सबसे अनुरूप प्रतिक्रिया कौन-सी है?","optionsHi":["खोज को पूरी तरह छोड़कर केवल व्याख्यानों का उपयोग करना, जो तेज़ और सुरक्षित हैं","समय की परवाह किए बिना हर विषय के लिए पूर्ण खोज का उपयोग करना, क्योंकि संघर्ष अधिगम बनाता है","खोज-पाठों को मौन और वैयक्तिक बनाना ताकि प्रत्येक बच्चा नियम खोजे","निर्देशित खोज का उपयोग करना: प्रमुख प्रश्नों और उदाहरणों की योजना बनाना, फिर सिद्धांत का सार बताना"],"explanationHi":"निर्देशित खोज सक्रिय तत्त्व को बनाए रखती है जबकि व्यर्थ समय और भ्रांतियाँ घटाती है। न उसे छोड़ना और न हर चीज़ के लिए उपयोग करना समर्थित है।"},
  {"id":"cdp-child-development-1387","question":"Which statement about Bruner’s ‘modes of representation’ and Piaget’s ‘stages’ is correct?","options":["Bruner’s modes coexist for life; Piaget’s stages are qualitatively distinct levels","Both are identical in every respect, differing only in the names they use","Bruner’s modes appear in the reverse order to Piaget’s stages, starting with symbols","Piaget’s stages, but not Bruner’s modes, include a role for action in early learning"],"answer":0,"explanation":"Bruner’s enactive, iconic and symbolic modes coexist and can be used for any new learning. Piaget’s stages describe a fixed sequence of overall cognitive structures, beginning with sensorimotor action.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"ब्रूनर की ‘निरूपण-विधाओं’ और पियाजे की ‘अवस्थाओं’ के बारे में कौन-सा कथन सही है?","optionsHi":["ब्रूनर की विधाएँ जीवन भर सह-अस्तित्व में रहती हैं; पियाजे की अवस्थाएँ गुणात्मक रूप से भिन्न स्तर हैं","दोनों हर दृष्टि से समान हैं, केवल प्रयुक्त नामों में भिन्न","ब्रूनर की विधाएँ पियाजे की अवस्थाओं के उलटे क्रम में आती हैं, प्रतीकों से शुरू करते हुए","पियाजे की अवस्थाओं में, ब्रूनर की विधाओं में नहीं, प्रारंभिक अधिगम में क्रिया की भूमिका शामिल है"],"explanationHi":"ब्रूनर की क्रियात्मक, आइकॉनिक और प्रतीकात्मक विधाएँ सह-अस्तित्व में रहती हैं और किसी भी नए अधिगम के लिए प्रयोग की जा सकती हैं। पियाजे की अवस्थाएँ समग्र संज्ञानात्मक संरचनाओं के निश्चित क्रम का वर्णन करती हैं, संवेदी-गामक क्रिया से आरंभ करते हुए।"},
  {"id":"cdp-child-development-1388","question":"A Class 5 teacher wants students to understand the concept ‘island’. She shows photos of Lakshadweep, Andaman and a river island in the Brahmaputra (yes), and a peninsula and a lake (no), asking students to work out the defining features. This method draws on Bruner’s work on:","options":["Operant conditioning, rewarding correct answers about places","Concept attainment through positive and negative examples","Classical conditioning, pairing pictures with place names","Moral reasoning about how different peoples use the land"],"answer":1,"explanation":"Bruner, Goodnow and Austin showed how learners infer the critical attributes of a concept by comparing examples with non-examples. Majuli in the Brahmaputra is a river island, while a peninsula is a useful near-miss.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 5 की एक शिक्षिका चाहती है कि विद्यार्थी ‘द्वीप’ की अवधारणा समझें। वह लक्षद्वीप, अंडमान और ब्रह्मपुत्र के एक नदी-द्वीप की तस्वीरें (हाँ), और एक प्रायद्वीप तथा एक झील (नहीं) दिखाती है, और विद्यार्थियों से परिभाषित करने वाली विशेषताएँ निकालने को कहती है। यह विधि ब्रूनर के किस कार्य पर आधारित है?","optionsHi":["क्रियाप्रसूत अनुबंधन, स्थानों के बारे में सही उत्तरों को पुरस्कृत करना","धनात्मक और ऋणात्मक उदाहरणों द्वारा अवधारणा-प्राप्ति","शास्त्रीय अनुबंधन, चित्रों को स्थानों के नामों से जोड़ना","लोग भूमि का उपयोग कैसे करते हैं, इस पर नैतिक तर्कण"],"explanationHi":"ब्रूनर, गुडनाउ और ऑस्टिन ने दिखाया कि अधिगमकर्ता उदाहरणों की गैर-उदाहरणों से तुलना करके किसी अवधारणा की निर्णायक विशेषताओं का अनुमान कैसे लगाते हैं। ब्रह्मपुत्र का माजुली नदी-द्वीप है, जबकि प्रायद्वीप एक उपयोगी निकट-चूक है।"},
  {"id":"cdp-child-development-1389","question":"Which practice runs AGAINST Bruner’s recommendations?","options":["Letting students find patterns before stating the general rule to them","Revisiting key ideas in later classes at a higher level of depth","Teaching each fact separately, with no attention to how ideas connect","Using objects and pictures before symbols when introducing new ideas"],"answer":2,"explanation":"Bruner stressed teaching the structure of a subject, the relationships between ideas. Isolated facts are hard to remember and do not transfer.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कौन-सा अभ्यास ब्रूनर की सिफ़ारिशों के विरुद्ध है?","optionsHi":["विद्यार्थियों को सामान्य नियम बताने से पहले प्रतिरूप खोजने देना","आगे की कक्षाओं में प्रमुख विचारों को अधिक गहराई के स्तर पर फिर देखना","प्रत्येक तथ्य को अलग-अलग पढ़ाना, यह ध्यान दिए बिना कि विचार कैसे जुड़ते हैं","नए विचारों को प्रस्तुत करते समय प्रतीकों से पहले वस्तुओं और चित्रों का उपयोग करना"],"explanationHi":"ब्रूनर ने किसी विषय की संरचना, विचारों के बीच के संबंधों, को पढ़ाने पर बल दिया। अलग-थलग तथ्य याद रखना कठिन होता है और स्थानांतरित नहीं होते।"},
  {"id":"cdp-child-development-1390","question":"A Class 3 child learns about clocks by moving the hands of a cardboard clock (Stage P), then by reading clock-face pictures in her book (Stage Q), and finally by writing times like 7:45 (Stage R). If she later cannot read a digital time, the most Bruner-consistent teacher action is to:","options":["Give her many more written times to copy until the digital form finally sticks","Scold her gently for forgetting, so that she pays much closer attention next time","Assume she is not yet ready and stop teaching time for this year","Go back to the cardboard clock beside the digital time, linking action to symbol"],"answer":3,"explanation":"When a symbolic representation breaks down, returning to enactive and iconic support helps rebuild meaning. Bruner did not treat difficulty as a reason to stop teaching.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 3 की एक बच्ची घड़ियों के बारे में पहले गत्ते की घड़ी की सूइयाँ चलाकर (चरण P), फिर अपनी पुस्तक में घड़ी-मुख के चित्र पढ़कर (चरण Q), और अंत में 7:45 जैसे समय लिखकर (चरण R) सीखती है। यदि वह बाद में डिजिटल समय नहीं पढ़ पाती, तो ब्रूनर के सबसे अनुरूप शिक्षक की कार्रवाई है:","optionsHi":["उसे डिजिटल रूप अंततः बैठने तक उतारने के लिए लिखे हुए बहुत अधिक समय देना","भूल जाने पर उसे हल्के से डाँटना, ताकि वह अगली बार कहीं अधिक ध्यान दे","मान लेना कि वह अभी तैयार नहीं है और इस वर्ष समय पढ़ाना बंद कर देना","डिजिटल समय के साथ-साथ गत्ते की घड़ी पर लौटना, क्रिया को प्रतीक से जोड़ते हुए"],"explanationHi":"जब कोई प्रतीकात्मक निरूपण टूट जाता है, तो क्रियात्मक और आइकॉनिक सहारे पर लौटना अर्थ को फिर बनाने में सहायक होता है। ब्रूनर कठिनाई को शिक्षण रोकने का कारण नहीं मानते थे।"},
  {"id":"cdp-child-development-1391","question":"How many of these classroom practices follow from Bruner’s ideas? I. Planning a topic so that it is met again at higher levels in later classes. II. Encouraging students to make educated guesses and then test them. III. Teaching new ideas only through symbols, since pictures waste time. IV. Asking students to discover principles from carefully chosen examples.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I (spiral curriculum), II (intuitive thinking) and IV (discovery) follow from Bruner. He valued iconic representation as a support, so III contradicts him.","difficulty":"hard","source":"CTET · DSSSB · State TETs","questionHi":"इनमें से कितने कक्षा-अभ्यास ब्रूनर के विचारों से निकलते हैं? I. किसी विषय की योजना इस प्रकार बनाना कि वह आगे की कक्षाओं में उच्चतर स्तरों पर फिर आए। II. विद्यार्थियों को सुशिक्षित अनुमान लगाने और फिर उन्हें परखने के लिए प्रोत्साहित करना। III. नए विचारों को केवल प्रतीकों के माध्यम से पढ़ाना, क्योंकि चित्र समय बर्बाद करते हैं। IV. विद्यार्थियों से सावधानी से चुने उदाहरणों से सिद्धांत खोजने को कहना।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"I (सर्पिल पाठ्यचर्या), II (सहज बोधात्मक चिंतन) और IV (खोज) ब्रूनर से निकलते हैं। वे आइकॉनिक निरूपण को सहारे के रूप में महत्त्व देते थे, इसलिए III उनका खंडन करता है।"},
  {"id":"cdp-child-development-1392","question":"A teacher keeps a group of students on track during a long experiment by reminding them, ‘Remember, we are trying to find out which soil holds more water,’ whenever they drift into other questions. In Wood, Bruner and Ross’s scaffolding functions, this is:","options":["Direction maintenance","Demonstration","Frustration control","Marking critical features"],"answer":0,"explanation":"Direction maintenance keeps learners pursuing the goal of the task. Demonstration means modelling a solution for the learner to imitate.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक शिक्षक विद्यार्थियों के एक समूह को लंबे प्रयोग के दौरान पटरी पर रखता है, जब वे अन्य प्रश्नों में भटकते हैं तो यह याद दिलाकर, ‘याद रखो, हम पता लगा रहे हैं कि कौन-सी मिट्टी अधिक पानी रोकती है।’ वुड, ब्रूनर और रॉस के पाड़-प्रकार्यों में, यह है:","optionsHi":["दिशा-अनुरक्षण","प्रदर्शन","निराशा-नियंत्रण","निर्णायक विशेषताओं को चिह्नित करना"],"explanationHi":"दिशा-अनुरक्षण अधिगमकर्ताओं को कार्य के लक्ष्य का पीछा करते रखता है। प्रदर्शन का अर्थ है अधिगमकर्ता के अनुकरण के लिए समाधान का आदर्श प्रस्तुत करना।"},
  {"id":"cdp-child-development-1393","question":"Which pair of ideas is most closely linked to Jerome Bruner?","options":["Equilibration and schema","Zone of proximal development and private speech","Spiral curriculum and intuitive thinking","Operant conditioning and shaping"],"answer":2,"explanation":"Bruner proposed the spiral curriculum and emphasised the value of intuitive thinking. The other pairs belong to Piaget, Vygotsky and Skinner respectively.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"विचारों का कौन-सा जोड़ा जेरोम ब्रूनर से सबसे निकट से जुड़ा है?","optionsHi":["साम्य-स्थापन और स्कीमा","निकटस्थ विकास का क्षेत्र और निजी वाक्","सर्पिल पाठ्यचर्या और सहज बोधात्मक चिंतन","क्रियाप्रसूत अनुबंधन और आकार देना"],"explanationHi":"ब्रूनर ने सर्पिल पाठ्यचर्या प्रस्तावित की और सहज बोधात्मक चिंतन के मूल्य पर बल दिया। अन्य जोड़े क्रमशः पियाजे, वाइगोत्स्की और स्किनर के हैं।"},
  {"id":"cdp-child-development-1394","question":"A science teacher asks Class 6 students, ‘Why do you think leaves of some plants close at night?’ and lets them suggest guesses before investigating. A colleague says guessing encourages careless thinking. Bruner would argue that:","options":["The colleague is right; only proven facts should ever be stated in a science class","Intuitive guesses, later tested, are central to how scientists and learners think","Guessing is useful only in mathematics, where answers can be checked easily","Students should be encouraged to guess but never asked to test their guesses"],"answer":1,"explanation":"Bruner held that schools undervalue intuitive thinking, which generates hypotheses that analytical thinking then checks. Untested guessing would miss the second half.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक विज्ञान शिक्षक कक्षा 6 के विद्यार्थियों से पूछता है, ‘तुम्हें क्या लगता है कि कुछ पौधों की पत्तियाँ रात में क्यों बंद हो जाती हैं?’ और जाँच से पहले उन्हें अनुमान सुझाने देता है। एक सहकर्मी कहता है कि अनुमान लगाना लापरवाह चिंतन को बढ़ावा देता है। ब्रूनर तर्क देंगे कि:","optionsHi":["सहकर्मी सही है; विज्ञान की कक्षा में केवल सिद्ध तथ्य ही कहे जाने चाहिए","सहज बोधात्मक अनुमान, जिन्हें बाद में परखा जाए, वैज्ञानिकों और अधिगमकर्ताओं के सोचने के तरीके के केंद्र में हैं","अनुमान लगाना केवल गणित में उपयोगी है, जहाँ उत्तर आसानी से जाँचे जा सकते हैं","विद्यार्थियों को अनुमान लगाने के लिए प्रोत्साहित करना चाहिए पर उन्हें अनुमान परखने के लिए कभी नहीं कहना चाहिए"],"explanationHi":"ब्रूनर का मत था कि विद्यालय सहज बोधात्मक चिंतन को कम आँकते हैं, जो परिकल्पनाएँ उत्पन्न करता है जिन्हें फिर विश्लेषणात्मक चिंतन जाँचता है। बिना परखा अनुमान दूसरा भाग चूक जाता।"},
  {"id":"cdp-child-development-1395","question":"Seven-year-old Aarav studies in Grade 2. Under the 5+3+3+4 structure of NEP 2020, he is in the ___ stage, where the pedagogy should be ___.","options":["Preparatory; light textbooks with some formal but interactive classroom learning","Foundational; flexible, multilevel, play- and activity-based learning","Foundational; formal subject teachers and written examinations","Middle; experiential learning across subjects with subject teachers"],"answer":1,"explanation":"The foundational stage covers ages 3–8 (three years of pre-school plus Grades 1–2) and calls for play- and activity-based learning; the preparatory stage starts at Grade 3.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"सात वर्षीय आरव कक्षा 2 में पढ़ता है। NEP 2020 की 5+3+3+4 संरचना के अंतर्गत, वह ___ चरण में है, जहाँ शिक्षणशास्त्र ___ होना चाहिए।","optionsHi":["प्रारंभिक (प्रिपरेटरी); हल्की पाठ्यपुस्तकें और कुछ औपचारिक पर संवादात्मक कक्षा-अधिगम","आधारभूत (फ़ाउंडेशनल); लचीला, बहुस्तरीय, खेल और गतिविधि आधारित अधिगम","आधारभूत; औपचारिक विषय-शिक्षक और लिखित परीक्षाएँ","मध्य; विषय-शिक्षकों के साथ विषयों में अनुभवात्मक अधिगम"],"explanationHi":"आधारभूत चरण 3–8 वर्ष की आयु को कवर करता है (तीन वर्ष का पूर्व-विद्यालय तथा कक्षा 1–2) और खेल तथा गतिविधि आधारित अधिगम की माँग करता है; प्रारंभिक चरण कक्षा 3 से शुरू होता है।"},
  {"id":"cdp-child-development-1396","question":"The five years of the foundational stage under NEP 2020 consist of:","options":["Grades 1 to 5, matching the old primary stage of schooling","Two years of pre-school or Anganwadi followed by Grades 1 to 3","One year of Balavatika followed by Grades 1 to 4 of the primary school","Three years of Anganwadi, pre-school or Balavatika, then Grades 1–2"],"answer":3,"explanation":"The foundational stage is ages 3–8: three years of ECCE plus Grades 1 and 2. Grades 3–5 form the preparatory stage, so options A and C mix up the two stages.","difficulty":"very-hard","source":"CTET Paper I · DSSSB PRT","questionHi":"NEP 2020 के अंतर्गत आधारभूत चरण के पाँच वर्षों में शामिल हैं:","optionsHi":["कक्षा 1 से 5, विद्यालयी शिक्षा के पुराने प्राथमिक चरण के अनुरूप","दो वर्ष का पूर्व-विद्यालय या आँगनवाड़ी, उसके बाद कक्षा 1 से 3","एक वर्ष की बालवाटिका, उसके बाद प्राथमिक विद्यालय की कक्षा 1 से 4","तीन वर्ष की आँगनवाड़ी, पूर्व-विद्यालय या बालवाटिका, फिर कक्षा 1–2"],"explanationHi":"आधारभूत चरण 3–8 वर्ष की आयु है: ECCE के तीन वर्ष तथा कक्षा 1 और 2। कक्षा 3–5 प्रारंभिक चरण बनाती हैं, इसलिए विकल्प A और C दोनों चरणों को मिला देते हैं।"},
  {"id":"cdp-child-development-1397","question":"Which statement correctly compares the 5+3+3+4 structure with the earlier 10+2 structure?","options":["It brings ages 3 to 6 into the curricular structure, which 10+2 did not","It cuts the total years of schooling from 12 to 10 to save time","It removes Grades 11 and 12 from school and moves them to junior colleges","It begins formal schooling with written tests at the age of 3"],"answer":0,"explanation":"5+3+3+4 covers ages 3–18 and so brings early childhood (ages 3–6), earlier outside 10+2, into the curricular framework; Grades 1–12 remain.","difficulty":"hard","source":"CTET · KVS PRT","questionHi":"कौन-सा कथन 5+3+3+4 संरचना की पहले की 10+2 संरचना से सही तुलना करता है?","optionsHi":["यह 3 से 6 वर्ष की आयु को पाठ्यचर्या-संरचना में लाती है, जो 10+2 में नहीं थी","यह समय बचाने के लिए विद्यालयी शिक्षा के कुल वर्ष 12 से घटाकर 10 कर देती है","यह कक्षा 11 और 12 को विद्यालय से हटाकर जूनियर कॉलेजों में ले जाती है","यह 3 वर्ष की आयु में लिखित परीक्षाओं से औपचारिक विद्यालयी शिक्षा आरंभ करती है"],"explanationHi":"5+3+3+4, 3–18 वर्ष की आयु को कवर करती है और इसलिए प्रारंभिक बाल्यावस्था (3–6 वर्ष), जो पहले 10+2 के बाहर थी, को पाठ्यचर्या-ढाँचे में लाती है; कक्षा 1–12 बनी रहती हैं।"},
  {"id":"cdp-child-development-1398","question":"Why does NEP 2020 treat foundational literacy and numeracy as an urgent national mission and its highest priority?","options":["Because Class 10 board results across the country have been falling steadily","Because English proficiency in schools is low and this limits higher education","Because many elementary pupils lack FLN, and later schooling then means little","Because FLN can replace the need for other subjects in the early grades"],"answer":2,"explanation":"NEP 2020 notes a learning crisis in which many children lack basic reading and arithmetic; since all later learning rests on FLN, it says the rest of the policy becomes largely irrelevant without it.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"NEP 2020 आधारभूत साक्षरता और संख्या-ज्ञान को अत्यावश्यक राष्ट्रीय मिशन और अपनी सर्वोच्च प्राथमिकता क्यों मानती है?","optionsHi":["क्योंकि देश भर में कक्षा 10 के बोर्ड परिणाम लगातार गिर रहे हैं","क्योंकि विद्यालयों में अंग्रेज़ी दक्षता कम है और यह उच्च शिक्षा को सीमित करती है","क्योंकि अनेक प्रारंभिक कक्षाओं के विद्यार्थियों में FLN नहीं है, और तब आगे की स्कूली शिक्षा का कोई अर्थ नहीं रहता","क्योंकि FLN प्रारंभिक कक्षाओं में अन्य विषयों की आवश्यकता को प्रतिस्थापित कर सकता है"],"explanationHi":"NEP 2020 एक अधिगम-संकट का उल्लेख करती है जिसमें अनेक बच्चों में बुनियादी पठन और अंकगणित का अभाव है; चूँकि सारा आगे का अधिगम FLN पर टिका है, वह कहती है कि इसके बिना शेष नीति काफ़ी हद तक अप्रासंगिक हो जाती है।"},
  {"id":"cdp-child-development-1399","question":"To tackle gaps in foundational literacy and numeracy, which strategy does NEP 2020 suggest besides the work of teachers?","options":["Detaining weak children in Grade 1 until they can read and count fluently","Peer tutoring and trained community volunteers giving one-on-one support","Replacing teachers with educational apps that adapt to each child","Postponing FLN teaching to Grade 6, when children are more mature"],"answer":1,"explanation":"NEP 2020 proposes peer tutoring and volunteer support (one-on-one help) to supplement teachers; detention and postponement would deepen the problem.","difficulty":"hard","source":"CTET Paper I · State TET","questionHi":"आधारभूत साक्षरता और संख्या-ज्ञान में अंतराल से निपटने के लिए, शिक्षकों के कार्य के अतिरिक्त NEP 2020 कौन-सी रणनीति सुझाती है?","optionsHi":["कमज़ोर बच्चों को कक्षा 1 में तब तक रोकना जब तक वे धाराप्रवाह पढ़ और गिन न सकें","सहपाठी शिक्षण और प्रशिक्षित सामुदायिक स्वयंसेवकों द्वारा एक-से-एक सहायता","शिक्षकों को शैक्षिक ऐप्स से बदलना जो हर बच्चे के अनुसार ढल जाएँ","FLN शिक्षण को कक्षा 6 तक टालना, जब बच्चे अधिक परिपक्व हों"],"explanationHi":"NEP 2020 शिक्षकों की पूरक के रूप में सहपाठी शिक्षण और स्वयंसेवक सहायता (एक-से-एक मदद) प्रस्तावित करती है; रोकना और टालना समस्या को गहरा करेगा।"},
  {"id":"cdp-child-development-1400","question":"Which statement about the three-language formula in NEP 2020 is correct?","options":["Hindi is made compulsory as one of the three languages in every state of India","English must be one of the three languages, as the link language","Every state must teach Sanskrit as the third language from Class 6","No language is imposed; states choose, with at least two native to India"],"answer":3,"explanation":"NEP 2020 keeps the three-language formula but makes it flexible: states and students choose, provided at least two of the three languages are native to India.","difficulty":"very-hard","source":"CTET · KVS TGT","questionHi":"NEP 2020 के त्रिभाषा सूत्र के बारे में कौन-सा कथन सही है?","optionsHi":["भारत के हर राज्य में हिंदी को तीन भाषाओं में से एक के रूप में अनिवार्य बनाया गया है","अंग्रेज़ी तीन भाषाओं में से एक होनी चाहिए, संपर्क भाषा के रूप में","हर राज्य को कक्षा 6 से तीसरी भाषा के रूप में संस्कृत पढ़ानी होगी","कोई भाषा थोपी नहीं जाती; राज्य चुनते हैं, कम-से-कम दो भारत की मूल भाषाएँ हों"],"explanationHi":"NEP 2020 त्रिभाषा सूत्र रखती है पर उसे लचीला बनाती है: राज्य और विद्यार्थी चुनते हैं, बशर्ते तीन में से कम-से-कम दो भाषाएँ भारत की मूल भाषाएँ हों।"},
  {"id":"cdp-child-development-1401","question":"A five-year-old in a Balavatika attached to a primary school is given daily handwriting drills and weekly written tests. Under NEP 2020, this practice is:","options":["Inappropriate: this stage calls for play- and activity-based learning","Appropriate, because early drills raise literacy faster than play does","Appropriate, but only for children in urban schools with good facilities","Required, so that children are ready for the Grade 1 entrance test"],"answer":0,"explanation":"NEP 2020 frames the Balavatika year as part of ECCE, with play-based, activity-based learning; drill-and-test routines are developmentally inappropriate at age five.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"प्राथमिक विद्यालय से संबद्ध बालवाटिका में पाँच वर्ष के बच्चे को दैनिक लिखावट-अभ्यास और साप्ताहिक लिखित परीक्षाएँ दी जाती हैं। NEP 2020 के अंतर्गत यह अभ्यास है:","optionsHi":["अनुचित: इस चरण में खेल और गतिविधि आधारित अधिगम की माँग है","उचित, क्योंकि प्रारंभिक अभ्यास खेल की तुलना में साक्षरता को तेज़ी से बढ़ाते हैं","उचित, पर केवल अच्छी सुविधाओं वाले शहरी विद्यालयों के बच्चों के लिए","आवश्यक, ताकि बच्चे कक्षा 1 की प्रवेश परीक्षा के लिए तैयार हों"],"explanationHi":"NEP 2020 बालवाटिका वर्ष को ECCE का भाग मानती है, जिसमें खेल-आधारित, गतिविधि-आधारित अधिगम हो; अभ्यास-और-परीक्षा की दिनचर्या पाँच वर्ष की आयु पर विकासात्मक रूप से अनुचित है।"},
  {"id":"cdp-child-development-1402","question":"Which school decision is most consistent with the NEP 2020 principle of ‘no hard separations’?","options":["Allowing only science students to take music in Class 11, as a reward","Offering vocational subjects only to students with low marks in Class 10","Letting a Class 11 student combine physics, history and music","Scheduling art classes only after the board examinations are over"],"answer":2,"explanation":"NEP 2020 rejects rigid walls between arts, humanities and sciences, between curricular and ‘extra-curricular’ activities, and between vocational and academic streams.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"कौन-सा विद्यालयी निर्णय NEP 2020 के ‘कठोर विभाजन नहीं’ के सिद्धांत के सबसे अनुरूप है?","optionsHi":["कक्षा 11 में केवल विज्ञान के विद्यार्थियों को पुरस्कार के रूप में संगीत लेने देना","व्यावसायिक विषय केवल कक्षा 10 में कम अंक पाने वाले विद्यार्थियों को देना","कक्षा 11 के विद्यार्थी को भौतिकी, इतिहास और संगीत मिलाकर चुनने देना","कला के कालांश केवल बोर्ड परीक्षाएँ समाप्त होने के बाद रखना"],"explanationHi":"NEP 2020 कला, मानविकी और विज्ञान के बीच, पाठ्यचर्या और ‘पाठ्येतर’ गतिविधियों के बीच, तथा व्यावसायिक और शैक्षिक धाराओं के बीच कठोर दीवारों को अस्वीकार करती है।"},
  {"id":"cdp-child-development-1403","question":"For students of Grades 6–8, NEP 2020 suggests a ten-day bagless period during which they:","options":["Revise for examinations without carrying books, using only their notes","Intern with local vocational experts such as carpenters, gardeners and potters","Stay at home to reduce their workload and rest before the term exams","Attend special coaching classes held in school for national competitive examinations"],"answer":1,"explanation":"The bagless days give hands-on exposure to local crafts and trades, in line with NEP 2020’s aim of integrating vocational exposure from the middle stage.","difficulty":"moderate","source":"CTET Paper II · State TET","questionHi":"कक्षा 6–8 के विद्यार्थियों के लिए, NEP 2020 दस दिन की बैग-रहित अवधि सुझाती है, जिसके दौरान वे:","optionsHi":["किताबें लिए बिना परीक्षाओं की तैयारी करते हैं, केवल अपने नोट्स का उपयोग करके","स्थानीय व्यावसायिक विशेषज्ञों, जैसे बढ़ई, माली और कुम्हार, के साथ प्रशिक्षुता करते हैं","अपना बोझ घटाने और सत्र-परीक्षाओं से पहले आराम करने के लिए घर पर रहते हैं","राष्ट्रीय प्रतियोगी परीक्षाओं के लिए विद्यालय में विशेष कोचिंग कक्षाओं में भाग लेते हैं"],"explanationHi":"बैग-रहित दिन स्थानीय शिल्पों और व्यवसायों से प्रत्यक्ष संपर्क देते हैं, जो मध्य चरण से व्यावसायिक संपर्क को समेकित करने के NEP 2020 के उद्देश्य के अनुरूप है।"},
  {"id":"cdp-child-development-1404","question":"Assertion (A): NEP 2020 recommends that early grades be taught, wherever possible, in the child’s home language or mother tongue. Reason (R): Children learn and grasp non-trivial concepts more quickly in their home language.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"NEP 2020 itself gives this reason: children understand concepts more readily in their home language, which is why it recommends it as the medium in the early grades.","difficulty":"hard","source":"CTET · REET","questionHi":"अभिकथन (A): NEP 2020 अनुशंसा करती है कि प्रारंभिक कक्षाओं में, जहाँ संभव हो, बच्चे की घर की भाषा या मातृभाषा में पढ़ाया जाए। कारण (R): बच्चे अपनी घर की भाषा में गैर-तुच्छ अवधारणाएँ अधिक शीघ्रता से सीखते और समझते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"NEP 2020 स्वयं यह कारण देती है: बच्चे अपनी घर की भाषा में अवधारणाएँ अधिक सहजता से समझते हैं, इसीलिए वह प्रारंभिक कक्षाओं में उसे माध्यम के रूप में अनुशंसित करती है।"},
  {"id":"cdp-child-development-1405","question":"NEP 2020 says assessment should move away from being primarily summative and focused on rote memorisation towards being:","options":["Based on more frequent rote tests to keep students revising regularly","Purely norm-referenced, ranking each student against the class","Limited to board examinations, with no school-level testing","Regular, formative and competency-based, testing higher-order skills"],"answer":3,"explanation":"NEP 2020 calls for regular, formative, competency-based assessment that promotes learning and tests higher-order skills rather than memory.","difficulty":"moderate","source":"CTET · KVS PRT","questionHi":"NEP 2020 कहती है कि आकलन को मुख्यतः योगात्मक और रटंत-केंद्रित होने से हटकर किस ओर जाना चाहिए?","optionsHi":["विद्यार्थियों को नियमित दोहराने के लिए अधिक बार रटंत परीक्षणों पर आधारित","विशुद्ध मानक-संदर्भित, प्रत्येक विद्यार्थी को कक्षा में श्रेणीबद्ध करता","बोर्ड परीक्षाओं तक सीमित, विद्यालय-स्तर के किसी परीक्षण के बिना","नियमित, रचनात्मक और दक्षता-आधारित, उच्चतर-क्रम कौशलों की जाँच करता हुआ"],"explanationHi":"NEP 2020 नियमित, रचनात्मक, दक्षता-आधारित आकलन की माँग करती है जो अधिगम को बढ़ावा दे और स्मृति के बजाय उच्चतर-क्रम कौशलों की जाँच करे।"},
  {"id":"cdp-child-development-1406","question":"Which of these describe the holistic progress card proposed in NEP 2020? I. It includes self-assessment and peer assessment besides teacher assessment. II. It reports progress in cognitive, affective and psychomotor domains. III. It is meant to be shared with parents, linking home and school. IV. It replaces teacher observation with standardised test scores.","options":["I and IV only","II and IV only","I, II and III only","I, II, III and IV"],"answer":2,"explanation":"The 360-degree progress card covers several domains, draws on self, peer and teacher assessment and actively involves parents; it does not reduce assessment to standardised scores.","difficulty":"very-hard","source":"CTET · DSSSB PRT","questionHi":"इनमें से कौन-से NEP 2020 में प्रस्तावित समग्र प्रगति-पत्र का वर्णन करते हैं? I. इसमें शिक्षक आकलन के अतिरिक्त स्व-आकलन और सहपाठी आकलन शामिल हैं। II. यह संज्ञानात्मक, भावात्मक और मनोगामक क्षेत्रों में प्रगति दर्शाता है। III. इसे अभिभावकों के साथ साझा करना है, जो घर और विद्यालय को जोड़ता है। IV. यह शिक्षक के अवलोकन को मानकीकृत परीक्षा-अंकों से प्रतिस्थापित करता है।","optionsHi":["केवल I और IV","केवल II और IV","केवल I, II और III","I, II, III और IV"],"explanationHi":"360-डिग्री प्रगति-पत्र कई क्षेत्रों को कवर करता है, स्व, सहपाठी और शिक्षक आकलन का उपयोग करता है और अभिभावकों को सक्रिय रूप से शामिल करता है; वह आकलन को मानकीकृत अंकों तक सीमित नहीं करता।"},
  {"id":"cdp-child-development-1407","question":"NEP 2020 proposes school examinations in Grades 3, 5 and 8. Their stated purpose is to:","options":["Track learning over the years to improve the system, testing core concepts","Decide which students must be detained in the same grade for one more year","Rank schools publicly so that parents can choose for admission","Replace the Grade 10 board examination with three smaller tests"],"answer":0,"explanation":"These examinations are meant to monitor learning and help improve teaching and the system; they test basic learning outcomes and core concepts, not memorised content.","difficulty":"very-hard","source":"CTET · KVS TGT","questionHi":"NEP 2020 कक्षा 3, 5 और 8 में विद्यालयी परीक्षाएँ प्रस्तावित करती है। उनका घोषित उद्देश्य है:","optionsHi":["मूल अवधारणाओं की जाँच करते हुए, प्रणाली को सुधारने के लिए वर्षों में अधिगम पर नज़र रखना","तय करना कि किन विद्यार्थियों को उसी कक्षा में एक और वर्ष रोका जाए","विद्यालयों को सार्वजनिक रूप से श्रेणीबद्ध करना ताकि अभिभावक प्रवेश के लिए चुन सकें","कक्षा 10 की बोर्ड परीक्षा को तीन छोटी परीक्षाओं से बदलना"],"explanationHi":"ये परीक्षाएँ अधिगम की निगरानी करने और शिक्षण तथा प्रणाली को सुधारने में सहायता के लिए हैं; ये बुनियादी अधिगम-प्रतिफलों और मूल अवधारणाओं की जाँच करती हैं, रटी सामग्री की नहीं।"},
  {"id":"cdp-child-development-1408","question":"A Class 7 teacher teaches symmetry through Warli and Madhubani patterns and the history of the region through its folk art. NEP 2020 calls this:","options":["Rote learning through patterns","Vocational training in folk crafts","Art-integrated education","Remedial teaching through drawing"],"answer":2,"explanation":"NEP 2020 promotes art-integrated education, which uses arts and culture to teach concepts across subjects and links learning with Indian culture.","difficulty":"moderate","source":"CTET Paper II · KVS TGT","questionHi":"कक्षा 7 का एक शिक्षक वारली और मधुबनी प्रतिरूपों के माध्यम से सममिति पढ़ाता है और क्षेत्र का इतिहास उसकी लोक-कला के माध्यम से। NEP 2020 इसे क्या कहती है?","optionsHi":["प्रतिरूपों द्वारा रटंत अधिगम","लोक-शिल्पों में व्यावसायिक प्रशिक्षण","कला-समेकित शिक्षा","चित्रकारी द्वारा उपचारात्मक शिक्षण"],"explanationHi":"NEP 2020 कला-समेकित शिक्षा को बढ़ावा देती है, जो विषयों में अवधारणाएँ पढ़ाने के लिए कलाओं और संस्कृति का उपयोग करती है और अधिगम को भारतीय संस्कृति से जोड़ती है।"},
  {"id":"cdp-child-development-1409","question":"Why does NEP 2020 recommend reducing curriculum content in each subject to its core essentials?","options":["To finish the syllabus faster and so hold more examinations during the year","To free time for critical thinking and inquiry- and discussion-based learning","To reduce the number of teachers needed for each subject in government schools","To shorten the school day so that children have more time for tuition"],"answer":1,"explanation":"Lighter content is meant to free time for deep, experiential and holistic learning instead of rote coverage of an overloaded syllabus.","difficulty":"hard","source":"CTET · State TET","questionHi":"NEP 2020 प्रत्येक विषय में पाठ्यचर्या की सामग्री को उसके मूल आवश्यक तत्त्वों तक घटाने की अनुशंसा क्यों करती है?","optionsHi":["पाठ्यक्रम जल्दी पूरा करने के लिए ताकि वर्ष में अधिक परीक्षाएँ हों","आलोचनात्मक चिंतन और पूछताछ तथा चर्चा-आधारित अधिगम के लिए समय मुक्त करने के लिए","सरकारी विद्यालयों में प्रत्येक विषय के लिए आवश्यक शिक्षकों की संख्या घटाने के लिए","विद्यालयी दिन छोटा करने के लिए ताकि बच्चों को ट्यूशन के लिए अधिक समय मिले"],"explanationHi":"हल्की सामग्री का उद्देश्य अत्यधिक बोझिल पाठ्यक्रम के रटंत विस्तार के बजाय गहन, अनुभवात्मक और समग्र अधिगम के लिए समय मुक्त करना है।"},
  {"id":"cdp-child-development-1410","question":"In a Grade 2 class in Bengaluru, children speak Kannada, Tamil, Urdu and Hindi at home, and the medium of instruction is Kannada. Consistent with NEP 2020, the teacher should:","options":["Insist on Kannada only and fine children who use their home languages","Change the medium to English so that no home language is favoured","Use a bilingual approach, drawing on home languages alongside Kannada","Shift the Urdu-speaking children to a school with an Urdu medium"],"answer":2,"explanation":"NEP 2020 encourages teachers to use a bilingual approach and bilingual materials with children whose home language differs from the medium of instruction.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"बेंगलुरु की कक्षा 2 में बच्चे घर पर कन्नड़, तमिल, उर्दू और हिंदी बोलते हैं, और शिक्षण का माध्यम कन्नड़ है। NEP 2020 के अनुरूप, शिक्षक को चाहिए कि वह:","optionsHi":["केवल कन्नड़ पर ज़ोर दे और घर की भाषाओं का प्रयोग करने वाले बच्चों पर जुर्माना लगाए","माध्यम को अंग्रेज़ी में बदल दे ताकि किसी घर की भाषा को वरीयता न मिले","द्विभाषिक उपागम का प्रयोग करे, कन्नड़ के साथ घर की भाषाओं का सहारा लेते हुए","उर्दू-भाषी बच्चों को उर्दू माध्यम वाले विद्यालय में भेज दे"],"explanationHi":"NEP 2020 शिक्षकों को उन बच्चों के साथ द्विभाषिक उपागम और द्विभाषिक सामग्री का प्रयोग करने के लिए प्रोत्साहित करती है जिनकी घर की भाषा शिक्षण के माध्यम से भिन्न है।"},
  {"id":"cdp-child-development-1411","question":"Match each NEP 2020 stage with its emphasis: P. Foundational  Q. Preparatory  R. Middle  S. Secondary — 1. Flexible, multilevel, play- and activity-based learning  2. Play and discovery with a gradual start of formal but interactive classroom learning  3. Experiential learning across sciences, mathematics, arts, social sciences and humanities with subject teachers  4. Greater depth, critical thinking and flexibility in the choice of subjects","options":["P-1, Q-2, R-3, S-4","P-2, Q-1, R-3, S-4","P-1, Q-3, R-2, S-4","P-1, Q-2, R-4, S-3"],"answer":0,"explanation":"The emphasis moves from play (foundational) to gradual formal learning (preparatory), to subject-based experiential learning (middle), to depth and choice (secondary).","difficulty":"very-hard","source":"CTET · DSSSB TGT","questionHi":"प्रत्येक NEP 2020 चरण का उसके बल से मिलान कीजिए: P. आधारभूत Q. प्रारंभिक R. मध्य S. माध्यमिक — 1. लचीला, बहुस्तरीय, खेल और गतिविधि आधारित अधिगम 2. खेल और खोज के साथ औपचारिक पर संवादात्मक कक्षा-अधिगम की क्रमिक शुरुआत 3. विषय-शिक्षकों के साथ विज्ञान, गणित, कला, सामाजिक विज्ञान और मानविकी में अनुभवात्मक अधिगम 4. विषयों के चयन में अधिक गहराई, आलोचनात्मक चिंतन और लचीलापन","optionsHi":["P-1, Q-2, R-3, S-4","P-2, Q-1, R-3, S-4","P-1, Q-3, R-2, S-4","P-1, Q-2, R-4, S-3"],"explanationHi":"बल खेल (आधारभूत) से क्रमिक औपचारिक अधिगम (प्रारंभिक), विषय-आधारित अनुभवात्मक अधिगम (मध्य), और गहराई तथा चयन (माध्यमिक) की ओर बढ़ता है।"},
  {"id":"cdp-child-development-1412","question":"NEP 2020 proposes that students be allowed to take board examinations on up to two occasions in a school year. The main purpose is to:","options":["Raise the income of examination boards through extra fees for each attempt","Make students study twice as hard, since each sitting is a fresh and complete test","Increase competition among students, as the better of two scores decides rank","Reduce the pressure of a single attempt, allowing a second try for improvement"],"answer":3,"explanation":"A second opportunity reduces the ‘one-shot’ pressure that drives coaching and anxiety, in keeping with NEP 2020’s aim of making board exams low-stakes.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"NEP 2020 प्रस्तावित करती है कि विद्यार्थियों को एक शैक्षणिक वर्ष में अधिकतम दो अवसरों पर बोर्ड परीक्षाएँ देने की अनुमति हो। मुख्य उद्देश्य है:","optionsHi":["हर प्रयास के अतिरिक्त शुल्क से परीक्षा-बोर्डों की आय बढ़ाना","विद्यार्थियों को दोगुना परिश्रम करने के लिए बाध्य करना, क्योंकि प्रत्येक बैठक नई और पूरी परीक्षा है","विद्यार्थियों में प्रतिस्पर्धा बढ़ाना, क्योंकि दो अंकों में बेहतर अंक श्रेणी तय करता है","एक प्रयास का दबाव घटाना, सुधार के लिए दूसरा प्रयास देते हुए"],"explanationHi":"दूसरा अवसर उस ‘एक-बार’ के दबाव को घटाता है जो कोचिंग और चिंता को बढ़ाता है, बोर्ड परीक्षाओं को कम-दाँव वाला बनाने के NEP 2020 के उद्देश्य के अनुरूप।"},
  {"id":"cdp-child-development-1413","question":"Assertion (A): NEP 2020 recommends that vocational education be introduced only after Class 12. Reason (R): NEP 2020 aims to remove the hard separation between vocational and academic streams.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"NEP 2020 brings vocational exposure in from Grade 6 (with internships and bagless days), precisely because it wants to integrate vocational and academic learning; so A is false.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"अभिकथन (A): NEP 2020 अनुशंसा करती है कि व्यावसायिक शिक्षा केवल कक्षा 12 के बाद प्रारंभ हो। कारण (R): NEP 2020 व्यावसायिक और शैक्षिक धाराओं के बीच कठोर विभाजन को हटाना चाहती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"NEP 2020 व्यावसायिक संपर्क को कक्षा 6 से (प्रशिक्षुताओं और बैग-रहित दिनों के साथ) लाती है, ठीक इसलिए कि वह व्यावसायिक और शैक्षिक अधिगम को समेकित करना चाहती है; इसलिए A असत्य है।"},
  {"id":"cdp-child-development-1414","question":"NEP 2020 says that teachers ‘truly shape the future of our children’. Which reform is consistent with this view?","options":["A four-year integrated B.Ed. as the minimum qualification by 2030","Dropping teacher eligibility requirements to recruit more teachers quickly","Replacing regular teachers with contract para-teachers to cut costs","Deploying teachers more often for census and election duty"],"answer":0,"explanation":"NEP 2020 aims to raise teacher preparation and status through the integrated B.Ed., CPD and an end to para-teacher hiring and non-teaching duties.","difficulty":"hard","source":"CTET · KVS TGT","questionHi":"NEP 2020 कहती है कि शिक्षक ‘हमारे बच्चों का भविष्य वास्तव में गढ़ते हैं’। कौन-सा सुधार इस दृष्टि के अनुरूप है?","optionsHi":["2030 तक न्यूनतम योग्यता के रूप में चार-वर्षीय एकीकृत B.Ed.","अधिक शिक्षकों की शीघ्र भर्ती के लिए शिक्षक पात्रता आवश्यकताएँ हटाना","लागत घटाने के लिए नियमित शिक्षकों को संविदा पैरा-शिक्षकों से बदलना","शिक्षकों को जनगणना और चुनाव-ड्यूटी में अधिक बार लगाना"],"explanationHi":"NEP 2020 एकीकृत B.Ed., सतत व्यावसायिक विकास (CPD) और पैरा-शिक्षक भर्ती तथा गैर-शिक्षण कर्तव्यों की समाप्ति के माध्यम से शिक्षक-तैयारी और प्रतिष्ठा बढ़ाना चाहती है।"},
  {"id":"cdp-child-development-1415","question":"Which NEP 2020 measure is aimed specifically at equity for socio-economically disadvantaged groups?","options":["A common entrance test for Class 1 admission, so seats go by merit alone","Ending the mid-day meal scheme to free funds for hiring more teachers","A Gender-Inclusion Fund and Special Education Zones in disadvantaged regions","Merging all small village schools into larger city schools with much better labs"],"answer":2,"explanation":"NEP 2020 proposes a Gender-Inclusion Fund for girls and transgender students and Special Education Zones in disadvantaged regions to close equity gaps.","difficulty":"very-hard","source":"CTET · DSSSB TGT","questionHi":"कौन-सा NEP 2020 उपाय विशेष रूप से सामाजिक-आर्थिक रूप से वंचित समूहों की समता के लिए लक्षित है?","optionsHi":["कक्षा 1 प्रवेश के लिए साझा प्रवेश परीक्षा, ताकि सीटें केवल योग्यता से जाएँ","अधिक शिक्षकों की भर्ती के लिए धन मुक्त करने हेतु मध्याह्न भोजन योजना समाप्त करना","वंचित क्षेत्रों में लैंगिक-समावेशन कोष और विशेष शिक्षा क्षेत्र","सभी छोटे गाँव के विद्यालयों को कहीं बेहतर प्रयोगशालाओं वाले बड़े शहरी विद्यालयों में विलय करना"],"explanationHi":"NEP 2020 समता के अंतर को पाटने के लिए लड़कियों और ट्रांसजेंडर विद्यार्थियों हेतु लैंगिक-समावेशन कोष और वंचित क्षेत्रों में विशेष शिक्षा क्षेत्र प्रस्तावित करती है।"},
  {"id":"cdp-child-development-1416","question":"Which activity best reflects ‘experiential learning’ as promoted by NEP 2020?","options":["Copying neat notes from the blackboard about rainfall and the monsoon","Measuring rainfall with home-made gauges and graphing the data","Reading the textbook chapter on weather aloud in turns around the class","Memorising definitions of weather terms for a weekly quiz"],"answer":1,"explanation":"Experiential learning means learning by doing and reflecting on real experience; the rain-gauge project combines hands-on work, data and inquiry.","difficulty":"moderate","source":"CTET Paper II · State TET","questionHi":"कौन-सी गतिविधि NEP 2020 द्वारा प्रोत्साहित ‘अनुभवात्मक अधिगम’ को सबसे अच्छी तरह दर्शाती है?","optionsHi":["वर्षा और मानसून के बारे में श्यामपट्ट से साफ़ नोट्स उतारना","घर में बने वर्षामापकों से वर्षा मापना और आँकड़ों का आलेख बनाना","मौसम पर पाठ्यपुस्तक का अध्याय कक्षा में बारी-बारी से ज़ोर से पढ़ना","साप्ताहिक प्रश्नोत्तरी के लिए मौसम संबंधी शब्दों की परिभाषाएँ रटना"],"explanationHi":"अनुभवात्मक अधिगम का अर्थ है वास्तविक अनुभव पर करके और चिंतन करके सीखना; वर्षामापक परियोजना प्रत्यक्ष कार्य, आँकड़े और पूछताछ को जोड़ती है।"},
  {"id":"cdp-child-development-1417","question":"Which of these ideas are common to NCF 2005 and NEP 2020? I. Reducing rote learning. II. Using the home language or mother tongue in the early years. III. Making board examinations less stressful. IV. Detaining children who fail from Class 1 onwards.","options":["I and IV only","II and IV only","I, II, III and IV","I, II and III only"],"answer":3,"explanation":"Both documents oppose rote learning, value the home language and want low-stress board exams; neither recommends detention from Class 1.","difficulty":"very-hard","source":"CTET · KVS PRT","questionHi":"NCF 2005 और NEP 2020 में इनमें से कौन-से विचार समान हैं? I. रटंत अधिगम घटाना। II. प्रारंभिक वर्षों में घर की भाषा या मातृभाषा का प्रयोग। III. बोर्ड परीक्षाओं को कम तनावपूर्ण बनाना। IV. कक्षा 1 से अनुत्तीर्ण बच्चों को रोकना।","optionsHi":["केवल I और IV","केवल II और IV","I, II, III और IV","केवल I, II और III"],"explanationHi":"दोनों दस्तावेज़ रटंत अधिगम के विरुद्ध हैं, घर की भाषा को महत्त्व देते हैं और कम-तनाव वाली बोर्ड परीक्षाएँ चाहते हैं; कोई भी कक्षा 1 से रोके जाने की अनुशंसा नहीं करता।"},
  {"id":"cdp-child-development-1418","question":"A deaf child joins a Grade 3 class. Consistent with NEP 2020, the school should:","options":["Send the child to a special school only, since regular classes cannot cope","Rely on lip-reading alone, so that the child adapts to hearing peers","Use Indian Sign Language, with suitable materials and support","Exempt the child from all language learning to reduce the burden"],"answer":2,"explanation":"NEP 2020 calls for Indian Sign Language to be standardised across the country and for national and state curriculum materials for students with hearing impairment.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"एक बधिर बच्चा कक्षा 3 में आता है। NEP 2020 के अनुरूप, विद्यालय को चाहिए कि वह:","optionsHi":["बच्चे को केवल विशेष विद्यालय भेजे, क्योंकि नियमित कक्षाएँ सँभाल नहीं सकतीं","केवल होंठ-पठन पर निर्भर रहे, ताकि बच्चा श्रवणसक्षम साथियों के अनुकूल हो जाए","उपयुक्त सामग्री और सहायता के साथ भारतीय सांकेतिक भाषा का प्रयोग करे","बोझ घटाने के लिए बच्चे को सारे भाषा-अधिगम से छूट दे"],"explanationHi":"NEP 2020 भारतीय सांकेतिक भाषा के देश भर में मानकीकरण और श्रवण-बाधित विद्यार्थियों के लिए राष्ट्रीय तथा राज्य पाठ्यचर्या-सामग्री की माँग करती है।"},
  {"id":"cdp-child-development-1419","question":"A Grade 4 teacher finds that half her class cannot read a Grade 2 text. The response most consistent with NEP 2020’s FLN priority is to:","options":["Continue with the Grade 4 syllabus so as to finish it on time for the exams","Assess levels and teach foundational reading by level for part of each day","Detain these children in Grade 4 until they can read at grade level again","Ask the parents to arrange private tuition so that reading improves at home"],"answer":1,"explanation":"NEP 2020 wants learning gaps in FLN closed urgently through targeted support at the child’s actual level; ploughing on with the syllabus leaves them behind permanently.","difficulty":"very-hard","source":"CTET Paper I · State TET","questionHi":"कक्षा 4 की एक शिक्षिका पाती है कि उसकी आधी कक्षा कक्षा 2 का पाठ नहीं पढ़ सकती। NEP 2020 की FLN प्राथमिकता के सबसे अनुरूप प्रतिक्रिया है:","optionsHi":["कक्षा 4 का पाठ्यक्रम चलाते रहना ताकि परीक्षाओं के लिए समय पर पूरा हो","स्तरों का आकलन करना और प्रत्येक दिन के एक भाग में स्तर के अनुसार आधारभूत पठन सिखाना","इन बच्चों को कक्षा 4 में तब तक रोकना जब तक वे कक्षा-स्तर पर फिर पढ़ न सकें","अभिभावकों से निजी ट्यूशन की व्यवस्था करने को कहना ताकि घर पर पठन सुधरे"],"explanationHi":"NEP 2020 चाहती है कि FLN के अधिगम-अंतराल बच्चे के वास्तविक स्तर पर लक्षित सहायता से तत्काल पाटे जाएँ; पाठ्यक्रम पर आगे बढ़ते जाना उन्हें स्थायी रूप से पीछे छोड़ देता है।"},
  {"id":"cdp-child-development-1420","question":"Match each theorist with the classroom technique that grows most directly out of his work. P. Skinner  Q. Bandura  R. Vygotsky  S. Ausubel. 1. Teacher thinks aloud while solving a problem so students can imitate the strategy 2. Small-step self-paced frames with immediate feedback 3. A brief overview before a new chapter to anchor details 4. Hints that are gradually withdrawn as the learner gains control","options":["P-2, Q-4, R-1, S-3","P-1, Q-2, R-4, S-3","P-2, Q-1, R-4, S-3","P-3, Q-1, R-4, S-2"],"answer":2,"explanation":"Programmed instruction is Skinner's; cognitive modelling follows Bandura; faded scaffolding within the ZPD follows Vygotsky; the advance organiser is Ausubel's.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"प्रत्येक सिद्धांतकार का उस कक्षा-तकनीक से मिलान कीजिए जो उसके कार्य से सबसे प्रत्यक्ष रूप से उपजती है। P. स्किनर Q. बैंडूरा R. वाइगोत्स्की S. ऑसुबेल। 1. शिक्षक समस्या हल करते समय ज़ोर से सोचता है ताकि विद्यार्थी रणनीति की नकल कर सकें 2. तत्काल प्रतिक्रिया के साथ छोटे चरणों वाले स्व-गति फ़्रेम 3. विवरणों को आधार देने के लिए नए अध्याय से पहले संक्षिप्त अवलोकन 4. संकेत जो अधिगमकर्ता के नियंत्रण पाने पर धीरे-धीरे हटाए जाते हैं","optionsHi":["P-2, Q-4, R-1, S-3","P-1, Q-2, R-4, S-3","P-2, Q-1, R-4, S-3","P-3, Q-1, R-4, S-2"],"explanationHi":"अभिक्रमित अनुदेशन स्किनर का है; संज्ञानात्मक आदर्श-प्रस्तुति बैंडूरा से निकलती है; ZPD के भीतर क्रमशः हटाया जाने वाला पाड़ वाइगोत्स्की से निकलता है; अग्रिम संगठक ऑसुबेल का है।"},
  {"id":"cdp-child-development-1421","question":"Asked to choose the larger fraction, many Class 4 children pick 1/8 over 1/4, saying ‘8 is bigger than 4’. What should the teacher conclude?","options":["They are guessing randomly, since fractions still mean nothing at all to them","Whole-number thinking: they miss that more equal parts make each part smaller","They cannot read numbers correctly and so confuse the digits 4 and 8","They need to memorise a list of fraction comparisons by heart"],"answer":1,"explanation":"The error is systematic and logical from a whole-number view. Sharing a roti among 4 versus 8 children quickly shows that each share is smaller when the denominator is larger.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"बड़ी भिन्न चुनने को कहने पर, कक्षा 4 के कई बच्चे 1/4 के स्थान पर 1/8 चुनते हैं, यह कहकर कि ‘8, 4 से बड़ा है’। शिक्षक को क्या निष्कर्ष निकालना चाहिए?","optionsHi":["वे यादृच्छिक अनुमान लगा रहे हैं, क्योंकि भिन्नों का उनके लिए अब भी कोई अर्थ नहीं है","पूर्ण-संख्या चिंतन: वे चूक जाते हैं कि अधिक बराबर भाग प्रत्येक भाग को छोटा बना देते हैं","वे संख्याएँ सही नहीं पढ़ सकते और इसलिए अंक 4 और 8 को उलझा देते हैं","उन्हें भिन्नों की तुलनाओं की सूची रटनी चाहिए"],"explanationHi":"यह त्रुटि पूर्ण-संख्या दृष्टिकोण से व्यवस्थित और तर्कसंगत है। एक रोटी को 4 बनाम 8 बच्चों में बाँटना शीघ्र दिखाता है कि हर अंश छोटा तब होता है जब हर बड़ा हो।"},
  {"id":"cdp-child-development-1422","question":"A Class 6 student says, ‘If I double each side of a square, its area will also double.’ What does this error reveal and how should the teacher respond?","options":["Over-applied doubling; drawing unit squares will show the area becomes four times","Careless reading of the question; ask him to read it twice before he answers it","A memory lapse about the formula; make him learn it by heart and recite it","Lack of intelligence for geometry; give him easier sums until he catches up"],"answer":0,"explanation":"Students often assume all quantities change proportionally with length. Drawing a 2×2 and a 4×4 square shows 4 versus 16 unit squares, challenging the linear assumption.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 6 का एक विद्यार्थी कहता है, ‘यदि मैं वर्ग की प्रत्येक भुजा को दोगुना कर दूँ, तो उसका क्षेत्रफल भी दोगुना हो जाएगा।’ यह त्रुटि क्या प्रकट करती है और शिक्षक को कैसे प्रतिक्रिया देनी चाहिए?","optionsHi":["दोगुना करने का अति-अनुप्रयोग; इकाई वर्ग बनाने से दिखेगा कि क्षेत्रफल चार गुना हो जाता है","प्रश्न की लापरवाह पढ़ाई; उससे उत्तर देने से पहले दो बार पढ़ने को कहें","सूत्र के बारे में स्मृति-चूक; उसे सूत्र रटवाकर सुनवाएँ","ज्यामिति के लिए बुद्धि की कमी; जब तक वह बराबरी न कर ले उसे आसान योग दें"],"explanationHi":"विद्यार्थी प्रायः मान लेते हैं कि सभी राशियाँ लंबाई के अनुपात में बदलती हैं। 2×2 और 4×4 का वर्ग बनाने से 4 बनाम 16 इकाई वर्ग दिखते हैं, जो रैखिक धारणा को चुनौती देते हैं।"},
  {"id":"cdp-child-development-1423","question":"In subtraction sums such as 300 − 156 and 402 − 127, Class 3 student Ritu always writes the bottom digit wherever the top digit is 0 (for example, 0 − 6 as 6). What is the best description of her errors?","options":["Random slips caused by tiredness at the end of a long school day","A visual problem with the digit zero, which she may not be seeing clearly","Proactive interference from addition, where order does not matter","A consistent faulty rule about zeros, to be diagnosed and re-taught"],"answer":3,"explanation":"The error is the same across sums, so it reflects a faulty procedure about zeros rather than carelessness. Exchanging bundles of tens and hundreds addresses the misunderstanding.","difficulty":"hard","source":"CTET Paper 1 · Super TET","questionHi":"300 − 156 और 402 − 127 जैसे घटाव के योगों में, कक्षा 3 की विद्यार्थी रितु जहाँ भी ऊपर का अंक 0 होता है, वहाँ नीचे का अंक लिख देती है (जैसे 0 − 6 को 6)। उसकी त्रुटियों का सबसे अच्छा वर्णन क्या है?","optionsHi":["लंबे विद्यालयी दिन के अंत में थकान से हुई यादृच्छिक चूकें","अंक शून्य के साथ दृश्य समस्या, जिसे वह स्पष्ट नहीं देख पा रही हो","जोड़ से अग्रलक्षी व्यतिकरण, जहाँ क्रम मायने नहीं रखता","शून्यों के बारे में एक सुसंगत दोषपूर्ण नियम, जिसका निदान करके पुनः शिक्षण करना चाहिए"],"explanationHi":"त्रुटि सभी योगों में एक-सी है, इसलिए वह लापरवाही के बजाय शून्यों के बारे में दोषपूर्ण प्रक्रिया को दर्शाती है। दहाइयों और सैकड़ों के बंडलों का विनिमय इस भ्रांति को संबोधित करता है।"},
  {"id":"cdp-child-development-1424","question":"A Class 5 student whose home language is Hindi writes in English, ‘I am having two brothers’ and ‘What you are doing?’. How should the teacher understand these errors?","options":["As evidence of poor intelligence, since the rules have been taught clearly in class","As deliberate carelessness that should be punished to stop the habit","As natural signs of a developing second language, shaped partly by the first","As a sign that English should be stopped until Class 8 to avoid confusion"],"answer":2,"explanation":"Second-language learners build an interim system using rules from their first language and their emerging hypotheses; such errors show learning in progress and guide teaching.","difficulty":"hard","source":"CTET · UPTET","questionHi":"कक्षा 5 का एक विद्यार्थी जिसकी घर की भाषा हिंदी है, अंग्रेज़ी में लिखता है, ‘I am having two brothers’ और ‘What you are doing?’। शिक्षक को इन त्रुटियों को कैसे समझना चाहिए?","optionsHi":["खराब बुद्धि के प्रमाण के रूप में, क्योंकि नियम कक्षा में स्पष्ट रूप से पढ़ाए गए हैं","जानबूझकर की गई लापरवाही के रूप में जिसे आदत रोकने के लिए दंडित किया जाना चाहिए","विकसित हो रही द्वितीय भाषा के स्वाभाविक संकेतों के रूप में, जो आंशिक रूप से पहली भाषा से आकार पाते हैं","इस संकेत के रूप में कि भ्रम से बचने के लिए कक्षा 8 तक अंग्रेज़ी रोक देनी चाहिए"],"explanationHi":"द्वितीय-भाषा अधिगमकर्ता अपनी पहली भाषा के नियमों और अपनी उभरती परिकल्पनाओं से एक अंतरिम प्रणाली बनाते हैं; ऐसी त्रुटियाँ चल रहे अधिगम को दिखाती हैं और शिक्षण का मार्गदर्शन करती हैं।"},
  {"id":"cdp-child-development-1425","question":"Which of the following teacher-related factors are known to influence students' learning? I. The teacher's expectations of students. II. The teacher's enthusiasm and clarity of explanation. III. The teacher's relationship and emotional climate in the class. IV. The colour of the teacher's clothes.","options":["I, II and III only","I and II only","II and IV only","I, II, III and IV"],"answer":0,"explanation":"Teacher expectations, clarity, enthusiasm and the emotional climate all affect learning; clothing colour has no established effect.","difficulty":"moderate","source":"CTET · REET","questionHi":"शिक्षक-संबंधी निम्नलिखित कारकों में से कौन-से विद्यार्थियों के अधिगम को प्रभावित करने के लिए ज्ञात हैं? I. विद्यार्थियों से शिक्षक की अपेक्षाएँ। II. शिक्षक का उत्साह और व्याख्या की स्पष्टता। III. शिक्षक का संबंध और कक्षा का भावनात्मक वातावरण। IV. शिक्षक के कपड़ों का रंग।","optionsHi":["केवल I, II और III","केवल I और II","केवल II और IV","I, II, III और IV"],"explanationHi":"शिक्षक की अपेक्षाएँ, स्पष्टता, उत्साह और भावनात्मक वातावरण सभी अधिगम को प्रभावित करते हैं; कपड़ों के रंग का कोई स्थापित प्रभाव नहीं है।"},
  {"id":"cdp-child-development-1426","question":"A Class 2 teacher keeps the room fear-free: children may ask questions without being laughed at, and mistakes are discussed calmly. Why does this matter for learning?","options":["It is required only for discipline, so that the class stays orderly","Anxiety drains attention and working memory; security invites exploration","It makes the teacher popular with parents, which in turn helps school enrolment","It removes the need for assessment, since mistakes no longer matter"],"answer":1,"explanation":"Anxiety consumes cognitive resources and discourages questioning. A safe climate, which the RTE Act and NCF 2005 both stress, supports active participation and learning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 की एक शिक्षिका कमरे को भय-मुक्त रखती है: बच्चे बिना उपहास के प्रश्न पूछ सकते हैं, और गलतियों पर शांत चर्चा होती है। यह अधिगम के लिए क्यों मायने रखता है?","optionsHi":["यह केवल अनुशासन के लिए आवश्यक है, ताकि कक्षा व्यवस्थित रहे","चिंता ध्यान और कार्यशील स्मृति को खींच लेती है; सुरक्षा अन्वेषण को आमंत्रित करती है","यह शिक्षिका को अभिभावकों में लोकप्रिय बनाता है, जो बदले में विद्यालय-नामांकन में सहायक है","यह आकलन की आवश्यकता समाप्त कर देता है, क्योंकि गलतियाँ अब मायने नहीं रखतीं"],"explanationHi":"चिंता संज्ञानात्मक संसाधनों को खर्च करती है और प्रश्न पूछने को हतोत्साहित करती है। सुरक्षित वातावरण, जिस पर RTE अधिनियम और NCF 2005 दोनों बल देते हैं, सक्रिय भागीदारी और अधिगम में सहायक है।"},
  {"id":"cdp-child-development-1427","question":"In a school serving many first-generation learners, homework often requires internet searches or explanations from parents. Many children return it incomplete. Which factor affecting learning is most at work, and what is the fair response?","options":["Laziness of the children; give extra homework as punishment to build habits","Low intelligence; place these children in a separate, slower-paced section","Lack of motivation; reward only those who complete it, to set an example","Unequal home resources; set doable tasks and support children at school"],"answer":3,"explanation":"Socio-economic and home factors (access to resources, educated adults) affect learning opportunities. Tasks that assume such support disadvantage some children through no fault of their own.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"पहली पीढ़ी के अनेक अधिगमकर्ताओं की सेवा करने वाले एक विद्यालय में, गृहकार्य के लिए प्रायः इंटरनेट पर खोज या माता-पिता से व्याख्या की आवश्यकता होती है। कई बच्चे उसे अधूरा लौटाते हैं। अधिगम को प्रभावित करने वाला कौन-सा कारक सबसे अधिक कार्य कर रहा है, और न्यायसंगत प्रतिक्रिया क्या है?","optionsHi":["बच्चों का आलस्य; आदतें बनाने के लिए दंड के रूप में अतिरिक्त गृहकार्य देना","निम्न बुद्धि; इन बच्चों को अलग, धीमी गति वाले अनुभाग में रखना","अभिप्रेरणा की कमी; केवल उन्हें पुरस्कृत करना जो उसे पूरा करें, उदाहरण स्थापित करने के लिए","असमान घरेलू संसाधन; साध्य कार्य देना और बच्चों को विद्यालय में सहायता देना"],"explanationHi":"सामाजिक-आर्थिक और घरेलू कारक (संसाधनों की उपलब्धता, शिक्षित वयस्क) अधिगम के अवसरों को प्रभावित करते हैं। जो कार्य ऐसी सहायता मानकर चलते हैं, वे कुछ बच्चों को उनकी अपनी किसी गलती के बिना हानि पहुँचाते हैं।"},
  {"id":"cdp-child-development-1428","question":"A Class 6 student must memorise a meaningful 16-line poem. Which method is generally recommended, and when would the alternative be better?","options":["Always the part method, since smaller parts are easier for any child to hold","Whole method here; the part method suits very long or difficult material","Always the whole method, whatever the length or difficulty of the material","Neither method; only the number of repetitions matters for memorising"],"answer":1,"explanation":"Learning a meaningful piece as a whole preserves its sense and connections; for very long or hard material, learning in parts (then joining them) can be more efficient.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"कक्षा 6 के एक विद्यार्थी को 16 पंक्तियों की एक अर्थपूर्ण कविता याद करनी है। सामान्यतः कौन-सी विधि अनुशंसित है, और विकल्प कब बेहतर होगा?","optionsHi":["सदैव अंश-विधि, क्योंकि छोटे भाग किसी भी बच्चे के लिए सँभालना आसान होते हैं","यहाँ पूर्ण-विधि; अंश-विधि बहुत लंबी या कठिन सामग्री के लिए उपयुक्त है","सदैव पूर्ण-विधि, सामग्री की लंबाई या कठिनाई चाहे जो हो","कोई विधि नहीं; याद करने के लिए केवल दोहराव की संख्या मायने रखती है"],"explanationHi":"किसी अर्थपूर्ण अंश को पूर्ण रूप में सीखना उसके अर्थ और संबंधों को बनाए रखता है; बहुत लंबी या कठिन सामग्री के लिए भागों में सीखना (फिर उन्हें जोड़ना) अधिक कुशल हो सकता है।"},
  {"id":"cdp-child-development-1429","question":"Gaurav's typing speed rose quickly for six weeks, then stayed flat for three weeks despite practice, and later began rising again. The flat stretch in his learning curve is called a plateau. Which is a common explanation?","options":["He has reached the absolute limit of his ability, and no further gain is possible","His earlier learning has been erased by interference from other activities","He has begun to forget what he learnt earlier because practice became routine","A shift to higher units, like whole words, or fatigue and lost interest"],"answer":3,"explanation":"Plateaus often occur while lower-level habits are reorganised into higher-level units, or due to fatigue, boredom or poor methods; with new strategies or motivation progress resumes.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"गौरव की टाइपिंग गति छह सप्ताह तक तेज़ी से बढ़ी, फिर अभ्यास के बावजूद तीन सप्ताह स्थिर रही, और बाद में फिर बढ़ने लगी। उसके अधिगम-वक्र का समतल भाग पठार (प्लेटू) कहलाता है। एक सामान्य व्याख्या कौन-सी है?","optionsHi":["वह अपनी योग्यता की परम सीमा तक पहुँच गया है, और आगे कोई लाभ संभव नहीं","उसका पहले का अधिगम अन्य गतिविधियों के व्यतिकरण से मिट गया है","वह पहले जो सीखा था उसे भूलने लगा है क्योंकि अभ्यास नियमित हो गया","पूरे शब्दों जैसी उच्च इकाइयों की ओर परिवर्तन, या थकान और रुचि की हानि"],"explanationHi":"पठार प्रायः तब आते हैं जब निम्न-स्तर की आदतें उच्च-स्तर की इकाइयों में पुनर्गठित हो रही होती हैं, या थकान, ऊब या खराब विधियों के कारण; नई रणनीतियों या अभिप्रेरणा के साथ प्रगति फिर शुरू हो जाती है।"},
  {"id":"cdp-child-development-1430","question":"A Class 4 teacher (a) praises children immediately when they answer correctly, (b) demonstrates how to fold paper into a boat while children watch, and (c) gives hints when children struggle and withdraws them as they improve. These practices draw respectively on the ideas of:","options":["Pavlov, Köhler and Piaget","Bandura, Skinner and Vygotsky","Skinner, Bandura and Vygotsky","Thorndike, Vygotsky and Bandura"],"answer":2,"explanation":"Immediate reinforcement reflects operant conditioning (Skinner); learning by watching a demonstration reflects Bandura's observational learning; faded hints reflect Vygotskian scaffolding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 की एक शिक्षिका (a) जब बच्चे सही उत्तर देते हैं तो तुरंत प्रशंसा करती है, (b) बच्चों के देखते हुए कागज़ की नाव बनाना सिखाकर दिखाती है, और (c) जब बच्चे संघर्ष करते हैं तो संकेत देती है और उनके सुधरने पर हटा लेती है। ये अभ्यास क्रमशः किनके विचारों पर आधारित हैं?","optionsHi":["पावलोव, कोहलर और पियाजे","बैंडूरा, स्किनर और वाइगोत्स्की","स्किनर, बैंडूरा और वाइगोत्स्की","थॉर्नडाइक, वाइगोत्स्की और बैंडूरा"],"explanationHi":"तत्काल पुनर्बलन क्रियाप्रसूत अनुबंधन (स्किनर) को दर्शाता है; प्रदर्शन देखकर सीखना बैंडूरा के अवलोकनात्मक अधिगम को दर्शाता है; क्रमशः हटाए गए संकेत वाइगोत्स्की के पाड़ को दर्शाते हैं।"},
  {"id":"cdp-child-development-1431","question":"Assertion (A): A teacher should study the pattern of a child's errors before re-teaching a topic. Reason (R): Systematic errors usually come from a consistent but faulty idea or rule that the child has constructed.","options":["Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Because systematic errors reflect a coherent wrong rule, re-teaching works best when it targets that rule; simply repeating the lesson may leave it untouched.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"अभिकथन (A): किसी विषय को दोबारा पढ़ाने से पहले शिक्षक को बच्चे की त्रुटियों के प्रतिरूप का अध्ययन करना चाहिए। कारण (R): व्यवस्थित त्रुटियाँ प्रायः बच्चे द्वारा गढ़े गए किसी सुसंगत पर दोषपूर्ण विचार या नियम से आती हैं।","optionsHi":["A और R दोनों सत्य हैं पर R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A सत्य है पर R असत्य है","A असत्य है पर R सत्य है"],"explanationHi":"क्योंकि व्यवस्थित त्रुटियाँ एक सुसंगत गलत नियम को दर्शाती हैं, पुनः शिक्षण तब सबसे अच्छा काम करता है जब वह उसी नियम को लक्षित करे; केवल पाठ दोहराना उसे अछूता छोड़ सकता है।"},
  {"id":"cdp-child-development-1432","question":"Assertion (A): Any change in a child's behaviour that appears with growth, such as being able to hold a pencil at age four, is learning. Reason (R): Learning is a relatively lasting change in behaviour or knowledge that results from experience or practice.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"Changes due mainly to maturation, fatigue, illness or drugs are not counted as learning. R correctly defines learning as change through experience, so A is false.","difficulty":"hard","source":"CTET · HTET","questionHi":"अभिकथन (A): बच्चे के व्यवहार में वृद्धि के साथ आने वाला कोई भी परिवर्तन, जैसे चार वर्ष की आयु में पेंसिल पकड़ पाना, अधिगम है। कारण (R): अधिगम अनुभव या अभ्यास के परिणामस्वरूप व्यवहार या ज्ञान में अपेक्षाकृत स्थायी परिवर्तन है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं पर R, A की सही व्याख्या नहीं है","A सत्य है पर R असत्य है","A असत्य है पर R सत्य है"],"explanationHi":"मुख्यतः परिपक्वता, थकान, बीमारी या दवाओं से होने वाले परिवर्तन अधिगम नहीं गिने जाते। R अधिगम को अनुभव से परिवर्तन के रूप में सही परिभाषित करता है, इसलिए A असत्य है।"},
  {"id":"cdp-child-development-1433","question":"Which of these changes would a psychologist count as learning?","options":["A child running more slowly at the end of a long race because of tiredness","A child who, after weeks of practice, can solve two-step word problems","A baby's first teeth appearing on schedule as the body grows","A child who is drowsy and forgetful after taking cough medicine"],"answer":1,"explanation":"Learning is a relatively permanent change resulting from experience. Fatigue, physical growth and the effects of medicine are temporary or maturational changes.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"इनमें से कौन-से परिवर्तन को मनोवैज्ञानिक अधिगम गिनेगा?","optionsHi":["थकान के कारण लंबी दौड़ के अंत में बच्चे का धीमे दौड़ना","सप्ताहों के अभ्यास के बाद बच्चे का दो-चरण वाली शब्द-समस्याएँ हल कर पाना","शरीर के बढ़ने के साथ शिशु के पहले दाँतों का समय पर निकलना","खाँसी की दवा लेने के बाद बच्चे का ऊँघना और भुलक्कड़ हो जाना"],"explanationHi":"अधिगम अनुभव के परिणामस्वरूप अपेक्षाकृत स्थायी परिवर्तन है। थकान, शारीरिक वृद्धि और दवा के प्रभाव अस्थायी या परिपक्वता-जनित परिवर्तन हैं।"},
  {"id":"cdp-child-development-1434","question":"Two groups practise the same arithmetic. Group A gets back its corrected work with specific comments the next day; Group B only receives final marks at the end of the term. Group A improves far more. Which principle explains this?","options":["Knowledge of results: specific, timely feedback guides correction","Spontaneous recovery of skills after a rest between practice sessions","Overjustification, as marks reduce interest in arithmetic itself","The law of disuse, as Group B forgot what it had not practised"],"answer":0,"explanation":"Specific, prompt feedback (knowledge of results) tells learners what to change and keeps them engaged; delayed marks give little information about what went wrong.","difficulty":"moderate","source":"CTET · REET","questionHi":"दो समूह एक ही अंकगणित का अभ्यास करते हैं। समूह A को अगले दिन विशिष्ट टिप्पणियों के साथ सुधारा हुआ कार्य वापस मिलता है; समूह B को केवल सत्र के अंत में अंतिम अंक मिलते हैं। समूह A कहीं अधिक सुधरता है। कौन-सा सिद्धांत इसे समझाता है?","optionsHi":["परिणामों का ज्ञान: विशिष्ट, समयबद्ध प्रतिक्रिया सुधार का मार्गदर्शन करती है","अभ्यास-सत्रों के बीच विश्राम के बाद कौशलों की स्वतः पुनर्प्राप्ति","अतिऔचित्य, क्योंकि अंक अंकगणित में ही रुचि घटाते हैं","अनुपयोग का नियम, क्योंकि समूह B ने जो अभ्यास नहीं किया उसे भूल गया"],"explanationHi":"विशिष्ट, शीघ्र प्रतिक्रिया (परिणामों का ज्ञान) अधिगमकर्ताओं को बताती है कि क्या बदलना है और उन्हें संलग्न रखती है; विलंबित अंक यह बहुत कम बताते हैं कि क्या गलत हुआ।"},
  {"id":"cdp-child-development-1435","question":"Before a project, Class 8 student Aditi sets goals and plans her time; while working she checks whether her plan is working and changes strategies; afterwards she reviews what went well. This cycle is best described as:","options":["Classical conditioning of study habits through repeated routines","Learned helplessness masked by over-careful planning","Self-regulated learning: planning, monitoring and reflection","Formal discipline, training the mind through hard tasks"],"answer":2,"explanation":"Self-regulated learners plan, monitor and evaluate their own learning, using metacognitive and motivational strategies; it draws on Bandura's work on self-regulation and on metacognition.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"परियोजना से पहले कक्षा 8 की विद्यार्थी अदिति लक्ष्य निर्धारित करती है और अपने समय की योजना बनाती है; कार्य करते समय वह जाँचती है कि उसकी योजना काम कर रही है या नहीं और रणनीतियाँ बदलती है; बाद में वह समीक्षा करती है कि क्या अच्छा रहा। इस चक्र का सबसे अच्छा वर्णन है:","optionsHi":["बार-बार की दिनचर्याओं से अध्ययन-आदतों का शास्त्रीय अनुबंधन","अति-सावधान योजना से छिपी सीखी हुई असहायता","स्व-नियमित अधिगम: नियोजन, निगरानी और चिंतन","औपचारिक अनुशासन, कठिन कार्यों से मन को प्रशिक्षित करना"],"explanationHi":"स्व-नियमित अधिगमकर्ता अपने अधिगम की योजना बनाते, निगरानी करते और मूल्यांकन करते हैं, अधिसंज्ञानात्मक और अभिप्रेरणात्मक रणनीतियों का उपयोग करते हुए; यह बैंडूरा के स्व-नियमन और अधिसंज्ञान पर कार्य पर आधारित है।"},
  {"id":"cdp-child-development-1436","question":"Match each classroom situation with the kind of learning it shows. P. A child repeatedly tries keys until one opens a lock  Q. After puzzling over a figure, a child suddenly sees how to split it into triangles  R. A child copies a classmate's polite greeting after seeing it praised  S. A child who has wandered the village can later guide a visitor along a new route. 1. Insight  2. Observational learning  3. Latent learning with a cognitive map  4. Trial and error","options":["P-1, Q-4, R-2, S-3","P-4, Q-1, R-3, S-2","P-2, Q-1, R-4, S-3","P-4, Q-1, R-2, S-3"],"answer":3,"explanation":"Trying keys is trial and error (Thorndike); sudden restructuring is insight (Köhler); copying a reinforced model is observational learning (Bandura); a cognitive map from exploration is latent learning (Tolman).","difficulty":"hard","source":"CTET · UPTET","questionHi":"प्रत्येक कक्षा-स्थिति का उस अधिगम के प्रकार से मिलान कीजिए जिसे वह दर्शाती है। P. एक बच्चा बार-बार चाबियाँ आज़माता है जब तक कोई ताला न खोल दे Q. किसी आकृति पर उलझने के बाद, एक बच्चा अचानक देखता है कि उसे त्रिभुजों में कैसे बाँटा जाए R. एक बच्चा किसी सहपाठी के विनम्र अभिवादन को सराहा जाते देखकर उसकी नकल करता है S. एक बच्चा जो गाँव में घूमा है, बाद में आगंतुक को नए रास्ते से मार्गदर्शन दे सकता है। 1. अंतर्दृष्टि 2. अवलोकनात्मक अधिगम 3. संज्ञानात्मक मानचित्र के साथ गुप्त अधिगम 4. प्रयास और त्रुटि","optionsHi":["P-1, Q-4, R-2, S-3","P-4, Q-1, R-3, S-2","P-2, Q-1, R-4, S-3","P-4, Q-1, R-2, S-3"],"explanationHi":"चाबियाँ आज़माना प्रयास और त्रुटि है (थॉर्नडाइक); अचानक पुनर्गठन अंतर्दृष्टि है (कोहलर); पुनर्बलित आदर्श की नकल करना अवलोकनात्मक अधिगम है (बैंडूरा); अन्वेषण से बना संज्ञानात्मक मानचित्र गुप्त अधिगम है (टोलमैन)।"},
  {"id":"cdp-child-development-1437","question":"A Class 3 child is easily distracted and has difficulty sustaining attention. Which classroom arrangement is most helpful?","options":["Seat him near the teacher, away from doors, with short tasks and checkpoints","Seat him at the back so that he does not disturb the others while they work","Give him longer tasks to build attention through endurance and practice","Remove him from group activities completely so there are fewer distractions"],"answer":0,"explanation":"Reducing distractions, keeping him near the teacher for cues, and breaking tasks into short segments with feedback support attention without excluding him from learning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 का एक बच्चा आसानी से विचलित हो जाता है और ध्यान बनाए रखने में कठिनाई महसूस करता है। कौन-सी कक्षा-व्यवस्था सबसे सहायक है?","optionsHi":["उसे शिक्षक के निकट, दरवाज़ों से दूर बैठाना, छोटे कार्यों और जाँच-बिंदुओं के साथ","उसे पीछे बैठाना ताकि वह दूसरों के काम करते समय उन्हें परेशान न करे","उसे सहनशक्ति और अभ्यास से ध्यान बनाने के लिए लंबे कार्य देना","उसे समूह गतिविधियों से पूरी तरह हटा देना ताकि विकर्षण कम हों"],"explanationHi":"विकर्षण घटाना, संकेतों के लिए उसे शिक्षक के निकट रखना, और कार्यों को प्रतिक्रिया-सहायता के साथ छोटे खंडों में बाँटना उसे अधिगम से बाहर किए बिना ध्यान में सहायता करते हैं।"},
  {"id":"cdp-child-development-1438","question":"Class 9 student Faizan loves reading novels but hides it because classmates mock ‘bookworms’, and he has stopped joining the library club. Which factor affecting learning is most at work here?","options":["Physical maturation, as adolescents naturally lose interest in reading","Retroactive interference between novels and his school textbooks","Learned helplessness about his own ability to read well","Peer-group norms and acceptance shaping his motivation and behaviour"],"answer":3,"explanation":"In adolescence the peer group strongly shapes what is valued; fear of rejection can suppress interests. Teachers can build classroom norms that make reading socially valued.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 9 का विद्यार्थी फ़ैज़ान उपन्यास पढ़ना पसंद करता है पर उसे छिपाता है क्योंकि सहपाठी ‘किताबी कीड़ों’ का मज़ाक उड़ाते हैं, और उसने पुस्तकालय क्लब में शामिल होना बंद कर दिया है। यहाँ अधिगम को प्रभावित करने वाला कौन-सा कारक सबसे अधिक कार्य कर रहा है?","optionsHi":["शारीरिक परिपक्वता, क्योंकि किशोर स्वाभाविक रूप से पढ़ने में रुचि खो देते हैं","उपन्यासों और उसकी विद्यालयी पाठ्यपुस्तकों के बीच पश्चलक्षी व्यतिकरण","अच्छी तरह पढ़ पाने की अपनी योग्यता के बारे में सीखी हुई असहायता","समवयस्क-समूह के मानदंड और स्वीकृति जो उसकी अभिप्रेरणा और व्यवहार को आकार दे रहे हैं"],"explanationHi":"किशोरावस्था में समवयस्क समूह दृढ़ता से आकार देता है कि क्या मूल्यवान है; अस्वीकृति का भय रुचियों को दबा सकता है। शिक्षक कक्षा के ऐसे मानदंड बना सकते हैं जो पढ़ने को सामाजिक रूप से मूल्यवान बनाएँ।"},
  {"id":"cdp-child-development-1439","question":"Which statements about errors in learning are correct? I. A child's error may come from a logical extension of a rule that worked in an earlier context. II. Over-correcting every error in red can discourage children from attempting difficult tasks. III. Errors made by many children in the same way usually point to a common misconception. IV. A correct final answer always proves correct understanding.","options":["I and IV only","I, II and III only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"A right answer can come from a wrong method or from memorisation without understanding, so IV is false. The other statements describe errors as windows into children's thinking.","difficulty":"hard","source":"CTET Paper 1 · Super TET","questionHi":"अधिगम में त्रुटियों के बारे में कौन-से कथन सही हैं? I. बच्चे की त्रुटि किसी नियम के तार्किक विस्तार से आ सकती है जो पहले के संदर्भ में काम करता था। II. हर त्रुटि को लाल रंग में अति-सुधारना बच्चों को कठिन कार्य करने के प्रयास से हतोत्साहित कर सकता है। III. कई बच्चों द्वारा एक ही तरह से की गई त्रुटियाँ प्रायः किसी साझा भ्रांति की ओर संकेत करती हैं। IV. सही अंतिम उत्तर सदैव सही समझ सिद्ध करता है।","optionsHi":["केवल I और IV","केवल I, II और III","केवल II, III और IV","I, II, III और IV"],"explanationHi":"सही उत्तर गलत विधि से या बिना समझे रटने से भी आ सकता है, इसलिए IV असत्य है। अन्य कथन त्रुटियों को बच्चों की सोच की खिड़की के रूप में वर्णित करते हैं।"},
  {"id":"cdp-child-development-1440","question":"A teacher asks Class 4 children to explain how they got answers that are correct as well as those that are wrong. One child got 25 × 4 = 100 by adding 25 four times while another reasoned ‘four quarters make a whole, so it is 100’. What is the main value of this practice?","options":["It wastes time, since the answer is already correct and needs no discussion","It helps only weaker students, who need to hear the steps again","It shows the different strategies and understanding behind one answer","It is useful only for grading, to give marks for the method shown"],"answer":2,"explanation":"Asking for reasoning shows the thinking behind answers: repeated addition and a part–whole insight are different levels of understanding, which helps the teacher plan next steps.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक कक्षा 4 के बच्चों से यह समझाने को कहता है कि उन्होंने सही और गलत दोनों उत्तर कैसे पाए। एक बच्चे ने 25 को चार बार जोड़कर 25 × 4 = 100 पाया, जबकि दूसरे ने तर्क किया ‘चार चौथाई मिलकर पूरा बनते हैं, इसलिए यह 100 है’। इस अभ्यास का मुख्य मूल्य क्या है?","optionsHi":["यह समय की बर्बादी है, क्योंकि उत्तर पहले से सही है और चर्चा की आवश्यकता नहीं","यह केवल कमज़ोर विद्यार्थियों की सहायता करता है, जिन्हें चरण फिर सुनने चाहिए","यह एक ही उत्तर के पीछे की विभिन्न रणनीतियों और समझ को दिखाता है","यह केवल मूल्यांकन के लिए उपयोगी है, दिखाई गई विधि के लिए अंक देने हेतु"],"explanationHi":"तर्क माँगना उत्तरों के पीछे के चिंतन को दिखाता है: बार-बार जोड़ना और अंश-पूर्ण की अंतर्दृष्टि समझ के भिन्न स्तर हैं, जो शिक्षक को अगले चरणों की योजना बनाने में सहायता करते हैं।"},
  {"id":"cdp-child-development-1441","question":"Which statement about the relation between learning and maturation is most accurate?","options":["Learning and maturation are the same process seen from two angles","Maturation depends entirely on the teaching and practice given at school","Learning can fully replace maturation if practice is intense enough","Maturation gives readiness, and experience and practice build on it"],"answer":3,"explanation":"Maturation is growth that unfolds largely from within; it provides readiness, and learning through experience builds skills on that base. Drill before readiness yields little.","difficulty":"moderate","source":"CTET · REET","questionHi":"अधिगम और परिपक्वता के संबंध के बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["अधिगम और परिपक्वता दो कोणों से देखी गई एक ही प्रक्रिया हैं","परिपक्वता पूरी तरह विद्यालय में दिए गए शिक्षण और अभ्यास पर निर्भर करती है","अभ्यास यदि पर्याप्त तीव्र हो तो अधिगम परिपक्वता का पूर्णतः स्थान ले सकता है","परिपक्वता तत्परता देती है, और अनुभव तथा अभ्यास उस पर निर्माण करते हैं"],"explanationHi":"परिपक्वता वह वृद्धि है जो मुख्यतः भीतर से प्रकट होती है; वह तत्परता देती है, और अनुभव द्वारा अधिगम उस आधार पर कौशल बनाता है। तत्परता से पहले अभ्यास कम फल देता है।"},
  {"id":"cdp-child-development-1442","question":"A teacher notices that Class 6 children recall a science concept much better after they have explained it to younger children in Class 3. The most likely reason is that:","options":["Teaching makes them organise, elaborate and retrieve what they know","Younger children correct the older ones' facts, so errors are removed","Explaining to others works through classical conditioning of the facts","Teaching reduces the amount of material that has to be learnt"],"answer":0,"explanation":"Preparing to teach and explaining involve retrieval, organisation and elaboration, strengthening the tutor's own learning (sometimes called the protégé or learning-by-teaching effect).","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षक देखता है कि कक्षा 6 के बच्चे किसी विज्ञान अवधारणा को कक्षा 3 के छोटे बच्चों को समझाने के बाद उसे कहीं बेहतर याद रखते हैं। सबसे संभावित कारण यह है कि:","optionsHi":["पढ़ाने से वे जो जानते हैं उसे व्यवस्थित, विस्तृत और पुनः प्राप्त करते हैं","छोटे बच्चे बड़ों के तथ्य सुधारते हैं, इसलिए त्रुटियाँ दूर हो जाती हैं","दूसरों को समझाना तथ्यों के शास्त्रीय अनुबंधन से काम करता है","पढ़ाने से सीखी जाने वाली सामग्री की मात्रा घट जाती है"],"explanationHi":"पढ़ाने की तैयारी और समझाने में पुनर्प्राप्ति, संगठन और विस्तार शामिल होते हैं, जो पढ़ाने वाले के अपने अधिगम को सुदृढ़ करते हैं (जिसे कभी-कभी प्रोटेजे या सिखाकर सीखने का प्रभाव कहते हैं)।"},
  {"id":"cdp-child-development-1443","question":"A Class 5 teacher finds that children grasp the idea of ‘perimeter’ much better when they walk around the school garden with a measuring tape than when they read its definition. Which combination of factors best explains this?","options":["Concrete experience suited to their stage, plus active involvement","Negative reinforcement, since children walk to avoid reading the definition","The law of disuse, since reading definitions is quickly forgotten","Only the novelty of going outside, with no real benefit to learning"],"answer":0,"explanation":"Children in the concrete operational stage learn best from concrete, hands-on experience; active participation also aids attention and memory.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 5 की एक शिक्षिका पाती है कि बच्चे ‘परिमाप’ की अवधारणा को परिभाषा पढ़ने की तुलना में माप-फीता लेकर विद्यालय के बगीचे का चक्कर लगाने पर कहीं बेहतर समझते हैं। कारकों का कौन-सा संयोजन इसे सबसे अच्छी तरह समझाता है?","optionsHi":["उनकी अवस्था के अनुकूल मूर्त अनुभव, तथा सक्रिय संलग्नता","नकारात्मक पुनर्बलन, क्योंकि बच्चे परिभाषा पढ़ने से बचने के लिए चलते हैं","अनुपयोग का नियम, क्योंकि परिभाषाएँ पढ़ना जल्दी भुला दिया जाता है","केवल बाहर जाने की नवीनता, अधिगम के लिए कोई वास्तविक लाभ नहीं"],"explanationHi":"मूर्त संक्रियात्मक अवस्था के बच्चे मूर्त, प्रत्यक्ष अनुभव से सबसे अच्छा सीखते हैं; सक्रिय भागीदारी ध्यान और स्मृति में भी सहायक है।"},
  {"id":"cdp-child-development-1444","question":"Which of these teacher actions is most consistent with what we know about how children learn, across theories?","options":["Covering the syllabus at one uniform pace for everyone and testing only memory","Avoiding feedback so that children discover all their own errors unaided","Using prior knowledge, active tasks, timely feedback and effort-based praise","Rewarding only the top three in every test to set a standard for others"],"answer":2,"explanation":"Prior knowledge (constructivism, Ausubel), active engagement, feedback (behaviourist and cognitive views) and effort attributions (Weiner, Dweck) are all well supported; the other options contradict them.","difficulty":"moderate","source":"CTET · HTET","questionHi":"इनमें से कौन-सी शिक्षक-क्रिया, सभी सिद्धांतों में, बच्चे कैसे सीखते हैं इस बारे में हमारी जानकारी के सबसे अनुरूप है?","optionsHi":["सबके लिए एक समान गति से पाठ्यक्रम पूरा करना और केवल स्मृति की जाँच करना","प्रतिक्रिया से बचना ताकि बच्चे अपनी सारी त्रुटियाँ बिना सहायता के खोजें","पूर्व ज्ञान, सक्रिय कार्य, समयबद्ध प्रतिक्रिया और प्रयास-आधारित प्रशंसा का उपयोग","हर परीक्षा में केवल शीर्ष तीन को पुरस्कृत करना ताकि दूसरों के लिए मानक बने"],"explanationHi":"पूर्व ज्ञान (रचनावाद, ऑसुबेल), सक्रिय संलग्नता, प्रतिक्रिया (व्यवहारवादी और संज्ञानात्मक दृष्टिकोण) और प्रयास-कारणारोपण (वीनर, ड्वेक) सभी भली-भाँति समर्थित हैं; अन्य विकल्प इनका खंडन करते हैं।"},
  {"id":"cdp-child-development-1445","question":"Match each teacher’s remark with the theorist it reflects most closely. P. ‘Before teaching, I find out what each child can do with a little help.’ Q. ‘I would rather let him puzzle over why his prediction failed than give him the answer.’ R. ‘I plan to come back to this topic next year at a deeper level.’ 1. Bruner 2. Piaget 3. Vygotsky","options":["P-2, Q-3, R-1","P-3, Q-1, R-2","P-1, Q-2, R-3","P-3, Q-2, R-1"],"answer":3,"explanation":"Assessing assisted performance points to Vygotsky’s ZPD, using a failed prediction to create disequilibrium is Piagetian, and returning to a topic at greater depth is Bruner’s spiral curriculum.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"प्रत्येक शिक्षक की टिप्पणी का उस सिद्धांतकार से मिलान कीजिए जिसे वह सबसे निकट से दर्शाती है। P. ‘पढ़ाने से पहले, मैं पता करता हूँ कि प्रत्येक बच्चा थोड़ी सहायता से क्या कर सकता है।’ Q. ‘मैं उसे उत्तर देने के बजाय यह सोचने दूँगा कि उसका अनुमान क्यों विफल हुआ।’ R. ‘मैं अगले वर्ष इस विषय पर अधिक गहराई से लौटने की योजना बनाता हूँ।’ 1. ब्रूनर 2. पियाजे 3. वाइगोत्स्की","optionsHi":["P-2, Q-3, R-1","P-3, Q-1, R-2","P-1, Q-2, R-3","P-3, Q-2, R-1"],"explanationHi":"सहायता-प्राप्त प्रदर्शन का आकलन वाइगोत्स्की के ZPD की ओर संकेत करता है, असफल अनुमान का उपयोग असंतुलन बनाने के लिए करना पियाजे के अनुरूप है, और किसी विषय पर अधिक गहराई से लौटना ब्रूनर की सर्पिल पाठ्यचर्या है।"},
  {"id":"cdp-child-development-1446","question":"According to Piaget, what mainly motivates a child to move to more advanced ways of thinking?","options":["Rewards and praise from the teacher for each new correct answer given","Fear of punishment for wrong answers, both in class and at home","Competition with classmates to be the first to understand the idea","The need to resolve imbalance when experience does not fit schemas"],"answer":3,"explanation":"For Piaget, disequilibrium is uncomfortable and the drive to restore balance, through accommodation, is intrinsic. External rewards play little part in his theory.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"पियाजे के अनुसार, बच्चे को चिंतन के अधिक उन्नत तरीकों की ओर बढ़ने के लिए मुख्यतः क्या प्रेरित करता है?","optionsHi":["हर नए सही उत्तर के लिए शिक्षक से पुरस्कार और प्रशंसा","गलत उत्तरों पर दंड का भय, कक्षा और घर दोनों में","विचार को सबसे पहले समझने के लिए सहपाठियों से प्रतिस्पर्धा","असंतुलन को सुलझाने की आवश्यकता जब अनुभव स्कीमाओं में फिट नहीं बैठता"],"explanationHi":"पियाजे के लिए असंतुलन असुविधाजनक है और संतुलन बहाल करने की प्रेरणा, समायोजन के माध्यम से, आंतरिक है। उनके सिद्धांत में बाह्य पुरस्कारों की बहुत कम भूमिका है।"},
  {"id":"cdp-child-development-1447","question":"A Class 6 student is sure that 0.5 × 4 must be more than 4, ‘because multiplying always makes a number bigger’. In Piaget’s terms, this error arises because the student is:","options":["Assimilating decimals into a whole-number multiplication schema","Accommodating correctly to decimals by changing his schema","Showing pre-operational animism about how numbers behave","Using formal operational proportional reasoning about size"],"answer":0,"explanation":"The rule ‘multiplication makes bigger’ holds for whole numbers greater than 1, and the student is fitting decimals into that schema without changing it. The teacher’s task is to create conditions for accommodation.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 6 का एक विद्यार्थी निश्चित है कि 0.5 × 4, 4 से अधिक होना चाहिए, ‘क्योंकि गुणा करने से संख्या हमेशा बड़ी होती है’। पियाजे की शब्दावली में, यह त्रुटि इसलिए उत्पन्न होती है क्योंकि विद्यार्थी:","optionsHi":["दशमलवों को पूर्ण-संख्या गुणन की स्कीमा में आत्मसात कर रहा है","अपनी स्कीमा बदलकर दशमलवों के प्रति सही ढंग से समायोजन कर रहा है","संख्याएँ कैसे व्यवहार करती हैं इस बारे में पूर्व-संक्रियात्मक जीववाद दिखा रहा है","आकार के बारे में औपचारिक संक्रियात्मक आनुपातिक तर्कण का उपयोग कर रहा है"],"explanationHi":"‘गुणा से बड़ा होता है’ का नियम 1 से बड़ी पूर्ण संख्याओं के लिए सही है, और विद्यार्थी दशमलवों को उसे बदले बिना उसी स्कीमा में बैठा रहा है। शिक्षक का कार्य समायोजन के लिए परिस्थितियाँ बनाना है।"},
  {"id":"cdp-child-development-1448","question":"A Class 5 child says 0.25 is greater than 0.3 ‘because 25 is bigger than 3’. Which teacher response best combines Piaget’s and Vygotsky’s ideas?","options":["Mark it wrong and give ten similar sums for homework to correct the habit","Tell the child to memorise the rule that ‘more digits does not mean bigger’","Have her shade both on hundred-squares and guide her with questions","Move the child to a lower-level group permanently for decimals"],"answer":2,"explanation":"Shading creates a concrete conflict with her rule (Piaget), while guiding questions help her reason it through (Vygotsky). Drill or memorised rules leave the faulty schema in place.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 5 की एक बच्ची कहती है कि 0.25, 0.3 से बड़ा है ‘क्योंकि 25, 3 से बड़ा है’। कौन-सी शिक्षक-प्रतिक्रिया पियाजे और वाइगोत्स्की के विचारों को सबसे अच्छी तरह जोड़ती है?","optionsHi":["इसे गलत अंकित करना और आदत सुधारने के लिए गृहकार्य में दस समान योग देना","बच्ची से यह नियम रटने को कहना कि ‘अधिक अंकों का अर्थ बड़ा होना नहीं है’","उससे दोनों को सौ-वर्गों पर छायांकित करवाना और प्रश्नों से उसका मार्गदर्शन करना","बच्ची को दशमलवों के लिए स्थायी रूप से निचले स्तर वाले समूह में भेजना"],"explanationHi":"छायांकन उसके नियम से ठोस विरोध उत्पन्न करता है (पियाजे), जबकि मार्गदर्शक प्रश्न उसे तर्क से सुलझाने में सहायता करते हैं (वाइगोत्स्की)। अभ्यास या रटे नियम दोषपूर्ण स्कीमा को वहीं छोड़ देते हैं।"},
  {"id":"cdp-child-development-1449","question":"To teach the triangle, a Class 2 teacher has children walk along a large triangle chalked on the playground, then draw triangles in their notebooks, and finally name the sides and corners. Her plan follows most closely:","options":["Skinner’s programmed learning in small, rewarded steps","Bruner’s enactive, iconic and symbolic sequence","Kohlberg’s stages of moral development","Pavlov’s classical conditioning of shapes"],"answer":1,"explanation":"Walking the shape is enactive, drawing it is iconic and naming its properties is symbolic. This is Bruner’s recommended sequence for new ideas.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"त्रिभुज सिखाने के लिए कक्षा 2 की शिक्षिका बच्चों को खेल के मैदान में चॉक से बने बड़े त्रिभुज के किनारे चलवाती है, फिर अपनी कॉपियों में त्रिभुज बनवाती है, और अंत में भुजाओं और कोनों के नाम बुलवाती है। उसकी योजना सबसे निकट से किसका अनुसरण करती है?","optionsHi":["स्किनर का छोटे, पुरस्कृत चरणों में अभिक्रमित अधिगम","ब्रूनर का क्रियात्मक, आइकॉनिक और प्रतीकात्मक क्रम","कोहलबर्ग की नैतिक विकास की अवस्थाएँ","पावलोव का आकृतियों का शास्त्रीय अनुबंधन"],"explanationHi":"आकृति के किनारे चलना क्रियात्मक है, उसे बनाना आइकॉनिक है और उसके गुणों के नाम बताना प्रतीकात्मक। यह नए विचारों के लिए ब्रूनर का अनुशंसित क्रम है।"},
  {"id":"cdp-child-development-1450","question":"Consider these statements about Piaget’s view of intelligence. 1. Intelligence is a form of adaptation to the environment. 2. The functions of organisation and adaptation remain the same throughout life. 3. The cognitive structures (schemas and operations) change from stage to stage. Which is/are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Piaget distinguished invariant functions (organisation, adaptation) from structures that change across stages. He saw intelligence itself as biological adaptation extended to thought.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"पियाजे के बुद्धि के दृष्टिकोण के बारे में इन कथनों पर विचार कीजिए। 1. बुद्धि पर्यावरण के प्रति अनुकूलन का एक रूप है। 2. संगठन और अनुकूलन के प्रकार्य जीवन भर समान रहते हैं। 3. संज्ञानात्मक संरचनाएँ (स्कीमाएँ और संक्रियाएँ) एक अवस्था से दूसरी में बदलती हैं। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"पियाजे ने अपरिवर्ती प्रकार्यों (संगठन, अनुकूलन) को उन संरचनाओं से अलग किया जो अवस्थाओं में बदलती हैं। वे बुद्धि को स्वयं चिंतन तक विस्तारित जैविक अनुकूलन मानते थे।"},
  {"id":"cdp-child-development-1451","question":"Planning an experiment on how fast sugar dissolves, a Class 8 student says, ‘If I change the temperature and the stirring at the same time, I won’t know which one made the difference.’ This shows the formal operational ability to:","options":["Isolate variables by changing one factor at a time","Conserve number when objects are spread out in a row","Classify objects by one attribute at a time","Use symbolic play to stand for real events"],"answer":0,"explanation":"Recognising that only one variable should be changed at a time is the scheme of isolating variables that Piaget and Inhelder linked to formal operations.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"चीनी के घुलने की गति पर प्रयोग की योजना बनाते हुए, कक्षा 8 का एक विद्यार्थी कहता है, ‘यदि मैं तापमान और हिलाना एक साथ बदलूँगा, तो मुझे पता नहीं चलेगा कि किससे अंतर आया।’ यह किस औपचारिक संक्रियात्मक क्षमता को दर्शाता है?","optionsHi":["एक बार में एक कारक बदलकर चरों को अलग करना","वस्तुओं को पंक्ति में फैलाने पर संख्या का संरक्षण करना","एक बार में एक गुण से वस्तुओं का वर्गीकरण करना","वास्तविक घटनाओं के प्रतिनिधि के लिए प्रतीकात्मक खेल का उपयोग करना"],"explanationHi":"यह पहचानना कि एक बार में केवल एक चर बदला जाना चाहिए, चरों को अलग करने की वह स्कीमा है जिसे पियाजे और इनहेल्डर ने औपचारिक संक्रियाओं से जोड़ा।"},
  {"id":"cdp-child-development-1452","question":"Studies using the ‘violation of expectation’ method found that infants of about four months look longer when a screen seems to pass through a hidden box, as if surprised. These findings are mostly used to argue that:","options":["Piaget overestimated infants’ abilities, since they are so easily surprised","Object permanence appears only after two years, as Piaget later admitted","Infants may grasp hidden objects earlier than Piaget’s search tasks implied","Infants are already in the formal operational stage by four months"],"answer":2,"explanation":"Piaget relied on manual search, which needs motor skills infants lack. Looking-time studies, such as Baillargeon’s, suggest some knowledge of hidden objects earlier, so Piaget may have underestimated infants.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"‘अपेक्षा-उल्लंघन’ विधि वाले अध्ययनों में पाया गया कि लगभग चार माह के शिशु तब अधिक देर तक देखते हैं जब कोई पर्दा छिपे डिब्बे के आर-पार जाता प्रतीत होता है, मानो आश्चर्यचकित हों। इन निष्कर्षों का उपयोग मुख्यतः यह तर्क देने के लिए किया जाता है कि:","optionsHi":["पियाजे ने शिशुओं की योग्यताओं को बढ़ा-चढ़ाकर आँका, क्योंकि वे इतनी आसानी से चकित हो जाते हैं","वस्तु-स्थायित्व केवल दो वर्ष के बाद प्रकट होता है, जैसा पियाजे ने बाद में स्वीकार किया","शिशु छिपी हुई वस्तुओं को पियाजे के खोज-कार्यों से सुझाए गए समय से पहले समझ सकते हैं","शिशु चार माह तक पहले से औपचारिक संक्रियात्मक अवस्था में हैं"],"explanationHi":"पियाजे हाथ से खोज पर निर्भर थे, जिसके लिए गामक कौशल चाहिए जो शिशुओं में नहीं होते। बैलार्जन जैसे देखने-के-समय वाले अध्ययन छिपी वस्तुओं के कुछ ज्ञान को पहले से सुझाते हैं, इसलिए पियाजे ने शिशुओं को कम आँका हो सकता है।"},
  {"id":"cdp-child-development-1453","question":"Which statement correctly distinguishes the ZPD from scaffolding?","options":["They are two names for exactly the same idea in Vygotsky’s writing","Scaffolding is the range of tasks a child can do alone; the ZPD is the help given","The ZPD is a Piagetian idea, scaffolding a Brunerian one, and they are unrelated","ZPD: tasks a learner can do only with help; scaffolding: support given there"],"answer":3,"explanation":"The ZPD describes where learning can happen; scaffolding describes how support is given there and gradually withdrawn. The two are linked but not identical.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कौन-सा कथन ZPD को पाड़ से सही अलग करता है?","optionsHi":["वाइगोत्स्की के लेखन में ये बिल्कुल एक ही विचार के दो नाम हैं","पाड़ उन कार्यों की परास है जो बच्चा अकेले कर सकता है; ZPD दी गई सहायता है","ZPD पियाजे का विचार है, पाड़ ब्रूनर का, और वे असंबद्ध हैं","ZPD: वे कार्य जो अधिगमकर्ता केवल सहायता से कर सकता है; पाड़: वहाँ दी गई सहायता"],"explanationHi":"ZPD वर्णन करता है कि अधिगम कहाँ हो सकता है; पाड़ वर्णन करता है कि वहाँ सहायता कैसे दी और धीरे-धीरे हटाई जाती है। दोनों जुड़े हैं पर समान नहीं।"},
  {"id":"cdp-child-development-1454","question":"Assertion (A): Piaget recommended that children be given many opportunities to handle and act on real objects. Reason (R): For Piaget, knowledge is constructed through the child’s own actions on the environment, which are gradually internalised as mental operations.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Piaget saw operations as internalised actions, so acting on objects is the raw material of thought. R therefore explains why he recommended it.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"अभिकथन (A): पियाजे ने अनुशंसा की कि बच्चों को वास्तविक वस्तुओं को हाथ में लेने और उन पर क्रिया करने के अनेक अवसर दिए जाएँ। कारण (R): पियाजे के लिए, ज्ञान पर्यावरण पर बच्चे की अपनी क्रियाओं से निर्मित होता है, जो धीरे-धीरे मानसिक संक्रियाओं के रूप में आत्मसात हो जाती हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"पियाजे संक्रियाओं को आंतरिक हुई क्रियाएँ मानते थे, इसलिए वस्तुओं पर क्रिया करना चिंतन का कच्चा माल है। इसलिए R समझाता है कि उन्होंने इसकी अनुशंसा क्यों की।"},
  {"id":"cdp-child-development-1455","question":"A three-year-old chooses a toy car as a birthday present for his grandmother, explaining, ‘She will like it because I like cars.’ Piaget would see this as an example of:","options":["Egocentrism: assuming others share his own preferences","Selfishness, which should be corrected through moral lessons","Conservation of identity, as the car stays the same","Transductive reasoning about time and birthdays"],"answer":0,"explanation":"Pre-operational egocentrism is a cognitive limitation in taking another’s perspective, not a moral fault. He genuinely believes the gift will please her.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"तीन वर्ष का एक बच्चा अपनी दादी के लिए जन्मदिन के उपहार के रूप में खिलौना कार चुनता है, यह समझाते हुए, ‘उन्हें यह पसंद आएगी क्योंकि मुझे कारें पसंद हैं।’ पियाजे इसे किसका उदाहरण मानेंगे?","optionsHi":["अहंकेंद्रिता: यह मान लेना कि दूसरों की भी वही पसंद है जो उसकी अपनी है","स्वार्थ, जिसे नैतिक पाठों से सुधारना चाहिए","तादात्म्य का संरक्षण, क्योंकि कार वही रहती है","समय और जन्मदिनों के बारे में पारगमनात्मक तर्क (Transductive reasoning)"],"explanationHi":"पूर्व-संक्रियात्मक अहंकेंद्रिता दूसरे का दृष्टिकोण लेने में एक संज्ञानात्मक सीमा है, नैतिक दोष नहीं। वह सचमुच विश्वास करता है कि उपहार उन्हें प्रसन्न करेगा।"},
  {"id":"cdp-child-development-1456","question":"In interviewing children, Piaget did not use a fixed list of questions; he followed each child’s answers with new questions tailored to what the child had said. A recognised strength and weakness of this clinical method are respectively:","options":["It is fully standardised; but it reveals nothing about children’s reasoning","It uses large random samples; it ignores the reasoning behind answers","It reveals reasoning behind answers; results may depend on the interviewer","It eliminates the influence of language; it takes too little time"],"answer":2,"explanation":"Flexible probing uncovers how children think, which fixed tests miss. The cost is reduced standardisation, so different interviewers may obtain different responses.","difficulty":"hard","source":"CTET · DSSSB · State TETs","questionHi":"बच्चों का साक्षात्कार लेते समय, पियाजे ने प्रश्नों की निश्चित सूची का उपयोग नहीं किया; उन्होंने प्रत्येक बच्चे के उत्तरों के अनुसार नए प्रश्न पूछे, जो बच्चे के कहे के अनुरूप थे। इस नैदानिक विधि की मान्यता-प्राप्त शक्ति और दुर्बलता क्रमशः हैं:","optionsHi":["यह पूर्णतः मानकीकृत है; पर यह बच्चों के तर्क के बारे में कुछ प्रकट नहीं करती","यह बड़े यादृच्छिक प्रतिदर्शों का उपयोग करती है; यह उत्तरों के पीछे के तर्क की उपेक्षा करती है","यह उत्तरों के पीछे के तर्क को प्रकट करती है; परिणाम साक्षात्कारकर्ता पर निर्भर हो सकते हैं","यह भाषा के प्रभाव को समाप्त करती है; इसमें बहुत कम समय लगता है"],"explanationHi":"लचीली पूछताछ यह उजागर करती है कि बच्चे कैसे सोचते हैं, जिसे निश्चित परीक्षण चूक जाते हैं। कीमत घटा हुआ मानकीकरण है, इसलिए भिन्न साक्षात्कारकर्ता भिन्न प्रतिक्रियाएँ पा सकते हैं।"},
  {"id":"cdp-child-development-1457","question":"Asked to put shapes ‘that go together’ into groups, a four-year-old puts a red square next to a red circle, then a blue circle next to the red circle, then a blue triangle next to the blue circle, changing her basis as she goes. Piaget would say this shows:","options":["Mature multiple classification, using colour and shape together","Seriation, arranging the shapes in a graded order of size","Pre-operational difficulty keeping one criterion while sorting","Formal operational combinatorial thinking about all pairings"],"answer":2,"explanation":"Young children often make ‘chains’ in which each item links to the last by a different feature. Using one consistent criterion develops later, in the concrete operational stage.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"‘जो साथ जाते हैं’ आकृतियों को समूहों में रखने को कहने पर, चार वर्ष की बच्ची एक लाल वर्ग को एक लाल वृत्त के पास रखती है, फिर एक नीला वृत्त लाल वृत्त के पास, फिर एक नीला त्रिभुज नीले वृत्त के पास, चलते-चलते अपना आधार बदलती हुई। पियाजे कहेंगे कि यह दर्शाता है:","optionsHi":["परिपक्व बहु-वर्गीकरण, रंग और आकृति को साथ-साथ उपयोग करते हुए","क्रमबद्धता, आकृतियों को आकार के श्रेणीबद्ध क्रम में रखना","छाँटते समय एक मानदंड बनाए रखने में पूर्व-संक्रियात्मक कठिनाई","सभी जोड़ियों के बारे में औपचारिक संक्रियात्मक संचयात्मक चिंतन"],"explanationHi":"छोटे बच्चे प्रायः ‘शृंखलाएँ’ बनाते हैं जिनमें प्रत्येक मद पिछली से भिन्न विशेषता से जुड़ती है। एक सुसंगत मानदंड का प्रयोग बाद में, मूर्त संक्रियात्मक अवस्था में, विकसित होता है।"},
  {"id":"cdp-child-development-1458","question":"A teacher shows that stick A is longer than stick B, then that stick B is longer than stick C, and then hides stick A. Asked which is longer, A or C, a five-year-old says, ‘I don’t know, I haven’t seen them together,’ while an eight-year-old says, ‘A, of course.’ The older child is using:","options":["Animism, treating the hidden stick as if it were alive","Transitive inference, a concrete operational ability","Hypothetical reasoning about imaginary sticks","Iconic representation only, from a mental picture"],"answer":1,"explanation":"Inferring A > C from A > B and B > C is transitivity, which develops with concrete operations. The younger child relies on direct perception and cannot combine the relations.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"एक शिक्षक दिखाता है कि छड़ी A छड़ी B से लंबी है, फिर कि छड़ी B छड़ी C से लंबी है, और फिर छड़ी A को छिपा देता है। पूछने पर कि A या C में कौन लंबी है, पाँच वर्ष का बच्चा कहता है, ‘मुझे नहीं पता, मैंने उन्हें साथ नहीं देखा,’ जबकि आठ वर्ष का बच्चा कहता है, ‘A, बिल्कुल।’ बड़ा बच्चा उपयोग कर रहा है:","optionsHi":["जीववाद, छिपी छड़ी को ऐसे मानते हुए मानो वह सजीव हो","संक्रमणीय अनुमान, एक मूर्त संक्रियात्मक क्षमता","काल्पनिक छड़ियों के बारे में परिकल्पनात्मक तर्कण","केवल आइकॉनिक निरूपण, मानसिक चित्र से"],"explanationHi":"A > B और B > C से A > C का अनुमान लगाना संक्रमणीयता है, जो मूर्त संक्रियाओं के साथ विकसित होती है। छोटा बच्चा प्रत्यक्ष प्रत्यक्षण पर निर्भर रहता है और संबंधों को जोड़ नहीं सकता।"},
  {"id":"cdp-child-development-1459","question":"How many of these classroom practices are consistent with Piaget’s theory? I. Setting problems slightly beyond children’s present understanding. II. Encouraging children to explain their reasoning to one another. III. Expecting all Class 3 children to master proportional reasoning. IV. Using children’s wrong answers to understand their thinking.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV fit Piaget’s ideas of moderate challenge, peer conflict and errors as clues. Proportional reasoning is formal operational, so expecting it in Class 3 contradicts the theory.","difficulty":"hard","source":"CTET · DSSSB · State TETs","questionHi":"इनमें से कितने कक्षा-अभ्यास पियाजे के सिद्धांत के अनुरूप हैं? I. बच्चों की वर्तमान समझ से थोड़ा आगे की समस्याएँ रखना। II. बच्चों को एक-दूसरे को अपना तर्क समझाने के लिए प्रोत्साहित करना। III. कक्षा 3 के सभी बच्चों से आनुपातिक तर्कण में निपुण होने की अपेक्षा करना। IV. बच्चों के गलत उत्तरों का उपयोग उनकी सोच समझने के लिए करना।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"I, II और IV पियाजे के मध्यम चुनौती, साथियों के बीच टकराव और त्रुटियों को सुराग मानने के विचारों से मेल खाते हैं। आनुपातिक तर्कण औपचारिक संक्रियात्मक है, इसलिए कक्षा 3 में उसकी अपेक्षा सिद्धांत का खंडन करती है।"},
  {"id":"cdp-child-development-1460","question":"A Class 1 child, watching the teacher pour juice from a short glass into a tall one, is asked a question that requires conservation. Which of these questions is the actual conservation question?","options":["‘Which of the two glasses is taller, the first or the second?’","‘What colour is the juice, and does it look different now?’","‘Can you pour the juice back into the short glass again?’","‘Is there more juice now, less, or the same amount as before?’"],"answer":3,"explanation":"Conservation is about whether the quantity is understood to stay the same despite a change in appearance. The other questions concern perception or action, not quantity.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 1 का एक बच्चा, शिक्षक को रस छोटे गिलास से लंबे गिलास में उँडेलते देखते हुए, संरक्षण माँगने वाला प्रश्न पूछा जाता है। इनमें से कौन-सा प्रश्न वास्तविक संरक्षण प्रश्न है?","optionsHi":["‘दोनों गिलासों में कौन-सा लंबा है, पहला या दूसरा?’","‘रस का रंग क्या है, और क्या वह अब भिन्न दिखता है?’","‘क्या तुम रस को फिर से छोटे गिलास में उँडेल सकते हो?’","‘क्या अब रस अधिक है, कम है, या पहले जितना ही है?’"],"explanationHi":"संरक्षण इस बारे में है कि रूप बदलने पर भी मात्रा को समान समझा जाता है या नहीं। अन्य प्रश्न प्रत्यक्षण या क्रिया से संबंधित हैं, मात्रा से नहीं।"},
  {"id":"cdp-child-development-1461","question":"A Class 4 child who usually uses Hindi at home learns English words for colours by matching coloured cards with the teacher and saying the words aloud together; later she labels colours in English on her own. Which statement best explains her learning from a Vygotskian view?","options":["She learnt through shared activity before using the words on her own","She learnt only through physical maturation of her speech organs","She learnt the words because she was corrected and punished for mistakes","Her Hindi interfered with learning, so the home language should be banned"],"answer":0,"explanation":"Learning moves from joint activity with a more knowledgeable other to independent use, which is internalisation. The home language is a resource, not a barrier.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 4 की एक बच्ची, जो प्रायः घर पर हिंदी बोलती है, शिक्षिका के साथ रंगीन कार्ड मिलाकर और शब्दों को साथ-साथ ज़ोर से बोलकर रंगों के अंग्रेज़ी शब्द सीखती है; बाद में वह स्वयं अंग्रेज़ी में रंगों के नाम बताती है। वाइगोत्स्की के दृष्टिकोण से कौन-सा कथन उसके अधिगम को सबसे अच्छी तरह समझाता है?","optionsHi":["उसने शब्दों को स्वयं प्रयोग करने से पहले साझा गतिविधि द्वारा सीखा","उसने केवल अपने वाक्-अंगों की शारीरिक परिपक्वता से सीखा","उसने शब्द इसलिए सीखे क्योंकि गलतियों पर उसे सुधारा और दंडित किया गया","उसकी हिंदी ने सीखने में व्यतिकरण किया, इसलिए घर की भाषा पर रोक लगनी चाहिए"],"explanationHi":"अधिगम अधिक जानकार अन्य के साथ संयुक्त गतिविधि से स्वतंत्र उपयोग की ओर बढ़ता है, जो आंतरिकीकरण है। घर की भाषा संसाधन है, बाधा नहीं।"},
  {"id":"cdp-child-development-1462","question":"Which of the following findings challenges Piaget’s claim that young children cannot take another person’s point of view?","options":["Four-year-olds talk more simply to two-year-olds than to adults","Six-year-olds often fail conservation of liquid in the glass task","Infants show the A-not-B error when searching for toys","Adolescents show the imaginary audience in their worries"],"answer":0,"explanation":"Adjusting speech to a younger listener shows that four-year-olds can consider another’s perspective in familiar situations. The other findings are consistent with Piaget.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"निम्नलिखित में से कौन-सा निष्कर्ष पियाजे के इस दावे को चुनौती देता है कि छोटे बच्चे दूसरे व्यक्ति का दृष्टिकोण नहीं ले सकते?","optionsHi":["चार वर्ष के बच्चे वयस्कों की तुलना में दो वर्ष के बच्चों से अधिक सरलता से बात करते हैं","छह वर्ष के बच्चे प्रायः गिलास वाले कार्य में द्रव के संरक्षण में असफल होते हैं","शिशु खिलौने ढूँढ़ते समय A-नॉट-B त्रुटि दिखाते हैं","किशोर अपनी चिंताओं में काल्पनिक दर्शक दिखाते हैं"],"explanationHi":"छोटे श्रोता के अनुसार भाषण को समायोजित करना दिखाता है कि चार वर्ष के बच्चे परिचित परिस्थितियों में दूसरे के दृष्टिकोण पर विचार कर सकते हैं। अन्य निष्कर्ष पियाजे के अनुरूप हैं।"},
  {"id":"cdp-child-development-1463","question":"Assertion (A): Vygotsky would see a child’s inability to solve a problem alone as incomplete information about her development. Reason (R): Vygotsky held that development is determined only by heredity, so testing is pointless.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Vygotsky argued that we must also see what the child can do with help, so A is true. R is false: he stressed social and cultural influences, not heredity alone.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"अभिकथन (A): वाइगोत्स्की किसी बच्ची की अकेले समस्या हल न कर पाने की स्थिति को उसके विकास की अधूरी जानकारी मानेंगे। कारण (R): वाइगोत्स्की का मत था कि विकास केवल आनुवंशिकता से निर्धारित होता है, इसलिए परीक्षण निरर्थक है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"वाइगोत्स्की ने तर्क दिया कि हमें यह भी देखना चाहिए कि बच्चा सहायता से क्या कर सकता है, इसलिए A सत्य है। R असत्य है: उन्होंने केवल आनुवंशिकता पर नहीं, सामाजिक और सांस्कृतिक प्रभावों पर बल दिया।"},
  {"id":"cdp-child-development-1464","question":"A teacher sets up a ‘shop’ corner in Class 2 where children buy and sell with toy money, while she plays a customer who asks for change and talks through the calculation with them. Which pair of theorists would BOTH value this activity, and for which reasons?","options":["Piaget, for concrete activity; Vygotsky, for guided talk with a skilled adult","Skinner, for reinforcing correct change; Pavlov, for conditioning money to rewards","Piaget, for formal reasoning; Bruner, for using only the symbolic mode with money","Erikson, for building identity; Kohlberg, for moral reasoning about fair trade"],"answer":0,"explanation":"Handling money and goods gives concrete experience valued by Piaget, while the teacher’s participation provides scaffolding valued by Vygotsky. The other pairs do not fit the reasons given.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 2 में एक शिक्षिका ‘दुकान’ का कोना बनाती है जहाँ बच्चे खिलौना मुद्रा से खरीदते-बेचते हैं, जबकि वह स्वयं एक ग्राहक बनती है जो छुट्टे पैसे माँगती है और उनके साथ गणना पर बातचीत करती है। सिद्धांतकारों का कौन-सा जोड़ा इस गतिविधि को दोनों महत्त्व देगा, और किन कारणों से?","optionsHi":["पियाजे, मूर्त गतिविधि के लिए; वाइगोत्स्की, कुशल वयस्क के साथ निर्देशित बातचीत के लिए","स्किनर, सही छुट्टे के पुनर्बलन के लिए; पावलोव, मुद्रा को पुरस्कारों से अनुबंधित करने के लिए","पियाजे, औपचारिक तर्कण के लिए; ब्रूनर, मुद्रा के साथ केवल प्रतीकात्मक विधा के उपयोग के लिए","एरिक्सन, पहचान निर्माण के लिए; कोहलबर्ग, निष्पक्ष व्यापार पर नैतिक तर्कण के लिए"],"explanationHi":"मुद्रा और वस्तुओं को सँभालना मूर्त अनुभव देता है जिसे पियाजे महत्त्व देते हैं, जबकि शिक्षिका की भागीदारी पाड़ देती है जिसे वाइगोत्स्की महत्त्व देते हैं। अन्य जोड़े दिए गए कारणों से मेल नहीं खाते।"},
  {"id":"cdp-child-development-1465","question":"A Class 9 teacher notices that her students handle algebra well but struggle to argue a position on whether a law is fair. Piaget’s theory would suggest that:","options":["Students are still pre-operational in social science and need concrete props","Formal thinking may be used unevenly across subjects, depending on experience","Formal operations always appear in social science first, so something is wrong","Students should stop studying algebra until their social reasoning catches up"],"answer":1,"explanation":"Formal reasoning is often domain-specific and depends on familiarity, a point Piaget accepted in his later work. Unevenness does not mean a return to an earlier stage.","difficulty":"hard","source":"CTET · DSSSB · State TETs","questionHi":"कक्षा 9 की एक शिक्षिका देखती है कि उसके विद्यार्थी बीजगणित अच्छी तरह सँभाल लेते हैं पर यह तर्क देने में संघर्ष करते हैं कि कोई कानून निष्पक्ष है या नहीं। पियाजे का सिद्धांत क्या सुझाएगा?","optionsHi":["विद्यार्थी सामाजिक विज्ञान में अब भी पूर्व-संक्रियात्मक हैं और उन्हें मूर्त साधन चाहिए","औपचारिक चिंतन अनुभव के आधार पर विषयों में असमान रूप से प्रयुक्त हो सकता है","औपचारिक संक्रियाएँ सदैव सामाजिक विज्ञान में पहले प्रकट होती हैं, इसलिए कुछ गड़बड़ है","विद्यार्थियों को बीजगणित पढ़ना तब तक बंद कर देना चाहिए जब तक उनका सामाजिक तर्कण बराबरी न कर ले"],"explanationHi":"औपचारिक तर्कण प्रायः क्षेत्र-विशिष्ट होता है और परिचितता पर निर्भर करता है, जिसे पियाजे ने अपने बाद के कार्य में स्वीकार किया। असमानता का अर्थ पहले की अवस्था में वापसी नहीं है।"},
  {"id":"cdp-child-development-1466","question":"A five-year-old sees her brother Ravi wearing a lion mask and screams, ‘It’s a real lion!’ even though she watched him put it on. Piaget would explain her fear mainly by:","options":["Formal operational reasoning about what a mask might really hide","Conservation of identity, which tells her that Ravi has truly changed","Seriation, which leads her to order Ravi and the lion by size and danger","The pre-operational tendency to judge by appearance rather than reality"],"answer":3,"explanation":"Young children often judge by how things look and struggle to hold that something is still the same despite a change in appearance. Understanding identity despite such changes develops later.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"पाँच वर्ष की एक बच्ची अपने भाई रवि को शेर का मुखौटा पहने देखकर चीख उठती है, ‘यह असली शेर है!’ जबकि उसने उसे मुखौटा पहनते देखा था। पियाजे उसके भय की व्याख्या मुख्यतः किससे करेंगे?","optionsHi":["मुखौटा वास्तव में क्या छिपा सकता है, इस पर औपचारिक संक्रियात्मक तर्कण से","तादात्म्य के संरक्षण से, जो उसे बताता है कि रवि सचमुच बदल गया है","क्रमबद्धता से, जो उसे रवि और शेर को आकार और खतरे के अनुसार क्रमित करने की ओर ले जाती है","वास्तविकता के बजाय रूप-रंग से निर्णय करने की पूर्व-संक्रियात्मक प्रवृत्ति से"],"explanationHi":"छोटे बच्चे प्रायः चीज़ें कैसी दिखती हैं उससे निर्णय करते हैं और यह धारण करने में संघर्ष करते हैं कि रूप बदलने पर भी कुछ वही रहता है। ऐसे परिवर्तनों के बावजूद तादात्म्य की समझ बाद में विकसित होती है।"},
  {"id":"cdp-child-development-1467","question":"Which classroom situation best shows Vygotsky’s idea that learning can lead development?","options":["Waiting until a child spontaneously shows readiness for reading before teaching letters","Refusing to teach fractions until every child can conserve area on Piagetian tasks","Guided practice in a new strategy that children later use alone on harder problems","Repeating last year’s work until every child performs it perfectly and fast"],"answer":2,"explanation":"Instruction within the ZPD helps children acquire abilities they then use independently, so learning pulls development forward. Waiting for readiness reflects the opposite view.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कौन-सी कक्षा-स्थिति वाइगोत्स्की के इस विचार को सबसे अच्छी तरह दर्शाती है कि अधिगम विकास का नेतृत्व कर सकता है?","optionsHi":["अक्षर पढ़ाने से पहले इंतज़ार करना कि बच्चा पठन के लिए स्वतः तत्परता दिखाए","जब तक हर बच्चा पियाजे-शैली के कार्यों में क्षेत्रफल का संरक्षण न कर सके, तब तक भिन्न पढ़ाने से इनकार करना","किसी नई रणनीति में निर्देशित अभ्यास जिसे बच्चे बाद में कठिन समस्याओं पर स्वयं प्रयोग करते हैं","पिछले वर्ष का कार्य तब तक दोहराना जब तक हर बच्चा उसे परिपूर्ण और तेज़ी से न कर ले"],"explanationHi":"ZPD के भीतर निर्देशन बच्चों को वे क्षमताएँ अर्जित करने में सहायता करता है जिन्हें वे फिर स्वतंत्र रूप से प्रयोग करते हैं, इसलिए अधिगम विकास को आगे खींचता है। तत्परता की प्रतीक्षा उलटे दृष्टिकोण को दर्शाती है।"},
  {"id":"cdp-child-development-1468","question":"Consider these statements. 1. Piaget saw language as a reflection of thought. 2. Vygotsky saw language as a tool that transforms thought. 3. Bruner linked the symbolic mode closely with language. Which is/are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":3,"explanation":"All three statements correctly summarise the theorists’ positions on language and thought.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"इन कथनों पर विचार कीजिए। 1. पियाजे भाषा को चिंतन का प्रतिबिंब मानते थे। 2. वाइगोत्स्की भाषा को ऐसा उपकरण मानते थे जो चिंतन को रूपांतरित करता है। 3. ब्रूनर ने प्रतीकात्मक विधा को भाषा से निकट रूप से जोड़ा। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"तीनों कथन भाषा और चिंतन पर सिद्धांतकारों की स्थितियों का सही सार प्रस्तुत करते हैं।"},
  {"id":"cdp-child-development-1469","question":"A Class 3 teacher asks children to estimate how many beans fill a cup, then count them in groups of ten, and compare. One child says, ‘My guess was too small because the beans were tiny.’ Which theoretical idea is best illustrated by the child’s comment?","options":["Operant extinction of her guessing after an unrewarded wrong answer","Revising an expectation after it clashes with experience (equilibration)","Classical conditioning that pairs the size of beans with counting","Imaginary audience, as she worries that others will notice her guess was wrong"],"answer":1,"explanation":"The child notices the gap between prediction and result and adjusts her thinking, the process Piaget described as moving from disequilibrium to a new equilibrium.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 3 की एक शिक्षिका बच्चों से अनुमान लगाने को कहती है कि एक कप में कितनी फलियाँ आती हैं, फिर उन्हें दस-दस के समूहों में गिनने और तुलना करने को। एक बच्ची कहती है, ‘मेरा अनुमान बहुत कम था क्योंकि फलियाँ बहुत छोटी थीं।’ बच्ची की टिप्पणी से कौन-सा सैद्धांतिक विचार सबसे अच्छी तरह स्पष्ट होता है?","optionsHi":["बिना पुरस्कृत गलत उत्तर के बाद उसके अनुमान का क्रियाप्रसूत विलोपन","अनुभव से टकराने के बाद किसी अपेक्षा का संशोधन (साम्य-स्थापन)","शास्त्रीय अनुबंधन जो फलियों के आकार को गिनती से जोड़ता है","काल्पनिक दर्शक, क्योंकि वह चिंतित है कि दूसरे नोटिस करेंगे कि उसका अनुमान गलत था"],"explanationHi":"बच्ची पूर्वानुमान और परिणाम के बीच के अंतर को देखती है और अपने चिंतन को समायोजित करती है, जिस प्रक्रिया को पियाजे ने असंतुलन से नई साम्यावस्था की ओर जाना कहा।"},
  {"id":"cdp-child-development-1470","question":"Asked about Heinz, a Class 7 student says, ‘If he loves his wife, he should steal; if he doesn’t care much for her, he shouldn’t. It’s his life and his choice; everyone looks after their own interest.’ Which stage does this most closely fit?","options":["Stage 5, because he accepts that values differ from person to person","Stage 2, because right is relative to each person’s own interests","Stage 3, because he talks about love","Stage 4, because he respects individual choice as a rule"],"answer":1,"explanation":"Stage 2 is individualistic and relativistic: each person pursues his own interests, and right depends on what one wants. Stage 5 relativism is grounded in rights and social agreements, which he never mentions.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"हाइंज़ के बारे में पूछे जाने पर, कक्षा 7 का एक विद्यार्थी कहता है, ‘यदि वह अपनी पत्नी से प्रेम करता है, तो उसे चोरी करनी चाहिए; यदि उसे उसकी बहुत परवाह नहीं, तो नहीं। यह उसका जीवन और उसका चुनाव है; हर कोई अपने हित का ध्यान रखता है।’ यह किस चरण से सबसे अधिक मेल खाता है?","optionsHi":["चरण 5, क्योंकि वह स्वीकार करता है कि मूल्य व्यक्ति-व्यक्ति में भिन्न होते हैं","चरण 2, क्योंकि सही प्रत्येक व्यक्ति के अपने हितों के सापेक्ष है","चरण 3, क्योंकि वह प्रेम की बात करता है","चरण 4, क्योंकि वह वैयक्तिक चुनाव का एक नियम के रूप में सम्मान करता है"],"explanationHi":"चरण 2 व्यक्तिवादी और सापेक्षतावादी है: प्रत्येक व्यक्ति अपने हितों का पीछा करता है, और सही इस पर निर्भर करता है कि कोई क्या चाहता है। चरण 5 की सापेक्षता अधिकारों और सामाजिक समझौतों पर आधारित है, जिनका वह कभी उल्लेख नहीं करता।"},
  {"id":"cdp-child-development-1471","question":"Kohlberg held that each higher stage reorganises and includes the understandings of the earlier stages, so that people can understand reasoning below their own stage and tend to prefer the highest stage they understand. This property is called:","options":["Invariant sequence of stages","Universality","Hierarchical integration","Structured whole"],"answer":2,"explanation":"Hierarchical integration means higher stages incorporate and transform lower ones. Invariant sequence refers to the fixed order; structured whole to consistency of reasoning across issues.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कोहलबर्ग का मत था कि प्रत्येक उच्चतर चरण पहले के चरणों की समझ को पुनर्गठित करता है और शामिल करता है, इसलिए लोग अपने चरण से नीचे के तर्कण को समझ सकते हैं और जिस सर्वोच्च चरण को समझते हैं उसे पसंद करते हैं। इस गुण को क्या कहते हैं?","optionsHi":["अवस्थाओं का अपरिवर्ती क्रम","सार्वभौमिकता","पदानुक्रमित समाकलन","संरचित समग्र"],"explanationHi":"पदानुक्रमित समाकलन का अर्थ है कि उच्चतर चरण निचले चरणों को समाहित करते और रूपांतरित करते हैं। अपरिवर्ती क्रम निश्चित क्रम को कहता है; संरचित समग्र मुद्दों में तर्कण की संगति को।"},
  {"id":"cdp-child-development-1472","question":"Piaget distinguished two kinds of respect in children’s moral lives. Which pairing is correct?","options":["Unilateral respect for adults supports heteronomous morality; mutual respect among peers supports autonomous morality","Mutual respect for adults supports heteronomous morality; unilateral respect among peers supports autonomous morality","Both forms of respect lead only to heteronomous morality","Unilateral respect leads to autonomous morality, since children obey adults"],"answer":0,"explanation":"One-sided respect for powerful adults keeps rules external and sacred; mutual respect between equals produces cooperation and an understanding of rules as agreements.","difficulty":"very-hard","source":"CTET Paper 2 · State TET","questionHi":"पियाजे ने बच्चों के नैतिक जीवन में दो प्रकार के सम्मान में भेद किया। कौन-सा जोड़ा सही है?","optionsHi":["वयस्कों के प्रति एकतरफ़ा सम्मान परतंत्र नैतिकता का समर्थन करता है; समवयस्कों के बीच पारस्परिक सम्मान स्वायत्त नैतिकता का","वयस्कों के प्रति पारस्परिक सम्मान परतंत्र नैतिकता का समर्थन करता है; समवयस्कों के बीच एकतरफ़ा सम्मान स्वायत्त नैतिकता का","सम्मान के दोनों रूप केवल परतंत्र नैतिकता की ओर ले जाते हैं","एकतरफ़ा सम्मान स्वायत्त नैतिकता की ओर ले जाता है, क्योंकि बच्चे वयस्कों की आज्ञा मानते हैं"],"explanationHi":"शक्तिशाली वयस्कों के प्रति एकतरफ़ा सम्मान नियमों को बाहरी और पवित्र बनाए रखता है; बराबर वालों के बीच पारस्परिक सम्मान सहयोग और नियमों को समझौतों के रूप में समझने की ओर ले जाता है।"},
  {"id":"cdp-child-development-1473","question":"Asked how to share sweets among children who did unequal work, a younger child says, ‘Whatever the teacher decides’; a slightly older one says, ‘Exactly the same for everyone’; an eleven-year-old says, ‘The little one who couldn’t do much should still get a fair share, and the ones who worked harder can get a bit more.’ Piaget would say the eleven-year-old shows:","options":["Obedience to adult authority as the source of fairness","Strict equality, with identical shares for all","Moral realism, judging by the consequences of acts","Equity, taking individual circumstances into account"],"answer":3,"explanation":"Piaget traced distributive justice from adult authority, to strict equality, to equity, where needs and circumstances are weighed; the eleven-year-old adjusts equality to circumstances.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"असमान काम करने वाले बच्चों में मिठाइयाँ कैसे बाँटी जाएँ, इस पर एक छोटा बच्चा कहता है, ‘जो शिक्षक तय करें’; थोड़ा बड़ा कहता है, ‘सबको बिल्कुल बराबर’; ग्यारह वर्ष का बच्चा कहता है, ‘जो छोटा बच्चा ज़्यादा नहीं कर सका उसे भी उचित हिस्सा मिलना चाहिए, और जिन्होंने ज़्यादा मेहनत की वे थोड़ा ज़्यादा पा सकते हैं।’ पियाजे कहेंगे कि ग्यारह वर्ष का बच्चा दर्शाता है:","optionsHi":["निष्पक्षता के स्रोत के रूप में वयस्क अधिकार का आज्ञापालन","कठोर समानता, सबके लिए समान हिस्से","नैतिक यथार्थवाद, कृत्यों के परिणामों से निर्णय करना","समता (इक्विटी), वैयक्तिक परिस्थितियों को ध्यान में रखना"],"explanationHi":"पियाजे ने वितरणात्मक न्याय का मार्ग वयस्क अधिकार से कठोर समानता और फिर समता तक खोजा, जहाँ आवश्यकताओं और परिस्थितियों को तौला जाता है; ग्यारह वर्ष का बच्चा समानता को परिस्थितियों के अनुसार समायोजित करता है।"},
  {"id":"cdp-child-development-1474","question":"Which statement best summarises Gilligan’s position?","options":["Women reason at higher Kohlberg stages than men, owing to their more caring nature","Care and justice are both valid moral orientations, and care reasoning develops","Moral development has no stages at all, only differences between the sexes","Moral reasoning is entirely learnt from religion and from family traditions"],"answer":1,"explanation":"Gilligan argued for a ‘different voice’ of care alongside justice and described a developmental sequence in care reasoning; she did not claim women were superior on Kohlberg’s scale.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कौन-सा कथन गिलिगन की स्थिति का सबसे अच्छा सार प्रस्तुत करता है?","optionsHi":["महिलाएँ पुरुषों से उच्चतर कोहलबर्ग चरणों में तर्क करती हैं, अपनी अधिक देखभालपूर्ण प्रकृति के कारण","देखभाल और न्याय दोनों वैध नैतिक अभिमुखताएँ हैं, और देखभाल-तर्कण विकसित होता है","नैतिक विकास की कोई अवस्थाएँ ही नहीं हैं, केवल लिंगों के बीच अंतर हैं","नैतिक तर्कण पूर्णतः धर्म और पारिवारिक परंपराओं से सीखा जाता है"],"explanationHi":"गिलिगन ने न्याय के साथ देखभाल की ‘भिन्न आवाज़’ के पक्ष में तर्क दिया और देखभाल-तर्कण में विकासात्मक क्रम का वर्णन किया; उन्होंने यह दावा नहीं किया कि महिलाएँ कोहलबर्ग के पैमाने पर श्रेष्ठ हैं।"},
  {"id":"cdp-child-development-1475","question":"A school plans to put all its ‘problem students’ from Class 8 into one separate section so they don’t disturb others. What does research on adolescent peer influence warn?","options":["Grouping them can raise problem behaviour, as they reinforce each other’s deviance","Grouping them will make them compete with one another to improve their record","It will have no effect, since peers do not really influence each other’s conduct","Only teachers influence adolescent behaviour, so grouping does not matter"],"answer":0,"explanation":"Studies of ‘deviancy training’ show that aggregating high-risk adolescents can escalate problem behaviour; mixing them with prosocial peers and giving targeted support works better.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक विद्यालय अपने सभी कक्षा 8 के ‘समस्याग्रस्त विद्यार्थियों’ को एक अलग अनुभाग में रखने की योजना बनाता है ताकि वे दूसरों को परेशान न करें। किशोर समवयस्क प्रभाव पर शोध क्या चेतावनी देता है?","optionsHi":["उन्हें समूहबद्ध करने से समस्या-व्यवहार बढ़ सकता है, क्योंकि वे एक-दूसरे के विचलन को पुष्ट करते हैं","उन्हें समूहबद्ध करने से वे अपना रिकॉर्ड सुधारने के लिए एक-दूसरे से प्रतिस्पर्धा करेंगे","इसका कोई प्रभाव नहीं होगा, क्योंकि समवयस्क वास्तव में एक-दूसरे के आचरण को प्रभावित नहीं करते","केवल शिक्षक किशोरों के व्यवहार को प्रभावित करते हैं, इसलिए समूहीकरण से फ़र्क नहीं पड़ता"],"explanationHi":"‘विचलन-प्रशिक्षण’ के अध्ययन दिखाते हैं कि उच्च-जोखिम वाले किशोरों को एक साथ करने से समस्या-व्यवहार बढ़ सकता है; उन्हें समाज-हितैषी साथियों के साथ मिलाना और लक्षित सहायता देना बेहतर काम करता है।"},
  {"id":"cdp-child-development-1476","question":"Which of these is an example of a mesosystem for a Class 5 child?","options":["The child’s close day-to-day relationship with her best friend","The national curriculum framework that shapes her textbooks","The child’s father’s office, where decisions affect her family","Her parents getting to know her friends and inviting them home"],"answer":3,"explanation":"A mesosystem is a link between two of the child’s microsystems (here family and peer group). A friendship is a microsystem relation; a parent’s office is exosystem; a national framework is broader than both.","difficulty":"very-hard","source":"CTET Paper 1 · State TET","questionHi":"कक्षा 5 की बच्ची के लिए इनमें से कौन-सा मध्य-तंत्र (मेसोसिस्टम) का उदाहरण है?","optionsHi":["बच्ची का अपनी सबसे अच्छी सहेली के साथ घनिष्ठ दैनिक संबंध","राष्ट्रीय पाठ्यचर्या की रूपरेखा जो उसकी पाठ्यपुस्तकों को आकार देती है","बच्ची के पिता का कार्यालय, जहाँ निर्णय उसके परिवार को प्रभावित करते हैं","उसके माता-पिता का उसके मित्रों से परिचित होना और उन्हें घर बुलाना"],"explanationHi":"मध्य-तंत्र बच्ची के दो सूक्ष्म-तंत्रों (यहाँ परिवार और समवयस्क समूह) के बीच की कड़ी है। मित्रता सूक्ष्म-तंत्र का संबंध है; माता-पिता का कार्यालय बाह्य-तंत्र है; राष्ट्रीय रूपरेखा दोनों से व्यापक है।"},
  {"id":"cdp-child-development-1477","question":"In later work, Bronfenbrenner renamed his approach the ‘bioecological model’. What did this change mainly emphasise?","options":["The child’s own traits and everyday interactions (proximal processes)","That only biology matters for development, and the environment does not","That the macrosystem is the most important layer in every child's life","That development is largely complete by the end of adolescence"],"answer":0,"explanation":"The bioecological model added the person’s characteristics and regular reciprocal interactions with people and objects (proximal processes), together with context and time, as the engines of development.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"बाद के कार्य में, ब्रॉन्फ़ेनब्रेनर ने अपने उपागम का नाम ‘जैव-पारिस्थितिक प्रतिरूप’ रखा। इस परिवर्तन ने मुख्यतः किस पर बल दिया?","optionsHi":["बच्चे की अपनी विशेषताएँ और दैनिक अंतःक्रियाएँ (निकटस्थ प्रक्रियाएँ)","कि विकास के लिए केवल जीव-विज्ञान मायने रखता है, पर्यावरण नहीं","कि वृहत्-तंत्र हर बच्चे के जीवन में सबसे महत्त्वपूर्ण परत है","कि विकास किशोरावस्था के अंत तक काफ़ी हद तक पूर्ण हो जाता है"],"explanationHi":"जैव-पारिस्थितिक प्रतिरूप ने व्यक्ति की विशेषताओं और लोगों तथा वस्तुओं के साथ नियमित पारस्परिक अंतःक्रियाओं (निकटस्थ प्रक्रियाओं) को, संदर्भ और समय के साथ, विकास के इंजन के रूप में जोड़ा।"},
  {"id":"cdp-child-development-1478","question":"Assertion (A): Children who were securely attached as infants tend, on average, to be more socially competent with peers and teachers in school. Reason (R): Secure attachment gives children positive expectations of relationships and confidence in exploring and interacting.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Longitudinal studies link secure attachment with later social competence, explained by positive internal working models and confident exploration; the link is probabilistic, not destiny.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"अभिकथन (A): जो बच्चे शैशवावस्था में सुरक्षित रूप से आसक्त थे, वे औसतन विद्यालय में समवयस्कों और शिक्षकों के साथ अधिक सामाजिक रूप से सक्षम होते हैं। कारण (R): सुरक्षित आसक्ति बच्चों को संबंधों की सकारात्मक अपेक्षाएँ और अन्वेषण तथा अंतःक्रिया में आत्मविश्वास देती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दीर्घकालिक अध्ययन सुरक्षित आसक्ति को बाद की सामाजिक सक्षमता से जोड़ते हैं, जिसकी व्याख्या सकारात्मक आंतरिक कार्यकारी प्रतिरूपों और आत्मविश्वासी अन्वेषण से होती है; यह संबंध संभाव्य है, नियति नहीं।"},
  {"id":"cdp-child-development-1479","question":"Studies of the Strange Situation in many countries found that:","options":["Avoidant attachment is the most common pattern everywhere in the world","Secure attachment is most common in most cultures; insecure types vary","Attachment patterns are identical in all cultures, in type and in proportion","Infants in collectivist cultures never form secure attachments to mothers"],"answer":1,"explanation":"Cross-cultural comparisons show secure attachment as the modal pattern in most samples, with variation in the frequency of avoidant and resistant types, partly reflecting childcare practices.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"अनेक देशों में स्ट्रेंज सिचुएशन के अध्ययनों ने पाया कि:","optionsHi":["परिहारात्मक आसक्ति पूरी दुनिया में सबसे आम प्रतिरूप है","सुरक्षित आसक्ति अधिकांश संस्कृतियों में सबसे आम है; असुरक्षित प्रकार भिन्न होते हैं","आसक्ति के प्रतिरूप सभी संस्कृतियों में प्रकार और अनुपात दोनों में समान हैं","सामूहिकतावादी संस्कृतियों में शिशु माताओं के प्रति कभी सुरक्षित आसक्ति नहीं बनाते"],"explanationHi":"अंतर-सांस्कृतिक तुलनाएँ अधिकांश नमूनों में सुरक्षित आसक्ति को प्रमुख प्रतिरूप दिखाती हैं, परिहारात्मक और प्रतिरोधी प्रकारों की आवृत्ति में भिन्नता के साथ, जो आंशिक रूप से बाल-देखभाल की प्रथाओं को दर्शाती है।"},
  {"id":"cdp-child-development-1480","question":"In a Class 2, parents complete most homework projects for their children, and the teacher praises the polished results. From Erikson’s viewpoint, what is the main risk?","options":["The children will develop too much autonomy and resist adult guidance","The children will become mistrustful of their parents and their help","The children lose real chances to feel competent, weakening industry","The children will move too quickly into the identity stage"],"answer":2,"explanation":"Industry grows from children’s own effort and mastery; when adults do the work, children miss the experience of competence, and praise of adult work can deepen feelings of inadequacy.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 में, माता-पिता अपने बच्चों की अधिकांश गृहकार्य परियोजनाएँ स्वयं पूरी कर देते हैं, और शिक्षक चमकदार परिणामों की प्रशंसा करता है। एरिक्सन के दृष्टिकोण से मुख्य जोखिम क्या है?","optionsHi":["बच्चे बहुत अधिक स्वायत्तता विकसित करेंगे और वयस्क मार्गदर्शन का विरोध करेंगे","बच्चे अपने माता-पिता और उनकी सहायता के प्रति अविश्वासी हो जाएँगे","बच्चे सक्षम महसूस करने के वास्तविक अवसर खो देते हैं, जिससे उद्यमशीलता कमज़ोर होती है","बच्चे पहचान की अवस्था में बहुत जल्दी पहुँच जाएँगे"],"explanationHi":"उद्यमशीलता बच्चों के अपने प्रयास और निपुणता से विकसित होती है; जब वयस्क काम करते हैं, तो बच्चे सक्षमता के अनुभव से वंचित रह जाते हैं, और वयस्कों के कार्य की प्रशंसा अपर्याप्तता की भावना को गहरा कर सकती है।"},
  {"id":"cdp-child-development-1481","question":"A three-month-old smiles and coos at almost anyone who talks to her, though she calms a little more quickly with her mother. In Bowlby’s sequence of attachment, she is most likely in the phase of:","options":["Clear-cut attachment, with marked separation protest and wariness of strangers","Goal-corrected partnership, adjusting to the mother’s plans and goals","Attachment in the making: some preference, but no separation protest","Imprinting, a fixed bond formed in a critical period after birth"],"answer":2,"explanation":"From about 6 weeks to 6–8 months infants respond more to familiar people but do not yet protest separation; clear-cut attachment with separation and stranger anxiety follows later.","difficulty":"very-hard","source":"CTET Paper 1 · State TET","questionHi":"तीन माह की एक शिशु लगभग किसी भी बात करने वाले को देखकर मुस्कुराती और गुँ-गुँ करती है, यद्यपि अपनी माँ के साथ वह थोड़ी जल्दी शांत होती है। बॉल्बी के आसक्ति-क्रम में, वह सबसे संभवतः किस चरण में है?","optionsHi":["स्पष्ट आसक्ति, जिसमें वियोग-विरोध और अजनबियों से सतर्कता स्पष्ट हो","लक्ष्य-सुधारित साझेदारी, माँ की योजनाओं और लक्ष्यों के अनुसार ढलना","बनती हुई आसक्ति: कुछ वरीयता, पर वियोग-विरोध नहीं","छाप (इंप्रिंटिंग), जन्म के बाद क्रांतिक अवधि में बना निश्चित बंधन"],"explanationHi":"लगभग 6 सप्ताह से 6–8 माह तक शिशु परिचित लोगों पर अधिक प्रतिक्रिया करते हैं पर अभी वियोग का विरोध नहीं करते; वियोग और अजनबी-चिंता के साथ स्पष्ट आसक्ति बाद में आती है।"},
  {"id":"cdp-child-development-1482","question":"The brain reaches about 90% of its adult weight by around age six, while the reproductive organs grow very little until puberty. Which principle of development does this illustrate?","options":["Development is uniform across all parts and systems of the body","Growth of the brain and body largely stops by around the age of six","Development proceeds from specific to general, as in the brain","Different parts and systems of the body develop at different rates"],"answer":3,"explanation":"Body systems follow different growth curves (as Scammon showed): neural tissue grows fastest early, reproductive tissue at puberty; development is not uniform.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"मस्तिष्क लगभग छह वर्ष की आयु तक अपने वयस्क भार का लगभग 90% पा लेता है, जबकि प्रजनन अंग यौवनारंभ तक बहुत कम बढ़ते हैं। यह विकास के किस सिद्धांत को दर्शाता है?","optionsHi":["विकास शरीर के सभी भागों और प्रणालियों में एक-सा होता है","मस्तिष्क और शरीर की वृद्धि लगभग छह वर्ष की आयु तक काफ़ी हद तक रुक जाती है","विकास विशिष्ट से सामान्य की ओर बढ़ता है, जैसे मस्तिष्क में","शरीर के भिन्न भाग और प्रणालियाँ भिन्न दरों से विकसित होती हैं"],"explanationHi":"शरीर की प्रणालियाँ भिन्न वृद्धि-वक्रों का अनुसरण करती हैं (जैसा स्कैमन ने दिखाया): तंत्रिका ऊतक आरंभ में सबसे तेज़ बढ़ता है, प्रजनन ऊतक यौवनारंभ पर; विकास एकसमान नहीं है।"},
  {"id":"cdp-child-development-1483","question":"Francis Galton found that eminent men tended to have eminent relatives and concluded that genius is mainly inherited. What is the main flaw in this reasoning?","options":["Such families also share wealth and schooling, confounding genes and environment","Eminence cannot be measured reliably, so nothing can be concluded about any family","Galton studied only identical twins, who share all their genes anyway","Genius can never run in families, as it is a purely random gift at birth"],"answer":0,"explanation":"Relatives share both genes and environment; family resemblance alone cannot separate the two, which is why twin and adoption designs were later developed.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"फ़्रांसिस गैल्टन ने पाया कि प्रतिष्ठित पुरुषों के प्रायः प्रतिष्ठित संबंधी होते थे और निष्कर्ष निकाला कि प्रतिभा मुख्यतः वंशानुगत है। इस तर्क में मुख्य त्रुटि क्या है?","optionsHi":["ऐसे परिवार धन और शिक्षा भी साझा करते हैं, जिससे जीन और पर्यावरण उलझ जाते हैं","प्रतिष्ठा को विश्वसनीय रूप से मापा नहीं जा सकता, इसलिए किसी परिवार के बारे में कुछ निष्कर्ष नहीं निकाला जा सकता","गैल्टन ने केवल समरूप जुड़वाँ का अध्ययन किया, जो वैसे भी सभी जीन साझा करते हैं","प्रतिभा कभी परिवारों में नहीं चल सकती, क्योंकि वह जन्म पर प्राप्त विशुद्ध यादृच्छिक उपहार है"],"explanationHi":"संबंधी जीन और पर्यावरण दोनों साझा करते हैं; केवल पारिवारिक समानता दोनों को अलग नहीं कर सकती, इसीलिए बाद में जुड़वाँ और गोद लेने वाले अभिकल्प विकसित किए गए।"},
  {"id":"cdp-child-development-1484","question":"The school council of a senior secondary school debates whether to change the uniform rule. Ritu says, ‘We must keep the rule; rules are rules, and changing them would create disorder.’ Sameer says, ‘The rule was made by agreement for students’ welfare; if most students and teachers agree it no longer serves them, we can change it fairly.’ Their stages are respectively:","options":["Stage 3 and Stage 4","Stage 4 and Stage 5","Stage 4 and Stage 6","Stage 5 and Stage 4"],"answer":1,"explanation":"Ritu upholds rules to maintain order (Stage 4); Sameer sees rules as revisable social contracts serving welfare (Stage 5). Stage 6 would appeal to universal principles above any agreement.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक वरिष्ठ माध्यमिक विद्यालय की विद्यालय परिषद गणवेश नियम बदलने पर बहस करती है। रितु कहती है, ‘हमें नियम रखना चाहिए; नियम तो नियम हैं, और उन्हें बदलने से अव्यवस्था होगी।’ समीर कहता है, ‘नियम विद्यार्थियों के कल्याण के लिए सहमति से बना था; यदि अधिकांश विद्यार्थी और शिक्षक सहमत हों कि वह अब उनकी सेवा नहीं करता, तो हम उसे न्यायसंगत ढंग से बदल सकते हैं।’ उनके चरण क्रमशः हैं:","optionsHi":["चरण 3 और चरण 4","चरण 4 और चरण 5","चरण 4 और चरण 6","चरण 5 और चरण 4"],"explanationHi":"रितु व्यवस्था बनाए रखने के लिए नियम का समर्थन करती है (चरण 4); समीर नियमों को कल्याण की सेवा करने वाले परिवर्तनीय सामाजिक अनुबंध मानता है (चरण 5)। चरण 6 किसी भी समझौते से ऊपर सार्वभौमिक सिद्धांतों की अपील करता।"},
  {"id":"cdp-child-development-1485","question":"A Class 10 student is being targeted by abusive messages from classmates in a group chat and has become withdrawn. What should the teacher do first?","options":["Tell her to leave the group and ignore the messages, as replying feeds bullies","Read the messages aloud in class so the bullies are shamed in front of everyone","Wait to see whether it stops on its own before involving anyone else","Listen privately, ensure safety, record it and follow the anti-bullying process"],"answer":3,"explanation":"Cyberbullying needs a supportive, private response and a systematic process involving parents and the counsellor; public shaming or waiting can worsen harm.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 10 की एक विद्यार्थी को समूह-चैट में सहपाठियों के अपमानजनक संदेशों का निशाना बनाया जा रहा है और वह अंतर्मुखी हो गई है। शिक्षक को सबसे पहले क्या करना चाहिए?","optionsHi":["उससे कहना कि समूह छोड़ दे और संदेशों को अनदेखा करे, क्योंकि जवाब देना उत्पीड़कों को बढ़ावा देता है","संदेशों को कक्षा में ज़ोर से पढ़ना ताकि उत्पीड़क सबके सामने शर्मिंदा हों","यह देखने के लिए प्रतीक्षा करना कि क्या वह अपने आप रुक जाता है, किसी और को शामिल करने से पहले","निजी तौर पर सुनना, सुरक्षा सुनिश्चित करना, उसे दर्ज करना और उत्पीड़न-विरोधी प्रक्रिया का पालन करना"],"explanationHi":"साइबर-उत्पीड़न को सहायक, निजी प्रतिक्रिया और अभिभावकों तथा परामर्शदाता को शामिल करने वाली व्यवस्थित प्रक्रिया चाहिए; सार्वजनिक शर्मिंदा करना या प्रतीक्षा करना हानि बढ़ा सकता है।"},
  {"id":"cdp-child-development-1486","question":"Over several weeks a usually lively Class 9 student has become withdrawn, sleeps in class, has stopped eating lunch and has written ‘nothing matters’ in her notebook. What is the most appropriate teacher action?","options":["Talk with her privately and promptly involve the counsellor and her parents","Treat it as normal adolescent moodiness that will pass on its own, and do nothing","Scold her for sleeping in class and for her falling standard of work","Announce her problem to the class so that her friends can help her"],"answer":0,"explanation":"Persistent changes in sleep, appetite and mood with hopeless statements are warning signs beyond ordinary moodiness; teachers should respond with care and refer promptly while protecting privacy.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"कई सप्ताहों में कक्षा 9 की सामान्यतः जीवंत विद्यार्थी अंतर्मुखी हो गई है, कक्षा में सोती है, दोपहर का भोजन करना बंद कर दिया है और अपनी कॉपी में लिखा है ‘कुछ भी मायने नहीं रखता’। सबसे उपयुक्त शिक्षक-कार्रवाई क्या है?","optionsHi":["उससे निजी तौर पर बात करना और शीघ्र परामर्शदाता तथा उसके माता-पिता को शामिल करना","इसे सामान्य किशोर मनमौजीपन मानना जो अपने आप बीत जाएगा, और कुछ न करना","कक्षा में सोने और उसके गिरते कार्य-स्तर के लिए उसे डाँटना","उसकी समस्या कक्षा में घोषित करना ताकि उसके मित्र उसकी सहायता करें"],"explanationHi":"नींद, भूख और मनोदशा में लगातार परिवर्तन निराशा भरे कथनों के साथ सामान्य मनमौजीपन से परे चेतावनी-संकेत हैं; शिक्षकों को गोपनीयता की रक्षा करते हुए देखभाल के साथ प्रतिक्रिया देनी और शीघ्र रेफ़र करना चाहिए।"},
  {"id":"cdp-child-development-1487","question":"Which statement about Piaget’s and Kohlberg’s methods is correct?","options":["Both relied only on standard paper-and-pencil tests given to large groups of children","Piaget: story pairs and games of marbles; Kohlberg: dilemmas with probing interviews","Kohlberg observed children playing marbles; Piaget used the Heinz dilemma","Both measured moral behaviour in real situations rather than reasoning"],"answer":1,"explanation":"Piaget used clinical questioning about story pairs and watched games of marbles; Kohlberg’s dilemmas and interviews probed reasoning. Both studied judgment rather than behaviour.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"पियाजे और कोहलबर्ग की विधियों के बारे में कौन-सा कथन सही है?","optionsHi":["दोनों ने केवल बड़े बच्चों के समूहों पर दिए गए मानक कागज़-पेंसिल परीक्षणों पर भरोसा किया","पियाजे: कहानी-युग्म और कंचों के खेल; कोहलबर्ग: दुविधाएँ और खोजी साक्षात्कार","कोहलबर्ग ने बच्चों को कंचे खेलते देखा; पियाजे ने हाइंज़ दुविधा का उपयोग किया","दोनों ने तर्कण के बजाय वास्तविक परिस्थितियों में नैतिक व्यवहार मापा"],"explanationHi":"पियाजे ने कहानी-युग्मों पर नैदानिक प्रश्नोत्तर का उपयोग किया और कंचों के खेल देखे; कोहलबर्ग की दुविधाओं और साक्षात्कारों ने तर्कण की जाँच की। दोनों ने व्यवहार के बजाय निर्णय का अध्ययन किया।"},
  {"id":"cdp-child-development-1488","question":"A tribal child from a Gond village joins a residential school where the language, food and customs differ from home, and teachers dismiss her home practices as ‘backward’. What does an ecological view of development suggest?","options":["She should forget her home culture so that she can adjust quickly to school","Culture has no effect on learning, so the teachers’ remarks do not matter","Only her family matters for her development, not the residential school","Home–school conflict can harm her; school should build on her home culture"],"answer":3,"explanation":"A weak, conflicting mesosystem and a dismissive school undermine development; culturally responsive teaching that links home and school strengthens it.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"गोंड गाँव की एक जनजातीय बच्ची एक आवासीय विद्यालय में आती है जहाँ भाषा, भोजन और रीति-रिवाज घर से भिन्न हैं, और शिक्षक उसकी घर की प्रथाओं को ‘पिछड़ा’ कहकर खारिज करते हैं। विकास का पारिस्थितिक दृष्टिकोण क्या सुझाता है?","optionsHi":["उसे अपनी घर की संस्कृति भूल जानी चाहिए ताकि वह विद्यालय में शीघ्र अनुकूलित हो जाए","संस्कृति का अधिगम पर कोई प्रभाव नहीं पड़ता, इसलिए शिक्षकों की टिप्पणियाँ मायने नहीं रखतीं","उसके विकास के लिए केवल उसका परिवार मायने रखता है, आवासीय विद्यालय नहीं","घर-विद्यालय का टकराव उसे हानि पहुँचा सकता है; विद्यालय को उसकी घर की संस्कृति पर निर्माण करना चाहिए"],"explanationHi":"कमज़ोर, टकराता मध्य-तंत्र और उपेक्षापूर्ण विद्यालय विकास को क्षीण करते हैं; घर और विद्यालय को जोड़ने वाला सांस्कृतिक रूप से अनुक्रियाशील शिक्षण उसे सुदृढ़ करता है।"},
  {"id":"cdp-child-development-1489","question":"Which of these combinations of Bronfenbrenner’s layers and examples is INCORRECT?","options":["Microsystem – the child’s class teacher","Exosystem – the school management committee whose decisions the child never sees","Macrosystem – the child’s grandparents living in the same house","Chronosystem – the child’s family moving cities when she is eight"],"answer":2,"explanation":"Grandparents living with the child are part of her microsystem; the macrosystem is the wider culture, values and laws.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"ब्रॉन्फ़ेनब्रेनर की परतों और उदाहरणों के इन संयोजनों में से कौन-सा गलत है?","optionsHi":["सूक्ष्म-तंत्र – बच्ची का कक्षा शिक्षक","बाह्य-तंत्र – विद्यालय प्रबंधन समिति जिसके निर्णय बच्ची कभी नहीं देखती","वृहत्-तंत्र – बच्ची के दादा-दादी जो उसी घर में रहते हैं","कालक्रम-तंत्र – बच्ची के आठ वर्ष की होने पर उसके परिवार का शहर बदलना"],"explanationHi":"बच्ची के साथ रहने वाले दादा-दादी उसके सूक्ष्म-तंत्र का भाग हैं; वृहत्-तंत्र व्यापक संस्कृति, मूल्य और कानून हैं।"},
  {"id":"cdp-child-development-1490","question":"Assertion (A): An adolescent may reason at Kohlberg’s Stage 4 in a class discussion yet follow friends into a risky prank. Reason (R): Moral action depends not only on reasoning but also on factors such as emotions, peer situations and self-control.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The gap between moral reasoning and behaviour is well documented; situational pressures, emotion and self-regulation also shape what adolescents actually do.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): कोई किशोर कक्षा-चर्चा में कोहलबर्ग के चरण 4 पर तर्क कर सकता है फिर भी मित्रों के पीछे किसी जोखिम भरी शरारत में शामिल हो सकता है। कारण (R): नैतिक कार्य केवल तर्कण पर नहीं बल्कि भावनाओं, साथियों की परिस्थितियों और आत्म-नियंत्रण जैसे कारकों पर भी निर्भर करता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"नैतिक तर्कण और व्यवहार के बीच का अंतर भली-भाँति प्रलेखित है; परिस्थितिगत दबाव, भावना और आत्म-नियमन भी आकार देते हैं कि किशोर वास्तव में क्या करते हैं।"},
  {"id":"cdp-child-development-1491","question":"A Class 6 teacher wants to foster empathy and moral reasoning together. Which activity combines insights from Kohlberg, Gilligan and Hoffman best?","options":["Students copy moral sayings ten times each so that good values sink in","The teacher reads out a list of rules and the punishments for breaking them","Discussing a real class conflict: each person’s feelings and what is fair","Students are rewarded with sweets each time they obey the class rules"],"answer":2,"explanation":"Discussion of real dilemmas (Kohlberg), attention to relationships and care (Gilligan) and perspective-taking about others’ feelings (Hoffman’s induction) are all present only in this activity.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"कक्षा 6 का एक शिक्षक सहानुभूति और नैतिक तर्कण को साथ-साथ विकसित करना चाहता है। कौन-सी गतिविधि कोहलबर्ग, गिलिगन और हॉफमैन की अंतर्दृष्टियों को सबसे अच्छी तरह जोड़ती है?","optionsHi":["विद्यार्थी नैतिक सूक्तियाँ दस-दस बार उतारते हैं ताकि अच्छे मूल्य बैठ जाएँ","शिक्षक नियमों की सूची और उन्हें तोड़ने के दंड पढ़कर सुनाता है","कक्षा के किसी वास्तविक संघर्ष पर चर्चा: प्रत्येक व्यक्ति की भावनाएँ और क्या उचित है","कक्षा के नियमों का पालन करने पर विद्यार्थियों को हर बार मिठाई से पुरस्कृत किया जाता है"],"explanationHi":"वास्तविक दुविधाओं पर चर्चा (कोहलबर्ग), संबंधों और देखभाल पर ध्यान (गिलिगन) और दूसरों की भावनाओं के बारे में दृष्टिकोण-ग्रहण (हॉफमैन का प्रेरण) केवल इसी गतिविधि में मौजूद हैं।"},
  {"id":"cdp-child-development-1492","question":"Which of these statements about attachment and later development is most accurate?","options":["An insecure attachment in infancy guarantees problems in all later relationships","Early attachment shapes later relationships, but later caring bonds can modify it","A child can form an attachment only with one person, usually the mother","Attachment has no relationship to later development once school begins"],"answer":1,"explanation":"Attachment shapes expectations, but development stays open to change; stable, warm relationships later in life can foster ‘earned security’.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"आसक्ति और आगे के विकास के बारे में इनमें से कौन-सा कथन सबसे सटीक है?","optionsHi":["शैशवावस्था में असुरक्षित आसक्ति सभी आगे के संबंधों में समस्याओं की गारंटी देती है","प्रारंभिक आसक्ति आगे के संबंधों को आकार देती है, पर जीवन में बाद के देखभालपूर्ण बंधन उसे बदल सकते हैं","बच्चा केवल एक व्यक्ति के साथ आसक्ति बना सकता है, प्रायः माँ के साथ","विद्यालय शुरू होने के बाद आसक्ति का आगे के विकास से कोई संबंध नहीं रहता"],"explanationHi":"आसक्ति अपेक्षाओं को आकार देती है, पर विकास परिवर्तन के लिए खुला रहता है; जीवन में बाद के स्थिर, स्नेहपूर्ण संबंध ‘अर्जित सुरक्षा’ को बढ़ावा दे सकते हैं।"},
  {"id":"cdp-child-development-1493","question":"A preschool child from a poor family attends a good anganwadi with nutritious meals, stimulating play and a caring worker, and her mother joins a self-help group that raises family income. Which statement in Bronfenbrenner’s terms is correct?","options":["Only the anganwadi, as a microsystem, affects the child directly or indirectly","The self-help group is her exosystem, helping her through the family","The self-help group is part of the child’s microsystem, like the anganwadi","Changes in family income have no developmental effect on a young child"],"answer":1,"explanation":"The child does not attend the self-help group, so it is an exosystem setting; it benefits her indirectly through the family. The anganwadi is a microsystem.","difficulty":"very-hard","source":"CTET Paper 1 · State TET","questionHi":"एक गरीब परिवार की पूर्व-विद्यालयी बच्ची पौष्टिक भोजन, उत्तेजक खेल और देखभाल करने वाली कार्यकर्ता वाली अच्छी आँगनवाड़ी में जाती है, और उसकी माँ एक स्वयं सहायता समूह से जुड़ती है जो परिवार की आय बढ़ाता है। ब्रॉन्फ़ेनब्रेनर की शब्दावली में कौन-सा कथन सही है?","optionsHi":["केवल आँगनवाड़ी, सूक्ष्म-तंत्र के रूप में, बच्ची को प्रत्यक्ष या अप्रत्यक्ष रूप से प्रभावित करती है","स्वयं सहायता समूह उसका बाह्य-तंत्र है, जो परिवार के माध्यम से उसकी सहायता करता है","स्वयं सहायता समूह बच्ची के सूक्ष्म-तंत्र का भाग है, आँगनवाड़ी की तरह","पारिवारिक आय में परिवर्तनों का छोटे बच्चे पर कोई विकासात्मक प्रभाव नहीं पड़ता"],"explanationHi":"बच्ची स्वयं सहायता समूह में नहीं जाती, इसलिए वह बाह्य-तंत्र की व्यवस्था है; वह परिवार के माध्यम से उसे अप्रत्यक्ष रूप से लाभ पहुँचाता है। आँगनवाड़ी सूक्ष्म-तंत्र है।"},
  {"id":"cdp-child-development-1494","question":"A Class 4 student consistently tries to please the teacher, saying ‘I want you to think I’m good’, while another says ‘I don’t care what people think; I only do what gets me something.’ Their Kohlberg stages are respectively:","options":["Stage 2 and Stage 3","Stage 1 and Stage 2","Stage 4 and Stage 2","Stage 3 and Stage 2"],"answer":3,"explanation":"Seeking approval as a ‘good’ child is Stage 3; acting for personal gain is Stage 2. The order in the options is the trap.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 4 का एक विद्यार्थी लगातार शिक्षक को प्रसन्न करने का प्रयास करता है, कहते हुए ‘मैं चाहता हूँ कि आप सोचें कि मैं अच्छा हूँ’, जबकि दूसरा कहता है ‘मुझे परवाह नहीं कि लोग क्या सोचते हैं; मैं केवल वही करता हूँ जिससे मुझे कुछ मिले।’ उनके कोहलबर्ग चरण क्रमशः हैं:","optionsHi":["चरण 2 और चरण 3","चरण 1 और चरण 2","चरण 4 और चरण 2","चरण 3 और चरण 2"],"explanationHi":"‘अच्छे’ बच्चे के रूप में स्वीकृति चाहना चरण 3 है; व्यक्तिगत लाभ के लिए कार्य करना चरण 2 है। विकल्पों में क्रम ही जाल है।"},
  {"id":"cdp-child-development-1495","question":"Eight-year-old Yash, who lives in a crowded part of Mumbai and has never kept plants or pets, can name the make and model of almost any car from a glimpse of its headlights and groups cars by their features. Gardner would most likely see this as an expression of:","options":["Naturalist intelligence, which can also apply to sorting man-made objects","Bodily-kinaesthetic intelligence, from his interest in vehicles","Logical-mathematical intelligence only, as he classifies cars by their features","Interpersonal intelligence, from talking with car-loving adults"],"answer":0,"explanation":"The core of naturalist intelligence is recognising and classifying members of a group by their features; Gardner noted that in urban settings it may be applied to things like cars or shoes.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"आठ वर्षीय यश, जो मुंबई के भीड़-भरे इलाके में रहता है और जिसने कभी पौधे या पालतू जानवर नहीं रखे, लगभग किसी भी कार का मेक और मॉडल उसकी हेडलाइट की एक झलक से बता सकता है और कारों को उनकी विशेषताओं से समूहबद्ध करता है। गार्डनर इसे सबसे संभवतः किसकी अभिव्यक्ति मानेंगे?","optionsHi":["प्रकृतिवादी बुद्धि, जो मानव-निर्मित वस्तुओं के वर्गीकरण पर भी लागू हो सकती है","शारीरिक-गतिबोधक बुद्धि, वाहनों में उसकी रुचि से","केवल तार्किक-गणितीय बुद्धि, क्योंकि वह कारों को उनकी विशेषताओं से वर्गीकृत करता है","अंतर्वैयक्तिक बुद्धि, कार-प्रेमी वयस्कों से बातचीत से"],"explanationHi":"प्रकृतिवादी बुद्धि का मूल किसी समूह के सदस्यों को उनकी विशेषताओं से पहचानना और वर्गीकृत करना है; गार्डनर ने उल्लेख किया कि शहरी परिवेश में इसे कारों या जूतों जैसी चीज़ों पर लागू किया जा सकता है।"},
  {"id":"cdp-child-development-1496","question":"Which finding is most often cited AGAINST Gardner’s claim that the intelligences are largely independent of one another?","options":["Some people show exceptional talent in only one area, such as music or mathematics","Brain damage can impair one ability while sparing others almost completely","Tests of very different abilities tend to correlate positively with each other","Different cultures value different abilities and train them differently"],"answer":2,"explanation":"The positive correlations among diverse mental tests are the main evidence for a general factor, which challenges strict independence. Savants and selective brain damage are evidence Gardner uses in his favour.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"गार्डनर के इस दावे के विरुद्ध कि बुद्धियाँ काफ़ी हद तक एक-दूसरे से स्वतंत्र हैं, कौन-सा निष्कर्ष सबसे अधिक उद्धृत किया जाता है?","optionsHi":["कुछ लोग केवल एक क्षेत्र में असाधारण प्रतिभा दिखाते हैं, जैसे संगीत या गणित","मस्तिष्क-क्षति एक योग्यता को क्षीण कर सकती है जबकि अन्य को लगभग पूरी तरह छोड़ देती है","बहुत भिन्न योग्यताओं के परीक्षण एक-दूसरे से धनात्मक रूप से सहसंबद्ध होते हैं","विभिन्न संस्कृतियाँ भिन्न योग्यताओं को महत्त्व देती हैं और उन्हें भिन्न रूप से प्रशिक्षित करती हैं"],"explanationHi":"विविध मानसिक परीक्षणों के बीच धनात्मक सहसंबंध सामान्य कारक के मुख्य प्रमाण हैं, जो कठोर स्वतंत्रता को चुनौती देते हैं। सावंत और चयनात्मक मस्तिष्क-क्षति वे प्रमाण हैं जिनका गार्डनर अपने पक्ष में उपयोग करते हैं।"},
  {"id":"cdp-child-development-1497","question":"Asked to read a newspaper editorial claiming that ‘mobile phones are the main cause of falling marks’, Farah lists the evidence given, points out that other causes have been ignored and judges that the conclusion goes beyond the data. In Sternberg’s theory, this mainly uses:","options":["Creative intelligence","Analytical intelligence","Practical intelligence","Emotional intelligence"],"answer":1,"explanation":"Analysing, comparing and evaluating arguments is analytical (componential) intelligence; creative intelligence deals with novelty and practical intelligence with everyday adaptation.","difficulty":"moderate","source":"CTET Paper 2 · State TET","questionHi":"एक समाचार-पत्र संपादकीय पढ़ने को कहा जाने पर, जो दावा करता है कि ‘मोबाइल फ़ोन गिरते अंकों का मुख्य कारण हैं’, फ़राह दिए गए प्रमाणों की सूची बनाती है, इंगित करती है कि अन्य कारणों की उपेक्षा की गई है और निर्णय देती है कि निष्कर्ष आँकड़ों से आगे जाता है। स्टर्नबर्ग के सिद्धांत में, यह मुख्यतः किसका उपयोग करता है?","optionsHi":["सृजनात्मक बुद्धि","विश्लेषणात्मक बुद्धि","व्यावहारिक बुद्धि","भावनात्मक बुद्धि"],"explanationHi":"तर्कों का विश्लेषण, तुलना और मूल्यांकन करना विश्लेषणात्मक (घटकीय) बुद्धि है; सृजनात्मक बुद्धि नवीनता से और व्यावहारिक बुद्धि रोज़मर्रा के अनुकूलन से संबंधित है।"},
  {"id":"cdp-child-development-1498","question":"After a year in the science stream, Divya finds that she cannot thrive in it despite effort. With guidance, she moves to commerce, where her abilities and interests fit well and she flourishes. In Sternberg’s contextual subtheory, this is an example of:","options":["Adaptation","Shaping","Selection","Automatisation"],"answer":2,"explanation":"When neither adapting to nor reshaping an environment works, practical intelligence may choose a different environment that fits better; Sternberg calls this selection.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"विज्ञान धारा में एक वर्ष के बाद, दिव्या पाती है कि प्रयास के बावजूद वह उसमें पनप नहीं सकती। मार्गदर्शन के साथ, वह वाणिज्य में जाती है, जहाँ उसकी योग्यताएँ और रुचियाँ अच्छी तरह मेल खाती हैं और वह फलती-फूलती है। स्टर्नबर्ग के संदर्भात्मक उप-सिद्धांत में, यह किसका उदाहरण है?","optionsHi":["अनुकूलन","आकार देना","चयन","स्वचालन"],"explanationHi":"जब किसी परिवेश के प्रति अनुकूलन या उसे पुनः आकार देना काम नहीं करता, तब व्यावहारिक बुद्धि कोई भिन्न परिवेश चुन सकती है जो बेहतर मेल खाता हो; स्टर्नबर्ग इसे चयन कहते हैं।"},
  {"id":"cdp-child-development-1499","question":"Assertion (A): According to Spearman, a person’s score on a test of musical pitch cannot be predicted fully from his level of g. Reason (R): Spearman held that, besides g, each test also draws on a specific factor (s) peculiar to that test.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"In the two-factor theory, every performance depends on g plus an s factor specific to the task; because s varies independently, g alone cannot fully predict a particular test score.","difficulty":"hard","source":"CTET · DSSSB TGT","questionHi":"अभिकथन (A): स्पीयरमैन के अनुसार, संगीत-स्वर के परीक्षण पर किसी व्यक्ति के अंक का उसके g के स्तर से पूर्णतः पूर्वानुमान नहीं लगाया जा सकता। कारण (R): स्पीयरमैन का मत था कि g के अतिरिक्त प्रत्येक परीक्षण उस परीक्षण के लिए विशिष्ट एक विशिष्ट कारक (s) का भी उपयोग करता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"द्वि-कारक सिद्धांत में, प्रत्येक प्रदर्शन g तथा कार्य-विशिष्ट s कारक पर निर्भर करता है; क्योंकि s स्वतंत्र रूप से बदलता है, केवल g किसी विशेष परीक्षण-अंक का पूर्ण पूर्वानुमान नहीं दे सकता।"},
  {"id":"cdp-child-development-1500","question":"Kanha, who has had very little schooling, solves unfamiliar pattern-completion puzzles quickly but knows few facts and words from textbooks. In Cattell’s terms, he shows relatively high:","options":["Crystallised intelligence","Fluid intelligence","Emotional intelligence","Level I ability"],"answer":1,"explanation":"Fluid intelligence is the capacity to reason and solve novel problems independent of learned knowledge; crystallised intelligence is the store of knowledge and vocabulary built through education and experience.","difficulty":"moderate","source":"CTET Paper 2 · State TET","questionHi":"कान्हा, जिसने बहुत कम स्कूली शिक्षा पाई है, अपरिचित प्रतिरूप-पूर्ति पहेलियाँ शीघ्रता से हल करता है पर पाठ्यपुस्तकों के कुछ ही तथ्य और शब्द जानता है। कैटेल की शब्दावली में, वह अपेक्षाकृत उच्च दिखाता है:","optionsHi":["मूर्त (क्रिस्टलीकृत) बुद्धि","तरल बुद्धि","भावनात्मक बुद्धि","स्तर I योग्यता"],"explanationHi":"तरल बुद्धि सीखे हुए ज्ञान से स्वतंत्र रूप से तर्क करने और नई समस्याएँ हल करने की क्षमता है; मूर्त बुद्धि शिक्षा और अनुभव से बना ज्ञान और शब्दावली का भंडार है।"},
  {"id":"cdp-child-development-1501","question":"Which term does the Rights of Persons with Disabilities Act, 2016 use for a condition marked by significant limitation in intellectual functioning and adaptive behaviour?","options":["Mental retardation","Specific learning disability","Mental illness","Intellectual disability"],"answer":3,"explanation":"The RPwD Act, 2016 uses ‘intellectual disability’, replacing the older stigmatising term ‘mental retardation’; mental illness is a different category, and specific learning disability covers difficulties such as dyslexia, not limited intellectual functioning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"दिव्यांगजन अधिकार अधिनियम, 2016 बौद्धिक कार्यप्रणाली और अनुकूली व्यवहार में महत्वपूर्ण सीमितता वाली स्थिति के लिए किस शब्द का प्रयोग करता है?","optionsHi":["मानसिक मंदता","विशिष्ट अधिगम अक्षमता","मानसिक रोग","बौद्धिक अक्षमता"],"explanationHi":"RPwD अधिनियम, 2016 में पुराने अपमानजनक शब्द ‘मानसिक मंदता’ के स्थान पर ‘बौद्धिक अक्षमता’ शब्द का प्रयोग किया गया है; मानसिक रोग एक अलग श्रेणी है, और विशिष्ट अधिगम अक्षमता में डिस्लेक्सिया जैसी कठिनाइयाँ आती हैं, सीमित बौद्धिक कार्यप्रणाली नहीं।"},
  {"id":"cdp-child-development-1502","question":"Which is a widely recognised criticism of many popular self-report questionnaires of emotional intelligence?","options":["They overlap heavily with traits like extraversion, so what new ability they measure is unclear","They are far too difficult for most adults to complete unless a trained examiner reads them aloud","They measure mainly mathematical reasoning rather than any emotional skill","Large studies have shown their scores to be identical to IQ test scores"],"answer":0,"explanation":"Self-report EI scales correlate strongly with personality measures and rely on people’s views of themselves; ability-based tests try to measure emotional skills more directly.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"भावनात्मक बुद्धि के अनेक लोकप्रिय स्व-प्रतिवेदन प्रश्नावलियों की एक व्यापक रूप से मान्य आलोचना कौन-सी है?","optionsHi":["वे बहिर्मुखता जैसे व्यक्तित्व गुणों से बहुत अधिक मेल खाती हैं, इसलिए यह स्पष्ट नहीं कि वे कौन-सी नई क्षमता मापती हैं","वे अधिकांश वयस्कों के लिए इतनी कठिन हैं कि प्रशिक्षित परीक्षक के पढ़कर सुनाए बिना पूरी नहीं की जा सकतीं","वे भावनात्मक कौशल के बजाय मुख्यतः गणितीय तर्क को मापती हैं","बड़े अध्ययनों ने दिखाया है कि उनके अंक IQ परीक्षण के अंकों के समान होते हैं"],"explanationHi":"स्व-प्रतिवेदन EI पैमाने व्यक्तित्व मापों से अत्यधिक सहसंबंधित होते हैं और लोगों की अपने बारे में राय पर निर्भर करते हैं; क्षमता-आधारित परीक्षण भावनात्मक कौशलों को अधिक प्रत्यक्ष रूप से मापने का प्रयास करते हैं।"},
  {"id":"cdp-child-development-1503","question":"While mixing colours, a Class 2 child discovers, for herself, that yellow and blue make green. The idea is new to her though not to the world. Kaufman and Beghetto would call this kind of creativity:","options":["Big-C creativity","Pro-c creativity","Mini-c creativity","Divergent production"],"answer":2,"explanation":"Mini-c is the personally meaningful new insight of a learner; little-c is everyday creativity, Pro-c is professional-level creativity and Big-C is eminent, field-changing creativity.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"रंग मिलाते समय कक्षा 2 की एक बच्ची स्वयं खोज लेती है कि पीला और नीला मिलकर हरा बनाते हैं। यह विचार उसके लिए नया है, पर दुनिया के लिए नहीं। काउफमैन और बेघेटो इस प्रकार की सृजनात्मकता को क्या कहेंगे?","optionsHi":["Big-C सृजनात्मकता","Pro-c सृजनात्मकता","Mini-c सृजनात्मकता","अपसारी उत्पादन"],"explanationHi":"Mini-c अधिगमकर्ता की व्यक्तिगत रूप से अर्थपूर्ण नई अंतर्दृष्टि है; little-c रोज़मर्रा की सृजनात्मकता है, Pro-c व्यावसायिक स्तर की सृजनात्मकता है और Big-C प्रख्यात, क्षेत्र को बदल देने वाली सृजनात्मकता है।"},
  {"id":"cdp-child-development-1504","question":"A Class 6 teacher asks, ‘Imagine you are a drop of water evaporating from the Narmada; describe how you feel as you rise and cool,’ to help students think about the water cycle in a new way. This use of personal analogy is a technique from:","options":["Programmed instruction","Synectics","Rote learning","Classical conditioning"],"answer":1,"explanation":"Synectics (William Gordon) uses direct, personal and symbolic analogies to ‘make the strange familiar and the familiar strange’, stimulating creative thinking.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"कक्षा 6 का एक शिक्षक जल चक्र के बारे में छात्रों को नए ढंग से सोचने में मदद करने के लिए कहता है, ‘कल्पना करो कि तुम नर्मदा से वाष्पित होती पानी की एक बूँद हो; बताओ ऊपर उठते और ठंडे होते समय तुम कैसा अनुभव करते हो।’ व्यक्तिगत सादृश्य का यह प्रयोग किसकी एक तकनीक है?","optionsHi":["अभिक्रमित अनुदेशन","सिनेक्टिक्स","रटकर सीखना","शास्त्रीय अनुबंधन"],"explanationHi":"सिनेक्टिक्स (विलियम गॉर्डन) प्रत्यक्ष, व्यक्तिगत और प्रतीकात्मक सादृश्यों का प्रयोग करके ‘अजनबी को परिचित और परिचित को अजनबी’ बनाती है, जिससे सृजनात्मक चिंतन को प्रोत्साहन मिलता है।"},
  {"id":"cdp-child-development-1505","question":"Zoya, a gifted Class 5 student, attends the Class 7 mathematics period each day but stays with her own class for all other subjects. This arrangement is called:","options":["Grade skipping","Enrichment","Curriculum compacting","Subject acceleration"],"answer":3,"explanation":"Subject (or content) acceleration places a student in a higher grade for one subject only; grade skipping moves her up in all subjects, and enrichment deepens work without moving ahead.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 5 की प्रतिभाशाली छात्रा ज़ोया प्रतिदिन कक्षा 7 के गणित के पीरियड में बैठती है, पर अन्य सभी विषयों के लिए अपनी ही कक्षा में रहती है। इस व्यवस्था को क्या कहते हैं?","optionsHi":["कक्षा छोड़कर आगे बढ़ाना (ग्रेड स्किपिंग)","समृद्धीकरण","पाठ्यचर्या संक्षेपण","विषय त्वरण"],"explanationHi":"विषय (या विषयवस्तु) त्वरण में छात्र को केवल एक विषय के लिए उच्च कक्षा में रखा जाता है; कक्षा छोड़कर आगे बढ़ाने में उसे सभी विषयों में ऊपर की कक्षा में भेज दिया जाता है, और समृद्धीकरण में आगे बढ़ाए बिना कार्य को गहन बनाया जाता है।"},
  {"id":"cdp-child-development-1506","question":"Francis Galton is associated with which of the following?","options":["Studying eminent families (‘Hereditary Genius’) and popularising ‘nature and nurture’","Developing, with Théodore Simon, the first practical intelligence scale for French schools","Proposing the zone of proximal development to explain learning with adult help","Coining the term emotional intelligence in his studies of social behaviour"],"answer":0,"explanation":"Galton argued, from studies of eminent families, that ability is largely inherited and popularised the ‘nature versus nurture’ phrase; the first practical scale was Binet and Simon’s.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"फ्रांसिस गाल्टन किससे संबंधित हैं?","optionsHi":["प्रख्यात परिवारों का अध्ययन (‘Hereditary Genius’) और ‘प्रकृति और पोषण’ को लोकप्रिय बनाना","थियोडोर साइमन के साथ मिलकर फ्रांसीसी विद्यालयों के लिए पहला व्यावहारिक बुद्धि पैमाना विकसित करना","वयस्क की सहायता से सीखने की व्याख्या के लिए निकटस्थ विकास का क्षेत्र प्रस्तावित करना","सामाजिक व्यवहार के अपने अध्ययनों में भावनात्मक बुद्धि शब्द गढ़ना"],"explanationHi":"गाल्टन ने प्रख्यात परिवारों के अध्ययन के आधार पर तर्क दिया कि योग्यता मुख्यतः वंशानुगत होती है और ‘प्रकृति बनाम पोषण’ वाक्यांश को लोकप्रिय बनाया; पहला व्यावहारिक पैमाना बिने और साइमन का था।"},
  {"id":"cdp-child-development-1507","question":"Identical twins raised together are, on average, more alike in IQ than fraternal twins raised together. Why is this taken as evidence of genetic influence?","options":["Because fraternal twins never share the same home environment as each other","Because identical twins share all their genes and fraternal twins about half, while homes are alike for both","Because identical twins usually attend better schools and receive more attention from their parents at home","Because it proves that IQ is determined entirely by the genes a child inherits"],"answer":1,"explanation":"If environments are similar for both twin types, greater similarity among identical twins points to their greater genetic similarity; it does not mean genes alone decide IQ.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"साथ-साथ पले समरूप जुड़वाँ बच्चे औसतन साथ-साथ पले सहोदर (भ्रातृक) जुड़वाँ बच्चों की तुलना में IQ में अधिक समान होते हैं। इसे आनुवंशिक प्रभाव का प्रमाण क्यों माना जाता है?","optionsHi":["क्योंकि सहोदर जुड़वाँ बच्चे कभी एक-दूसरे के साथ एक जैसा घरेलू वातावरण साझा नहीं करते","क्योंकि समरूप जुड़वाँ बच्चे सभी जीन साझा करते हैं और सहोदर जुड़वाँ लगभग आधे, जबकि घर दोनों के लिए एक जैसे होते हैं","क्योंकि समरूप जुड़वाँ बच्चे प्रायः बेहतर विद्यालयों में पढ़ते हैं और घर पर उन्हें माता-पिता का अधिक ध्यान मिलता है","क्योंकि यह सिद्ध करता है कि IQ पूरी तरह बच्चे को विरासत में मिले जीनों से निर्धारित होता है"],"explanationHi":"यदि दोनों प्रकार के जुड़वाँ बच्चों के लिए वातावरण समान है, तो समरूप जुड़वाँ बच्चों में अधिक समानता उनकी अधिक आनुवंशिक समानता की ओर संकेत करती है; इसका अर्थ यह नहीं कि केवल जीन ही IQ तय करते हैं।"},
  {"id":"cdp-child-development-1508","question":"A private school in Delhi admits children under the RTE quota for economically weaker sections but places them in a separate afternoon section with different activities. Which evaluation is correct?","options":["It is acceptable, since these children need a slower pace and separate attention","It is required by the RTE Act, which says quota admissions must be taught in a separate afternoon section","It segregates and stigmatises them, against the RTE Act’s intent that they learn with other children","It is fine as long as both sections use the same textbooks and the same teachers"],"answer":2,"explanation":"The 25% admission provision aims at social inclusion; segregating admitted children labels them and denies the shared learning the Act intends.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"दिल्ली का एक निजी विद्यालय आर्थिक रूप से कमज़ोर वर्गों के लिए RTE कोटे के अंतर्गत बच्चों को प्रवेश देता है, परंतु उन्हें अलग गतिविधियों वाले एक अलग दोपहर के अनुभाग में रखता है। कौन-सा मूल्यांकन सही है?","optionsHi":["यह स्वीकार्य है, क्योंकि इन बच्चों को धीमी गति और अलग ध्यान की आवश्यकता होती है","RTE अधिनियम में यह अनिवार्य है कि कोटे के प्रवेश वाले बच्चों को अलग दोपहर के अनुभाग में पढ़ाया जाए","यह उन्हें अलग-थलग करता है और कलंकित करता है, जो RTE अधिनियम की उस मंशा के विरुद्ध है कि वे अन्य बच्चों के साथ सीखें","यह तब तक ठीक है जब तक दोनों अनुभागों में समान पाठ्यपुस्तकें और समान शिक्षक हों"],"explanationHi":"25% प्रवेश के प्रावधान का उद्देश्य सामाजिक समावेशन है; प्रवेश पाए बच्चों को अलग करना उन पर ठप्पा लगाता है और अधिनियम द्वारा अपेक्षित साझा अधिगम से उन्हें वंचित करता है।"},
  {"id":"cdp-child-development-1509","question":"Instead of only measuring what a child can do alone, an examiner teaches a strategy during the test and records how much and how quickly the child improves with this help. This approach, associated with Reuven Feuerstein and Vygotskian ideas, is called:","options":["Static assessment","Norm-referenced testing","Summative assessment","Dynamic assessment"],"answer":3,"explanation":"Dynamic assessment measures learning potential through mediated help (the test–teach–retest idea), revealing ability that a one-time static test can underestimate, especially for disadvantaged children.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"केवल यह मापने के बजाय कि बच्चा अकेले क्या कर सकता है, एक परीक्षक परीक्षण के दौरान एक युक्ति सिखाता है और यह दर्ज करता है कि इस सहायता से बच्चे में कितना और कितनी शीघ्रता से सुधार होता है। रियूवेन फ्यूअरस्टीन और वाइगोत्स्की के विचारों से संबंधित इस उपागम को क्या कहते हैं?","optionsHi":["स्थैतिक आकलन","मानक-संदर्भित परीक्षण","योगात्मक आकलन","गत्यात्मक आकलन"],"explanationHi":"गत्यात्मक आकलन मध्यस्थ सहायता (परीक्षण–शिक्षण–पुनःपरीक्षण की अवधारणा) के माध्यम से अधिगम की संभाव्यता को मापता है, और उस योग्यता को प्रकट करता है जिसे एक बार का स्थैतिक परीक्षण कम आँक सकता है, विशेषकर वंचित बच्चों के मामले में।"},
  {"id":"cdp-child-development-1510","question":"After a child solves a hard puzzle, Teacher X says, ‘You are so intelligent!’ while Teacher Y says, ‘You tried different strategies until one worked!’ According to Carol Dweck’s research, which is more likely when the children later meet a much harder puzzle?","options":["Children praised like Teacher X persist longer, as they feel sure of their ability","Both kinds of praise have the same effect, since any praise raises motivation","Children praised like Teacher Y persist more, linking success to effort and strategy","Neither kind of praise matters, since persistence depends only on how hard the puzzle is"],"answer":2,"explanation":"Praising fixed ability encourages a fixed mindset, so failure seems to show low intelligence; praising process supports a growth mindset and persistence after setbacks.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"किसी कठिन पहेली को हल करने के बाद शिक्षक X कहता है, ‘तुम कितने बुद्धिमान हो!’ जबकि शिक्षक Y कहता है, ‘तुमने अलग-अलग युक्तियाँ तब तक आज़माईं जब तक एक काम नहीं कर गई!’ कैरोल ड्वेक के शोध के अनुसार, जब बच्चों का सामना बाद में बहुत कठिन पहेली से होता है तो कौन-सी स्थिति अधिक संभावित है?","optionsHi":["शिक्षक X जैसी प्रशंसा पाने वाले बच्चे अधिक देर तक डटे रहते हैं, क्योंकि उन्हें अपनी योग्यता पर भरोसा होता है","दोनों प्रकार की प्रशंसा का प्रभाव समान होता है, क्योंकि कोई भी प्रशंसा अभिप्रेरणा बढ़ाती है","शिक्षक Y जैसी प्रशंसा पाने वाले बच्चे अधिक डटे रहते हैं, क्योंकि वे सफलता को प्रयास और युक्ति से जोड़ते हैं","किसी भी प्रकार की प्रशंसा मायने नहीं रखती, क्योंकि डटे रहना केवल पहेली की कठिनाई पर निर्भर करता है"],"explanationHi":"स्थिर योग्यता की प्रशंसा स्थिर मानसिकता को बढ़ावा देती है, इसलिए असफलता निम्न बुद्धि का प्रमाण लगती है; प्रक्रिया की प्रशंसा विकासशील मानसिकता और असफलताओं के बाद भी डटे रहने में सहायक होती है।"},
  {"id":"cdp-child-development-1511","question":"A school grades every test ‘on the curve’, so that a fixed share of students always gets the lowest grade. Which is the strongest criticism of this practice?","options":["Some students must get a low grade even if all have mastered the content, so grades show rank, not learning","It makes grading too easy for the teacher, who no longer has to read answers carefully","It gives too many high grades, since the curve always pushes everyone’s marks upwards","It cannot be used for large classes, where so many marks cannot be arranged in order"],"answer":0,"explanation":"Forced norm-referenced grading guarantees ‘failures’ regardless of actual achievement and fosters competition; criterion-referenced reporting shows what each student has learned.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"एक विद्यालय प्रत्येक परीक्षा को ‘वक्र पर’ (कर्व पर) ग्रेड देता है, जिससे छात्रों का एक निश्चित हिस्सा सदैव सबसे निचला ग्रेड पाता है। इस प्रथा की सबसे सशक्त आलोचना कौन-सी है?","optionsHi":["यदि सभी ने विषयवस्तु में निपुणता पा ली हो तब भी कुछ छात्रों को निम्न ग्रेड मिलना ही है, इसलिए ग्रेड अधिगम नहीं बल्कि श्रेणी (रैंक) दर्शाते हैं","इससे शिक्षक के लिए ग्रेड देना बहुत आसान हो जाता है, क्योंकि उसे उत्तर ध्यान से पढ़ने की आवश्यकता नहीं रहती","यह बहुत अधिक उच्च ग्रेड देता है, क्योंकि वक्र सदैव सभी के अंकों को ऊपर धकेल देता है","इसका प्रयोग बड़ी कक्षाओं में नहीं किया जा सकता, जहाँ इतने सारे अंकों को क्रम में नहीं रखा जा सकता"],"explanationHi":"बाध्यकारी मानक-संदर्भित ग्रेडिंग वास्तविक उपलब्धि की परवाह किए बिना ‘असफल’ विद्यार्थियों की गारंटी देती है और प्रतिस्पर्धा को बढ़ावा देती है; मानदंड-संदर्भित प्रतिवेदन दर्शाता है कि प्रत्येक छात्र ने क्या सीखा है।"},
  {"id":"cdp-child-development-1512","question":"Vygotsky found that young children’s ‘egocentric’ speech dropped sharply when they were placed among children who could not understand them (for example, deaf children or speakers of another language). What did he conclude?","options":["Egocentric speech is purely a sign of immature, self-centred thinking that fades with age","Egocentric speech is social in origin and still depends on listeners, even as it guides the child’s thinking","Children simply stop speaking when they are bored or are placed among unfamiliar classmates","Language develops independently of any social setting, through inner maturation alone"],"answer":1,"explanation":"If the speech were purely egocentric, an audience would not matter; its decline without understanding listeners showed Vygotsky that it is social speech on its way to becoming inner speech.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"वाइगोत्स्की ने पाया कि छोटे बच्चों की ‘अहंकेंद्रित’ वाणी तब तेज़ी से घट गई जब उन्हें ऐसे बच्चों के बीच रखा गया जो उन्हें समझ नहीं सकते थे (उदाहरण के लिए, बधिर बच्चे या अन्य भाषा बोलने वाले)। उन्होंने क्या निष्कर्ष निकाला?","optionsHi":["अहंकेंद्रित वाणी केवल अपरिपक्व, स्वकेंद्रित चिंतन का चिह्न है जो आयु के साथ लुप्त हो जाती है","अहंकेंद्रित वाणी मूल रूप से सामाजिक है और श्रोताओं पर निर्भर रहती है, भले ही वह बच्चे के चिंतन का मार्गदर्शन करती हो","बच्चे ऊब जाने पर या अपरिचित सहपाठियों के बीच रखे जाने पर बस बोलना बंद कर देते हैं","भाषा किसी भी सामाजिक परिवेश से स्वतंत्र होकर केवल आंतरिक परिपक्वता से विकसित होती है"],"explanationHi":"यदि वाणी केवल अहंकेंद्रित होती, तो श्रोता का होना मायने नहीं रखता; समझने वाले श्रोताओं के बिना उसमें कमी आने से वाइगोत्स्की ने जाना कि यह सामाजिक वाणी है जो आंतरिक वाणी बनने की ओर अग्रसर है।"},
  {"id":"cdp-child-development-1513","question":"In Piaget’s theory, the emergence of language in the pre-operational stage is seen as:","options":["The single cause of all later cognitive development, including concrete operations","Unrelated to other changes in thinking, being a separate module that matures on its own","One expression of the broader symbolic function, alongside pretend play and deferred imitation","A result of reinforcement by parents, who reward and repeat the child’s first correctly spoken words"],"answer":2,"explanation":"Piaget saw language as one manifestation of the semiotic or symbolic function, the capacity to represent things mentally, which also appears in pretend play, drawing and deferred imitation.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"पियाजे के सिद्धांत में पूर्व-संक्रियात्मक अवस्था में भाषा के उद्भव को किस रूप में देखा जाता है?","optionsHi":["मूर्त संक्रियाओं सहित बाद के सभी संज्ञानात्मक विकास का एकमात्र कारण","चिंतन में होने वाले अन्य परिवर्तनों से असंबद्ध, एक अलग मॉड्यूल जो स्वयं परिपक्व होता है","व्यापक प्रतीकात्मक कार्य की एक अभिव्यक्ति, जो कल्पनात्मक खेल और विलंबित अनुकरण के साथ-साथ प्रकट होती है","माता-पिता द्वारा पुनर्बलन का परिणाम, जो बच्चे के पहले सही बोले गए शब्दों को पुरस्कृत करते और दोहराते हैं"],"explanationHi":"पियाजे भाषा को लाक्षणिक या प्रतीकात्मक कार्य की एक अभिव्यक्ति मानते थे, अर्थात चीज़ों को मानसिक रूप से निरूपित करने की क्षमता, जो कल्पनात्मक खेल, चित्रांकन और विलंबित अनुकरण में भी प्रकट होती है।"},
  {"id":"cdp-child-development-1514","question":"Assertion (A): Behaviourist principles fully explain how children produce sentences they have never heard before. Reason (R): Behaviourists hold that language is learned through imitation and reinforcement.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"R correctly states the behaviourist view, but imitation and reinforcement cannot account for the endless new sentences children create, which was a central point in Chomsky’s critique.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"अभिकथन (A): व्यवहारवादी सिद्धांत यह पूरी तरह स्पष्ट करते हैं कि बच्चे ऐसे वाक्य कैसे बनाते हैं जो उन्होंने पहले कभी नहीं सुने। कारण (R): व्यवहारवादियों का मानना है कि भाषा अनुकरण और पुनर्बलन से सीखी जाती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"R व्यवहारवादी मत को सही ढंग से बताता है, परंतु अनुकरण और पुनर्बलन उन अनंत नए वाक्यों की व्याख्या नहीं कर सकते जो बच्चे रचते हैं, जो चॉम्स्की की आलोचना का एक केंद्रीय बिंदु था।"},
  {"id":"cdp-child-development-1515","question":"Hindi has separate words for a father’s younger brother (chacha), a father’s elder brother (tau), a mother’s brother (mama) and a father’s sister’s husband (phupha), where English mostly says ‘uncle’. What is the most defensible conclusion?","options":["English speakers cannot understand these family relations because their language lacks the words","Language reflects distinctions a culture values and makes them easy to express, though others can still grasp them","Hindi speakers think more logically than English speakers, because their kinship vocabulary is far more precise and detailed","Vocabulary like this is fixed at birth by the LAD and does not depend on the surrounding culture"],"answer":1,"explanation":"Kinship vocabulary mirrors the social importance of these relations and keeps them salient, a weak relativity effect; English speakers can express the same relations with phrases.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"हिंदी में पिता के छोटे भाई (चाचा), पिता के बड़े भाई (ताऊ), माँ के भाई (मामा) और पिता की बहन के पति (फूफा) के लिए अलग-अलग शब्द हैं, जबकि अंग्रेज़ी में प्रायः ‘uncle’ कहा जाता है। सबसे उचित निष्कर्ष क्या है?","optionsHi":["अंग्रेज़ी भाषी इन पारिवारिक संबंधों को नहीं समझ सकते, क्योंकि उनकी भाषा में ये शब्द नहीं हैं","भाषा उन भेदों को दर्शाती है जिन्हें कोई संस्कृति महत्व देती है और उन्हें व्यक्त करना सरल बना देती है, फिर भी अन्य लोग उन्हें समझ सकते हैं","हिंदी भाषी अंग्रेज़ी भाषियों से अधिक तार्किक सोचते हैं, क्योंकि उनकी नातेदारी की शब्दावली कहीं अधिक सटीक और विस्तृत है","इस प्रकार की शब्दावली जन्म के समय LAD द्वारा निर्धारित होती है और आसपास की संस्कृति पर निर्भर नहीं करती"],"explanationHi":"नातेदारी की शब्दावली इन संबंधों के सामाजिक महत्व को प्रतिबिंबित करती है और उन्हें स्पष्ट बनाए रखती है, जो एक दुर्बल सापेक्षता प्रभाव है; अंग्रेज़ी भाषी उन्हीं संबंधों को वाक्यांशों से व्यक्त कर सकते हैं।"},
  {"id":"cdp-child-development-1516","question":"A teacher conducts a gender audit of a Class 4 EVS textbook. Which set of checks is most relevant?","options":["The number of pages, the size of the font and the quality of the pictures in each chapter","Whether the chapters are arranged in alphabetical order and each one ends with exercises","Only the spelling of women’s names and whether their titles are written correctly","How many women and men appear, in what roles, who takes decisions and whether the language is inclusive"],"answer":3,"explanation":"A gender audit looks at representation, roles, agency and language to find stereotypes and invisibility, which the teacher can then counter in class.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"एक शिक्षक कक्षा 4 की EVS पाठ्यपुस्तक का लैंगिक अंकेक्षण (जेंडर ऑडिट) करता है। कौन-सी जाँचों का समूह सबसे अधिक प्रासंगिक है?","optionsHi":["प्रत्येक अध्याय में पृष्ठों की संख्या, अक्षरों का आकार और चित्रों की गुणवत्ता","क्या अध्याय वर्णानुक्रम में व्यवस्थित हैं और प्रत्येक के अंत में अभ्यास हैं","केवल महिलाओं के नामों की वर्तनी और उनके पदनाम सही लिखे गए हैं या नहीं","कितनी महिलाएँ और पुरुष दिखाई देते हैं, किन भूमिकाओं में, निर्णय कौन लेता है और भाषा समावेशी है या नहीं"],"explanationHi":"लैंगिक अंकेक्षण प्रतिनिधित्व, भूमिकाओं, कर्ता-भाव और भाषा को देखता है ताकि रूढ़िबद्ध धारणाओं और अदृश्यता का पता चले, जिनका शिक्षक फिर कक्षा में प्रतिकार कर सकता है।"},
  {"id":"cdp-child-development-1517","question":"A transgender student joins a Class 9 classroom and some classmates mock her. In the light of the Transgender Persons (Protection of Rights) Act, 2019 and inclusive education principles, the school should:","options":["Advise her to study through correspondence courses so that she avoids further trouble","Ignore the mocking, since classmates will get used to her presence over time","Ask her to dress according to the sex recorded at birth so that she draws less attention","Respect her identity, act firmly against harassment and ensure she takes part equally in all activities"],"answer":3,"explanation":"The 2019 Act prohibits discrimination against transgender persons, including in education; inclusive practice requires a safe, respectful environment, not exclusion or pressure to conform.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 9 में एक ट्रांसजेंडर छात्रा आती है और कुछ सहपाठी उसका मज़ाक उड़ाते हैं। ट्रांसजेंडर व्यक्ति (अधिकारों का संरक्षण) अधिनियम, 2019 और समावेशी शिक्षा के सिद्धांतों के आलोक में, विद्यालय को क्या करना चाहिए?","optionsHi":["उसे पत्राचार पाठ्यक्रमों से पढ़ने की सलाह देनी चाहिए ताकि वह और परेशानी से बच सके","मज़ाक की उपेक्षा करनी चाहिए, क्योंकि समय के साथ सहपाठी उसकी उपस्थिति के आदी हो जाएँगे","उससे कहना चाहिए कि वह जन्म के समय दर्ज लिंग के अनुसार पहनावा रखे ताकि उसकी ओर कम ध्यान जाए","उसकी पहचान का सम्मान करना चाहिए, उत्पीड़न के विरुद्ध दृढ़ता से कार्रवाई करनी चाहिए और सुनिश्चित करना चाहिए कि वह सभी गतिविधियों में समान रूप से भाग ले"],"explanationHi":"2019 का अधिनियम शिक्षा सहित ट्रांसजेंडर व्यक्तियों के साथ भेदभाव का निषेध करता है; समावेशी व्यवहार के लिए सुरक्षित, सम्मानजनक वातावरण आवश्यक है, बहिष्करण या अनुरूप होने का दबाव नहीं।"},
  {"id":"cdp-child-development-1518","question":"Which practice is most likely to reduce test anxiety among Class 8 students?","options":["Announcing that results will be read aloud in rank order to push everyone to work harder","Telling students that this one exam will decide their future, so they take it seriously","Clear criteria in advance, frequent low-stakes practice with feedback, and no public comparison","Increasing surprise tests with heavy penalties so that students stay fully prepared at all times"],"answer":2,"explanation":"Anxiety rises with high stakes, uncertainty and public comparison; transparent expectations and low-stakes practice reduce it and let students show what they know.","difficulty":"moderate","source":"CTET Paper 2 · State TET","questionHi":"कक्षा 8 के छात्रों में परीक्षा-चिंता को कम करने की सबसे अधिक संभावना किस व्यवहार में है?","optionsHi":["यह घोषणा करना कि सभी को अधिक परिश्रम के लिए प्रेरित करने हेतु परिणाम श्रेणी के क्रम में पढ़कर सुनाए जाएँगे","छात्रों से कहना कि यही परीक्षा उनका भविष्य तय करेगी, ताकि वे इसे गंभीरता से लें","पहले से स्पष्ट मानदंड, प्रतिपुष्टि सहित बार-बार कम-जोखिम वाला अभ्यास, और सार्वजनिक तुलना न करना","औचक परीक्षाएँ बढ़ाना और भारी दंड देना ताकि छात्र हर समय पूरी तरह तैयार रहें"],"explanationHi":"चिंता ऊँचे दाँव, अनिश्चितता और सार्वजनिक तुलना के साथ बढ़ती है; पारदर्शी अपेक्षाएँ और कम-जोखिम वाला अभ्यास इसे घटाते हैं और छात्रों को जो आता है वह दिखाने देते हैं।"},
  {"id":"cdp-child-development-1519","question":"Arpit was the top student in his village school. After moving to a highly selective residential school where nearly everyone is very able, his academic self-concept drops, though his ability has not changed. This is known as:","options":["The big-fish-little-pond effect","The Flynn effect of rising IQ","The Pygmalion or expectancy effect","Functional fixedness"],"answer":0,"explanation":"Herbert Marsh’s big-fish-little-pond effect describes how students judge their ability by comparison with classmates, so equally able students have a lower academic self-concept in high-ability schools.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"अर्पित अपने गाँव के विद्यालय का शीर्ष छात्र था। एक अत्यंत चयनात्मक आवासीय विद्यालय में जाने के बाद, जहाँ लगभग सभी बहुत योग्य हैं, उसका शैक्षिक आत्म-संप्रत्यय गिर जाता है, यद्यपि उसकी योग्यता नहीं बदली है। इसे क्या कहते हैं?","optionsHi":["बड़ी मछली-छोटा तालाब प्रभाव","IQ में वृद्धि का फ्लिन प्रभाव","पिग्मेलियन या प्रत्याशा प्रभाव","कार्यात्मक स्थिरता"],"explanationHi":"हर्बर्ट मार्श का बड़ी मछली-छोटा तालाब प्रभाव बताता है कि छात्र अपनी योग्यता का आकलन सहपाठियों से तुलना करके करते हैं, इसलिए समान रूप से योग्य छात्रों का उच्च-योग्यता वाले विद्यालयों में शैक्षिक आत्म-संप्रत्यय निम्न होता है।"},
  {"id":"cdp-child-development-1520","question":"J. P. Guilford’s 1950 presidential address to the American Psychological Association is remembered mainly because it:","options":["Introduced the first group IQ test, used to select army recruits in the First World War","Called attention to creativity as neglected and linked it to divergent thinking, unlike IQ tests","Proved through factor analysis that creativity and intelligence are really one and the same ability","Introduced the term emotional intelligence and argued it matters more than IQ for success"],"answer":1,"explanation":"Guilford argued that psychology had neglected creativity and that IQ tests mainly tap convergent thinking, setting off modern research on divergent thinking.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"जे. पी. गिलफोर्ड का 1950 में अमेरिकन साइकोलॉजिकल एसोसिएशन में अध्यक्षीय भाषण मुख्यतः किसलिए याद किया जाता है?","optionsHi":["इसने पहला समूह IQ परीक्षण प्रस्तुत किया, जिसका प्रयोग प्रथम विश्व युद्ध में सेना की भर्ती के चयन हेतु हुआ","इसने सृजनात्मकता की उपेक्षा की ओर ध्यान दिलाया और उसे IQ परीक्षणों के विपरीत अपसारी चिंतन से जोड़ा","इसने कारक विश्लेषण द्वारा सिद्ध किया कि सृजनात्मकता और बुद्धि वास्तव में एक ही योग्यता हैं","इसने भावनात्मक बुद्धि शब्द प्रस्तुत किया और तर्क दिया कि सफलता के लिए यह IQ से अधिक महत्वपूर्ण है"],"explanationHi":"गिलफोर्ड ने तर्क दिया कि मनोविज्ञान ने सृजनात्मकता की उपेक्षा की है और IQ परीक्षण मुख्यतः अभिसारी चिंतन को ही परखते हैं, जिससे अपसारी चिंतन पर आधुनिक शोध की शुरुआत हुई।"},
  {"id":"cdp-child-development-1521","question":"Under the RPwD Act, 2016, which of the following are measures the government is required to take to promote inclusive education? I. Conducting a survey of school-going children every five years to identify children with disabilities. II. Training and employing teachers, including teachers with disabilities, who are qualified in sign language and Braille. III. Providing books, learning materials and assistive devices free to students with benchmark disabilities up to 18 years. IV. Admitting children with disabilities only to special schools after the age of 14.","options":["I and II only","I, II and III only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"The Act lists periodic surveys, trained teachers (including teachers with disabilities skilled in sign language and Braille) and free learning materials and devices up to 18; compulsory special schooling after 14 is not part of it.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"RPwD अधिनियम, 2016 के अंतर्गत, निम्नलिखित में से कौन-से समावेशी शिक्षा को बढ़ावा देने के लिए सरकार द्वारा आवश्यक रूप से उठाए जाने वाले उपाय हैं? I. दिव्यांग बच्चों की पहचान के लिए प्रत्येक पाँच वर्ष में विद्यालय जाने वाले बच्चों का सर्वेक्षण कराना। II. सांकेतिक भाषा और ब्रेल में योग्य शिक्षकों, जिनमें दिव्यांग शिक्षक भी शामिल हों, को प्रशिक्षित करना और नियुक्त करना। III. बेंचमार्क दिव्यांगता वाले विद्यार्थियों को 18 वर्ष की आयु तक पुस्तकें, अधिगम सामग्री और सहायक उपकरण निःशुल्क उपलब्ध कराना। IV. 14 वर्ष की आयु के बाद दिव्यांग बच्चों को केवल विशेष विद्यालयों में प्रवेश देना।","optionsHi":["केवल I और II","केवल I, II और III","केवल II, III और IV","I, II, III और IV"],"explanationHi":"अधिनियम में आवधिक सर्वेक्षण, प्रशिक्षित शिक्षक (जिनमें सांकेतिक भाषा और ब्रेल में कुशल दिव्यांग शिक्षक भी शामिल हैं) और 18 वर्ष की आयु तक निःशुल्क अधिगम सामग्री व उपकरण सूचीबद्ध हैं; 14 के बाद अनिवार्य विशेष विद्यालयी शिक्षा इसका भाग नहीं है।"},
  {"id":"cdp-child-development-1522","question":"Parents of a Class 9 student with severe dyslexia ask whether he can be exempted from the third language, which he finds extremely hard to read and write. Which statement is correct?","options":["No exemption is possible, since all students must study the same subjects to the same level","Exemption is allowed only if the student moves from the regular school to a special school","The RPwD Act, 2016 lists exemption from second and third language courses among permitted modifications","Exemption is possible only for students who are blind, never for those with specific learning disabilities"],"answer":2,"explanation":"Among suitable modifications in curriculum and examinations, the Act names extra time, a scribe and exemption from second and third language courses, so the request is legitimate.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 9 के एक गंभीर डिस्लेक्सिया वाले छात्र के माता-पिता पूछते हैं कि क्या उसे तीसरी भाषा से छूट मिल सकती है, जिसे पढ़ना-लिखना उसके लिए अत्यंत कठिन है। कौन-सा कथन सही है?","optionsHi":["कोई छूट संभव नहीं है, क्योंकि सभी छात्रों को समान विषय समान स्तर तक पढ़ने होते हैं","छूट तभी दी जाती है जब छात्र नियमित विद्यालय से विशेष विद्यालय में चला जाए","RPwD अधिनियम, 2016 में दूसरी और तीसरी भाषा के पाठ्यक्रमों से छूट को अनुमत परिवर्तनों में सूचीबद्ध किया गया है","छूट केवल दृष्टिबाधित छात्रों के लिए संभव है, विशिष्ट अधिगम अक्षमता वाले छात्रों के लिए कभी नहीं"],"explanationHi":"पाठ्यचर्या और परीक्षाओं में उपयुक्त परिवर्तनों के अंतर्गत अधिनियम अतिरिक्त समय, लेखक (स्क्राइब) और दूसरी व तीसरी भाषा के पाठ्यक्रमों से छूट का उल्लेख करता है, इसलिए यह अनुरोध वैध है।"},
  {"id":"cdp-child-development-1523","question":"A pre-primary teacher is observing 4-year-olds. Which behaviour is part of TYPICAL development and is NOT by itself a reason for concern about autism?","options":["Rarely pointing or showing things to share interest with others","Not responding to her name, though her hearing is normal","Talking aloud to herself while building with blocks","Lining up toys in rows for long periods and becoming upset if they are moved, with no pretend play"],"answer":2,"explanation":"Talking to oneself during play is private speech, which Vygotsky saw as a normal tool for guiding thought; weak joint attention, no response to name and rigid play without pretence are early signs worth discussing.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक पूर्व-प्राथमिक शिक्षिका 4 वर्ष के बच्चों का अवलोकन कर रही है। कौन-सा व्यवहार सामान्य विकास का हिस्सा है और अपने आप में ऑटिज़्म की चिंता का कारण नहीं है?","optionsHi":["दूसरों के साथ रुचि बाँटने के लिए चीज़ों की ओर शायद ही कभी इशारा करना या उन्हें दिखाना","सुनने की क्षमता सामान्य होने पर भी अपना नाम पुकारे जाने पर प्रतिक्रिया न देना","ब्लॉक से निर्माण करते समय स्वयं से ज़ोर-ज़ोर से बात करना","लंबे समय तक खिलौनों को पंक्तियों में सजाना और उन्हें हटाए जाने पर परेशान हो जाना, तथा कोई कल्पनात्मक खेल न होना"],"explanationHi":"खेल के दौरान स्वयं से बात करना निजी वाणी है, जिसे वाइगोत्स्की चिंतन को निर्देशित करने का सामान्य साधन मानते थे; कमज़ोर संयुक्त ध्यान, नाम पर प्रतिक्रिया न देना और कल्पना-रहित कठोर खेल प्रारंभिक संकेत हैं जिन पर चर्चा करना उचित है।"},
  {"id":"cdp-child-development-1524","question":"Assertion (A): A very active 4-year-old in nursery, who runs about and finds it hard to sit through a story, should be considered to have ADHD. Reason (R): For ADHD, the behaviour must be clearly beyond what is expected for the child’s developmental level and must persist across settings.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"High activity and short attention are normal at four; ADHD is considered only when behaviour is excessive for the developmental level and persistent across settings, so A is false and R is true.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): नर्सरी का एक अत्यंत सक्रिय 4 वर्षीय बच्चा, जो इधर-उधर दौड़ता है और कहानी सुनते समय बैठना कठिन पाता है, उसे ADHD वाला माना जाना चाहिए। कारण (R): ADHD के लिए व्यवहार का बच्चे के विकासात्मक स्तर से अपेक्षित व्यवहार से स्पष्ट रूप से अधिक होना और विभिन्न परिवेशों में बने रहना आवश्यक है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"चार वर्ष की आयु में उच्च सक्रियता और कम ध्यान-अवधि सामान्य हैं; ADHD पर तभी विचार किया जाता है जब व्यवहार विकासात्मक स्तर के लिए अत्यधिक हो और विभिन्न परिवेशों में बना रहे, इसलिए A असत्य और R सत्य है।"},
  {"id":"cdp-child-development-1525","question":"Shreya, a Class 4 student with hearing impairment, relies on speech-reading. She has not understood a sentence the teacher has just said. What is the best thing for the teacher to do?","options":["Repeat the same sentence more loudly and slowly, exaggerating every lip movement clearly","Rephrase it in different words, since some words are much harder to read on the lips","Write the whole lesson on the board and stop speaking for the rest of the period","Ask another student to explain it to her later, so the lesson is not interrupted"],"answer":1,"explanation":"Many words look alike or are nearly invisible on the lips, so repeating the same words often fails again; rephrasing offers new visual cues, while extra volume and exaggerated lip movements actually distort speech-reading.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 4 की श्रवण-बाधित छात्रा श्रेया वाक्-पठन (होंठ पढ़ने) पर निर्भर है। शिक्षक ने अभी जो वाक्य कहा, वह उसकी समझ में नहीं आया। शिक्षक के लिए सबसे अच्छा कदम क्या है?","optionsHi":["उसी वाक्य को अधिक ज़ोर से और धीरे दोहराना, प्रत्येक होंठ-गति को स्पष्ट रूप से बढ़ा-चढ़ाकर दिखाना","उसे अलग शब्दों में दोहराना, क्योंकि कुछ शब्दों को होंठों पर पढ़ना बहुत कठिन होता है","पूरा पाठ श्यामपट्ट पर लिख देना और पीरियड के शेष समय बोलना बंद कर देना","किसी अन्य छात्र से कहना कि वह बाद में उसे समझा दे, ताकि पाठ में बाधा न आए"],"explanationHi":"अनेक शब्द होंठों पर एक जैसे दिखते हैं या लगभग अदृश्य होते हैं, इसलिए वही शब्द दोहराने पर प्रायः फिर असफलता मिलती है; दूसरे शब्दों में कहने से नए दृश्य संकेत मिलते हैं, जबकि अधिक आवाज़ और बढ़ा-चढ़ाकर होंठ हिलाना वास्तव में वाक्-पठन को बिगाड़ देता है।"},
  {"id":"cdp-child-development-1526","question":"Govind, a blind Class 2 student, often rocks his body and presses his eyes when he is idle in class. What is the most appropriate response?","options":["Scolding him each time it happens so that he learns the habit is not acceptable","Seating him away from others so that the behaviour is not copied by classmates","Ignoring it completely, since such mannerisms in blind children are permanent and cannot be changed","Keeping him engaged with tactile and auditory tasks and gently teaching other uses for his hands"],"answer":3,"explanation":"Such mannerisms often arise from lack of stimulation; active engagement and gentle redirection work better than punishment, and eye-pressing should be reduced because it can harm the eyes.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 2 का दृष्टिबाधित छात्र गोविंद, जब कक्षा में खाली होता है तो प्रायः अपने शरीर को हिलाता-डुलाता है और आँखें दबाता है। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["हर बार उसे डाँटना ताकि वह सीखे कि यह आदत स्वीकार्य नहीं है","उसे दूसरों से दूर बैठाना ताकि सहपाठी इस व्यवहार की नकल न करें","इसे पूरी तरह अनदेखा करना, क्योंकि दृष्टिबाधित बच्चों में ऐसी आदतें स्थायी होती हैं और बदली नहीं जा सकतीं","उसे स्पर्शीय और श्रव्य कार्यों में व्यस्त रखना और उसके हाथों के अन्य उपयोग धीरे-धीरे सिखाना"],"explanationHi":"ऐसी आदतें प्रायः उद्दीपन की कमी से उत्पन्न होती हैं; दंड की अपेक्षा सक्रिय संलग्नता और कोमल पुनर्निर्देशन बेहतर काम करते हैं, और आँखें दबाने को कम किया जाना चाहिए क्योंकि इससे आँखों को हानि पहुँच सकती है।"},
  {"id":"cdp-child-development-1527","question":"Arun, who has intellectual disability, throws his book whenever a reading task begins. Each time, he is sent out of the room. The teacher’s records show the throwing has increased. What is the best explanation and response?","options":["It lets him escape a task that is too hard; adjust the task, teach him to ask for a break, stop sending him out","He is aggressive by nature, so he should be suspended until his behaviour clearly improves","He wants classmates’ attention, so the whole class should be told to ignore him completely","He dislikes the teacher, so he should be moved to another section with a different teacher"],"answer":0,"explanation":"Looking at what happens before and after a behaviour shows its function; being sent out rewards escape, so the behaviour grows. Matching the task to his level and teaching a replacement behaviour removes the need for it.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"बौद्धिक अक्षमता वाला अरुण जब भी पठन-कार्य शुरू होता है तो अपनी पुस्तक फेंक देता है। हर बार उसे कक्षा से बाहर भेज दिया जाता है। शिक्षक के अभिलेख दर्शाते हैं कि फेंकना बढ़ गया है। सबसे अच्छी व्याख्या और प्रतिक्रिया क्या है?","optionsHi":["इससे वह ऐसे कार्य से बच निकलता है जो उसके लिए बहुत कठिन है; कार्य को समायोजित करें, उसे विराम माँगना सिखाएँ, और उसे बाहर भेजना बंद करें","वह स्वभाव से आक्रामक है, इसलिए जब तक उसका व्यवहार स्पष्ट रूप से न सुधरे उसे निलंबित कर देना चाहिए","वह सहपाठियों का ध्यान चाहता है, इसलिए पूरी कक्षा से कहना चाहिए कि उसे पूरी तरह अनदेखा करें","उसे शिक्षक पसंद नहीं है, इसलिए उसे किसी अन्य शिक्षक वाले दूसरे अनुभाग में भेज देना चाहिए"],"explanationHi":"किसी व्यवहार से पहले और बाद में क्या होता है, इसे देखने से उसका प्रकार्य पता चलता है; बाहर भेजे जाने से बचाव को पुरस्कार मिलता है, इसलिए व्यवहार बढ़ता है। कार्य को उसके स्तर के अनुरूप बनाना और विकल्प-व्यवहार सिखाना उसकी आवश्यकता को समाप्त कर देता है।"},
  {"id":"cdp-child-development-1528","question":"A Class 5 teacher regularly uses Aryan, a gifted student, as an ‘assistant teacher’ to explain lessons to weaker classmates whenever he finishes early. Aryan now seems bored and restless. What is the main concern?","options":["Peer tutoring should never be used in an inclusive class, as it embarrasses weaker students","Aryan should be told to finish his work more slowly so that he does not get restless","Occasional tutoring is fine, but he also needs challenging work at his level, not only a helper’s role","There is no concern, since teaching weaker classmates is always the best form of enrichment for the gifted"],"answer":2,"explanation":"Gifted students have a right to learn something new too; tutoring can be valuable at times, but as a permanent role it replaces their own growth.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 5 का एक शिक्षक नियमित रूप से प्रतिभाशाली छात्र आर्यन को ‘सहायक शिक्षक’ के रूप में प्रयोग करता है, ताकि जब वह जल्दी काम पूरा कर ले तो कमज़ोर सहपाठियों को पाठ समझाए। आर्यन अब ऊबा हुआ और बेचैन दिखता है। मुख्य चिंता क्या है?","optionsHi":["समावेशी कक्षा में सहपाठी-शिक्षण का प्रयोग कभी नहीं किया जाना चाहिए, क्योंकि इससे कमज़ोर छात्र शर्मिंदा होते हैं","आर्यन से कहना चाहिए कि वह अपना काम और धीरे पूरा करे ताकि वह बेचैन न हो","कभी-कभार शिक्षण ठीक है, पर उसे अपने स्तर का चुनौतीपूर्ण कार्य भी चाहिए, केवल सहायक की भूमिका नहीं","कोई चिंता नहीं है, क्योंकि कमज़ोर सहपाठियों को पढ़ाना प्रतिभाशाली बच्चों के लिए सदैव समृद्धीकरण का सर्वोत्तम रूप है"],"explanationHi":"प्रतिभाशाली छात्रों को भी कुछ नया सीखने का अधिकार है; शिक्षण कभी-कभी मूल्यवान हो सकता है, पर स्थायी भूमिका के रूप में वह उनके अपने विकास का स्थान ले लेता है।"},
  {"id":"cdp-child-development-1529","question":"A Class 2 teacher plans an activity, ‘Tell us about your mother and father and what they do’. Two children live in a children’s home and one lives with her grandmother. Which change makes the activity most inclusive?","options":["Excusing those three children from the activity so that they are not made to feel sad","Changing it to ‘Tell us about the people who care for you’, so every child’s family is included","Asking those three children to describe an imaginary family instead, so that they can still take part","Keeping the activity as it is, since most children in the class live with both parents"],"answer":1,"explanation":"Activities that assume one family type exclude children in other situations; a broader framing lets every child take part without being singled out.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 2 की एक शिक्षिका गतिविधि की योजना बनाती है, ‘हमें अपनी माँ और पिता के बारे में बताओ और वे क्या करते हैं’। दो बच्चे बाल गृह में रहते हैं और एक अपनी दादी के साथ रहती है। कौन-सा परिवर्तन गतिविधि को सबसे अधिक समावेशी बनाता है?","optionsHi":["उन तीनों बच्चों को गतिविधि से छूट देना ताकि उन्हें दुख न हो","इसे बदलकर ‘हमें उन लोगों के बारे में बताओ जो तुम्हारी देखभाल करते हैं’ करना, ताकि प्रत्येक बच्चे का परिवार शामिल हो","उन तीनों बच्चों से कहना कि वे इसके बजाय एक काल्पनिक परिवार का वर्णन करें, ताकि वे भी भाग ले सकें","गतिविधि को जैसा है वैसा रखना, क्योंकि कक्षा के अधिकांश बच्चे माता-पिता दोनों के साथ रहते हैं"],"explanationHi":"जो गतिविधियाँ एक ही प्रकार का परिवार मानकर चलती हैं, वे अन्य परिस्थितियों वाले बच्चों को बाहर कर देती हैं; व्यापक ढाँचा हर बच्चे को अलग किए बिना भाग लेने देता है।"},
  {"id":"cdp-child-development-1530","question":"When Rohan, a Class 3 boy, cries after falling in the playground, his teacher says, ‘Boys don’t cry, be a man.’ What is the main problem with this response?","options":["It reinforces a gender stereotype that harms boys too, teaching them to hide their feelings","There is no problem, since such words toughen boys up for life outside the school","The teacher should have said the same to girls too, so that all children are treated equally","The teacher should instead have ignored the boy until he stopped crying by himself"],"answer":0,"explanation":"Gender stereotypes restrict boys as well as girls; telling boys not to show feelings discourages healthy emotional expression.","difficulty":"hard","source":"CTET · State TETs","questionHi":"जब कक्षा 3 का लड़का रोहन खेल के मैदान में गिरकर रोता है तो उसकी शिक्षिका कहती है, ‘लड़के नहीं रोते, मर्द बनो।’ इस प्रतिक्रिया में मुख्य समस्या क्या है?","optionsHi":["यह एक लैंगिक रूढ़ धारणा को पुष्ट करती है जो लड़कों को भी हानि पहुँचाती है, उन्हें भावनाएँ छिपाना सिखाती है","कोई समस्या नहीं है, क्योंकि ऐसे शब्द लड़कों को विद्यालय के बाहर के जीवन के लिए सख़्त बनाते हैं","शिक्षिका को लड़कियों से भी यही कहना चाहिए था ताकि सभी बच्चों के साथ समान व्यवहार हो","शिक्षिका को इसके बजाय लड़के को तब तक अनदेखा करना चाहिए था जब तक वह स्वयं रोना बंद न कर दे"],"explanationHi":"लैंगिक रूढ़ धारणाएँ लड़कियों की तरह लड़कों को भी सीमित करती हैं; लड़कों से भावनाएँ न दिखाने को कहना स्वस्थ भावनात्मक अभिव्यक्ति को हतोत्साहित करता है।"},
  {"id":"cdp-child-development-1531","question":"An English-medium school fines children who speak their mother tongue on the campus. From a child-development point of view, what is the most serious problem?","options":["The fines are too small to change behaviour, so a stricter penalty is needed to make the rule work","Parents may object to paying the fines, which can damage relations between the school and families","It is fine, since full immersion with no use of the home language is the only way to learn English","It signals that their home language is inferior, silences them, and ignores how a strong first language aids a second"],"answer":3,"explanation":"Punishing home languages damages self-esteem and silences children, and first-language strength actually aids second-language learning; multilingualism should be treated as a resource.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"एक अंग्रेज़ी-माध्यम विद्यालय परिसर में मातृभाषा बोलने वाले बच्चों पर जुर्माना लगाता है। बाल विकास की दृष्टि से सबसे गंभीर समस्या क्या है?","optionsHi":["जुर्माने इतने छोटे हैं कि व्यवहार नहीं बदल सकते, इसलिए नियम को कारगर बनाने के लिए कठोर दंड चाहिए","माता-पिता जुर्माना देने पर आपत्ति कर सकते हैं, जिससे विद्यालय और परिवारों के संबंध बिगड़ सकते हैं","यह ठीक है, क्योंकि घर की भाषा के प्रयोग के बिना पूर्ण निमज्जन ही अंग्रेज़ी सीखने का एकमात्र तरीका है","यह संकेत देता है कि उनकी घर की भाषा हीन है, उन्हें चुप करा देता है, और इस बात की अनदेखी करता है कि मज़बूत प्रथम भाषा द्वितीय भाषा सीखने में सहायक होती है"],"explanationHi":"घर की भाषाओं को दंडित करना आत्म-सम्मान को हानि पहुँचाता है और बच्चों को चुप करा देता है, जबकि प्रथम भाषा की मज़बूती वास्तव में द्वितीय भाषा सीखने में सहायक होती है; बहुभाषिकता को संसाधन माना जाना चाहिए।"},
  {"id":"cdp-child-development-1532","question":"Tenzing, a Class 6 student from Sikkim, is repeatedly called ‘Chinese’ by classmates in a Delhi school. What should the teacher do?","options":["Tell Tenzing to ignore it, since the classmates are only joking and mean no real harm","Stop the name-calling, make clear racist remarks are unacceptable, and teach the class about India’s diversity","Seat Tenzing with other students from the North-East so that he feels more at home in class","Wait until the parents complain, since remarks among students are outside the teacher’s role"],"answer":1,"explanation":"Racial and regional slurs are discrimination that the teacher must address directly, along with building awareness of India's diversity; ignoring or segregating places the burden on the victim.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"सिक्किम का कक्षा 6 का छात्र तेनज़िंग दिल्ली के एक विद्यालय में सहपाठियों द्वारा बार-बार ‘चाइनीज़’ कहा जाता है। शिक्षक को क्या करना चाहिए?","optionsHi":["तेनज़िंग से कहना कि वह इसे अनदेखा करे, क्योंकि सहपाठी केवल मज़ाक कर रहे हैं और उनका कोई वास्तविक बुरा इरादा नहीं है","नाम पुकारना बंद करवाना, स्पष्ट करना कि नस्लीय टिप्पणियाँ अस्वीकार्य हैं, और कक्षा को भारत की विविधता के बारे में सिखाना","तेनज़िंग को पूर्वोत्तर के अन्य छात्रों के साथ बैठाना ताकि वह कक्षा में अधिक सहज महसूस करे","माता-पिता के शिकायत करने तक प्रतीक्षा करना, क्योंकि छात्रों के बीच की टिप्पणियाँ शिक्षक की भूमिका से बाहर हैं"],"explanationHi":"नस्लीय और क्षेत्रीय अपमानजनक शब्द भेदभाव हैं जिन्हें शिक्षक को सीधे संबोधित करना चाहिए, साथ ही भारत की विविधता के प्रति जागरूकता भी बढ़ानी चाहिए; अनदेखा करने या अलग बैठाने से बोझ पीड़ित पर आ जाता है।"},
  {"id":"cdp-child-development-1533","question":"A teacher realises that, for the same quality of answer, she tends to give higher marks to students whose families she sees as ‘well-educated’. Which step best reduces this bias?","options":["Marking students from poorer families more leniently to balance out the bias","Asking students to write their parents’ occupation on the answer sheet for reference","Marking with a clear rubric and, where possible, without seeing the student’s name","Letting the class monitor do the marking, since students do not have such biases"],"answer":2,"explanation":"Expectation bias in marking is reduced by fixed criteria applied blind to identity; lenient marking for one group is another form of bias.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक शिक्षिका को एहसास होता है कि उत्तर की समान गुणवत्ता के लिए वह उन छात्रों को अधिक अंक देती है जिनके परिवार वह ‘सुशिक्षित’ मानती है। इस पूर्वाग्रह को कम करने के लिए कौन-सा कदम सर्वोत्तम है?","optionsHi":["संतुलन बनाने के लिए गरीब परिवारों के छात्रों को अधिक उदारता से अंक देना","छात्रों से कहना कि संदर्भ के लिए उत्तर-पुस्तिका पर अपने माता-पिता का व्यवसाय लिखें","स्पष्ट रूब्रिक के साथ और जहाँ संभव हो छात्र का नाम देखे बिना अंक देना","कक्षा के मॉनिटर को अंक देने देना, क्योंकि छात्रों में ऐसे पूर्वाग्रह नहीं होते"],"explanationHi":"अंकन में अपेक्षा-जनित पूर्वाग्रह को पहचान से अनभिज्ञ रहकर लागू किए गए निश्चित मानदंडों से कम किया जाता है; किसी एक समूह को उदारता से अंक देना पूर्वाग्रह का ही दूसरा रूप है।"},
  {"id":"cdp-child-development-1534","question":"Which phrase about a Class 5 student reflects respectful, person-first language?","options":["‘She is a student who uses a wheelchair.’","‘She is wheelchair-bound and needs help.’","‘She suffers from a physical disability.’","‘She is a handicapped student in my class.’"],"answer":0,"explanation":"Person-first language puts the child before the condition and describes it neutrally; ‘bound’, ‘suffers’ and ‘handicapped’ suggest tragedy or limitation.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 5 की एक छात्रा के बारे में कौन-सा वाक्यांश सम्मानजनक, व्यक्ति-प्रथम भाषा को दर्शाता है?","optionsHi":["‘वह एक छात्रा है जो व्हीलचेयर का उपयोग करती है।’","‘वह व्हीलचेयर से बंधी है और उसे सहायता चाहिए।’","‘वह शारीरिक अक्षमता से पीड़ित है।’","‘वह मेरी कक्षा की एक विकलांग छात्रा है।’"],"explanationHi":"व्यक्ति-प्रथम भाषा बच्चे को उसकी स्थिति से पहले रखती है और उसका तटस्थ वर्णन करती है; ‘बंधी’, ‘पीड़ित’ और ‘विकलांग’ शब्द त्रासदी या सीमा का आभास देते हैं।"},
  {"id":"cdp-child-development-1535","question":"Assertion (A): Letting a Class 7 student with dyslexia listen to an audiobook of the prescribed story for the literature lesson is a form of cheating. Reason (R): The goals of the literature lesson are understanding and appreciating the story, not decoding print.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Since the goal is comprehension and appreciation, an audiobook removes the decoding barrier while keeping the goal; it is an accommodation, not cheating, so A is false and R is true.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अभिकथन (A): डिस्लेक्सिया वाले कक्षा 7 के छात्र को साहित्य के पाठ के लिए निर्धारित कहानी का ऑडियोबुक सुनने देना धोखाधड़ी का एक रूप है। कारण (R): साहित्य के पाठ का लक्ष्य कहानी को समझना और उसकी सराहना करना है, मुद्रित सामग्री को डीकोड करना नहीं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"चूँकि लक्ष्य बोध और सराहना है, ऑडियोबुक लक्ष्य को बनाए रखते हुए डीकोडिंग की बाधा को हटा देता है; यह एक सुविधा (अनुकूलन) है, धोखाधड़ी नहीं, इसलिए A असत्य और R सत्य है।"},
  {"id":"cdp-child-development-1536","question":"Amit, a Class 6 student with dysgraphia, writes correct scientific explanations but with many spelling errors and untidy work. In the science test, how should his answers be marked?","options":["Deducting heavily for spelling, since correct spelling is part of every subject","Marking his scientific content against the science criteria and supporting spelling separately","Giving him full marks for every answer so that he is not discouraged by his writing difficulty","Asking him to rewrite the whole test neatly before it is marked by the teacher"],"answer":1,"explanation":"Assessment should measure the intended learning; penalising a disability-related writing difficulty in a science test measures the barrier, not his science knowledge.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 6 का डिस्ग्राफिया वाला छात्र अमित सही वैज्ञानिक व्याख्याएँ लिखता है, परंतु बहुत-सी वर्तनी की त्रुटियों और अस्वच्छ कार्य के साथ। विज्ञान की परीक्षा में उसके उत्तरों का मूल्यांकन कैसे किया जाना चाहिए?","optionsHi":["वर्तनी के लिए भारी अंक काटना, क्योंकि सही वर्तनी हर विषय का हिस्सा होती है","उसकी वैज्ञानिक विषयवस्तु को विज्ञान के मानदंडों पर आँकना और वर्तनी में सहायता अलग से देना","हर उत्तर के पूरे अंक देना ताकि उसकी लेखन-कठिनाई के कारण वह हतोत्साहित न हो","शिक्षक द्वारा जाँचे जाने से पहले उससे पूरी परीक्षा साफ़-सुथरी लिखकर दोबारा लिखवाना"],"explanationHi":"आकलन को इच्छित अधिगम को मापना चाहिए; विज्ञान की परीक्षा में अक्षमता से जुड़ी लेखन-कठिनाई पर अंक काटना बाधा को मापता है, उसके विज्ञान-ज्ञान को नहीं।"},
  {"id":"cdp-child-development-1537","question":"Which classroom job is likely to suit Chirag, a Class 3 child with ADHD, best?","options":["Distributing and collecting notebooks, which lets him move with a purpose","Copying the timetable neatly into every notebook to practise careful work","Sitting at the door as ‘silence monitor’ to learn to control his movements","Keeping a written record of late-comers all day to build responsibility"],"answer":0,"explanation":"Purposeful movement channels restlessness constructively and builds responsibility; long sedentary or detail-heavy jobs work against his difficulties.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"ADHD वाले कक्षा 3 के बच्चे चिराग के लिए कक्षा का कौन-सा कार्य सबसे उपयुक्त होने की संभावना है?","optionsHi":["कॉपियाँ बाँटना और इकट्ठा करना, जिससे उसे उद्देश्यपूर्वक चलने-फिरने का अवसर मिलता है","समय-सारणी को प्रत्येक कॉपी में सावधानी से उतारना, ताकि वह सावधानीपूर्वक काम करने का अभ्यास करे","द्वार पर ‘शांति-निरीक्षक’ बनकर बैठना, ताकि वह अपनी गतिविधियों पर नियंत्रण करना सीखे","पूरे दिन देर से आने वालों का लिखित रिकॉर्ड रखना, ताकि उसमें ज़िम्मेदारी विकसित हो"],"explanationHi":"उद्देश्यपूर्ण गति बेचैनी को रचनात्मक दिशा देती है और ज़िम्मेदारी विकसित करती है; लंबे समय तक बैठकर करने वाले या बारीकी वाले कार्य उसकी कठिनाइयों के विपरीत पड़ते हैं।"},
  {"id":"cdp-child-development-1538","question":"In group projects, Mira, an autistic Class 6 student, either takes over or withdraws because she is unsure what to do. Which support is most helpful?","options":["Giving her a card that sets out her role, the task steps and when each part is due","Telling the group to manage her as best they can, as it builds their patience","Letting her work alone on every project so that she never feels stressed in a group","Putting her in the group with the most talkative students to draw her out of herself"],"answer":0,"explanation":"Unclear social expectations are hard for many autistic learners; an explicit role and steps make group work predictable and let her contribute.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"समूह परियोजनाओं में, कक्षा 6 की ऑटिस्टिक छात्रा मीरा या तो सब कुछ अपने हाथ में ले लेती है या पीछे हट जाती है क्योंकि उसे पता नहीं होता कि क्या करना है। कौन-सी सहायता सबसे उपयोगी है?","optionsHi":["उसे एक कार्ड देना जिसमें उसकी भूमिका, कार्य के चरण और प्रत्येक भाग की समय-सीमा लिखी हो","समूह से कहना कि वे उसे जैसे बने सँभालें, क्योंकि इससे उनमें धैर्य बढ़ता है","उसे हर परियोजना में अकेले काम करने देना ताकि वह समूह में कभी तनाव महसूस न करे","उसे सबसे बातूनी छात्रों वाले समूह में रखना ताकि वह अपने खोल से बाहर आए"],"explanationHi":"अस्पष्ट सामाजिक अपेक्षाएँ अनेक ऑटिस्टिक अधिगमकर्ताओं के लिए कठिन होती हैं; स्पष्ट भूमिका और चरण समूह-कार्य को पूर्वानुमेय बनाते हैं और उसे योगदान देने में सक्षम करते हैं।"},
  {"id":"cdp-child-development-1539","question":"A school has both a class teacher and a resource teacher for children with disabilities. Which way of working is most inclusive?","options":["The resource teacher takes the children out of class for all subjects, giving them focused one-to-one help","The resource teacher works only with the parents, guiding them on support at home","The class teacher sends the children to the resource room whenever they fall behind","Both teachers plan and teach together in the regular class, with brief pull-outs only if needed"],"answer":3,"explanation":"Co-teaching keeps children learning with peers while bringing specialist expertise into the regular class; routine pull-out recreates segregation within the school.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक विद्यालय में कक्षा शिक्षक और दिव्यांग बच्चों के लिए एक संसाधन शिक्षक दोनों हैं। कार्य करने का कौन-सा तरीका सबसे अधिक समावेशी है?","optionsHi":["संसाधन शिक्षक बच्चों को सभी विषयों के लिए कक्षा से बाहर ले जाता है और उन्हें केंद्रित एक-से-एक सहायता देता है","संसाधन शिक्षक केवल माता-पिता के साथ काम करता है और उन्हें घर पर सहायता के बारे में मार्गदर्शन देता है","कक्षा शिक्षक बच्चों को जब भी वे पिछड़ें संसाधन कक्ष में भेज देता है","दोनों शिक्षक नियमित कक्षा में साथ मिलकर योजना बनाते और पढ़ाते हैं, आवश्यकता होने पर ही संक्षिप्त रूप से बच्चों को बाहर ले जाया जाता है"],"explanationHi":"सह-शिक्षण बच्चों को साथियों के साथ सीखते रखता है और विशेषज्ञता को नियमित कक्षा में लाता है; नियमित रूप से बाहर ले जाना विद्यालय के भीतर ही पृथक्करण को फिर से पैदा करता है।"},
  {"id":"cdp-child-development-1540","question":"Riya, a Class 1 child with a language delay, points and says, ‘Ball fall.’ Which teacher response best supports her language development?","options":["‘No, say it properly.’","Ignoring it until she speaks in a full sentence","‘Yes, the ball fell down. Where did it go?’","‘Ball fall? That is wrong.’"],"answer":2,"explanation":"Expanding the child's words into a correct, slightly fuller model, without criticism, and continuing the conversation, supports language growth; correction and ignoring discourage her from speaking.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"भाषा-विलंब वाली कक्षा 1 की बच्ची रिया इशारा करके कहती है, ‘Ball fall.’ शिक्षक की कौन-सी प्रतिक्रिया उसके भाषा विकास में सबसे अधिक सहायक है?","optionsHi":["‘नहीं, ठीक से बोलो।’","तब तक अनदेखा करना जब तक वह पूरे वाक्य में न बोले","‘हाँ, गेंद नीचे गिर गई। वह कहाँ गई?’","‘Ball fall? यह गलत है।’"],"explanationHi":"बच्चे के शब्दों को सही और थोड़ा अधिक पूर्ण रूप में विस्तारित करना, बिना आलोचना के और बातचीत जारी रखते हुए, भाषा के विकास में सहायक होता है; सुधारना और अनदेखा करना उसे बोलने से हतोत्साहित करते हैं।"},
  {"id":"cdp-child-development-1541","question":"Assertion (A): A child with a cochlear implant hears exactly like her hearing classmates and needs no support in class. Reason (R): A cochlear implant gives access to sound, but listening remains effortful, especially in noisy rooms.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Implants do not create typical hearing; noise, distance and fatigue still matter, so quiet rooms, visual support and good seating remain important. A is false, R is true.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): कॉक्लियर इम्प्लांट वाली बच्ची अपनी सुनने वाली सहपाठियों की तरह ही सुनती है और उसे कक्षा में किसी सहायता की आवश्यकता नहीं है। कारण (R): कॉक्लियर इम्प्लांट ध्वनि तक पहुँच देता है, परंतु सुनना श्रमसाध्य बना रहता है, विशेषकर शोरगुल वाले कमरों में।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"इम्प्लांट सामान्य श्रवण उत्पन्न नहीं करते; शोर, दूरी और थकान अब भी मायने रखते हैं, इसलिए शांत कक्ष, दृश्य सहायता और उचित बैठक-व्यवस्था महत्वपूर्ण बनी रहती हैं। A असत्य है, R सत्य है।"},
  {"id":"cdp-child-development-1542","question":"During a brainstorming session on ‘how to reduce plastic in our school’, which teacher behaviour best encourages creative thinking?","options":["Correcting every unusual idea immediately so that no time is wasted on poor ones","Recording all ideas without judging them, and evaluating only after many have been collected","Asking only the toppers for ideas, since they are the most likely to give good ones","Giving the class the textbook answer before they begin, so they have a correct model to follow"],"answer":1,"explanation":"Separating idea generation from evaluation allows fluency and originality to grow; early criticism makes students stick to safe, conventional answers.","difficulty":"hard","source":"CTET · State TETs","questionHi":"‘हमारे विद्यालय में प्लास्टिक कैसे कम करें’ विषय पर विचार-मंथन सत्र के दौरान शिक्षक का कौन-सा व्यवहार सृजनात्मक चिंतन को सबसे अच्छा प्रोत्साहित करता है?","optionsHi":["हर असामान्य विचार को तुरंत सुधारना ताकि कमज़ोर विचारों पर समय नष्ट न हो","सभी विचारों को बिना आँके दर्ज करना, और अनेक विचार इकट्ठा हो जाने के बाद ही उनका मूल्यांकन करना","केवल अव्वल छात्रों से विचार पूछना, क्योंकि उनके अच्छे विचार देने की संभावना सबसे अधिक होती है","शुरू करने से पहले कक्षा को पाठ्यपुस्तक का उत्तर दे देना, ताकि उनके पास अनुसरण के लिए सही नमूना हो"],"explanationHi":"विचार-सृजन को मूल्यांकन से अलग रखने पर प्रवाह और मौलिकता बढ़ती है; शीघ्र आलोचना छात्रों को सुरक्षित, रूढ़िगत उत्तरों तक सीमित कर देती है।"},
  {"id":"cdp-child-development-1543","question":"To ‘avoid crowding’, a school gives its children with disabilities a separate lunch break, 20 minutes before everyone else. What is the main problem with this arrangement?","options":["Twenty minutes is too short for lunch, so the break should be made longer for them","It is subtle segregation that cuts these children off from social time with peers, central to inclusion","It is unfair to the other children, who must then wait longer and have less time to eat and play together","There is no problem, since all children still get lunch and the crowding is avoided"],"answer":1,"explanation":"Inclusion covers social life, not just lessons; separate break times deny friendship and belonging, so needs such as crowding should be handled within shared time.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"‘भीड़ से बचने’ के लिए एक विद्यालय अपने दिव्यांग बच्चों को बाकी सब से 20 मिनट पहले अलग भोजनावकाश देता है। इस व्यवस्था में मुख्य समस्या क्या है?","optionsHi":["भोजन के लिए बीस मिनट बहुत कम हैं, इसलिए उनके लिए अवकाश लंबा किया जाना चाहिए","यह सूक्ष्म पृथक्करण है जो इन बच्चों को साथियों के साथ सामाजिक समय से काट देता है, जो समावेशन के लिए केंद्रीय है","यह अन्य बच्चों के प्रति अन्याय है, जिन्हें फिर अधिक प्रतीक्षा करनी पड़ती है और खाने व साथ खेलने का समय कम मिलता है","कोई समस्या नहीं है, क्योंकि सभी बच्चों को भोजन फिर भी मिलता है और भीड़ से बचाव हो जाता है"],"explanationHi":"समावेशन में केवल पाठ ही नहीं, सामाजिक जीवन भी आता है; अलग अवकाश-समय मित्रता और अपनेपन से वंचित करता है, इसलिए भीड़ जैसी आवश्यकताओं को साझा समय के भीतर ही सँभाला जाना चाहिए।"},
  {"id":"cdp-child-development-1544","question":"For maths word problems, a Class 4 teacher reads each problem aloud, shows a picture of the situation and uses simple, consistent wording. Which statement about this practice is most accurate?","options":["It applies UDL’s representation principle, helping many, such as learners with dyslexia or new to the language","It helps only children with dyslexia, so it should be limited to them to avoid slowing down the other learners","It makes the problems easier and therefore lowers the standard expected in Class 4 mathematics","It applies UDL’s engagement principle, since pictures make maths more fun for the class"],"answer":0,"explanation":"Presenting content in several forms reduces barriers of reading and language without changing the maths being assessed, which is UDL's representation principle and benefits many learners.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"गणित के शाब्दिक प्रश्नों के लिए कक्षा 4 की शिक्षिका प्रत्येक प्रश्न को ज़ोर से पढ़ती है, स्थिति का चित्र दिखाती है और सरल, एकरूप शब्दावली का प्रयोग करती है। इस प्रथा के बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["यह UDL के निरूपण सिद्धांत को लागू करती है, जो डिस्लेक्सिया वाले या भाषा में नए अधिगमकर्ताओं जैसे अनेक विद्यार्थियों की सहायता करता है","यह केवल डिस्लेक्सिया वाले बच्चों की सहायता करती है, इसलिए इसे केवल उन्हीं तक सीमित रखना चाहिए ताकि अन्य अधिगमकर्ताओं की गति धीमी न हो","यह प्रश्नों को आसान बना देती है और इसलिए कक्षा 4 के गणित के लिए अपेक्षित स्तर को घटा देती है","यह UDL के संलग्नता सिद्धांत को लागू करती है, क्योंकि चित्र गणित को कक्षा के लिए अधिक रोचक बना देते हैं"],"explanationHi":"विषयवस्तु को अनेक रूपों में प्रस्तुत करना, आँके जा रहे गणित को बदले बिना, पठन और भाषा की बाधाओं को कम करता है; यह UDL का निरूपण सिद्धांत है और अनेक अधिगमकर्ताओं को लाभ पहुँचाता है।"},
  {"id":"cdp-child-development-1545","question":"A Class 7 teacher sets homework that needs internet searches and coloured printouts. Several first-generation learners from low-income homes regularly fail to submit it. What is the best response?","options":["Penalising late submissions so that all students learn to take their homework seriously","Asking these students to use a cyber café or a neighbour’s phone to complete the work","Redesigning homework so all can do it with resources at home, with school access for any tech tasks","Excusing these students from all homework for the year, since their homes cannot support such work at all"],"answer":2,"explanation":"Homework that depends on resources some homes lack measures access, not learning; designing for available resources and offering school access keeps expectations equal and fair.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 7 का एक शिक्षक ऐसा गृहकार्य देता है जिसके लिए इंटरनेट पर खोज और रंगीन प्रिंटआउट चाहिए। कम आय वाले घरों के कई प्रथम-पीढ़ी के अधिगमकर्ता उसे नियमित रूप से जमा नहीं कर पाते। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["देर से जमा करने पर दंडित करना ताकि सभी छात्र अपने गृहकार्य को गंभीरता से लेना सीखें","इन छात्रों से कहना कि काम पूरा करने के लिए साइबर कैफ़े या पड़ोसी के फ़ोन का उपयोग करें","गृहकार्य को इस प्रकार पुनः डिज़ाइन करना कि सभी उसे घर के संसाधनों से कर सकें, और तकनीकी कार्यों के लिए विद्यालय में पहुँच उपलब्ध हो","इन छात्रों को पूरे वर्ष सभी गृहकार्य से छूट देना, क्योंकि उनके घर ऐसे कार्य का बिल्कुल समर्थन नहीं कर सकते"],"explanationHi":"जो गृहकार्य ऐसे संसाधनों पर निर्भर है जो कुछ घरों में नहीं हैं, वह अधिगम नहीं बल्कि पहुँच को मापता है; उपलब्ध संसाधनों के अनुसार डिज़ाइन करना और विद्यालय में पहुँच देना अपेक्षाओं को समान और निष्पक्ष बनाए रखता है।"},
  {"id":"cdp-child-development-1546","question":"Many students in Ms. Kaur’s Class 6 section do not submit homework. If she tackles this through action research, her first step should be to:","options":["Frame a broad hypothesis about homework habits in all Indian schools and then test it","Punish the defaulters firmly so that the problem stops at once and others take note","Identify and define the problem precisely (who, which homework, how often) using her class data","Read international studies on homework and apply their conclusions directly to her own Class 6 section"],"answer":2,"explanation":"Action research starts by identifying and sharply defining a problem in the practitioner’s own setting; broad hypotheses and borrowed conclusions come before the problem is even understood.","difficulty":"moderate","source":"CTET · KVS PRT","questionHi":"सुश्री कौर की कक्षा 6 के अनुभाग के कई छात्र गृहकार्य जमा नहीं करते। यदि वे इसका समाधान क्रियात्मक अनुसंधान से करती हैं, तो उनका पहला चरण होना चाहिए:","optionsHi":["सभी भारतीय विद्यालयों में गृहकार्य की आदतों के बारे में एक व्यापक परिकल्पना बनाना और फिर उसका परीक्षण करना","चूककर्ताओं को कठोर दंड देना ताकि समस्या तुरंत रुके और अन्य सबक लें","अपनी कक्षा के आँकड़ों से समस्या को स्पष्ट रूप से पहचानना और परिभाषित करना (कौन, कौन-सा गृहकार्य, कितनी बार)","गृहकार्य पर अंतरराष्ट्रीय अध्ययनों को पढ़ना और उनके निष्कर्षों को सीधे अपने कक्षा 6 के अनुभाग पर लागू करना"],"explanationHi":"क्रियात्मक अनुसंधान की शुरुआत व्यवसायी के अपने परिवेश में किसी समस्या की पहचान और उसकी स्पष्ट परिभाषा से होती है; व्यापक परिकल्पनाएँ और उधार लिए निष्कर्ष तब आते हैं जब समस्या समझी भी नहीं गई होती।"},
  {"id":"cdp-child-development-1547","question":"Which is the best example of an action hypothesis?","options":["‘If I set homework linked to daily life and give brief feedback next day, submission in my Class 6 will rise.’","‘Homework is useful for children and should be given regularly in every class at school.’","‘Children from poor families do less homework than other children all over India.’","‘There is a relationship between the amount of homework and children’s intelligence.’"],"answer":0,"explanation":"An action hypothesis names a specific action the teacher will take and the expected improvement in her own situation, so it can be tried and checked; the others are vague beliefs or general research questions.","difficulty":"hard","source":"CTET Paper II · DSSSB TGT","questionHi":"क्रियात्मक परिकल्पना का सर्वश्रेष्ठ उदाहरण कौन-सा है?","optionsHi":["‘यदि मैं दैनिक जीवन से जुड़ा गृहकार्य दूँ और अगले दिन संक्षिप्त प्रतिपुष्टि दूँ, तो मेरी कक्षा 6 में गृहकार्य जमा करने की दर बढ़ेगी।’","‘गृहकार्य बच्चों के लिए उपयोगी है और विद्यालय की हर कक्षा में नियमित रूप से दिया जाना चाहिए।’","‘गरीब परिवारों के बच्चे पूरे भारत में अन्य बच्चों की तुलना में कम गृहकार्य करते हैं।’","‘गृहकार्य की मात्रा और बच्चों की बुद्धि के बीच संबंध है।’"],"explanationHi":"क्रियात्मक परिकल्पना शिक्षक द्वारा की जाने वाली किसी विशिष्ट कार्रवाई और उसकी अपनी स्थिति में अपेक्षित सुधार को बताती है, ताकि उसे आज़माया और जाँचा जा सके; अन्य विकल्प अस्पष्ट मान्यताएँ या सामान्य शोध-प्रश्न हैं।"},
  {"id":"cdp-child-development-1548","question":"Which feature distinguishes action research from fundamental research?","options":["It uses large random samples so that its results can be generalised to all schools","It is carried out mainly by university experts who visit schools to collect data for their own studies","It aims to build universal theories of learning that hold across all classrooms","It is done by practitioners to improve their own practice in one setting, not to generalise widely"],"answer":3,"explanation":"Fundamental research seeks generalisable theory through rigorous sampling; action research is practitioner-led, local and aimed at immediate improvement.","difficulty":"moderate","source":"CTET · State TET","questionHi":"कौन-सी विशेषता क्रियात्मक अनुसंधान को मौलिक अनुसंधान से अलग करती है?","optionsHi":["यह बड़े यादृच्छिक प्रतिदर्शों का उपयोग करता है ताकि इसके परिणाम सभी विद्यालयों पर सामान्यीकृत किए जा सकें","यह मुख्यतः विश्वविद्यालय के विशेषज्ञों द्वारा किया जाता है जो अपने अध्ययनों के लिए आँकड़े एकत्र करने विद्यालयों में जाते हैं","इसका उद्देश्य अधिगम के ऐसे सार्वभौमिक सिद्धांत बनाना है जो सभी कक्षाओं में लागू हों","यह व्यवसायियों द्वारा एक ही परिवेश में अपनी कार्य-पद्धति सुधारने के लिए किया जाता है, व्यापक सामान्यीकरण के लिए नहीं"],"explanationHi":"मौलिक अनुसंधान कठोर प्रतिचयन द्वारा सामान्यीकरण योग्य सिद्धांत खोजता है; क्रियात्मक अनुसंधान व्यवसायी-प्रेरित, स्थानीय और तात्कालिक सुधार पर केंद्रित होता है।"},
  {"id":"cdp-child-development-1549","question":"Arrange these steps of action research in order: P. Carry out the planned action. Q. Identify and define the problem. R. Analyse probable causes and frame action hypotheses. S. Evaluate the results and reflect, revising the plan if needed.","options":["Q, P, R, S","Q, R, P, S","R, Q, P, S","Q, R, S, P"],"answer":1,"explanation":"The problem is identified first, causes are analysed and action hypotheses framed, the action is carried out, and finally its effect is evaluated, which may start a new cycle.","difficulty":"hard","source":"CTET · KVS TGT","questionHi":"क्रियात्मक अनुसंधान के इन चरणों को क्रम में व्यवस्थित कीजिए: P. नियोजित कार्रवाई करना। Q. समस्या की पहचान करना और उसे परिभाषित करना। R. संभावित कारणों का विश्लेषण करना और क्रियात्मक परिकल्पनाएँ बनाना। S. परिणामों का मूल्यांकन करना और चिंतन करना, आवश्यकता हो तो योजना में संशोधन करना।","optionsHi":["Q, P, R, S","Q, R, P, S","R, Q, P, S","Q, R, S, P"],"explanationHi":"पहले समस्या की पहचान होती है, कारणों का विश्लेषण और क्रियात्मक परिकल्पनाओं का निर्माण होता है, कार्रवाई की जाती है, और अंत में उसके प्रभाव का मूल्यांकन होता है, जिससे नया चक्र शुरू हो सकता है।"},
  {"id":"cdp-child-development-1550","question":"After trying peer reading for six weeks, Mr. Das finds only partial improvement in his Class 4 students’ reading fluency. Within action research, he should:","options":["End the study and declare the idea a failure for all schools","Publish the result as a general law of reading","Reflect on the evidence, modify the plan and begin another cycle","Give up reading practice altogether and try a different subject instead"],"answer":2,"explanation":"Action research is cyclical (plan, act, observe, reflect); partial success is evidence for revising the action in the next cycle, not a final verdict.","difficulty":"hard","source":"CTET Paper I · State TET","questionHi":"छह सप्ताह तक सहपाठी-पठन आज़माने के बाद श्री दास पाते हैं कि उनकी कक्षा 4 के छात्रों की पठन-प्रवाहिता में केवल आंशिक सुधार हुआ है। क्रियात्मक अनुसंधान के अंतर्गत उन्हें क्या करना चाहिए?","optionsHi":["अध्ययन समाप्त कर देना और इस विचार को सभी विद्यालयों के लिए असफल घोषित कर देना","परिणाम को पठन के सामान्य नियम के रूप में प्रकाशित करना","प्रमाणों पर चिंतन करना, योजना में संशोधन करना और एक और चक्र शुरू करना","पठन-अभ्यास पूरी तरह छोड़ देना और इसके बजाय किसी अन्य विषय को आज़माना"],"explanationHi":"क्रियात्मक अनुसंधान चक्रीय है (योजना, कार्रवाई, अवलोकन, चिंतन); आंशिक सफलता अगले चक्र में कार्रवाई को संशोधित करने का प्रमाण है, अंतिम निर्णय नहीं।"},
  {"id":"cdp-child-development-1551","question":"Assertion (A): Action research is usually not meant to produce generalisations valid for all schools. Reason (R): It is carried out with a small, specific group in a particular context, often without random sampling or control of variables.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because action research studies one teacher’s class without random sampling or controls, its findings serve that setting; this is exactly why it does not aim at wide generalisation.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"अभिकथन (A): क्रियात्मक अनुसंधान का उद्देश्य सामान्यतः ऐसे सामान्यीकरण उत्पन्न करना नहीं होता जो सभी विद्यालयों पर मान्य हों। कारण (R): यह किसी विशेष संदर्भ में एक छोटे, विशिष्ट समूह के साथ किया जाता है, प्रायः बिना यादृच्छिक प्रतिचयन या चरों के नियंत्रण के।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"क्योंकि क्रियात्मक अनुसंधान एक शिक्षक की कक्षा का अध्ययन बिना यादृच्छिक प्रतिचयन या नियंत्रण के करता है, इसके निष्कर्ष उसी परिवेश के काम आते हैं; यही कारण है कि इसका लक्ष्य व्यापक सामान्यीकरण नहीं होता।"},
  {"id":"cdp-child-development-1552","question":"Which pairing about the origins of action research is correct?","options":["Kurt Lewin brought action research into school education; Stephen Corey coined the term","Kurt Lewin coined ‘action research’; Stephen M. Corey popularised it in education","B. F. Skinner coined the term; Jean Piaget later applied it to schools","John Dewey coined the term in the 1990s; Corey then applied it to classrooms"],"answer":1,"explanation":"The social psychologist Kurt Lewin introduced action research in the 1940s; Stephen M. Corey popularised it among teachers in the 1950s. Option A swaps their roles.","difficulty":"hard","source":"CTET · KVS TGT","questionHi":"क्रियात्मक अनुसंधान की उत्पत्ति के बारे में कौन-सा युग्म सही है?","optionsHi":["कर्ट लेविन ने क्रियात्मक अनुसंधान को विद्यालयी शिक्षा में लाया; स्टीफन कोरी ने यह शब्द गढ़ा","कर्ट लेविन ने ‘क्रियात्मक अनुसंधान’ शब्द गढ़ा; स्टीफन एम. कोरी ने शिक्षा में इसे लोकप्रिय बनाया","बी. एफ. स्किनर ने यह शब्द गढ़ा; जीन पियाजे ने बाद में इसे विद्यालयों पर लागू किया","जॉन डेवी ने 1990 के दशक में यह शब्द गढ़ा; कोरी ने फिर इसे कक्षाओं पर लागू किया"],"explanationHi":"सामाजिक मनोवैज्ञानिक कर्ट लेविन ने 1940 के दशक में क्रियात्मक अनुसंधान की शुरुआत की; स्टीफन एम. कोरी ने 1950 के दशक में इसे शिक्षकों के बीच लोकप्रिय बनाया। विकल्प A में उनकी भूमिकाएँ आपस में बदल दी गई हैं।"},
  {"id":"cdp-child-development-1553","question":"While explaining fractions with a drawing of a roti, a teacher notices puzzled faces and immediately switches to folding paper strips. That evening she writes in her diary about why the first explanation failed. These are, respectively:","options":["Reflection-on-action and reflection-in-action","Reflection-for-action and reflection-on-action","Reflection-in-action and reflection-on-action","Routine action and reflection-for-action"],"answer":2,"explanation":"In Donald Schön’s terms, adjusting during the lesson is reflection-in-action; thinking back over it afterwards is reflection-on-action.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT","questionHi":"रोटी के चित्र से भिन्न समझाते समय एक शिक्षिका को उलझे हुए चेहरे दिखते हैं और वह तुरंत कागज़ की पट्टियों को मोड़ने पर आ जाती है। उसी शाम वह अपनी डायरी में लिखती है कि पहली व्याख्या क्यों असफल रही। ये क्रमशः क्या हैं?","optionsHi":["कार्रवाई-पश्चात चिंतन और कार्रवाई-के-दौरान चिंतन","कार्रवाई-पूर्व चिंतन और कार्रवाई-पश्चात चिंतन","कार्रवाई-के-दौरान चिंतन और कार्रवाई-पश्चात चिंतन","नियमित कार्रवाई और कार्रवाई-पूर्व चिंतन"],"explanationHi":"डोनाल्ड शॉन की शब्दावली में, पाठ के दौरान समायोजन करना कार्रवाई-के-दौरान चिंतन है; बाद में उस पर विचार करना कार्रवाई-पश्चात चिंतन है।"},
  {"id":"cdp-child-development-1554","question":"Before starting a new unit, a teacher reviews last year’s notes on where children struggled and plans activities to avoid those problems. This is best called:","options":["Reflection-for-action","Reflection-in-action","Routine, habitual action","Summative evaluation"],"answer":0,"explanation":"Reflection-for-action looks ahead, using past reflection to plan future teaching; reflection-in-action happens during teaching itself.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"नई इकाई शुरू करने से पहले एक शिक्षक पिछले वर्ष के उन नोट्स की समीक्षा करता है जिनमें बच्चों को कठिनाई हुई थी, और उन समस्याओं से बचने के लिए गतिविधियाँ योजित करता है। इसे सबसे उपयुक्त रूप में क्या कहा जाएगा?","optionsHi":["कार्रवाई-पूर्व चिंतन","कार्रवाई-के-दौरान चिंतन","नियमित, आदतन कार्रवाई","योगात्मक मूल्यांकन"],"explanationHi":"कार्रवाई-पूर्व चिंतन आगे की ओर देखता है, और भविष्य के शिक्षण की योजना बनाने के लिए पिछले चिंतन का उपयोग करता है; कार्रवाई-के-दौरान चिंतन शिक्षण के समय ही होता है।"},
  {"id":"cdp-child-development-1555","question":"To examine her teaching critically, a teacher recalls her own experiences as a learner, collects anonymous feedback from students, invites a colleague to observe her, and reads research on the topic. She is using:","options":["Kolb’s four-stage cycle of experiential learning","Bloom’s taxonomy of educational objectives","Gagné’s nine events of instruction in sequence","Brookfield’s four lenses of critical reflection"],"answer":3,"explanation":"Stephen Brookfield’s four lenses are the autobiographical lens, students’ eyes, colleagues’ perceptions and theoretical literature; using all four checks a teacher’s assumptions.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"अपने शिक्षण की आलोचनात्मक जाँच के लिए एक शिक्षिका अधिगमकर्ता के रूप में अपने अनुभवों को याद करती है, छात्रों से अनाम प्रतिपुष्टि एकत्र करती है, एक सहकर्मी को अपनी कक्षा देखने के लिए आमंत्रित करती है, और विषय पर शोध पढ़ती है। वह किसका उपयोग कर रही है?","optionsHi":["कोल्ब का अनुभवात्मक अधिगम का चार-चरणीय चक्र","ब्लूम का शैक्षिक उद्देश्यों का वर्गीकरण","गेने की अनुदेशन की नौ घटनाएँ क्रम से","ब्रुकफ़ील्ड के आलोचनात्मक चिंतन के चार लेंस"],"explanationHi":"स्टीफन ब्रुकफ़ील्ड के चार लेंस हैं: आत्मकथात्मक लेंस, छात्रों की दृष्टि, सहकर्मियों की धारणाएँ और सैद्धांतिक साहित्य; चारों का उपयोग शिक्षक की मान्यताओं की जाँच करता है।"},
  {"id":"cdp-child-development-1556","question":"A teacher tries group work, notices that several students sit idle, concludes that groups need clearly assigned roles, and next day tries assigning roles. In Kolb’s experiential learning cycle, ‘concluding that groups need clearly assigned roles’ is the stage of:","options":["Concrete experience","Abstract conceptualisation","Reflective observation","Active experimentation"],"answer":1,"explanation":"Kolb’s cycle runs from concrete experience (trying group work) to reflective observation (noticing idle students), abstract conceptualisation (forming the general idea about roles) and active experimentation (trying roles).","difficulty":"hard","source":"KVS TGT · DSSSB TGT","questionHi":"एक शिक्षक समूह-कार्य आज़माता है, देखता है कि कई छात्र निष्क्रिय बैठे हैं, निष्कर्ष निकालता है कि समूहों को स्पष्ट रूप से सौंपी गई भूमिकाएँ चाहिए, और अगले दिन भूमिकाएँ सौंपकर आज़माता है। कोल्ब के अनुभवात्मक अधिगम चक्र में, ‘यह निष्कर्ष निकालना कि समूहों को स्पष्ट रूप से सौंपी गई भूमिकाएँ चाहिए’ किस चरण का है?","optionsHi":["मूर्त अनुभव","अमूर्त संप्रत्ययीकरण","चिंतनशील अवलोकन","सक्रिय प्रयोग"],"explanationHi":"कोल्ब का चक्र मूर्त अनुभव (समूह-कार्य आज़माना) से चिंतनशील अवलोकन (निष्क्रिय छात्रों को देखना), अमूर्त संप्रत्ययीकरण (भूमिकाओं के बारे में सामान्य विचार बनाना) और सक्रिय प्रयोग (भूमिकाएँ आज़माना) तक चलता है।"},
  {"id":"cdp-child-development-1557","question":"A new teacher keeps a reflective journal. For it to support her professional growth, most entries should:","options":["List the topics covered each day, so that a full record of her teaching is kept","Record complaints about students and the administration to release her stress","Describe key classroom events, analyse why they happened and consider what to try next","Copy lesson plans from the teachers’ guide so that her daily planning becomes faster and neater"],"answer":2,"explanation":"A reflective journal is useful when it moves from description to analysis to planning; mere logs, complaints or copied plans involve no reflection.","difficulty":"moderate","source":"CTET · State TET","questionHi":"एक नई शिक्षिका चिंतनशील जर्नल रखती है। उसके व्यावसायिक विकास में सहायक होने के लिए, अधिकांश प्रविष्टियाँ क्या होनी चाहिए?","optionsHi":["प्रतिदिन पढ़ाए गए विषयों की सूची, ताकि उसके शिक्षण का पूरा अभिलेख रहे","छात्रों और प्रशासन के बारे में शिकायतें दर्ज करना, ताकि उसका तनाव कम हो","प्रमुख कक्षा-घटनाओं का वर्णन, वे क्यों घटीं इसका विश्लेषण और आगे क्या आज़माना है इस पर विचार","शिक्षक-मार्गदर्शिका से पाठ-योजनाएँ उतारना, ताकि उसकी दैनिक योजना तेज़ और व्यवस्थित हो जाए"],"explanationHi":"चिंतनशील जर्नल तब उपयोगी होती है जब वह वर्णन से विश्लेषण और फिर योजना तक पहुँचे; केवल लेखा-जोखा, शिकायतें या उतारी हुई योजनाएँ चिंतन नहीं हैं।"},
  {"id":"cdp-child-development-1558","question":"A teacher asks herself, ‘Why do the children from the nearby basti always sit at the back and rarely speak? Do my practices or the school’s norms silence them?’ In Van Manen’s levels of reflection, this is:","options":["Critical reflection, which examines equity, power and justice in practice","Technical reflection about efficient means to reach fixed classroom goals","Not reflection at all, since it concerns social issues rather than teaching","Reflection-in-action, since she is adjusting the lesson as she teaches"],"answer":0,"explanation":"Van Manen distinguishes technical, practical and critical reflection; questioning how practices and norms affect fairness for marginalised children is the critical level.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"एक शिक्षिका स्वयं से पूछती है, ‘पास की बस्ती के बच्चे हमेशा पीछे क्यों बैठते हैं और बहुत कम बोलते हैं? क्या मेरी कार्य-पद्धतियाँ या विद्यालय के मानदंड उन्हें चुप करा देते हैं?’ वैन मैनन के चिंतन के स्तरों में, यह क्या है?","optionsHi":["आलोचनात्मक चिंतन, जो व्यवहार में समता, शक्ति और न्याय की जाँच करता है","तकनीकी चिंतन, जो कक्षा के निश्चित लक्ष्यों तक पहुँचने के कुशल साधनों के बारे में होता है","चिंतन है ही नहीं, क्योंकि यह शिक्षण के बजाय सामाजिक मुद्दों से संबंधित है","कार्रवाई-के-दौरान चिंतन, क्योंकि वह पढ़ाते समय पाठ को समायोजित कर रही है"],"explanationHi":"वैन मैनन तकनीकी, व्यावहारिक और आलोचनात्मक चिंतन में भेद करते हैं; यह प्रश्न करना कि कार्य-पद्धतियाँ और मानदंड हाशिये के बच्चों के प्रति निष्पक्षता को कैसे प्रभावित करते हैं, आलोचनात्मक स्तर है।"},
  {"id":"cdp-child-development-1559","question":"Ms. Rao is doing action research on improving girls’ participation in her Class 7 science discussions. Which data source is LEAST appropriate for her study?","options":["A tally of who speaks in each discussion over four weeks","Short interviews with some girls about what holds them back in class","Her own observation notes after each class","National data on women’s enrolment in university science courses"],"answer":3,"explanation":"Action research needs evidence from the teacher’s own setting; national university data says nothing about what is happening in her class or whether her action works.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"सुश्री राव अपनी कक्षा 7 की विज्ञान-चर्चाओं में लड़कियों की भागीदारी सुधारने पर क्रियात्मक अनुसंधान कर रही हैं। उनके अध्ययन के लिए कौन-सा आँकड़ा-स्रोत सबसे कम उपयुक्त है?","optionsHi":["चार सप्ताह तक हर चर्चा में कौन बोलता है, इसकी गणना","कुछ लड़कियों से इस बारे में संक्षिप्त साक्षात्कार कि कक्षा में उन्हें क्या रोकता है","प्रत्येक कक्षा के बाद उनके अपने अवलोकन-नोट्स","विश्वविद्यालयों के विज्ञान पाठ्यक्रमों में महिलाओं के नामांकन के राष्ट्रीय आँकड़े"],"explanationHi":"क्रियात्मक अनुसंधान को शिक्षक के अपने परिवेश से प्रमाण चाहिए; विश्वविद्यालयों के राष्ट्रीय आँकड़े इस बारे में कुछ नहीं बताते कि उसकी कक्षा में क्या हो रहा है या उसकी कार्रवाई कारगर है या नहीं।"},
  {"id":"cdp-child-development-1560","question":"Which of these statements about action research are correct? I. It can be collaborative, involving several teachers of a school. II. It needs a control group and random sampling to be valid. III. Its success is judged by improvement in the practitioner’s own situation. IV. It treats the teacher as a researcher, not just a consumer of research.","options":["I and II only","II and III only","I, III and IV only","I, II, III and IV"],"answer":2,"explanation":"Action research may be individual or collaborative, aims at local improvement and positions teachers as researchers; it does not require control groups or random sampling, so II is false.","difficulty":"very-hard","source":"CTET · DSSSB TGT","questionHi":"क्रियात्मक अनुसंधान के बारे में इनमें से कौन-से कथन सही हैं? I. यह सहयोगात्मक हो सकता है, जिसमें विद्यालय के कई शिक्षक शामिल हों। II. वैध होने के लिए इसमें नियंत्रण समूह और यादृच्छिक प्रतिचयन चाहिए। III. इसकी सफलता का निर्णय व्यवसायी की अपनी स्थिति में सुधार से होता है। IV. यह शिक्षक को अनुसंधान का केवल उपभोक्ता नहीं, बल्कि अनुसंधानकर्ता मानता है।","optionsHi":["केवल I और II","केवल II और III","केवल I, III और IV","I, II, III और IV"],"explanationHi":"क्रियात्मक अनुसंधान व्यक्तिगत या सहयोगात्मक हो सकता है, स्थानीय सुधार का लक्ष्य रखता है और शिक्षकों को अनुसंधानकर्ता के रूप में स्थापित करता है; इसमें नियंत्रण समूह या यादृच्छिक प्रतिचयन आवश्यक नहीं, इसलिए II असत्य है।"},
  {"id":"cdp-child-development-1561","question":"The idea of the ‘teacher as researcher’, associated with Lawrence Stenhouse, holds that:","options":["Only university experts should research teaching, and teachers should simply apply their findings","Teachers should systematically study their own classrooms to test and improve curriculum ideas","Teachers should avoid changing their practice once they have completed their training","Research has no place in schools, where the teacher’s task is only to teach the syllabus"],"answer":1,"explanation":"Stenhouse argued that curriculum proposals are hypotheses that teachers should test in their own classrooms; this underlies classroom-based action research.","difficulty":"hard","source":"KVS PGT · DSSSB TGT","questionHi":"लॉरेंस स्टेनहाउस से जुड़ी ‘शिक्षक अनुसंधानकर्ता के रूप में’ की अवधारणा का मानना है कि:","optionsHi":["केवल विश्वविद्यालय के विशेषज्ञों को शिक्षण पर अनुसंधान करना चाहिए, और शिक्षकों को उनके निष्कर्ष बस लागू करने चाहिए","शिक्षकों को अपनी कक्षाओं का व्यवस्थित अध्ययन करना चाहिए ताकि पाठ्यचर्या संबंधी विचारों का परीक्षण और सुधार हो सके","प्रशिक्षण पूरा करने के बाद शिक्षकों को अपनी कार्य-पद्धति बदलने से बचना चाहिए","विद्यालयों में अनुसंधान का कोई स्थान नहीं है, जहाँ शिक्षक का कार्य केवल पाठ्यक्रम पढ़ाना है"],"explanationHi":"स्टेनहाउस ने तर्क दिया कि पाठ्यचर्या संबंधी प्रस्ताव परिकल्पनाएँ हैं जिन्हें शिक्षकों को अपनी कक्षाओं में परखना चाहिए; यही कक्षा-आधारित क्रियात्मक अनुसंधान का आधार है।"},
  {"id":"cdp-child-development-1562","question":"Two Class 4 teachers observe each other’s mathematics lessons and discuss what they noticed, without giving any grades. This practice mainly supports:","options":["Collaborative reflection and professional learning","Inspection of lessons leading to disciplinary action","Ranking of teachers for the annual school report","Summative evaluation of teachers for promotion"],"answer":0,"explanation":"Non-judgemental peer observation gives each teacher a colleague’s lens on her practice; once grades are attached it becomes inspection and teachers stop being open.","difficulty":"moderate","source":"CTET · KVS PRT","questionHi":"कक्षा 4 के दो शिक्षक एक-दूसरे के गणित के पाठ देखते हैं और बिना कोई ग्रेड दिए यह चर्चा करते हैं कि उन्होंने क्या देखा। यह प्रथा मुख्यतः किसमें सहायक है?","optionsHi":["सहयोगात्मक चिंतन और व्यावसायिक अधिगम","पाठों का निरीक्षण जिससे अनुशासनात्मक कार्रवाई हो","वार्षिक विद्यालय रिपोर्ट के लिए शिक्षकों की श्रेणी निर्धारित करना","पदोन्नति के लिए शिक्षकों का योगात्मक मूल्यांकन"],"explanationHi":"निर्णय-रहित सहपाठी अवलोकन प्रत्येक शिक्षक को अपनी कार्य-पद्धति पर सहकर्मी का दृष्टिकोण देता है; ग्रेड जुड़ते ही यह निरीक्षण बन जाता है और शिक्षक खुलकर बात करना बंद कर देते हैं।"},
  {"id":"cdp-child-development-1563","question":"Assertion (A): A teacher who has used the same methods for 20 years necessarily has 20 years of reflective experience. Reason (R): Experience becomes learning only when it is reflected upon and used to change practice.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"By R’s own logic, unexamined repetition may amount to one year’s experience repeated twenty times; years of service do not by themselves make reflective practice, so A is false.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"अभिकथन (A): जिस शिक्षक ने 20 वर्ष तक वही विधियाँ अपनाई हैं, उसके पास अनिवार्यतः 20 वर्ष का चिंतनशील अनुभव है। कारण (R): अनुभव तभी अधिगम बनता है जब उस पर चिंतन किया जाए और उसका उपयोग कार्य-पद्धति बदलने में हो।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"R के ही तर्क से, बिना जाँचे दोहराव एक वर्ष के अनुभव को बीस बार दोहराने के बराबर हो सकता है; सेवा के वर्ष अपने आप में चिंतनशील अभ्यास नहीं बनाते, इसलिए A असत्य है।"},
  {"id":"cdp-child-development-1564","question":"Which question best shows reflective teaching rather than self-justification?","options":["‘Why can’t these students ever pay attention like last year’s batch did?’","‘I taught it well; they just didn’t study at home as I told them to.’","‘What in my lesson made it hard for some to follow, and what is my evidence?’","‘How can I finish the syllabus faster so that more time is left for revision?’"],"answer":2,"explanation":"Reflection examines one’s own practice using evidence; blaming students or focusing only on coverage avoids looking at the teaching itself.","difficulty":"moderate","source":"CTET · State TET","questionHi":"कौन-सा प्रश्न आत्म-औचित्य के बजाय चिंतनशील शिक्षण को सबसे अच्छी तरह दर्शाता है?","optionsHi":["‘ये छात्र पिछले वर्ष के बैच की तरह कभी ध्यान क्यों नहीं देते?’","‘मैंने तो अच्छा पढ़ाया; उन्होंने ही घर पर नहीं पढ़ा जैसा मैंने कहा था।’","‘मेरे पाठ में ऐसा क्या था जिससे कुछ को समझना कठिन हुआ, और मेरे पास इसका क्या प्रमाण है?’","‘मैं पाठ्यक्रम और जल्दी कैसे पूरा करूँ ताकि पुनरावृत्ति के लिए अधिक समय बचे?’"],"explanationHi":"चिंतन प्रमाणों के सहारे अपनी ही कार्य-पद्धति की जाँच करता है; छात्रों को दोष देना या केवल पाठ्यक्रम पूरा करने पर ध्यान देना शिक्षण को ही देखने से बचना है।"},
  {"id":"cdp-child-development-1565","question":"Which is the most suitable problem for an action research project by a Class 3 teacher?","options":["The effect of socio-economic status on the IQ of children across India","How to improve the reading of the six children in my class who confuse ‘b’ and ‘d’","A history of primary education policy in India since independence","A comparison of the school systems of India and Finland in the 2020s"],"answer":1,"explanation":"Action research problems are specific, local, within the teacher’s control and aimed at immediate improvement; the others are large-scale or historical research topics.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"कक्षा 3 की शिक्षिका के क्रियात्मक अनुसंधान परियोजना के लिए सबसे उपयुक्त समस्या कौन-सी है?","optionsHi":["पूरे भारत में बच्चों के IQ पर सामाजिक-आर्थिक स्थिति का प्रभाव","मेरी कक्षा के उन छह बच्चों का पठन कैसे सुधारूँ जो ‘b’ और ‘d’ में भ्रमित होते हैं","स्वतंत्रता के बाद से भारत में प्राथमिक शिक्षा नीति का इतिहास","2020 के दशक में भारत और फ़िनलैंड की विद्यालयी प्रणालियों की तुलना"],"explanationHi":"क्रियात्मक अनुसंधान की समस्याएँ विशिष्ट, स्थानीय, शिक्षक के नियंत्रण में और तात्कालिक सुधार के लक्ष्य वाली होती हैं; अन्य बड़े पैमाने के या ऐतिहासिक अनुसंधान-विषय हैं।"},
  {"id":"cdp-child-development-1566","question":"At the end of each week a teacher hands out anonymous slips asking for ‘one thing that helped me and one thing that confused me’. This is mainly a tool for:","options":["Seeing her teaching through students’ eyes to inform her reflection","Grading the students on how well they have understood the week’s work","Identifying and disciplining students who complain about her lessons","Ranking her teaching against her colleagues’ for the annual review"],"answer":0,"explanation":"Anonymous student feedback gives the ‘students’ eyes’ lens on teaching and helps the teacher check her assumptions about what is working.","difficulty":"hard","source":"CTET · KVS TGT","questionHi":"प्रत्येक सप्ताह के अंत में एक शिक्षिका अनाम पर्चियाँ बाँटती है जिनमें ‘एक बात जिसने मेरी मदद की और एक बात जिसने मुझे उलझाया’ पूछा जाता है। यह मुख्यतः किसका उपकरण है?","optionsHi":["अपने शिक्षण को छात्रों की दृष्टि से देखना ताकि उसके चिंतन को दिशा मिले","सप्ताह के कार्य को छात्रों ने कितना समझा, इस पर उन्हें ग्रेड देना","उन छात्रों की पहचान करके उन्हें अनुशासित करना जो उसके पाठों की शिकायत करते हैं","वार्षिक समीक्षा के लिए उसके शिक्षण को सहकर्मियों से तुलनात्मक श्रेणी देना"],"explanationHi":"अनाम छात्र-प्रतिपुष्टि शिक्षण पर ‘छात्रों की दृष्टि’ का लेंस देती है और शिक्षिका को इस बारे में अपनी धारणाओं की जाँच करने में सहायता करती है कि क्या कारगर है।"},
  {"id":"cdp-child-development-1567","question":"Mr. Iqbal uses maths games for four weeks, and his Class 5’s test average rises from 52 to 61. Before concluding that the games caused the improvement, a reflective teacher-researcher would MOST need to consider that:","options":["Students’ own feedback on whether they enjoyed the games is the best proof of effect","Four weeks is too short, so only a full year of games could show a real effect","The gain should be checked separately for high and low scorers to see who gained","Other factors, such as an easier second test or extra revision, may explain the rise"],"answer":3,"explanation":"A causal claim needs alternative explanations ruled out, such as test difficulty or extra revision. Running the games longer or splitting the gains by group still leaves those rival causes unexamined, and enjoyment is not evidence of learning.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"श्री इक़बाल चार सप्ताह तक गणित के खेलों का उपयोग करते हैं, और उनकी कक्षा 5 का परीक्षण-औसत 52 से बढ़कर 61 हो जाता है। यह निष्कर्ष निकालने से पहले कि खेलों के कारण सुधार हुआ, एक चिंतनशील शिक्षक-अनुसंधानकर्ता को सबसे अधिक किस बात पर विचार करना चाहिए?","optionsHi":["खेलों का आनंद आया या नहीं, इस पर छात्रों की अपनी प्रतिपुष्टि प्रभाव का सबसे अच्छा प्रमाण है","चार सप्ताह बहुत कम हैं, इसलिए केवल पूरे वर्ष के खेल ही वास्तविक प्रभाव दिखा सकते हैं","उच्च और निम्न अंक पाने वालों के लिए लाभ की अलग-अलग जाँच होनी चाहिए कि किसे लाभ हुआ","अन्य कारक, जैसे दूसरा परीक्षण आसान होना या अतिरिक्त पुनरावृत्ति, वृद्धि की व्याख्या कर सकते हैं"],"explanationHi":"कारण-संबंधी दावे के लिए वैकल्पिक व्याख्याओं को अलग करना ज़रूरी है, जैसे परीक्षण की कठिनाई या अतिरिक्त पुनरावृत्ति। खेलों को अधिक समय तक चलाने या लाभ को समूहों में बाँटने से भी वे प्रतिद्वंद्वी कारण अनजाँचे रह जाते हैं, और आनंद अधिगम का प्रमाण नहीं है।"},
  {"id":"cdp-child-development-1568","question":"In an action research project with her own students, which practice is ethically appropriate?","options":["Publishing students’ names and scores without permission","Deliberately withholding help from a ‘control’ group of weak students for a whole term to compare","Informing students and parents, keeping data confidential and ensuring no child is disadvantaged","Recording the class on video and sharing it on social media to showcase the project"],"answer":2,"explanation":"Research with children requires informed consent, confidentiality and no harm; denying weak students help for the sake of a comparison is unethical in a teacher’s own class.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"अपने ही छात्रों के साथ क्रियात्मक अनुसंधान परियोजना में कौन-सी प्रथा नैतिक रूप से उपयुक्त है?","optionsHi":["छात्रों के नाम और अंक बिना अनुमति के प्रकाशित करना","तुलना के लिए कमज़ोर छात्रों के ‘नियंत्रण’ समूह को पूरे सत्र तक जानबूझकर सहायता न देना","छात्रों और अभिभावकों को सूचित करना, आँकड़ों को गोपनीय रखना और यह सुनिश्चित करना कि किसी बच्चे को हानि न हो","कक्षा की वीडियो रिकॉर्डिंग करना और परियोजना को दिखाने के लिए उसे सोशल मीडिया पर साझा करना"],"explanationHi":"बच्चों के साथ अनुसंधान में सूचित सहमति, गोपनीयता और अहानि आवश्यक है; शिक्षक की अपनी कक्षा में तुलना के लिए कमज़ोर छात्रों को सहायता से वंचित करना अनैतिक है।"},
  {"id":"cdp-child-development-1569","question":"NCF 2005 and NEP 2020 both expect teachers to be reflective practitioners. Which is the best example?","options":["Following the textbook page by page every year, since the board has approved it and parents expect it","Revising a lesson on ‘our food’ after noticing it left out tribal students’ foods, and inviting them to share","Using the same question paper every year so that standards stay consistent","Avoiding any change in her methods unless the principal or a visiting inspector specifically instructs her to"],"answer":1,"explanation":"Reflective practice means noticing how one’s teaching affects particular learners and changing it; here the teacher spots an exclusion and makes the lesson inclusive.","difficulty":"hard","source":"CTET Paper I · State TET","questionHi":"NCF 2005 और NEP 2020 दोनों शिक्षकों से चिंतनशील व्यवसायी होने की अपेक्षा करते हैं। सर्वश्रेष्ठ उदाहरण कौन-सा है?","optionsHi":["हर वर्ष पाठ्यपुस्तक को पृष्ठ-दर-पृष्ठ पढ़ाना, क्योंकि बोर्ड ने उसे अनुमोदित किया है और अभिभावक उसकी अपेक्षा करते हैं","‘हमारा भोजन’ पाठ को यह देखकर संशोधित करना कि उसमें जनजातीय छात्रों के भोजन छूट गए थे, और उन्हें साझा करने के लिए आमंत्रित करना","हर वर्ष वही प्रश्न-पत्र प्रयोग करना ताकि स्तर एक-सा बना रहे","जब तक प्रधानाचार्य या आगंतुक निरीक्षक विशेष रूप से निर्देश न दें, अपनी विधियों में कोई परिवर्तन न करना"],"explanationHi":"चिंतनशील अभ्यास का अर्थ है यह देखना कि शिक्षण विशिष्ट अधिगमकर्ताओं को कैसे प्रभावित करता है और उसे बदलना; यहाँ शिक्षिका एक बहिष्करण को पहचानती है और पाठ को समावेशी बनाती है।"},
  {"id":"cdp-child-development-1570","question":"A teacher spends a term studying one child with severe reading difficulty in depth, examining family background, health, school history and work samples, to understand the child’s problem. This is primarily a:","options":["Survey of reading levels","Cycle of action research","Experimental study with a control group","Case study"],"answer":3,"explanation":"An in-depth study of a single individual from many sources is a case study; action research would centre on trying and evaluating a change in practice.","difficulty":"hard","source":"CTET · KVS PRT","questionHi":"एक शिक्षिका एक सत्र तक गंभीर पठन-कठिनाई वाले एक बच्चे का गहन अध्ययन करती है, बच्चे की समस्या को समझने के लिए पारिवारिक पृष्ठभूमि, स्वास्थ्य, विद्यालयी इतिहास और कार्य-नमूनों की जाँच करती है। यह मुख्यतः क्या है?","optionsHi":["पठन-स्तरों का सर्वेक्षण","क्रियात्मक अनुसंधान का एक चक्र","नियंत्रण समूह के साथ प्रायोगिक अध्ययन","व्यक्ति-अध्ययन (केस स्टडी)"],"explanationHi":"अनेक स्रोतों से एक अकेले व्यक्ति का गहन अध्ययन व्यक्ति-अध्ययन है; क्रियात्मक अनुसंधान कार्य-पद्धति में किसी परिवर्तन को आज़माने और उसका मूल्यांकन करने पर केंद्रित होगा।"},
  {"id":"cdp-child-development-1571","question":"In a Class 6 classroom in Uttar Pradesh with 55 students of widely varying levels, which plan best applies Vygotsky’s zone of proximal development?","options":["Tasks at two or three levels, groups based on what students can do with help, and trained peer helpers","Teach the whole class from the textbook at one pace and test everyone together, so that no one is left out","Seat the weakest students at the back so the lesson can move quickly for the majority","Let each student work alone on the same worksheet without help, to build independence"],"answer":0,"explanation":"Large classes still allow for differences in ZPDs through tiered tasks, grouping by assisted performance and peer support. Uniform, unaided work ignores those differences.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"उत्तर प्रदेश की कक्षा 6 में, जहाँ 55 छात्र बहुत भिन्न स्तरों के हैं, कौन-सी योजना वाइगोत्स्की के निकटस्थ विकास के क्षेत्र को सबसे अच्छी तरह लागू करती है?","optionsHi":["दो या तीन स्तरों के कार्य, इस आधार पर समूह कि छात्र सहायता से क्या कर सकते हैं, और प्रशिक्षित सहपाठी-सहायक","पूरी कक्षा को पाठ्यपुस्तक से एक ही गति से पढ़ाना और सबका एक साथ परीक्षण करना, ताकि कोई छूट न जाए","सबसे कमज़ोर छात्रों को पीछे बैठाना ताकि अधिकांश के लिए पाठ तेज़ी से आगे बढ़ सके","हर छात्र को बिना सहायता के उसी कार्यपत्रक पर अकेले काम करने देना, ताकि आत्मनिर्भरता विकसित हो"],"explanationHi":"बड़ी कक्षाओं में भी स्तरीकृत कार्यों, सहायता सहित प्रदर्शन पर आधारित समूहीकरण और सहपाठी सहयोग से ZPD के अंतर को ध्यान में रखा जा सकता है। एक-समान, बिना सहायता का कार्य उन अंतरों की अनदेखी करता है।"},
  {"id":"cdp-child-development-1572","question":"NEP 2020’s foundational stage (ages 3 to 8) stresses play, activity and discovery-based learning. Which feature of children’s thinking, as described by Piaget, best supports this emphasis?","options":["They reason mainly through abstract propositions, so discovery lets them test their hypotheses systematically","They learn best from long lectures, so play is needed only as a reward afterwards","They are mostly pre-operational or early concrete operational, learning through action, play and the concrete","They have already mastered all forms of conservation, so they are ready for formal rules"],"answer":2,"explanation":"Ages 3 to 8 cover the pre-operational period and the start of concrete operations, when learning is grounded in action and play. Abstract or lecture-based teaching does not fit this thinking.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"NEP 2020 का आधारभूत चरण (3 से 8 वर्ष की आयु) खेल, गतिविधि और खोज-आधारित अधिगम पर ज़ोर देता है। पियाजे द्वारा वर्णित बच्चों के चिंतन की कौन-सी विशेषता इस ज़ोर का सबसे अच्छा समर्थन करती है?","optionsHi":["वे मुख्यतः अमूर्त प्रस्तावों के माध्यम से तर्क करते हैं, इसलिए खोज उन्हें अपनी परिकल्पनाओं का व्यवस्थित परीक्षण करने देती है","वे लंबे व्याख्यानों से सबसे अच्छा सीखते हैं, इसलिए खेल केवल बाद में पुरस्कार के रूप में आवश्यक है","वे अधिकतर पूर्व-संक्रियात्मक या प्रारंभिक मूर्त संक्रियात्मक अवस्था में होते हैं, और क्रिया, खेल तथा मूर्त वस्तुओं के माध्यम से सीखते हैं","उन्होंने संरक्षण के सभी रूपों में पहले ही महारत पा ली है, इसलिए वे औपचारिक नियमों के लिए तैयार हैं"],"explanationHi":"3 से 8 वर्ष की आयु पूर्व-संक्रियात्मक काल और मूर्त संक्रियाओं के आरंभ को समेटती है, जब अधिगम क्रिया और खेल पर आधारित होता है। अमूर्त या व्याख्यान-आधारित शिक्षण इस चिंतन के अनुकूल नहीं है।"},
  {"id":"cdp-child-development-1573","question":"In a pre-primary class, four children sit together, each talking about his own drawing, but no one listens or responds to the others. Piaget called this form of speech:","options":["Inner speech","Socialised speech","Private speech used for self-regulation","Collective monologue"],"answer":3,"explanation":"Collective monologue is egocentric speech in a group, where children talk in each other’s presence without real exchange. ‘Private speech used for self-regulation’ is Vygotsky’s interpretation of such talk in other contexts.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"एक पूर्व-प्राथमिक कक्षा में चार बच्चे साथ बैठे हैं, प्रत्येक अपने चित्र के बारे में बोल रहा है, परंतु कोई दूसरों की सुनता या उत्तर नहीं देता। पियाजे ने वाणी के इस रूप को क्या कहा?","optionsHi":["आंतरिक वाणी","समाजीकृत वाणी","आत्म-नियमन के लिए प्रयुक्त निजी वाणी","सामूहिक एकालाप"],"explanationHi":"सामूहिक एकालाप समूह में अहंकेंद्रित वाणी है, जिसमें बच्चे एक-दूसरे की उपस्थिति में बिना वास्तविक आदान-प्रदान के बोलते हैं। ‘आत्म-नियमन के लिए प्रयुक्त निजी वाणी’ अन्य संदर्भों में ऐसी बातचीत की वाइगोत्स्की की व्याख्या है।"},
  {"id":"cdp-child-development-1574","question":"How many of these did Piaget describe as forms of egocentric speech in young children? I. Repetition of words and syllables for the pleasure of it. II. Monologue, talking to oneself while acting. III. Collective monologue, talking in a group without real exchange. IV. Adapted information, telling a listener something taking his viewpoint into account.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Piaget classified repetition, monologue and collective monologue as egocentric speech. Adapted information, which considers the listener, is socialised speech.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"इनमें से कितनों को पियाजे ने छोटे बच्चों में अहंकेंद्रित वाणी के रूप में वर्णित किया? I. आनंद के लिए शब्दों और अक्षरों की पुनरावृत्ति। II. एकालाप, कार्य करते समय स्वयं से बात करना। III. सामूहिक एकालाप, समूह में बिना वास्तविक आदान-प्रदान के बोलना। IV. अनुकूलित सूचना, श्रोता के दृष्टिकोण को ध्यान में रखकर उसे कुछ बताना।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"पियाजे ने पुनरावृत्ति, एकालाप और सामूहिक एकालाप को अहंकेंद्रित वाणी के रूप में वर्गीकृत किया। अनुकूलित सूचना, जो श्रोता का ध्यान रखती है, समाजीकृत वाणी है।"},
  {"id":"cdp-child-development-1575","question":"Vygotsky distinguished technical tools, which act on objects, from psychological tools, which act on the mind. Which of the following is a psychological tool?","options":["A plough for tilling soil","A hammer for driving nails","A system of written numerals","A cooking pot for boiling rice"],"answer":2,"explanation":"Number systems, writing, maps and mnemonics are psychological tools that organise thinking. Ploughs and hammers change the physical world.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"वाइगोत्स्की ने तकनीकी उपकरणों, जो वस्तुओं पर कार्य करते हैं, और मनोवैज्ञानिक उपकरणों, जो मस्तिष्क पर कार्य करते हैं, में भेद किया। इनमें से कौन-सा मनोवैज्ञानिक उपकरण है?","optionsHi":["मिट्टी जोतने के लिए हल","कील ठोकने के लिए हथौड़ा","लिखित अंकों की प्रणाली","चावल उबालने के लिए खाना पकाने का बर्तन"],"explanationHi":"संख्या-प्रणालियाँ, लेखन, मानचित्र और स्मरण-सहायक युक्तियाँ मनोवैज्ञानिक उपकरण हैं जो चिंतन को संगठित करते हैं। हल और हथौड़े भौतिक संसार को बदलते हैं।"},
  {"id":"cdp-child-development-1576","question":"A Class 7 maths teacher first shows a fully worked example, then gives examples with the last step blank, then with the last two steps blank, and finally problems with no steps shown. This ‘fading’ technique is an application of:","options":["Piaget’s horizontal décalage across tasks","Scaffolding that is gradually withdrawn","Classical conditioning of correct steps","Bruner’s narrative mode of thought"],"answer":1,"explanation":"Fading worked examples moves responsibility from teacher to learner step by step, the essence of scaffolding within the ZPD.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 7 का गणित-शिक्षक पहले पूरी तरह हल किया गया उदाहरण दिखाता है, फिर ऐसे उदाहरण देता है जिनका अंतिम चरण खाली हो, फिर जिनके अंतिम दो चरण खाली हों, और अंत में ऐसे प्रश्न जिनमें कोई चरण नहीं दिखाया गया। ‘फेडिंग’ (क्रमशः हटाने) की यह तकनीक किसका अनुप्रयोग है?","optionsHi":["विभिन्न कार्यों में पियाजे का क्षैतिज विचलन (डेकालाज)","पाड़ (स्कैफ़ोल्डिंग) जिसे धीरे-धीरे हटाया जाता है","सही चरणों का शास्त्रीय अनुबंधन","ब्रूनर का चिंतन का आख्यानात्मक प्रकार"],"explanationHi":"हल किए गए उदाहरणों को क्रमशः हटाना उत्तरदायित्व को शिक्षक से अधिगमकर्ता की ओर चरण-दर-चरण ले जाता है, जो ZPD के भीतर पाड़ का सार है।"},
  {"id":"cdp-child-development-1577","question":"Asked where they would put a third eye if they could have one, nine-year-olds mostly said ‘in the middle of my forehead’, while many older adolescents suggested places such as the back of the head or the palm, with reasons like ‘to see behind me’. The difference best illustrates:","options":["Formal operational reasoning about hypothetical possibilities","Pre-operational animism persisting into the teenage years","Conservation of number in the concrete stage","Vygotsky’s private speech being used aloud to guide problem-solving"],"answer":0,"explanation":"Concrete operational children stay close to the familiar arrangement, while formal operational thinkers explore unusual possibilities and justify them. The task is hypothetical, so it reveals formal reasoning.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"यह पूछे जाने पर कि यदि उन्हें तीसरी आँख मिले तो वे उसे कहाँ रखेंगे, नौ वर्ष के बच्चों ने अधिकतर कहा ‘मेरे माथे के बीच में’, जबकि अनेक बड़े किशोरों ने सिर के पीछे या हथेली जैसे स्थान सुझाए, ‘ताकि अपने पीछे देख सकूँ’ जैसे कारणों के साथ। यह अंतर सबसे अच्छी तरह किसे दर्शाता है?","optionsHi":["काल्पनिक संभावनाओं के बारे में औपचारिक संक्रियात्मक तर्क","किशोरावस्था तक बनी रहने वाली पूर्व-संक्रियात्मक सजीवारोपण प्रवृत्ति","मूर्त अवस्था में संख्या का संरक्षण","वाइगोत्स्की की निजी वाणी का समस्या-समाधान को निर्देशित करने के लिए ज़ोर से प्रयोग"],"explanationHi":"मूर्त संक्रियात्मक बच्चे परिचित व्यवस्था के निकट रहते हैं, जबकि औपचारिक संक्रियात्मक चिंतक असामान्य संभावनाओं की खोज करते हैं और उनका औचित्य बताते हैं। कार्य काल्पनिक है, इसलिए यह औपचारिक तर्क को प्रकट करता है।"},
  {"id":"cdp-child-development-1578","question":"Consider these statements about play. 1. Piaget saw symbolic play mainly as a reflection and practice of the child’s current level of thinking. 2. Vygotsky saw pretend play as creating a zone of proximal development in which children act beyond their usual level. 3. Both Piaget and Vygotsky regarded play as unimportant for cognitive development. Which is/are correct?","options":["1 and 2 only","3 only","1 only","2 and 3 only"],"answer":0,"explanation":"Piaget treated play as assimilation that consolidates existing schemas, while Vygotsky saw it as leading development, for example through self-imposed rules. Both valued play, so statement 3 is false.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"खेल के बारे में इन कथनों पर विचार कीजिए। 1. पियाजे प्रतीकात्मक खेल को मुख्यतः बच्चे के वर्तमान चिंतन-स्तर का प्रतिबिंब और अभ्यास मानते थे। 2. वाइगोत्स्की कल्पनात्मक खेल को ऐसा निकटस्थ विकास का क्षेत्र बनाने वाला मानते थे जिसमें बच्चे अपने सामान्य स्तर से आगे कार्य करते हैं। 3. पियाजे और वाइगोत्स्की दोनों खेल को संज्ञानात्मक विकास के लिए महत्वहीन मानते थे। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 3","केवल 1","केवल 2 और 3"],"explanationHi":"पियाजे खेल को आत्मसात्करण मानते थे जो मौजूदा स्कीमा को सुदृढ़ करता है, जबकि वाइगोत्स्की उसे विकास का अग्रणी मानते थे, उदाहरण के लिए स्वयं थोपे गए नियमों के माध्यम से। दोनों खेल को महत्व देते थे, इसलिए कथन 3 असत्य है।"},
  {"id":"cdp-child-development-1579","question":"Bruner wrote that knowing is a process, not a product. For a Class 8 science teacher, this most directly implies that she should:","options":["Make students memorise the final conclusions of each chapter, since these are what the board exam tests","Engage students in methods of inquiry such as questioning, hypothesising and checking evidence","Cover as many facts as possible in the syllabus, as broad knowledge is the base of science","Replace experiments with notes dictated in class, which save time and avoid confusion"],"answer":1,"explanation":"Bruner wanted students to take part in the process of knowledge-getting, thinking as a scientist or historian would, rather than storing finished conclusions.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"ब्रूनर ने लिखा कि जानना एक प्रक्रिया है, उत्पाद नहीं। कक्षा 8 की विज्ञान-शिक्षिका के लिए इसका सबसे प्रत्यक्ष निहितार्थ क्या है कि उसे:","optionsHi":["छात्रों को प्रत्येक अध्याय के अंतिम निष्कर्ष रटवाने चाहिए, क्योंकि बोर्ड परीक्षा में वही पूछे जाते हैं","छात्रों को प्रश्न पूछने, परिकल्पना बनाने और प्रमाणों की जाँच करने जैसी अन्वेषण-विधियों में संलग्न करना चाहिए","पाठ्यक्रम के अधिक से अधिक तथ्य पूरे करने चाहिए, क्योंकि व्यापक ज्ञान विज्ञान का आधार है","प्रयोगों के स्थान पर कक्षा में लिखवाए गए नोट्स देने चाहिए, जिससे समय बचता है और भ्रम नहीं होता"],"explanationHi":"ब्रूनर चाहते थे कि छात्र ज्ञान-प्राप्ति की प्रक्रिया में भाग लें, वैज्ञानिक या इतिहासकार की तरह सोचें, न कि तैयार निष्कर्षों का संग्रह करें।"},
  {"id":"cdp-child-development-1580","question":"How many of these benefits did Bruner claim for learning by discovery? I. It increases intellectual potency, the ability to solve problems. II. It shifts motivation from extrinsic to intrinsic rewards. III. It teaches the methods (heuristics) of discovery. IV. It helps learners remember what they have found.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"In ‘The Act of Discovery’ Bruner listed all four: intellectual potency, intrinsic motivation, learning the heuristics of discovery, and better memory for what is discovered.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"खोज द्वारा अधिगम के इनमें से कितने लाभ ब्रूनर ने बताए? I. यह बौद्धिक सामर्थ्य, अर्थात समस्याएँ हल करने की क्षमता, बढ़ाता है। II. यह अभिप्रेरणा को बाह्य से आंतरिक पुरस्कारों की ओर ले जाता है। III. यह खोज की विधियाँ (ह्यूरिस्टिक्स) सिखाता है। IV. यह अधिगमकर्ताओं को जो उन्होंने खोजा उसे याद रखने में मदद करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"‘The Act of Discovery’ में ब्रूनर ने चारों गिनाए: बौद्धिक सामर्थ्य, आंतरिक अभिप्रेरणा, खोज की ह्यूरिस्टिक्स सीखना, और जो खोजा गया उसकी बेहतर स्मृति।"},
  {"id":"cdp-child-development-1581","question":"Assertion (A): A Piagetian teacher would try to match instruction to the child’s current stage of thinking. Reason (R): Bruner held that readiness can be nurtured by presenting ideas in an appropriate form.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both statements are accurate, but R describes Bruner’s view and does not explain why a Piagetian teacher matches instruction to stages; that follows from Piaget’s own idea that learning depends on development.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"अभिकथन (A): पियाजेवादी शिक्षक अनुदेशन को बच्चे के चिंतन की वर्तमान अवस्था के अनुरूप बनाने का प्रयास करेगा। कारण (R): ब्रूनर का मत था कि विचारों को उपयुक्त रूप में प्रस्तुत करके तत्परता को पोषित किया जा सकता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों कथन सटीक हैं, परंतु R ब्रूनर का मत बताता है और यह स्पष्ट नहीं करता कि पियाजेवादी शिक्षक अनुदेशन को अवस्थाओं के अनुरूप क्यों बनाता है; वह पियाजे के अपने इस विचार से आता है कि अधिगम विकास पर निर्भर करता है।"},
  {"id":"cdp-child-development-1582","question":"A 20-month-old watches her father put a ball into his closed hand, move the hand inside a basket, and bring the hand out empty. She immediately searches in the basket. Piaget would say she can now:","options":["Follow only the visible displacements of an object she can see","Show secondary circular reactions with objects","Mentally represent invisible displacements of an object","Conserve volume when liquid is poured between containers"],"answer":2,"explanation":"Inferring where an object went when its movement was hidden requires mental representation, the final achievement of object permanence at about 18 to 24 months.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"20 माह की एक बच्ची देखती है कि उसके पिता गेंद को अपनी बंद मुट्ठी में रखते हैं, मुट्ठी को टोकरी के भीतर घुमाते हैं, और खाली मुट्ठी बाहर निकालते हैं। वह तुरंत टोकरी में खोजती है। पियाजे के अनुसार वह अब क्या कर सकती है?","optionsHi":["केवल उस वस्तु के दृश्य विस्थापन का अनुसरण करना जिसे वह देख सके","वस्तुओं के साथ द्वितीयक वृत्तीय प्रतिक्रियाएँ दिखाना","किसी वस्तु के अदृश्य विस्थापन को मानसिक रूप से निरूपित करना","तरल को पात्रों के बीच उँडेले जाने पर आयतन का संरक्षण करना"],"explanationHi":"यह अनुमान लगाना कि वस्तु कहाँ गई जब उसकी गति छिपी हुई थी, मानसिक निरूपण की माँग करता है, जो लगभग 18 से 24 माह में वस्तु-स्थायित्व की अंतिम उपलब्धि है।"},
  {"id":"cdp-child-development-1583","question":"A nine-month-old pushes a pillow aside in order to grab the toy hidden behind it. Piaget regarded this behaviour as a landmark of substage 4 because it shows:","options":["A primary circular reaction, repeating a chance action centred on her own body","Intentional, means-end behaviour, using one action to achieve another","Symbolic play, using the pillow to stand for something else","Deferred imitation of an action she had seen earlier"],"answer":1,"explanation":"Coordinating schemas so that one (pushing) serves another (grasping) is the first clear intentional, means-end behaviour, appearing at about 8 to 12 months.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"नौ माह की बच्ची तकिये को हटाकर उसके पीछे छिपा खिलौना पकड़ती है। पियाजे ने इस व्यवहार को उपअवस्था 4 की एक महत्वपूर्ण पहचान क्यों माना?","optionsHi":["यह प्राथमिक वृत्तीय प्रतिक्रिया दिखाता है, जिसमें अपने शरीर पर केंद्रित संयोगवश की गई क्रिया को दोहराया जाता है","यह सोद्देश्य, साधन-साध्य व्यवहार दिखाता है, जिसमें एक क्रिया का उपयोग दूसरी को पाने के लिए किया जाता है","यह प्रतीकात्मक खेल दिखाता है, जिसमें तकिये का प्रयोग किसी अन्य वस्तु के प्रतीक के रूप में होता है","यह विलंबित अनुकरण दिखाता है, जिसमें पहले देखी गई क्रिया की नकल की जाती है"],"explanationHi":"स्कीमाओं का समन्वय, जिससे एक (धकेलना) दूसरी (पकड़ना) की सेवा करे, पहला स्पष्ट सोद्देश्य, साधन-साध्य व्यवहार है, जो लगभग 8 से 12 माह में प्रकट होता है।"},
  {"id":"cdp-child-development-1584","question":"Which statement about Piaget’s concept of egocentrism is correct?","options":["It means the same as selfishness, so it should be corrected through moral instruction","It disappears completely by about age four, once children begin playing and talking with their peers","It applies only to adults who have rigid opinions and refuse to consider others","It is a cognitive difficulty in separating one’s own perspective from others’, taking different forms across stages"],"answer":3,"explanation":"Egocentrism is a cognitive limitation, not a moral fault. It appears in infancy, in the pre-operational stage and, as Elkind described, in a new form in adolescence.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"पियाजे की अहंकेंद्रिता की अवधारणा के बारे में कौन-सा कथन सही है?","optionsHi":["इसका अर्थ स्वार्थीपन के समान है, इसलिए इसे नैतिक शिक्षा द्वारा ठीक किया जाना चाहिए","यह लगभग चार वर्ष की आयु तक पूरी तरह लुप्त हो जाती है, जब बच्चे साथियों के साथ खेलने-बोलने लगते हैं","यह केवल उन वयस्कों पर लागू होती है जिनकी राय कठोर होती है और जो दूसरों पर विचार करने से इनकार करते हैं","यह अपने दृष्टिकोण को दूसरों के दृष्टिकोण से अलग करने की संज्ञानात्मक कठिनाई है, जो अवस्थाओं में अलग-अलग रूप लेती है"],"explanationHi":"अहंकेंद्रिता एक संज्ञानात्मक सीमा है, नैतिक दोष नहीं। यह शैशवावस्था में, पूर्व-संक्रियात्मक अवस्था में और, जैसा एल्काइंड ने बताया, किशोरावस्था में एक नए रूप में प्रकट होती है।"},
  {"id":"cdp-child-development-1585","question":"Two Class 2 children of the same independent reading level are in a teacher’s guided reading group. Which teacher behaviour is LEAST consistent with scaffolding?","options":["Asking a child to predict what will happen next before turning the page","Reading every hard word aloud before the children try, every time, all year","Pointing to the first letter as a cue when a child gets stuck on a word","Gradually letting the children take over more of the discussion as they grow confident"],"answer":1,"explanation":"Help that is never reduced keeps children dependent and prevents them from taking over the task. Scaffolding responds to need and is faded over time.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 2 के समान स्वतंत्र पठन-स्तर वाले दो बच्चे शिक्षिका के निर्देशित पठन समूह में हैं। शिक्षिका का कौन-सा व्यवहार पाड़ (स्कैफ़ोल्डिंग) से सबसे कम मेल खाता है?","optionsHi":["बच्चे से पन्ना पलटने से पहले यह अनुमान लगाने को कहना कि आगे क्या होगा","बच्चों के प्रयास करने से पहले हर कठिन शब्द को हर बार, पूरे वर्ष, ज़ोर से पढ़ देना","जब बच्चा किसी शब्द पर अटक जाए तो संकेत के रूप में पहले अक्षर की ओर इशारा करना","जैसे-जैसे बच्चे आत्मविश्वासी हों, चर्चा का अधिक भाग उन्हें धीरे-धीरे सौंपना"],"explanationHi":"जो सहायता कभी घटाई नहीं जाती वह बच्चों को निर्भर बनाए रखती है और उन्हें कार्य सँभालने से रोकती है। पाड़ आवश्यकता के अनुसार प्रतिक्रिया करता है और समय के साथ हटाया जाता है।"},
  {"id":"cdp-child-development-1586","question":"A Class 3 teacher finds that a child explains clearly in Bhojpuri how she divided 12 mangoes among 4 friends, but cannot answer the same question in a written Hindi worksheet. A teacher drawing on Vygotsky and Bruner would conclude that:","options":["The child has no real understanding of division, only memorised talk, and must start again","The child should be held back a class until her written Hindi improves","The child has the concept but needs help linking it to the symbols and language of school","The child is still in the sensorimotor stage and cannot use symbols yet"],"answer":2,"explanation":"Her oral, home-language explanation shows understanding; the gap lies in moving to written, school forms. Scaffolding that connects familiar language and action to new symbols is the remedy.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 3 की शिक्षिका पाती है कि एक बच्ची भोजपुरी में स्पष्ट रूप से समझाती है कि उसने 12 आम 4 मित्रों में कैसे बाँटे, परंतु लिखित हिंदी कार्यपत्रक में वही प्रश्न नहीं हल कर पाती। वाइगोत्स्की और ब्रूनर के विचारों पर आधारित शिक्षिका क्या निष्कर्ष निकालेगी?","optionsHi":["बच्ची में भाग की वास्तविक समझ नहीं है, केवल रटी हुई बातें हैं, और उसे फिर से शुरू करना होगा","जब तक उसकी लिखित हिंदी न सुधरे, उसे एक कक्षा पीछे रोक देना चाहिए","बच्ची में संप्रत्यय है, पर उसे उसे विद्यालय के प्रतीकों और भाषा से जोड़ने में सहायता चाहिए","बच्ची अब भी संवेदी-गामक अवस्था में है और अभी प्रतीकों का उपयोग नहीं कर सकती"],"explanationHi":"उसकी मौखिक, घर की भाषा में व्याख्या समझ को दर्शाती है; अंतर लिखित, विद्यालयी रूपों की ओर बढ़ने में है। परिचित भाषा और क्रिया को नए प्रतीकों से जोड़ने वाला पाड़ इसका उपाय है।"},
  {"id":"cdp-child-development-1587","question":"Which experimental finding would MOST strongly support Vygotsky over Piaget?","options":["Children given targeted help on a task beyond them later do it alone sooner than children left to explore","Children in every culture studied pass through the sensorimotor stage before the pre-operational stage begins","Infants in many cultures show the A-not-B error at around 8 to 12 months","Most adolescents use formal reasoning in all subjects once they reach about 12"],"answer":0,"explanation":"Faster independent mastery after assisted learning supports Vygotsky’s claim that instruction within the ZPD leads development. The second and third findings fit Piaget.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"कौन-सा प्रायोगिक निष्कर्ष पियाजे की तुलना में वाइगोत्स्की का सबसे अधिक समर्थन करेगा?","optionsHi":["जिन बच्चों को उनकी क्षमता से परे के कार्य पर लक्षित सहायता दी गई, वे अन्वेषण के लिए छोड़े गए बच्चों से जल्दी उसे अकेले करने लगे","अध्ययन की गई हर संस्कृति के बच्चे पूर्व-संक्रियात्मक अवस्था शुरू होने से पहले संवेदी-गामक अवस्था से गुज़रते हैं","अनेक संस्कृतियों के शिशु लगभग 8 से 12 माह में A-not-B त्रुटि दिखाते हैं","लगभग 12 वर्ष की आयु तक पहुँचने पर अधिकांश किशोर सभी विषयों में औपचारिक तर्क का उपयोग करते हैं"],"explanationHi":"सहायता प्राप्त अधिगम के बाद स्वतंत्र रूप से तेज़ महारत वाइगोत्स्की के इस दावे का समर्थन करती है कि ZPD के भीतर अनुदेशन विकास को आगे ले जाता है। दूसरे और तीसरे निष्कर्ष पियाजे के अनुरूप हैं।"},
  {"id":"cdp-child-development-1588","question":"A Class 10 student argues, ‘If a law is unjust, citizens may have a duty to oppose it peacefully,’ citing examples from the freedom movement. Which Piagetian ability is she mainly using?","options":["Seriation, ordering historical events correctly along a timeline","Conservation of quantity across transformations","Reasoning about abstract principles and applying them to cases","Object permanence, knowing things exist when unseen"],"answer":2,"explanation":"Reasoning about abstract ideas like justice and duty, and testing them against cases, belongs to formal operations. Seriation and conservation are concrete operational skills.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 10 की एक छात्रा स्वतंत्रता आंदोलन के उदाहरण देते हुए तर्क देती है, ‘यदि कोई कानून अन्यायपूर्ण है तो नागरिकों का कर्तव्य हो सकता है कि वे शांतिपूर्वक उसका विरोध करें।’ वह मुख्यतः पियाजे की किस क्षमता का उपयोग कर रही है?","optionsHi":["क्रमबद्धता, ऐतिहासिक घटनाओं को समयरेखा पर सही क्रम में रखना","परिवर्तनों के बावजूद मात्रा का संरक्षण","अमूर्त सिद्धांतों के बारे में तर्क करना और उन्हें उदाहरणों पर लागू करना","वस्तु-स्थायित्व, यह जानना कि वस्तुएँ अदृश्य होने पर भी मौजूद रहती हैं"],"explanationHi":"न्याय और कर्तव्य जैसे अमूर्त विचारों के बारे में तर्क करना और उन्हें उदाहरणों पर परखना औपचारिक संक्रियाओं का अंग है। क्रमबद्धता और संरक्षण मूर्त संक्रियात्मक कौशल हैं।"},
  {"id":"cdp-child-development-1589","question":"How many of these statements about Vygotsky’s internalisation are correct? I. It is a process by which social, external activity becomes inner mental activity. II. It involves the child simply copying external activity without transforming it. III. It happens without any role for language. IV. Inner speech is a transitional step between social speech and private speech.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. Internalisation transforms rather than copies, language is central to it, and the sequence runs social speech → private speech → inner speech, so private speech (not inner speech) is the transitional step.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"वाइगोत्स्की के आंतरीकरण के बारे में इनमें से कितने कथन सही हैं? I. यह वह प्रक्रिया है जिसके द्वारा सामाजिक, बाह्य गतिविधि आंतरिक मानसिक गतिविधि बन जाती है। II. इसमें बच्चा बाह्य गतिविधि को बिना रूपांतरित किए केवल नकल करता है। III. यह भाषा की किसी भूमिका के बिना होता है। IV. आंतरिक वाणी सामाजिक वाणी और निजी वाणी के बीच का संक्रमणकालीन चरण है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"केवल I सही है। आंतरीकरण नकल नहीं, रूपांतरण करता है, भाषा इसके लिए केंद्रीय है, और क्रम सामाजिक वाणी → निजी वाणी → आंतरिक वाणी का है, इसलिए संक्रमणकालीन चरण निजी वाणी है (आंतरिक वाणी नहीं)।"},
  {"id":"cdp-child-development-1590","question":"In a Class 4 group task, a child who can already conserve area and a child who cannot are asked to agree on which of two equal fields has more grass. After arguing, the non-conserving child begins to justify equality. Which explanation would Piaget most likely give?","options":["The child simply copied the friend to avoid further argument, with no real change in her own underlying thinking","The disagreement created cognitive conflict that pushed the child to coordinate dimensions and re-equilibrate","The child was rewarded by the friend’s approval for agreeing, which reinforced the answer","The child had already conserved area but was hiding it until a friend agreed with her"],"answer":1,"explanation":"Piaget saw peer disagreement as a source of cognitive conflict that leads to restructuring. If the child gives her own justification, the change is more than copying.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 4 के समूह-कार्य में, एक बच्चे को जो क्षेत्रफल का संरक्षण पहले से कर सकता है और एक को जो नहीं कर सकता, यह तय करने को कहा जाता है कि दो बराबर खेतों में किसमें अधिक घास है। बहस के बाद संरक्षण न करने वाला बच्चा बराबरी का औचित्य बताने लगता है। पियाजे सबसे अधिक संभावना से कौन-सी व्याख्या देंगे?","optionsHi":["बच्चे ने और बहस से बचने के लिए बस मित्र की नकल की, उसके अपने अंतर्निहित चिंतन में कोई वास्तविक बदलाव नहीं आया","असहमति ने संज्ञानात्मक द्वंद्व पैदा किया जिसने बच्चे को आयामों का समन्वय करने और पुनः संतुलन प्राप्त करने के लिए प्रेरित किया","मित्र की स्वीकृति से सहमत होने पर बच्चे को पुरस्कार मिला, जिसने उत्तर को पुनर्बलित किया","बच्चा क्षेत्रफल का संरक्षण पहले ही कर चुका था, पर मित्र के सहमत होने तक उसे छिपा रहा था"],"explanationHi":"पियाजे सहपाठी असहमति को संज्ञानात्मक द्वंद्व का स्रोत मानते थे जो पुनर्गठन की ओर ले जाता है। यदि बच्चा अपना औचित्य स्वयं देता है, तो परिवर्तन नकल से अधिक है।"},
  {"id":"cdp-child-development-1591","question":"Which classroom statement contradicts Piaget’s theory?","options":["‘Children’s mistakes tell me a lot about how they are thinking.’","‘Hands-on experience with real objects is especially valuable for young learners.’","‘Children learn by actively constructing knowledge for themselves.’","‘If I explain clearly enough, any Class 1 child can follow algebraic proofs.’"],"answer":3,"explanation":"Piaget held that what a child can understand is limited by her current cognitive structures; clear explanation alone cannot produce formal reasoning in a pre-operational child.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"कक्षा का कौन-सा कथन पियाजे के सिद्धांत का खंडन करता है?","optionsHi":["‘बच्चों की गलतियाँ मुझे बहुत कुछ बताती हैं कि वे कैसे सोच रहे हैं।’","‘वास्तविक वस्तुओं के साथ प्रत्यक्ष अनुभव छोटे अधिगमकर्ताओं के लिए विशेष रूप से मूल्यवान है।’","‘बच्चे ज्ञान का स्वयं सक्रिय रूप से निर्माण करके सीखते हैं।’","‘यदि मैं पर्याप्त स्पष्टता से समझाऊँ, तो कक्षा 1 का कोई भी बच्चा बीजगणितीय उपपत्तियाँ समझ सकता है।’"],"explanationHi":"पियाजे का मत था कि बच्चा जो समझ सकता है वह उसकी वर्तमान संज्ञानात्मक संरचनाओं से सीमित होता है; केवल स्पष्ट व्याख्या पूर्व-संक्रियात्मक बच्चे में औपचारिक तर्क उत्पन्न नहीं कर सकती।"},
  {"id":"cdp-child-development-1592","question":"Consider these statements about Vygotsky’s view of concepts. 1. Everyday (spontaneous) concepts develop from concrete experience upward towards awareness. 2. Scientific concepts develop from definitions downward towards concrete experience. 3. The two kinds of concepts develop completely separately and never influence each other. Which is/are correct?","options":["1 and 2 only","1 only","3 only","1, 2 and 3"],"answer":0,"explanation":"Vygotsky described spontaneous concepts as growing ‘upward’ and scientific concepts ‘downward’, meeting and enriching each other. Statement 3 contradicts this interaction.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"वाइगोत्स्की के संप्रत्ययों के दृष्टिकोण के बारे में इन कथनों पर विचार कीजिए। 1. रोज़मर्रा के (स्वतःस्फूर्त) संप्रत्यय मूर्त अनुभव से जागरूकता की ओर ऊपर की दिशा में विकसित होते हैं। 2. वैज्ञानिक संप्रत्यय परिभाषाओं से मूर्त अनुभव की ओर नीचे की दिशा में विकसित होते हैं। 3. दोनों प्रकार के संप्रत्यय पूरी तरह अलग-अलग विकसित होते हैं और एक-दूसरे को कभी प्रभावित नहीं करते। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 1","केवल 3","1, 2 और 3"],"explanationHi":"वाइगोत्स्की ने स्वतःस्फूर्त संप्रत्ययों को ‘ऊपर की ओर’ और वैज्ञानिक संप्रत्ययों को ‘नीचे की ओर’ बढ़ता बताया, जो मिलकर एक-दूसरे को समृद्ध करते हैं। कथन 3 इस पारस्परिक क्रिया का खंडन करता है।"},
  {"id":"cdp-child-development-1593","question":"A Class 5 teacher in Odisha plans a unit on maps: children first walk around the school and mark landmarks on a rough sketch, then use a printed map of the school, and finally read a map of their district using a key and scale. Which statement best describes the plan?","options":["It moves through Bruner’s enactive, iconic and symbolic modes, suiting concrete operational learners","It skips the iconic mode entirely, going straight from walking around the school to the district map","It is unsuitable for Class 5, because reading any kind of map needs formal operational thinking","It follows Skinner’s schedules of reinforcement, rewarding each correct landmark"],"answer":0,"explanation":"Walking and marking is enactive, the printed map iconic, and the scale and key symbolic. Map reading of familiar places is within reach of concrete operational children.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"ओडिशा की कक्षा 5 की शिक्षिका मानचित्रों पर एक इकाई की योजना बनाती है: बच्चे पहले विद्यालय के चारों ओर घूमकर एक कच्चे रेखाचित्र पर प्रमुख स्थल चिह्नित करते हैं, फिर विद्यालय का छपा मानचित्र उपयोग करते हैं, और अंत में सूची और पैमाने की सहायता से अपने ज़िले का मानचित्र पढ़ते हैं। इस योजना का सबसे अच्छा वर्णन कौन-सा कथन करता है?","optionsHi":["यह ब्रूनर की क्रियात्मक, प्रतिबिंबात्मक और प्रतीकात्मक विधाओं से गुज़रती है, जो मूर्त संक्रियात्मक अधिगमकर्ताओं के अनुकूल है","यह प्रतिबिंबात्मक विधा को पूरी तरह छोड़ देती है, विद्यालय में घूमने से सीधे ज़िले के मानचित्र पर पहुँच जाती है","यह कक्षा 5 के लिए अनुपयुक्त है, क्योंकि किसी भी प्रकार का मानचित्र पढ़ने के लिए औपचारिक संक्रियात्मक चिंतन चाहिए","यह स्किनर की पुनर्बलन अनुसूचियों का अनुसरण करती है, जिसमें प्रत्येक सही स्थल पर पुरस्कार दिया जाता है"],"explanationHi":"घूमना और चिह्नित करना क्रियात्मक है, छपा मानचित्र प्रतिबिंबात्मक है, और पैमाना तथा सूची प्रतीकात्मक हैं। परिचित स्थानों का मानचित्र पढ़ना मूर्त संक्रियात्मक बच्चों की पहुँच में है।"},
  {"id":"cdp-child-development-1594","question":"Assertion (A): Piaget’s stage descriptions should not be used to label a child as ‘incapable’ of a task because of her age. Reason (R): Research shows that performance depends on familiarity with materials, task demands and support, and that ages for stages vary.","options":["A is false, but R is true","A is true, but R is false","Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"Because performance varies with task and context, age-based stage labels can underestimate children. R gives the reason for the caution in A.","difficulty":"very-hard","source":"CTET · DSSSB · State TETs","questionHi":"अभिकथन (A): पियाजे के अवस्था-वर्णनों का उपयोग किसी बच्चे को उसकी आयु के कारण किसी कार्य के लिए ‘अक्षम’ ठहराने में नहीं किया जाना चाहिए। कारण (R): शोध दर्शाता है कि प्रदर्शन सामग्री की परिचितता, कार्य की माँगों और सहायता पर निर्भर करता है, और अवस्थाओं की आयु अलग-अलग होती है।","optionsHi":["A असत्य है, परंतु R सत्य है","A सत्य है, परंतु R असत्य है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं, और R, A की सही व्याख्या है"],"explanationHi":"चूँकि प्रदर्शन कार्य और संदर्भ के साथ बदलता है, आयु-आधारित अवस्था-नामकरण बच्चों को कम आँक सकता है। R, A में दी गई सावधानी का कारण बताता है।"},
  {"id":"cdp-child-development-1595","question":"A Class 6 teacher introduces negative numbers by asking students to move forward and backward on a number line painted on the floor, then draws the line on the board, and finally writes rules such as (−3) + 5 = 2. When a student says, ‘I picture myself walking backwards when I see a minus sign,’ which idea is best illustrated?","options":["Symbolic thinking supported by earlier enactive and iconic experience","An absence of formal reasoning, since he still needs physical images","Classical conditioning, with the minus sign acting as a conditioned stimulus","Pre-operational animism, treating numbers as if they were alive"],"answer":0,"explanation":"The student draws on enactive and iconic experiences to give meaning to symbols, exactly as Bruner intended. It shows integration of modes, not a lack of reasoning.","difficulty":"hard","source":"CTET · KVS · State TETs","questionHi":"कक्षा 6 का शिक्षक छात्रों से फ़र्श पर बनी संख्या-रेखा पर आगे-पीछे चलवाकर ऋणात्मक संख्याओं का परिचय देता है, फिर श्यामपट्ट पर रेखा बनाता है, और अंत में (−3) + 5 = 2 जैसे नियम लिखता है। जब एक छात्र कहता है, ‘ऋण चिह्न देखकर मैं अपने को पीछे की ओर चलता हुआ कल्पित करता हूँ,’ तो कौन-सा विचार सबसे अच्छी तरह दर्शित होता है?","optionsHi":["पूर्ववर्ती क्रियात्मक और प्रतिबिंबात्मक अनुभव द्वारा समर्थित प्रतीकात्मक चिंतन","औपचारिक तर्क का अभाव, क्योंकि उसे अब भी भौतिक प्रतिबिंबों की आवश्यकता है","शास्त्रीय अनुबंधन, जिसमें ऋण चिह्न अनुबंधित उद्दीपक की तरह कार्य करता है","पूर्व-संक्रियात्मक सजीवारोपण, संख्याओं को ऐसे मानना मानो वे जीवित हों"],"explanationHi":"छात्र प्रतीकों को अर्थ देने के लिए क्रियात्मक और प्रतिबिंबात्मक अनुभवों का सहारा लेता है, ठीक जैसा ब्रूनर का उद्देश्य था। यह विधाओं के एकीकरण को दर्शाता है, तर्क के अभाव को नहीं।"},
  {"id":"cdp-child-development-1596","question":"How many of the following are correctly matched as Erikson stage – period of life – virtue? 1. Trust vs mistrust – infancy – hope 2. Initiative vs guilt – pre-school years – purpose 3. Identity vs role confusion – adolescence – fidelity 4. Generativity vs stagnation – late adulthood – wisdom","options":["One","Two","Three","Four"],"answer":2,"explanation":"The first three are correct. Generativity vs stagnation belongs to middle adulthood and yields care; wisdom comes from integrity vs despair in late adulthood.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"निम्नलिखित में से कितने एरिक्सन की अवस्था – जीवन की अवधि – सद्गुण के रूप में सही मिलाए गए हैं? 1. विश्वास बनाम अविश्वास – शैशवावस्था – आशा 2. पहल बनाम अपराध-बोध – पूर्व-विद्यालय वर्ष – उद्देश्य 3. पहचान बनाम भूमिका भ्रम – किशोरावस्था – निष्ठा 4. उत्पादकता बनाम स्थिरता – उत्तर प्रौढ़ावस्था – ज्ञान","optionsHi":["एक","दो","तीन","चार"],"explanationHi":"पहले तीन सही हैं। उत्पादकता बनाम स्थिरता मध्य प्रौढ़ावस्था से संबंधित है और देखभाल का सद्गुण देती है; ज्ञान उत्तर प्रौढ़ावस्था की अखंडता बनाम निराशा से आता है।"},
  {"id":"cdp-child-development-1597","question":"Ainsworth linked attachment patterns to the kind of care infants received. Which caregiving pattern is most associated with insecure-resistant (ambivalent) attachment?","options":["Consistently sensitive and responsive care from the mother alone","Inconsistent care, sometimes warm and responsive, sometimes unavailable or intrusive","Consistently rejecting care that discourages the infant from seeking any closeness at all","Care shared by several warm caregivers in a large joint family"],"answer":1,"explanation":"Unpredictable responsiveness leads infants to cling and protest to get attention; consistent rejection is linked with avoidance, and sensitive care, from one or several caregivers, with security.","difficulty":"very-hard","source":"CTET Paper 1 · State TET","questionHi":"आइंसवर्थ ने संबद्धता के प्रतिरूपों को शिशुओं को मिली देखभाल के प्रकार से जोड़ा। असुरक्षित-प्रतिरोधी (द्विभावी) संबद्धता से कौन-सा देखभाल प्रतिरूप सबसे अधिक जुड़ा है?","optionsHi":["केवल माँ की ओर से निरंतर संवेदनशील और अनुक्रियाशील देखभाल","असंगत देखभाल, कभी स्नेहपूर्ण और अनुक्रियाशील, कभी अनुपलब्ध या हस्तक्षेपकारी","निरंतर अस्वीकार करने वाली देखभाल जो शिशु को किसी भी प्रकार की निकटता खोजने से हतोत्साहित करती है","बड़े संयुक्त परिवार में कई स्नेही देखभालकर्ताओं द्वारा साझा की गई देखभाल"],"explanationHi":"अप्रत्याशित अनुक्रियाशीलता शिशुओं को ध्यान पाने के लिए चिपकने और विरोध करने की ओर ले जाती है; निरंतर अस्वीकार करना परिहार से जुड़ा है, और संवेदनशील देखभाल, एक या अनेक देखभालकर्ताओं से, सुरक्षा से।"},
  {"id":"cdp-child-development-1598","question":"Assertion (A): An avoidant infant’s calm behaviour during separation in the Strange Situation shows that he is not stressed. Reason (R): Physiological measures such as heart rate show that avoidant infants are often aroused and stressed during separation despite appearing calm.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Avoidant infants mask distress; physiological arousal reveals stress, so the outward calm is not evidence of no stress. A is false and R is true.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): स्ट्रेंज सिचुएशन में पृथक्करण के दौरान परिहारी शिशु का शांत व्यवहार दर्शाता है कि वह तनावग्रस्त नहीं है। कारण (R): हृदय गति जैसे शारीरिक माप दर्शाते हैं कि परिहारी शिशु शांत दिखने के बावजूद पृथक्करण के दौरान प्रायः उत्तेजित और तनावग्रस्त होते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"परिहारी शिशु अपनी व्यथा छिपाते हैं; शारीरिक उत्तेजना तनाव को प्रकट करती है, इसलिए बाहरी शांति तनाव न होने का प्रमाण नहीं है। A असत्य है और R सत्य है।"},
  {"id":"cdp-child-development-1599","question":"Which statements about Bronfenbrenner’s model are correct? I. The child is an active participant who influences the environment. II. The mesosystem consists of interactions between the child’s microsystems. III. The exosystem consists of settings in which the child directly participates. IV. The macrosystem includes cultural values, customs and laws.","options":["I, II and IV only","I and III only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"III is false: the exosystem consists of settings in which the child does NOT directly participate, such as a parent’s workplace. The others are correct.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"ब्रोनफेनब्रेनर के मॉडल के बारे में कौन-से कथन सही हैं? I. बच्चा एक सक्रिय भागीदार है जो पर्यावरण को प्रभावित करता है। II. मेसोतंत्र बच्चे के सूक्ष्मतंत्रों के बीच की अंतःक्रियाओं से बना है। III. बाह्यतंत्र उन परिवेशों से बना है जिनमें बच्चा प्रत्यक्ष रूप से भाग लेता है। IV. व्यापकतंत्र में सांस्कृतिक मूल्य, रीति-रिवाज और कानून शामिल हैं।","optionsHi":["केवल I, II और IV","केवल I और III","केवल II, III और IV","I, II, III और IV"],"explanationHi":"III असत्य है: बाह्यतंत्र उन परिवेशों से बना है जिनमें बच्चा प्रत्यक्ष रूप से भाग नहीं लेता, जैसे माता-पिता का कार्यस्थल। शेष सही हैं।"},
  {"id":"cdp-child-development-1600","question":"Bronfenbrenner used the term ‘ecological transition’ for changes in a person’s role or setting. Which of these is the clearest example for a child?","options":["A child reads a new storybook at home with her elder sister","A child’s grandmother tells her a folktale she has never heard before","A child moves from home and anganwadi into Class 1 of a formal school","A child watches a television programme about life in a faraway country"],"answer":2,"explanation":"Entering formal school changes the child’s setting and role (from home child to pupil), a classic ecological transition; such transitions are both outcomes and drivers of development.","difficulty":"very-hard","source":"CTET Paper 1 · State TET","questionHi":"ब्रोनफेनब्रेनर ने किसी व्यक्ति की भूमिका या परिवेश में परिवर्तन के लिए ‘पारिस्थितिक संक्रमण’ शब्द का प्रयोग किया। एक बच्चे के लिए इनमें से सबसे स्पष्ट उदाहरण कौन-सा है?","optionsHi":["एक बच्ची घर पर अपनी बड़ी बहन के साथ कोई नई कहानी की पुस्तक पढ़ती है","एक बच्ची की दादी उसे ऐसी लोककथा सुनाती हैं जो उसने पहले कभी नहीं सुनी","एक बच्चा घर और आँगनवाड़ी से निकलकर औपचारिक विद्यालय की कक्षा 1 में जाता है","एक बच्चा किसी दूर देश के जीवन पर एक टेलीविज़न कार्यक्रम देखता है"],"explanationHi":"औपचारिक विद्यालय में प्रवेश बच्चे का परिवेश और भूमिका बदल देता है (घर के बच्चे से विद्यार्थी), जो एक क्लासिक पारिस्थितिक संक्रमण है; ऐसे संक्रमण विकास के परिणाम भी हैं और प्रेरक भी।"},
  {"id":"cdp-child-development-1601","question":"In a Class 3, boys tease a boy who prefers to play with the girls, calling him ‘girly’, and he begins to avoid them. What does this illustrate, and what should the teacher do?","options":["Peers strongly enforce gender norms; the teacher should challenge the teasing and encourage mixed play","Gender preferences are purely biological, so the teacher should not interfere in how children choose to play","Only parents teach gender roles, so the teacher should simply inform them and stop there","The boy should be encouraged to play only with boys, so that he fits in and is teased less"],"answer":0,"explanation":"From early childhood, peers police gender-typed behaviour through teasing and exclusion; teachers can counter it by addressing teasing and structuring mixed-group activities.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 में, लड़के एक ऐसे लड़के को चिढ़ाते हैं जो लड़कियों के साथ खेलना पसंद करता है, उसे ‘लड़कियों जैसा’ कहते हैं, और वह उनसे बचने लगता है। यह क्या दर्शाता है, और शिक्षक को क्या करना चाहिए?","optionsHi":["साथी लैंगिक मानदंडों को ज़ोर से लागू करते हैं; शिक्षक को चिढ़ाने का विरोध करना चाहिए और मिश्रित खेल को प्रोत्साहित करना चाहिए","लैंगिक पसंद पूरी तरह जैविक है, इसलिए शिक्षक को बच्चों के खेल चुनने के ढंग में हस्तक्षेप नहीं करना चाहिए","केवल माता-पिता लैंगिक भूमिकाएँ सिखाते हैं, इसलिए शिक्षक को उन्हें बस सूचित करके रुक जाना चाहिए","लड़के को केवल लड़कों के साथ खेलने के लिए प्रोत्साहित करना चाहिए, ताकि वह घुल-मिल जाए और उसे कम चिढ़ाया जाए"],"explanationHi":"प्रारंभिक बाल्यावस्था से ही साथी चिढ़ाने और बहिष्कार के माध्यम से लिंग-प्रारूपित व्यवहार पर निगरानी रखते हैं; शिक्षक चिढ़ाने को संबोधित करके और मिश्रित समूह-गतिविधियाँ संरचित करके इसका प्रतिकार कर सकते हैं।"},
  {"id":"cdp-child-development-1602","question":"Assertion (A): Schools teach values and attitudes that are not written in any syllabus. Reason (R): Through routines, rules, seating patterns and teachers’ behaviour, a hidden curriculum socialises students.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Punctuality, obedience, gender roles and attitudes to authority are learnt through school practices, which is exactly what the hidden curriculum means; R explains A.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"अभिकथन (A): विद्यालय ऐसे मूल्य और अभिवृत्तियाँ सिखाते हैं जो किसी पाठ्यक्रम में नहीं लिखे होते। कारण (R): दिनचर्या, नियमों, बैठक-क्रम और शिक्षकों के व्यवहार के माध्यम से एक छिपी हुई पाठ्यचर्या विद्यार्थियों का समाजीकरण करती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"समय की पाबंदी, आज्ञाकारिता, लैंगिक भूमिकाएँ और सत्ता के प्रति अभिवृत्तियाँ विद्यालयी व्यवहारों से सीखी जाती हैं, और छिपी हुई पाठ्यचर्या का यही अर्थ है; R, A की व्याख्या करता है।"},
  {"id":"cdp-child-development-1603","question":"Class 1 children repeatedly demand snacks and toys they have seen in TV advertisements and believe the ads ‘are telling us what’s good’. What does research on children and advertising suggest?","options":["Young children fully understand that ads try to sell products, but they enjoy them anyway","Young children are largely unaffected by advertisements, since they pay attention only to the cartoons in them","Before about seven or eight, children often miss the persuasive intent of ads, making them more susceptible","Only adolescents are affected by advertising, since younger children cannot buy anything"],"answer":2,"explanation":"Young children usually see ads as information or entertainment and do not yet understand they are designed to persuade; media-literacy talk by adults helps.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 1 के बच्चे बार-बार टीवी विज्ञापनों में देखे नाश्ते और खिलौनों की माँग करते हैं और मानते हैं कि विज्ञापन ‘हमें बता रहे हैं कि क्या अच्छा है’। बच्चों और विज्ञापन पर शोध क्या सुझाता है?","optionsHi":["छोटे बच्चे पूरी तरह समझते हैं कि विज्ञापन उत्पाद बेचने का प्रयास करते हैं, फिर भी वे उनका आनंद लेते हैं","छोटे बच्चे विज्ञापनों से काफ़ी हद तक अप्रभावित रहते हैं, क्योंकि वे केवल उनमें के कार्टूनों पर ध्यान देते हैं","लगभग सात या आठ वर्ष की आयु से पहले, बच्चे प्रायः विज्ञापनों के प्रेरक आशय को नहीं समझ पाते, जिससे वे अधिक प्रभावित होते हैं","केवल किशोर विज्ञापन से प्रभावित होते हैं, क्योंकि छोटे बच्चे कुछ खरीद नहीं सकते"],"explanationHi":"छोटे बच्चे सामान्यतः विज्ञापनों को सूचना या मनोरंजन के रूप में देखते हैं और अभी नहीं समझते कि उन्हें प्रेरित करने के लिए बनाया गया है; वयस्कों द्वारा मीडिया-साक्षरता की चर्चा सहायक होती है।"},
  {"id":"cdp-child-development-1604","question":"Research on the move from primary to middle school found that many students’ motivation and self-esteem dip just when schools become more controlling, competitive and impersonal. Eccles explained this as a poor:","options":["Stage–environment fit: schools offer less autonomy and closeness just when adolescents need more","Mesosystem, meaning weak links between the adolescent’s friends, family, school and neighbourhood","Attachment between the student and the mother in early infancy","Maturation of the prefrontal cortex, which temporarily slows down in early adolescence"],"answer":0,"explanation":"Stage–environment fit theory holds that declines occur when school settings offer less autonomy and warmth exactly as adolescents need more; better-matched schools reduce the dip.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"प्राथमिक से माध्यमिक विद्यालय में जाने पर शोध ने पाया कि अनेक विद्यार्थियों की अभिप्रेरणा और आत्म-सम्मान ठीक तभी गिरता है जब विद्यालय अधिक नियंत्रणकारी, प्रतिस्पर्धी और अवैयक्तिक हो जाते हैं। एक्लेस ने इसे किसकी कमी बताकर समझाया?","optionsHi":["अवस्था–पर्यावरण मेल: विद्यालय ठीक तब कम स्वायत्तता और निकटता देते हैं जब किशोरों को अधिक चाहिए","मेसोतंत्र, अर्थात किशोर के मित्रों, परिवार, विद्यालय और पड़ोस के बीच कमज़ोर संबंध","शैशवावस्था में विद्यार्थी और माँ के बीच संबद्धता","प्रीफ्रंटल कॉर्टेक्स की परिपक्वता, जो प्रारंभिक किशोरावस्था में अस्थायी रूप से धीमी हो जाती है"],"explanationHi":"अवस्था–पर्यावरण मेल सिद्धांत मानता है कि गिरावट तब आती है जब विद्यालय परिवेश ठीक उसी समय कम स्वायत्तता और गर्मजोशी देते हैं जब किशोरों को अधिक चाहिए; बेहतर मेल वाले विद्यालय इस गिरावट को घटाते हैं।"},
  {"id":"cdp-child-development-1605","question":"Studies of peer pressure found that conformity to peers in antisocial acts (such as cheating or vandalism) tends to:","options":["Decline steadily from early childhood onwards as children become more independent","Remain about equal at all ages from childhood to adulthood","Be highest in late adulthood, when social approval matters most","Rise in early adolescence, peak around the early-to-mid teens, then decline"],"answer":3,"explanation":"Susceptibility to peer pressure, especially for antisocial behaviour, peaks around the age of 14–15 and then decreases as autonomy and self-regulation grow, which makes the early secondary years critical.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"साथियों के दबाव के अध्ययनों में पाया गया कि समाज-विरोधी कार्यों (जैसे नकल करना या तोड़फोड़) में साथियों के अनुरूप चलने की प्रवृत्ति:","optionsHi":["प्रारंभिक बाल्यावस्था से लगातार घटती है क्योंकि बच्चे अधिक स्वतंत्र होते जाते हैं","बाल्यावस्था से प्रौढ़ावस्था तक सभी आयु में लगभग समान रहती है","उत्तर प्रौढ़ावस्था में सबसे अधिक होती है, जब सामाजिक स्वीकृति सबसे अधिक मायने रखती है","प्रारंभिक किशोरावस्था में बढ़ती है, प्रारंभिक-से-मध्य किशोर वर्षों में चरम पर पहुँचती है, फिर घटती है"],"explanationHi":"साथियों के दबाव के प्रति संवेदनशीलता, विशेषकर समाज-विरोधी व्यवहार के लिए, लगभग 14–15 वर्ष की आयु में चरम पर होती है और फिर स्वायत्तता तथा आत्म-नियमन बढ़ने पर घटती है, जो प्रारंभिक माध्यमिक वर्षों को निर्णायक बनाती है।"},
  {"id":"cdp-child-development-1606","question":"Research on parent–adolescent conflict in many families finds that most disagreements concern:","options":["Fundamental values such as honesty, religion and respect for elders","Everyday matters such as chores, dress, phone use and coming-home times","Whether the parent and the adolescent should continue their relationship at all","Only academic marks and the choice of stream after Class 10"],"answer":1,"explanation":"Conflict rises in early adolescence but mostly concerns day-to-day issues that adolescents see as personal choice and parents as rules; basic values are usually shared.","difficulty":"very-hard","source":"CTET Paper 2 · State TET","questionHi":"अनेक परिवारों में माता-पिता और किशोर के बीच संघर्ष पर शोध में पाया गया कि अधिकांश असहमतियाँ किससे संबंधित होती हैं?","optionsHi":["ईमानदारी, धर्म और बड़ों के प्रति सम्मान जैसे मूलभूत मूल्य","घर के काम, पहनावा, फ़ोन का उपयोग और घर लौटने के समय जैसे रोज़मर्रा के मामले","क्या माता-पिता और किशोर को अपना संबंध बिल्कुल जारी रखना चाहिए","केवल शैक्षणिक अंक और कक्षा 10 के बाद संकाय का चयन"],"explanationHi":"प्रारंभिक किशोरावस्था में संघर्ष बढ़ता है, परंतु अधिकतर रोज़मर्रा के उन मुद्दों पर होता है जिन्हें किशोर निजी पसंद और माता-पिता नियम मानते हैं; मूल मूल्य प्रायः साझा होते हैं।"},
  {"id":"cdp-child-development-1607","question":"During the pubertal growth spurt, a Class 8 boy suddenly has large hands and feet while his trunk is still small, making him look and feel clumsy. What does this show?","options":["Pubertal growth follows exactly the same head-to-toe cephalocaudal pattern that is seen in infancy","He has a growth disorder that needs medical treatment before he grows further","Body parts grow at different times; hands and feet often grow before the trunk, causing temporary awkwardness","Growth of the trunk stops at puberty, so his proportions will stay like this"],"answer":2,"explanation":"In the adolescent spurt, the extremities often grow first and the trunk last, a temporary asynchrony; understanding it helps teachers be sensitive to self-consciousness in PE and classwork.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"यौवनारंभ की वृद्धि-तेज़ी के दौरान कक्षा 8 के एक लड़के के हाथ-पैर अचानक बड़े हो जाते हैं जबकि धड़ अभी छोटा है, जिससे वह अनाड़ी दिखता और महसूस करता है। यह क्या दर्शाता है?","optionsHi":["यौवनारंभ की वृद्धि ठीक वही शीर्ष-से-पाद दिशा वाले (मस्तकपादीय) प्रतिरूप का अनुसरण करती है जो शैशवावस्था में दिखता है","उसे वृद्धि का विकार है जिसे आगे बढ़ने से पहले चिकित्सा की आवश्यकता है","शरीर के अंग अलग-अलग समय पर बढ़ते हैं; हाथ-पैर प्रायः धड़ से पहले बढ़ते हैं, जिससे अस्थायी अनाड़ीपन आता है","यौवनारंभ पर धड़ की वृद्धि रुक जाती है, इसलिए उसके अनुपात ऐसे ही रहेंगे"],"explanationHi":"किशोरावस्था की वृद्धि-तेज़ी में अंग-प्रत्यंग प्रायः पहले और धड़ अंत में बढ़ता है, जो अस्थायी असमकालिकता है; इसे समझना शिक्षकों को शारीरिक शिक्षा और कक्षा-कार्य में आत्म-चेतना के प्रति संवेदनशील होने में सहायता करता है।"},
  {"id":"cdp-child-development-1608","question":"At birth the head is about one-quarter of the body’s length, but in an adult it is about one-eighth. This change in proportion is best explained by:","options":["The proximodistal principle: growth proceeds from the centre to the extremities","Development from specific to general, so that later growth spreads evenly across the body","Uniform growth of all body parts at the same rate throughout life","The cephalocaudal principle: the head develops early and the lower body catches up later"],"answer":3,"explanation":"Growth begins at the head and proceeds downward, so the head is relatively large early; the trunk and legs grow more later, reducing the head’s proportion.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"जन्म के समय सिर शरीर की लंबाई का लगभग एक-चौथाई होता है, परंतु वयस्क में लगभग एक-आठवाँ। अनुपात में इस परिवर्तन की सबसे अच्छी व्याख्या किससे होती है?","optionsHi":["निकट-से-दूर (समीप-दूर) का सिद्धांत: वृद्धि केंद्र से छोरों की ओर बढ़ती है","विशिष्ट से सामान्य की ओर विकास, ताकि बाद की वृद्धि पूरे शरीर में समान रूप से फैले","शरीर के सभी अंगों की पूरे जीवन समान दर से एकसमान वृद्धि","मस्तकपादीय सिद्धांत: सिर पहले विकसित होता है और निचला शरीर बाद में पकड़ बनाता है"],"explanationHi":"वृद्धि सिर से शुरू होकर नीचे की ओर बढ़ती है, इसलिए प्रारंभ में सिर अपेक्षाकृत बड़ा होता है; धड़ और पैर बाद में अधिक बढ़ते हैं, जिससे सिर का अनुपात घट जाता है।"},
  {"id":"cdp-child-development-1609","question":"Scores on infant development tests (based on sensorimotor milestones) given in the first year are poor predictors of IQ in later childhood. Which explanation is most reasonable?","options":["Intelligence does not really exist in infancy at all, so there is nothing for these early tests to measure","Infant tests tap sensorimotor skills, which differ in kind from the reasoning skills later IQ tests measure","IQ is fixed at birth, so testing in infancy is unnecessary and adds nothing","Infant tests always overestimate intelligence because babies are tested when alert"],"answer":1,"explanation":"Because development involves qualitative change, early sensorimotor measures tap different abilities from later reasoning; hence low predictive power, a reason not to label infants.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"पहले वर्ष में दिए गए शिशु-विकास परीक्षणों (संवेदी-गामक उपलब्धियों पर आधारित) के अंक बाद की बाल्यावस्था के IQ के कमज़ोर पूर्वानुमानक हैं। कौन-सी व्याख्या सबसे युक्तिसंगत है?","optionsHi":["शैशवावस्था में बुद्धि वास्तव में होती ही नहीं, इसलिए इन प्रारंभिक परीक्षणों के लिए मापने को कुछ नहीं है","शिशु परीक्षण संवेदी-गामक कौशलों को मापते हैं, जो बाद के IQ परीक्षणों द्वारा मापे जाने वाले तर्क-कौशलों से प्रकृति में भिन्न हैं","IQ जन्म से तय होता है, इसलिए शैशवावस्था में परीक्षण अनावश्यक है और कुछ नहीं जोड़ता","शिशु परीक्षण सदैव बुद्धि को अधिक आँकते हैं क्योंकि शिशुओं का परीक्षण तब होता है जब वे सतर्क होते हैं"],"explanationHi":"चूँकि विकास में गुणात्मक परिवर्तन होता है, प्रारंभिक संवेदी-गामक माप बाद के तर्क से भिन्न क्षमताओं को मापते हैं; इसीलिए पूर्वानुमान शक्ति कम है, जो शिशुओं पर ठप्पा न लगाने का एक कारण है।"},
  {"id":"cdp-child-development-1610","question":"Asked whether it is OK to hit another child if the teacher says there is no rule against it, most four-year-olds say it is still wrong; but they say it is fine to talk without raising a hand if the teacher allows it. What does this suggest about young children’s moral understanding?","options":["They can tell moral rules about harm from social conventions, earlier than Piaget’s account suggested","They see all rules as equally sacred and unchangeable, exactly as Piaget’s account of moral realism claimed","They judge right and wrong only by what the adults around them say","They have no moral understanding at all until they start formal schooling"],"answer":0,"explanation":"Research in social domain theory (Turiel) shows preschoolers treat harm-based rules as wrong regardless of authority, but conventions as changeable, refining the picture of strict moral realism.","difficulty":"very-hard","source":"CTET Paper 1 · State TET","questionHi":"यह पूछे जाने पर कि क्या दूसरे बच्चे को मारना ठीक है यदि शिक्षक कहे कि इसके विरुद्ध कोई नियम नहीं है, अधिकांश चार वर्ष के बच्चे कहते हैं कि यह फिर भी गलत है; परंतु वे कहते हैं कि यदि शिक्षक अनुमति दे तो हाथ उठाए बिना बोलना ठीक है। यह छोटे बच्चों की नैतिक समझ के बारे में क्या सुझाता है?","optionsHi":["वे हानि से संबंधित नैतिक नियमों को सामाजिक परंपराओं से अलग पहचान सकते हैं, पियाजे के वृत्तांत के सुझाव से पहले ही","वे सभी नियमों को समान रूप से पवित्र और अपरिवर्तनीय मानते हैं, ठीक जैसा पियाजे के नैतिक यथार्थवाद के वृत्तांत ने दावा किया","वे सही-गलत का निर्णय केवल अपने आसपास के वयस्कों के कहने से करते हैं","औपचारिक विद्यालय जाने तक उनमें कोई नैतिक समझ नहीं होती"],"explanationHi":"सामाजिक क्षेत्र सिद्धांत (ट्यूरियल) के शोध से पता चलता है कि पूर्व-विद्यालयी बच्चे हानि-आधारित नियमों को अधिकार से स्वतंत्र रूप से गलत मानते हैं, पर परंपराओं को परिवर्तनीय मानते हैं, जो कठोर नैतिक यथार्थवाद की तस्वीर को परिष्कृत करता है।"},
  {"id":"cdp-child-development-1611","question":"After Class 12, a student with admission offers decides to spend a year volunteering in rural schools and talking to people in different careers before choosing a course. Her parents fear she is ‘lost’. How would Erikson view this?","options":["As role confusion, an unhealthy failure of identity that needs professional treatment","As identity foreclosure, accepting a path without exploring","As a psychosocial moratorium, a healthy period of exploration before commitment","As stagnation, a failure of generativity in early adulthood"],"answer":2,"explanation":"A planned period of exploration before committing to adult roles is what Erikson called a moratorium; it typically leads toward identity achievement, not confusion.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 12 के बाद, प्रवेश प्रस्ताव वाली एक छात्रा पाठ्यक्रम चुनने से पहले एक वर्ष ग्रामीण विद्यालयों में स्वयंसेवा करने और विभिन्न व्यवसायों के लोगों से बात करने का निर्णय लेती है। उसके माता-पिता को डर है कि वह ‘भटक गई’ है। एरिक्सन इसे किस रूप में देखेंगे?","optionsHi":["भूमिका भ्रम के रूप में, पहचान की अस्वस्थ विफलता जिसे व्यावसायिक उपचार की आवश्यकता है","पहचान अवरुद्धता के रूप में, बिना खोजबीन के किसी मार्ग को स्वीकार कर लेना","मनोसामाजिक स्थगन के रूप में, प्रतिबद्धता से पहले खोजबीन की एक स्वस्थ अवधि","स्थिरता के रूप में, प्रारंभिक प्रौढ़ावस्था में उत्पादकता की विफलता"],"explanationHi":"प्रौढ़ भूमिकाओं के प्रति प्रतिबद्ध होने से पहले खोजबीन की नियोजित अवधि को एरिक्सन ने स्थगन (मोरेटोरियम) कहा; यह सामान्यतः भ्रम की ओर नहीं, पहचान की प्राप्ति की ओर ले जाती है।"},
  {"id":"cdp-child-development-1612","question":"Working parents worry that sending their toddler to a crèche will damage his attachment to them. What does research on childcare broadly suggest?","options":["Any non-parental care always produces insecure attachment, whatever its quality","Security depends mainly on parents’ sensitivity; good, stable childcare generally does not harm it","Children in full-time childcare cannot form attachments to their parents, only to their paid carers","Childcare quality does not matter, as long as the child is fed and kept safe"],"answer":1,"explanation":"Large studies found parental sensitivity is the main predictor of attachment; high-quality, stable care supports development, while very poor-quality care is the concern.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कामकाजी माता-पिता को चिंता है कि अपने शिशु को क्रेच भेजने से उनके प्रति उसकी संबद्धता को हानि पहुँचेगी। बाल-देखभाल पर शोध व्यापक रूप से क्या सुझाता है?","optionsHi":["माता-पिता के अतिरिक्त किसी की भी देखभाल, गुणवत्ता चाहे जैसी हो, सदैव असुरक्षित संबद्धता उत्पन्न करती है","सुरक्षा मुख्यतः माता-पिता की संवेदनशीलता पर निर्भर करती है; अच्छी, स्थिर बाल-देखभाल सामान्यतः उसे हानि नहीं पहुँचाती","पूरे समय बाल-देखभाल में रहने वाले बच्चे अपने माता-पिता से संबद्धता नहीं बना सकते, केवल वेतनभोगी देखभालकर्ताओं से बनाते हैं","बाल-देखभाल की गुणवत्ता मायने नहीं रखती, बस बच्चे को भोजन मिले और वह सुरक्षित रहे"],"explanationHi":"बड़े अध्ययनों में पाया गया कि माता-पिता की संवेदनशीलता संबद्धता की मुख्य पूर्वानुमानक है; उच्च गुणवत्ता की, स्थिर देखभाल विकास में सहायक है, जबकि बहुत निम्न गुणवत्ता की देखभाल चिंता का विषय है।"},
  {"id":"cdp-child-development-1613","question":"After the mid-day meal scheme reached a village school, teachers found that children paid attention longer, attendance rose and learning improved. Which principle of development does this best illustrate?","options":["Domains of development are interrelated: better nutrition supports attention and learning","Development depends only on heredity, so the improvement must be coincidence","Cognitive development is independent of physical health, so the meal only raised attendance","Development proceeds cephalocaudally, from the head downwards to the feet"],"answer":0,"explanation":"Physical well-being affects cognitive and social functioning; hunger impairs attention, so nutrition supports learning, showing the interrelation of domains.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"मध्याह्न भोजन योजना के एक ग्रामीण विद्यालय में पहुँचने के बाद शिक्षकों ने पाया कि बच्चे अधिक देर तक ध्यान देते हैं, उपस्थिति बढ़ी और अधिगम में सुधार हुआ। विकास का कौन-सा सिद्धांत इसे सबसे अच्छी तरह दर्शाता है?","optionsHi":["विकास के क्षेत्र परस्पर संबद्ध हैं: बेहतर पोषण ध्यान और अधिगम में सहायक होता है","विकास केवल आनुवंशिकता पर निर्भर करता है, इसलिए सुधार संयोग मात्र होगा","संज्ञानात्मक विकास शारीरिक स्वास्थ्य से स्वतंत्र है, इसलिए भोजन ने केवल उपस्थिति बढ़ाई","विकास मस्तकपादीय रूप से, सिर से पैरों की ओर, आगे बढ़ता है"],"explanationHi":"शारीरिक कल्याण संज्ञानात्मक और सामाजिक कार्यप्रणाली को प्रभावित करता है; भूख ध्यान को क्षीण करती है, इसलिए पोषण अधिगम में सहायक होता है, जो विकास के क्षेत्रों की अंतर्संबद्धता दर्शाता है।"},
  {"id":"cdp-child-development-1614","question":"In a Class 7, a group bullies a quiet student while most classmates watch and laugh. Which approach does research find most effective?","options":["Suspending only the bully, with no change at all for the watching classmates or the school’s rules","Asking the victim to be tougher and stand up to the group on his own","A whole-school approach that teaches bystanders to support the victim and report, with clear rules","Ignoring it, as children must sort out such conflicts and it builds character"],"answer":2,"explanation":"Bullying is a group phenomenon sustained by bystanders; whole-school programmes that mobilise bystanders and set clear norms reduce it more than punishing individuals alone.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 में एक समूह एक शांत छात्र को धमकाता है जबकि अधिकांश सहपाठी देखते और हँसते हैं। शोध के अनुसार कौन-सा उपागम सबसे प्रभावी है?","optionsHi":["केवल धमकाने वाले को निलंबित करना, देखने वाले सहपाठियों या विद्यालय के नियमों में कोई बदलाव किए बिना","पीड़ित से कहना कि वह कठोर बने और समूह का अकेले सामना करे","पूरे विद्यालय का उपागम जो दर्शकों को पीड़ित का साथ देना और सूचना देना सिखाता है, स्पष्ट नियमों के साथ","इसे अनदेखा करना, क्योंकि बच्चों को ऐसे विवाद स्वयं सुलझाने होते हैं और इससे चरित्र बनता है"],"explanationHi":"धमकाना एक समूह-परिघटना है जिसे दर्शक बनाए रखते हैं; दर्शकों को सक्रिय करने और स्पष्ट मानदंड स्थापित करने वाले पूरे-विद्यालय के कार्यक्रम केवल व्यक्तियों को दंडित करने से अधिक इसे कम करते हैं।"},
  {"id":"cdp-child-development-1615","question":"A teacher training text says ‘the concrete operational stage runs from 7 to 11 years’ and ‘identity vs role confusion runs from 12 to 18’. How should a teacher interpret such ages?","options":["As exact cut-offs that every child crosses on time, so that teaching can be planned strictly by age","As irrelevant, since research has shown that stages do not exist at all","As approximate averages; children pass through stages in order but at different ages, gradually","As legal age limits that the RTE Act sets for each class"],"answer":2,"explanation":"Stage ages are rough norms; development is continuous with individual differences in rate, so transitions are gradual and vary between children.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"शिक्षक-प्रशिक्षण की एक पुस्तक कहती है ‘मूर्त संक्रियात्मक अवस्था 7 से 11 वर्ष तक चलती है’ और ‘पहचान बनाम भूमिका भ्रम 12 से 18 वर्ष तक चलता है’। शिक्षक को ऐसी आयु की व्याख्या कैसे करनी चाहिए?","optionsHi":["सटीक सीमाओं के रूप में जिन्हें हर बच्चा समय पर पार करता है, ताकि शिक्षण की योजना कड़ाई से आयु के आधार पर बनाई जा सके","अप्रासंगिक के रूप में, क्योंकि शोध ने दिखा दिया है कि अवस्थाएँ होती ही नहीं","अनुमानित औसत के रूप में; बच्चे अवस्थाओं से क्रम में, पर अलग-अलग आयु में, धीरे-धीरे गुज़रते हैं","RTE अधिनियम द्वारा प्रत्येक कक्षा के लिए निर्धारित वैधानिक आयु-सीमाओं के रूप में"],"explanationHi":"अवस्थाओं की आयु मोटे मानक हैं; विकास सतत है और दर में वैयक्तिक भिन्नताएँ होती हैं, इसलिए संक्रमण क्रमिक होते हैं और बच्चों में भिन्न-भिन्न होते हैं।"},
  {"id":"cdp-child-development-1616","question":"Which statement about attachment in adolescence is best supported?","options":["Adolescents no longer need attachment to parents, since peer relationships fully replace it","Secure attachment to parents makes adolescents more dependent on them and less willing to explore","Attachment matters only for girls, as boys become independent at puberty","Securely attached adolescents tend to explore identity and peers more confidently, using parents as a secure base"],"answer":3,"explanation":"Autonomy grows best within secure relationships; parents remain a secure base from which adolescents explore, rather than attachment ending at puberty.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"किशोरावस्था में संबद्धता के बारे में कौन-सा कथन सबसे अच्छी तरह समर्थित है?","optionsHi":["किशोरों को अब माता-पिता से संबद्धता की आवश्यकता नहीं होती, क्योंकि साथियों के संबंध उसकी पूरी तरह जगह ले लेते हैं","माता-पिता से सुरक्षित संबद्धता किशोरों को उन पर अधिक निर्भर और खोज के प्रति कम इच्छुक बनाती है","संबद्धता केवल लड़कियों के लिए मायने रखती है, क्योंकि लड़के यौवनारंभ पर स्वतंत्र हो जाते हैं","सुरक्षित रूप से संबद्ध किशोर पहचान और साथियों की खोज अधिक आत्मविश्वास से करते हैं, माता-पिता को सुरक्षित आधार के रूप में उपयोग करते हुए"],"explanationHi":"स्वायत्तता सुरक्षित संबंधों के भीतर सबसे अच्छी तरह बढ़ती है; माता-पिता वह सुरक्षित आधार बने रहते हैं जहाँ से किशोर खोज करते हैं, यौवनारंभ पर संबद्धता समाप्त नहीं हो जाती।"},
  {"id":"cdp-child-development-1617","question":"A child with Down syndrome joins Class 1. A teacher says, ‘It is genetic, so nothing can be done to help her learn.’ What is the best response?","options":["The teacher is right; genetic conditions are fixed and cannot be influenced by teaching or care","It is due to an extra chromosome 21, but early intervention and inclusive teaching can greatly aid her development","Down syndrome is caused by poor parenting during infancy, so the parents must change first","She should be kept out of school until she matures enough to cope"],"answer":1,"explanation":"Down syndrome is a chromosomal condition (trisomy 21), not a result of parenting; environment and teaching strongly influence how far each child develops, so inclusion and support matter.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"डाउन सिंड्रोम वाली एक बच्ची कक्षा 1 में आती है। एक शिक्षिका कहती है, ‘यह आनुवंशिक है, इसलिए उसे सीखने में मदद करने के लिए कुछ नहीं किया जा सकता।’ सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["शिक्षिका सही है; आनुवंशिक स्थितियाँ स्थिर होती हैं और शिक्षण या देखभाल से प्रभावित नहीं की जा सकतीं","यह गुणसूत्र 21 की अतिरिक्त प्रति के कारण है, परंतु शीघ्र हस्तक्षेप और समावेशी शिक्षण उसके विकास में बहुत सहायक हो सकते हैं","डाउन सिंड्रोम शैशवावस्था में खराब पालन-पोषण से होता है, इसलिए पहले माता-पिता को बदलना होगा","उसे तब तक विद्यालय से बाहर रखना चाहिए जब तक वह सामना करने योग्य परिपक्व न हो जाए"],"explanationHi":"डाउन सिंड्रोम एक गुणसूत्रीय स्थिति (ट्राइसोमी 21) है, पालन-पोषण का परिणाम नहीं; परिवेश और शिक्षण इस पर बहुत प्रभाव डालते हैं कि प्रत्येक बच्चा कितना विकसित होता है, इसलिए समावेशन और सहायता मायने रखते हैं।"},
  {"id":"cdp-child-development-1618","question":"A Class 11 student finds out that seniors are ragging juniors. He reports it, saying, ‘The anti-ragging rules are there to protect the order of the institution; if we let some break them, the whole system collapses.’ His reasoning reflects Kohlberg’s:","options":["Stage 6, because he acts on a self-chosen universal ethical principle","Stage 3, because he wants seniors and teachers to like him","Stage 2, because he will benefit personally by reporting","Stage 4, because he upholds rules to maintain the social order"],"answer":3,"explanation":"Upholding rules because the system depends on them is Stage 4. He refers to institutional order, not universal ethical principles (Stage 6) or personal approval or gain.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 11 के एक छात्र को पता चलता है कि वरिष्ठ छात्र कनिष्ठों की रैगिंग कर रहे हैं। वह इसकी शिकायत करता है, यह कहते हुए, ‘रैगिंग-विरोधी नियम संस्था की व्यवस्था की रक्षा के लिए हैं; यदि हम कुछ को इन्हें तोड़ने दें, तो पूरी प्रणाली ढह जाएगी।’ उसका तर्क कोहलबर्ग की किस अवस्था को दर्शाता है?","optionsHi":["अवस्था 6, क्योंकि वह स्वयं चुने हुए सार्वभौमिक नैतिक सिद्धांत पर कार्य करता है","अवस्था 3, क्योंकि वह चाहता है कि वरिष्ठ और शिक्षक उसे पसंद करें","अवस्था 2, क्योंकि शिकायत करने से उसे व्यक्तिगत लाभ होगा","अवस्था 4, क्योंकि वह सामाजिक व्यवस्था बनाए रखने के लिए नियमों का पालन करवाता है"],"explanationHi":"इसलिए नियमों का पालन करवाना कि प्रणाली उन पर निर्भर है, अवस्था 4 है। वह संस्थागत व्यवस्था का हवाला देता है, सार्वभौमिक नैतिक सिद्धांतों (अवस्था 6) या व्यक्तिगत स्वीकृति अथवा लाभ का नहीं।"},
  {"id":"cdp-child-development-1619","question":"In a Class 6 maths class, the teacher always calls on boys for difficult problems and gives girls easy ones ‘so they don’t feel bad’. Over time, the girls start saying maths is ‘for boys’. What process is mainly at work?","options":["Biological differences in mathematical ability that clearly show up between boys and girls by Class 6","Socialisation through teacher expectations and unequal treatment, shaping students’ self-beliefs","Peer pressure from other girls to avoid maths to stay popular","Immanent justice, the belief that wrongdoing is always punished"],"answer":1,"explanation":"Differential treatment communicates low expectations, which students internalise as beliefs about their own abilities: school as an agent of gender socialisation and a self-fulfilling prophecy.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की गणित-कक्षा में शिक्षक कठिन प्रश्नों के लिए सदैव लड़कों को बुलाता है और लड़कियों को सरल प्रश्न देता है ‘ताकि उन्हें बुरा न लगे’। समय के साथ लड़कियाँ कहने लगती हैं कि गणित ‘लड़कों के लिए’ है। मुख्यतः कौन-सी प्रक्रिया कार्य कर रही है?","optionsHi":["गणितीय योग्यता में जैविक अंतर जो कक्षा 6 तक लड़कों और लड़कियों में स्पष्ट रूप से दिखने लगते हैं","शिक्षक की अपेक्षाओं और असमान व्यवहार के माध्यम से समाजीकरण, जो छात्रों की आत्म-मान्यताओं को आकार देता है","अन्य लड़कियों का साथियों का दबाव कि लोकप्रिय बने रहने के लिए गणित से बचें","आसन्न न्याय, यह विश्वास कि गलत करने पर सदैव दंड मिलता है"],"explanationHi":"भेदभावपूर्ण व्यवहार निम्न अपेक्षाएँ संप्रेषित करता है, जिन्हें छात्र अपनी क्षमताओं के बारे में मान्यताओं के रूप में आंतरिक कर लेते हैं: विद्यालय लैंगिक समाजीकरण का अभिकर्ता और स्वतः पूर्ण होने वाली भविष्यवाणी के रूप में कार्य करता है।"},
  {"id":"cdp-child-development-1620","question":"Staff at a crèche are trained to respond promptly to each infant’s cues and to assign each infant a regular primary caregiver instead of rotating staff daily. According to Erikson and attachment research, this mainly supports:","options":["Basic trust and secure attachment, through consistent and responsive care","Industry, through early achievement and the mastery of small tasks","Autonomy, by leaving infants to soothe themselves without adult help","Identity formation, through a stable adult whose role the infant can copy"],"answer":0,"explanation":"Infants build trust and secure attachment when care is consistent, predictable and responsive; a stable primary caregiver provides exactly this.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक क्रेच के कर्मचारियों को प्रत्येक शिशु के संकेतों पर शीघ्र प्रतिक्रिया देने और प्रतिदिन कर्मचारी बदलने के बजाय प्रत्येक शिशु को एक नियमित प्राथमिक देखभालकर्ता सौंपने का प्रशिक्षण दिया गया है। एरिक्सन और संबद्धता शोध के अनुसार, यह मुख्यतः किसमें सहायक है?","optionsHi":["मूल विश्वास और सुरक्षित संबद्धता, निरंतर और अनुक्रियाशील देखभाल के माध्यम से","उद्यमिता (परिश्रम), प्रारंभिक उपलब्धि और छोटे कार्यों में निपुणता के माध्यम से","स्वायत्तता, शिशुओं को वयस्क की सहायता के बिना स्वयं को शांत करने के लिए छोड़कर","पहचान निर्माण, एक स्थिर वयस्क के माध्यम से जिसकी भूमिका शिशु अनुकरण कर सके"],"explanationHi":"जब देखभाल निरंतर, पूर्वानुमेय और अनुक्रियाशील होती है तब शिशु विश्वास और सुरक्षित संबद्धता बनाते हैं; एक स्थिर प्राथमिक देखभालकर्ता ठीक यही प्रदान करता है।"},
  {"id":"cdp-child-development-1621","question":"Match each theorist with the model of intelligence: 1. Spearman 2. Thurstone 3. Guilford 4. Sternberg; a. A three-dimensional ‘cube’ of operations, contents and products b. A general factor plus specific factors c. A triarchic theory rooted in information processing, experience and context d. Several primary mental abilities","options":["1-b, 2-a, 3-d, 4-c","1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-a, 4-c"],"answer":3,"explanation":"Spearman: g and s; Thurstone: primary mental abilities; Guilford: the structure-of-intellect cube; Sternberg: the triarchic theory with componential, experiential and contextual parts.","difficulty":"hard","source":"CTET · DSSSB TGT","questionHi":"प्रत्येक सिद्धांतकार का मिलान बुद्धि के मॉडल से कीजिए: 1. स्पीयरमैन 2. थर्स्टन 3. गिलफोर्ड 4. स्टर्नबर्ग; a. संक्रियाओं, विषयवस्तुओं और उत्पादों का त्रि-आयामी ‘घन’ b. एक सामान्य कारक और विशिष्ट कारक c. सूचना प्रक्रमण, अनुभव और संदर्भ पर आधारित त्रितंत्रीय सिद्धांत d. कई प्राथमिक मानसिक योग्यताएँ","optionsHi":["1-b, 2-a, 3-d, 4-c","1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-a, 4-c"],"explanationHi":"स्पीयरमैन: g और s; थर्स्टन: प्राथमिक मानसिक योग्यताएँ; गिलफोर्ड: बुद्धि-संरचना का घन; स्टर्नबर्ग: घटकीय, अनुभवात्मक और संदर्भगत भागों वाला त्रितंत्रीय सिद्धांत।"},
  {"id":"cdp-child-development-1622","question":"How many of these statements about Sternberg’s triarchic theory are correct? I. The componential subtheory deals with the internal mental processes of thinking. II. The experiential subtheory deals with handling novelty and automatising familiar tasks. III. The contextual subtheory deals with adapting to, shaping and selecting environments. IV. Sternberg held that conventional IQ tests capture all three aspects fully.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III describe the three subtheories correctly. Sternberg argued that IQ tests tap mainly analytical ability and neglect creative and practical intelligence, so IV is false.","difficulty":"hard","source":"KVS PGT · DSSSB TGT","questionHi":"स्टर्नबर्ग के त्रितंत्रीय सिद्धांत के बारे में इनमें से कितने कथन सही हैं? I. घटकीय उप-सिद्धांत चिंतन की आंतरिक मानसिक प्रक्रियाओं से संबंधित है। II. अनुभवात्मक उप-सिद्धांत नवीनता से निपटने और परिचित कार्यों के स्वचालन से संबंधित है। III. संदर्भगत उप-सिद्धांत परिवेशों के अनुकूलन, उन्हें आकार देने और चुनने से संबंधित है। IV. स्टर्नबर्ग का मत था कि पारंपरिक IQ परीक्षण तीनों पक्षों को पूरी तरह पकड़ते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"I, II और III तीनों उप-सिद्धांतों का सही वर्णन करते हैं। स्टर्नबर्ग ने तर्क दिया कि IQ परीक्षण मुख्यतः विश्लेषणात्मक योग्यता को परखते हैं और सृजनात्मक तथा व्यावहारिक बुद्धि की उपेक्षा करते हैं, इसलिए IV असत्य है।"},
  {"id":"cdp-child-development-1623","question":"Simran, a Class 4 child with cerebral palsy, has limited control over her hand movements but remembers and sings long songs perfectly after hearing them once. Applying Gardner’s ideas, the teacher’s best step is to:","options":["Teach her only music, since that is her single intelligence and she will excel in it","Focus only on improving her handwriting until it reaches grade level, since neat writing underlies every subject","Excuse her from all academic learning because of her disability and let her just sing","Use songs and rhythm to teach multiplication tables and new words, while also supporting her other abilities"],"answer":3,"explanation":"Gardner’s theory encourages using a child’s strengths as entry points to other content; confining her to music alone or concentrating only on her weakness ignores her full potential.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 की मस्तिष्क पक्षाघात (सेरेब्रल पाल्सी) वाली बच्ची सिमरन के हाथ की गतियों पर सीमित नियंत्रण है, परंतु वह लंबे गीत एक बार सुनकर ही पूरी तरह याद रखती और गाती है। गार्डनर के विचारों को लागू करते हुए, शिक्षिका का सबसे अच्छा कदम क्या है?","optionsHi":["उसे केवल संगीत सिखाना, क्योंकि वही उसकी एकमात्र बुद्धि है और उसमें वह उत्कृष्ट होगी","केवल उसकी लिखावट सुधारने पर ध्यान देना जब तक वह कक्षा-स्तर तक न पहुँचे, क्योंकि सुंदर लेखन हर विषय का आधार है","उसकी अक्षमता के कारण उसे सभी शैक्षणिक अधिगम से छूट देना और बस गाने देना","पहाड़े और नए शब्द सिखाने के लिए गीतों और लय का उपयोग करना, साथ ही उसकी अन्य क्षमताओं को भी सहारा देना"],"explanationHi":"गार्डनर का सिद्धांत बच्चे की शक्तियों को अन्य विषयवस्तु के प्रवेश-द्वार के रूप में उपयोग करने को प्रोत्साहित करता है; उसे केवल संगीत तक सीमित करना या केवल उसकी कमज़ोरी पर ध्यान देना उसकी पूरी संभावना की अनदेखी है।"},
  {"id":"cdp-child-development-1624","question":"In the early twentieth century, English-language intelligence tests given to newly arrived immigrants at Ellis Island in the USA labelled large numbers of them ‘feeble-minded’. The main lesson for test users today is that:","options":["Tests should be translated word for word into each test-taker’s mother tongue","A test in an unfamiliar language and culture can produce invalid, harmful labels","Intelligence tests should be given only by trained psychologists, not officials","Tired travellers score lower, so tests should be repeated after a period of rest"],"answer":1,"explanation":"The tests measured familiarity with English and American culture, not intelligence, so the labels were invalid and were used to justify exclusion. Word-for-word translation is tempting but does not remove culturally loaded content or norms built on a different population.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"बीसवीं सदी के प्रारंभ में, अमेरिका के एलिस आइलैंड पर नए आए आप्रवासियों को दिए गए अंग्रेज़ी भाषा के बुद्धि परीक्षणों ने उनमें से बड़ी संख्या को ‘मंदबुद्धि’ करार दिया। आज परीक्षण-प्रयोक्ताओं के लिए मुख्य सबक क्या है?","optionsHi":["परीक्षणों का अनुवाद प्रत्येक परीक्षार्थी की मातृभाषा में शब्द-दर-शब्द होना चाहिए","अपरिचित भाषा और संस्कृति में परीक्षण अमान्य, हानिकारक पहचान-चिह्न उत्पन्न कर सकता है","बुद्धि परीक्षण केवल प्रशिक्षित मनोवैज्ञानिकों द्वारा दिए जाने चाहिए, अधिकारियों द्वारा नहीं","थके हुए यात्री कम अंक पाते हैं, इसलिए विश्राम की अवधि के बाद परीक्षण दोहराए जाने चाहिए"],"explanationHi":"परीक्षण अंग्रेज़ी और अमेरिकी संस्कृति की परिचितता को माप रहे थे, बुद्धि को नहीं, इसलिए वे पहचान-चिह्न अमान्य थे और बहिष्कार को उचित ठहराने में प्रयोग हुए। शब्द-दर-शब्द अनुवाद आकर्षक है परंतु सांस्कृतिक रूप से भारित सामग्री या किसी भिन्न जनसंख्या पर बने मानकों को नहीं हटाता।"},
  {"id":"cdp-child-development-1625","question":"When a student repeatedly disrupts her lesson, a teacher in Ajmer notices her own anger rising, pauses, lowers her voice and speaks to the student calmly after class. Beyond managing the situation, the teacher is modelling for students the emotional-intelligence skill of:","options":["Empathy","Social awareness","Self-motivation","Self-regulation"],"answer":3,"explanation":"Recognising and controlling one’s own impulses before acting is self-regulation; students learn this skill partly by watching how adults handle strong emotions.","difficulty":"moderate","source":"CTET Paper 2 · State TET","questionHi":"जब एक छात्रा बार-बार उसके पाठ में बाधा डालती है, तो अजमेर की एक शिक्षिका अपना क्रोध बढ़ता हुआ महसूस करती है, रुकती है, आवाज़ धीमी करती है और कक्षा के बाद छात्रा से शांति से बात करती है। स्थिति को सँभालने के अलावा, शिक्षिका छात्रों के लिए भावनात्मक बुद्धि के किस कौशल का आदर्श प्रस्तुत कर रही है?","optionsHi":["समानुभूति","सामाजिक जागरूकता","स्व-अभिप्रेरणा","आत्म-नियमन"],"explanationHi":"कार्य करने से पहले अपने आवेगों को पहचानना और नियंत्रित करना आत्म-नियमन है; छात्र यह कौशल आंशिक रूप से यह देखकर सीखते हैं कि वयस्क तीव्र भावनाओं को कैसे सँभालते हैं।"},
  {"id":"cdp-child-development-1626","question":"Assertion (A): In classrooms where wrong answers are laughed at, students offer fewer original ideas. Reason (R): Creative thinking involves taking intellectual risks, which students do only when they feel psychologically safe.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Original ideas are often wrong at first; when mistakes bring ridicule, students avoid risk and offer only safe answers, which is exactly what R describes.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"अभिकथन (A): जिन कक्षाओं में गलत उत्तरों पर हँसा जाता है, वहाँ छात्र कम मौलिक विचार प्रस्तुत करते हैं। कारण (R): सृजनात्मक चिंतन में बौद्धिक जोखिम उठाना शामिल है, जिसे छात्र तभी उठाते हैं जब वे मनोवैज्ञानिक रूप से सुरक्षित महसूस करते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"मौलिक विचार प्रायः पहले गलत होते हैं; जब गलतियों पर उपहास होता है तो छात्र जोखिम से बचते हैं और केवल सुरक्षित उत्तर देते हैं, जो ठीक वही है जो R बताता है।"},
  {"id":"cdp-child-development-1627","question":"A Class 9 teacher gives a hard open-ended design problem on Friday, discusses it briefly, and asks students to come back with ideas on Monday rather than solving it in one sitting. Which aspect of the creative process is she deliberately making room for?","options":["Verification","Functional fixedness","Mental set","Incubation"],"answer":3,"explanation":"Stepping away after initial preparation allows incubation, during which ideas may reorganise without conscious effort; illumination often follows when the problem is taken up again.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 9 की शिक्षिका शुक्रवार को एक कठिन, खुले अंत वाली डिज़ाइन-समस्या देती है, उस पर संक्षेप में चर्चा करती है, और छात्रों से कहती है कि उसे एक बैठक में हल करने के बजाय सोमवार को विचारों के साथ आएँ। वह सृजनात्मक प्रक्रिया के किस पक्ष के लिए जानबूझकर स्थान बना रही है?","optionsHi":["सत्यापन","कार्यात्मक स्थिरता","मानसिक वृत्ति","उद्भवन (इन्क्यूबेशन)"],"explanationHi":"प्रारंभिक तैयारी के बाद दूर हटना उद्भवन की अनुमति देता है, जिसमें विचार बिना सचेत प्रयास के पुनर्गठित हो सकते हैं; समस्या को फिर उठाने पर प्रायः प्रदीप्ति (इल्यूमिनेशन) होती है।"},
  {"id":"cdp-child-development-1628","question":"Which of these questions is genuinely DIVERGENT?","options":["In how many different ways can 12 be written as a product of two whole numbers?","List the three causes of the revolt of 1857 given in the chapter.","Suggest different ways our school could help younger children save electricity.","What is the sum of the interior angles of any triangle drawn on paper?"],"answer":2,"explanation":"The question about 12 sounds open but has one fixed correct answer (1 × 12, 2 × 6, 3 × 4), so it is convergent; only the electricity question invites many varied, original answers.","difficulty":"very-hard","source":"CTET Paper 2 · State TET","questionHi":"इनमें से कौन-सा प्रश्न वास्तव में अपसारी है?","optionsHi":["12 को दो पूर्ण संख्याओं के गुणनफल के रूप में कितने अलग-अलग तरीकों से लिखा जा सकता है?","अध्याय में दिए गए 1857 के विद्रोह के तीन कारणों की सूची बनाइए।","सुझाइए कि हमारा विद्यालय छोटे बच्चों को बिजली बचाने में किन-किन भिन्न तरीकों से सहायता कर सकता है।","कागज़ पर बनाए गए किसी भी त्रिभुज के अंतः कोणों का योग क्या है?"],"explanationHi":"12 वाला प्रश्न खुला लगता है, पर उसका एक निश्चित सही उत्तर है (1 × 12, 2 × 6, 3 × 4), इसलिए वह अभिसारी है; केवल बिजली वाला प्रश्न अनेक विविध, मौलिक उत्तरों को आमंत्रित करता है।"},
  {"id":"cdp-child-development-1629","question":"Three highly able students in a Class 6 section are placed in the same group for project work so that they can challenge one another, while staying in the regular class. This arrangement is called:","options":["Cluster grouping","Grade skipping","Tracking into a separate section","Remedial grouping"],"answer":0,"explanation":"Cluster grouping places a small group of gifted students together within a regular class, giving them intellectual peers without separating them from the rest of the class.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 के एक अनुभाग के तीन अत्यंत योग्य छात्रों को परियोजना कार्य के लिए एक ही समूह में रखा जाता है ताकि वे एक-दूसरे को चुनौती दे सकें, जबकि वे नियमित कक्षा में ही रहते हैं। इस व्यवस्था को क्या कहते हैं?","optionsHi":["गुच्छ समूहीकरण (क्लस्टर ग्रुपिंग)","कक्षा छोड़कर आगे बढ़ाना (ग्रेड स्किपिंग)","अलग अनुभाग में स्तरबद्ध करना (ट्रैकिंग)","उपचारात्मक समूहीकरण"],"explanationHi":"गुच्छ समूहीकरण प्रतिभाशाली छात्रों के एक छोटे समूह को नियमित कक्षा के भीतर साथ रखता है, जिससे उन्हें कक्षा के शेष छात्रों से अलग किए बिना बौद्धिक साथी मिलते हैं।"},
  {"id":"cdp-child-development-1630","question":"According to Carol Ann Tomlinson’s model of differentiated instruction, a teacher may adapt content, process and products according to students’:","options":["Caste, religion and gender of the students","Readiness, interests and learning profiles","IQ scores and last year’s class rank only","Parents’ occupation, income and education"],"answer":1,"explanation":"Differentiation responds to readiness (current level), interests and learning profiles; it never sorts children by social identity.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कैरल ऐन टॉमलिंसन के विभेदित अनुदेशन के मॉडल के अनुसार, शिक्षक विषयवस्तु, प्रक्रिया और उत्पादों को छात्रों की किन बातों के अनुसार अनुकूलित कर सकता है?","optionsHi":["छात्रों की जाति, धर्म और लिंग","तत्परता, रुचियाँ और अधिगम प्रोफ़ाइल","केवल IQ अंक और पिछले वर्ष की कक्षा-श्रेणी","माता-पिता का व्यवसाय, आय और शिक्षा"],"explanationHi":"विभेदन तत्परता (वर्तमान स्तर), रुचियों और अधिगम प्रोफ़ाइल के अनुरूप प्रतिक्रिया करता है; यह बच्चों को कभी सामाजिक पहचान के आधार पर नहीं छाँटता।"},
  {"id":"cdp-child-development-1631","question":"A teacher in a fishing village in Kerala uses children’s knowledge of tides, boat repair, net-mending and fish-market prices to teach measurement, patterns and money. This approach draws on what researchers (Luis Moll and colleagues) call:","options":["Cultural deficit","Hidden curriculum","Funds of knowledge","Crystallised intelligence"],"answer":2,"explanation":"Funds of knowledge are the skills and knowledge accumulated in households and communities; using them treats children’s backgrounds as resources rather than deficits.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"केरल के एक मछुआरा गाँव का शिक्षक माप, प्रतिरूप और मुद्रा सिखाने के लिए बच्चों के ज्वार-भाटे, नाव की मरम्मत, जाल बुनने और मछली-बाज़ार के भाव के ज्ञान का उपयोग करता है। यह उपागम उस पर आधारित है जिसे शोधकर्ता (लुइस मोल और सहयोगी) क्या कहते हैं?","optionsHi":["सांस्कृतिक अभाव","छिपी हुई पाठ्यचर्या","ज्ञान के कोष (फंड्स ऑफ़ नॉलेज)","क्रिस्टलीकृत बुद्धि"],"explanationHi":"ज्ञान के कोष वे कौशल और ज्ञान हैं जो परिवारों और समुदायों में संचित होते हैं; इनका उपयोग बच्चों की पृष्ठभूमि को अभाव के बजाय संसाधन मानता है।"},
  {"id":"cdp-child-development-1632","question":"Mangal, a Class 1 child whose home language is Kurukh, stays silent in class where only Hindi is used. His teacher writes ‘dull and unresponsive’ in his record. Which is the best evaluation?","options":["The teacher is right; long silence in class is a reliable sign of low intelligence","Mangal should be shifted to a special school, where teachers have more time for slow children like him","The teacher should wait for Mangal to pick up Hindi on his own from his classmates before assessing him at all","His silence likely reflects the language gap, not ability; use his home language and visuals before judging"],"answer":3,"explanation":"A mismatch between home and school language commonly causes silence in the early months; labelling it as dullness is a serious misreading that can become self-fulfilling.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"कक्षा 1 का बच्चा मंगल, जिसकी घर की भाषा कुड़ुख है, उस कक्षा में चुप रहता है जहाँ केवल हिंदी का प्रयोग होता है। उसकी शिक्षिका उसके अभिलेख में ‘मंदबुद्धि और अनुक्रियाहीन’ लिखती है। सबसे अच्छा मूल्यांकन कौन-सा है?","optionsHi":["शिक्षिका सही है; कक्षा में लंबी चुप्पी निम्न बुद्धि का विश्वसनीय संकेत है","मंगल को विशेष विद्यालय में भेज देना चाहिए, जहाँ शिक्षकों के पास उसके जैसे धीमे बच्चों के लिए अधिक समय होता है","शिक्षिका को मंगल का आकलन करने से पहले प्रतीक्षा करनी चाहिए कि वह सहपाठियों से स्वयं हिंदी सीख ले","उसकी चुप्पी संभवतः भाषा के अंतर को दर्शाती है, क्षमता को नहीं; आकलन से पहले उसकी घर की भाषा और चित्रों का प्रयोग करें"],"explanationHi":"घर और विद्यालय की भाषा में बेमेल प्रारंभिक महीनों में चुप्पी का सामान्य कारण होता है; इसे मंदबुद्धि कहना गंभीर गलत पाठ है जो स्वतः पूर्ण होने वाली भविष्यवाणी बन सकता है।"},
  {"id":"cdp-child-development-1633","question":"NCF 2005 recommends that children be taught in their home language in the early years. Which view of language mainly underlies this recommendation?","options":["Language is only a means of communication and has no real link with how children think or form concepts","Children grasp new concepts best in the language in which they already think and make meaning","Home languages are easier to set and mark in the board examinations later on","Using English from Class 1 harms young children’s physical health and growth"],"answer":1,"explanation":"NCF 2005 treats language as a medium of thought as well as communication; concepts built in the home language are deeper and transfer later to other languages.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"NCF 2005 सिफ़ारिश करता है कि बच्चों को प्रारंभिक वर्षों में उनकी घर की भाषा में पढ़ाया जाए। इस सिफ़ारिश के पीछे भाषा का कौन-सा दृष्टिकोण मुख्यतः है?","optionsHi":["भाषा केवल संप्रेषण का साधन है और बच्चों के सोचने या संप्रत्यय बनाने से उसका कोई वास्तविक संबंध नहीं है","बच्चे नए संप्रत्यय उसी भाषा में सबसे अच्छी तरह ग्रहण करते हैं जिसमें वे पहले से सोचते और अर्थ बनाते हैं","बाद में बोर्ड परीक्षाओं में घर की भाषाओं में प्रश्न बनाना और जाँचना आसान होता है","कक्षा 1 से अंग्रेज़ी का प्रयोग छोटे बच्चों के शारीरिक स्वास्थ्य और वृद्धि को हानि पहुँचाता है"],"explanationHi":"NCF 2005 भाषा को संप्रेषण के साथ-साथ चिंतन का माध्यम भी मानता है; घर की भाषा में बने संप्रत्यय अधिक गहरे होते हैं और बाद में अन्य भाषाओं में स्थानांतरित होते हैं।"},
  {"id":"cdp-child-development-1634","question":"Which of the following statements correctly compare Piaget and Vygotsky? I. For Piaget, development largely sets the limits of what can be learned. II. For Vygotsky, good learning can lead development. III. For Piaget, language is the main driving force of cognitive development. IV. For Vygotsky, social interaction is the source of higher mental functions.","options":["I, II and III only","II and III only","I, II and IV only","I, III and IV only"],"answer":2,"explanation":"Piaget saw language as reflecting cognitive development rather than driving it, so III is false; the other three statements correctly describe the two theorists.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"इनमें से कौन-से कथन पियाजे और वाइगोत्स्की की सही तुलना करते हैं? I. पियाजे के लिए, विकास बहुत हद तक यह सीमा निर्धारित करता है कि क्या सीखा जा सकता है। II. वाइगोत्स्की के लिए, अच्छा अधिगम विकास को आगे ले जा सकता है। III. पियाजे के लिए, भाषा संज्ञानात्मक विकास की मुख्य प्रेरक शक्ति है। IV. वाइगोत्स्की के लिए, सामाजिक अंतःक्रिया उच्चतर मानसिक प्रकार्यों का स्रोत है।","optionsHi":["केवल I, II और III","केवल II और III","केवल I, II और IV","केवल I, III और IV"],"explanationHi":"पियाजे भाषा को संज्ञानात्मक विकास को चलाने वाली नहीं, उसे प्रतिबिंबित करने वाली मानते थे, इसलिए III असत्य है; शेष तीन कथन दोनों सिद्धांतकारों का सही वर्णन करते हैं।"},
  {"id":"cdp-child-development-1635","question":"In the 1980s, deaf children brought together in new schools in Nicaragua, without any existing sign language, created their own sign language, and later, younger groups of children made it grammatically richer. This case is often cited as evidence for:","options":["Skinner’s view that grammar must be shaped by adults who reinforce children’s correct forms","An innate human capacity to create grammatical structure, especially in young children","The strong Sapir–Whorf hypothesis that language fixes how people perceive","Piaget’s claim that language appears only after formal operations are reached"],"answer":1,"explanation":"No adult model provided the grammar; children themselves built and regularised it, which is consistent with nativist ideas of an inborn language capacity that is strongest early in life.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"1980 के दशक में, निकारागुआ के नए विद्यालयों में एक साथ लाए गए बधिर बच्चों ने, बिना किसी मौजूदा सांकेतिक भाषा के, अपनी सांकेतिक भाषा रची, और बाद में छोटे बच्चों के समूहों ने उसे व्याकरणिक रूप से अधिक समृद्ध बनाया। इस उदाहरण को प्रायः किसके प्रमाण के रूप में उद्धृत किया जाता है?","optionsHi":["स्किनर के इस मत का कि व्याकरण को वयस्कों द्वारा आकार दिया जाना चाहिए जो बच्चों के सही रूपों को पुनर्बलित करते हैं","व्याकरणिक संरचना रचने की जन्मजात मानवीय क्षमता का, विशेषकर छोटे बच्चों में","प्रबल सपीर–वॉर्फ़ परिकल्पना का कि भाषा तय करती है कि लोग कैसे प्रत्यक्षण करते हैं","पियाजे के इस दावे का कि भाषा औपचारिक संक्रियाओं तक पहुँचने के बाद ही प्रकट होती है"],"explanationHi":"किसी वयस्क ने व्याकरण का नमूना नहीं दिया; बच्चों ने स्वयं उसे बनाया और नियमित किया, जो जीवन के आरंभ में सबसे प्रबल जन्मजात भाषा-क्षमता के नेटिविस्ट विचारों से मेल खाता है।"},
  {"id":"cdp-child-development-1636","question":"A science teacher says, ‘Once students learn words like “evaporation” and “condensation”, they have tools to notice and think about processes they earlier saw only as water disappearing.’ This view of words as tools for thinking is closest to:","options":["Vygotsky’s idea of language as a psychological tool","Skinner’s idea of verbal operants shaped by reward","Freud’s idea of the unconscious mind shaping all thought","Thorndike’s law of exercise strengthening bonds"],"answer":0,"explanation":"Vygotsky saw language as the main psychological tool that mediates and reorganises thinking; scientific words help children form systematic concepts.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक विज्ञान शिक्षक कहता है, ‘जब छात्र “वाष्पीकरण” और “संघनन” जैसे शब्द सीख लेते हैं, तो उनके पास उन प्रक्रियाओं को देखने और उन पर सोचने के उपकरण आ जाते हैं जिन्हें वे पहले केवल पानी के गायब होने के रूप में देखते थे।’ शब्दों को चिंतन के उपकरण मानने वाला यह दृष्टिकोण किसके सबसे निकट है?","optionsHi":["भाषा को मनोवैज्ञानिक उपकरण मानने का वाइगोत्स्की का विचार","पुरस्कार से आकार पाने वाले मौखिक प्रचालकों का स्किनर का विचार","अचेतन मन द्वारा सभी चिंतन को आकार देने का फ्रायड का विचार","बंधनों को सुदृढ़ करने वाले अभ्यास के नियम का थॉर्नडाइक का विचार"],"explanationHi":"वाइगोत्स्की भाषा को मुख्य मनोवैज्ञानिक उपकरण मानते थे जो चिंतन में मध्यस्थता करता और उसे पुनर्गठित करता है; वैज्ञानिक शब्द बच्चों को व्यवस्थित संप्रत्यय बनाने में सहायता करते हैं।"},
  {"id":"cdp-child-development-1637","question":"A father in Ludhiana tells his eight-year-old son, ‘Boys don’t cry,’ whenever he is hurt or sad. Seen through the lens of gender as a social construct, the most likely effect is that the boy:","options":["Learns that hiding feelings is part of being male, limiting his emotional expression and help-seeking","Becomes emotionally stronger in a healthy way, since he learns early to control upsetting feelings","Is unaffected, because the way emotions are expressed is fixed by biology rather than by what parents say","Learns to express his feelings more openly, since he is told to speak up"],"answer":0,"explanation":"Gender norms restrict boys as well as girls; teaching boys to suppress sadness can hinder emotional development and willingness to seek support.","difficulty":"moderate","source":"CTET Paper 1 · State TET","questionHi":"लुधियाना का एक पिता अपने आठ वर्षीय बेटे को, जब भी वह चोटिल या उदास होता है, कहता है, ‘लड़के नहीं रोते।’ लिंग को सामाजिक रचना मानने के दृष्टिकोण से, सबसे संभावित प्रभाव यह है कि लड़का:","optionsHi":["सीखता है कि भावनाएँ छिपाना पुरुष होने का हिस्सा है, जिससे उसकी भावनात्मक अभिव्यक्ति और सहायता माँगना सीमित होता है","स्वस्थ तरीके से भावनात्मक रूप से अधिक मज़बूत बनता है, क्योंकि वह परेशान करने वाली भावनाओं को जल्दी नियंत्रित करना सीखता है","अप्रभावित रहता है, क्योंकि भावनाओं की अभिव्यक्ति का ढंग माता-पिता के कहने से नहीं बल्कि जीव-विज्ञान से तय होता है","अपनी भावनाओं को अधिक खुलकर व्यक्त करना सीखता है, क्योंकि उसे बोलने को कहा गया है"],"explanationHi":"लैंगिक मानदंड लड़कियों के साथ-साथ लड़कों को भी सीमित करते हैं; लड़कों को उदासी दबाना सिखाना भावनात्मक विकास और सहायता माँगने की इच्छा में बाधक हो सकता है।"},
  {"id":"cdp-child-development-1638","question":"In a Class 7 debate, Arjun interrupts and argues forcefully and is praised as ‘a natural leader’, while Meera, who does the same, is called ‘rude and too loud for a girl’. This is an example of:","options":["Fair, gender-neutral assessment of the two students’ debating skills","Positive discrimination in favour of girls in debates","A double standard judging the same behaviour differently by gender","Criterion-referenced evaluation of speaking skills"],"answer":2,"explanation":"Judging identical behaviour by gender expectations is a double standard; it teaches girls to be silent and boys that assertiveness is their right.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"कक्षा 7 की एक वाद-विवाद प्रतियोगिता में, अर्जुन टोकता है और ज़ोरदार तर्क देता है और उसे ‘जन्मजात नेता’ कहकर सराहा जाता है, जबकि मीरा, जो वही करती है, ‘बदतमीज़ और एक लड़की के लिए बहुत ज़ोर से बोलने वाली’ कही जाती है। यह किसका उदाहरण है?","optionsHi":["दोनों छात्रों की वाद-विवाद क्षमता का निष्पक्ष, लिंग-तटस्थ आकलन","वाद-विवाद में लड़कियों के पक्ष में सकारात्मक भेदभाव","दोहरा मापदंड, जो समान व्यवहार को लिंग के आधार पर भिन्न रूप से आँकता है","बोलने के कौशलों का मानदंड-संदर्भित मूल्यांकन"],"explanationHi":"समान व्यवहार को लैंगिक अपेक्षाओं से आँकना दोहरा मापदंड है; यह लड़कियों को चुप रहना और लड़कों को यह सिखाता है कि मुखरता उनका अधिकार है।"},
  {"id":"cdp-child-development-1639","question":"How does Kohlberg’s cognitive-developmental account of gender-role development differ from social learning theory?","options":["Children learn gender roles only through the rewards and punishments that their parents and teachers give them","Once children grasp that gender is permanent, they seek out same-gender activities, socialising themselves","Gender roles are fixed by prenatal hormones, so understanding plays no part in them","Children do not understand gender at all until adolescence, when roles are first learned"],"answer":1,"explanation":"For Kohlberg, cognitive understanding (gender constancy) comes first and motivates children to adopt gender-typed behaviour; social learning theory puts modelling and reinforcement first.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"लैंगिक भूमिका के विकास का कोहलबर्ग का संज्ञानात्मक-विकासात्मक विवरण सामाजिक अधिगम सिद्धांत से कैसे भिन्न है?","optionsHi":["बच्चे लैंगिक भूमिकाएँ केवल उन पुरस्कारों और दंडों से सीखते हैं जो उनके माता-पिता और शिक्षक उन्हें देते हैं","जब बच्चे समझ लेते हैं कि लिंग स्थायी है, तो वे समान-लिंग की गतिविधियाँ खोजते हैं, और स्वयं का समाजीकरण करते हैं","लैंगिक भूमिकाएँ जन्मपूर्व हार्मोनों द्वारा तय होती हैं, इसलिए समझ की इनमें कोई भूमिका नहीं","बच्चे किशोरावस्था तक लिंग को बिल्कुल नहीं समझते, जब पहली बार भूमिकाएँ सीखी जाती हैं"],"explanationHi":"कोहलबर्ग के लिए संज्ञानात्मक समझ (लिंग-स्थिरता) पहले आती है और बच्चों को लिंग-प्रारूपित व्यवहार अपनाने के लिए प्रेरित करती है; सामाजिक अधिगम सिद्धांत अनुकरण और पुनर्बलन को पहले रखता है।"},
  {"id":"cdp-child-development-1640","question":"A Dalit girl from a landless family in rural Bihar faces disadvantages that differ from those of a Dalit boy or an upper-caste girl, because caste, gender and poverty combine. The concept that captures this is:","options":["Psychological androgyny","Bourdieu’s cultural capital","Intersectionality","Gender constancy"],"answer":2,"explanation":"Intersectionality (Kimberlé Crenshaw) describes how social identities such as caste, gender and class interact to produce particular, compounded forms of disadvantage.","difficulty":"very-hard","source":"KVS PGT · CTET Paper 2","questionHi":"ग्रामीण बिहार के एक भूमिहीन परिवार की दलित बालिका को ऐसी हानियों का सामना करना पड़ता है जो दलित बालक या उच्च जाति की बालिका की हानियों से भिन्न होती हैं, क्योंकि जाति, लिंग और गरीबी मिल जाते हैं। इसे समझाने वाली अवधारणा कौन-सी है?","optionsHi":["मनोवैज्ञानिक उभयलिंगता","बोर्द्यू की सांस्कृतिक पूँजी","अंतर्संबद्धता (इंटरसेक्शनैलिटी)","लिंग-स्थिरता"],"explanationHi":"अंतर्संबद्धता (किम्बर्ली क्रेनशॉ) बताती है कि जाति, लिंग और वर्ग जैसी सामाजिक पहचानें कैसे परस्पर क्रिया करके विशिष्ट, संयुक्त रूप के नुकसान उत्पन्न करती हैं।"},
  {"id":"cdp-child-development-1641","question":"The same Class 5 students take an arithmetic test on Monday and an equivalent version on Wednesday. Their scores and ranks change wildly between the two days, with no teaching in between. The main problem is that the test is:","options":["Invalid but reliable","Unreliable","Too objective","Criterion-referenced"],"answer":1,"explanation":"Reliability is the consistency of scores across occasions or forms; wildly varying results show low reliability, and an unreliable test cannot be valid either.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 5 के वही छात्र सोमवार को अंकगणित की एक परीक्षा और बुधवार को उसका समतुल्य संस्करण देते हैं। बीच में बिना किसी शिक्षण के, दोनों दिन उनके अंक और श्रेणियाँ बहुत बदल जाती हैं। मुख्य समस्या यह है कि परीक्षण:","optionsHi":["अमान्य परंतु विश्वसनीय है","अविश्वसनीय है","अत्यधिक वस्तुनिष्ठ है","मानदंड-संदर्भित है"],"explanationHi":"विश्वसनीयता अवसरों या रूपों में अंकों की संगति है; बहुत बदलते परिणाम निम्न विश्वसनीयता दर्शाते हैं, और अविश्वसनीय परीक्षण वैध भी नहीं हो सकता।"},
  {"id":"cdp-child-development-1642","question":"A Class 4 teacher passes on a note to next year’s teacher: ‘Rohit – trouble-maker, weak, don’t expect much.’ The most serious risk of this practice is that:","options":["The next teacher will simply ignore the note and form her own views of Rohit over time","Rohit will be promoted too early to the next class without being ready for its much harder work","It will make record-keeping slower and add to the paperwork of both teachers at year end","The next teacher’s expectations may be biased from day one, making the label self-fulfilling"],"answer":3,"explanation":"Labels passed on without context shape how the next teacher treats the child; useful records should describe specific needs and strategies, not fixed judgements.","difficulty":"hard","source":"CTET Paper 1 · State TET","questionHi":"कक्षा 4 की एक शिक्षिका अगले वर्ष की शिक्षिका को एक टिप्पणी भेजती है: ‘रोहित – उपद्रवी, कमज़ोर, अधिक अपेक्षा मत रखना।’ इस प्रथा का सबसे गंभीर जोखिम क्या है?","optionsHi":["अगली शिक्षिका टिप्पणी को बस अनदेखा कर देगी और समय के साथ रोहित के बारे में अपनी राय बनाएगी","रोहित को बहुत जल्दी अगली कक्षा में पदोन्नत कर दिया जाएगा, बिना उसके कहीं अधिक कठिन कार्य के लिए तैयार हुए","इससे अभिलेख-रखरखाव धीमा होगा और वर्ष के अंत में दोनों शिक्षिकाओं का कागज़ी काम बढ़ेगा","अगली शिक्षिका की अपेक्षाएँ पहले दिन से पूर्वाग्रहग्रस्त हो सकती हैं, जिससे वह पहचान-चिह्न स्वतः सत्य हो जाएगा"],"explanationHi":"बिना संदर्भ के आगे बढ़ाए गए पहचान-चिह्न अगली शिक्षिका के बच्चे के प्रति व्यवहार को आकार देते हैं; उपयोगी अभिलेखों में स्थिर निर्णयों के बजाय विशिष्ट आवश्यकताओं और युक्तियों का वर्णन होना चाहिए।"},
  {"id":"cdp-child-development-1643","question":"Assertion (A): Displaying the rank list of every Class 3 child on the notice board motivates all children to work harder. Reason (R): Constant comparison with peers can damage the self-esteem and motivation of children who rank low.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Public ranking may spur a few but discourages many, especially those at the bottom; NCF 2005 discourages comparison of young children, so A is false and R is true.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): कक्षा 3 के प्रत्येक बच्चे की श्रेणी-सूची सूचना-पट्ट पर लगाना सभी बच्चों को अधिक परिश्रम के लिए प्रेरित करता है। कारण (R): साथियों से निरंतर तुलना निम्न श्रेणी वाले बच्चों के आत्म-सम्मान और अभिप्रेरणा को हानि पहुँचा सकती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"सार्वजनिक श्रेणी निर्धारण कुछ को प्रेरित कर सकता है पर अनेक को हतोत्साहित करता है, विशेषकर निचली श्रेणी वालों को; NCF 2005 छोटे बच्चों की तुलना को हतोत्साहित करता है, इसलिए A असत्य और R सत्य है।"},
  {"id":"cdp-child-development-1644","question":"Assertion (A): A student with a very high IQ may still struggle to work well in group projects. Reason (R): IQ and interpersonal or emotional skills are relatively distinct abilities.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because IQ tests mainly measure reasoning and knowledge, a high score does not guarantee skills in understanding others and managing emotions, which group work needs.","difficulty":"hard","source":"CTET Paper 2 · State TET","questionHi":"अभिकथन (A): बहुत उच्च IQ वाले छात्र को भी समूह परियोजनाओं में अच्छी तरह कार्य करने में कठिनाई हो सकती है। कारण (R): IQ और अंतर्वैयक्तिक या भावनात्मक कौशल अपेक्षाकृत भिन्न योग्यताएँ हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"चूँकि IQ परीक्षण मुख्यतः तर्क और ज्ञान को मापते हैं, उच्च अंक दूसरों को समझने और भावनाओं को सँभालने के कौशलों की गारंटी नहीं देता, जिनकी समूह-कार्य को आवश्यकता होती है।"},
  {"id":"cdp-child-development-1645","question":"David Wechsler described intelligence as the ‘aggregate or global capacity’ of a person to act purposefully, to think rationally and to deal effectively with the environment. Which feature of his tests followed from this broad view?","options":["Separate verbal and performance scales, as well as an overall score","A single vocabulary test treated as the complete measure of ability","A focus on the speed of simple reactions as the core of intelligence","Testing only children below the age of eight"],"answer":0,"explanation":"Wechsler saw intelligence as global but made up of different abilities, so his scales gave verbal and performance (non-verbal) scores as well as a full-scale IQ, and he built scales for adults too.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"डेविड वेक्स्लर ने बुद्धि को व्यक्ति की उद्देश्यपूर्ण ढंग से कार्य करने, तर्कसंगत ढंग से सोचने और पर्यावरण से प्रभावी ढंग से निपटने की ‘समुच्चित या वैश्विक क्षमता’ बताया। उनके परीक्षणों की कौन-सी विशेषता इस व्यापक दृष्टिकोण से उत्पन्न हुई?","optionsHi":["अलग-अलग शाब्दिक और निष्पादन पैमाने, तथा एक समग्र अंक","एक अकेला शब्दावली परीक्षण जिसे योग्यता का पूर्ण माप माना जाए","सरल प्रतिक्रियाओं की गति पर ध्यान, बुद्धि के मूल के रूप में","केवल आठ वर्ष से कम आयु के बच्चों का परीक्षण"],"explanationHi":"वेक्स्लर बुद्धि को वैश्विक किंतु विभिन्न योग्यताओं से बनी मानते थे, इसलिए उनके पैमाने पूर्ण-पैमाना IQ के साथ शाब्दिक और निष्पादन (अशाब्दिक) अंक भी देते थे, और उन्होंने वयस्कों के लिए भी पैमाने बनाए।"},
  {"id":"cdp-child-development-1646","question":"A boy aged 12 years has a mental age of 9 years. What is his ratio IQ?","options":["133","80","75","70"],"answer":2,"explanation":"Ratio IQ = MA ÷ CA × 100 = 9 ÷ 12 × 100 = 75. Inverting the ratio gives about 133.","difficulty":"moderate","source":"CTET Paper 2 · State TET","questionHi":"12 वर्ष के एक लड़के की मानसिक आयु 9 वर्ष है। उसका अनुपात IQ क्या है?","optionsHi":["133","80","75","70"],"explanationHi":"अनुपात IQ = MA ÷ CA × 100 = 9 ÷ 12 × 100 = 75। अनुपात को उलटने पर लगभग 133 आता है।"},
  {"id":"cdp-child-development-1647","question":"Wallach and Kogan gave children creativity tasks in a relaxed, game-like, untimed setting instead of a test-like one. What did they find?","options":["Creativity scores were virtually identical to IQ scores, so a separate creativity test is not needed","Creativity scores were fairly independent of intelligence scores, suggesting the two are distinct","Children could not produce any creative ideas at all without the pressure of time limits","Only children with IQs above 140 showed any creativity on the game-like tasks"],"answer":1,"explanation":"In a non-evaluative, game-like setting, creativity measures correlated highly with one another but only weakly with intelligence measures, supporting creativity as a distinct ability.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"वैलेक और कोगन ने बच्चों को परीक्षा जैसे परिवेश के बजाय आरामदायक, खेल जैसे, बिना समय-सीमा वाले परिवेश में सृजनात्मकता के कार्य दिए। उन्होंने क्या पाया?","optionsHi":["सृजनात्मकता के अंक IQ अंकों के लगभग समान थे, इसलिए अलग सृजनात्मकता परीक्षण की आवश्यकता नहीं है","सृजनात्मकता के अंक बुद्धि के अंकों से काफ़ी स्वतंत्र थे, जो सुझाता है कि दोनों भिन्न हैं","समय-सीमा के दबाव के बिना बच्चे कोई भी सृजनात्मक विचार नहीं दे सके","केवल 140 से अधिक IQ वाले बच्चों ने खेल जैसे कार्यों पर कुछ सृजनात्मकता दिखाई"],"explanationHi":"गैर-मूल्यांकनात्मक, खेल जैसे परिवेश में सृजनात्मकता के माप आपस में उच्च सहसंबद्ध थे परंतु बुद्धि के मापों से केवल कमज़ोर रूप से, जो सृजनात्मकता को एक भिन्न योग्यता के रूप में समर्थन देता है।"},
  {"id":"cdp-child-development-1648","question":"Which of the following is one of the six PRODUCTS in Guilford’s structure-of-intellect model?","options":["Divergent production","Figural content","Transformations","Evaluation"],"answer":2,"explanation":"Guilford’s products are units, classes, relations, systems, transformations and implications. Divergent production and evaluation are operations, and figural is a content.","difficulty":"very-hard","source":"KVS PGT · DSSSB PGT","questionHi":"निम्नलिखित में से कौन गिलफोर्ड के बुद्धि-संरचना मॉडल के छह उत्पादों में से एक है?","optionsHi":["अपसारी उत्पादन","आकृतिक विषयवस्तु","रूपांतरण","मूल्यांकन"],"explanationHi":"गिलफोर्ड के उत्पाद हैं: इकाइयाँ, वर्ग, संबंध, प्रणालियाँ, रूपांतरण और निहितार्थ। अपसारी उत्पादन और मूल्यांकन संक्रियाएँ हैं, और आकृतिक एक विषयवस्तु है।"},
  {"id":"cdp-child-development-1649","question":"Assertion (A): Thurstone originally argued that intelligence consists of several primary abilities rather than one dominant general factor. Reason (R): Thurstone used factor analysis of scores on many tests.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but factor analysis is only the method; Spearman used it too and reached g. Thurstone’s conclusion came from his particular way of analysing the factors, so R does not explain A.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"अभिकथन (A): थर्स्टन ने मूलतः तर्क दिया कि बुद्धि में एक प्रमुख सामान्य कारक के बजाय अनेक प्राथमिक योग्यताएँ होती हैं। कारण (R): थर्स्टन ने अनेक परीक्षणों के अंकों के कारक विश्लेषण का प्रयोग किया।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं, परंतु कारक विश्लेषण केवल विधि है; स्पीयरमैन ने भी इसका प्रयोग किया और g तक पहुँचे। थर्स्टन का निष्कर्ष कारकों के विश्लेषण के उनके विशेष तरीके से आया, इसलिए R, A की व्याख्या नहीं करता।"},
  {"id":"cdp-child-development-1650","question":"Provoked by a classmate’s remark, Class 9 student Kunal suddenly explodes in rage and throws a book, then regrets it minutes later and cannot explain why he reacted so strongly. Daniel Goleman popularised a term for such moments when emotion overwhelms rational control:","options":["Emotional (‘amygdala’) hijacking","Self-actualisation (Maslow’s peak need)","Cognitive dissonance (Festinger’s tension)","Functional fixedness under provocation"],"answer":0,"explanation":"Goleman used ‘amygdala hijack’ for sudden emotional reactions that override reasoned responses; EI training teaches pausing and naming feelings to regain control.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक सहपाठी की टिप्पणी से भड़ककर कक्षा 9 का छात्र कुणाल अचानक क्रोध में फट पड़ता है और पुस्तक फेंक देता है, फिर कुछ मिनट बाद पछताता है और समझा नहीं पाता कि उसने इतनी तीव्र प्रतिक्रिया क्यों दी। डैनियल गोलमैन ने ऐसे क्षणों के लिए, जब भावना तर्कसंगत नियंत्रण पर हावी हो जाती है, कौन-सा शब्द लोकप्रिय बनाया?","optionsHi":["भावनात्मक (‘एमिग्डाला’) अपहरण","आत्म-सिद्धि (मैस्लो की चरम आवश्यकता)","संज्ञानात्मक विसंवादिता (फेस्टिंगर का तनाव)","उत्तेजना में कार्यात्मक स्थिरता"],"explanationHi":"गोलमैन ने ‘एमिग्डाला अपहरण’ शब्द का प्रयोग उन अचानक भावनात्मक प्रतिक्रियाओं के लिए किया जो तर्कसंगत प्रतिक्रियाओं को दबा देती हैं; EI प्रशिक्षण रुकना और भावनाओं को नाम देना सिखाता है ताकि नियंत्रण वापस मिले।"},
  {"id":"cdp-child-development-1651","question":"Which feature is found in inclusion but NOT in integration?","options":["The child with a disability attends a regular neighbourhood school with other children","The child receives some help from a resource teacher outside the regular class for part of the day","The school changes its curriculum, teaching and assessment so that diverse learners can take part","The child is expected to meet the existing standards with the existing teaching methods"],"answer":2,"explanation":"Both arrangements may place children in regular schools with some extra help, but only inclusion restructures the system itself; expecting the child to fit unchanged methods is the mark of integration.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कौन-सी विशेषता समावेशन में पाई जाती है परंतु एकीकरण में नहीं?","optionsHi":["दिव्यांग बच्चा अन्य बच्चों के साथ नियमित पड़ोस के विद्यालय में जाता है","बच्चे को दिन के कुछ समय नियमित कक्षा के बाहर संसाधन शिक्षक से कुछ सहायता मिलती है","विद्यालय अपनी पाठ्यचर्या, शिक्षण और आकलन को इस प्रकार बदलता है कि विविध अधिगमकर्ता भाग ले सकें","बच्चे से अपेक्षा की जाती है कि वह मौजूदा शिक्षण-विधियों के साथ मौजूदा मानकों को पूरा करे"],"explanationHi":"दोनों व्यवस्थाएँ बच्चों को कुछ अतिरिक्त सहायता के साथ नियमित विद्यालयों में रख सकती हैं, पर केवल समावेशन ही प्रणाली को स्वयं पुनर्संरचित करता है; बच्चे से अपरिवर्तित विधियों में ढलने की अपेक्षा एकीकरण की पहचान है।"},
  {"id":"cdp-child-development-1652","question":"In a mixed-ability Class 6 class, a few students always finish early and then disturb others, while the teacher is busy with a small group. Which differentiation strategy best addresses this?","options":["Asking early finishers to sit silently with arms folded until everyone is done, to build patience","Setting up ‘anchor activities’: meaningful tasks linked to the unit that students move to on their own","Giving early finishers extra copies of the same exercise to practise more","Sending early finishers to the library without any task, so that they can read whatever they happen to like"],"answer":1,"explanation":"Anchor activities keep finished students learning independently and free the teacher to work with groups; silent waiting or repeated drill wastes their time and invites disruption.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"मिश्रित-योग्यता वाली कक्षा 6 में कुछ छात्र सदैव जल्दी काम पूरा कर लेते हैं और फिर दूसरों को बाधित करते हैं, जबकि शिक्षिका एक छोटे समूह के साथ व्यस्त होती है। कौन-सी विभेदन रणनीति इसे सबसे अच्छी तरह संबोधित करती है?","optionsHi":["जल्दी पूरा करने वालों से कहना कि सब के पूरा करने तक हाथ बाँधकर चुपचाप बैठें, ताकि धैर्य विकसित हो","‘एंकर गतिविधियाँ’ तैयार करना: इकाई से जुड़े अर्थपूर्ण कार्य जिन पर छात्र स्वयं चले जाएँ","जल्दी पूरा करने वालों को उसी अभ्यास की अतिरिक्त प्रतियाँ देना ताकि वे और अभ्यास करें","जल्दी पूरा करने वालों को बिना किसी कार्य के पुस्तकालय भेज देना, ताकि वे जो पसंद आए वह पढ़ सकें"],"explanationHi":"एंकर गतिविधियाँ काम पूरा कर चुके छात्रों को स्वतंत्र रूप से सीखते रखती हैं और शिक्षिका को समूहों के साथ कार्य करने के लिए मुक्त करती हैं; चुपचाप प्रतीक्षा या बार-बार का अभ्यास उनका समय व्यर्थ करता है और बाधा को आमंत्रित करता है।"},
  {"id":"cdp-child-development-1653","question":"A Class 3 teacher asks, ‘Find as many ways as you can to make 24 using any operations.’ Some children write 12 + 12, while others write 4 × 3 × 2 or 30 − 6. Why is this a good task for an inclusive class?","options":["It is easy, so every child gets full marks and feels successful, which is the main aim of inclusion","It tests only the brightest children, who can find the most ways","It replaces the need for any other teaching of operations in Class 3","It is open-ended: every child can start at her own level while able learners go much further"],"answer":3,"explanation":"Open tasks with an easy entry point and no upper limit let the whole class work on the same problem at different depths, which differentiates naturally.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 3 की शिक्षिका पूछती है, ‘किन्हीं भी संक्रियाओं का उपयोग करके 24 बनाने के जितने तरीके ढूँढ सको, ढूँढो।’ कुछ बच्चे 12 + 12 लिखते हैं, जबकि अन्य 4 × 3 × 2 या 30 − 6 लिखते हैं। यह समावेशी कक्षा के लिए अच्छा कार्य क्यों है?","optionsHi":["यह आसान है, इसलिए हर बच्चे को पूरे अंक मिलते हैं और वह सफल महसूस करता है, जो समावेशन का मुख्य उद्देश्य है","यह केवल सबसे तेज़ बच्चों की परीक्षा लेता है, जो सबसे अधिक तरीके ढूँढ सकते हैं","यह कक्षा 3 में संक्रियाओं के किसी अन्य शिक्षण की आवश्यकता को समाप्त कर देता है","यह खुले अंत वाला है: हर बच्चा अपने स्तर से शुरू कर सकता है जबकि सक्षम अधिगमकर्ता कहीं आगे जा सकते हैं"],"explanationHi":"आसान प्रवेश-बिंदु और बिना ऊपरी सीमा वाले खुले कार्य पूरी कक्षा को एक ही समस्या पर अलग-अलग गहराई में कार्य करने देते हैं, जो स्वाभाविक रूप से विभेदन करता है।"},
  {"id":"cdp-child-development-1654","question":"Anjali, a gifted Class 4 student, scores 100% on every class maths test. Her teacher wants to know how far her ability actually goes. What is the best approach?","options":["Using above-level problems, since grade-level tests have a ceiling and cannot show how far she can go","Relying on her class test scores, since a score of 100% on every single test already shows her full ability","Comparing her marks with the class average to see how far ahead of others she is","Waiting for the board exams in Class 10 to give a fair judgement of her ability"],"answer":0,"explanation":"Grade-level tests have a ceiling: a perfect score shows only that she has mastered that level, not how far beyond it she can go; above-level tasks reveal her true level for planning.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 4 की प्रतिभाशाली छात्रा अंजलि हर कक्षा गणित परीक्षण में 100% अंक पाती है। उसकी शिक्षिका जानना चाहती है कि उसकी क्षमता वास्तव में कितनी दूर तक जाती है। सबसे अच्छा उपागम क्या है?","optionsHi":["कक्षा-स्तर से ऊपर के प्रश्नों का प्रयोग, क्योंकि कक्षा-स्तर के परीक्षणों की एक सीमा होती है और वे नहीं दिखा सकते कि वह कितनी दूर जा सकती है","उसके कक्षा परीक्षण के अंकों पर निर्भर रहना, क्योंकि हर परीक्षण में 100% अंक पहले ही उसकी पूरी क्षमता दर्शाते हैं","उसके अंकों की कक्षा के औसत से तुलना करना यह देखने के लिए कि वह दूसरों से कितनी आगे है","कक्षा 10 की बोर्ड परीक्षाओं की प्रतीक्षा करना ताकि उसकी क्षमता का निष्पक्ष निर्णय हो सके"],"explanationHi":"कक्षा-स्तर के परीक्षणों की एक सीमा (सीलिंग) होती है: पूर्ण अंक केवल यह दिखाते हैं कि उसने उस स्तर पर महारत पा ली है, यह नहीं कि वह उसके आगे कितनी दूर जा सकती है; ऊपरी-स्तर के कार्य योजना बनाने के लिए उसका वास्तविक स्तर उजागर करते हैं।"},
  {"id":"cdp-child-development-1655","question":"Siddharth, in Class 6, reasons brilliantly in discussions and spends hours on his interest in astronomy, but he is disorganised, loses track in routine tasks and rarely finishes written work. What should the teacher plan?","options":["Only challenging enrichment, since he is clearly gifted and the rest will follow","Only support for attention and organisation, since his written marks are low and that must come first","Both: challenging, interest-based work for his ability and structured support for organisation","Neither, since bright children usually grow out of such problems by themselves"],"answer":2,"explanation":"He shows signs of being twice-exceptional, with high ability alongside attention difficulties; meeting only one need either wastes his ability or leaves the barrier in place.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 6 का सिद्धार्थ चर्चाओं में शानदार तर्क देता है और खगोल-विज्ञान में अपनी रुचि पर घंटों बिताता है, परंतु वह अव्यवस्थित है, नियमित कार्यों में भटक जाता है और शायद ही कभी लिखित कार्य पूरा करता है। शिक्षक को क्या योजना बनानी चाहिए?","optionsHi":["केवल चुनौतीपूर्ण समृद्धीकरण, क्योंकि वह स्पष्टतः प्रतिभाशाली है और शेष अपने आप ठीक हो जाएगा","केवल ध्यान और संगठन के लिए सहायता, क्योंकि उसके लिखित अंक कम हैं और वही पहले आना चाहिए","दोनों: उसकी योग्यता के लिए चुनौतीपूर्ण, रुचि-आधारित कार्य और संगठन के लिए संरचित सहायता","दोनों में से कोई नहीं, क्योंकि मेधावी बच्चे प्रायः ऐसी समस्याओं से स्वयं उबर जाते हैं"],"explanationHi":"वह द्वि-असाधारण (ट्वाइस-एक्सेप्शनल) होने के संकेत दिखाता है, जिसमें उच्च योग्यता के साथ ध्यान संबंधी कठिनाइयाँ हैं; केवल एक आवश्यकता की पूर्ति या तो उसकी योग्यता को व्यर्थ करती है या बाधा को बनाए रखती है।"},
  {"id":"cdp-child-development-1656","question":"After repeated failure, Rahul, a Class 5 student with dyslexia, says, ‘I am stupid. I will never be able to read.’ Which teacher response is most helpful?","options":["‘Don’t worry, reading is not that important; many successful people never read much.’","‘You’re not stupid; your brain learns reading differently, and look, you read many more words than in June.’","‘If you just work harder and stop being lazy, you will soon read as well as the others in class.’","‘Everyone is good at something; let’s forget about reading and focus on your drawing.’"],"answer":1,"explanation":"Helping the child attribute difficulty to a specific, changeable cause and showing real evidence of progress counters learned helplessness; ‘work harder’ implies he has not tried, and dismissing reading lowers expectations.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"बार-बार असफल होने के बाद कक्षा 5 का डिस्लेक्सिया वाला छात्र राहुल कहता है, ‘मैं मूर्ख हूँ। मैं कभी पढ़ नहीं पाऊँगा।’ शिक्षक की कौन-सी प्रतिक्रिया सबसे अधिक सहायक है?","optionsHi":["‘चिंता मत करो, पढ़ना इतना महत्वपूर्ण नहीं है; अनेक सफल लोगों ने कभी अधिक नहीं पढ़ा।’","‘तुम मूर्ख नहीं हो; तुम्हारा मस्तिष्क पढ़ना अलग ढंग से सीखता है, और देखो, तुम जून की तुलना में कहीं अधिक शब्द पढ़ लेते हो।’","‘यदि तुम बस और परिश्रम करो और आलस्य छोड़ दो, तो जल्दी ही कक्षा के अन्य बच्चों जितना अच्छा पढ़ने लगोगे।’","‘हर कोई किसी न किसी चीज़ में अच्छा होता है; पढ़ना भूल जाओ और अपनी चित्रकारी पर ध्यान दो।’"],"explanationHi":"बच्चे को कठिनाई का कारण किसी विशिष्ट, परिवर्तनीय कारण को मानने में मदद करना और प्रगति के वास्तविक प्रमाण दिखाना सीखी हुई असहायता का प्रतिकार करता है; ‘और परिश्रम करो’ यह जताता है कि उसने प्रयास नहीं किया, और पढ़ने को खारिज करना अपेक्षाएँ घटाता है।"},
  {"id":"cdp-child-development-1657","question":"Neel, a Class 6 student with ADHD, often drifts off during independent work. The teacher gives him a card with a small box for every 10 minutes, where he ticks whether he was on task, and they review it together at the end. What is the main purpose of this strategy?","options":["To collect a written record of his lapses that can later justify a punishment or report to parents","To teach self-monitoring, so that he gradually learns to notice and manage his own attention","To replace the teacher’s instruction with a self-paced checklist","To compare him publicly with classmates who stay on task more"],"answer":1,"explanation":"Self-monitoring builds the self-regulation that ADHD makes difficult; reviewing it together turns it into a learning tool rather than a punishment record.","difficulty":"hard","source":"CTET · State TETs","questionHi":"ADHD वाला कक्षा 6 का छात्र नील स्वतंत्र कार्य के दौरान प्रायः भटक जाता है। शिक्षक उसे एक कार्ड देता है जिसमें प्रत्येक 10 मिनट के लिए एक छोटा खाना है, जहाँ वह टिक करता है कि वह कार्य पर था या नहीं, और अंत में वे साथ मिलकर उसकी समीक्षा करते हैं। इस युक्ति का मुख्य उद्देश्य क्या है?","optionsHi":["उसकी चूकों का लिखित अभिलेख एकत्र करना जो बाद में दंड या माता-पिता को रिपोर्ट करने को उचित ठहराए","आत्म-निरीक्षण सिखाना, ताकि वह धीरे-धीरे अपने ध्यान को पहचानना और सँभालना सीखे","शिक्षक के निर्देशन के स्थान पर स्व-गति वाली जाँच-सूची रखना","उसकी तुलना सार्वजनिक रूप से उन सहपाठियों से करना जो अधिक ध्यान लगाए रखते हैं"],"explanationHi":"आत्म-निरीक्षण उस आत्म-नियमन को विकसित करता है जिसे ADHD कठिन बना देता है; साथ मिलकर समीक्षा इसे दंड-अभिलेख के बजाय अधिगम का उपकरण बनाती है।"},
  {"id":"cdp-child-development-1658","question":"A Class 2 teacher tells Arnav, who is autistic, ‘Be good during assembly.’ He looks confused and wanders off. Which instruction would work better?","options":["‘Behave yourself properly during the assembly today, Arnav.’","‘You know what I mean, so don’t make me repeat it again.’","‘Be nice to everyone, and just do whatever the other children around you are doing.’","‘Stand in line next to Riya and keep your hands by your side till the bell rings.’"],"answer":3,"explanation":"Abstract instructions like ‘be good’ do not tell an autistic child what to do; concrete, specific statements of the expected behaviour are clearer.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 2 की शिक्षिका ऑटिस्टिक बच्चे अर्नव से कहती है, ‘सभा के दौरान अच्छे बने रहना।’ वह उलझन में दिखता है और इधर-उधर भटक जाता है। कौन-सा निर्देश बेहतर काम करेगा?","optionsHi":["‘अर्नव, आज सभा में ठीक से व्यवहार करना।’","‘तुम जानते हो मेरा क्या मतलब है, इसलिए मुझे दोबारा मत कहलवाओ।’","‘सबके साथ अच्छे रहना, और बस वही करना जो तुम्हारे आसपास के दूसरे बच्चे कर रहे हैं।’","‘रिया के बगल में पंक्ति में खड़े रहो और घंटी बजने तक हाथ अपने बगल में रखो।’"],"explanationHi":"‘अच्छे बनो’ जैसे अमूर्त निर्देश ऑटिस्टिक बच्चे को यह नहीं बताते कि क्या करना है; अपेक्षित व्यवहार के ठोस, विशिष्ट कथन अधिक स्पष्ट होते हैं।"},
  {"id":"cdp-child-development-1659","question":"Tara, a Class 4 student on the autism spectrum, knows the names and sizes of dozens of dinosaurs but has no interest in maths. What is a sensible step for the teacher?","options":["Using dinosaurs in maths tasks, such as comparing their lengths or ordering their weights","Banning all dinosaur talk in class until her maths marks begin to improve steadily","Ignoring her interest completely, since dinosaurs are not part of the Class 4 maths syllabus","Telling her parents to stop buying dinosaur books so she focuses on maths"],"answer":0,"explanation":"Strong special interests are powerful motivators for many autistic learners and can be used as a bridge into less preferred subjects.","difficulty":"moderate","source":"CTET · UPTET · State TETs","questionHi":"ऑटिज़्म स्पेक्ट्रम पर कक्षा 4 की छात्रा तारा दर्जनों डायनासोरों के नाम और आकार जानती है, परंतु गणित में उसकी कोई रुचि नहीं है। शिक्षक के लिए समझदारी भरा कदम क्या है?","optionsHi":["गणित के कार्यों में डायनासोरों का उपयोग, जैसे उनकी लंबाई की तुलना या उनके वज़न को क्रमबद्ध करना","जब तक उसके गणित के अंक लगातार सुधरने न लगें, कक्षा में डायनासोर की सारी चर्चा पर रोक लगाना","उसकी रुचि को पूरी तरह अनदेखा करना, क्योंकि डायनासोर कक्षा 4 के गणित पाठ्यक्रम का हिस्सा नहीं हैं","उसके माता-पिता से कहना कि डायनासोर की पुस्तकें खरीदना बंद करें ताकि वह गणित पर ध्यान दे"],"explanationHi":"अनेक ऑटिस्टिक अधिगमकर्ताओं के लिए प्रबल विशेष रुचियाँ शक्तिशाली प्रेरक होती हैं और कम पसंद के विषयों तक पहुँचने के सेतु के रूप में प्रयोग की जा सकती हैं।"},
  {"id":"cdp-child-development-1660","question":"Using the sighted-guide technique, a Class 7 student is guiding her blind classmate to the computer lab. Which description of the correct technique is right?","options":["The guide holds the blind student’s hand firmly and leads him along the corridor at her pace","The guide walks behind him and steers him gently by the shoulders at each turn","The blind student holds the guide’s arm just above the elbow, walking half a step behind","The guide walks ahead and calls out directions from a short distance away"],"answer":2,"explanation":"Holding just above the guide's elbow and following half a step behind lets the blind person feel turns, steps and stops through the guide's movement while staying in control.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"दृष्टिसक्षम मार्गदर्शक तकनीक का उपयोग करते हुए कक्षा 7 की एक छात्रा अपने दृष्टिबाधित सहपाठी को कंप्यूटर प्रयोगशाला तक ले जा रही है। सही तकनीक का कौन-सा वर्णन सही है?","optionsHi":["मार्गदर्शक दृष्टिबाधित छात्र का हाथ मज़बूती से पकड़ती है और उसे अपनी गति से गलियारे में ले जाती है","मार्गदर्शक उसके पीछे चलती है और हर मोड़ पर उसे कंधों से धीरे-धीरे मोड़ती है","दृष्टिबाधित छात्र मार्गदर्शक की बाँह को कोहनी के ठीक ऊपर पकड़ता है, आधा कदम पीछे चलते हुए","मार्गदर्शक आगे चलती है और थोड़ी दूरी से दिशाएँ पुकारकर बताती है"],"explanationHi":"मार्गदर्शक की कोहनी के ठीक ऊपर पकड़ना और आधा कदम पीछे चलना दृष्टिबाधित व्यक्ति को मार्गदर्शक की गति से मोड़, सीढ़ियाँ और रुकना महसूस करने देता है, जबकि वह नियंत्रण में रहता है।"},
  {"id":"cdp-child-development-1661","question":"Assertion (A): Even though audiobooks and screen readers are widely available, blind children should still learn Braille. Reason (R): Braille gives direct access to spelling, punctuation and the layout of written language, which listening alone does not.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Listening gives content but not the written form; Braille literacy lets blind learners read and write independently with full knowledge of spelling and structure, which is why it remains essential.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): ऑडियोबुक और स्क्रीन रीडर के व्यापक रूप से उपलब्ध होने पर भी दृष्टिबाधित बच्चों को ब्रेल सीखनी चाहिए। कारण (R): ब्रेल वर्तनी, विराम चिह्नों और लिखित भाषा के लेआउट तक प्रत्यक्ष पहुँच देती है, जो केवल सुनने से नहीं मिलती।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"सुनना विषयवस्तु देता है पर लिखित रूप नहीं; ब्रेल साक्षरता दृष्टिबाधित अधिगमकर्ताओं को वर्तनी और संरचना के पूरे ज्ञान के साथ स्वतंत्र रूप से पढ़ने-लिखने देती है, इसीलिए यह आवश्यक बनी रहती है।"},
  {"id":"cdp-child-development-1662","question":"During a fire drill, Naveen, a deaf Class 5 student, does not respond to the alarm bell and stays in the classroom. Which arrangement best ensures his safety?","options":["Asking him to watch the clock closely at the scheduled drill time and leave when it is due","Installing visual alerts such as flashing lights, plus a buddy who always alerts him","Excusing him from fire drills since he cannot hear the bell","Making the bell much louder so that he can feel or hear it"],"answer":1,"explanation":"Emergency systems that rely only on sound exclude deaf students; visual signals plus a buddy give reliable access, and a louder bell may still not be heard.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"अग्नि-अभ्यास के दौरान, कक्षा 5 का बधिर छात्र नवीन अलार्म की घंटी पर प्रतिक्रिया नहीं देता और कक्षा में ही रहता है। कौन-सी व्यवस्था उसकी सुरक्षा को सबसे अच्छी तरह सुनिश्चित करती है?","optionsHi":["उससे कहना कि निर्धारित अभ्यास के समय घड़ी पर ध्यान रखे और समय होने पर बाहर निकले","चमकती रोशनी जैसी दृश्य चेतावनियाँ लगाना, साथ ही एक सहपाठी-साथी जो सदैव उसे सूचित करे","उसे अग्नि-अभ्यास से छूट देना, क्योंकि वह घंटी नहीं सुन सकता","घंटी को बहुत अधिक तेज़ करना ताकि वह उसे महसूस कर या सुन सके"],"explanationHi":"जो आपातकालीन प्रणालियाँ केवल ध्वनि पर निर्भर हैं वे बधिर छात्रों को बाहर रखती हैं; दृश्य संकेत और एक साथी विश्वसनीय पहुँच देते हैं, और तेज़ घंटी भी शायद न सुनी जाए।"},
  {"id":"cdp-child-development-1663","question":"Javed, a Class 5 student with cerebral palsy, answers questions by pointing slowly to words on a communication board. Classmates often call out the answer before he finishes. What should the teacher do?","options":["Ask Javed only yes/no questions so that he can answer quickly and less class time is used","Let classmates finish his answers for him, since they usually know exactly what he is trying to say anyway","Give him enough wait time, teach the class to wait until he finishes, and value his answers equally","Stop asking him questions during lessons to avoid embarrassing him"],"answer":2,"explanation":"Users of communication aids need extra time; when others answer for them, they lose their voice, so the class must learn to wait and respect his communication.","difficulty":"hard","source":"CTET · State TETs","questionHi":"मस्तिष्क पक्षाघात वाला कक्षा 5 का छात्र जावेद संप्रेषण-पट पर शब्दों की ओर धीरे-धीरे इशारा करके प्रश्नों के उत्तर देता है। सहपाठी प्रायः उसके पूरा करने से पहले ही उत्तर बोल देते हैं। शिक्षक को क्या करना चाहिए?","optionsHi":["जावेद से केवल हाँ/नहीं वाले प्रश्न पूछना ताकि वह जल्दी उत्तर दे सके और कक्षा का कम समय लगे","सहपाठियों को उसके उत्तर पूरे करने देना, क्योंकि वे प्रायः ठीक-ठीक जानते हैं कि वह क्या कहना चाहता है","उसे पर्याप्त प्रतीक्षा-समय देना, कक्षा को सिखाना कि वह पूरा करने तक प्रतीक्षा करे, और उसके उत्तरों को समान महत्व देना","पाठों के दौरान उससे प्रश्न पूछना बंद करना ताकि वह शर्मिंदा न हो"],"explanationHi":"संप्रेषण-सहायकों के उपयोगकर्ताओं को अतिरिक्त समय चाहिए; जब दूसरे उनके लिए उत्तर देते हैं तो वे अपनी आवाज़ खो देते हैं, इसलिए कक्षा को प्रतीक्षा करना और उसके संप्रेषण का सम्मान करना सीखना चाहिए।"},
  {"id":"cdp-child-development-1664","question":"For the annual sports day, the PE teacher plans to make Kunal, who uses a wheelchair, the scorekeeper for all events. Which alternative best reflects inclusion?","options":["Excusing Kunal from sports day so that he is not placed under any strain","Keeping him as scorekeeper for every event, since it is a responsible job that keeps him busy and involved all day","Letting him watch from the stands with his parents and cheer for his house","Designing some events all can join, such as seated throws and mixed relays, so that Kunal competes with others"],"answer":3,"explanation":"Inclusion means taking part as a participant, not only as a helper; adapting events lets him compete, while a permanent support role still leaves him on the sidelines.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"वार्षिक खेल दिवस के लिए, शारीरिक शिक्षा शिक्षक व्हीलचेयर का उपयोग करने वाले कुणाल को सभी प्रतियोगिताओं का अंक-लेखक बनाने की योजना बनाता है। कौन-सा विकल्प समावेशन को सबसे अच्छी तरह दर्शाता है?","optionsHi":["कुणाल को खेल दिवस से छूट देना ताकि उस पर कोई दबाव न पड़े","उसे हर प्रतियोगिता का अंक-लेखक बनाए रखना, क्योंकि यह एक ज़िम्मेदार कार्य है जो उसे पूरे दिन व्यस्त और शामिल रखता है","उसे अपने माता-पिता के साथ दर्शक दीर्घा से देखने और अपने सदन का उत्साहवर्धन करने देना","कुछ ऐसी प्रतियोगिताएँ बनाना जिनमें सभी भाग ले सकें, जैसे बैठकर फेंकना और मिश्रित रिले, ताकि कुणाल दूसरों के साथ प्रतिस्पर्धा करे"],"explanationHi":"समावेशन का अर्थ है केवल सहायक के रूप में नहीं, बल्कि प्रतिभागी के रूप में भाग लेना; प्रतियोगिताओं को अनुकूलित करना उसे प्रतिस्पर्धा करने देता है, जबकि स्थायी सहायक भूमिका उसे फिर भी किनारे पर रखती है।"},
  {"id":"cdp-child-development-1665","question":"A Class 8 teacher learns that Sunita, aged 14, has stopped attending school and that her family is arranging her marriage. What should the teacher do?","options":["Treat it as a private family matter that the school has no right to interfere in, and simply wait for her to return","Speak to the family about her right to education, and alert Childline (1098), as marriage below 18 is prohibited","Remove her name from the register after a month of continuous absence, as attendance rules require","Tell her classmates to persuade her to come back, without involving any adults"],"answer":1,"explanation":"Marriage of a girl under 18 is prohibited by law, and the school has a duty to protect the child's right to education; engaging the family and alerting child-protection services are the right steps.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 8 की शिक्षिका को पता चलता है कि 14 वर्ष की सुनीता ने विद्यालय आना बंद कर दिया है और उसका परिवार उसके विवाह की व्यवस्था कर रहा है। शिक्षिका को क्या करना चाहिए?","optionsHi":["इसे निजी पारिवारिक मामला मानना जिसमें विद्यालय को हस्तक्षेप का अधिकार नहीं, और बस उसके लौटने की प्रतीक्षा करना","परिवार से उसके शिक्षा के अधिकार के बारे में बात करना, और चाइल्डलाइन (1098) को सूचित करना, क्योंकि 18 वर्ष से कम में विवाह निषिद्ध है","लगातार एक माह की अनुपस्थिति के बाद उसका नाम पंजिका से हटा देना, जैसा उपस्थिति नियम अपेक्षित करते हैं","उसके सहपाठियों से कहना कि वे उसे लौटने के लिए मनाएँ, बिना किसी वयस्क को शामिल किए"],"explanationHi":"18 वर्ष से कम आयु की बालिका का विवाह कानून द्वारा निषिद्ध है, और विद्यालय का कर्तव्य है कि बच्चे के शिक्षा के अधिकार की रक्षा करे; परिवार से संवाद और बाल-संरक्षण सेवाओं को सूचित करना सही कदम हैं।"},
  {"id":"cdp-child-development-1666","question":"After the summer break, many first-generation learners in a Class 3 village class have forgotten much of their reading, since their homes have no books. Which step helps most?","options":["A lending library or book bags so children take books home, with activities families can do even without reading","Assigning long written holiday homework so that children keep practising letters and words every day","Blaming the parents for not teaching their children at home, and asking them to sign a written promise to do so","Repeating the whole of last year’s syllabus from the beginning before moving on"],"answer":0,"explanation":"Access to books at home sustains reading; activities that do not depend on literate parents make it possible for every family to help.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"गर्मी की छुट्टियों के बाद, कक्षा 3 की एक ग्रामीण कक्षा के अनेक प्रथम-पीढ़ी के अधिगमकर्ता अपना बहुत-सा पठन भूल गए हैं, क्योंकि उनके घरों में पुस्तकें नहीं हैं। कौन-सा कदम सबसे अधिक सहायक है?","optionsHi":["उधार देने वाला पुस्तकालय या पुस्तक-थैले ताकि बच्चे पुस्तकें घर ले जाएँ, साथ में ऐसी गतिविधियाँ जो परिवार पढ़े बिना भी कर सकें","लंबा लिखित छुट्टी का गृहकार्य देना ताकि बच्चे प्रतिदिन अक्षरों और शब्दों का अभ्यास करते रहें","माता-पिता को दोष देना कि वे घर पर बच्चों को नहीं पढ़ाते, और उनसे ऐसा करने की लिखित प्रतिज्ञा पर हस्ताक्षर करवाना","आगे बढ़ने से पहले पिछले वर्ष का पूरा पाठ्यक्रम शुरू से दोहराना"],"explanationHi":"घर पर पुस्तकों तक पहुँच पठन को बनाए रखती है; जो गतिविधियाँ साक्षर माता-पिता पर निर्भर नहीं करतीं वे हर परिवार के लिए सहायता करना संभव बनाती हैं।"},
  {"id":"cdp-child-development-1667","question":"For the school’s annual day, a teacher selects only ‘neat, well-dressed and fluent in English’ children to perform. Many children from poorer homes are never chosen. What is the main concern?","options":["The teacher should select children by lottery only, ignoring interest and effort, so that nobody can ever complain","It does not matter, since only a few children can ever perform on annual day","Such criteria reflect class bias and deny some children recognition; every child should get chances, with support","Children from poorer homes are usually not interested in performing on stage"],"answer":2,"explanation":"Criteria like dress and English fluency favour advantaged children; inclusive schools rotate opportunities and support every child to take part.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"विद्यालय के वार्षिकोत्सव के लिए एक शिक्षिका केवल ‘साफ़-सुथरे, अच्छे कपड़े पहने और अंग्रेज़ी में धाराप्रवाह’ बच्चों को प्रस्तुति के लिए चुनती है। गरीब घरों के अनेक बच्चे कभी नहीं चुने जाते। मुख्य चिंता क्या है?","optionsHi":["शिक्षिका को केवल लॉटरी से बच्चों का चयन करना चाहिए, रुचि और प्रयास की अनदेखी करके, ताकि कोई कभी शिकायत न कर सके","इससे फ़र्क नहीं पड़ता, क्योंकि वार्षिकोत्सव पर केवल कुछ ही बच्चे प्रस्तुति दे सकते हैं","ऐसे मानदंड वर्ग-पूर्वाग्रह को दर्शाते हैं और कुछ बच्चों को मान्यता से वंचित करते हैं; हर बच्चे को अवसर मिलने चाहिए, सहायता के साथ","गरीब घरों के बच्चे प्रायः मंच पर प्रस्तुति देने में रुचि नहीं रखते"],"explanationHi":"पहनावे और अंग्रेज़ी की धाराप्रवाहता जैसे मानदंड सुविधा-संपन्न बच्चों के पक्ष में होते हैं; समावेशी विद्यालय अवसरों को बारी-बारी से देते हैं और हर बच्चे को भाग लेने में सहायता करते हैं।"},
  {"id":"cdp-child-development-1668","question":"A Class 5 PE teacher lets only boys play cricket and only girls practise dance for the annual function. A boy who loves dance and a girl who loves cricket complain. What is the best course of action?","options":["Keep the arrangement, since it matches what most children in the class prefer anyway","Allow the two children to switch quietly, but keep the gender rule unchanged for everyone else in the class","Tell the children that these activities do not suit their gender and offer alternatives","Open every activity to all children by interest, and actively encourage participation across gender lines"],"answer":3,"explanation":"Assigning activities by gender reinforces stereotypes and limits every child; access based on interest, with encouragement, challenges those limits.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 5 का एक शारीरिक शिक्षा शिक्षक वार्षिक समारोह के लिए केवल लड़कों को क्रिकेट खेलने और केवल लड़कियों को नृत्य का अभ्यास करने देता है। नृत्य पसंद करने वाला एक लड़का और क्रिकेट पसंद करने वाली एक लड़की शिकायत करते हैं। सबसे अच्छी कार्रवाई क्या है?","optionsHi":["व्यवस्था को बनाए रखना, क्योंकि यह वैसे भी कक्षा के अधिकांश बच्चों की पसंद से मेल खाती है","दोनों बच्चों को चुपचाप अदला-बदली करने देना, पर कक्षा के अन्य सभी के लिए लैंगिक नियम को अपरिवर्तित रखना","बच्चों से कहना कि ये गतिविधियाँ उनके लिंग के अनुकूल नहीं हैं और विकल्प देना","प्रत्येक गतिविधि को रुचि के आधार पर सभी बच्चों के लिए खोलना, और लैंगिक सीमाओं के पार भागीदारी को सक्रिय रूप से प्रोत्साहित करना"],"explanationHi":"गतिविधियों को लिंग के आधार पर सौंपना रूढ़ धारणाओं को पुष्ट करता है और हर बच्चे को सीमित करता है; रुचि पर आधारित पहुँच, प्रोत्साहन के साथ, उन सीमाओं को चुनौती देती है।"},
  {"id":"cdp-child-development-1669","question":"Under the RPwD Act, 2016, which of the following are among the duties of educational institutions? I. Providing transportation facilities to children with disabilities and their attendants where they have high support needs. II. Monitoring the participation, progress and completion of education of every student with a disability. III. Ensuring that education of children who are blind, deaf or both is in the most appropriate languages and modes of communication.","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":3,"explanation":"All three are listed duties: transport (including for attendants of children with high support needs), monitoring of participation and progress, and education in appropriate languages and modes for blind and deaf learners.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"RPwD अधिनियम, 2016 के अंतर्गत, निम्नलिखित में से कौन-से शैक्षिक संस्थानों के कर्तव्यों में हैं? I. उच्च सहायता आवश्यकताओं वाले दिव्यांग बच्चों और उनके परिचारकों को परिवहन सुविधाएँ उपलब्ध कराना। II. प्रत्येक दिव्यांग छात्र की शिक्षा में भागीदारी, प्रगति और पूर्णता की निगरानी करना। III. यह सुनिश्चित करना कि दृष्टिबाधित, बधिर या दोनों बच्चों की शिक्षा सबसे उपयुक्त भाषाओं और संप्रेषण-विधाओं में हो।","optionsHi":["केवल I और II","केवल II और III","केवल I और III","I, II और III"],"explanationHi":"तीनों सूचीबद्ध कर्तव्य हैं: परिवहन (उच्च सहायता आवश्यकताओं वाले बच्चों के परिचारकों सहित), भागीदारी और प्रगति की निगरानी, और दृष्टिबाधित तथा बधिर अधिगमकर्ताओं के लिए उपयुक्त भाषाओं व विधाओं में शिक्षा।"},
  {"id":"cdp-child-development-1670","question":"Match each UDL principle with the kind of learner it aims to develop. 1. Engagement 2. Representation 3. Action and expression; a. Strategic and goal-directed b. Resourceful and knowledgeable c. Purposeful and motivated","options":["1-c, 2-b, 3-a","1-a, 2-b, 3-c","1-c, 2-a, 3-b","1-b, 2-c, 3-a"],"answer":0,"explanation":"Engagement builds purposeful, motivated learners; representation builds resourceful, knowledgeable learners; and action and expression build strategic, goal-directed learners.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"प्रत्येक UDL सिद्धांत का मिलान उस प्रकार के अधिगमकर्ता से कीजिए जिसे वह विकसित करना चाहता है। 1. संलग्नता 2. निरूपण 3. क्रिया और अभिव्यक्ति; a. रणनीतिक और लक्ष्य-निर्देशित b. साधन-संपन्न और ज्ञानवान c. उद्देश्यपूर्ण और अभिप्रेरित","optionsHi":["1-c, 2-b, 3-a","1-a, 2-b, 3-c","1-c, 2-a, 3-b","1-b, 2-c, 3-a"],"explanationHi":"संलग्नता उद्देश्यपूर्ण, अभिप्रेरित अधिगमकर्ता बनाती है; निरूपण साधन-संपन्न, ज्ञानवान अधिगमकर्ता बनाता है; और क्रिया तथा अभिव्यक्ति रणनीतिक, लक्ष्य-निर्देशित अधिगमकर्ता बनाती है।"},
  {"id":"cdp-child-development-1671","question":"A Class 6 trip to a science centre costs ₹600. Several children from low-income families say they ‘don’t want to go’ and stay back each year. What should the school do?","options":["Accept their choice without question, since the trip is optional and families know their own situation best","Make the trip compulsory and ask all families to pay the full amount in instalments","Cover the cost discreetly through school funds or sponsorship, so that no child is left out or singled out","Cancel all trips, so that no child ever feels left out of an activity"],"answer":2,"explanation":"Hidden costs quietly exclude poorer children, who often hide the real reason; discreet support keeps the experience open to all without embarrassment.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 6 की विज्ञान केंद्र की यात्रा की लागत ₹600 है। कम आय वाले परिवारों के कई बच्चे कहते हैं कि वे ‘जाना नहीं चाहते’ और हर वर्ष पीछे रह जाते हैं। विद्यालय को क्या करना चाहिए?","optionsHi":["उनकी पसंद को बिना प्रश्न के स्वीकार करना, क्योंकि यात्रा वैकल्पिक है और परिवार अपनी स्थिति सबसे अच्छी जानते हैं","यात्रा को अनिवार्य करना और सभी परिवारों से किस्तों में पूरी राशि चुकाने को कहना","विद्यालय कोष या प्रायोजन से लागत को चुपचाप वहन करना, ताकि कोई बच्चा छूटे नहीं या अलग न दिखे","सभी यात्राएँ रद्द कर देना, ताकि कोई बच्चा किसी गतिविधि से कभी वंचित महसूस न करे"],"explanationHi":"छिपे हुए खर्च गरीब बच्चों को चुपचाप बाहर कर देते हैं, जो प्रायः असली कारण छिपाते हैं; चुपचाप दी गई सहायता अनुभव को बिना शर्मिंदगी के सभी के लिए खुला रखती है।"},
  {"id":"cdp-child-development-1672","question":"The RPwD Act, 2016 describes ‘specific learning disabilities’ as a group of conditions involving difficulty in processing spoken or written language or calculation. Which of these does the Act name as examples? I. Dyspraxia II. Developmental aphasia III. Attention deficit hyperactivity disorder","options":["I and II only","I only","II and III only","I, II and III"],"answer":0,"explanation":"The Act's description of specific learning disabilities names conditions such as perceptual disabilities, dyslexia, dysgraphia, dyscalculia, dyspraxia and developmental aphasia; ADHD is not among them.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"RPwD अधिनियम, 2016 ‘विशिष्ट अधिगम अक्षमताओं’ को बोली या लिखी भाषा या गणना के प्रक्रमण में कठिनाई वाली स्थितियों के समूह के रूप में वर्णित करता है। इनमें से किन्हें अधिनियम उदाहरण के रूप में नाम देता है? I. डिस्प्रैक्सिया II. विकासात्मक वाग्घात (एफ़ेज़िया) III. ध्यान-अभाव अतिसक्रियता विकार","optionsHi":["केवल I और II","केवल I","केवल II और III","I, II और III"],"explanationHi":"अधिनियम का विशिष्ट अधिगम अक्षमताओं का वर्णन प्रत्यक्षणात्मक अक्षमताओं, डिस्लेक्सिया, डिस्ग्राफिया, डिस्कैल्कुलिया, डिस्प्रैक्सिया और विकासात्मक वाग्घात जैसी स्थितियों का नाम लेता है; ADHD उनमें नहीं है।"},
  {"id":"cdp-child-development-1673","question":"Priyanshu, a Class 5 student with dyslexia, copies notes from the board very slowly and with many errors, so he has little time left to listen or think. Which support is most suitable?","options":["Making him stay back after school every day until he has copied all the notes correctly","Giving him printed notes or letting him photograph the board, so he can focus on understanding","Asking him to copy only the first half of the notes and leave the rest","Telling him to copy faster, and to practise copying pages from the textbook at home every evening"],"answer":1,"explanation":"Copying is a heavy load for a child with dyslexia and takes attention away from learning; providing notes removes the barrier without lowering the content.","difficulty":"hard","source":"CTET · State TETs","questionHi":"डिस्लेक्सिया वाला कक्षा 5 का छात्र प्रियांशु श्यामपट्ट से नोट्स बहुत धीरे और अनेक त्रुटियों के साथ उतारता है, इसलिए उसके पास सुनने या सोचने के लिए बहुत कम समय बचता है। कौन-सी सहायता सबसे उपयुक्त है?","optionsHi":["उसे प्रतिदिन विद्यालय के बाद तब तक रोके रखना जब तक वह सभी नोट्स सही उतार न ले","उसे छपे हुए नोट्स देना या श्यामपट्ट की तस्वीर लेने देना, ताकि वह समझने पर ध्यान दे सके","उससे केवल नोट्स का पहला आधा भाग उतारने और शेष छोड़ देने को कहना","उससे कहना कि तेज़ी से उतारे, और प्रत्येक शाम घर पर पाठ्यपुस्तक के पृष्ठ उतारने का अभ्यास करे"],"explanationHi":"डिस्लेक्सिया वाले बच्चे के लिए उतारना भारी बोझ है और अधिगम से ध्यान हटाता है; नोट्स उपलब्ध कराना विषयवस्तु को घटाए बिना बाधा को हटा देता है।"},
  {"id":"cdp-child-development-1674","question":"Kartik, a deaf Class 2 child, often hits classmates during games. The teacher notices it usually happens when others change the rules quickly or laugh at something he did not catch. What is the most likely cause and the best response?","options":["He is naturally aggressive and needs strict punishment every time he hits someone","He should be kept out of group games and given solo activities until he learns to control his temper","Frustration at being left out of communication; teach peers simple signs and give Kartik other ways to express it","He is jealous of his classmates and needs counselling only, not classroom changes"],"answer":2,"explanation":"Behaviour often signals unmet communication needs; making communication accessible and teaching alternative ways to express feelings tackles the cause.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 2 का बधिर बच्चा कार्तिक खेलों के दौरान प्रायः सहपाठियों को मारता है। शिक्षक देखता है कि यह प्रायः तब होता है जब दूसरे नियम जल्दी बदल देते हैं या किसी ऐसी बात पर हँसते हैं जो वह समझ नहीं पाया। सबसे संभावित कारण और सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["वह स्वभाव से आक्रामक है और जब भी किसी को मारे उसे कठोर दंड चाहिए","उसे समूह के खेलों से बाहर रखना चाहिए और अकेले की गतिविधियाँ देनी चाहिए जब तक वह अपना क्रोध नियंत्रित करना न सीख ले","संप्रेषण से बाहर रह जाने की हताशा; सहपाठियों को सरल संकेत सिखाएँ और कार्तिक को इसे व्यक्त करने के अन्य तरीके दें","वह अपने सहपाठियों से ईर्ष्या करता है और उसे केवल परामर्श चाहिए, कक्षा में बदलाव नहीं"],"explanationHi":"व्यवहार प्रायः अपूर्ण संप्रेषण-आवश्यकताओं का संकेत होता है; संप्रेषण को सुलभ बनाना और भावनाओं को व्यक्त करने के वैकल्पिक तरीके सिखाना कारण का समाधान करता है।"},
  {"id":"cdp-child-development-1675","question":"Which of these statements are consistent with NEP 2020 regarding children with disabilities? I. Indian Sign Language is to be standardised across the country, with curriculum materials developed for students with hearing impairment. II. Home-based education remains a choice for children with severe and profound disabilities who are unable to go to school. III. All children with disabilities must study in special schools.","options":["I only","II and III only","I, II and III","I and II only"],"answer":3,"explanation":"NEP 2020 calls for standardising Indian Sign Language and keeps home-based education as an option for children who cannot attend school; it supports choice and inclusion, not compulsory special schooling.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"दिव्यांग बच्चों के संबंध में NEP 2020 से इनमें से कौन-से कथन संगत हैं? I. भारतीय सांकेतिक भाषा को पूरे देश में मानकीकृत किया जाना है, और श्रवण-बाधित छात्रों के लिए पाठ्यचर्या सामग्री विकसित की जानी है। II. गंभीर और गहन दिव्यांगता वाले जो बच्चे विद्यालय नहीं जा सकते, उनके लिए गृह-आधारित शिक्षा एक विकल्प बनी रहती है। III. सभी दिव्यांग बच्चों को विशेष विद्यालयों में ही पढ़ना होगा।","optionsHi":["केवल I","केवल II और III","I, II और III","केवल I और II"],"explanationHi":"NEP 2020 भारतीय सांकेतिक भाषा के मानकीकरण का आह्वान करती है और विद्यालय न जा सकने वाले बच्चों के लिए गृह-आधारित शिक्षा को विकल्प बनाए रखती है; यह चयन और समावेशन का समर्थन करती है, अनिवार्य विशेष विद्यालयी शिक्षा का नहीं।"},
  {"id":"cdp-child-development-1676","question":"A new 15-minute reading test for Class 3 is given in the same week as an established, longer reading assessment, and the two sets of scores correlate highly. This is evidence of the new test’s:","options":["Predictive validity","Concurrent validity","Face validity","Split-half reliability"],"answer":1,"explanation":"Agreement with an established measure taken at about the same time is concurrent validity; predictive validity would compare the test with a criterion measured later.","difficulty":"hard","source":"KVS TGT · DSSSB TGT","questionHi":"कक्षा 3 के लिए एक नया 15 मिनट का पठन परीक्षण एक स्थापित, लंबे पठन आकलन के साथ उसी सप्ताह में दिया जाता है, और दोनों के अंकों में उच्च सहसंबंध है। यह नए परीक्षण की किस बात का प्रमाण है?","optionsHi":["पूर्वकथनात्मक वैधता","समवर्ती वैधता","आभासी वैधता","अर्ध-विभाजन विश्वसनीयता"],"explanationHi":"लगभग उसी समय लिए गए स्थापित माप से सहमति समवर्ती वैधता है; पूर्वकथनात्मक वैधता परीक्षण की तुलना बाद में मापे गए मानदंड से करती।"},
  {"id":"cdp-child-development-1677","question":"A ‘creativity test’ for Class 6 consists only of questions asking students to recall the names of famous inventors. Its main weakness lies in its:","options":["Inter-rater reliability, since scorers may disagree","Test–retest reliability, since recall can change over a few weeks","Objectivity of scoring, since names can be spelt variously","Construct validity, since it measures memory, not creativity"],"answer":3,"explanation":"Recalling names taps factual memory, not the construct of creativity (fluency, originality, flexibility); such items can be scored objectively and consistently and still measure the wrong thing.","difficulty":"moderate","source":"CTET Paper II · KVS TGT","questionHi":"कक्षा 6 के लिए एक ‘सृजनात्मकता परीक्षण’ में केवल ऐसे प्रश्न हैं जो छात्रों से प्रसिद्ध आविष्कारकों के नाम याद करने को कहते हैं। इसकी मुख्य कमज़ोरी किसमें है?","optionsHi":["अंतर-मूल्यांकनकर्ता विश्वसनीयता, क्योंकि अंक देने वाले असहमत हो सकते हैं","परीक्षण–पुनःपरीक्षण विश्वसनीयता, क्योंकि कुछ सप्ताहों में स्मरण बदल सकता है","अंकन की वस्तुनिष्ठता, क्योंकि नामों की वर्तनी अलग-अलग हो सकती है","संरचना वैधता, क्योंकि यह स्मृति को मापता है, सृजनात्मकता को नहीं"],"explanationHi":"नाम याद करना तथ्यात्मक स्मृति को परखता है, सृजनात्मकता (प्रवाह, मौलिकता, लचीलापन) की संरचना को नहीं; ऐसे प्रश्नों को वस्तुनिष्ठ और संगत रूप से अंकित किया जा सकता है फिर भी वे गलत चीज़ को मापते हैं।"},
  {"id":"cdp-child-development-1678","question":"To make scoring ‘fair’, a Class 9 English teacher replaces all essay questions with multiple-choice items. Which statement best evaluates this change?","options":["Scoring objectivity rises, but validity for assessing writing and argument falls","Both reliability and validity for assessing writing skills improve together","Validity rises, since well-made multiple-choice items are always more valid than essays","Nothing changes, since the format of a test does not affect what it measures"],"answer":0,"explanation":"MCQs remove scorer disagreement but cannot show whether a student can compose an argument; gaining objectivity at the cost of the target skill lowers validity.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"अंकन को ‘निष्पक्ष’ बनाने के लिए कक्षा 9 की अंग्रेज़ी शिक्षिका सभी निबंध प्रश्नों को बहुविकल्पीय प्रश्नों से बदल देती है। इस परिवर्तन का सबसे अच्छा मूल्यांकन कौन-सा कथन करता है?","optionsHi":["अंकन की वस्तुनिष्ठता बढ़ती है, परंतु लेखन और तर्क के आकलन के लिए वैधता घटती है","लेखन-कौशल के आकलन के लिए विश्वसनीयता और वैधता दोनों साथ-साथ बढ़ती हैं","वैधता बढ़ती है, क्योंकि अच्छी तरह बने बहुविकल्पीय प्रश्न निबंधों से सदैव अधिक वैध होते हैं","कुछ नहीं बदलता, क्योंकि परीक्षण का प्रारूप इस पर प्रभाव नहीं डालता कि वह क्या मापता है"],"explanationHi":"बहुविकल्पीय प्रश्न अंकन में असहमति को हटाते हैं, पर यह नहीं दिखा सकते कि छात्र तर्क रच सकता है या नहीं; लक्षित कौशल की कीमत पर वस्तुनिष्ठता पाना वैधता को घटाता है।"},
  {"id":"cdp-child-development-1679","question":"Which top-level rubric descriptor for ‘use of evidence’ in a Class 8 essay is best written?","options":["‘Excellent and impressive use of evidence throughout the whole essay, with very good quotations.’","‘Uses five or more quotations from the text in every paragraph of the essay.’","‘Supports each main point with relevant evidence from the text and explains how it helps.’","‘Uses evidence better than most other students in the class this term.’"],"answer":2,"explanation":"Good descriptors state observable qualities of performance; ‘excellent’ is vague, counting quotations ignores quality, and comparison with peers is not a criterion.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"कक्षा 8 के निबंध में ‘प्रमाणों के उपयोग’ के लिए कौन-सा शीर्ष-स्तर का रूब्रिक विवरण सबसे अच्छा लिखा गया है?","optionsHi":["‘पूरे निबंध में प्रमाणों का उत्कृष्ट और प्रभावशाली उपयोग, बहुत अच्छे उद्धरणों के साथ।’","‘निबंध के प्रत्येक अनुच्छेद में पाठ से पाँच या अधिक उद्धरणों का उपयोग।’","‘प्रत्येक मुख्य बिंदु का पाठ से प्रासंगिक प्रमाणों द्वारा समर्थन और यह स्पष्टीकरण कि वह कैसे सहायक है।’","‘इस सत्र में कक्षा के अधिकांश अन्य छात्रों से बेहतर प्रमाणों का उपयोग।’"],"explanationHi":"अच्छे विवरण निष्पादन की प्रेक्षणीय विशेषताएँ बताते हैं; ‘उत्कृष्ट’ अस्पष्ट है, उद्धरण गिनना गुणवत्ता की अनदेखी करता है, और साथियों से तुलना कोई मानदंड नहीं है।"},
  {"id":"cdp-child-development-1680","question":"A teacher asks Class 8 students to keep every draft, rough note and reflection from their science project in one folder, so that she can see how their thinking developed and not just the final product. This folder is a:","options":["Showcase portfolio of best work","Assessment rubric for the project","Cumulative record of the student","Process (working) portfolio"],"answer":3,"explanation":"A process portfolio documents the journey of learning, including drafts and reflections; a showcase portfolio holds only best final work, and a cumulative record is the school’s long-term record of a pupil.","difficulty":"hard","source":"CTET Paper II · State TET","questionHi":"कक्षा 8 की शिक्षिका छात्रों से कहती है कि वे अपने विज्ञान परियोजना के हर प्रारूप, कच्चे नोट और चिंतन को एक फ़ोल्डर में रखें, ताकि वह देख सके कि उनका चिंतन कैसे विकसित हुआ, केवल अंतिम उत्पाद ही नहीं। यह फ़ोल्डर क्या है?","optionsHi":["सर्वश्रेष्ठ कार्य का प्रदर्शन पोर्टफ़ोलियो","परियोजना का आकलन रूब्रिक","छात्र का संचित अभिलेख","प्रक्रिया (कार्यशील) पोर्टफ़ोलियो"],"explanationHi":"प्रक्रिया पोर्टफ़ोलियो अधिगम की यात्रा को दर्ज करता है, जिसमें प्रारूप और चिंतन शामिल हैं; प्रदर्शन पोर्टफ़ोलियो में केवल सर्वश्रेष्ठ अंतिम कार्य होता है, और संचित अभिलेख विद्यार्थी का विद्यालय का दीर्घकालिक अभिलेख है।"},
  {"id":"cdp-child-development-1681","question":"A child moves from Class 5 in one Kendriya Vidyalaya to Class 6 in another. Which document best helps the new teacher understand her progress over the years in scholastic and co-scholastic areas, health and attendance?","options":["An anecdotal record of a single incident","Her cumulative record","The previous teacher’s daily lesson plan","Her admission form"],"answer":1,"explanation":"A cumulative record gathers information on a pupil across years (achievement, co-scholastic areas, health, attendance) and travels with the child; an anecdotal record captures only one incident.","difficulty":"moderate","source":"KVS PRT · NVS","questionHi":"एक बच्ची एक केंद्रीय विद्यालय की कक्षा 5 से दूसरे विद्यालय की कक्षा 6 में जाती है। कौन-सा दस्तावेज़ नई शिक्षिका को वर्षों में शैक्षिक और सह-शैक्षिक क्षेत्रों, स्वास्थ्य और उपस्थिति में उसकी प्रगति समझने में सबसे अच्छी तरह सहायता करता है?","optionsHi":["किसी एक घटना का उपाख्यानात्मक अभिलेख","उसका संचित अभिलेख","पिछली शिक्षिका की दैनिक पाठ-योजना","उसका प्रवेश-प्रपत्र"],"explanationHi":"संचित अभिलेख वर्षों में विद्यार्थी की जानकारी (उपलब्धि, सह-शैक्षिक क्षेत्र, स्वास्थ्य, उपस्थिति) एकत्र करता है और बच्चे के साथ जाता है; उपाख्यानात्मक अभिलेख केवल एक घटना दर्ज करता है।"},
  {"id":"cdp-child-development-1682","question":"According to Hattie and Timperley’s model of feedback levels, which comment on a Class 5 child’s division work operates at the ‘process’ level?","options":["‘Well done, you are a star and a very clever mathematician, the best in the class!’","‘Answer 3 is wrong; the correct answer is 47, so please write it out again neatly in your copy.’","‘You got stuck on large numbers; try estimating first to check if your answer is reasonable.’","‘Your handwriting is very neat, and your work is well laid out.’"],"answer":2,"explanation":"Process-level feedback addresses the strategies used to do the task; ‘Answer 3 is wrong’ is task-level, and ‘you are a star’ is self-level praise, which does least for learning.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"हैटी और टिम्परली के प्रतिपुष्टि-स्तरों के मॉडल के अनुसार, कक्षा 5 के बच्चे के भाग के कार्य पर कौन-सी टिप्पणी ‘प्रक्रिया’ स्तर पर काम करती है?","optionsHi":["‘शाबाश, तुम सितारे हो और बहुत चतुर गणितज्ञ, कक्षा में सर्वश्रेष्ठ!’","‘उत्तर 3 गलत है; सही उत्तर 47 है, इसलिए कृपया इसे अपनी कॉपी में साफ़-साफ़ फिर से लिखो।’","‘तुम बड़ी संख्याओं पर अटक गए; पहले अनुमान लगाकर देखो कि तुम्हारा उत्तर उचित है या नहीं।’","‘तुम्हारी लिखावट बहुत साफ़ है, और तुम्हारा कार्य अच्छी तरह व्यवस्थित है।’"],"explanationHi":"प्रक्रिया-स्तर की प्रतिपुष्टि कार्य करने के लिए प्रयुक्त युक्तियों को संबोधित करती है; ‘उत्तर 3 गलत है’ कार्य-स्तर की है, और ‘तुम सितारे हो’ स्व-स्तर की प्रशंसा है, जो अधिगम के लिए सबसे कम करती है।"},
  {"id":"cdp-child-development-1683","question":"A teacher writes: ‘You know the features of a good paragraph. Check your draft against them and decide which one you still need to work on.’ This feedback aims mainly at:","options":["Self-regulation, helping the learner monitor and direct her own work","Praise of the learner as a person, to build up her confidence and self-esteem","The correctness of a single answer in the draft paragraph","Comparison of the learner’s work with that of her peers"],"answer":0,"explanation":"The comment does not correct the work itself; it prompts the learner to check against criteria and decide what to do next, which is the self-regulation level.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT","questionHi":"एक शिक्षिका लिखती है: ‘तुम्हें एक अच्छे अनुच्छेद की विशेषताएँ पता हैं। अपने प्रारूप को उनसे मिलाकर जाँचो और तय करो कि तुम्हें अब भी किस पर काम करना है।’ इस प्रतिपुष्टि का मुख्य उद्देश्य क्या है?","optionsHi":["आत्म-नियमन, अधिगमकर्ता को अपने कार्य की निगरानी और दिशा-निर्धारण में सहायता करना","अधिगमकर्ता की एक व्यक्ति के रूप में प्रशंसा, ताकि उसका आत्मविश्वास और आत्म-सम्मान बढ़े","प्रारूप अनुच्छेद में किसी एक उत्तर की सटीकता","अधिगमकर्ता के कार्य की उसके साथियों के कार्य से तुलना"],"explanationHi":"टिप्पणी स्वयं कार्य को सही नहीं करती; यह अधिगमकर्ता को मानदंडों से जाँचने और अगला कदम तय करने के लिए प्रेरित करती है, जो आत्म-नियमन का स्तर है।"},
  {"id":"cdp-child-development-1684","question":"A Class 2 report card says only ‘Maths: B’, and a parent cannot tell what the child can or cannot do. A more useful report would:","options":["Give an exact percentage instead of a letter grade, since a number is more precise and easy to track","Add the child’s rank in the class so that parents know where she stands","Add the class average beside her grade, so that parents can judge whether she is above or below the others","Describe what the child can do (e.g. adds two-digit numbers with carrying) and what she is still learning"],"answer":3,"explanation":"Descriptive, criterion-based reporting tells parents what has been learnt and what comes next; percentages, ranks and averages are just other kinds of single numbers.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"कक्षा 2 की रिपोर्ट-कार्ड में केवल ‘गणित: B’ लिखा है, और माता-पिता नहीं जान पाते कि बच्चा क्या कर सकता है या क्या नहीं। अधिक उपयोगी रिपोर्ट क्या करेगी?","optionsHi":["अक्षर-ग्रेड के बजाय सटीक प्रतिशत देना, क्योंकि संख्या अधिक सटीक और ट्रैक करने में आसान है","बच्चे की कक्षा में श्रेणी जोड़ना ताकि माता-पिता जानें कि वह कहाँ खड़ी है","उसके ग्रेड के बगल में कक्षा का औसत जोड़ना, ताकि माता-पिता आँक सकें कि वह दूसरों से ऊपर है या नीचे","वर्णन करना कि बच्चा क्या कर सकता है (जैसे हासिल वाले दो अंकीय संख्याओं का योग) और वह अब भी क्या सीख रही है"],"explanationHi":"वर्णनात्मक, मानदंड-आधारित प्रतिवेदन माता-पिता को बताता है कि क्या सीखा गया और आगे क्या है; प्रतिशत, श्रेणियाँ और औसत केवल अन्य प्रकार की एकल संख्याएँ हैं।"},
  {"id":"cdp-child-development-1685","question":"Which of these are consistent with the original intention of continuous and comprehensive evaluation (CCE)? I. Using assessment information to improve teaching during the year. II. Reducing the weight of a single year-end examination. III. Grading every class activity for the report card. IV. Assessing life skills, attitudes and values along with subjects.","options":["I, II and III only","I, II and IV only","III and IV only","I, II, III and IV"],"answer":1,"explanation":"CCE was meant to make assessment part of teaching, reduce dependence on one exam and cover co-scholastic areas; grading every activity was the distortion that arose in practice.","difficulty":"very-hard","source":"CTET · DSSSB TGT","questionHi":"इनमें से कौन-से सतत एवं व्यापक मूल्यांकन (CCE) के मूल आशय से संगत हैं? I. वर्ष के दौरान शिक्षण को सुधारने के लिए आकलन की जानकारी का उपयोग करना। II. एकल वर्षांत परीक्षा के भार को कम करना। III. रिपोर्ट-कार्ड के लिए कक्षा की हर गतिविधि को ग्रेड देना। IV. विषयों के साथ जीवन-कौशल, अभिवृत्तियों और मूल्यों का आकलन करना।","optionsHi":["केवल I, II और III","केवल I, II और IV","केवल III और IV","I, II, III और IV"],"explanationHi":"CCE का उद्देश्य आकलन को शिक्षण का हिस्सा बनाना, एक परीक्षा पर निर्भरता घटाना और सह-शैक्षिक क्षेत्रों को समेटना था; हर गतिविधि को ग्रेड देना वह विकृति थी जो व्यवहार में उभरी।"},
  {"id":"cdp-child-development-1686","question":"Which question for Class 6 history tests ‘evaluating’ in the revised Bloom’s taxonomy?","options":["‘Was Ashoka right to give up war after Kalinga? Judge, using his edicts.’","‘In which year was the battle of Kalinga fought, and who won it?’","‘Describe the battle of Kalinga and its results in your own words.’","‘List all the places in India and abroad where Ashoka’s edicts have been found.’"],"answer":0,"explanation":"Evaluating means making a judgement against criteria or evidence; the others are remembering (year, list) and understanding (describing in one’s own words).","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"कक्षा 6 के इतिहास का कौन-सा प्रश्न संशोधित ब्लूम वर्गीकरण में ‘मूल्यांकन’ को परखता है?","optionsHi":["‘क्या कलिंग के बाद अशोक का युद्ध त्यागना सही था? उसके अभिलेखों का उपयोग करके निर्णय दीजिए।’","‘कलिंग का युद्ध किस वर्ष लड़ा गया और उसे किसने जीता?’","‘कलिंग के युद्ध और उसके परिणामों का अपने शब्दों में वर्णन कीजिए।’","‘भारत और विदेश के उन सभी स्थानों की सूची बनाइए जहाँ अशोक के अभिलेख मिले हैं।’"],"explanationHi":"मूल्यांकन का अर्थ है मानदंडों या प्रमाणों के आधार पर निर्णय लेना; अन्य स्मरण (वर्ष, सूची) और बोध (अपने शब्दों में वर्णन) हैं।"},
  {"id":"cdp-child-development-1687","question":"Which statement best distinguishes Dewey from Montessori?","options":["Dewey stressed individual work with self-correcting materials, while Montessori stressed social, community-based activity","Both rejected the importance of the child’s own activity","Dewey stressed shared problem-solving in a community; Montessori stressed individual work with self-correcting materials","Montessori was a pragmatist philosopher, while Dewey was a medical doctor"],"answer":2,"explanation":"Both were child-centred, but Dewey’s school was a social community solving shared problems, while Montessori’s child worked largely individually in a prepared environment; options A and D swap their features.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"कौन-सा कथन डेवी को मॉन्टेसरी से सबसे अच्छी तरह अलग करता है?","optionsHi":["डेवी ने स्व-सुधारक सामग्री के साथ वैयक्तिक कार्य पर ज़ोर दिया, जबकि मॉन्टेसरी ने सामाजिक, समुदाय-आधारित गतिविधि पर","दोनों ने बच्चे की अपनी गतिविधि के महत्व को अस्वीकार किया","डेवी ने समुदाय में साझा समस्या-समाधान पर ज़ोर दिया; मॉन्टेसरी ने स्व-सुधारक सामग्री के साथ वैयक्तिक कार्य पर","मॉन्टेसरी एक व्यावहारिकतावादी दार्शनिक थीं, जबकि डेवी एक चिकित्सक थे"],"explanationHi":"दोनों बाल-केंद्रित थे, परंतु डेवी का विद्यालय साझा समस्याएँ सुलझाने वाला एक सामाजिक समुदाय था, जबकि मॉन्टेसरी का बच्चा तैयार परिवेश में मुख्यतः वैयक्तिक रूप से कार्य करता था; विकल्प A और D में उनकी विशेषताएँ आपस में बदल दी गई हैं।"},
  {"id":"cdp-child-development-1688","question":"Which statement best contrasts Tagore and Gandhi on education?","options":["Tagore made a productive craft the centre of the curriculum, while Gandhi stressed the arts, nature and an international outlook","Gandhi centred education on productive craft and self-reliance; Tagore stressed creative freedom, nature and internationalism","Both opposed teaching through the mother tongue and preferred a classical language","Both wanted English as the medium of instruction in all schools"],"answer":1,"explanation":"Both favoured the mother tongue and rejected colonial rote schooling, but Gandhi’s Nai Talim centred on craft and self-reliance, while Tagore’s emphasis was on freedom, the arts, nature and internationalism.","difficulty":"hard","source":"CTET · State TET","questionHi":"शिक्षा पर टैगोर और गांधी की सबसे अच्छी तुलना कौन-सा कथन करता है?","optionsHi":["टैगोर ने उत्पादक शिल्प को पाठ्यचर्या का केंद्र बनाया, जबकि गांधी ने कलाओं, प्रकृति और अंतरराष्ट्रीय दृष्टिकोण पर ज़ोर दिया","गांधी ने शिक्षा को उत्पादक शिल्प और आत्मनिर्भरता पर केंद्रित किया; टैगोर ने सृजनात्मक स्वतंत्रता, प्रकृति और अंतरराष्ट्रीयता पर ज़ोर दिया","दोनों ने मातृभाषा के माध्यम से शिक्षण का विरोध किया और शास्त्रीय भाषा को प्राथमिकता दी","दोनों सभी विद्यालयों में शिक्षण के माध्यम के रूप में अंग्रेज़ी चाहते थे"],"explanationHi":"दोनों मातृभाषा के पक्षधर थे और औपनिवेशिक रटंत विद्यालयी शिक्षा को अस्वीकार करते थे, परंतु गांधी की नई तालीम शिल्प और आत्मनिर्भरता पर केंद्रित थी, जबकि टैगोर का ज़ोर स्वतंत्रता, कलाओं, प्रकृति और अंतरराष्ट्रीयता पर था।"},
  {"id":"cdp-child-development-1689","question":"A Montessori teacher arranges low shelves, child-sized jugs and real brooms so that three-year-olds can pour, sweep and dress themselves. The principle behind this ‘prepared environment’ is that:","options":["Children should be kept busy with chores so that the teacher gets time to rest","Adults should model such tasks first and then do them for young children to prevent spills and mistakes","Real tools teach caution, since minor injuries show children what is dangerous","An orderly, accessible setting lets children act independently and learn through their own activity"],"answer":3,"explanation":"Montessori designed the environment to fit the child so that the child can work independently (‘help me to do it myself’); the adult prepares rather than does.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"एक मॉन्टेसरी शिक्षिका नीची अलमारियाँ, बच्चों के आकार की सुराहियाँ और असली झाड़ू रखती है ताकि तीन वर्ष के बच्चे उँडेल सकें, झाड़ू लगा सकें और स्वयं कपड़े पहन सकें। इस ‘तैयार परिवेश’ के पीछे सिद्धांत क्या है?","optionsHi":["बच्चों को कामों में व्यस्त रखना चाहिए ताकि शिक्षिका को आराम का समय मिले","वयस्कों को पहले ऐसे कार्य करके दिखाने चाहिए और फिर छोटे बच्चों के लिए स्वयं कर देने चाहिए ताकि गिरना और गलतियाँ न हों","असली उपकरण सावधानी सिखाते हैं, क्योंकि छोटी चोटें बच्चों को दिखाती हैं कि क्या खतरनाक है","व्यवस्थित, सुलभ परिवेश बच्चों को स्वतंत्र रूप से कार्य करने और अपनी गतिविधि से सीखने देता है"],"explanationHi":"मॉन्टेसरी ने परिवेश को बच्चे के अनुरूप डिज़ाइन किया ताकि बच्चा स्वतंत्र रूप से कार्य कर सके (‘मुझे स्वयं करने में मदद करो’); वयस्क तैयारी करता है, स्वयं कार्य नहीं करता।"},
  {"id":"cdp-child-development-1690","question":"In Froebel’s kindergarten, ‘occupations’ such as paper folding, clay modelling and weaving differ from ‘gifts’ mainly in that:","options":["Occupations change the material itself (it is cut, folded or moulded), while gifts keep a fixed form","Occupations were meant only for the teachers and the older children, never for the kindergarten itself","Gifts were used as rewards and punishments to control the children’s behaviour","There is no real difference, as both terms refer to the same set of materials"],"answer":0,"explanation":"Froebel’s gifts (ball, blocks and so on) are fixed forms that children arrange; occupations use materials the child transforms, moving from discovery to creative production.","difficulty":"very-hard","source":"KVS PRT · DSSSB PRT","questionHi":"फ्रोबेल के किंडरगार्टन में, कागज़ मोड़ना, मिट्टी की मॉडलिंग और बुनाई जैसे ‘व्यवसाय’ (ऑक्यूपेशन्स) ‘उपहारों’ (गिफ़्ट्स) से मुख्यतः किस बात में भिन्न हैं?","optionsHi":["व्यवसाय सामग्री को स्वयं बदल देते हैं (उसे काटा, मोड़ा या ढाला जाता है), जबकि उपहार एक निश्चित रूप बनाए रखते हैं","व्यवसाय केवल शिक्षकों और बड़े बच्चों के लिए थे, किंडरगार्टन के लिए कभी नहीं","उपहारों का प्रयोग बच्चों के व्यवहार को नियंत्रित करने के लिए पुरस्कार और दंड के रूप में होता था","कोई वास्तविक अंतर नहीं है, क्योंकि दोनों शब्द सामग्री के एक ही समूह को दर्शाते हैं"],"explanationHi":"फ्रोबेल के उपहार (गेंद, गुटके आदि) निश्चित रूप हैं जिन्हें बच्चे व्यवस्थित करते हैं; व्यवसाय ऐसी सामग्री का उपयोग करते हैं जिसे बच्चा रूपांतरित करता है, और खोज से सृजनात्मक उत्पादन की ओर बढ़ता है।"},
  {"id":"cdp-child-development-1691","question":"Gijubhai Badheka was affectionately called ‘Moochhali Maa’ (the mother with a moustache) because:","options":["He ran a hostel for orphaned girls and was a mother figure to them","He wrote books mainly for mothers on how to raise small children","Though a man, he cared for children with a mother’s love and tenderness","He insisted that teachers be strict like fathers but gentle like mothers"],"answer":2,"explanation":"The nickname captures his motherly affection for children; Gijubhai rejected fear and strictness and built his Bal Mandir on love, freedom and joy.","difficulty":"moderate","source":"CTET Paper I · UPTET","questionHi":"गिजुभाई बधेका को स्नेह से ‘मूँछाली माँ’ (मूँछों वाली माँ) क्यों कहा जाता था?","optionsHi":["वे अनाथ बालिकाओं का एक छात्रावास चलाते थे और उनके लिए माँ समान थे","उन्होंने मुख्यतः माताओं के लिए छोटे बच्चों के पालन-पोषण पर पुस्तकें लिखीं","पुरुष होते हुए भी वे बच्चों की देखभाल माँ जैसे प्रेम और कोमलता से करते थे","वे आग्रह करते थे कि शिक्षक पिता की तरह कठोर परंतु माँ की तरह कोमल हों"],"explanationHi":"यह उपनाम बच्चों के प्रति उनके मातृवत स्नेह को दर्शाता है; गिजुभाई ने भय और कठोरता को अस्वीकार किया और अपने बाल मंदिर को प्रेम, स्वतंत्रता और आनंद पर आधारित किया।"},
  {"id":"cdp-child-development-1692","question":"Dewey described education as the continuous reconstruction of experience. A teacher acting on this idea would:","options":["Teach facts once and test whether they are reproduced exactly, so learning is measurable","Help children reorganise what they already know in light of new experiences, so it guides further experience","Set aside children’s prior experiences as unscientific and start afresh with the correct textbook ideas instead","Postpone real learning till adulthood, when a person’s experience of life is complete"],"answer":1,"explanation":"For Dewey, each new experience reorganises earlier ones and increases the ability to direct later ones; learning builds on, rather than ignores, what the child brings.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"डेवी ने शिक्षा को अनुभव का सतत पुनर्निर्माण बताया। इस विचार पर कार्य करने वाला शिक्षक क्या करेगा?","optionsHi":["तथ्य एक बार सिखाना और परखना कि वे ठीक-ठीक दोहराए जाते हैं या नहीं, ताकि अधिगम मापने योग्य हो","बच्चों को नए अनुभवों के आलोक में वह पुनर्गठित करने में मदद करना जो वे पहले से जानते हैं, ताकि वह आगे के अनुभव का मार्गदर्शन करे","बच्चों के पूर्व अनुभवों को अवैज्ञानिक मानकर एक ओर रख देना और सही पाठ्यपुस्तक के विचारों से नए सिरे से शुरू करना","वास्तविक अधिगम को प्रौढ़ावस्था तक टाल देना, जब व्यक्ति का जीवन-अनुभव पूर्ण हो जाता है"],"explanationHi":"डेवी के लिए, प्रत्येक नया अनुभव पहले के अनुभवों को पुनर्गठित करता है और बाद के अनुभवों को निर्देशित करने की क्षमता बढ़ाता है; अधिगम उस पर निर्माण करता है जो बच्चा लाता है, उसकी अनदेखी नहीं करता।"},
  {"id":"cdp-child-development-1693","question":"In a Class 7 test, many good students give different answers to one MCQ because two of its options are defensible. The main effect of such an item is that it:","options":["Raises the item’s discrimination, since only the best students notice both answers","Improves the test’s content validity, by covering two different ideas within one single question","Lowers reliability and validity, as scores partly reflect guessing the setter’s intention","Makes the item easier for everyone, since two answers can be marked right"],"answer":2,"explanation":"An ambiguous item adds random error (lower reliability) and measures something other than the intended learning (lower validity); it usually fails to separate strong from weak students.","difficulty":"moderate","source":"KVS TGT · DSSSB TGT","questionHi":"कक्षा 7 के एक परीक्षण में, कई अच्छे छात्र एक बहुविकल्पीय प्रश्न के अलग-अलग उत्तर देते हैं क्योंकि उसके दो विकल्प मान्य हैं। ऐसे प्रश्न का मुख्य प्रभाव यह है कि वह:","optionsHi":["प्रश्न की विभेदन-क्षमता बढ़ाता है, क्योंकि केवल सर्वश्रेष्ठ छात्र ही दोनों उत्तरों को पहचानते हैं","एक ही प्रश्न में दो भिन्न विचारों को समेटकर परीक्षण की विषयवस्तु वैधता को सुधारता है","विश्वसनीयता और वैधता घटाता है, क्योंकि अंक आंशिक रूप से प्रश्न-निर्माता के आशय का अनुमान लगाने को दर्शाते हैं","प्रश्न को सभी के लिए आसान बनाता है, क्योंकि दो उत्तर सही माने जा सकते हैं"],"explanationHi":"अस्पष्ट प्रश्न यादृच्छिक त्रुटि जोड़ता है (विश्वसनीयता कम) और इच्छित अधिगम के अलावा कुछ और मापता है (वैधता कम); यह प्रायः सशक्त और कमज़ोर छात्रों में अंतर करने में विफल रहता है।"},
  {"id":"cdp-child-development-1694","question":"Assertion (A): Self-assessment by students is unreliable and therefore has no place in school assessment. Reason (R): Without clear criteria, students may over- or under-rate their own work.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"R points to a real risk, but the remedy is to give students clear criteria and practice, not to drop self-assessment, which builds metacognition and is part of NEP 2020’s holistic progress card.","difficulty":"very-hard","source":"CTET · KVS PRT","questionHi":"अभिकथन (A): छात्रों द्वारा स्व-आकलन अविश्वसनीय है और इसलिए विद्यालयी आकलन में उसका कोई स्थान नहीं है। कारण (R): स्पष्ट मानदंडों के बिना छात्र अपने कार्य को अधिक या कम आँक सकते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"R एक वास्तविक जोखिम की ओर इशारा करता है, पर उपाय छात्रों को स्पष्ट मानदंड और अभ्यास देना है, स्व-आकलन छोड़ना नहीं, जो अधिसंज्ञान विकसित करता है और NEP 2020 के समग्र प्रगति कार्ड का हिस्सा है।"},
  {"id":"cdp-child-development-1695","question":"In ‘The Child and the Curriculum’, Dewey argued that the child’s experience and the organised school subjects are:","options":["Opposed to each other, so the teacher must choose to follow either the child’s own interests or the set subject","Unrelated, since subjects are adult inventions that have nothing to do with children’s lives","Two ends of one process: subject matter is the mature form of the child’s experience, and teaching links them","Relevant only for older students who have already gained enough experience of the world"],"answer":2,"explanation":"Dewey rejected both the subject-centred and the purely child-centred extremes; the task of teaching is to lead the child’s present experience towards the organised knowledge of the subjects.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"‘द चाइल्ड एंड द करिकुलम’ में डेवी ने तर्क दिया कि बच्चे का अनुभव और संगठित विद्यालयी विषय:","optionsHi":["एक-दूसरे के विरोधी हैं, इसलिए शिक्षक को या तो बच्चे की अपनी रुचियों या निर्धारित विषय का अनुसरण चुनना होगा","असंबद्ध हैं, क्योंकि विषय वयस्कों के आविष्कार हैं जिनका बच्चों के जीवन से कोई संबंध नहीं","एक ही प्रक्रिया के दो छोर हैं: विषयवस्तु बच्चे के अनुभव का परिपक्व रूप है, और शिक्षण उन्हें जोड़ता है","केवल बड़े छात्रों के लिए प्रासंगिक हैं जिन्होंने संसार का पर्याप्त अनुभव पा लिया है"],"explanationHi":"डेवी ने विषय-केंद्रित और विशुद्ध बाल-केंद्रित दोनों अतियों को अस्वीकार किया; शिक्षण का कार्य बच्चे के वर्तमान अनुभव को विषयों के संगठित ज्ञान की ओर ले जाना है।"},
  {"id":"cdp-child-development-1696","question":"A Montessori teacher shows a child two tablets and says, ‘This is rough; this is smooth.’ Next she asks, ‘Show me the rough one.’ Finally she asks, ‘What is this?’ This sequence is the:","options":["Herbartian five formal steps, from preparation to application","Three-period lesson: naming, then recognition, then recall","Socratic method of questioning to expose the child’s errors","Project method, built around a purposeful real-life task"],"answer":1,"explanation":"Montessori’s three-period lesson moves from naming (‘This is…’) to recognition (‘Show me…’) to recall (‘What is this?’), going from easier to harder demands.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"एक मॉन्टेसरी शिक्षिका बच्चे को दो पट्टिकाएँ दिखाकर कहती है, ‘यह खुरदरी है; यह चिकनी है।’ फिर वह पूछती है, ‘मुझे खुरदरी वाली दिखाओ।’ अंत में वह पूछती है, ‘यह क्या है?’ यह क्रम क्या है?","optionsHi":["हर्बार्टीय पाँच औपचारिक सोपान, तैयारी से अनुप्रयोग तक","त्रि-चरणीय पाठ: नामकरण, फिर पहचान, फिर स्मरण","बच्चे की त्रुटियाँ उजागर करने के लिए प्रश्न पूछने की सुकराती विधि","परियोजना विधि, जो उद्देश्यपूर्ण वास्तविक-जीवन कार्य पर आधारित है"],"explanationHi":"मॉन्टेसरी का त्रि-चरणीय पाठ नामकरण (‘यह है…’) से पहचान (‘मुझे दिखाओ…’) और फिर स्मरण (‘यह क्या है?’) की ओर बढ़ता है, जो आसान से कठिन माँगों की ओर जाता है।"},
  {"id":"cdp-child-development-1697","question":"Arrange these in a sensible sequence for helping a Class 4 group that struggles with division: P. Remedial teaching aimed at the error identified. Q. A diagnostic test to locate the specific difficulty. R. A formative check to see whether the difficulty has been resolved. S. Noticing during class work that the group keeps getting division wrong.","options":["S, Q, P, R","Q, S, P, R","S, P, Q, R","P, Q, S, R"],"answer":0,"explanation":"Classroom observation flags the problem, diagnosis pinpoints its cause, remedial teaching targets it and a follow-up check confirms whether it worked; remediating before diagnosing (option C) is guesswork.","difficulty":"hard","source":"CTET Paper I · State TET","questionHi":"भाग में संघर्ष करने वाले कक्षा 4 के समूह की सहायता के लिए इन्हें उचित क्रम में व्यवस्थित कीजिए: P. पहचानी गई त्रुटि पर लक्षित उपचारात्मक शिक्षण। Q. विशिष्ट कठिनाई का पता लगाने के लिए निदानात्मक परीक्षण। R. यह देखने के लिए रचनात्मक जाँच कि कठिनाई दूर हुई या नहीं। S. कक्षा-कार्य के दौरान यह देखना कि समूह भाग में बार-बार गलती करता है।","optionsHi":["S, Q, P, R","Q, S, P, R","S, P, Q, R","P, Q, S, R"],"explanationHi":"कक्षा-अवलोकन समस्या की ओर संकेत करता है, निदान उसका कारण पहचानता है, उपचारात्मक शिक्षण उसे लक्षित करता है और अनुवर्ती जाँच पुष्टि करती है कि वह कारगर रहा या नहीं; निदान से पहले उपचार करना (विकल्प C) अनुमान लगाना है।"},
  {"id":"cdp-child-development-1698","question":"Which of these are features of competency-based assessment? I. Items set in real-life or unfamiliar contexts. II. A focus on applying concepts. III. Questions whose answers can be copied word for word from the textbook. IV. A clear statement of the learning outcomes being assessed.","options":["I and III only","II and III only","I, II and IV only","I, II, III and IV"],"answer":2,"explanation":"Competency-based items assess application of learning outcomes in new contexts; answers lifted verbatim from the textbook test recall, the opposite of competency.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT","questionHi":"इनमें से कौन-सी योग्यता-आधारित आकलन की विशेषताएँ हैं? I. वास्तविक-जीवन या अपरिचित संदर्भों में रखे गए प्रश्न। II. संप्रत्ययों के अनुप्रयोग पर ध्यान। III. ऐसे प्रश्न जिनके उत्तर पाठ्यपुस्तक से शब्दशः उतारे जा सकें। IV. आकलित किए जा रहे अधिगम-प्रतिफलों का स्पष्ट कथन।","optionsHi":["केवल I और III","केवल II और III","केवल I, II और IV","I, II, III और IV"],"explanationHi":"योग्यता-आधारित प्रश्न नए संदर्भों में अधिगम-प्रतिफलों के अनुप्रयोग का आकलन करते हैं; पाठ्यपुस्तक से शब्दशः उठाए उत्तर स्मरण को परखते हैं, जो योग्यता के विपरीत है।"},
  {"id":"cdp-child-development-1699","question":"Which practice best reduces bias when a teacher marks essays?","options":["Reading the name first so as to recall each student’s past performance and keep all marks consistent","Marking the essays of strong students first to set a high standard for the rest","Giving extra marks for neat handwriting, since it shows care and effort in the essay","Marking without names, using a rubric, and marking one question across all scripts before the next"],"answer":3,"explanation":"Anonymous marking prevents halo and expectation effects, a rubric anchors judgement, and marking question by question keeps standards consistent across scripts.","difficulty":"hard","source":"CTET Paper II · DSSSB TGT","questionHi":"जब कोई शिक्षक निबंधों का मूल्यांकन करता है तो कौन-सी प्रथा पूर्वाग्रह को सबसे अधिक कम करती है?","optionsHi":["पहले नाम पढ़ना ताकि प्रत्येक छात्र का पिछला प्रदर्शन याद आए और सभी अंक संगत रहें","सशक्त छात्रों के निबंध पहले जाँचना ताकि बाकी के लिए ऊँचा मानक बने","सुंदर लिखावट के लिए अतिरिक्त अंक देना, क्योंकि वह निबंध में सावधानी और प्रयास दिखाती है","बिना नाम के, रूब्रिक का प्रयोग करके, और अगले प्रश्न से पहले सभी उत्तर-पुस्तिकाओं में एक प्रश्न जाँचकर अंकन करना"],"explanationHi":"अनाम अंकन हैलो और अपेक्षा प्रभावों को रोकता है, रूब्रिक निर्णय को आधार देता है, और प्रश्न-दर-प्रश्न अंकन उत्तर-पुस्तिकाओं में मानकों को संगत रखता है।"},
  {"id":"cdp-child-development-1700","question":"A teacher rates ‘presentation’ on a 1–5 scale with only the labels ‘poor’ to ‘excellent’, and two teachers using it disagree widely. The best fix is to:","options":["Convert it into a rubric that describes performance at each level","Stretch the scale to 1–10 so that finer differences can be shown","Simply average the two teachers’ ratings to cancel out their bias","Drop presentation from assessment altogether, as it is subjective"],"answer":0,"explanation":"Disagreement comes from undefined levels; describing what each level looks like gives raters a shared standard, whereas a longer scale only adds more undefined points.","difficulty":"hard","source":"CTET · KVS TGT","questionHi":"एक शिक्षक ‘प्रस्तुति’ को केवल ‘खराब’ से ‘उत्कृष्ट’ के नामों वाले 1–5 पैमाने पर आँकता है, और इसका प्रयोग करने वाले दो शिक्षक बहुत असहमत होते हैं। सर्वश्रेष्ठ उपाय क्या है?","optionsHi":["इसे ऐसे रूब्रिक में बदलना जो प्रत्येक स्तर पर निष्पादन का वर्णन करे","पैमाने को 1–10 तक बढ़ाना ताकि सूक्ष्म अंतर दिखाए जा सकें","दोनों शिक्षकों की रेटिंग का औसत लेना ताकि उनका पूर्वाग्रह समाप्त हो जाए","प्रस्तुति को आकलन से पूरी तरह हटा देना, क्योंकि वह व्यक्तिनिष्ठ है"],"explanationHi":"असहमति अपरिभाषित स्तरों से आती है; प्रत्येक स्तर कैसा दिखता है इसका वर्णन मूल्यांकनकर्ताओं को साझा मानक देता है, जबकि लंबा पैमाना केवल और अपरिभाषित बिंदु जोड़ता है।"},
  {"id":"cdp-child-development-1701","question":"At a staff meeting, the principal says, ‘Inclusion is the special educator’s job; class teachers should focus on the syllabus.’ Which response best reflects inclusive education?","options":["Inclusion is a whole-school duty: class teachers plan for all learners, with the special educator as a partner","The principal is right, since special educators alone are trained to teach such children","Class teachers should handle inclusion only during free periods, once the syllabus for the day has been covered","Inclusion is mainly the parents’ responsibility, with the school only providing admission"],"answer":0,"explanation":"Children spend most of their time with class teachers, so inclusion depends on every teacher's planning and attitude; specialists support it but cannot carry it alone.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"एक स्टाफ़ बैठक में प्रधानाचार्य कहते हैं, ‘समावेशन विशेष शिक्षक का कार्य है; कक्षा शिक्षकों को पाठ्यक्रम पर ध्यान देना चाहिए।’ कौन-सी प्रतिक्रिया समावेशी शिक्षा को सबसे अच्छी तरह दर्शाती है?","optionsHi":["समावेशन पूरे विद्यालय का दायित्व है: कक्षा शिक्षक सभी अधिगमकर्ताओं के लिए योजना बनाते हैं, विशेष शिक्षक के साथ साझेदारी में","प्रधानाचार्य सही हैं, क्योंकि केवल विशेष शिक्षक ही ऐसे बच्चों को पढ़ाने के लिए प्रशिक्षित होते हैं","कक्षा शिक्षकों को समावेशन केवल खाली पीरियडों में सँभालना चाहिए, जब दिन का पाठ्यक्रम पूरा हो जाए","समावेशन मुख्यतः माता-पिता की ज़िम्मेदारी है, विद्यालय केवल प्रवेश देता है"],"explanationHi":"बच्चे अपना अधिकांश समय कक्षा शिक्षकों के साथ बिताते हैं, इसलिए समावेशन हर शिक्षक की योजना और अभिवृत्ति पर निर्भर करता है; विशेषज्ञ इसमें सहायता करते हैं परंतु अकेले इसका भार नहीं उठा सकते।"},
  {"id":"cdp-child-development-1702","question":"Assertion (A): Schooling children with disabilities in separate institutions can limit their social participation later in adult life. Reason (R): Children build social skills, friendships and community networks by growing up and learning together.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Separation in childhood denies both groups the shared experiences through which social ties and mutual acceptance develop, which is why segregation can carry into adult life.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): दिव्यांग बच्चों को अलग संस्थानों में पढ़ाना बाद में वयस्क जीवन में उनकी सामाजिक भागीदारी को सीमित कर सकता है। कारण (R): बच्चे साथ-साथ बड़े होकर और सीखकर सामाजिक कौशल, मित्रता और सामुदायिक नेटवर्क बनाते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"बाल्यावस्था में अलगाव दोनों समूहों को उन साझा अनुभवों से वंचित करता है जिनसे सामाजिक संबंध और पारस्परिक स्वीकृति विकसित होती है, इसीलिए पृथक्करण वयस्क जीवन तक बना रह सकता है।"},
  {"id":"cdp-child-development-1703","question":"Assertion (A): Reasonable accommodation must be decided case by case, according to the needs of the individual child. Reason (R): The RPwD Act requires schools to give an identical set of aids to every child with a disability.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"The Act ties reasonable accommodation to individual requirements, so the right adjustment differs from child to child; an identical package for all is not what it requires.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अभिकथन (A): उचित सुविधा (रीज़नेबल एकोमोडेशन) का निर्णय प्रत्येक बच्चे की आवश्यकताओं के अनुसार प्रकरण-दर-प्रकरण होना चाहिए। कारण (R): RPwD अधिनियम विद्यालयों से अपेक्षा करता है कि वे प्रत्येक दिव्यांग बच्चे को सहायक साधनों का समान समूह दें।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"अधिनियम उचित सुविधा को व्यक्तिगत आवश्यकताओं से जोड़ता है, इसलिए सही समायोजन हर बच्चे के लिए भिन्न होता है; सबके लिए एक समान पैकेज इसकी अपेक्षा नहीं है।"},
  {"id":"cdp-child-development-1704","question":"A pre-primary teacher wants to spot early signs that a child may later have difficulty learning to read. Which observation is most worth noting?","options":["The child is left-handed and holds the pencil awkwardly while drawing","At age 5, the child sometimes writes letters such as b, d and s in mirror image on her slate","The child prefers drawing to listening to stories during circle time","Persistent difficulty recognising rhymes and breaking words into syllables, unlike her peers"],"answer":3,"explanation":"Weak phonological awareness, such as trouble with rhyme and syllables, is a strong early predictor of reading difficulty; left-handedness is irrelevant and mirror writing is common at this age.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक पूर्व-प्राथमिक शिक्षिका उन शुरुआती संकेतों को पहचानना चाहती है कि बच्चे को आगे चलकर पढ़ना सीखने में कठिनाई हो सकती है। कौन-सा अवलोकन सबसे अधिक नोट करने योग्य है?","optionsHi":["बच्चा बाएँ हाथ से काम करता है और चित्र बनाते समय पेंसिल को अटपटे ढंग से पकड़ता है","5 वर्ष की आयु में बच्ची अपनी स्लेट पर कभी-कभी b, d और s जैसे अक्षर दर्पण-प्रतिबिंब में लिखती है","बच्चा वृत्त-समय में कहानियाँ सुनने की बजाय चित्र बनाना पसंद करता है","साथियों के विपरीत, तुकबंदी पहचानने और शब्दों को अक्षरांशों (सिलेबल्स) में तोड़ने में लगातार कठिनाई"],"explanationHi":"कमज़ोर ध्वनि-बोध, जैसे तुक और अक्षरांशों में कठिनाई, पठन-कठिनाई का सशक्त प्रारंभिक पूर्वानुमानक है; बाएँ हाथ से काम करना अप्रासंगिक है और इस आयु में दर्पण-लेखन सामान्य है।"},
  {"id":"cdp-child-development-1705","question":"Harsh, in Class 5, explains maths reasoning well in untimed oral tasks and solves problems correctly at home, but freezes and leaves blank answers in timed class tests, saying ‘I hate maths.’ What is the most likely explanation and response?","options":["He has dyscalculia, a core difficulty with numbers, and needs an immediate referral for formal assessment now","He is lazy during tests and should be warned that marks will be cut","Maths anxiety is the likelier cause; reduce time pressure, use low-stakes practice and build confidence first","He has an attention disorder, since he does well only at home and not in class"],"answer":2,"explanation":"Sound understanding in relaxed settings with breakdown under timed pressure points to anxiety rather than a core number-processing difficulty like dyscalculia.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 5 का हर्ष बिना समय-सीमा के मौखिक कार्यों में गणित का तर्क अच्छी तरह समझाता है और घर पर प्रश्न सही हल करता है, परंतु समयबद्ध कक्षा परीक्षणों में जम जाता है और उत्तर खाली छोड़ देता है, कहता है ‘मुझे गणित से नफ़रत है।’ सबसे संभावित व्याख्या और प्रतिक्रिया क्या है?","optionsHi":["उसे डिस्कैल्कुलिया है, जो संख्याओं की मूल कठिनाई है, और अभी औपचारिक आकलन के लिए तुरंत भेजना चाहिए","वह परीक्षणों में आलसी है और उसे चेतावनी देनी चाहिए कि अंक काटे जाएँगे","गणित-चिंता अधिक संभावित कारण है; समय का दबाव घटाएँ, कम-जोखिम वाला अभ्यास कराएँ और पहले आत्मविश्वास बढ़ाएँ","उसे ध्यान संबंधी विकार है, क्योंकि वह केवल घर पर अच्छा करता है, कक्षा में नहीं"],"explanationHi":"आरामदायक परिवेश में ठोस समझ और समयबद्ध दबाव में टूट जाना चिंता की ओर संकेत करता है, डिस्कैल्कुलिया जैसी संख्या-प्रक्रमण की मूल कठिनाई की ओर नहीं।"},
  {"id":"cdp-child-development-1706","question":"A Class 3 teacher with several children who have attention difficulties is framing classroom rules. Which set of rules is likely to work best?","options":["A long list of 15 rules, each starting with ‘Don’t’, so that every possible kind of misbehaviour is covered","Rules decided by the teacher and announced once at the start of the year, then enforced","Rules that change every week so that children stay alert and do not get bored","A few positively stated rules (‘Raise your hand to speak’), shown with pictures and practised regularly"],"answer":3,"explanation":"Few, positive, visible and practised rules give clear guidance that children with attention difficulties can remember and follow; long negative lists are hard to hold in mind.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 3 की शिक्षिका, जिसके यहाँ ध्यान संबंधी कठिनाइयों वाले कई बच्चे हैं, कक्षा के नियम बना रही है। कौन-सा नियम-समूह सबसे अच्छा काम करने की संभावना रखता है?","optionsHi":["15 नियमों की लंबी सूची, प्रत्येक ‘मत’ से शुरू, ताकि हर संभव प्रकार का दुर्व्यवहार शामिल हो","शिक्षिका द्वारा तय किए गए और वर्ष के आरंभ में एक बार घोषित किए गए नियम, फिर लागू किए जाएँ","नियम जो हर सप्ताह बदलें ताकि बच्चे सतर्क रहें और ऊबें नहीं","कुछ सकारात्मक रूप से कहे गए नियम (‘बोलने के लिए हाथ उठाओ’), चित्रों के साथ दिखाए और नियमित रूप से अभ्यास किए गए"],"explanationHi":"कम, सकारात्मक, दृश्य और अभ्यास किए गए नियम ऐसा स्पष्ट मार्गदर्शन देते हैं जिसे ध्यान संबंधी कठिनाइयों वाले बच्चे याद रख सकें और अपना सकें; लंबी नकारात्मक सूचियाँ मन में रखना कठिन होता है।"},
  {"id":"cdp-child-development-1707","question":"A Class 4 teacher keeps telling Vihaan, who is autistic, ‘Look at me when I’m talking to you.’ Vihaan becomes anxious and stops following what she says. What is the most appropriate view?","options":["Many autistic children find eye contact distracting and listen better without it; check understanding in other ways","Eye contact must be insisted on firmly, since it shows respect and is the only proof that he is listening","Vihaan is being deliberately disrespectful and should be punished so the class sees it","Vihaan probably has a vision problem that makes eye contact hard, so test his eyes first"],"answer":0,"explanation":"Forcing eye contact can overload an autistic child and reduce attention to the content; understanding is better checked through responses than through gaze.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 4 की शिक्षिका ऑटिस्टिक बच्चे विहान से बार-बार कहती है, ‘जब मैं तुमसे बात कर रही हूँ तो मेरी ओर देखो।’ विहान चिंतित हो जाता है और उसकी बातों का अनुसरण करना बंद कर देता है। सबसे उपयुक्त दृष्टिकोण क्या है?","optionsHi":["अनेक ऑटिस्टिक बच्चों को आँखों का संपर्क ध्यान भंग करने वाला लगता है और वे उसके बिना बेहतर सुनते हैं; समझ को अन्य तरीकों से जाँचें","आँखों के संपर्क पर दृढ़ता से ज़ोर देना चाहिए, क्योंकि यह सम्मान दर्शाता है और यही उसके सुनने का एकमात्र प्रमाण है","विहान जानबूझकर अनादर कर रहा है और उसे दंडित किया जाना चाहिए ताकि कक्षा देखे","विहान को शायद दृष्टि की समस्या है जिससे आँखों का संपर्क कठिन है, इसलिए पहले उसकी आँखों की जाँच करें"],"explanationHi":"आँखों के संपर्क के लिए बाध्य करना ऑटिस्टिक बच्चे पर अतिभार डाल सकता है और विषयवस्तु पर ध्यान घटा सकता है; समझ को दृष्टि की अपेक्षा प्रतिक्रियाओं से बेहतर जाँचा जाता है।"},
  {"id":"cdp-child-development-1708","question":"Which of these statements about Braille are correct? I. Braille is read from left to right by touch. II. When writing with a slate and stylus, the dots are pressed into the reverse side of the paper, so the writer works from right to left. III. Standard literary Braille uses a cell of eight dots.","options":["I only","I and II only","II and III only","I, II and III"],"answer":1,"explanation":"Braille is read left to right; with a slate and stylus the dots are pressed from the reverse side, so writing proceeds right to left in mirror image. The standard literary cell has six dots, not eight.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"ब्रेल के बारे में इनमें से कौन-से कथन सही हैं? I. ब्रेल को स्पर्श से बाएँ से दाएँ पढ़ा जाता है। II. स्लेट और स्टाइलस से लिखते समय बिंदु काग़ज़ के पिछले पृष्ठ पर दबाए जाते हैं, इसलिए लेखक दाएँ से बाएँ कार्य करता है। III. मानक साहित्यिक ब्रेल में आठ बिंदुओं की कोशिका होती है।","optionsHi":["केवल I","केवल I और II","केवल II और III","I, II और III"],"explanationHi":"ब्रेल बाएँ से दाएँ पढ़ी जाती है; स्लेट और स्टाइलस से बिंदु पिछले पृष्ठ से दबाए जाते हैं, इसलिए लेखन दर्पण-प्रतिबिंब में दाएँ से बाएँ चलता है। मानक साहित्यिक कोशिका में छह बिंदु होते हैं, आठ नहीं।"},
  {"id":"cdp-child-development-1709","question":"Assertion (A): Identifying hearing loss in infancy is very important for a child’s language development. Reason (R): The early years are a sensitive period for acquiring language.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because language develops most readily in the early years, a hearing loss found late means lost access during that period; early identification allows timely aids and accessible language.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): शैशवावस्था में श्रवण-हानि की पहचान बच्चे के भाषा विकास के लिए अत्यंत महत्वपूर्ण है। कारण (R): प्रारंभिक वर्ष भाषा अर्जन के लिए संवेदनशील काल हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"क्योंकि भाषा प्रारंभिक वर्षों में सबसे सहजता से विकसित होती है, देर से पाई गई श्रवण-हानि का अर्थ है उस अवधि में पहुँच का खोना; शीघ्र पहचान से समय पर सहायक उपकरण और सुलभ भाषा संभव होती है।"},
  {"id":"cdp-child-development-1710","question":"For months, a teacher has guided the hand of Deepu, a child with intellectual disability, through every step of writing his name. He still cannot start on his own and waits for her hand. What is the problem and the fix?","options":["He is unwilling, so he should be made to try alone from now on without any help","He cannot learn to write, so the goal should be dropped from his plan altogether","He has become prompt-dependent; she should fade help step by step, from hand guidance to a touch, to gestures","He needs even more full hand-over-hand guidance, every day and for longer, until his writing improves by itself"],"answer":2,"explanation":"Prompts that are never faded create prompt dependence; reducing the level of help gradually and rewarding independent attempts builds independence.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"महीनों से एक शिक्षिका बौद्धिक अक्षमता वाले बच्चे दीपू का हाथ पकड़कर उसका नाम लिखने के हर चरण से गुज़ारती रही है। वह अब भी अपने आप शुरू नहीं कर पाता और उसके हाथ की प्रतीक्षा करता है। समस्या और उपाय क्या है?","optionsHi":["वह अनिच्छुक है, इसलिए अब से उसे बिना किसी सहायता के अकेले प्रयास करने को कहना चाहिए","वह लिखना नहीं सीख सकता, इसलिए लक्ष्य को उसकी योजना से पूरी तरह हटा देना चाहिए","वह संकेत-निर्भर हो गया है; उसे सहायता को चरण-दर-चरण घटाना चाहिए, हाथ पकड़ने से स्पर्श, फिर इशारों तक","उसे और भी अधिक पूर्ण हाथ-पर-हाथ मार्गदर्शन चाहिए, प्रतिदिन और अधिक समय तक, जब तक उसका लेखन स्वयं न सुधरे"],"explanationHi":"जिन संकेतों को कभी हटाया नहीं जाता वे संकेत-निर्भरता उत्पन्न करते हैं; सहायता का स्तर धीरे-धीरे घटाना और स्वतंत्र प्रयासों को पुरस्कृत करना स्वतंत्रता विकसित करता है।"},
  {"id":"cdp-child-development-1711","question":"A school has eight gifted students spread across four Class 5 sections, and each feels isolated. The school places all eight in one section with a teacher trained to extend them, while the section still has students of all abilities. This arrangement is called:","options":["Grade skipping","Tracking","Pull-out programme","Cluster grouping"],"answer":3,"explanation":"Cluster grouping places a small group of gifted students in an otherwise mixed-ability class so that they have intellectual peers and planned challenge; tracking streams whole classes by ability.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक विद्यालय में आठ प्रतिभाशाली छात्र कक्षा 5 के चार अनुभागों में बिखरे हैं, और प्रत्येक स्वयं को अलग-थलग महसूस करता है। विद्यालय सभी आठ को एक अनुभाग में रखता है जिसमें उन्हें आगे बढ़ाने के लिए प्रशिक्षित शिक्षक है, जबकि अनुभाग में सभी योग्यताओं के छात्र हैं। इस व्यवस्था को क्या कहते हैं?","optionsHi":["कक्षा छोड़कर आगे बढ़ाना (ग्रेड स्किपिंग)","स्तरीकरण (ट्रैकिंग)","बाहर निकालकर पढ़ाने का कार्यक्रम (पुल-आउट)","गुच्छ समूहीकरण (क्लस्टर ग्रुपिंग)"],"explanationHi":"गुच्छ समूहीकरण प्रतिभाशाली छात्रों के एक छोटे समूह को अन्यथा मिश्रित-योग्यता वाली कक्षा में रखता है ताकि उन्हें बौद्धिक साथी और नियोजित चुनौती मिले; स्तरीकरण पूरी कक्षाओं को योग्यता के आधार पर धाराओं में बाँटता है।"},
  {"id":"cdp-child-development-1712","question":"A teacher of a Class 6 section with 60 students says that differentiated instruction is impossible in such a large class. Which response is most realistic?","options":["She is right, so she should teach one way to all and simply accept the results","Differentiation means a separate lesson plan for each of the 60 students, so she first needs an assistant","Flexible groups, tiered tasks, choice of products and structured peer support make it workable even at 60","She should differentiate only for the top ten students, who can benefit the most"],"answer":2,"explanation":"Differentiation does not require individual lessons; grouping, tiering, choice and peer support let a teacher respond to diversity at scale.","difficulty":"hard","source":"CTET · State TETs","questionHi":"60 छात्रों वाले कक्षा 6 के अनुभाग की एक शिक्षिका कहती है कि इतनी बड़ी कक्षा में विभेदित अनुदेशन असंभव है। कौन-सी प्रतिक्रिया सबसे यथार्थवादी है?","optionsHi":["वह सही है, इसलिए उसे सबको एक ही ढंग से पढ़ाना चाहिए और परिणामों को बस स्वीकार करना चाहिए","विभेदन का अर्थ 60 छात्रों में से प्रत्येक के लिए अलग पाठ-योजना है, इसलिए उसे पहले एक सहायक चाहिए","लचीले समूह, स्तरीकृत कार्य, उत्पादों का चयन और संरचित सहपाठी सहायता इसे 60 में भी व्यावहारिक बनाते हैं","उसे केवल शीर्ष दस छात्रों के लिए विभेदन करना चाहिए, जो सबसे अधिक लाभान्वित हो सकते हैं"],"explanationHi":"विभेदन के लिए व्यक्तिगत पाठ आवश्यक नहीं; समूहीकरण, स्तरीकरण, चयन और सहपाठी सहायता शिक्षक को बड़े पैमाने पर विविधता का उत्तर देने में सक्षम करते हैं।"},
  {"id":"cdp-child-development-1713","question":"For a unit on ‘Our Food’, a Class 4 teacher gives a 3 × 3 grid of tasks, such as writing a recipe, drawing a food chain, interviewing a cook or making a market price chart. Students must complete any three in a line. What does this approach mainly provide?","options":["Choice in how students work and show learning, with all tasks aimed at the same unit goals","A way to rank students by how difficult the tasks they choose turn out to be","A replacement for teaching the unit, since students can now learn everything entirely on their own","Separate goals for each student, matched to the tasks they pick"],"answer":0,"explanation":"A choice board differentiates by interest and learning profile, giving students control over the route while every task addresses the shared learning goals.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"‘हमारा भोजन’ इकाई के लिए कक्षा 4 की शिक्षिका कार्यों का 3 × 3 ग्रिड देती है, जैसे व्यंजन-विधि लिखना, खाद्य शृंखला बनाना, किसी रसोइये का साक्षात्कार लेना या बाज़ार-भाव तालिका बनाना। छात्रों को एक पंक्ति में कोई तीन पूरे करने हैं। यह उपागम मुख्यतः क्या प्रदान करता है?","optionsHi":["छात्र कैसे कार्य करें और अधिगम कैसे दिखाएँ इसमें चयन, जबकि सभी कार्य समान इकाई-लक्ष्यों की ओर लक्षित हैं","चुने गए कार्यों की कठिनाई के आधार पर छात्रों को श्रेणीबद्ध करने का तरीका","इकाई को पढ़ाने का विकल्प, क्योंकि छात्र अब सब कुछ पूरी तरह स्वयं सीख सकते हैं","प्रत्येक छात्र के लिए अलग लक्ष्य, उनके चुने कार्यों के अनुरूप"],"explanationHi":"चयन-पट्ट रुचि और अधिगम प्रोफ़ाइल के अनुसार विभेदन करता है, और छात्रों को मार्ग पर नियंत्रण देता है जबकि प्रत्येक कार्य साझा अधिगम लक्ष्यों को संबोधित करता है।"},
  {"id":"cdp-child-development-1714","question":"Several Class 2 children in a school serving a low-income area are listless and inattentive in the first period, and the teacher learns many come to school without breakfast. What best explains the situation and the right response?","options":["They are lazy and need stricter discipline in the first period to build good habits","They have attention disorders and should all be referred to a specialist for diagnosis and medication","They are not interested in learning, so the first period should be made more fun","Hunger blocks attention and learning, so the school should ensure they get food early, via the meal scheme or a snack"],"answer":3,"explanation":"Basic physical needs must be met before children can attend to learning; hunger-related inattention is solved by food, not by discipline or labels.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"कम आय वाले क्षेत्र की सेवा करने वाले विद्यालय में कक्षा 2 के कई बच्चे पहले पीरियड में सुस्त और अन्यमनस्क रहते हैं, और शिक्षिका जानती है कि कई बिना नाश्ता किए विद्यालय आते हैं। स्थिति की सबसे अच्छी व्याख्या और सही प्रतिक्रिया क्या है?","optionsHi":["वे आलसी हैं और अच्छी आदतें बनाने के लिए पहले पीरियड में कठोर अनुशासन चाहिए","उन्हें ध्यान संबंधी विकार हैं और सभी को निदान और दवा के लिए विशेषज्ञ के पास भेजना चाहिए","वे सीखने में रुचि नहीं रखते, इसलिए पहले पीरियड को अधिक मनोरंजक बनाना चाहिए","भूख ध्यान और अधिगम को बाधित करती है, इसलिए विद्यालय को सुनिश्चित करना चाहिए कि उन्हें जल्दी भोजन मिले, भोजन योजना या नाश्ते के माध्यम से"],"explanationHi":"बच्चे अधिगम पर ध्यान दे सकें इससे पहले मूल शारीरिक आवश्यकताओं की पूर्ति होनी चाहिए; भूख से जुड़ी अन्यमनस्कता का समाधान भोजन है, अनुशासन या पहचान-चिह्न नहीं।"},
  {"id":"cdp-child-development-1715","question":"Assertion (A): Bringing up a child with two languages causes language delay. Reason (R): A bilingual child’s vocabulary in each single language may be smaller at first, though the total across both languages is comparable to that of monolingual children.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Bilingualism does not cause delay; counting only one language underestimates a bilingual child's vocabulary, so A is false while R is true.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अभिकथन (A): बच्चे को दो भाषाओं में पालने से भाषा-विलंब होता है। कारण (R): द्विभाषी बच्चे की प्रत्येक एकल भाषा में शब्दावली शुरू में कम हो सकती है, यद्यपि दोनों भाषाओं में कुल शब्दावली एकभाषी बच्चों के बराबर होती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"द्विभाषिकता विलंब उत्पन्न नहीं करती; केवल एक भाषा को गिनना द्विभाषी बच्चे की शब्दावली को कम आँकता है, इसलिए A असत्य है जबकि R सत्य है।"},
  {"id":"cdp-child-development-1716","question":"After two years in an English-medium school, Lalita, a Tulu-speaking child, refuses to speak Tulu even with her grandmother, saying it is ‘a village language’. Her English is still weak. Which concept best describes this?","options":["Additive bilingualism, where a second language is added to the first","Subtractive bilingualism, where the new language replaces the first instead of adding to it","Code-switching, moving between Tulu and English within the same conversation","Balanced bilingualism, in which she has roughly equal command of both languages"],"answer":1,"explanation":"When the school language displaces a devalued home language, the child loses the first language without fully gaining the second; additive bilingualism keeps and builds both.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अंग्रेज़ी-माध्यम विद्यालय में दो वर्ष बाद, तुलु भाषी बच्ची ललिता अपनी दादी के साथ भी तुलु बोलने से मना करती है, कहती है कि यह ‘गाँव की भाषा’ है। उसकी अंग्रेज़ी अब भी कमज़ोर है। कौन-सी अवधारणा इसका सबसे अच्छा वर्णन करती है?","optionsHi":["योगात्मक द्विभाषिकता, जहाँ प्रथम भाषा में दूसरी भाषा जोड़ी जाती है","ह्रासात्मक द्विभाषिकता, जहाँ नई भाषा पहली भाषा को जोड़ने के बजाय उसकी जगह ले लेती है","कोड-स्विचिंग, एक ही बातचीत के भीतर तुलु और अंग्रेज़ी के बीच आना-जाना","संतुलित द्विभाषिकता, जिसमें उसकी दोनों भाषाओं पर लगभग समान पकड़ है"],"explanationHi":"जब विद्यालय की भाषा अवमूल्यित घर की भाषा को विस्थापित कर देती है, तो बच्चा पहली भाषा खो देता है और दूसरी पूरी तरह नहीं पाता; योगात्मक द्विभाषिकता दोनों को बनाए रखती और विकसित करती है।"},
  {"id":"cdp-child-development-1717","question":"A Class 4 grammar worksheet uses sentences such as ‘Ramu cleans the drain’ and ‘Rohit is an engineer’, with names that, in the local context, are linked to caste and class. What is the concern?","options":["There is no concern, since the sentences are grammatically correct and such names are common in the area","Such examples quietly link some communities to low-status work and others to prestige, reinforcing stereotypes","The names are too difficult for Class 4 children to read and spell correctly","The worksheet should use only English names so that it is neutral and modern"],"answer":1,"explanation":"Teaching materials carry social messages; repeatedly pairing certain names with certain jobs reinforces hierarchies, so examples should be chosen to avoid such patterns.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 के व्याकरण कार्यपत्रक में ‘रामू नाली साफ़ करता है’ और ‘रोहित इंजीनियर है’ जैसे वाक्य हैं, जिनके नाम स्थानीय संदर्भ में जाति और वर्ग से जुड़े हैं। चिंता क्या है?","optionsHi":["कोई चिंता नहीं है, क्योंकि वाक्य व्याकरणिक रूप से सही हैं और क्षेत्र में ऐसे नाम सामान्य हैं","ऐसे उदाहरण चुपचाप कुछ समुदायों को निम्न-स्तर के कार्य से और अन्य को प्रतिष्ठा से जोड़ते हैं, जिससे रूढ़ धारणाएँ पुष्ट होती हैं","नाम कक्षा 4 के बच्चों के लिए पढ़ने और सही वर्तनी लिखने में बहुत कठिन हैं","कार्यपत्रक में केवल अंग्रेज़ी नाम होने चाहिए ताकि वह तटस्थ और आधुनिक हो"],"explanationHi":"शिक्षण सामग्री सामाजिक संदेश वहन करती है; कुछ नामों को कुछ व्यवसायों के साथ बार-बार जोड़ना पदानुक्रमों को पुष्ट करता है, इसलिए उदाहरण ऐसे प्रतिरूपों से बचते हुए चुने जाने चाहिए।"},
  {"id":"cdp-child-development-1718","question":"A Class 1 teacher insists that Zainab, who naturally writes with her left hand, must switch to her right hand, and scolds her when she does not. Which evaluation is correct?","options":["The teacher is right, since writing with the right hand is the correct, standard way taught in all good schools","It is acceptable, as long as the parents agree with the teacher’s decision","Left-handedness is natural; forcing a switch can cause frustration and slow writing, so support her left hand","Zainab may use either hand, but her left-handed work should be marked lower"],"answer":2,"explanation":"Handedness is a natural difference, not an error; respecting it, with suitable seating and pencil grip, is part of accepting diversity in class.","difficulty":"hard","source":"CTET · UPTET · State TETs","questionHi":"कक्षा 1 की शिक्षिका आग्रह करती है कि स्वाभाविक रूप से बाएँ हाथ से लिखने वाली ज़ैनब को दाएँ हाथ पर आना होगा, और जब वह नहीं आती तो उसे डाँटती है। कौन-सा मूल्यांकन सही है?","optionsHi":["शिक्षिका सही है, क्योंकि दाएँ हाथ से लिखना सही, मानक तरीका है जो सभी अच्छे विद्यालयों में सिखाया जाता है","यह स्वीकार्य है, जब तक माता-पिता शिक्षिका के निर्णय से सहमत हों","बाएँ हाथ का प्रयोग स्वाभाविक है; बदलने के लिए बाध्य करना हताशा उत्पन्न कर सकता है और लेखन धीमा कर सकता है, इसलिए उसके बाएँ हाथ का समर्थन करें","ज़ैनब किसी भी हाथ का उपयोग कर सकती है, पर उसके बाएँ हाथ के कार्य को कम अंक मिलने चाहिए"],"explanationHi":"हस्त-प्राथमिकता एक स्वाभाविक भिन्नता है, त्रुटि नहीं; उपयुक्त बैठक और पेंसिल-पकड़ के साथ उसका सम्मान करना कक्षा में विविधता को स्वीकार करने का हिस्सा है।"},
  {"id":"cdp-child-development-1719","question":"Which of these statements are correct? I. The RTE Act, 2009 requires private unaided schools to admit children from weaker sections and disadvantaged groups in at least 25% of entry-level seats. II. The RPwD Act, 2016 requires government and government-aided higher education institutions to reserve not less than 5% of seats for persons with benchmark disabilities. III. The RPwD Act requires private unaided schools to reserve 25% seats exclusively for children with disabilities.","options":["I and II only","II and III only","I only","I, II and III"],"answer":0,"explanation":"RTE's 25% entry-level provision covers weaker sections and disadvantaged groups, and the RPwD Act reserves at least 5% of seats in government and aided higher education institutions; there is no 25% disability-only quota.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"इनमें से कौन-से कथन सही हैं? I. RTE अधिनियम, 2009 के अनुसार निजी गैर-सहायता प्राप्त विद्यालयों को प्रवेश-स्तर की कम से कम 25% सीटों पर कमज़ोर वर्गों और वंचित समूहों के बच्चों को प्रवेश देना आवश्यक है। II. RPwD अधिनियम, 2016 के अनुसार सरकारी और सरकारी सहायता प्राप्त उच्च शिक्षा संस्थानों को बेंचमार्क दिव्यांगता वाले व्यक्तियों के लिए 5% से कम सीटें आरक्षित नहीं करनी चाहिए। III. RPwD अधिनियम के अनुसार निजी गैर-सहायता प्राप्त विद्यालयों को 25% सीटें केवल दिव्यांग बच्चों के लिए आरक्षित करनी चाहिए।","optionsHi":["केवल I और II","केवल II और III","केवल I","I, II और III"],"explanationHi":"RTE का प्रवेश-स्तर का 25% प्रावधान कमज़ोर वर्गों और वंचित समूहों को शामिल करता है, और RPwD अधिनियम सरकारी और सहायता प्राप्त उच्च शिक्षा संस्थानों में कम से कम 5% सीटें आरक्षित करता है; केवल दिव्यांगता के लिए 25% कोटा नहीं है।"},
  {"id":"cdp-child-development-1720","question":"Assertion (A): Autistic children do not want to have friends. Reason (R): Many autistic children find it hard to read social cues and unwritten rules of interaction.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Many autistic children want friendships but struggle with how to make and keep them because social cues are hard to read; so A is false while R is true.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अभिकथन (A): ऑटिस्टिक बच्चे मित्र नहीं बनाना चाहते। कारण (R): अनेक ऑटिस्टिक बच्चों को सामाजिक संकेतों और अंतःक्रिया के अलिखित नियमों को पढ़ना कठिन लगता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"अनेक ऑटिस्टिक बच्चे मित्रता चाहते हैं पर उसे बनाने और निभाने में कठिनाई पाते हैं क्योंकि सामाजिक संकेत पढ़ना कठिन होता है; इसलिए A असत्य है जबकि R सत्य है।"},
  {"id":"cdp-child-development-1721","question":"A new Class 5 teacher avoids saying words like ‘see’ and ‘look’ in front of Ayesha, who is blind, and gets flustered when she slips. Which advice is most appropriate?","options":["She should carefully replace every such word with ‘touch’ or ‘hear’ whenever Ayesha is present in class","She should avoid talking directly to Ayesha so that such slips do not upset her","She should ask the whole class never to use such words near Ayesha, to protect her feelings","She can use words like ‘see’ and ‘look’ naturally, as blind people do; what matters is describing visuals clearly"],"answer":3,"explanation":"Blind people use ‘see’ and ‘look’ in ordinary speech; avoiding them only creates awkwardness, while clear verbal description is what gives real access.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"कक्षा 5 की एक नई शिक्षिका दृष्टिबाधित आयशा के सामने ‘देखो’ और ‘नज़र डालो’ जैसे शब्द कहने से बचती है, और चूक होने पर घबरा जाती है। कौन-सा परामर्श सबसे उपयुक्त है?","optionsHi":["उसे आयशा की उपस्थिति में हर ऐसे शब्द को सावधानी से ‘छुओ’ या ‘सुनो’ से बदलना चाहिए","उसे आयशा से सीधे बात करने से बचना चाहिए ताकि ऐसी चूकें उसे परेशान न करें","उसे पूरी कक्षा से कहना चाहिए कि आयशा के पास कभी ऐसे शब्द न बोलें, ताकि उसकी भावनाएँ सुरक्षित रहें","वह ‘देखो’ और ‘नज़र डालो’ जैसे शब्द स्वाभाविक रूप से प्रयोग कर सकती है, जैसे दृष्टिबाधित लोग करते हैं; महत्वपूर्ण है दृश्यों का स्पष्ट वर्णन करना"],"explanationHi":"दृष्टिबाधित लोग सामान्य बोलचाल में ‘देखो’ और ‘नज़र डालो’ का प्रयोग करते हैं; उनसे बचना केवल असहजता पैदा करता है, जबकि स्पष्ट मौखिक वर्णन वास्तविक पहुँच देता है।"},
  {"id":"cdp-child-development-1722","question":"Ishita, a Class 8 student with hearing impairment, cannot watch the teacher’s face and take notes at the same time, so she misses either the lesson or the notes. Which support is best?","options":["Asking her to write faster, using abbreviations, so that she can watch the teacher and still keep up","Arranging a peer note-taker or giving printed notes, so she can keep her eyes on the speaker","Asking her to copy a classmate’s notes during the next period instead","Letting her skip note-taking altogether and rely only on the textbook"],"answer":1,"explanation":"Speech-reading needs constant visual attention, which competes with writing; providing notes removes this conflict without lowering the content.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"श्रवण-बाधित कक्षा 8 की छात्रा इशिता शिक्षिका का चेहरा देखने और नोट्स लेने का काम एक साथ नहीं कर पाती, इसलिए वह या तो पाठ से चूकती है या नोट्स से। कौन-सी सहायता सर्वश्रेष्ठ है?","optionsHi":["उससे संक्षिप्त रूपों का प्रयोग करते हुए तेज़ लिखने को कहना, ताकि वह शिक्षिका को देख सके और साथ भी चल सके","सहपाठी नोट-लेखक की व्यवस्था करना या छपे नोट्स देना, ताकि वह वक्ता पर नज़र रख सके","उससे अगले पीरियड में किसी सहपाठी के नोट्स उतारने को कहना","उसे नोट्स लेना पूरी तरह छोड़ने देना और केवल पाठ्यपुस्तक पर निर्भर रहना"],"explanationHi":"वाक्-पठन के लिए निरंतर दृश्य ध्यान चाहिए, जो लिखने से प्रतिस्पर्धा करता है; नोट्स उपलब्ध कराना विषयवस्तु को घटाए बिना इस टकराव को हटा देता है।"},
  {"id":"cdp-child-development-1723","question":"In a Class 5 science lesson on plants, the class studies plant parts and their functions in detail. Bhola, who has intellectual disability, works alongside them in the same activity, learning to name the main parts and to water and care for the class plant. This approach is best described as:","options":["Segregation within the class, since his goals and tasks are kept separate from everyone else’s","Multi-level teaching: children work on the same topic and activity towards different goals suited to them","Tracking, placing him in a lower stream for science","Curriculum compacting, letting him skip parts of the content he has already mastered"],"answer":1,"explanation":"Multi-level teaching (curriculum overlapping) keeps the child in the shared lesson while his goals are set at his level; he is not removed or given an unrelated task.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 5 के पौधों पर विज्ञान के पाठ में, कक्षा पौधों के भागों और उनके कार्यों का विस्तार से अध्ययन करती है। बौद्धिक अक्षमता वाला भोला उसी गतिविधि में उनके साथ काम करता है, मुख्य भागों के नाम बताना और कक्षा के पौधे को पानी देना व उसकी देखभाल करना सीखता है। इस उपागम का सबसे अच्छा वर्णन क्या है?","optionsHi":["कक्षा के भीतर पृथक्करण, क्योंकि उसके लक्ष्य और कार्य सबसे अलग रखे गए हैं","बहु-स्तरीय शिक्षण: बच्चे एक ही विषय और गतिविधि पर अपने अनुरूप अलग-अलग लक्ष्यों की ओर कार्य करते हैं","स्तरीकरण (ट्रैकिंग), उसे विज्ञान के लिए निचली धारा में रखना","पाठ्यचर्या संक्षेपण, उसे विषयवस्तु के उन भागों को छोड़ने देना जिनमें वह पहले से निपुण है"],"explanationHi":"बहु-स्तरीय शिक्षण (पाठ्यचर्या अतिव्यापन) बच्चे को साझा पाठ में रखता है जबकि उसके लक्ष्य उसके स्तर पर निर्धारित होते हैं; उसे हटाया नहीं जाता या असंबद्ध कार्य नहीं दिया जाता।"},
  {"id":"cdp-child-development-1724","question":"Assertion (A): Before a gifted child skips a grade, her social and emotional readiness should be considered along with her academic ability. Reason (R): Acceleration always harms gifted children.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A careful decision weighs academic, social and emotional factors and the child's own wishes; for well-chosen students acceleration is often successful, so the claim that it always harms is false.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): किसी प्रतिभाशाली बच्चे के कक्षा छोड़ने से पहले, उसकी शैक्षणिक योग्यता के साथ-साथ उसकी सामाजिक और भावनात्मक तत्परता पर भी विचार किया जाना चाहिए। कारण (R): त्वरण सदैव प्रतिभाशाली बच्चों को हानि पहुँचाता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"सावधानीपूर्ण निर्णय शैक्षणिक, सामाजिक और भावनात्मक कारकों तथा बच्चे की अपनी इच्छा को तौलता है; भली-भाँति चुने गए छात्रों के लिए त्वरण प्रायः सफल होता है, इसलिए यह दावा कि वह सदैव हानि पहुँचाता है, असत्य है।"},
  {"id":"cdp-child-development-1725","question":"In a Class 6 class, several children tease a dark-skinned classmate, calling her ‘kali’ and saying fair skin is beautiful. What is the most appropriate response?","options":["Stopping the teasing as discrimination and discussing how colour-based beauty ideas are prejudices that hurt","Telling the girl to ignore it and stay calm, since the other children mean it only as a harmless joke","Advising her parents to try fairness creams so the teasing stops","Ignoring it, since children usually outgrow such remarks as they get older"],"answer":0,"explanation":"Colour-based teasing reflects a deep social prejudice and harms self-esteem; the teacher must stop it and help children question the bias behind it.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 6 में, कई बच्चे एक साँवली सहपाठी को ‘काली’ कहकर चिढ़ाते हैं और कहते हैं कि गोरी त्वचा सुंदर होती है। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["चिढ़ाने को भेदभाव मानकर रोकना और चर्चा करना कि रंग-आधारित सौंदर्य की धारणाएँ पूर्वाग्रह हैं जो आहत करते हैं","लड़की से कहना कि उसे अनदेखा करे और शांत रहे, क्योंकि अन्य बच्चे इसे केवल हानिरहित मज़ाक के रूप में कहते हैं","उसके माता-पिता को सलाह देना कि वे गोरेपन की क्रीम आज़माएँ ताकि चिढ़ाना बंद हो जाए","इसे अनदेखा करना, क्योंकि बच्चे बड़े होने पर प्रायः ऐसी टिप्पणियों से उबर जाते हैं"],"explanationHi":"रंग-आधारित चिढ़ाना गहरे सामाजिक पूर्वाग्रह को दर्शाता है और आत्म-सम्मान को हानि पहुँचाता है; शिक्षक को इसे रोकना चाहिए और बच्चों को इसके पीछे के पूर्वाग्रह पर प्रश्न करने में सहायता करनी चाहिए।"},
  {"id":"cdp-child-development-1726","question":"A nine-year-old who dropped out after Class 1 re-enrols in a government school and is placed in an age-appropriate class. Under the RTE Act, the special training she is entitled to should be:","options":["Given only in a separate residential school, where she must stay until she turns 14 and finishes Class 8","Organised so she can catch up and join her age-appropriate class, preferably on the school premises","Replaced by simply placing her in Class 1 with six-year-olds to start afresh","Given only after she passes an admission test showing her level"],"answer":1,"explanation":"Section 4 and the rules under it treat special training as a bridge that helps an out-of-school child join her age-appropriate class; it is not a reason to segregate, test or demote her.","difficulty":"hard","source":"CTET · UPTET · REET","questionHi":"नौ वर्ष की एक बच्ची जिसने कक्षा 1 के बाद पढ़ाई छोड़ दी थी, एक सरकारी विद्यालय में पुनः नामांकित होती है और उसे आयु-उपयुक्त कक्षा में रखा जाता है। RTE अधिनियम के अंतर्गत उसे मिलने वाला विशेष प्रशिक्षण कैसा होना चाहिए?","optionsHi":["केवल एक अलग आवासीय विद्यालय में दिया जाए, जहाँ उसे 14 वर्ष की होने और कक्षा 8 पूरी करने तक रहना होगा","इस प्रकार आयोजित हो कि वह पकड़ बना सके और अपनी आयु-उपयुक्त कक्षा में शामिल हो सके, अधिमानतः विद्यालय परिसर में","उसे छह वर्ष के बच्चों के साथ कक्षा 1 में रखकर नए सिरे से शुरू कराने से बदल दिया जाए","केवल तब दिया जाए जब वह प्रवेश परीक्षा पास कर ले जो उसका स्तर दिखाए"],"explanationHi":"धारा 4 और उसके अंतर्गत नियम विशेष प्रशिक्षण को एक सेतु मानते हैं जो विद्यालय से बाहर रही बच्ची को उसकी आयु-उपयुक्त कक्षा में शामिल होने में सहायता करता है; यह उसे अलग करने, परीक्षा लेने या नीचे की कक्षा में डालने का कारण नहीं है।"},
  {"id":"cdp-child-development-1727","question":"A private school continues to run without a certificate of recognition after the RTE Act came into force. Which statement is correct under the Act?","options":["It may keep running as long as it follows the prescribed CBSE syllabus and uses NCERT textbooks in all classes","It may keep running if it admits 25% children from disadvantaged groups every year","It cannot run without recognition; the fine is up to ₹1 lakh, plus up to ₹10,000 per day if it continues","Only government and aided schools need a certificate of recognition under the Act"],"answer":2,"explanation":"Section 18 requires every non-government school covered by the Act to obtain recognition, with fines for running without it; the 25% quota and syllabus have nothing to do with recognition.","difficulty":"very-hard","source":"CTET · DSSSB PRT","questionHi":"RTE अधिनियम लागू होने के बाद भी एक निजी विद्यालय बिना मान्यता प्रमाणपत्र के चलता रहता है। अधिनियम के अंतर्गत कौन-सा कथन सही है?","optionsHi":["वह चलता रह सकता है जब तक वह निर्धारित CBSE पाठ्यक्रम का पालन करे और सभी कक्षाओं में NCERT पाठ्यपुस्तकें प्रयोग करे","वह चलता रह सकता है यदि वह हर वर्ष वंचित समूहों के 25% बच्चों को प्रवेश दे","वह बिना मान्यता के नहीं चल सकता; जुर्माना ₹1 लाख तक है, और जारी रखने पर प्रतिदिन ₹10,000 तक अतिरिक्त","अधिनियम के अंतर्गत केवल सरकारी और सहायता प्राप्त विद्यालयों को मान्यता प्रमाणपत्र चाहिए"],"explanationHi":"धारा 18 के अनुसार अधिनियम द्वारा आच्छादित प्रत्येक गैर-सरकारी विद्यालय को मान्यता प्राप्त करनी होती है, और बिना उसके चलाने पर जुर्माना है; 25% कोटा और पाठ्यक्रम का मान्यता से कोई संबंध नहीं है।"},
  {"id":"cdp-child-development-1728","question":"Assertion (A): Dewey accepted Froebel’s emphasis on play and the child’s self-activity. Reason (R): Dewey also endorsed the mystical, symbolic meanings that Froebel attached to his gifts.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Dewey praised Froebel’s respect for play and self-activity but criticised his abstract symbolism, arguing that play should be grounded in the child’s actual social life.","difficulty":"very-hard","source":"KVS PGT · DSSSB TGT","questionHi":"अभिकथन (A): डेवी ने खेल और बच्चे की आत्म-क्रियाशीलता पर फ्रोबेल के ज़ोर को स्वीकार किया। कारण (R): डेवी ने फ्रोबेल द्वारा अपने उपहारों से जोड़े गए रहस्यवादी, प्रतीकात्मक अर्थों का भी समर्थन किया।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"डेवी ने फ्रोबेल के खेल और आत्म-क्रियाशीलता के सम्मान की प्रशंसा की पर उनके अमूर्त प्रतीकवाद की आलोचना की, यह तर्क देते हुए कि खेल बच्चे के वास्तविक सामाजिक जीवन पर आधारित होना चाहिए।"},
  {"id":"cdp-child-development-1729","question":"Gandhi’s scheme was called ‘Basic’ Education mainly because:","options":["It taught only the basics of reading, writing and arithmetic to village children","It was meant only for the lowest classes of a school, before the formal academic subjects were begun","It was a short basic course to be followed by English-medium schooling in towns","It was rooted in the basic crafts and needs of village life, as the foundation of national education"],"answer":3,"explanation":"‘Basic’ referred to education grounded in the fundamental crafts and needs of the people, forming the base of national education, not to a minimal literacy course.","difficulty":"hard","source":"CTET · UPTET","questionHi":"गांधी की योजना को मुख्यतः ‘बुनियादी’ शिक्षा क्यों कहा गया?","optionsHi":["यह ग्रामीण बच्चों को केवल पढ़ने, लिखने और अंकगणित की बुनियादी बातें सिखाती थी","यह विद्यालय की केवल निम्नतम कक्षाओं के लिए थी, औपचारिक शैक्षणिक विषय शुरू करने से पहले","यह एक छोटा बुनियादी पाठ्यक्रम था जिसके बाद शहरों में अंग्रेज़ी-माध्यम की स्कूली शिक्षा होनी थी","यह ग्रामीण जीवन के बुनियादी शिल्पों और आवश्यकताओं में निहित थी, राष्ट्रीय शिक्षा की नींव के रूप में"],"explanationHi":"‘बुनियादी’ का आशय लोगों के मूल शिल्पों और आवश्यकताओं पर आधारित शिक्षा से था, जो राष्ट्रीय शिक्षा का आधार बने, न कि न्यूनतम साक्षरता पाठ्यक्रम से।"},
  {"id":"cdp-child-development-1730","question":"When a high-stakes board examination tests mainly recall, teachers start drilling students on past papers and skipping projects and discussion. This influence of an examination on teaching is called the:","options":["Washback (backwash) effect","Halo effect in marking","Hawthorne effect of observation","Pygmalion (expectancy) effect"],"answer":0,"explanation":"Washback is the effect a test has on teaching and learning; NCF 2005 and NEP 2020 want board exams reformed partly so that their washback encourages understanding rather than rote drill.","difficulty":"hard","source":"KVS TGT · DSSSB TGT","questionHi":"जब ऊँचे दाँव वाली बोर्ड परीक्षा मुख्यतः स्मरण को परखती है, तो शिक्षक छात्रों से पिछले वर्षों के प्रश्न-पत्रों का अभ्यास करवाने लगते हैं और परियोजनाओं तथा चर्चा को छोड़ देते हैं। शिक्षण पर परीक्षा के इस प्रभाव को क्या कहते हैं?","optionsHi":["प्रतिप्रवाह प्रभाव (वॉशबैक)","अंकन में हैलो प्रभाव","अवलोकन का हॉथॉर्न प्रभाव","पिग्मेलियन (प्रत्याशा) प्रभाव"],"explanationHi":"वॉशबैक वह प्रभाव है जो परीक्षण का शिक्षण और अधिगम पर पड़ता है; NCF 2005 और NEP 2020 चाहते हैं कि बोर्ड परीक्षाओं में सुधार हो, आंशिक रूप से ताकि उनका वॉशबैक रटंत अभ्यास के बजाय समझ को प्रोत्साहित करे।"},
  {"id":"cdp-child-development-1731","question":"Consider: I. In a criterion-referenced test, every student in a class can get the top grade. II. A norm-referenced test suits situations where a fixed number of candidates must be selected. III. A criterion-referenced test reports each student’s percentile rank in the group. Which are correct?","options":["I only","I and II only","II and III only","I, II and III"],"answer":1,"explanation":"Criterion-referenced results compare each student with a standard, so all can reach it; percentile ranks belong to norm-referenced reporting, which suits selection, so III is wrong.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"विचार कीजिए: I. मानदंड-संदर्भित परीक्षण में कक्षा का प्रत्येक छात्र सर्वोच्च ग्रेड पा सकता है। II. मानक-संदर्भित परीक्षण उन स्थितियों के लिए उपयुक्त है जहाँ परीक्षार्थियों की एक निश्चित संख्या चुननी हो। III. मानदंड-संदर्भित परीक्षण समूह में प्रत्येक छात्र की प्रतिशतक श्रेणी बताता है। कौन-से सही हैं?","optionsHi":["केवल I","केवल I और II","केवल II और III","I, II और III"],"explanationHi":"मानदंड-संदर्भित परिणाम प्रत्येक छात्र की तुलना एक मानक से करते हैं, इसलिए सभी उस तक पहुँच सकते हैं; प्रतिशतक श्रेणियाँ मानक-संदर्भित प्रतिवेदन की हैं, जो चयन के लिए उपयुक्त है, इसलिए III गलत है।"},
  {"id":"cdp-child-development-1732","question":"Ms. Bano judges whether her new reading circles worked by looking at children’s test scores, her own observation notes and short interviews with the children. Using several sources of evidence in this way is called:","options":["Randomisation","Standardisation","Generalisation","Triangulation"],"answer":3,"explanation":"Triangulation cross-checks a finding through different kinds of data; when scores, observation and interviews agree, the teacher-researcher’s conclusion is more credible.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"सुश्री बानो अपने नए पठन-मंडलों की सफलता का निर्णय बच्चों के परीक्षण-अंकों, अपने अवलोकन-नोट्स और बच्चों के संक्षिप्त साक्षात्कारों को देखकर करती हैं। इस प्रकार प्रमाण के कई स्रोतों का उपयोग करना क्या कहलाता है?","optionsHi":["यादृच्छिकीकरण","मानकीकरण","सामान्यीकरण","त्रिकोणन (ट्राइएंग्युलेशन)"],"explanationHi":"त्रिकोणन विभिन्न प्रकार के आँकड़ों से किसी निष्कर्ष की क्रॉस-जाँच करता है; जब अंक, अवलोकन और साक्षात्कार सहमत होते हैं, तो शिक्षक-अनुसंधानकर्ता का निष्कर्ष अधिक विश्वसनीय होता है।"},
  {"id":"cdp-child-development-1733","question":"Tagore modelled Santiniketan partly on the ancient Indian ashram (tapovan) ideal. This implies:","options":["Teachers and students living simply together close to nature, learning through a shared life","A strict separation between teachers and students, with lessons held only in formal classrooms","Learning only the scriptures by rote under a single strict guru","Military-style discipline and drill in a remote forest camp"],"answer":0,"explanation":"Tagore drew on the forest-hermitage tradition, where pupils and teachers lived together close to nature; he combined it with freedom, the arts and an international outlook.","difficulty":"hard","source":"CTET · State TET","questionHi":"टैगोर ने शांतिनिकेतन को आंशिक रूप से प्राचीन भारतीय आश्रम (तपोवन) के आदर्श पर ढाला। इसका अर्थ है:","optionsHi":["शिक्षक और छात्र प्रकृति के निकट सादगी से साथ रहते हैं, साझा जीवन के माध्यम से सीखते हैं","शिक्षकों और छात्रों के बीच कठोर पृथक्करण, पाठ केवल औपचारिक कक्षाओं में","एक कठोर गुरु के अधीन केवल शास्त्रों को रटकर सीखना","दूरस्थ वन-शिविर में सैन्य-शैली का अनुशासन और कवायद"],"explanationHi":"टैगोर ने वन-आश्रम परंपरा से प्रेरणा ली, जहाँ शिष्य और गुरु प्रकृति के निकट साथ रहते थे; उन्होंने इसे स्वतंत्रता, कलाओं और अंतरराष्ट्रीय दृष्टिकोण से जोड़ा।"},
  {"id":"cdp-child-development-1734","question":"Which limitation applies most to true–false items in a classroom test?","options":["They cannot be scored objectively, since different teachers may disagree about the right answer","They take students a long time to answer compared with other item types","With only two choices, guessing succeeds half the time, and such items often test trivial facts","They cannot be used in subjects such as mathematics or science at all"],"answer":2,"explanation":"True–false items are quick and objective to score, but the high chance of guessing lowers reliability, and they tend to test isolated facts rather than understanding.","difficulty":"moderate","source":"CTET · KVS TGT","questionHi":"कक्षा परीक्षण में सही–गलत प्रश्नों पर कौन-सी सीमा सबसे अधिक लागू होती है?","optionsHi":["उन्हें वस्तुनिष्ठ रूप से अंकित नहीं किया जा सकता, क्योंकि सही उत्तर पर अलग-अलग शिक्षक असहमत हो सकते हैं","अन्य प्रकार के प्रश्नों की तुलना में छात्रों को उत्तर देने में बहुत समय लगता है","केवल दो विकल्पों के साथ, अनुमान आधी बार सफल होता है, और ऐसे प्रश्न प्रायः तुच्छ तथ्यों को परखते हैं","उनका प्रयोग गणित या विज्ञान जैसे विषयों में बिल्कुल नहीं किया जा सकता"],"explanationHi":"सही–गलत प्रश्नों को अंकित करना तेज़ और वस्तुनिष्ठ है, परंतु अनुमान की ऊँची संभावना विश्वसनीयता घटाती है, और वे समझ के बजाय पृथक तथ्यों को परखते हैं।"},
  {"id":"cdp-child-development-1735","question":"A Class 10 mathematics test is so long that most students cannot finish it, and careful, able students often score lower than quick but careless ones. The main problem is that:","options":["The test is too reliable, giving the same rank order whatever students know","Speed has become a construct-irrelevant factor, lowering validity as a measure of understanding","The test is criterion-referenced, so it cannot separate able students from weak or careless ones","The test has high face validity, which always reduces its true validity"],"answer":1,"explanation":"If the aim is to measure understanding, working speed is irrelevant to that construct; an unintended speed test rewards the wrong quality and so distorts what scores mean.","difficulty":"hard","source":"KVS TGT · DSSSB TGT","questionHi":"कक्षा 10 का गणित परीक्षण इतना लंबा है कि अधिकांश छात्र उसे पूरा नहीं कर पाते, और सावधान, योग्य छात्र प्रायः तेज़ पर लापरवाह छात्रों से कम अंक पाते हैं। मुख्य समस्या यह है कि:","optionsHi":["परीक्षण बहुत अधिक विश्वसनीय है, जो छात्र कुछ भी जानें वही श्रेणी-क्रम देता है","गति एक संरचना-अप्रासंगिक कारक बन गई है, जो समझ के माप के रूप में वैधता घटाती है","परीक्षण मानदंड-संदर्भित है, इसलिए वह योग्य छात्रों को कमज़ोर या लापरवाह छात्रों से अलग नहीं कर सकता","परीक्षण की आभासी वैधता उच्च है, जो सदैव उसकी वास्तविक वैधता घटाती है"],"explanationHi":"यदि लक्ष्य समझ को मापना है, तो कार्य की गति उस संरचना के लिए अप्रासंगिक है; अनचाहा गति-परीक्षण गलत गुण को पुरस्कृत करता है और इसलिए अंकों के अर्थ को विकृत करता है।"},
  {"id":"cdp-child-development-1736","question":"In a village school, Dalit children are made to sit separately during the mid-day meal. Under the RTE Act, this violates:","options":["The duty of government and local authorities to ensure that disadvantaged children are not discriminated against","Nothing in the RTE Act, since seating during the mid-day meal is purely an internal school matter","Only criminal law, since the RTE Act itself says nothing at all about discrimination against any group of children","Section 28 on private tuition, which covers teachers’ conduct in school"],"answer":0,"explanation":"Sections 8 and 9 oblige the government and local authority to ensure that children of weaker sections and disadvantaged groups are not discriminated against; segregation at meals is exactly such discrimination.","difficulty":"hard","source":"CTET · UPTET","questionHi":"एक ग्रामीण विद्यालय में दलित बच्चों को मध्याह्न भोजन के दौरान अलग बैठाया जाता है। RTE अधिनियम के अंतर्गत, यह किसका उल्लंघन है?","optionsHi":["सरकार और स्थानीय प्राधिकरणों के उस कर्तव्य का कि वंचित बच्चों के साथ भेदभाव न हो","RTE अधिनियम में इसका कुछ नहीं, क्योंकि मध्याह्न भोजन के दौरान बैठने की व्यवस्था विशुद्ध आंतरिक विद्यालयी मामला है","केवल आपराधिक कानून का, क्योंकि RTE अधिनियम स्वयं बच्चों के किसी समूह के साथ भेदभाव के बारे में कुछ नहीं कहता","निजी ट्यूशन पर धारा 28 का, जो विद्यालय में शिक्षकों के आचरण को समेटती है"],"explanationHi":"धाराएँ 8 और 9 सरकार और स्थानीय प्राधिकरण को बाध्य करती हैं कि कमज़ोर वर्गों और वंचित समूहों के बच्चों के साथ भेदभाव न हो; भोजन में अलगाव ठीक ऐसा ही भेदभाव है।"},
  {"id":"cdp-child-development-1737","question":"NEP 2020’s idea of school complexes or clusters mainly aims to:","options":["Place all the government schools in a block under a single private management company to cut running costs","Increase the number of board examinations that students must take each year","Let nearby schools share teachers, libraries, labs and counsellors, reducing the isolation of small schools","Replace anganwadis with primary schools so that pre-school ends"],"answer":2,"explanation":"NEP 2020 notes that many schools are very small and isolated; grouping them into complexes lets them share teachers and facilities and builds a professional community.","difficulty":"hard","source":"CTET · KVS PRT","questionHi":"NEP 2020 की विद्यालय-परिसर या समूह की अवधारणा का मुख्य उद्देश्य क्या है?","optionsHi":["संचालन-लागत घटाने के लिए एक खंड के सभी सरकारी विद्यालयों को किसी एक निजी प्रबंधन कंपनी के अधीन रखना","छात्रों को प्रति वर्ष देनी पड़ने वाली बोर्ड परीक्षाओं की संख्या बढ़ाना","निकट के विद्यालयों को शिक्षक, पुस्तकालय, प्रयोगशालाएँ और परामर्शदाता साझा करने देना, छोटे विद्यालयों का अलगाव कम करना","आँगनवाड़ियों को प्राथमिक विद्यालयों से बदलना ताकि पूर्व-विद्यालय समाप्त हो जाए"],"explanationHi":"NEP 2020 नोट करती है कि अनेक विद्यालय बहुत छोटे और अलग-थलग हैं; उन्हें परिसरों में समूहित करने से वे शिक्षक और सुविधाएँ साझा कर सकते हैं और एक व्यावसायिक समुदाय बनता है।"},
  {"id":"cdp-child-development-1738","question":"A Class 4 student asks, ‘Why does our textbook show only city families with cars?’ In the spirit of NCF 2005, the teacher should:","options":["Tell the student that the textbook has been approved by experts and so must not be questioned in class","Ignore the question and continue the lesson so that the syllabus is not delayed","Ask the student to raise such points only after school, so the class is not disturbed","Welcome the question, discuss whose lives the book shows and leaves out, and add examples from children’s lives"],"answer":3,"explanation":"NCF 2005 values children’s questions and experiences and wants the curriculum to reflect diverse lives; a critical question is a learning opportunity, not indiscipline.","difficulty":"moderate","source":"CTET Paper I · KVS PRT","questionHi":"कक्षा 4 का एक छात्र पूछता है, ‘हमारी पाठ्यपुस्तक में केवल कारों वाले शहरी परिवार ही क्यों दिखाए गए हैं?’ NCF 2005 की भावना के अनुरूप, शिक्षिका को क्या करना चाहिए?","optionsHi":["छात्र से कहना कि पाठ्यपुस्तक विशेषज्ञों द्वारा अनुमोदित है और इसलिए कक्षा में उस पर प्रश्न नहीं उठाए जाने चाहिए","प्रश्न को अनदेखा करके पाठ जारी रखना ताकि पाठ्यक्रम में देरी न हो","छात्र से कहना कि ऐसी बातें विद्यालय के बाद उठाए, ताकि कक्षा में बाधा न हो","प्रश्न का स्वागत करना, चर्चा करना कि पुस्तक किनके जीवन को दिखाती और किन्हें छोड़ देती है, और बच्चों के जीवन से उदाहरण जोड़ना"],"explanationHi":"NCF 2005 बच्चों के प्रश्नों और अनुभवों को महत्व देता है और चाहता है कि पाठ्यचर्या विविध जीवनों को प्रतिबिंबित करे; आलोचनात्मक प्रश्न अधिगम का अवसर है, अनुशासनहीनता नहीं।"},
  {"id":"cdp-child-development-1739","question":"A teacher inspired by Dewey would expect good discipline in class to come mainly from:","options":["Children’s fear of punishment if they break the class rules","Children’s absorption in shared, purposeful work in which each has a role","Strict rules of silence that the teacher enforces firmly and consistently all day","Rewards for obedience, such as stars and extra play time"],"answer":1,"explanation":"Dewey saw discipline as growing out of engagement in a common task, as in any working community; order imposed by fear or bribes is external and short-lived.","difficulty":"hard","source":"CTET Paper II · DSSSB TGT","questionHi":"डेवी से प्रेरित शिक्षक कक्षा में अच्छा अनुशासन मुख्यतः किससे आने की अपेक्षा करेगा?","optionsHi":["कक्षा के नियम तोड़ने पर बच्चों के मन में दंड का भय","साझा, उद्देश्यपूर्ण कार्य में बच्चों की तल्लीनता, जिसमें प्रत्येक की एक भूमिका हो","मौन के कठोर नियम जिन्हें शिक्षक दिन भर दृढ़ता और निरंतरता से लागू करे","आज्ञाकारिता के लिए पुरस्कार, जैसे सितारे और अतिरिक्त खेल-समय"],"explanationHi":"डेवी अनुशासन को साझा कार्य में संलग्नता से उपजता मानते थे, जैसा किसी भी कार्यशील समुदाय में होता है; भय या प्रलोभन से थोपी गई व्यवस्था बाह्य और अल्पकालिक होती है।"},
  {"id":"cdp-child-development-1740","question":"Which of these is NOT one of the key strategies of formative assessment described by Dylan Wiliam?","options":["Clarifying and sharing learning intentions and success criteria","Giving feedback that moves learners forward","Ranking students publicly after every test to motivate them","Activating students as owners of their own learning and as resources for one another"],"answer":2,"explanation":"Wiliam’s strategies include sharing intentions, engineering effective discussions and questions, feedback that moves learning forward, and activating peers and the learners themselves; public ranking undermines formative assessment.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"इनमें से कौन-सी डिलन विलियम द्वारा वर्णित रचनात्मक आकलन की प्रमुख रणनीतियों में से नहीं है?","optionsHi":["अधिगम के उद्देश्यों और सफलता के मानदंडों को स्पष्ट करना और साझा करना","ऐसी प्रतिपुष्टि देना जो अधिगमकर्ताओं को आगे बढ़ाए","प्रेरित करने के लिए हर परीक्षण के बाद छात्रों को सार्वजनिक रूप से श्रेणीबद्ध करना","छात्रों को अपने अधिगम के स्वामी और एक-दूसरे के संसाधन के रूप में सक्रिय करना"],"explanationHi":"विलियम की रणनीतियों में उद्देश्यों को साझा करना, प्रभावी चर्चाएँ और प्रश्न गढ़ना, अधिगम को आगे बढ़ाने वाली प्रतिपुष्टि, और साथियों तथा अधिगमकर्ताओं को स्वयं सक्रिय करना शामिल हैं; सार्वजनिक श्रेणी निर्धारण रचनात्मक आकलन को कमज़ोर करता है।"},
  {"id":"cdp-child-development-1741","question":"Which Class 7 mathematics task mainly targets ‘applying’ in the revised Bloom’s taxonomy?","options":["‘State the formula for the area of a rectangle.’","‘How many 30 cm × 30 cm tiles are needed to cover a floor measuring 3 m × 4.5 m?’","‘Devise and justify a new method for finding the area of any irregular shape you like.’","‘Explain in your own words what area means.’"],"answer":1,"explanation":"Applying means using a known procedure in a given situation (here, area and unit conversion, giving 150 tiles); stating is remembering, explaining is understanding and devising a new method is creating.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"कक्षा 7 का कौन-सा गणित कार्य मुख्यतः संशोधित ब्लूम वर्गीकरण में ‘अनुप्रयोग’ को लक्षित करता है?","optionsHi":["‘आयत के क्षेत्रफल का सूत्र बताइए।’","‘30 cm × 30 cm की कितनी टाइलें 3 m × 4.5 m माप के फ़र्श को ढकने के लिए चाहिए?’","‘किसी भी अनियमित आकृति का क्षेत्रफल निकालने की एक नई विधि सोचिए और उसका औचित्य बताइए।’","‘क्षेत्रफल का अर्थ अपने शब्दों में समझाइए।’"],"explanationHi":"अनुप्रयोग का अर्थ है किसी ज्ञात प्रक्रिया को दी गई स्थिति में प्रयोग करना (यहाँ क्षेत्रफल और इकाई-रूपांतरण, जिससे 150 टाइलें आती हैं); बताना स्मरण है, समझाना बोध है और नई विधि सोचना सृजन है।"},
  {"id":"cdp-child-development-1742","question":"Which routine best builds assessment AS learning in a Class 4 classroom?","options":["Children end each day writing in a learning log what they learnt, what puzzled them and what to try next","The teacher marks a short test every Saturday and returns it on Monday with grades and corrections","A rank list of the class is displayed on the notice board every month so that all can see their progress","Parents check and sign the homework diary daily to keep track"],"answer":0,"explanation":"Assessment as learning develops the learner’s own monitoring of learning; a reflective learning log does this, whereas teacher marking, ranking and parental checks keep the learner passive.","difficulty":"hard","source":"CTET Paper I · State TET","questionHi":"कक्षा 4 में कौन-सी दिनचर्या ‘अधिगम के रूप में आकलन’ को सबसे अच्छी तरह विकसित करती है?","optionsHi":["बच्चे प्रत्येक दिन के अंत में अधिगम-डायरी में लिखते हैं कि उन्होंने क्या सीखा, क्या उलझाया और आगे क्या आज़माना है","शिक्षक प्रत्येक शनिवार को एक छोटा परीक्षण जाँचता है और सोमवार को ग्रेड और सुधार सहित लौटाता है","कक्षा की श्रेणी-सूची प्रत्येक माह सूचना-पट्ट पर लगाई जाती है ताकि सभी अपनी प्रगति देख सकें","माता-पिता ट्रैक रखने के लिए प्रतिदिन गृहकार्य-डायरी जाँचते और हस्ताक्षर करते हैं"],"explanationHi":"अधिगम के रूप में आकलन अधिगमकर्ता की अपने अधिगम की निगरानी को विकसित करता है; चिंतनशील अधिगम-डायरी यह करती है, जबकि शिक्षक द्वारा अंकन, श्रेणी निर्धारण और अभिभावकों की जाँच अधिगमकर्ता को निष्क्रिय रखती है।"},
  {"id":"cdp-child-development-1743","question":"Under NEP 2020, early childhood care and education (ECCE) is to be delivered through:","options":["Private play schools only, licensed and regulated by each state government","Grade 1 classrooms only, with ECCE merged fully into formal primary teaching from age five","Home tutoring by parents alone, supported by television lessons","Strengthened anganwadis and stand-alone or co-located pre-schools (Balavatikas), with trained staff"],"answer":3,"explanation":"NEP 2020 proposes universal ECCE through strengthened anganwadis and pre-schools, including those co-located with primary schools, staffed by trained ECCE workers and teachers.","difficulty":"hard","source":"CTET Paper I · KVS PRT","questionHi":"NEP 2020 के अंतर्गत, प्रारंभिक बाल्यावस्था देखभाल और शिक्षा (ECCE) किसके माध्यम से प्रदान की जानी है?","optionsHi":["केवल निजी प्ले स्कूल, जिन्हें प्रत्येक राज्य सरकार द्वारा लाइसेंस और विनियमित किया जाए","केवल कक्षा 1 की कक्षाएँ, ECCE को पाँच वर्ष की आयु से औपचारिक प्राथमिक शिक्षण में पूरी तरह मिलाकर","केवल माता-पिता द्वारा घर पर ट्यूशन, टेलीविज़न पाठों की सहायता से","सशक्त की गई आँगनवाड़ियाँ और स्वतंत्र या सह-स्थित पूर्व-विद्यालय (बालवाटिकाएँ), प्रशिक्षित कर्मचारियों के साथ"],"explanationHi":"NEP 2020 सशक्त आँगनवाड़ियों और पूर्व-विद्यालयों के माध्यम से सार्वभौमिक ECCE का प्रस्ताव करती है, जिनमें प्राथमिक विद्यालयों के साथ सह-स्थित भी शामिल हैं, और जिनमें प्रशिक्षित ECCE कार्यकर्ता और शिक्षक होते हैं।"},
  {"id":"cdp-child-development-1744","question":"The 2012 amendment to the RTE Act made provision for children with disabilities. Under it, a child with multiple or severe disabilities:","options":["Is excluded from the coverage of the Act entirely","May also have the right to opt for home-based education","Must attend a special school only, not a regular school","Gets free education only till the age of ten years"],"answer":1,"explanation":"The 2012 amendment brought children with disabilities within the Act and allowed those with multiple or severe disabilities to also opt for home-based education; it did not exclude or segregate them.","difficulty":"very-hard","source":"CTET · DSSSB PRT","questionHi":"RTE अधिनियम के 2012 के संशोधन ने दिव्यांग बच्चों के लिए प्रावधान किया। इसके अंतर्गत, बहु या गंभीर दिव्यांगता वाला बच्चा:","optionsHi":["अधिनियम के दायरे से पूरी तरह बाहर है","गृह-आधारित शिक्षा चुनने का अधिकार भी रख सकता है","केवल विशेष विद्यालय में जाएगा, नियमित विद्यालय में नहीं","केवल दस वर्ष की आयु तक निःशुल्क शिक्षा पाता है"],"explanationHi":"2012 के संशोधन ने दिव्यांग बच्चों को अधिनियम के दायरे में लाया और बहु या गंभीर दिव्यांगता वालों को गृह-आधारित शिक्षा चुनने का भी विकल्प दिया; इसने उन्हें बाहर नहीं किया या अलग नहीं किया।"},
  {"id":"cdp-child-development-1745","question":"Assertion (A): Nai Talim aimed at the harmonious development of the head, the heart and the hand. Reason (R): Gandhi held that a craft taught scientifically, with the child learning the why and how of each process, develops the intellect as well as the hand.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Gandhi insisted that craft be taught not mechanically but scientifically, so that manual work became a route to intellectual and moral growth, which is how Nai Talim sought to develop head, heart and hand together.","difficulty":"very-hard","source":"CTET Paper II · UPTET","questionHi":"अभिकथन (A): नई तालीम का उद्देश्य मस्तिष्क, हृदय और हाथ का सामंजस्यपूर्ण विकास था। कारण (R): गांधी का मत था कि वैज्ञानिक रूप से सिखाया गया शिल्प, जिसमें बच्चा प्रत्येक प्रक्रिया का क्यों और कैसे सीखता है, बुद्धि के साथ-साथ हाथ को भी विकसित करता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"गांधी का आग्रह था कि शिल्प यांत्रिक रूप से नहीं, वैज्ञानिक रूप से सिखाया जाए, ताकि हस्तकार्य बौद्धिक और नैतिक विकास का मार्ग बने, और इसी प्रकार नई तालीम ने मस्तिष्क, हृदय और हाथ को साथ-साथ विकसित करना चाहा।"},
  {"id":"cdp-child-development-1746","question":"A teacher video-records her Class 9 lesson and notices that she called on boys four times as often as girls. The most reflective next step is to:","options":["Delete the video and forget about it, since one lesson proves nothing","Conclude that the girls are simply less interested in the subject, so calling on them would embarrass them","Plan a strategy such as random name sticks and longer wait time, then record another lesson to check","Ask the boys to speak less in future so that girls get more chances"],"answer":2,"explanation":"Reflective practice turns evidence into a planned change and then checks the result; blaming the girls or the boys skips the examination of her own questioning habits.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"एक शिक्षिका अपने कक्षा 9 के पाठ की वीडियो रिकॉर्डिंग करती है और देखती है कि उसने लड़कियों की तुलना में लड़कों को चार गुना अधिक बार बुलाया। सबसे चिंतनशील अगला कदम क्या है?","optionsHi":["वीडियो हटाकर भूल जाना, क्योंकि एक पाठ से कुछ सिद्ध नहीं होता","निष्कर्ष निकालना कि लड़कियों की विषय में रुचि बस कम है, इसलिए उन्हें बुलाना उन्हें शर्मिंदा करेगा","यादृच्छिक नाम-पर्चियों और अधिक प्रतीक्षा-समय जैसी रणनीति बनाना, फिर जाँचने के लिए एक और पाठ रिकॉर्ड करना","लड़कों से भविष्य में कम बोलने को कहना ताकि लड़कियों को अधिक अवसर मिलें"],"explanationHi":"चिंतनशील अभ्यास प्रमाण को नियोजित परिवर्तन में बदलता है और फिर परिणाम जाँचता है; लड़कियों या लड़कों को दोष देना उसके अपने प्रश्न पूछने की आदतों की जाँच को छोड़ देता है।"},
  {"id":"cdp-child-development-1747","question":"A father in Jaipur keeps his ten-year-old daughter at home to look after her younger siblings. Which RTE provision does this most directly conflict with?","options":["Section 10, which makes it the duty of every parent or guardian to admit the child to elementary education","Section 28, which bars teachers from giving private tuition to their own students","Section 27, which limits the deployment of teachers for non-educational work like the census","Section 23, which lays down the minimum qualifications required for appointing teachers in all schools"],"answer":0,"explanation":"Section 10 (echoing Article 51A(k)) places on parents and guardians the duty to get their children aged 6–14 admitted to elementary education.","difficulty":"hard","source":"CTET · REET","questionHi":"जयपुर का एक पिता अपनी दस वर्षीय बेटी को छोटे भाई-बहनों की देखभाल के लिए घर पर रखता है। यह RTE के किस प्रावधान से सबसे प्रत्यक्ष टकराता है?","optionsHi":["धारा 10, जो हर माता-पिता या संरक्षक का कर्तव्य बनाती है कि बच्चे को प्रारंभिक शिक्षा में प्रवेश दिलाए","धारा 28, जो शिक्षकों को अपने ही छात्रों को निजी ट्यूशन देने से रोकती है","धारा 27, जो जनगणना जैसे गैर-शैक्षिक कार्य में शिक्षकों की तैनाती सीमित करती है","धारा 23, जो सभी विद्यालयों में शिक्षकों की नियुक्ति के लिए न्यूनतम योग्यताएँ निर्धारित करती है"],"explanationHi":"धारा 10 (अनुच्छेद 51A(k) को प्रतिध्वनित करती हुई) माता-पिता और संरक्षकों पर कर्तव्य डालती है कि वे 6–14 आयु के अपने बच्चों को प्रारंभिक शिक्षा में प्रवेश दिलाएँ।"},
  {"id":"cdp-child-development-1748","question":"A teacher has Class 5 children colour pictures of the planets for an hour and calls it ‘learning by doing’. A Deweyan critique would be that:","options":["Colouring is the best form of learning in science, since children enjoy it and remember the planets’ colours","Dewey opposed all hands-on work in school as a waste of learning time","Science should be taught only through lectures, with activities left for art class","Activity is educative only when it involves thinking about a problem and its consequences, not busy handwork"],"answer":3,"explanation":"For Dewey, ‘doing’ matters because it engages reflective thought about a real problem; hands-on activity without minds-on inquiry is just busywork.","difficulty":"very-hard","source":"CTET Paper II · DSSSB TGT","questionHi":"एक शिक्षिका कक्षा 5 के बच्चों से एक घंटे तक ग्रहों के चित्रों में रंग भरवाती है और इसे ‘करके सीखना’ कहती है। इस पर डेवी की दृष्टि से आलोचना यह होगी कि:","optionsHi":["रंग भरना विज्ञान में अधिगम का सर्वोत्तम रूप है, क्योंकि बच्चे उसका आनंद लेते हैं और ग्रहों के रंग याद रखते हैं","डेवी स्कूल में सभी हस्त-कार्यों के विरुद्ध थे क्योंकि वे अधिगम-समय की बर्बादी हैं","विज्ञान केवल व्याख्यान से पढ़ाया जाना चाहिए, गतिविधियाँ कला की कक्षा के लिए छोड़ देनी चाहिए","गतिविधि तभी शैक्षिक है जब उसमें किसी समस्या और उसके परिणामों के बारे में सोचना शामिल हो, केवल व्यस्त हस्तकार्य नहीं"],"explanationHi":"डेवी के लिए, ‘करना’ इसलिए महत्वपूर्ण है कि वह किसी वास्तविक समस्या पर चिंतनशील विचार को संलग्न करता है; मानसिक अन्वेषण के बिना प्रत्यक्ष गतिविधि केवल व्यस्तता है।"},
  {"id":"cdp-child-development-1749","question":"A Class 6 child with dyslexia understands science well but scores poorly on written tests. Which adaptation keeps the assessment valid while making it fair?","options":["Asking her easier science questions than the rest of the class, so that she is sure to score well this time","Exempting her from science assessment altogether because of her dyslexia","Grading her mainly on her handwriting and spelling to improve them","Giving extra time, reading questions aloud or allowing oral answers, on the same science concepts"],"answer":3,"explanation":"Accommodations remove barriers unrelated to what is being measured (reading and writing) while the construct, science understanding, stays the same; easier questions would change what is assessed.","difficulty":"hard","source":"CTET · KVS TGT","questionHi":"डिस्लेक्सिया वाली कक्षा 6 की बच्ची विज्ञान अच्छी तरह समझती है पर लिखित परीक्षणों में कम अंक पाती है। कौन-सा अनुकूलन आकलन को वैध रखते हुए उसे निष्पक्ष बनाता है?","optionsHi":["उससे कक्षा के बाकी बच्चों की तुलना में आसान विज्ञान प्रश्न पूछना, ताकि इस बार उसे अच्छे अंक मिलना निश्चित हो","उसकी डिस्लेक्सिया के कारण उसे विज्ञान के आकलन से पूरी तरह छूट देना","उसकी लिखावट और वर्तनी को सुधारने के लिए उसे मुख्यतः उन्हीं पर ग्रेड देना","उन्हीं विज्ञान संप्रत्ययों पर अतिरिक्त समय देना, प्रश्न ज़ोर से पढ़ना या मौखिक उत्तर की अनुमति देना"],"explanationHi":"सुविधाएँ उन बाधाओं को हटाती हैं जो जो मापा जा रहा है उससे असंबद्ध हैं (पढ़ना और लिखना), जबकि संरचना, विज्ञान की समझ, वही रहती है; आसान प्रश्न जो आँका जा रहा है उसे बदल देंगे।"},
  {"id":"cdp-child-development-1750","question":"A Class 6 child writes ‘0.25 is greater than 0.3, because 25 is greater than 3’. The best formative response is to:","options":["Mark it wrong and write the correct answer beside it in red ink so that he can study it at home that evening","Make him repeat the rule ‘compare the tenths digit first’ ten times until he remembers it","Use place-value charts or shaded grids to show tenths and hundredths, then ask him to compare and explain","Move on, since it is only a minor slip that he will correct later"],"answer":2,"explanation":"The error reveals a misconception (treating decimals as whole numbers, ‘longer is larger’); a representation that exposes place value lets the child rebuild the idea, which correction or drill cannot do.","difficulty":"hard","source":"CTET Paper II · KVS TGT","questionHi":"कक्षा 6 का बच्चा लिखता है ‘0.25, 0.3 से बड़ा है, क्योंकि 25, 3 से बड़ा है’। सबसे अच्छी रचनात्मक प्रतिक्रिया क्या है?","optionsHi":["इसे गलत अंकित करना और लाल स्याही में उसके बगल में सही उत्तर लिखना ताकि वह उस शाम घर पर उसका अध्ययन कर सके","उससे नियम ‘पहले दशमांश का अंक तुलना करो’ दस बार दोहरवाना जब तक वह याद न कर ले","दशमांश और शतांश दिखाने के लिए स्थानमान चार्ट या छायांकित ग्रिड का उपयोग करना, फिर उससे तुलना करने और समझाने को कहना","आगे बढ़ जाना, क्योंकि यह केवल एक छोटी चूक है जिसे वह बाद में स्वयं ठीक कर लेगा"],"explanationHi":"त्रुटि एक भ्रांत धारणा प्रकट करती है (दशमलव को पूर्ण संख्या मानना, ‘लंबा अर्थात बड़ा’); स्थानमान को उजागर करने वाला निरूपण बच्चे को विचार का पुनर्निर्माण करने देता है, जो सुधार या अभ्यास नहीं कर सकते।"},
  {"id":"cdp-child-development-1751","question":"Before a debate, a teacher tells nervous Class 9 students: ‘First your heart pounds and your hands shake; the feeling of fear is simply your awareness of those bodily changes, so steady your breathing and the fear will ease.’ Her explanation follows which theory of emotion?","options":["The Cannon–Bard theory","The James–Lange theory","The Schachter–Singer two-factor theory","Lazarus’s cognitive appraisal theory"],"answer":1,"explanation":"James–Lange holds that the felt emotion is the perception of bodily changes, so changing the body should change the feeling. Cannon–Bard makes arousal and feeling simultaneous and independent, and the two-factor theory adds a cognitive label for the arousal.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"वाद-विवाद से पहले एक शिक्षिका घबराए हुए कक्षा 9 के छात्रों से कहती है: ‘पहले तुम्हारा दिल धड़कता है और हाथ काँपते हैं; भय की अनुभूति बस उन शारीरिक परिवर्तनों की तुम्हारी जागरूकता है, इसलिए साँसें स्थिर करो और भय कम हो जाएगा।’ उसकी व्याख्या संवेग के किस सिद्धांत का अनुसरण करती है?","optionsHi":["कैनन–बार्ड सिद्धांत","जेम्स–लैंग सिद्धांत","शैक्टर–सिंगर द्वि-कारक सिद्धांत","लेज़ारस का संज्ञानात्मक मूल्यांकन सिद्धांत"],"explanationHi":"जेम्स–लैंग मानता है कि अनुभव किया गया संवेग शारीरिक परिवर्तनों का प्रत्यक्षण है, इसलिए शरीर बदलने से अनुभूति बदलनी चाहिए। कैनन–बार्ड उत्तेजना और अनुभूति को एक साथ और स्वतंत्र मानता है, और द्वि-कारक सिद्धांत उत्तेजना पर एक संज्ञानात्मक नामकरण जोड़ता है।"},
  {"id":"cdp-child-development-1752","question":"Two Class 10 students sprint up three flights of stairs and arrive breathless at the exam hall. Asha joins classmates nervously discussing ‘impossible’ questions and feels her racing heart as panic; Bina joins friends joking about the exam and feels the same racing heart as eager excitement. Which theory best accounts for the two different emotions?","options":["Cannon–Bard theory: the thalamus sends arousal and feeling to body and cortex at once","James–Lange theory: each emotion has its own distinct pattern of bodily changes","Schachter–Singer two-factor theory: the same arousal is labelled using cues from the situation","Facial feedback hypothesis: the expressions the girls happen to make produce their feelings"],"answer":2,"explanation":"The same unexplained arousal took different emotional labels from the social context, which is the heart of the two-factor theory; James–Lange would need different bodily patterns for panic and excitement.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 10 की दो छात्राएँ तीन मंज़िल सीढ़ियाँ दौड़कर चढ़ती हैं और हाँफती हुई परीक्षा-कक्ष पहुँचती हैं। आशा उन सहपाठियों के साथ जुड़ती है जो घबराहट से ‘असंभव’ प्रश्नों की चर्चा कर रहे हैं और अपने तेज़ धड़कते हृदय को घबराहट के रूप में महसूस करती है; बीना उन मित्रों के साथ जुड़ती है जो परीक्षा पर चुटकुले सुना रहे हैं और उसी तेज़ धड़कन को उत्साहपूर्ण उमंग के रूप में महसूस करती है। दो भिन्न संवेगों की सबसे अच्छी व्याख्या कौन-सा सिद्धांत करता है?","optionsHi":["कैनन–बार्ड सिद्धांत: थैलेमस उत्तेजना और अनुभूति को एक साथ शरीर और प्रांतस्था को भेजता है","जेम्स–लैंग सिद्धांत: प्रत्येक संवेग के शारीरिक परिवर्तनों का अपना विशिष्ट प्रतिरूप होता है","शैक्टर–सिंगर द्वि-कारक सिद्धांत: उसी उत्तेजना को परिस्थिति के संकेतों का उपयोग करके नाम दिया जाता है","चेहरे की प्रतिपुष्टि परिकल्पना: लड़कियाँ जो भाव-भंगिमाएँ संयोगवश बनाती हैं वे उनकी अनुभूतियाँ उत्पन्न करती हैं"],"explanationHi":"उसी अव्याख्यायित उत्तेजना को सामाजिक संदर्भ से भिन्न संवेगात्मक नाम मिले, जो द्वि-कारक सिद्धांत का मर्म है; जेम्स–लैंग को घबराहट और उत्साह के लिए अलग शारीरिक प्रतिरूप चाहिए होते।"},
  {"id":"cdp-child-development-1753","question":"Which pair of objections to the James–Lange theory led Walter Cannon, with Philip Bard, to propose a different account of emotion?","options":["Facial muscles, not the viscera, carry the signals that the brain reads as fear, anger or joy","Emotions depend on how arousal is labelled, and the labels are learnt mainly from the people who are nearby at the time","Feelings arise only after a person judges whether an event threatens them and whether they can cope","Very different emotions share similar bodily arousal, and visceral changes are too slow to be the source of feelings"],"answer":3,"explanation":"Cannon argued that the same visceral arousal accompanies fear, anger and even excitement, and that the viscera respond too slowly to produce a sudden feeling; so he proposed that arousal and feeling arise together. The other options describe two-factor, appraisal and facial-feedback ideas.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"जेम्स–लैंग सिद्धांत पर आपत्तियों का कौन-सा युग्म वाल्टर कैनन को, फ़िलिप बार्ड के साथ, संवेग का भिन्न विवरण प्रस्तावित करने की ओर ले गया?","optionsHi":["भय, क्रोध या आनंद के रूप में मस्तिष्क जिन संकेतों को पढ़ता है उन्हें अंतरंग अंग नहीं, चेहरे की पेशियाँ वहन करती हैं","संवेग इस पर निर्भर करते हैं कि उत्तेजना को कैसे नाम दिया जाता है, और ये नाम मुख्यतः उस समय पास के लोगों से सीखे जाते हैं","अनुभूतियाँ तभी उत्पन्न होती हैं जब व्यक्ति यह निर्णय करता है कि घटना उसके लिए खतरा है या नहीं और वह सामना कर सकता है या नहीं","बहुत भिन्न संवेग समान शारीरिक उत्तेजना साझा करते हैं, और अंतरंग परिवर्तन अनुभूतियों का स्रोत होने के लिए बहुत धीमे हैं"],"explanationHi":"कैनन ने तर्क दिया कि वही अंतरंग उत्तेजना भय, क्रोध और उत्साह तक के साथ आती है, और अंतरंग अंग अचानक अनुभूति उत्पन्न करने के लिए बहुत धीमे प्रतिक्रिया करते हैं; इसलिए उन्होंने प्रस्तावित किया कि उत्तेजना और अनुभूति साथ-साथ उत्पन्न होती हैं। अन्य विकल्प द्वि-कारक, मूल्यांकन और चेहरे की प्रतिपुष्टि के विचार हैं।"},
  {"id":"cdp-child-development-1754","question":"Before her board practical, Nisha thinks, ‘This practical carries 30 marks, so it really matters to me,’ and then, ‘But I have rehearsed every experiment and the lab assistant will help if equipment fails.’ In Richard Lazarus’s theory, her second thought is:","options":["Secondary appraisal, an evaluation of her resources and options for coping","Primary appraisal, a judgement of whether the event matters to her well-being","Reappraisal, a later revision of her first judgement after the practical is over","Cognitive labelling, naming her bodily arousal from cues given by people around her"],"answer":0,"explanation":"Primary appraisal asks ‘Does this matter to me?’ and secondary appraisal asks ‘What can I do about it?’; weighing rehearsal and available help is secondary appraisal. Reappraisal needs new information after the event, and labelling arousal belongs to the two-factor theory.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"बोर्ड प्रायोगिक परीक्षा से पहले निशा सोचती है, ‘इस प्रयोग के 30 अंक हैं, इसलिए यह मेरे लिए सचमुच मायने रखता है,’ और फिर, ‘पर मैंने हर प्रयोग का अभ्यास किया है और यदि उपकरण विफल हुए तो प्रयोगशाला सहायक मदद करेगा।’ रिचर्ड लेज़ारस के सिद्धांत में, उसका दूसरा विचार क्या है?","optionsHi":["द्वितीयक मूल्यांकन, सामना करने के लिए उसके संसाधनों और विकल्पों का आकलन","प्राथमिक मूल्यांकन, इस बात का निर्णय कि घटना उसके कल्याण के लिए मायने रखती है या नहीं","पुनर्मूल्यांकन, प्रयोग समाप्त होने के बाद उसके पहले निर्णय का बाद में संशोधन","संज्ञानात्मक नामकरण, आसपास के लोगों के संकेतों से अपनी शारीरिक उत्तेजना को नाम देना"],"explanationHi":"प्राथमिक मूल्यांकन पूछता है ‘क्या यह मेरे लिए मायने रखता है?’ और द्वितीयक मूल्यांकन पूछता है ‘इसके बारे में मैं क्या कर सकता हूँ?’; अभ्यास और उपलब्ध सहायता को तौलना द्वितीयक मूल्यांकन है। पुनर्मूल्यांकन के लिए घटना के बाद नई जानकारी चाहिए, और उत्तेजना का नामकरण द्वि-कारक सिद्धांत से संबंधित है।"},
  {"id":"cdp-child-development-1755","question":"Before presenting a project, Arjun tells himself, ‘This is a chance to show what I found, not a test of my worth,’ while Kabir keeps a straight face and hides his nervousness from everyone. Research on emotion regulation (James Gross) suggests that, compared with Kabir’s strategy, Arjun’s is more likely to:","options":["Raise his arousal, because thinking about the situation keeps the emotion active for longer","Lower his visible signs of nervousness while leaving his inner feeling and arousal unchanged","Work only after the talk, since reappraisal acts once the emotion has fully run its course","Lower the nervousness he actually feels without taxing his memory of the presentation"],"answer":3,"explanation":"Reappraisal changes the meaning of a situation early and so reduces the felt emotion; expressive suppression (Kabir) hides the expression but leaves arousal high and tends to impair memory for the event. Option two describes suppression, not reappraisal.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"परियोजना प्रस्तुत करने से पहले अर्जुन स्वयं से कहता है, ‘यह मेरी खोज दिखाने का अवसर है, मेरे मूल्य की परीक्षा नहीं,’ जबकि कबीर सपाट चेहरा रखता है और अपनी घबराहट सबसे छिपाता है। संवेग-नियमन पर शोध (जेम्स ग्रॉस) सुझाता है कि कबीर की रणनीति की तुलना में अर्जुन की रणनीति के अधिक संभावित परिणाम क्या हैं?","optionsHi":["उसकी उत्तेजना बढ़ाएगी, क्योंकि स्थिति के बारे में सोचना संवेग को अधिक समय तक सक्रिय रखता है","उसकी घबराहट के दृश्य संकेत घटाएगी जबकि उसकी आंतरिक अनुभूति और उत्तेजना अपरिवर्तित रहेगी","केवल वार्ता के बाद काम करेगी, क्योंकि पुनर्मूल्यांकन तब कार्य करता है जब संवेग पूरी तरह चल चुका हो","उसकी वास्तव में महसूस की जाने वाली घबराहट घटाएगी, प्रस्तुति की उसकी स्मृति पर बोझ डाले बिना"],"explanationHi":"पुनर्मूल्यांकन स्थिति का अर्थ शीघ्र बदलता है और इसलिए अनुभव किए गए संवेग को घटाता है; अभिव्यक्तिपरक दमन (कबीर) अभिव्यक्ति छिपाता है पर उत्तेजना ऊँची रखता है और घटना की स्मृति बिगाड़ने की प्रवृत्ति रखता है। दूसरा विकल्प दमन का वर्णन है, पुनर्मूल्यांकन का नहीं।"},
  {"id":"cdp-child-development-1756","question":"Seven-year-old Tara opens a birthday gift of socks she does not want, smiles and says, ‘Thank you, Aunty, I love it.’ Her behaviour shows that she has learnt:","options":["Social referencing, reading other people’s faces to judge an unfamiliar event","Display rules, the cultural norms about which emotions to show and when","Reaction formation, unconsciously turning a feeling into its opposite","Emotional contagion, automatically taking on the mood of those nearby"],"answer":1,"explanation":"She feels disappointment but deliberately shows pleasure because a social norm asks for it, which is a display rule. Reaction formation is an unconscious defence, not a deliberate, socially guided mask.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"सात वर्ष की तारा जन्मदिन का एक उपहार खोलती है जिसमें मोज़े हैं जो उसे नहीं चाहिए, मुस्कुराती है और कहती है, ‘धन्यवाद आंटी, मुझे बहुत पसंद आया।’ उसका व्यवहार दर्शाता है कि उसने क्या सीखा है?","optionsHi":["सामाजिक संदर्भण, किसी अपरिचित घटना का निर्णय करने के लिए दूसरों के चेहरे पढ़ना","प्रदर्शन नियम, कि कौन-से संवेग कब दिखाने हैं इस बारे में सांस्कृतिक मानदंड","प्रतिक्रिया-निर्माण, अचेतन रूप से भावना को उसके विपरीत में बदलना","संवेगात्मक संक्रमण, आसपास के लोगों के मनोभाव को स्वतः अपना लेना"],"explanationHi":"वह निराशा महसूस करती है पर जानबूझकर प्रसन्नता दिखाती है क्योंकि सामाजिक मानदंड यही माँगता है, जो प्रदर्शन नियम है। प्रतिक्रिया-निर्माण एक अचेतन रक्षा है, जानबूझकर, सामाजिक रूप से निर्देशित मुखौटा नहीं।"},
  {"id":"cdp-child-development-1757","question":"On her first day in Class 1, Mehak sees a large, noisy robot toy in the activity corner. She stops, looks at her teacher’s face, and moves towards the toy only after the teacher smiles and nods. Which developmental process is she using?","options":["Joint attention","Secure-base exploration","Social referencing","Observational learning"],"answer":2,"explanation":"Social referencing is using another person’s emotional expression to decide how to respond to an ambiguous situation. Secure-base exploration is exploring with the attachment figure nearby and returning to her; joint attention is simply sharing focus on the same object.","difficulty":"hard","source":"CTET Paper 1 · NVS PRT","questionHi":"कक्षा 1 के पहले दिन, मेहक गतिविधि-कोने में एक बड़ा, शोर करने वाला रोबोट खिलौना देखती है। वह रुकती है, अपनी शिक्षिका के चेहरे को देखती है, और शिक्षिका के मुस्कुराने और सिर हिलाने के बाद ही खिलौने की ओर बढ़ती है। वह किस विकासात्मक प्रक्रिया का उपयोग कर रही है?","optionsHi":["संयुक्त ध्यान","सुरक्षित आधार से खोज","सामाजिक संदर्भण","अवलोकनात्मक अधिगम"],"explanationHi":"सामाजिक संदर्भण किसी अस्पष्ट स्थिति में कैसे प्रतिक्रिया करनी है, यह तय करने के लिए दूसरे व्यक्ति की संवेगात्मक अभिव्यक्ति का उपयोग करना है। सुरक्षित आधार से खोज संबद्धता-पात्र के पास रहकर खोज करना और उसके पास लौटना है; संयुक्त ध्यान बस एक ही वस्तु पर ध्यान साझा करना है।"},
  {"id":"cdp-child-development-1758","question":"According to Katharine Bridges’ classic observations of infants, a newborn’s emotional life begins with:","options":["General excitement, which later branches into distress and then delight","Three innate emotions, fear, rage and love, all fully present at the moment of birth","Distress alone, with pleasure appearing only after the first year","Pleasure and pain as two separate emotions from the very first day"],"answer":0,"explanation":"Bridges described emotions as differentiating out of an undifferentiated excitement, first into distress and then delight, and later into finer emotions. Fear, rage and love as innate emotions was J. B. Watson’s view.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कैथरीन ब्रिजेस के शिशुओं के शास्त्रीय अवलोकनों के अनुसार, नवजात का संवेगात्मक जीवन किससे शुरू होता है?","optionsHi":["सामान्य उत्तेजना, जो बाद में व्यथा और फिर आनंद में शाखित होती है","तीन जन्मजात संवेग, भय, क्रोध और प्रेम, जन्म के क्षण पूरी तरह उपस्थित","केवल व्यथा, आनंद पहले वर्ष के बाद ही प्रकट होता है","पहले ही दिन से सुख और पीड़ा दो पृथक संवेगों के रूप में"],"explanationHi":"ब्रिजेस ने संवेगों को अविभेदित उत्तेजना से विभेदित होते बताया, पहले व्यथा और फिर आनंद में, और बाद में सूक्ष्म संवेगों में। भय, क्रोध और प्रेम को जन्मजात संवेग मानना जे. बी. वाटसन का मत था।"},
  {"id":"cdp-child-development-1759","question":"Joy, anger and fear are seen in the first months of life, but pride, shame and embarrassment appear only from about the second year. The best explanation is that these later emotions require:","options":["Fluent language, since a child cannot feel an emotion before she can name it","Self-awareness and some sense of standards against which the self is judged","Concrete operational thought, which Piaget placed at about seven years","Direct teaching of manners, without which such feelings never arise"],"answer":1,"explanation":"Self-conscious emotions depend on recognising oneself (seen around 18 months in the mirror test) and evaluating one’s acts against rules. They appear well before seven and before language is fluent, so the other options misplace the cause.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"जीवन के पहले महीनों में आनंद, क्रोध और भय दिखाई देते हैं, परंतु गर्व, लज्जा और संकोच लगभग दूसरे वर्ष से ही प्रकट होते हैं। सबसे अच्छी व्याख्या यह है कि इन बाद के संवेगों के लिए चाहिए:","optionsHi":["धाराप्रवाह भाषा, क्योंकि बच्चा किसी संवेग को नाम दे सकने से पहले उसे महसूस नहीं कर सकता","आत्म-जागरूकता और मानकों की कुछ समझ जिनके विरुद्ध स्वयं को आँका जाए","मूर्त संक्रियात्मक चिंतन, जिसे पियाजे ने लगभग सात वर्ष की आयु पर रखा","शिष्टाचार की प्रत्यक्ष शिक्षा, जिसके बिना ऐसी अनुभूतियाँ कभी उत्पन्न नहीं होतीं"],"explanationHi":"आत्म-सचेत संवेग स्वयं को पहचानने (लगभग 18 माह में दर्पण-परीक्षण में दिखाई देता है) और अपने कार्यों को नियमों के विरुद्ध आँकने पर निर्भर करते हैं। वे सात वर्ष से बहुत पहले और भाषा के धाराप्रवाह होने से पहले प्रकट होते हैं, इसलिए अन्य विकल्प कारण को गलत स्थान देते हैं।"},
  {"id":"cdp-child-development-1760","question":"Arjun, in Class 3, tears Rani’s storybook during a quarrel. Which teacher response is most likely to produce constructive guilt rather than shame?","options":["‘Don’t worry, Arjun, it is only a book; I will get Rani a new one myself.’","‘I am disappointed in you, Arjun; you are usually such a good and kind boy.’","‘Rani is upset because her book is torn. What could you do to help put it right?’","‘Go and sit quietly in the corner for ten minutes and think about what you have done.’"],"answer":2,"explanation":"Guilt that leads to repair arises when attention is on the act and its effect on another person; comments on the child’s whole self push towards shame, while rescuing or isolating him offers no path to making amends.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 का अर्जुन झगड़े के दौरान रानी की कहानी की पुस्तक फाड़ देता है। शिक्षक की कौन-सी प्रतिक्रिया लज्जा के बजाय रचनात्मक अपराध-बोध उत्पन्न करने की सबसे अधिक संभावना रखती है?","optionsHi":["‘चिंता मत करो अर्जुन, यह तो बस एक किताब है; मैं स्वयं रानी को नई ला दूँगी।’","‘मैं तुमसे निराश हूँ अर्जुन; तुम तो आमतौर पर इतने अच्छे और दयालु लड़के हो।’","‘रानी परेशान है क्योंकि उसकी किताब फट गई है। इसे ठीक करने के लिए तुम क्या कर सकते हो?’","‘जाओ और दस मिनट कोने में चुपचाप बैठो और सोचो कि तुमने क्या किया है।’"],"explanationHi":"सुधार की ओर ले जाने वाला अपराध-बोध तब उत्पन्न होता है जब ध्यान कृत्य और दूसरे व्यक्ति पर उसके प्रभाव पर हो; बच्चे के पूरे स्व पर टिप्पणी लज्जा की ओर धकेलती है, जबकि उसे बचाना या अलग करना क्षतिपूर्ति का कोई मार्ग नहीं देता।"},
  {"id":"cdp-child-development-1761","question":"After losing a heated inter-house match, Class 7 boys fight far more often when toy guns and wrestling posters are around the hostel common room than when they are not. Which account explains this best?","options":["Aggression is an instinctive drive that builds up and must be drained through vigorous games","Frustration always leads to aggression, and every act of aggression is caused by some frustration","Aggression is learnt only by watching models who are rewarded, so frustration plays no part in it","Frustration creates anger, a readiness to aggress, and aggressive cues nearby make an attack more likely"],"answer":3,"explanation":"Berkowitz revised the frustration–aggression hypothesis: frustration produces anger, and cues associated with aggression raise the chance that it is acted on. The second option is the original strong form of Dollard’s hypothesis, which this revision rejected.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक गरमागरम अंतर-सदन मैच हारने के बाद, कक्षा 7 के लड़के तब कहीं अधिक झगड़ते हैं जब छात्रावास के सामान्य कक्ष में खिलौना बंदूकें और कुश्ती के पोस्टर होते हैं, बनिस्बत जब वे नहीं होते। कौन-सा विवरण इसे सबसे अच्छी तरह समझाता है?","optionsHi":["आक्रामकता एक सहज प्रेरणा है जो संचित होती है और जोरदार खेलों से निकाली जानी चाहिए","कुंठा सदैव आक्रामकता की ओर ले जाती है, और आक्रामकता का हर कृत्य किसी कुंठा से उत्पन्न होता है","आक्रामकता केवल उन आदर्शों को देखकर सीखी जाती है जिन्हें पुरस्कृत किया जाता है, इसलिए कुंठा की इसमें कोई भूमिका नहीं","कुंठा क्रोध, आक्रामक होने की तत्परता, उत्पन्न करती है, और आसपास के आक्रामक संकेत हमले की संभावना बढ़ाते हैं"],"explanationHi":"बर्कोविट्ज़ ने कुंठा–आक्रामकता परिकल्पना को संशोधित किया: कुंठा क्रोध उत्पन्न करती है, और आक्रामकता से जुड़े संकेत उस पर अमल की संभावना बढ़ाते हैं। दूसरा विकल्प डॉलर्ड की परिकल्पना का मूल प्रबल रूप है, जिसे इस संशोधन ने अस्वीकार किया।"},
  {"id":"cdp-child-development-1762","question":"To help angry children ‘get the anger out of their system’, a teacher lets them punch a pillow while thinking about the classmate who upset them. What does research on venting suggest?","options":["Venting while dwelling on the provocation tends to keep anger high or raise it further","Venting drains anger as the catharsis idea predicts, if done soon after the provocation","Venting helps boys release anger but not girls, whose anger is mostly expressed in words","Venting helps only children under eight, whose anger is mostly physical rather than verbal"],"answer":0,"explanation":"Studies of venting (for example Bushman’s pillow-punching experiments) found that hitting while ruminating on the provoker left people angrier and more aggressive; calming down, distraction and reappraisal work better than catharsis.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"क्रोधित बच्चों को ‘क्रोध अपने तंत्र से बाहर निकालने’ में मदद करने के लिए एक शिक्षिका उन्हें तकिये पर मुक्के मारने देती है जबकि वे उस सहपाठी के बारे में सोचते हैं जिसने उन्हें परेशान किया। निकास (वेंटिंग) पर शोध क्या सुझाता है?","optionsHi":["उकसावे पर मनन करते हुए वेंटिंग करने से क्रोध ऊँचा बना रहता है या और बढ़ जाता है","वेंटिंग क्रोध को घटाती है जैसा विरेचन विचार पूर्वानुमान करता है, यदि उकसावे के तुरंत बाद की जाए","वेंटिंग लड़कों को क्रोध निकालने में मदद करती है पर लड़कियों को नहीं, जिनका क्रोध अधिकतर शब्दों में व्यक्त होता है","वेंटिंग केवल आठ वर्ष से कम के बच्चों की मदद करती है, जिनका क्रोध अधिकतर मौखिक नहीं बल्कि शारीरिक होता है"],"explanationHi":"वेंटिंग के अध्ययनों (उदाहरण के लिए बुशमैन के तकिये पर मुक्के मारने के प्रयोग) ने पाया कि उकसाने वाले पर मनन करते हुए मारने से लोग और क्रुद्ध और आक्रामक हो गए; शांत होना, ध्यान बँटाना और पुनर्मूल्यांकन विरेचन से बेहतर काम करते हैं।"},
  {"id":"cdp-child-development-1763","question":"Match each situation with Kurt Lewin’s type of conflict. P. Choosing between two equally exciting summer camps. Q. Having either to own up to the teacher now or to be caught later. R. Wanting to be class monitor for the status but dreading the extra duties of that same post. S. Choosing between science (good career but heavy load) and arts (enjoyable but parents disapprove). 1. Avoidance–avoidance 2. Approach–approach 3. Double approach–avoidance 4. Approach–avoidance","options":["P-2, Q-4, R-1, S-3","P-2, Q-1, R-4, S-3","P-3, Q-1, R-4, S-2","P-2, Q-1, R-3, S-4"],"answer":1,"explanation":"Two attractive camps is approach–approach; two unpleasant outcomes is avoidance–avoidance; one goal with both pull and push is approach–avoidance; two alternatives that each have good and bad sides is double approach–avoidance.","difficulty":"very-hard","source":"DSSSB TGT · KVS TGT","questionHi":"प्रत्येक स्थिति का मिलान कर्ट लेविन के द्वंद्व के प्रकार से कीजिए। P. दो समान रूप से रोमांचक ग्रीष्म शिविरों में से चुनना। Q. या तो अभी शिक्षक के सामने स्वीकार करना या बाद में पकड़े जाना। R. प्रतिष्ठा के लिए कक्षा-प्रतिनिधि बनना चाहना पर उसी पद के अतिरिक्त कर्तव्यों से डरना। S. विज्ञान (अच्छा करियर पर भारी बोझ) और कला (आनंददायक पर माता-पिता अस्वीकार करते हैं) में से चुनना। 1. परिहार–परिहार 2. उपागम–उपागम 3. द्वि-उपागम–परिहार 4. उपागम–परिहार","optionsHi":["P-2, Q-4, R-1, S-3","P-2, Q-1, R-4, S-3","P-3, Q-1, R-4, S-2","P-2, Q-1, R-3, S-4"],"explanationHi":"दो आकर्षक शिविर उपागम–उपागम हैं; दो अप्रिय परिणाम परिहार–परिहार हैं; खिंचाव और विकर्षण दोनों वाला एक लक्ष्य उपागम–परिहार है; दो विकल्प जिनमें प्रत्येक के अच्छे और बुरे पक्ष हैं, द्वि-उपागम–परिहार है।"},
  {"id":"cdp-child-development-1764","question":"Weeks ago, Rohit eagerly volunteered to speak at assembly. As the day approaches he wants to withdraw, though he still values the chance. According to Neal Miller’s analysis of approach–avoidance conflict, this happens because:","options":["Both tendencies stay fixed, but tiredness makes the unpleasant side of the goal feel bigger","The approach tendency rises more steeply than the avoidance tendency as the goal gets nearer","The avoidance tendency rises more steeply than the approach tendency as the goal gets nearer","Approach and avoidance cancel out at a distance, so he feels nothing until the final day"],"answer":2,"explanation":"Miller showed that both tendencies grow as a goal nears, but the avoidance gradient is steeper; far away, approach dominates, close up, avoidance overtakes it, which produces late hesitation and vacillation.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"सप्ताहों पहले रोहित ने उत्साह से सभा में बोलने के लिए स्वेच्छा से नाम दिया था। जैसे-जैसे दिन निकट आता है वह पीछे हटना चाहता है, यद्यपि वह अब भी अवसर को महत्व देता है। नील मिलर के उपागम–परिहार द्वंद्व के विश्लेषण के अनुसार, ऐसा इसलिए होता है क्योंकि:","optionsHi":["दोनों प्रवृत्तियाँ स्थिर रहती हैं, पर थकान लक्ष्य के अप्रिय पक्ष को बड़ा महसूस कराती है","जैसे-जैसे लक्ष्य निकट आता है, उपागम प्रवृत्ति परिहार प्रवृत्ति से अधिक तीव्रता से बढ़ती है","जैसे-जैसे लक्ष्य निकट आता है, परिहार प्रवृत्ति उपागम प्रवृत्ति से अधिक तीव्रता से बढ़ती है","उपागम और परिहार दूरी पर एक-दूसरे को निरस्त कर देते हैं, इसलिए अंतिम दिन तक वह कुछ महसूस नहीं करता"],"explanationHi":"मिलर ने दिखाया कि लक्ष्य के निकट आने पर दोनों प्रवृत्तियाँ बढ़ती हैं, परंतु परिहार प्रवणता अधिक तीव्र है; दूर रहने पर उपागम प्रबल होता है, निकट आने पर परिहार उसे पीछे छोड़ देता है, जिससे देर से हिचकिचाहट और दुविधा उत्पन्न होती है।"},
  {"id":"cdp-child-development-1765","question":"Two-year-old Gauri sees her teacher looking sad and brings her own favourite soft toy to comfort her. In Martin Hoffman’s account of empathy development, this shows:","options":["Mature perspective-taking: she infers exactly what the teacher needs","Global empathy: she cannot yet tell whether the distress she feels is hers or another’s","Empathy for another’s life condition, beyond the immediate situation","Egocentric empathy: she feels for another but offers what would comfort herself"],"answer":3,"explanation":"In Hoffman’s sequence the toddler knows the distress is someone else’s but still assumes others want what she wants, so she offers her own comfort object. Global empathy is the infant’s confusion of self and other, and concern for life conditions comes in late childhood.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"दो वर्ष की गौरी अपनी शिक्षिका को उदास देखती है और उसे सांत्वना देने के लिए अपना सबसे प्रिय मुलायम खिलौना ले आती है। मार्टिन हॉफ़मैन के समानुभूति विकास के विवरण में, यह क्या दर्शाता है?","optionsHi":["परिपक्व परिप्रेक्ष्य-ग्रहण: वह ठीक-ठीक अनुमान लगाती है कि शिक्षिका को क्या चाहिए","वैश्विक समानुभूति: वह अभी यह नहीं बता सकती कि जो व्यथा वह महसूस करती है वह उसकी है या दूसरे की","दूसरे की जीवन-स्थिति के लिए समानुभूति, तात्कालिक स्थिति से परे","अहंकेंद्रित समानुभूति: वह दूसरे के लिए महसूस करती है पर वही प्रस्तुत करती है जो स्वयं उसे सांत्वना देगा"],"explanationHi":"हॉफ़मैन के क्रम में नन्हा बच्चा जानता है कि व्यथा किसी और की है पर फिर भी मान लेता है कि दूसरे वही चाहते हैं जो वह चाहता है, इसलिए वह अपनी सांत्वना-वस्तु प्रस्तुत करता है। वैश्विक समानुभूति शिशु का स्व और अन्य का भ्रम है, और जीवन-स्थितियों के प्रति चिंता उत्तर बाल्यावस्था में आती है।"},
  {"id":"cdp-child-development-1766","question":"Test anxiety is often split into a worry component and an emotionality component. Which is more consistently linked with lower test scores?","options":["The worry component: self-doubting thoughts that occupy working memory during the test","The emotionality component: sweating, a racing heart and ‘butterflies’ during the test","Both equally, since anxious thoughts and bodily signs always rise and fall together","The avoidance component: skipping revision so that failure can be blamed on lack of effort"],"answer":0,"explanation":"Research since Liebert and Morris finds that the cognitive worry component predicts poorer performance more strongly than bodily emotionality, because worry competes for working-memory capacity. The ‘avoidance component’ describes self-handicapping, not a standard part of test anxiety.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"परीक्षा-चिंता को प्रायः चिंता-घटक और संवेगात्मकता-घटक में बाँटा जाता है। कौन-सा निम्न परीक्षण-अंकों से अधिक संगत रूप से जुड़ा है?","optionsHi":["चिंता-घटक: आत्म-संदेह भरे विचार जो परीक्षण के दौरान कार्यकारी स्मृति को घेर लेते हैं","संवेगात्मकता-घटक: परीक्षण के दौरान पसीना, तेज़ धड़कन और ‘घबराहट’","दोनों समान रूप से, क्योंकि चिंतित विचार और शारीरिक संकेत सदैव साथ-साथ बढ़ते-घटते हैं","परिहार-घटक: पुनरावृत्ति छोड़ना ताकि असफलता का दोष प्रयास की कमी पर डाला जा सके"],"explanationHi":"लीबर्ट और मॉरिस के बाद के शोध में पाया गया कि संज्ञानात्मक चिंता-घटक शारीरिक संवेगात्मकता की तुलना में खराब प्रदर्शन का अधिक सशक्त पूर्वानुमान करता है, क्योंकि चिंता कार्यकारी स्मृति की क्षमता से प्रतिस्पर्धा करती है। ‘परिहार-घटक’ स्व-अवरोधन का वर्णन करता है, परीक्षा-चिंता का कोई मानक भाग नहीं।"},
  {"id":"cdp-child-development-1767","question":"Years later, students vividly ‘remember’ where they were when they heard about a dramatic national event, and they are very confident about it. Research on such flashbulb memories shows that they are:","options":["Photographic records that stay accurate in every detail because strong emotion fixes them","Vivid and confidently held, yet often no more accurate than ordinary memories of the same age","Accurate for the central event but never for personal details such as where one was","Lost faster than ordinary memories, since strong emotion blocks storage in long-term memory"],"answer":1,"explanation":"Studies that tested people soon after events and again years later found flashbulb memories change and contain errors much like everyday memories; what stays high is vividness and confidence, not accuracy.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"वर्षों बाद, छात्र एक नाटकीय राष्ट्रीय घटना के बारे में सुनते समय वे कहाँ थे यह स्पष्ट रूप से ‘याद’ करते हैं, और इसके बारे में बहुत आश्वस्त होते हैं। ऐसी फ़्लैशबल्ब स्मृतियों पर शोध दर्शाता है कि वे हैं:","optionsHi":["फ़ोटोग्राफ़ी जैसे अभिलेख जो हर विवरण में सटीक रहते हैं क्योंकि प्रबल संवेग उन्हें स्थिर कर देता है","स्पष्ट और आत्मविश्वास से धारण की गई, फिर भी प्रायः उसी आयु की सामान्य स्मृतियों से अधिक सटीक नहीं","केंद्रीय घटना के लिए सटीक पर व्यक्तिगत विवरणों, जैसे व्यक्ति कहाँ था, के लिए कभी नहीं","सामान्य स्मृतियों से अधिक तेज़ी से खोने वाली, क्योंकि प्रबल संवेग दीर्घकालिक स्मृति में संचयन को अवरुद्ध करता है"],"explanationHi":"जिन अध्ययनों ने घटनाओं के शीघ्र बाद और फिर वर्षों बाद लोगों का परीक्षण किया, उनमें पाया गया कि फ़्लैशबल्ब स्मृतियाँ बदलती हैं और रोज़मर्रा की स्मृतियों की तरह त्रुटियाँ रखती हैं; जो ऊँचा रहता है वह स्पष्टता और आत्मविश्वास है, सटीकता नहीं।"},
  {"id":"cdp-child-development-1768","question":"A toddler calms when her caregiver rocks her; by school age she distracts herself or talks herself through a scary injection. This change is best described as a shift from:","options":["Expressive suppression in infancy to reappraisal, which is present from birth","Self-regulation in infancy to dependence on peers for comfort in childhood","Co-regulation of emotion by adults to increasingly independent self-regulation","Social referencing in infancy to display rules as the child’s language grows"],"answer":2,"explanation":"Early emotion regulation is largely external, done by caregivers; with language, attention control and experience children take over these strategies themselves. Reappraisal is not present at birth and display rules concern expression, not soothing.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक नन्ही बच्ची तब शांत होती है जब उसकी देखभालकर्ता उसे झुलाती है; विद्यालय की आयु तक वह स्वयं का ध्यान बँटाती है या डरावने इंजेक्शन के दौरान स्वयं को समझाती है। इस परिवर्तन का सबसे अच्छा वर्णन किस बदलाव के रूप में होता है?","optionsHi":["शैशवावस्था में अभिव्यक्तिपरक दमन से पुनर्मूल्यांकन, जो जन्म से उपस्थित है","शैशवावस्था में आत्म-नियमन से बाल्यावस्था में सांत्वना के लिए साथियों पर निर्भरता","वयस्कों द्वारा संवेग के सह-नियमन से बढ़ते स्वतंत्र आत्म-नियमन तक","शैशवावस्था में सामाजिक संदर्भण से बच्चे की भाषा बढ़ने पर प्रदर्शन नियमों तक"],"explanationHi":"प्रारंभिक संवेग-नियमन मुख्यतः बाह्य होता है, जो देखभालकर्ताओं द्वारा किया जाता है; भाषा, ध्यान-नियंत्रण और अनुभव के साथ बच्चे इन रणनीतियों को स्वयं अपना लेते हैं। पुनर्मूल्यांकन जन्म से उपस्थित नहीं है और प्रदर्शन नियम अभिव्यक्ति से संबंधित हैं, शांत करने से नहीं।"},
  {"id":"cdp-child-development-1769","question":"Riya, in Class 2, cries, ‘I hate maths!’ over a sheet of sums. In John Gottman’s terms, which teacher response is emotion coaching?","options":["‘Big girls handle mistakes calmly. Take a deep breath, stop crying and finish the sheet.’","‘It’s okay to feel that way, Riya; you can skip maths for today and do some drawing instead.’","‘Cheer up! Here’s a sticker for trying. Now let’s get back to the sums with a smile.’","‘You’re really frustrated with these sums. Let’s find the step that’s stuck and try it together.’"],"answer":3,"explanation":"Emotion coaching names and accepts the feeling and then helps the child solve the problem. Accepting the feeling without any guidance is Gottman’s laissez-faire style, distracting with a sticker is dismissing, and telling her to stop crying is disapproving.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 की रिया सवालों की शीट देखकर रोते हुए कहती है, ‘मुझे गणित से नफ़रत है!’ जॉन गॉटमैन के शब्दों में, शिक्षक की कौन-सी प्रतिक्रिया संवेग-प्रशिक्षण है?","optionsHi":["‘बड़ी लड़कियाँ गलतियों को शांति से सँभालती हैं। गहरी साँस लो, रोना बंद करो और शीट पूरी करो।’","‘ऐसा महसूस करना ठीक है, रिया; आज तुम गणित छोड़कर कुछ चित्र बना सकती हो।’","‘हिम्मत रखो! प्रयास के लिए यह स्टिकर लो। अब मुस्कुराकर सवालों पर वापस लौटते हैं।’","‘तुम इन सवालों से सचमुच निराश हो। चलो वह चरण खोजें जहाँ अटकी हो और उसे साथ मिलकर आज़माएँ।’"],"explanationHi":"संवेग-प्रशिक्षण भावना को नाम देता और स्वीकारता है और फिर बच्चे को समस्या सुलझाने में मदद करता है। बिना किसी मार्गदर्शन के भावना को स्वीकारना गॉटमैन की ढीली-ढाली शैली है, स्टिकर से ध्यान बँटाना उपेक्षा है, और रोना बंद करने को कहना अस्वीकृति है।"},
  {"id":"cdp-child-development-1770","question":"Which sequence of typical children’s fears, from infancy to adolescence, is most accurate?","options":["Loud noises and strangers → the dark and imaginary creatures → injury and school failure → social rejection and looks","The dark and imaginary creatures → loud noises and strangers → social rejection and looks → injury and school failure","Loud noises and strangers → injury and school failure → the dark and imaginary creatures → social rejection and looks","Social rejection and looks → loud noises and strangers → the dark and imaginary creatures → injury and school failure"],"answer":0,"explanation":"Infant fears centre on sudden stimuli and strangers; pre-schoolers, who mix fantasy and reality, fear the dark and monsters; school-age fears become realistic (injury, failure); adolescents fear social evaluation and appearance.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"शैशवावस्था से किशोरावस्था तक बच्चों के सामान्य भयों का कौन-सा क्रम सबसे सटीक है?","optionsHi":["तेज़ आवाज़ें और अजनबी → अँधेरा और काल्पनिक जीव → चोट और विद्यालय में असफलता → सामाजिक अस्वीकृति और रूप-रंग","अँधेरा और काल्पनिक जीव → तेज़ आवाज़ें और अजनबी → सामाजिक अस्वीकृति और रूप-रंग → चोट और विद्यालय में असफलता","तेज़ आवाज़ें और अजनबी → चोट और विद्यालय में असफलता → अँधेरा और काल्पनिक जीव → सामाजिक अस्वीकृति और रूप-रंग","सामाजिक अस्वीकृति और रूप-रंग → तेज़ आवाज़ें और अजनबी → अँधेरा और काल्पनिक जीव → चोट और विद्यालय में असफलता"],"explanationHi":"शिशुओं के भय अचानक उद्दीपनों और अजनबियों पर केंद्रित होते हैं; पूर्व-विद्यालयी बच्चे, जो कल्पना और वास्तविकता को मिलाते हैं, अँधेरे और राक्षसों से डरते हैं; विद्यालय-आयु के भय यथार्थवादी (चोट, असफलता) हो जाते हैं; किशोर सामाजिक मूल्यांकन और रूप-रंग से डरते हैं।"},
  {"id":"cdp-child-development-1771","question":"Assertion (A): Many five-year-olds insist that a child cannot feel happy and sad at the same time about one event, such as moving to a new house. Reason (R): Young children tend to centre on one salient aspect of a situation at a time.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Research by Susan Harter and others shows understanding of mixed emotions develops gradually in middle childhood; the young child’s difficulty is linked to centration, attending to one feeling at a time.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): अनेक पाँच वर्ष के बच्चे आग्रह करते हैं कि बच्चा एक ही घटना, जैसे नए घर में जाने, पर एक साथ प्रसन्न और उदास महसूस नहीं कर सकता। कारण (R): छोटे बच्चे एक समय में स्थिति के एक ही उभरे हुए पक्ष पर केंद्रित होते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"सूज़न हार्टर और अन्य के शोध से पता चलता है कि मिश्रित संवेगों की समझ मध्य बाल्यावस्था में धीरे-धीरे विकसित होती है; छोटे बच्चे की कठिनाई केंद्रीकरण से जुड़ी है, एक समय में एक अनुभूति पर ध्यान देना।"},
  {"id":"cdp-child-development-1772","question":"A Class 4 teacher uses a ‘feelings chart’ on which children point to and name what they feel before a test. Research on affect labelling suggests this helps mainly because:","options":["It mainly widens vocabulary, which shows up as better marks in language tests","Naming a feeling makes it stronger, so children get it fully out of their system","Children who name a feeling stop experiencing it altogether after a few weeks","Putting a feeling into words tends to dampen its intensity and supports regulation"],"answer":3,"explanation":"Studies of affect labelling find that naming one’s emotion reduces its intensity and the brain’s threat response, so it is a simple regulation tool; it does not ‘discharge’ or abolish the feeling.","difficulty":"hard","source":"CTET Paper 1 · NVS PRT","questionHi":"कक्षा 4 की एक शिक्षिका ‘भावना चार्ट’ का प्रयोग करती है जिस पर बच्चे परीक्षण से पहले इंगित करते और नाम बताते हैं कि वे क्या महसूस करते हैं। संवेग-नामकरण पर शोध सुझाता है कि यह मुख्यतः इसलिए सहायक है क्योंकि:","optionsHi":["यह मुख्यतः शब्दावली बढ़ाता है, जो भाषा परीक्षणों में बेहतर अंकों के रूप में दिखती है","भावना को नाम देने से वह प्रबल हो जाती है, इसलिए बच्चे उसे पूरी तरह निकाल पाते हैं","भावना को नाम देने वाले बच्चे कुछ सप्ताह बाद उसे पूरी तरह अनुभव करना बंद कर देते हैं","भावना को शब्दों में ढालना उसकी तीव्रता को कम करता है और नियमन में सहायता करता है"],"explanationHi":"संवेग-नामकरण के अध्ययनों में पाया गया कि अपने संवेग को नाम देने से उसकी तीव्रता और मस्तिष्क की खतरे की प्रतिक्रिया घटती है, इसलिए यह एक सरल नियमन उपकरण है; यह भावना को ‘निकालता’ या समाप्त नहीं करता।"},
  {"id":"cdp-child-development-1773","question":"Rahul, in Class 2, pushes a classmate aside to get the first turn on the swing, though he is not angry with her and does not want to hurt her. This is best described as:","options":["Hostile (reactive) aggression","Instrumental aggression","Relational aggression","Displaced aggression"],"answer":1,"explanation":"Instrumental aggression uses harm as a means to an object or goal; hostile aggression aims at hurting the person, relational aggression damages relationships, and displaced aggression redirects anger onto a safer target.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 का रोहन झूले पर पहली बारी पाने के लिए एक सहपाठी को धकेलकर एक ओर कर देता है, यद्यपि वह उससे क्रोधित नहीं है और उसे चोट नहीं पहुँचाना चाहता। इसका सबसे अच्छा वर्णन क्या है?","optionsHi":["शत्रुतापूर्ण (प्रतिक्रियात्मक) आक्रामकता","साधनात्मक आक्रामकता","संबंधपरक आक्रामकता","विस्थापित आक्रामकता"],"explanationHi":"साधनात्मक आक्रामकता किसी वस्तु या लक्ष्य के साधन के रूप में हानि का उपयोग करती है; शत्रुतापूर्ण आक्रामकता व्यक्ति को चोट पहुँचाने का लक्ष्य रखती है, संबंधपरक आक्रामकता संबंधों को हानि पहुँचाती है, और विस्थापित आक्रामकता क्रोध को अधिक सुरक्षित लक्ष्य पर मोड़ देती है।"},
  {"id":"cdp-child-development-1774","question":"A school’s anti-bullying rule says only, ‘No hitting, kicking or pushing.’ Which form of aggression, common among upper-primary children, does it leave out?","options":["Hostile aggression, such as kicking a child who teased you, out of anger","Instrumental aggression, such as pushing someone aside in the line to get a turn first","Relational aggression, such as spreading rumours and deliberately excluding a classmate","Reactive aggression, such as hitting back at someone who hit you first"],"answer":2,"explanation":"All the other options involve physical acts the rule already bans; relational aggression harms through relationships and reputation, rises in middle childhood, and needs its own rules and monitoring.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक विद्यालय के धमकाने-विरोधी नियम में केवल इतना कहा गया है, ‘मारना, लात मारना या धकेलना मना है।’ उच्च-प्राथमिक बच्चों में सामान्य आक्रामकता का कौन-सा रूप इसमें छूट जाता है?","optionsHi":["शत्रुतापूर्ण आक्रामकता, जैसे क्रोध में उस बच्चे को लात मारना जिसने आपको चिढ़ाया","साधनात्मक आक्रामकता, जैसे पंक्ति में पहले बारी पाने के लिए किसी को धकेलकर हटाना","संबंधपरक आक्रामकता, जैसे अफ़वाहें फैलाना और किसी सहपाठी को जानबूझकर बाहर रखना","प्रतिक्रियात्मक आक्रामकता, जैसे उस पर पलटकर मारना जिसने पहले आपको मारा"],"explanationHi":"अन्य सभी विकल्पों में शारीरिक कृत्य हैं जिन्हें नियम पहले ही प्रतिबंधित करता है; संबंधपरक आक्रामकता संबंधों और प्रतिष्ठा के माध्यम से हानि पहुँचाती है, मध्य बाल्यावस्था में बढ़ती है, और उसे अपने नियमों तथा निगरानी की आवश्यकता है।"},
  {"id":"cdp-child-development-1775","question":"Before a brainstorming session, a teacher plays a short funny clip to her Class 8. Barbara Fredrickson’s broaden-and-build theory predicts that mild positive emotion will:","options":["Widen the range of thoughts and actions students consider, helping creative solutions","Narrow attention onto the single most important detail, helping careful accuracy","Speed up recall of facts while leaving the variety of ideas students produce unchanged","Help only those students who were already in a good mood before the clip"],"answer":0,"explanation":"Fredrickson proposed that positive emotions broaden the momentary repertoire of thought and action, which supports flexible, creative thinking; it is negative emotions like fear that narrow attention.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"विचार-मंथन सत्र से पहले एक शिक्षिका अपनी कक्षा 8 को एक छोटी हास्य क्लिप दिखाती है। बारबरा फ़्रेडरिक्सन का विस्तार-और-निर्माण सिद्धांत पूर्वानुमान करता है कि हल्का सकारात्मक संवेग:","optionsHi":["छात्रों द्वारा विचारित विचारों और कार्यों के दायरे को चौड़ा करेगा, जो सृजनात्मक समाधानों में सहायक है","ध्यान को सबसे महत्वपूर्ण एकल विवरण पर संकुचित करेगा, जो सावधान सटीकता में सहायक है","तथ्यों के स्मरण को तेज़ करेगा जबकि छात्रों द्वारा उत्पन्न विचारों की विविधता को अपरिवर्तित छोड़ देगा","केवल उन छात्रों की सहायता करेगा जो क्लिप से पहले ही अच्छे मनोभाव में थे"],"explanationHi":"फ़्रेडरिक्सन ने प्रस्तावित किया कि सकारात्मक संवेग चिंतन और कार्य के क्षणिक भंडार को विस्तृत करते हैं, जो लचीले, सृजनात्मक चिंतन में सहायक है; भय जैसे नकारात्मक संवेग ध्यान को संकुचित करते हैं।"},
  {"id":"cdp-child-development-1776","question":"A Class 3 teacher tells children who dislike writing, ‘Finish your four lines of handwriting first, and then you may play carrom.’ Carrom is something they choose often on their own. Which principle is she using?","options":["The Premack principle","Negative reinforcement","The overjustification effect","Shaping by successive approximation"],"answer":0,"explanation":"The Premack principle uses a high-probability (preferred) activity to reinforce a low-probability one. Nothing unpleasant is being removed, so it is not negative reinforcement, and no step-by-step approximations are rewarded.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की शिक्षिका लिखना नापसंद करने वाले बच्चों से कहती है, ‘पहले अपनी लिखावट की चार पंक्तियाँ पूरी करो, फिर तुम कैरम खेल सकते हो।’ कैरम वह है जिसे वे अपने आप प्रायः चुनते हैं। वह किस सिद्धांत का उपयोग कर रही है?","optionsHi":["प्रेमैक सिद्धांत","नकारात्मक पुनर्बलन","अतिऔचित्य प्रभाव","क्रमिक सन्निकटन द्वारा आकार-निर्माण"],"explanationHi":"प्रेमैक सिद्धांत एक उच्च-संभाव्यता (पसंदीदा) गतिविधि का उपयोग निम्न-संभाव्यता गतिविधि को पुनर्बलित करने के लिए करता है। कुछ अप्रिय हटाया नहीं जा रहा, इसलिए यह नकारात्मक पुनर्बलन नहीं है, और चरण-दर-चरण सन्निकटनों को पुरस्कृत नहीं किया जा रहा।"},
  {"id":"cdp-child-development-1777","question":"Match each student’s reason for studying biology with the type of motivation in Deci and Ryan’s self-determination theory. P. ‘So that Papa does not take away my phone.’ Q. ‘I would feel guilty and ashamed if I didn’t.’ R. ‘Biology matters for my aim of becoming a nurse.’ S. ‘I love working out how cells function.’ 1. Identified regulation 2. Intrinsic motivation 3. External regulation 4. Introjected regulation","options":["P-4, Q-3, R-1, S-2","P-3, Q-4, R-1, S-2","P-3, Q-1, R-4, S-2","P-3, Q-4, R-2, S-1"],"answer":1,"explanation":"Studying to avoid a penalty is external regulation; acting to avoid guilt or protect self-worth is introjected; valuing the activity for a personal goal is identified; doing it for its own enjoyment is intrinsic. Introjected regulation is the trap, as it is internal but still pressured.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"जीव-विज्ञान पढ़ने के प्रत्येक छात्र के कारण का मिलान डेसी और रायन के स्व-निर्धारण सिद्धांत में अभिप्रेरणा के प्रकार से कीजिए। P. ‘ताकि पापा मेरा फ़ोन न छीन लें।’ Q. ‘अगर नहीं पढ़ूँगी तो मुझे अपराध-बोध और शर्म महसूस होगी।’ R. ‘नर्स बनने के मेरे लक्ष्य के लिए जीव-विज्ञान मायने रखता है।’ S. ‘मुझे यह जानना अच्छा लगता है कि कोशिकाएँ कैसे कार्य करती हैं।’ 1. पहचानी गई नियमन 2. आंतरिक अभिप्रेरणा 3. बाह्य नियमन 4. अंतःक्षेपित नियमन","optionsHi":["P-4, Q-3, R-1, S-2","P-3, Q-4, R-1, S-2","P-3, Q-1, R-4, S-2","P-3, Q-4, R-2, S-1"],"explanationHi":"दंड से बचने के लिए पढ़ना बाह्य नियमन है; अपराध-बोध से बचने या आत्म-मूल्य की रक्षा के लिए कार्य करना अंतःक्षेपित है; किसी व्यक्तिगत लक्ष्य के लिए गतिविधि को महत्व देना पहचाना गया है; उसे उसके आनंद के लिए करना आंतरिक है। अंतःक्षेपित नियमन जाल है, क्योंकि वह आंतरिक है पर फिर भी दबाव-युक्त है।"},
  {"id":"cdp-child-development-1778","question":"Before a class quiz, Shalini says, ‘My main aim is just not to look stupid in front of everyone.’ In the 2 × 2 achievement-goal framework, her goal is:","options":["Mastery-approach","Performance-approach","Mastery-avoidance","Performance-avoidance"],"answer":3,"explanation":"Her standard is comparison with others (performance) and her focus is on avoiding a negative outcome (avoidance). Performance-approach would be wanting to look better than others; mastery-avoidance is fearing not to understand fully.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा-प्रश्नोत्तरी से पहले शालिनी कहती है, ‘मेरा मुख्य लक्ष्य बस सबके सामने मूर्ख न दिखना है।’ 2 × 2 उपलब्धि-लक्ष्य ढाँचे में, उसका लक्ष्य है:","optionsHi":["निपुणता-उपागम","निष्पादन-उपागम","निपुणता-परिहार","निष्पादन-परिहार"],"explanationHi":"उसका मानक दूसरों से तुलना (निष्पादन) है और उसका ध्यान नकारात्मक परिणाम से बचने (परिहार) पर है। निष्पादन-उपागम दूसरों से बेहतर दिखना चाहना होगा; निपुणता-परिहार पूरी तरह न समझ पाने का भय है।"},
  {"id":"cdp-child-development-1779","question":"Carole Ames grouped classroom features that shape students’ goal orientation under the acronym TARGET. In this framework, the ‘R’ stands for:","options":["Recognition: how and for what students are acknowledged","Rewards: how many prizes are given for top scores","Responsibility: which duties students take on in class","Reinforcement: how quickly correct answers are praised"],"answer":0,"explanation":"TARGET stands for Task, Authority, Recognition, Grouping, Evaluation and Time. A mastery climate recognises effort, progress and improvement privately rather than publicly ranking the best scorers.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"कैरोल एम्स ने उन कक्षा-विशेषताओं को, जो छात्रों के लक्ष्य-अभिविन्यास को आकार देती हैं, संक्षिप्त नाम TARGET के अंतर्गत समूहित किया। इस ढाँचे में ‘R’ का अर्थ है:","optionsHi":["मान्यता (रिकग्निशन): छात्रों को कैसे और किसके लिए स्वीकार किया जाता है","पुरस्कार (रिवॉर्ड्स): शीर्ष अंकों के लिए कितने पुरस्कार दिए जाते हैं","उत्तरदायित्व (रिस्पॉन्सिबिलिटी): छात्र कक्षा में कौन-से कर्तव्य निभाते हैं","पुनर्बलन (रीइनफ़ोर्समेंट): सही उत्तरों की कितनी शीघ्र प्रशंसा की जाती है"],"explanationHi":"TARGET का अर्थ है कार्य (Task), अधिकार (Authority), मान्यता (Recognition), समूहीकरण (Grouping), मूल्यांकन (Evaluation) और समय (Time)। निपुणता वातावरण प्रयास, प्रगति और सुधार को निजी रूप से मान्यता देता है, सर्वश्रेष्ठ अंक पाने वालों को सार्वजनिक रूप से श्रेणीबद्ध नहीं करता।"},
  {"id":"cdp-child-development-1780","question":"After failing maths tests for two years despite real effort, Kiran now stops trying even on easy sums that she could solve, saying, ‘It won’t make any difference.’ Which description and remedy fit best?","options":["Performance-avoidance; tell her that her marks will not be compared with anyone else’s","Learned helplessness; excuse her from maths tests for a while until her confidence returns on its own","Self-handicapping; warn her firmly that holding back effort will only make her marks fall further","Learned helplessness; give her tasks she can succeed at and link each success to her own strategies"],"answer":3,"explanation":"Seligman’s learned helplessness is the belief that outcomes are uncontrollable, so effort stops. The remedy is to restore the link between action and outcome through attainable successes and attributions to effort and strategy; simply removing tests leaves the belief untouched.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"वास्तविक प्रयास के बावजूद दो वर्ष तक गणित परीक्षणों में असफल रहने के बाद, किरण अब उन आसान सवालों पर भी प्रयास करना बंद कर देती है जिन्हें वह हल कर सकती है, कहती है, ‘इससे कोई फ़र्क नहीं पड़ेगा।’ कौन-सा वर्णन और उपाय सबसे उपयुक्त है?","optionsHi":["निष्पादन-परिहार; उससे कहना कि उसके अंकों की तुलना किसी और से नहीं की जाएगी","सीखी हुई असहायता; उसे कुछ समय के लिए गणित परीक्षणों से छूट देना जब तक उसका आत्मविश्वास स्वयं न लौट आए","स्व-अवरोधन; उसे दृढ़ता से चेतावनी देना कि प्रयास रोकने से उसके अंक और गिरेंगे","सीखी हुई असहायता; उसे ऐसे कार्य देना जिनमें वह सफल हो सके और प्रत्येक सफलता को उसकी अपनी युक्तियों से जोड़ना"],"explanationHi":"सेलिगमैन की सीखी हुई असहायता यह विश्वास है कि परिणाम अनियंत्रणीय हैं, इसलिए प्रयास रुक जाता है। उपाय है प्राप्य सफलताओं और प्रयास तथा युक्ति के आरोपण द्वारा क्रिया और परिणाम के बीच संबंध को बहाल करना; केवल परीक्षण हटाने से विश्वास अछूता रह जाता है।"},
  {"id":"cdp-child-development-1781","question":"Before every major test, Varun stays up late watching cricket and tells friends he ‘hasn’t opened a book’. In Covington’s self-worth theory, the most likely purpose of this behaviour is to:","options":["Show his friends that he does not value marks and cares more about sport","Let any failure be blamed on lack of effort rather than lack of ability","Lower his arousal to the moderate level that suits a difficult test best","Make the test feel like a casual game so that he can enjoy it more"],"answer":1,"explanation":"Self-handicapping creates an excuse in advance: if he fails, the cause is the late night, not low ability, and if he succeeds, he looks especially able. Covington saw this as protecting a sense of self-worth tied to ability.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"प्रत्येक बड़े परीक्षण से पहले वरुण देर रात तक क्रिकेट देखता है और मित्रों से कहता है कि उसने ‘किताब खोली तक नहीं’। कविंगटन के आत्म-मूल्य सिद्धांत में, इस व्यवहार का सबसे संभावित उद्देश्य क्या है?","optionsHi":["मित्रों को दिखाना कि वह अंकों को महत्व नहीं देता और खेल की अधिक परवाह करता है","किसी भी असफलता का दोष योग्यता की कमी के बजाय प्रयास की कमी पर डालने देना","अपनी उत्तेजना को उस मध्यम स्तर तक घटाना जो कठिन परीक्षण के लिए सबसे उपयुक्त है","परीक्षण को आकस्मिक खेल जैसा महसूस कराना ताकि वह उसका अधिक आनंद ले सके"],"explanationHi":"स्व-अवरोधन पहले से बहाना बनाता है: यदि वह असफल होता है तो कारण देर रात है, निम्न योग्यता नहीं, और यदि सफल होता है तो वह विशेष रूप से योग्य दिखता है। कविंगटन इसे योग्यता से बँधे आत्म-मूल्य की रक्षा के रूप में देखते थे।"},
  {"id":"cdp-child-development-1782","question":"Covington called student effort a ‘double-edged sword’. What did he mean?","options":["Effort helps in practical subjects but harms performance in subjects that depend mainly on sudden insight","Effort raises marks in the short run but steadily lowers the student’s interest in the subject in the long run","Effort earns teachers’ approval, but trying hard and still failing suggests to the student that he lacks ability","Effort is useful for weaker students but tends to make naturally able students lazy and careless"],"answer":2,"explanation":"Teachers reward effort, but for a student who tries hard and fails, the obvious inference is low ability, which threatens self-worth; so some students withhold or hide effort.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"कविंगटन ने छात्र के प्रयास को ‘दोधारी तलवार’ कहा। उनका क्या आशय था?","optionsHi":["प्रयास व्यावहारिक विषयों में सहायक है पर उन विषयों में प्रदर्शन को हानि पहुँचाता है जो मुख्यतः अचानक अंतर्दृष्टि पर निर्भर हैं","प्रयास अल्पकाल में अंक बढ़ाता है पर दीर्घकाल में विषय में छात्र की रुचि लगातार घटाता है","प्रयास शिक्षकों की स्वीकृति दिलाता है, पर कठिन परिश्रम करके भी असफल होना छात्र को सुझाता है कि उसमें योग्यता की कमी है","प्रयास कमज़ोर छात्रों के लिए उपयोगी है पर स्वाभाविक रूप से योग्य छात्रों को आलसी और लापरवाह बना देता है"],"explanationHi":"शिक्षक प्रयास को पुरस्कृत करते हैं, परंतु जो छात्र कड़ी मेहनत करके असफल होता है, उसके लिए स्पष्ट निष्कर्ष निम्न योग्यता है, जो आत्म-मूल्य को खतरे में डालता है; इसलिए कुछ छात्र प्रयास को रोकते या छिपाते हैं।"},
  {"id":"cdp-child-development-1783","question":"A teacher opens a lesson by dropping a heavy and a light ball together; both land at the same moment, and students who expected otherwise eagerly ask why. In Daniel Berlyne’s terms, the lesson begins with:","options":["A collative variable such as surprise or incongruity that arouses epistemic curiosity","A primary drive that pushes students to act in order to reduce an unmet bodily need","A secondary reinforcer that strengthens attention by rewarding it after it occurs","An advance organiser that links the new content to anchoring ideas already held"],"answer":0,"explanation":"Berlyne held that novelty, surprise, complexity and incongruity (collative variables) arouse curiosity, and epistemic curiosity drives the search for knowledge. A discrepant event works by clashing with expectations, not by reward or an organiser.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षक पाठ की शुरुआत एक भारी और एक हल्की गेंद को साथ गिराकर करता है; दोनों एक ही क्षण पर गिरती हैं, और जिन छात्रों ने कुछ और अपेक्षा की थी वे उत्सुकता से पूछते हैं क्यों। डैनियल बर्लाइन के शब्दों में, पाठ किससे शुरू होता है?","optionsHi":["आश्चर्य या असंगति जैसे संकलनात्मक (कोलेटिव) चर से, जो ज्ञानात्मक जिज्ञासा को जगाता है","प्राथमिक अंतर्नोद से, जो छात्रों को किसी अपूर्ण शारीरिक आवश्यकता को घटाने के लिए कार्य करने को प्रेरित करता है","द्वितीयक पुनर्बलक से, जो ध्यान को घटित होने के बाद पुरस्कृत करके उसे सुदृढ़ करता है","अग्रिम व्यवस्थापक से, जो नई विषयवस्तु को पहले से धारित आधार-विचारों से जोड़ता है"],"explanationHi":"बर्लाइन का मत था कि नवीनता, आश्चर्य, जटिलता और असंगति (संकलनात्मक चर) जिज्ञासा जगाते हैं, और ज्ञानात्मक जिज्ञासा ज्ञान की खोज को चलाती है। विसंगत घटना अपेक्षाओं से टकराकर काम करती है, पुरस्कार या व्यवस्थापक से नहीं।"},
  {"id":"cdp-child-development-1784","question":"George Loewenstein’s information-gap view of curiosity predicts that students will be most curious about a topic when they:","options":["Know nothing at all about it beforehand, so that everything about it feels new","Know a little about it and become aware of a specific gap in what they know","Already know almost everything about it, so that they feel confident and in control","Are told the full answer first and are then asked to remember it for a test"],"answer":1,"explanation":"Curiosity arises from noticing a gap between what one knows and wants to know; with no knowledge there is no felt gap, and complete knowledge leaves none. Teachers create curiosity by giving partial information and posing a sharp question.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"जॉर्ज लोवेनस्टाइन का जिज्ञासा का सूचना-अंतराल दृष्टिकोण पूर्वानुमान करता है कि छात्र किसी विषय के बारे में सबसे अधिक जिज्ञासु तब होंगे जब वे:","optionsHi":["उसके बारे में पहले से कुछ भी नहीं जानते, ताकि उसके बारे में सब कुछ नया लगे","उसके बारे में थोड़ा जानते हैं और जो वे जानते हैं उसमें एक विशिष्ट अंतराल से अवगत होते हैं","उसके बारे में लगभग सब कुछ पहले से जानते हैं, ताकि वे आत्मविश्वासी और नियंत्रण में महसूस करें","पहले पूरा उत्तर बताए जाते हैं और फिर परीक्षण के लिए उसे याद रखने को कहा जाता है"],"explanationHi":"जिज्ञासा तब उत्पन्न होती है जब व्यक्ति जो जानता है और जो जानना चाहता है, उसके बीच अंतर देखता है; ज्ञान के बिना कोई अनुभव किया हुआ अंतराल नहीं होता, और पूर्ण ज्ञान में कोई अंतराल नहीं बचता। शिक्षक आंशिक जानकारी देकर और तीखा प्रश्न रखकर जिज्ञासा उत्पन्न करते हैं।"},
  {"id":"cdp-child-development-1785","question":"In Csikszentmihalyi’s account of flow, a Class 7 chess player who wins every game easily against her classmates is most likely to feel:","options":["Flow, because she always succeeds at the task","Anxiety, because her skill is well below the challenge","Boredom, because her skill is well above the challenge","Apathy, because both skill and challenge are high"],"answer":2,"explanation":"Flow appears when a high challenge meets matching high skill; when skill greatly exceeds challenge the result is boredom, and when challenge exceeds skill, anxiety. Apathy goes with low skill and low challenge.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"चिक्सेंटमिहाली के प्रवाह (फ़्लो) के विवरण में, कक्षा 7 की शतरंज खिलाड़ी जो अपने सहपाठियों के विरुद्ध हर खेल आसानी से जीतती है, सबसे अधिक संभावना से क्या महसूस करेगी?","optionsHi":["प्रवाह, क्योंकि वह कार्य में सदैव सफल होती है","चिंता, क्योंकि उसका कौशल चुनौती से बहुत कम है","ऊब, क्योंकि उसका कौशल चुनौती से बहुत अधिक है","उदासीनता, क्योंकि कौशल और चुनौती दोनों उच्च हैं"],"explanationHi":"प्रवाह तब प्रकट होता है जब उच्च चुनौती मेल खाते उच्च कौशल से मिलती है; जब कौशल चुनौती से बहुत अधिक हो तो परिणाम ऊब है, और जब चुनौती कौशल से अधिक हो तो चिंता। उदासीनता निम्न कौशल और निम्न चुनौती के साथ जाती है।"},
  {"id":"cdp-child-development-1786","question":"In class projects, Imran always wants to be the group leader, enjoys persuading others to follow his plan and likes being seen as influential. In David McClelland’s terms he shows a strong need for:","options":["Recognition","Achievement","Affiliation","Power"],"answer":3,"explanation":"McClelland’s three learned needs are achievement (excelling at a standard), affiliation (warm relationships) and power (influencing and controlling others); wanting to lead and persuade is the need for power.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा परियोजनाओं में इमरान सदैव समूह का नेता बनना चाहता है, दूसरों को अपनी योजना का अनुसरण करने के लिए मनाने में आनंद लेता है और प्रभावशाली माने जाना पसंद करता है। डेविड मैक्लेलैंड के शब्दों में वह किसकी प्रबल आवश्यकता दर्शाता है?","optionsHi":["मान्यता","उपलब्धि","संबद्धता","शक्ति"],"explanationHi":"मैक्लेलैंड की तीन सीखी हुई आवश्यकताएँ हैं: उपलब्धि (किसी मानक पर उत्कृष्टता), संबद्धता (गर्मजोशी भरे संबंध) और शक्ति (दूसरों को प्रभावित और नियंत्रित करना); नेतृत्व करना और मनाना शक्ति की आवश्यकता है।"},
  {"id":"cdp-child-development-1787","question":"Arrange Hidi and Renninger’s phases of interest development in order. P. Emerging individual interest Q. Triggered situational interest R. Well-developed individual interest S. Maintained situational interest","options":["Q, S, P, R","Q, P, S, R","S, Q, P, R","Q, S, R, P"],"answer":0,"explanation":"Interest is first triggered by something in the situation, then maintained by meaningful tasks, then becomes an emerging personal interest the learner returns to, and finally a well-developed individual interest.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"हिडी और रेनिंगर के रुचि-विकास के चरणों को क्रम में व्यवस्थित कीजिए। P. उभरती वैयक्तिक रुचि Q. प्रेरित परिस्थितिजन्य रुचि R. सुविकसित वैयक्तिक रुचि S. बनाए रखी गई परिस्थितिजन्य रुचि","optionsHi":["Q, S, P, R","Q, P, S, R","S, Q, P, R","Q, S, R, P"],"explanationHi":"रुचि पहले परिस्थिति में किसी वस्तु से जगाई जाती है, फिर अर्थपूर्ण कार्यों से बनाए रखी जाती है, फिर एक उभरती व्यक्तिगत रुचि बनती है जिसकी ओर अधिगमकर्ता लौटता है, और अंत में सुविकसित वैयक्तिक रुचि।"},
  {"id":"cdp-child-development-1788","question":"Megha enjoys chemistry and knows it is useful for her goal of studying pharmacy, but she drops the optional chemistry club because it would mean giving up her evening kabaddi practice. In Eccles’s expectancy–value theory, the value component behind her decision is:","options":["Utility value","Cost","Attainment value","Intrinsic value"],"answer":1,"explanation":"Eccles named four value components: intrinsic (enjoyment), attainment (importance to identity), utility (usefulness for goals) and cost (what must be given up). The club scores well on the first three, so it is the cost that tipped the decision.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"मेघा को रसायन विज्ञान अच्छा लगता है और वह जानती है कि यह फ़ार्मेसी पढ़ने के उसके लक्ष्य के लिए उपयोगी है, पर वह वैकल्पिक रसायन क्लब छोड़ देती है क्योंकि इसका अर्थ होगा शाम का कबड्डी अभ्यास छोड़ना। एक्लेस के प्रत्याशा–मूल्य सिद्धांत में, उसके निर्णय के पीछे मूल्य-घटक है:","optionsHi":["उपयोगिता मूल्य","लागत","उपलब्धि मूल्य","आंतरिक मूल्य"],"explanationHi":"एक्लेस ने चार मूल्य-घटक बताए: आंतरिक (आनंद), उपलब्धि (पहचान के लिए महत्व), उपयोगिता (लक्ष्यों के लिए उपयोगिता) और लागत (क्या छोड़ना पड़ता है)। क्लब पहले तीन पर अच्छा अंक पाता है, इसलिए लागत ही निर्णय को झुकाती है।"},
  {"id":"cdp-child-development-1789","question":"Well-fed, rested Class 4 children spend their whole break taking apart an old radio, though no need is being met and no reward is offered. Which theory of motivation has the most difficulty explaining this?","options":["White’s competence motivation","Arousal (optimal stimulation) theory","Hull’s drive-reduction theory","Self-determination theory"],"answer":2,"explanation":"Drive-reduction theory says behaviour aims to reduce tension from unmet biological needs, so seeking extra stimulation with no need to reduce is hard for it to explain; arousal, competence and self-determination theories all expect such exploration.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"भली-भाँति भोजन किए, विश्राम किए कक्षा 4 के बच्चे पूरा अवकाश एक पुराने रेडियो को खोलने में बिताते हैं, जबकि कोई आवश्यकता पूरी नहीं हो रही और कोई पुरस्कार नहीं दिया जा रहा। अभिप्रेरणा का कौन-सा सिद्धांत इसे समझाने में सबसे अधिक कठिनाई पाता है?","optionsHi":["व्हाइट की सक्षमता अभिप्रेरणा","उत्तेजना (इष्टतम उद्दीपन) सिद्धांत","हल का अंतर्नोद-न्यूनीकरण सिद्धांत","स्व-निर्धारण सिद्धांत"],"explanationHi":"अंतर्नोद-न्यूनीकरण सिद्धांत कहता है कि व्यवहार का उद्देश्य अपूर्ण जैविक आवश्यकताओं से उत्पन्न तनाव को घटाना है, इसलिए घटाने के लिए कोई आवश्यकता न होने पर अतिरिक्त उद्दीपन की खोज इसके लिए समझाना कठिन है; उत्तेजना, सक्षमता और स्व-निर्धारण सिद्धांत सभी ऐसी खोज की अपेक्षा करते हैं।"},
  {"id":"cdp-child-development-1790","question":"Match each statement with the self-belief it best expresses. P. ‘I can solve this quadratic equation.’ Q. ‘I am good at maths.’ R. ‘On the whole, I am satisfied with myself.’ 1. Global self-esteem 2. Self-efficacy 3. Academic self-concept","options":["P-1, Q-3, R-2","P-3, Q-2, R-1","P-2, Q-1, R-3","P-2, Q-3, R-1"],"answer":3,"explanation":"Self-efficacy is confidence about a specific task; academic self-concept is a broader view of oneself in a domain; global self-esteem is an overall evaluation of one’s worth. Confusing self-efficacy with self-concept is the usual trap.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"प्रत्येक कथन का मिलान उस आत्म-विश्वास से कीजिए जिसे वह सबसे अच्छी तरह व्यक्त करता है। P. ‘मैं यह द्विघात समीकरण हल कर सकती हूँ।’ Q. ‘मैं गणित में अच्छी हूँ।’ R. ‘कुल मिलाकर, मैं स्वयं से संतुष्ट हूँ।’ 1. वैश्विक आत्म-सम्मान 2. आत्म-प्रभाविता 3. शैक्षिक आत्म-संप्रत्यय","optionsHi":["P-1, Q-3, R-2","P-3, Q-2, R-1","P-2, Q-1, R-3","P-2, Q-3, R-1"],"explanationHi":"आत्म-प्रभाविता किसी विशिष्ट कार्य के बारे में आत्मविश्वास है; शैक्षिक आत्म-संप्रत्यय किसी क्षेत्र में स्वयं का अधिक व्यापक दृष्टिकोण है; वैश्विक आत्म-सम्मान अपने मूल्य का समग्र मूल्यांकन है। आत्म-प्रभाविता को आत्म-संप्रत्यय से भ्रमित करना सामान्य जाल है।"},
  {"id":"cdp-child-development-1791","question":"A teacher wants group work in Class 6 to be truly cooperative in Johnson and Johnson’s sense. Which pair of features is essential?","options":["Positive interdependence and individual accountability","A single group mark for all members and a free choice of partners","Grouping by ability, with a prize for the best-performing group","Competition between groups and a group leader"],"answer":0,"explanation":"Members must need one another to succeed (positive interdependence) and each must be answerable for his own learning (individual accountability); without the second, a few students do the work while others coast.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षिका चाहती है कि कक्षा 6 में समूह-कार्य जॉनसन और जॉनसन के अर्थ में सचमुच सहयोगात्मक हो। कौन-सा विशेषता-युग्म आवश्यक है?","optionsHi":["सकारात्मक परस्पर-निर्भरता और वैयक्तिक उत्तरदायित्व","सभी सदस्यों के लिए एक ही समूह-अंक और साथियों का मुक्त चयन","योग्यता के आधार पर समूहीकरण, सर्वश्रेष्ठ प्रदर्शन करने वाले समूह के लिए पुरस्कार के साथ","समूहों के बीच प्रतिस्पर्धा और एक समूह-नेता"],"explanationHi":"सदस्यों को सफल होने के लिए एक-दूसरे की आवश्यकता होनी चाहिए (सकारात्मक परस्पर-निर्भरता) और प्रत्येक को अपने अधिगम के लिए उत्तरदायी होना चाहिए (वैयक्तिक उत्तरदायित्व); दूसरे के बिना, कुछ छात्र काम करते हैं जबकि अन्य बस साथ चलते हैं।"},
  {"id":"cdp-child-development-1792","question":"Rahul, a Class 9 boy who often got into fights, is persuaded by his PE teacher to join the school wrestling team. He now pours his aggression into disciplined training and wins medals. In Freud's terms, the defence mechanism at work is:","options":["Displacement","Reaction formation","Sublimation","Rationalisation"],"answer":2,"explanation":"Sublimation channels an unacceptable impulse into a socially valued activity. Displacement only shifts the impulse onto a safer target (for example hitting a younger sibling), reaction formation shows the opposite of the impulse, and rationalisation invents acceptable reasons for it.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 9 का लड़का राहुल, जो प्रायः झगड़ों में पड़ता था, उसके शारीरिक शिक्षा शिक्षक द्वारा विद्यालय की कुश्ती टीम में शामिल होने के लिए मनाया जाता है। अब वह अपनी आक्रामकता अनुशासित प्रशिक्षण में लगाता है और पदक जीतता है। फ्रायड के शब्दों में, कार्य कर रही रक्षा-युक्ति है:","optionsHi":["विस्थापन","प्रतिक्रिया-निर्माण","उदात्तीकरण","युक्तिकरण"],"explanationHi":"उदात्तीकरण किसी अस्वीकार्य आवेग को सामाजिक रूप से मूल्यवान गतिविधि में प्रवाहित करता है। विस्थापन आवेग को केवल अधिक सुरक्षित लक्ष्य पर स्थानांतरित करता है (उदाहरण के लिए छोटे भाई-बहन को मारना), प्रतिक्रिया-निर्माण आवेग का विपरीत दिखाता है, और युक्तिकरण उसके लिए स्वीकार्य कारण गढ़ता है।"},
  {"id":"cdp-child-development-1793","question":"Students weak at subtraction worked through a booklet of 42 pages. Group A set a goal of finishing about six pages each session; Group B set the goal of finishing the whole booklet by the end of seven sessions. Bandura and Schunk found that Group A most likely:","options":["Did about as well as Group B, since both groups had to complete exactly the same pages","Gained less, because six pages a session is too easy a target to motivate anyone to try","Gained more skill, self-efficacy and interest, because near goals give frequent evidence of progress","Gained more skill but lost interest, because close, frequent goals feel like constant extra pressure"],"answer":2,"explanation":"Proximal (close) goals give regular, clear evidence of progress, which raises self-efficacy and intrinsic interest; distant goals give little feedback along the way. The total work is the same, so the difference lies in the goal structure.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"घटाव में कमज़ोर छात्रों ने 42 पृष्ठों की एक पुस्तिका पर कार्य किया। समूह A ने प्रत्येक सत्र में लगभग छह पृष्ठ पूरे करने का लक्ष्य रखा; समूह B ने सात सत्रों के अंत तक पूरी पुस्तिका पूरी करने का लक्ष्य रखा। बंडूरा और शंक ने पाया कि समूह A ने सबसे अधिक संभावना से:","optionsHi":["समूह B के लगभग बराबर प्रदर्शन किया, क्योंकि दोनों समूहों को ठीक वही पृष्ठ पूरे करने थे","कम प्राप्त किया, क्योंकि प्रति सत्र छह पृष्ठ किसी को भी प्रयास के लिए प्रेरित करने के लिहाज़ से बहुत आसान लक्ष्य है","अधिक कौशल, आत्म-प्रभाविता और रुचि प्राप्त की, क्योंकि निकट लक्ष्य प्रगति के बार-बार प्रमाण देते हैं","अधिक कौशल प्राप्त किया पर रुचि खो दी, क्योंकि निकट, बार-बार आने वाले लक्ष्य निरंतर अतिरिक्त दबाव जैसे लगते हैं"],"explanationHi":"निकटस्थ लक्ष्य प्रगति के नियमित, स्पष्ट प्रमाण देते हैं, जो आत्म-प्रभाविता और आंतरिक रुचि बढ़ाते हैं; दूरस्थ लक्ष्य मार्ग में बहुत कम प्रतिपुष्टि देते हैं। कुल कार्य समान है, इसलिए अंतर लक्ष्य की संरचना में है।"},
  {"id":"cdp-child-development-1794","question":"Large studies of school students in several countries broadly agree that average intrinsic motivation for schoolwork, from the early primary years to the middle-school years:","options":["Rises sharply at puberty","Tends to rise slowly but steadily","Stays almost unchanged","Tends to decline steadily"],"answer":3,"explanation":"Research such as Lepper, Corpus and Iyengar’s found intrinsic motivation falls across grades, linked partly to more grades, comparison and control in school; this is why later classes need deliberate attention to interest and autonomy.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कई देशों के विद्यालयी छात्रों के बड़े अध्ययन मोटे तौर पर इस पर सहमत हैं कि प्रारंभिक प्राथमिक वर्षों से माध्यमिक-विद्यालय वर्षों तक विद्यालयी कार्य के लिए औसत आंतरिक अभिप्रेरणा:","optionsHi":["यौवनारंभ पर तेज़ी से बढ़ती है","धीरे-धीरे पर लगातार बढ़ने की प्रवृत्ति रखती है","लगभग अपरिवर्तित रहती है","लगातार घटने की प्रवृत्ति रखती है"],"explanationHi":"लेपर, कॉर्पस और अयेंगर जैसे शोध में पाया गया कि आंतरिक अभिप्रेरणा कक्षाओं में घटती है, जो आंशिक रूप से विद्यालय में अधिक ग्रेड, तुलना और नियंत्रण से जुड़ी है; इसीलिए बाद की कक्षाओं में रुचि और स्वायत्तता पर सोद्देश्य ध्यान चाहिए।"},
  {"id":"cdp-child-development-1795","question":"In Diener and Dweck’s studies, children were given problems they could solve and then some they could not. During the failures, ‘mastery-oriented’ children differed from ‘helpless’ children mainly in that they:","options":["Kept or even improved their strategies and treated failure as a problem to work on","Rated themselves as more intelligent than others and so felt that failure was beneath them","Remembered their earlier successes better and so did not notice the failures","Attributed failure to bad luck, which protected their self-esteem from harm"],"answer":0,"explanation":"Helpless children blamed their ability and their strategies broke down; mastery-oriented children hardly mentioned causes, gave themselves instructions and kept using good strategies. The difference was in reaction to failure, not in measured ability.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"डीनर और ड्वेक के अध्ययनों में, बच्चों को ऐसी समस्याएँ दी गईं जिन्हें वे हल कर सकते थे और फिर कुछ ऐसी जिन्हें वे नहीं कर सकते थे। असफलताओं के दौरान, ‘निपुणता-उन्मुख’ बच्चे ‘असहाय’ बच्चों से मुख्यतः इस बात में भिन्न थे कि वे:","optionsHi":["अपनी युक्तियाँ बनाए रखते या सुधारते थे और असफलता को काम करने योग्य समस्या मानते थे","स्वयं को दूसरों से अधिक बुद्धिमान आँकते थे और इसलिए असफलता को अपने से नीचे की बात मानते थे","अपनी पहले की सफलताओं को बेहतर याद रखते थे और इसलिए असफलताओं पर ध्यान नहीं देते थे","असफलता का श्रेय दुर्भाग्य को देते थे, जो उनके आत्म-सम्मान को हानि से बचाता था"],"explanationHi":"असहाय बच्चे अपनी योग्यता को दोष देते थे और उनकी युक्तियाँ टूट जाती थीं; निपुणता-उन्मुख बच्चों ने कारणों का मुश्किल से उल्लेख किया, स्वयं को निर्देश दिए और अच्छी युक्तियों का प्रयोग जारी रखा। अंतर असफलता के प्रति प्रतिक्रिया में था, मापी गई योग्यता में नहीं।"},
  {"id":"cdp-child-development-1796","question":"J. McV. Hunt’s ‘problem of the match’ advises that, to keep children interested, new material should be:","options":["Chosen only after the child has fully mastered the textbook","Exactly the same as what the child already understands","As different as possible from what the child already understands","Moderately different from what the child already understands"],"answer":3,"explanation":"Hunt argued that intrinsic interest is aroused by an optimal discrepancy: input too familiar is boring and input too strange cannot be assimilated, so a moderate mismatch with existing schemas works best.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"जे. मैकवी. हंट की ‘मेल की समस्या’ सुझाती है कि बच्चों की रुचि बनाए रखने के लिए नई सामग्री होनी चाहिए:","optionsHi":["केवल तब चुनी जाए जब बच्चा पाठ्यपुस्तक में पूरी तरह निपुण हो चुका हो","ठीक वैसी ही जैसी बच्चा पहले से समझता है","जितनी संभव हो उतनी भिन्न जो बच्चा पहले से समझता है","जो बच्चा पहले से समझता है उससे मध्यम रूप से भिन्न"],"explanationHi":"हंट ने तर्क दिया कि आंतरिक रुचि इष्टतम विसंगति से जगती है: बहुत परिचित सामग्री ऊब पैदा करती है और बहुत अजनबी सामग्री आत्मसात नहीं हो सकती, इसलिए मौजूदा स्कीमाओं से मध्यम बेमेल सबसे अच्छा काम करता है।"},
  {"id":"cdp-child-development-1797","question":"Assertion (A): Children who are already keen readers may later read fewer books on their own after a scheme pays them a prize for every book read. Reason (R): Every reward given for an activity always lowers intrinsic motivation for it.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Expected, tangible rewards for an already enjoyable activity can undermine interest (the overjustification effect), so A is true. R overstates it: informational praise and unexpected rewards usually do not lower intrinsic motivation.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): जो बच्चे पहले से उत्सुक पाठक हैं वे बाद में अपने आप कम पुस्तकें पढ़ सकते हैं, यदि कोई योजना प्रत्येक पढ़ी गई पुस्तक के लिए पुरस्कार देती है। कारण (R): किसी गतिविधि के लिए दिया गया प्रत्येक पुरस्कार सदैव उसके लिए आंतरिक अभिप्रेरणा घटाता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"पहले से आनंददायक गतिविधि के लिए अपेक्षित, मूर्त पुरस्कार रुचि को कमज़ोर कर सकते हैं (अतिऔचित्य प्रभाव), इसलिए A सत्य है। R इसे बढ़ा-चढ़ाकर कहता है: सूचनात्मक प्रशंसा और अप्रत्याशित पुरस्कार सामान्यतः आंतरिक अभिप्रेरणा नहीं घटाते।"},
  {"id":"cdp-child-development-1798","question":"Which statement about setting goals for students is best supported by Locke and Latham’s research?","options":["‘Do your best’ goals work better than specific ones because they reduce pressure","Specific, challenging goals usually lead to better performance than ‘do your best’","Easy goals produce the highest performance because they ensure frequent success","Goals help only adults; children perform the same with or without them"],"answer":1,"explanation":"Goal-setting research consistently finds that specific, difficult but attainable goals, with feedback and commitment, raise performance more than vague ‘do your best’ instructions or easy goals.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"छात्रों के लिए लक्ष्य निर्धारण के बारे में कौन-सा कथन लॉक और लैथम के शोध से सबसे अच्छी तरह समर्थित है?","optionsHi":["‘अपना सर्वश्रेष्ठ करो’ वाले लक्ष्य विशिष्ट लक्ष्यों से बेहतर काम करते हैं क्योंकि वे दबाव घटाते हैं","विशिष्ट, चुनौतीपूर्ण लक्ष्य सामान्यतः ‘अपना सर्वश्रेष्ठ करो’ से बेहतर प्रदर्शन की ओर ले जाते हैं","आसान लक्ष्य सर्वोच्च प्रदर्शन देते हैं क्योंकि वे बार-बार सफलता सुनिश्चित करते हैं","लक्ष्य केवल वयस्कों की सहायता करते हैं; बच्चे उनके साथ या बिना समान प्रदर्शन करते हैं"],"explanationHi":"लक्ष्य-निर्धारण शोध लगातार पाता है कि विशिष्ट, कठिन परंतु प्राप्य लक्ष्य, प्रतिपुष्टि और प्रतिबद्धता के साथ, अस्पष्ट ‘अपना सर्वश्रेष्ठ करो’ निर्देशों या आसान लक्ष्यों की तुलना में प्रदर्शन को अधिक बढ़ाते हैं।"},
  {"id":"cdp-child-development-1799","question":"A teacher wants to reduce learned helplessness in her Class 5. Which of these steps fit attribution retraining? I. Pointing out after each success which strategy the child used. II. Telling children who fail that the task was simply too hard for them. III. Modelling self-talk such as ‘I made a mistake; let me try another way.’ IV. Telling them that some people are just born good at maths.","options":["II and IV only","I, II and III only","I and III only","I, III and IV only"],"answer":2,"explanation":"Attribution retraining moves explanations of success and failure towards controllable, unstable causes such as effort and strategy. Blaming task difficulty (II) or innate talent (IV) points to causes the child cannot change.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षिका अपनी कक्षा 5 में सीखी हुई असहायता कम करना चाहती है। इनमें से कौन-से कदम आरोपण पुनःप्रशिक्षण के अनुकूल हैं? I. प्रत्येक सफलता के बाद यह बताना कि बच्चे ने कौन-सी युक्ति अपनाई। II. असफल होने वाले बच्चों से कहना कि कार्य उनके लिए बस बहुत कठिन था। III. ‘मुझसे गलती हुई; मुझे दूसरे तरीके से कोशिश करने दो’ जैसा आत्म-संवाद आदर्श रूप में प्रस्तुत करना। IV. उनसे कहना कि कुछ लोग जन्म से ही गणित में अच्छे होते हैं।","optionsHi":["केवल II और IV","केवल I, II और III","केवल I और III","केवल I, III और IV"],"explanationHi":"आरोपण पुनःप्रशिक्षण सफलता और असफलता की व्याख्याओं को नियंत्रणीय, अस्थिर कारणों, जैसे प्रयास और युक्ति, की ओर ले जाता है। कार्य की कठिनाई (II) या जन्मजात प्रतिभा (IV) को दोष देना उन कारणों की ओर इंगित करता है जिन्हें बच्चा बदल नहीं सकता।"},
  {"id":"cdp-child-development-1800","question":"A student says, ‘I don’t see any point in studying; nothing I do here connects to anything I want.’ In self-determination theory this state is called:","options":["Amotivation","External regulation","Introjected regulation","Integrated regulation"],"answer":0,"explanation":"Amotivation is the lack of any intention to act, from seeing no value or no link between action and outcome. External and introjected regulation still involve acting, though for pressured reasons.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक छात्र कहता है, ‘मुझे पढ़ाई का कोई मतलब नहीं दिखता; यहाँ मैं जो कुछ भी करता हूँ वह मेरी चाही किसी चीज़ से नहीं जुड़ता।’ स्व-निर्धारण सिद्धांत में इस अवस्था को क्या कहते हैं?","optionsHi":["अभिप्रेरणाहीनता (एमोटिवेशन)","बाह्य नियमन","अंतःक्षेपित नियमन","एकीकृत नियमन"],"explanationHi":"अभिप्रेरणाहीनता कार्य करने के किसी भी आशय का अभाव है, जो कोई मूल्य या क्रिया और परिणाम के बीच संबंध न देखने से आता है। बाह्य और अंतःक्षेपित नियमन में फिर भी कार्य होता है, यद्यपि दबाव-युक्त कारणों से।"},
  {"id":"cdp-child-development-1801","question":"In a listening experiment, students repeat aloud a story played to the left ear and ignore a different story in the right ear. When the stories suddenly swap ears, many students briefly continue the original story from the right ear. What does this most directly show?","options":["The ignored message was processed for meaning to some extent, supporting Treisman’s attenuation model over Broadbent’s early filter","The ignored message was blocked entirely, supporting Broadbent’s all-or-none early filter over Treisman’s attenuation model","Attention can be divided equally between two meaningful messages if both are heard through earphones","Students who repeat a message aloud stop processing its meaning and attend only to the voice"],"answer":0,"explanation":"If the unattended ear were filtered out completely on physical features, its content could not pull attention across. Treisman proposed that unattended input is weakened, not blocked, so highly probable or meaningful words can still break through.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"एक श्रवण प्रयोग में, छात्र बाएँ कान में बजाई गई एक कहानी को ज़ोर से दोहराते हैं और दाएँ कान की एक भिन्न कहानी को अनदेखा करते हैं। जब कहानियाँ अचानक कान बदल लेती हैं, तो अनेक छात्र कुछ देर तक दाएँ कान से मूल कहानी जारी रखते हैं। यह सबसे प्रत्यक्ष रूप से क्या दर्शाता है?","optionsHi":["अनदेखे संदेश का कुछ हद तक अर्थ के लिए प्रक्रमण हुआ, जो ब्रॉडबेंट के प्रारंभिक फ़िल्टर पर ट्रीज़मैन के क्षीणन मॉडल का समर्थन करता है","अनदेखा संदेश पूरी तरह अवरुद्ध हुआ, जो ट्रीज़मैन के क्षीणन मॉडल पर ब्रॉडबेंट के सर्व-या-कुछ-नहीं प्रारंभिक फ़िल्टर का समर्थन करता है","ध्यान दो अर्थपूर्ण संदेशों के बीच समान रूप से विभाजित हो सकता है यदि दोनों ईयरफ़ोन से सुने जाएँ","जो छात्र संदेश को ज़ोर से दोहराते हैं वे उसके अर्थ का प्रक्रमण बंद कर देते हैं और केवल आवाज़ पर ध्यान देते हैं"],"explanationHi":"यदि अनदेखे कान को भौतिक विशेषताओं पर पूरी तरह छाँटकर बाहर कर दिया जाता, तो उसकी विषयवस्तु ध्यान को खींच नहीं सकती थी। ट्रीज़मैन ने प्रस्तावित किया कि अनदेखा निवेश अवरुद्ध नहीं, कमज़ोर किया जाता है, इसलिए अत्यंत संभावित या अर्थपूर्ण शब्द फिर भी बीच में घुस सकते हैं।"},
  {"id":"cdp-child-development-1802","question":"A school finds that Class 11 students who chat on their phones during lessons score lower on later quizzes than those who do not. What does research on such classroom multitasking also suggest?","options":["The loss disappears once students become practised at switching between tasks","Classmates who can see a multitasking student’s screen also tend to understand less","The loss affects only students of low ability, not the able students in class","Listening ability actually improves, because phone use keeps students alert and awake"],"answer":1,"explanation":"Attention cannot be fully shared between two demanding tasks; frequent switching lowers comprehension. Studies such as Sana and colleagues’ found that nearby students who could view a laptop multitasker were distracted and scored lower too.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"एक विद्यालय पाता है कि कक्षा 11 के जो छात्र पाठों के दौरान फ़ोन पर बातचीत करते हैं वे बाद की प्रश्नोत्तरियों में उन छात्रों से कम अंक पाते हैं जो नहीं करते। कक्षा में ऐसी बहु-कार्यता पर शोध और क्या सुझाता है?","optionsHi":["जब छात्र कार्यों के बीच स्विच करने में अभ्यस्त हो जाते हैं तो यह हानि समाप्त हो जाती है","जो सहपाठी बहु-कार्य करने वाले छात्र की स्क्रीन देख सकते हैं वे भी कम समझने की प्रवृत्ति रखते हैं","हानि केवल निम्न योग्यता वाले छात्रों को प्रभावित करती है, कक्षा के योग्य छात्रों को नहीं","सुनने की क्षमता वास्तव में सुधरती है, क्योंकि फ़ोन का उपयोग छात्रों को सतर्क और जागृत रखता है"],"explanationHi":"ध्यान दो माँग वाले कार्यों के बीच पूरी तरह साझा नहीं किया जा सकता; बार-बार स्विच करना बोध घटाता है। साना और सहयोगियों जैसे अध्ययनों में पाया गया कि लैपटॉप पर बहु-कार्य करने वाले को देख सकने वाले आसपास के छात्र भी विचलित हुए और कम अंक पाए।"},
  {"id":"cdp-child-development-1803","question":"In the Stroop task, children name the ink colour of colour words, such as RED printed in green. Compared with a Class 1 child who cannot yet read, a fluent Class 4 reader is most likely to show:","options":["The same slowing, because the task measures colour perception, which is mature by Class 1","Less slowing, because older children have better attention and simply ignore the printed word","More slowing, because reading the word has become automatic and competes with naming the ink","No slowing at all, because fluent readers process words and colours in separate brain areas"],"answer":2,"explanation":"Stroop interference arises from automatic reading; children who cannot read do not show it, and it appears once word reading becomes automatic in the early school years. It shows that practised skills run without deliberate attention and are hard to switch off.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"स्ट्रूप कार्य में, बच्चे रंग-शब्दों की स्याही का रंग बताते हैं, जैसे हरे रंग में छपा RED। कक्षा 1 के उस बच्चे की तुलना में जो अभी पढ़ नहीं सकता, कक्षा 4 का धाराप्रवाह पाठक सबसे अधिक संभावना से क्या दिखाएगा?","optionsHi":["वही धीमापन, क्योंकि कार्य रंग-प्रत्यक्षण मापता है, जो कक्षा 1 तक परिपक्व होता है","कम धीमापन, क्योंकि बड़े बच्चों में बेहतर ध्यान होता है और वे छपे शब्द को बस अनदेखा कर देते हैं","अधिक धीमापन, क्योंकि शब्द पढ़ना स्वचालित हो गया है और स्याही को नाम देने से प्रतिस्पर्धा करता है","कोई धीमापन नहीं, क्योंकि धाराप्रवाह पाठक शब्दों और रंगों का प्रक्रमण मस्तिष्क के अलग क्षेत्रों में करते हैं"],"explanationHi":"स्ट्रूप व्यतिकरण स्वचालित पठन से उत्पन्न होता है; जो बच्चे पढ़ नहीं सकते वे इसे नहीं दिखाते, और यह तब प्रकट होता है जब प्रारंभिक विद्यालयी वर्षों में शब्द-पठन स्वचालित हो जाता है। यह दर्शाता है कि अभ्यास किए गए कौशल सोद्देश्य ध्यान के बिना चलते हैं और उन्हें बंद करना कठिन है।"},
  {"id":"cdp-child-development-1804","question":"Students asked to count the passes made by one team in a video often fail to notice a person in a gorilla suit walking through the scene. What is the main lesson for a teacher?","options":["Learners who miss such events lack interest in the subject and need stronger motivation","Learners notice anything unusual, so a surprising object is the surest way to make sure a point is remembered","Young learners cannot attend properly to moving pictures, so videos should be kept out of lessons","Learners focused on one demanding detail may miss even striking information, so direct their attention to what matters"],"answer":3,"explanation":"This is inattentional blindness: what is not attended to is often not perceived at all. Teachers cannot assume something visible will be seen; they must cue attention to the key features.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"किसी वीडियो में एक टीम द्वारा किए गए पास गिनने को कहे जाने पर छात्र प्रायः दृश्य में गोरिल्ला की पोशाक में चलते व्यक्ति को नहीं देख पाते। शिक्षक के लिए मुख्य सबक क्या है?","optionsHi":["जो अधिगमकर्ता ऐसी घटनाएँ चूक जाते हैं उनमें विषय में रुचि की कमी है और उन्हें प्रबल अभिप्रेरणा चाहिए","अधिगमकर्ता किसी भी असामान्य चीज़ पर ध्यान देते हैं, इसलिए आश्चर्यजनक वस्तु यह सुनिश्चित करने का सबसे पक्का तरीका है कि बात याद रहे","छोटे अधिगमकर्ता चलते चित्रों पर ठीक से ध्यान नहीं दे सकते, इसलिए पाठों में वीडियो नहीं होने चाहिए","एक माँग वाले विवरण पर केंद्रित अधिगमकर्ता आकर्षक जानकारी भी चूक सकते हैं, इसलिए उनका ध्यान उस ओर निर्देशित करें जो मायने रखता है"],"explanationHi":"यह असावधानीजन्य अंधता है: जिस पर ध्यान नहीं दिया जाता वह प्रायः बिल्कुल प्रत्यक्षित नहीं होता। शिक्षक यह नहीं मान सकते कि जो दृश्य है वह देखा जाएगा; उन्हें मुख्य विशेषताओं की ओर ध्यान संकेतित करना चाहिए।"},
  {"id":"cdp-child-development-1805","question":"Asked to check a long list of numbers for errors over an hour, students catch most errors in the first ten minutes and fewer later, though the errors are spread evenly. This decline is called:","options":["Vigilance decrement","Habituation of the orienting response","Retroactive interference","Response set"],"answer":0,"explanation":"Vigilance decrement is the fall in detection over a long monitoring task, showing the limits of sustained attention. Habituation is a weakened response to a repeated stimulus; interference concerns memory, not detection.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक घंटे तक संख्याओं की लंबी सूची में त्रुटियाँ जाँचने को कहे जाने पर, छात्र पहले दस मिनट में अधिकांश त्रुटियाँ पकड़ते हैं और बाद में कम, यद्यपि त्रुटियाँ समान रूप से फैली हैं। इस गिरावट को क्या कहते हैं?","optionsHi":["सतर्कता-ह्रास (विजिलेंस डिक्रिमेंट)","अनुस्थापन-प्रतिक्रिया का आदतन अभ्यस्तीकरण","पश्चोन्मुख व्यतिकरण","प्रतिक्रिया-मनोवृत्ति (रिस्पॉन्स सेट)"],"explanationHi":"सतर्कता-ह्रास लंबे निगरानी कार्य में पहचान की गिरावट है, जो सतत ध्यान की सीमाएँ दर्शाती है। अभ्यस्तीकरण बार-बार आने वाले उद्दीपक के प्रति कमज़ोर प्रतिक्रिया है; व्यतिकरण स्मृति से संबंधित है, पहचान से नहीं।"},
  {"id":"cdp-child-development-1806","question":"Children of different ages were shown cards, each with an animal and a household object, and told to remember only the position of the animals. Later they were also asked which object had gone with which animal. Hagen’s classic findings showed that with age:","options":["Recall of both the animals and the objects stayed the same","Recall of both the animals and the paired objects rose by the same amount","Recall of the paired objects rose more than recall of the animals","Recall of the animals rose clearly, but recall of the paired objects did not"],"answer":3,"explanation":"Central learning improved with age while incidental learning stayed flat or even dropped in the oldest groups, showing that older children are better at selectively attending to the task-relevant items and ignoring others.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"विभिन्न आयु के बच्चों को कार्ड दिखाए गए, प्रत्येक पर एक पशु और एक घरेलू वस्तु थी, और उनसे केवल पशुओं की स्थिति याद रखने को कहा गया। बाद में उनसे यह भी पूछा गया कि कौन-सी वस्तु किस पशु के साथ थी। हेगन के शास्त्रीय निष्कर्षों ने दिखाया कि आयु के साथ:","optionsHi":["पशुओं और वस्तुओं दोनों का स्मरण समान रहा","पशुओं और जोड़ी गई वस्तुओं दोनों का स्मरण समान मात्रा में बढ़ा","जोड़ी गई वस्तुओं का स्मरण पशुओं के स्मरण से अधिक बढ़ा","पशुओं का स्मरण स्पष्ट रूप से बढ़ा, पर जोड़ी गई वस्तुओं का स्मरण नहीं"],"explanationHi":"केंद्रीय अधिगम आयु के साथ सुधरा जबकि आकस्मिक अधिगम स्थिर रहा या सबसे बड़े समूहों में घट भी गया, जो दर्शाता है कि बड़े बच्चे कार्य-संबंधी मदों पर चयनात्मक ध्यान देने और अन्य को अनदेखा करने में बेहतर हैं।"},
  {"id":"cdp-child-development-1807","question":"A Class 2 teacher claps twice to get attention. It works well in the first week, but by the third week children barely look up. The best explanation is:","options":["Extinction: the clap was never paired with any reward, so the response gradually died out","Habituation: a repeated, predictable stimulus stops drawing the orienting response","Retroactive interference: new rules in the third week replaced the old one","Spontaneous recovery: the response returns after a break and then fades again"],"answer":1,"explanation":"Novel stimuli draw an orienting response, which weakens with repetition; changing the signal or pairing it with something meaningful restores attention. Extinction would need an earlier reinforced response that is no longer reinforced.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 की शिक्षिका ध्यान आकर्षित करने के लिए दो बार ताली बजाती है। यह पहले सप्ताह में अच्छा काम करता है, पर तीसरे सप्ताह तक बच्चे मुश्किल से ऊपर देखते हैं। सबसे अच्छी व्याख्या है:","optionsHi":["विलोपन: ताली को कभी किसी पुरस्कार के साथ नहीं जोड़ा गया, इसलिए प्रतिक्रिया धीरे-धीरे समाप्त हो गई","अभ्यस्तीकरण: बार-बार आने वाला, पूर्वानुमेय उद्दीपक अनुस्थापन प्रतिक्रिया को खींचना बंद कर देता है","पश्चोन्मुख व्यतिकरण: तीसरे सप्ताह के नए नियमों ने पुराने की जगह ले ली","स्वतः पुनःप्राप्ति: विराम के बाद प्रतिक्रिया लौटती है और फिर मंद पड़ जाती है"],"explanationHi":"नए उद्दीपक अनुस्थापन प्रतिक्रिया खींचते हैं, जो दोहराव के साथ कमज़ोर होती है; संकेत बदलना या उसे किसी अर्थपूर्ण चीज़ से जोड़ना ध्यान बहाल करता है। विलोपन के लिए पहले की पुनर्बलित प्रतिक्रिया चाहिए जिसे अब पुनर्बलित नहीं किया जाता।"},
  {"id":"cdp-child-development-1808","question":"A slide on photosynthesis carries a dancing cartoon sun, sound effects and an amusing story about a record-breaking sunflower that has nothing to do with the process. Research on multimedia learning predicts that these additions will most likely:","options":["Make no difference, since students simply ignore whatever is irrelevant to the lesson","Improve learning, because more interest always means more attention to the main content","Reduce learning of the process, because they add extraneous load and pull attention away from it","Help weak students but not strong students, who do not need extra interest"],"answer":2,"explanation":"Mayer’s coherence principle and studies of ‘seductive details’ show that interesting but irrelevant material uses limited attention and working memory and can lead learners to organise the lesson around the wrong ideas.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"प्रकाश-संश्लेषण की एक स्लाइड में नाचता हुआ कार्टून सूर्य, ध्वनि-प्रभाव और रिकॉर्ड तोड़ने वाले सूरजमुखी की एक मनोरंजक कहानी है जिसका प्रक्रिया से कोई संबंध नहीं। मल्टीमीडिया अधिगम पर शोध पूर्वानुमान करता है कि ये जोड़ सबसे अधिक संभावना से:","optionsHi":["कोई अंतर नहीं डालेंगे, क्योंकि छात्र पाठ के लिए अप्रासंगिक चीज़ों को बस अनदेखा कर देते हैं","अधिगम सुधारेंगे, क्योंकि अधिक रुचि का अर्थ सदैव मुख्य विषयवस्तु पर अधिक ध्यान है","प्रक्रिया के अधिगम को घटाएँगे, क्योंकि वे बाह्य भार जोड़ते हैं और ध्यान को उससे हटा देते हैं","कमज़ोर छात्रों की सहायता करेंगे पर सशक्त छात्रों की नहीं, जिन्हें अतिरिक्त रुचि की आवश्यकता नहीं"],"explanationHi":"मेयर का संसक्ति सिद्धांत और ‘लुभावने विवरणों’ के अध्ययन दिखाते हैं कि रोचक पर अप्रासंगिक सामग्री सीमित ध्यान और कार्यकारी स्मृति का उपयोग करती है और अधिगमकर्ताओं को पाठ को गलत विचारों के इर्द-गिर्द संगठित करने की ओर ले जा सकती है।"},
  {"id":"cdp-child-development-1809","question":"While showing an animated diagram of blood circulation, a teacher also reads out a text box that repeats her spoken words exactly. According to Mayer’s redundancy principle, students would learn better if she:","options":["Removed the text box and kept the narration with the animation","Removed the narration and kept the text box with the animation","Kept the narration, the text box and the animation all together","Showed the text box alone before showing the animation alone"],"answer":0,"explanation":"Identical printed text competes with the animation for the visual channel and forces learners to reconcile two verbal streams; narration plus the picture uses the auditory and visual channels without overload.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"रक्त परिसंचरण का एक एनिमेटेड आरेख दिखाते समय, एक शिक्षिका एक टेक्स्ट-बॉक्स भी पढ़ती है जो उसके बोले शब्दों को ठीक-ठीक दोहराता है। मेयर के अतिरेक सिद्धांत के अनुसार, छात्र बेहतर सीखते यदि वह:","optionsHi":["टेक्स्ट-बॉक्स हटा देती और एनिमेशन के साथ कथन रखती","कथन हटा देती और एनिमेशन के साथ टेक्स्ट-बॉक्स रखती","कथन, टेक्स्ट-बॉक्स और एनिमेशन तीनों साथ रखती","पहले टेक्स्ट-बॉक्स अकेला और फिर एनिमेशन अकेला दिखाती"],"explanationHi":"समान छपा पाठ एनिमेशन के साथ दृश्य माध्यम के लिए प्रतिस्पर्धा करता है और अधिगमकर्ताओं को दो शाब्दिक धाराओं का मेल बैठाने को बाध्य करता है; कथन के साथ चित्र श्रव्य और दृश्य माध्यमों का भार-रहित उपयोग करता है।"},
  {"id":"cdp-child-development-1810","question":"For a labelled diagram of the human ear, which accompanying explanation is predicted by the modality principle to work best for Class 8 students?","options":["A printed paragraph read silently before seeing the diagram","A printed paragraph placed beside the diagram","A printed paragraph on the next page after the diagram","A spoken explanation while students look at the diagram"],"answer":3,"explanation":"When a picture must be examined, words are better heard than read, because both the diagram and printed text compete for visual attention; spreading the load across ears and eyes frees working memory.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"मानव कान के नामांकित आरेख के लिए, माध्यम सिद्धांत के अनुसार कक्षा 8 के छात्रों के लिए कौन-सी साथ की व्याख्या सबसे अच्छा काम करेगी?","optionsHi":["आरेख देखने से पहले चुपचाप पढ़ा गया छपा अनुच्छेद","आरेख के बगल में रखा गया छपा अनुच्छेद","आरेख के बाद अगले पृष्ठ पर छपा अनुच्छेद","छात्रों के आरेख देखते समय मौखिक व्याख्या"],"explanationHi":"जब किसी चित्र की जाँच करनी हो तो शब्दों को पढ़ने के बजाय सुनना बेहतर है, क्योंकि आरेख और छपा पाठ दोनों दृश्य ध्यान के लिए प्रतिस्पर्धा करते हैं; भार को कानों और आँखों में फैलाना कार्यकारी स्मृति को मुक्त करता है।"},
  {"id":"cdp-child-development-1811","question":"Fully solved examples help beginners in algebra learn more than solving the same problems unaided. For students who are already skilled, however, the same worked examples can give less benefit than practice problems. This is called:","options":["The redundancy principle","The expertise reversal effect","The generation effect in problem solving","The spacing (distributed practice) effect"],"answer":1,"explanation":"Worked examples reduce load for novices, but experts already hold the schemas, so processing the steps becomes redundant extra load; methods must change as expertise grows.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"पूरी तरह हल किए गए उदाहरण बीजगणित में शुरुआती छात्रों को वही प्रश्न बिना सहायता हल करने की तुलना में अधिक सीखने में सहायता करते हैं। परंतु पहले से कुशल छात्रों के लिए वही हल किए उदाहरण अभ्यास प्रश्नों की तुलना में कम लाभ दे सकते हैं। इसे क्या कहते हैं?","optionsHi":["अतिरेक सिद्धांत","विशेषज्ञता-प्रतिलोम प्रभाव","समस्या-समाधान में सृजन प्रभाव","अंतराल (वितरित अभ्यास) प्रभाव"],"explanationHi":"हल किए गए उदाहरण नौसिखियों के लिए भार घटाते हैं, पर विशेषज्ञों के पास पहले से स्कीमा होते हैं, इसलिए चरणों का प्रक्रमण अतिरिक्त भार बन जाता है; विशेषज्ञता बढ़ने पर विधियाँ बदलनी चाहिए।"},
  {"id":"cdp-child-development-1812","question":"In cognitive load theory, which task carries the highest intrinsic load for a Class 7 student meeting it for the first time?","options":["Memorising the names of the eight planets in their order outward from the Sun","Learning the spellings of ten unrelated new words, one word at a time each day","Solving a two-step equation, where each step depends on keeping the others in mind","Learning the meanings of the Hindi names for the days of the week"],"answer":2,"explanation":"Intrinsic load depends on element interactivity: how many elements must be processed together. Word lists can be learnt item by item, but equation-solving requires several interacting elements at once.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"संज्ञानात्मक भार सिद्धांत में, कक्षा 7 के छात्र के लिए, जो इसका पहली बार सामना कर रहा है, कौन-सा कार्य सर्वाधिक आंतरिक भार वहन करता है?","optionsHi":["सूर्य से बाहर की ओर क्रम में आठ ग्रहों के नाम याद करना","प्रतिदिन एक शब्द के हिसाब से दस असंबद्ध नए शब्दों की वर्तनी सीखना","दो-चरण वाला समीकरण हल करना, जहाँ प्रत्येक चरण दूसरों को मन में रखने पर निर्भर करता है","सप्ताह के दिनों के हिंदी नामों के अर्थ सीखना"],"explanationHi":"आंतरिक भार तत्व-अंतःक्रियाशीलता पर निर्भर करता है: कितने तत्वों को एक साथ प्रक्रमित करना होता है। शब्द-सूचियाँ मद-दर-मद सीखी जा सकती हैं, पर समीकरण हल करने में एक साथ अनेक अंतःक्रियाशील तत्व चाहिए।"},
  {"id":"cdp-child-development-1813","question":"A teacher asks students to proofread an essay only for spelling mistakes. Most find every spelling error but miss a glaring factual error about a date. Which determinant of attention does this show most clearly?","options":["Mental set, the readiness to attend to what one expects or is looking for","Intensity, the strength of a stimulus such as a loud sound or bright colour","Novelty, the unusual or unexpected element in a situation","Movement, a change in position that draws the eye"],"answer":0,"explanation":"Mental (preparatory) set is a subjective determinant: the instruction tuned students to spelling, so other errors, though obvious, went unnoticed. The other options are objective features of the stimulus.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक छात्रों से एक निबंध को केवल वर्तनी की गलतियों के लिए जाँचने को कहता है। अधिकांश हर वर्तनी की त्रुटि पकड़ लेते हैं पर एक तिथि के बारे में स्पष्ट तथ्यात्मक त्रुटि चूक जाते हैं। यह ध्यान के किस निर्धारक को सबसे स्पष्ट रूप से दर्शाता है?","optionsHi":["मानसिक वृत्ति, उस पर ध्यान देने की तत्परता जिसकी अपेक्षा हो या जिसे खोजा जा रहा हो","तीव्रता, उद्दीपक की शक्ति जैसे तेज़ ध्वनि या चटक रंग","नवीनता, स्थिति में असामान्य या अप्रत्याशित तत्व","गति, स्थिति में परिवर्तन जो आँख को खींचता है"],"explanationHi":"मानसिक (प्रारंभिक) वृत्ति एक आत्मनिष्ठ निर्धारक है: निर्देश ने छात्रों को वर्तनी की ओर समस्वरित कर दिया, इसलिए अन्य त्रुटियाँ, स्पष्ट होते हुए भी, किसी का ध्यान नहीं गईं। अन्य विकल्प उद्दीपक की वस्तुनिष्ठ विशेषताएँ हैं।"},
  {"id":"cdp-child-development-1814","question":"Looking at a line drawing of a cube, a student finds that first one face seems to be in front and then, a few seconds later, another. This illustrates:","options":["The division of attention","The span of attention","The fluctuation of attention","The distraction of attention"],"answer":2,"explanation":"Attention cannot stay fixed on one interpretation for long; with reversible figures such as the Necker cube it alternates every few seconds even though the drawing does not change.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक घन के रेखाचित्र को देखते हुए, एक छात्र पाता है कि पहले एक फलक आगे दिखता है और फिर कुछ सेकंड बाद दूसरा। यह क्या दर्शाता है?","optionsHi":["ध्यान का विभाजन","ध्यान का विस्तार","ध्यान का उतार-चढ़ाव","ध्यान का विचलन"],"explanationHi":"ध्यान किसी एक व्याख्या पर देर तक स्थिर नहीं रह सकता; नेकर घन जैसी प्रतिवर्ती आकृतियों के साथ यह चित्र के न बदलने पर भी हर कुछ सेकंड में बदलता रहता है।"},
  {"id":"cdp-child-development-1815","question":"Which pair of activities is a Class 5 student most likely to carry out together with the least loss on either?","options":["Listening to a story read aloud while reading a different story silently","Listening to a story read aloud while colouring a simple familiar pattern","Silently reading a story while copying a different passage from the board","Listening to a story while also listening to a different story on a radio"],"answer":1,"explanation":"Divided attention is easiest when tasks use different modalities and codes and when one is practised and automatic. The other pairs compete for the same verbal or auditory resources (multiple-resource theory).","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 5 का छात्र किस जोड़ी की गतिविधियाँ एक साथ किसी पर भी न्यूनतम हानि के साथ करने की सबसे अधिक संभावना रखता है?","optionsHi":["ज़ोर से पढ़ी जा रही कहानी सुनना जबकि चुपचाप एक दूसरी कहानी पढ़ना","ज़ोर से पढ़ी जा रही कहानी सुनना जबकि एक सरल परिचित प्रतिरूप में रंग भरना","चुपचाप कहानी पढ़ना जबकि श्यामपट्ट से एक अलग अनुच्छेद उतारना","एक कहानी सुनना जबकि रेडियो पर एक दूसरी कहानी भी सुनना"],"explanationHi":"विभाजित ध्यान तब सबसे आसान होता है जब कार्य भिन्न माध्यमों और कूटों का उपयोग करते हैं और जब एक अभ्यस्त और स्वचालित हो। अन्य जोड़ियाँ एक ही शाब्दिक या श्रव्य संसाधनों के लिए प्रतिस्पर्धा करती हैं (बहु-संसाधन सिद्धांत)।"},
  {"id":"cdp-child-development-1816","question":"In a recorded lecture, one group of students gets a short quiz after each segment; the other group gets no quizzes until the end. Research on such interpolated testing found that the quizzed group mostly:","options":["Showed no differences, since they had heard the same lecture","Mind-wandered more, because the frequent quizzes made them anxious and distracted","Learnt more only of the quizzed segments and less of the rest","Mind-wandered less, took more notes and learnt more of the lecture"],"answer":3,"explanation":"Szpunar and colleagues found that brief quizzes between segments reduced mind-wandering, increased note-taking and improved final test performance, besides giving retrieval practice.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक रिकॉर्ड किए व्याख्यान में, छात्रों के एक समूह को प्रत्येक खंड के बाद एक छोटी प्रश्नोत्तरी मिलती है; दूसरे समूह को अंत तक कोई प्रश्नोत्तरी नहीं मिलती। ऐसे अंतर्विष्ट परीक्षण पर शोध ने पाया कि प्रश्नोत्तरी वाले समूह ने मुख्यतः:","optionsHi":["कोई अंतर नहीं दिखाया, क्योंकि उन्होंने वही व्याख्यान सुना था","अधिक मन-भटकाव किया, क्योंकि बार-बार की प्रश्नोत्तरियों ने उन्हें चिंतित और विचलित किया","केवल प्रश्नोत्तरी वाले खंड अधिक सीखे और शेष कम","कम मन-भटकाव किया, अधिक नोट्स लिए और व्याख्यान का अधिक सीखा"],"explanationHi":"स्ज़्पुनार और सहयोगियों ने पाया कि खंडों के बीच संक्षिप्त प्रश्नोत्तरियों ने मन-भटकाव घटाया, नोट-लेखन बढ़ाया और अंतिम परीक्षण का प्रदर्शन सुधारा, साथ ही पुनःप्राप्ति अभ्यास भी दिया।"},
  {"id":"cdp-child-development-1817","question":"Before a race, the starter says, ‘On your marks, get set…’, and runners become ready to respond. In Michael Posner’s model of attention networks, this preparation mainly involves the:","options":["Alerting network","Orienting network","Executive network","Default network"],"answer":0,"explanation":"Posner described three networks: alerting (achieving and keeping a ready state after a warning), orienting (selecting a location or input) and executive (resolving conflict and controlling responses). A warning signal engages alerting.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"दौड़ से पहले, प्रारंभकर्ता कहता है, ‘अपने स्थान पर, तैयार…’, और धावक प्रतिक्रिया के लिए तत्पर हो जाते हैं। माइकल पोस्नर के ध्यान-तंत्रिका-जाल मॉडल में, यह तैयारी मुख्यतः किसमें शामिल होती है?","optionsHi":["सचेतक जाल (अलर्टिंग नेटवर्क)","अनुस्थापन जाल (ओरिएंटिंग नेटवर्क)","कार्यकारी जाल (एक्ज़ीक्यूटिव नेटवर्क)","डिफ़ॉल्ट जाल (डिफ़ॉल्ट नेटवर्क)"],"explanationHi":"पोस्नर ने तीन जाल बताए: सचेतक (चेतावनी के बाद तत्पर अवस्था पाना और बनाए रखना), अनुस्थापन (स्थान या निवेश का चयन करना) और कार्यकारी (द्वंद्व सुलझाना और प्रतिक्रियाओं को नियंत्रित करना)। चेतावनी संकेत सचेतक जाल को संलग्न करता है।"},
  {"id":"cdp-child-development-1818","question":"A Class 3 teacher adds three-minute movement breaks between long periods of seated work. Classroom studies of such brief activity breaks generally found:","options":["No change, since attention depends only on the lesson","More off-task behaviour, as children stayed excited","More on-task behaviour in the lessons that followed","Better behaviour only on days with no outdoor games"],"answer":2,"explanation":"Studies of short in-class activity breaks, such as the ‘Energizers’ programme, reported more time on task after the breaks; young children’s sustained attention benefits from changes in activity.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की शिक्षिका लंबे बैठे कार्य की अवधियों के बीच तीन मिनट के गतिशील विराम जोड़ती है। ऐसे संक्षिप्त गतिविधि-विरामों पर कक्षा-अध्ययनों ने सामान्यतः क्या पाया?","optionsHi":["कोई बदलाव नहीं, क्योंकि ध्यान केवल पाठ पर निर्भर करता है","अधिक कार्य-इतर व्यवहार, क्योंकि बच्चे उत्तेजित बने रहे","उसके बाद के पाठों में अधिक कार्य-संलग्न व्यवहार","बेहतर व्यवहार केवल उन दिनों जब बाहरी खेल नहीं होते"],"explanationHi":"‘एनर्जाइज़र्स’ कार्यक्रम जैसे संक्षिप्त कक्षा-गतिविधि विरामों के अध्ययनों ने विरामों के बाद कार्य पर अधिक समय की सूचना दी; छोटे बच्चों के सतत ध्यान को गतिविधि में बदलाव से लाभ होता है।"},
  {"id":"cdp-child-development-1819","question":"Ms Rao asks the class, ‘Why does the moon seem to change shape?’, pauses while looking around the room, and only then names a student to answer. Jacob Kounin would call this:","options":["Withitness","Group alerting","Overlapping","The ripple effect"],"answer":1,"explanation":"Group alerting keeps the whole class attentive by posing the question before naming the responder, so everyone must think. Naming first lets the rest switch off.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"सुश्री राव कक्षा से पूछती हैं, ‘चंद्रमा का आकार बदलता हुआ क्यों लगता है?’, कमरे में चारों ओर देखते हुए रुकती हैं, और उसके बाद ही उत्तर देने के लिए किसी छात्र का नाम लेती हैं। जैकब कौनिन इसे क्या कहेंगे?","optionsHi":["सतर्कता-बोध (विदिटनेस)","समूह-सचेतन (ग्रुप अलर्टिंग)","अतिव्यापन (ओवरलैपिंग)","तरंग प्रभाव (रिपल इफ़ेक्ट)"],"explanationHi":"समूह-सचेतन उत्तर देने वाले का नाम लेने से पहले प्रश्न पूछकर पूरी कक्षा को सावधान रखता है, ताकि सभी को सोचना पड़े। पहले नाम लेने से बाकी लोग अलग हो जाते हैं।"},
  {"id":"cdp-child-development-1820","question":"Match Jacob Kounin’s classroom terms with their meanings. P. Withitness Q. Overlapping R. Smoothness S. Ripple effect 1. Handling two matters at once without dropping either 2. Moving between activities without abrupt breaks or digressions 3. A correction given to one student influences others who see it 4. Showing students that the teacher knows what is happening everywhere in the room","options":["P-4, Q-1, R-3, S-2","P-1, Q-4, R-2, S-3","P-4, Q-2, R-1, S-3","P-4, Q-1, R-2, S-3"],"answer":3,"explanation":"Kounin found that effective managers show withitness, overlap tasks, keep lessons smooth and maintain momentum; his early work also described the ripple effect of a teacher’s desists on onlookers.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"जैकब कौनिन के कक्षा संबंधी शब्दों का उनके अर्थों से मिलान कीजिए। P. सतर्कता-बोध Q. अतिव्यापन R. सुगमता S. तरंग प्रभाव 1. किसी को छोड़े बिना एक साथ दो मामलों को सँभालना 2. आकस्मिक विच्छेद या भटकाव के बिना गतिविधियों के बीच जाना 3. एक छात्र को दिया गया सुधार उसे देखने वाले अन्य छात्रों को प्रभावित करता है 4. छात्रों को दिखाना कि शिक्षक जानता है कि कमरे में हर जगह क्या हो रहा है","optionsHi":["P-4, Q-1, R-3, S-2","P-1, Q-4, R-2, S-3","P-4, Q-2, R-1, S-3","P-4, Q-1, R-2, S-3"],"explanationHi":"कौनिन ने पाया कि प्रभावी प्रबंधक सतर्कता-बोध दिखाते हैं, कार्यों का अतिव्यापन करते हैं, पाठ को सुगम रखते हैं और गति बनाए रखते हैं; उनके प्रारंभिक कार्य ने दर्शकों पर शिक्षक की रोक-टोक के तरंग प्रभाव का भी वर्णन किया।"},
  {"id":"cdp-child-development-1821","question":"A teacher wants one key value in a table of 40 numbers to be spotted instantly by every student. According to feature-integration research on visual search, the best design is to:","options":["Print that one value in a colour different from all the others","Print that value in a colour and font both shared with some other values","Put that value in the same style as the others but in the middle of the table","Repeat that value in several places in the table in the same style"],"answer":0,"explanation":"An item that differs from all others by a single feature ‘pops out’ almost regardless of the number of items; when it shares features with others (a conjunction), search becomes slow and item by item.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षिका चाहती है कि 40 संख्याओं की तालिका में एक मुख्य मान प्रत्येक छात्र को तुरंत दिख जाए। दृश्य खोज पर विशेषता-एकीकरण शोध के अनुसार, सर्वोत्तम डिज़ाइन है:","optionsHi":["उस एक मान को अन्य सभी से भिन्न रंग में छापना","उस मान को ऐसे रंग और फ़ॉन्ट में छापना जो कुछ अन्य मानों के साथ भी साझा हों","उस मान को अन्य के समान शैली में पर तालिका के बीच में रखना","उस मान को तालिका में कई स्थानों पर उसी शैली में दोहराना"],"explanationHi":"जो मद एक विशेषता से अन्य सभी से भिन्न होता है वह मदों की संख्या की परवाह किए बिना लगभग ‘उभर आता’ है; जब वह अन्य के साथ विशेषताएँ साझा करता है (संयोजन), खोज धीमी और मद-दर-मद हो जाती है।"},
  {"id":"cdp-child-development-1822","question":"A teacher underlines the key terms on a slide, adds headings such as ‘Cause’ and ‘Effect’, and points to each part of the diagram as she speaks about it. Which of Mayer’s multimedia principles is she mainly applying?","options":["Pre-training","Segmenting","Signalling","Personalisation"],"answer":2,"explanation":"Signalling adds cues that highlight the essential material and its organisation, guiding attention; segmenting splits a lesson into learner-paced parts, and pre-training teaches key names beforehand.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक शिक्षिका स्लाइड पर मुख्य शब्दों को रेखांकित करती है, ‘कारण’ और ‘प्रभाव’ जैसे शीर्षक जोड़ती है, और आरेख के प्रत्येक भाग की ओर संकेत करती है जब उसके बारे में बोलती है। वह मेयर के किस मल्टीमीडिया सिद्धांत को मुख्यतः लागू कर रही है?","optionsHi":["पूर्व-प्रशिक्षण","खंडीकरण","संकेतन","वैयक्तीकरण"],"explanationHi":"संकेतन आवश्यक सामग्री और उसके संगठन को उभारने वाले संकेत जोड़ता है, ध्यान को निर्देशित करता है; खंडीकरण पाठ को अधिगमकर्ता की गति वाले भागों में बाँटता है, और पूर्व-प्रशिक्षण पहले से मुख्य नाम सिखाता है।"},
  {"id":"cdp-child-development-1823","question":"Before showing a complex animation of how a bicycle pump works, a teacher first lets students handle the piston, inlet valve and outlet valve and learn what each part is called and does. Mayer would predict this helps because:","options":["Handling parts makes students more interested, and interest is what reduces cognitive load","Knowing the parts in advance frees working memory to follow how they interact in the animation","It replaces the animation, so students no longer need to watch the full sequence","It adds a second, practical modality, so the information enters memory twice"],"answer":1,"explanation":"This is the pre-training principle: when the main lesson is complex, learning the names and characteristics of key components first means learners can devote capacity to the causal sequence instead of identifying parts.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"साइकिल पंप कैसे काम करता है इसका जटिल एनिमेशन दिखाने से पहले, एक शिक्षक पहले छात्रों को पिस्टन, अंतर्गम वाल्व और निर्गम वाल्व को छूने देता है और सीखने देता है कि प्रत्येक भाग को क्या कहते हैं और वह क्या करता है। मेयर पूर्वानुमान करेंगे कि यह इसलिए सहायक है क्योंकि:","optionsHi":["भागों को छूने से छात्र अधिक रुचि लेते हैं, और रुचि ही संज्ञानात्मक भार को घटाती है","भागों को पहले से जानना कार्यकारी स्मृति को मुक्त करता है ताकि वे एनिमेशन में उनकी अंतःक्रिया का अनुसरण कर सकें","यह एनिमेशन का स्थान ले लेता है, इसलिए छात्रों को पूरा क्रम देखने की आवश्यकता नहीं रहती","यह एक दूसरा, व्यावहारिक माध्यम जोड़ता है, इसलिए सूचना स्मृति में दो बार प्रवेश करती है"],"explanationHi":"यह पूर्व-प्रशिक्षण सिद्धांत है: जब मुख्य पाठ जटिल हो, तो पहले प्रमुख घटकों के नाम और विशेषताएँ सीखने से अधिगमकर्ता भागों को पहचानने के बजाय कारण-संबंधी क्रम पर क्षमता लगा सकते हैं।"},
  {"id":"cdp-child-development-1824","question":"A long animated explanation of the water cycle plays straight through without pause, and many students lose track. Which change applies Mayer’s segmenting principle?","options":["Playing the whole animation twice in a row without stopping","Adding on-screen text that repeats every word of the narration","Adding background music throughout to keep students attentive and alert","Breaking it into short parts that students advance at their own pace"],"answer":3,"explanation":"Segmenting divides a continuous lesson into learner-paced chunks so each part can be processed before the next arrives; adding repeated text or music increases load rather than reducing it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"जल चक्र की एक लंबी एनिमेटेड व्याख्या बिना रुके सीधे चलती है, और अनेक छात्र सूत्र खो देते हैं। कौन-सा परिवर्तन मेयर के खंडीकरण सिद्धांत को लागू करता है?","optionsHi":["पूरे एनिमेशन को बिना रुके लगातार दो बार चलाना","स्क्रीन पर ऐसा पाठ जोड़ना जो कथन के हर शब्द को दोहराए","छात्रों को सतर्क और जागृत रखने के लिए पूरे समय पृष्ठभूमि संगीत जोड़ना","इसे छोटे भागों में तोड़ना जिन्हें छात्र अपनी गति से आगे बढ़ाएँ"],"explanationHi":"खंडीकरण एक सतत पाठ को अधिगमकर्ता-गति वाले खंडों में बाँटता है ताकि अगला आने से पहले प्रत्येक भाग का प्रक्रमण हो सके; दोहराया पाठ या संगीत जोड़ना भार घटाने के बजाय बढ़ाता है।"},
  {"id":"cdp-child-development-1825","question":"According to Easterbrook’s cue-utilisation hypothesis, a very anxious student taking a complex reasoning test is likely to:","options":["Narrow attention to fewer cues, which can make him miss information the problem needs","Widen attention to more cues, which overloads him with irrelevant details","Attend to cues normally but recall them less well afterwards","Attend better to every single cue, since anxiety always sharpens a student’s focus"],"answer":0,"explanation":"Easterbrook proposed that rising arousal shrinks the range of cues used. On simple tasks dropping irrelevant cues can help, but on complex tasks relevant peripheral cues are lost too, so performance falls.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"ईस्टरब्रुक की संकेत-उपयोग परिकल्पना के अनुसार, जटिल तर्क परीक्षण देने वाला अत्यंत चिंतित छात्र संभवतः:","optionsHi":["ध्यान को कम संकेतों तक संकुचित कर लेगा, जिससे वह समस्या के लिए आवश्यक जानकारी चूक सकता है","ध्यान को अधिक संकेतों तक फैला देगा, जिससे वह अप्रासंगिक विवरणों से अभिभूत हो जाएगा","संकेतों पर सामान्य रूप से ध्यान देगा, पर बाद में उन्हें कम अच्छी तरह याद करेगा","प्रत्येक संकेत पर बेहतर ध्यान देगा, क्योंकि चिंता सदैव छात्र के ध्यान को तीक्ष्ण करती है"],"explanationHi":"ईस्टरब्रुक ने प्रस्तावित किया कि बढ़ती उत्तेजना प्रयुक्त संकेतों के दायरे को सिकोड़ती है। सरल कार्यों पर अप्रासंगिक संकेतों का छूटना सहायक हो सकता है, पर जटिल कार्यों पर प्रासंगिक परिधीय संकेत भी छूट जाते हैं, इसलिए प्रदर्शन गिरता है।"},
  {"id":"cdp-child-development-1826","question":"Divers who learnt word lists underwater recalled them better underwater, and those who learnt on land recalled better on land. A Class 10 student always revises in her quiet bedroom but takes board exams in a noisy hall. Which advice follows best from this research?","options":["Revise in a few varied places and, in the hall, mentally recall the setting where she studied","Revise only in the bedroom, since one familiar, quiet setting always makes memories strongest","Revise only in the exam hall, since recall depends on nothing but the testing place","Ignore study settings, since context effects on memory appear only in unusual places such as underwater"],"answer":0,"explanation":"Encoding specificity means retrieval is best when cues present at learning are present at testing. Varying study contexts makes memories less tied to one place, and mentally reinstating the study context recovers some of its cues.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"जिन गोताखोरों ने शब्द-सूचियाँ पानी के नीचे सीखीं उन्होंने उन्हें पानी के नीचे बेहतर याद किया, और जिन्होंने ज़मीन पर सीखीं उन्होंने ज़मीन पर बेहतर। कक्षा 10 की एक छात्रा सदैव अपने शांत शयनकक्ष में पुनरावृत्ति करती है पर बोर्ड परीक्षाएँ शोरगुल वाले हॉल में देती है। इस शोध से कौन-सी सलाह सबसे अच्छी तरह निकलती है?","optionsHi":["कुछ भिन्न स्थानों पर पुनरावृत्ति करें और हॉल में, उस परिवेश को मानसिक रूप से याद करें जहाँ उसने पढ़ा था","केवल शयनकक्ष में पुनरावृत्ति करें, क्योंकि एक परिचित, शांत परिवेश सदैव स्मृतियों को सबसे सुदृढ़ बनाता है","केवल परीक्षा-हॉल में पुनरावृत्ति करें, क्योंकि स्मरण परीक्षण-स्थान के अलावा किसी पर निर्भर नहीं करता","अध्ययन-परिवेशों की अनदेखी करें, क्योंकि स्मृति पर संदर्भ-प्रभाव केवल पानी के नीचे जैसे असामान्य स्थानों में प्रकट होते हैं"],"explanationHi":"संकेतन-विशिष्टता का अर्थ है कि पुनःप्राप्ति तब सबसे अच्छी होती है जब सीखते समय उपस्थित संकेत परीक्षण के समय भी उपस्थित हों। अध्ययन-संदर्भों में विविधता स्मृतियों को एक स्थान से कम बाँधती है, और अध्ययन-संदर्भ को मानसिक रूप से पुनः स्थापित करना उसके कुछ संकेत वापस दिलाता है।"},
  {"id":"cdp-child-development-1827","question":"To prepare for a science test a month away, Kavya studies three hours on one Sunday, while Arif studies one hour on each of three Sundays. If both learn the same material, what does research on the spacing effect predict for the test?","options":["Kavya will remember more, because one long session builds deeper concentration","Arif will remember more, because spaced sessions give better long-term retention","Both will remember the same, because total study time is what decides retention","Kavya will remember more, because her learning ended closer to the test"],"answer":1,"explanation":"For the same total time, distributed practice gives better long-term retention than massed practice; Kavya’s session actually ended earlier, not later, than Arif’s last session.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक महीने बाद होने वाले विज्ञान परीक्षण की तैयारी के लिए, काव्या एक रविवार तीन घंटे पढ़ती है, जबकि आरिफ़ तीन रविवारों में प्रत्येक पर एक घंटा पढ़ता है। यदि दोनों समान सामग्री सीखते हैं, तो अंतराल प्रभाव पर शोध परीक्षण के लिए क्या पूर्वानुमान करता है?","optionsHi":["काव्या अधिक याद रखेगी, क्योंकि एक लंबा सत्र गहरी एकाग्रता बनाता है","आरिफ़ अधिक याद रखेगा, क्योंकि अंतराल वाले सत्र बेहतर दीर्घकालिक धारण देते हैं","दोनों समान याद रखेंगे, क्योंकि कुल अध्ययन समय ही धारण तय करता है","काव्या अधिक याद रखेगी, क्योंकि उसका अधिगम परीक्षण के अधिक निकट समाप्त हुआ"],"explanationHi":"समान कुल समय के लिए, वितरित अभ्यास केंद्रित अभ्यास की तुलना में बेहतर दीर्घकालिक धारण देता है; काव्या का सत्र वास्तव में आरिफ़ के अंतिम सत्र से बाद में नहीं, पहले समाप्त हुआ।"},
  {"id":"cdp-child-development-1828","question":"Group A practises volume problems for cubes, then for cylinders, then for cones, each block separately. Group B practises the same problems mixed in random order. Group B scores lower during practice but much higher on a test a week later. The best explanation is that mixing:","options":["Lets students memorise each formula in its own block first, before applying it in mixed tests later","Gives students more problems to solve in the same time, so they get more total practice","Makes practice easier, so that students feel confident and try harder on the test","Forces students to choose the right method for each problem, which blocked practice lets them skip"],"answer":3,"explanation":"Interleaved practice requires learners to discriminate problem types and select a strategy each time, as a test does; blocked practice tells them the method in advance. Rohrer and Taylor found exactly this pattern of lower practice but higher delayed scores.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"समूह A घन के आयतन के प्रश्नों का अभ्यास करता है, फिर बेलन के, फिर शंकु के, प्रत्येक खंड अलग-अलग। समूह B वही प्रश्न यादृच्छिक क्रम में मिलाकर अभ्यास करता है। समूह B अभ्यास के दौरान कम अंक पाता है पर एक सप्ताह बाद के परीक्षण में कहीं अधिक। सबसे अच्छी व्याख्या यह है कि मिलाना:","optionsHi":["छात्रों को पहले प्रत्येक सूत्र अपने खंड में याद करने देता है, बाद में मिश्रित परीक्षणों में लागू करने से पहले","छात्रों को उसी समय में अधिक प्रश्न हल करने देता है, इसलिए उन्हें कुल अधिक अभ्यास मिलता है","अभ्यास को आसान बनाता है, ताकि छात्र आत्मविश्वासी महसूस करें और परीक्षण में अधिक प्रयास करें","छात्रों को प्रत्येक प्रश्न के लिए सही विधि चुनने को बाध्य करता है, जिसे खंडित अभ्यास उन्हें छोड़ देने देता है"],"explanationHi":"अंतर्ग्रथित (इंटरलीव्ड) अभ्यास अधिगमकर्ताओं से प्रश्न-प्रकारों में भेद करने और हर बार रणनीति चुनने की माँग करता है, जैसा परीक्षण करता है; खंडित अभ्यास उन्हें विधि पहले से बता देता है। रोहरर और टेलर ने ठीक यही कम अभ्यास-अंक पर अधिक विलंबित अंक का प्रतिरूप पाया।"},
  {"id":"cdp-child-development-1829","question":"Assertion (A): Practice that makes learning feel slower and harder, such as spacing sessions and testing oneself, often produces better long-term retention than easy re-reading. Reason (R): Conditions that make performance during learning look best are always the conditions that make long-term learning best.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Robert Bjork called these ‘desirable difficulties’: they lower immediate performance but strengthen durable learning. R is false precisely because performance during learning is a poor guide to long-term learning.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"अभिकथन (A): ऐसा अभ्यास जो अधिगम को धीमा और कठिन महसूस कराता है, जैसे सत्रों में अंतराल रखना और स्वयं को परखना, प्रायः आसान पुनः पठन की तुलना में बेहतर दीर्घकालिक धारण उत्पन्न करता है। कारण (R): जो परिस्थितियाँ अधिगम के दौरान प्रदर्शन को सबसे अच्छा दिखाती हैं वे सदैव वही परिस्थितियाँ होती हैं जो दीर्घकालिक अधिगम को सबसे अच्छा बनाती हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"रॉबर्ट बजोर्क ने इन्हें ‘वांछनीय कठिनाइयाँ’ कहा: ये तात्कालिक प्रदर्शन घटाती हैं पर टिकाऊ अधिगम को सुदृढ़ करती हैं। R असत्य है ठीक इसलिए कि अधिगम के दौरान प्रदर्शन दीर्घकालिक अधिगम का खराब मार्गदर्शक है।"},
  {"id":"cdp-child-development-1830","question":"One group of students reads word pairs like ‘hot–cold’; another sees ‘hot–c_ _ _’ and must complete the second word. On a later memory test, the second group usually recalls more words. This is called the:","options":["Generation effect","Testing effect","Spacing effect","Von Restorff effect"],"answer":0,"explanation":"Producing information oneself, even with a small effort, leads to better memory than reading it; the testing effect is specifically retrieval of previously learnt material, and the von Restorff effect concerns a distinctive item.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"छात्रों का एक समूह ‘hot–cold’ जैसे शब्द-युग्म पढ़ता है; दूसरा ‘hot–c_ _ _’ देखता है और दूसरा शब्द पूरा करना होता है। बाद की स्मृति-परीक्षा में, दूसरा समूह प्रायः अधिक शब्द याद करता है। इसे क्या कहते हैं?","optionsHi":["सृजन प्रभाव (जनरेशन इफ़ेक्ट)","परीक्षण प्रभाव","अंतराल प्रभाव","वॉन रेस्टोर्फ़ प्रभाव"],"explanationHi":"सूचना को स्वयं उत्पन्न करना, थोड़े प्रयास से भी, उसे पढ़ने की तुलना में बेहतर स्मृति की ओर ले जाता है; परीक्षण प्रभाव विशेष रूप से पहले सीखी सामग्री की पुनःप्राप्ति है, और वॉन रेस्टोर्फ़ प्रभाव एक विशिष्ट मद से संबंधित है।"},
  {"id":"cdp-child-development-1831","question":"Match each memory aid with an example. P. Method of loci Q. Acronym R. Acrostic S. Peg-word method 1. ‘VIBGYOR’ for the colours of the spectrum 2. ‘My Very Educated Mother Just Served Us Nachos’ for the planets 3. Imagining each item of a list placed at a spot along the route from home to school 4. Linking each item to a memorised rhyme such as ‘one is a bun, two is a shoe’","options":["P-3, Q-1, R-4, S-2","P-4, Q-1, R-2, S-3","P-3, Q-2, R-1, S-4","P-3, Q-1, R-2, S-4"],"answer":3,"explanation":"Loci uses familiar places along a route; an acronym makes a word from first letters; an acrostic makes a sentence from them; the peg-word method hangs items on a pre-learnt rhyming list.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"प्रत्येक स्मृति-सहायक का मिलान एक उदाहरण से कीजिए। P. स्थान-विधि (मेथड ऑफ़ लोकाई) Q. संक्षिप्ति (एक्रोनिम) R. वाक्य-संक्षेप (एक्रोस्टिक) S. खूँटी-शब्द विधि (पेग-वर्ड मेथड) 1. वर्णक्रम के रंगों के लिए ‘VIBGYOR’ 2. ग्रहों के लिए ‘My Very Educated Mother Just Served Us Nachos’ 3. सूची की प्रत्येक मद को घर से विद्यालय के मार्ग पर एक स्थान पर रखी कल्पना करना 4. प्रत्येक मद को याद की गई तुकबंदी जैसे ‘one is a bun, two is a shoe’ से जोड़ना","optionsHi":["P-3, Q-1, R-4, S-2","P-4, Q-1, R-2, S-3","P-3, Q-2, R-1, S-4","P-3, Q-1, R-2, S-4"],"explanationHi":"स्थान-विधि मार्ग के परिचित स्थानों का उपयोग करती है; संक्षिप्ति प्रथम अक्षरों से एक शब्द बनाती है; वाक्य-संक्षेप उनसे एक वाक्य बनाता है; खूँटी-शब्द विधि मदों को पहले से सीखी तुकबंदी वाली सूची पर टाँगती है।"},
  {"id":"cdp-child-development-1832","question":"Which order correctly ranks the three methods of measuring retention from the most sensitive (detecting the faintest traces) to the least sensitive?","options":["Recall, recognition, relearning (savings)","Relearning (savings), recognition, recall","Recognition, recall, relearning (savings)","Relearning (savings), recall, recognition"],"answer":1,"explanation":"Material that cannot be recalled may still be recognised, and material that can no longer be recognised may still be relearnt faster than the first time, as Ebbinghaus’s savings method showed.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"धारण को मापने की तीन विधियों को सर्वाधिक संवेदी (सबसे धुँधले चिह्न पहचानने वाली) से न्यूनतम संवेदी तक सही क्रम में कौन-सा क्रम रखता है?","optionsHi":["स्मरण, पहचान, पुनः अधिगम (बचत)","पुनः अधिगम (बचत), पहचान, स्मरण","पहचान, स्मरण, पुनः अधिगम (बचत)","पुनः अधिगम (बचत), स्मरण, पहचान"],"explanationHi":"जो सामग्री याद नहीं की जा सकती वह फिर भी पहचानी जा सकती है, और जो सामग्री अब पहचानी नहीं जा सकती वह भी पहली बार की तुलना में तेज़ी से पुनः सीखी जा सकती है, जैसा एबिंगहॉस की बचत विधि ने दिखाया।"},
  {"id":"cdp-child-development-1833","question":"Asked the name of the scientist who discovered penicillin, Rohan says, ‘It starts with F… two syllables… it’s on the tip of my tongue!’ Research on this state shows that:","options":["The word was never stored in long-term memory, only in sensory memory","The word has been completely lost from long-term memory and must now be learnt all over again","Partial information about the word, such as its first letter or length, is often available","The state is caused by low intelligence and seldom happens to people who speak fluently"],"answer":2,"explanation":"Brown and McNeill showed that in the tip-of-the-tongue state people can often report the first letter, number of syllables or similar-sounding words, so the problem is retrieval, not storage.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"यह पूछे जाने पर कि पेनिसिलिन खोजने वाले वैज्ञानिक का नाम क्या है, रोहन कहता है, ‘यह F से शुरू होता है… दो अक्षरांश… यह मेरी ज़ुबान पर है!’ इस अवस्था पर शोध दर्शाता है कि:","optionsHi":["शब्द दीर्घकालिक स्मृति में कभी संचित ही नहीं हुआ, केवल संवेदी स्मृति में हुआ","शब्द दीर्घकालिक स्मृति से पूरी तरह खो गया है और अब उसे फिर से सीखना होगा","शब्द के बारे में आंशिक जानकारी, जैसे उसका पहला अक्षर या लंबाई, प्रायः उपलब्ध होती है","यह अवस्था निम्न बुद्धि के कारण होती है और धाराप्रवाह बोलने वालों के साथ शायद ही कभी होती है"],"explanationHi":"ब्राउन और मैकनील ने दिखाया कि ज़ुबान पर होने की अवस्था में लोग प्रायः पहला अक्षर, अक्षरांशों की संख्या या मिलते-जुलते शब्द बता सकते हैं, इसलिए समस्या पुनःप्राप्ति की है, संचयन की नहीं।"},
  {"id":"cdp-child-development-1834","question":"A teacher stops an exciting story just before the climax at the end of the period. Next day, children remember the unfinished story in rich detail. Which effect is this?","options":["The Zeigarnik effect","The primacy effect","The von Restorff effect","The overjustification effect"],"answer":0,"explanation":"Bluma Zeigarnik found that interrupted, unfinished tasks are recalled better than completed ones, as the open goal keeps the material active; primacy concerns items at the start of a list.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक पीरियड के अंत में एक रोमांचक कहानी को चरमोत्कर्ष से ठीक पहले रोक देता है। अगले दिन बच्चे अधूरी कहानी को समृद्ध विवरण में याद रखते हैं। यह कौन-सा प्रभाव है?","optionsHi":["ज़ीगार्निक प्रभाव","प्राथमिकता प्रभाव","वॉन रेस्टोर्फ़ प्रभाव","अतिऔचित्य प्रभाव"],"explanationHi":"ब्लूमा ज़ीगार्निक ने पाया कि बाधित, अधूरे कार्य पूरे किए गए कार्यों की तुलना में बेहतर याद रहते हैं, क्योंकि खुला लक्ष्य सामग्री को सक्रिय रखता है; प्राथमिकता सूची के आरंभ की मदों से संबंधित है।"},
  {"id":"cdp-child-development-1835","question":"Having learnt the multiplication table of 13 until he can recite it once without error, Abhay keeps practising it for a few more days. What does research on overlearning predict?","options":["He will forget it faster, because extra practice after mastery causes boredom and interference","He will forget it more slowly, though each extra round of practice adds less benefit than the one before","He will gain nothing, because once material is mastered further practice cannot strengthen it","He will gain more from each additional round than from the first, so practice should continue indefinitely"],"answer":1,"explanation":"Practice beyond first mastery strengthens retention, as Krueger showed, but with diminishing returns; spacing the extra practice over time is especially useful.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"13 का पहाड़ा तब तक सीखने के बाद जब वह उसे बिना त्रुटि एक बार सुना सकता है, अभय उसे कुछ और दिन अभ्यास करता रहता है। अतिअधिगम पर शोध क्या पूर्वानुमान करता है?","optionsHi":["वह इसे तेज़ी से भूलेगा, क्योंकि निपुणता के बाद अतिरिक्त अभ्यास ऊब और व्यतिकरण उत्पन्न करता है","वह इसे अधिक धीरे भूलेगा, यद्यपि अभ्यास का प्रत्येक अतिरिक्त चक्र पिछले से कम लाभ जोड़ता है","वह कुछ नहीं पाएगा, क्योंकि एक बार सामग्री में निपुणता पाने के बाद आगे का अभ्यास उसे सुदृढ़ नहीं कर सकता","वह पहले चक्र की तुलना में प्रत्येक अतिरिक्त चक्र से अधिक लाभ पाएगा, इसलिए अभ्यास अनिश्चित काल तक जारी रहना चाहिए"],"explanationHi":"पहली निपुणता से आगे का अभ्यास धारण को सुदृढ़ करता है, जैसा क्रूगर ने दिखाया, पर घटते प्रतिफल के साथ; अतिरिक्त अभ्यास को समय पर फैलाना विशेष रूप से उपयोगी है।"},
  {"id":"cdp-child-development-1836","question":"A Class 6 student must learn a 40-line poem whose stanzas tell one connected story. Which method is generally best for him?","options":["Learn the last stanza first so that recency helps him finish confidently","Learn it strictly one line at a time, never looking ahead until each line is perfect","Read it through as a whole for its meaning, then give extra practice to the hard stanzas","Read it in a fixed order once a day without attending to its meaning"],"answer":2,"explanation":"For meaningful, connected material the whole method preserves the links between parts, while extra attention to difficult sections (a combined or progressive approach) handles long passages; pure line-by-line learning loses the structure.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 6 के एक छात्र को 40 पंक्तियों की एक कविता सीखनी है जिसके छंद एक जुड़ी हुई कहानी कहते हैं। उसके लिए सामान्यतः कौन-सी विधि सर्वश्रेष्ठ है?","optionsHi":["अंतिम छंद पहले सीखना ताकि अंतिमता प्रभाव उसे आत्मविश्वास से समाप्त करने में सहायता करे","इसे कड़ाई से एक-एक पंक्ति करके सीखना, जब तक प्रत्येक पंक्ति पूर्ण न हो आगे न देखना","इसे अर्थ के लिए पूरा एक बार पढ़ना, फिर कठिन छंदों का अतिरिक्त अभ्यास करना","इसे अर्थ पर ध्यान दिए बिना, प्रतिदिन एक बार निश्चित क्रम में पढ़ना"],"explanationHi":"अर्थपूर्ण, जुड़ी सामग्री के लिए पूर्ण विधि भागों के बीच संबंधों को बनाए रखती है, जबकि कठिन खंडों पर अतिरिक्त ध्यान (संयुक्त या प्रगामी उपागम) लंबे अंशों को सँभालता है; शुद्ध पंक्ति-दर-पंक्ति अधिगम संरचना खो देता है।"},
  {"id":"cdp-child-development-1837","question":"Students who are made to feel sad recall more sad events from a story they read, while happy students recall more happy events. Gordon Bower described this as:","options":["Retroactive interference","Repression","Encoding failure","Mood-congruent memory"],"answer":3,"explanation":"Mood-congruent memory is the tendency to encode and retrieve material that matches one’s current mood; repression is a Freudian motivated forgetting of threatening material, which does not explain the symmetrical pattern.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"जिन छात्रों को उदास महसूस कराया जाता है वे पढ़ी गई कहानी की अधिक उदास घटनाएँ याद करते हैं, जबकि प्रसन्न छात्र अधिक प्रसन्न घटनाएँ याद करते हैं। गॉर्डन बॉवर ने इसे क्या कहा?","optionsHi":["पश्चोन्मुख व्यतिकरण","दमन","कूटन विफलता","मनोदशा-संगत स्मृति"],"explanationHi":"मनोदशा-संगत स्मृति उस सामग्री को कूटित और पुनःप्राप्त करने की प्रवृत्ति है जो अपनी वर्तमान मनोदशा से मेल खाती है; दमन खतरनाक सामग्री का फ्रायडीय प्रेरित विस्मरण है, जो सममित प्रतिरूप की व्याख्या नहीं करता।"},
  {"id":"cdp-child-development-1838","question":"Students judge a list of adjectives in three ways: whether each is printed in capitals, whether it rhymes with another word, or whether it describes themselves. On a surprise test, which group recalls the most adjectives?","options":["Those who judged whether each word described themselves","Those who judged whether each word rhymed with another","Those who judged whether each word was in capital letters","All three groups recall equally, since they saw the same words"],"answer":0,"explanation":"Rogers and colleagues found a self-reference effect: relating material to oneself is a very deep, elaborative way of encoding, beyond semantic or sound-based judgements.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"छात्र विशेषणों की एक सूची का तीन प्रकार से निर्णय करते हैं: क्या प्रत्येक बड़े अक्षरों में छपा है, क्या वह किसी अन्य शब्द के साथ तुक मिलाता है, या क्या वह स्वयं का वर्णन करता है। एक औचक परीक्षण में, कौन-सा समूह सबसे अधिक विशेषण याद करता है?","optionsHi":["वे जिन्होंने निर्णय किया कि प्रत्येक शब्द उनका वर्णन करता है या नहीं","वे जिन्होंने निर्णय किया कि प्रत्येक शब्द किसी अन्य के साथ तुक मिलाता है या नहीं","वे जिन्होंने निर्णय किया कि प्रत्येक शब्द बड़े अक्षरों में है या नहीं","तीनों समूह समान याद करते हैं, क्योंकि उन्होंने वही शब्द देखे थे"],"explanationHi":"रॉजर्स और सहयोगियों ने स्व-संदर्भ प्रभाव पाया: सामग्री को अपने से जोड़ना कूटन का बहुत गहरा, विस्तारात्मक तरीका है, जो अर्थगत या ध्वनि-आधारित निर्णयों से भी आगे है।"},
  {"id":"cdp-child-development-1839","question":"While reading that ‘camels can go many days without drinking water’, a student asks herself, ‘Why would that be true for a camel?’ and answers using what she knows about deserts and fat stores. This strategy is called:","options":["Maintenance rehearsal","Elaborative interrogation","Self-testing by retrieval practice","Interleaved practice"],"answer":1,"explanation":"Elaborative interrogation prompts learners to explain why a fact is true, linking it to prior knowledge; maintenance rehearsal merely repeats, and retrieval practice recalls material without the text.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"यह पढ़ते हुए कि ‘ऊँट बिना पानी पिए कई दिन रह सकते हैं’, एक छात्रा स्वयं से पूछती है, ‘ऊँट के लिए यह सच क्यों होगा?’ और रेगिस्तानों तथा वसा-भंडारों के बारे में जो वह जानती है उसका प्रयोग करके उत्तर देती है। इस रणनीति को क्या कहते हैं?","optionsHi":["अनुरक्षण पुनरावृत्ति","विस्तारात्मक प्रश्न-पूछन (एलैबोरेटिव इंटरोगेशन)","पुनःप्राप्ति अभ्यास द्वारा स्व-परीक्षण","अंतर्ग्रथित अभ्यास"],"explanationHi":"विस्तारात्मक प्रश्न-पूछन अधिगमकर्ताओं को समझाने के लिए प्रेरित करता है कि कोई तथ्य क्यों सच है, उसे पूर्व ज्ञान से जोड़ता हुआ; अनुरक्षण पुनरावृत्ति केवल दोहराती है, और पुनःप्राप्ति अभ्यास पाठ के बिना सामग्री याद करता है।"},
  {"id":"cdp-child-development-1840","question":"In a large review by Dunlosky and colleagues, which study techniques were rated as having high usefulness for students across many conditions? I. Practice testing II. Distributed practice III. Highlighting and underlining IV. Re-reading","options":["II and III only","I, II and IV only","I and II only","I, III and IV only"],"answer":2,"explanation":"The review rated practice testing and distributed practice as high utility; highlighting and re-reading were rated low because they give little benefit beyond simple reading.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"डनलॉस्की और सहयोगियों की एक बड़ी समीक्षा में, कौन-सी अध्ययन तकनीकों को अनेक परिस्थितियों में छात्रों के लिए उच्च उपयोगिता वाला आँका गया? I. अभ्यास परीक्षण II. वितरित अभ्यास III. हाइलाइट करना और रेखांकित करना IV. पुनः पठन","optionsHi":["केवल II और III","केवल I, II और IV","केवल I और II","केवल I, III और IV"],"explanationHi":"समीक्षा ने अभ्यास परीक्षण और वितरित अभ्यास को उच्च उपयोगिता वाला आँका; हाइलाइट करने और पुनः पठन को निम्न आँका गया क्योंकि वे साधारण पठन से आगे बहुत कम लाभ देते हैं।"},
  {"id":"cdp-child-development-1841","question":"Reena keeps forgetting to bring her signed permission slip for the school trip, though she knows the trip details perfectly. Her lapse is mainly a failure of:","options":["Procedural memory","Episodic memory","Semantic memory","Prospective memory"],"answer":3,"explanation":"Prospective memory is remembering to carry out an intended action in the future; her memory for past facts and events about the trip is intact.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"रीना विद्यालय यात्रा के लिए अपनी हस्ताक्षरित अनुमति-पर्ची लाना बार-बार भूल जाती है, यद्यपि वह यात्रा का विवरण पूरी तरह जानती है। उसकी चूक मुख्यतः किसकी विफलता है?","optionsHi":["प्रक्रियात्मक स्मृति","घटनात्मक स्मृति","अर्थगत स्मृति","प्रत्याशित स्मृति"],"explanationHi":"प्रत्याशित स्मृति भविष्य में किसी इच्छित कार्य को करना याद रखना है; यात्रा के बारे में अतीत के तथ्यों और घटनाओं की उसकी स्मृति अक्षुण्ण है।"},
  {"id":"cdp-child-development-1842","question":"Shown ten pictures, most pre-schoolers predict they will remember all ten, but they actually recall only three or four; older children predict much more accurately. This study by Flavell and colleagues shows the development of:","options":["Metamemory","Rehearsal","Recognition memory","Memory span"],"answer":0,"explanation":"Metamemory is knowledge about one’s own memory and its limits. Young children greatly overestimate how much they will remember, which partly explains why they do not use strategies to help themselves.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"दस चित्र दिखाए जाने पर, अधिकांश पूर्व-विद्यालयी बच्चे पूर्वानुमान करते हैं कि वे सभी दस याद रखेंगे, पर वास्तव में केवल तीन या चार याद करते हैं; बड़े बच्चे कहीं अधिक सटीक पूर्वानुमान करते हैं। फ्लेवेल और सहयोगियों का यह अध्ययन किसके विकास को दर्शाता है?","optionsHi":["अधिसंज्ञान (मेटामेमोरी)","पुनरावृत्ति","पहचान स्मृति","स्मृति विस्तार"],"explanationHi":"मेटामेमोरी अपनी स्मृति और उसकी सीमाओं के बारे में ज्ञान है। छोटे बच्चे बहुत अधिक अनुमान लगाते हैं कि वे कितना याद रखेंगे, जो आंशिक रूप से समझाता है कि वे स्वयं की सहायता के लिए रणनीतियों का उपयोग क्यों नहीं करते।"},
  {"id":"cdp-child-development-1843","question":"After reading a chapter three times, Neha feels she ‘knows it perfectly’ because it now reads so easily, but she scores poorly on a test. The most likely explanation is that:","options":["Re-reading three times was too much and caused interference among the many facts in the chapter","Familiarity from re-reading created an illusion of knowing without testing her ability to retrieve it","She forgot the chapter because it was read in a different room from the test","Her feeling of knowing was accurate, so the test must have been unfair or badly set"],"answer":1,"explanation":"Fluent re-reading makes material feel familiar, which learners mistake for mastery; self-testing reveals what can actually be retrieved and also strengthens it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक अध्याय को तीन बार पढ़ने के बाद, नेहा महसूस करती है कि वह उसे ‘पूरी तरह जानती है’ क्योंकि वह अब बहुत आसानी से पढ़ा जाता है, पर वह परीक्षण में खराब अंक पाती है। सबसे संभावित व्याख्या यह है कि:","optionsHi":["तीन बार पुनः पढ़ना बहुत अधिक था और उसने अध्याय के अनेक तथ्यों के बीच व्यतिकरण उत्पन्न किया","पुनः पठन से उत्पन्न परिचितता ने उसकी पुनःप्राप्ति क्षमता को परखे बिना जानने का भ्रम पैदा किया","वह अध्याय भूल गई क्योंकि वह परीक्षण से अलग कमरे में पढ़ा गया था","उसकी जानने की अनुभूति सटीक थी, इसलिए परीक्षण अनुचित या खराब बनाया गया होगा"],"explanationHi":"धाराप्रवाह पुनः पठन सामग्री को परिचित महसूस कराता है, जिसे अधिगमकर्ता निपुणता समझ लेते हैं; स्व-परीक्षण प्रकट करता है कि वास्तव में क्या पुनःप्राप्त किया जा सकता है और उसे सुदृढ़ भी करता है।"},
  {"id":"cdp-child-development-1844","question":"Most adults remember almost nothing from before about the age of three. Which explanation is best supported?","options":["Infants cannot learn anything before three, since they cannot form any memories","Infants store everything but repress all early memories to protect themselves from anxiety","Brain systems and the self-concept and language used to organise lasting memories are still immature","Early memories are perfectly stored but are lost when children start school"],"answer":2,"explanation":"Infants clearly learn and remember in the short term; childhood (infantile) amnesia is explained by the immaturity of brain structures such as the hippocampus and by the late development of a self-concept and language for organising autobiographical memories.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अधिकांश वयस्क लगभग तीन वर्ष की आयु से पहले का लगभग कुछ भी याद नहीं रखते। कौन-सी व्याख्या सबसे अच्छी तरह समर्थित है?","optionsHi":["शिशु तीन वर्ष से पहले कुछ भी नहीं सीख सकते, क्योंकि वे कोई स्मृति नहीं बना सकते","शिशु सब कुछ संचित करते हैं पर चिंता से स्वयं को बचाने के लिए सभी प्रारंभिक स्मृतियों का दमन कर देते हैं","मस्तिष्क-तंत्र तथा स्थायी स्मृतियों को संगठित करने वाले आत्म-संप्रत्यय और भाषा अभी अपरिपक्व हैं","प्रारंभिक स्मृतियाँ पूर्ण रूप से संचित होती हैं पर बच्चों के विद्यालय शुरू करते ही खो जाती हैं"],"explanationHi":"शिशु स्पष्टतः अल्पकाल में सीखते और याद रखते हैं; बाल्यकालीन (शैशवी) विस्मृति की व्याख्या हिप्पोकैम्पस जैसी मस्तिष्क संरचनाओं की अपरिपक्वता और आत्मकथात्मक स्मृतियों को संगठित करने के लिए आत्म-संप्रत्यय और भाषा के देर से विकास से होती है।"},
  {"id":"cdp-child-development-1845","question":"A Class 1 child says an older student pushed her. When the teacher asks what happened, which question is most likely to give an accurate account?","options":["‘Did he push you with his right hand or his left?’","‘He pushed you very hard on purpose, didn’t he, beta?’","‘Was it Raju who pushed you, or was it Sonu?’","‘Tell me everything that happened near the swings.’"],"answer":3,"explanation":"Young children are especially open to suggestion; leading, tag or forced-choice questions plant details, while open-ended prompts let the child give her own account.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 की एक बच्ची कहती है कि एक बड़े छात्र ने उसे धक्का दिया। जब शिक्षिका पूछती है कि क्या हुआ, तो कौन-सा प्रश्न सबसे अधिक संभावना से सटीक विवरण देगा?","optionsHi":["‘क्या उसने तुम्हें दाएँ हाथ से धक्का दिया या बाएँ से?’","‘उसने तुम्हें जानबूझकर बहुत ज़ोर से धक्का दिया, है ना बेटा?’","‘क्या राजू ने तुम्हें धक्का दिया, या सोनू ने?’","‘झूलों के पास जो कुछ हुआ, वह सब मुझे बताओ।’"],"explanationHi":"छोटे बच्चे सुझावों के प्रति विशेष रूप से खुले होते हैं; प्रमुख, पुष्टिकारक या बाध्य-विकल्प प्रश्न विवरण रोप देते हैं, जबकि खुले प्रश्न बच्ची को अपना विवरण देने देते हैं।"},
  {"id":"cdp-child-development-1846","question":"Students watch a video of two cycles colliding. Those later asked ‘How fast were the cycles going when they smashed into each other?’ give higher speed estimates and are more likely to ‘remember’ broken glass than those asked with the word ‘hit’. This shows:","options":["The misinformation effect: wording after an event can change memory of it","Proactive interference: earlier memories block the learning of new ones","Encoding failure: the speed was never noticed during the video","Mood-congruent memory: frightened students remember more damage"],"answer":0,"explanation":"Loftus and Palmer showed that information supplied after an event can alter the memory itself; the video was the same for both groups, so encoding and mood cannot explain the difference.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"छात्र दो साइकिलों के टकराने का वीडियो देखते हैं। जिनसे बाद में पूछा गया ‘जब साइकिलें एक-दूसरे से टकराकर चूर हुईं तो वे कितनी तेज़ चल रही थीं?’ वे अधिक गति का अनुमान देते हैं और जिनसे ‘hit’ शब्द के साथ पूछा गया उनकी तुलना में टूटे काँच को ‘याद’ करने की अधिक संभावना रखते हैं। यह दर्शाता है:","optionsHi":["गलत सूचना प्रभाव: किसी घटना के बाद का शब्द-चयन उसकी स्मृति को बदल सकता है","अग्रोन्मुख व्यतिकरण: पहले की स्मृतियाँ नई स्मृतियों के सीखने को अवरुद्ध करती हैं","कूटन विफलता: वीडियो के दौरान गति पर ध्यान ही नहीं गया","मनोदशा-संगत स्मृति: भयभीत छात्र अधिक क्षति याद रखते हैं"],"explanationHi":"लॉफ़्टस और पामर ने दिखाया कि किसी घटना के बाद दी गई सूचना स्वयं स्मृति को बदल सकती है; दोनों समूहों के लिए वीडियो समान था, इसलिए कूटन और मनोदशा अंतर की व्याख्या नहीं कर सकते।"},
  {"id":"cdp-child-development-1847","question":"Five-year-olds who do not rehearse on their own are taught to repeat names of pictures, and their recall improves. Given a free choice later, many stop rehearsing. Flavell called this:","options":["A capacity deficiency","A mediation deficiency","A utilisation deficiency","A production deficiency"],"answer":3,"explanation":"In a production deficiency children can use a strategy that would help them but do not produce it spontaneously. A mediation deficiency means the strategy does not help even when used; a utilisation deficiency means it is used but gives little benefit yet.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"पाँच वर्ष के बच्चे जो स्वयं पुनरावृत्ति नहीं करते उन्हें चित्रों के नाम दोहराना सिखाया जाता है, और उनका स्मरण सुधरता है। बाद में स्वतंत्र चयन दिए जाने पर, अनेक पुनरावृत्ति करना बंद कर देते हैं। फ्लेवेल ने इसे क्या कहा?","optionsHi":["क्षमता-न्यूनता","मध्यस्थता-न्यूनता","उपयोग-न्यूनता","उत्पादन-न्यूनता"],"explanationHi":"उत्पादन-न्यूनता में बच्चे ऐसी युक्ति का उपयोग कर सकते हैं जो उनकी सहायता करेगी पर उसे स्वतः उत्पन्न नहीं करते। मध्यस्थता-न्यूनता का अर्थ है कि युक्ति प्रयोग करने पर भी सहायक नहीं होती; उपयोग-न्यूनता का अर्थ है कि प्रयोग होती है पर अभी बहुत कम लाभ देती है।"},
  {"id":"cdp-child-development-1848","question":"Ten-year-old chess players recalled board positions from real games better than adult non-players, but the adults recalled lists of digits better. What does Michelene Chi’s study show?","options":["Children have a larger basic memory capacity than adults for every kind of material","A rich knowledge base in a domain improves memory for material in that domain","Adults have better strategies for every kind of material than children","Memory depends only on age, so the chess results must simply reflect chance"],"answer":1,"explanation":"The children’s expert knowledge let them chunk and interpret chess positions, so domain knowledge, not age or general capacity, drove recall; on digits, where they had no special knowledge, adults did better.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"दस वर्ष के शतरंज खिलाड़ियों ने असली खेलों की बिसात की स्थितियाँ शतरंज न खेलने वाले वयस्कों से बेहतर याद कीं, पर वयस्कों ने अंकों की सूचियाँ बेहतर याद कीं। मिशेलीन ची का अध्ययन क्या दर्शाता है?","optionsHi":["हर प्रकार की सामग्री के लिए बच्चों की मूल स्मृति-क्षमता वयस्कों से बड़ी होती है","किसी क्षेत्र में समृद्ध ज्ञान-आधार उस क्षेत्र की सामग्री की स्मृति को सुधारता है","हर प्रकार की सामग्री के लिए वयस्कों के पास बच्चों से बेहतर युक्तियाँ होती हैं","स्मृति केवल आयु पर निर्भर करती है, इसलिए शतरंज के परिणाम बस संयोग दर्शाते होंगे"],"explanationHi":"बच्चों के विशेषज्ञ ज्ञान ने उन्हें शतरंज की स्थितियों को खंडों में बाँटने और उनकी व्याख्या करने दिया, इसलिए स्मरण को क्षेत्र-ज्ञान ने चलाया, आयु या सामान्य क्षमता ने नहीं; अंकों पर, जहाँ उनका कोई विशेष ज्ञान नहीं था, वयस्कों ने बेहतर किया।"},
  {"id":"cdp-child-development-1849","question":"In Sperling’s experiments, a grid of 12 letters is flashed briefly. Asked to report all letters, people give about 4; but when a tone right after the flash cues just one row, they can report most of that row. What does this show?","options":["Attention can be divided equally among all rows at the same moment","Short-term memory can hold all 12 letters as long as they are rehearsed quickly","Sensory (iconic) memory briefly holds much more than can be reported before it fades","Long-term memory stores the letters that are later cued by a particular tone"],"answer":2,"explanation":"Since any row could be cued, nearly all the letters must have been available for an instant; the visual trace fades within about a second, faster than whole report can be given.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"स्पर्लिंग के प्रयोगों में, 12 अक्षरों का एक ग्रिड संक्षेप में चमकाया जाता है। सभी अक्षर बताने को कहे जाने पर लोग लगभग 4 बताते हैं; पर जब चमक के ठीक बाद एक स्वर केवल एक पंक्ति का संकेत देता है, तो वे उस पंक्ति का अधिकांश बता सकते हैं। यह क्या दर्शाता है?","optionsHi":["ध्यान को एक ही क्षण पर सभी पंक्तियों में समान रूप से बाँटा जा सकता है","अल्पकालिक स्मृति सभी 12 अक्षर रख सकती है यदि उन्हें शीघ्रता से दोहराया जाए","संवेदी (प्रतिबिंबात्मक) स्मृति लुप्त होने से पहले संक्षेप में इतना अधिक धारण करती है जितना बताया जा सकता है","दीर्घकालिक स्मृति उन अक्षरों को संचित करती है जिनका बाद में किसी विशेष स्वर द्वारा संकेत दिया जाता है"],"explanationHi":"चूँकि किसी भी पंक्ति का संकेत दिया जा सकता था, लगभग सभी अक्षर एक क्षण के लिए उपलब्ध रहे होंगे; दृश्य चिह्न लगभग एक सेकंड में लुप्त हो जाता है, पूर्ण रिपोर्ट दिए जाने से तेज़ी से।"},
  {"id":"cdp-child-development-1850","question":"Students who could recall only a few words from a long list were given category names such as ‘fruits’ and ‘tools’, and then recalled many more. Tulving and Pearlstone concluded that much forgetting reflects:","options":["Items that are available in memory but not accessible without suitable cues","Items that decayed from memory and were regenerated by guessing","Items that were never encoded, which the categories then supplied","Items displaced from short-term memory when the category names were presented"],"answer":0,"explanation":"Cues recovered words that free recall missed, so those words had been stored; the problem was retrieval. This is the distinction between availability and accessibility.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"जो छात्र लंबी सूची से केवल कुछ शब्द याद कर सके, उन्हें ‘फल’ और ‘औज़ार’ जैसे श्रेणी-नाम दिए गए, और तब उन्होंने कहीं अधिक याद किए। टल्विंग और पियरलस्टोन ने निष्कर्ष निकाला कि अधिकांश विस्मरण इसे दर्शाता है:","optionsHi":["वे मदें जो स्मृति में उपलब्ध हैं पर उपयुक्त संकेतों के बिना सुगम नहीं हैं","वे मदें जो स्मृति से क्षीण हो गईं और अनुमान द्वारा पुनः उत्पन्न हुईं","वे मदें जो कभी कूटित नहीं हुईं, जिन्हें श्रेणियों ने फिर प्रदान किया","वे मदें जो श्रेणी-नाम प्रस्तुत किए जाने पर अल्पकालिक स्मृति से विस्थापित हो गईं"],"explanationHi":"संकेतों ने वे शब्द पुनः प्राप्त कराए जो मुक्त स्मरण में छूट गए थे, इसलिए वे शब्द संचित थे; समस्या पुनःप्राप्ति की थी। यही उपलब्धता और सुगमता का भेद है।"},
  {"id":"cdp-child-development-1851","question":"Pre-school children are shown unfamiliar gadgets. Some gadgets are described as ‘things girls really like’ and others as ‘things boys really like’. A week later, children have explored more and remember more names for the gadgets labelled for their own sex. Which theory predicts this most directly?","options":["Psychoanalytic theory: children identify with the same-sex parent after resolving the Oedipal conflict","Gender schema theory: children attend to and remember what their gender schema marks as ‘for me’","Operant learning: children remember gadgets for which they were directly rewarded","Biological theory: prenatal hormones fix interest in particular kinds of objects"],"answer":1,"explanation":"The gadgets were new, so no prior reward or hormone-linked preference could favour them; only the label differed. Martin and Halverson’s gender schema theory says children use ‘own-sex’ labels to decide what to explore and encode.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"पूर्व-विद्यालयी बच्चों को अपरिचित उपकरण दिखाए जाते हैं। कुछ उपकरणों को ‘वे चीज़ें जो लड़कियाँ सचमुच पसंद करती हैं’ और अन्य को ‘वे चीज़ें जो लड़के सचमुच पसंद करते हैं’ बताया जाता है। एक सप्ताह बाद, बच्चे अपने लिंग के लिए लेबल किए गए उपकरणों की अधिक खोज करते हैं और उनके अधिक नाम याद रखते हैं। कौन-सा सिद्धांत इसका सबसे प्रत्यक्ष पूर्वानुमान करता है?","optionsHi":["मनोविश्लेषणात्मक सिद्धांत: ईडिपस द्वंद्व सुलझाने के बाद बच्चे समलिंग माता-पिता से तादात्म्य बनाते हैं","लिंग स्कीमा सिद्धांत: बच्चे उस पर ध्यान देते और उसे याद रखते हैं जिसे उनका लिंग स्कीमा ‘मेरे लिए’ चिह्नित करता है","क्रियाप्रसूत अधिगम: बच्चे उन उपकरणों को याद रखते हैं जिनके लिए उन्हें सीधे पुरस्कृत किया गया","जैविक सिद्धांत: जन्मपूर्व हार्मोन विशेष प्रकार की वस्तुओं में रुचि को स्थिर करते हैं"],"explanationHi":"उपकरण नए थे, इसलिए कोई पूर्व पुरस्कार या हार्मोन-संबंधी पसंद उनका पक्ष नहीं ले सकती थी; केवल लेबल भिन्न था। मार्टिन और हैल्वर्सन का लिंग स्कीमा सिद्धांत कहता है कि बच्चे ‘अपने-लिंग’ के लेबलों का उपयोग यह तय करने में करते हैं कि क्या खोजना और कूटित करना है।"},
  {"id":"cdp-child-development-1852","question":"Two-year-olds already prefer gender-typed toys, though most children do not grasp gender constancy until about five to seven years. Which theory is more directly challenged by this finding?","options":["Bandura’s social learning theory, which links gender-typing to modelling and to direct reinforcement by others","Gender schema theory, which needs only a basic gender identity, not constancy, for gender-typing to begin","Kohlberg’s cognitive-developmental theory, which made gender constancy the starting point of gender-typing","Bronfenbrenner’s ecological theory, which places gender norms in the macrosystem"],"answer":2,"explanation":"Kohlberg held that children first understand that gender is permanent and then seek out gender-appropriate behaviour; preferences seen long before constancy fit schema and social learning accounts better.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"दो वर्ष के बच्चे पहले से लिंग-प्रारूपित खिलौने पसंद करते हैं, यद्यपि अधिकांश बच्चे लगभग पाँच से सात वर्ष की आयु तक लिंग-स्थिरता नहीं समझते। यह निष्कर्ष किस सिद्धांत को अधिक प्रत्यक्ष रूप से चुनौती देता है?","optionsHi":["बंडूरा का सामाजिक अधिगम सिद्धांत, जो लिंग-प्रारूपण को अनुकरण और दूसरों द्वारा प्रत्यक्ष पुनर्बलन से जोड़ता है","लिंग स्कीमा सिद्धांत, जिसे लिंग-प्रारूपण शुरू होने के लिए केवल मूल लिंग-पहचान चाहिए, स्थिरता नहीं","कोहलबर्ग का संज्ञानात्मक-विकासात्मक सिद्धांत, जिसने लिंग-स्थिरता को लिंग-प्रारूपण का प्रारंभ-बिंदु बनाया","ब्रोनफेनब्रेनर का पारिस्थितिक सिद्धांत, जो लैंगिक मानदंडों को व्यापकतंत्र में रखता है"],"explanationHi":"कोहलबर्ग का मत था कि बच्चे पहले समझते हैं कि लिंग स्थायी है और फिर लिंग-उपयुक्त व्यवहार खोजते हैं; स्थिरता से बहुत पहले दिखने वाली पसंदें स्कीमा और सामाजिक अधिगम विवरणों से बेहतर मेल खाती हैं।"},
  {"id":"cdp-child-development-1853","question":"From about age three, children increasingly choose same-sex playmates even when teachers encourage mixed play, and this peaks in middle childhood. Eleanor Maccoby’s explanation emphasised that:","options":["Each sex has a different profile of abilities, so boys and girls cannot easily share games","Teachers quietly reward same-sex play, so children learn to prefer it through reinforcement","Children copy their parents, who mostly choose close friends of their own sex","Boys’ rough, dominant play and girls’ preference for negotiation make same-sex play more compatible"],"answer":3,"explanation":"Maccoby argued that children seek partners whose interaction style matches theirs; girls find boys unresponsive to polite influence, and boys prefer rough play, so segregation arises largely from the children themselves.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"लगभग तीन वर्ष की आयु से, बच्चे अधिकाधिक समलिंग खेल-साथी चुनते हैं, भले ही शिक्षक मिश्रित खेल को प्रोत्साहित करें, और यह मध्य बाल्यावस्था में चरम पर होता है। एलेनॉर मैककोबी की व्याख्या ने इस पर ज़ोर दिया कि:","optionsHi":["प्रत्येक लिंग की योग्यताओं का भिन्न प्रोफ़ाइल है, इसलिए लड़के और लड़कियाँ आसानी से खेल साझा नहीं कर सकते","शिक्षक चुपचाप समलिंग खेल को पुरस्कृत करते हैं, इसलिए बच्चे पुनर्बलन से उसे पसंद करना सीखते हैं","बच्चे अपने माता-पिता की नकल करते हैं, जो अधिकतर अपने लिंग के घनिष्ठ मित्र चुनते हैं","लड़कों का कठोर, प्रभुत्वशील खेल और लड़कियों की वार्ता की पसंद समलिंग खेल को अधिक अनुकूल बनाती है"],"explanationHi":"मैककोबी ने तर्क दिया कि बच्चे ऐसे साथी खोजते हैं जिनकी अंतःक्रिया-शैली उनसे मेल खाती है; लड़कियों को लड़के विनम्र प्रभाव के प्रति अनुत्तरदायी लगते हैं, और लड़के कठोर खेल पसंद करते हैं, इसलिए पृथक्करण बहुत हद तक बच्चों से ही उत्पन्न होता है।"},
  {"id":"cdp-child-development-1854","question":"In early adolescence, both boys and girls often become stricter about acting ‘like a man’ or ‘like a woman’ in dress, interests and behaviour. Hill and Lynch called this:","options":["Gender intensification","Gender constancy","Gender-role transcendence","Gender stability"],"answer":0,"explanation":"The gender intensification hypothesis links increased pressure to conform to gender roles in early adolescence to puberty and to expectations from parents and peers; constancy and stability are early childhood understandings.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"प्रारंभिक किशोरावस्था में, लड़के और लड़कियाँ दोनों प्रायः पहनावे, रुचियों और व्यवहार में ‘पुरुष जैसा’ या ‘स्त्री जैसा’ व्यवहार करने के बारे में अधिक कठोर हो जाते हैं। हिल और लिंच ने इसे क्या कहा?","optionsHi":["लिंग-गहनता (जेंडर इंटेंसिफ़िकेशन)","लिंग-स्थिरता","लिंग-भूमिका अतिक्रमण","लिंग-स्थायित्व"],"explanationHi":"लिंग-गहनता परिकल्पना प्रारंभिक किशोरावस्था में लैंगिक भूमिकाओं के अनुरूप होने के बढ़े हुए दबाव को यौवनारंभ और माता-पिता तथा साथियों की अपेक्षाओं से जोड़ती है; स्थिरता और स्थायित्व प्रारंभिक बाल्यावस्था की समझ हैं।"},
  {"id":"cdp-child-development-1855","question":"Janet Hyde reviewed many studies of psychological differences between males and females. Her ‘gender similarities hypothesis’ concluded that:","options":["Differences are large in childhood but disappear only after age forty","Most differences are large and are fixed at birth by biological sex","Girls are much better in maths and boys much better in reading","Most differences, including in maths ability, are small or close to zero"],"answer":3,"explanation":"Hyde found that most effect sizes were small or near zero, with a few exceptions such as some motor skills; overstating differences can harm children’s choices and teachers’ expectations.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"जेनेट हाइड ने पुरुषों और महिलाओं के बीच मनोवैज्ञानिक अंतरों के अनेक अध्ययनों की समीक्षा की। उनकी ‘लैंगिक समानताओं की परिकल्पना’ ने निष्कर्ष निकाला कि:","optionsHi":["बाल्यावस्था में अंतर बड़े हैं पर केवल चालीस वर्ष की आयु के बाद समाप्त होते हैं","अधिकांश अंतर बड़े हैं और जैविक लिंग से जन्म के समय तय होते हैं","लड़कियाँ गणित में बहुत बेहतर और लड़के पठन में बहुत बेहतर हैं","अधिकांश अंतर, गणितीय योग्यता सहित, छोटे या शून्य के निकट हैं"],"explanationHi":"हाइड ने पाया कि अधिकांश प्रभाव-आकार छोटे या शून्य के निकट थे, कुछ अपवादों जैसे कुछ गामक कौशलों के साथ; अंतरों को बढ़ा-चढ़ाकर बताना बच्चों के चयनों और शिक्षकों की अपेक्षाओं को हानि पहुँचा सकता है।"},
  {"id":"cdp-child-development-1856","question":"Studies of parents watching their children play found that cross-gender play (such as a boy playing with dolls) drew more disapproval when it was done by:","options":["Girls, especially from their fathers","Boys, especially from their fathers","Girls, especially from their mothers","Boys and girls equally, from both parents"],"answer":1,"explanation":"Research such as that of Fagot and of Langlois and Downs found that boys’ cross-gender play is discouraged more strongly than girls’, with fathers the most likely to react.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"अपने बच्चों को खेलते देखने वाले माता-पिता के अध्ययनों में पाया गया कि विपरीत-लिंग का खेल (जैसे लड़के का गुड़ियों से खेलना) अधिक अस्वीकृति तब पाता था जब वह किसके द्वारा किया जाता था?","optionsHi":["लड़कियाँ, विशेषकर उनके पिताओं से","लड़के, विशेषकर उनके पिताओं से","लड़कियाँ, विशेषकर उनकी माताओं से","लड़के और लड़कियाँ समान रूप से, दोनों माता-पिता से"],"explanationHi":"फ़ैगोट और लैंगलॉइस तथा डाउन्स जैसे शोध ने पाया कि लड़कों के विपरीत-लिंग के खेल को लड़कियों की तुलना में अधिक दृढ़ता से हतोत्साहित किया जाता है, और पिता सबसे अधिक प्रतिक्रिया करने वाले होते हैं।"},
  {"id":"cdp-child-development-1857","question":"Ramesh begins to think of himself as ‘clever’ after noticing how his teachers and friends react to his answers in class. This idea that the self is formed by imagining how others see and judge us was given by:","options":["Erik Erikson, as ‘identity achievement’ in adolescence","George Herbert Mead, as the ‘generalised other’","Charles Horton Cooley, as the ‘looking-glass self’","Carl Rogers, as the ‘ideal self’"],"answer":2,"explanation":"Cooley’s looking-glass self has three parts: we imagine how we appear to others, imagine their judgement, and feel pride or shame. Mead’s generalised other refers to the attitudes of the community as a whole.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"रमेश अपने शिक्षकों और मित्रों की कक्षा में उसके उत्तरों पर प्रतिक्रिया देखकर स्वयं को ‘चतुर’ समझने लगता है। यह विचार कि स्व की रचना यह कल्पना करके होती है कि दूसरे हमें कैसे देखते और आँकते हैं, किसने दिया?","optionsHi":["एरिक एरिक्सन ने, किशोरावस्था में ‘पहचान की प्राप्ति’ के रूप में","जॉर्ज हर्बर्ट मीड ने, ‘सामान्यीकृत अन्य’ के रूप में","चार्ल्स हॉर्टन कूले ने, ‘दर्पण-स्व’ के रूप में","कार्ल रॉजर्स ने, ‘आदर्श स्व’ के रूप में"],"explanationHi":"कूले के दर्पण-स्व के तीन भाग हैं: हम कल्पना करते हैं कि हम दूसरों को कैसे दिखते हैं, उनके निर्णय की कल्पना करते हैं, और गर्व या लज्जा महसूस करते हैं। मीड का सामान्यीकृत अन्य पूरे समुदाय की अभिवृत्तियों को संदर्भित करता है।"},
  {"id":"cdp-child-development-1858","question":"A five-year-old pretends to be a doctor, then a shopkeeper; a nine-year-old playing cricket adjusts to the roles of bowler, fielders and umpire all at once and follows the rules of the game. George Herbert Mead saw the second child as having reached:","options":["The game stage, taking the attitude of the generalised other","The play stage, taking the role of one particular other","The preparatory stage, imitating others without understanding roles","The formal stage, reasoning about hypothetical roles"],"answer":0,"explanation":"In the play stage a child takes one role at a time; in the game stage he must hold the expectations of all players and the rules together, the ‘generalised other’ that becomes the basis of the social self.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"पाँच वर्ष का बच्चा डॉक्टर बनने का अभिनय करता है, फिर दुकानदार का; क्रिकेट खेलता हुआ नौ वर्ष का बच्चा गेंदबाज़, क्षेत्ररक्षकों और अंपायर की भूमिकाओं के साथ एक साथ समायोजन करता है और खेल के नियमों का पालन करता है। जॉर्ज हर्बर्ट मीड ने दूसरे बच्चे को किस अवस्था तक पहुँचा हुआ माना?","optionsHi":["खेल अवस्था (गेम स्टेज), सामान्यीकृत अन्य की अभिवृत्ति लेना","क्रीड़ा अवस्था (प्ले स्टेज), किसी एक विशेष अन्य की भूमिका लेना","प्रारंभिक अवस्था, भूमिकाओं को समझे बिना दूसरों की नकल करना","औपचारिक अवस्था, काल्पनिक भूमिकाओं के बारे में तर्क करना"],"explanationHi":"क्रीड़ा अवस्था में बच्चा एक समय में एक भूमिका लेता है; खेल अवस्था में उसे सभी खिलाड़ियों की अपेक्षाओं और नियमों को एक साथ धारण करना होता है, यही ‘सामान्यीकृत अन्य’ है जो सामाजिक स्व का आधार बनता है।"},
  {"id":"cdp-child-development-1859","question":"Match each process with its example. P. Primary socialisation Q. Secondary socialisation R. Anticipatory socialisation S. Resocialisation 1. A Class 12 student practises formal speech and dress before joining a college debate club 2. A toddler learns language and basic habits at home 3. A child learns to wait for turns and follow timetables at school 4. A boy who had worked in a factory adjusts to classroom routines after a bridge course","options":["P-2, Q-1, R-3, S-4","P-2, Q-3, R-1, S-4","P-3, Q-2, R-1, S-4","P-2, Q-3, R-4, S-1"],"answer":1,"explanation":"Primary socialisation happens mainly in the family in early years; secondary socialisation occurs in wider institutions such as school; anticipatory socialisation prepares for a role one expects to take; resocialisation replaces earlier patterns with new ones.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"प्रत्येक प्रक्रिया का मिलान उसके उदाहरण से कीजिए। P. प्राथमिक समाजीकरण Q. द्वितीयक समाजीकरण R. पूर्वाभासी समाजीकरण S. पुनः समाजीकरण 1. कक्षा 12 का छात्र कॉलेज के वाद-विवाद क्लब में शामिल होने से पहले औपचारिक भाषण और पहनावे का अभ्यास करता है 2. नन्हा बच्चा घर पर भाषा और मूल आदतें सीखता है 3. बच्चा विद्यालय में बारी का इंतज़ार करना और समय-सारणी का पालन करना सीखता है 4. फ़ैक्टरी में काम कर चुका लड़का सेतु पाठ्यक्रम के बाद कक्षा की दिनचर्या में ढलता है","optionsHi":["P-2, Q-1, R-3, S-4","P-2, Q-3, R-1, S-4","P-3, Q-2, R-1, S-4","P-2, Q-3, R-4, S-1"],"explanationHi":"प्राथमिक समाजीकरण मुख्यतः प्रारंभिक वर्षों में परिवार में होता है; द्वितीयक समाजीकरण विद्यालय जैसी व्यापक संस्थाओं में होता है; पूर्वाभासी समाजीकरण उस भूमिका के लिए तैयार करता है जिसे व्यक्ति निभाने की अपेक्षा करता है; पुनः समाजीकरण पहले के प्रतिरूपों को नए से बदलता है।"},
  {"id":"cdp-child-development-1860","question":"At home, a child is loved and treated as special simply because she is ‘our daughter’; at school she is judged by the same rules and standards as everyone else in her class. Parsons and Dreeben saw this second experience as the school teaching the norm of:","options":["Ascription","Particularism","Universalism","Affectivity"],"answer":2,"explanation":"Families treat members particularistically, by who they are; schools apply universalistic standards to all pupils alike and reward achievement rather than ascribed status, preparing children for wider society.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"घर पर, बच्ची को प्यार मिलता है और उसे केवल इसलिए विशेष माना जाता है क्योंकि वह ‘हमारी बेटी’ है; विद्यालय में उसे कक्षा के बाकी सब के समान नियमों और मानकों से आँका जाता है। पार्सन्स और ड्रीबेन ने इस दूसरे अनुभव को विद्यालय द्वारा किस मानदंड की शिक्षा देना माना?","optionsHi":["आरोपण (एस्क्रिप्शन)","विशिष्टतावाद (पार्टिकुलैरिज़्म)","सार्वभौमिकतावाद (यूनिवर्सलिज़्म)","भावात्मकता (एफ़ेक्टिविटी)"],"explanationHi":"परिवार सदस्यों के साथ विशिष्टतावादी व्यवहार करते हैं, वे कौन हैं इस आधार पर; विद्यालय सभी विद्यार्थियों पर समान रूप से सार्वभौमिकतावादी मानक लागू करते हैं और आरोपित स्थिति के बजाय उपलब्धि को पुरस्कृत करते हैं, जो बच्चों को व्यापक समाज के लिए तैयार करता है।"},
  {"id":"cdp-child-development-1861","question":"Parents who set few rules and also show little warmth or involvement, rarely knowing where their child is or how she is doing at school, fit which style in Maccoby and Martin’s extension of Baumrind’s model?","options":["Authoritative","Permissive (indulgent)","Authoritarian (restrictive)","Uninvolved (neglectful)"],"answer":3,"explanation":"Crossing demandingness with responsiveness gives four styles; low demands with low responsiveness is uninvolved, while permissive parents make few demands but are warm and responsive.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"जो माता-पिता कम नियम बनाते हैं और साथ ही कम गर्मजोशी या संलग्नता दिखाते हैं, शायद ही कभी जानते हैं कि उनका बच्चा कहाँ है या विद्यालय में कैसा कर रहा है, वे बॉमरिंड के मॉडल के मैककोबी और मार्टिन के विस्तार में किस शैली में आते हैं?","optionsHi":["प्राधिकारपूर्ण (ऑथोरिटेटिव)","अनुमतिदायी (पर्मिसिव / प्रश्रयकारी)","अधिनायकवादी (ऑथोरिटेरियन / प्रतिबंधात्मक)","असंलग्न (अनइन्वॉल्व्ड / उपेक्षापूर्ण)"],"explanationHi":"माँगों को अनुक्रियाशीलता से काटने पर चार शैलियाँ मिलती हैं; निम्न माँग के साथ निम्न अनुक्रियाशीलता असंलग्न है, जबकि अनुमतिदायी माता-पिता कम माँग करते हैं पर स्नेही और अनुक्रियाशील होते हैं।"},
  {"id":"cdp-child-development-1862","question":"Children of families who have moved from Kerala to Delhi grow up speaking Hindi with the accent of their Delhi classmates rather than that of their parents. Judith Rich Harris used such cases to argue that:","options":["Peer groups play a major part in socialising children, sometimes more than parents","Parents have no influence at all on any aspect of their children’s development","Language accent is fixed genetically and only appears to have been learnt from others","Teachers, not peers or parents, decide how children speak outside class"],"answer":0,"explanation":"Harris’s group socialisation theory holds that children adapt to the norms of their peer group outside the home; it does not claim parents have zero influence, only that peer effects are often underrated.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"केरल से दिल्ली आए परिवारों के बच्चे अपने माता-पिता के नहीं, बल्कि अपने दिल्ली के सहपाठियों के लहजे में हिंदी बोलते हुए बड़े होते हैं। जूडिथ रिच हैरिस ने ऐसे उदाहरणों से क्या तर्क दिया?","optionsHi":["बच्चों के समाजीकरण में साथी-समूह प्रमुख भूमिका निभाते हैं, कभी-कभी माता-पिता से भी अधिक","बच्चों के विकास के किसी भी पक्ष पर माता-पिता का कोई प्रभाव नहीं होता","भाषा का लहजा आनुवंशिक रूप से स्थिर होता है और केवल दूसरों से सीखा हुआ प्रतीत होता है","शिक्षक, साथी या माता-पिता नहीं, तय करते हैं कि बच्चे कक्षा के बाहर कैसे बोलते हैं"],"explanationHi":"हैरिस का समूह समाजीकरण सिद्धांत मानता है कि बच्चे घर के बाहर अपने साथी-समूह के मानदंडों के अनुसार ढल जाते हैं; यह दावा नहीं करता कि माता-पिता का प्रभाव शून्य है, केवल यह कि साथियों के प्रभावों को प्रायः कम आँका जाता है।"},
  {"id":"cdp-child-development-1863","question":"In many farming communities, young children learn to sort grain or tend animals by watching closely and joining in family work, with adults adjusting their help as the child’s part grows. Barbara Rogoff describes this as:","options":["Programmed instruction in small, carefully graded steps","Guided participation in culturally valued activities","Discovery learning without any adult involvement at all","Classical conditioning of useful household habits"],"answer":1,"explanation":"Rogoff’s guided participation extends Vygotsky’s ideas: children learn through shared participation in real activities, with mutual involvement and support that shifts as competence grows.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अनेक कृषक समुदायों में, छोटे बच्चे ध्यान से देखकर और परिवार के कार्य में शामिल होकर अनाज छाँटना या पशुओं की देखभाल करना सीखते हैं, और जैसे-जैसे बच्चे की भागीदारी बढ़ती है वयस्क अपनी सहायता को समायोजित करते हैं। बारबरा रोगॉफ़ इसे क्या वर्णित करती हैं?","optionsHi":["छोटे, सावधानी से श्रेणीबद्ध चरणों में अभिक्रमित अनुदेशन","सांस्कृतिक रूप से मूल्यवान गतिविधियों में निर्देशित सहभागिता","बिना किसी वयस्क की संलग्नता के खोज अधिगम","उपयोगी घरेलू आदतों का शास्त्रीय अनुबंधन"],"explanationHi":"रोगॉफ़ की निर्देशित सहभागिता वाइगोत्स्की के विचारों का विस्तार है: बच्चे वास्तविक गतिविधियों में साझा भागीदारी के माध्यम से सीखते हैं, पारस्परिक संलग्नता और सहायता के साथ जो सक्षमता बढ़ने पर बदलती है।"},
  {"id":"cdp-child-development-1864","question":"Philip Jackson, who coined the term ‘hidden curriculum’, said that children in classrooms must learn to live with three facts of school life. These are:","options":["Tests, grades and promotion","Rules, rewards and punishments","Crowds, praise and power","Peers, parents and teachers"],"answer":2,"explanation":"In ‘Life in Classrooms’ Jackson described crowds (waiting, delay, sharing attention), praise (constant evaluation) and power (the teacher’s authority) as lessons learnt beyond the official syllabus.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"‘छिपी हुई पाठ्यचर्या’ शब्द गढ़ने वाले फ़िलिप जैक्सन ने कहा कि कक्षाओं में बच्चों को विद्यालयी जीवन के तीन तथ्यों के साथ जीना सीखना पड़ता है। ये हैं:","optionsHi":["परीक्षण, ग्रेड और पदोन्नति","नियम, पुरस्कार और दंड","भीड़, प्रशंसा और शक्ति","साथी, माता-पिता और शिक्षक"],"explanationHi":"‘लाइफ़ इन क्लासरूम्स’ में जैक्सन ने भीड़ (प्रतीक्षा, विलंब, ध्यान बाँटना), प्रशंसा (निरंतर मूल्यांकन) और शक्ति (शिक्षक का अधिकार) को आधिकारिक पाठ्यक्रम से परे सीखे जाने वाले पाठ बताया।"},
  {"id":"cdp-child-development-1865","question":"A mother believes boys are naturally better at maths. Even when her daughter scores as well as her son, she rates the daughter’s maths ability lower. Research in Eccles’s parent-socialiser model suggests that over time:","options":["The son’s maths self-concept falls, since he is compared with a high-scoring sister","The daughter’s maths marks rise, since she works harder to prove her mother wrong","The mother’s belief has no effect, since children judge ability only from test scores","The daughter’s own view of her maths ability tends to fall, regardless of her actual marks"],"answer":3,"explanation":"Jacobs and Eccles found that parents’ gender-stereotyped beliefs shape their perceptions of their child’s ability, which in turn shape the child’s self-perceptions and choices, independent of actual performance.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक माँ मानती है कि लड़के स्वाभाविक रूप से गणित में बेहतर होते हैं। जब उसकी बेटी उसके बेटे जितना ही अंक पाती है, तब भी वह बेटी की गणितीय योग्यता को कम आँकती है। एक्लेस के माता-पिता-समाजीकारक मॉडल में शोध सुझाता है कि समय के साथ:","optionsHi":["बेटे का गणित का आत्म-संप्रत्यय गिरेगा, क्योंकि उसकी तुलना उच्च अंक पाने वाली बहन से होती है","बेटी के गणित के अंक बढ़ेंगे, क्योंकि वह अपनी माँ को गलत साबित करने के लिए अधिक परिश्रम करेगी","माँ के विश्वास का कोई प्रभाव नहीं होगा, क्योंकि बच्चे योग्यता का निर्णय केवल परीक्षण-अंकों से करते हैं","बेटी का अपनी गणितीय योग्यता के बारे में अपना दृष्टिकोण गिरने की प्रवृत्ति रखेगा, उसके वास्तविक अंकों की परवाह किए बिना"],"explanationHi":"जैकब्स और एक्लेस ने पाया कि माता-पिता की लैंगिक रूढ़ मान्यताएँ बच्चे की योग्यता के बारे में उनकी धारणाओं को आकार देती हैं, जो बदले में बच्चे की आत्म-धारणाओं और चयनों को आकार देती हैं, वास्तविक प्रदर्शन से स्वतंत्र।"},
  {"id":"cdp-child-development-1866","question":"A six-year-old insists that ‘only girls can be nurses’ and is upset when shown a male nurse; by nine she accepts that ‘boys and girls can both do it’. This change reflects the typical pattern that:","options":["Rigidity about gender stereotypes peaks around five to seven and then becomes more flexible","Children are flexible about gender at six and become steadily more rigid as they grow older","Gender rigidity is fixed by heredity and does not change during childhood","Children lose all knowledge of gender stereotypes once they reach school age"],"answer":0,"explanation":"Once children learn stereotypes they apply them rigidly in early childhood; with more cognitive flexibility and experience, they come to see gender roles as conventions that can vary.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"छह वर्ष का बच्चा आग्रह करता है कि ‘केवल लड़कियाँ ही नर्स हो सकती हैं’ और पुरुष नर्स दिखाए जाने पर परेशान हो जाता है; नौ वर्ष की आयु तक वह स्वीकार करता है कि ‘लड़के और लड़कियाँ दोनों यह कर सकते हैं’। यह परिवर्तन किस सामान्य प्रतिरूप को दर्शाता है?","optionsHi":["लैंगिक रूढ़ धारणाओं के प्रति कठोरता लगभग पाँच से सात वर्ष पर चरम पर होती है और फिर अधिक लचीली हो जाती है","बच्चे छह वर्ष की आयु पर लिंग के बारे में लचीले होते हैं और बड़े होने पर निरंतर अधिक कठोर हो जाते हैं","लैंगिक कठोरता आनुवंशिकता से तय होती है और बाल्यावस्था में नहीं बदलती","विद्यालय-आयु तक पहुँचने पर बच्चे लैंगिक रूढ़ धारणाओं का सारा ज्ञान खो देते हैं"],"explanationHi":"एक बार जब बच्चे रूढ़ धारणाएँ सीख लेते हैं तो प्रारंभिक बाल्यावस्था में उन्हें कठोरता से लागू करते हैं; अधिक संज्ञानात्मक लचीलेपन और अनुभव के साथ, वे लैंगिक भूमिकाओं को ऐसी परंपराओं के रूप में देखने लगते हैं जो बदल सकती हैं।"},
  {"id":"cdp-child-development-1867","question":"In a summer school, children are given blue or yellow T-shirts at random. In some classes teachers use the colours to organise the day (separate lines, desks labelled by colour); in others the colours are worn but never used. Bigler’s study found that children showed favouritism towards their own colour group:","options":["Equally in both kinds of class, as soon as the coloured shirts were handed out","Mainly in classes where teachers made functional use of the colour groups","Only in classes where teachers said that one colour group was cleverer","In neither kind of class, since the groups were assigned at random"],"answer":1,"explanation":"Even arbitrary groups produced in-group bias when adults made them salient by using them to sort and label children; merely wearing the shirts was not enough. Teachers’ routine sorting by gender or caste can similarly fuel bias.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"एक ग्रीष्म विद्यालय में, बच्चों को यादृच्छिक रूप से नीली या पीली टी-शर्ट दी जाती हैं। कुछ कक्षाओं में शिक्षक रंगों का उपयोग दिन को व्यवस्थित करने में करते हैं (अलग पंक्तियाँ, रंग से चिह्नित डेस्क); अन्य में रंग पहने तो जाते हैं पर कभी प्रयोग नहीं किए जाते। बिगलर के अध्ययन ने पाया कि बच्चों ने अपने रंग-समूह के प्रति पक्षपात दिखाया:","optionsHi":["दोनों प्रकार की कक्षाओं में समान रूप से, रंगीन शर्ट मिलते ही","मुख्यतः उन कक्षाओं में जहाँ शिक्षकों ने रंग-समूहों का कार्यात्मक उपयोग किया","केवल उन कक्षाओं में जहाँ शिक्षकों ने कहा कि एक रंग-समूह अधिक चतुर है","किसी भी प्रकार की कक्षा में नहीं, क्योंकि समूह यादृच्छिक रूप से निर्धारित किए गए थे"],"explanationHi":"मनमाने समूहों ने भी आंतरिक-समूह पूर्वाग्रह उत्पन्न किया जब वयस्कों ने उन्हें बच्चों को छाँटने और नाम देने के लिए प्रयोग करके प्रमुख बनाया; केवल शर्ट पहनना पर्याप्त नहीं था। शिक्षकों द्वारा लिंग या जाति के आधार पर नियमित छँटाई भी इसी प्रकार पूर्वाग्रह को बढ़ावा दे सकती है।"},
  {"id":"cdp-child-development-1868","question":"A school wants its mixed activities to reduce prejudice between children of two communities. According to Allport’s contact hypothesis, which arrangement is most likely to help?","options":["Competitions between teams drawn from each community, to build healthy rivalry","Seating children of both communities in the same room while each group works on its own","Teams with equal status working cooperatively towards shared goals, backed by school leaders","Lectures on tolerance with the communities seated in separate sections of the hall"],"answer":2,"explanation":"Allport held that contact reduces prejudice under four conditions: equal status, common goals, intergroup cooperation and institutional support. Mere co-presence or competition can even strengthen bias.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक विद्यालय चाहता है कि उसकी मिश्रित गतिविधियाँ दो समुदायों के बच्चों के बीच पूर्वाग्रह को कम करें। ऑलपोर्ट की संपर्क परिकल्पना के अनुसार, कौन-सी व्यवस्था सबसे अधिक सहायक होने की संभावना रखती है?","optionsHi":["स्वस्थ प्रतिद्वंद्विता बनाने के लिए प्रत्येक समुदाय से चुनी टीमों के बीच प्रतियोगिताएँ","दोनों समुदायों के बच्चों को एक ही कमरे में बैठाना जबकि प्रत्येक समूह अपना कार्य करे","समान स्थिति वाली टीमें साझा लक्ष्यों की ओर सहयोगपूर्वक कार्य करें, विद्यालय-नेतृत्व के समर्थन के साथ","सहनशीलता पर व्याख्यान, समुदायों को सभागार के अलग-अलग खंडों में बैठाकर"],"explanationHi":"ऑलपोर्ट का मत था कि संपर्क चार शर्तों के अंतर्गत पूर्वाग्रह घटाता है: समान स्थिति, साझा लक्ष्य, अंतर-समूह सहयोग और संस्थागत समर्थन। केवल सह-उपस्थिति या प्रतिस्पर्धा पूर्वाग्रह को और मज़बूत भी कर सकती है।"},
  {"id":"cdp-child-development-1869","question":"Annette Lareau found that middle-class parents tend to fill children’s time with organised activities and to train them to question adults and negotiate, while working-class parents let children play freely and expect obedience to authority. She called the middle-class approach:","options":["Cultural deprivation","Accomplishment of natural growth","Authoritarian control","Concerted cultivation"],"answer":3,"explanation":"Concerted cultivation develops skills that schools reward, such as speaking up to adults; the working-class pattern she called the accomplishment of natural growth. She stressed both had strengths but schools valued the first.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"एनेट लेरो ने पाया कि मध्यवर्गीय माता-पिता बच्चों का समय संगठित गतिविधियों से भरते हैं और उन्हें वयस्कों से प्रश्न करना और वार्ता करना सिखाते हैं, जबकि श्रमिक वर्ग के माता-पिता बच्चों को स्वतंत्र खेलने देते हैं और अधिकार के प्रति आज्ञाकारिता की अपेक्षा रखते हैं। उन्होंने मध्यवर्गीय उपागम को क्या कहा?","optionsHi":["सांस्कृतिक अभाव","प्राकृतिक वृद्धि की सिद्धि","अधिनायकवादी नियंत्रण","समन्वित संवर्धन (कॉन्सर्टेड कल्टिवेशन)"],"explanationHi":"समन्वित संवर्धन ऐसे कौशल विकसित करता है जिन्हें विद्यालय पुरस्कृत करते हैं, जैसे वयस्कों के सामने बोलना; श्रमिक-वर्गीय प्रतिरूप को उन्होंने प्राकृतिक वृद्धि की सिद्धि कहा। उन्होंने ज़ोर दिया कि दोनों में ताक़तें थीं पर विद्यालय पहले को महत्व देते थे।"},
  {"id":"cdp-child-development-1870","question":"When Class 3 children are asked to ‘draw a scientist’, most draw a man. Reviews of such studies over several decades have found that:","options":["Children now draw more women scientists than decades ago, but drawing men increases with age","Children draw only women scientists today, so the stereotype has vanished","The share of children drawing men falls steadily as they move up to higher classes","Drawings show no gender pattern at all once children have studied science for a year"],"answer":0,"explanation":"Reviews of draw-a-scientist studies show more female scientists drawn now than in the 1960s–70s, yet children increasingly draw men as they get older, so classroom images and role models still matter.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"जब कक्षा 3 के बच्चों से ‘एक वैज्ञानिक का चित्र बनाओ’ कहा जाता है, तो अधिकांश एक पुरुष बनाते हैं। कई दशकों के ऐसे अध्ययनों की समीक्षाओं में क्या पाया गया है?","optionsHi":["बच्चे अब दशकों पहले की तुलना में अधिक महिला वैज्ञानिक बनाते हैं, परंतु आयु बढ़ने के साथ पुरुष बनाना बढ़ता है","बच्चे आज केवल महिला वैज्ञानिक बनाते हैं, इसलिए रूढ़ धारणा लुप्त हो गई है","पुरुष बनाने वाले बच्चों का अनुपात उच्च कक्षाओं में जाने पर लगातार घटता है","एक वर्ष विज्ञान पढ़ने के बाद चित्रों में कोई लैंगिक प्रतिरूप नहीं रहता"],"explanationHi":"वैज्ञानिक-चित्रण अध्ययनों की समीक्षाएँ दर्शाती हैं कि अब 1960–70 के दशकों की तुलना में अधिक महिला वैज्ञानिक बनाई जाती हैं, फिर भी बच्चे बड़े होने पर अधिकाधिक पुरुष बनाते हैं, इसलिए कक्षा की छवियाँ और आदर्श अब भी मायने रखते हैं।"},
  {"id":"cdp-child-development-1871","question":"Children watched several adult men and women choose between pairs of neutral items. Perry and Bussey found that children most strongly copied the choices of their own sex when:","options":["The models were children rather than adults of either sex","Only one same-sex model made the choice and others did not watch","The model was of the other sex but was rewarded for the choice","Most or all of the same-sex models agreed in their choices"],"answer":3,"explanation":"Children learn what counts as appropriate for their sex partly by noticing which behaviours are typical of many same-sex people; imitation was strongest when same-sex models showed high consensus.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"बच्चों ने कई वयस्क पुरुषों और महिलाओं को तटस्थ मदों के जोड़ों में से चयन करते देखा। पेरी और बुसी ने पाया कि बच्चों ने अपने लिंग के चयनों की नकल सबसे अधिक दृढ़ता से तब की जब:","optionsHi":["आदर्श किसी भी लिंग के वयस्कों के बजाय बच्चे थे","केवल एक समलिंग आदर्श ने चयन किया और दूसरों ने नहीं देखा","आदर्श विपरीत लिंग का था पर चयन के लिए उसे पुरस्कृत किया गया","अधिकांश या सभी समलिंग आदर्श अपने चयनों में सहमत थे"],"explanationHi":"बच्चे आंशिक रूप से यह देखकर सीखते हैं कि अपने लिंग के लिए क्या उपयुक्त है कि कौन-से व्यवहार अनेक समलिंग लोगों के लिए सामान्य हैं; अनुकरण तब सबसे प्रबल था जब समलिंग आदर्शों में उच्च सर्वसम्मति थी।"},
  {"id":"cdp-child-development-1872","question":"Children in a Class 2 playground invent their own version of a ‘teacher’ game in which the ‘teacher’ is teased and rules are made up together. William Corsaro would see this as an example of:","options":["Passive internalisation: children absorb adult norms exactly as given, without changing them","Interpretive reproduction: children creatively take up adult culture to form their own peer culture","Regression: children return to the play of earlier stages when anxious about school","Classical conditioning: cues in the school setting trigger fixed, learnt play responses"],"answer":1,"explanation":"Corsaro argued that socialisation is not one-way; children appropriate and reshape adult information in their peer cultures and so both reproduce and change society.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 के खेल के मैदान में बच्चे ‘शिक्षक’ खेल का अपना संस्करण गढ़ते हैं जिसमें ‘शिक्षक’ को चिढ़ाया जाता है और नियम साथ मिलकर बनाए जाते हैं। विलियम कोर्सारो इसे किसका उदाहरण मानेंगे?","optionsHi":["निष्क्रिय आंतरीकरण: बच्चे वयस्क मानदंडों को जैसे के तैसे, बिना बदले आत्मसात करते हैं","व्याख्यात्मक पुनरुत्पादन: बच्चे वयस्क संस्कृति को सृजनात्मक रूप से अपनाकर अपनी साथी-संस्कृति बनाते हैं","प्रतिगमन: विद्यालय के बारे में चिंतित होने पर बच्चे पहले की अवस्थाओं के खेल पर लौट जाते हैं","शास्त्रीय अनुबंधन: विद्यालयी परिवेश के संकेत निश्चित, सीखी हुई खेल-प्रतिक्रियाओं को ट्रिगर करते हैं"],"explanationHi":"कोर्सारो का तर्क था कि समाजीकरण एकतरफ़ा नहीं है; बच्चे अपनी साथी-संस्कृतियों में वयस्कों की जानकारी को अपनाते और उसे नया रूप देते हैं और इस प्रकार समाज का पुनरुत्पादन भी करते हैं और उसे बदलते भी हैं।"},
  {"id":"cdp-child-development-1873","question":"Assertion (A): Even without any adult instruction, children in a playground may chase ‘boys versus girls’ and tease those who cross over, keeping the sexes apart. Reason (R): Children actively construct and police gender boundaries in their peer play, a process Barrie Thorne called ‘borderwork’.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Thorne’s observations showed children themselves marking and policing gender lines through games and teasing, which explains why boundaries persist even without adult pressure.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): किसी वयस्क के निर्देश के बिना भी, खेल के मैदान में बच्चे ‘लड़के बनाम लड़कियाँ’ का पीछा-खेल खेल सकते हैं और उन्हें चिढ़ा सकते हैं जो पार जाते हैं, जिससे दोनों लिंग अलग बने रहते हैं। कारण (R): बच्चे अपने साथी-खेल में लैंगिक सीमाओं का सक्रिय रूप से निर्माण और पहरेदारी करते हैं, एक प्रक्रिया जिसे बैरी थॉर्न ने ‘सीमा-कार्य’ (बॉर्डरवर्क) कहा।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"थॉर्न के अवलोकनों ने दिखाया कि बच्चे स्वयं खेलों और चिढ़ाने के माध्यम से लैंगिक रेखाओं को चिह्नित और उनकी पहरेदारी करते हैं, जो समझाता है कि वयस्क दबाव के बिना भी सीमाएँ क्यों बनी रहती हैं।"},
  {"id":"cdp-child-development-1874","question":"A Class 3 worksheet says, ‘Every child must bring his own lunch box and keep his desk clean.’ Research on such ‘generic he’ wording suggests that children reading it:","options":["Picture girls more often, since lunch and tidiness are seen as girls’ tasks","Understand that it includes everyone, so the wording has no effect on what they picture","Tend to picture boys, so inclusive wording such as ‘their’ or ‘his or her’ is better","Ignore pronouns completely and attend only to the instructions"],"answer":2,"explanation":"Studies show that generic masculine pronouns call up mostly male images in children’s minds, which can subtly suggest that instructions or roles are for boys; inclusive wording avoids this.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 का एक कार्यपत्रक कहता है, ‘प्रत्येक बच्चे को अपना (his) लंच बॉक्स लाना चाहिए और अपनी (his) डेस्क साफ़ रखनी चाहिए।’ ऐसे ‘सामान्य he’ शब्द-प्रयोग पर शोध सुझाता है कि इसे पढ़ने वाले बच्चे:","optionsHi":["लड़कियों की अधिक कल्पना करते हैं, क्योंकि भोजन और साफ़-सफ़ाई को लड़कियों के कार्य माना जाता है","समझते हैं कि इसमें सब शामिल हैं, इसलिए शब्द-प्रयोग का इस पर कोई प्रभाव नहीं पड़ता कि वे क्या कल्पना करते हैं","लड़कों की कल्पना करने की प्रवृत्ति रखते हैं, इसलिए ‘their’ या ‘his or her’ जैसा समावेशी शब्द-प्रयोग बेहतर है","सर्वनामों की पूरी तरह अनदेखी करते हैं और केवल निर्देशों पर ध्यान देते हैं"],"explanationHi":"अध्ययन दिखाते हैं कि सामान्य पुल्लिंग सर्वनाम बच्चों के मन में अधिकतर पुरुष छवियाँ उत्पन्न करते हैं, जो सूक्ष्म रूप से सुझा सकते हैं कि निर्देश या भूमिकाएँ लड़कों के लिए हैं; समावेशी शब्द-प्रयोग इससे बचाता है।"},
  {"id":"cdp-child-development-1875","question":"Children who watch many hours of television in which women appear mostly at home and men at work come to believe that this is how the real world is. This media effect is best described by:","options":["Cultivation theory","Catharsis theory","Uses and gratifications","Recapitulation theory"],"answer":0,"explanation":"Gerbner’s cultivation theory holds that heavy, long-term viewing gradually shapes viewers’ beliefs about social reality to match television’s portrayals, which can strengthen gender stereotypes.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"जो बच्चे ऐसे टेलीविज़न के कई घंटे देखते हैं जिनमें महिलाएँ अधिकतर घर पर और पुरुष काम पर दिखते हैं, वे मानने लगते हैं कि वास्तविक संसार ऐसा ही है। इस मीडिया-प्रभाव का सबसे अच्छा वर्णन किससे होता है?","optionsHi":["संवर्धन सिद्धांत (कल्टिवेशन थ्योरी)","विरेचन सिद्धांत","उपयोग और संतुष्टि","पुनरावृत्ति सिद्धांत"],"explanationHi":"गर्बनर का संवर्धन सिद्धांत मानता है कि भारी, दीर्घकालिक दर्शन धीरे-धीरे दर्शकों के सामाजिक वास्तविकता के बारे में विश्वासों को टेलीविज़न के चित्रणों के अनुरूप ढाल देता है, जो लैंगिक रूढ़ धारणाओं को मज़बूत कर सकता है।"},
  {"id":"cdp-child-development-1876","question":"Health records show that girls in a district now reach menarche, on average, a year or more earlier than their grandmothers did, and are taller as adults. This trend is mainly explained by:","options":["Better nutrition and health across generations, known as the secular trend","A genetic change in the population that has built up over two generations","Earlier admission to school, which speeds up children’s physical growth","Greater exam competition, which triggers the early release of growth hormones"],"answer":0,"explanation":"The secular trend towards earlier puberty and greater height has followed improvements in nutrition, health and living conditions; two or three generations are far too short for genetic change to explain it.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"स्वास्थ्य अभिलेख दर्शाते हैं कि एक ज़िले में लड़कियाँ अब औसतन अपनी दादियों की तुलना में एक वर्ष या अधिक पहले रजोदर्शन तक पहुँचती हैं और वयस्क के रूप में अधिक लंबी होती हैं। इस प्रवृत्ति की मुख्य व्याख्या क्या है?","optionsHi":["पीढ़ियों में बेहतर पोषण और स्वास्थ्य, जिसे दीर्घकालिक प्रवृत्ति (सेक्युलर ट्रेंड) कहते हैं","जनसंख्या में आनुवंशिक परिवर्तन जो दो पीढ़ियों में संचित हुआ है","विद्यालय में जल्दी प्रवेश, जो बच्चों की शारीरिक वृद्धि को तेज़ करता है","अधिक परीक्षा-प्रतिस्पर्धा, जो वृद्धि हार्मोनों के शीघ्र स्राव को ट्रिगर करती है"],"explanationHi":"पहले यौवनारंभ और अधिक ऊँचाई की ओर दीर्घकालिक प्रवृत्ति पोषण, स्वास्थ्य और रहन-सहन की स्थितियों में सुधार के साथ चली है; दो या तीन पीढ़ियाँ आनुवंशिक परिवर्तन से इसकी व्याख्या के लिए बहुत छोटी हैं।"},
  {"id":"cdp-child-development-1877","question":"In Class 6, many girls are taller than the boys; by Class 10 most boys have caught up and passed them. The best explanation is that:","options":["Boys grow at a steady rate throughout, while girls stop growing at about twelve","Girls’ growth spurt usually starts about two years before boys’ does","Girls get better nutrition in childhood, which stops mattering in adolescence","Boys’ growth spurt happens in early childhood, before they join school"],"answer":1,"explanation":"Girls start and finish their growth spurt earlier; boys’ spurt comes later, lasts longer and is larger, so they overtake girls in mid-adolescence.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 6 में, अनेक लड़कियाँ लड़कों से लंबी हैं; कक्षा 10 तक अधिकांश लड़के उन्हें पकड़कर आगे निकल चुके हैं। सबसे अच्छी व्याख्या यह है कि:","optionsHi":["लड़के पूरे समय स्थिर दर से बढ़ते हैं, जबकि लड़कियाँ लगभग बारह वर्ष पर बढ़ना बंद कर देती हैं","लड़कियों की वृद्धि-तेज़ी सामान्यतः लड़कों की तुलना में लगभग दो वर्ष पहले शुरू होती है","लड़कियों को बाल्यावस्था में बेहतर पोषण मिलता है, जो किशोरावस्था में मायने नहीं रखता","लड़कों की वृद्धि-तेज़ी प्रारंभिक बाल्यावस्था में, विद्यालय में आने से पहले होती है"],"explanationHi":"लड़कियाँ अपनी वृद्धि-तेज़ी जल्दी शुरू और समाप्त करती हैं; लड़कों की तेज़ी बाद में आती है, अधिक समय चलती है और बड़ी होती है, इसलिए वे मध्य किशोरावस्था में लड़कियों से आगे निकल जाते हैं।"},
  {"id":"cdp-child-development-1878","question":"Which statement about early-maturing boys is best supported by research?","options":["They show no social differences from other boys, since only girls are affected by pubertal timing","They are usually more anxious and less popular, since their changing bodies make them stand out from classmates","They are often more popular and confident, but are also at higher risk of early substance use and rule-breaking","They do better in every respect, so schools should try to speed up maturation in other boys"],"answer":2,"explanation":"Early maturation often brings status for boys through size and sports, but it also draws them towards older peers and earlier risky behaviour; anxiety and lower status are more typical of late-maturing boys.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"शीघ्र परिपक्व होने वाले लड़कों के बारे में कौन-सा कथन शोध से सबसे अच्छी तरह समर्थित है?","optionsHi":["वे अन्य लड़कों से कोई सामाजिक अंतर नहीं दिखाते, क्योंकि केवल लड़कियाँ ही यौवनारंभ के समय से प्रभावित होती हैं","वे प्रायः अधिक चिंतित और कम लोकप्रिय होते हैं, क्योंकि उनके बदलते शरीर उन्हें सहपाठियों से अलग दिखाते हैं","वे प्रायः अधिक लोकप्रिय और आत्मविश्वासी होते हैं, परंतु शीघ्र मादक पदार्थों के उपयोग और नियम-उल्लंघन का भी उच्च जोखिम रखते हैं","वे हर दृष्टि से बेहतर करते हैं, इसलिए विद्यालयों को अन्य लड़कों की परिपक्वता तेज़ करने का प्रयास करना चाहिए"],"explanationHi":"शीघ्र परिपक्वता प्रायः आकार और खेल के माध्यम से लड़कों को प्रतिष्ठा दिलाती है, परंतु यह उन्हें बड़े साथियों और जल्दी जोखिम भरे व्यवहार की ओर भी खींचती है; चिंता और निम्न प्रतिष्ठा विलंब से परिपक्व होने वाले लड़कों के लिए अधिक विशिष्ट हैं।"},
  {"id":"cdp-child-development-1879","question":"Many Class 11 students are sleepy and slow in a 7:30 a.m. first period, though they say they cannot fall asleep before 11 p.m. Sleep research explains this mainly by:","options":["An attention disorder that appears in most students at about sixteen years","Laziness learnt from late-night phone use, which is the only real cause of this pattern","Lower total sleep needs in adolescence, so they simply do not feel tired late at night","A biological shift in adolescents’ body clock, with sleep hormones released later at night"],"answer":3,"explanation":"Puberty shifts the circadian rhythm so that melatonin is released later, pushing natural sleep and wake times later while sleep needs remain high; screens can worsen this but are not the only cause.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 11 के अनेक छात्र सुबह 7:30 बजे के पहले पीरियड में नींद में और धीमे रहते हैं, यद्यपि वे कहते हैं कि रात 11 बजे से पहले सो नहीं पाते। निद्रा-शोध इसे मुख्यतः किससे समझाता है?","optionsHi":["एक ध्यान संबंधी विकार जो अधिकांश छात्रों में लगभग सोलह वर्ष की आयु पर प्रकट होता है","देर रात फ़ोन के उपयोग से सीखा आलस्य, जो इस प्रतिरूप का एकमात्र वास्तविक कारण है","किशोरावस्था में कम कुल नींद की आवश्यकता, इसलिए उन्हें रात को देर तक बस थकान महसूस नहीं होती","किशोरों की शारीरिक घड़ी में जैविक परिवर्तन, जिसमें नींद के हार्मोन रात में देर से स्रावित होते हैं"],"explanationHi":"यौवनारंभ सर्केडियन लय को बदल देता है ताकि मेलाटोनिन देर से स्रावित हो, जो नींद की आवश्यकता ऊँची रहते हुए स्वाभाविक सोने-जागने के समय को देर की ओर धकेलता है; स्क्रीन इसे बिगाड़ सकती हैं पर एकमात्र कारण नहीं हैं।"},
  {"id":"cdp-child-development-1880","question":"A 16-year-old reasons as well as an adult about risks in a calm classroom discussion, yet takes a dangerous dare at night with friends watching. Which distinction best explains this gap?","options":["‘Cold’ cognition matures earlier than ‘hot’ cognition used in emotionally charged, social situations","Formal operations are lost in social settings and must be regained each time the person is alone","Adolescents understand risks only when they are told about them by a trusted adult","Adolescents have a weaker knowledge of risks than adults, whatever the situation"],"answer":0,"explanation":"Logical reasoning under calm conditions is adult-like by mid-adolescence, but self-control in arousing, peer-laden situations matures later, as the dual-systems account explains. Knowledge of risks is not the problem.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"एक 16 वर्षीय शांत कक्षा-चर्चा में जोखिमों के बारे में वयस्क जितना अच्छा तर्क करता है, फिर भी रात में मित्रों के देखते हुए खतरनाक चुनौती स्वीकार कर लेता है। कौन-सा भेद इस अंतर की सबसे अच्छी व्याख्या करता है?","optionsHi":["‘शीतल’ संज्ञान ‘उष्ण’ संज्ञान से पहले परिपक्व होता है, जिसका प्रयोग भावनात्मक रूप से आवेशित, सामाजिक स्थितियों में होता है","औपचारिक संक्रियाएँ सामाजिक परिवेशों में खो जाती हैं और व्यक्ति के अकेले होने पर हर बार पुनः प्राप्त करनी पड़ती हैं","किशोर जोखिमों को तभी समझते हैं जब कोई विश्वसनीय वयस्क उन्हें बताता है","किशोरों को जोखिमों का ज्ञान वयस्कों से कम होता है, स्थिति चाहे जो हो"],"explanationHi":"शांत परिस्थितियों में तार्किक चिंतन मध्य किशोरावस्था तक वयस्क जैसा हो जाता है, परंतु उत्तेजक, साथी-भरी परिस्थितियों में आत्म-नियंत्रण बाद में परिपक्व होता है, जैसा द्वि-तंत्र विवरण समझाता है। जोखिमों का ज्ञान समस्या नहीं है।"},
  {"id":"cdp-child-development-1881","question":"Robert Havighurst defined a developmental task as one that:","options":["Is decided only by physical maturation, with no part played by society or by the individual","Is set by teachers for each class level and must be passed before a child can be promoted","Appears only in adolescence and is resolved once and for all by about eighteen years","Arises around a certain period of life, and mastering it eases later tasks"],"answer":3,"explanation":"Havighurst saw developmental tasks as arising from physical maturation, cultural pressure and personal values; mastering them leads to adjustment and success later, while failure brings difficulty with later tasks.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"रॉबर्ट हैविगहर्स्ट ने विकासात्मक कार्य को ऐसा कार्य परिभाषित किया जो:","optionsHi":["केवल शारीरिक परिपक्वता से तय होता है, जिसमें समाज या व्यक्ति की कोई भूमिका नहीं","शिक्षकों द्वारा प्रत्येक कक्षा-स्तर के लिए निर्धारित किया जाता है और बच्चे के पदोन्नत होने से पहले उसे पास करना होता है","केवल किशोरावस्था में प्रकट होता है और लगभग अठारह वर्ष तक सदा के लिए सुलझ जाता है","जीवन की एक निश्चित अवधि के आसपास उत्पन्न होता है, और उसमें निपुणता पाना बाद के कार्यों को आसान बनाता है"],"explanationHi":"हैविगहर्स्ट विकासात्मक कार्यों को शारीरिक परिपक्वता, सांस्कृतिक दबाव और व्यक्तिगत मूल्यों से उत्पन्न मानते थे; उनमें निपुणता बाद में समायोजन और सफलता की ओर ले जाती है, जबकि विफलता बाद के कार्यों में कठिनाई लाती है।"},
  {"id":"cdp-child-development-1882","question":"A Class 10 student increasingly wants to make her own decisions and depends less on her parents for emotional support, though she still loves them. Leta Hollingworth called this adolescent process:","options":["Identity foreclosure","Psychological weaning","Emotional regression","Reactive detachment disorder"],"answer":1,"explanation":"Hollingworth used ‘psychological weaning’ for the adolescent’s gradual emotional and practical move towards independence from the family; it is a normal developmental process, not a disorder.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 10 की एक छात्रा अधिकाधिक अपने निर्णय स्वयं लेना चाहती है और भावनात्मक सहारे के लिए अपने माता-पिता पर कम निर्भर रहती है, यद्यपि वह अब भी उनसे प्रेम करती है। लीटा हॉलिंगवर्थ ने इस किशोर प्रक्रिया को क्या कहा?","optionsHi":["पहचान अवरुद्धता","मनोवैज्ञानिक स्तन्य-त्याग (साइकोलॉजिकल वीनिंग)","संवेगात्मक प्रतिगमन","प्रतिक्रियात्मक विलगन विकार"],"explanationHi":"हॉलिंगवर्थ ने किशोर के परिवार से स्वतंत्रता की ओर क्रमिक संवेगात्मक और व्यावहारिक गति के लिए ‘मनोवैज्ञानिक स्तन्य-त्याग’ का प्रयोग किया; यह एक सामान्य विकासात्मक प्रक्रिया है, विकार नहीं।"},
  {"id":"cdp-child-development-1883","question":"Harry Stack Sullivan held that, just before adolescence, the most important new need is met by a close same-sex friend, a ‘chum’. This need is for:","options":["Acceptance, through membership of a large and popular peer group","Tenderness, through the physical care and comfort given by a parent","Intimacy, through a relationship of mutual concern between equals","Romantic love, through a partner of the other sex at this age"],"answer":2,"explanation":"Sullivan placed the need for intimacy in preadolescence, first met in a chumship; tenderness belongs to infancy and the desire for romantic partners comes later in adolescence.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"हैरी स्टैक सुलिवन का मत था कि किशोरावस्था से ठीक पहले, सबसे महत्वपूर्ण नई आवश्यकता एक घनिष्ठ समलिंग मित्र, एक ‘चम’, द्वारा पूरी होती है। यह आवश्यकता किसकी है?","optionsHi":["स्वीकृति की, किसी बड़े और लोकप्रिय साथी-समूह की सदस्यता के माध्यम से","कोमलता की, माता-पिता द्वारा दी गई शारीरिक देखभाल और सांत्वना के माध्यम से","आत्मीयता की, बराबर वालों के बीच पारस्परिक चिंता वाले संबंध के माध्यम से","रोमानी प्रेम की, इस आयु में विपरीत लिंग के साथी के माध्यम से"],"explanationHi":"सुलिवन ने आत्मीयता की आवश्यकता को पूर्व-किशोरावस्था में रखा, जो पहले एक ‘चम’ संबंध में पूरी होती है; कोमलता शैशवावस्था की है और रोमानी साथियों की इच्छा किशोरावस्था में बाद में आती है।"},
  {"id":"cdp-child-development-1884","question":"In Dexter Dunphy’s classic account of how adolescent peer groups change, which sequence is correct?","options":["Same-sex cliques → a mixed-sex crowd of linked cliques → loose groups of couples","A mixed-sex crowd of linked cliques → same-sex cliques → loose groups of couples","Loose groups of couples → same-sex cliques → a mixed-sex crowd of linked cliques","Same-sex cliques → loose groups of couples → a mixed-sex crowd of linked cliques"],"answer":0,"explanation":"Dunphy observed early adolescents in same-sex cliques, which then joined into larger mixed-sex crowds, and in late adolescence the crowd broke up into loosely linked couples.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"डेक्स्टर डनफ़ी के किशोर साथी-समूहों के बदलने के शास्त्रीय विवरण में, कौन-सा क्रम सही है?","optionsHi":["समलिंग गुट → जुड़े हुए गुटों की मिश्र-लिंग भीड़ → जोड़ों के ढीले समूह","जुड़े हुए गुटों की मिश्र-लिंग भीड़ → समलिंग गुट → जोड़ों के ढीले समूह","जोड़ों के ढीले समूह → समलिंग गुट → जुड़े हुए गुटों की मिश्र-लिंग भीड़","समलिंग गुट → जोड़ों के ढीले समूह → जुड़े हुए गुटों की मिश्र-लिंग भीड़"],"explanationHi":"डनफ़ी ने प्रारंभिक किशोरों को समलिंग गुटों में देखा, जो फिर बड़ी मिश्र-लिंग भीड़ों में जुड़ गए, और उत्तर किशोरावस्था में भीड़ ढीले जुड़े जोड़ों में बँट गई।"},
  {"id":"cdp-child-development-1885","question":"In a large school, students talk about ‘the toppers’, ‘the sports gang’ and ‘the band kids’, though many so labelled have never spoken to each other. Researchers call such reputation-based groups:","options":["Chumships","Cliques","Dyads","Crowds"],"answer":3,"explanation":"Crowds are larger, reputation-based categories that place students by image or activity, whether or not members interact; cliques are small groups of friends who actually spend time together.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक बड़े विद्यालय में, छात्र ‘अव्वल लोगों’, ‘खेल वाली टोली’ और ‘बैंड वाले बच्चों’ की बात करते हैं, यद्यपि इस तरह लेबल किए गए अनेक ने कभी एक-दूसरे से बात नहीं की। शोधकर्ता ऐसे प्रतिष्ठा-आधारित समूहों को क्या कहते हैं?","optionsHi":["चम संबंध","गुट (क्लिक)","युग्म (डायड)","भीड़ (क्राउड)"],"explanationHi":"भीड़ बड़ी, प्रतिष्ठा-आधारित श्रेणियाँ हैं जो छात्रों को छवि या गतिविधि के आधार पर रखती हैं, चाहे सदस्य परस्पर बातचीत करें या नहीं; गुट मित्रों के छोटे समूह हैं जो वास्तव में साथ समय बिताते हैं।"},
  {"id":"cdp-child-development-1886","question":"The son of a respected police officer, constantly told to be a ‘model student’, begins skipping school and openly copying the local troublemakers’ style. Erikson might describe this as:","options":["Identity achievement: committing to values after a period of exploration","A negative identity: taking on the very roles presented as most undesirable","Identity foreclosure: accepting his parents’ choices without exploring","Generativity: caring for the next generation through guidance and teaching"],"answer":1,"explanation":"Erikson described a negative identity as one built, often defiantly, on roles adults have shown as most undesirable, when acceptable identities seem out of reach or imposed.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"एक सम्मानित पुलिस अधिकारी का बेटा, जिसे निरंतर ‘आदर्श छात्र’ बनने को कहा जाता है, विद्यालय से भागने और स्थानीय उपद्रवियों की शैली की खुलेआम नकल करने लगता है। एरिक्सन इसे क्या कहेंगे?","optionsHi":["पहचान की प्राप्ति: खोज की अवधि के बाद मूल्यों के प्रति प्रतिबद्ध होना","नकारात्मक पहचान: ठीक उन्हीं भूमिकाओं को अपनाना जिन्हें सबसे अवांछनीय बताया गया हो","पहचान अवरुद्धता: बिना खोज के अपने माता-पिता के चयनों को स्वीकार करना","उत्पादकता: मार्गदर्शन और शिक्षण द्वारा अगली पीढ़ी की देखभाल करना"],"explanationHi":"एरिक्सन ने नकारात्मक पहचान को ऐसी पहचान बताया जो, प्रायः अवज्ञा में, उन भूमिकाओं पर बनी हो जिन्हें वयस्कों ने सबसे अवांछनीय दिखाया हो, जब स्वीकार्य पहचानें पहुँच से बाहर या थोपी हुई लगती हैं।"},
  {"id":"cdp-child-development-1887","question":"A Class 11 student from a tribal community, who had never thought about her heritage, begins reading about her community’s history, talking to elders and attending cultural events, unsure what it means for her. In Jean Phinney’s model, she is in the stage of:","options":["Achieved ethnic identity","Unexamined ethnic identity","Ethnic identity search","Ethnic identity diffusion"],"answer":2,"explanation":"Phinney’s model moves from an unexamined ethnic identity, through a search (exploration) stage, to an achieved, secure sense of one’s ethnic identity; active exploration without settled commitment marks the search stage.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"कक्षा 11 की एक जनजातीय समुदाय की छात्रा, जिसने कभी अपनी विरासत के बारे में नहीं सोचा था, अपने समुदाय का इतिहास पढ़ना, बुज़ुर्गों से बात करना और सांस्कृतिक आयोजनों में जाना शुरू करती है, अनिश्चित कि यह उसके लिए क्या अर्थ रखता है। जीन फिनी के मॉडल में, वह किस अवस्था में है?","optionsHi":["प्राप्त जातीय पहचान","अपरीक्षित जातीय पहचान","जातीय पहचान की खोज","जातीय पहचान विसरण"],"explanationHi":"फिनी का मॉडल अपरीक्षित जातीय पहचान से, खोज (अन्वेषण) अवस्था से होते हुए, अपनी जातीय पहचान की प्राप्त, सुरक्षित भावना तक जाता है; स्थिर प्रतिबद्धता के बिना सक्रिय खोज खोज-अवस्था का चिह्न है।"},
  {"id":"cdp-child-development-1888","question":"Asked, ‘If all purple animals have six legs, and Bholu is a purple animal, how many legs does Bholu have?’, an eight-year-old says, ‘There are no purple animals!’ while a fourteen-year-old answers ‘six’. The older child shows:","options":["Propositional thought, reasoning from premises regardless of whether they are true","Conservation, recognising that quantity stays the same despite changes in form","Seriation, arranging items in order along a dimension such as length","Animism, attributing life and feelings to things that are not alive"],"answer":0,"explanation":"In the formal operational stage adolescents can judge the logic of statements apart from real-world content; concrete thinkers tie reasoning to known reality and reject premises contrary to fact.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"यह पूछे जाने पर, ‘यदि सभी बैंगनी जानवरों के छह पैर होते हैं, और भोलू एक बैंगनी जानवर है, तो भोलू के कितने पैर हैं?’ आठ वर्ष का बच्चा कहता है, ‘बैंगनी जानवर होते ही नहीं!’ जबकि चौदह वर्ष का बच्चा उत्तर देता है ‘छह’। बड़ा बच्चा क्या दर्शाता है?","optionsHi":["प्रस्तावात्मक चिंतन, आधार-वाक्यों से तर्क करना चाहे वे सत्य हों या नहीं","संरक्षण, यह पहचानना कि रूप बदलने पर भी मात्रा वही रहती है","क्रमबद्धता, मदों को लंबाई जैसे आयाम के अनुसार क्रम में रखना","सजीवारोपण, जो चीज़ें जीवित नहीं हैं उनमें जीवन और भावनाओं का आरोपण करना"],"explanationHi":"औपचारिक संक्रियात्मक अवस्था में किशोर वास्तविक जगत की विषयवस्तु से अलग कथनों के तर्क का निर्णय कर सकते हैं; मूर्त चिंतक तर्क को ज्ञात वास्तविकता से बाँधते हैं और तथ्य के विपरीत आधार-वाक्यों को अस्वीकार कर देते हैं।"},
  {"id":"cdp-child-development-1889","question":"Ananya passionately campaigns for a plastic-free school in assembly, yet leaves plastic wrappers on her desk. David Elkind would describe this as:","options":["Imaginary audience: believing that everyone is watching and judging her behaviour","Personal fable: believing that her experiences are unique and that nothing can harm her","Apparent hypocrisy: believing that stating an ideal is the same as living up to it","Pseudostupidity: approaching a simple problem at too complex a level and failing"],"answer":2,"explanation":"Elkind used apparent hypocrisy for young adolescents’ feeling that expressing an ideal is enough, without the work of acting on it; it is a cognitive immaturity rather than deliberate dishonesty.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"अनन्या सभा में प्लास्टिक-मुक्त विद्यालय के लिए जोश से अभियान चलाती है, फिर भी अपनी डेस्क पर प्लास्टिक की पन्नियाँ छोड़ देती है। डेविड एल्काइंड इसे क्या कहेंगे?","optionsHi":["काल्पनिक दर्शक: यह विश्वास कि सब उसके व्यवहार को देख रहे और आँक रहे हैं","व्यक्तिगत कथा: यह विश्वास कि उसके अनुभव अनूठे हैं और उसे कुछ हानि नहीं पहुँचा सकता","आभासी पाखंड: यह विश्वास कि किसी आदर्श को कह देना उस पर चलने के बराबर है","छद्म-मूर्खता: किसी सरल समस्या को अत्यधिक जटिल स्तर पर देखना और असफल होना"],"explanationHi":"एल्काइंड ने आभासी पाखंड का प्रयोग छोटे किशोरों की इस अनुभूति के लिए किया कि आदर्श को व्यक्त करना ही पर्याप्त है, उस पर अमल करने के श्रम के बिना; यह जानबूझकर बेईमानी नहीं, संज्ञानात्मक अपरिपक्वता है।"},
  {"id":"cdp-child-development-1890","question":"A bright Class 8 student gets a simple puzzle wrong because she looks for hidden tricks and complex motives that are not there. Elkind called this tendency:","options":["Personal fable","Pseudostupidity","Apparent hypocrisy","Imaginary audience"],"answer":1,"explanation":"Elkind’s pseudostupidity is the young adolescent’s habit of over-interpreting simple situations with newly gained formal thinking, so she fails not because the task is too hard but because it is too simple.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 8 की एक मेधावी छात्रा एक सरल पहेली गलत हल करती है क्योंकि वह छिपी चालें और जटिल मंतव्य खोजती है जो वहाँ हैं ही नहीं। एल्काइंड ने इस प्रवृत्ति को क्या कहा?","optionsHi":["व्यक्तिगत कथा","छद्म-मूर्खता","आभासी पाखंड","काल्पनिक दर्शक"],"explanationHi":"एल्काइंड की छद्म-मूर्खता छोटे किशोर की नए पाए औपचारिक चिंतन से सरल स्थितियों की अति-व्याख्या करने की आदत है, इसलिए वह इसलिए असफल नहीं होती कि कार्य बहुत कठिन है बल्कि इसलिए कि वह बहुत सरल है।"},
  {"id":"cdp-child-development-1891","question":"Simmons and Blyth found that girls’ self-esteem dropped most when they moved to a new, larger school at the same time as they were going through puberty. Their explanation was that:","options":["Girls’ self-esteem falls at thirteen for purely biological reasons","Puberty by itself lowers self-esteem, whatever kind of school a girl is in","A change of school by itself lowers self-esteem, whatever the stage of puberty","Several major changes at once overwhelm coping more than the same changes spread out"],"answer":3,"explanation":"Their ‘cumulative change’ view held that adolescents cope better when changes come one at a time; girls in schools without an early transition, facing puberty alone, showed smaller drops.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"सिमन्स और ब्लाइथ ने पाया कि लड़कियों का आत्म-सम्मान तब सबसे अधिक गिरा जब वे यौवनारंभ से गुज़रते समय ही नए, बड़े विद्यालय में गईं। उनकी व्याख्या यह थी कि:","optionsHi":["तेरह वर्ष की आयु में लड़कियों का आत्म-सम्मान विशुद्ध जैविक कारणों से गिरता है","यौवनारंभ अपने आप आत्म-सम्मान घटाता है, लड़की किसी भी प्रकार के विद्यालय में हो","विद्यालय का परिवर्तन अपने आप आत्म-सम्मान घटाता है, यौवनारंभ की अवस्था चाहे जो हो","एक साथ कई बड़े परिवर्तन उन्हीं परिवर्तनों के अलग-अलग फैले होने की तुलना में सामना करने की क्षमता को अधिक अभिभूत करते हैं"],"explanationHi":"उनका ‘संचयी परिवर्तन’ मत था कि किशोर तब बेहतर सामना करते हैं जब परिवर्तन एक-एक करके आते हैं; जिन विद्यालयों में शीघ्र संक्रमण नहीं था, वहाँ अकेले यौवनारंभ का सामना करने वाली लड़कियों में गिरावट कम रही।"},
  {"id":"cdp-child-development-1892","question":"A 15-year-old writes, ‘I’m cheerful with friends, rude at home and shy in class. Which one is the real me?’ and feels upset by this. Susan Harter’s research suggests that:","options":["Noticing contradictory selves across roles peaks in mid-adolescence and is later integrated","This shows a serious identity disorder that needs specialist treatment straight away","Such contradictions are common in early childhood but become rare after about age ten","She is in Piaget’s concrete stage and cannot yet think abstractly about herself"],"answer":0,"explanation":"With abstract thought, middle adolescents notice that their traits differ across settings but cannot yet integrate them, which causes distress; by late adolescence they form higher-order ideas such as ‘moody’ or ‘flexible’.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"एक 15 वर्षीया लिखती है, ‘मैं दोस्तों के साथ हँसमुख, घर पर रूखी और कक्षा में संकोची हूँ। इनमें से असली मैं कौन-सी हूँ?’ और इससे व्यथित होती है। सूज़न हार्टर का शोध सुझाता है कि:","optionsHi":["भूमिकाओं में विरोधी स्वों को देखना मध्य किशोरावस्था में चरम पर होता है और बाद में एकीकृत हो जाता है","यह गंभीर पहचान-विकार दर्शाता है जिसके लिए तुरंत विशेषज्ञ उपचार चाहिए","ऐसे विरोधाभास प्रारंभिक बाल्यावस्था में सामान्य हैं पर लगभग दस वर्ष की आयु के बाद दुर्लभ हो जाते हैं","वह पियाजे की मूर्त अवस्था में है और अभी अपने बारे में अमूर्त रूप से नहीं सोच सकती"],"explanationHi":"अमूर्त चिंतन के साथ, मध्य किशोर ध्यान देते हैं कि उनके गुण परिवेशों में भिन्न हैं पर उन्हें अभी एकीकृत नहीं कर पाते, जिससे व्यथा होती है; उत्तर किशोरावस्था तक वे ‘मनमौजी’ या ‘लचीला’ जैसे उच्च-स्तरीय विचार बनाते हैं।"},
  {"id":"cdp-child-development-1893","question":"Laurence Steinberg distinguished three kinds of adolescent autonomy. A Class 12 student who forms her own reasoned views on right and wrong, rather than taking them from parents or friends, shows:","options":["Behavioural autonomy","Emotional autonomy","Value autonomy","Economic autonomy"],"answer":2,"explanation":"Emotional autonomy concerns relinquishing childish dependence on parents, behavioural autonomy making and acting on one’s own decisions, and value autonomy holding an independent set of principles.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"लॉरेंस स्टाइनबर्ग ने किशोर स्वायत्तता के तीन प्रकारों में भेद किया। कक्षा 12 की एक छात्रा जो सही और गलत पर अपने तर्कसंगत विचार स्वयं बनाती है, माता-पिता या मित्रों से लेने के बजाय, क्या दर्शाती है?","optionsHi":["व्यवहारिक स्वायत्तता","संवेगात्मक स्वायत्तता","मूल्य स्वायत्तता","आर्थिक स्वायत्तता"],"explanationHi":"संवेगात्मक स्वायत्तता माता-पिता पर बचकानी निर्भरता को छोड़ने से संबंधित है, व्यवहारिक स्वायत्तता अपने निर्णय स्वयं लेने और उन पर चलने से, और मूल्य स्वायत्तता सिद्धांतों का स्वतंत्र समूह रखने से।"},
  {"id":"cdp-child-development-1894","question":"Research by Stattin and Kerr on how parents come to know what their adolescents are doing found that parents’ knowledge comes mainly from:","options":["Strict rules and curfews set by the parents","The adolescent’s own willingness to tell them","Parents’ questioning of friends and teachers","Checking the adolescent’s phone and private messages"],"answer":1,"explanation":"Their studies found that what parents know depends mostly on the teenager’s voluntary disclosure, which flows from a warm, trusting relationship, rather than from parental control or surveillance.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"माता-पिता को अपने किशोरों के कार्यों का पता कैसे चलता है, इस पर स्टैटिन और केर के शोध ने पाया कि माता-पिता का ज्ञान मुख्यतः किससे आता है:","optionsHi":["माता-पिता द्वारा बनाए गए कठोर नियमों और समय-सीमाओं से","किशोर की स्वयं उन्हें बताने की इच्छा से","माता-पिता द्वारा मित्रों और शिक्षकों से पूछताछ से","किशोर के फ़ोन और निजी संदेशों की जाँच से"],"explanationHi":"उनके अध्ययनों में पाया गया कि माता-पिता जो जानते हैं वह मुख्यतः किशोर के स्वैच्छिक प्रकटीकरण पर निर्भर करता है, जो गर्मजोशी भरे, विश्वासपूर्ण संबंध से आता है, माता-पिता के नियंत्रण या निगरानी से नहीं।"},
  {"id":"cdp-child-development-1895","question":"Which of these statements about adolescence are supported by research? I. Before puberty boys and girls show similar rates of depression, but after puberty girls show about twice the rate. II. Body dissatisfaction tends to rise in many girls during puberty. III. Most adolescents go through severe, continuous turmoil with their families.","options":["I, II and III","I and III only","II and III only","I and II only"],"answer":3,"explanation":"The gender gap in depression and the rise in girls’ body dissatisfaction around puberty are well documented; severe, continuous turmoil describes only a minority, contrary to the ‘storm and stress’ stereotype.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"किशोरावस्था के बारे में इनमें से कौन-से कथन शोध से समर्थित हैं? I. यौवनारंभ से पहले लड़के और लड़कियाँ अवसाद की समान दर दिखाते हैं, पर यौवनारंभ के बाद लड़कियाँ लगभग दोगुनी दर दिखाती हैं। II. अनेक लड़कियों में यौवनारंभ के दौरान शरीर के प्रति असंतोष बढ़ने की प्रवृत्ति होती है। III. अधिकांश किशोर अपने परिवारों के साथ गंभीर, निरंतर उथल-पुथल से गुज़रते हैं।","optionsHi":["I, II और III","केवल I और III","केवल II और III","केवल I और II"],"explanationHi":"अवसाद में लैंगिक अंतर और यौवनारंभ के आसपास लड़कियों के शरीर-असंतोष में वृद्धि भली-भाँति प्रलेखित हैं; गंभीर, निरंतर उथल-पुथल केवल अल्पसंख्यक का वर्णन करती है, ‘आँधी और तनाव’ की रूढ़ धारणा के विपरीत।"},
  {"id":"cdp-child-development-1896","question":"A Class 9 student says, ‘I like science, I’m good at maths and I want work that helps people, so maybe medicine or engineering.’ In Eli Ginzberg’s theory of career choice, she is in the:","options":["Tentative period","Fantasy period","Realistic period","Maintenance period"],"answer":0,"explanation":"Ginzberg described a fantasy period in childhood, a tentative period in early adolescence when interests, capacities and values are weighed, and a realistic period from about 17 when options are explored and narrowed.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 9 की एक छात्रा कहती है, ‘मुझे विज्ञान पसंद है, मैं गणित में अच्छी हूँ और मैं ऐसा काम चाहती हूँ जो लोगों की मदद करे, तो शायद चिकित्सा या इंजीनियरिंग।’ एली गिंज़बर्ग के कैरियर-चयन सिद्धांत में, वह किस अवधि में है?","optionsHi":["अस्थायी अवधि","काल्पनिक अवधि","यथार्थवादी अवधि","अनुरक्षण अवधि"],"explanationHi":"गिंज़बर्ग ने बाल्यावस्था में काल्पनिक अवधि, प्रारंभिक किशोरावस्था में अस्थायी अवधि जब रुचियों, क्षमताओं और मूल्यों को तौला जाता है, और लगभग 17 वर्ष से यथार्थवादी अवधि बताई जब विकल्पों की खोज और संकुचन होता है।"},
  {"id":"cdp-child-development-1897","question":"A Class 10 student enjoys repairing bicycles, working with tools and building things with his hands. In John Holland’s RIASEC model, his interests are closest to the:","options":["Artistic type","Investigative type","Realistic type","Enterprising type"],"answer":2,"explanation":"Holland’s Realistic type prefers practical, hands-on work with tools, machines and objects; Investigative people like ideas and analysis, Artistic people self-expression, Enterprising people persuading and leading.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 10 के एक छात्र को साइकिलें ठीक करना, औज़ारों के साथ काम करना और हाथों से चीज़ें बनाना पसंद है। जॉन हॉलैंड के RIASEC मॉडल में, उसकी रुचियाँ किसके सबसे निकट हैं?","optionsHi":["कलात्मक प्रकार","अन्वेषणात्मक प्रकार","यथार्थवादी प्रकार","उद्यमी प्रकार"],"explanationHi":"हॉलैंड का यथार्थवादी प्रकार औज़ारों, मशीनों और वस्तुओं के साथ व्यावहारिक, हाथ से किए जाने वाले कार्य को पसंद करता है; अन्वेषणात्मक लोग विचारों और विश्लेषण को, कलात्मक लोग आत्म-अभिव्यक्ति को, उद्यमी लोग मनाने और नेतृत्व करने को पसंद करते हैं।"},
  {"id":"cdp-child-development-1898","question":"Which set consists entirely of core life skills listed by the World Health Organization for school-based life skills education?","options":["Decision making, time management, coping with stress","Decision making, empathy, coping with stress","Empathy, leadership, critical thinking","Self-awareness, goal setting, problem solving"],"answer":1,"explanation":"WHO’s ten core life skills are decision making, problem solving, creative thinking, critical thinking, effective communication, interpersonal relationships, self-awareness, empathy, coping with emotions and coping with stress.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कौन-सा समूह पूरी तरह उन मूल जीवन-कौशलों से बना है जिन्हें विश्व स्वास्थ्य संगठन ने विद्यालय-आधारित जीवन-कौशल शिक्षा के लिए सूचीबद्ध किया है?","optionsHi":["निर्णय लेना, समय प्रबंधन, तनाव का सामना करना","निर्णय लेना, समानुभूति, तनाव का सामना करना","समानुभूति, नेतृत्व, आलोचनात्मक चिंतन","आत्म-जागरूकता, लक्ष्य निर्धारण, समस्या-समाधान"],"explanationHi":"WHO के दस मूल जीवन-कौशल हैं: निर्णय लेना, समस्या-समाधान, सृजनात्मक चिंतन, आलोचनात्मक चिंतन, प्रभावी संप्रेषण, अंतर्वैयक्तिक संबंध, आत्म-जागरूकता, समानुभूति, संवेगों का सामना और तनाव का सामना।"},
  {"id":"cdp-child-development-1899","question":"Which feature most clearly makes cyberbullying harder for adolescents to escape than playground bullying?","options":["It is always carried out by older students against younger ones","It always involves physical threats that are later carried out inside the school","It happens only between students who have never met each other in person","It can reach the victim at any hour and spread to a wide audience, often anonymously"],"answer":3,"explanation":"Online bullying follows the student home, can be shared widely and kept, and may be anonymous; it frequently involves classmates and is not limited to physical threats or older bullies.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कौन-सी विशेषता साइबरबुलिंग से बचना किशोरों के लिए खेल-मैदान की धमकी से अधिक कठिन बनाती है?","optionsHi":["यह सदैव बड़े छात्रों द्वारा छोटे छात्रों के विरुद्ध की जाती है","इसमें सदैव शारीरिक धमकियाँ शामिल होती हैं जो बाद में विद्यालय के भीतर पूरी की जाती हैं","यह केवल उन छात्रों के बीच होती है जो कभी व्यक्तिगत रूप से नहीं मिले","यह किसी भी समय पीड़ित तक पहुँच सकती है और व्यापक दर्शकों में फैल सकती है, प्रायः अनाम रूप से"],"explanationHi":"ऑनलाइन धमकी छात्र के पीछे घर तक आती है, व्यापक रूप से साझा और संग्रहीत की जा सकती है, और अनाम हो सकती है; इसमें प्रायः सहपाठी शामिल होते हैं और यह शारीरिक धमकियों या बड़े धमकाने वालों तक सीमित नहीं है।"},
  {"id":"cdp-child-development-1900","question":"A survey shows that most Class 10 students in a school believe ‘most of my classmates smoke’, though only a small minority actually do. A programme that shares the accurate figures with students is using the:","options":["Social norms approach","Fear-appeal approach","Information-deficit approach","Zero-tolerance approach"],"answer":0,"explanation":"The social norms approach corrects exaggerated beliefs about how common a risky behaviour is, because adolescents tend to conform to what they think peers do; fear appeals and bare health facts work differently.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक सर्वेक्षण दर्शाता है कि एक विद्यालय के अधिकांश कक्षा 10 के छात्र मानते हैं कि ‘मेरे अधिकांश सहपाठी धूम्रपान करते हैं’, यद्यपि वास्तव में केवल एक छोटा अल्पसंख्यक करता है। छात्रों के साथ सटीक आँकड़े साझा करने वाला कार्यक्रम किसका उपयोग कर रहा है?","optionsHi":["सामाजिक मानदंड उपागम","भय-अपील उपागम","सूचना-अभाव उपागम","शून्य-सहिष्णुता उपागम"],"explanationHi":"सामाजिक मानदंड उपागम इस बारे में बढ़ा-चढ़ाकर की गई मान्यताओं को सुधारता है कि कोई जोखिम भरा व्यवहार कितना सामान्य है, क्योंकि किशोर उसके अनुरूप चलते हैं जो वे सोचते हैं कि साथी करते हैं; भय-अपील और केवल स्वास्थ्य-तथ्य भिन्न रूप से काम करते हैं।"},
  {"id":"cdp-child-development-1901","question":"During free play, four-year-old Tenzin stands near a group building a sand fort, watches closely, asks them questions and makes suggestions, but does not join in. In Mildred Parten’s categories, this is:","options":["Onlooker behaviour","Solitary play","Parallel play","Unoccupied behaviour"],"answer":0,"explanation":"An onlooker watches a particular group and may talk to them without joining; unoccupied behaviour is aimless watching of anything that catches attention, and parallel play means playing beside others with similar materials.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"मुक्त खेल के दौरान, चार वर्ष का तेनज़िंग रेत का किला बनाते एक समूह के पास खड़ा होकर ध्यान से देखता है, उनसे प्रश्न पूछता है और सुझाव देता है, पर शामिल नहीं होता। मिल्ड्रेड पार्टन की श्रेणियों में, यह क्या है?","optionsHi":["दर्शक व्यवहार","एकाकी खेल","समानांतर खेल","अनधिकृत (खाली) व्यवहार"],"explanationHi":"दर्शक किसी विशेष समूह को देखता है और शामिल हुए बिना उनसे बात कर सकता है; अनधिकृत व्यवहार किसी भी चीज़ को लक्ष्यहीन देखना है जो ध्यान खींचे, और समानांतर खेल का अर्थ है समान सामग्री के साथ दूसरों के पास खेलना।"},
  {"id":"cdp-child-development-1902","question":"Several pre-schoolers are all making clay animals at one table. They chat, lend each other tools and admire each other’s work, but each makes whatever he likes and there is no shared plan or division of roles. In Parten’s terms this is:","options":["Cooperative play","Associative play","Parallel play","Onlooker behaviour"],"answer":1,"explanation":"In associative play children interact and share materials but do not organise around a common goal; cooperative play involves a shared aim and assigned roles, while parallel play involves little interaction at all.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"अनेक पूर्व-विद्यालयी बच्चे एक ही मेज़ पर मिट्टी के पशु बना रहे हैं। वे बातें करते हैं, एक-दूसरे को औज़ार देते हैं और एक-दूसरे के काम की प्रशंसा करते हैं, पर प्रत्येक जो चाहे बनाता है और कोई साझा योजना या भूमिकाओं का विभाजन नहीं है। पार्टन के शब्दों में यह क्या है?","optionsHi":["सहकारी खेल","साहचर्य खेल","समानांतर खेल","दर्शक व्यवहार"],"explanationHi":"साहचर्य खेल में बच्चे अंतःक्रिया करते और सामग्री साझा करते हैं पर किसी साझा लक्ष्य के इर्द-गिर्द संगठित नहीं होते; सहकारी खेल में साझा उद्देश्य और सौंपी गई भूमिकाएँ होती हैं, जबकि समानांतर खेल में बहुत कम अंतःक्रिया होती है।"},
  {"id":"cdp-child-development-1903","question":"Parten saw solitary play as the least mature form of social play. Later research by Kenneth Rubin and others suggested that, for a five-year-old who often builds detailed models alone:","options":["The child is still at the stage of unoccupied behaviour and needs adult direction","Any solitary play at this age shows a social delay that needs immediate referral","Solitary constructive play is not in itself a warning sign and can go with competence","The child should be stopped from building alone and placed in a group every time"],"answer":2,"explanation":"Rubin found that the kind of solitary play matters: solitary construction and reading are linked with competence, whereas aimless, reticent hovering or repetitive solitary-functional play in older pre-schoolers is more of a concern.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"पार्टन ने एकाकी खेल को सामाजिक खेल का सबसे अपरिपक्व रूप माना। केनेथ रुबिन और अन्य के बाद के शोध ने सुझाया कि एक पाँच वर्ष के बच्चे के लिए जो प्रायः अकेले विस्तृत मॉडल बनाता है:","optionsHi":["बच्चा अब भी अनधिकृत व्यवहार की अवस्था में है और उसे वयस्क निर्देशन चाहिए","इस आयु में कोई भी एकाकी खेल सामाजिक विलंब दर्शाता है जिसके लिए तुरंत संदर्भण चाहिए","एकाकी रचनात्मक खेल अपने आप में चेतावनी का संकेत नहीं है और सक्षमता के साथ जा सकता है","बच्चे को अकेले निर्माण करने से रोका जाना चाहिए और हर बार समूह में रखा जाना चाहिए"],"explanationHi":"रुबिन ने पाया कि एकाकी खेल का प्रकार मायने रखता है: एकाकी निर्माण और पठन सक्षमता से जुड़े हैं, जबकि बड़े पूर्व-विद्यालयी बच्चों में लक्ष्यहीन, संकोची मँडराना या दोहरावदार एकाकी-कार्यात्मक खेल अधिक चिंता का विषय है।"},
  {"id":"cdp-child-development-1904","question":"Match each play activity with Smilansky’s cognitive category. P. A toddler repeatedly fills and empties a bucket of water. Q. A child builds a bridge from blocks. R. Children act as a doctor and patient. S. Children play kho-kho by its rules. 1. Constructive play 2. Games with rules 3. Functional play 4. Dramatic play","options":["P-3, Q-1, R-2, S-4","P-1, Q-3, R-4, S-2","P-3, Q-4, R-1, S-2","P-3, Q-1, R-4, S-2"],"answer":3,"explanation":"Functional play is repeated simple muscle action, constructive play makes something, dramatic play involves pretence and roles, and games with rules follow agreed rules; Smilansky adapted these from Piaget.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"प्रत्येक खेल-गतिविधि का मिलान स्मिलांस्की की संज्ञानात्मक श्रेणी से कीजिए। P. एक नन्हा बच्चा बार-बार पानी की बाल्टी भरता और खाली करता है। Q. एक बच्चा गुटकों से पुल बनाता है। R. बच्चे डॉक्टर और रोगी की भूमिका करते हैं। S. बच्चे खो-खो को उसके नियमों से खेलते हैं। 1. रचनात्मक खेल 2. नियमों वाले खेल 3. कार्यात्मक खेल 4. नाटकीय खेल","optionsHi":["P-3, Q-1, R-2, S-4","P-1, Q-3, R-4, S-2","P-3, Q-4, R-1, S-2","P-3, Q-1, R-4, S-2"],"explanationHi":"कार्यात्मक खेल बार-बार की सरल पेशीय क्रिया है, रचनात्मक खेल कुछ बनाता है, नाटकीय खेल में कल्पना और भूमिकाएँ होती हैं, और नियमों वाले खेल सहमत नियमों का पालन करते हैं; स्मिलांस्की ने इन्हें पियाजे से अपनाया।"},
  {"id":"cdp-child-development-1905","question":"Sara Smilansky’s studies of sociodramatic play found that children from very poor families showed less of it than other children. What did she conclude from her interventions?","options":["Adult ‘play tutoring’ could increase sociodramatic play and the skills linked with it","Such children lacked the ability for pretend play, so formal drills should replace it","The difference was hereditary and could not be changed by any adult support","Pretend play was harmful for these children, as it confused fantasy with reality"],"answer":0,"explanation":"Smilansky showed that teachers modelling roles, suggesting themes and joining play raised the amount and quality of sociodramatic play, with gains in language and social skills; the gap reflected opportunity, not ability.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"सारा स्मिलांस्की के सामाजिक-नाटकीय खेल के अध्ययनों ने पाया कि बहुत गरीब परिवारों के बच्चे अन्य बच्चों की तुलना में इसे कम दिखाते थे। अपने हस्तक्षेपों से उन्होंने क्या निष्कर्ष निकाला?","optionsHi":["वयस्क ‘खेल-प्रशिक्षण’ सामाजिक-नाटकीय खेल और उससे जुड़े कौशलों को बढ़ा सकता है","ऐसे बच्चों में कल्पनात्मक खेल की योग्यता नहीं थी, इसलिए औपचारिक अभ्यास को उसकी जगह लेनी चाहिए","अंतर आनुवंशिक था और किसी भी वयस्क सहायता से बदला नहीं जा सकता था","कल्पनात्मक खेल इन बच्चों के लिए हानिकारक था, क्योंकि वह कल्पना और वास्तविकता को उलझाता था"],"explanationHi":"स्मिलांस्की ने दिखाया कि शिक्षकों द्वारा भूमिकाओं का आदर्श प्रस्तुत करना, विषय सुझाना और खेल में शामिल होना सामाजिक-नाटकीय खेल की मात्रा और गुणवत्ता बढ़ाता है, भाषा और सामाजिक कौशलों में लाभ के साथ; अंतर अवसर का था, योग्यता का नहीं।"},
  {"id":"cdp-child-development-1906","question":"Match each classical theory of play with its claim. P. Surplus energy theory Q. Relaxation (recreation) theory R. Practice (pre-exercise) theory S. Recapitulation theory 1. Play prepares the young for adult roles 2. Play burns off energy left over after needs are met 3. Play re-enacts stages in the evolution of the human race 4. Play restores energy used up in work","options":["P-2, Q-1, R-4, S-3","P-4, Q-2, R-1, S-3","P-2, Q-4, R-3, S-1","P-2, Q-4, R-1, S-3"],"answer":3,"explanation":"Schiller and Spencer saw play as using up surplus energy; Lazarus saw it as recreation from fatigue; Groos saw it as practice of instincts needed in adult life; Hall saw it as reliving the race’s past.","difficulty":"hard","source":"DSSSB PRT · KVS PRT","questionHi":"खेल के प्रत्येक शास्त्रीय सिद्धांत का मिलान उसके दावे से कीजिए। P. अधिशेष ऊर्जा सिद्धांत Q. विश्राम (मनोरंजन) सिद्धांत R. अभ्यास (पूर्व-व्यायाम) सिद्धांत S. पुनरावृत्ति सिद्धांत 1. खेल युवाओं को वयस्क भूमिकाओं के लिए तैयार करता है 2. खेल आवश्यकताओं की पूर्ति के बाद बची ऊर्जा को खर्च करता है 3. खेल मानव जाति के विकास की अवस्थाओं को पुनः अभिनीत करता है 4. खेल कार्य में खर्च हुई ऊर्जा को पुनःस्थापित करता है","optionsHi":["P-2, Q-1, R-4, S-3","P-4, Q-2, R-1, S-3","P-2, Q-4, R-3, S-1","P-2, Q-4, R-1, S-3"],"explanationHi":"शिलर और स्पेंसर ने खेल को अधिशेष ऊर्जा का उपयोग माना; लाज़ारस ने इसे थकान से मनोरंजन माना; ग्रूस ने इसे वयस्क जीवन के लिए आवश्यक सहज वृत्तियों का अभ्यास माना; हॉल ने इसे जाति के अतीत को पुनः जीना माना।"},
  {"id":"cdp-child-development-1907","question":"Kittens stalk and pounce on a ball of wool, and young girls and boys play at cooking, shopkeeping and farming. Which theorist explained such play mainly as practice for skills needed in adult life?","options":["Herbert Spencer","Karl Groos","G. Stanley Hall","Moritz Lazarus"],"answer":1,"explanation":"Groos’s pre-exercise (practice) theory held that play exercises instincts and skills the animal or child will need as an adult; Spencer linked play to surplus energy and Hall to recapitulation of evolution.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"बिल्ली के बच्चे ऊन के गोले पर दबे पाँव चलकर झपटते हैं, और छोटी लड़कियाँ और लड़के खाना पकाने, दुकान चलाने और खेती का खेल खेलते हैं। किस सिद्धांतकार ने ऐसे खेल को मुख्यतः वयस्क जीवन के लिए आवश्यक कौशलों का अभ्यास बताया?","optionsHi":["हर्बर्ट स्पेंसर","कार्ल ग्रूस","जी. स्टैनली हॉल","मोरित्ज़ लाज़ारस"],"explanationHi":"ग्रूस का पूर्व-व्यायाम (अभ्यास) सिद्धांत मानता था कि खेल उन सहज वृत्तियों और कौशलों का अभ्यास कराता है जिनकी पशु या बच्चे को वयस्क के रूप में आवश्यकता होगी; स्पेंसर ने खेल को अधिशेष ऊर्जा से और हॉल ने विकास की पुनरावृत्ति से जोड़ा।"},
  {"id":"cdp-child-development-1908","question":"After receiving a painful injection, four-year-old Pihu spends days playing ‘doctor’, firmly giving injections to her dolls. A psychoanalytic view of play would explain this mainly as:","options":["Practising a skill she will need later as an adult in a medical career","Using up surplus energy left over after her ordinary needs were met","Mastering an upsetting event by turning a passive role into an active one","Imitating a model only because the doctor was rewarded for his actions"],"answer":2,"explanation":"Freud described children repeating distressing events in play so that what they suffered passively they now control actively, which helps them master the anxiety; the other options belong to other theories.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक दर्दनाक इंजेक्शन लगवाने के बाद, चार वर्ष की पीहू कई दिन ‘डॉक्टर’ बनकर खेलती है, अपनी गुड़ियों को दृढ़ता से इंजेक्शन लगाती है। खेल का मनोविश्लेषणात्मक दृष्टिकोण इसे मुख्यतः किस रूप में समझाएगा?","optionsHi":["ऐसे कौशल का अभ्यास जिसकी उसे बाद में वयस्क के रूप में चिकित्सा कैरियर में आवश्यकता होगी","उसकी सामान्य आवश्यकताओं की पूर्ति के बाद बची अधिशेष ऊर्जा का उपयोग","निष्क्रिय भूमिका को सक्रिय में बदलकर परेशान करने वाली घटना पर निपुणता पाना","आदर्श की केवल इसलिए नकल करना कि डॉक्टर को उसके कार्यों के लिए पुरस्कृत किया गया"],"explanationHi":"फ्रायड ने बताया कि बच्चे व्यथित घटनाओं को खेल में दोहराते हैं ताकि जो उन्होंने निष्क्रिय रूप से सहा वह अब सक्रिय रूप से नियंत्रित करें, जो उन्हें चिंता पर निपुणता पाने में सहायता करता है; अन्य विकल्प अन्य सिद्धांतों के हैं।"},
  {"id":"cdp-child-development-1909","question":"Erik Erikson described play as moving through three spheres. Which order is correct?","options":["Autosphere (own body) → microsphere (small toys) → macrosphere (play shared with others)","Microsphere (small toys) → autosphere (own body) → macrosphere (play shared with others)","Macrosphere (play shared with others) → microsphere (small toys) → autosphere (own body)","Autosphere (own body) → macrosphere (play shared with others) → microsphere (small toys)"],"answer":0,"explanation":"Erikson saw the infant first playing with its own body, then the young child mastering a small world of toys, and later sharing play with others in the wider macrosphere.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"एरिक एरिक्सन ने खेल को तीन क्षेत्रों से गुज़रता बताया। कौन-सा क्रम सही है?","optionsHi":["स्वक्षेत्र (अपना शरीर) → सूक्ष्मक्षेत्र (छोटे खिलौने) → बृहत्क्षेत्र (दूसरों के साथ साझा खेल)","सूक्ष्मक्षेत्र (छोटे खिलौने) → स्वक्षेत्र (अपना शरीर) → बृहत्क्षेत्र (दूसरों के साथ साझा खेल)","बृहत्क्षेत्र (दूसरों के साथ साझा खेल) → सूक्ष्मक्षेत्र (छोटे खिलौने) → स्वक्षेत्र (अपना शरीर)","स्वक्षेत्र (अपना शरीर) → बृहत्क्षेत्र (दूसरों के साथ साझा खेल) → सूक्ष्मक्षेत्र (छोटे खिलौने)"],"explanationHi":"एरिक्सन ने शिशु को पहले अपने शरीर से खेलते, फिर छोटे बच्चे को खिलौनों के एक छोटे संसार में निपुणता पाते, और बाद में व्यापक बृहत्क्षेत्र में दूसरों के साथ खेल साझा करते देखा।"},
  {"id":"cdp-child-development-1910","question":"A counsellor lets a withdrawn six-year-old choose freely among toys, reflects the child’s feelings back without directing the play, and accepts whatever the child does within a few safety limits. This approach follows:","options":["Smilansky’s sociodramatic play tutoring","Skinner’s programmed instruction","Montessori’s method of practical-life exercises","Virginia Axline’s non-directive play therapy"],"answer":3,"explanation":"Axline, drawing on Carl Rogers, set out principles of non-directive play therapy: warm acceptance, reflecting feelings and letting the child lead, so that play becomes a means of expressing and working through feelings.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक परामर्शदाता एक अंतर्मुखी छह वर्षीय बच्चे को खिलौनों में से स्वतंत्र रूप से चुनने देता है, खेल को निर्देशित किए बिना बच्चे की भावनाओं को वापस प्रतिबिंबित करता है, और कुछ सुरक्षा-सीमाओं के भीतर बच्चा जो भी करता है उसे स्वीकार करता है। यह उपागम किसका अनुसरण करता है?","optionsHi":["स्मिलांस्की का सामाजिक-नाटकीय खेल-प्रशिक्षण","स्किनर का अभिक्रमित अनुदेशन","मॉन्टेसरी की व्यावहारिक-जीवन अभ्यासों की विधि","वर्जीनिया एक्सलाइन की निर्देशन-रहित खेल चिकित्सा"],"explanationHi":"एक्सलाइन ने, कार्ल रॉजर्स के आधार पर, निर्देशन-रहित खेल चिकित्सा के सिद्धांत निर्धारित किए: गर्मजोशी भरी स्वीकृति, भावनाओं को प्रतिबिंबित करना और बच्चे को नेतृत्व करने देना, ताकि खेल भावनाओं को व्यक्त करने और सुलझाने का माध्यम बने।"},
  {"id":"cdp-child-development-1911","question":"A teacher wants to tell rough-and-tumble play from real fighting in the playground. Which set of signs points to play?","options":["Frowns and fixed stares, one child always winning, and the children separating afterwards","Smiling ‘play faces’, children taking turns being on top, and staying together afterwards","Loud shouting, many children watching, and a struggle lasting several minutes","Children of the same sex involved, physical contact, and running across the ground"],"answer":1,"explanation":"Pellegrini’s work shows that rough-and-tumble play has play faces, role reversal and self-handicapping, and partners stay together after; real fights show hostile faces, one-sided outcomes and separation. Noise and contact occur in both.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक खेल के मैदान में उठा-पटक वाले खेल और वास्तविक लड़ाई में भेद करना चाहता है। कौन-से संकेतों का समूह खेल की ओर इशारा करता है?","optionsHi":["माथे पर बल और स्थिर घूरना, एक बच्चा सदैव जीतता हुआ, और बाद में बच्चों का अलग हो जाना","मुस्कुराते ‘खेल-चेहरे’, बच्चों का बारी-बारी से ऊपर होना, और बाद में साथ रहना","ज़ोर से चिल्लाना, अनेक बच्चों का देखना, और कई मिनट चलने वाला संघर्ष","समान लिंग के बच्चों का शामिल होना, शारीरिक संपर्क, और मैदान भर में दौड़ना"],"explanationHi":"पेलेग्रिनी का कार्य दिखाता है कि उठा-पटक वाले खेल में खेल-चेहरे, भूमिका-परिवर्तन और स्व-अवरोधन होते हैं, और साथी बाद में साथ रहते हैं; वास्तविक लड़ाइयों में शत्रुतापूर्ण चेहरे, एकतरफ़ा परिणाम और अलगाव होते हैं। शोर और संपर्क दोनों में होते हैं।"},
  {"id":"cdp-child-development-1912","question":"A teacher wants children to discover the properties of shapes. She sets out a ‘mystery shapes’ box with chosen shapes, lets children handle and sort them as they like, and asks open questions such as ‘What do you notice about the corners?’. This is best described as:","options":["Direct instruction","Free play","Guided play","Unstructured exploration"],"answer":2,"explanation":"In guided play the adult designs the setting with a learning goal in mind and supports through questions while the child keeps the lead; in free play there is no adult learning goal, and in direct instruction the adult leads.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक शिक्षिका चाहती है कि बच्चे आकृतियों के गुण खोजें। वह चुनी हुई आकृतियों वाला ‘रहस्यमय आकृतियाँ’ डिब्बा रखती है, बच्चों को उन्हें इच्छानुसार छूने और छाँटने देती है, और ‘कोनों के बारे में तुम क्या देखते हो?’ जैसे खुले प्रश्न पूछती है। इसका सबसे अच्छा वर्णन क्या है?","optionsHi":["प्रत्यक्ष अनुदेशन","मुक्त खेल","निर्देशित खेल","असंरचित अन्वेषण"],"explanationHi":"निर्देशित खेल में वयस्क अधिगम-लक्ष्य को ध्यान में रखकर परिवेश डिज़ाइन करता है और प्रश्नों से सहायता करता है जबकि बच्चा नेतृत्व बनाए रखता है; मुक्त खेल में वयस्क का कोई अधिगम-लक्ष्य नहीं होता, और प्रत्यक्ष अनुदेशन में वयस्क नेतृत्व करता है।"},
  {"id":"cdp-child-development-1913","question":"In the ‘Tools of the Mind’ curriculum, pre-schoolers draw and talk through a ‘play plan’ before pretend play and keep to the roles they have chosen. The main aim, following Vygotsky, is to develop:","options":["Self-regulation and executive functions through mature make-believe play","Fine motor control and neat handwriting through drawing the plan before play","Rote memory for the vocabulary used in the different pretend themes","Healthy competition between children for the most popular roles in play"],"answer":0,"explanation":"Bodrova and Leong used play plans and sustained roles to make children act by rules of the imaginary situation, strengthening inhibition, working memory and planning; studies reported gains in executive functions.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"‘टूल्स ऑफ़ द माइंड’ पाठ्यचर्या में, पूर्व-विद्यालयी बच्चे कल्पनात्मक खेल से पहले एक ‘खेल-योजना’ बनाते और उस पर बात करते हैं और अपनी चुनी हुई भूमिकाओं पर टिके रहते हैं। वाइगोत्स्की के अनुसार, मुख्य उद्देश्य क्या विकसित करना है?","optionsHi":["परिपक्व कल्पनात्मक खेल के माध्यम से आत्म-नियमन और कार्यकारी प्रकार्य","खेल से पहले योजना का चित्र बनाकर सूक्ष्म गामक नियंत्रण और साफ़ लिखावट","विभिन्न कल्पनात्मक विषयों में प्रयुक्त शब्दावली की रटंत स्मृति","खेल में सबसे लोकप्रिय भूमिकाओं के लिए बच्चों के बीच स्वस्थ प्रतिस्पर्धा"],"explanationHi":"बोड्रोवा और लियोंग ने खेल-योजनाओं और स्थायी भूमिकाओं का प्रयोग बच्चों को काल्पनिक स्थिति के नियमों से कार्य कराने के लिए किया, जो अवरोध, कार्यकारी स्मृति और योजना को सुदृढ़ करता है; अध्ययनों ने कार्यकारी प्रकार्यों में लाभ की सूचना दी।"},
  {"id":"cdp-child-development-1914","question":"A Class 1 teacher adds menus, order pads, price labels and pencils to the play ‘dhaba’ corner. Studies of such literacy-enriched play settings found that children:","options":["Played less, because the materials made the corner feel like a classroom","Ignored the materials, since play and literacy cannot be combined","Read and wrote more during play, using print for real purposes","Learnt to read only if the teacher tested them on the labels every day"],"answer":2,"explanation":"Research by Neuman and Roskos and others found that adding print props to play settings increased children’s reading and writing behaviours and their talk about print during play.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 की शिक्षिका खेल के ‘ढाबा’ कोने में मेनू, ऑर्डर पैड, मूल्य-लेबल और पेंसिलें जोड़ती है। ऐसे साक्षरता-समृद्ध खेल परिवेशों के अध्ययनों में पाया गया कि बच्चे:","optionsHi":["कम खेले, क्योंकि सामग्री ने कोने को कक्षा जैसा महसूस कराया","सामग्री की अनदेखी करते रहे, क्योंकि खेल और साक्षरता को जोड़ा नहीं जा सकता","खेल के दौरान अधिक पढ़े और लिखे, वास्तविक उद्देश्यों के लिए छपाई का उपयोग करते हुए","केवल तभी पढ़ना सीखे जब शिक्षक प्रतिदिन उनसे लेबलों पर परीक्षा लेता था"],"explanationHi":"न्यूमैन और रोस्कोस तथा अन्य के शोध ने पाया कि खेल परिवेशों में छपाई वाली सामग्री जोड़ने से बच्चों के पठन-लेखन व्यवहार और खेल के दौरान छपाई के बारे में उनकी बातचीत बढ़ी।"},
  {"id":"cdp-child-development-1915","question":"A two-year-old pretends to ‘drink’ only from a toy cup, while a four-year-old happily uses a block as a cup and a five-year-old ‘drinks’ from an imaginary cup. What does this show?","options":["Younger children are more imaginative, since they need fewer objects to pretend","Pretend play becomes less dependent on realistic objects as symbolic thought develops","Pretend play is learnt mainly by copying the uses of toys that adults provide","Children stop pretending once they can use blocks as other objects"],"answer":1,"explanation":"Object substitution develops gradually: toddlers need realistic props, older pre-schoolers can use less similar substitutes, and later they can pretend with no object at all, reflecting growing ability to separate meaning from objects.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"दो वर्ष की बच्ची केवल खिलौने के कप से ‘पीने’ का अभिनय करती है, जबकि चार वर्ष का बच्चा खुशी से गुटके को कप की तरह प्रयोग करता है और पाँच वर्ष की बच्ची एक काल्पनिक कप से ‘पीती’ है। यह क्या दर्शाता है?","optionsHi":["छोटे बच्चे अधिक कल्पनाशील होते हैं, क्योंकि उन्हें अभिनय के लिए कम वस्तुओं की आवश्यकता होती है","प्रतीकात्मक चिंतन के विकसित होने पर कल्पनात्मक खेल यथार्थवादी वस्तुओं पर कम निर्भर होता जाता है","कल्पनात्मक खेल मुख्यतः वयस्कों द्वारा दिए खिलौनों के उपयोगों की नकल करके सीखा जाता है","बच्चे कल्पना करना बंद कर देते हैं जब वे गुटकों को अन्य वस्तुओं की तरह प्रयोग कर सकते हैं"],"explanationHi":"वस्तु-प्रतिस्थापन धीरे-धीरे विकसित होता है: नन्हे बच्चों को यथार्थवादी सामग्री चाहिए, बड़े पूर्व-विद्यालयी बच्चे कम मिलते-जुलते प्रतिस्थापनों का प्रयोग कर सकते हैं, और बाद में वे बिना किसी वस्तु के कल्पना कर सकते हैं, जो अर्थ को वस्तुओं से अलग करने की बढ़ती क्षमता दर्शाता है।"},
  {"id":"cdp-child-development-1916","question":"A school removes all climbing frames and bans running games to prevent injuries. Research on children’s ‘risky play’ suggests that, within reasonable safety limits, such play:","options":["Matters mainly for boys, so girls lose little or nothing from such a ban","Has little developmental value, so removing it costs children nothing important","Makes children reckless in later life, so a full ban is the safer policy","Helps children judge risks and manage fear, so it should not be removed altogether"],"answer":3,"explanation":"Studies of risky play, such as Sandseter’s, suggest that climbing, speed and rough play help children learn to assess risk, master fear and build confidence; the aim is to manage hazards, not eliminate challenge.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक विद्यालय चोटों को रोकने के लिए सभी चढ़ने वाले ढाँचे हटा देता है और दौड़ने के खेलों पर प्रतिबंध लगा देता है। बच्चों के ‘जोखिम भरे खेल’ पर शोध सुझाता है कि उचित सुरक्षा-सीमाओं के भीतर, ऐसा खेल:","optionsHi":["मुख्यतः लड़कों के लिए मायने रखता है, इसलिए ऐसे प्रतिबंध से लड़कियों की कोई या बहुत कम हानि होती है","इसका विकासात्मक मूल्य बहुत कम है, इसलिए इसे हटाने से बच्चों की कोई महत्वपूर्ण चीज़ नहीं जाती","बाद के जीवन में बच्चों को लापरवाह बनाता है, इसलिए पूर्ण प्रतिबंध अधिक सुरक्षित नीति है","बच्चों को जोखिम आँकने और भय सँभालने में मदद करता है, इसलिए इसे पूरी तरह नहीं हटाना चाहिए"],"explanationHi":"जोखिम भरे खेल के अध्ययन, जैसे सैंडसेटर के, सुझाते हैं कि चढ़ना, गति और उठा-पटक वाला खेल बच्चों को जोखिम का आकलन करना, भय पर निपुणता पाना और आत्मविश्वास बनाना सिखाने में मदद करते हैं; उद्देश्य खतरों को सँभालना है, चुनौती को समाप्त करना नहीं।"},
  {"id":"cdp-child-development-1917","question":"Five-year-old Riya often talks to an imaginary friend called ‘Chiku’. Her parents worry. What does research suggest?","options":["Imaginary companions are common in early childhood and are not a sign of disturbance","Imaginary companions signal emotional disturbance and call for professional treatment","Imaginary companions appear only in only-children who have no real friends","Imaginary companions show that the child cannot tell fantasy from reality"],"answer":0,"explanation":"Studies by Marjorie Taylor and others show that a majority of children have pretend friends at some point; such children usually know the friend is pretend and often show good social understanding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"पाँच वर्ष की रिया प्रायः ‘चीकू’ नामक काल्पनिक मित्र से बात करती है। उसके माता-पिता चिंतित हैं। शोध क्या सुझाता है?","optionsHi":["काल्पनिक साथी प्रारंभिक बाल्यावस्था में सामान्य हैं और विक्षोभ का संकेत नहीं हैं","काल्पनिक साथी संवेगात्मक विक्षोभ का संकेत हैं और पेशेवर उपचार माँगते हैं","काल्पनिक साथी केवल उन इकलौते बच्चों में दिखते हैं जिनके कोई वास्तविक मित्र नहीं","काल्पनिक साथी दर्शाते हैं कि बच्चा कल्पना और वास्तविकता में भेद नहीं कर सकता"],"explanationHi":"मार्जोरी टेलर और अन्य के अध्ययन दिखाते हैं कि अधिकांश बच्चों के किसी समय काल्पनिक मित्र होते हैं; ऐसे बच्चे प्रायः जानते हैं कि मित्र काल्पनिक है और प्रायः अच्छी सामाजिक समझ दिखाते हैं।"},
  {"id":"cdp-child-development-1918","question":"In studies of primary children, attention to classwork was higher just after recess, and the longer children waited for recess, the less attentive they became. Pellegrini and Bjorklund linked this mainly to:","options":["The fact that recess removes the need for any teacher-directed work","Physical tiredness after recess, which makes children sit still and quiet afterwards","Young children’s immature cognitive control, which benefits from spaced breaks","Rewards handed out at recess, which reinforce attention in the next period"],"answer":2,"explanation":"Their ‘cognitive immaturity’ view holds that young children are less able to sustain focused, effortful attention, so breaks spaced through the day restore attention; recess complements, not replaces, classwork.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"प्राथमिक बच्चों के अध्ययनों में, कक्षा-कार्य पर ध्यान अवकाश के ठीक बाद अधिक था, और बच्चे अवकाश की जितनी देर प्रतीक्षा करते, उतने कम ध्यानमग्न होते गए। पेलेग्रिनी और ब्यॉर्कलंड ने इसे मुख्यतः किससे जोड़ा?","optionsHi":["इस तथ्य से कि अवकाश शिक्षक-निर्देशित किसी कार्य की आवश्यकता को हटा देता है","अवकाश के बाद शारीरिक थकान से, जो बच्चों को बाद में स्थिर और शांत बैठाती है","छोटे बच्चों के अपरिपक्व संज्ञानात्मक नियंत्रण से, जिसे अंतराल वाले विरामों से लाभ होता है","अवकाश में बाँटे जाने वाले पुरस्कारों से, जो अगले पीरियड में ध्यान को पुनर्बलित करते हैं"],"explanationHi":"उनका ‘संज्ञानात्मक अपरिपक्वता’ मत मानता है कि छोटे बच्चे केंद्रित, श्रमसाध्य ध्यान को टिकाए रखने में कम सक्षम होते हैं, इसलिए दिन भर में अंतराल पर रखे विराम ध्यान को पुनःस्थापित करते हैं; अवकाश कक्षा-कार्य का पूरक है, विकल्प नहीं।"},
  {"id":"cdp-child-development-1919","question":"Which of these is NOT among the commonly listed characteristics of play (as given by Rubin, Fein and Vandenberg)?","options":["It is intrinsically motivated rather than done for a reward","It is aimed at a product that an adult has set in advance","It focuses on the process more than on any end result","It is non-literal, often involving pretence or ‘as if’"],"answer":1,"explanation":"Play is intrinsically motivated, process-oriented, non-literal, free from externally imposed rules and actively engaged; an activity steered towards an adult’s pre-set product is closer to work.","difficulty":"hard","source":"DSSSB PRT · KVS PRT","questionHi":"इनमें से कौन-सी खेल की सामान्यतः सूचीबद्ध विशेषताओं (जैसा रुबिन, फ़ाइन और वैंडेनबर्ग ने दिया) में से नहीं है?","optionsHi":["यह पुरस्कार के लिए नहीं बल्कि आंतरिक रूप से अभिप्रेरित होता है","यह वयस्क द्वारा पहले से निर्धारित उत्पाद की ओर लक्षित होता है","यह किसी अंतिम परिणाम से अधिक प्रक्रिया पर केंद्रित होता है","यह अ-शाब्दिक है, प्रायः कल्पना या ‘मानो’ को शामिल करता है"],"explanationHi":"खेल आंतरिक रूप से अभिप्रेरित, प्रक्रिया-उन्मुख, अ-शाब्दिक, बाह्य रूप से थोपे नियमों से मुक्त और सक्रिय रूप से संलग्न होता है; वयस्क के पूर्व-निर्धारित उत्पाद की ओर चलाई जाने वाली गतिविधि कार्य के अधिक निकट है।"},
  {"id":"cdp-child-development-1920","question":"Pre-schoolers had to get a prize out of a box by clamping two sticks together. One group first played freely with the sticks and clamps; another watched an adult demonstrate the solution. Sylva, Bruner and Genova found that the play group:","options":["Solved it as well but gave up sooner, because play made them restless","Failed far more often, since free play without any instruction teaches nothing useful","Solved it faster only because they had been told the answer in advance","Solved the problem about as well as the demonstration group and persisted more when stuck"],"answer":3,"explanation":"Children who had played did as well as those who saw the principle demonstrated, and used hints more and gave up less, supporting Bruner’s view that play lowers the cost of trying and encourages flexible problem solving.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"पूर्व-विद्यालयी बच्चों को दो छड़ियों को कसकर बाँधकर एक डिब्बे से इनाम निकालना था। एक समूह ने पहले छड़ियों और क्लैंपों से स्वतंत्र रूप से खेला; दूसरे ने एक वयस्क को समाधान दिखाते देखा। सिल्वा, ब्रूनर और जेनोवा ने पाया कि खेलने वाले समूह ने:","optionsHi":["उतना ही अच्छा हल किया पर जल्दी छोड़ दिया, क्योंकि खेल ने उन्हें बेचैन कर दिया","कहीं अधिक बार असफलता पाई, क्योंकि बिना किसी निर्देश के मुक्त खेल कुछ उपयोगी नहीं सिखाता","केवल इसलिए तेज़ी से हल किया कि उन्हें उत्तर पहले से बता दिया गया था","समस्या को प्रदर्शन वाले समूह के लगभग बराबर हल किया और अटकने पर अधिक डटे रहे"],"explanationHi":"जिन बच्चों ने खेला था उन्होंने उतना ही अच्छा किया जितना उन्होंने जिन्होंने सिद्धांत का प्रदर्शन देखा, और संकेतों का अधिक उपयोग किया और कम छोड़ा, जो ब्रूनर के इस मत का समर्थन करता है कि खेल प्रयास की कीमत घटाता है और लचीली समस्या-समाधान को प्रोत्साहित करता है।"},
  {"id":"cdp-child-development-1921","question":"How did Maria Montessori’s view of young children’s fantasy and pretend play differ from Froebel’s and Vygotsky’s?","options":["She gave it less value, preferring real, purposeful activities with real materials","She valued it most of all, seeing it as the highest form of children’s learning","She saw it as dangerous and banned all play from her Children’s Houses","She agreed with them fully and built her whole method around sociodramatic play"],"answer":0,"explanation":"Montessori preferred practical-life work with real, child-sized tools and graded materials to make-believe, whereas Froebel valued play as self-expression and Vygotsky saw pretend play as a leading activity of development.","difficulty":"hard","source":"DSSSB PRT · KVS PRT","questionHi":"छोटे बच्चों की कल्पना और कल्पनात्मक खेल पर मारिया मॉन्टेसरी का दृष्टिकोण फ्रोबेल और वाइगोत्स्की से कैसे भिन्न था?","optionsHi":["उन्होंने उसे कम महत्व दिया, वास्तविक सामग्री के साथ वास्तविक, उद्देश्यपूर्ण गतिविधियों को प्राथमिकता देते हुए","उन्होंने उसे सबसे अधिक महत्व दिया, उसे बच्चों के अधिगम का उच्चतम रूप मानते हुए","उन्होंने उसे खतरनाक माना और अपने बाल-गृहों में सभी खेल प्रतिबंधित कर दिए","वे उनसे पूरी तरह सहमत थीं और अपनी पूरी पद्धति सामाजिक-नाटकीय खेल के इर्द-गिर्द बनाई"],"explanationHi":"मॉन्टेसरी कल्पनात्मक खेल की अपेक्षा वास्तविक, बच्चों के आकार के औज़ारों और श्रेणीबद्ध सामग्री के साथ व्यावहारिक-जीवन कार्य को पसंद करती थीं, जबकि फ्रोबेल ने खेल को आत्म-अभिव्यक्ति के रूप में और वाइगोत्स्की ने कल्पनात्मक खेल को विकास की अग्रणी गतिविधि के रूप में महत्व दिया।"},
  {"id":"cdp-child-development-1922","question":"Which sequence matches Piaget’s types of play to the periods of development in which they first become prominent?","options":["Practice play (sensorimotor) → games with rules (pre-operational) → symbolic play (concrete operational)","Symbolic play (sensorimotor) → practice play (pre-operational) → games with rules (concrete operational)","Practice play (sensorimotor) → symbolic play (pre-operational) → games with rules (concrete operational)","Games with rules (sensorimotor) → symbolic play (pre-operational) → practice play (concrete operational)"],"answer":2,"explanation":"Infants repeat actions for pleasure (practice play); from about two, symbolic play reflects the semiotic function; from about seven, children enjoy rule-governed games that need cooperation and decentration.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कौन-सा क्रम पियाजे के खेल के प्रकारों को विकास की उन अवधियों से मिलाता है जिनमें वे पहले प्रमुख होते हैं?","optionsHi":["अभ्यास खेल (संवेदी-गामक) → नियमों वाले खेल (पूर्व-संक्रियात्मक) → प्रतीकात्मक खेल (मूर्त संक्रियात्मक)","प्रतीकात्मक खेल (संवेदी-गामक) → अभ्यास खेल (पूर्व-संक्रियात्मक) → नियमों वाले खेल (मूर्त संक्रियात्मक)","अभ्यास खेल (संवेदी-गामक) → प्रतीकात्मक खेल (पूर्व-संक्रियात्मक) → नियमों वाले खेल (मूर्त संक्रियात्मक)","नियमों वाले खेल (संवेदी-गामक) → प्रतीकात्मक खेल (पूर्व-संक्रियात्मक) → अभ्यास खेल (मूर्त संक्रियात्मक)"],"explanationHi":"शिशु आनंद के लिए क्रियाएँ दोहराते हैं (अभ्यास खेल); लगभग दो वर्ष से प्रतीकात्मक खेल लाक्षणिक प्रकार्य को दर्शाता है; लगभग सात वर्ष से बच्चे नियम-शासित खेलों का आनंद लेते हैं जिनमें सहयोग और विकेंद्रण चाहिए।"},
  {"id":"cdp-child-development-1923","question":"In a pretend ‘bus’ game, the teacher wants to deepen play without taking it over. In Smilansky’s terms, which is an ‘inside’ intervention?","options":["She stands just outside the play and says, ‘Perhaps the bus needs a conductor to sell tickets.’","She takes the role of a passenger and asks the ‘conductor’ for a ticket to the market","She stops the game to explain how real buses work and then lets it restart","She praises the children afterwards for playing nicely together on the bus"],"answer":1,"explanation":"Inside intervention means the adult joins the play in a role and models from within the pretend frame; outside intervention gives suggestions or comments from outside the play while the children keep their roles.","difficulty":"hard","source":"DSSSB PRT · KVS PRT","questionHi":"कल्पनात्मक ‘बस’ खेल में, शिक्षिका खेल को अपने हाथ में लिए बिना गहरा करना चाहती है। स्मिलांस्की के शब्दों में, ‘भीतर’ का हस्तक्षेप कौन-सा है?","optionsHi":["वह खेल के ठीक बाहर खड़ी होकर कहती है, ‘शायद बस को टिकट बेचने के लिए एक कंडक्टर चाहिए।’","वह यात्री की भूमिका लेकर ‘कंडक्टर’ से बाज़ार का टिकट माँगती है","वह खेल रोककर समझाती है कि असली बसें कैसे काम करती हैं और फिर उसे फिर शुरू करने देती है","वह बाद में बस में मिल-जुलकर अच्छा खेलने के लिए बच्चों की प्रशंसा करती है"],"explanationHi":"भीतर के हस्तक्षेप का अर्थ है कि वयस्क किसी भूमिका में खेल में शामिल होता है और कल्पना के ढाँचे के भीतर से आदर्श प्रस्तुत करता है; बाहर का हस्तक्षेप खेल के बाहर से सुझाव या टिप्पणियाँ देता है जबकि बच्चे अपनी भूमिकाएँ बनाए रखते हैं।"},
  {"id":"cdp-child-development-1924","question":"Given a new toy with levers and lights, a child first looks at it intently, handles it carefully and tries each lever; later she uses it in many relaxed, varied ways in a pretend game. Corinne Hutt distinguished the first phase as exploration. Its guiding question is:","options":["‘How can I win with this object?’","‘What can I do with this object?’","‘Who gave me this object?’","‘What does this object do?’"],"answer":3,"explanation":"Hutt found that exploration, focused on discovering an object’s properties, comes first; play, asking what the child can do with it, follows once the object is familiar.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"लीवर और बत्तियों वाला एक नया खिलौना मिलने पर, बच्ची पहले उसे ध्यान से देखती है, सावधानी से छूती है और प्रत्येक लीवर आज़माती है; बाद में वह कल्पनात्मक खेल में उसे अनेक आरामदायक, विविध ढंग से प्रयोग करती है। कोरिन हट ने पहले चरण को अन्वेषण के रूप में अलग किया। इसका मार्गदर्शक प्रश्न है:","optionsHi":["‘इस वस्तु से मैं कैसे जीत सकती हूँ?’","‘इस वस्तु से मैं क्या कर सकती हूँ?’","‘यह वस्तु मुझे किसने दी?’","‘यह वस्तु क्या करती है?’"],"explanationHi":"हट ने पाया कि अन्वेषण, जो किसी वस्तु के गुणों की खोज पर केंद्रित होता है, पहले आता है; खेल, जो पूछता है कि बच्चा उससे क्या कर सकता है, वस्तु के परिचित होने पर आता है।"},
  {"id":"cdp-child-development-1925","question":"A pre-school is choosing materials for its play area. Which choice best supports varied, imaginative play?","options":["Open-ended materials such as blocks, cloth and boxes that can become many things","Battery toys that perform one fixed action each time a button is pressed","Detailed model kits that can be assembled in only one correct way","Worksheets with play-themed pictures for children to colour in neatly"],"answer":0,"explanation":"Open-ended materials let children assign many meanings and uses, encouraging symbolic, constructive and cooperative play, while single-purpose toys and colouring sheets limit what children can invent.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक पूर्व-विद्यालय अपने खेल क्षेत्र के लिए सामग्री चुन रहा है। कौन-सा चयन विविध, कल्पनाशील खेल का सबसे अच्छा समर्थन करता है?","optionsHi":["गुटके, कपड़े और डिब्बे जैसी खुले अंत वाली सामग्री जो अनेक चीज़ें बन सकती है","बैटरी वाले खिलौने जो बटन दबाने पर हर बार एक ही निश्चित क्रिया करते हैं","विस्तृत मॉडल किट जिन्हें केवल एक ही सही तरीके से जोड़ा जा सकता है","खेल-थीम वाले चित्रों के कार्यपत्रक जिनमें बच्चे साफ़-सुथरे रंग भरें"],"explanationHi":"खुले अंत वाली सामग्री बच्चों को अनेक अर्थ और उपयोग देने देती है, प्रतीकात्मक, रचनात्मक और सहकारी खेल को प्रोत्साहित करती है, जबकि एकल-उद्देश्य वाले खिलौने और रंग भरने के पत्रक बच्चों की गढ़ने की क्षमता को सीमित करते हैं।"},
  {"id":"cdp-child-development-1926","question":"On Jerome Kagan’s Matching Familiar Figures Test, a child must find the one picture, among six similar variants, that exactly matches a standard. Aryan answers within seconds and makes many errors; Bela takes much longer and makes few. In Kagan’s terms:","options":["Aryan is field dependent and Bela is field independent in cognitive style","Aryan has an impulsive cognitive tempo and Bela a reflective one","Aryan has low intelligence and Bela high intelligence on this measure","Aryan is a divergent thinker and Bela a convergent thinker on such tasks"],"answer":1,"explanation":"Kagan’s reflection–impulsivity dimension combines response speed and accuracy on uncertain tasks: fast and inaccurate is impulsive, slow and accurate is reflective. It is a style of responding, not a measure of intelligence or of field dependence.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"जेरोम केगन के मैचिंग फ़ैमिलियर फ़िगर्स टेस्ट में, बच्चे को छह समान प्रकारों में से वह एक चित्र खोजना होता है जो मानक से ठीक मेल खाता हो। आर्यन कुछ ही सेकंड में उत्तर देता है और अनेक त्रुटियाँ करता है; बेला कहीं अधिक समय लेती है और कम त्रुटियाँ करती है। केगन के शब्दों में:","optionsHi":["आर्यन संज्ञानात्मक शैली में क्षेत्र-निर्भर है और बेला क्षेत्र-स्वतंत्र","आर्यन की संज्ञानात्मक गति आवेगशील है और बेला की चिंतनशील","इस माप पर आर्यन की बुद्धि निम्न है और बेला की उच्च","ऐसे कार्यों पर आर्यन अपसारी चिंतक है और बेला अभिसारी चिंतक"],"explanationHi":"केगन का चिंतन–आवेगशीलता आयाम अनिश्चित कार्यों पर प्रतिक्रिया की गति और सटीकता को जोड़ता है: तेज़ और गलत आवेगशील है, धीमा और सही चिंतनशील। यह प्रतिक्रिया करने की शैली है, बुद्धि या क्षेत्र-निर्भरता का माप नहीं।"},
  {"id":"cdp-child-development-1927","question":"Jerome Kagan found that some infants react strongly to unfamiliar sights and sounds and become shy, cautious toddlers. Follow-up research on such ‘behaviourally inhibited’ children showed that:","options":["Inhibition is moderately stable, but many become less shy, especially with gentle encouragement to approach","Inhibition is completely fixed, so a shy toddler always becomes a withdrawn adult whatever happens","Inhibition disappears in almost all children by school age, regardless of how they are handled","Inhibition is caused entirely by over-protective parenting and has no basis in temperament"],"answer":0,"explanation":"Kagan’s longitudinal work found a biologically based tendency with some stability, yet many inhibited toddlers became less so, particularly when caregivers gently supported approach rather than either forcing or shielding them.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"जेरोम केगन ने पाया कि कुछ शिशु अपरिचित दृश्यों और ध्वनियों पर प्रबल प्रतिक्रिया करते हैं और संकोची, सावधान नन्हे बच्चे बन जाते हैं। ऐसे ‘व्यवहारगत रूप से अवरुद्ध’ बच्चों पर अनुवर्ती शोध ने दिखाया कि:","optionsHi":["अवरोध मध्यम रूप से स्थिर है, पर अनेक कम संकोची हो जाते हैं, विशेषकर निकट आने के कोमल प्रोत्साहन से","अवरोध पूरी तरह स्थिर है, इसलिए संकोची नन्हा बच्चा कुछ भी हो सदैव अंतर्मुखी वयस्क बनता है","विद्यालय-आयु तक लगभग सभी बच्चों में अवरोध लुप्त हो जाता है, उन्हें कैसे सँभाला गया हो इसकी परवाह किए बिना","अवरोध पूरी तरह अत्यधिक सुरक्षात्मक पालन-पोषण से उत्पन्न होता है और स्वभाव में उसका कोई आधार नहीं"],"explanationHi":"केगन के दीर्घकालिक कार्य ने कुछ स्थिरता वाली जैविक आधार की प्रवृत्ति पाई, फिर भी अनेक अवरुद्ध नन्हे बच्चे कम अवरुद्ध हो गए, विशेषकर जब देखभालकर्ताओं ने उन्हें बाध्य करने या बचाने के बजाय निकट आने में कोमलता से सहायता की।"},
  {"id":"cdp-child-development-1928","question":"Rahul, a highly active child, does well with a Class 2 teacher who builds in movement and short tasks, but is constantly in trouble with a teacher who expects children to sit still for long periods. Thomas and Chess would explain this through the idea of:","options":["Fixed hereditary traits that the environment cannot influence","A difficult temperament that always predicts poor school adjustment","Goodness of fit between temperament and the demands of the setting","Low intelligence showing up only when tasks become long"],"answer":2,"explanation":"Thomas and Chess stressed that adjustment depends on the match between a child’s temperament and the expectations of the environment; the same child fares well where demands fit his temperament.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अत्यंत सक्रिय बच्चा राहुल कक्षा 2 के उस शिक्षक के साथ अच्छा करता है जो गति और छोटे कार्य शामिल करता है, पर उस शिक्षक के साथ निरंतर परेशानी में रहता है जो बच्चों से लंबे समय तक स्थिर बैठने की अपेक्षा करता है। थॉमस और चेस इसे किस विचार से समझाएँगे?","optionsHi":["स्थिर आनुवंशिक गुण जिन्हें पर्यावरण प्रभावित नहीं कर सकता","कठिन स्वभाव जो सदैव खराब विद्यालयी समायोजन का पूर्वानुमान करता है","स्वभाव और परिवेश की माँगों के बीच उपयुक्तता (गुडनेस ऑफ़ फ़िट)","निम्न बुद्धि जो केवल कार्य लंबे होने पर प्रकट होती है"],"explanationHi":"थॉमस और चेस ने ज़ोर दिया कि समायोजन बच्चे के स्वभाव और पर्यावरण की अपेक्षाओं के मेल पर निर्भर करता है; वही बच्चा वहाँ अच्छा करता है जहाँ माँगें उसके स्वभाव के अनुकूल हों।"},
  {"id":"cdp-child-development-1929","question":"Mary Rothbart’s model of temperament includes a dimension that covers a child’s ability to hold back a dominant response, such as waiting for a turn, and to shift attention on purpose. This dimension is called:","options":["Rhythmicity","Surgency (extraversion)","Negative affectivity","Effortful control"],"answer":3,"explanation":"Rothbart’s three broad dimensions are surgency/extraversion, negative affectivity and effortful control; effortful control involves inhibitory and attentional control and predicts later self-regulation. Rhythmicity is one of Thomas and Chess’s nine dimensions.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"मैरी रॉथबार्ट के स्वभाव के मॉडल में एक आयाम है जो बच्चे की प्रबल प्रतिक्रिया को रोकने की क्षमता, जैसे बारी की प्रतीक्षा करना, और जानबूझकर ध्यान बदलने की क्षमता को समेटता है। इस आयाम को क्या कहते हैं?","optionsHi":["लयबद्धता","उत्साहशीलता (बहिर्मुखता)","नकारात्मक भावात्मकता","प्रयासपूर्ण नियंत्रण"],"explanationHi":"रॉथबार्ट के तीन व्यापक आयाम हैं उत्साहशीलता/बहिर्मुखता, नकारात्मक भावात्मकता और प्रयासपूर्ण नियंत्रण; प्रयासपूर्ण नियंत्रण में अवरोधक और ध्यान संबंधी नियंत्रण शामिल है और बाद के आत्म-नियमन का पूर्वानुमान करता है। लयबद्धता थॉमस और चेस के नौ आयामों में से एक है।"},
  {"id":"cdp-child-development-1930","question":"Babbling appears at about the same age in infants across very different cultures and home environments, and even deaf infants begin to babble vocally. Waddington’s term for such strongly genetically guided development is:","options":["Reaction range","Canalisation","Niche-picking","Imprinting"],"answer":1,"explanation":"A highly canalised trait follows a similar course across a wide range of environments, like a ball rolling down a deep groove; a reaction range describes the spread of outcomes a genotype allows in different environments.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"बड़बड़ाना (बैबलिंग) बहुत भिन्न संस्कृतियों और घरेलू परिवेशों के शिशुओं में लगभग एक ही आयु में प्रकट होता है, और बधिर शिशु भी स्वर से बड़बड़ाना शुरू करते हैं। ऐसे प्रबल रूप से आनुवंशिक रूप से निर्देशित विकास के लिए वाडिंगटन का शब्द क्या है?","optionsHi":["प्रतिक्रिया-परिसर (रिएक्शन रेंज)","नलिकाकरण (कैनलाइज़ेशन)","आला-चयन (निश-पिकिंग)","छापांकन (इम्प्रिंटिंग)"],"explanationHi":"अत्यधिक नलिकाकृत गुण परिवेशों की व्यापक श्रेणी में समान पथ का अनुसरण करता है, जैसे गहरी खाँच में लुढ़कती गेंद; प्रतिक्रिया-परिसर उन परिणामों के विस्तार का वर्णन करता है जिन्हें एक जीनप्ररूप विभिन्न परिवेशों में अनुमत करता है।"},
  {"id":"cdp-child-development-1931","question":"Large reviews of the ‘Big Five’ personality traits and school achievement have found that the trait most consistently linked with higher marks is:","options":["Neuroticism","Extraversion","Openness to experience","Conscientiousness"],"answer":3,"explanation":"Conscientiousness, being organised, persistent and dependable, predicts academic performance across ages, partly independent of intelligence; extraversion shows weak or mixed links and neuroticism, if anything, a small negative one.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"‘बिग फ़ाइव’ व्यक्तित्व-गुणों और विद्यालयी उपलब्धि की बड़ी समीक्षाओं ने पाया कि ऊँचे अंकों से सबसे अधिक संगत रूप से जुड़ा गुण है:","optionsHi":["न्यूरोटिसिज़्म (तंत्रिकातापिता)","बहिर्मुखता","अनुभव के प्रति खुलापन","कर्तव्यनिष्ठा"],"explanationHi":"कर्तव्यनिष्ठा, यानी संगठित, दृढ़ और भरोसेमंद होना, सभी आयु में शैक्षणिक प्रदर्शन का पूर्वानुमान करती है, आंशिक रूप से बुद्धि से स्वतंत्र; बहिर्मुखता के कमज़ोर या मिश्रित संबंध हैं और न्यूरोटिसिज़्म का, यदि कुछ है तो, छोटा नकारात्मक।"},
  {"id":"cdp-child-development-1932","question":"Hans Eysenck first described personality using two broad dimensions, and later added a third. Which set is his?","options":["Extraversion–introversion, neuroticism–stability, psychoticism","Openness, conscientiousness and agreeableness, with two more traits","Cardinal, central and secondary traits of the individual","Surface traits, source traits and dynamic (motivational) traits"],"answer":0,"explanation":"Eysenck’s PEN model uses extraversion, neuroticism and psychoticism; openness and the others belong to the Big Five, cardinal/central/secondary traits are Allport’s, and surface/source traits are Cattell’s.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"हंस आइज़ेंक ने पहले व्यक्तित्व का वर्णन दो व्यापक आयामों से किया, और बाद में तीसरा जोड़ा। उनका समूह कौन-सा है?","optionsHi":["बहिर्मुखता–अंतर्मुखता, न्यूरोटिसिज़्म–स्थिरता, मनोविक्षिप्तता (साइकोटिसिज़्म)","खुलापन, कर्तव्यनिष्ठा और सहमतिशीलता, दो और गुणों के साथ","व्यक्ति के कार्डिनल, केंद्रीय और द्वितीयक गुण","सतही गुण, स्रोत गुण और गत्यात्मक (अभिप्रेरणात्मक) गुण"],"explanationHi":"आइज़ेंक का PEN मॉडल बहिर्मुखता, न्यूरोटिसिज़्म और साइकोटिसिज़्म का प्रयोग करता है; खुलापन और अन्य बिग फ़ाइव के हैं, कार्डिनल/केंद्रीय/द्वितीयक गुण ऑलपोर्ट के हैं, और सतही/स्रोत गुण कैटेल के हैं।"},
  {"id":"cdp-child-development-1933","question":"Eysenck proposed a biological explanation for why introverted students often prefer quiet study and avoid noisy crowds. According to him, introverts:","options":["Have weaker memories, so they need quiet to remember what they study","Have a lower resting level of cortical arousal, so they actively seek out extra stimulation","Have a higher resting level of cortical arousal, so extra stimulation quickly feels too much","Have less intelligence, so they cannot process several inputs at once"],"answer":2,"explanation":"Eysenck argued that introverts are chronically more aroused, so they avoid further stimulation, while extraverts are under-aroused and seek it; this concerns preference for stimulation, not memory or intelligence.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"आइज़ेंक ने इसके लिए जैविक व्याख्या प्रस्तावित की कि अंतर्मुखी छात्र प्रायः शांत अध्ययन क्यों पसंद करते हैं और शोरगुल वाली भीड़ से क्यों बचते हैं। उनके अनुसार, अंतर्मुखी:","optionsHi":["की स्मृति कमज़ोर होती है, इसलिए वे जो पढ़ते हैं उसे याद रखने के लिए उन्हें शांति चाहिए","का प्रांतस्थीय उत्तेजना का विश्राम-स्तर निम्न होता है, इसलिए वे अतिरिक्त उद्दीपन सक्रिय रूप से खोजते हैं","का प्रांतस्थीय उत्तेजना का विश्राम-स्तर उच्च होता है, इसलिए अतिरिक्त उद्दीपन शीघ्र ही बहुत अधिक लगने लगता है","की बुद्धि कम होती है, इसलिए वे एक साथ कई निवेशों का प्रक्रमण नहीं कर सकते"],"explanationHi":"आइज़ेंक ने तर्क दिया कि अंतर्मुखी दीर्घकालिक रूप से अधिक उत्तेजित होते हैं, इसलिए वे और उद्दीपन से बचते हैं, जबकि बहिर्मुखी कम-उत्तेजित होते हैं और उसे खोजते हैं; यह उद्दीपन की पसंद से संबंधित है, स्मृति या बुद्धि से नहीं।"},
  {"id":"cdp-child-development-1934","question":"Carl Jung described a personality type whose energy is directed inward, who prefers reflection and a few close relationships, and who is drained by long social gatherings. This type is called:","options":["Extravert","Introvert","Ambivert","Endomorph"],"answer":1,"explanation":"Jung’s introvert turns attention and energy towards the inner world of thoughts and feelings; the extravert turns outward. An ambivert shows both tendencies, and endomorph is one of Sheldon’s body types.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कार्ल युंग ने एक ऐसे व्यक्तित्व-प्रकार का वर्णन किया जिसकी ऊर्जा भीतर की ओर निर्देशित होती है, जो चिंतन और कुछ घनिष्ठ संबंधों को पसंद करता है, और लंबी सामाजिक सभाओं से थक जाता है। इस प्रकार को क्या कहते हैं?","optionsHi":["बहिर्मुखी","अंतर्मुखी","उभयमुखी","एंडोमॉर्फ़"],"explanationHi":"युंग का अंतर्मुखी ध्यान और ऊर्जा को विचारों और भावनाओं के आंतरिक जगत की ओर मोड़ता है; बहिर्मुखी बाहर की ओर मोड़ता है। उभयमुखी दोनों प्रवृत्तियाँ दिखाता है, और एंडोमॉर्फ़ शेल्डन के शारीरिक प्रकारों में से एक है।"},
  {"id":"cdp-child-development-1935","question":"In William Sheldon’s body-type theory, a lean, delicate, tall build (ectomorph) was linked with which temperament?","options":["Ambiversion: equally outgoing and reserved in all settings","Viscerotonia: relaxed, sociable and fond of comfort and food","Somatotonia: assertive, energetic and fond of adventure","Cerebrotonia: restrained, sensitive and inclined to inhibition"],"answer":3,"explanation":"Sheldon paired endomorphy with viscerotonia, mesomorphy with somatotonia and ectomorphy with cerebrotonia. His links between physique and temperament are now regarded as weak and are not used to judge children.","difficulty":"moderate","source":"DSSSB TGT · KVS PGT","questionHi":"विलियम शेल्डन के शारीरिक-प्रकार सिद्धांत में, दुबले, नाज़ुक, लंबे डील-डौल (एक्टोमॉर्फ़) को किस स्वभाव से जोड़ा गया?","optionsHi":["उभयमुखता: सभी परिवेशों में समान रूप से मिलनसार और संकोची","विसेरोटोनिया: शांत, मिलनसार और आराम तथा भोजन के शौकीन","सोमैटोटोनिया: मुखर, ऊर्जावान और साहसिक कार्यों के शौकीन","सेरेब्रोटोनिया: संयमित, संवेदनशील और अवरोध की ओर झुके"],"explanationHi":"शेल्डन ने एंडोमॉर्फ़ी को विसेरोटोनिया से, मीज़ोमॉर्फ़ी को सोमैटोटोनिया से और एक्टोमॉर्फ़ी को सेरेब्रोटोनिया से जोड़ा। शरीर-गठन और स्वभाव के उनके संबंध अब कमज़ोर माने जाते हैं और बच्चों को आँकने में प्रयुक्त नहीं होते।"},
  {"id":"cdp-child-development-1936","question":"Mahatma Gandhi’s life is often said to have been organised around a commitment to non-violence. In Gordon Allport’s trait theory, a single trait that dominates a person’s whole life like this is a:","options":["Cardinal trait","Central trait","Secondary trait","Source trait"],"answer":0,"explanation":"Allport called rare, all-pervading traits cardinal; central traits are the handful of general characteristics describing most people, and secondary traits are narrower preferences. Source traits belong to Cattell’s theory.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"महात्मा गांधी के जीवन के बारे में प्रायः कहा जाता है कि वह अहिंसा के प्रति प्रतिबद्धता के इर्द-गिर्द संगठित था। गॉर्डन ऑलपोर्ट के गुण सिद्धांत में, एक ऐसा अकेला गुण जो इस प्रकार किसी व्यक्ति के पूरे जीवन पर हावी हो, क्या है?","optionsHi":["कार्डिनल गुण","केंद्रीय गुण","द्वितीयक गुण","स्रोत गुण"],"explanationHi":"ऑलपोर्ट ने दुर्लभ, सर्वव्यापी गुणों को कार्डिनल कहा; केंद्रीय गुण वे मुट्ठी भर सामान्य विशेषताएँ हैं जो अधिकांश लोगों का वर्णन करती हैं, और द्वितीयक गुण संकीर्ण पसंदें हैं। स्रोत गुण कैटेल के सिद्धांत के हैं।"},
  {"id":"cdp-child-development-1937","question":"Raymond Cattell used factor analysis on many observed behaviours. In his theory, the 16 basic underlying factors that explain clusters of observable behaviour are called:","options":["Cardinal traits","Surface traits","Source traits","Secondary traits"],"answer":2,"explanation":"Cattell distinguished surface traits, clusters of behaviour seen together, from the deeper source traits that cause them; his 16PF questionnaire measures sixteen source traits.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"रेमंड कैटेल ने अनेक प्रेक्षित व्यवहारों पर कारक विश्लेषण का प्रयोग किया। उनके सिद्धांत में, प्रेक्षणीय व्यवहार के समूहों की व्याख्या करने वाले 16 मूल अंतर्निहित कारकों को क्या कहते हैं?","optionsHi":["कार्डिनल गुण","सतही गुण","स्रोत गुण","द्वितीयक गुण"],"explanationHi":"कैटेल ने सतही गुणों, जो एक साथ दिखने वाले व्यवहार के समूह हैं, को उन गहरे स्रोत गुणों से अलग किया जो उन्हें उत्पन्न करते हैं; उनकी 16PF प्रश्नावली सोलह स्रोत गुणों को मापती है।"},
  {"id":"cdp-child-development-1938","question":"A counsellor shows a child pictures of animals in human-like situations and asks her to tell a story about each, to learn about her concerns and relationships. This is:","options":["A self-report inventory of the child’s personality traits","A projective technique, the Children’s Apperception Test","A standardised test of the child’s verbal intelligence","A rating scale completed by the child’s class teacher"],"answer":1,"explanation":"Projective techniques present ambiguous stimuli so that the person projects needs and conflicts into responses; the CAT, adapted from the TAT for children, uses animal figures.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"एक परामर्शदाता एक बच्ची को मानव जैसी स्थितियों में पशुओं के चित्र दिखाता है और उससे प्रत्येक के बारे में कहानी सुनाने को कहता है, ताकि उसकी चिंताओं और संबंधों के बारे में जान सके। यह क्या है?","optionsHi":["बच्ची के व्यक्तित्व-गुणों की स्व-प्रतिवेदन सूची","एक प्रक्षेपी तकनीक, चिल्ड्रन एपरसेप्शन टेस्ट","बच्ची की शाब्दिक बुद्धि का मानकीकृत परीक्षण","बच्ची की कक्षा-शिक्षिका द्वारा भरा गया मूल्यांकन-पैमाना"],"explanationHi":"प्रक्षेपी तकनीकें अस्पष्ट उद्दीपक प्रस्तुत करती हैं ताकि व्यक्ति अपनी आवश्यकताओं और द्वंद्वों को प्रतिक्रियाओं में प्रक्षेपित करे; CAT, जो बच्चों के लिए TAT से अनुकूलित है, पशु आकृतियों का प्रयोग करता है।"},
  {"id":"cdp-child-development-1939","question":"When a personality questionnaire asks Class 9 students, ‘Do you always tell the truth?’, many answer ‘Yes’. This illustrates a major limitation of self-report inventories, namely:","options":["The halo effect: one good trait colouring the rater’s judgement of others","Projection: revealing hidden conflicts through ambiguous pictures","Social desirability: answering in ways that look good rather than accurately","Low reliability caused by scoring that depends on the examiner’s judgement"],"answer":2,"explanation":"Respondents may present themselves favourably, so inventories often include lie or social-desirability scales. Projection belongs to projective tests, and the halo effect concerns ratings by others.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"जब कोई व्यक्तित्व प्रश्नावली कक्षा 9 के छात्रों से पूछती है, ‘क्या आप सदैव सच बोलते हैं?’, तो अनेक ‘हाँ’ में उत्तर देते हैं। यह स्व-प्रतिवेदन सूचियों की किस प्रमुख सीमा को दर्शाता है?","optionsHi":["हैलो प्रभाव: एक अच्छा गुण मूल्यांकनकर्ता के दूसरों के बारे में निर्णय को रंग देता है","प्रक्षेपण: अस्पष्ट चित्रों के माध्यम से छिपे द्वंद्वों को प्रकट करना","सामाजिक वांछनीयता: सटीक रूप से नहीं बल्कि ऐसे उत्तर देना जो अच्छे दिखें","निम्न विश्वसनीयता, जो अंकन के परीक्षक के निर्णय पर निर्भर होने के कारण होती है"],"explanationHi":"उत्तरदाता स्वयं को अनुकूल रूप से प्रस्तुत कर सकते हैं, इसलिए सूचियों में प्रायः झूठ या सामाजिक-वांछनीयता के पैमाने शामिल होते हैं। प्रक्षेपण प्रक्षेपी परीक्षणों का है, और हैलो प्रभाव दूसरों द्वारा किए गए मूल्यांकनों से संबंधित है।"},
  {"id":"cdp-child-development-1940","question":"In John Carroll’s model of school learning, how much a student learns depends on the ratio of:","options":["Time actually spent on learning to the time the student needs to learn","Marks obtained in class tests to marks obtained in annual examinations","Intelligence quotient to the age of the student at the time of learning","Number of teachers in the school to the number of students in each class"],"answer":0,"explanation":"Carroll saw aptitude as the time needed to learn; time spent depends on opportunity and perseverance. If enough time and good instruction are given, most students can learn, which Bloom built into mastery learning.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"जॉन कैरोल के विद्यालयी अधिगम के मॉडल में, छात्र कितना सीखता है यह किसके अनुपात पर निर्भर करता है?","optionsHi":["अधिगम पर वास्तव में बिताए समय का उस समय से जो छात्र को सीखने के लिए चाहिए","कक्षा परीक्षणों में प्राप्त अंकों का वार्षिक परीक्षाओं में प्राप्त अंकों से","बुद्धि-लब्धि का अधिगम के समय छात्र की आयु से","विद्यालय में शिक्षकों की संख्या का प्रत्येक कक्षा में छात्रों की संख्या से"],"explanationHi":"कैरोल ने अभिक्षमता को सीखने के लिए आवश्यक समय माना; बिताया गया समय अवसर और दृढ़ता पर निर्भर करता है। यदि पर्याप्त समय और अच्छा अनुदेशन दिया जाए, तो अधिकांश छात्र सीख सकते हैं, जिसे ब्लूम ने निपुणता अधिगम में समाहित किया।"},
  {"id":"cdp-child-development-1941","question":"A study finds that highly structured, step-by-step teaching helps anxious, lower-scoring students most, while a more open, discovery approach suits confident, high-scoring students better. Cronbach and Snow called such findings:","options":["Practice and fatigue effects","Expectancy (Pygmalion) effects","Regression towards the mean","Aptitude–treatment interactions"],"answer":3,"explanation":"An aptitude–treatment interaction exists when the best method depends on learner characteristics, so no single method is best for everyone; it supports adapting instruction to individual differences.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"एक अध्ययन पाता है कि अत्यधिक संरचित, चरण-दर-चरण शिक्षण चिंतित, निम्न-अंक वाले छात्रों की सबसे अधिक सहायता करता है, जबकि अधिक खुला, खोज उपागम आत्मविश्वासी, उच्च-अंक वाले छात्रों के लिए बेहतर है। क्रॉनबैक और स्नो ने ऐसे निष्कर्षों को क्या कहा?","optionsHi":["अभ्यास और थकान प्रभाव","प्रत्याशा (पिग्मेलियन) प्रभाव","माध्य की ओर प्रतिगमन","अभिक्षमता–उपचार अंतःक्रियाएँ"],"explanationHi":"अभिक्षमता–उपचार अंतःक्रिया तब होती है जब सर्वश्रेष्ठ विधि अधिगमकर्ता की विशेषताओं पर निर्भर करती है, इसलिए कोई एक विधि सभी के लिए सर्वश्रेष्ठ नहीं होती; यह अनुदेशन को वैयक्तिक भिन्नताओं के अनुरूप ढालने का समर्थन करती है।"},
  {"id":"cdp-child-development-1942","question":"Children who read well early read more, gain more vocabulary and knowledge, and so read even better, while weak early readers read less and fall further behind. Keith Stanovich called this:","options":["The Flynn effect","The Matthew effect","The Pygmalion effect","The Hawthorne effect"],"answer":1,"explanation":"Stanovich used the ‘rich get richer’ Matthew effect to describe how early differences in reading widen over time, which is why early support for weak readers matters so much.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"जो बच्चे जल्दी अच्छा पढ़ते हैं वे अधिक पढ़ते हैं, अधिक शब्दावली और ज्ञान पाते हैं, और इसलिए और भी बेहतर पढ़ते हैं, जबकि कमज़ोर प्रारंभिक पाठक कम पढ़ते हैं, जिससे वे और भी पीछे रह जाते हैं। कीथ स्टैनोविच ने इसे क्या कहा?","optionsHi":["फ्लिन प्रभाव","मैथ्यू प्रभाव","पिग्मेलियन प्रभाव","हॉथॉर्न प्रभाव"],"explanationHi":"स्टैनोविच ने ‘अमीर और अमीर’ वाले मैथ्यू प्रभाव का प्रयोग यह वर्णन करने के लिए किया कि पठन में प्रारंभिक अंतर समय के साथ कैसे बढ़ते हैं, इसीलिए कमज़ोर पाठकों को शीघ्र सहायता इतनी महत्वपूर्ण है।"},
  {"id":"cdp-child-development-1943","question":"A test that asks students to solve problems based on what was taught in Class 7 maths is an achievement test. A test used to predict how well students will do in a future course of study, such as music training, is:","options":["An interest inventory","An attitude scale","An aptitude test","A diagnostic test"],"answer":2,"explanation":"Achievement tests measure what has been learnt; aptitude tests predict potential to learn in a future area. Interest inventories measure preferences, and diagnostic tests locate specific learning difficulties.","difficulty":"moderate","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 7 के गणित में जो पढ़ाया गया उस पर आधारित प्रश्न हल करवाने वाला परीक्षण उपलब्धि परीक्षण है। भविष्य के किसी अध्ययन-पाठ्यक्रम, जैसे संगीत प्रशिक्षण, में छात्र कितना अच्छा करेंगे इसका पूर्वानुमान लगाने के लिए प्रयुक्त परीक्षण क्या है?","optionsHi":["रुचि सूची","अभिवृत्ति पैमाना","अभिक्षमता परीक्षण","निदानात्मक परीक्षण"],"explanationHi":"उपलब्धि परीक्षण मापते हैं कि क्या सीखा गया है; अभिक्षमता परीक्षण भविष्य के क्षेत्र में सीखने की संभाव्यता का पूर्वानुमान करते हैं। रुचि सूचियाँ पसंदें मापती हैं, और निदानात्मक परीक्षण विशिष्ट अधिगम-कठिनाइयों का पता लगाते हैं।"},
  {"id":"cdp-child-development-1944","question":"Benjamin Bloom reported that students taught one-to-one by a tutor using mastery methods scored about two standard deviations above students taught in a conventional class. The ‘2 sigma problem’ he posed to teachers was:","options":["How to find group teaching methods that come close to the results of one-to-one tutoring","How to raise every single student to two standard deviations above the national mean","How to pick out the two per cent of students who most need individual tutoring","How to cut class time by two-thirds without lowering average achievement"],"answer":0,"explanation":"Since one-to-one tutoring is too costly for all, Bloom challenged educators to find group methods, such as mastery learning with feedback and correctives, that approach its effects.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"बेंजामिन ब्लूम ने बताया कि निपुणता-विधियों का उपयोग करने वाले ट्यूटर से एक-से-एक पढ़ने वाले छात्रों ने पारंपरिक कक्षा में पढ़ने वाले छात्रों से लगभग दो मानक विचलन अधिक अंक पाए। शिक्षकों के सामने उनकी रखी ‘2 सिग्मा समस्या’ थी:","optionsHi":["ऐसी समूह-शिक्षण विधियाँ कैसे खोजें जो एक-से-एक ट्यूटरिंग के परिणामों के निकट पहुँचें","प्रत्येक छात्र को राष्ट्रीय माध्य से दो मानक विचलन ऊपर कैसे पहुँचाएँ","उन दो प्रतिशत छात्रों को कैसे पहचानें जिन्हें व्यक्तिगत ट्यूटरिंग की सबसे अधिक आवश्यकता है","औसत उपलब्धि घटाए बिना कक्षा-समय को दो-तिहाई कैसे घटाएँ"],"explanationHi":"चूँकि सभी के लिए एक-से-एक ट्यूटरिंग बहुत महँगी है, ब्लूम ने शिक्षकों को ऐसी समूह-विधियाँ खोजने की चुनौती दी, जैसे प्रतिपुष्टि और उपचारकों वाला निपुणता अधिगम, जो उसके प्रभावों के निकट पहुँचें।"},
  {"id":"cdp-child-development-1945","question":"In Fred Keller’s Personalized System of Instruction, students work through units of written material, take a test on each unit and move on only after showing mastery, with older students acting as proctors. Which feature is central to PSI?","options":["Group tests, so the class moves on together","Lectures as the main source of new content","Grading on a curve, so only a few earn top marks","Self-pacing, so each student moves on when ready"],"answer":3,"explanation":"Keller’s PSI is self-paced and mastery-based, relies on written materials and proctors, and uses lectures mainly for motivation; it treats individual differences in learning time rather than ranking students.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"फ्रेड केलर की वैयक्तिकृत अनुदेशन प्रणाली में, छात्र लिखित सामग्री की इकाइयों से गुज़रते हैं, प्रत्येक इकाई पर परीक्षण देते हैं और निपुणता दिखाने के बाद ही आगे बढ़ते हैं, बड़े छात्र प्रॉक्टर के रूप में कार्य करते हैं। PSI की केंद्रीय विशेषता कौन-सी है?","optionsHi":["समूह परीक्षण, ताकि कक्षा साथ आगे बढ़े","व्याख्यान नई विषयवस्तु के मुख्य स्रोत के रूप में","वक्र पर ग्रेडिंग, ताकि केवल कुछ ही उच्च अंक पाएँ","स्व-गति, ताकि प्रत्येक छात्र तैयार होने पर आगे बढ़े"],"explanationHi":"केलर की PSI स्व-गति और निपुणता-आधारित है, लिखित सामग्री और प्रॉक्टरों पर निर्भर है, और व्याख्यानों का उपयोग मुख्यतः अभिप्रेरणा के लिए करती है; यह छात्रों को श्रेणीबद्ध करने के बजाय अधिगम-समय की वैयक्तिक भिन्नताओं को स्वीकार करती है।"},
  {"id":"cdp-child-development-1946","question":"Which of the Big Five personality traits is most consistently associated with creativity and divergent thinking?","options":["Conscientiousness","Openness to experience","Extraversion (sociability)","Emotional stability"],"answer":1,"explanation":"Openness, which includes imagination, curiosity and preference for variety, is the trait most strongly linked with creative achievement; conscientiousness predicts marks but is not especially tied to creativity.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"बिग फ़ाइव व्यक्तित्व-गुणों में से कौन-सा सृजनात्मकता और अपसारी चिंतन से सबसे अधिक संगत रूप से जुड़ा है?","optionsHi":["कर्तव्यनिष्ठा","अनुभव के प्रति खुलापन","बहिर्मुखता (मिलनसारिता)","संवेगात्मक स्थिरता"],"explanationHi":"खुलापन, जिसमें कल्पना, जिज्ञासा और विविधता की पसंद शामिल हैं, सृजनात्मक उपलब्धि से सबसे प्रबल रूप से जुड़ा गुण है; कर्तव्यनिष्ठा अंकों का पूर्वानुमान करती है पर सृजनात्मकता से विशेष रूप से बँधी नहीं है।"},
  {"id":"cdp-child-development-1947","question":"Learning a new topic, Ishaan likes to go step by step, mastering each small part before moving on, while Tanya first wants the big picture and links ideas across the whole topic. Gordon Pask would call Ishaan’s style:","options":["Field independent","Holist","Serialist","Reflective"],"answer":2,"explanation":"Pask distinguished serialists, who build understanding in linear, step-by-step sequences, from holists, who prefer to grasp the overall structure and make wide connections first.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"कोई नया विषय सीखते हुए, ईशान चरण-दर-चरण चलना पसंद करता है, आगे बढ़ने से पहले प्रत्येक छोटे भाग में निपुणता पाता है, जबकि तान्या पहले बड़ी तस्वीर चाहती है और पूरे विषय में विचारों को जोड़ती है। गॉर्डन पास्क ईशान की शैली को क्या कहेंगे?","optionsHi":["क्षेत्र-स्वतंत्र","समग्रवादी (होलिस्ट)","क्रमवादी (सीरियलिस्ट)","चिंतनशील"],"explanationHi":"पास्क ने क्रमवादियों, जो रैखिक, चरण-दर-चरण क्रमों में समझ बनाते हैं, को समग्रवादियों से अलग किया, जो पहले समग्र संरचना को समझना और व्यापक संबंध बनाना पसंद करते हैं।"},
  {"id":"cdp-child-development-1948","question":"A Class 4 teacher reports, ‘Neha now reads 60 words per minute, up from 35 in June.’ She is comparing Neha with her own earlier performance rather than with classmates or a fixed standard. This is:","options":["Ipsative assessment","Norm-referenced assessment","Criterion-referenced assessment","Summative assessment"],"answer":0,"explanation":"Ipsative assessment compares a learner with her own previous attainment, which respects individual differences in starting points; norm-referenced compares with others and criterion-referenced with a set standard.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 की एक शिक्षिका बताती है, ‘नेहा अब प्रति मिनट 60 शब्द पढ़ती है, जून में 35 थे।’ वह नेहा की तुलना सहपाठियों या निश्चित मानक से नहीं, बल्कि उसके अपने पहले के प्रदर्शन से कर रही है। यह क्या है?","optionsHi":["स्व-तुलनात्मक (इप्सेटिव) आकलन","मानक-संदर्भित आकलन","मानदंड-संदर्भित आकलन","योगात्मक आकलन"],"explanationHi":"स्व-तुलनात्मक आकलन अधिगमकर्ता की तुलना उसकी अपनी पिछली उपलब्धि से करता है, जो प्रारंभिक बिंदुओं में वैयक्तिक भिन्नताओं का सम्मान करता है; मानक-संदर्भित दूसरों से तुलना करता है और मानदंड-संदर्भित निर्धारित मानक से।"},
  {"id":"cdp-child-development-1949","question":"A teacher notices that her quieter, more introverted students rarely answer when she calls for instant replies. Which practice best allows for this individual difference without lowering expectations?","options":["Grading participation only by the number of times a student speaks aloud","Calling only on students who raise their hands first, so no one is put on the spot","Excusing introverted students from all speaking tasks to protect their comfort","Think-pair-share: individual thinking time, then discussion with a partner, then sharing"],"answer":3,"explanation":"Thinking time and a low-risk partner stage let reflective students prepare and still contribute to the whole class; excusing them or rewarding only quick talkers either lowers expectations or favours one temperament.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षिका देखती है कि जब वह तुरंत उत्तर के लिए पुकारती है तो उसके शांत, अधिक अंतर्मुखी छात्र शायद ही कभी उत्तर देते हैं। अपेक्षाएँ घटाए बिना इस वैयक्तिक भिन्नता को स्थान देने वाली कौन-सी प्रथा सबसे अच्छी है?","optionsHi":["सहभागिता को केवल इस आधार पर अंकित करना कि छात्र कितनी बार ज़ोर से बोलता है","केवल उन छात्रों को बुलाना जो पहले हाथ उठाते हैं, ताकि किसी को असहज स्थिति में न डाला जाए","अंतर्मुखी छात्रों को उनके आराम की रक्षा के लिए सभी बोलने के कार्यों से छूट देना","सोचो-जोड़ी बनाओ-साझा करो: वैयक्तिक चिंतन का समय, फिर साथी से चर्चा, फिर साझा करना"],"explanationHi":"चिंतन का समय और कम-जोखिम वाला साथी-चरण चिंतनशील छात्रों को तैयारी करने और फिर भी पूरी कक्षा में योगदान देने देता है; उन्हें छूट देना या केवल तेज़ बोलने वालों को पुरस्कृत करना या तो अपेक्षाएँ घटाता है या एक स्वभाव का पक्ष लेता है।"},
  {"id":"cdp-child-development-1950","question":"Arif is among the best in his class at mathematics but well below his own level in written English. This difference within Arif is an example of:","options":["Inter-individual differences","Intra-individual differences","Group differences","Developmental delay"],"answer":1,"explanation":"Intra-individual differences are variations among a single person’s own abilities; inter-individual differences are variations between people, and an uneven profile alone does not indicate developmental delay.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"आरिफ़ अपनी कक्षा में गणित में सर्वश्रेष्ठ में से है पर लिखित अंग्रेज़ी में अपने स्तर से बहुत नीचे है। आरिफ़ के भीतर का यह अंतर किसका उदाहरण है?","optionsHi":["अंतर-वैयक्तिक भिन्नताएँ","अंतः-वैयक्तिक भिन्नताएँ","समूह भिन्नताएँ","विकासात्मक विलंब"],"explanationHi":"अंतः-वैयक्तिक भिन्नताएँ किसी एक व्यक्ति की अपनी योग्यताओं के बीच के अंतर हैं; अंतर-वैयक्तिक भिन्नताएँ लोगों के बीच के अंतर हैं, और केवल असमान प्रोफ़ाइल विकासात्मक विलंब का संकेत नहीं है।"},
  {"id":"cdp-child-development-1951","question":"Match each student’s remark with the kind of metacognitive knowledge John Flavell described. P. ‘I remember words much better than numbers.’ Q. ‘Essay questions need more organised revision than one-word questions.’ R. ‘Making my own summary helps me understand a chapter.’ 1. Strategy knowledge 2. Person knowledge 3. Task knowledge","options":["P-2, Q-1, R-3","P-3, Q-2, R-1","P-2, Q-3, R-1","P-1, Q-3, R-2"],"answer":2,"explanation":"Flavell divided metacognitive knowledge into person variables (beliefs about oneself and others as learners), task variables (how a task’s demands affect performance) and strategy variables (which methods work for which goals).","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"प्रत्येक छात्र की टिप्पणी का मिलान जॉन फ्लेवेल द्वारा वर्णित अधिसंज्ञानात्मक ज्ञान के प्रकार से कीजिए। P. ‘मुझे शब्द संख्याओं से कहीं बेहतर याद रहते हैं।’ Q. ‘निबंध प्रश्नों के लिए एक-शब्द वाले प्रश्नों की तुलना में अधिक संगठित पुनरावृत्ति चाहिए।’ R. ‘अपना सारांश बनाने से मुझे अध्याय समझने में मदद मिलती है।’ 1. युक्ति ज्ञान 2. व्यक्ति ज्ञान 3. कार्य ज्ञान","optionsHi":["P-2, Q-1, R-3","P-3, Q-2, R-1","P-2, Q-3, R-1","P-1, Q-3, R-2"],"explanationHi":"फ्लेवेल ने अधिसंज्ञानात्मक ज्ञान को व्यक्ति चरों (अधिगमकर्ता के रूप में स्वयं और दूसरों के बारे में विश्वास), कार्य चरों (कार्य की माँगें प्रदर्शन को कैसे प्रभावित करती हैं) और युक्ति चरों (किन लक्ष्यों के लिए कौन-सी विधियाँ काम करती हैं) में बाँटा।"},
  {"id":"cdp-child-development-1952","question":"While reading a science chapter, Mohit stops and says to himself, ‘Wait, I didn’t follow that paragraph about friction,’ and goes back to reread it with the diagram. Which component of metacognitive regulation is he mainly showing?","options":["Monitoring his comprehension while the task is going on","Planning which strategies to use before starting the task","Evaluating the final outcome after the task is completed","Declaring knowledge of facts he has already memorised"],"answer":0,"explanation":"Metacognitive regulation includes planning (before), monitoring (during) and evaluating (after). Noticing a breakdown in understanding mid-reading and fixing it is monitoring with a repair strategy.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"विज्ञान का अध्याय पढ़ते हुए, मोहित रुककर स्वयं से कहता है, ‘रुको, मुझे घर्षण वाला वह अनुच्छेद समझ नहीं आया,’ और आरेख के साथ उसे फिर से पढ़ने लौटता है। वह अधिसंज्ञानात्मक नियमन के किस घटक को मुख्यतः दर्शा रहा है?","optionsHi":["कार्य के चलते समय अपने बोध की निगरानी","कार्य शुरू करने से पहले यह योजना बनाना कि कौन-सी युक्तियाँ अपनानी हैं","कार्य पूरा होने के बाद अंतिम परिणाम का मूल्यांकन","उन तथ्यों के ज्ञान की घोषणा जिन्हें वह पहले से याद कर चुका है"],"explanationHi":"अधिसंज्ञानात्मक नियमन में योजना (पहले), निगरानी (दौरान) और मूल्यांकन (बाद) शामिल हैं। पढ़ने के बीच में समझ में अवरोध को पहचानना और उसे सुधारना मरम्मत-युक्ति के साथ निगरानी है।"},
  {"id":"cdp-child-development-1953","question":"In Barry Zimmerman’s cyclical model of self-regulated learning, setting goals and choosing strategies, then observing oneself while working, and then judging results and explaining them belong, in order, to which phases?","options":["Performance, forethought, self-reflection","Forethought, performance, self-reflection","Self-reflection, performance, forethought","Forethought, self-reflection, performance"],"answer":1,"explanation":"Zimmerman’s forethought phase covers goal setting, planning and self-efficacy; the performance phase includes self-control and self-observation; the self-reflection phase includes self-evaluation, attributions and adjustments that feed the next cycle.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"बैरी ज़िमरमैन के स्व-नियमित अधिगम के चक्रीय मॉडल में, लक्ष्य निर्धारित करना और युक्तियाँ चुनना, फिर कार्य करते समय स्वयं का अवलोकन करना, और फिर परिणामों का निर्णय करना और उनकी व्याख्या करना, क्रम से किन चरणों के अंतर्गत आते हैं?","optionsHi":["निष्पादन, पूर्वचिंतन, आत्म-चिंतन","पूर्वचिंतन, निष्पादन, आत्म-चिंतन","आत्म-चिंतन, निष्पादन, पूर्वचिंतन","पूर्वचिंतन, आत्म-चिंतन, निष्पादन"],"explanationHi":"ज़िमरमैन का पूर्वचिंतन चरण लक्ष्य-निर्धारण, योजना और आत्म-प्रभाविता को समेटता है; निष्पादन चरण में आत्म-नियंत्रण और आत्म-अवलोकन शामिल हैं; आत्म-चिंतन चरण में आत्म-मूल्यांकन, आरोपण और समायोजन शामिल हैं जो अगले चक्र का आधार बनते हैं।"},
  {"id":"cdp-child-development-1954","question":"Before a unit on birds, a Class 4 teacher draws three columns on the board, fills the first with what children already know, the second with what they want to find out, and returns at the end to fill the third. This strategy is called:","options":["A flow chart","A concept map","A Venn diagram","A KWL chart"],"answer":3,"explanation":"Donna Ogle’s KWL chart (Know, Want to know, Learned) activates prior knowledge, gives learners a say in what they will explore, and ends with reflection on what was learnt.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"पक्षियों पर इकाई से पहले, कक्षा 4 की शिक्षिका श्यामपट्ट पर तीन स्तंभ बनाती है, पहले में वह भरती है जो बच्चे पहले से जानते हैं, दूसरे में जो वे जानना चाहते हैं, और अंत में लौटकर तीसरा भरती है। इस रणनीति को क्या कहते हैं?","optionsHi":["प्रवाह-चार्ट","संप्रत्यय मानचित्र","वेन आरेख","KWL चार्ट"],"explanationHi":"डोना ओगल का KWL चार्ट (जानते हैं, जानना चाहते हैं, सीखा) पूर्व ज्ञान को सक्रिय करता है, अधिगमकर्ताओं को इसमें हिस्सेदारी देता है कि वे क्या खोजेंगे, और जो सीखा गया उस पर चिंतन के साथ समाप्त होता है।"},
  {"id":"cdp-child-development-1955","question":"Hattie and Timperley suggest that effective feedback answers three questions. Which set matches ‘feed up’, ‘feed back’ and ‘feed forward’ in that order?","options":["Where to next? How am I going? Where am I going?","How am I going? Where am I going? Where to next?","Where am I going? How am I going? Where to next?","Where am I going? Where to next? How am I going?"],"answer":2,"explanation":"Feed up clarifies the goal, feed back describes progress towards it, and feed forward identifies the next steps; together they help close the gap between current and desired performance.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"हैटी और टिम्परली सुझाते हैं कि प्रभावी प्रतिपुष्टि तीन प्रश्नों के उत्तर देती है। कौन-सा समूह उसी क्रम में ‘फ़ीड अप’, ‘फ़ीड बैक’ और ‘फ़ीड फ़ॉरवर्ड’ से मेल खाता है?","optionsHi":["आगे कहाँ? मैं कैसा कर रहा हूँ? मैं कहाँ जा रहा हूँ?","मैं कैसा कर रहा हूँ? मैं कहाँ जा रहा हूँ? आगे कहाँ?","मैं कहाँ जा रहा हूँ? मैं कैसा कर रहा हूँ? आगे कहाँ?","मैं कहाँ जा रहा हूँ? आगे कहाँ? मैं कैसा कर रहा हूँ?"],"explanationHi":"फ़ीड अप लक्ष्य को स्पष्ट करता है, फ़ीड बैक उसकी ओर प्रगति का वर्णन करता है, और फ़ीड फ़ॉरवर्ड अगले चरण पहचानता है; साथ मिलकर वे वर्तमान और वांछित प्रदर्शन के बीच की खाई को पाटने में मदद करते हैं।"},
  {"id":"cdp-child-development-1956","question":"Ms Kaur asks, ‘Why do we see lightning before we hear thunder?’ Rani answers, ‘Because light is faster.’ Ms Kaur then turns to Sohail: ‘Do you agree with Rani? Why?’ This questioning technique is called:","options":["Rhetorical questioning","Probing","Prompting","Redirecting"],"answer":3,"explanation":"Redirecting puts the same question or a classmate’s answer to another student, widening participation; probing would ask Rani herself to explain further, and prompting gives hints to a student who is stuck.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"सुश्री कौर पूछती हैं, ‘हम बिजली की चमक पहले क्यों देखते हैं और गड़गड़ाहट बाद में क्यों सुनते हैं?’ रानी उत्तर देती है, ‘क्योंकि प्रकाश तेज़ है।’ फिर सुश्री कौर सोहेल की ओर मुड़ती हैं: ‘क्या तुम रानी से सहमत हो? क्यों?’ इस प्रश्न-तकनीक को क्या कहते हैं?","optionsHi":["वाक्पटु (रेटोरिकल) प्रश्न","अन्वेषी (प्रोबिंग) प्रश्न","संकेतात्मक (प्रॉम्प्टिंग) प्रश्न","पुनर्निर्देशन (रीडायरेक्टिंग)"],"explanationHi":"पुनर्निर्देशन उसी प्रश्न या किसी सहपाठी के उत्तर को दूसरे छात्र के सामने रखता है, भागीदारी बढ़ाता है; अन्वेषी प्रश्न रानी से ही और समझाने को कहता, और संकेतात्मक प्रश्न अटके हुए छात्र को संकेत देता।"},
  {"id":"cdp-child-development-1957","question":"In the 5E model of inquiry teaching, which sequence is correct?","options":["Engage, Explore, Explain, Elaborate, Evaluate","Explain, Engage, Explore, Elaborate, Evaluate","Engage, Explain, Explore, Evaluate, Elaborate","Explore, Engage, Explain, Evaluate, Elaborate"],"answer":0,"explanation":"Students’ interest is first engaged, they then explore phenomena hands-on, concepts are explained (building on that exploration), applied in new situations (elaborate), and understanding is evaluated.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"जाँच-आधारित शिक्षण के 5E मॉडल में, कौन-सा क्रम सही है?","optionsHi":["संलग्न करना (Engage), अन्वेषण (Explore), व्याख्या (Explain), विस्तार (Elaborate), मूल्यांकन (Evaluate)","व्याख्या (Explain), संलग्न करना (Engage), अन्वेषण (Explore), विस्तार (Elaborate), मूल्यांकन (Evaluate)","संलग्न करना (Engage), व्याख्या (Explain), अन्वेषण (Explore), मूल्यांकन (Evaluate), विस्तार (Elaborate)","अन्वेषण (Explore), संलग्न करना (Engage), व्याख्या (Explain), मूल्यांकन (Evaluate), विस्तार (Elaborate)"],"explanationHi":"पहले छात्रों की रुचि जगाई जाती है, फिर वे परिघटनाओं का प्रत्यक्ष अन्वेषण करते हैं, संप्रत्ययों की व्याख्या (उस अन्वेषण पर आधारित) की जाती है, नई स्थितियों में उनका अनुप्रयोग (विस्तार) होता है, और समझ का मूल्यांकन किया जाता है।"},
  {"id":"cdp-child-development-1958","question":"Which classroom sequence is typical of problem-based learning?","options":["The teacher first explains all the concepts, then gives problems from the textbook to practise them","Students first meet an open, real problem, find out what they need to learn, research it and propose solutions","Students read the textbook chapter alone and then answer the questions given at its end","The teacher demonstrates a solution, then students repeat the same steps on similar problems"],"answer":1,"explanation":"In problem-based learning an ill-structured, realistic problem comes first and drives self-directed inquiry, with the teacher as facilitator; teaching concepts first and then setting problems is conventional instruction.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"समस्या-आधारित अधिगम का विशिष्ट कक्षा-क्रम कौन-सा है?","optionsHi":["शिक्षक पहले सभी संप्रत्यय समझाता है, फिर उनके अभ्यास के लिए पाठ्यपुस्तक से प्रश्न देता है","छात्र पहले एक खुली, वास्तविक समस्या से मिलते हैं, पता लगाते हैं कि उन्हें क्या सीखना है, उस पर शोध करते हैं और समाधान प्रस्तावित करते हैं","छात्र अकेले पाठ्यपुस्तक का अध्याय पढ़ते हैं और फिर उसके अंत में दिए गए प्रश्नों के उत्तर देते हैं","शिक्षक एक समाधान प्रदर्शित करता है, फिर छात्र समान प्रश्नों पर वही चरण दोहराते हैं"],"explanationHi":"समस्या-आधारित अधिगम में एक अपरिभाषित, यथार्थवादी समस्या पहले आती है और स्व-निर्देशित अन्वेषण को चलाती है, शिक्षक सुविधाप्रदाता के रूप में; पहले संप्रत्यय पढ़ाना और फिर समस्याएँ देना पारंपरिक अनुदेशन है।"},
  {"id":"cdp-child-development-1959","question":"Class 6 decides to set up a small kitchen garden. Which order follows the steps of William Kilpatrick’s project method?","options":["Purposing, executing, planning, judging","Planning, purposing, executing, judging","Purposing, planning, executing, judging","Executing, purposing, planning, judging"],"answer":2,"explanation":"Kilpatrick, Dewey’s student, described a project as a ‘wholehearted purposeful activity’: learners first form the purpose, then plan, carry out the plan and finally judge the outcome.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"कक्षा 6 एक छोटी किचन गार्डन बनाने का निर्णय लेती है। विलियम किलपैट्रिक की परियोजना विधि के चरणों का अनुसरण करने वाला क्रम कौन-सा है?","optionsHi":["उद्देश्य निर्धारण, क्रियान्वयन, योजना बनाना, निर्णय करना","योजना बनाना, उद्देश्य निर्धारण, क्रियान्वयन, निर्णय करना","उद्देश्य निर्धारण, योजना बनाना, क्रियान्वयन, निर्णय करना","क्रियान्वयन, उद्देश्य निर्धारण, योजना बनाना, निर्णय करना"],"explanationHi":"डेवी के शिष्य किलपैट्रिक ने परियोजना को ‘पूर्ण मनोयोग से उद्देश्यपूर्ण गतिविधि’ बताया: अधिगमकर्ता पहले उद्देश्य बनाते हैं, फिर योजना बनाते हैं, योजना को क्रियान्वित करते हैं और अंत में परिणाम का निर्णय करते हैं।"},
  {"id":"cdp-child-development-1960","question":"In Robert Slavin’s Student Teams–Achievement Divisions (STAD), mixed-ability teams study together, but each student takes the quiz alone. How are team scores worked out?","options":["From one joint quiz answered together by the whole team","From the single highest quiz score obtained by any member","From the quiz score of the weakest member of the team only","From how much each member improves on his or her own past average"],"answer":3,"explanation":"STAD awards improvement points based on each student’s gain over his own base score, so every member, weak or strong, can contribute equally; individual quizzes keep each member accountable.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"रॉबर्ट स्लैविन के स्टूडेंट टीम्स–एचीवमेंट डिवीज़न्स (STAD) में, मिश्रित-योग्यता वाली टीमें साथ पढ़ती हैं, परंतु प्रत्येक छात्र प्रश्नोत्तरी अकेले देता है। टीम के अंक कैसे निकाले जाते हैं?","optionsHi":["एक संयुक्त प्रश्नोत्तरी से जो पूरी टीम साथ मिलकर हल करती है","किसी भी सदस्य द्वारा प्राप्त एकमात्र उच्चतम प्रश्नोत्तरी अंक से","केवल टीम के सबसे कमज़ोर सदस्य के प्रश्नोत्तरी अंक से","प्रत्येक सदस्य के अपने पिछले औसत की तुलना में सुधार से"],"explanationHi":"STAD प्रत्येक छात्र के अपने आधार अंक से प्राप्त लाभ पर आधारित सुधार-अंक देता है, इसलिए प्रत्येक सदस्य, कमज़ोर हो या सशक्त, समान रूप से योगदान दे सकता है; वैयक्तिक प्रश्नोत्तरियाँ प्रत्येक सदस्य को उत्तरदायी रखती हैं।"},
  {"id":"cdp-child-development-1961","question":"A teacher first solves a sum aloud while the class watches, then solves similar sums together with the class, then lets pairs try, and finally has each child solve on his own. This follows the model of:","options":["Gradual release of responsibility","Skinner’s linear programmed instruction","Bruner’s guided discovery learning","Rote drill and repeated practice"],"answer":0,"explanation":"Pearson and Gallagher’s gradual release model (‘I do, we do, you do together, you do alone’) shifts responsibility from teacher to learner step by step.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक पहले कक्षा के देखते हुए एक सवाल ज़ोर से हल करता है, फिर कक्षा के साथ मिलकर समान सवाल हल करता है, फिर जोड़ियों को आज़माने देता है, और अंत में प्रत्येक बच्चे से अकेले हल करवाता है। यह किस मॉडल का अनुसरण करता है?","optionsHi":["उत्तरदायित्व का क्रमिक हस्तांतरण","स्किनर का रैखिक अभिक्रमित अनुदेशन","ब्रूनर का निर्देशित खोज अधिगम","रटंत अभ्यास और बार-बार का अभ्यास"],"explanationHi":"पियर्सन और गैलाघर का क्रमिक हस्तांतरण मॉडल (‘मैं करता हूँ, हम करते हैं, तुम साथ करते हो, तुम अकेले करते हो’) उत्तरदायित्व को शिक्षक से अधिगमकर्ता की ओर चरण-दर-चरण ले जाता है।"},
  {"id":"cdp-child-development-1962","question":"Before dropping a sheet of paper and a crumpled ball of the same paper, a teacher asks students to write down which will land first and why, then to watch, and then to reconcile what they saw with what they predicted. This strategy is:","options":["Think–Pair–Share","Predict–Observe–Explain","Know–Want–Learned (KWL)","Drill and repeated practice"],"answer":1,"explanation":"White and Gunstone’s POE makes students commit to a prediction based on their ideas, so a surprising observation creates conflict that the explanation stage helps resolve.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक काग़ज़ की शीट और उसी काग़ज़ की मुड़ी हुई गेंद गिराने से पहले, एक शिक्षक छात्रों से लिखने को कहता है कि कौन पहले गिरेगी और क्यों, फिर देखने को, और फिर जो देखा उसे अपने पूर्वानुमान से मिलाने को। यह रणनीति क्या है?","optionsHi":["सोचो–जोड़ी बनाओ–साझा करो","पूर्वानुमान–अवलोकन–व्याख्या","जानते हैं–जानना चाहते हैं–सीखा (KWL)","रटंत अभ्यास और बार-बार का अभ्यास"],"explanationHi":"व्हाइट और गनस्टोन का POE छात्रों को अपने विचारों पर आधारित पूर्वानुमान के प्रति प्रतिबद्ध करता है, ताकि आश्चर्यजनक अवलोकन द्वंद्व उत्पन्न करे जिसे व्याख्या चरण सुलझाने में सहायता करता है।"},
  {"id":"cdp-child-development-1963","question":"In Helen Parkhurst’s Dalton Plan, students receive monthly assignments in each subject, decide their own pace and order of work, and use subject ‘laboratories’ with teachers as advisers. Its central principles are:","options":["Teacher lectures, rote revision and monthly ranking","Strict class timetables, daily drill and frequent rewards","Freedom, cooperation and budgeting of one’s own time","Play, songs and Froebel-style gifts in groups"],"answer":2,"explanation":"Parkhurst based the Dalton Plan on freedom to work at one’s own rhythm, cooperation among students, and responsibility for budgeting time through assignment contracts.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"हेलेन पार्कहर्स्ट की डाल्टन योजना में, छात्रों को प्रत्येक विषय में मासिक कार्य-नियत मिलते हैं, वे अपनी गति और कार्य का क्रम स्वयं तय करते हैं, और शिक्षकों के सलाहकार होने के साथ विषय ‘प्रयोगशालाओं’ का उपयोग करते हैं। इसके केंद्रीय सिद्धांत हैं:","optionsHi":["शिक्षक का व्याख्यान, रटंत पुनरावृत्ति और मासिक श्रेणीकरण","कठोर कक्षा समय-सारणी, दैनिक कवायद और बार-बार पुरस्कार","स्वतंत्रता, सहयोग और अपने समय का बजट बनाना","खेल, गीत और समूहों में फ्रोबेल-शैली के उपहार"],"explanationHi":"पार्कहर्स्ट ने डाल्टन योजना को अपनी लय में कार्य करने की स्वतंत्रता, छात्रों के बीच सहयोग, और कार्य-अनुबंधों के माध्यम से समय का बजट बनाने के उत्तरदायित्व पर आधारित किया।"},
  {"id":"cdp-child-development-1964","question":"Rousseau, in ‘Emile’, recommended ‘negative education’ in the early years. By this he meant that:","options":["Children should be corrected for every mistake so that bad habits never take root","Adults should not force lessons or rules early, but let nature and experience teach","Early education should focus on correcting children’s negative feelings and attitudes","Children should learn by memorising what not to do from books of rules"],"answer":1,"explanation":"For Rousseau, early education should guard the heart from vice and the mind from error rather than teach virtue and truth directly; the child learns from things and natural consequences at his own pace.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"रूसो ने ‘एमिल’ में प्रारंभिक वर्षों में ‘नकारात्मक शिक्षा’ की अनुशंसा की। इससे उनका आशय था कि:","optionsHi":["बच्चों को हर गलती पर सुधारा जाना चाहिए ताकि बुरी आदतें कभी जड़ न पकड़ें","वयस्कों को शुरू में पाठ या नियम नहीं थोपने चाहिए, बल्कि प्रकृति और अनुभव को सिखाने देना चाहिए","प्रारंभिक शिक्षा को बच्चों की नकारात्मक भावनाओं और अभिवृत्तियों को सुधारने पर केंद्रित होना चाहिए","बच्चों को नियमों की पुस्तकों से यह रटकर सीखना चाहिए कि क्या नहीं करना है"],"explanationHi":"रूसो के लिए, प्रारंभिक शिक्षा को सद्गुण और सत्य सीधे सिखाने के बजाय हृदय को दुर्गुण से और मस्तिष्क को त्रुटि से बचाना चाहिए; बच्चा वस्तुओं और प्राकृतिक परिणामों से अपनी गति से सीखता है।"},
  {"id":"cdp-child-development-1965","question":"Pestalozzi insisted that teaching should begin with what children directly perceive through the senses, moving from the concrete to the abstract. His term for this principle is:","options":["Anschauung (sense impression)","Kindergarten (child garden)","Apperception (assimilating ideas)","Prepared environment"],"answer":0,"explanation":"Pestalozzi’s Anschauung stressed observation and sense experience as the foundation of knowledge, leading to object lessons; the kindergarten is Froebel’s, apperception Herbart’s, and the prepared environment Montessori’s.","difficulty":"moderate","source":"DSSSB TGT · KVS PGT","questionHi":"पेस्टालॉज़ी का आग्रह था कि शिक्षण उससे शुरू होना चाहिए जो बच्चे इंद्रियों से सीधे प्रत्यक्ष करते हैं, मूर्त से अमूर्त की ओर बढ़ते हुए। इस सिद्धांत के लिए उनका शब्द क्या है?","optionsHi":["आंशाउंग (इंद्रिय-अनुभूति)","किंडरगार्टन (बाल उद्यान)","अपप्रत्यक्षण (विचारों का आत्मसात्करण)","तैयार परिवेश"],"explanationHi":"पेस्टालॉज़ी के आंशाउंग ने ज्ञान की नींव के रूप में अवलोकन और इंद्रिय-अनुभव पर ज़ोर दिया, जो वस्तु-पाठों की ओर ले गया; किंडरगार्टन फ्रोबेल का है, अपप्रत्यक्षण हर्बार्ट का, और तैयार परिवेश मॉन्टेसरी का।"},
  {"id":"cdp-child-development-1966","question":"Which order gives the Herbartian formal steps of a lesson?","options":["Application, preparation, presentation, association, generalisation","Presentation, preparation, generalisation, association, application","Preparation, association, presentation, application, generalisation","Preparation, presentation, association, generalisation, application"],"answer":3,"explanation":"Herbart’s followers set out preparation (linking to old ideas), presentation, association (comparison), generalisation and application; the plan is systematic but largely teacher-directed.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"कौन-सा क्रम पाठ के हर्बार्टीय औपचारिक सोपान देता है?","optionsHi":["अनुप्रयोग, तैयारी, प्रस्तुतीकरण, साहचर्य, सामान्यीकरण","प्रस्तुतीकरण, तैयारी, सामान्यीकरण, साहचर्य, अनुप्रयोग","तैयारी, साहचर्य, प्रस्तुतीकरण, अनुप्रयोग, सामान्यीकरण","तैयारी, प्रस्तुतीकरण, साहचर्य, सामान्यीकरण, अनुप्रयोग"],"explanationHi":"हर्बार्ट के अनुयायियों ने तैयारी (पुराने विचारों से जोड़ना), प्रस्तुतीकरण, साहचर्य (तुलना), सामान्यीकरण और अनुप्रयोग को निर्धारित किया; योजना व्यवस्थित है पर बहुत हद तक शिक्षक-निर्देशित।"},
  {"id":"cdp-child-development-1967","question":"In a Class 7 discussion, the teacher responds to each answer by asking others to build on it, chains the ideas together over several turns and keeps the discussion moving towards a clear goal. Robin Alexander calls teaching with these features:","options":["Rote teaching","Recitation","Dialogic teaching","Expository teaching"],"answer":2,"explanation":"Alexander’s dialogic teaching is collective, reciprocal, supportive, cumulative and purposeful; recitation is a closed question–answer–feedback cycle that tests recall rather than building ideas together.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"कक्षा 7 की चर्चा में, शिक्षक प्रत्येक उत्तर पर दूसरों से उस पर आगे बढ़ने को कहता है, कई बारी में विचारों को जोड़ती है और चर्चा को स्पष्ट लक्ष्य की ओर चलाए रखती है। रॉबिन अलेक्ज़ेंडर इन विशेषताओं वाले शिक्षण को क्या कहते हैं?","optionsHi":["रटंत शिक्षण","पाठ-पठन (रेसिटेशन)","संवादात्मक शिक्षण","व्याख्यानात्मक शिक्षण"],"explanationHi":"अलेक्ज़ेंडर का संवादात्मक शिक्षण सामूहिक, पारस्परिक, सहायक, संचयी और उद्देश्यपूर्ण है; पाठ-पठन एक बंद प्रश्न–उत्तर–प्रतिपुष्टि चक्र है जो विचारों को साथ बनाने के बजाय स्मरण को परखता है।"},
  {"id":"cdp-child-development-1968","question":"A Class 9 teacher asks students to watch a short video lesson at home and uses class time for problem-solving, discussion and individual help. This model is called:","options":["Programmed learning","The flipped classroom","The Dalton Plan","Team teaching by two teachers"],"answer":1,"explanation":"In the flipped classroom, first exposure to content happens outside class and class time is used for active work and guidance; the Dalton Plan uses monthly assignment contracts and subject laboratories.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 9 का शिक्षक छात्रों से घर पर एक छोटा वीडियो पाठ देखने को कहता है और कक्षा-समय का उपयोग समस्या-समाधान, चर्चा और वैयक्तिक सहायता के लिए करता है। इस मॉडल को क्या कहते हैं?","optionsHi":["अभिक्रमित अधिगम","उलटी कक्षा (फ़्लिप्ड क्लासरूम)","डाल्टन योजना","दो शिक्षकों द्वारा सहयोगी शिक्षण"],"explanationHi":"उलटी कक्षा में विषयवस्तु से पहला परिचय कक्षा के बाहर होता है और कक्षा-समय सक्रिय कार्य और मार्गदर्शन के लिए प्रयुक्त होता है; डाल्टन योजना में मासिक कार्य-अनुबंध और विषय प्रयोगशालाएँ होती हैं।"},
  {"id":"cdp-child-development-1969","question":"Michelene Chi and colleagues studied students learning physics from worked examples. Those who learnt the most were the ones who:","options":["Explained each step to themselves, saying why it worked and how it linked to principles","Read each worked example several times until they could reproduce it from memory","Skipped the examples and went straight to solving practice problems","Copied the examples neatly into their notebooks before solving problems"],"answer":0,"explanation":"Chi’s self-explanation effect: good learners generated explanations that filled gaps and connected steps to principles, while weaker learners paraphrased or simply read; prompting self-explanation improves learning.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"मिशेलीन ची और सहयोगियों ने हल किए गए उदाहरणों से भौतिकी सीखने वाले छात्रों का अध्ययन किया। जिन्होंने सबसे अधिक सीखा, वे वे थे जिन्होंने:","optionsHi":["प्रत्येक चरण को स्वयं को समझाया, यह कहते हुए कि वह क्यों काम करता है और सिद्धांतों से कैसे जुड़ता है","प्रत्येक हल किए उदाहरण को कई बार पढ़ा जब तक वे उसे स्मृति से दोहरा न सकें","उदाहरणों को छोड़कर सीधे अभ्यास प्रश्न हल करने लगे","प्रश्न हल करने से पहले उदाहरणों को अपनी कॉपी में साफ़-साफ़ उतारा"],"explanationHi":"ची का स्व-व्याख्या प्रभाव: अच्छे अधिगमकर्ताओं ने ऐसी व्याख्याएँ उत्पन्न कीं जो अंतराल भरती थीं और चरणों को सिद्धांतों से जोड़ती थीं, जबकि कमज़ोर अधिगमकर्ताओं ने अन्य शब्दों में दोहराया या केवल पढ़ा; स्व-व्याख्या के लिए प्रेरित करना अधिगम सुधारता है।"},
  {"id":"cdp-child-development-1970","question":"In ‘cognitive apprenticeship’, as described by Collins, Brown and Newman, a teacher first thinks aloud while solving, then coaches and scaffolds students, and then asks them to put their own reasoning into words. That last step is called:","options":["Exploration","Modelling","Coaching","Articulation"],"answer":3,"explanation":"The methods of cognitive apprenticeship are modelling, coaching, scaffolding, articulation, reflection and exploration; articulation gets learners to make their knowledge and reasoning explicit.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"कॉलिन्स, ब्राउन और न्यूमैन द्वारा वर्णित ‘संज्ञानात्मक प्रशिक्षुता’ में, शिक्षक पहले हल करते समय ज़ोर से सोचता है, फिर छात्रों को निर्देशित और पाड़ प्रदान करता है, और फिर उनसे अपने तर्क को शब्दों में रखने को कहता है। उस अंतिम चरण को क्या कहते हैं?","optionsHi":["अन्वेषण","आदर्श-प्रस्तुति (मॉडलिंग)","प्रशिक्षण (कोचिंग)","अभिव्यक्तिकरण (आर्टिकुलेशन)"],"explanationHi":"संज्ञानात्मक प्रशिक्षुता की विधियाँ हैं आदर्श-प्रस्तुति, कोचिंग, पाड़, अभिव्यक्तिकरण, चिंतन और अन्वेषण; अभिव्यक्तिकरण अधिगमकर्ताओं को अपने ज्ञान और तर्क को स्पष्ट करवाता है।"},
  {"id":"cdp-child-development-1971","question":"Group A is taught a formula for variability and then practises it. Group B is first asked to invent their own ways of comparing the consistency of two cricketers, mostly fails to find the standard method, and is then taught the formula. Manu Kapur’s studies of such ‘productive failure’ found that Group B typically:","options":["Did better only because they spent more total time on the topic","Did worse on all measures, because failing first lowered their confidence","Gained deeper conceptual understanding and transfer, with similar routine skill","Did equally well on everything, since both groups learnt the same formula"],"answer":2,"explanation":"Generating solutions first activates prior knowledge and highlights the key features of the problem, so later instruction is better understood; studies found gains in conceptual understanding and transfer with similar procedural skill.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"समूह A को परिवर्तनशीलता का सूत्र सिखाया जाता है और फिर वे उसका अभ्यास करते हैं। समूह B से पहले दो क्रिकेटरों की संगति की तुलना के अपने तरीके गढ़ने को कहा जाता है, वे प्रायः मानक विधि खोजने में असफल रहते हैं, और फिर उन्हें सूत्र सिखाया जाता है। मनु कपूर के ऐसे ‘उत्पादक विफलता’ के अध्ययनों ने पाया कि समूह B ने सामान्यतः:","optionsHi":["केवल इसलिए बेहतर किया क्योंकि उन्होंने विषय पर कुल अधिक समय बिताया","सभी मापों पर बदतर किया, क्योंकि पहले असफल होने ने उनका आत्मविश्वास घटाया","समान नियमित कौशल के साथ गहरी संप्रत्ययात्मक समझ और अंतरण प्राप्त किया","सब कुछ पर समान किया, क्योंकि दोनों समूहों ने वही सूत्र सीखा"],"explanationHi":"पहले समाधान उत्पन्न करना पूर्व ज्ञान को सक्रिय करता है और समस्या की मुख्य विशेषताओं को उभारता है, इसलिए बाद का अनुदेशन बेहतर समझा जाता है; अध्ययनों ने समान प्रक्रियात्मक कौशल के साथ संप्रत्ययात्मक समझ और अंतरण में लाभ पाया।"},
  {"id":"cdp-child-development-1972","question":"When Varun refuses to work and says, ‘You can’t make me,’ his teacher feels angry and challenged. According to Rudolf Dreikurs, Varun’s mistaken goal is most likely:","options":["Attention","Power","Revenge","Display of inadequacy"],"answer":1,"explanation":"Dreikurs used the teacher’s own reaction as a clue: annoyance suggests attention-seeking, feeling challenged or defeated suggests a power struggle, feeling hurt suggests revenge, and feeling helpless suggests assumed inadequacy.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"जब वरुण काम करने से मना करता है और कहता है, ‘आप मुझे बाध्य नहीं कर सकते,’ तो उसका शिक्षक क्रोधित और चुनौती-ग्रस्त महसूस करता है। रूडोल्फ़ ड्रेइकुर्स के अनुसार, वरुण का भ्रांत लक्ष्य सबसे अधिक संभावना से है:","optionsHi":["ध्यान","शक्ति","प्रतिशोध","अक्षमता का प्रदर्शन"],"explanationHi":"ड्रेइकुर्स ने शिक्षक की अपनी प्रतिक्रिया को संकेत के रूप में प्रयोग किया: खीझ ध्यान-आकर्षण सुझाती है, चुनौती-ग्रस्त या पराजित महसूस करना शक्ति-संघर्ष, आहत महसूस करना प्रतिशोध, और असहाय महसूस करना मानी हुई अक्षमता सुझाता है।"},
  {"id":"cdp-child-development-1973","question":"During art, Kavya carelessly knocks over a pot of paint on the floor. Which response is a ‘logical consequence’ in Dreikurs’ sense?","options":["Kavya helps wipe up the paint before going on with her work","Kavya loses her games period for the rest of the week","Kavya writes ‘I will be careful’ fifty times after school","Kavya is scolded in front of the class so that others learn"],"answer":0,"explanation":"A logical consequence is related to the behaviour, respectful and reasonable, so the child sees the link between action and result; unrelated penalties or public shaming are punishments.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कला के दौरान, काव्या लापरवाही से फ़र्श पर रंग का एक पात्र गिरा देती है। ड्रेइकुर्स के अर्थ में कौन-सी प्रतिक्रिया ‘तार्किक परिणाम’ है?","optionsHi":["काव्या अपना काम आगे बढ़ाने से पहले रंग पोंछने में सहायता करती है","काव्या सप्ताह के शेष भाग के लिए अपना खेल-पीरियड खो देती है","काव्या विद्यालय के बाद पचास बार ‘मैं सावधान रहूँगी’ लिखती है","काव्या को कक्षा के सामने डाँटा जाता है ताकि दूसरे सीखें"],"explanationHi":"तार्किक परिणाम व्यवहार से संबंधित, सम्मानजनक और उचित होता है, ताकि बच्चा क्रिया और परिणाम के बीच संबंध देखे; असंबद्ध दंड या सार्वजनिक अपमान दंड हैं।"},
  {"id":"cdp-child-development-1974","question":"William Glasser’s choice theory holds that all behaviour is an attempt to satisfy basic needs. Which set lists the needs he proposed?","options":["Achievement, affiliation, power","Physiological, safety, belonging, esteem, self-actualisation","Autonomy, competence, relatedness","Survival, love and belonging, power, freedom, fun"],"answer":3,"explanation":"Glasser named five needs, survival, love and belonging, power (competence), freedom and fun, and urged schools to meet them so students choose to work; the other sets are Maslow’s, Deci and Ryan’s, and McClelland’s.","difficulty":"hard","source":"DSSSB TGT · KVS PGT","questionHi":"विलियम ग्लैसर का चयन सिद्धांत मानता है कि सभी व्यवहार मूल आवश्यकताओं को संतुष्ट करने का प्रयास है। कौन-सा समूह उन आवश्यकताओं की सूची देता है जिनका उन्होंने प्रस्ताव किया?","optionsHi":["उपलब्धि, संबद्धता, शक्ति","शारीरिक, सुरक्षा, अपनापन, सम्मान, आत्म-सिद्धि","स्वायत्तता, सक्षमता, संबद्धता","उत्तरजीविता, प्रेम और अपनापन, शक्ति, स्वतंत्रता, आनंद"],"explanationHi":"ग्लैसर ने पाँच आवश्यकताएँ बताईं: उत्तरजीविता, प्रेम और अपनापन, शक्ति (सक्षमता), स्वतंत्रता और आनंद, और विद्यालयों से आग्रह किया कि इन्हें पूरा करें ताकि छात्र कार्य करना चुनें; अन्य समूह मैस्लो, डेसी और रायन, तथा मैक्लेलैंड के हैं।"},
  {"id":"cdp-child-development-1975","question":"In ‘Experience and Education’, John Dewey warned that not all experiences are educative. He judged an experience by two criteria, namely:","options":["Discipline, whether it trains the mind, and memory, how much of it can be recalled later","Pleasure, whether learners enjoy it, and speed, how quickly the syllabus gets covered","Continuity (does it lead to further growth?) and interaction (does it fit learner and setting?)","Novelty, whether it is new, and difficulty, whether it challenges the brightest students"],"answer":2,"explanation":"Dewey argued that an experience is educative when it promotes further growth (continuity) and arises from the interplay between the learner’s needs and the environment (interaction); some enjoyable experiences are mis-educative.","difficulty":"very-hard","source":"DSSSB TGT · KVS PGT","questionHi":"‘एक्सपीरियंस एंड एजुकेशन’ में जॉन डेवी ने चेतावनी दी कि सभी अनुभव शैक्षिक नहीं होते। उन्होंने किसी अनुभव को दो कसौटियों पर परखा, अर्थात:","optionsHi":["अनुशासन, कि क्या वह मस्तिष्क को प्रशिक्षित करता है, और स्मृति, कि उसका कितना बाद में याद किया जा सकता है","आनंद, कि क्या अधिगमकर्ता उसका आनंद लेते हैं, और गति, कि पाठ्यक्रम कितनी शीघ्र पूरा होता है","निरंतरता (क्या वह आगे के विकास की ओर ले जाता है?) और अंतःक्रिया (क्या वह अधिगमकर्ता और परिवेश के अनुरूप है?)","नवीनता, कि क्या वह नया है, और कठिनाई, कि क्या वह सबसे मेधावी छात्रों को चुनौती देता है"],"explanationHi":"डेवी ने तर्क दिया कि अनुभव शैक्षिक तब है जब वह आगे के विकास को बढ़ावा दे (निरंतरता) और अधिगमकर्ता की आवश्यकताओं और परिवेश की अंतःक्रिया से उत्पन्न हो (अंतःक्रिया); कुछ आनंददायक अनुभव अशैक्षिक होते हैं।"},
  {"id":"cdp-child-development-1976","question":"Children watch a puppet, Sally, put her marble in a basket and leave. Another puppet moves it to a box. Asked, ‘Where will Sally look for her marble?’, most three-year-olds point to the box. Typically developing children begin to answer ‘the basket’ at about:","options":["Ten to eleven years","Eighteen months","Seven to eight years","Four to five years"],"answer":3,"explanation":"Passing this first-order false-belief task shows understanding that people act on their beliefs even when the beliefs are wrong; most children pass at about four to five, while three-year-olds answer from their own knowledge.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"बच्चे एक कठपुतली, सैली, को अपना कंचा टोकरी में रखकर जाते देखते हैं। दूसरी कठपुतली उसे एक डिब्बे में ले जाती है। यह पूछे जाने पर, ‘सैली अपना कंचा कहाँ ढूँढ़ेगी?’, अधिकांश तीन वर्ष के बच्चे डिब्बे की ओर इशारा करते हैं। सामान्य रूप से विकसित हो रहे बच्चे लगभग किस आयु में ‘टोकरी’ उत्तर देना शुरू करते हैं?","optionsHi":["दस से ग्यारह वर्ष","अठारह माह","सात से आठ वर्ष","चार से पाँच वर्ष"],"explanationHi":"इस प्रथम-क्रम के मिथ्या-विश्वास कार्य को पार करना यह समझ दर्शाता है कि लोग अपने विश्वासों पर कार्य करते हैं भले ही विश्वास गलत हों; अधिकांश बच्चे लगभग चार से पाँच वर्ष पर पार करते हैं, जबकि तीन वर्ष के बच्चे अपने ज्ञान के आधार पर उत्तर देते हैं।"},
  {"id":"cdp-child-development-1977","question":"A three-year-old is shown a familiar sweets box, says it holds sweets, and is then shown it actually holds pencils. Asked, ‘What did you think was inside before we opened it?’, she replies, ‘Pencils.’ This shows that she:","options":["Cannot yet represent her own earlier false belief about the box","Is deliberately lying so as not to look foolish in front of the adult","Has forgotten what she said because of a weak short-term memory","Lacks object permanence and cannot remember objects once hidden"],"answer":0,"explanation":"In Gopnik and Astington’s unexpected-contents task, three-year-olds misreport their own past belief as well as predicting others will think ‘pencils’; understanding false belief in self and others develops together, around four.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"तीन वर्ष की बच्ची को मिठाइयों का एक परिचित डिब्बा दिखाया जाता है, वह कहती है कि उसमें मिठाइयाँ हैं, और फिर दिखाया जाता है कि उसमें वास्तव में पेंसिलें हैं। यह पूछे जाने पर, ‘खोलने से पहले तुमने क्या सोचा था कि अंदर क्या है?’, वह उत्तर देती है, ‘पेंसिलें।’ यह दर्शाता है कि वह:","optionsHi":["डिब्बे के बारे में अपने पहले के मिथ्या विश्वास को अभी निरूपित नहीं कर सकती","वयस्क के सामने मूर्ख न दिखने के लिए जानबूझकर झूठ बोल रही है","कमज़ोर अल्पकालिक स्मृति के कारण भूल गई है कि उसने क्या कहा था","वस्तु-स्थायित्व की कमी रखती है और वस्तुओं के छिप जाने पर उन्हें याद नहीं रख सकती"],"explanationHi":"गोपनिक और एस्टिंगटन के अप्रत्याशित-विषयवस्तु कार्य में, तीन वर्ष के बच्चे अपने स्वयं के पिछले विश्वास को गलत बताते हैं और यह भी पूर्वानुमान करते हैं कि दूसरे ‘पेंसिलें’ सोचेंगे; स्वयं और दूसरों में मिथ्या विश्वास की समझ साथ-साथ विकसित होती है, लगभग चार वर्ष पर।"},
  {"id":"cdp-child-development-1978","question":"Baron-Cohen, Leslie and Frith gave the Sally–Anne task to autistic children, to children with Down syndrome of lower mental age, and to typically developing four-year-olds. Their key finding was that:","options":["All three groups failed, since the task was too hard for under-tens","Most autistic children failed while most children in the other two groups passed","Children with Down syndrome failed most often because of their lower mental age","The autistic children passed more often, because of their good memory for detail"],"answer":1,"explanation":"Most autistic children, despite higher mental age, predicted Sally would look where the marble really was, while most of the other children passed, suggesting a specific difficulty in theory of mind rather than general delay.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"बैरन-कोहेन, लेस्ली और फ्रिथ ने सैली–ऐन कार्य ऑटिस्टिक बच्चों, निम्न मानसिक आयु वाले डाउन सिंड्रोम के बच्चों, और सामान्य रूप से विकसित हो रहे चार वर्ष के बच्चों को दिया। उनका मुख्य निष्कर्ष यह था कि:","optionsHi":["तीनों समूह असफल रहे, क्योंकि कार्य दस वर्ष से कम के लिए बहुत कठिन था","अधिकांश ऑटिस्टिक बच्चे असफल रहे जबकि अन्य दोनों समूहों के अधिकांश बच्चे सफल रहे","डाउन सिंड्रोम के बच्चे अपनी निम्न मानसिक आयु के कारण सबसे अधिक बार असफल रहे","ऑटिस्टिक बच्चे अधिक बार सफल रहे, विवरण की उनकी अच्छी स्मृति के कारण"],"explanationHi":"अधिकांश ऑटिस्टिक बच्चों ने, उच्चतर मानसिक आयु के बावजूद, पूर्वानुमान किया कि सैली वहाँ देखेगी जहाँ कंचा वास्तव में था, जबकि अन्य अधिकांश बच्चे सफल रहे, जो सामान्य विलंब के बजाय मन के सिद्धांत में विशिष्ट कठिनाई का सुझाव देता है।"},
  {"id":"cdp-child-development-1979","question":"Asked, ‘Where does Rohan think that Meena thinks the ice-cream van is?’, children must reason about one person’s belief about another person’s belief. Such second-order false-belief tasks are usually passed at about:","options":["Four to five years","Three to four years","Six to seven years","Thirteen to fourteen years"],"answer":2,"explanation":"Perner and Wimmer found that understanding beliefs about beliefs comes later than first-order false belief, at about six to seven; it underlies grasp of white lies, irony and social strategies in the primary years.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"यह पूछे जाने पर, ‘रोहन के अनुसार मीना क्या सोचती है कि आइसक्रीम की गाड़ी कहाँ है?’, बच्चों को एक व्यक्ति के दूसरे व्यक्ति के विश्वास के बारे में विश्वास के बारे में तर्क करना होता है। ऐसे द्वितीय-क्रम के मिथ्या-विश्वास कार्य सामान्यतः लगभग किस आयु में पार किए जाते हैं?","optionsHi":["चार से पाँच वर्ष","तीन से चार वर्ष","छह से सात वर्ष","तेरह से चौदह वर्ष"],"explanationHi":"पर्नर और विमर ने पाया कि विश्वासों के बारे में विश्वासों की समझ प्रथम-क्रम के मिथ्या-विश्वास से बाद में, लगभग छह से सात वर्ष पर आती है; यह प्राथमिक वर्षों में सफेद झूठ, व्यंग्य और सामाजिक युक्तियों की समझ का आधार है।"},
  {"id":"cdp-child-development-1980","question":"Studies found that pre-schoolers with more brothers and sisters, especially older ones, tended to pass false-belief tasks earlier. The most likely reason is that:","options":["Parents of large families use more physical punishment, which speeds up maturity","Children with many siblings inherit greater general intelligence from their parents","Children with siblings receive more formal teaching in reading before starting school","Daily talk, pretend play and quarrels with siblings give practice in reading minds"],"answer":3,"explanation":"Perner, Ruffman and others linked sibling numbers to earlier theory of mind; daily interaction, pretence, teasing and arguments about what others want and believe supply rich social experience.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"अध्ययनों में पाया गया कि अधिक भाई-बहनों वाले, विशेषकर बड़े भाई-बहनों वाले, पूर्व-विद्यालयी बच्चे मिथ्या-विश्वास कार्यों को पहले पार करने की प्रवृत्ति रखते थे। सबसे संभावित कारण है कि:","optionsHi":["बड़े परिवारों के माता-पिता अधिक शारीरिक दंड का प्रयोग करते हैं, जो परिपक्वता को तेज़ करता है","अनेक भाई-बहनों वाले बच्चे अपने माता-पिता से अधिक सामान्य बुद्धि विरासत में पाते हैं","भाई-बहनों वाले बच्चों को विद्यालय शुरू करने से पहले पठन में अधिक औपचारिक शिक्षण मिलता है","भाई-बहनों के साथ दैनिक बातचीत, कल्पनात्मक खेल और झगड़े मन पढ़ने का अभ्यास देते हैं"],"explanationHi":"पर्नर, रफ़मैन और अन्य ने भाई-बहनों की संख्या को मन के सिद्धांत के पहले विकास से जोड़ा; दैनिक अंतःक्रिया, अभिनय, चिढ़ाना और इस पर बहस कि दूसरे क्या चाहते और मानते हैं, समृद्ध सामाजिक अनुभव प्रदान करते हैं।"},
  {"id":"cdp-child-development-1981","question":"In Walter Mischel’s delay-of-gratification studies, which strategy helped young children wait longest for a bigger reward?","options":["Being reminded again and again by the adult how delicious the treats were while waiting","Keeping the treats in full view and thinking about how sweet and tasty they would be","Thinking of the treats in ‘cool’ abstract ways, such as imagining marshmallows as clouds","Holding one treat in a hand the whole time so that they could feel it while they waited"],"answer":2,"explanation":"Mischel found that focusing on ‘hot’, consummatory features made waiting harder, whereas covering the rewards, self-distraction or ‘cool’ abstract thoughts made it easier; self-control can be taught as strategy.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"वॉल्टर मिशेल के संतुष्टि-विलंब अध्ययनों में, किस युक्ति ने छोटे बच्चों को बड़े पुरस्कार के लिए सबसे अधिक देर प्रतीक्षा करने में मदद की?","optionsHi":["प्रतीक्षा करते समय वयस्क द्वारा बार-बार याद दिलाया जाना कि मिठाइयाँ कितनी स्वादिष्ट थीं","मिठाइयों को पूर्ण दृश्य में रखना और सोचना कि वे कितनी मीठी और स्वादिष्ट होंगी","मिठाइयों के बारे में ‘शीतल’ अमूर्त ढंग से सोचना, जैसे मार्शमैलो को बादल मानना","प्रतीक्षा करते समय पूरे समय एक मिठाई को हाथ में पकड़े रहना ताकि वे उसे महसूस कर सकें"],"explanationHi":"मिशेल ने पाया कि ‘उष्ण’, उपभोग-संबंधी विशेषताओं पर ध्यान देने से प्रतीक्षा करना कठिन हुआ, जबकि पुरस्कारों को ढकना, स्वयं का ध्यान बँटाना या ‘शीतल’ अमूर्त विचार इसे आसान बनाते थे; आत्म-नियंत्रण को युक्ति के रूप में सिखाया जा सकता है।"},
  {"id":"cdp-child-development-1982","question":"Before a marshmallow-waiting test, one group of children found that an adult’s earlier promises of better crayons were broken; another group found they were kept. The first group waited far less. Kidd and colleagues concluded that waiting depends partly on:","options":["A rational judgement about whether the environment can be trusted to deliver","A fixed trait of self-control that the experience could not have changed","The number of marshmallows offered, which differed between the groups","How hungry the children were, since the first group had eaten less"],"answer":0,"explanation":"Children who had experienced an unreliable adult reasonably expected the bigger reward might never come, so they did not wait; this shows that ‘self-control’ scores reflect beliefs about the environment as well as an inner ability.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"मार्शमैलो-प्रतीक्षा परीक्षण से पहले, बच्चों के एक समूह ने पाया कि एक वयस्क के पहले के बेहतर क्रेयॉन के वादे टूट गए; दूसरे समूह ने पाया कि वे निभाए गए। पहले समूह ने बहुत कम प्रतीक्षा की। किड और सहयोगियों ने निष्कर्ष निकाला कि प्रतीक्षा आंशिक रूप से किस पर निर्भर करती है?","optionsHi":["इस पर तर्कसंगत निर्णय कि क्या परिवेश पर भरोसा किया जा सकता है कि वह पूरा करेगा","आत्म-नियंत्रण का एक स्थिर गुण जिसे अनुभव बदल नहीं सकता था","प्रस्तावित मार्शमैलो की संख्या पर, जो समूहों के बीच भिन्न थी","बच्चे कितने भूखे थे इस पर, क्योंकि पहले समूह ने कम खाया था"],"explanationHi":"जिन बच्चों ने अविश्वसनीय वयस्क का अनुभव किया था, उन्होंने उचित रूप से अपेक्षा की कि बड़ा पुरस्कार शायद कभी न आए, इसलिए उन्होंने प्रतीक्षा नहीं की; यह दर्शाता है कि ‘आत्म-नियंत्रण’ के अंक आंतरिक योग्यता के साथ-साथ परिवेश के बारे में विश्वासों को भी प्रतिबिंबित करते हैं।"},
  {"id":"cdp-child-development-1983","question":"Three-year-olds sort cards correctly by colour. When told, ‘Now sort them by shape,’ many go on sorting by colour, even though they can repeat the new rule aloud. Most five-year-olds switch easily. This task mainly tracks the growth of:","options":["Conservation of number, as described for Piaget’s concrete operational stage","Cognitive flexibility and inhibitory control, parts of executive function","Colour and shape perception, which mature only at about five years of age","Long-term memory for the names of the different shapes and colours"],"answer":1,"explanation":"In Zelazo’s Dimensional Change Card Sort, the younger children know the new rule but cannot inhibit the old one or shift their mental set; the improvement reflects developing executive functions.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"तीन वर्ष के बच्चे कार्डों को रंग के अनुसार सही छाँटते हैं। जब कहा जाता है, ‘अब इन्हें आकार के अनुसार छाँटो,’ तो अनेक रंग के अनुसार छाँटना जारी रखते हैं, यद्यपि वे नया नियम ज़ोर से दोहरा सकते हैं। अधिकांश पाँच वर्ष के बच्चे आसानी से बदल जाते हैं। यह कार्य मुख्यतः किसकी वृद्धि को दर्शाता है?","optionsHi":["संख्या का संरक्षण, जैसा पियाजे की मूर्त संक्रियात्मक अवस्था के लिए वर्णित है","संज्ञानात्मक लचीलापन और अवरोधक नियंत्रण, कार्यकारी प्रकार्य के अंग","रंग और आकार का प्रत्यक्षण, जो केवल लगभग पाँच वर्ष की आयु तक परिपक्व होता है","विभिन्न आकारों और रंगों के नामों की दीर्घकालिक स्मृति"],"explanationHi":"ज़ेलाज़ो के डाइमेंशनल चेंज कार्ड सॉर्ट में, छोटे बच्चे नया नियम जानते हैं पर पुराने को अवरुद्ध नहीं कर पाते या अपनी मानसिक वृत्ति नहीं बदल पाते; सुधार विकसित हो रहे कार्यकारी प्रकार्यों को दर्शाता है।"},
  {"id":"cdp-child-development-1984","question":"Asked about a quarrel between two friends, Ayesha, aged 12, says, ‘If I were a neutral outsider, I’d see that both of them had a point and both behaved badly.’ In Robert Selman’s levels of perspective taking, this shows:","options":["Undifferentiated (egocentric) perspective taking","Self-reflective perspective taking","Social-informational perspective taking","Third-party (mutual) perspective taking"],"answer":3,"explanation":"Selman’s third-party level involves stepping outside a two-person situation and imagining how a neutral observer would see both people; the self-reflective level only allows viewing one’s own thoughts from the other’s side.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"दो मित्रों के बीच झगड़े के बारे में पूछे जाने पर, 12 वर्ष की आयशा कहती है, ‘यदि मैं एक तटस्थ बाहरी व्यक्ति होती, तो मैं देखती कि दोनों की बात में दम था और दोनों ने बुरा व्यवहार किया।’ रॉबर्ट सेल्मन के परिप्रेक्ष्य-ग्रहण के स्तरों में, यह क्या दर्शाता है?","optionsHi":["अविभेदित (अहंकेंद्रित) परिप्रेक्ष्य-ग्रहण","स्व-चिंतनशील परिप्रेक्ष्य-ग्रहण","सामाजिक-सूचनात्मक परिप्रेक्ष्य-ग्रहण","तृतीय-पक्ष (पारस्परिक) परिप्रेक्ष्य-ग्रहण"],"explanationHi":"सेल्मन का तृतीय-पक्ष स्तर दो-व्यक्ति की स्थिति से बाहर निकलकर कल्पना करना शामिल करता है कि एक तटस्थ प्रेक्षक दोनों व्यक्तियों को कैसे देखेगा; स्व-चिंतनशील स्तर केवल अपने विचारों को दूसरे की ओर से देखने की अनुमति देता है।"},
  {"id":"cdp-child-development-1985","question":"Robert Siegler watched children solve addition sums over many weeks. On the same day, a child might count from one, count on from the larger number, or simply recall the answer, with the mix slowly shifting towards better strategies. He described this as:","options":["Vygotsky’s zone of proximal development","Piaget’s stage model with abrupt shifts between stages","The overlapping-waves model of strategy development","Skinner’s model of shaping by successive approximation"],"answer":2,"explanation":"In Siegler’s model several strategies coexist and compete, and their frequency changes gradually with experience, rather than one way of thinking being replaced abruptly by the next.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"रॉबर्ट सीग्लर ने कई सप्ताहों तक बच्चों को जोड़ के सवाल हल करते देखा। उसी दिन, एक बच्चा एक से गिन सकता था, बड़ी संख्या से आगे गिन सकता था, या बस उत्तर याद कर सकता था, और मिश्रण धीरे-धीरे बेहतर युक्तियों की ओर खिसकता था। उन्होंने इसे क्या वर्णित किया?","optionsHi":["वाइगोत्स्की का निकटस्थ विकास का क्षेत्र","पियाजे का अवस्था मॉडल, अवस्थाओं के बीच अचानक परिवर्तन के साथ","युक्ति-विकास का अतिव्यापी-तरंग मॉडल","स्किनर का क्रमिक सन्निकटन द्वारा आकार-निर्माण का मॉडल"],"explanationHi":"सीग्लर के मॉडल में कई युक्तियाँ सह-अस्तित्व में रहती हैं और प्रतिस्पर्धा करती हैं, और उनकी आवृत्ति अनुभव के साथ धीरे-धीरे बदलती है, न कि चिंतन का एक तरीका अगले द्वारा अचानक प्रतिस्थापित होता है।"},
  {"id":"cdp-child-development-1986","question":"Neo-Piagetian Robbie Case explained children’s progress through stages mainly in terms of:","options":["More efficient use of working memory, as practice makes schemes automatic","Moral reasoning that moves from fear of punishment to universal principles","Social interaction with more capable others within a zone of proximal development","Unconscious conflicts between the id, ego and superego at each stage"],"answer":0,"explanation":"Case combined Piaget’s stages with information processing: as processing becomes automatic, it frees working-memory space, letting children coordinate more ideas and form central conceptual structures.","difficulty":"hard","source":"DSSSB PRT · KVS PRT","questionHi":"नव-पियाजेवादी रॉबी केस ने बच्चों की अवस्थाओं में प्रगति को मुख्यतः किस रूप में समझाया?","optionsHi":["कार्यकारी स्मृति का अधिक कुशल उपयोग, जैसे अभ्यास योजनाओं को स्वचालित बनाता है","नैतिक तर्क जो दंड के भय से सार्वभौमिक सिद्धांतों तक जाता है","अधिक सक्षम व्यक्तियों के साथ निकटस्थ विकास के क्षेत्र के भीतर सामाजिक अंतःक्रिया","प्रत्येक अवस्था में इड, ईगो और सुपरईगो के बीच अचेतन द्वंद्व"],"explanationHi":"केस ने पियाजे की अवस्थाओं को सूचना प्रक्रमण से जोड़ा: जैसे-जैसे प्रक्रमण स्वचालित होता है, वह कार्यकारी स्मृति का स्थान मुक्त करता है, जिससे बच्चे अधिक विचारों का समन्वय कर पाते और केंद्रीय संप्रत्ययात्मक संरचनाएँ बना पाते हैं।"},
  {"id":"cdp-child-development-1987","question":"On Gibson and Walk’s ‘visual cliff’, most crawling infants refuse to cross the side that looks deep, even when their mother calls. Later research by Joseph Campos found that:","options":["Infants cannot perceive depth at all until some time after their first birthday","Pre-crawling infants notice the depth, but fear of it grows with crawling experience","Fear of heights is fully present at birth and needs no experience to develop","Infants avoid the deep side only because they dislike the feel of its glass surface"],"answer":1,"explanation":"Very young infants showed interest, not fear, at the deep side (slowed heart rate), while infants with crawling experience showed fear (faster heart rate), so wariness of heights develops with self-produced locomotion.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"गिब्सन और वॉक की ‘दृश्य खाई’ पर, अधिकांश रेंगते शिशु उस ओर पार करने से मना करते हैं जो गहरी दिखती है, तब भी जब उनकी माँ पुकारती है। जोसेफ़ कैम्पोस के बाद के शोध ने पाया कि:","optionsHi":["शिशु पहले जन्मदिन के कुछ समय बाद तक गहराई बिल्कुल नहीं देख सकते","रेंगने से पहले के शिशु गहराई को पहचानते हैं, पर उसका भय रेंगने के अनुभव के साथ बढ़ता है","ऊँचाई का भय जन्म के समय पूरी तरह उपस्थित होता है और विकसित होने के लिए अनुभव नहीं चाहिए","शिशु गहरे पक्ष से केवल इसलिए बचते हैं कि उन्हें उसकी काँच की सतह का स्पर्श पसंद नहीं"],"explanationHi":"बहुत छोटे शिशुओं ने गहरे पक्ष पर रुचि दिखाई, भय नहीं (हृदय गति धीमी हुई), जबकि रेंगने के अनुभव वाले शिशुओं ने भय दिखाया (हृदय गति तेज़), इसलिए ऊँचाई की सतर्कता स्व-उत्पन्न गमन के साथ विकसित होती है।"},
  {"id":"cdp-child-development-1988","question":"Robert Fantz showed babies pairs of pictures and measured how long they looked at each. He found that even very young infants:","options":["Could not focus on pictures until about six months of age","Looked equally at all pictures, showing no visual preferences at all","Looked longer only at bright colours, ignoring all patterns","Looked longer at patterned and face-like pictures than at plain ones"],"answer":3,"explanation":"Fantz’s preferential-looking method showed that newborns and young infants prefer patterned and face-like stimuli, so they can discriminate visual patterns far earlier than once believed.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"रॉबर्ट फ़ैंट्ज़ ने शिशुओं को चित्रों के जोड़े दिखाए और मापा कि वे प्रत्येक को कितनी देर देखते हैं। उन्होंने पाया कि बहुत छोटे शिशु भी:","optionsHi":["लगभग छह माह की आयु तक चित्रों पर ध्यान केंद्रित नहीं कर सकते थे","सभी चित्रों को समान रूप से देखते थे, कोई दृश्य पसंद नहीं दिखाते थे","केवल चटक रंगों को अधिक देर देखते थे, सभी प्रतिरूपों की अनदेखी करते थे","प्रतिरूपित और चेहरे जैसे चित्रों को सादे चित्रों से अधिक देर देखते थे"],"explanationHi":"फ़ैंट्ज़ की अधिमान्य-दृष्टि विधि ने दिखाया कि नवजात और छोटे शिशु प्रतिरूपित और चेहरे जैसे उद्दीपकों को पसंद करते हैं, इसलिए वे पहले माने जाने से कहीं पहले दृश्य प्रतिरूपों में भेद कर सकते हैं।"},
  {"id":"cdp-child-development-1989","question":"A baby is shown the same picture of a cat again and again until she looks at it only briefly. A picture of a dog is then shown, and she looks at it much longer. Researchers infer that she:","options":["Prefers dogs to cats, since she looked at the dog picture for so much longer","Can tell the dog from the cat, as shown by renewed attention to the new picture","Has forgotten the cat picture, since her looking time fell with each repetition","Is simply tired by now, since attention always drops as a session goes on"],"answer":1,"explanation":"In the habituation–dishabituation method, recovery of looking to a new stimulus shows that the infant detects a difference; the fall in looking reflects familiarity, not forgetting.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक शिशु को बिल्ली का वही चित्र बार-बार दिखाया जाता है जब तक वह उसे केवल संक्षेप में देखती है। फिर कुत्ते का चित्र दिखाया जाता है, और वह उसे बहुत अधिक देर देखती है। शोधकर्ता निष्कर्ष निकालते हैं कि वह:","optionsHi":["कुत्तों को बिल्लियों से अधिक पसंद करती है, क्योंकि उसने कुत्ते के चित्र को इतनी देर तक देखा","कुत्ते को बिल्ली से अलग पहचान सकती है, जैसा नए चित्र पर नवीनीकृत ध्यान से दर्शित होता है","बिल्ली का चित्र भूल गई है, क्योंकि प्रत्येक दोहराव के साथ उसका देखने का समय घटा","अब बस थक गई है, क्योंकि सत्र बढ़ने के साथ ध्यान सदैव घटता है"],"explanationHi":"अभ्यस्तीकरण–विअभ्यस्तीकरण विधि में, नए उद्दीपक पर देखने का पुनः बढ़ना दर्शाता है कि शिशु अंतर पहचानता है; देखने में गिरावट परिचितता को दर्शाती है, विस्मरण को नहीं।"},
  {"id":"cdp-child-development-1990","question":"Renée Baillargeon showed four- to five-month-old infants a screen that seemed to rotate right through the space where a box had been hidden. The infants looked longer at this event than at one where the screen stopped at the box. This suggests that:","options":["Infants may understand that hidden objects still exist earlier than Piaget’s search tasks implied","Infants this young understand nothing at all about objects that they cannot see","Infants prefer a rotating screen, because longer movement always attracts more attention","Infants look longest at events they find familiar and expected from experience"],"answer":0,"explanation":"Longer looking at the ‘impossible’ event suggests surprise that the hidden box did not stop the screen; looking-time methods avoid the motor demands of manual search, which may have led Piaget to underestimate infants.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"रेनी बैलार्जन ने चार से पाँच माह के शिशुओं को एक ऐसा पर्दा दिखाया जो उस स्थान से सीधे घूमता प्रतीत हुआ जहाँ एक डिब्बा छिपाया गया था। शिशुओं ने इस घटना को उस घटना की तुलना में अधिक देर देखा जिसमें पर्दा डिब्बे पर रुक गया। यह सुझाता है कि:","optionsHi":["शिशु पियाजे के खोज-कार्यों के संकेत से पहले ही समझ सकते हैं कि छिपी वस्तुएँ अब भी मौजूद रहती हैं","इतने छोटे शिशु उन वस्तुओं के बारे में कुछ भी नहीं समझते जिन्हें वे देख नहीं सकते","शिशु घूमता पर्दा पसंद करते हैं, क्योंकि लंबी गति सदैव अधिक ध्यान खींचती है","शिशु उन घटनाओं को सबसे अधिक देर देखते हैं जो उन्हें परिचित और अनुभव से अपेक्षित लगती हैं"],"explanationHi":"‘असंभव’ घटना को अधिक देर देखना आश्चर्य सुझाता है कि छिपे डिब्बे ने पर्दे को नहीं रोका; देखने-के-समय की विधियाँ हाथ से खोज की गामक माँगों से बचती हैं, जिन्होंने पियाजे को शिशुओं को कम आँकने की ओर ले जाया हो सकता है।"},
  {"id":"cdp-child-development-1991","question":"Karen Wynn showed five-month-olds one doll placed behind a screen and then a second doll added. When the screen dropped to reveal only one doll, infants looked longer than when it showed two. What did she conclude?","options":["Infants cannot tell one object from two before they learn to count","Infants simply prefer looking at one doll rather than at two dolls","Young infants may have a basic sense of small numbers and simple addition","Infants look longer at whatever they saw most recently"],"answer":2,"explanation":"Longer looking at the ‘impossible’ outcome of 1 + 1 = 1 suggested that infants expected two dolls; the finding has been debated, but it supports claims of early, non-verbal number sense.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कैरेन विन ने पाँच माह के शिशुओं को एक पर्दे के पीछे एक गुड़िया रखी दिखाई और फिर एक दूसरी गुड़िया जोड़ी। जब पर्दा गिरा और केवल एक गुड़िया प्रकट हुई, तो शिशुओं ने उस स्थिति की तुलना में अधिक देर देखा जब दो दिखीं। उन्होंने क्या निष्कर्ष निकाला?","optionsHi":["शिशु गिनना सीखने से पहले एक वस्तु को दो से अलग नहीं पहचान सकते","शिशु बस एक गुड़िया को दो गुड़ियों की तुलना में देखना पसंद करते हैं","छोटे शिशुओं में छोटी संख्याओं और सरल जोड़ की मूल समझ हो सकती है","शिशु उसे अधिक देर देखते हैं जो उन्होंने सबसे हाल में देखा"],"explanationHi":"1 + 1 = 1 के ‘असंभव’ परिणाम को अधिक देर देखना सुझाता है कि शिशुओं ने दो गुड़ियों की अपेक्षा की थी; इस निष्कर्ष पर बहस हुई है, परंतु यह प्रारंभिक, अशाब्दिक संख्या-बोध के दावों का समर्थन करता है।"},
  {"id":"cdp-child-development-1992","question":"Robert Kail found that children’s speed on many different tasks, from mental rotation to memory search, increased with age along a very similar curve. This pattern suggests that:","options":["Children become faster only on the kinds of tasks they have been trained on in school","Each task improves for entirely separate reasons, with no common cause behind them","Speed stays the same through childhood and improves only after adolescence begins","A general, age-related increase in processing speed underlies improvement across tasks"],"answer":3,"explanation":"Because the speed-up followed the same exponential pattern across unrelated tasks, Kail argued for a global change in processing speed, probably linked to brain maturation such as myelination.","difficulty":"hard","source":"DSSSB PRT · KVS PRT","questionHi":"रॉबर्ट केल ने पाया कि मानसिक घूर्णन से लेकर स्मृति-खोज तक, अनेक भिन्न कार्यों पर बच्चों की गति आयु के साथ बहुत समान वक्र के अनुसार बढ़ी। यह प्रतिरूप सुझाता है कि:","optionsHi":["बच्चे केवल उन प्रकार के कार्यों पर तेज़ होते हैं जिनका उन्हें विद्यालय में प्रशिक्षण दिया गया है","प्रत्येक कार्य पूरी तरह भिन्न कारणों से सुधरता है, उनके पीछे कोई साझा कारण नहीं","बाल्यावस्था में गति वही रहती है और किशोरावस्था शुरू होने के बाद ही सुधरती है","प्रक्रमण गति में एक सामान्य, आयु-संबंधी वृद्धि कार्यों में सुधार का आधार है"],"explanationHi":"क्योंकि गति-वृद्धि असंबद्ध कार्यों में समान चरघातांकी प्रतिरूप के अनुसार हुई, केल ने प्रक्रमण गति में वैश्विक परिवर्तन का तर्क दिया, जो संभवतः माइलिनीकरण जैसी मस्तिष्क-परिपक्वता से जुड़ा है।"},
  {"id":"cdp-child-development-1993","question":"According to Brainerd and Reyna’s fuzzy-trace theory, which statement is correct?","options":["Children rely more on gist than adults, who store mainly exact verbatim details","Verbatim and gist traces are stored in parallel, and reliance on gist grows with age","Only verbatim traces are stored; the gist is constructed afresh at the time of recall","Verbatim traces last much longer than gist traces once stored in long-term memory"],"answer":1,"explanation":"Fuzzy-trace theory holds that verbatim and gist traces are encoded in parallel; gist lasts longer, and reliance on gist increases with age, which is why some gist-based false memories actually increase with development.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"ब्रेनर्ड और रेना के अस्पष्ट-चिह्न सिद्धांत के अनुसार, कौन-सा कथन सही है?","optionsHi":["बच्चे सार पर वयस्कों से अधिक निर्भर करते हैं, जो मुख्यतः यथावत विवरण संचित करते हैं","यथावत और सार चिह्न समानांतर रूप में संचित होते हैं, और सार पर निर्भरता आयु के साथ बढ़ती है","केवल यथावत चिह्न संचित होते हैं; सार स्मरण के समय नए सिरे से रचा जाता है","दीर्घकालिक स्मृति में संचित होने के बाद यथावत चिह्न सार चिह्नों की तुलना में बहुत लंबे समय तक रहते हैं"],"explanationHi":"अस्पष्ट-चिह्न सिद्धांत मानता है कि यथावत और सार चिह्न समानांतर रूप से कूटित होते हैं; सार अधिक टिकता है, और सार पर निर्भरता आयु के साथ बढ़ती है, इसीलिए कुछ सार-आधारित झूठी स्मृतियाँ वास्तव में विकास के साथ बढ़ती हैं।"},
  {"id":"cdp-child-development-1994","question":"To study how children discover a new maths strategy, a researcher observes the same children solving problems in many sessions over a few weeks, recording each strategy closely. This research design is called:","options":["The microgenetic method","The cross-sectional method","The case-history method","The co-twin control method"],"answer":0,"explanation":"Microgenetic studies make dense observations during a period of rapid change, so the process of change itself can be seen; cross-sectional studies compare different age groups at one time.","difficulty":"hard","source":"DSSSB PRT · KVS PRT","questionHi":"यह अध्ययन करने के लिए कि बच्चे नई गणितीय युक्ति कैसे खोजते हैं, एक शोधकर्ता उन्हीं बच्चों को कुछ सप्ताहों में अनेक सत्रों में प्रश्न हल करते देखता है, प्रत्येक युक्ति को ध्यान से दर्ज करते हुए। इस शोध-अभिकल्प को क्या कहते हैं?","optionsHi":["सूक्ष्म-जननिक (माइक्रोजेनेटिक) विधि","अनुप्रस्थ-काट विधि","व्यक्ति-इतिहास विधि","सह-जुड़वाँ नियंत्रण विधि"],"explanationHi":"सूक्ष्म-जननिक अध्ययन तीव्र परिवर्तन की अवधि में सघन अवलोकन करते हैं, ताकि परिवर्तन की प्रक्रिया स्वयं देखी जा सके; अनुप्रस्थ-काट अध्ययन एक समय में भिन्न आयु-समूहों की तुलना करते हैं।"},
  {"id":"cdp-child-development-1995","question":"Elizabeth Spelke’s ‘core knowledge’ view proposes that infants:","options":["Develop all knowledge only through stages driven by a general, logical structure","Begin life as blank slates who must learn everything from experience alone","Begin life with a few specialised systems for objects, number, space and agents","Gain knowledge only through the language that they learn from caregivers"],"answer":2,"explanation":"Core knowledge theorists argue for innate, domain-specific systems that are built on through experience; this contrasts with empiricist blank-slate views and with Piaget’s domain-general stages.","difficulty":"hard","source":"DSSSB PRT · KVS PRT","questionHi":"एलिज़ाबेथ स्पेल्के का ‘मूल ज्ञान’ दृष्टिकोण प्रस्ताव करता है कि शिशु:","optionsHi":["सारा ज्ञान केवल एक सामान्य, तार्किक संरचना द्वारा संचालित अवस्थाओं से विकसित करते हैं","कोरी स्लेट के रूप में जीवन शुरू करते हैं जिन्हें सब कुछ केवल अनुभव से सीखना होता है","वस्तुओं, संख्या, स्थान और कर्ताओं के लिए कुछ विशिष्ट प्रणालियों के साथ जीवन शुरू करते हैं","ज्ञान केवल उस भाषा के माध्यम से पाते हैं जो वे देखभालकर्ताओं से सीखते हैं"],"explanationHi":"मूल ज्ञान सिद्धांतकार जन्मजात, क्षेत्र-विशिष्ट प्रणालियों का तर्क देते हैं जिन पर अनुभव से निर्माण होता है; यह अनुभववादी कोरी-स्लेट मतों और पियाजे की क्षेत्र-सामान्य अवस्थाओं के विपरीत है।"},
  {"id":"cdp-child-development-1996","question":"A one-year-old points at a bird, looks at her father to check that he is looking too, and smiles. This pointing to share interest, rather than to ask for something, is called:","options":["Telegraphic speech, a short two-word sentence","Protoimperative pointing, a request for an object","Holophrastic speech, a one-word sentence","Protodeclarative pointing, a sign of joint attention"],"answer":3,"explanation":"Protodeclarative pointing directs another’s attention to share an experience and emerges with joint attention around nine to twelve months; protoimperative pointing is used to obtain something.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक वर्ष की बच्ची एक पक्षी की ओर इशारा करती है, अपने पिता की ओर देखकर पक्का करती है कि वह भी देख रहा है, और मुस्कुराती है। कुछ माँगने के बजाय रुचि साझा करने के लिए इस प्रकार इशारा करना क्या कहलाता है?","optionsHi":["तार-शैली वाणी, दो शब्दों का छोटा वाक्य","प्रोटो-आदेशात्मक इशारा, किसी वस्तु का अनुरोध","एक-शब्दी वाणी (होलोफ़्रास्टिक), एक शब्द का वाक्य","प्रोटो-घोषणात्मक इशारा, संयुक्त ध्यान का चिह्न"],"explanationHi":"प्रोटो-घोषणात्मक इशारा किसी अनुभव को साझा करने के लिए दूसरे का ध्यान निर्देशित करता है और संयुक्त ध्यान के साथ लगभग नौ से बारह माह में उभरता है; प्रोटो-आदेशात्मक इशारा कुछ पाने के लिए प्रयुक्त होता है।"},
  {"id":"cdp-child-development-1997","question":"Usha Goswami found that many three- and four-year-olds could complete analogies such as ‘Play-dough is to cut play-dough as apple is to ___’ (choosing a cut apple). What did this show?","options":["Analogical reasoning appears only once children reach formal operations at eleven","Young children can reason by analogy when they understand the relation involved","Young children solve such items only by matching surface features such as colour","Analogical reasoning depends only on how many words a young child already knows"],"answer":1,"explanation":"Earlier studies used relations unfamiliar to young children; with familiar causal relations like cutting, they reasoned by analogy, showing that relational knowledge, not stage, limits performance.","difficulty":"very-hard","source":"DSSSB PRT · KVS PRT","questionHi":"उषा गोस्वामी ने पाया कि अनेक तीन और चार वर्ष के बच्चे ‘प्ले-डो काटने की चीज़ है, जैसे सेब ___ के लिए’ (कटा हुआ सेब चुनना) जैसी उपमाएँ पूरी कर सकते थे। इसने क्या दर्शाया?","optionsHi":["उपमात्मक तर्क तभी प्रकट होता है जब बच्चे ग्यारह वर्ष पर औपचारिक संक्रियाओं तक पहुँचते हैं","छोटे बच्चे उपमा से तर्क कर सकते हैं जब वे इसमें शामिल संबंध को समझते हैं","छोटे बच्चे ऐसी मदें केवल रंग जैसी सतही विशेषताओं का मिलान करके हल करते हैं","उपमात्मक तर्क केवल इस पर निर्भर करता है कि छोटे बच्चे को पहले से कितने शब्द आते हैं"],"explanationHi":"पहले के अध्ययनों ने ऐसे संबंधों का उपयोग किया जो छोटे बच्चों के लिए अपरिचित थे; काटने जैसे परिचित कारण-संबंधों के साथ, उन्होंने उपमा से तर्क किया, जो दर्शाता है कि प्रदर्शन को अवस्था नहीं, संबंधात्मक ज्ञान सीमित करता है।"},
  {"id":"cdp-child-development-1998","question":"A three-year-old handles a sponge painted to look like a rock. She then says it ‘really is a sponge’ and also that it ‘looks like a sponge’. John Flavell’s research shows that this difficulty with the appearance–reality distinction:","options":["Is common at three and largely overcome by about six or seven years","Persists until adolescence in most children, whatever their experiences","Is found mainly in children with learning disabilities, not in others","Shows that she cannot yet perceive colours or shapes properly at all"],"answer":0,"explanation":"Young children struggle to hold two representations of one object, how it looks and what it is; skill improves markedly during the pre-school and early school years, alongside theory of mind.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"तीन वर्ष की बच्ची एक ऐसा स्पंज संभालती है जिसे पत्थर जैसा रंगा गया है। फिर वह कहती है कि वह ‘वास्तव में स्पंज है’ और यह भी कि वह ‘स्पंज जैसा दिखता है’। जॉन फ्लेवेल का शोध दर्शाता है कि दिखावट–वास्तविकता के भेद में यह कठिनाई:","optionsHi":["तीन वर्ष की आयु में सामान्य है और लगभग छह या सात वर्ष तक काफ़ी हद तक दूर हो जाती है","अधिकांश बच्चों में किशोरावस्था तक बनी रहती है, उनके अनुभव चाहे जो हों","मुख्यतः अधिगम अक्षमता वाले बच्चों में पाई जाती है, अन्य में नहीं","दर्शाती है कि वह अभी रंगों या आकारों का ठीक से प्रत्यक्षण बिल्कुल नहीं कर सकती"],"explanationHi":"छोटे बच्चों को एक वस्तु के दो निरूपण, वह कैसी दिखती है और वह क्या है, साथ रखने में कठिनाई होती है; पूर्व-विद्यालय और प्रारंभिक विद्यालयी वर्षों में कौशल उल्लेखनीय रूप से सुधरता है, मन के सिद्धांत के साथ-साथ।"},
  {"id":"cdp-child-development-1999","question":"Asked what happens at a birthday party, a four-year-old says, ‘You come, you give presents, you cut the cake, you eat, you go home.’ Katherine Nelson would describe this general knowledge of a routine event as a:","options":["Episodic flashback","Schema of conservation","Script","Mnemonic device"],"answer":2,"explanation":"Scripts are general representations of the sequence of familiar events; young children organise memory of routines this way and recall ‘what usually happens’ better than unique details.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"यह पूछे जाने पर कि जन्मदिन की पार्टी में क्या होता है, चार वर्ष का बच्चा कहता है, ‘तुम आते हो, तुम उपहार देते हो, तुम केक काटते हो, तुम खाते हो, तुम घर जाते हो।’ कैथरीन नेल्सन किसी परिचित घटना की इस सामान्य जानकारी को क्या कहेंगी?","optionsHi":["घटनात्मक झलक (एपिसोडिक फ़्लैशबैक)","संरक्षण का स्कीमा","स्क्रिप्ट (पटकथा)","स्मरण-सहायक युक्ति"],"explanationHi":"स्क्रिप्ट परिचित घटनाओं के क्रम के सामान्य निरूपण हैं; छोटे बच्चे दिनचर्याओं की स्मृति को इसी प्रकार संगठित करते हैं और अनोखे विवरणों की तुलना में ‘प्रायः क्या होता है’ बेहतर याद रखते हैं।"},
  {"id":"cdp-child-development-2000","question":"Some parents talk with their pre-schoolers about past events in rich detail, asking open questions and adding information (‘What did we see at the zoo? Yes, and what was the elephant doing?’). Research by Reese and Fivush found that their children later:","options":["Became more anxious, since talking about the past revived old feelings","Remembered fewer events, since parents did the remembering for them","Showed no difference from children of parents who asked only yes–no questions","Gave fuller, more detailed accounts of their own past experiences"],"answer":3,"explanation":"Elaborative reminiscing provides a model of how to organise and narrate memories, so children develop richer autobiographical memory; repetitive, yes–no styles are less helpful.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कुछ माता-पिता अपने पूर्व-विद्यालयी बच्चों से अतीत की घटनाओं के बारे में समृद्ध विवरण में बात करते हैं, खुले प्रश्न पूछते हैं और जानकारी जोड़ते हैं (‘हमने चिड़ियाघर में क्या देखा? हाँ, और हाथी क्या कर रहा था?’)। रीज़ और फ़िवश के शोध ने पाया कि उनके बच्चे बाद में:","optionsHi":["अधिक चिंतित हो गए, क्योंकि अतीत के बारे में बात करने ने पुरानी भावनाओं को जगाया","कम घटनाएँ याद रखे, क्योंकि माता-पिता ने उनके लिए याद रखा","केवल हाँ–नहीं प्रश्न पूछने वाले माता-पिता के बच्चों से कोई अंतर नहीं दिखाया","अपने स्वयं के अतीत के अनुभवों के बारे में अधिक पूर्ण, अधिक विस्तृत विवरण दिए"],"explanationHi":"विस्तारात्मक स्मरण-वार्ता यह आदर्श प्रस्तुत करती है कि स्मृतियों को कैसे संगठित और वर्णित किया जाए, इसलिए बच्चे अधिक समृद्ध आत्मकथात्मक स्मृति विकसित करते हैं; दोहरावदार, हाँ–नहीं वाली शैलियाँ कम सहायक होती हैं।"},
];

export default questions;
